        ["wpf_layer_viewer_legacy_readout"] = path =>
        {
            using OpenVisionLayerViewerView view = new();
            return CaptureWindowWithContent(view, path, 520, 380, () =>
            {
                Grid root = FindNamedVisualChild<Grid>(view, "viewerRootGrid")!;
                Border status = FindNamedVisualChild<Border>(view, "statusFooter")!;
                Grid main = FindNamedVisualChild<Grid>(view, "mainPaneFooter")!;
                if (view.MainPane != null || root.RowDefinitions[2].Height.Value != 30 || !status.IsVisible || main.IsVisible || view.MinWidth != 420 || view.MinHeight != 300) throw new InvalidOperationException("120 ordinary LayerViewer chrome changed.");
                AssertElementWithinAncestor("ordinary LayerViewer footer", status, root);
                view.SetCompactChrome(true); Pump(3);
                if (view.MinWidth != 160 || view.MinHeight != 120 || status.IsVisible) throw new InvalidOperationException("121 changed shared compact LayerViewer minimums.");
                view.SetCompactChrome(false); Pump(3);
                Type controllerType = typeof(OpenVisionLab.Docking.Controls.OpenVisionDockWorkspaceController);
                ConstructorInfo constructor = controllerType.GetConstructors(BindingFlags.Instance | BindingFlags.NonPublic).Single(item => item.GetParameters().Length == 5);
                object controller = constructor.Invoke(new object[] { null, null, null, null, new Func<bool>(() => false) });
                double normalWidth = (double)controllerType.GetProperty("MinimumPaneWidth", BindingFlags.Instance | BindingFlags.NonPublic)!.GetValue(controller)!;
                double normalHeight = (double)controllerType.GetProperty("MinimumPaneHeight", BindingFlags.Instance | BindingFlags.NonPublic)!.GetValue(controller)!;
                if (normalWidth != 280 || normalHeight != 180) throw new InvalidOperationException("121 changed normal comparison pane minimums.");
            });
        },
