    [STAThread]
    private static int Main(string[] args)
    {
        try
        {
            args = args
                .Where(arg => !string.Equals(arg, "--quiet", StringComparison.OrdinalIgnoreCase)
                    && !string.Equals(arg, "--visible-capture", StringComparison.OrdinalIgnoreCase))
                .ToArray();

            if ((args.Length == 3 || args.Length == 4) && string.Equals(args[0], "--ui-performance-contract", StringComparison.OrdinalIgnoreCase))
            {
                EnsureApplication();
                return UiPerformanceContract.Run(args[1], args[2], args.Length == 4 ? args[3] : "all");
            }

            if (args.Length == 2 && string.Equals(args[0], "--log-copy-contract", StringComparison.OrdinalIgnoreCase))
            {
                EnsureApplication();
                return CheckLogCopyContract(args[1]);
            }

            if (args.Length == 3 && string.Equals(args[0], "--workbench-name-wrap-contract", StringComparison.OrdinalIgnoreCase))
            {
                return WorkbenchNameTextContract.Run(args[1], args[2]);
            }

            if (args.Length == 2 && string.Equals(args[0], "--images-added-copy-contract", StringComparison.OrdinalIgnoreCase))
            {
                return CheckImageQuantityCopy(args[1], "Workbench.Action.ImagesAddedFormat");
            }
            if (args.Length == 2 && string.Equals(args[0], "--images-opening-copy-contract", StringComparison.OrdinalIgnoreCase))
            {
                return CheckImageQuantityCopy(args[1], "Workbench.Action.ImagesOpeningFormat");
            }

            if (args.Length == 2 && string.Equals(args[0], "--recipe-manager-workbench-contract", StringComparison.OrdinalIgnoreCase))
            {
                return RecipeManagerWorkbenchContract.Run(args[1]);
            }

            if ((args.Length == 1 || args.Length == 2)
                && string.Equals(args[0], "--command-line-contract", StringComparison.OrdinalIgnoreCase))
            {
                return ScreenshotSmokeTargetRunnerContract.Run(args.Length == 2 ? args[1] : null);
            }
            if ((args.Length == 1 || args.Length == 2)
                && string.Equals(args[0], "--learn-document-copy-contract", StringComparison.OrdinalIgnoreCase))
            {
                return LearnDocumentationCopyPolicyContract.Run(args.Length == 2 ? args[1] : null);
            }
            if ((args.Length == 1 || args.Length == 2)
                && string.Equals(args[0], "--screenshot-bitmap-assertions-contract", StringComparison.OrdinalIgnoreCase))
            {
                return ScreenshotBitmapAssertionsContract.Run(args.Length == 2 ? args[1] : null);
            }
            if ((args.Length == 1 || args.Length == 2)
                && string.Equals(args[0], "--screenshot-png-writer-contract", StringComparison.OrdinalIgnoreCase))
            {
                return ScreenshotPngWriterContract.Run(args.Length == 2 ? args[1] : null);
            }
            if ((args.Length == 1 || args.Length == 2)
                && string.Equals(args[0], "--direct-smoke-screenshot-writer-contract", StringComparison.OrdinalIgnoreCase))
            {
                return DirectSmokeScreenshotWriterContract.Run(args.Length == 2 ? args[1] : null);
            }
            if ((args.Length == 1 || args.Length == 2)
                && string.Equals(args[0], "--smoke-clipboard-retry-contract", StringComparison.OrdinalIgnoreCase))
            {
                return SmokeClipboardRetryContract.Run(args.Length == 2 ? args[1] : null);
            }
            if ((args.Length == 1 || args.Length == 2)
                && string.Equals(args[0], "--smoke-task-waiter-contract", StringComparison.OrdinalIgnoreCase))
            {
                return SmokeTaskWaiterContract.Run(args.Length == 2 ? args[1] : null);
            }
            if ((args.Length == 1 || args.Length == 2)
                && string.Equals(args[0], "--smoke-window-monitor-placement-contract", StringComparison.OrdinalIgnoreCase))
            {
                return SmokeWindowMonitorPlacementContract.Run(args.Length == 2 ? args[1] : null);
            }
            if ((args.Length == 1 || args.Length == 2)
                && string.Equals(args[0], "--smoke-mouse-input-contract", StringComparison.OrdinalIgnoreCase))
            {
                return SmokeMouseInputContract.Run(args.Length == 2 ? args[1] : null);
            }
            if ((args.Length == 1 || args.Length == 2)
                && string.Equals(args[0], "--screenshot-capture-lifecycle-contract", StringComparison.OrdinalIgnoreCase))
            {
                return ScreenshotCaptureLifecycleContract.Run(args.Length == 2 ? args[1] : null);
            }
            if ((args.Length == 1 || args.Length == 2)
                && string.Equals(args[0], "--smoke-fixture-resources-contract", StringComparison.OrdinalIgnoreCase))
            {
                return SmokeFixtureResourcesContract.Run(args.Length == 2 ? args[1] : null);
            }
            if ((args.Length == 1 || args.Length == 2)
                && string.Equals(args[0], "--smoke-docking-state-files-contract", StringComparison.OrdinalIgnoreCase))
            {
                return SmokeDockingStateFilesContract.Run(args.Length == 2 ? args[1] : null);
            }
            if ((args.Length == 1 || args.Length == 2)
                && string.Equals(args[0], "--validation-dataset-artifact-writer-contract", StringComparison.OrdinalIgnoreCase))
            {
                return ValidationDatasetArtifactWriterContract.Run(args.Length == 2 ? args[1] : null);
            }
            if ((args.Length == 1 || args.Length == 2)
                && string.Equals(args[0], "--recipe-context-fixture-contract", StringComparison.OrdinalIgnoreCase))
            {
                return RecipeContextFixtureContract.Run(args.Length == 2 ? args[1] : null);
            }
            if ((args.Length == 1 || args.Length == 2)
                && string.Equals(args[0], "--smoke-recipe-workspace-cleanup-contract", StringComparison.OrdinalIgnoreCase))
            {
                return SmokeRecipeWorkspaceCleanupContract.Run(args.Length == 2 ? args[1] : null);
            }
            if ((args.Length == 1 || args.Length == 2)
                && string.Equals(args[0], "--validation-dataset-configuration-contract", StringComparison.OrdinalIgnoreCase))
            {
                return ValidationDatasetSmokeConfigurationContract.Run(args.Length == 2 ? args[1] : null);
            }
            if ((args.Length == 1 || args.Length == 2)
                && string.Equals(args[0], "--validation-dataset-execution-progress-contract", StringComparison.OrdinalIgnoreCase))
            {
                return ValidationDatasetExecutionProgressContract.Run(args.Length == 2 ? args[1] : null);
            }
            if ((args.Length == 1 || args.Length == 2)
                && string.Equals(args[0], "--validation-dataset-review-queue-evidence-contract", StringComparison.OrdinalIgnoreCase))
            {
                return ValidationDatasetReviewQueueEvidenceContract.Run(args.Length == 2 ? args[1] : null);
            }
            if ((args.Length == 1 || args.Length == 2)
                && string.Equals(args[0], "--validation-dataset-drawing-evidence-contract", StringComparison.OrdinalIgnoreCase))
            {
                return ValidationDatasetDrawingEvidenceContract.Run(args.Length == 2 ? args[1] : null);
            }
            if ((args.Length == 1 || args.Length == 2)
                && string.Equals(args[0], "--recipe-validation-suite-view-contract", StringComparison.OrdinalIgnoreCase))
            {
                return RecipeValidationSuiteViewContract.Run(args.Length == 2 ? args[1] : null);
            }
            if ((args.Length == 1 || args.Length == 2)
                && string.Equals(args[0], "--native-preview-production-delegate-contract", StringComparison.OrdinalIgnoreCase))
            {
                return NativePreviewProductionDelegateContract.Run(args.Length == 2 ? args[1] : null);
            }
            if ((args.Length == 1 || args.Length == 2)
                && string.Equals(args[0], "--shell-responsive-layout-contract", StringComparison.OrdinalIgnoreCase))
            {
                EnsureApplication();
                OpenVisionLanguageService.Load();
                return ShellResponsiveLayoutContract.Run(args.Length == 2 ? args[1] : null, CreateShellHost, Pump, WriteOpenGlDiagnostics);
            }
            if ((args.Length == 1 || args.Length == 2)
                && string.Equals(args[0], "--ui-readability-contract", StringComparison.OrdinalIgnoreCase))
            {
                return UiReadabilityContract.Run(args.Length == 2 ? args[1] : null);
            }
            if ((args.Length == 1 || args.Length == 2)
                && string.Equals(args[0], "--layer-name-contract", StringComparison.OrdinalIgnoreCase))
            {
                return UiReadabilityContract.RunLayerNames(args.Length == 2 ? args[1] : null);
            }
            if ((args.Length == 1 || args.Length == 2)
                && string.Equals(args[0], "--tool-shell-status-contract", StringComparison.OrdinalIgnoreCase))
            {
                return UiReadabilityContract.RunToolShellStatus(args.Length == 2 ? args[1] : null);
            }
            if ((args.Length == 1 || args.Length == 2)
                && string.Equals(args[0], "--segmented-selection-contract", StringComparison.OrdinalIgnoreCase))
            {
                return UiReadabilityContract.RunSegmentedSelection(args.Length == 2 ? args[1] : null);
            }
            if ((args.Length == 1 || args.Length == 2)
                && string.Equals(args[0], "--tcp-integration-localization-contract", StringComparison.OrdinalIgnoreCase))
            {
                return TcpIntegrationLocalizationContract.Run(args.Length == 2 ? args[1] : null);
            }
            if ((args.Length == 1 || args.Length == 2)
                && string.Equals(args[0], "--roi-array-dialog-contract", StringComparison.OrdinalIgnoreCase))
            {
                return RoiArrayDialogContract.Run(args.Length == 2 ? args[1] : null);
            }
            if ((args.Length == 1 || args.Length == 2)
                && string.Equals(args[0], "--simplepreprocess-preview-production-contract", StringComparison.OrdinalIgnoreCase))
            {
                return SimplePreprocessPreviewProductionContract.Run(args.Length == 2 ? args[1] : null);
            }
            if ((args.Length == 1 || args.Length == 2)
                && string.Equals(args[0], "--matching-line-affine-preview-contract", StringComparison.OrdinalIgnoreCase))
            {
                return MatchingLineAffinePreviewContract.Run(args.Length == 2 ? args[1] : null);
            }
            if (args.Length >= 1 && string.Equals(args[0], "--list", StringComparison.OrdinalIgnoreCase))
            {
                ScreenshotSmokeTargetRunner.PrintTargetsAndSuites(Targets, Suites);
                return 0;
            }

            RequireIsolatedScreenshotDataRoot();
            EnsureApplication();
            OpenVisionLanguage? manualCaptureLanguage = ResolveManualCaptureLanguage(args);
            if (manualCaptureLanguage.HasValue)
            {
                string languageCode = manualCaptureLanguage.Value == OpenVisionLanguage.English ? "en" : "ko";
                string localizationDirectory = Path.Combine(
                    Path.GetTempPath(),
                    "OpenVisionLab-ScreenshotSmoke",
                    "manual-localization-" + languageCode);
                Directory.CreateDirectory(localizationDirectory);
                OpenVisionLanguageService.ConfigureDataDirectory(localizationDirectory);
                OpenVisionLanguageService.Load();
                OpenVisionLanguageService.SetLanguage(manualCaptureLanguage.Value, true);
            }
            else
            {
                OpenVisionLanguageService.Load();
            }

            if (args.Length >= 2 && string.Equals(args[0], "--all", StringComparison.OrdinalIgnoreCase))
            {
                return ScreenshotSmokeTargetRunner.CaptureTargets(args[1], Targets.Keys, Targets);
            }

            if (args.Length >= 3 && string.Equals(args[0], "--target", StringComparison.OrdinalIgnoreCase))
            {
                return ScreenshotSmokeTargetRunner.CaptureTargets(args[2], ScreenshotSmokeTargetRunner.SplitNames(args[1]), Targets);
            }

            if (args.Length >= 3 && string.Equals(args[0], "--suite", StringComparison.OrdinalIgnoreCase))
            {
                return ScreenshotSmokeTargetRunner.CaptureTargets(
                    args[2],
                    ScreenshotSmokeTargetRunner.ExpandSuites(ScreenshotSmokeTargetRunner.SplitNames(args[1]), Suites),
                    Targets);
            }

            Console.Error.WriteLine("   or: PipelineViewerScreenshotSmoke --command-line-contract [evidenceDirectory]");
            Console.Error.WriteLine("   or: PipelineViewerScreenshotSmoke --learn-document-copy-contract [evidenceDirectory]");
            Console.Error.WriteLine("   or: PipelineViewerScreenshotSmoke --screenshot-bitmap-assertions-contract [evidenceDirectory]");
            Console.Error.WriteLine("   or: PipelineViewerScreenshotSmoke --screenshot-png-writer-contract [evidenceDirectory]");
            Console.Error.WriteLine("   or: PipelineViewerScreenshotSmoke --screenshot-capture-lifecycle-contract [evidenceDirectory]");
            Console.Error.WriteLine("   or: PipelineViewerScreenshotSmoke --smoke-fixture-resources-contract [evidenceDirectory]");
            Console.Error.WriteLine("   or: PipelineViewerScreenshotSmoke --smoke-docking-state-files-contract [evidenceDirectory]");
            Console.Error.WriteLine("   or: PipelineViewerScreenshotSmoke --smoke-task-waiter-contract [evidenceDirectory]");
            Console.Error.WriteLine("   or: PipelineViewerScreenshotSmoke --smoke-window-monitor-placement-contract [evidenceDirectory]");
            Console.Error.WriteLine("   or: PipelineViewerScreenshotSmoke --smoke-mouse-input-contract [evidenceDirectory]");
            Console.Error.WriteLine("   or: PipelineViewerScreenshotSmoke --validation-dataset-artifact-writer-contract [evidenceDirectory]");
            Console.Error.WriteLine("   or: PipelineViewerScreenshotSmoke --recipe-context-fixture-contract [evidenceDirectory]");
            Console.Error.WriteLine("   or: PipelineViewerScreenshotSmoke --smoke-recipe-workspace-cleanup-contract [evidenceDirectory]");
            Console.Error.WriteLine("   or: PipelineViewerScreenshotSmoke --validation-dataset-configuration-contract [evidenceDirectory]");
            Console.Error.WriteLine("   or: PipelineViewerScreenshotSmoke --validation-dataset-execution-progress-contract [evidenceDirectory]");
            Console.Error.WriteLine("   or: PipelineViewerScreenshotSmoke --validation-dataset-review-queue-evidence-contract [evidenceDirectory]");
            Console.Error.WriteLine("   or: PipelineViewerScreenshotSmoke --validation-dataset-drawing-evidence-contract [evidenceDirectory]");
            Console.Error.WriteLine("   or: PipelineViewerScreenshotSmoke --recipe-validation-suite-view-contract [evidenceDirectory]");
            Console.Error.WriteLine("   or: PipelineViewerScreenshotSmoke --native-preview-production-delegate-contract [evidenceDirectory]");
            Console.Error.WriteLine("   or: PipelineViewerScreenshotSmoke --shell-responsive-layout-contract [evidenceDirectory]");
            Console.Error.WriteLine("   or: PipelineViewerScreenshotSmoke --ui-readability-contract [evidenceDirectory]");
            Console.Error.WriteLine("   or: PipelineViewerScreenshotSmoke --tool-shell-status-contract [evidenceDirectory]");
            Console.Error.WriteLine("   or: PipelineViewerScreenshotSmoke --layer-name-contract [evidenceDirectory]");
            Console.Error.WriteLine("   or: PipelineViewerScreenshotSmoke --segmented-selection-contract [evidenceDirectory]");
            Console.Error.WriteLine("   or: PipelineViewerScreenshotSmoke --tcp-integration-localization-contract [evidenceDirectory]");
            Console.Error.WriteLine("   or: PipelineViewerScreenshotSmoke --roi-array-dialog-contract [evidenceDirectory]");
            Console.Error.WriteLine("   or: PipelineViewerScreenshotSmoke --simplepreprocess-preview-production-contract [evidenceDirectory]");
            Console.Error.WriteLine("   or: PipelineViewerScreenshotSmoke --matching-line-affine-preview-contract [evidenceDirectory]");
            Console.Error.WriteLine("Usage: --target target1,target2 outputDir | --suite suite1,suite2 outputDir | --all outputDir | --list");
            return 2;
        }
        catch (Exception ex)
        {
            Console.Error.WriteLine(ex.GetBaseException().Message);
            return 1;
        }
    }

