    private static CaptureResult CaptureWorkbenchThemeContract(string outputPath)
    {
        StackPanel samples = new();
        List<object> measurements = new();
        List<object> fontEvidence = new();
        string prefix = "OpenVision.Workbench.";
        foreach (string theme in new[] { "Dark", "Light" })
        {
            ResourceDictionary resources = new()
            {
                Source = new Uri($"/OpenVisionLab;component/UI/Wpf/OpenVisionWorkbench{theme}.xaml", UriKind.Relative)
            };
            if (resources.Keys.Cast<object>().Any(key => key.ToString()!.Contains("DEV", StringComparison.OrdinalIgnoreCase)))
                throw new InvalidOperationException("Workbench theme contains a development-only key.");
            FontFamily family = (FontFamily)resources[prefix + "FontFamily"];
            if (!family.Source.EndsWith("Segoe UI Variable Text, Segoe UI, Malgun Gothic", StringComparison.Ordinal))
                throw new InvalidOperationException("Workbench font fallback order changed.");
            if ((double)resources[prefix + "ControlHeight"] != 30 || (double)resources[prefix + "FontSizeM"] != 13)
                throw new InvalidOperationException("Workbench size tokens do not match the development specification.");

            WrapPanel themePanel = new() { Width = 960, Background = (Brush)resources[prefix + "PanelBrush"] };
            foreach ((FontWeight weight, string file) in new[]
            {
                (FontWeights.Normal, "Regular"), (FontWeights.Medium, "Medium"),
                (FontWeights.SemiBold, "SemiBold"), (FontWeights.Bold, "Bold")
            })
            {
                Typeface typeface = new(family, FontStyles.Normal, weight, FontStretches.Normal);
                FormattedText text = new("파이프라인 Pipeline 7 / 20", CultureInfo.GetCultureInfo("ko-KR"),
                    FlowDirection.LeftToRight, typeface, 16, (Brush)resources[prefix + "TextBrush"], 1);
                DrawingVisual visual = new();
                using (DrawingContext context = visual.RenderOpen()) context.DrawText(text, new Point(0, 0));
                List<GlyphRunDrawing> runs = GlyphRuns(visual.Drawing).ToList();
                if (runs.Count == 0 || runs.Any(run => !run.GlyphRun.GlyphTypeface.FontUri.ToString()
                    .EndsWith($"Pretendard-{file}.ttf", StringComparison.OrdinalIgnoreCase)))
                    throw new InvalidOperationException($"{theme} {weight}: rendered text did not use the packaged Pretendard-{file} font.");
                if (runs.Any(run => !run.GlyphRun.GlyphTypeface.CharacterToGlyphMap.ContainsKey('가')
                    || !run.GlyphRun.GlyphTypeface.CharacterToGlyphMap.ContainsKey('A')))
                    throw new InvalidOperationException($"{theme} {weight}: packaged Korean/English glyphs are missing.");
                fontEvidence.Add(new { Theme = theme, Weight = weight.ToString(), FontUris = runs.Select(run => run.GlyphRun.GlyphTypeface.FontUri.ToString()).Distinct() });
                themePanel.Children.Add(new TextBlock
                {
                    Text = $"{theme} {file} · 파이프라인 Pipeline", FontFamily = family, FontWeight = weight,
                    FontSize = 16, Foreground = (Brush)resources[prefix + "TextBrush"], Width = 460, Margin = new Thickness(10)
                });
            }

            foreach ((string foreground, string background, double minimum) in new[]
            {
                ("Text", "Panel", 4.5), ("SecondaryText", "Panel", 4.5), ("MutedText", "Panel", 4.5),
                ("MutedText", "PanelAlt", 4.5), ("AccentText", "Accent", 4.5), ("AccentText", "AccentHover", 4.5),
                ("Ok", "Panel", 4.5), ("Ng", "Panel", 4.5), ("Error", "Panel", 4.5),
                ("Stale", "Panel", 4.5), ("Done", "Panel", 4.5), ("Skip", "Panel", 4.5),
                ("FieldBorder", "Panel", 3.0), ("FieldBorder", "PanelAlt", 3.0)
            })
            {
                Brush front = (Brush)resources[prefix + foreground + "Brush"];
                Brush back = (Brush)resources[prefix + background + "Brush"];
                DrawingVisual swatch = new();
                using (DrawingContext context = swatch.RenderOpen())
                {
                    context.DrawRectangle(back, null, new Rect(0, 0, 20, 10));
                    context.DrawRectangle(front, null, new Rect(10, 0, 10, 10));
                }
                RenderTargetBitmap rendered = new(20, 10, 96, 96, PixelFormats.Pbgra32);
                rendered.Render(swatch);
                byte[] pixels = new byte[20 * 10 * 4];
                rendered.CopyPixels(pixels, 20 * 4, 0);
                double first = Luminance(pixels, (5 * 20 + 5) * 4);
                double second = Luminance(pixels, (5 * 20 + 15) * 4);
                double ratio = (Math.Max(first, second) + 0.05) / (Math.Min(first, second) + 0.05);
                measurements.Add(new { Theme = theme, Foreground = foreground, Background = background, Minimum = minimum, Ratio = ratio });
                if (ratio < minimum)
                    throw new InvalidOperationException($"{theme} {foreground}/{background} contrast {ratio:F3} is below {minimum:F1}:1.");
                themePanel.Children.Add(new Border
                {
                    Background = back, BorderBrush = foreground == "FieldBorder" ? front : null,
                    BorderThickness = new Thickness(1), Width = 460, Margin = new Thickness(8), Padding = new Thickness(8),
                    Child = new TextBlock { Text = $"{foreground}/{background} · 파이프라인 Pipeline · {ratio:F2}:1",
                        FontFamily = family, FontSize = 13, Foreground = foreground == "FieldBorder" ? (Brush)resources[prefix + "TextBrush"] : front }
                });
            }
            samples.Children.Add(themePanel);
        }
        File.WriteAllText(Path.ChangeExtension(outputPath, ".measurements.json"), JsonSerializer.Serialize(
            new { Fonts = fontEvidence, Contrast = measurements }, new JsonSerializerOptions { WriteIndented = true }));
        return CaptureElement(samples, outputPath, 960, 920);

        static IEnumerable<GlyphRunDrawing> GlyphRuns(Drawing drawing)
        {
            if (drawing is GlyphRunDrawing glyph) yield return glyph;
            if (drawing is DrawingGroup group)
                foreach (Drawing child in group.Children)
                    foreach (GlyphRunDrawing run in GlyphRuns(child)) yield return run;
        }

        static double Luminance(byte[] pixels, int offset)
        {
            static double Linear(byte value)
            {
                double component = value / 255D;
                return component <= 0.04045 ? component / 12.92 : Math.Pow((component + 0.055) / 1.055, 2.4);
            }
            return 0.2126 * Linear(pixels[offset + 2]) + 0.7152 * Linear(pixels[offset + 1]) + 0.0722 * Linear(pixels[offset]);
        }
    }


    private static CaptureResult CaptureWorkbenchShellTheme(string outputPath, int width, int height)
    {
        OpenVisionLanguageService.SetLanguage(OpenVisionLanguage.Korean, false);
        OpenVisionShellHostView shellHost = CreateShellHost("Smoke_WorkbenchTheme", seedMainLayer: false);
        return CaptureWindowWithContent(shellHost, outputPath, width, height, () =>
        {
            int runsBefore = shellHost.NativePreviewRunCount;
            int layersBefore = shellHost.LayerDocumentCount;
            AssertToolRailIconInteractionTheme(shellHost);
            foreach ((string id, MahApps.Metro.IconPacks.PackIconMaterialKind expected) in new[]
            {
                ("HostToolNav_EdgeBasedMatching", MahApps.Metro.IconPacks.PackIconMaterialKind.ShapeOutline),
                ("HostToolNav_AffineTransform", MahApps.Metro.IconPacks.PackIconMaterialKind.AxisArrow),
                ("HostToolNav_Mean", MahApps.Metro.IconPacks.PackIconMaterialKind.Brightness6)
            })
            {
                Button button = FindVisualChildren<Button>(shellHost).First(item => AutomationProperties.GetAutomationId(item) == id);
                MahApps.Metro.IconPacks.PackIconMaterial icon = FindVisualChildren<MahApps.Metro.IconPacks.PackIconMaterial>(button).First();
                if (icon.Kind != expected) throw new InvalidOperationException($"{id} icon {icon.Kind} does not match {expected}.");
            }
            FontFamily family = (FontFamily)shellHost.FindResource("OpenVision.Workbench.FontFamily");
            TextBlock title = FindNamedVisualChild<TextBlock>(shellHost, "txtHostWorkspaceEmptyTitle");
            if (title == null || title.FontFamily.Source != family.Source)
                throw new InvalidOperationException("Shell workspace text did not inherit the Workbench font.");
            shellHost.SetToolSearchTextForTest("핀 간격 mm");
            Pump(6);
            TextBox search = FindVisualChildren<TextBox>(shellHost).First(item => AutomationProperties.GetAutomationId(item) == "HostToolSearchTextBox");
            Border chrome = FindNamedVisualChild<Border>(search, "fieldChrome")
                ?? throw new InvalidOperationException("Search field chrome did not render.");
            AssertBrushContrast(search.Foreground, chrome.Background, "Workbench search entered text");
            shellHost.ClearToolSearchForTest();
            Pump(6);
            if (shellHost.NativePreviewRunCount != runsBefore || shellHost.LayerDocumentCount != layersBefore
                || shellHost.HasNativePreviewResult || shellHost.IsNativeDocumentActive || shellHost.IsActiveWpfToolWindowVisibleForTest)
                throw new InvalidOperationException("Workbench font/focus/search verification caused execution, layers or tool activation.");
        }, captureFloatingToolWindow: false);
    }



    private static void RequireIsolatedScreenshotDataRoot()
    {
        string? configured = Environment.GetEnvironmentVariable("OPENVISIONLAB_DATA_ROOT");
        if (string.IsNullOrWhiteSpace(configured) || !Path.IsPathFullyQualified(configured))
            throw new InvalidOperationException("Screenshot targets require explicit absolute OPENVISIONLAB_DATA_ROOT before application initialization.");
        string root = Path.GetFullPath(configured).TrimEnd(Path.DirectorySeparatorChar, Path.AltDirectorySeparatorChar);
        bool IsWithin(string path, string parent) => string.Equals(path, parent, StringComparison.OrdinalIgnoreCase)
            || path.StartsWith(parent.TrimEnd(Path.DirectorySeparatorChar, Path.AltDirectorySeparatorChar) + Path.DirectorySeparatorChar, StringComparison.OrdinalIgnoreCase);
        string defaultData = Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData), "OpenVisionLab");
        string installation = Path.GetFullPath(AppContext.BaseDirectory).TrimEnd(Path.DirectorySeparatorChar, Path.AltDirectorySeparatorChar);
        if (IsWithin(root, defaultData) || IsWithin(defaultData, root) || IsWithin(root, installation) || IsWithin(installation, root))
            throw new InvalidOperationException("Screenshot data root must be isolated from default user data and the runner installation.");
        bool physicalDRequired = Directory.Exists(@"D:\") && !string.Equals(Environment.GetEnvironmentVariable("CI"), "true", StringComparison.OrdinalIgnoreCase);
        if (physicalDRequired && !string.Equals(Path.GetPathRoot(root), @"D:\", StringComparison.OrdinalIgnoreCase))
            throw new InvalidOperationException("Screenshot data root must use physical D: storage on this workstation.");
        for (DirectoryInfo? directory = new DirectoryInfo(root); directory != null; directory = directory.Parent)
        {
            if (directory.Exists && (directory.Attributes & FileAttributes.ReparsePoint) != 0)
                throw new InvalidOperationException("Screenshot data root must use a physical path without directory links.");
        }
        Environment.SetEnvironmentVariable("OPENVISIONLAB_DATA_ROOT_RESOLVED", root);
    }

    private static CaptureResult CaptureMainHelpLifetime(string outputPath)
    {
        CaptureResult result = default;
        foreach (bool toast in new[] { false, true })
        {
            GlobalState global = new(); global.Recipe.Name = "Smoke_MainHelpLifetime_" + Guid.NewGuid().ToString("N");
            VisionPipeline pipeline = new() { Name = "Pipeline" };
            VisionPipelineStorage.Save(global.Recipe.Name, pipeline); VisionPipelineStorage.SaveActivePipelineName(global.Recipe.Name, pipeline.Name);
            global.System.SaveWorkbenchLayout(new SystemStateConfig());
            OpenVisionShellHostWindow window = new(new ApplicationRuntimeContext(global, new DisplayManagerService()));
            window.ClearValue(OpenVisionShellHostWindow.ClosingCommandProperty);
            OpenVisionWorkbenchViewModel model = window.ShellHostForSmoke.Workbench;
            string path = toast ? outputPath : Path.ChangeExtension(outputPath, ".shortcuts.png");
            result = CaptureStandaloneWindow(window, path, 1280, 760, () =>
            {
                ICommand command = (ICommand)model.GetType().GetProperty(toast ? "ShowProductInfoCommand" : "OpenShortcutsCommand")!.GetValue(model)!;
                command.Execute(null); Pump(5);
                string elementName = toast ? "mainProductInfoToast" : "mainShortcutsOverlay";
                if (FindNamedVisualChild<FrameworkElement>(window, elementName)?.IsVisible != true) throw new InvalidOperationException("Main help lifetime active state missing.");
                if (toast)
                {
                    var animation = (System.Windows.Media.Animation.Storyboard)typeof(OpenVisionShellHostWindow).GetField("productInfoAnimation", BindingFlags.NonPublic | BindingFlags.Instance)!.GetValue(window)!;
                    animation.SeekAlignedToLastTick(FindNamedVisualChild<Border>(window, elementName)!, TimeSpan.FromSeconds(0.2D), System.Windows.Media.Animation.TimeSeekOrigin.BeginTime); Pump(3);
                }
            });
            if (window.DataContext != null || window.ShellHostForSmoke != null || window.IsVisible
                || typeof(OpenVisionShellHostWindow).GetField("productInfoAnimation", BindingFlags.NonPublic | BindingFlags.Instance)!.GetValue(window) != null
                || typeof(OpenVisionShellHostWindow).GetField("shortcutPreviousFocus", BindingFlags.NonPublic | BindingFlags.Instance)!.GetValue(window) != null
                || (bool)model.GetType().GetProperty("IsShortcutsOpen")!.GetValue(model)!
                || ((ICommand)model.GetType().GetProperty("OpenShortcutsCommand")!.GetValue(model)!).CanExecute(null))
                throw new InvalidOperationException("Main help Window close retained active UI/focus/animation or enabled commands.");
            Delegate subscribers = (Delegate)model.GetType().GetField("ProductInfoRequested", BindingFlags.NonPublic | BindingFlags.Instance)!.GetValue(model)!;
            if (subscribers.GetInvocationList().Any(handler => ReferenceEquals(handler.Target, window)))
                throw new InvalidOperationException("Main product-info event retained closed Window.");
        }
        File.WriteAllText(Path.ChangeExtension(outputPath, ".json"), JsonSerializer.Serialize(new { Scope = "Inprocess quiet WPF lifetime; no actual EXE/dirty-close guard", Cases = new[] { "close with shortcut overlay open", "close with toast animation active" }, ReleasedFocus = true, ReleasedClock = true, UnsubscribedWindow = true, DisposedCommandsDisabled = true }, new JsonSerializerOptions { WriteIndented = true }));
        return result;
    }





    private static CaptureResult CaptureMainPreviousCaption(string outputPath)
    {
        GlobalState global = new(); global.Recipe.Name = "Smoke_MainPreviousCaption_" + Guid.NewGuid().ToString("N");
        VisionPipeline source = new() { Name = "Original" }; source.Steps.Add(new VisionPipelineStep { Name = new string('P', 48), ToolType = "Mean", InputLayer = "Main", OutputLayer = "KeepOutput" }); VisionPipelineStorage.Save(global.Recipe.Name, source); VisionPipelineStorage.SaveActivePipelineName(global.Recipe.Name, source.Name);
        string image = Path.Combine(Path.GetDirectoryName(outputPath)!, "previous-input.png"); using (Bitmap input = CreateWorkspaceSeedSmokeBitmap()) input.Save(image, System.Drawing.Imaging.ImageFormat.Png); global.System.SaveWorkbenchLayout(new SystemStateConfig());
        using DisplayManagerService display = new(); OpenVisionShellHostWindow window = new(new ApplicationRuntimeContext(global, display)); window.ClearValue(OpenVisionShellHostWindow.ClosingCommandProperty); OpenVisionShellHostView host = window.ShellHostForSmoke;
        return CaptureStandaloneWindow(window, outputPath, 1280, 760, () =>
        {
            if (!host.LoadMainImageFromFileForTest(image)) throw new InvalidOperationException("Previous caption input failed."); Pump(3); int runs = host.NativePreviewRunCount; List<object> cases = new();
            host.Workbench.Pipeline.PublishToolResult(0, new VisionPipelineStepResultSummary { Executed = true, Success = true, ExecutionState = VisionPipelineResultSummaryService.ExecutedState, ElapsedMilliseconds = 4D }, previous: true);
            foreach (string palette in new[] { "Dark", "Light" })
            foreach (OpenVisionLanguage locale in new[] { OpenVisionLanguage.Korean, OpenVisionLanguage.English })
            {
                (palette == "Dark" ? host.Workbench.SelectDarkThemeCommand : host.Workbench.SelectLightThemeCommand).Execute(null); OpenVisionLanguageService.SetLanguage(locale, false); Pump(4);
                OpenVisionWorkbenchStepViewModel row = host.Workbench.Pipeline.Rows.Single(); Border chip = FindVisualChildren<Border>(host).Single(frame => frame.Name == "statusChip" && ReferenceEquals(frame.DataContext, row)); TextBlock label = FindVisualChildren<TextBlock>(chip).Single(text => text.Name == "statusText");
                TextBlock expected = new() { Text = row.StatusText, FontFamily = label.FontFamily, FontStyle = label.FontStyle, FontWeight = label.FontWeight, FontStretch = label.FontStretch, FontSize = label.FontSize, FlowDirection = label.FlowDirection, Language = label.Language, UseLayoutRounding = label.UseLayoutRounding }; TextOptions.SetTextFormattingMode(expected, TextOptions.GetTextFormattingMode(label)); expected.Measure(new System.Windows.Size(double.PositiveInfinity, double.PositiveInfinity));
                TextBlock name = FindVisualChildren<TextBlock>(host).Single(text => text.Name == "workbenchStepName" && ReferenceEquals(text.DataContext, row));
                bool readable = row.StatusKind == "Previous" && row.StatusText == host.Workbench["Workbench.Status.Previous"] && chip.IsVisible && label.IsVisible && label.ActualWidth >= expected.DesiredSize.Width && label.ActualHeight >= expected.DesiredSize.Height && name.IsVisible && name.ActualWidth > 0D && name.TextTrimming == TextTrimming.CharacterEllipsis && name.ToolTip?.ToString() == row.Name;
                cases.Add(new { Palette = palette, Language = locale.ToString(), Label = label.Text, LabelVisible = label.IsVisible, Width = label.ActualWidth, RequiredWidth = expected.DesiredSize.Width, Height = label.ActualHeight, RequiredHeight = expected.DesiredSize.Height, FormattingMode = TextOptions.GetTextFormattingMode(label).ToString(), NameWidth = name.ActualWidth, NameVisible = name.IsVisible, NameTooltip = name.ToolTip?.ToString(), Readable = readable });
                ScreenshotPngWriter.WriteElementPng(window, Path.ChangeExtension(outputPath, $".{palette}-{locale}.png"), 1280, 760);
            }
            File.WriteAllText(Path.ChangeExtension(outputPath, ".json"), JsonSerializer.Serialize(new { Scope = "Main Compact previous caption/long-name layout, synthetic result, inprocess WPF only", Cases = cases, NoRun = host.NativePreviewRunCount == runs }, new JsonSerializerOptions { WriteIndented = true }));
            if (cases.Any(item => !(bool)item.GetType().GetProperty("Readable")!.GetValue(item)!)) throw new InvalidOperationException("Main Compact previous caption is hidden/clipped; see layout JSON.");
            if (host.NativePreviewRunCount != runs) throw new InvalidOperationException("Caption check executed preview.");
        });
    }

