                auto.SetCurrentValue(UIElement.IsEnabledProperty, true); all.SetCurrentValue(UIElement.IsEnabledProperty, true); model.AutoScroll = true; model.ShowEntireStream = true; Observe("recovered", true);
                void Observe(string state, bool expected)
                {
