                        bool aligned = box.Background is SolidColorBrush actual && wanted is SolidColorBrush brush && actual.Color == brush.Color;
                        bool bound = check.IsChecked == expected && (ReferenceEquals(check, auto) ? model.AutoScroll : model.ShowEntireStream) == expected;
                        bool tickAligned = tick.Visibility == (expected ? Visibility.Visible : Visibility.Collapsed);
                        rows.Add(new { check.Content, IsChecked = check.IsChecked, Color = (box.Background as SolidColorBrush)?.Color.ToString(), Aligned = aligned, BindingAligned = bound, TickAligned = tickAligned });
                        if (!aligned || !bound || !tickAligned) failures.Add(palette + "/" + state + "/" + check.Content);
                    }
                    string capture = Path.ChangeExtension(outputPath, "." + palette + "." + state + ".png"); ScreenshotPngWriter.WriteElementPng(host, capture, 1280, 760);
