    private static CaptureResult CaptureMainLogEmptyRecovery(string outputPath)
    {
        OpenVisionShellHostView host = CreateShellHost("Smoke_MainLogRecovery_" + Guid.NewGuid().ToString("N"), false);
        List<object> cases = new(); List<string> failures = new();
        return CaptureWindowWithContent(host, outputPath, 1280, 760, () =>
        {
            LogPanelView log = FindVisualChildren<LogPanelView>(host).Single(); LogPanelViewModel model = (LogPanelViewModel)log.DataContext;
            int runs = host.NativePreviewRunCount; byte[] working = VisionPipelineExecutionPlan.SerializePipeline(host.Workbench.Pipeline.WorkingCopyForTest);
            WaitForTaskWithPump(Task.Delay(180), 2000, "Main log reader drain"); host.Workbench.OpenLogCommand.Execute(null);
            foreach (string palette in new[] { "Dark", "Light" })
            {
                (palette == "Dark" ? host.Workbench.SelectDarkThemeCommand : host.Workbench.SelectLightThemeCommand).Execute(null);
                OpenVisionLanguageService.SetLanguage(palette == "Dark" ? OpenVisionLanguage.Korean : OpenVisionLanguage.English, false);
                model.ResetCommand.Execute(null); model.ShowEntireStream = false; model.SelectedLevel = "Any"; model.SearchText = string.Empty; model.IsDetailedMode = true;
                Observe("empty", false);
                LogManager.GetLogger("OpenVisionLab.Main93").Info("[System][Info][OwnedMain93] OwnedMain93 Recovery");
                WaitForTaskWithPump(Task.Delay(350), 2000, "Main log reader arrival");
                Observe("received", true);
                model.SearchText = "OwnedMain93 no matching row"; Observe("filtered-empty", false);
                model.SearchText = string.Empty; Observe("filter-restored", true);
                model.ResetCommand.Execute(null); Observe("reset", false);
                (palette == "Dark" ? host.Workbench.SelectLightThemeCommand : host.Workbench.SelectDarkThemeCommand).Execute(null);
                (palette == "Dark" ? host.Workbench.SelectDarkThemeCommand : host.Workbench.SelectLightThemeCommand).Execute(null);
                Observe("theme-restored", false);
                void Observe(string state, bool rowsExpected)
                {
                    Pump(4); ScrollViewer scroll = (ScrollViewer)log.FindName("emptyLogScroller"); Border empty = (Border)log.FindName("emptyLogState");
                    ListBox list = (ListBox)log.FindName("LogList"); scroll.ScrollToBottom(); Pump(3);
                    Visibility expected = rowsExpected ? Visibility.Collapsed : Visibility.Visible;
                    bool transition = model.HasVisibleLogs == rowsExpected && scroll.Visibility == expected && empty.Visibility == expected;
                    bool rowVisible = !rowsExpected || FindVisualChildren<TextBlock>(list).Any(text => text.Text == "OwnedMain93 Recovery" && text.IsVisible);
                    bool oneWrapper = FindVisualChildren<ScrollViewer>(log).Count(viewer => viewer.Name == "emptyLogScroller") == 1;
                    string capture = Path.ChangeExtension(outputPath, "." + palette + "." + state + ".png"); ScreenshotPngWriter.WriteElementPng(host, capture, 1280, 760);
                    cases.Add(new { Palette = palette, State = state, model.HasVisibleLogs, ScrollerVisibility = scroll.Visibility.ToString(), EmptyVisibility = empty.Visibility.ToString(), Transition = transition, RowVisible = rowVisible, OneWrapper = oneWrapper, Capture = capture });
                    if (!transition || !rowVisible || !oneWrapper) failures.Add(palette + "/" + state + ": empty/log transition");
                }
            }
            bool noRun = runs == host.NativePreviewRunCount; bool unchanged = working.SequenceEqual(VisionPipelineExecutionPlan.SerializePipeline(host.Workbench.Pipeline.WorkingCopyForTest));
            File.WriteAllText(Path.ChangeExtension(outputPath, ".json"), JsonSerializer.Serialize(new { Scope = "inprocess Main log data/empty/filter/reset/theme recovery; no actual input", Cases = cases, Failures = failures, NoRun = noRun, WorkingUnchanged = unchanged, ProductSHA256 = Convert.ToHexString(SHA256.HashData(File.ReadAllBytes(typeof(OpenVisionShellHostView).Assembly.Location))), LogModuleSHA256 = Convert.ToHexString(SHA256.HashData(File.ReadAllBytes(typeof(LogPanelView).Assembly.Location))) }, new JsonSerializerOptions { WriteIndented = true }));
            if (!noRun || !unchanged || failures.Count > 0) throw new InvalidOperationException(string.Join(" | ", failures));
        });
    }

    private static CaptureResult CaptureMainLogEmptyScroll(string outputPath, int width, int height, bool standalone)
    {
        OpenVisionShellHostView? host = standalone ? null : CreateShellHost("Smoke_MainEmptyLog_" + Guid.NewGuid().ToString("N"), false);
        FrameworkElement content = host != null ? host : new LogPanelView(); List<object> cases = new(); List<string> failures = new();
        return CaptureWindowWithContent(content, outputPath, width, height, () =>
        {
            LogPanelView log = content is LogPanelView direct ? direct : FindVisualChildren<LogPanelView>(content).Single();
            LogPanelViewModel model = (LogPanelViewModel)log.DataContext; int runs = host?.NativePreviewRunCount ?? 0;
            byte[]? working = host == null ? null : VisionPipelineExecutionPlan.SerializePipeline(host.Workbench.Pipeline.WorkingCopyForTest);
            WaitForTaskWithPump(Task.Delay(180), 2000, "Main empty log reader drain"); model.ResetCommand.Execute(null);
            foreach (string palette in standalone ? new[] { "StandaloneDefault" } : new[] { "Dark", "Light" })
            {
                if (host != null) (palette == "Dark" ? host.Workbench.SelectDarkThemeCommand : host.Workbench.SelectLightThemeCommand).Execute(null);
                foreach (OpenVisionLanguage language in standalone ? new[] { OpenVisionLanguage.English } : new[] { OpenVisionLanguage.Korean, OpenVisionLanguage.English })
                {
                    OpenVisionLanguageService.SetLanguage(language, false); host?.Workbench.OpenLogCommand.Execute(null);
                    foreach (bool detailed in standalone ? new[] { true } : new[] { false, true })
                    {
                        model.ShowEntireStream = false; model.SelectedLevel = "Any"; model.SearchText = string.Empty; model.IsDetailedMode = detailed; Pump(4);
                        ScrollViewer? scroll = log.FindName("emptyLogScroller") as ScrollViewer;
                        if (standalone)
                        {
                            if (scroll != null) failures.Add("Standalone default visual tree changed");
                            string capture = Path.ChangeExtension(outputPath, ".StandaloneDefault.English.details.png"); ScreenshotPngWriter.WriteElementPng(content, capture, width, height);
                            cases.Add(new { Palette = palette, Language = language.ToString(), DefaultTreeUnchanged = scroll == null, Capture = capture });
                            continue;
                        }
                        if (scroll == null) throw new InvalidOperationException("Main empty scroller missing");
                        TextBlock hint = FindVisualChildren<TextBlock>(scroll).Single(text => AutomationProperties.GetAutomationId(text) == "LogPanelEmptyActionHint");
                        scroll.ScrollToTop(); Pump(3); string prefix = "." + palette + "." + language + "." + (detailed ? "details" : "summary");
                        string before = Path.ChangeExtension(outputPath, prefix + ".top.png"); ScreenshotPngWriter.WriteElementPng(content, before, width, height);
                        scroll.ScrollToBottom(); Pump(4); Rect bounds = hint.TransformToAncestor(scroll).TransformBounds(new Rect(hint.RenderSize));
                        bool reachable = bounds.Top >= -1D && bounds.Bottom <= scroll.ViewportHeight + 1D && bounds.Left >= -1D && bounds.Right <= scroll.ViewportWidth + 1D;
                        if (!reachable) failures.Add(palette + "/" + language + "/" + detailed + ": last hint not reachable " + bounds);
                        if (host != null && scroll.VerticalScrollBarVisibility != ScrollBarVisibility.Auto) failures.Add("Main empty scrolling missing");
                        if (host == null && scroll.VerticalScrollBarVisibility != ScrollBarVisibility.Disabled) failures.Add("Standalone default scrollbar contract changed");
                        string after = Path.ChangeExtension(outputPath, prefix + ".bottom.png"); ScreenshotPngWriter.WriteElementPng(content, after, width, height);
                        cases.Add(new { Palette = palette, Language = language.ToString(), Detailed = detailed, Reachable = reachable, scroll.ScrollableHeight, scroll.ViewportHeight, HintBounds = bounds.ToString(), Before = before, After = after });
                    }
                }
            }
            bool noRun = host == null || runs == host.NativePreviewRunCount;
            bool unchanged = host == null || working!.SequenceEqual(VisionPipelineExecutionPlan.SerializePipeline(host.Workbench.Pipeline.WorkingCopyForTest));
            File.WriteAllText(Path.ChangeExtension(outputPath, ".json"), JsonSerializer.Serialize(new { Scope = "inprocess Main log empty caption reachability; ScrollToBottom is synthetic, not actual pointer wheel", Cases = cases, Failures = failures, NoRun = noRun, WorkingUnchanged = unchanged, ProductSHA256 = Convert.ToHexString(SHA256.HashData(File.ReadAllBytes(typeof(OpenVisionShellHostView).Assembly.Location))), LogModuleSHA256 = Convert.ToHexString(SHA256.HashData(File.ReadAllBytes(typeof(LogPanelView).Assembly.Location))) }, new JsonSerializerOptions { WriteIndented = true }));
            if (!noRun || !unchanged || failures.Count > 0) throw new InvalidOperationException(string.Join(" | ", failures));
        });
    }

    private static CaptureResult CaptureMainLogPalette(string outputPath, int width, int height, bool standalone)
    {
        OpenVisionShellHostView? host = standalone ? null : CreateShellHost("Smoke_MainLogPalette_" + Guid.NewGuid().ToString("N"), false);
        FrameworkElement content = host != null ? host : new LogPanelView();
        List<object> cases = new(); List<string> failures = new();
        return CaptureWindowWithContent(content, outputPath, width, height, () =>
        {
            LogPanelView log = content is LogPanelView direct ? direct : FindVisualChildren<LogPanelView>(content).Single();
            LogPanelViewModel model = (LogPanelViewModel)log.DataContext;
            int runs = host?.NativePreviewRunCount ?? 0;
            byte[]? working = host == null ? null : VisionPipelineExecutionPlan.SerializePipeline(host.Workbench.Pipeline.WorkingCopyForTest);
            var tone = new OpenVisionLab.Logging.Controls.Converter.LogToneBrushConverter();
            foreach (string level in new[] { "Info", "Debug", "Warning", "Error", "error", "eRrOr", "", "unknown" })
            {
                Brush value = (Brush)tone.Convert(level, typeof(Brush), null!, CultureInfo.InvariantCulture);
                Color expected = level.Equals("Error", StringComparison.OrdinalIgnoreCase) ? Colors.IndianRed : level == "Warning" ? Colors.Khaki : level == "Debug" ? Colors.LightSteelBlue : Colors.WhiteSmoke;
                if (value is not SolidColorBrush brush || brush.Color != expected) failures.Add("Standalone converter contract: " + level);
                if (level.Equals("Error", StringComparison.OrdinalIgnoreCase) && !(bool)tone.Convert(level, typeof(bool), "Error", CultureInfo.InvariantCulture)) failures.Add("Case-insensitive level match: " + level);
            }
            foreach (string palette in standalone ? new[] { "StandaloneDefault" } : new[] { "Dark", "Light" })
            {
                if (host != null) (palette == "Dark" ? host.Workbench.SelectDarkThemeCommand : host.Workbench.SelectLightThemeCommand).Execute(null);
                foreach (OpenVisionLanguage language in new[] { OpenVisionLanguage.Korean, OpenVisionLanguage.English })
                {
                    OpenVisionLanguageService.SetLanguage(language, false);
                    host?.Workbench.OpenLogCommand.Execute(null);
                    model.ShowEntireStream = true; model.SelectedLevel = "Any"; model.SearchText = string.Empty; model.IsDetailedMode = true;
                    WaitForTaskWithPump(Task.Delay(180), 2000, "Main log initial reader drain"); model.ResetCommand.Execute(null); Pump(3);
                    Observe("empty");
                    foreach (string level in new[] { "Info", "Debug", "Warning", "Error" })
                        model.Logs.Add(new OpenVisionLab.Logging.Controls.Model.LogLine(DateTime.Now, "", "System", level, "OwnedMain93", "Main93 " + level + " readable message", "Main93 " + level));
                    model.SearchText = "Main93"; Pump(4);
                    ListBox list = (ListBox)log.FindName("LogList");
                    foreach (var row in model.FilteredLogs.ToArray()) { list.ScrollIntoView(row); Pump(3); Observe("level-" + row.Level, row); }
                    model.ShowEntireStream = false; model.SelectedLevel = "Warning"; Pump(3); Observe("filtered-warning");
                    model.SelectedLevel = "Any"; model.SearchText = string.Empty; Pump(3);
                    TextBox search = FindVisualChildren<TextBox>(log).Single(); search.Focus(); Pump(3); Observe("synthetic-focus");
                    model.ShowEntireStream = true; Pump(3); Observe("disabled-filters");
                    model.ShowEntireStream = false; Pump(3); ComboBox filter = FindVisualChildren<ComboBox>(log).First();
                    filter.IsDropDownOpen = true; Pump(5); Observe("popup"); filter.IsDropDownOpen = false; Pump(3);
                    model.ResetCommand.Execute(null); Pump(3); Observe("clear-recovery");

                    void Observe(string state, OpenVisionLab.Logging.Controls.Model.LogLine? row = null)
                    {
                        Grid root = FindVisualChildren<Grid>(log).First();
                        Brush expectedRoot = host == null ? (Brush)new BrushConverter().ConvertFromString("#111821")! : (Brush)host.FindResource("OpenVision.Workbench.PanelBrush");
                        string actualRoot = root.Background?.ToString() ?? ""; bool paletteAligned = actualRoot == expectedRoot.ToString();
                        if (!paletteAligned) failures.Add(palette + "/" + state + ": local root palette " + actualRoot);
                        List<object> texts = new();
                        foreach (TextBlock text in FindVisualChildren<TextBlock>(log).Where(text => text.IsVisible && text.Text.Length > 0 && (row == null || ReferenceEquals(text.DataContext, row))))
                        {
                            Brush? background = null; for (DependencyObject parent = VisualTreeHelper.GetParent(text); parent != null; parent = VisualTreeHelper.GetParent(parent))
                            {
                                if (parent is Border border && border.Background is SolidColorBrush b && b.Color.A == 255) { background = b; break; }
                                if (parent is Panel panel && panel.Background is SolidColorBrush p && p.Color.A == 255) { background = p; break; }
                            }
                            double contrast = text.Foreground is SolidColorBrush fg && background is SolidColorBrush bg ? GetContrastRatio(fg.Color, bg.Color) : 0D;
                            bool levelText = row != null && text.Text == row.Message;
                            if (host != null && levelText && contrast < 4.5D) failures.Add(palette + "/" + language + "/" + state + ": message contrast " + contrast);
                            if (host == null && levelText && text.Foreground is SolidColorBrush legacyBrush)
                            {
                                Color expectedTone = row!.Level == "Error" ? Colors.IndianRed : row.Level == "Warning" ? Colors.Khaki : row.Level == "Debug" ? Colors.LightSteelBlue : Colors.WhiteSmoke;
                                if (legacyBrush.Color != expectedTone) failures.Add("Standalone rendered tone changed: " + row.Level);
                            }
                            texts.Add(new { text.Text, Foreground = text.Foreground?.ToString(), Background = background?.ToString(), Contrast = contrast, text.Opacity, LevelMessage = levelText });
                        }
                        if (row != null && texts.Count == 0) failures.Add("Expected level row not realized: " + row.Level);
                        string capture = Path.ChangeExtension(outputPath, "." + palette + "." + language + "." + state + ".png");
                        ScreenshotPngWriter.WriteElementPng(content, capture, width, height);
                        string? popupCapture = null;
                        if (state == "popup")
                        {
                            ComboBox filter = FindVisualChildren<ComboBox>(log).First(); Popup popup = (Popup)filter.Template.FindName("PART_Popup", filter);
                            if (popup.Child is FrameworkElement child) { popupCapture = Path.ChangeExtension(capture, ".popup.png"); ScreenshotPngWriter.WriteElementPng(child, popupCapture, Math.Max(1, (int)Math.Ceiling(child.ActualWidth)), Math.Max(1, (int)Math.Ceiling(child.ActualHeight))); }
                            else failures.Add("Main log popup child missing");
                        }
                        cases.Add(new { Palette = palette, Language = language.ToString(), State = state, Standalone = standalone, PaletteAligned = paletteAligned, ActualRoot = actualRoot, Texts = texts, Filtered = model.FilteredLogs.Count, Capture = capture, PopupCapture = popupCapture });
                    }
                }
            }
            bool noRun = host == null || host.NativePreviewRunCount == runs;
            bool unchanged = host == null || working!.SequenceEqual(VisionPipelineExecutionPlan.SerializePipeline(host.Workbench.Pipeline.WorkingCopyForTest));
            if (!noRun || !unchanged) failures.Add("Log presentation changed execution or working pipeline");
            File.WriteAllText(Path.ChangeExtension(outputPath, ".json"), JsonSerializer.Serialize(new { Scope = "inprocess Main log palette and standalone fallback; synthetic focus/popup/disabled, no actual input", Cases = cases, Failures = failures, NoRun = noRun, WorkingUnchanged = unchanged, Module = typeof(OpenVisionShellHostView).Assembly.Location, ProductSHA256 = Convert.ToHexString(SHA256.HashData(File.ReadAllBytes(typeof(OpenVisionShellHostView).Assembly.Location))), LogModuleSHA256 = Convert.ToHexString(SHA256.HashData(File.ReadAllBytes(typeof(LogPanelView).Assembly.Location))), FinalN = (int?)null, Main96 = false }, new JsonSerializerOptions { WriteIndented = true }));
            if (failures.Count > 0) throw new InvalidOperationException(string.Join(" | ", failures));
        });
    }


    private static CaptureResult CaptureMainToolChromeTheme(string outputPath, int width, int height)
    {
        GlobalState global = new(); global.Recipe.Name = "Smoke_MainChrome_" + Guid.NewGuid().ToString("N");
        VisionPipelineStorage.Save(global.Recipe.Name, new VisionPipeline { Name = "Main" }); global.System.SaveWorkbenchLayout(new SystemStateConfig());
        string savedPath = RecipeWorkspaceService.GetVisionPipelinePath(global.Recipe.Name, "Main"); byte[] savedBytes = File.ReadAllBytes(savedPath);
        using DisplayManagerService display = new(); OpenVisionShellHostWindow window = new(new ApplicationRuntimeContext(global, display));
        window.ClearValue(OpenVisionShellHostWindow.ClosingCommandProperty); OpenVisionShellHostView host = window.ShellHostForSmoke;
        return CaptureStandaloneWindow(window, outputPath, width, height, () =>
        {
            var model = host.Workbench; model.Tool.ConfigureAutoRunPreference(() => false, _ => { });
            string image = Path.ChangeExtension(outputPath, ".input.png"); using (Bitmap input = CreateWorkspaceSeedSmokeBitmap()) input.Save(image, ImageFormat.Png);
            if (!host.LoadMainImageFromFileForTest(image)) throw new InvalidOperationException("Main chrome owned valid input");
            byte[] working = VisionPipelineExecutionPlan.SerializePipeline(model.Pipeline.WorkingCopyForTest); byte[] imageBytes = File.ReadAllBytes(image);
            int runs = host.NativePreviewRunCount; List<object> cases = new(); List<string> failures = new(); List<OpenVisionNativeToolDocument> documents = new();
            string Wanted(string key) => ((Brush)host.FindResource("OpenVision.Workbench." + key)).ToString();
            string Color(Brush brush) => brush?.ToString() ?? "";
            foreach (string palette in new[] { "Dark", "Light" })
            foreach (OpenVisionLanguage language in new[] { OpenVisionLanguage.Korean, OpenVisionLanguage.English })
            foreach (VISION_MENU menu in new[] { VISION_MENU.Threshold, VISION_MENU.Mean, VISION_MENU.Arithmetic })
            {
                (palette == "Dark" ? model.SelectDarkThemeCommand : model.SelectLightThemeCommand).Execute(null);
                OpenVisionLanguageService.SetLanguage(language, false); host.SelectToolForTest(menu); Pump(6);
                OpenVisionNativeToolDocument document = host.ActiveNativeDocumentForTest!;
                FrameworkElement shell = (FrameworkElement)document.View.FindName("toolShell");
                if (!documents.Contains(document)) documents.Add(document);
                Grid root = (Grid)shell.FindName("shellRoot");
                HeaderedContentControl[] groups = new[] { "gbInputLayer", "gbInputA", "gbInputB", "gbOutputLayer" }
                    .Select(name => shell.FindName(name) as HeaderedContentControl).Where(group => group != null && group.IsVisible).ToArray()!;
                ComboBox[] combos = groups.SelectMany(group => FindVisualChildren<ComboBox>(group)).Where(combo => combo.IsVisible).ToArray();
                Button[] buttons = new[] { "btnWorkbenchDefaults", "btnAddPipeline", "btnRunPreview", "btnRunOffset", "btnNImageVerification" }
                    .Select(name => shell.FindName(name) as Button).Where(button => button != null && button.IsVisible).ToArray()!;
                Observe("normal");
                if (language == OpenVisionLanguage.English && menu == VISION_MENU.Threshold)
                {
                    ComboBox input = combos[0]; input.Focus(); Pump(3); Observe("synthetic-focus");
                    input.IsDropDownOpen = true; Pump(4); Observe("synthetic-popup"); input.IsDropDownOpen = false;
                    input.SetCurrentValue(UIElement.IsEnabledProperty, false); Pump(3); Observe("synthetic-disabled");
                    input.SetCurrentValue(UIElement.IsEnabledProperty, true); Keyboard.ClearFocus(); Pump(3); Observe("recovered");
                }
                void Observe(string state)
                {
                    Pump(3); List<string> mismatches = new();
                    BindingExpression? themeBinding = BindingOperations.GetBindingExpression(shell, OpenVisionWorkbenchThemeBehavior.ThemeNameProperty);
                    bool bound = themeBinding?.Status == BindingStatus.Active && ReferenceEquals(themeBinding.DataItem, model);
                    if (!bound) mismatches.Add("Main theme source not bound");
                    if (combos.Length != (menu == VISION_MENU.Arithmetic ? 3 : 2)) mismatches.Add("required common route fields absent");
                    if (Color(root.Background) != Wanted("PanelBrush")) mismatches.Add("common root background " + Color(root.Background));
                    Panel parameters = (Panel)shell.FindName("parameterPanel");
                    bool parametersPreserved = Color(parameters.Background) == Color((Brush)shell.FindResource("VisionTool.SurfaceBrush"));
                    if (!parametersPreserved) mismatches.Add("native parameter backdrop changed");
                    List<object> fields = new();
                    foreach (ComboBox combo in combos)
                    {
                        Border chrome = (Border)combo.Template.FindName("comboChrome", combo);
                        Border cue = (Border)combo.Template.FindName("comboFocusGlow", combo);
                        ContentPresenter content = (ContentPresenter)combo.Template.FindName("contentSite", combo);
                        TextBlock[] texts = FindVisualChildren<TextBlock>(content).Where(label => label.IsVisible && !string.IsNullOrEmpty(label.Text)).ToArray();
                        TextBox editable = (TextBox)combo.Template.FindName("PART_EditableTextBox", combo);
                        bool editableAligned = !combo.IsEditable || Color(editable.Foreground) == Color(combo.Foreground);
                        bool field = Color(chrome.Background) == Wanted(combo.IsDropDownOpen ? "PressedBrush" : "PanelAltBrush") && editableAligned &&
                            Color(cue.BorderBrush) == Wanted("AccentBrush") && texts.All(label => Color(label.Foreground) == Color(combo.Foreground));
                        if (!field) mismatches.Add(combo.Name + " rendered route palette/text");
                        fields.Add(new { combo.Name, combo.IsEnabled, combo.SelectedItem, combo.IsKeyboardFocusWithin, combo.IsDropDownOpen,
                            Background = Color(chrome.Background), Foreground = Color(combo.Foreground), FocusBrush = Color(cue.BorderBrush), FocusOpacity = cue.Opacity,
                            Editable = combo.IsEditable ? new { editable.Text, Foreground = Color(editable.Foreground), Aligned = editableAligned } : null,
                            Texts = texts.Select(label => new { label.Text, Foreground = Color(label.Foreground) }).ToArray(), Aligned = field });
                    }
                    List<object> actions = new();
                    foreach (Button button in buttons)
                    {
                        bool primary = button.Name is "btnRunPreview" or "btnRunOffset";
                        string expected = Wanted(primary && button.IsEnabled ? "AccentBrush" : "PanelAltBrush");
                        bool aligned = !button.IsEnabled || Color(button.Background) == expected || (!primary && Color(button.Background) == Wanted("RaisedBrush"));
                        if (!aligned) mismatches.Add(button.Name + " action palette " + Color(button.Background));
                        actions.Add(new { button.Name, button.IsEnabled, Background = Color(button.Background), Foreground = Color(button.Foreground), Aligned = aligned });
                    }
                    List<object> popups = new();
                    foreach (ComboBox combo in combos.Where(field => field.IsDropDownOpen))
                    {
                        Popup popup = (Popup)combo.Template.FindName("PART_Popup", combo);
                        if (popup.Child is FrameworkElement child)
                        {
                            string popupCapture = Path.ChangeExtension(outputPath, "." + palette + "." + language + "." + menu + ".popup-child.png");
                            TextBlock[] labels = FindVisualChildren<TextBlock>(child).Where(label => label.IsVisible && !string.IsNullOrEmpty(label.Text)).ToArray();
                            bool aligned = labels.Length > 0 && labels.All(label => Color(label.Foreground) == Wanted("TextBrush"));
                            if (!aligned) mismatches.Add("popup content palette/text");
                            ScreenshotPngWriter.WriteElementPng(child, popupCapture, Math.Max(1, (int)Math.Ceiling(child.ActualWidth)), Math.Max(1, (int)Math.Ceiling(child.ActualHeight)));
                            popups.Add(new { combo.Name, Aligned = aligned, Labels = labels.Select(label => new { label.Text, Foreground = Color(label.Foreground) }).ToArray(), Capture = popupCapture });
                        }
                    }
                    string capture = Path.ChangeExtension(outputPath, "." + palette + "." + language + "." + menu + "." + state + ".png");
                    ScreenshotPngWriter.WriteElementPng(window, capture, width, height);
                    if (mismatches.Count > 0) failures.Add(palette + "/" + language + "/" + menu + "/" + state + ": " + string.Join(", ", mismatches));
                    cases.Add(new { Palette = palette, Language = language.ToString(), Tool = menu.ToString(), State = state, ThemeBinding = bound, RootBackground = Color(root.Background), ParameterBackground = Color(parameters.Background), ParametersPreserved = parametersPreserved,
                        Groups = groups.Select(group => new { group.Name, group.Header, Foreground = Color(group.Foreground) }).ToArray(), Fields = fields, Actions = actions, Popups = popups, Capture = capture, Failures = mismatches });
                }
                host.CloseActiveWpfToolWindowForTest(); Pump(3);
            }
            int released = 0;
            foreach (OpenVisionNativeToolDocument document in documents)
            {
                FrameworkElement shell = (FrameworkElement)document.View.FindName("toolShell"); document.Dispose();
                if (BindingOperations.GetBindingExpression(shell, OpenVisionWorkbenchThemeBehavior.ThemeNameProperty) == null) released++;
                else failures.Add("disposed native theme source retained");
            }
            bool noRun = host.NativePreviewRunCount == runs;
            bool unchanged = working.SequenceEqual(VisionPipelineExecutionPlan.SerializePipeline(model.Pipeline.WorkingCopyForTest));
            bool savedUnchanged = savedBytes.SequenceEqual(File.ReadAllBytes(savedPath)), inputUnchanged = imageBytes.SequenceEqual(File.ReadAllBytes(image));
            File.WriteAllText(Path.ChangeExtension(outputPath, ".json"), JsonSerializer.Serialize(new { Scope = "inprocess Main common tool chrome theme only; synthetic focus/popup/disabled, no actual input or algorithm campaign", Cases = cases, Failures = failures,
                NoRun = noRun, WorkingUnchanged = unchanged, SavedUnchanged = savedUnchanged, InputUnchanged = inputUnchanged, ReleasedThemeBindings = released, Documents = documents.Count,
                ProductSHA256 = Convert.ToHexString(SHA256.HashData(File.ReadAllBytes(typeof(OpenVisionShellHostView).Assembly.Location))) }, new JsonSerializerOptions { WriteIndented = true }));
            if (!noRun || !unchanged || !savedUnchanged || !inputUnchanged || failures.Count > 0) throw new InvalidOperationException(string.Join(" | ", failures));
        });
    }

    private static void AssertLoadedMainBannerAbsent(OpenVisionShellHostView host, bool sampleExpected = false)
    {
        if (FindVisualChildrenIncludingSelf<FrameworkElement>(host).Any(item => AutomationProperties.GetAutomationId(item).StartsWith("WorkspaceMainAction", StringComparison.Ordinal)))
            throw new InvalidOperationException("Duplicate loaded-image ready banner remains in the visual tree.");
        Grid workspace = (Grid)host.FindName("wpfLayerWorkspace");
        if (!sampleExpected && workspace.RowDefinitions[1].ActualHeight != 0)
            throw new InvalidOperationException("Normal input retained a ready-banner row height: " + workspace.RowDefinitions[1].ActualHeight);
    }

    private static CaptureResult CaptureMainReadyToolOpenLayout(string outputPath, int width, int height)
    {
        GlobalState global = new(); global.Recipe.Name = "Smoke_MainGuideBounds_" + Guid.NewGuid().ToString("N");
        VisionPipeline saved = new() { Name = "Main" }; saved.Steps.Add(new VisionPipelineStep { Name = "Ready guide reference", ToolType = "Threshold", InputLayer = "Main", OutputLayer = "ReadyGuide_1" });
        VisionPipelineStorage.Save(global.Recipe.Name, saved); global.System.SaveWorkbenchLayout(new SystemStateConfig());
        string savedPath = RecipeWorkspaceService.GetVisionPipelinePath(global.Recipe.Name, "Main"); byte[] savedBytes = File.ReadAllBytes(savedPath);
        using DisplayManagerService display = new(); OpenVisionShellHostWindow window = new(new ApplicationRuntimeContext(global, display));
        window.ClearValue(OpenVisionShellHostWindow.ClosingCommandProperty); OpenVisionShellHostView host = window.ShellHostForSmoke;
        return CaptureStandaloneWindow(window, outputPath, width, height, () =>
        {
            var model = host.Workbench; model.Tool.ConfigureAutoRunPreference(() => false, _ => { }); int runs = host.NativePreviewRunCount;
            byte[] working = VisionPipelineExecutionPlan.SerializePipeline(model.Pipeline.WorkingCopyForTest);
            Pump(8); AssertLoadedMainBannerAbsent(host);
            string image = Path.ChangeExtension(outputPath, ".input.png"); using (Bitmap input = CreateWorkspaceSeedSmokeBitmap()) input.Save(image, ImageFormat.Png);
            if (!host.LoadMainImageFromFileForTest(image)) throw new InvalidOperationException("Main ready guide valid image precondition");
            host.SelectToolForTest(VISION_MENU.Threshold); model.SelectedBottomTab = 0;
            List<object> cases = new(); List<string> failures = new(); int captureIndex = 0;
            foreach (string palette in new[] { "Dark", "Light" })
            {
                (palette == "Dark" ? model.SelectDarkThemeCommand : model.SelectLightThemeCommand).Execute(null);
                foreach (OpenVisionLanguage language in new[] { OpenVisionLanguage.Korean, OpenVisionLanguage.English })
                {
                    OpenVisionLanguageService.SetLanguage(language, false);
                    foreach (bool wide in new[] { false, true })
                    {
                        if (model.IsToolPanelWide != wide) model.ToggleToolPanelWideCommand.Execute(null); Pump(8);
                        foreach (int split in new[] { 2, 4 })
                        {
                            (split == 2 ? model.Viewer.Split2Command : model.Viewer.Split4Command).Execute(null); Pump(8);
                            AssertLoadedMainBannerAbsent(host);
                            Grid workspace = (Grid)host.FindName("wpfLayerWorkspace");
                            List<object> elements = new();
                            foreach (FrameworkElement item in FindVisualChildren<OpenVisionLayerViewerView>(host))
                            {
                                AssertElementWithinAncestor("Main viewer", item, workspace);
                                OpenVisionLayerViewerView pane = (OpenVisionLayerViewerView)item;
                                foreach (FrameworkElement control in FindVisualChildren<FrameworkElement>(pane).Where(child => child.IsVisible && new[] { "MainPaneSource", "MainPanePin", "MainPaneMenu" }.Contains(AutomationProperties.GetAutomationId(child))))
                                {
                                    AssertElementWithinAncestor(AutomationProperties.GetAutomationId(control), control, pane);
                                    if (control.ActualWidth <= 0 || control.ActualHeight <= 0) throw new InvalidOperationException("Main pane command lost its hit area.");
                                }
                                if (pane.ZoomText.Length > 0) { pane.ShowOriginalSize(); pane.ZoomImage(40); Pump(2); if (pane.ZoomText != "4000%") throw new InvalidOperationException("Nonempty Main pane did not reach 4000%."); }
                                typeof(OpenVisionLayerViewerView).GetMethod("ApplyPointerStatus", BindingFlags.Instance | BindingFlags.NonPublic)!.Invoke(pane, new object[] { new OpenVisionZoomableImageStatus(true, int.MaxValue, int.MaxValue, 255, 255, 255, 255) }); Pump(2);
                                TextBlock pointer = FindNamedVisualChild<TextBlock>(pane, "mainPanePointerText")!, zoom = FindNamedVisualChild<TextBlock>(pane, "mainPaneZoomText")!;
                                AssertElementWithinAncestor("Main long pointer", pointer, pane); AssertElementWithinAncestor("Main zoom", zoom.Text.Length == 0 ? (FrameworkElement)zoom.Parent : zoom, pane);
                                if (!pointer.Text.Contains("2147483647", StringComparison.Ordinal) || pointer.Text != pane.PointerText || zoom.Text != pane.ZoomText || zoom.Text.Length > 0 && zoom.Text != "4000%")
                                    throw new InvalidOperationException("Main readout binding failed at its actual available width.");

                                Rect bounds = item.TransformToAncestor(window).TransformBounds(new Rect(new Point(0, 0), item.RenderSize));
                                elements.Add(new { item.Name, pane.MainPane.Source, Pointer = pointer.Text, Zoom = zoom.Text, Bounds = new { bounds.X, bounds.Y, bounds.Width, bounds.Height } });
                            }
                            string capture = Path.ChangeExtension(outputPath, ".case" + captureIndex++ + ".png");
                            System.Windows.Size captureSize = window.RenderSize;
                            OpenVisionLayerViewerView[] captureViews = FindVisualChildren<OpenVisionLayerViewerView>(host).ToArray();
                            System.Windows.Size[] paneSizes = captureViews.Select(view => view.RenderSize).ToArray();
                            foreach (OpenVisionLayerViewerView view in captureViews)
                            {
                                TextBlock pointer = FindNamedVisualChild<TextBlock>(view, "mainPanePointerText")!, zoom = FindNamedVisualChild<TextBlock>(view, "mainPaneZoomText")!;
                                AssertElementWithinAncestor("Main pointer within its readout", pointer, (FrameworkElement)pointer.Parent);
                                if (zoom.Text.Length > 0) AssertElementWithinAncestor("Main zoom within its readout", zoom, (FrameworkElement)zoom.Parent);
                            }
                            ScreenshotPngWriter.WriteDpiAwareWindowPng(window, capture);
                            if (window.RenderSize != captureSize || captureViews.Where((view, i) => view.RenderSize != paneSizes[i]).Any())
                                throw new InvalidOperationException("Main capture changed existing window/pane layout.");
                            cases.Add(new { Palette = palette, Language = language.ToString(), ToolPanelWide = wide, Split = split, Width = width, Height = height, BannerAbsent = true, CaptureLayoutUnchanged = true, ActualWindowSize = captureSize, Capture = capture, Elements = elements });
                        }
                    }
                }
            }
            BitmapSource retained = model.Shell.WorkspaceInputPreview;
            if (host.LoadMainImageFromFileForTest(Path.ChangeExtension(image, ".missing.png")) || !ReferenceEquals(retained, model.Shell.WorkspaceInputPreview))
                throw new InvalidOperationException("Failed image load replaced current Main input.");
            model.Images.SelectAllCommand.Execute(null); model.Images.RemoveCommand.Execute(null); Pump(8); AssertLoadedMainBannerAbsent(host);
            if (model.Shell.HasWorkspaceInputImage || !host.LoadMainImageFromFileForTest(image)) throw new InvalidOperationException("Main empty/reopen did not recover.");
            Pump(8); AssertLoadedMainBannerAbsent(host);
            bool savedUnchanged = savedBytes.SequenceEqual(File.ReadAllBytes(savedPath)), workingUnchanged = working.SequenceEqual(VisionPipelineExecutionPlan.SerializePipeline(model.Pipeline.WorkingCopyForTest)), noRun = host.NativePreviewRunCount == runs;
            if (!savedUnchanged || !workingUnchanged || !noRun) failures.Add("Main ready guide owner invariant");
            File.WriteAllText(Path.ChangeExtension(outputPath, ".json"), JsonSerializer.Serialize(new { Scope = "Main loaded/Tool-open viewer bounds and absent duplicate banner; in-process only", Cases = cases, Failures = failures, SavedUnchanged = savedUnchanged, WorkingUnchanged = workingUnchanged, NoRun = noRun, ProductSHA256 = Convert.ToHexString(SHA256.HashData(File.ReadAllBytes(typeof(OpenVisionShellHostView).Assembly.Location))) }, new JsonSerializerOptions { WriteIndented = true }));
            if (failures.Count > 0) throw new InvalidOperationException("Main ready guide bounds " + failures.Count + " failures; first=" + failures[0]);
        });
    }

    private static CaptureResult CaptureMainToolLlmFooterCancel(string outputPath, int width, int height, bool verifyRemovedStepStatus = false)
    {
        GlobalState global = new(); global.Recipe.Name = "Smoke_MainLlmCancel_" + Guid.NewGuid().ToString("N");
        VisionPipelineStorage.Save(global.Recipe.Name, new VisionPipeline { Name = "Main" }); global.System.SaveWorkbenchLayout(new SystemStateConfig());
        string savedPath = RecipeWorkspaceService.GetVisionPipelinePath(global.Recipe.Name, "Main"); byte[] saved = File.ReadAllBytes(savedPath);
        using DisplayManagerService display = new(); OpenVisionShellHostWindow window = new(new ApplicationRuntimeContext(global, display));
        window.ClearValue(OpenVisionShellHostWindow.ClosingCommandProperty); OpenVisionShellHostView host = window.ShellHostForSmoke;
        return CaptureStandaloneWindow(window, outputPath, width, height, () =>
        {
            var model = host.Workbench; model.Tool.ConfigureAutoRunPreference(() => false, _ => { }); model.SelectDarkThemeCommand.Execute(null);
            model.IsLeftCollapsed = false; model.IsRightCollapsed = true; model.IsToolPaletteCollapsed = false;
            int runs = host.NativePreviewRunCount; byte[] original = VisionPipelineExecutionPlan.SerializePipeline(model.Pipeline.WorkingCopyForTest);
            Button footer = FindNamedVisualChild<Button>(host, "mainToolLlmAssistant")!;
            Button close = FindVisualChildren<Button>(host).Single(item => AutomationProperties.GetAutomationId(item) == "HostRecipeManagerCloseButton");
            ToggleButton review = FindNamedVisualChild<ToggleButton>(host, "recipeAdvancedReviewToggle")!;
            Border panel = FindNamedVisualChild<Border>(host, "recipeManagerPanel")!;
            PresentationSource keyScope = PresentationSource.FromVisual(window) ?? throw new InvalidOperationException("Main cancel presentation source missing"); int checks = 0; List<object> cases = new();
            foreach (bool hasInput in verifyRemovedStepStatus ? new[] { false, true } : new[] { false })
            {
                if (hasInput)
                {
                    string imagePath = Path.ChangeExtension(outputPath, ".owned-input.png"); using (Bitmap image = CreateWorkspaceSeedSmokeBitmap()) image.Save(imagePath, ImageFormat.Png);
                    if (!host.LoadMainImageFromFileForTest(imagePath)) { throw new InvalidOperationException("Main removed status input precondition"); }
                    Pump(5);
                }
                foreach (OpenVisionLanguage language in new[] { OpenVisionLanguage.Korean, OpenVisionLanguage.English })
                {
                    string captureLanguage = language + (verifyRemovedStepStatus ? hasInput ? "-loaded" : "-empty" : string.Empty);
                    OpenVisionLanguageService.SetLanguage(language, false); Pump(3);
                    Require(!review.IsChecked.GetValueOrDefault() && !close.IsCancel && !panel.IsVisible, "closed mode has no work cancellation role");
                    FindNamedVisualChild<ScrollViewer>(host, "toolRailScroll")!.ScrollToEnd(); footer.Focus(); Pump(2); InvokeFooter();
                    File.WriteAllText(Path.ChangeExtension(outputPath, "." + captureLanguage + "-registration-debug.json"), JsonSerializer.Serialize(new { Review = review.IsChecked, close.IsCancel, PanelVisible = panel.IsVisible, WindowVisible = window.IsVisible, RegisteredWindow = AccessKeyManager.IsKeyRegistered(window, "\u001b"), RegisteredSource = AccessKeyManager.IsKeyRegistered(PresentationSource.FromVisual(window), "\u001b"), RegisteredActive = AccessKeyManager.IsKeyRegistered(null, "\u001b"), Source = PresentationSource.FromVisual(window)?.GetType().FullName, ProductSHA256 = Convert.ToHexString(SHA256.HashData(File.ReadAllBytes(typeof(OpenVisionShellHostView).Assembly.Location))) }, new JsonSerializerOptions { WriteIndented = true }));
                    if (!verifyRemovedStepStatus) ScreenshotPngWriter.WriteElementPng(window, Path.ChangeExtension(outputPath, "." + captureLanguage + "-registration-debug.png"), width, height);
                    Require(review.IsChecked == true && close.IsCancel && panel.IsVisible && AccessKeyManager.IsKeyRegistered(keyScope, "\u001b"), "work mode registers native Escape");
                    Snapshot("open"); AccessKeyManager.ProcessKey(keyScope, "\u001b", false); Pump(5);
                    Require(window.IsVisible && !panel.IsVisible && review.IsChecked == false && !close.IsCancel && !host.RecipeCommands.IsRecipeManagerDetailContextActive, "native cancellation uses existing return without closing Main");
                    Snapshot("returned"); InvokeFooter();
                    model.Pipeline.InsertStep(0, new VisionPipelineStep { Name = "CancelOnly", ToolType = "Mean", InputLayer = "Main", OutputLayer = "GuardOutput" }); Pump(2);
                    Require(model.Pipeline.IsDirty && host.RecipeCommands.IsRecipeManagerDetailContextActive, "owned Main working-copy dirty precondition");
                    byte[] dirty = VisionPipelineExecutionPlan.SerializePipeline(model.Pipeline.WorkingCopyForTest);
                    host.QueuePendingRecipeEditDecisionForTest(OpenVisionRecipePendingEditDecision.Cancel);
                    AccessKeyManager.ProcessKey(keyScope, "\u001b", false); Pump(5);
                    Require(window.IsVisible && panel.IsVisible && review.IsChecked == true && close.IsCancel && model.Pipeline.IsDirty && dirty.SequenceEqual(VisionPipelineExecutionPlan.SerializePipeline(model.Pipeline.WorkingCopyForTest)) && saved.SequenceEqual(File.ReadAllBytes(savedPath)), "existing Cancel decision restores role/panel and retains draft/saved state");
                    Snapshot("cancel-retained"); host.QueuePendingRecipeEditDecisionForTest(OpenVisionRecipePendingEditDecision.Discard);
                    AccessKeyManager.ProcessKey(keyScope, "\u001b", false); Pump(5);
                    Require(window.IsVisible && !panel.IsVisible && !close.IsCancel && !model.Pipeline.IsDirty && original.SequenceEqual(VisionPipelineExecutionPlan.SerializePipeline(model.Pipeline.WorkingCopyForTest)), "existing Discard decision returns Main and restores working source");
                    model.IsRightCollapsed = false; Pump(3); Snapshot("discard-return");
                    Border inspector = FindNamedVisualChild<Border>(host, "toolInspectorPanel")!;
                    File.WriteAllText(Path.ChangeExtension(outputPath, "." + captureLanguage + "-missing-step-return.json"), JsonSerializer.Serialize(new { StepCount = model.Pipeline.StepCount, Selection = model.Pipeline.SelectedStepIndex, ToolOpen = model.Tool.IsOpen, ToolTitle = model.Tool.Title, InspectorVisible = inspector.IsVisible, EmptyVisible = FindVisualChildren<Border>(host).Single(item => AutomationProperties.GetAutomationId(item) == "WorkbenchToolPanelEmpty").IsVisible }, new JsonSerializerOptions { WriteIndented = true }));
                    Require(model.Pipeline.StepCount == 0 && model.Pipeline.SelectedRow == null && !model.Tool.IsOpen && !inspector.IsVisible, "removed step does not retain an active Main inspector after Discard");
                    if (verifyRemovedStepStatus)
                    {
                        Require(FindNamedVisualChild<TextBlock>(host, "txtHostSelectedTool")!.Text == OpenVisionLanguageService.T(hasInput ? "Shell.MainAction.ImageReadyTitle" : "Shell.WorkspaceStatus.EmptyTitle"), "removed step status title reflects current input");
                        Require(FindNamedVisualChild<TextBlock>(host, "txtHostSelectedRoute")!.Text == OpenVisionLanguageService.T(hasInput ? "Shell.MainAction.ImageReadyRoute" : "Shell.WorkspaceStatus.EmptyRoute"), "removed step status route does not retain native tool output");
                        Require(FindNamedVisualChild<TextBlock>(host, "txtHostDirectBadge")!.Text == OpenVisionLanguageService.T(hasInput ? "Shell.MainAction.ReadyBadge" : "Shell.WorkspaceStatus.EmptyBadge"), "removed step status badge reflects current input");
                        Require(FindNamedVisualChild<TextBlock>(host, "txtHostDirectStatus")!.Text == OpenVisionLanguageService.T(hasInput ? "Shell.MainAction.ImageReadyStatus" : "Shell.WorkspaceStatus.EmptyStatus") && model.Shell.HasWorkspaceInputImage == hasInput, "removed step status detail/input projection remains current");
                    }
                    AccessKeyManager.ProcessKey(keyScope, "\u001b", false); Pump(2);
                    Require(window.IsVisible && !panel.IsVisible && !close.IsCancel, "repeated closed Escape has no work action");
                    cases.Add(new { Language = language.ToString(), HasInput = hasInput, RegisteredOnlyInWork = true, WindowRetained = window.IsVisible, CancelRetainedDraft = true, DiscardRetry = true, RepeatedClosedNoAction = true });
                    void Snapshot(string state) { if (!verifyRemovedStepStatus || state == "discard-return") ScreenshotPngWriter.WriteElementPng(window, Path.ChangeExtension(outputPath, "." + captureLanguage + "-" + state + ".png"), width, height); }
                }
            }
            bool noRun = runs == host.NativePreviewRunCount, workingSame = original.SequenceEqual(VisionPipelineExecutionPlan.SerializePipeline(model.Pipeline.WorkingCopyForTest)), savedSame = saved.SequenceEqual(File.ReadAllBytes(savedPath));
            Require(noRun && workingSame && savedSame, "cancel route noRun/working/saved invariant");
            File.WriteAllText(Path.ChangeExtension(outputPath, ".json"), JsonSerializer.Serialize(new { Scope = verifyRemovedStepStatus ? "Main removed-step status only; synthetic WPF/guard/input projection; no actual/nativeDPI/HTML/Main96 proof" : "Main footer return only; native WPF AccessKeyManager dispatch is synthetic, no actual key/nativeDPI/HTML/Main96 evidence", Width = width, Height = height, Checks = checks, Cases = cases, NoRun = noRun, WorkingUnchanged = workingSame, SavedUnchanged = savedSame, ProductSHA256 = Convert.ToHexString(SHA256.HashData(File.ReadAllBytes(typeof(OpenVisionShellHostView).Assembly.Location))) }, new JsonSerializerOptions { WriteIndented = true }));
            void InvokeFooter() { ((System.Windows.Automation.Provider.IInvokeProvider)System.Windows.Automation.Peers.UIElementAutomationPeer.CreatePeerForElement(footer)!.GetPattern(System.Windows.Automation.Peers.PatternInterface.Invoke)).Invoke(); Pump(6); }
            void Require(bool condition, string detail) { if (!condition) throw new InvalidOperationException("Main footer cancel: " + detail); checks++; }
        });
    }

    private static CaptureResult CaptureMainToolLlmFooter(string outputPath, int width, int height)
    {
        GlobalState global = new(); global.Recipe.Name = "Smoke_MainLlmFooter_" + Guid.NewGuid().ToString("N");
        VisionPipelineStorage.Save(global.Recipe.Name, new VisionPipeline { Name = "Main" }); global.System.SaveWorkbenchLayout(new SystemStateConfig());
        string savedPath = RecipeWorkspaceService.GetVisionPipelinePath(global.Recipe.Name, "Main"); byte[] saved = File.ReadAllBytes(savedPath);
