                    Require(button.Background is SolidColorBrush background && background.Color.A == 0 && button.BorderBrush is SolidColorBrush border && border.Color.A == 0, name + ": ghost chrome");
                    AssertBrushContrast(caption.Foreground, (Brush)host.FindResource("OpenVision.Workbench.PanelBrush"), name + ": caption contrast");
