    private static CaptureResult CaptureMainInstanceAddresses(string outputPath)
    {
        GlobalState global = new(); global.Recipe.Name = "Smoke_MainInstances_" + Guid.NewGuid().ToString("N");
        VisionPipeline saved = new() { Name = "Main" }; VisionPipelineStorage.Save(global.Recipe.Name, saved);
        global.System.SaveWorkbenchLayout(new SystemStateConfig());
        string savedPath = RecipeWorkspaceService.GetVisionPipelinePath(global.Recipe.Name, "Main"); byte[] savedBytes = File.ReadAllBytes(savedPath);
        using DisplayManagerService display = new(); OpenVisionShellHostWindow window = new(new ApplicationRuntimeContext(global, display));
        window.ClearValue(OpenVisionShellHostWindow.ClosingCommandProperty); OpenVisionShellHostView host = window.ShellHostForSmoke;
        return CaptureStandaloneWindow(window, outputPath, 1600, 900, () =>
        {
            var model = host.Workbench; model.Tool.ConfigureAutoRunPreference(() => false, _ => { });
            model.IsLeftCollapsed = false; model.IsRightCollapsed = true; model.IsToolPaletteCollapsed = false;
            model.SelectDarkThemeCommand.Execute(null); OpenVisionLanguageService.SetLanguage(OpenVisionLanguage.English, false);
            int runs = host.NativePreviewRunCount; byte[] working = VisionPipelineExecutionPlan.SerializePipeline(model.Pipeline.WorkingCopyForTest);
            string image = Path.ChangeExtension(outputPath, ".input.png"); using (Bitmap input = CreateWorkspaceSeedSmokeBitmap()) input.Save(image, ImageFormat.Png);
            if (!host.LoadMainImageFromFileForTest(image)) throw new InvalidOperationException("Main instance ownedimage precondition");
            Pump(6);
            Button[] tiles = FindVisualChildrenIncludingSelf<Button>(host).Where(b => AutomationProperties.GetAutomationId(b).StartsWith("HostToolNav_", StringComparison.Ordinal)).ToArray();
            if (tiles.Length != 16 || tiles.Select(AutomationProperties.GetAutomationId).Distinct().Count() != 16) throw new InvalidOperationException("Main required16 distincttooltiles");
            List<object> tileRows = new();
            foreach (Button tile in tiles)
            {
                tile.BringIntoView(); Pump(2);
                string id = AutomationProperties.GetAutomationId(tile); TextBlock? caption = FindNamedVisualChild<TextBlock>(tile, "navItemTitle");
                if (caption == null || string.IsNullOrWhiteSpace(caption.Text) || tile.Command == null || tile.CommandParameter == null) throw new InvalidOperationException("Main tile instance contract: " + id);
                Rect bounds = new(tile.TranslatePoint(new Point(0, 0), window), tile.RenderSize);
                tileRows.Add(new { ID = id, Name = AutomationProperties.GetName(tile), Caption = caption.Text, Owner = tile.DataContext?.GetType().FullName,
                    Command = tile.Command.GetType().FullName, ParameterOwner = tile.CommandParameter.GetType().FullName, CanExecute = tile.Command.CanExecute(tile.CommandParameter), Bounds = Bounds(bounds) });
                if (tileRows.Count is 1 or 8 or 16) ScreenshotPngWriter.WriteElementPng(window, Path.ChangeExtension(outputPath, ".tiles" + tileRows.Count + ".png"), 1600, 900);
            }
            List<object> paneRows = new();
            foreach (int count in new[] { 1, 2, 4 })
            {
                (count == 1 ? model.Viewer.SingleCommand : count == 2 ? model.Viewer.Split2Command : model.Viewer.Split4Command).Execute(null); Pump(6);
                ComboBox[] sources = FindVisualChildrenIncludingSelf<ComboBox>(host).Where(c => c.IsVisible && c.Name == "mainPaneSource").ToArray();
                string[] expected = count == 1 ? new[] { "follow:out" } : count == 2 ? new[] { "follow:in", "follow:out" } : new[] { "layer:Main", "follow:in", "follow:out", "final" };
                if (sources.Length != count || model.Viewer.Panes.Count != count || !model.Viewer.Panes.Select(p => p.Source).SequenceEqual(expected)) throw new InvalidOperationException("Main pane instance preset: " + count);
                foreach (var pane in model.Viewer.Panes)
                {
                    ComboBox? source = sources.SingleOrDefault(c => ReferenceEquals(c.DataContext, pane));
                    if (source == null || (string?)source.SelectedValue != pane.Source) throw new InvalidOperationException("Main pane instance DataContext: " + pane.Id);
                    Rect bounds = new(source.TranslatePoint(new Point(0, 0), window), source.RenderSize);
                    paneRows.Add(new { Layout = count, Slot = pane.Id, Source = pane.Source, pane.Title, Control = source.Name, Owner = source.DataContext?.GetType().FullName, Bounds = Bounds(bounds) });
                }
                ScreenshotPngWriter.WriteElementPng(window, Path.ChangeExtension(outputPath, ".pane" + count + ".png"), 1600, 900);
            }
            bool noRun = runs == host.NativePreviewRunCount, workingSame = working.SequenceEqual(VisionPipelineExecutionPlan.SerializePipeline(model.Pipeline.WorkingCopyForTest)), savedSame = savedBytes.SequenceEqual(File.ReadAllBytes(savedPath));
            File.WriteAllText(Path.ChangeExtension(outputPath, ".json"), JsonSerializer.Serialize(new { Scope = "Main16tooltile and7pane instance addresses; no Toolparameterbody/actualinput/Main96", Tiles = tileRows, Panes = paneRows,
                NoRun = noRun, WorkingUnchanged = workingSame, SavedUnchanged = savedSame, ProductSHA256 = Convert.ToHexString(SHA256.HashData(File.ReadAllBytes(typeof(OpenVisionShellHostView).Assembly.Location))) }, new JsonSerializerOptions { WriteIndented = true }));
            if (!noRun || !workingSame || !savedSame) throw new InvalidOperationException("Main instance preserved contracts");
            object Bounds(Rect rect) => new { rect.X, rect.Y, rect.Width, rect.Height };
        });
    }

    private static CaptureResult CaptureMainBindingIntegrity(string outputPath, int width, int height)
    {
        GlobalState global = new(); global.Recipe.Name = "Smoke_MainBindings_" + Guid.NewGuid().ToString("N");
        VisionPipeline saved = new() { Name = "Main" };
        for (int i = 0; i < 2; i++) saved.Steps.Add(new VisionPipelineStep { Name = "Binding reference " + (i + 1), ToolType = "Threshold", InputLayer = i == 0 ? "Main" : "Binding_1", OutputLayer = "Binding_" + (i + 1) });
        VisionPipelineStorage.Save(global.Recipe.Name, saved); global.System.SaveWorkbenchLayout(new SystemStateConfig());
        string savedPath = RecipeWorkspaceService.GetVisionPipelinePath(global.Recipe.Name, "Main"); byte[] savedBytes = File.ReadAllBytes(savedPath);
        using DisplayManagerService display = new(); OpenVisionShellHostWindow window = new(new ApplicationRuntimeContext(global, display));
        window.ClearValue(OpenVisionShellHostWindow.ClosingCommandProperty); OpenVisionShellHostView host = window.ShellHostForSmoke;
        return CaptureStandaloneWindow(window, outputPath, width, height, () =>
        {
            var model = host.Workbench; model.Tool.ConfigureAutoRunPreference(() => false, _ => { });
            int runs = host.NativePreviewRunCount; byte[] working = VisionPipelineExecutionPlan.SerializePipeline(model.Pipeline.WorkingCopyForTest);
            string image = Path.ChangeExtension(outputPath, ".input.png"); using (Bitmap input = CreateWorkspaceSeedSmokeBitmap()) input.Save(image, ImageFormat.Png);
            List<object> snapshots = new(); List<string> failures = new();
            foreach (string palette in new[] { "Dark", "Light" })
            {
                (palette == "Dark" ? model.SelectDarkThemeCommand : model.SelectLightThemeCommand).Execute(null);
                foreach (OpenVisionLanguage language in new[] { OpenVisionLanguage.Korean, OpenVisionLanguage.English })
                {
                    OpenVisionLanguageService.SetLanguage(language, false);
                    if (host.ActiveNativeDocumentForTest != null) host.CloseActiveWpfToolWindowForTest();
                    model.Images.SelectAllCommand.Execute(null); model.Images.RemoveCommand.Execute(null); Pump(6);
                    if (model.Images.HasImages) throw new InvalidOperationException("Main binding empty fixture precondition");
                    foreach (string state in new[] { "empty-no-tool", "loaded-no-tool", "saved-step", "trial" })
                    {
                        if (state == "loaded-no-tool" && !host.LoadMainImageFromFileForTest(image)) throw new InvalidOperationException("Main binding owned valid image precondition");
                        if (state == "saved-step") model.Pipeline.SelectStepCommand.Execute(0);
                        if (state == "trial") host.SelectToolForTest(VISION_MENU.Threshold);
                        foreach (int tab in new[] { 0, 1, 2 })
                        {
                            model.SelectedBottomTab = tab; Pump(6); List<object> elements = new(); int bindingCount = 0;
                            foreach (FrameworkElement element in FindVisualChildrenIncludingSelf<FrameworkElement>(window))
                            {
                                if (!element.IsVisible) continue;
                                List<string> ancestors = new(); bool separateView = false;
                                for (DependencyObject parent = VisualTreeHelper.GetParent(element); parent != null; parent = VisualTreeHelper.GetParent(parent))
                                {
                                    if (parent is not FrameworkElement frame) continue;
                                    string parentId = AutomationProperties.GetAutomationId(frame);
                                    if (frame.Name is "hostRail" or "recipeManagerPanel" or "HostRecipeManagerPanel" or "toolContentHost" || frame.Name == "ParameterContent") separateView = true;
                                    if (parentId.Length > 0 || frame.Name.Length > 0) ancestors.Add(frame.GetType().Name + ":" + (parentId.Length > 0 ? parentId : frame.Name));
                                }
                                if (separateView) continue;
                                List<object> bindings = new(); LocalValueEnumerator values = element.GetLocalValueEnumerator();
                                while (values.MoveNext())
                                {
                                    DependencyProperty property = values.Current.Property;
                                    if (BindingOperations.GetBindingExpressionBase(element, property) is not BindingExpressionBase binding) continue;
                                    List<BindingExpressionBase> expressions = binding is MultiBindingExpression multi ? multi.BindingExpressions.ToList() : new() { binding };
                                    foreach (BindingExpressionBase expression in expressions)
                                    {
                                        BindingExpression? single = expression as BindingExpression;
                                        string status = expression.Status.ToString(), path = single?.ParentBinding.Path?.Path ?? "";
                                        string id = AutomationProperties.GetAutomationId(element), name = element.Name;
                                        if (status is "PathError" or "UpdateSourceError" or "UpdateTargetError") failures.Add(palette + "/" + language + "/" + state + "/tab" + tab + ":" + element.GetType().Name + ":" + (id.Length > 0 ? id : name) + ":" + property.Name + ":" + path + ":" + status);
                                        bindings.Add(new { Property = property.Name, Path = path, Status = status, Mode = single?.ParentBinding.Mode.ToString(), SourceType = single?.DataItem?.GetType().FullName, NullSource = single != null && single.DataItem == null }); bindingCount++;
                                    }
                                }
                                if (bindings.Count > 0) elements.Add(new { Type = element.GetType().FullName, ID = AutomationProperties.GetAutomationId(element), Name = element.Name, DataContext = element.DataContext?.GetType().FullName, TemplatedParent = element.TemplatedParent?.GetType().FullName, Ancestors = ancestors, Bindings = bindings });
                            }
                            string? capture = null;
                            if (language == OpenVisionLanguage.English && state == "trial" && tab == 0)
                            {
                                capture = Path.ChangeExtension(outputPath, "." + palette + "-current.png"); ScreenshotPngWriter.WriteElementPng(window, capture, width, height);
                            }
                            snapshots.Add(new { Palette = palette, Language = language.ToString(), State = state, BottomTab = tab, Width = width, Height = height, HasImages = model.Images.HasImages, StepSelected = model.Pipeline.SelectedRow?.Index, BindingCount = bindingCount, Capture = capture, Elements = elements });
                        }
                    }
                }
            }
            bool savedUnchanged = savedBytes.SequenceEqual(File.ReadAllBytes(savedPath)), workingUnchanged = working.SequenceEqual(VisionPipelineExecutionPlan.SerializePipeline(model.Pipeline.WorkingCopyForTest)), noRun = runs == host.NativePreviewRunCount;
            if (!savedUnchanged || !workingUnchanged || !noRun) failures.Add("Main binding owner invariant: saved=" + savedUnchanged + ", working=" + workingUnchanged + ", noRun=" + noRun);
            File.WriteAllText(Path.ChangeExtension(outputPath, ".json"), JsonSerializer.Serialize(new { Scope = "current visible Main binding integrity; parameter bodies excluded; not complete TwoWay/actualinput/HTML parity", Snapshots = snapshots, Failures = failures, ProductModule = typeof(OpenVisionShellHostView).Assembly.Location, ProductSHA256 = Convert.ToHexString(SHA256.HashData(File.ReadAllBytes(typeof(OpenVisionShellHostView).Assembly.Location))), SavedUnchanged = savedUnchanged, WorkingUnchanged = workingUnchanged, NoRun = noRun, FinalN = (int?)null, Main96 = false }, new JsonSerializerOptions { WriteIndented = true }));
            if (failures.Count > 0) throw new InvalidOperationException("Main binding integrity " + failures.Count + " failures; first=" + failures[0]);
        });
    }

