                Require(title.Text == tool.Title && route.Text == tool.MainDraftRouteText && chip.Tag?.ToString() == "NotRun" && FindVisualChildren<TextBlock>(chip).Single().Text == tool.ResultStatusText, "title/route/status reflect the live owner");
