                    ListBoxItem following = FindVisualChildren<ListBoxItem>(host).Single(item => ReferenceEquals(item.DataContext, pipeline.Rows[1]));
                    Point draftTop = draft.TranslatePoint(new Point(0, 0), host), anchorTop = chrome.TranslatePoint(new Point(0, 0), host), followingTop = following.TranslatePoint(new Point(0, 0), host);
