                Require(tool.SetRoute(token, tool.InputLayer, null, "Trial_" + new string('R', 72)), "long valid trial output"); Pump(4);
                Require(route.Text == tool.MainDraftRouteText && route.Text.Length > 72 && route.TextTrimming == TextTrimming.CharacterEllipsis && route.ToolTip?.ToString() == route.Text, "bounded long route with full supplemental tooltip value");
                string longShown = Capture(palette + "-" + locale + "-long-route"); Require(tool.SetRoute(token, tool.InputLayer, null, originalOutput), "route restore"); Pump(3);
                byte[] draftStep = TrialSnapshot();
                Require(host.CloseActiveWpfToolWindowForTest(), "existing native close entry"); Pump(5); lifetimeChecks++;
                Require(!tool.IsOpen && !tool.IsMainDraftVisible && DraftRows().Length == 0 && document.WorkbenchParameterStep == null, "close releases Main draft and active editor token");
