                string closed = Capture(palette + "-" + locale + "-closed"); host.SelectToolForTest(VISION_MENU.Threshold); Pump(5); long nextToken = Session(document);
                Require(ReferenceEquals(document, host.ActiveNativeDocumentForTest) && nextToken != token && tool.IsMainDraftVisible && DraftRows().Length == 1, "cached document reopened as a fresh active session");
                tool.Deactivate(token); Pump(3); Require(tool.IsActive(nextToken) && DraftRows().Length == 1, "old generation cannot close newer session");
                byte[] restoredDraft = TrialSnapshot();
                Require(draftStep.SequenceEqual(restoredDraft), "reopened test route/parameters retained");
                Require(pipeline.StepCount == (empty ? 0 : 2) && pipeline.SelectedStepIndex == (empty ? -1 : 0) && working.SequenceEqual(VisionPipelineExecutionPlan.SerializePipeline(pipeline.WorkingCopyForTest)) && host.NativePreviewRunCount == runs, "saved rows/selection/working data/no-run unchanged");
                cases.Add(new { Palette = palette, Locale = locale.ToString(), Width = width, Empty = empty, Trial = shown, LongRoute = longShown, Closed = closed, SavedRows = pipeline.StepCount, DraftRows = 1, ReopenedSameDocument = true, GenerationGuard = true, NoRun = true });
                Require(host.CloseActiveWpfToolWindowForTest(), "close after restored trial"); Pump(3);
            }
            host.SelectToolForTest(VISION_MENU.Threshold); Pump(5); OpenVisionNativeToolDocument current = host.ActiveNativeDocumentForTest!; long currentToken = Session(current);
            foreach (string palette in new[] { "Dark", "Light" })
