                    string semantic = kind == "Done" ? "Done" : kind == "Previous" ? "Stale" : kind == "Ng" ? "Ng" : "Error";
                    Require(((SolidColorBrush)System.Windows.Documents.TextElement.GetForeground(chip)).Color == ((SolidColorBrush)host.FindResource("OpenVision.Workbench." + semantic + "Brush")).Color, "synthetic " + kind + " semantic foreground");
