            stale.DeactivateWorkbenchEditor(); Pump(3); Require(tool.IsActive(latestToken) && tool.ToolName == "Mean" && DraftRows().Length == 1, "inactive cached tool release cannot remove active other-tool trial"); lifetimeChecks++;
