            Require(!tool.IsOpen && DraftRows().Length == 0 && File.ReadAllBytes(savedPath).SequenceEqual(savedBytes) && File.ReadAllBytes(image).SequenceEqual(inputBytes) && working.SequenceEqual(VisionPipelineExecutionPlan.SerializePipeline(pipeline.WorkingCopyForTest)) && ReferenceEquals(inputImage, display.ImageSpace.GetImage(VisionRecipeRunner.DefaultInputLayer)) && host.NativePreviewRunCount == runs, "final saved/working/input/cache lifetime/no-run invariants");
            File.WriteAllText(Path.ChangeExtension(outputPath, ".json"), JsonSerializer.Serialize(new { Cases = cases, SyntheticResultDisplays = stateChecks, LifetimeCases = lifetimeChecks, SourceBytesUnchanged = true, WorkingUnchanged = true, NoRun = true, Scope = "Inprocess WPF actual existing Main tool-entry/close paths plus synthetic result display only", Unverified = new[] { "desktop key/pointer", "actual pressed/busy", "native125", "same-state HTML", "full Main binding/finalN" }, FinalN = (int?)null, Main96 = false }, new JsonSerializerOptions { WriteIndented = true }));
        });
    }

