            pipeline.InsertStep(1, new VisionPipelineStep { Name = "Unsaved", ToolType = "Mean", InputLayer = "Main", OutputLayer = "DraftOutput" });
            selectedPath = exportedPath; model.ExportMainPipelineXmlCommand.Execute(null);
            Require(VisionPipelineStorage.TryLoadFromFile(exportedPath, out VisionPipeline exported, out _) && exported.Name == "Selected" && exported.Steps.Count == 1 && exported.Steps[0].Name == "SelectedOnly", "current selected saved pipeline, not default");
            Require(pipeline.IsDirty && pipeline.Rows.Count == 2 && source.SequenceEqual(File.ReadAllBytes(sourcePath)) && defaultBytes.SequenceEqual(File.ReadAllBytes(defaultPath)) && VisionPipelineStorage.LoadActivePipelineName(recipe, "Fallback") == "Default", "read-only export preserves draft/source/default");
            string legacy = Path.ChangeExtension(outputPath, ".legacy.xml"); Require(commands.ExportActivePipelineXmlToPath(legacy) && VisionPipelineStorage.TryLoadFromFile(legacy, out VisionPipeline legacyExport, out _) && legacyExport.Name == "Default" && legacyExport.Steps.Count == 0, "existing default export contract preserved");
