            model.ExportMainPipelineXmlCommand.Execute(null); Require(notices == 1 && VisionPipelineStorage.TryLoadFromFile(exportedPath, out exported, out _) && exported.Name == "Selected", "unlock retry succeeds");
            string unreadableTarget = Path.ChangeExtension(outputPath, ".unreadable.xml"); selectedPath = unreadableTarget;
            using (FileStream unreadable = new(sourcePath, FileMode.Open, FileAccess.Read, FileShare.None)) { model.ExportMainPipelineXmlCommand.Execute(null); Require(notices == 2 && !File.Exists(unreadableTarget), "source read failure blocks export without fallback"); }
            Require(source.SequenceEqual(File.ReadAllBytes(sourcePath)), "source unlock retained exact bytes");
            File.WriteAllText(sourcePath, "<OwnedMalformedPipeline>"); byte[] malformed = File.ReadAllBytes(sourcePath); model.ExportMainPipelineXmlCommand.Execute(null);
            Require(notices == 3 && !File.Exists(unreadableTarget) && malformed.SequenceEqual(File.ReadAllBytes(sourcePath)), "malformed source retained without backup/replacement/export");
            File.WriteAllBytes(sourcePath, source); model.ExportMainPipelineXmlCommand.Execute(null); Require(VisionPipelineStorage.TryLoadFromFile(unreadableTarget, out exported, out _) && exported.Name == "Selected", "valid source recovery");
            string retainedTarget = Path.ChangeExtension(outputPath, ".retained.xml"); selectedPath = retainedTarget; onDialog = () => commands.SelectedPipelineOption = commands.PipelineOptions.Single(option => option.PipelineName == "Default"); model.ExportMainPipelineXmlCommand.Execute(null); Require(VisionPipelineStorage.TryLoadFromFile(retainedTarget, out exported, out _) && exported.Name == "Selected" && pipeline.IsDirty && notices == 3 && commands.SelectedPipelineOption?.PipelineName == "Selected", "pending Cancel retains selected context; read-only export remains allowed");
            string staleTarget = Path.ChangeExtension(outputPath, ".stale.xml"); selectedPath = staleTarget; pending = OpenVisionRecipePendingEditDecision.Discard; model.ExportMainPipelineXmlCommand.Execute(null); Require(!File.Exists(staleTarget) && notices == 3 && commands.SelectedPipelineOption?.PipelineName == "Default", "changed selection after dialog cancels export");
            onDialog = () => { }; model.OpenShortcutsCommand.Execute(null); Require(!model.ExportMainPipelineXmlCommand.CanExecute(null), "Main overlay blocks export"); model.CloseShortcutsCommand.Execute(null); Require(model.ExportMainPipelineXmlCommand.CanExecute(null), "overlay cancel restores export");
