                Popup popup = (Popup)parent.Template.FindName("PART_Popup", parent); FrameworkElement popupRoot = (FrameworkElement)popup.Child; Pump(2);
                Require(popup.IsOpen && popupRoot.ActualWidth > 100D && popupRoot.ActualHeight > 100D, "rendered Main popup");
