                string copiedName = RecipeWorkspaceService.GetVisionPipelineNames(global.Recipe.Name).Except(before, StringComparer.OrdinalIgnoreCase).Single(); VisionPipeline copied = VisionPipelineStorage.Load(global.Recipe.Name, copiedName);
                Require(model.Recipes.SelectedPipelineOption?.PipelineName == "Original" && VisionPipelineStorage.LoadActivePipelineName(global.Recipe.Name, "Fallback") == "Original" && ReferenceEquals(selectedRow, model.Pipeline.SelectedRow), "copy retains current/default/row selection");
                Require(copied.Name == copiedName && copied.Steps.Count == 1 && copied.Steps[0].Name == "Keep" && copiedName.StartsWith("Original " + model["Workbench.Recipe.CopySuffix"], StringComparison.Ordinal) && sourceBytes.SequenceEqual(File.ReadAllBytes(sourcePath)) && otherBytes.SequenceEqual(File.ReadAllBytes(otherPath)), "localized unique copy/saved content/source and other bytes");
                Require(ReferenceEquals(input, display.ImageSpace.GetImage(VisionRecipeRunner.DefaultInputLayer)) && model.Images.Count == 1 && model.Shell.WorkspaceInputSourcePath == image && model.Pipeline.ResultCountForTest == 0 && host.NativePreviewRunCount == runs, "copy preserves input/current results and does not Run");
