                    }
                    model.Pipeline.ToggleEnabledCommand.Execute(null); Pump(3); Require(model.Pipeline.Rows.Single().StatusKind == "Disabled", "disabled chip preserved"); rowFrame = FindVisualChildren<Border>(host).Single(frame => frame.Name == "stepRow" && ReferenceEquals(frame.DataContext, model.Pipeline.Rows.Single())); ScreenshotPngWriter.WriteElementPng(rowFrame, Path.ChangeExtension(outputPath, $".{palette}-{locale}-Disabled.png"), (int)Math.Ceiling(rowFrame.ActualWidth), (int)Math.Ceiling(rowFrame.ActualHeight)); stateCases++; model.Pipeline.ToggleEnabledCommand.Execute(null);
                    typeof(OpenVisionWorkbenchPipelineViewModel).GetField("runningIndex", BindingFlags.Instance | BindingFlags.NonPublic)!.SetValue(model.Pipeline, 0); model.Pipeline.RefreshInputState(); Pump(3); Require(model.Pipeline.Rows.Single().StatusKind == "Running", "synthetic running chip preserved"); rowFrame = FindVisualChildren<Border>(host).Single(frame => frame.Name == "stepRow" && ReferenceEquals(frame.DataContext, model.Pipeline.Rows.Single())); ScreenshotPngWriter.WriteElementPng(rowFrame, Path.ChangeExtension(outputPath, $".{palette}-{locale}-Running.png"), (int)Math.Ceiling(rowFrame.ActualWidth), (int)Math.Ceiling(rowFrame.ActualHeight)); stateCases++;
                    typeof(OpenVisionWorkbenchPipelineViewModel).GetField("runningIndex", BindingFlags.Instance | BindingFlags.NonPublic)!.SetValue(model.Pipeline, -1); model.Pipeline.RefreshInputState();
                    model.Recipes.SelectedPipelineOption = model.Recipes.PipelineOptions.Single(option => option.PipelineName == "Other"); model.Recipes.SelectedPipelineOption = model.Recipes.PipelineOptions.Single(option => option.PipelineName == "Original"); Pump(3);
                }
                cases++;
            }
            File.WriteAllText(Path.ChangeExtension(outputPath, ".json"), JsonSerializer.Serialize(new { Scope = "Main inprocess flow copy/no-result/menu, two live palettes/KOEN, no actual pointer input", Cases = cases, SyntheticNeighborStates = stateCases, CopyRetainsSelectionAndDefault = true, SourceBytesAndInputPreserved = true, NoRun = true, FinalN = (int?)null, Main96 = false }, new JsonSerializerOptions { WriteIndented = true }));
        });
