    private static CaptureResult CaptureMainFlowCopyPending(string outputPath)
    {
        string selected = "CopyPending_" + Guid.NewGuid().ToString("N"); VisionPipeline clean = new() { Name = "Original" }; clean.Steps.Add(new VisionPipelineStep { Name = "Saved", ToolType = "Mean", InputLayer = "Main", OutputLayer = "SavedOutput" });
        VisionPipelineStorage.Save(selected, clean); VisionPipelineStorage.Save(selected, new VisionPipeline { Name = "Other" }); VisionPipelineStorage.SaveActivePipelineName(selected, clean.Name);
        string path = RecipeWorkspaceService.GetVisionPipelinePath(selected, clean.Name); byte[] saved = File.ReadAllBytes(path);
        OpenVisionRecipePendingEditDecision decision = OpenVisionRecipePendingEditDecision.Cancel; int decisions = 0, checks = 0;
        OpenVisionShellHostRecipeCommandSurface commands = new(() => selected, _ => throw new InvalidOperationException("Copy switched recipe."), () => { }, decidePendingEdit: _ => decision, saveRuntimeRecipeCopy: _ => true);
        using DisplayManagerService display = new(); using OpenVisionWorkbenchPipelineViewModel pipeline = new(commands, display, action => action(), _ => { decisions++; return decision; }, _ => true, Array.Empty<OpenVisionShellNavGroup>()); commands.AttachWorkbenchPipeline(pipeline);
        OpenVisionWorkbenchViewModel model = new(new SystemStateConfig(), _ => true, recipes: commands); int notices = 0; model.ProductInfoRequested += (_, _) => notices++;
        return CaptureWindowWithContent(new TextBlock { Text = "Main pipeline copy/pending/read-failure/retry contracts" }, outputPath, 640, 160, () =>
        {
            void Require(bool value, string detail) { if (!value) throw new InvalidOperationException("Main flow copy pending: " + detail); checks++; }
            pipeline.InsertStep(1, new VisionPipelineStep { Name = "Draft", ToolType = "Mean", InputLayer = "Main", OutputLayer = "DraftOutput" }); string[] before = RecipeWorkspaceService.GetVisionPipelineNames(selected);
            var canceled = commands.DuplicateMainPipeline(); Require(canceled.Canceled && decisions == 1 && pipeline.IsDirty && before.SequenceEqual(RecipeWorkspaceService.GetVisionPipelineNames(selected)) && saved.SequenceEqual(File.ReadAllBytes(path)), "Cancel preserves current draft/source/names");
            decision = OpenVisionRecipePendingEditDecision.ApplyAndContinue;
            using (FileStream locked = new(path, FileMode.Open, FileAccess.Read, FileShare.Read)) { var blocked = commands.DuplicateMainPipeline(); Require(blocked.Canceled && pipeline.IsDirty && before.SequenceEqual(RecipeWorkspaceService.GetVisionPipelineNames(selected)), "failed Apply blocks copy"); }
            Require(commands.DuplicateMainPipeline().Succeeded, "Apply saves and copies"); string appliedName = RecipeWorkspaceService.GetVisionPipelineNames(selected).Except(before, StringComparer.OrdinalIgnoreCase).Single();
            Require(VisionPipelineStorage.Load(selected, appliedName).Steps.Count == 2 && VisionPipelineStorage.Load(selected, "Original").Steps.Count == 2 && !pipeline.IsDirty && pipeline.Rows.Count == 2 && commands.SelectedPipelineOption?.PipelineName == "Original" && VisionPipelineStorage.LoadActivePipelineName(selected, "Fallback") == "Original", "Apply saved content with current/default retained");
            before = RecipeWorkspaceService.GetVisionPipelineNames(selected); Require(commands.DuplicateMainPipeline().Succeeded && RecipeWorkspaceService.GetVisionPipelineNames(selected).Length == before.Length + 1 && commands.SelectedPipelineOption?.PipelineName == "Original", "name collision uses existing unique-name owner");
            commands.SelectedPipelineOption = commands.PipelineOptions.Single(option => option.PipelineName == "Other"); pipeline.InsertStep(0, new VisionPipelineStep { Name = "Discard", ToolType = "Mean", InputLayer = "Main", OutputLayer = "DiscardOutput" }); decision = OpenVisionRecipePendingEditDecision.Discard; before = RecipeWorkspaceService.GetVisionPipelineNames(selected);
            Require(commands.DuplicateMainPipeline().Succeeded && pipeline.Rows.Count == 0 && !pipeline.IsDirty, "Discard restores saved source before copy"); string discardedName = RecipeWorkspaceService.GetVisionPipelineNames(selected).Except(before, StringComparer.OrdinalIgnoreCase).Single(); Require(VisionPipelineStorage.Load(selected, discardedName).Steps.Count == 0 && commands.SelectedPipelineOption?.PipelineName == "Other" && VisionPipelineStorage.LoadActivePipelineName(selected, "Fallback") == "Original", "nondefault copy retains selection/default");
            string otherPath = RecipeWorkspaceService.GetVisionPipelinePath(selected, "Other"); before = RecipeWorkspaceService.GetVisionPipelineNames(selected); byte[] otherSaved = File.ReadAllBytes(otherPath); string[] physicalBefore = Directory.GetFiles(Path.GetDirectoryName(otherPath)!);
            using (FileStream unreadable = new(otherPath, FileMode.Open, FileAccess.Read, FileShare.None)) { model.DuplicateMainPipelineCommand.Execute(null); File.WriteAllText(Path.ChangeExtension(outputPath, ".read-failure.json"), JsonSerializer.Serialize(new { Notices = notices, Notice = model.MainNoticeText, ExpectedFormat = model["Workbench.Pipeline.CopyFailedFormat"], Before = before, After = RecipeWorkspaceService.GetVisionPipelineNames(selected), Selected = commands.SelectedPipelineOption?.PipelineName, Dirty = pipeline.IsDirty, CanCopy = model.DuplicateMainPipelineCommand.CanExecute(null) }, new JsonSerializerOptions { WriteIndented = true })); Require(notices == 1 && model.MainNoticeText.Contains(model["Workbench.Pipeline.CopyFailedFormat"].Split("{0}")[0].Trim(), StringComparison.Ordinal) && physicalBefore.ToHashSet(StringComparer.OrdinalIgnoreCase).SetEquals(Directory.GetFiles(Path.GetDirectoryName(otherPath)!)) && File.Exists(otherPath) && commands.SelectedPipelineOption?.PipelineName == "Other", "source read failure is visible and creates no copy"); }
            Require(before.SequenceEqual(RecipeWorkspaceService.GetVisionPipelineNames(selected)) && otherSaved.SequenceEqual(File.ReadAllBytes(otherPath)), "unlock restores catalog visibility and source bytes");
            Require(commands.DuplicateMainPipeline().Succeeded && RecipeWorkspaceService.GetVisionPipelineNames(selected).Length == before.Length + 1 && commands.SelectedPipelineOption?.PipelineName == "Other", "valid retry restores copy operation");
            model.OpenMainNewPipelineCommand.Execute(null); Require(!model.DuplicateMainPipelineCommand.CanExecute(null), "modal blocks duplicate action"); model.CloseMainRecipeCommand.Execute(null); Require(model.DuplicateMainPipelineCommand.CanExecute(null), "modal cancel restores duplicate action");
            commands.DetachWorkbenchPipeline(pipeline); model.Dispose(); File.WriteAllText(Path.ChangeExtension(outputPath, ".json"), JsonSerializer.Serialize(new { Scope = "Owned D copy contracts; synthetic pending decisions, not actual UI", Checks = checks, Pending = "Cancel/Apply/save lock/Discard", ReadFailureAndRetry = true, DefaultAndSelectionRetained = true, NoRun = true, HistoryAcrossFlowCrud = "Unverified" }, new JsonSerializerOptions { WriteIndented = true }));
        });
    }

