    private static CaptureResult CaptureMainRenamePipelinePending(string outputPath)
    {
        string selected = "RenamePending_" + Guid.NewGuid().ToString("N");
        VisionPipeline clean = new() { Name = "Original" }; clean.Steps.Add(new VisionPipelineStep { Name = "Saved", ToolType = "Mean", InputLayer = "Main", OutputLayer = "SavedOutput" }); VisionPipelineStorage.Save(selected, clean); VisionPipelineStorage.Save(selected, new VisionPipeline { Name = "Other" }); VisionPipelineStorage.SaveActivePipelineName(selected, clean.Name);
        string path = RecipeWorkspaceService.GetVisionPipelinePath(selected, clean.Name); byte[] saved = File.ReadAllBytes(path);
        OpenVisionRecipePendingEditDecision decision = OpenVisionRecipePendingEditDecision.Cancel; int decisions = 0, checks = 0;
        OpenVisionShellHostRecipeCommandSurface commands = new(() => selected, _ => throw new InvalidOperationException("Rename switched recipe."), () => { }, decidePendingEdit: _ => decision, saveRuntimeRecipeCopy: _ => true);
        using DisplayManagerService display = new(); using OpenVisionWorkbenchPipelineViewModel pipeline = new(commands, display, action => action(), _ => { decisions++; return decision; }, _ => true, Array.Empty<OpenVisionShellNavGroup>()); commands.AttachWorkbenchPipeline(pipeline);
        OpenVisionWorkbenchViewModel model = new(new SystemStateConfig(), _ => true, recipes: commands);
