        {
            void Require(bool value, string detail) { if (!value) throw new InvalidOperationException("Main rename pipeline pending: " + detail); checks++; }
            pipeline.InsertStep(1, new VisionPipelineStep { Name = "Draft", ToolType = "Mean", InputLayer = "Main", OutputLayer = "DraftOutput" });
            Require(!commands.RenameMainPipeline("Original", "OTHER").Succeeded && !commands.RenameMainPipeline("Original", "bad/name").Succeeded && !commands.RenameMainPipeline("Original", "").Succeeded && decisions == 0 && pipeline.IsDirty, "name guards before pending/writes");
            Require(commands.RenameMainPipeline("Original", "Original").Succeeded && decisions == 0 && pipeline.IsDirty && saved.SequenceEqual(File.ReadAllBytes(path)), "unchanged name no-op preserves dirty source");
            var canceled = commands.RenameMainPipeline("Original", "Canceled"); Require(canceled.Canceled && pipeline.IsDirty && saved.SequenceEqual(File.ReadAllBytes(path)) && !File.Exists(RecipeWorkspaceService.GetVisionPipelinePath(selected, "Canceled")), "pending Cancel preserves source/draft");
            decision = OpenVisionRecipePendingEditDecision.ApplyAndContinue;
            using (FileStream locked = new(path, FileMode.Open, FileAccess.Read, FileShare.Read))
            {
                var blocked = commands.RenameMainPipeline("Original", "LockedSource"); Require(blocked.Canceled && pipeline.IsDirty && saved.SequenceEqual(File.ReadAllBytes(path)) && !File.Exists(RecipeWorkspaceService.GetVisionPipelinePath(selected, "LockedSource")), "failed Apply blocks rename/keeps dirty");
            }
