            commands.SelectedPipelineOption = commands.PipelineOptions.Single(p => p.PipelineName == "Other"); pipeline.InsertStep(0, new VisionPipelineStep { Name = "Discard", ToolType = "Mean", InputLayer = "Main", OutputLayer = "DiscardOutput" }); decision = OpenVisionRecipePendingEditDecision.Discard;
            var discarded = commands.RenameMainPipeline("Other", "Discarded"); Require(discarded.Succeeded && pipeline.Rows.Count == 0 && VisionPipelineStorage.Load(selected, "Discarded").Steps.Count == 0 && VisionPipelineStorage.LoadActivePipelineName(selected, "Fallback") == "Applied", "Discard restores saved source; nondefault rename keeps active pointer");
            string discardedPath = RecipeWorkspaceService.GetVisionPipelinePath(selected, "Discarded"); model.OpenMainRenamePipelineCommand.Execute(null); model.MainRecipeName = "Retry";
            using (FileStream unreadable = new(discardedPath, FileMode.Open, FileAccess.Read, FileShare.None))
            {
                model.SubmitMainRecipeCommand.Execute(null); WaitForTaskWithPump(model.MainRecipeSubmission, 10000, "Main rename source read failure"); Require(model.IsMainRecipeOpen && model.HasMainRecipeError && !model.IsMainRecipeBusy && commands.SelectedPipelineOption?.PipelineName == "Discarded" && !File.Exists(RecipeWorkspaceService.GetVisionPipelinePath(selected, "Retry")), "source read failure retains form/current context");
            }
