            model.OpenMainRenamePipelineCommand.Execute(null); model.MainRecipeName = "Stale"; commands.SelectedPipelineOption = commands.PipelineOptions.Single(p => p.PipelineName == "Applied"); Require(!model.IsMainRecipeOpen && !model.SubmitMainRecipeCommand.CanExecute(null) && !File.Exists(RecipeWorkspaceService.GetVisionPipelinePath(selected, "Stale")), "selection transition closes stale form");
            Require(!commands.RenameMainPipeline("Retry", "WrongSource").Succeeded && !File.Exists(RecipeWorkspaceService.GetVisionPipelinePath(selected, "WrongSource")), "stale source refuses writes");
            commands.DetachWorkbenchPipeline(pipeline); model.Dispose();
            File.WriteAllText(Path.ChangeExtension(outputPath, ".json"), JsonSerializer.Serialize(new { Scope = "Owned D Main rename/pending/form contracts, not actual UI", Checks = checks, Pending = "Cancel/Discard/Apply/source-save lock/source-read failure/retry", DefaultIdentityPreserved = true, NoRun = true, StaleContextCanceled = true }, new JsonSerializerOptions { WriteIndented = true }));
        });
    }

