    private static CaptureResult CaptureMainImageCompareLaunchContract(string outputPath)
    {
        string root = Path.Combine(Path.GetDirectoryName(outputPath)!, "owned installation with spaces"); string directory = Path.Combine(root, "Tools", "ImageCompare"); Directory.CreateDirectory(directory);
        string[] names = { "OpenVisionLab.ImageCompare.exe", "OpenVisionLab.ImageCompare.dll", "OpenVisionLab.ImageCompare.runtimeconfig.json" }; int started = 0, checks = 0;
        void Require(bool value, string detail) { if (!value) throw new InvalidOperationException("Main image comparison launch: " + detail); checks++; }
        System.Diagnostics.Process Start(System.Diagnostics.ProcessStartInfo info)
        {
            Require(info.FileName == Path.Combine(directory, names[0]) && info.WorkingDirectory == directory && info.UseShellExecute && info.Arguments.Length == 0 && info.ArgumentList.Count == 0, "exact independent executable/no image or Run args");
            started++; return new System.Diagnostics.Process();
        }
        foreach (string name in names) File.WriteAllText(Path.Combine(directory, name), "Owned launch-contract stub; never executed.");
        foreach (string missing in names)
        {
            File.Delete(Path.Combine(directory, missing));
            Require(!OpenVisionShellHostCommandController.TryOpenImageCompare(root, Start, out string error) && error.Contains(missing) && started == 0, "missing required launch file does not start");
            File.WriteAllText(Path.Combine(directory, missing), "Owned launch-contract stub; never executed.");
        }
        Require(OpenVisionShellHostCommandController.TryOpenImageCompare(root, Start, out string success) && success.Length == 0 && started == 1, "valid files/retry contract");
        Require(!OpenVisionShellHostCommandController.TryOpenImageCompare(root, _ => throw new System.ComponentModel.Win32Exception("Owned start failure"), out string failed) && failed == "Owned start failure", "OS start failure reported");
        Require(!OpenVisionShellHostCommandController.TryOpenImageCompare(root, _ => null!, out string absent) && absent.Length > 0, "no process handle cannot report success");
        Require(OpenVisionShellHostCommandController.TryOpenImageCompare(root, Start, out _) && started == 2, "valid retry after failed launch");
        File.WriteAllText(outputPath, "Launch-delegate contract passed; no OS process was launched.");
        File.WriteAllText(Path.ChangeExtension(outputPath, ".json"), JsonSerializer.Serialize(new { Scope = "Owned files/fake delegate contract, not actual EXE", Checks = checks, StartedDelegates = started, ActualEXE = "U" }, new JsonSerializerOptions { WriteIndented = true }));
        return default;
    }

    private static CaptureResult CaptureMainValidationForm(string outputPath, int width, int height)
    {
        GlobalState global = new(); global.Recipe.Name = "Smoke_MainValidationForm_" + Guid.NewGuid().ToString("N");
        VisionPipeline source = new() { Name = "Pipeline" }; VisionPipelineStorage.Save(global.Recipe.Name, source); VisionPipelineStorage.SaveActivePipelineName(global.Recipe.Name, source.Name);
        string savedPath = RecipeWorkspaceService.GetVisionPipelinePath(global.Recipe.Name, source.Name); byte[] saved = File.ReadAllBytes(savedPath);
        string data = Path.Combine(Path.GetDirectoryName(outputPath)!, "validation-input"); Directory.CreateDirectory(data);
        string[] files = Enumerable.Range(0, 3).Select(i => Path.Combine(data, "validation-" + i + ".png")).ToArray();
        using (Bitmap input = CreateWorkspaceSeedSmokeBitmap()) foreach (string path in files) input.Save(path, System.Drawing.Imaging.ImageFormat.Png);
        global.System.SaveWorkbenchLayout(new SystemStateConfig());
        OpenVisionShellHostWindow window = new(new ApplicationRuntimeContext(global, new DisplayManagerService())); window.ClearValue(OpenVisionShellHostWindow.ClosingCommandProperty);
        OpenVisionShellHostView host = window.ShellHostForSmoke;
        return CaptureStandaloneWindow(window, outputPath, width, height, () =>
        {
            void Require(bool value, string detail) { if (!value) throw new InvalidOperationException("Main validation form: " + detail); }
            OpenVisionWorkbenchViewModel model = host.Workbench; Require(host.LoadMainImageFromFileForTest(files[0]), "first owned input"); Pump(4);
            model.Images.AddImages(files.Skip(1).Select(path => new OpenVisionWorkbenchImageItem(path, Path.GetFileName(path), OpenVisionBitmapImagePreviewFactory.CreateFromPath(path))));
            model.Images.Images[0].Label = "good"; model.Images.Images[1].Label = "bad";
            int runs = host.NativePreviewRunCount, cases = 0;
            Menu menu = FindVisualChildren<Menu>(window).Single(item => AutomationProperties.GetAutomationId(item) == "WorkbenchMainMenu"); MenuItem tools = menu.Items.OfType<MenuItem>().Single(item => item.Header?.ToString() == model["Workbench.Menu.Tools"]);
            Menu bottom = FindVisualChildren<Menu>(host).Single(item => AutomationProperties.GetAutomationId(item) == "MainImagesValidationMenu"); MenuItem bottomHeader = (MenuItem)bottom.Items[0];
            MenuItem save = tools.Items.OfType<MenuItem>().Single(item => AutomationProperties.GetAutomationId(item) == "MainMenuValidationSave");
            MenuItem load = bottomHeader.Items.OfType<MenuItem>().Single(item => AutomationProperties.GetAutomationId(item) == "MainImagesValidationLoad");
            void Invoke(MenuItem parent, MenuItem item)
            {
                parent.IsSubmenuOpen = true; Pump(2);
                var peer = System.Windows.Automation.Peers.UIElementAutomationPeer.CreatePeerForElement(item)!;
                ((System.Windows.Automation.Provider.IInvokeProvider)peer.GetPattern(System.Windows.Automation.Peers.PatternInterface.Invoke)).Invoke(); Pump(4);
            }
            foreach (string palette in new[] { "Dark", "Light" })
            {
                (palette == "Dark" ? model.SelectDarkThemeCommand : model.SelectLightThemeCommand).Execute(null); Pump(3);
                foreach (OpenVisionLanguage locale in new[] { OpenVisionLanguage.Korean, OpenVisionLanguage.English })
                {
                    OpenVisionLanguageService.SetLanguage(locale); Pump(3);
                    string validationCaption = locale == OpenVisionLanguage.Korean ? "검증 세트" : "Validation set";
                    Require(model["Workbench.Images.ValidationSet"] == validationCaption && FindVisualChildren<TextBlock>(bottomHeader).Any(text => text.Text == validationCaption), "bottom localized caption");
                    Invoke(tools, save);
                    Grid overlay = FindNamedVisualChild<Grid>(window, "mainValidationOverlay")!; Border frame = FindNamedVisualChild<Border>(window, "mainValidationFrame")!;
                    TextBox name = FindNamedVisualChild<TextBox>(window, "mainValidationNameInput")!;
                    Require(overlay.IsVisible && !host.IsEnabled && frame.ActualWidth == 560D && frame.ActualHeight <= height - 60D && name.MaxLength == 60 && !model.OpenShortcutsCommand.CanExecute(null), "save structure/modal bounds");
                    Require(!menu.IsEnabled && !((FrameworkElement)window.FindName("shellTitleBar")).IsEnabled, "menu/titlebar isolated from modal");
                    Require(model.MainValidationSummary.Contains("2") && model.MainValidationSummary.Contains("1"), "labeled/excluded summary");
                    ScreenshotPngWriter.WriteElementPng(window, Path.ChangeExtension(outputPath, $".{palette}-{locale}-save.png"), width, height);
                    name.SetCurrentValue(TextBox.TextProperty, "bad/name"); Pump(2); Require(model.MainValidationName == name.Text, "control to form binding"); model.SaveMainValidationCommand.Execute(null); Pump(2);
                    TextBlock error = FindNamedVisualChild<TextBlock>(window, "mainValidationErrorText")!;
                    Require(error.IsVisible && error.Text == model["Workbench.ValidationSet.NameInvalid"] && error.Foreground is SolidColorBrush brush && brush.Color == ((SolidColorBrush)error.FindResource("OpenVision.Workbench.NgBrush")).Color, "visible localized semantic error");
                    ScreenshotPngWriter.WriteElementPng(window, Path.ChangeExtension(outputPath, $".{palette}-{locale}-error.png"), width, height);
                    model.MainValidationName = new string(locale == OpenVisionLanguage.Korean ? '검' : 'V', 52) + "_" + cases; Pump(2); Require(name.Text == model.MainValidationName, "form to control binding");
                    Button confirm = FindNamedVisualChild<Button>(window, "mainValidationConfirm")!;
                    ((System.Windows.Automation.Provider.IInvokeProvider)System.Windows.Automation.Peers.UIElementAutomationPeer.CreatePeerForElement(confirm)!.GetPattern(System.Windows.Automation.Peers.PatternInterface.Invoke)).Invoke(); Pump(4);
                    Require(!model.IsMainValidationOpen && model.MainNoticeText.Contains(model.MainValidationName) && host.IsEnabled, "saved notice/close");
                    Require(OpenVisionRecipeValidationSetStorage.TryLoad(global.Recipe.Name, out OpenVisionRecipeValidationSetDocument doc, out string loadError), "XML reload: " + loadError);
                    OpenVisionRecipeValidationSet set = doc.Sets.Single(item => item.Name == model.MainValidationName);
                    Require(set.Images.Count == 2 && set.Images.Single(item => item.Path == files[0]).Expected == OpenVisionRecipeValidationSetImage.ExpectedOk && set.Images.Single(item => item.Path == files[1]).IsExpectedNg, "only good/bad saved");
                    Invoke(bottomHeader, load); ItemsControl choices = FindVisualChildren<ItemsControl>(window).Single(item => AutomationProperties.GetAutomationId(item) == "MainValidationChoices");
                    Require(model.IsMainValidationLoad && choices.Items.Count == doc.Sets.Count && choices.IsVisible, "load choice binding");
                    ScreenshotPngWriter.WriteElementPng(window, Path.ChangeExtension(outputPath, $".{palette}-{locale}-load.png"), width, height);
                    Button choice = FindVisualChildren<Button>(choices).First(item => item.CommandParameter is OpenVisionRecipeValidationSetOption option && option.Name == set.Name);
                    Require(choice.ActualHeight >= 48D, "long name/count choice does not use one-line height");
                    ((System.Windows.Automation.Provider.IInvokeProvider)System.Windows.Automation.Peers.UIElementAutomationPeer.CreatePeerForElement(choice)!.GetPattern(System.Windows.Automation.Peers.PatternInterface.Invoke)).Invoke(); Pump(4);
                    Require(!model.IsMainValidationOpen && model.Images.Count == 3 && model.Shell.WorkspaceInputSourcePath == files[0] && host.NativePreviewRunCount == runs, "load deduplicates/preserves input/no Run");
                    save.Command.Execute(null); model.MainValidationName = set.Name; model.SaveMainValidationCommand.Execute(null); Pump(2); Require(model.MainValidationError == model["Workbench.ValidationSet.NameExists"], "duplicate cannot overwrite");
                    var run = new KeyEventArgs(Keyboard.PrimaryDevice, PresentationSource.FromVisual(window)!, 0, Key.F5) { RoutedEvent = Keyboard.PreviewKeyDownEvent }; window.RaiseEvent(run); Require(run.Handled && host.NativePreviewRunCount == runs, "modal blocks execution key");
                    var escape = new KeyEventArgs(Keyboard.PrimaryDevice, PresentationSource.FromVisual(window)!, 0, Key.Escape) { RoutedEvent = Keyboard.PreviewKeyDownEvent }; window.RaiseEvent(escape); Pump(3); Require(escape.Handled && !overlay.IsVisible && host.IsEnabled, "Escape restores Main");
                    model.ShowProductInfoCommand.Execute(null); Pump(2); Require(model.MainNoticeText == model.ProductInfoText, "product information restored after set notice");
                    string currentRecipe = global.Recipe.Name, currentInput = model.Shell.WorkspaceInputSourcePath;
                    byte[] working = VisionPipelineExecutionPlan.SerializePipeline(model.Pipeline.WorkingCopyForTest), validationXml = File.ReadAllBytes(OpenVisionRecipeValidationSetStorage.GetPath(currentRecipe));
                    string[] labels = model.Images.Images.Select(image => image.Label).ToArray();
                    object[] results = model.Images.Images.Select(image => (object)image.Result!).ToArray();
                    int layers = host.LayerDocumentCount;
                    MenuItem manage = bottomHeader.Items.OfType<MenuItem>().Single(item => AutomationProperties.GetAutomationId(item) == "MainImagesValidationManage");
                    Require(ReferenceEquals(manage.Command, model.OpenRecipeManagerCommand) && manage.CommandParameter == null, "Manage uses existing management-only command");
                    Invoke(bottomHeader, manage);
                    ToggleButton manager = FindNamedVisualChild<ToggleButton>(window, "btnHostRecipeManager")!;
                    ToggleButton advanced = FindNamedVisualChild<ToggleButton>(window, "recipeAdvancedReviewToggle")!;
                    TabItem overview = FindNamedVisualChild<TabItem>(window, "tabRecipeOverview")!;
                    Require(manager.IsChecked == true && advanced.IsChecked != true && overview.IsSelected && !model.Recipes.IsRecipeManagerDetailContextActive, "Manage opens existing overview without validation work");
                    Require(FindNamedVisualChild<Border>(window, "recipeManagerPanel")!.IsVisible, "management overview rendered");
                    Require(global.Recipe.Name == currentRecipe && model.Shell.WorkspaceInputSourcePath == currentInput && host.NativePreviewRunCount == runs && host.LayerDocumentCount == layers
                        && working.SequenceEqual(VisionPipelineExecutionPlan.SerializePipeline(model.Pipeline.WorkingCopyForTest)) && saved.SequenceEqual(File.ReadAllBytes(savedPath))
                        && validationXml.SequenceEqual(File.ReadAllBytes(OpenVisionRecipeValidationSetStorage.GetPath(currentRecipe))) && labels.SequenceEqual(model.Images.Images.Select(image => image.Label))
                        && results.SequenceEqual(model.Images.Images.Select(image => (object)image.Result!)), "Manage preserves recipe/input/pipeline/layers/labels/results/saved set without Run");
                    ScreenshotPngWriter.WriteElementPng(window, Path.ChangeExtension(outputPath, $".{palette}-{locale}-manage.png"), width, height);
                    manager.SetCurrentValue(ToggleButton.IsCheckedProperty, false); Pump(3);
                    Require(!FindNamedVisualChild<Border>(window, "recipeManagerPanel")!.IsVisible && host.IsEnabled, "manager closes back to unchanged Main");
                    cases += 2;
                }
            }
            Require(saved.SequenceEqual(File.ReadAllBytes(savedPath)) && host.NativePreviewRunCount == runs, "pipeline bytes/no Run invariant");
            File.WriteAllText(Path.ChangeExtension(outputPath, ".json"), JsonSerializer.Serialize(new { Scope = "Inprocess WPF AutomationPeer/synthetic keyboard, two live palettes/KOEN/save+load; no actual pointer/nativeDPI", DisplayCases = cases, SourcePipelineUnchanged = true, NoRun = true, LabeledOnly = true, DeduplicateCurrentPreserved = true, TwoWayName = true, CancelRecovery = true, ManageUsesExistingOverview = true, ManageDoesNotEnterValidationWork = true, ManagePreservesWorkingContext = true, SavedSetSummaryBoundary = "Existing overview has no saved validation-set summary; this check proves navigation only" }, new JsonSerializerOptions { WriteIndented = true }));
        });
    }

    private static CaptureResult CaptureMainValidationWorkflow(string outputPath)
    {
        GlobalState global = new(); global.Recipe.Name = "Smoke_MainValidationWorkflow_" + Guid.NewGuid().ToString("N");
        VisionPipeline source = new() { Name = "Pipeline" };
        source.Steps.Add(new VisionPipelineStep { Name = "Saved", ToolType = "Mean", InputLayer = "Main", OutputLayer = "SavedOutput" });
        VisionPipelineStorage.Save(global.Recipe.Name, source); VisionPipelineStorage.SaveActivePipelineName(global.Recipe.Name, source.Name);
        string pipelinePath = RecipeWorkspaceService.GetVisionPipelinePath(global.Recipe.Name, source.Name); byte[] pipelineBytes = File.ReadAllBytes(pipelinePath);
        string data = Path.Combine(Path.GetDirectoryName(outputPath)!, "validation-contract"); Directory.CreateDirectory(data);
        string good = Path.Combine(data, "good.png"), bad = Path.Combine(data, "bad.png"), corrupt = Path.Combine(data, "corrupt.png");
        using (Bitmap bitmap = CreateWorkspaceSeedSmokeBitmap()) { bitmap.Save(good, System.Drawing.Imaging.ImageFormat.Png); bitmap.Save(bad, System.Drawing.Imaging.ImageFormat.Png); }
        File.WriteAllText(corrupt, "invalid image");
        global.System.SaveWorkbenchLayout(new SystemStateConfig());
        OpenVisionShellHostWindow window = new(new ApplicationRuntimeContext(global, new DisplayManagerService())); window.ClearValue(OpenVisionShellHostWindow.ClosingCommandProperty);
        OpenVisionShellHostView host = window.ShellHostForSmoke;
        return CaptureStandaloneWindow(window, outputPath, 1280, 760, () =>
        {
            void Require(bool value, string detail) { if (!value) throw new InvalidOperationException("Main validation workflow: " + detail); }
            File.WriteAllText(Path.ChangeExtension(outputPath, ".monitor.txt"), SmokeWindowMonitorPlacement.PlaceOnLeftmostMonitor(window));
            OpenVisionWorkbenchViewModel model = host.Workbench; int runs = host.NativePreviewRunCount, cases = 0;
            model.OpenMainValidationLoadCommand.Execute(null); Pump(3); Require(model.IsMainValidationOpen && model.HasNoMainValidationSets && !model.HasMainValidationError, "empty set chooser"); model.CloseMainValidationCommand.Execute(null);
            OpenVisionRecipeValidationSet set = new() { Name = "Owned good/bad", Images = new() { new() { Path = good, Expected = OpenVisionRecipeValidationSetImage.ExpectedOk }, new() { Path = bad, Expected = OpenVisionRecipeValidationSetImage.ExpectedNg } } };
            OpenVisionRecipeValidationSet broken = new() { Name = "Broken", Images = new() { new() { Path = good }, new() { Path = corrupt } } };
            Require(!model.Images.TryLoadValidationSet(broken, out string error) && model.Images.Count == 0 && !model.Shell.HasWorkspaceInputImage, "corrupt set retains empty state: " + error);
            Require(model.Images.TryLoadValidationSet(set, out error) && model.Images.Count == 2 && model.Images.CurrentIndex == 0 && model.Shell.WorkspaceInputSourcePath == good, "valid retry selects first only from empty");
            model.Images.Images[0].ReplaceResult(new OpenVisionWorkbenchImageResult("Previous", 0, source, new Dictionary<int, VisionPipelineStepResultSummary>(), new Dictionary<int, Bitmap>(), "Ok", 1, "Synthetic retained result"));
            var result = model.Images.Images[0].Result;
            Require(!model.Images.TryLoadValidationSet(broken, out error) && model.Images.Count == 2 && ReferenceEquals(result, model.Images.Images[0].Result), "failure preserves current/result/list");
            Require(model.Images.TryLoadValidationSet(set, out error) && model.Images.Count == 2 && ReferenceEquals(result, model.Images.Images[0].Result), "repeat load deduplicates/result independent"); cases++;
            model.OpenMainValidationSaveCommand.Execute(null); model.MainValidationName = "Stored"; model.SaveMainValidationCommand.Execute(null); Require(!model.IsMainValidationOpen, "save existing labels");
            string store = OpenVisionRecipeValidationSetStorage.GetPath(global.Recipe.Name); byte[] xml = File.ReadAllBytes(store);
            model.OpenMainValidationSaveCommand.Execute(null); model.MainValidationName = "AfterLock";
            using (FileStream locked = new(store, FileMode.Open, FileAccess.Read, FileShare.Read)) { model.SaveMainValidationCommand.Execute(null); Require(model.IsMainValidationOpen && model.HasMainValidationError && xml.SequenceEqual(File.ReadAllBytes(store)), "locked save preserves form/XML"); }
            model.SaveMainValidationCommand.Execute(null); Require(!model.IsMainValidationOpen && OpenVisionRecipeValidationSetStorage.TryLoad(global.Recipe.Name, out OpenVisionRecipeValidationSetDocument savedDoc, out error) && savedDoc.Sets.Count == 2, "retry after save lock"); cases++;
            byte[] validXml = File.ReadAllBytes(store); File.WriteAllText(store, "<broken>");
            model.OpenMainValidationLoadCommand.Execute(null); Require(model.IsMainValidationOpen && model.HasMainValidationError && model.MainValidationSets.Count == 0, "malformed XML error retained"); model.CloseMainValidationCommand.Execute(null); File.WriteAllBytes(store, validXml);
            model.OpenMainValidationLoadCommand.Execute(null); Require(!model.HasMainValidationError && model.MainValidationSets.Count == 2, "valid reload after malformed XML"); Pump(3);
            ScreenshotPngWriter.WriteElementPng(window, Path.ChangeExtension(outputPath, ".chooser.png"), 1280, 760);
            model.CloseMainValidationCommand.Execute(null); cases++;
            model.Images.Images[0].Label = ""; model.Images.Images[1].Label = "";
            model.OpenMainValidationSaveCommand.Execute(null); model.MainValidationName = "NoLabels"; model.SaveMainValidationCommand.Execute(null); Require(model.MainValidationError == model["Workbench.ValidationSet.NoLabels"] && validXml.SequenceEqual(File.ReadAllBytes(store)), "no labels not saved"); model.CloseMainValidationCommand.Execute(null);
            Require(!model.Recipes.TrySaveMainValidationSet("NonFile", new[] { new OpenVisionRecipeValidationSetImage { Path = "", Expected = OpenVisionRecipeValidationSetImage.ExpectedOk } }, out error) && validXml.SequenceEqual(File.ReadAllBytes(store)), "non-file label cannot partially save");
            model.OpenMainValidationSaveCommand.Execute(null); model.MainValidationName = ""; model.SaveMainValidationCommand.Execute(null); Require(model.MainValidationError == model["Workbench.ValidationSet.NameRequired"], "required name"); model.CloseMainValidationCommand.Execute(null); cases++;
            string[] labelsBefore = model.Images.Images.Select(image => image.Label).ToArray();
            byte[] workingBefore = VisionPipelineExecutionPlan.SerializePipeline(model.Pipeline.WorkingCopyForTest);
            void Retained(string scenario) => Require(model.Images.Count == 2 && model.Images.Images.Select(image => image.Label).SequenceEqual(labelsBefore)
                && ReferenceEquals(result, model.Images.Images[0].Result) && model.Shell.WorkspaceInputSourcePath == good
                && workingBefore.SequenceEqual(VisionPipelineExecutionPlan.SerializePipeline(model.Pipeline.WorkingCopyForTest)), scenario + " retains images/labels/result/input/working copy");
            model.OpenMainValidationLoadCommand.Execute(null);
            OpenVisionRecipeValidationSetOption storedOption = model.MainValidationSets.Single(option => option.Name == "Stored");
            Require(storedOption.Set.Images.All(image => image.Sha256 == OpenVisionRecipeValidationSetStorage.ComputeFileSha256(image.Path))
                && !storedOption.IsIdentityLocked && string.IsNullOrEmpty(storedOption.ImageSetSha256), "Main save captures row hashes without freezing editable set");
            string foreignRecipe = global.Recipe.Name + "_Other";
            OpenVisionRecipeValidationSetDocument foreignDoc = new() { Sets = new() { new() { Name = "Stored", Images = new() { new() { Path = good, Expected = "NG" } } } } };
            Require(OpenVisionRecipeValidationSetStorage.TrySave(foreignRecipe, foreignDoc, out error), "owned foreign set fixture");
            var foreignOption = new OpenVisionRecipeValidationSetOption(foreignDoc.Sets[0]);
            Require(!model.LoadMainValidationCommand.CanExecute(foreignOption), "foreign chooser option disabled");
            model.LoadMainValidationCommand.Execute(foreignOption);
            Require(model.IsMainValidationOpen && model.MainValidationError == model["Workbench.ValidationSet.SetNotCurrent"], "direct foreign option rejected"); Retained("foreign chooser");
            OpenVisionRecipeValidationSetStorage.TryLoad(global.Recipe.Name, out OpenVisionRecipeValidationSetDocument changedDoc, out error);
            changedDoc.Sets.Single(value => value.Name == "Stored").Images[0].Expected = "NG";
            Require(OpenVisionRecipeValidationSetStorage.TrySave(global.Recipe.Name, changedDoc, out error), "owned label change fixture");
            model.LoadMainValidationCommand.Execute(storedOption);
            Require(model.IsMainValidationOpen && model.MainValidationError == model["Workbench.ValidationSet.SetChanged"], "changed saved label rejected before loading"); Retained("stale label");
            File.WriteAllBytes(store, validXml);
            changedDoc.Sets.Single(value => value.Name == "Stored").Images[0].Expected = storedOption.Set.Images[0].Expected;
            changedDoc.Sets.Single(value => value.Name == "Stored").PipelineDefinitionSha256 = new string('A', 64);
            Require(OpenVisionRecipeValidationSetStorage.TrySave(global.Recipe.Name, changedDoc, out error), "owned frozen-state change fixture");
            model.LoadMainValidationCommand.Execute(storedOption);
            Require(model.IsMainValidationOpen && model.MainValidationError == model["Workbench.ValidationSet.SetChanged"], "changed frozen state cannot reuse unlocked chooser snapshot"); Retained("stale frozen state");
            File.WriteAllBytes(store, validXml);
            changedDoc.Sets.RemoveAll(value => value.Name == "Stored");
            Require(OpenVisionRecipeValidationSetStorage.TrySave(global.Recipe.Name, changedDoc, out error), "owned deleted-set fixture");
            model.LoadMainValidationCommand.Execute(storedOption);
            Require(model.IsMainValidationOpen && model.MainValidationError == model["Workbench.ValidationSet.SetChanged"], "deleted selected set rejected"); Retained("deleted set");
            File.WriteAllBytes(store, validXml); model.CloseMainValidationCommand.Execute(null);
            model.OpenMainValidationLoadCommand.Execute(null); storedOption = model.MainValidationSets.Single(option => option.Name == "Stored");
            byte[] validBad = File.ReadAllBytes(bad);
            using (Bitmap replacement = new(24, 18)) { using Graphics graphics = Graphics.FromImage(replacement); graphics.Clear(DrawingColor.Green); replacement.Save(bad, ImageFormat.Png); }
            foreach (string palette in new[] { "Dark", "Light" })
            foreach (OpenVisionLanguage locale in new[] { OpenVisionLanguage.Korean, OpenVisionLanguage.English })
            {
                (palette == "Dark" ? model.SelectDarkThemeCommand : model.SelectLightThemeCommand).Execute(null);
                OpenVisionLanguageService.SetLanguage(locale, false);
                model.LoadMainValidationCommand.Execute(storedOption); Pump(3);
                Require(model.IsMainValidationOpen && model.HasMainValidationError, "valid-image byte mismatch rejected"); Retained("image hash mismatch");
                ScreenshotPngWriter.WriteElementPng(window, Path.ChangeExtension(outputPath, $".{palette}-{locale}-hash-error.png"), 1280, 760);
            }
            File.WriteAllBytes(bad, validBad);
            model.LoadMainValidationCommand.Execute(storedOption);
            Require(!model.IsMainValidationOpen, "valid image restore recovers same selection without Run");
            labelsBefore = model.Images.Images.Select(image => image.Label).ToArray();
            OpenVisionLanguageService.SetLanguage(OpenVisionLanguage.Korean, false); model.SelectDarkThemeCommand.Execute(null);
            var partial = new OpenVisionRecipeValidationSet { Name = "Legacy partial", Images = new() { new() { Path = good, Expected = "OK", Sha256 = OpenVisionRecipeValidationSetStorage.ComputeFileSha256(good) }, new() { Path = bad, Expected = "NG" } } };
            Require(model.Images.TryLoadValidationSet(partial, out error), "legacy partial hash remains compatible; unhashed row is unverified");
            var frozenMissing = new OpenVisionRecipeValidationSet { Name = "Frozen missing", PipelineDefinitionSha256 = new string('A', 64), Images = partial.Images };
            frozenMissing.ImageSetSha256 = OpenVisionRecipeValidationSetStorage.ComputeImageSetSha256(frozenMissing.Images);
            Require(!model.Images.TryLoadValidationSet(frozenMissing, out error), "frozen row without hash rejected"); Retained("frozen missing hash"); cases++;
            Require(host.RecipeCommands.FocusPipelineStepForEdit(global.Recipe.Name, source.Name, 1) && host.RecipeCommands.SelectedStepEditObject != null, "existing nonempty Step editor fixture");
            Require(model.Pipeline.InsertStep(1, new VisionPipelineStep { Name = "Pending", ToolType = "Mean", InputLayer = "SavedOutput", OutputLayer = "PendingOutput" }) != null, "owned dirty working copy fixture");
            Pump(3);
            Require(host.RecipeCommands.SelectedStepEditObject != null, "nonempty editor retained by owned fixture mutation");
            host.RecipeCommands.MarkSelectedStepEditDirtyForQualificationTest();
            object pendingEditor = host.RecipeCommands.SelectedStepEditObject;
            byte[] pendingWorking = VisionPipelineExecutionPlan.SerializePipeline(model.Pipeline.WorkingCopyForTest);
            string pipelineBefore = host.RecipeCommands.SelectedPipelineOption.PipelineName;
            model.OpenMainValidationSaveCommand.Execute(null); model.MainValidationName = "HashRetry";
            using (FileStream locked = new(bad, FileMode.Open, FileAccess.ReadWrite, FileShare.None))
            {
                model.SaveMainValidationCommand.Execute(null);
                Require(model.IsMainValidationOpen && model.HasMainValidationError && validXml.SequenceEqual(File.ReadAllBytes(store)), "hash read failure preserves form and stored XML");
            }
            model.SaveMainValidationCommand.Execute(null);
            Require(!model.IsMainValidationOpen && host.RecipeCommands.IsSelectedStepEditDirty && ReferenceEquals(pendingEditor, host.RecipeCommands.SelectedStepEditObject)
                && model.Pipeline.IsDirty && pendingWorking.SequenceEqual(VisionPipelineExecutionPlan.SerializePipeline(model.Pipeline.WorkingCopyForTest))
                && host.RecipeCommands.SelectedPipelineOption.PipelineName == pipelineBefore && host.RecipeCommands.MainRecipeName == global.Recipe.Name
                && host.RecipeCommands.RecipeManagerValidationSets.Any(option => option.Name == "HashRetry"), "save retry refreshes read projections without resetting dirty editor/context"); cases++;
            string replacementPath = Path.Combine(data, "replacement.png"), backupBad = Path.Combine(data, "bad-backup.png");
            using (Bitmap replacement = new(28, 20)) { using Graphics graphics = Graphics.FromImage(replacement); graphics.Clear(DrawingColor.Blue); replacement.Save(replacementPath, ImageFormat.Png); }
            Require(Path.GetDirectoryName(Path.GetFullPath(bad)) == Path.GetFullPath(data) && Path.GetDirectoryName(Path.GetFullPath(backupBad)) == Path.GetFullPath(data), "owned D repair paths");
            File.Move(bad, backupBad);
            try
            {
                var repairOwner = new OpenVisionRecipeValidationSetDocumentOwner(); Require(repairOwner.TryLoad(global.Recipe.Name, out error), "repair reads same saved schema");
                OpenVisionRecipeValidationSet repairSet = repairOwner.BuildSelection("Stored", "", "", "").Selected.Set;
                OpenVisionRecipeValidationSetImage repairRow = repairSet.Images.Single(image => image.Path == bad);
                string oldHash = repairRow.Sha256, oldExpected = repairRow.Expected; repairRow.Notes = "Owned repair notes";
                using (FileStream locked = new(replacementPath, FileMode.Open, FileAccess.ReadWrite, FileShare.None))
                    Require(!repairOwner.TryRepairMissingImagePath("Stored", bad, replacementPath, out _, out error) && repairRow.Path == bad && repairRow.Sha256 == oldHash, "repair hash failure retains prior path/hash");
                Require(repairOwner.TryRepairMissingImagePath("Stored", bad, replacementPath, out _, out error) && repairRow.Expected == oldExpected && repairRow.Notes == "Owned repair notes"
                    && repairRow.Sha256 == OpenVisionRecipeValidationSetStorage.ComputeFileSha256(replacementPath) && repairOwner.TrySave(global.Recipe.Name, out error), "explicit repair updates known hash with path and preserves label/notes");
                model.OpenMainValidationLoadCommand.Execute(null);
                model.LoadMainValidationCommand.Execute(model.MainValidationSets.Single(option => option.Name == "Stored"));
                Require(!model.IsMainValidationOpen && model.Images.Images.Any(image => image.Path == replacementPath && image.Label == "bad"), "repaired saved set loads without engine");
            }
            finally { File.Move(backupBad, bad); }
            Require(host.RecipeCommands.IsSelectedStepEditDirty && ReferenceEquals(pendingEditor, host.RecipeCommands.SelectedStepEditObject)
                && pendingWorking.SequenceEqual(VisionPipelineExecutionPlan.SerializePipeline(model.Pipeline.WorkingCopyForTest)), "load preserves same dirty editor and working copy"); cases++;
            Require(host.NativePreviewRunCount == runs && pipelineBytes.SequenceEqual(File.ReadAllBytes(pipelinePath)) && model.Shell.WorkspaceInputSourcePath == good && ReferenceEquals(result, model.Images.Images[0].Result), "no Run/input/result/pipeline immutable");
            File.WriteAllText(Path.ChangeExtension(outputPath, ".json"), JsonSerializer.Serialize(new { Scope = "Owned D files/XML failures and Main input recovery; no actual file dialogs or algorithm validation", Cases = cases, EmptyRetry = true, DuplicatePreservesInputResult = true, SaveFaultRetry = true, MalformedXmlRecovery = true, NoLabelsAndNonFileRejected = true, NoRun = true, SourcePipelineUnchanged = true }, new JsonSerializerOptions { WriteIndented = true }));
        });
    }

    private static CaptureResult CaptureMainRecipePendingSave(string outputPath)
    {
        string token = Guid.NewGuid().ToString("N").Substring(0, 12), selected = "PendingSave_" + token;
        VisionPipeline clean = new() { Name = "Guard" }; clean.Steps.Add(new VisionPipelineStep { Name = "Saved", ToolType = "Mean", InputLayer = "Main", OutputLayer = "SavedOutput" });
        VisionPipelineStorage.Save(selected, clean); VisionPipelineStorage.SaveActivePipelineName(selected, clean.Name);
        OpenVisionRecipePendingEditDecision decision = OpenVisionRecipePendingEditDecision.ApplyAndContinue;
        OpenVisionShellHostRecipeCommandSurface commands = new(() => selected, name => selected = name, () => { }, decidePendingEdit: _ => decision, saveRecipe: () => true, saveRuntimeRecipeCopy: _ => false);
        using DisplayManagerService display = new(); using OpenVisionWorkbenchPipelineViewModel pipeline = new(commands, display, action => action(), _ => decision, _ => true, Array.Empty<OpenVisionShellNavGroup>()); commands.AttachWorkbenchPipeline(pipeline);
        OpenVisionWorkbenchViewModel model = new(new SystemStateConfig(), _ => true, recipes: commands);
        return CaptureWindowWithContent(new TextBlock { Text = "Main recipe pending-save/error contracts" }, outputPath, 640, 160, () =>
        {
            pipeline.InsertStep(1, new VisionPipelineStep { Name = "Pending", ToolType = "Mean", InputLayer = "Main", OutputLayer = "PendingOutput" });
            string source = selected, path = RecipeWorkspaceService.GetVisionPipelinePath(source, "Guard"); byte[] original = File.ReadAllBytes(path);
            string deniedName = "Denied_" + token;
            using (FileStream locked = new(path, FileMode.Open, FileAccess.Read, FileShare.Read))
            {
                var denied = commands.CreateMainRecipeAsync(deniedName, "", "Copied", true, false); WaitForTaskWithPump(denied, 10000, "Main new copy pending save failure");
                if (!denied.Result.Canceled || !pipeline.IsDirty || !original.SequenceEqual(File.ReadAllBytes(path)) || RecipeWorkspaceService.GetRecipeNames().Contains(deniedName))
                    throw new InvalidOperationException("Main pending-save failure switched, created target, discarded working copy or changed original.");
            }
            var saved = commands.CreateMainRecipeAsync("AfterSave_" + token, "", "Copied", true, false); WaitForTaskWithPump(saved, 10000, "Main pending save succeeds but target runtime copy fails");
            if (saved.Result.Succeeded || selected != source || pipeline.IsDirty || VisionPipelineStorage.Load(source, "Guard").Steps.Count != 2 || RecipeWorkspaceService.GetRecipeNames().Contains("AfterSave_" + token))
                throw new InvalidOperationException("Main apply saved snapshot/failed target rollback differs: succeeded=" + saved.Result.Succeeded + "; canceled=" + saved.Result.Canceled + "; selected=" + selected + "; source=" + source + "; dirty=" + pipeline.IsDirty + "; steps=" + VisionPipelineStorage.Load(source, "Guard").Steps.Count + "; targetExists=" + RecipeWorkspaceService.GetRecipeNames().Contains("AfterSave_" + token) + "; error=" + saved.Result.Error + "; status=" + commands.StatusText);
            model.OpenMainSaveAsCommand.Execute(null); model.MainRecipeName = "UiFailure_" + token; model.SubmitMainRecipeCommand.Execute(null); WaitForTaskWithPump(model.MainRecipeSubmission, 10000, "Main SaveAs form save failure");
            if (!model.IsMainRecipeOpen || model.IsMainRecipeBusy || string.IsNullOrEmpty(model.MainRecipeError) || selected != source || RecipeWorkspaceService.GetRecipeNames().Contains("UiFailure_" + token))
                throw new InvalidOperationException("Main save failure did not keep error form/original context.");
            model.CloseMainRecipeCommand.Execute(null); model.OpenMainSaveAsCommand.Execute(null);
            if (!model.IsMainRecipeOpen || model.HasMainRecipeError) throw new InvalidOperationException("Main save error cancel/reopen retained stale error.");
            model.CloseMainRecipeCommand.Execute(null); commands.DetachWorkbenchPipeline(pipeline); model.Dispose();
            File.WriteAllText(Path.ChangeExtension(outputPath, ".json"), JsonSerializer.Serialize(new { Scope = "Isolated Main pending-save/failure and form-state contracts; file lock owned D fixture, no actual modal UI", Cases = 4, LockedSaveKeptDirtyOriginal = true, ApplySavedOriginalBeforeCopy = true, TargetFailureRolledBack = true, SaveFailureFormCancelReopen = true }, new JsonSerializerOptions { WriteIndented = true }));
        });
    }

    private static CaptureResult CaptureMainRecipeWorkflow(string outputPath)
    {
        string token = Guid.NewGuid().ToString("N").Substring(0, 12);
        GlobalState global = new(); global.Recipe.Name = "Smoke_MainRecipe_" + token;
        VisionPipeline source = new() { Name = "Source" }; VisionPipelineStorage.Save(global.Recipe.Name, source); VisionPipelineStorage.SaveActivePipelineName(global.Recipe.Name, source.Name);
        RecipeDataStorage.Save(global.Recipe.Name, new DataState { Description = "Original description" });
        global.System.SaveWorkbenchLayout(new SystemStateConfig());
        OpenVisionShellHostWindow window = new(new ApplicationRuntimeContext(global, new DisplayManagerService())); window.ClearValue(OpenVisionShellHostWindow.ClosingCommandProperty);
        OpenVisionShellHostView host = window.ShellHostForSmoke;
        return CaptureStandaloneWindow(window, outputPath, 1280, 760, () =>
        {
            OpenVisionWorkbenchViewModel model = host.Workbench; List<object> cases = new();
            void Require(bool value, string detail) { if (!value) throw new InvalidOperationException("Main recipe workflow: " + detail); }
            Dictionary<string, byte[]> Snapshot(string recipe) => Directory.EnumerateFiles(RecipeWorkspaceService.GetRecipeWorkspaceDirectory(recipe), "*", SearchOption.AllDirectories).ToDictionary(path => Path.GetRelativePath(RecipeWorkspaceService.GetRecipeWorkspaceDirectory(recipe), path), File.ReadAllBytes);
            bool Unchanged(string recipe, Dictionary<string, byte[]> before)
            {
                Dictionary<string, byte[]> after = Snapshot(recipe); return before.Count == after.Count && before.All(pair => after.TryGetValue(pair.Key, out byte[] bytes) && pair.Value.SequenceEqual(bytes));
            }
            using Bitmap input = CreateWorkspaceSeedSmokeBitmap(); host.SetMainLayerImageForTest(input); Pump(6);
            int runs = host.NativePreviewRunCount, imageCount = model.Images.Count;
            string original = global.Recipe.Name; Dictionary<string, byte[]> originalBytes = Snapshot(original);
            model.OpenMainNewRecipeCommand.Execute(null); model.MainRecipeName = "Empty_" + token; model.MainRecipeDescription = "새 설명 & <새 레시피>"; model.MainRecipeFirstPipeline = "First_" + token;
            model.SubmitMainRecipeCommand.Execute(null); Require(!model.SubmitMainRecipeCommand.CanExecute(null), "duplicate submit unavailable while switching");
            CancelEventArgs closing = new(); model.CloseMainWindowCommand.Execute(closing); Require(closing.Cancel, "close prevented while switching");
            WaitForTaskWithPump(model.MainRecipeSubmission, 30000, "Main new empty recipe"); Pump(10);
            Require(!model.IsMainRecipeOpen && !model.IsMainRecipeBusy && global.Recipe.Name == "Empty_" + token, "empty create/open completed: " + model.MainRecipeError);
            Require(model.Pipeline.WorkingCopyForTest.Name == "First_" + token && model.Pipeline.WorkingCopyForTest.Steps.Count == 0, "one empty named first pipeline");
            Require(RecipeDataStorage.Load(global.Recipe.Name, new DataState()).Description == "새 설명 & <새 레시피>", "description XML round trip");
            Require(Unchanged(original, originalBytes) && host.NativePreviewRunCount == runs && model.Images.Count == imageCount && model.Shell.HasWorkspaceInputImage, "new recipe preserves original, input list and no Run");
            Require(global.Data.SavedRevision == 1 && !string.IsNullOrEmpty(global.Data.SavedContentHash), "manual New initializes r1 and complete saved content hash");
            string createdHash = global.Data.SavedContentHash;
            var createdFiles = Snapshot(global.Recipe.Name);
            bool unchangedSaveSucceeded = RecipeRuntimeStorage.SaveWithRevision(global.Recipe.Name, () => global.Data, () => global.VisionTools);
            var afterFirstSave = Snapshot(global.Recipe.Name);
            string changedFiles = string.Join(",", afterFirstSave.Where(pair => !createdFiles.TryGetValue(pair.Key, out byte[] bytes) || !pair.Value.SequenceEqual(bytes)).Select(pair => pair.Key));
            Require(unchangedSaveSucceeded && global.Data.SavedRevision == 1 && global.Data.SavedContentHash == createdHash, "first unchanged save after default tools load retains r1: revision=" + global.Data.SavedRevision + ", changedFiles=" + changedFiles);
            cases.Add(new { Case = "new-empty-description-open-r1-unchanged-save", PASS = true });
            string savedRecipe = global.Recipe.Name;
            VisionPipeline second = new() { Name = "Second" }; second.Steps.Add(new VisionPipelineStep { Name = "Saved second", ToolType = "Mean", InputLayer = "Main", OutputLayer = "SecondOutput" }); VisionPipelineStorage.Save(savedRecipe, second);
            model.Pipeline.InsertStep(0, new VisionPipelineStep { Name = "Unsaved working step", ToolType = "Mean", InputLayer = "Main", OutputLayer = "WorkingOutput", Enabled = false }); Pump(4);
            VisionPipeline working = model.Pipeline.CopyWorkingPipeline(); Require(model.Pipeline.IsDirty, "dirty working source");
            if (model.Images.Count > 0) model.Images.Images[0].ReplaceResult(new OpenVisionWorkbenchImageResult("Previous", 0, source, new Dictionary<int, VisionPipelineStepResultSummary>(), new Dictionary<int, Bitmap>(), "Ok", 1, "Synthetic prior result"));
            Dictionary<string, byte[]> savedBytes = Snapshot(savedRecipe);
            model.OpenMainSaveAsCommand.Execute(null); model.MainRecipeName = "SaveAs_" + token; model.MainRecipeDescription = "Current working copy description";
            model.SubmitMainRecipeCommand.Execute(null); WaitForTaskWithPump(model.MainRecipeSubmission, 30000, "Main SaveAs working copy"); Pump(10);
            Require(!model.IsMainRecipeOpen && global.Recipe.Name == "SaveAs_" + token, "SaveAs selects target: " + model.MainRecipeError);
            Require(VisionPipelineExecutionPlan.SerializePipeline(working).SequenceEqual(VisionPipelineExecutionPlan.SerializePipeline(model.Pipeline.WorkingCopyForTest)), "SaveAs current working pipeline equals copied DTO");
            Require(RecipeWorkspaceService.GetVisionPipelineNames(global.Recipe.Name).Contains("Second") && VisionPipelineStorage.Load(global.Recipe.Name, "Second").Steps[0].Name == "Saved second", "SaveAs retains other saved pipeline");
            Require(RecipeDataStorage.Load(global.Recipe.Name, new DataState()).Description == "Current working copy description", "SaveAs description reopened");
            Require(Unchanged(savedRecipe, savedBytes) && model.Images.Count == imageCount && model.Images.Images.All(item => item.Result == null) && model.Shell.HasWorkspaceInputImage && host.NativePreviewRunCount == runs, "SaveAs original bytes unchanged/input kept/prior results cleared/no Run");
            Require(global.Data.SavedRevision == 1 && !string.IsNullOrEmpty(global.Data.SavedContentHash), "SaveAs new identity initializes r1 and current target hash");
            cases.Add(new { Case = "saveas-current-working-with-other-saved-pipeline-r1", PASS = true });
            ScreenshotPngWriter.WriteElementPng(window, Path.ChangeExtension(outputPath, ".saveas-main.png"), 1280, 760);
            OpenVisionRecipeWorkspaceUseCase useCase = new(); string failed = "Failure_" + token;
            OpenVisionRecipeWorkspaceResult failure = useCase.CreateWorkbenchRecipe(failed, "Failure", working, savedRecipe, _ => false);
            Require(!failure.Succeeded && !RecipeWorkspaceService.GetRecipeNames().Contains(failed) && Unchanged(savedRecipe, savedBytes), "failed runtime save rolls back only target");
            Require(useCase.CreateWorkbenchRecipe(failed, "Retry", working, savedRecipe, _ => true).Succeeded, "valid retry after save fault");
            Require(!useCase.CreateWorkbenchRecipe(failed, "overwrite", working, savedRecipe, _ => true).Succeeded && RecipeDataStorage.Load(failed, new DataState()).Description == "Retry", "duplicate cannot overwrite target");
            string hashFailure = "HashFailure_" + token;
            var hashFailed = useCase.CreateWorkbenchRecipe(hashFailure, "Hash failure", working, savedRecipe, target => { File.WriteAllText(RecipeWorkspaceService.GetVisionConfigPath(target, "InvalidHashInput"), "<truncated"); return true; });
            Require(!hashFailed.Succeeded && !RecipeWorkspaceService.GetRecipeNames().Contains(hashFailure) && Unchanged(savedRecipe, savedBytes), "initial target hash failure cleans only target and preserves source");
            Require(useCase.CreateWorkbenchRecipe(hashFailure, "Retry", working, savedRecipe, _ => true).Succeeded && RecipeDataStorage.Load(hashFailure, new DataState()).SavedRevision == 1, "initial hash failure valid retry persists r1");
            cases.Add(new { Case = "save-and-initial-hash-fault-target-cleanup-retry-duplicate", PASS = true });
            string selected = "Guard_" + token; VisionPipeline clean = new() { Name = "GuardPipeline" }; clean.Steps.Add(new VisionPipelineStep { Name = "Saved guard step", ToolType = "Mean", InputLayer = "Main", OutputLayer = "GuardOutput" }); VisionPipelineStorage.Save(selected, clean); VisionPipelineStorage.SaveActivePipelineName(selected, clean.Name);
            OpenVisionRecipePendingEditDecision decision = OpenVisionRecipePendingEditDecision.Cancel; int decisions = 0;
            OpenVisionShellHostRecipeCommandSurface commands = new(() => selected, name => selected = name, () => { }, decidePendingEdit: _ => { decisions++; return decision; }, saveRuntimeRecipeCopy: _ => true);
            using DisplayManagerService display = new(); using OpenVisionWorkbenchPipelineViewModel pipeline = new(commands, display, action => action(), _ => { decisions++; return decision; }, _ => true, Array.Empty<OpenVisionShellNavGroup>()); commands.AttachWorkbenchPipeline(pipeline);
            pipeline.InsertStep(1, new VisionPipelineStep { Name = "Unsaved guard step", ToolType = "Mean", InputLayer = "Main", OutputLayer = "UnsavedOutput" });
            string canceledName = "Canceled_" + token; var canceledTask = commands.CreateMainRecipeAsync(canceledName, "", "Copied", true, false); WaitForTaskWithPump(canceledTask, 10000, "Main new copy cancel");
            Require(canceledTask.Result.Canceled && pipeline.WorkingCopyForTest.Steps.Count == 2 && !RecipeWorkspaceService.GetRecipeNames().Contains(canceledName), "New copy cancel retains unsaved original/no target");
            decision = OpenVisionRecipePendingEditDecision.Discard; var copiedTask = commands.CreateMainRecipeAsync("Copied_" + token, "Copy", "Copied", true, false); WaitForTaskWithPump(copiedTask, 10000, "Main new copy after discard");
            Require(copiedTask.Result.Succeeded && VisionPipelineStorage.Load(selected, "Copied").Steps.Count == 1 && VisionPipelineStorage.Load(selected, "Copied").Steps[0].Name == "Saved guard step" && decisions == 2, "New copy snapshot occurs after discard guard");
            commands.DetachWorkbenchPipeline(pipeline); cases.Add(new { Case = "new-copy-pending-cancel-discard-order", PASS = true });
            using StringWriter xml = new(); new System.Xml.Serialization.XmlSerializer(typeof(DataState)).Serialize(xml, new DataState()); Require(!xml.ToString().Contains("<Description", StringComparison.Ordinal), "empty metadata preserves legacy CData shape");
            File.WriteAllText(Path.ChangeExtension(outputPath, ".json"), JsonSerializer.Serialize(new { Scope = "Inprocess WPF Main create/SaveAs plus existing pending guard and isolated save fault; no actual input/template detachment/full Tool roundtrip", Cases = cases, NoRun = true, OriginalFilesUnchanged = true, InputKept = true, EmptyDescriptionOmitted = true }, new JsonSerializerOptions { WriteIndented = true }));
        });
    }

    private static CaptureResult CaptureMainRecipeForm(string outputPath, int width, int height)
    {
        GlobalState global = new(); global.Recipe.Name = "Smoke_MainRecipeForm_" + Guid.NewGuid().ToString("N");
        VisionPipeline source = new() { Name = "Pipeline" }; VisionPipelineStorage.Save(global.Recipe.Name, source); VisionPipelineStorage.SaveActivePipelineName(global.Recipe.Name, source.Name);
        string savedPath = RecipeWorkspaceService.GetVisionPipelinePath(global.Recipe.Name, source.Name); byte[] saved = File.ReadAllBytes(savedPath);
        global.System.SaveWorkbenchLayout(new SystemStateConfig());
        OpenVisionShellHostWindow window = new(new ApplicationRuntimeContext(global, new DisplayManagerService())); window.ClearValue(OpenVisionShellHostWindow.ClosingCommandProperty);
        OpenVisionShellHostView host = window.ShellHostForSmoke;
        return CaptureStandaloneWindow(window, outputPath, width, height, () =>
        {
            OpenVisionWorkbenchViewModel model = host.Workbench;
            Menu menu = FindVisualChildren<Menu>(window).Single(item => AutomationProperties.GetAutomationId(item) == "WorkbenchMainMenu"); MenuItem file = (MenuItem)menu.Items[0];
            int runs = host.NativePreviewRunCount, cases = 0; string prefs = JsonSerializer.Serialize(global.System.WorkbenchLayoutPreferences);
            foreach (string palette in new[] { "Dark", "Light" })
            {
                (palette == "Dark" ? model.SelectDarkThemeCommand : model.SelectLightThemeCommand).Execute(null); Pump(4); prefs = JsonSerializer.Serialize(global.System.WorkbenchLayoutPreferences);
                foreach (OpenVisionLanguage locale in new[] { OpenVisionLanguage.Korean, OpenVisionLanguage.English })
                {
                    OpenVisionLanguageService.SetLanguage(locale); Pump(3);
                    foreach (bool saveAs in new[] { false, true })
                    {
                        MenuItem entry = file.Items.OfType<MenuItem>().Single(item => item.Header?.ToString() == model[saveAs ? "Workbench.Menu.SaveAs" : "Workbench.Menu.NewRecipe"]);
                        if (entry.Command?.CanExecute(entry.CommandParameter) != true) throw new InvalidOperationException("Main recipe menu remains unavailable.");
                        file.IsSubmenuOpen = true; Pump(3);
                        var peer = System.Windows.Automation.Peers.UIElementAutomationPeer.CreatePeerForElement(entry)!;
                        ((System.Windows.Automation.Provider.IInvokeProvider)peer.GetPattern(System.Windows.Automation.Peers.PatternInterface.Invoke)).Invoke(); Pump(5);
                        Grid overlay = FindNamedVisualChild<Grid>(window, "mainRecipeOverlay")!; Border frame = FindNamedVisualChild<Border>(window, "mainRecipeFrame")!;
                        TextBox name = FindNamedVisualChild<TextBox>(window, "mainRecipeNameInput")!, memo = FindNamedVisualChild<TextBox>(window, "mainRecipeDescriptionInput")!, first = FindNamedVisualChild<TextBox>(window, "mainRecipePipelineInput")!;
                        StackPanel fields = FindNamedVisualChild<StackPanel>(window, "mainRecipeNewFields")!;
                        if (!overlay.IsVisible || frame.ActualWidth != 560D || frame.ActualHeight > height - 60D || host.IsEnabled || fields.IsVisible == saveAs
                            || model.OpenShortcutsCommand.CanExecute(null) || model.IsMainRecipeSaveAs != saveAs || name.MaxLength != 60 || memo.MaxLength != 120 || first.MaxLength != 60)
                            throw new InvalidOperationException("Main recipe modal structure/isolation/limits differ.");
                        if (!saveAs && (name.Text != "" || first.Text != model["Workbench.Recipe.DefaultPipeline"] || !model.MainRecipeStartEmpty)) throw new InvalidOperationException("New recipe defaults differ.");
                        if (saveAs && !name.Text.StartsWith(global.Recipe.Name + "_", StringComparison.Ordinal)) throw new InvalidOperationException("SaveAs name default differs.");
                        ScreenshotPngWriter.WriteElementPng(window, Path.ChangeExtension(outputPath, $".{palette}-{locale}-{saveAs}-normal.png"), width, height);
                        name.SetCurrentValue(TextBox.TextProperty, new string(locale == OpenVisionLanguage.Korean ? '가' : 'N', 60)); Pump(2);
                        memo.SetCurrentValue(TextBox.TextProperty, new string(locale == OpenVisionLanguage.Korean ? '설' : 'D', 120)); Pump(2);
                        if (model.MainRecipeName != name.Text || model.MainRecipeDescription != memo.Text) throw new InvalidOperationException("Main recipe control-to-working-form binding differs.");
                        model.MainRecipeDescription = locale == OpenVisionLanguage.Korean ? "저장 확인 설명" : "Save verification description"; Pump(2);
                        if (memo.Text != model.MainRecipeDescription) throw new InvalidOperationException("Main recipe form-to-control binding differs.");
                        if (!saveAs)
                        {
                            RadioButton copy = FindNamedVisualChild<RadioButton>(window, "mainRecipeCopyOption")!;
                            var radioPeer = System.Windows.Automation.Peers.UIElementAutomationPeer.CreatePeerForElement(copy)!;
                            ((System.Windows.Automation.Provider.ISelectionItemProvider)radioPeer.GetPattern(System.Windows.Automation.Peers.PatternInterface.SelectionItem)).Select(); Pump(3);
                            if (!model.MainRecipeCopyCurrent || model.MainRecipeStartEmpty) throw new InvalidOperationException("Main recipe copy option binding differs.");
                            model.MainRecipeStartEmpty = true; Pump(3);
                            if (copy.IsChecked == true) throw new InvalidOperationException("Main recipe empty option restoration differs.");
                        }
                        name.SetCurrentValue(TextBox.TextProperty, "bad/name"); Pump(2); model.SubmitMainRecipeCommand.Execute(null); WaitForTaskWithPump(model.MainRecipeSubmission, 2000, "Main recipe invalid name"); Pump(3);
                        TextBlock error = FindNamedVisualChild<TextBlock>(window, "mainRecipeErrorText")!;
                        if (!overlay.IsVisible || error.Text != model["Workbench.Recipe.NameInvalid"] || !error.IsVisible
                            || error.Foreground is not SolidColorBrush errorBrush || errorBrush.Color != ((SolidColorBrush)error.FindResource("OpenVision.Workbench.NgBrush")).Color) throw new InvalidOperationException("Main recipe validation did not retain the form/localized error.");
                        ScreenshotPngWriter.WriteElementPng(window, Path.ChangeExtension(outputPath, $".{palette}-{locale}-{saveAs}-error.png"), width, height);
                        name.SetCurrentValue(TextBox.TextProperty, ""); model.SubmitMainRecipeCommand.Execute(null); WaitForTaskWithPump(model.MainRecipeSubmission, 2000, "Main recipe empty name"); Pump(2);
                        if (model.MainRecipeError != model["Workbench.Recipe.NameRequired"]) throw new InvalidOperationException("Required recipe name error differs.");
                        name.SetCurrentValue(TextBox.TextProperty, global.Recipe.Name); model.SubmitMainRecipeCommand.Execute(null); WaitForTaskWithPump(model.MainRecipeSubmission, 2000, "Main recipe duplicate name"); Pump(2);
                        if (model.MainRecipeError != model["Workbench.Recipe.NameExists"]) throw new InvalidOperationException("Duplicate recipe error differs.");
                        var run = new KeyEventArgs(Keyboard.PrimaryDevice, PresentationSource.FromVisual(window)!, 0, Key.F5) { RoutedEvent = Keyboard.PreviewKeyDownEvent }; window.RaiseEvent(run);
                        if (!run.Handled || host.NativePreviewRunCount != runs) throw new InvalidOperationException("Main recipe modal leaked run shortcut.");
                        var escape = new KeyEventArgs(Keyboard.PrimaryDevice, PresentationSource.FromVisual(window)!, 0, Key.Escape) { RoutedEvent = Keyboard.PreviewKeyDownEvent }; window.RaiseEvent(escape); Pump(5);
                        if (!escape.Handled || overlay.IsVisible || !host.IsEnabled) throw new InvalidOperationException("Main recipe Escape did not restore Main.");
                        entry.Command.Execute(null); Pump(4); FindNamedVisualChild<Button>(window, "mainRecipeCancel")!.Command.Execute(null); Pump(3);
                        if (model.IsMainRecipeOpen || model.IsMainRecipeBusy) throw new InvalidOperationException("Main recipe reopen/cancel differs.");
                        cases++;
                    }
                    string originalRecipeName = global.Recipe.Name;
                    try
                    {
                        foreach (string sourceName in new[] { new string('N', 60), new string('가', 60), new string('N', 54) + "😀" + "NNNN", new string('N', 56) + "😀" + "NN" })
                        {
                            global.Recipe.Name = sourceName;
                            model.OpenMainSaveAsCommand.Execute(null); Pump(3);
                            string proposed = model.MainRecipeName, suffix = "_" + model["Workbench.Recipe.CopySuffix"];
                            if (proposed.Length > 60 || !proposed.EndsWith(suffix, StringComparison.Ordinal) || proposed.Any(character => char.IsSurrogate(character)) && !proposed.Contains("😀", StringComparison.Ordinal))
                                throw new InvalidOperationException("SaveAs long-name proposal exceeds limit, loses localized suffix, or splits a surrogate pair.");
                            model.CloseMainRecipeCommand.Execute(null); Pump(2);
                        }
                    }
                    finally { global.Recipe.Name = originalRecipeName; }
                    if (prefs != JsonSerializer.Serialize(global.System.WorkbenchLayoutPreferences)) throw new InvalidOperationException("Main recipe dialog changed layout preferences.");
                }
            }
            if (!saved.SequenceEqual(File.ReadAllBytes(savedPath)) || host.NativePreviewRunCount != runs) throw new InvalidOperationException("Main recipe invalid/cancel wrote original or ran inspection.");
            if (!window.InputBindings.OfType<KeyBinding>().Any(key => key.Key == Key.N && key.Modifiers == ModifierKeys.Control && ReferenceEquals(key.Command, model.OpenMainNewRecipeCommand))
                || !window.InputBindings.OfType<KeyBinding>().Any(key => key.Key == Key.S && key.Modifiers == (ModifierKeys.Control | ModifierKeys.Shift) && ReferenceEquals(key.Command, model.OpenMainSaveAsCommand)))
                throw new InvalidOperationException("Main recipe key entry differs.");
            File.WriteAllText(Path.ChangeExtension(outputPath, ".json"), JsonSerializer.Serialize(new { Scope = "Inprocess WPF AutomationPeer/synthetic keys; no actual pointer/nativeDPI", DisplayCases = cases, NoRun = true, InvalidCancelOriginalUnchanged = true, TwoWayFormBindings = true, StrictDuplicate = true }, new JsonSerializerOptions { WriteIndented = true }));
        });
    }

    private static CaptureResult CaptureMainHelpConnections(string outputPath, int width, int height)
    {
        GlobalState global = new(); global.Recipe.Name = "Smoke_MainHelp_" + Guid.NewGuid().ToString("N");
        VisionPipeline source = new() { Name = "Pipeline" };
        source.Steps.Add(new VisionPipelineStep { Name = "Help invariant", ToolType = "Mean", InputLayer = "Main", OutputLayer = "Help_Output" });
        VisionPipelineStorage.Save(global.Recipe.Name, source); VisionPipelineStorage.SaveActivePipelineName(global.Recipe.Name, source.Name);
        string savedPath = RecipeWorkspaceService.GetVisionPipelinePath(global.Recipe.Name, source.Name);
        byte[] saved = File.ReadAllBytes(savedPath); global.System.SaveWorkbenchLayout(new SystemStateConfig());
        OpenVisionShellHostWindow window = new(new ApplicationRuntimeContext(global, new DisplayManagerService()));
        window.ClearValue(OpenVisionShellHostWindow.ClosingCommandProperty);
        OpenVisionShellHostView host = window.ShellHostForSmoke;
        return CaptureStandaloneWindow(window, outputPath, width, height, () =>
        {
            OpenVisionWorkbenchViewModel model = host.Workbench;
            Menu menu = FindVisualChildren<Menu>(window).Single(item => AutomationProperties.GetAutomationId(item) == "WorkbenchMainMenu");
            MenuItem help = (MenuItem)menu.Items[5];
            MenuItem shortcuts = help.Items.OfType<MenuItem>().Single(item => item.Header?.ToString() == model["Workbench.Menu.Shortcuts"]);
            MenuItem about = help.Items.OfType<MenuItem>().Single(item => item.Header?.ToString() == model["Workbench.Menu.About"]);
            int runs = host.NativePreviewRunCount, layers = host.LayerDocumentCount;
            byte[] working = VisionPipelineExecutionPlan.SerializePipeline(model.Pipeline.WorkingCopyForTest);
            if (shortcuts.Command?.CanExecute(shortcuts.CommandParameter) != true || about.Command?.CanExecute(about.CommandParameter) != true)
                throw new InvalidOperationException("Main shortcuts/About entry remains unavailable.");
            void InvokeMenu(MenuItem item)
            {
                help.IsSubmenuOpen = true; Pump(3);
                var peer = System.Windows.Automation.Peers.UIElementAutomationPeer.CreatePeerForElement(item)!;
                ((System.Windows.Automation.Provider.IInvokeProvider)peer.GetPattern(System.Windows.Automation.Peers.PatternInterface.Invoke)).Invoke(); Pump(5);
            }
            string[] keys = { "F5", "Ctrl+F5", "F8", "F6", "Shift+F5", "Ctrl+S", "Ctrl+Shift+S", "Ctrl+O", "Ctrl+N", "Ctrl+I", "Ctrl+A", "Ctrl+Enter", "PgUp / PgDn", "1 · 2 · 4", "F2", "Ctrl+D", "Ctrl+E", "Del", "Alt+↑ / ↓", "Ctrl+Z / Ctrl+Y", "Esc", "Ctrl+1 / 2 / 3", "F1", "Ctrl+/" };
            foreach (string palette in new[] { "Dark", "Light" })
            {
                (palette == "Dark" ? model.SelectDarkThemeCommand : model.SelectLightThemeCommand).Execute(null); Pump(4);
                foreach (OpenVisionLanguage locale in new[] { OpenVisionLanguage.Korean, OpenVisionLanguage.English })
                {
                    OpenVisionLanguageService.SetLanguage(locale); Pump(3);
                    string preferences = JsonSerializer.Serialize(global.System.WorkbenchLayoutPreferences);
                    for (int closePath = 0; closePath < 4; closePath++)
                    {
                        InvokeMenu(shortcuts);
                        Grid overlay = FindNamedVisualChild<Grid>(window, "mainShortcutsOverlay")!;
                        Border frame = FindNamedVisualChild<Border>(window, "mainShortcutsFrame")!;
                        ItemsControl rows = FindNamedVisualChild<ItemsControl>(window, "mainShortcutsRows")!;
                        File.WriteAllText(Path.ChangeExtension(outputPath, ".structure.json"), JsonSerializer.Serialize(new { OverlayVisible = overlay?.IsVisible, FrameWidth = frame?.ActualWidth, FrameHeight = frame?.ActualHeight, Rows = rows?.Items.Count, HostEnabled = host.IsEnabled, ShortcutsEnabled = shortcuts.IsEnabled, ModelOpen = model.GetType().GetProperty("IsShortcutsOpen")?.GetValue(model), TitlebarEnabled = ((FrameworkElement)window.FindName("shellTitleBar")).IsEnabled, MenuEnabled = menu.IsEnabled, HelpHeaderEnabled = help.IsEnabled, ShortcutCanExecute = shortcuts.Command.CanExecute(shortcuts.CommandParameter), TitlebarDataContext = ((FrameworkElement)window.FindName("shellTitleBar")).DataContext?.GetType().FullName }, new JsonSerializerOptions { WriteIndented = true }));
                        ScreenshotPngWriter.WriteElementPng(window, Path.ChangeExtension(outputPath, ".structure.png"), width, height);
                        if (overlay?.IsVisible != true || frame == null || rows.Items.Count != 24 || frame.ActualWidth != 560D
                            || frame.ActualHeight > height - 60D || host.IsEnabled || ((FrameworkElement)window.FindName("shellTitleBar")).IsEnabled || shortcuts.Command.CanExecute(shortcuts.CommandParameter))
                            throw new InvalidOperationException("Main shortcut overlay structure/bounds/modal isolation differ.");
                        var items = rows.Items.Cast<KeyValuePair<string, string>>().ToArray();
                        if (!items.Select(row => row.Key).SequenceEqual(keys) || items.Any(row => string.IsNullOrWhiteSpace(row.Value)
                            || (locale == OpenVisionLanguage.English && Regex.IsMatch(row.Value, "[가-힣]"))))
                            throw new InvalidOperationException("Main 24 shortcut keys/localized captions differ.");
                        TextBlock title = FindNamedVisualChild<TextBlock>(window, "mainShortcutsTitle")!;
                        if (title.Text != (locale == OpenVisionLanguage.Korean ? "단축키" : "Keyboard shortcuts")) throw new InvalidOperationException("Main shortcut title locale differs.");
                        var blocked = new KeyEventArgs(Keyboard.PrimaryDevice, PresentationSource.FromVisual(window)!, 0, Key.F5) { RoutedEvent = Keyboard.PreviewKeyDownEvent };
                        window.RaiseEvent(blocked);
                        if (!blocked.Handled || host.NativePreviewRunCount != runs) throw new InvalidOperationException("Main execution key was not blocked by shortcut overlay.");
                        ScrollViewer scroll = FindNamedVisualChild<ScrollViewer>(window, "mainShortcutsScroll")!;
                        if (closePath == 0)
                        {
                            ScreenshotPngWriter.WriteElementPng(window, Path.ChangeExtension(outputPath, $".{palette}-{locale}-top.png"), width, height);
                            scroll.ScrollToBottom(); Pump(3);
                            ScreenshotPngWriter.WriteElementPng(window, Path.ChangeExtension(outputPath, $".{palette}-{locale}-bottom.png"), width, height);
                        }
                        Button close = FindNamedVisualChild<Button>(window, closePath == 0 ? "mainShortcutsClose" : closePath == 1 ? "mainShortcutsHeaderClose" : "mainShortcutsScrim")!;
                        if (closePath == 3)
                        {
                            var escape = new KeyEventArgs(Keyboard.PrimaryDevice, PresentationSource.FromVisual(window)!, 0, Key.Escape) { RoutedEvent = Keyboard.PreviewKeyDownEvent };
                            window.RaiseEvent(escape); if (!escape.Handled) throw new InvalidOperationException("Main shortcut Escape unhandled.");
                        }
                        else { close.Command.Execute(close.CommandParameter); }
                        Pump(5);
                        if (overlay.IsVisible || !host.IsEnabled) throw new InvalidOperationException("Main shortcut close did not restore Main input.");
                    }
                    InvokeMenu(about);
                    Border toast = FindNamedVisualChild<Border>(window, "mainProductInfoToast")!;
                    TextBlock text = FindNamedVisualChild<TextBlock>(window, "mainProductInfoText")!;
                    string version = typeof(OpenVisionWorkbenchViewModel).Assembly.GetCustomAttribute<AssemblyInformationalVersionAttribute>()!.InformationalVersion.Split('+')[0];
                    File.WriteAllText(Path.ChangeExtension(outputPath, ".toast.json"), JsonSerializer.Serialize(new { Visible = toast?.IsVisible, Width = toast?.ActualWidth, Text = text?.Text, Version = version }, new JsonSerializerOptions { WriteIndented = true }));
                    if (toast?.IsVisible != true || !text.Text.Contains(version, StringComparison.Ordinal)
                        || toast.ActualWidth < 260D || toast.ActualWidth > 420D)
                        throw new InvalidOperationException("Main product info toast version/structure differs.");
                    var entryAnimation = (System.Windows.Media.Animation.Storyboard)typeof(OpenVisionShellHostWindow).GetField("productInfoAnimation", BindingFlags.NonPublic | BindingFlags.Instance)!.GetValue(window)!;
                    entryAnimation.SeekAlignedToLastTick(toast, TimeSpan.FromSeconds(0.2D), System.Windows.Media.Animation.TimeSeekOrigin.BeginTime); Pump(3);
                    ScreenshotPngWriter.WriteElementPng(window, Path.ChangeExtension(outputPath, $".{palette}-{locale}-about.png"), width, height);
                    InvokeMenu(about);
                    var animation = (System.Windows.Media.Animation.Storyboard)typeof(OpenVisionShellHostWindow).GetField("productInfoAnimation", BindingFlags.NonPublic | BindingFlags.Instance)!.GetValue(window)!;
                    animation.SeekAlignedToLastTick(toast, TimeSpan.FromSeconds(3.2D), System.Windows.Media.Animation.TimeSeekOrigin.BeginTime); Pump(3);
                    if (toast.Visibility != Visibility.Collapsed) throw new InvalidOperationException("Main product info toast did not dismiss.");
                    if (preferences != JsonSerializer.Serialize(global.System.WorkbenchLayoutPreferences)) throw new InvalidOperationException("Main help changed layout preferences.");
                }
            }
            if (host.NativePreviewRunCount != runs || host.LayerDocumentCount != layers || !saved.SequenceEqual(File.ReadAllBytes(savedPath))
                || !working.SequenceEqual(VisionPipelineExecutionPlan.SerializePipeline(model.Pipeline.WorkingCopyForTest)))
                throw new InvalidOperationException("Main help changed execution, layers, recipe or working copy.");
            if (!window.InputBindings.OfType<KeyBinding>().Any(key => key.Key == Key.OemQuestion && key.Modifiers == ModifierKeys.Control && ReferenceEquals(key.Command, shortcuts.Command)))
                throw new InvalidOperationException("Main Ctrl+/ shortcut entry missing.");
            File.WriteAllText(Path.ChangeExtension(outputPath, ".json"), JsonSerializer.Serialize(new { Scope = "Inprocess WPF AutomationPeer/synthetic key; no actual pointer/nativeDPI", Rows = 24, OverlayCases = 16, ToastCases = 4, LayoutPreferencesUnchanged = true, NoRun = true, SavedXmlUnchanged = true, WorkingCopyUnchanged = true }, new JsonSerializerOptions { WriteIndented = true }));
        });
    }

    private static CaptureResult CaptureMainLayerManager(string outputPath)
