            var model=host.Workbench;var commands=host.LayerCommands;model.Tool.ConfigureAutoRunPreference(()=>false,_=>{});Place(window);
            string inputPath=Path.ChangeExtension(outputPath,".main-input.png");using(Bitmap input=new(17,11)){using Graphics g=Graphics.FromImage(input);g.Clear(System.Drawing.Color.FromArgb(42,42,42));input.Save(inputPath,ImageFormat.Png);}
