            int count=display.LayerCount,runs=host.NativePreviewRunCount;string selected=display.SelectedItem,focus=display.FocusItem;var inputItem=model.Images.CurrentImage;var result=inputItem.Result;var inputBitmap=display.ImageSpace.GetImage("Main");var inputBBitmap=display.ImageSpace.GetImage("InputB");var inputPreview=model.Shell.WorkspaceInputPreview;
            byte[] working=VisionPipelineExecutionPlan.SerializePipeline(model.Pipeline.CopyWorkingPipeline());
            void BusinessRetained(string state){Require(runs==host.NativePreviewRunCount && ReferenceEquals(inputItem,model.Images.CurrentImage) && ReferenceEquals(result,inputItem.Result) && ReferenceEquals(inputBitmap,display.ImageSpace.GetImage("Main")) && ReferenceEquals(inputBBitmap,display.ImageSpace.GetImage("InputB")) && ReferenceEquals(inputPreview,model.Shell.WorkspaceInputPreview) && working.SequenceEqual(VisionPipelineExecutionPlan.SerializePipeline(model.Pipeline.CopyWorkingPipeline())) && saved.SequenceEqual(File.ReadAllBytes(savedPath)),state+" preserves A/B input images/result/working/routes/saved XML/run");}
            void ReadonlyRetained(string state){BusinessRetained(state);Require(count==display.LayerCount && selected==display.SelectedItem && focus==display.FocusItem,state+" preserves layers/display");}
            OpenVisionLanguageService.SetLanguage(OpenVisionLanguage.English,false);Pump(3);
            Menu menu=FindVisualChildren<Menu>(window).Single(item=>AutomationProperties.GetAutomationId(item)=="WorkbenchMainMenu");MenuItem parent=menu.Items.OfType<MenuItem>().Single(item=>item.Items.OfType<MenuItem>().Any(child=>ReferenceEquals(child.Command,model.OpenLayerManagerCommand)));MenuItem entry=parent.Items.OfType<MenuItem>().Single(item=>ReferenceEquals(item.Command,model.OpenLayerManagerCommand));parent.IsSubmenuOpen=true;Pump(2);
            ((System.Windows.Automation.Provider.IInvokeProvider)System.Windows.Automation.Peers.UIElementAutomationPeer.CreatePeerForElement(entry)!.GetPattern(System.Windows.Automation.Peers.PatternInterface.Invoke)).Invoke();Pump(3);
            Require(model.IsLayerManagerOpen && !FindNamedVisualChild<MenuItem>(host,"workbenchLayerMenu")!.IsSubmenuOpen,"actual entry opens standalone table purpose without embedded menu");
            ListBox rows=(ListBox)window.FindName("managedLayerRows");Require(ReferenceEquals(rows.ItemsSource,commands.ManagerRows),"shared readonly rows binding");rows.SelectedValue="InputB";Pump(3);Require(commands.ManagerSelectedTitle=="InputB","browse binding writes manager selection only");ReadonlyRetained("open/browse");
            var projected=commands.ManagerRows.Cast<OpenVisionShellHostLayerTabItem>().Single(row=>row.Title=="InputB");Require(projected.SizeText=="17×11" && projected.OriginText=="Not recorded","real size and unknown provenance");
            window.Width=1600;window.Height=900;Place(window);Capture("english-wide");model.CloseLayerManagerCommand.Execute(null);Pump(3);ReadonlyRetained("manager close");
            OpenVisionLanguageService.SetLanguage(OpenVisionLanguage.Korean,false);window.Width=1280;window.Height=760;Place(window);model.OpenLayerManagerCommand.Execute(null);rows.SelectedValue="Main";Pump(3);
            Require(!commands.DeleteManagerLayerCommand.CanExecute(null) && !commands.RenameManagerLayerCommand.CanExecute(null),"Main protection in commands");commands.DeleteManagerLayerCommand.Execute(null);commands.ManagerRenameTitle="WrongMain";commands.RenameManagerLayerCommand.Execute(null);ReadonlyRetained("Main direct execute");
            rows.SelectedValue="InputB";Pump(3);Require(!commands.DeleteManagerLayerCommand.CanExecute(null) && !commands.RenameManagerLayerCommand.CanExecute(null),"actual required B protection");commands.DeleteManagerLayerCommand.Execute(null);commands.ManagerRenameTitle="WrongB";commands.RenameManagerLayerCommand.Execute(null);Require(!host.DeleteLayerForTest("InputB") && !host.RenameLayerForTest("InputB","WrongB"),"shared controller execute cannot bypass B guard");ReadonlyRetained("B direct execute");
