            ((TextBox)window.FindName("managedLayerRename")).SetCurrentValue(TextBox.TextProperty,"Renamed operator layer with a deliberately long name");Pump(2);string renamed=commands.ManagerRenameTitle;commands.RenameManagerLayerCommand.Execute(null);Pump(3);Require(display.FindIndex(renamed)>=0 && display.FindIndex(loose)<0 && commands.ManagerSelectedTitle==renamed,"valid rename/browse recovery");BusinessRetained("rename");
            selected=display.SelectedItem;focus=display.FocusItem;count=display.LayerCount;Require(commands.AddManagerImageFromPath(null)==null,"cancel before image creation");ReadonlyRetained("add cancel");
            string bad=Path.ChangeExtension(outputPath,".bad-image.png");File.WriteAllText(bad,"not an image");Require(commands.AddManagerImageFromPath(bad)==null && commands.HasManagerError,"malformed image rejected before layer creation");ReadonlyRetained("add failure");Capture("invalid-image-ko");
            string good=Path.ChangeExtension(outputPath,".valid-image.png");using(Bitmap image=new(23,19)){using Graphics g=Graphics.FromImage(image);g.Clear(System.Drawing.Color.CornflowerBlue);image.Save(good,ImageFormat.Png);}
            string added=commands.AddManagerImageFromPath(good);Pump(3);Require(!string.IsNullOrWhiteSpace(added) && display.LayerCount==count+1 && display.ImageSpace.GetImage(added).Width==23 && display.ImageSpace.GetImage(added).Height==19 && display.ImageSpace.GetImage(added).GetPixel(1,1).ToArgb()==System.Drawing.Color.CornflowerBlue.ToArgb(),"valid retry creates one real image layer");BusinessRetained("add");Capture("added-ko");
            var raw=display.ImageSpace.GetImage(added);commands.DeleteManagerLayerCommand.Execute(null);Pump(3);Require(display.FindIndex(added)<0 && display.LayerCount==count,"explicit delete removes selected added layer");BusinessRetained("delete");
            bool released=false;try{_=raw.Width;}catch(Exception ex)when(ex is ArgumentException or ObjectDisposedException or System.Runtime.InteropServices.ExternalException){released=true;}Require(released,"deleted image lifetime released after metadata leases");
            count=display.LayerCount;selected=display.SelectedItem;focus=display.FocusItem;model.CloseLayerManagerCommand.Execute(null);Pump(3);ReadonlyRetained("final close");model.OpenLayerManagerCommand.Execute(null);Pump(3);Require(model.IsLayerManagerOpen,"reopen current collection");model.CloseLayerManagerCommand.Execute(null);ReadonlyRetained("reopen/close");
            File.WriteAllText(Path.ChangeExtension(outputPath,".json"),JsonSerializer.Serialize(new{Scope="표시되는 in-process WPF source host; actual 제품 GUI/native125 미검증",Popup=true,BrowseViewerCloseReadonly=true,MainRequiredBProtected=true,UnusedBAllowed=true,CancelInvalidValidRetry=true,RenameDeleteExplicit=true,LeaseAndImageRelease=true,InputResultSynthetic=true,NoEngineRun=true},new JsonSerializerOptions{WriteIndented=true}));
