            void Place() => File.AppendAllText(Path.ChangeExtension(outputPath,".monitor.txt"), SmokeWindowMonitorPlacement.PlaceOnLeftmostMonitor(window) + Environment.NewLine);
            var model = host.Workbench; model.Tool.ConfigureAutoRunPreference(() => false, _ => { }); Place();
