            string valid=System.Text.Encoding.UTF8.GetString(VisionPipelineExecutionPlan.SerializePipeline(draft));
            Menu menu=FindVisualChildren<Menu>(window).Single(item=>AutomationProperties.GetAutomationId(item)=="WorkbenchMainMenu");
            MenuItem parent=menu.Items.OfType<MenuItem>().Single(item=>item.Items.OfType<MenuItem>().Any(child=>ReferenceEquals(child.Command,model.OpenMainLlmCommand)));
            MenuItem entry=parent.Items.OfType<MenuItem>().Single(item=>ReferenceEquals(item.Command,model.OpenMainLlmCommand)); parent.IsSubmenuOpen=true; Pump(3);
            ((System.Windows.Automation.Provider.IInvokeProvider)System.Windows.Automation.Peers.UIElementAutomationPeer.CreatePeerForElement(entry)!.GetPattern(System.Windows.Automation.Peers.PatternInterface.Invoke)).Invoke(); Pump(4);
            Require(model.IsMainLlmOpen && model.MainLlmStage==1 && !host.RecipeCommands.IsRecipeManagerDetailContextActive,"actual menu opens independent stage1");
            TextBox goal=(TextBox)window.FindName("mainLlmGoal"); goal.SetCurrentValue(TextBox.TextProperty,"Review brightness without running inspection. Keep the current work and results. " + new string('x',120)); Pump(2);
