            ((CheckBox)window.FindName("mainLlmIncludeImage")).SetCurrentValue(System.Windows.Controls.Primitives.ToggleButton.IsCheckedProperty,false); Pump(2); model.BuildMainLlmPromptCommand.Execute(null);
