            model.SelectMainLlmStageCommand.Execute("3"); window.Width=1600;window.Height=900;Place();Capture("review-en-wide");
            host.RecipeCommands.SelectedPipelineOption=host.RecipeCommands.PipelineOptions.Single(option=>option.PipelineName=="Other"); Pump(3);
            string[] names=RecipeWorkspaceService.GetVisionPipelineNames(global.Recipe.Name); model.SaveMainLlmCommand.Execute(null);
