            Require(host.RecipeCommands.SelectedStepEditObject is MeanProperty,"nonempty pending editor"); var editor=(MeanProperty)host.RecipeCommands.SelectedStepEditObject;editor.MEAN_MIN=13;host.RecipeCommands.MarkSelectedStepEditDirtyForQualificationTest();
            var working=VisionPipelineExecutionPlan.SerializePipeline(model.Pipeline.CopyWorkingPipeline());layers=host.LayerDocumentCount;route=host.ActiveHostLayerTitle; image=model.Images.CurrentImage;result=image.Result;
            string active=VisionPipelineStorage.LoadActivePipelineName(global.Recipe.Name,source.Name);
            void Retained(string state) { Require(host.NativePreviewRunCount==runs && host.LayerDocumentCount==layers && host.ActiveHostLayerTitle==route && ReferenceEquals(image,model.Images.CurrentImage) && ReferenceEquals(result,image.Result)
                && ReferenceEquals(editor,host.RecipeCommands.SelectedStepEditObject) && editor.MEAN_MIN==13 && host.RecipeCommands.IsSelectedStepEditDirty && model.Pipeline.IsDirty && active==VisionPipelineStorage.LoadActivePipelineName(global.Recipe.Name,source.Name)
                && working.SequenceEqual(VisionPipelineExecutionPlan.SerializePipeline(model.Pipeline.CopyWorkingPipeline())) && saved.SequenceEqual(File.ReadAllBytes(savedPath)) && !host.RecipeCommands.IsRecipeManagerDetailContextActive,state+" retains dirty editor/value/working/input/result/pointer/run/layer/route/saved source"); }
            Button footer=FindNamedVisualChild<Button>(host,"mainToolLlmAssistant")!;Require(ReferenceEquals(footer.Command,model.OpenMainLlmCommand) && footer.CommandParameter==null,"footer uses the same popup command");footer.BringIntoView();Pump(3);Invoke(footer);Pump(3);Retained("footer open");
