    private static CaptureResult CaptureMainHistoryEntry(string outputPath)
    {
        GlobalState global = new(); global.Recipe.Name = "Smoke_MainHistory_" + Guid.NewGuid().ToString("N");
        VisionPipeline source = new() { Name = "Pipeline" };
        source.Steps.Add(new VisionPipelineStep { Name = "Owned history step", ToolType = "Mean", InputLayer = "Main", OutputLayer = "History_Output" });
        VisionPipelineStorage.Save(global.Recipe.Name, source); VisionPipelineStorage.SaveActivePipelineName(global.Recipe.Name, source.Name);
        string savedPath = RecipeWorkspaceService.GetVisionPipelinePath(global.Recipe.Name, source.Name); byte[] saved = File.ReadAllBytes(savedPath);
        global.System.SaveWorkbenchLayout(new SystemStateConfig());
        OpenVisionShellHostWindow window = new(new ApplicationRuntimeContext(global, new DisplayManagerService()));
        window.ClearValue(OpenVisionShellHostWindow.ClosingCommandProperty);
        OpenVisionShellHostView host = window.ShellHostForSmoke;
        return CaptureStandaloneWindow(window, outputPath, 1280, 760, () =>
        {
            File.WriteAllText(Path.ChangeExtension(outputPath, ".monitor.txt"), SmokeWindowMonitorPlacement.PlaceOnLeftmostMonitor(window));
            void Require(bool ok, string message) { if (!ok) throw new InvalidOperationException("History: " + message); }
            OpenVisionLanguageService.SetLanguage(OpenVisionLanguage.English, false); Pump(4);
            OpenVisionWorkbenchViewModel model = host.Workbench;
            Menu menu = FindVisualChildren<Menu>(window).Single(item => AutomationProperties.GetAutomationId(item) == "WorkbenchMainMenu");
            MenuItem parent = (MenuItem)menu.Items[3];
            MenuItem history = parent.Items.OfType<MenuItem>().Single(item => item.Header?.ToString() == model["Workbench.Menu.RunHistory"]);
            Require(ReferenceEquals(history.Command, model.OpenMainHistoryCommand), "menu uses independent readonly command");
            int runs = host.NativePreviewRunCount, layers = host.LayerDocumentCount;
            object editor = host.RecipeCommands.SelectedStepEditObject; object image = model.Images.CurrentImage; object result = model.Tool.CurrentResult;
            byte[] working = VisionPipelineExecutionPlan.SerializePipeline(model.Pipeline.WorkingCopyForTest);
            string recipe = host.RecipeCommands.MainRecipeName, pipeline = host.RecipeCommands.SelectedPipelineOption.PipelineName;
            string root = RecipeWorkspaceService.GetContainedStoragePath(RecipeWorkspaceService.GetRecipeDirectoryPath(recipe), Path.Combine("VISION", "PipelineBatchRuns"), "Owned history fixture");
            void Retained()
            {
                Require(host.NativePreviewRunCount == runs && host.LayerDocumentCount == layers && ReferenceEquals(image, model.Images.CurrentImage) && ReferenceEquals(result, model.Tool.CurrentResult)
                    && ReferenceEquals(editor, host.RecipeCommands.SelectedStepEditObject) && recipe == host.RecipeCommands.MainRecipeName && pipeline == host.RecipeCommands.SelectedPipelineOption.PipelineName
                    && !host.RecipeCommands.IsRecipeManagerDetailContextActive && !model.IsMainRecipeOpen && !model.IsMainValidationOpen
                    && working.SequenceEqual(VisionPipelineExecutionPlan.SerializePipeline(model.Pipeline.WorkingCopyForTest)) && saved.SequenceEqual(File.ReadAllBytes(savedPath)), "readonly state/input/result/editor/route/working/saved retention");
            }
            model.OpenMainHistoryCommand.Execute(null); Pump(4);
            Require(model.IsMainHistoryOpen && model.HasNoMainHistory && !model.IsMainInteractive && !Directory.Exists(root), "empty lookup creates no storage directories");
            ScreenshotPngWriter.WriteElementPng(window, Path.ChangeExtension(outputPath, ".empty.png"), 1280, 760);
            model.CloseMainHistoryCommand.Execute(null); Retained();
            VisionPipelineBatchSampleRunResult Row(bool complete, bool actual, bool expected, double ms)
            {
                VisionPipelineBatchSampleRunResult row = new() { SampleName = Guid.NewGuid().ToString("N"), TotalMilliseconds = ms };
                VisionPipelineBatchOutcomeContract.Apply(row, complete, actual, true, expected, complete && actual == expected); return row;
            }
            var explicitRows = new[] { Row(true,true,true,10), Row(true,false,false,20), Row(true,true,false,30), Row(true,false,true,40), Row(false,false,true,0) };
            string explicitPath = VisionPipelineBatchRunSummaryStorage.Save(recipe, "Archived pipeline with a deliberately long historical name", new DateTime(2026,1,2,3,4,5), new DateTime(2026,1,2,3,4,6), explicitRows, pipelineSnapshot: source, inputSampleCount: 6);
            string legacyPath = VisionPipelineBatchRunSummaryStorage.Save(recipe, source.Name, new DateTime(2025,1,1), new DateTime(2025,1,1), new[] { new VisionPipelineBatchSampleRunResult { SampleName = "legacy", Success = true } });
            var legacySummary = VisionPipelineBatchRunSummaryStorage.Load(legacyPath); legacySummary.StartedAt = ""; SerializeHelper.SaveXmlFile(legacyPath, legacySummary);
            // 잘못된 Recipe identity를 가진 파일은 같은 폴더에서도 화면에 포함하지 않는다.
            string foreignPath = VisionPipelineBatchRunSummaryStorage.Save(recipe, source.Name, new DateTime(2024,1,1), new DateTime(2024,1,1), explicitRows);
            var foreign = VisionPipelineBatchRunSummaryStorage.Load(foreignPath); foreign.RecipeName = "AnotherRecipe"; SerializeHelper.SaveXmlFile(foreignPath, foreign);
            var files = Directory.GetFiles(root, "*", SearchOption.AllDirectories).ToDictionary(path => path, File.ReadAllBytes);
            model.OpenMainHistoryCommand.Execute(null); Pump(4);
            Require(model.MainHistoryRows.Count == 2 && model.MainHistoryRows.Single(row => row.SummaryPath == legacyPath).HistoryOk == "Not recorded" && FindVisualChildren<TextBlock>(window).Any(text => text.IsVisible && text.Text == model["Workbench.History.Title"]), "clean English title and legacy values");
            window.Width = 1600; window.Height = 900; File.AppendAllText(Path.ChangeExtension(outputPath, ".monitor.txt"), Environment.NewLine + SmokeWindowMonitorPlacement.PlaceOnLeftmostMonitor(window)); Pump(4);
            ScreenshotPngWriter.WriteElementPng(window, Path.ChangeExtension(outputPath, ".clean-en-wide.png"), 1600, 900);
            model.CloseMainHistoryCommand.Execute(null); Retained();
            OpenVisionLanguageService.SetLanguage(OpenVisionLanguage.Korean, false); window.Width = 1280; window.Height = 760; Pump(4);
            Require(host.RecipeCommands.FocusPipelineStepForEdit(global.Recipe.Name, source.Name, 1), "nonempty editor fixture");
            Require(model.Pipeline.InsertStep(1, new VisionPipelineStep { Name = "Pending history", ToolType = "Mean", InputLayer = "History_Output", OutputLayer = "Pending_Output" }) != null, "dirty working fixture");
            host.RecipeCommands.MarkSelectedStepEditDirtyForQualificationTest();
            editor = host.RecipeCommands.SelectedStepEditObject; working = VisionPipelineExecutionPlan.SerializePipeline(model.Pipeline.WorkingCopyForTest); layers = host.LayerDocumentCount;
            parent.IsSubmenuOpen = true; Pump(3);
            var peer = System.Windows.Automation.Peers.UIElementAutomationPeer.CreatePeerForElement(history)!;
            ((System.Windows.Automation.Provider.IInvokeProvider)peer.GetPattern(System.Windows.Automation.Peers.PatternInterface.Invoke)).Invoke(); Pump(8);
            Require(model.IsMainHistoryOpen && model.MainHistoryRows.Count == 2, "actual menu opens history across archived pipelines with recipe filter");
            var current = model.MainHistoryRows.Single(row => row.SummaryPath == explicitPath); var legacy = model.MainHistoryRows.Single(row => row.SummaryPath == legacyPath);
            Require(current.HistoryCount == 6 && current.HistoryOk == "2" && current.HistoryNg == "2" && current.HistoryError == "1" && current.HistoryMatch == "2/5" && current.HistoryFalseAccept == "1" && current.HistoryFalseReject == "1", "persisted explicit outcome and partial input count");
            Require(current.HistoryAverage.StartsWith("25") && current.HistoryP95.StartsWith("40") && current.HistoryCoverage.Contains("4/5"), "persisted timing excludes missing sample and records coverage");
            Require(current.HistorySource.Contains("미기록") && current.HistorySnapshot.Contains(current.RunSummary.ExecutionProvenance.OriginalPipelineSha256), "source uses past hash without live revision");
            Require(legacy.HistoryOk == "미기록" && legacy.HistoryError == "미기록" && legacy.HistoryAverage == "미기록" && legacy.HistoryStarted == "미기록", "legacy aggregate and absent timing/date stay unrecorded");
            ListBox list = (ListBox)window.FindName("mainHistoryRows"); Require(ReferenceEquals(list.ItemsSource, model.MainHistoryRows), "rendered rows use readonly binding");
            foreach (string theme in new[] { "Dark", "Light" })
            {
                (theme == "Dark" ? model.SelectDarkThemeCommand : model.SelectLightThemeCommand).Execute(null); Pump(4);
                list.SelectedIndex = 0; list.Focus(); Pump(3); Retained();
                ScreenshotPngWriter.WriteElementPng(window, Path.ChangeExtension(outputPath, "." + theme + ".png"), 1280, 760);
            }
            Button close = (Button)window.FindName("mainHistoryClose"); Require(ReferenceEquals(close.Command, model.CloseMainHistoryCommand), "close binding");
            ((System.Windows.Automation.Provider.IInvokeProvider)System.Windows.Automation.Peers.UIElementAutomationPeer.CreatePeerForElement(close)!.GetPattern(System.Windows.Automation.Peers.PatternInterface.Invoke)).Invoke(); Pump(4);
            Require(!model.IsMainHistoryOpen && model.IsMainInteractive && files.All(pair => pair.Value.SequenceEqual(File.ReadAllBytes(pair.Key))) && Directory.GetFiles(root,"*",SearchOption.AllDirectories).Length == files.Count, "close returns to unchanged Main and history files"); Retained();
            File.WriteAllText(Path.ChangeExtension(outputPath, ".wide-stage.txt"), "Wide resize starts; dirty live locale transition remains unverified after the separate timeout."); window.Width = 1600; window.Height = 900;
            File.AppendAllText(Path.ChangeExtension(outputPath, ".monitor.txt"), Environment.NewLine + SmokeWindowMonitorPlacement.PlaceOnLeftmostMonitor(window));
            model.OpenMainHistoryCommand.Execute(null); Pump(5); Require(model.MainHistoryRows[0].SummaryPath == explicitPath && model.MainHistoryRows[1].HistoryOk == "미기록", "saved date ordering and missing values");
            ScreenshotPngWriter.WriteElementPng(window, Path.ChangeExtension(outputPath, ".wide.png"), 1600, 900);
            model.CloseMainHistoryCommand.Execute(null); Retained(); File.AppendAllText(Path.ChangeExtension(outputPath, ".wide-stage.txt"), Environment.NewLine + "Wide assertions/capture/return completed.");
            File.WriteAllText(Path.ChangeExtension(outputPath, ".json"), JsonSerializer.Serialize(new { Scope = "표시된 in-process WPF source host; 실제 제품 EXE GUI/native125 미검증", IndependentReadonlyEntry = true, ArchivedPipeline = true, ExplicitOutcomes = true, LegacyUnrecorded = true, MissingTiming = true, NoWritesOrRuns = true, ReturnedToMain = true, Themes = new[] { "Dark", "Light" } }, new JsonSerializerOptions { WriteIndented = true }));
        });
    }

    private static CaptureResult CaptureMainMenuIcons(string outputPath, int width, int height)
    {
        GlobalState global = new(); global.Recipe.Name = "Smoke_MainMenuIcons";
        global.System.SaveWorkbenchLayout(new SystemStateConfig());
        OpenVisionShellHostWindow window = new(new ApplicationRuntimeContext(global, new DisplayManagerService()));
        window.ClearValue(OpenVisionShellHostWindow.ClosingCommandProperty);
        OpenVisionShellHostView host = window.ShellHostForSmoke;
        List<object> cases = new();
        void Require(bool value, string detail) { if (!value) throw new InvalidOperationException("Main menu icons: " + detail); }
        return CaptureStandaloneWindow(window, outputPath, width, height, () =>
        {
            OpenVisionWorkbenchViewModel model = host.Workbench;
            model.Pipeline.InsertStep(0, new VisionPipelineStep { Name = "Owned menu step", ToolType = "Mean", InputLayer = "Main", OutputLayer = "Main_Menu_Output" });
            Pump(4);
            Menu menu = FindVisualChildren<Menu>(window).Single(item => AutomationProperties.GetAutomationId(item) == "WorkbenchMainMenu");
            Dictionary<string, string> icons = new()
            {
                ["Workbench.Menu.NewRecipe"] = "Plus",
                ["Workbench.Menu.RecipeManager"] = "BookOpenPageVariantOutline",
                ["Workbench.Menu.SaveRecipe"] = "ContentSaveOutline",
                ["Workbench.Menu.SaveAs"] = "ContentSaveOutline",
                ["Workbench.Menu.OpenImage"] = "ImagePlusOutline",
                ["Workbench.Menu.OpenFolder"] = "FolderImage",
                ["Workbench.Images.AddSamples"] = "ImageMultipleOutline",
                ["Workbench.Menu.SaveImage"] = "FileExport",
                ["Workbench.Menu.ImportXml"] = "Import",
                ["Workbench.Menu.ExportXml"] = "Export",
                ["Workbench.Menu.Undo"] = "Undo",
                ["Workbench.Menu.Redo"] = "Redo",
                ["Workbench.Menu.RenameStep"] = "PencilOutline",
                ["Workbench.Menu.DuplicateStep"] = "ContentCopy",
                ["Workbench.Menu.ToggleStep"] = "EyeOff",
                ["Workbench.Menu.MoveUp"] = "ArrowUp",
                ["Workbench.Menu.MoveDown"] = "ArrowDown",
                ["Workbench.Menu.DeleteStep"] = "Delete",
                ["Workbench.Menu.ResetLayout"] = "Restore",
                ["Workbench.Command.RunPipelineCurrent"] = "Play",
                ["Workbench.Command.RunToStep"] = "DebugStepOver",
                ["Workbench.Command.RunStepOnly"] = "PlayOutline",
                ["Workbench.Command.BatchAll"] = "PlaylistPlay",
                ["Workbench.Command.BatchSelected"] = "PlaylistPlay",
                ["Workbench.Menu.Stop"] = "Stop",
                ["Workbench.Menu.RunHistory"] = "History",
                ["Workbench.ValidationSet.SaveTitle"] = "ClipboardCheckOutline",
                ["Workbench.ValidationSet.LoadTitle"] = "ClipboardCheckOutline",
                ["Workbench.Llm.Title"] = "RobotOutline",
                ["Workbench.Menu.LayerManager"] = "LayersOutline",
                ["Workbench.Menu.Compare"] = "SwapHorizontal",
                ["Workbench.Menu.Tcp"] = "Cog",
                ["Workbench.Menu.Guide"] = "BookOpenVariant",
                ["Workbench.Menu.Learn"] = "School",
                ["Workbench.Menu.Shortcuts"] = "KeyboardOutline",
                ["Workbench.Menu.About"] = "InformationOutline",
            };
            byte[] working = VisionPipelineExecutionPlan.SerializePipeline(model.Pipeline.WorkingCopyForTest);
            int runs = host.NativePreviewRunCount, layers = host.LayerDocumentCount;
            foreach (string theme in new[] { "Dark", "Light" })
            foreach (OpenVisionLanguage locale in new[] { OpenVisionLanguage.Korean, OpenVisionLanguage.English })
            {
                (theme == "Dark" ? model.SelectDarkThemeCommand : model.SelectLightThemeCommand).Execute(null);
                OpenVisionLanguageService.SetLanguage(locale, false); Pump(5);
                string route = host.DirectResultRouteText;
                string suffix = $"{width}-{theme}-{locale}";
                foreach (MenuItem parent in menu.Items)
                {
                    parent.IsSubmenuOpen = true; Pump(4);
                    Popup popup = FindNamedVisualChild<Popup>(parent, "PART_Popup")!;
                    FrameworkElement root = (FrameworkElement)popup.Child;
                    ScreenshotPngWriter.WriteElementPng(root, Path.Combine(Path.GetDirectoryName(outputPath)!, "before-menu-" + parent.Header + "-" + suffix + ".png"), (int)Math.Ceiling(root.ActualWidth), (int)Math.Ceiling(root.ActualHeight));
                    foreach (MenuItem item in parent.Items.OfType<MenuItem>())
                    {
                        ContentPresenter headerPresenter = FindNamedVisualChild<ContentPresenter>(item, "menuHeader")!;
                        AccessText expectedHeader = new AccessText { Text = item.Header?.ToString() ?? string.Empty, FontFamily = item.FontFamily, FontStyle = item.FontStyle, FontWeight = item.FontWeight, FontStretch = item.FontStretch, FontSize = item.FontSize, UseLayoutRounding = headerPresenter.UseLayoutRounding, SnapsToDevicePixels = headerPresenter.SnapsToDevicePixels };
                        TextOptions.SetTextFormattingMode(expectedHeader, TextOptions.GetTextFormattingMode(headerPresenter));
                        expectedHeader.Measure(new Size(double.PositiveInfinity, double.PositiveInfinity));
                        Require(Math.Ceiling(headerPresenter.ActualWidth) >= Math.Ceiling(expectedHeader.DesiredSize.Width), "full menu caption width: " + item.Header + " actual=" + headerPresenter.ActualWidth + " required=" + expectedHeader.DesiredSize.Width);
                        if (item.Header?.ToString() == model["Workbench.Menu.Stop"]) Require(item.Header.ToString() == (OpenVisionLanguageService.CurrentLanguage == OpenVisionLanguage.English ? "Stop" : "중지"), "canonical short Stop caption");
                        if (item.Header?.ToString() == model["Workbench.Menu.RunHistory"]) Require(ReferenceEquals(item.Command, host.RecipeCommands.OpenMainRecipeWorkCommand) && item.CommandParameter?.ToString() == "Validation", "existing run history entry and parameter");
                        if (item.IsCheckable)
                        {
                            MahApps.Metro.IconPacks.PackIconMaterial check = FindNamedVisualChild<MahApps.Metro.IconPacks.PackIconMaterial>(item, "menuCheck")!;
                            Require(check.Kind.ToString() == "CheckCircle" && check.Width == 16D && check.Height == 16D, "canonical check circle dimensions");
                            Require(check.Visibility == (item.IsChecked ? Visibility.Visible : Visibility.Collapsed), "checked marker state");
                            if (item.IsChecked) Require(check.ActualWidth == 16D && check.ActualHeight == 16D && check.Foreground.ToString() == ((Brush)host.FindResource("OpenVision.Workbench.AccentBrush")).ToString(), "checked marker rendered dimensions and semantic brush");
                        }
                        else
                        {
                            string key = icons.Keys.Single(key => model[key] == item.Header?.ToString());
                            MahApps.Metro.IconPacks.PackIconMaterial icon = item.Icon as MahApps.Metro.IconPacks.PackIconMaterial;
                            string expectedIcon = key == "Workbench.Menu.ToggleStep" && model.Pipeline.SelectedRow?.IsEnabled == false ? "Eye" : icons[key];
                            Require(icon != null && icon.Kind.ToString() == expectedIcon && icon.IsVisible && icon.ActualWidth == 16D, "missing rendered " + expectedIcon);
                            Require(icon.Foreground.ToString() == ((Brush)host.FindResource("OpenVision.Workbench.SecondaryTextBrush")).ToString(), "menu icon semantic brush");
                        }
                        Require(item.Command != null && item.IsEnabled == item.Command.CanExecute(item.CommandParameter), "existing command CanExecute");
                        cases.Add(new { Theme = theme, Language = locale.ToString(), Width = width, Menu = parent.Header, Item = item.Header, item.IsCheckable, item.IsChecked, item.IsEnabled, Icon = (item.Icon as MahApps.Metro.IconPacks.PackIconMaterial)?.Kind.ToString(), Scope = "Inprocess WPF; no actual pointer/pressed/nativeDPI" });
                    }
                    AssertWorkbenchMenuPopup(parent);
                    ScreenshotPngWriter.WriteElementPng(root, Path.Combine(Path.GetDirectoryName(outputPath)!, "menu-" + parent.Header + "-" + suffix + ".png"), (int)Math.Ceiling(root.ActualWidth), (int)Math.Ceiling(root.ActualHeight));
                    parent.IsSubmenuOpen = false; Pump(2);
                }
                MenuItem edit = (MenuItem)menu.Items[1];
                MenuItem toggleStep = edit.Items.OfType<MenuItem>().Single(item => item.Header?.ToString() == model["Workbench.Menu.ToggleStep"]);
                model.Pipeline.ToggleEnabledCommand.Execute(null); Pump(3);
                Require(((MahApps.Metro.IconPacks.PackIconMaterial)toggleStep.Icon).Kind.ToString() == "Eye", "disabled step icon update");
                model.Pipeline.ToggleEnabledCommand.Execute(null); Pump(3);
                Require(((MahApps.Metro.IconPacks.PackIconMaterial)toggleStep.Icon).Kind.ToString() == "EyeOff", "enabled step icon restore");
                MenuItem view = (MenuItem)menu.Items[2];
                foreach ((string key, ICommand command, Func<bool> current) in new (string, ICommand, Func<bool>)[]
                {
                    ("Workbench.Menu.PipelinePanel", model.ToggleLeftPanelCommand, () => model.IsLeftExpanded),
                    ("Workbench.Menu.ToolPanel", model.ToggleRightPanelCommand, () => model.IsRightExpanded),
                    ("Workbench.Menu.BottomPanel", model.ToggleBottomPanelCommand, () => model.IsBottomExpanded),
                    ("Workbench.Menu.ToolPanelWide", model.ToggleToolPanelWideCommand, () => (bool)typeof(OpenVisionWorkbenchViewModel).GetProperty("IsToolPanelWide")!.GetValue(model)!)
                })
                {
                    MenuItem item = view.Items.OfType<MenuItem>().Single(item => item.Header?.ToString() == model[key]);
                    Require(item.IsCheckable && item.IsChecked == current() && ReferenceEquals(item.Command, command), "panel marker binding");
                    item.Command.Execute(null); Pump(3); Require(item.IsChecked == current(), "panel marker change");
                    item.Command.Execute(null); Pump(3); Require(item.IsChecked == current(), "panel marker restore");
                }
                Require(host.DirectResultRouteText == route && host.NativePreviewRunCount == runs && host.LayerDocumentCount == layers && working.SequenceEqual(VisionPipelineExecutionPlan.SerializePipeline(model.Pipeline.WorkingCopyForTest)), "menu display no run/working/layer/route side effect");
                ScreenshotPngWriter.WriteElementPng(window, Path.Combine(Path.GetDirectoryName(outputPath)!, "main-menu-" + suffix + ".png"), width, height);
            }
            File.WriteAllText(Path.ChangeExtension(outputPath, ".json"), JsonSerializer.Serialize(new { Cases = cases, WorkingCopyUnchanged = true, NativeRuns = runs, MissingRequiredCommandsStillOpen = true }, new JsonSerializerOptions { WriteIndented = true }));
        });
    }

    private static CaptureResult CaptureMainBottomHeader(string outputPath, int width, int height)
    {
        GlobalState global = new(); global.Recipe.Name = "Smoke_MainBottomHeader";
        global.System.SaveWorkbenchLayout(new SystemStateConfig());
        OpenVisionShellHostWindow window = new(new ApplicationRuntimeContext(global, new DisplayManagerService()));
        window.ClearValue(OpenVisionShellHostWindow.ClosingCommandProperty);
        OpenVisionShellHostView host = window.ShellHostForSmoke;
        List<object> cases = new();
        void Require(bool value, string detail) { if (!value) throw new InvalidOperationException("Main bottom header: " + detail); }
        return CaptureStandaloneWindow(window, outputPath, width, height, () =>
        {
            OpenVisionWorkbenchViewModel model = host.Workbench;
            TabControl tabs = (TabControl)host.FindName("workbenchBottomTabs");
            ToggleButton toggle = (ToggleButton)host.FindName("btnShellLogToggle");
            MahApps.Metro.IconPacks.PackIconMaterial chevron = (MahApps.Metro.IconPacks.PackIconMaterial)host.FindName("iconShellLogToggle");
            FrameworkElement panel = FindVisualChildren<FrameworkElement>(host).Single(item => AutomationProperties.GetAutomationId(item) == "WorkbenchBottomPanel");
            byte[] working = VisionPipelineExecutionPlan.SerializePipeline(model.Pipeline.WorkingCopyForTest);
            int runs = host.NativePreviewRunCount, layers = host.LayerDocumentCount;
            string route = host.DirectResultRouteText;
            OpenVisionLanguage startingLanguage = OpenVisionLanguageService.CurrentLanguage;
            foreach (string theme in new[] { "Dark", "Light" })
            foreach (OpenVisionLanguage locale in new[] { OpenVisionLanguage.Korean, OpenVisionLanguage.English })
            {
                (theme == "Dark" ? model.SelectDarkThemeCommand : model.SelectLightThemeCommand).Execute(null);
                OpenVisionLanguageService.SetLanguage(locale, false); model.IsBottomCollapsed = false; Pump(5);
                string suffix = $"{width}-{theme}-{locale}";
                ScreenshotPngWriter.WriteElementPng(window, Path.Combine(Path.GetDirectoryName(outputPath)!, "header-before-" + suffix + ".png"), width, height);
                for (int index = 0; index < 3; index++)
                {
                    tabs.SetCurrentValue(TabControl.SelectedIndexProperty, index); Pump(3);
                    Require(model.SelectedBottomTab == index, "control to model selection");
                    model.SelectedBottomTab = (index + 1) % 3; Pump(3);
                    Require(tabs.SelectedIndex == (index + 1) % 3, "model to control selection");
                    model.SelectedBottomTab = index; Pump(3);
                    TabItem tab = (TabItem)tabs.Items[index];
                    string expectedIcon = new[] { "ImageMultipleOutline", "TableLarge", "TextBoxOutline" }[index];
                    MahApps.Metro.IconPacks.PackIconMaterial icon = FindVisualChildren<MahApps.Metro.IconPacks.PackIconMaterial>(tab).FirstOrDefault(item => item.Kind.ToString() == expectedIcon)!;
                    Require(icon != null && icon.IsVisible && icon.ActualWidth == 16D && icon.ActualHeight == 16D, "missing rendered " + expectedIcon);
                    Require(icon.Foreground.ToString() == tab.Foreground.ToString(), "icon follows tab state foreground");
                    string caption = model[new[] { "Workbench.Bottom.Images", "Workbench.Bottom.Results", "Workbench.Bottom.Log" }[index]];
                    TextBlock text = FindVisualChildren<TextBlock>(tab).First(item => item.Text == caption);
                    AssertElementWithinAncestor("Main bottom tab caption", text, tab);
                    Require(text.Foreground.ToString() == ((Brush)host.FindResource("OpenVision.Workbench.TextBrush")).ToString() && text.FontWeight == FontWeights.SemiBold, "selected caption presentation");
                    if (index == 0) Require(FindVisualChildren<TextBlock>(tab).Any(item => item.Text == model.Images.Count.ToString(CultureInfo.CurrentCulture) && item.IsVisible), "zero image count visible");
                    Require(model.IsLogPanelVisible == (index == 2), "existing LogPanel tab routing");
                    Rect tabBounds = tab.TransformToAncestor(host).TransformBounds(new Rect(tab.RenderSize));
                    Rect toggleBounds = toggle.TransformToAncestor(host).TransformBounds(new Rect(toggle.RenderSize));
                    Require(tabBounds.Right <= toggleBounds.Left, "tab/toggle overlap");
                    for (int cycle = 0; cycle < 2; cycle++)
                    {
                        toggle.Command.Execute(null); Pump(4);
                        bool collapsed = cycle == 0;
                        Require(model.IsBottomCollapsed == collapsed && toggle.IsChecked == !collapsed, "toggle state binding");
                        Require(chevron.Kind.ToString() == (collapsed ? "ChevronUp" : "ChevronDown"), "collapse direction");
                        string expectedTitle = locale == OpenVisionLanguage.English ? (collapsed ? "Expand bottom panel (Ctrl+3)" : "Collapse bottom panel (Ctrl+3)") : (collapsed ? "하단 패널 펼치기 (Ctrl+3)" : "하단 패널 접기 (Ctrl+3)");
                        Require(toggle.ToolTip?.ToString() == expectedTitle && AutomationProperties.GetName(toggle) == expectedTitle, "localized state title");
                        Require(model.SelectedBottomTab == index, "collapse preserves selected tab");
                        AssertNear(panel.ActualHeight, collapsed ? 36D : height <= 820 ? 200D : 256D, "bottom height");
                        cases.Add(new { Theme = theme, Language = locale.ToString(), Width = width, Tab = index, Collapsed = collapsed, Icon = expectedIcon, Chevron = chevron.Kind.ToString(), Title = toggle.ToolTip, TabBounds = tabBounds.ToString(), ToggleBounds = toggleBounds.ToString(), Scope = "Inprocess WPF, command/binding; no actual pressed/nativeDPI" });
                    }
                }
                toggle.Focus(); Pump(3);
                Require(toggle.IsKeyboardFocused, "toggle keyboard focus");
                toggle.SetCurrentValue(UIElement.IsEnabledProperty, false); Pump(2);
                Require(chevron.IsVisible && toggle.Foreground.ToString() == ((Brush)host.FindResource("OpenVision.Workbench.MutedTextBrush")).ToString(), "disabled icon semantic state");
                toggle.ClearValue(UIElement.IsEnabledProperty); Pump(3);
                model.IsBottomCollapsed = true; Pump(3);
                ScreenshotPngWriter.WriteElementPng(window, Path.Combine(Path.GetDirectoryName(outputPath)!, "header-collapsed-" + suffix + ".png"), width, height);
                ExecuteWorkbenchKey(host, Key.D3, ModifierKeys.Control); Pump(4);
                Require(!model.IsBottomCollapsed && chevron.Kind.ToString() == "ChevronDown", "existing Ctrl3 restore");
                model.SelectedBottomTab = 0; Pump(4);
                ScreenshotPngWriter.WriteElementPng(window, Path.Combine(Path.GetDirectoryName(outputPath)!, "header-expanded-" + suffix + ".png"), width, height);
            }
            OpenVisionLanguageService.SetLanguage(startingLanguage, false); Pump(4);
            File.WriteAllText(Path.ChangeExtension(outputPath, ".invariant.json"), JsonSerializer.Serialize(new { RunsBefore = runs, RunsAfter = host.NativePreviewRunCount, LayersBefore = layers, LayersAfter = host.LayerDocumentCount, RouteBefore = route, RouteAfter = host.DirectResultRouteText, WorkingUnchanged = working.SequenceEqual(VisionPipelineExecutionPlan.SerializePipeline(model.Pipeline.WorkingCopyForTest)) }));
            Require(host.NativePreviewRunCount == runs && host.LayerDocumentCount == layers && host.DirectResultRouteText == route && working.SequenceEqual(VisionPipelineExecutionPlan.SerializePipeline(model.Pipeline.WorkingCopyForTest)), "presentation no inspection/working/source route side effect");
            string input = Path.ChangeExtension(outputPath, ".input.png");
            using (Bitmap image = new(32, 24)) { using Graphics graphics = Graphics.FromImage(image); graphics.Clear(DrawingColor.FromArgb(128, 128, 128)); image.Save(input, ImageFormat.Png); }
            Require(host.LoadMainImageFromFileForTest(input), "owned count input"); Pump(5);
            Require(model.Images.Count == 1 && FindVisualChildren<TextBlock>((TabItem)tabs.Items[0]).Any(item => item.Text == "1" && item.IsVisible), "live image count update");
            Require(host.NativePreviewRunCount == runs && working.SequenceEqual(VisionPipelineExecutionPlan.SerializePipeline(model.Pipeline.WorkingCopyForTest)), "count update no run/working change");
            ScreenshotPngWriter.WriteElementPng(window, Path.ChangeExtension(outputPath, ".loaded.png"), width, height);
            global.System.LoadConfig();
            using (OpenVisionWorkbenchViewModel restored = new(global.System.WorkbenchLayoutPreferences, _ => true))
                Require(!restored.IsBottomCollapsed && restored.SelectedBottomTab == 0, "existing preference round trip");
            File.WriteAllText(Path.ChangeExtension(outputPath, ".json"), JsonSerializer.Serialize(new { Cases = cases, NativeRuns = runs, WorkingCopyUnchanged = true, PreferenceRestore = true }, new JsonSerializerOptions { WriteIndented = true }));
        });
    }

    private static CaptureResult CaptureMainThemeConnections(string outputPath, int width, int height)
    {
        GlobalState global = new();
        global.Recipe.Name = "Smoke_MainThemeConnections";
        global.System.SaveWorkbenchLayout(new SystemStateConfig { WorkbenchAutoRunEnabled = false });
        OpenVisionShellHostWindow window = new(new ApplicationRuntimeContext(global, new DisplayManagerService()));
        OpenVisionShellHostView host = window.ShellHostForSmoke;
        List<object> cases = new();
        void Require(bool value, string detail) { if (!value) throw new InvalidOperationException("Main theme: " + detail); }
        bool IsRendered(TextBlock text)
        {
            if (!text.IsVisible || !text.IsEnabled || text.ActualWidth <= 0 || string.IsNullOrWhiteSpace(text.Text)) return false;
            for (DependencyObject? element = text; element != null; element = VisualTreeHelper.GetParent(element))
                if (element is UIElement visual && visual.Opacity == 0) return false;
            return true;
        }
        System.Windows.Media.Color Composite(System.Windows.Media.Color front, System.Windows.Media.Color back)
        {
            double alpha = front.A / 255D;
            return System.Windows.Media.Color.FromRgb((byte)Math.Round(front.R * alpha + back.R * (1 - alpha)), (byte)Math.Round(front.G * alpha + back.G * (1 - alpha)), (byte)Math.Round(front.B * alpha + back.B * (1 - alpha)));
        }
        SolidColorBrush? RenderedBackground(DependencyObject source)
        {
            List<System.Windows.Media.Color> layers = new();
            for (DependencyObject? current = source; current != null; current = VisualTreeHelper.GetParent(current))
            {
                Brush? brush = current is Border border ? border.Background : current is Panel panel ? panel.Background : current is TextBlock text ? text.Background : null;
                if (brush is not SolidColorBrush solid || solid.Color.A == 0) continue;
                layers.Add(solid.Color);
                if (solid.Color.A != 255) continue;
                System.Windows.Media.Color color = solid.Color;
                for (int index = layers.Count - 2; index >= 0; index--) color = Composite(layers[index], color);
                return new SolidColorBrush(color);
            }
            return null;
        }
        return CaptureStandaloneWindow(window, outputPath, width, height, () =>
        {
            OpenVisionWorkbenchViewModel model = host.Workbench;
            Menu menu = FindVisualChildren<Menu>(window).Single(item => AutomationProperties.GetAutomationId(item) == "WorkbenchMainMenu");
            MenuItem view = (MenuItem)menu.Items[2];
            view.IsSubmenuOpen = true; Pump(5);
            ScreenshotPngWriter.WriteElementPng(window, Path.ChangeExtension(outputPath, ".before.png"), width, height);
            FrameworkElement popupRoot = (FrameworkElement)FindNamedVisualChild<Popup>(view, "PART_Popup")!.Child;
            ScreenshotPngWriter.WriteElementPng(popupRoot, Path.ChangeExtension(outputPath, ".before-popup.png"), (int)Math.Ceiling(popupRoot.ActualWidth), (int)Math.Ceiling(popupRoot.ActualHeight));
            MenuItem dark = view.Items.OfType<MenuItem>().Single(item => item.Header?.ToString() == model["Workbench.Menu.Dark"]);
            MenuItem light = view.Items.OfType<MenuItem>().Single(item => item.Header?.ToString() == model["Workbench.Menu.Light"]);
            Require(light.Command.CanExecute(null) && dark.Command.CanExecute(null), "theme commands available");
            view.IsSubmenuOpen = false;
            string input = Path.ChangeExtension(outputPath, ".input.png");
            using (Bitmap image = new(32, 24)) { using Graphics graphics = Graphics.FromImage(image); graphics.Clear(DrawingColor.FromArgb(128, 128, 128)); image.Save(input, ImageFormat.Png); }
            byte[] working = VisionPipelineExecutionPlan.SerializePipeline(model.Pipeline.WorkingCopyForTest);
            int runs = host.NativePreviewRunCount;
            foreach (bool loaded in new[] { false, true })
            {
                if (loaded) Require(host.LoadMainImageFromFileForTest(input), "valid input");
                string panes = JsonSerializer.Serialize(model.Viewer.Panes.Select(pane => new { pane.Id, pane.Source, pane.Viewport }));
                foreach (OpenVisionLanguage locale in new[] { OpenVisionLanguage.Korean, OpenVisionLanguage.English })
                foreach (string theme in new[] { "Light", "Dark" })
                {
                    OpenVisionLanguageService.SetLanguage(locale, false); Pump(4);
                    MenuItem selected = theme == "Light" ? light : dark;
                    selected.Command.Execute(null); Pump(8);
                    view.IsSubmenuOpen = true; Pump(5);
                    Require(model.ThemeName == theme && light.IsChecked == model.IsLightTheme && dark.IsChecked == model.IsDarkTheme, "theme source/check");
                    selected.SetCurrentValue(MenuItem.IsCheckedProperty, false); selected.Command.Execute(null); Pump(4);
                    Require(selected.IsChecked, "repeat active checked");
                    ResourceDictionary palette = new() { Source = new Uri($"/OpenVisionLab;component/UI/Wpf/OpenVisionWorkbench{theme}.xaml", UriKind.Relative) };
                    string Expected(string key) => ((SolidColorBrush)palette["OpenVision.Workbench." + key]).Color.ToString();
                    OpenVisionWindowTitleBar title = FindVisualChildren<OpenVisionWindowTitleBar>(window).Single();
                    foreach (FrameworkElement root in new FrameworkElement[] { window, host, title }.Concat(FindVisualChildren<OpenVisionLayerViewerView>(host)))
                    {
                        Require(((SolidColorBrush)root.FindResource("OpenVision.Workbench.TextBrush")).Color.ToString() == Expected("TextBrush"), root.GetType().Name + " text palette");
                        Require(root.Resources.MergedDictionaries.Count(dictionary => dictionary.Source?.OriginalString.Contains("OpenVisionWorkbench", StringComparison.Ordinal) == true) == 1, root.GetType().Name + " one live palette");
                    }
                    Require(light.Foreground.ToString() == Expected("TextBrush") && dark.Foreground.ToString() == Expected("TextBrush"), "rendered menu foreground");
                    Border popupBorder = (Border)popupRoot;
                    Require(popupBorder.Background.ToString() == Expected("RaisedBrush"), "rendered popup background");
                    Require(FindNamedVisualChild<TextBlock>(title, "txtTitle")!.Foreground.ToString() == Expected("TextBrush"), "rendered title text");
                    MahApps.Metro.IconPacks.PackIconMaterial bottomIcon = FindNamedVisualChild<MahApps.Metro.IconPacks.PackIconMaterial>(host, "iconShellLogToggle")!;
                    SolidColorBrush bottomBackground = RenderedBackground(bottomIcon)!;
                    double bottomContrast = GetContrastRatio(Composite(((SolidColorBrush)bottomIcon.Foreground).Color, bottomBackground.Color), bottomBackground.Color);
                    Require(bottomContrast >= 3D, $"bottom selected icon contrast {bottomContrast:F2}; foreground={bottomIcon.Foreground}; background={bottomBackground}");
                    var captions = FindVisualChildren<TextBlock>(host).Where(text => IsRendered(text))
                        .Select(text => new { text.Name, text.Text, Foreground = text.Foreground.ToString(), Background = RenderedBackground(text)?.Color.ToString(), Contrast = text.Foreground is SolidColorBrush fg && RenderedBackground(text) is SolidColorBrush bg ? GetContrastRatio(Composite(fg.Color, bg.Color), bg.Color) : 0D }).ToArray();
                    File.WriteAllText(Path.Combine(Path.GetDirectoryName(outputPath)!, $"contrast-{width}-{theme}-{locale}-{loaded}.json"), JsonSerializer.Serialize(captions, new JsonSerializerOptions { WriteIndented = true }));
                    if (captions.Any(text => text.Contrast > 0 && text.Contrast < 3D))
                    {
                        var failed = FindVisualChildren<TextBlock>(host).Where(text => IsRendered(text) && text.Foreground is SolidColorBrush foreground && RenderedBackground(text) is SolidColorBrush background && GetContrastRatio(Composite(foreground.Color, background.Color), background.Color) < 3D).Select(text =>
                        {
                            List<object> parents = new();
                            for (DependencyObject? parent = text; parent != null && parent != host; parent = VisualTreeHelper.GetParent(parent))
                                if (parent is FrameworkElement element) parents.Add(new { Type = element.GetType().Name, element.Name, element.ActualWidth, element.ActualHeight, element.ClipToBounds, Clip = element.Clip?.ToString(), element.Opacity, Background = element is Border border ? border.Background?.ToString() : element is Panel panel ? panel.Background?.ToString() : element is Control control ? control.Background?.ToString() : null });
                            return new { text.Text, Bounds = text.TransformToAncestor(host).TransformBounds(new Rect(text.RenderSize)).ToString(), Parents = parents };
                        }).ToArray();
                        File.WriteAllText(Path.Combine(Path.GetDirectoryName(outputPath)!, $"failed-parents-{width}-{theme}-{locale}-{loaded}.json"), JsonSerializer.Serialize(failed, new JsonSerializerOptions { WriteIndented = true }));
                        view.IsSubmenuOpen = false; Pump(4);
                        ScreenshotPngWriter.WriteElementPng(window, Path.Combine(Path.GetDirectoryName(outputPath)!, $"failed-main-{width}-{theme}-{locale}-{loaded}.png"), width, height);
                    }
                    Require(!captions.Any(text => text.Contrast > 0 && text.Contrast < 3D), "visible Main caption contrast below3; inspect diagnostic");
                    AssertWorkbenchMenuPopup(view);
                    string suffix = $"{width}-{theme}-{locale}-{loaded}";
                    ScreenshotPngWriter.WriteElementPng(popupRoot, Path.Combine(Path.GetDirectoryName(outputPath)!, "menu-" + suffix + ".png"), (int)Math.Ceiling(popupRoot.ActualWidth), (int)Math.Ceiling(popupRoot.ActualHeight));
                    view.IsSubmenuOpen = false; Pump(4);
                    ScreenshotPngWriter.WriteElementPng(window, Path.Combine(Path.GetDirectoryName(outputPath)!, "main-" + suffix + ".png"), width, height);
                    Require(JsonSerializer.Serialize(model.Viewer.Panes.Select(pane => new { pane.Id, pane.Source, pane.Viewport })) == panes, "theme preserves source/viewport");
                    Require(host.NativePreviewRunCount == runs && working.SequenceEqual(VisionPipelineExecutionPlan.SerializePipeline(model.Pipeline.WorkingCopyForTest)), "theme no inspection or working-copy change");
                    cases.Add(new { Theme = theme, Language = locale.ToString(), Width = width, Height = height, Loaded = loaded, Selected = selected.IsChecked, NativeRuns = runs, Scope = "Inprocess WPF; command execution and synthetic repeat-check, not actual input/nativeDPI" });
                }
            }
            OpenVisionShellHostChromeController chrome = (OpenVisionShellHostChromeController)typeof(OpenVisionShellHostView).GetField("chromeController", BindingFlags.NonPublic | BindingFlags.Instance)!.GetValue(host)!;
            List<object> stateCases = new();
            foreach ((string state, Action apply, string badgeKey, string statusKey) in new (string, Action, string, string)[]
            {
                ("WorkspaceEmpty", chrome.SetWorkspaceEmptyStatus, "StaleBrush", "AccentBrush"),
                ("ImageReady", chrome.SetWorkspaceImageReadyStatus, "StaleBrush", "AccentBrush"),
                ("SampleReady", chrome.SetWorkspaceSampleReadyStatus, "OkBrush", "OkBrush"),
                ("Pending", chrome.SetDirectRunPending, "StaleBrush", "AccentBrush"),
                ("Succeeded", chrome.SetDirectRunSucceeded, "OkBrush", "OkBrush")
            })
            {
                model.SelectDarkThemeCommand.Execute(null); apply(); Pump(3);
                string statusValue = ((TextBlock)host.FindName("txtHostDirectStatus")).Text;
                foreach (ICommand command in new[] { model.SelectLightThemeCommand, model.SelectDarkThemeCommand })
                {
                    command.Execute(null); Pump(5);
                    TextBlock status = (TextBlock)host.FindName("txtHostDirectStatus"), badge = (TextBlock)host.FindName("txtHostDirectBadge");
                    string expectedStatus = ((Brush)host.FindResource("OpenVision.Workbench." + statusKey)).ToString();
                    Require(status.Foreground.ToString() == expectedStatus && status.Text == statusValue, state + " dynamic status brush/text");
                    Require(badge.Foreground.ToString() == ((Brush)host.FindResource("OpenVision.Workbench." + badgeKey)).ToString(), state + " dynamic badge brush");
                    double ratio = GetContrastRatio(((SolidColorBrush)status.Foreground).Color, RenderedBackground(status)!.Color);
                    Require(ratio >= 4.5D, state + " status text contrast");
                    string capture = Path.Combine(Path.GetDirectoryName(outputPath)!, $"status-{width}-{model.ThemeName}-{state}.png");
                    ScreenshotPngWriter.WriteElementPng(window, capture, width, height);
                    stateCases.Add(new { State = state, Theme = model.ThemeName, status.Text, Foreground = status.Foreground.ToString(), Contrast = ratio, Capture = capture, Scope = "Synthetic display state; Succeeded did not run inspection" });
                }
            }
            model.SelectLightThemeCommand.Execute(null); model.ResetLayoutCommand.Execute(null); Pump(4);
            Require(model.IsLightTheme, "layout reset preserves theme");
            Require(global.System.LoadConfig() && global.System.WorkbenchLayoutPreferences.WorkbenchThemeName == "Light", "SYSTEM reload theme");
            using (OpenVisionWorkbenchViewModel restored = new(global.System.WorkbenchLayoutPreferences, _ => true)) Require(restored.IsLightTheme, "new Main preference restore");
            using (OpenVisionWorkbenchViewModel legacy = new(new SystemStateConfig(), _ => true)) Require(legacy.IsDarkTheme, "old/default Dark restore");
            using (OpenVisionWorkbenchViewModel invalid = new(new SystemStateConfig { WorkbenchThemeName = "unsupported" }, _ => true)) Require(invalid.IsDarkTheme, "invalid preference fallback");
            model.SelectDarkThemeCommand.Execute(null); Pump(5);
            File.WriteAllText(Path.ChangeExtension(outputPath, ".json"), JsonSerializer.Serialize(new { Cases = cases, StateCases = stateCases, PreferenceReload = true, LayoutResetPreservesTheme = true, NativeRunsBefore = runs, NativeRunsAfter = host.NativePreviewRunCount, WorkingCopyUnchanged = working.SequenceEqual(VisionPipelineExecutionPlan.SerializePipeline(model.Pipeline.WorkingCopyForTest)) }, new JsonSerializerOptions { WriteIndented = true }));
        });
    }

    private static CaptureResult CaptureMainRunConnections(string outputPath, string theme, int width, int height)
    {
        GlobalState global = new(); global.Recipe.Name = "Smoke_MainRunConnections";
        global.System.SaveWorkbenchLayout(new SystemStateConfig());
        OpenVisionShellHostWindow window = new(new ApplicationRuntimeContext(global, new DisplayManagerService()));
        window.ClearValue(OpenVisionShellHostWindow.ClosingCommandProperty);
        OpenVisionShellHostView host = window.ShellHostForSmoke;
        (theme == "Light" ? host.Workbench.SelectLightThemeCommand : host.Workbench.SelectDarkThemeCommand).Execute(null);
        List<object> cases = new();
        void Require(bool condition, string detail) { if (!condition) throw new InvalidOperationException("Main run connection: " + detail); }
        return CaptureStandaloneWindow(window, outputPath, width, height, () =>
        {
            OpenVisionWorkbenchViewModel model = host.Workbench;
            model.Tool.ConfigureAutoRunPreference(() => false, _ => { });
            for (int i = 0; i < 2; i++)
            {
                VisionPipelineStep step = new() { Name = "Main row " + (i + 1), ToolType = "Mean", InputLayer = "Main", OutputLayer = "Row_Output_" + (i + 1) };
                step.Parameters["MEAN_TYPES"] = "Mean"; step.Parameters["MEAN_MIN"] = "0"; step.Parameters["MEAN_MAX"] = "255";
                step.Parameters["USE_THRESHOLD"] = "False"; step.Parameters["USE_ADAPTIVE_THRESHOLD"] = "False"; step.Parameters["USE_ROI"] = "False";
                step.Parameters["USE_BITWISENOT"] = i == 0 ? "False" : "True";
                Require(model.Pipeline.InsertStep(i, step) != null, "owned step setup");
            }
            Pump(8);
            Border[] rows = FindVisualChildren<Border>(host).Where(b => b.Name == "stepRow").OrderBy(b => ((OpenVisionWorkbenchStepViewModel)b.DataContext).Index).ToArray();
            Require(rows.Length == 2, "two rendered rows");
            ContextMenu menu = rows[0].ContextMenu!; menu.PlacementTarget = rows[0]; menu.IsOpen = true; Pump(6);
            MenuItem only = menu.Items.OfType<MenuItem>().First();
            KeyBinding? f6 = window.InputBindings.OfType<KeyBinding>().SingleOrDefault(k => k.Key == Key.F6 && k.Modifiers == ModifierKeys.None);
            bool rootConnected = f6 != null && ReferenceEquals(f6.Command, model.Images.RunBatchCommand) && (string?)f6.CommandParameter == "all";
            bool rowConnected = only.Command != null && only.Command.CanExecute(only.CommandParameter) && only.CommandParameter is int rowIndex && rowIndex == 0;
            File.WriteAllText(Path.ChangeExtension(outputPath, ".baseline.json"), JsonSerializer.Serialize(new { RootF6 = rootConnected, RowRunOnly = rowConnected, only.IsEnabled, Parameter = only.CommandParameter, Theme = theme, Width = width, Height = height }, new JsonSerializerOptions { WriteIndented = true }));
            ScreenshotPngWriter.WriteElementPng(window, Path.ChangeExtension(outputPath, ".before.png"), width, height);
            ScreenshotPngWriter.WriteVisibleElementPng(menu, Path.ChangeExtension(outputPath, ".before-popup.png"));
            Require(rootConnected && rowConnected, "Window F6 / row RunOnly missing: " + rootConnected + "/" + rowConnected);
            ICommand[] existing = { model.Pipeline.RunToSelectedCommand, model.Pipeline.ToggleEnabledCommand, model.Pipeline.DuplicateCommand, model.Pipeline.RenameCommand, model.Pipeline.MoveUpCommand, model.Pipeline.MoveDownCommand, model.Pipeline.NewTestCommand, model.Pipeline.DeleteCommand };
            MenuItem[] remaining = menu.Items.OfType<MenuItem>().Skip(1).ToArray();
            Require(remaining.Length == existing.Length && remaining.Select((item, i) => ReferenceEquals(item.Command, existing[i])).All(same => same), "remaining eight row commands preserve Pipeline owner");
            menu.IsOpen = false;
            Require(!f6!.Command.CanExecute(f6.CommandParameter), "empty batch disabled");
            string input = Path.ChangeExtension(outputPath, ".input.png");
            using (Bitmap image = new(32, 24)) { using Graphics graphics = Graphics.FromImage(image); graphics.Clear(DrawingColor.FromArgb(128, 128, 128)); image.Save(input, ImageFormat.Png); }
            Require(host.LoadMainImageFromFileForTest(input), "valid owned image");
            byte[] working = VisionPipelineExecutionPlan.SerializePipeline(model.Pipeline.WorkingCopyForTest);
            byte[] inputBytes = File.ReadAllBytes(input);
            Require(f6.Command.CanExecute(f6.CommandParameter), "loaded batch enabled");
            OpenVisionNativeToolDocument? cachedMean = null;
            for (int index = 0; index < 2; index++)
            {
                model.Pipeline.SelectStepCommand.Execute(index); Pump(8);
                host.SelectToolForTest(VISION_MENU.Threshold); Pump(8);
                Require(cachedMean?.WorkbenchParameterStep == null, "inactive cached document does not read another active editor");
                Require(model.Tool.IsNewTest, "distinct trial is active before row action");
                ContextMenu rowMenu = rows[index].ContextMenu!;
                System.Windows.Controls.Button dots = FindVisualChildren<System.Windows.Controls.Button>(rows[index]).Single(button => ReferenceEquals(button.ContextMenu, rowMenu));
                Require(ReferenceEquals(dots.Tag, model), "dots popup uses the same Workbench owner");
                ListBoxItem container = FindVisualChildren<ListBoxItem>(host).Single(item => ReferenceEquals(item.DataContext, rows[index].DataContext));
                Keyboard.Focus(container); Pump(5);
                Require(container.IsKeyboardFocusWithin && FindVisualChildren<StackPanel>(rows[index]).Single(panel => panel.Name == "quickActions").Visibility == Visibility.Visible, "keyboard row focus exposes actions");
                rowMenu.PlacementTarget = index == 0 ? rows[index] : dots; rowMenu.IsOpen = true; Pump(5);
                MenuItem item = rowMenu.Items.OfType<MenuItem>().First();
                Require(item.CommandParameter is int parameter && parameter == index && item.Command?.CanExecute(item.CommandParameter) == true, "row target parameter/CanExecute");
                Require(rowMenu.Items.OfType<MenuItem>().Skip(1).Select((entry, i) => ReferenceEquals(entry.Command, existing[i])).All(same => same), "right-click and dots retain eight existing commands");
                int beforeRuns = cachedMean?.PreviewRunCount ?? 0;
                item.Command!.Execute(item.CommandParameter); rowMenu.IsOpen = false;
                OpenVisionNativeToolDocument document = host.ActiveNativeDocumentForTest ?? throw new InvalidOperationException("Main row editor not opened");
                Stopwatch wait = Stopwatch.StartNew();
                while (document.IsPreviewRunning && wait.Elapsed < TimeSpan.FromSeconds(8)) { Pump(2); Thread.Sleep(5); }
                Pump(8);
                Require(model.Tool.IsStepEditing && model.Pipeline.SelectedStepIndex == index && model.Tool.ToolName == "Mean", "row replaces same-index trial with stored Mean");
                string expectedToolTitle = string.Format(CultureInfo.CurrentCulture, OpenVisionLanguageService.T("Shell.SelectedToolFormat"), OpenVisionShellCommandCatalog.DisplayName(VISION_MENU.Mean));
                File.WriteAllText(Path.ChangeExtension(outputPath, ".display-current.json"), JsonSerializer.Serialize(new { Index = index, Actual = host.DirectResultTitleText, Expected = expectedToolTitle, Route = host.DirectResultRouteText }));
                Require(host.DirectResultTitleText == expectedToolTitle && host.DirectResultRouteText.Contains("Row_Output_" + (index + 1), StringComparison.Ordinal), "current saved-tool label/route: " + host.DirectResultTitleText);
                File.WriteAllText(Path.ChangeExtension(outputPath, ".run-current.json"), JsonSerializer.Serialize(new { Index = index, Before = beforeRuns, After = document.PreviewRunCount, document.LastStatusText, document.IsPreviewRunning, document.HasPreviewResult }));
                Require(document.HasPreviewResult && !document.IsPreviewRunning && document.PreviewRunCount == beforeRuns + 1, "one explicit row preview: " + document.LastStatusText);
                double expectedMean = index == 0 ? 128D : 127D;
                double actualMean = model.Tool.CurrentResult?.Metrics?.TryGetValue("MeanValueAvg", out double meanValue) == true ? meanValue : double.NaN;
                File.WriteAllText(Path.ChangeExtension(outputPath, ".mean-current.json"), JsonSerializer.Serialize(new { Index = index, Expected = expectedMean, Actual = double.IsFinite(actualMean) ? actualMean : (double?)null, Parameters = model.Tool.CurrentStep.Parameters }));
                Require(actualMean == expectedMean, "saved common preprocessing preserves mean: " + actualMean + "/" + expectedMean);
                cachedMean = document;
                Require(model.Pipeline.Rows[index].HasStatus, "selected row result published");
                if (index == 0) Require(!model.Pipeline.Rows[1].HasStatus, "other row not run");
                Require(working.SequenceEqual(VisionPipelineExecutionPlan.SerializePipeline(model.Pipeline.WorkingCopyForTest)), "working steps unchanged");
                cases.Add(new { Theme = theme, Index = index, model.Tool.IsStepEditing, model.Tool.ToolName, model.Pipeline.SelectedStepIndex, BeforeRuns = beforeRuns, document.PreviewRunCount, document.LastStatusText, OtherRowNotRun = index != 0 || !model.Pipeline.Rows[1].HasStatus, ActualMean = actualMean, ExpectedMean = expectedMean });
                foreach (OpenVisionLanguage locale in new[] { OpenVisionLanguage.Korean, OpenVisionLanguage.English })
                {
                    OpenVisionLanguageService.SetLanguage(locale, false); Pump(5); rowMenu.IsOpen = true; Pump(5);
                    Require(host.DirectResultTitleText == string.Format(CultureInfo.CurrentCulture, OpenVisionLanguageService.T("Shell.SelectedToolFormat"), OpenVisionShellCommandCatalog.DisplayName(VISION_MENU.Mean)), "current label follows saved editor locale");
                    Require(item.Header?.ToString() == model["Workbench.Command.RunStepOnly"] && item.IsEnabled && item.InputGestureText == "F8", "localized row popup command");
                    ScreenshotPngWriter.WriteVisibleElementPng(rowMenu, Path.Combine(Path.GetDirectoryName(outputPath)!, $"row-{theme}-{width}-{index}-{locale}-popup.png"));
                    rowMenu.IsOpen = false;
                }
                ScreenshotPngWriter.WriteElementPng(window, Path.Combine(Path.GetDirectoryName(outputPath)!, $"main-row-{theme}-{width}-{index}.png"), width, height);
                Require(item.Command!.CanExecute(null) == false && item.Command.CanExecute("0") == false && item.Command.CanExecute(-1) == false && item.Command.CanExecute(2) == false, "null/wrong/invalid row rejected");
                item.Command.Execute(null); item.Command.Execute("0"); Require(document.PreviewRunCount == beforeRuns + 1, "invalid parameter no action");
            }
            int savedRuns = cachedMean!.PreviewRunCount;
            MeanProperty legacyMean = OpenVisionNativeSimplePreprocessPropertyFactory.CreateMeanProperty((SimplePreprocessToolWpfView)cachedMean.View);
            Require(legacyMean.USE_THRESHOLD && !legacyMean.USE_BITWISENOT, "legacy/default factory common flags remain unchanged");
            model.Tool.NewTestCommand.Execute(null); Pump(8);
            Require(model.Tool.IsNewTest && model.Tool.CurrentStep.Parameters["USE_THRESHOLD"] == "False" && model.Tool.CurrentStep.Parameters["USE_BITWISENOT"] == "True", "same-tool test clone preserves saved hidden options");
            host.SelectToolForTest(VISION_MENU.Threshold); Pump(5);
            Require(cachedMean.WorkbenchParameterStep == null, "inactive cached Mean has no other-tool baseline");
            host.SelectToolForTest(VISION_MENU.Mean); Pump(5);
            Require(model.Tool.IsNewTest && model.Tool.CurrentStep.Parameters["USE_BITWISENOT"] == "True" && cachedMean.PreviewRunCount == savedRuns, "cached test restore preserves options without execution");
            model.Pipeline.SelectStepCommand.Execute(0); Pump(5);
            Require(model.Tool.IsStepEditing && model.Tool.CurrentStep.Parameters["USE_BITWISENOT"] == "False" && cachedMean.PreviewRunCount == savedRuns, "stored row reactivation restores its own options without execution");
            Require(working.SequenceEqual(VisionPipelineExecutionPlan.SerializePipeline(model.Pipeline.WorkingCopyForTest)), "test/saved restoration leaves working steps unchanged");
            Menu mainMenu = FindVisualChildren<Menu>(window).Single(m => AutomationProperties.GetAutomationId(m) == "WorkbenchMainMenu");
            MenuItem run = (MenuItem)mainMenu.Items[3]; MenuItem active = run.Items.OfType<MenuItem>().Single(m => m.InputGestureText == "F8");
            Require(ReferenceEquals(active.Command, model.Tool.RunCommand), "F8 keeps active tool/stored editor contract");
            Require(host.InputBindings.OfType<KeyBinding>().Count(k => k.Key == Key.F6 && k.Modifiers == ModifierKeys.None) == 1, "existing Host F6 retained once");
            Require(File.ReadAllBytes(input).SequenceEqual(inputBytes), "owned image bytes unchanged");
            File.WriteAllText(Path.ChangeExtension(outputPath, ".json"), JsonSerializer.Serialize(new { Cases = cases, WindowF6 = true, HostF6 = true, ActiveF8 = true, InputUnchanged = true, WorkingStepsUnchanged = true, Boundary = "Inprocess bound command/preview setup; actual key and pointer/nativeDPI verified separately; no full Main96 claim" }, new JsonSerializerOptions { WriteIndented = true }));
        });
    }

    private static CaptureResult CaptureMainMenuConnections(string outputPath, string theme)
    {
        GlobalState global = new();
        global.Recipe.Name = "Smoke_MainMenuConnections";
        global.System.SaveWorkbenchLayout(new SystemStateConfig());
        string sourceRecipe = global.Recipe.Name, token = Guid.NewGuid().ToString("N").Substring(0, 10);
        string[] visited = new[] { sourceRecipe }.Concat(Enumerable.Range(1, 5).Select(index => "MRU_" + token + "_" + index)).ToArray();
        foreach (string name in visited) { VisionPipelineStorage.Save(name, new VisionPipeline { Name = "Pipeline" }); VisionPipelineStorage.SaveActivePipelineName(name, "Pipeline"); }
        const string fallbackRecipe = "AAA_MRU_Fallback";
        VisionPipelineStorage.Save(fallbackRecipe, new VisionPipeline { Name = "Pipeline" }); VisionPipelineStorage.SaveActivePipelineName(fallbackRecipe, "Pipeline");
        string current = sourceRecipe;
        bool switchSucceeds = true, configSucceeds = true;
        Task recentCompletion = Task.CompletedTask;
        OpenVisionRecipePendingEditDecision recentDecision = OpenVisionRecipePendingEditDecision.Cancel;
        OpenVisionShellHostRecipeCommandSurface recentCommands = new(() => current, name => { if (switchSucceeds) { current = name; } }, () => { },
            decidePendingEdit: _ => recentDecision, saveRecipe: () => true, saveRuntimeRecipeCopy: _ => true, yieldToUi: () => Task.CompletedTask, waitForRecipeSwitchCompletion: () => recentCompletion);
        using (DisplayManagerService recentDisplay = new())
        using (OpenVisionWorkbenchPipelineViewModel recentPipeline = new(recentCommands, recentDisplay, action => action(), _ => recentDecision, _ => true, Array.Empty<OpenVisionShellNavGroup>()))
        {
            recentCommands.AttachWorkbenchPipeline(recentPipeline);
            using OpenVisionWorkbenchViewModel recentModel = new(new SystemStateConfig(), preferences => configSucceeds && global.System.SaveWorkbenchLayout(preferences), recipes: recentCommands);
            void RequireRecent(bool condition, string name) { if (!condition) throw new InvalidOperationException("Recent recipe: " + name); }
            void OpenRecent(string name) { recentCommands.OpenMainRecentRecipeCommand.Execute(name); Pump(3); RequireRecent(!recentCommands.IsSwitchingRecipe, "transition slot released"); }
            RequireRecent(recentModel.RecentRecipes.Count == 0, "startup does not invent visits");
            recentModel.UpdateViewport(1600, 800); RequireRecent(recentModel.IsToolPaletteCollapsed, "default palette at short viewport");
            recentPipeline.InsertStep(0, new VisionPipelineStep { Name = "Pending", ToolType = "Mean", InputLayer = "Main", OutputLayer = "Pending_Output" });
            OpenRecent(visited[1]); RequireRecent(current == sourceRecipe && recentPipeline.IsDirty && recentModel.RecentRecipes.Count == 0, "unsaved cancel retains history and working copy");
            recentDecision = OpenVisionRecipePendingEditDecision.ApplyAndContinue;
            string sourcePath = RecipeWorkspaceService.GetVisionPipelinePath(sourceRecipe, "Pipeline");
            using (FileStream locked = new(sourcePath, FileMode.Open, FileAccess.Read, FileShare.Read))
            {
                OpenRecent(visited[1]); RequireRecent(current == sourceRecipe && recentPipeline.IsDirty && recentModel.RecentRecipes.Count == 0, "save failure does not record an open");
            }
            recentDecision = OpenVisionRecipePendingEditDecision.Discard;
            OpenRecent(visited[1]); RequireRecent(current == visited[1] && recentModel.RecentRecipes.Select(item => item.Key).SequenceEqual(new[] { visited[1] }), "discard then valid open commits first visit");
            RequireRecent(global.System.WorkbenchLayoutPreferences.WorkbenchLayoutVersion == 0 && global.System.WorkbenchLayoutPreferences.WorkbenchLeftWidth == 0
                && global.System.WorkbenchLayoutPreferences.WorkbenchRightWidth == 0 && global.System.WorkbenchLayoutPreferences.WorkbenchBottomHeight == 0, "MRU preserves default version and requested zero widths");
            recentModel.UpdateViewport(1600, 950); RequireRecent(!recentModel.IsToolPaletteCollapsed, "MRU does not freeze tall default palette");
            recentModel.UpdateViewport(1600, 800); RequireRecent(recentModel.IsToolPaletteCollapsed, "MRU does not freeze short default palette");
            switchSucceeds = false; OpenRecent(visited[2]); RequireRecent(current == visited[1] && recentModel.RecentRecipes.Count == 1, "load failure does not record target"); switchSucceeds = true;
            foreach (string name in visited.Skip(2).Append(sourceRecipe)) { OpenRecent(name); }
            VisionPipelineStorage.TryGetPersistenceState(sourceRecipe, "Pipeline", out VisionPipelinePersistenceState sourceSaveState);
            File.WriteAllText(Path.ChangeExtension(outputPath, ".recent-source-reload.json"), JsonSerializer.Serialize(new { Current = current, History = recentModel.RecentRecipes.Select(item => item.Key), SourceState = sourceSaveState?.Kind.ToString(), PipelineXmlProjection = recentCommands.SelectedPipelineOption?.XmlValid, SummaryXmlProjection = recentCommands.SelectedRecipeSummary?.XmlValid, RawXmlReadable = VisionPipelineStorage.TryLoadFromFile(sourcePath, out _, out _) }, new JsonSerializerOptions { WriteIndented = true }));
            RequireRecent(recentModel.RecentRecipes.Select(item => item.Key).SequenceEqual(new[] { sourceRecipe, visited[5], visited[4], visited[3], visited[2] }), "successful order and maximum five: " + string.Join(",", recentModel.RecentRecipes.Select(item => item.Key)) + "; current=" + current + "; persistenceFailure=" + recentCommands.HasSelectedRecipePersistenceFailure);
            OpenRecent(visited[2]); OpenRecent(sourceRecipe);
            RequireRecent(recentModel.RecentRecipes.Select(item => item.Key).SequenceEqual(new[] { sourceRecipe, visited[2], visited[5], visited[4], visited[3] }), "revisit deduplicates and moves to front");
            string missing = "Missing_" + token;
            RequireRecent(!recentCommands.OpenMainRecentRecipeCommand.CanExecute(missing), "missing workspace disabled"); OpenRecent(missing);
            RequireRecent(!RecipeWorkspaceService.GetRecipeNames().Contains(missing), "stale command cannot create a workspace");
            configSucceeds = false; OpenRecent(visited[1]); RequireRecent(current == visited[1] && recentModel.HasLayoutStatus
                && recentModel.LayoutStatusText == recentModel["Workbench.Recipe.RecentSaveFailed"], "config failure retains transition and reports history/settings failure"); configSucceeds = true; OpenRecent(sourceRecipe);
            RequireRecent(VisionPipelineStorage.TryGetPersistenceState(sourceRecipe, "Pipeline", out VisionPipelinePersistenceState retainedSaveFailure) && retainedSaveFailure.Kind == VisionPipelinePersistenceStateKind.SaveFailed, "successful reload records source while retaining its earlier save failure warning");
            string createdName = new string('가', 50) + token, copyName = "MRU_Copy_" + token;
            var created = recentCommands.CreateMainRecipeAsync(createdName, "", "Pipeline", false, false); WaitForTaskWithPump(created, 10000, "recent create"); RequireRecent(created.Result.Succeeded && recentModel.RecentRecipes[0].Key == createdName, "created recipe uses successful-open boundary");
            var copy = recentCommands.CreateMainRecipeAsync(copyName, "", "Pipeline", true, true); WaitForTaskWithPump(copy, 10000, "recent SaveAs"); RequireRecent(copy.Result.Succeeded && recentModel.RecentRecipes[0].Key == copyName, "SaveAs uses successful-open boundary");
            string renamed = "MRU_Renamed_" + token;
            recentCommands.RecipeManagerSelectedRecipeName = copyName; recentCommands.EditRecipeName = renamed; recentCommands.RenameRecipeCommand.Execute(null); Pump(3);
            RequireRecent(current == renamed && recentModel.RecentRecipes[0].Key == renamed && !global.System.WorkbenchLayoutPreferences.WorkbenchRecentRecipeNames.Contains(copyName), "current rename records new identity and removes stale name");
            recentCommands.DeleteRecipeCommand.Execute(null); Pump(3);
            RequireRecent(current == fallbackRecipe && recentModel.RecentRecipes[0].Key == fallbackRecipe && !global.System.WorkbenchLayoutPreferences.WorkbenchRecentRecipeNames.Contains(renamed), "current deletion records successful fallback and removes stale name");
            OpenRecent(sourceRecipe);
            string[] finalHistory = new[] { sourceRecipe, fallbackRecipe, createdName, visited[1], visited[2] };
            RequireRecent(global.System.WorkbenchLayoutPreferences.WorkbenchRecentRecipeNames.SequenceEqual(finalHistory), "user config contains final successful order");
            recentModel.ResetLayoutCommand.Execute(null);
            RequireRecent(global.System.WorkbenchLayoutPreferences.WorkbenchRecentRecipeNames.SequenceEqual(finalHistory), "layout reset preserves activity history");
            SystemState restoredSystem = new();
            RequireRecent(recentPipeline.ResultCountForTest == 0 && !recentPipeline.IsRunning, "history workflow never executes inspection");
            // The existing completion Task stays pending through close; the old consumer must not write a later visit.
            string configPath = RecipeWorkspaceService.GetSystemConfigPath("SYSTEM"); byte[] committedConfig = File.ReadAllBytes(configPath);
            OpenRecent(visited[5]);
            TaskCompletionSource delayedOpen = new(); recentCompletion = delayedOpen.Task;
            recentCommands.RecipeManagerSelectedRecipeName = current; recentCommands.EditRecipeName = "MRU_Late_" + token; recentCommands.RenameRecipeCommand.Execute(null); Pump(2);
            byte[] beforeCloseCompletion = File.ReadAllBytes(configPath);
            recentModel.Dispose(); delayedOpen.SetResult(); Pump(3);
            RequireRecent(beforeCloseCompletion.SequenceEqual(File.ReadAllBytes(configPath)), "late completion after dispose does not record history");
            File.WriteAllBytes(configPath, committedConfig); global.System.LoadConfig();
            using OpenVisionWorkbenchViewModel restoredModel = new(restoredSystem.WorkbenchLayoutPreferences, _ => true, recipes: recentCommands);
            RequireRecent(restoredModel.RecentRecipes.Select(item => item.Key).SequenceEqual(finalHistory), "config reload restores order without opening recipes");
            File.WriteAllText(Path.ChangeExtension(outputPath, ".recent-policy.json"), JsonSerializer.Serialize(new { FinalHistory = finalHistory, CancelSaveLoadFailureNoVisit = true, MissingNoCreate = true, CreateAndSaveAs = true, ConfigFailureRecovery = true, ResetAndReload = true, Boundary = "Owned inprocess actual command and config XML; no native input" }, new JsonSerializerOptions { WriteIndented = true }));
        }
        OpenVisionShellHostWindow window = new(new ApplicationRuntimeContext(global, new DisplayManagerService()));
        window.ClearValue(OpenVisionShellHostWindow.ClosingCommandProperty); // Owned fixture inserts an unsaved step; actual save/close policy is verified separately.
        OpenVisionShellHostView host = window.ShellHostForSmoke;
        (theme == "Light" ? host.Workbench.SelectLightThemeCommand : host.Workbench.SelectDarkThemeCommand).Execute(null);
        List<object> cases = new();
        void Require(bool condition, string detail) { if (!condition) throw new InvalidOperationException("Main menu connection: " + detail); }
        return CaptureStandaloneWindow(window, outputPath, 1920, 1032, () =>
        {
            OpenVisionWorkbenchViewModel model = host.Workbench;
            model.Tool.IsAutoRunEnabled = false;
            TextBlock pipelineTitle = FindVisualChildren<TextBlock>(host).Single(item => AutomationProperties.GetAutomationId(item) == "WorkbenchPipelineTitle");
            Require(pipelineTitle.Text == model["Workbench.Pipeline.Title"] && !pipelineTitle.Focusable, "display-only localized Pipeline title");
            Require(!FindVisualChildren<Button>((DependencyObject)pipelineTitle.Parent).Any(item => ReferenceEquals(item.Command, host.RecipeCommands.OpenMainRecipeWorkCommand)), "no legacy Work command on Main title");
            int runs = host.NativePreviewRunCount;
            byte[] working = VisionPipelineExecutionPlan.SerializePipeline(model.Pipeline.WorkingCopyForTest);
            Menu mainMenu = FindVisualChildren<Menu>(window).Single(menu => AutomationProperties.GetAutomationId(menu) == "WorkbenchMainMenu");
            MenuItem fileMenu = (MenuItem)mainMenu.Items[0];
            MenuItem[] recentItems = fileMenu.Items.OfType<MenuItem>().Where(item => ReferenceEquals(item.Command, model.Recipes.OpenMainRecentRecipeCommand)).ToArray();
            Require(recentItems.Length == 5 && recentItems.Select(item => (string)item.CommandParameter).SequenceEqual(global.System.WorkbenchLayoutPreferences.WorkbenchRecentRecipeNames), "restored flat recent menu order/target/command");
            fileMenu.IsSubmenuOpen = true; Pump(3);
            File.WriteAllText(Path.ChangeExtension(outputPath, ".recent-menu-state.json"), JsonSerializer.Serialize(new { Current = model.Recipes.MainRecipeName, Language = OpenVisionLanguageService.CurrentLanguage.ToString(), Items = recentItems.Select(item => new { Header = ((TextBlock)item.Header).Text, item.CommandParameter, item.IsEnabled, CanExecute = item.Command.CanExecute(item.CommandParameter) }) }, new JsonSerializerOptions { WriteIndented = true }));
            Require(!recentItems[0].IsEnabled && ((TextBlock)recentItems[0].Header).Text.Contains(model["Workbench.Recipe.InUse"]) && recentItems.Skip(1).All(item => item.IsEnabled), "current recipe caption and disabled command");
            foreach (MenuItem item in recentItems)
            {
                TextBlock header = (TextBlock)item.Header;
                Require(header.Text.StartsWith((string)item.CommandParameter, StringComparison.Ordinal) && !FindVisualChildren<AccessText>(header).Any()
                    && header.TextWrapping == TextWrapping.Wrap && header.ActualHeight + header.Margin.Top + header.Margin.Bottom <= item.ActualHeight + 1D,
                    "literal recipe name/current suffix wraps inside its menu row");
            }
            AssertWorkbenchMenuPopup(fileMenu);
            ScreenshotPngWriter.WriteElementPng(window, Path.ChangeExtension(outputPath, ".recent-menu.png"), 1920, 1032);
            fileMenu.IsSubmenuOpen = false; Pump(2);
            MenuItem view = (MenuItem)mainMenu.Items[2], run = (MenuItem)mainMenu.Items[3];
            MenuItem[] viewItems = view.Items.OfType<MenuItem>().Take(6).ToArray();
            MenuItem all = run.Items.OfType<MenuItem>().Single(item => item.Header?.ToString() == model["Workbench.Command.BatchAll"]);
            MenuItem selected = run.Items.OfType<MenuItem>().Single(item => item.Header?.ToString() == model["Workbench.Command.BatchSelected"]);
            (ICommand Command, Func<bool> On)[] expected =
            {
                (model.Viewer.SingleCommand, () => model.Viewer.IsSingle), (model.Viewer.Split2Command, () => model.Viewer.IsSplit2),
                (model.Viewer.Split4Command, () => model.Viewer.IsSplit4), (model.Viewer.ToggleSyncCommand, () => model.Viewer.IsSyncEnabled),
                (model.Viewer.ToggleOverlayCommand, () => model.Viewer.IsOverlayVisible), (model.Viewer.ToggleRoiCommand, () => model.Viewer.IsRoiVisible)
            };
            view.IsSubmenuOpen = true; Pump(5);
            ScreenshotPngWriter.WriteElementPng(window, Path.ChangeExtension(outputPath, ".before.png"), 1920, 1032);
            System.Windows.Controls.Primitives.Popup popup = FindNamedVisualChild<System.Windows.Controls.Primitives.Popup>(view, "PART_Popup")!;
            FrameworkElement popupRoot = (FrameworkElement)popup.Child;
            ScreenshotPngWriter.WriteElementPng(popupRoot, Path.ChangeExtension(outputPath, ".before-popup.png"), (int)Math.Ceiling(popupRoot.ActualWidth), (int)Math.Ceiling(popupRoot.ActualHeight));
            view.IsSubmenuOpen = false;
            for (int index = 0; index < 6; index++) Require(ReferenceEquals(viewItems[index].Command, expected[index].Command), "view command " + index);
            Require(ReferenceEquals(all.Command, model.Images.RunBatchCommand) && (string)all.CommandParameter == "all", "batch all command/parameter");
            Require(ReferenceEquals(selected.Command, model.Images.RunBatchCommand) && (string)selected.CommandParameter == "selected", "batch selected command/parameter");
            bool emptyAllBeforeOpen = all.IsEnabled, emptySelectedBeforeOpen = selected.IsEnabled;
            run.IsSubmenuOpen = true; Pump(5);
            File.WriteAllText(Path.ChangeExtension(outputPath, ".empty-applicability.json"), JsonSerializer.Serialize(new { model.Images.Count, model.Images.SelectedCount, PipelineSteps = model.Pipeline.Rows.Count, EmptyAllBeforeOpen = emptyAllBeforeOpen, EmptySelectedBeforeOpen = emptySelectedBeforeOpen, AllCanExecute = all.Command.CanExecute(all.CommandParameter), SelectedCanExecute = selected.Command.CanExecute(selected.CommandParameter), AllEnabled = all.IsEnabled, SelectedEnabled = selected.IsEnabled }, new JsonSerializerOptions { WriteIndented = true }));
            Require(!all.IsEnabled && !selected.IsEnabled, "empty batch disabled");
            run.IsSubmenuOpen = false;
            foreach ((int width, int height) in new[] { (1920, 1032), (1280, 760) })
            foreach (OpenVisionLanguage locale in new[] { OpenVisionLanguage.Korean, OpenVisionLanguage.English })
            {
                window.Width = width; window.Height = height; OpenVisionLanguageService.SetLanguage(locale, false); Pump(8);
                view.IsSubmenuOpen = true; Pump(4); AssertWorkbenchMenuPopup(view);
                for (int index = 0; index < 6; index++)
                {
                    Require(viewItems[index].IsEnabled && viewItems[index].IsChecked == expected[index].On(), "initial check " + index);
                    bool previous = expected[index].On();
                    viewItems[index].Command.Execute(viewItems[index].CommandParameter); Pump(5);
                    Require(viewItems[index].IsChecked == expected[index].On(), "source -> checked " + index);
                    if (index < 3)
                    {
                        Require(model.Viewer.Panes.Count == new[] { 1, 2, 4 }[index], "rendered pane layout " + index);
                        viewItems[index].SetCurrentValue(MenuItem.IsCheckedProperty, false); // WPF checkable-item click toggles the target before its command.
                        viewItems[index].Command.Execute(null); Pump(4);
                        Require(viewItems[index].IsChecked, "repeat active layout stays checked " + index);
                    }
                    else Require(expected[index].On() != previous, "one toggle " + index);
                    expected[index].Command.Execute(null); Pump(4);
                    Require(viewItems[index].IsChecked == expected[index].On(), "toolbar/source -> menu check " + index);
                    if (index >= 3) Require(expected[index].On() == previous, "toggle restore " + index);
                    cases.Add(new { Theme = theme, Width = width, Height = height, Language = locale.ToString(), Action = index, viewItems[index].IsEnabled, viewItems[index].IsChecked, Scope = "Inprocess bound command, not actual click" });
                }
                ScreenshotPngWriter.WriteElementPng(popupRoot, Path.Combine(Path.GetDirectoryName(outputPath)!, $"menu-{theme}-{width}-{locale}.png"), (int)Math.Ceiling(popupRoot.ActualWidth), (int)Math.Ceiling(popupRoot.ActualHeight));
                view.IsSubmenuOpen = false; Pump(4);
                ScreenshotPngWriter.WriteElementPng(window, Path.Combine(Path.GetDirectoryName(outputPath)!, $"main-{theme}-{width}-{locale}.png"), width, height);
            }
            string input = Path.ChangeExtension(outputPath, ".input.png");
            using (Bitmap image = new(32, 24)) { using Graphics graphics = Graphics.FromImage(image); graphics.Clear(DrawingColor.FromArgb(128, 128, 128)); image.Save(input, ImageFormat.Png); }
            Require(host.LoadMainImageFromFileForTest(input), "valid Main input");
            model.Pipeline.InsertStep(0, new VisionPipelineStep { Name = "Menu applicability", ToolType = "Mean", InputLayer = "Main", OutputLayer = "Menu_Output" });
            string secondInput = Path.ChangeExtension(outputPath, ".second-input.png"); File.Copy(input, secondInput, true);
            Require(model.Images.AddImages(new[] { new OpenVisionWorkbenchImageItem(secondInput, "Second", OpenVisionBitmapImagePreviewFactory.CreateFromPath(secondInput)) }) == 1, "second distinct owned input");
            Pump(5);
            model.Pipeline.SelectStepCommand.Execute(0); Pump(8);
            Require(model.Tool.IsStepEditing && model.Tool.CurrentStep?.Name == "Menu applicability"
                && model.Pipeline.SelectedStepIndex == 0 && host.RecipeCommands.MainRecipeName == "Smoke_MainMenuConnections", "same Main selected-Step editor");
            Require(!host.IsRecipeManagerOpenForTest && !host.RecipeCommands.IsRecipeManagerDetailContextActive, "step selection leaves Main visible");
            int titleLayers = host.LayerDocumentCount, titleResults = model.Pipeline.ResultCountForTest;
            string titleActiveLayer = host.ActiveHostLayerTitle, titleInput = host.ActiveNativeRouteInputLayerNameForTest, titleOutput = host.ActiveNativeRouteOutputLayerNameForTest;
            byte[] titleWorkingCopy = VisionPipelineExecutionPlan.SerializePipeline(model.Pipeline.WorkingCopyForTest);
            pipelineTitle.RaiseEvent(new MouseButtonEventArgs(Mouse.PrimaryDevice, Environment.TickCount, MouseButton.Left) { RoutedEvent = UIElement.MouseLeftButtonDownEvent });
            pipelineTitle.RaiseEvent(new MouseButtonEventArgs(Mouse.PrimaryDevice, Environment.TickCount, MouseButton.Left) { RoutedEvent = UIElement.MouseLeftButtonUpEvent }); Pump(3);
            Require(!host.IsRecipeManagerOpenForTest && !host.RecipeCommands.IsRecipeManagerDetailContextActive && model.Pipeline.SelectedStepIndex == 0, "title click preserves Main and selection");
            Require(host.NativePreviewRunCount == runs && host.LayerDocumentCount == titleLayers && model.Pipeline.ResultCountForTest == titleResults
                && host.ActiveHostLayerTitle == titleActiveLayer && host.ActiveNativeRouteInputLayerNameForTest == titleInput && host.ActiveNativeRouteOutputLayerNameForTest == titleOutput
                && titleWorkingCopy.SequenceEqual(VisionPipelineExecutionPlan.SerializePipeline(model.Pipeline.WorkingCopyForTest)), "title leaves execution, layers, active layer, routes and workcopy unchanged");
            run.IsSubmenuOpen = true; Pump(4);
            Require(all.IsEnabled && !selected.IsEnabled, "loaded all/selected applicability");
            model.Images.Images[1].IsSelected = true; Pump(5); Require(selected.IsEnabled, "selection enables same command");
            model.Images.ClearSelectionCommand.Execute(null); Pump(5); Require(!selected.IsEnabled, "clear selection disables command");
            FrameworkElement runRoot = (FrameworkElement)FindNamedVisualChild<System.Windows.Controls.Primitives.Popup>(run, "PART_Popup")!.Child;
            ScreenshotPngWriter.WriteElementPng(runRoot, Path.ChangeExtension(outputPath, ".run-popup.png"), (int)Math.Ceiling(runRoot.ActualWidth), (int)Math.Ceiling(runRoot.ActualHeight));
            run.IsSubmenuOpen = false; model.Viewer.Split2Command.Execute(null); Pump(4);
            Require(ReferenceEquals(window.ViewerSingleCommand, model.Viewer.SingleCommand) && ReferenceEquals(window.ViewerSplit2Command, model.Viewer.Split2Command)
                && ReferenceEquals(window.ViewerSplit4Command, model.Viewer.Split4Command), "viewer key DP bindings use the menu commands");
            ButtonBase viewerFocus = FindNamedVisualChild<ToggleButton>(host, "btnMainViewerSingle")!;
            KeyEventArgs ViewerKey(Key key)
            {
                var args = new KeyEventArgs(Keyboard.PrimaryDevice, PresentationSource.FromVisual(window)!, 0, key) { RoutedEvent = Keyboard.PreviewKeyDownEvent };
                window.RaiseEvent(args); Pump(3); return args;
            }
            FrameworkElement viewerFrame = FindNamedVisualChild<FrameworkElement>(host, "hostWorkspaceFrame")!;
            foreach (MenuItem item in FindVisualChildren<MenuItem>(window)) item.IsSubmenuOpen = false;
            Require(viewerFocus.Focus(), "exit menu mode before surface input"); Pump(3);
            Require(Mouse.Captured == null, "closed menus release mouse capture before surface input");
            foreach ((Key key, int count) in new[] { (Key.D1, 1), (Key.D2, 2), (Key.D4, 4) })
            {
                Grid surface = FindVisualChildren<Grid>(viewerFrame).First(item => item.Name == "layerImageSurface" && item.IsVisible);
                var down = new MouseButtonEventArgs(Mouse.PrimaryDevice, Environment.TickCount, MouseButton.Left) { RoutedEvent = Mouse.PreviewMouseDownEvent };
                surface.RaiseEvent(down); Pump(2);
                Require(!down.Handled && ReferenceEquals(Keyboard.FocusedElement, viewerFrame), "image surface routing hands off keyboard focus without consuming mouse input: handled=" + down.Handled + ", focus=" + (Keyboard.FocusedElement as FrameworkElement)?.Name + ", focusType=" + Keyboard.FocusedElement?.GetType().Name + ", within=" + viewerFrame.IsKeyboardFocusWithin + ", focusable=" + viewerFrame.Focusable + ", capture=" + (Mouse.Captured as FrameworkElement)?.Name + ", captureType=" + Mouse.Captured?.GetType().Name);
                Require(ViewerKey(key).Handled && model.Viewer.Panes.Count == count, "surface focus layout key " + key);
            }
            Grid capturedSurface = FindVisualChildren<Grid>(viewerFrame).First(item => item.Name == "layerImageSurface" && item.IsVisible);
            try
            {
                Require(Mouse.Capture(capturedSurface), "owned mouse capture");
                Require(!ViewerKey(Key.D1).Handled && model.Viewer.Panes.Count == 4, "capture/drag does not release the current layout");
            }
            finally { Mouse.Capture(null); }
            foreach ((Key key, int count) in new[] { (Key.D1, 1), (Key.D2, 2), (Key.D4, 4) })
            {
                Require(viewerFocus.Focus(), "viewer toolbar keyboard focus"); Pump(2);
                Require(ViewerKey(key).Handled && model.Viewer.Panes.Count == count, "viewer key uses same layout " + key);
                Require(viewerFocus.Focus(), "repeat viewer toolbar focus"); Pump(2);
                Require(ViewerKey(key).Handled && model.Viewer.Panes.Count == count, "repeated layout key is idempotent " + key);
            }
            Require(viewerFocus.Focus(), "viewer guard focus"); Pump(2);
            window.SetCurrentValue(OpenVisionShellHostWindow.ViewerSingleCommandProperty, null);
            Require(!ViewerKey(Key.D1).Handled && model.Viewer.IsSplit4, "null layout command leaves key/state alone");
            window.SetCurrentValue(OpenVisionShellHostWindow.ViewerSingleCommandProperty, new OpenVisionLab.Mvvm.RelayCommand(() => throw new InvalidOperationException("Disabled viewer key executed."), () => false));
            Require(!ViewerKey(Key.D1).Handled && model.Viewer.IsSplit4, "disabled layout command leaves key/state alone");
            window.SetBinding(OpenVisionShellHostWindow.ViewerSingleCommandProperty, new Binding("Viewer.SingleCommand"));
            ComboBox sourceInput = FindVisualChildren<ComboBox>(host).First(item => item.IsVisible && item.IsEnabled);
            Require(sourceInput.Focus(), "combo input focus"); Pump(2);
            Require(!ViewerKey(Key.D1).Handled && model.Viewer.IsSplit4, "combo input does not change layout");
            model.OpenMainNewRecipeCommand.Execute(null); Pump(3);
            TextBox recipeInput = FindNamedVisualChild<TextBox>(window, "mainRecipeNameInput")!;
            Require(recipeInput.Focus(), "overlay text input focus"); Pump(2);
            Require(!ViewerKey(Key.D2).Handled && model.Viewer.IsSplit4 && recipeInput.Text == "", "overlay digits are not consumed or layout commands");
            model.CloseMainRecipeCommand.Execute(null); Pump(3);
            model.Viewer.Split2Command.Execute(null); Pump(3);
            Require(host.NativePreviewRunCount == runs && model.Pipeline.Rows.All(row => !row.HasStatus) && model.Pipeline.VerdictValue == "—", "no implicit execution from menu/view/selection");
            File.WriteAllText(Path.ChangeExtension(outputPath, ".json"), JsonSerializer.Serialize(new { Cases = cases, EmptyAndLoadedCanExecute = true, BatchSelectionRoundTrip = true, NativeRunsBefore = runs, NativeRunsAfter = host.NativePreviewRunCount, InitialWorkingCopy = working, FinalWorkingCopy = VisionPipelineExecutionPlan.SerializePipeline(model.Pipeline.WorkingCopyForTest), Boundary = "Owned synthetic input/step setup; no explicit inspection, actual pointer/DPI/full Main96 proof" }, new JsonSerializerOptions { WriteIndented = true }));
        });
    }

    private static CaptureResult CaptureWorkbenchLayout(string outputPath, int width, int height)
    {
        OpenVisionLanguageService.SetLanguage(OpenVisionLanguage.Korean, false);
        DisplayManagerService display = new();
        GlobalState global = new();
        global.Recipe.Name = "Smoke_WorkbenchLayout_" + Guid.NewGuid().ToString("N");
        global.Recipe.SaveTools();
        global.System.SaveWorkbenchLayout(new SystemStateConfig());
        OpenVisionShellHostWindow window = new(new ApplicationRuntimeContext(global, display));
        window.ClearValue(OpenVisionShellHostWindow.ClosingCommandProperty);
        OpenVisionLanguageService.SetLanguage(OpenVisionLanguage.Korean, false); // Seed after the shell restores persisted locale.
        return CaptureStandaloneWindow(window, outputPath, width, height, () =>
        {
            Pump(30);
            OpenVisionShellHostView host = window.ShellHostForSmoke;
            OpenVisionWorkbenchViewModel model = host.Workbench;
            ColumnDefinition left = FindNamedVisualChild<Grid>(host, "rootShellHost") == null
                ? throw new InvalidOperationException("Workbench root missing.")
                : (ColumnDefinition)host.FindName("toolRailColumn");
            ColumnDefinition right = (ColumnDefinition)host.FindName("toolInspectorColumn");
            RowDefinition bottom = (RowDefinition)host.FindName("logPanelRow");
            double expectedLeft = width <= 1360 ? 248D : width <= 1560 ? 264D : 296D;
            double expectedRight = width <= 1360 ? 480D : width <= 1560 ? 488D : 520D;
            double expectedBottom = height <= 820 ? 200D : 256D;
            AssertNear(left.ActualWidth, expectedLeft, "default left");
            AssertNear(right.ActualWidth, expectedRight, "default right");
            AssertNear(bottom.ActualHeight, expectedBottom, "default bottom");
            if (model.IsToolPaletteCollapsed != (height < 900)) { throw new InvalidOperationException("Tool palette kept an intermediate startup size."); }
            Button paletteToggle = FindNamedVisualChild<Button>(host, "btnToggleToolRail")!;
            if (!ReferenceEquals(paletteToggle.Command, model.ToggleToolPaletteCommand)) { throw new InvalidOperationException("Tool palette toggle changed the pipeline panel instead."); }
            TextBlock pipelineEntry = FindVisualChildren<TextBlock>(host).Single(item => AutomationProperties.GetAutomationId(item) == "WorkbenchPipelineTitle");
            if (AutomationProperties.GetName(pipelineEntry) != model["Workbench.Pipeline.Title"]) { throw new InvalidOperationException("Main pipeline entry lost its localized accessible name."); }
            int runs = host.NativePreviewRunCount;
            int layerCount = host.LayerDocumentCount;
            string active = host.WorkspaceLayerTitle;
            string route = host.DirectResultRouteText;
            AssertVisibleAutomationIds(window, "Workbench frame", "WorkbenchMainMenu", "WorkbenchLanguage", "WorkbenchCommandBar", "WorkbenchLeftPanel", "WorkbenchCenterPanel", "WorkbenchToolPanelEmpty", "WorkbenchBottomPanel", "WorkbenchStatusBar");
            ComboBox language = FindVisualChildren<ComboBox>(window).Single(item => AutomationProperties.GetAutomationId(item) == "WorkbenchLanguage");
            Grid languageHost = (Grid)language.Parent;
            if (language.ActualWidth > languageHost.ColumnDefinitions[2].ActualWidth) { throw new InvalidOperationException("Language field overflows its header column."); }
            if (language.ActualWidth != 76D || language.ActualHeight != 26D) { throw new InvalidOperationException("Language field differs from the current HTML logical size, 76x26."); }
            Border languageChrome = FindNamedVisualChild<Border>(language, "comboChrome") ?? throw new InvalidOperationException("Language chrome did not render.");
            AssertBrushContrast(language.Foreground, languageChrome.Background, "Workbench language entered text");
            System.Windows.Shapes.Path languageArrow = FindNamedVisualChild<System.Windows.Shapes.Path>(language, "comboDropGlyph");
            if (languageArrow?.Fill is not SolidColorBrush arrowBrush || arrowBrush.Color.A == 0) { throw new InvalidOperationException("Language dropdown glyph is transparent."); }
            language.RaiseEvent(new MouseButtonEventArgs(Mouse.PrimaryDevice, Environment.TickCount, MouseButton.Left) { RoutedEvent = UIElement.PreviewMouseLeftButtonDownEvent });
            Pump(4);
            if (!language.IsDropDownOpen) { throw new InvalidOperationException("Language field click did not open its popup."); }
            for (int optionIndex = 0; optionIndex < language.Items.Count; optionIndex++)
            {
                ComboBoxItem option = language.ItemContainerGenerator.ContainerFromIndex(optionIndex) as ComboBoxItem;
                if (option?.Foreground is not SolidColorBrush optionBrush || optionBrush.Color.A == 0) { throw new InvalidOperationException("Language popup text is transparent."); }
                if (!FindVisualChildren<TextBlock>(option).Any(text => text.Text == model.Shell.LanguageOptions[optionIndex].DisplayName)) { throw new InvalidOperationException("Language popup did not render its display name."); }
            }
            language.IsDropDownOpen = false;
            language.SelectedItem = model.Shell.LanguageOptions.Single(option => option.Language == OpenVisionLanguage.English);
            Pump(4);
            if (model.Shell.SelectedLanguageOption.Language != OpenVisionLanguage.English) { throw new InvalidOperationException("Language control did not update its ViewModel."); }
            ToolTip layoutLanguageTip = language.ToolTip as ToolTip ?? throw new InvalidOperationException("Language field tooltip was not explicitly themed.");
            layoutLanguageTip.PlacementTarget = language; layoutLanguageTip.IsOpen = true; Pump(4);
            try
            {
                if (layoutLanguageTip.Content?.ToString() != "Switch the UI language between Korean and English.") { throw new InvalidOperationException("Language field tooltip did not switch to English."); }
            }
            finally { layoutLanguageTip.IsOpen = false; }
            TextBlock selectedLanguageText = FindVisualChildren<TextBlock>(language).Single(text => text.Text == model.Shell.SelectedLanguageOption.DisplayName);
            ContentPresenter languageContent = FindNamedVisualChild<ContentPresenter>(language, "contentSite");
            FormattedText languageRequired = new(selectedLanguageText.Text, CultureInfo.CurrentCulture, selectedLanguageText.FlowDirection,
                new Typeface(selectedLanguageText.FontFamily, selectedLanguageText.FontStyle, selectedLanguageText.FontWeight, selectedLanguageText.FontStretch),
                selectedLanguageText.FontSize, selectedLanguageText.Foreground, VisualTreeHelper.GetDpi(selectedLanguageText).PixelsPerDip);
            Rect languageContentSlot = System.Windows.Controls.Primitives.LayoutInformation.GetLayoutSlot(languageContent);
            double availableLanguageWidth = languageContentSlot.Width - languageContent.Margin.Left - languageContent.Margin.Right;
            if (availableLanguageWidth < languageRequired.WidthIncludingTrailingWhitespace) { throw new InvalidOperationException($"Selected English language label exceeds its layout slot: available={availableLanguageWidth}, required={languageRequired.WidthIncludingTrailingWhitespace}."); }
            AssertElementWithinAncestor("Selected language", selectedLanguageText, languageChrome);
            model.Shell.SelectedLanguageOption = model.Shell.LanguageOptions.Single(option => option.Language == OpenVisionLanguage.Korean);
            Pump(4);
            if (!ReferenceEquals(language.SelectedItem, model.Shell.SelectedLanguageOption)) { throw new InvalidOperationException("Language ViewModel did not restore the control selection."); }
            Menu menu = FindVisualChildren<Menu>(window).First(item => AutomationProperties.GetAutomationId(item) == "WorkbenchMainMenu");
            if (menu.Items.Count != 6 || !ReferenceEquals(menu.DataContext, model)) { throw new InvalidOperationException("Chrome menu context/headers were not wired."); }
            foreach (MenuItem item in menu.Items)
            {
                if (string.IsNullOrEmpty(item.Header?.ToString()) || item.Header.ToString()!.StartsWith("Workbench.", StringComparison.Ordinal)) { throw new InvalidOperationException("Untranslated menu header."); }
                item.IsSubmenuOpen = true;
                try { AssertWorkbenchMenuPopup(item); }
                finally { item.IsSubmenuOpen = false; }
            }
            ExecuteWorkbenchKey(host, Key.D1, ModifierKeys.Control);
            Pump(4); AssertNear(left.ActualWidth, 48D, "collapsed left");
            ExecuteWorkbenchKey(host, Key.D2, ModifierKeys.Control);
            Pump(4); AssertNear(right.ActualWidth, 0D, "collapsed right");
            ExecuteWorkbenchKey(host, Key.D3, ModifierKeys.Control);
            Pump(4); AssertNear(bottom.ActualHeight, 36D, "collapsed bottom");
            model.ResetLayoutCommand.Execute(null); Pump(4);
            AssertNear(left.ActualWidth, expectedLeft, "reset left");
            AssertNear(right.ActualWidth, expectedRight, "reset right");
            AssertNear(bottom.ActualHeight, expectedBottom, "reset bottom");
            left.SetCurrentValue(ColumnDefinition.WidthProperty, new GridLength(310D));
            right.SetCurrentValue(ColumnDefinition.WidthProperty, new GridLength(500D));
            bottom.SetCurrentValue(RowDefinition.HeightProperty, new GridLength(220D));
            host.UpdateLayout();
            GridSplitter splitter = FindVisualChildren<GridSplitter>(host).First(item => AutomationProperties.GetAutomationId(item) == "WorkbenchLeftSplitter");
            splitter.RaiseEvent(new System.Windows.Controls.Primitives.DragCompletedEventArgs(0D, 0D, false));
            Pump(4);
            if (!BindingOperations.IsDataBound(left, ColumnDefinition.WidthProperty)) { throw new InvalidOperationException("Splitter removed layout binding."); }
            global.System.LoadConfig();
            using (OpenVisionWorkbenchViewModel restored = new(global.System.WorkbenchLayoutPreferences, _ => true))
            {
                restored.UpdateViewport(width, height);
                AssertNear(global.System.WorkbenchLayoutPreferences.WorkbenchLeftWidth, 310D, "requested left persisted");
                AssertNear(global.System.WorkbenchLayoutPreferences.WorkbenchRightWidth, 500D, "requested right persisted");
                AssertNear(restored.LeftPanelWidth.Value, Math.Min(310D, width - 12D - 480D - 480D), "reopened left display");
                AssertNear(restored.RightPanelWidth.Value, Math.Min(500D, width - 12D - restored.LeftPanelWidth.Value - 480D), "reopened right display");
                AssertNear(restored.BottomPanelHeight.Value, 220D, "reopened bottom");
            }
            model.OpenLogCommand.Execute(null); Pump(8);
            LogPanelView log = FindVisualChildren<LogPanelView>(host).Single();
            if (!log.IsVisible || model.SelectedBottomTab != 2 || model.IsBottomCollapsed) { throw new InvalidOperationException("Bottom Log tab did not show existing log control."); }
            model.SelectedBottomTab = 0; Pump(4);
            if (log.IsVisible) { throw new InvalidOperationException("Log stayed visible after tab switch."); }
            OpenVisionLanguageService.SetLanguage(OpenVisionLanguage.English, false); Pump(4);
            if (((MenuItem)menu.Items[0]).Header?.ToString() != "File") { throw new InvalidOperationException("Menu failed language update."); }
            OpenVisionLanguageService.SetLanguage(OpenVisionLanguage.Korean, false); Pump(4);
            if (host.NativePreviewRunCount != runs || host.LayerDocumentCount != layerCount || host.WorkspaceLayerTitle != active || host.DirectResultRouteText != route)
            {
                throw new InvalidOperationException("Menu/layout/restore/language produced an execution, layer or route side effect.");
            }
            model.ResetLayoutCommand.Execute(null); Pump(4);
            OpenVisionLayerViewerView[] inputPanes = FindVisualChildren<OpenVisionLayerViewerView>(host).Where(pane => pane.IsVisible && pane.MainPane?.Source == "follow:in").ToArray();
            if (inputPanes.Length == 0) { throw new InvalidOperationException("Current input pane did not render."); }
            foreach (OpenVisionLayerViewerView pane in inputPanes)
            {
                foreach ((string actionId, ICommand command) in new[] { ("MainPaneEmptyOpenImage", host.WorkspaceCommands.LoadImageCommand), ("MainPaneEmptyOpenFolder", host.WorkspaceCommands.OpenFolderCommand), ("MainPaneEmptyOpenSamples", host.WorkspaceCommands.OpenSampleCommand) })
                {
                    Button action = FindVisualChildren<Button>(pane).Single(button => AutomationProperties.GetAutomationId(button) == actionId);
                    if (!action.IsVisible || !ReferenceEquals(action.Command, command)) { throw new InvalidOperationException(actionId + " lost its visible input command."); }
                    AssertElementWithinAncestor(actionId, action, pane);
                }
            }
            if (width <= 1360)
            {
                model.ToggleToolPanelWideCommand.Execute(null); Pump(4);
                ScrollViewer toolbar = FindNamedVisualChild<ScrollViewer>(host, "workbenchViewerToolbarScroll")!;
                Button finalAction = FindVisualChildren<Button>(host).Single(button => AutomationProperties.GetAutomationId(button) == "MainImageNext");
                bool toolbarOverflows = toolbar.ScrollableWidth > 0D;
                if (toolbarOverflows)
                {
                    toolbar.ScrollToRightEnd(); Pump(4);
                    System.Windows.Controls.Primitives.ScrollBar horizontalBar = FindVisualChildren<System.Windows.Controls.Primitives.ScrollBar>(toolbar).Single(item => item.Orientation == Orientation.Horizontal && ReferenceEquals(item.TemplatedParent, toolbar));
                    toolbar.ScrollToLeftEnd(); Pump(4);
                    System.Windows.Controls.Primitives.ScrollBar.PageRightCommand.Execute(null, horizontalBar); Pump(4);
                    if (toolbar.HorizontalOffset <= 0D) { throw new InvalidOperationException("Toolbar horizontal scrollbar command does not move the viewport."); }
                    toolbar.ScrollToRightEnd(); Pump(4);
                    Rect barBounds = horizontalBar.TransformToAncestor(toolbar).TransformBounds(new Rect(0D, 0D, horizontalBar.ActualWidth, horizontalBar.ActualHeight));
                    File.WriteAllText(Path.ChangeExtension(outputPath, ".toolbar.json"), JsonSerializer.Serialize(new { toolbar.ActualHeight, toolbar.ViewportHeight, toolbar.ViewportWidth, toolbar.ScrollableWidth, BarWidth = horizontalBar.ActualWidth, BarHeight = horizontalBar.ActualHeight, horizontalBar.MinHeight, BarLeft = barBounds.Left, BarRight = barBounds.Right, BarTop = barBounds.Top, BarBottom = barBounds.Bottom, horizontalBar.Opacity }, new JsonSerializerOptions { WriteIndented = true }));
                    if (horizontalBar.ActualWidth < toolbar.ViewportWidth - 1D) { throw new InvalidOperationException("Toolbar horizontal scrollbar is narrower than the viewport."); }
                    if (!horizontalBar.IsVisible || barBounds.Bottom > toolbar.ActualHeight + 1D || toolbar.ViewportHeight + horizontalBar.ActualHeight > toolbar.ActualHeight + 1D) { throw new InvalidOperationException("Compact toolbar clips or overlaps its horizontal scrollbar."); }
                    Thumb scrollThumb = FindVisualChildren<Thumb>(horizontalBar).Single();
                    Track scrollTrack = FindVisualChildren<Track>(horizontalBar).Single();
                    Rect thumbBounds = scrollThumb.TransformToAncestor(toolbar).TransformBounds(new Rect(scrollThumb.RenderSize));
                    Rect trackBounds = scrollTrack.TransformToAncestor(toolbar).TransformBounds(new Rect(scrollTrack.RenderSize));
                    Point thumbCenter = new Point(thumbBounds.Left + thumbBounds.Width / 2D, thumbBounds.Top + thumbBounds.Height / 2D);
                    File.WriteAllText(Path.ChangeExtension(outputPath, ".thumb.json"), JsonSerializer.Serialize(new { ThumbLeft=thumbBounds.Left, ThumbTop=thumbBounds.Top, ThumbRight=thumbBounds.Right, ThumbBottom=thumbBounds.Bottom, TrackLeft=trackBounds.Left, TrackTop=trackBounds.Top, TrackRight=trackBounds.Right, TrackBottom=trackBounds.Bottom, scrollThumb.IsVisible, scrollThumb.Opacity, Background=scrollThumb.Background?.ToString(), Hit=toolbar.InputHitTest(thumbCenter)?.GetType().Name, DecreaseHeight=scrollTrack.DecreaseRepeatButton?.ActualHeight, IncreaseHeight=scrollTrack.IncreaseRepeatButton?.ActualHeight }, new JsonSerializerOptions { WriteIndented = true }));
                    if (thumbBounds.Top < barBounds.Top - 1D || thumbBounds.Bottom > barBounds.Bottom + 1D) { throw new InvalidOperationException("Toolbar scroll thumb extends outside the horizontal scrollbar."); }
                    if (scrollThumb.ActualHeight < 6D || scrollThumb.ActualWidth < 20D) { throw new InvalidOperationException("Toolbar horizontal scroll thumb is not visible."); }
                    Point finalBottom = finalAction.TranslatePoint(new Point(finalAction.ActualWidth, finalAction.ActualHeight), toolbar);
                    if (finalBottom.X > toolbar.ActualWidth + 1D || finalBottom.X < 0D || finalBottom.Y > toolbar.ViewportHeight + 1D)
                    {
                        throw new InvalidOperationException("Compact wide inspector still clips the final toolbar action.");
                    }
                }
                else
                {
                    if (toolbar.HorizontalOffset != 0D || !finalAction.IsVisible) { throw new InvalidOperationException("Fitted Compact toolbar hides its last image command or retains a scroll offset."); }
                    AssertElementWithinAncestor("Fitted Compact last image command", finalAction, toolbar);
                    File.WriteAllText(Path.ChangeExtension(outputPath, ".toolbar.json"), JsonSerializer.Serialize(new { toolbar.ActualWidth, toolbar.ActualHeight, toolbar.ViewportWidth, toolbar.ViewportHeight, toolbar.ScrollableWidth, toolbar.HorizontalOffset, LastAction = AutomationProperties.GetAutomationId(finalAction), LastActionVisible = finalAction.IsVisible, Cases = "natural fitted toolbar; scrollbar is required only for overflowing content" }));
                }
                if (host.NativePreviewRunCount != runs || host.LayerDocumentCount != layerCount || host.WorkspaceLayerTitle != active || host.DirectResultRouteText != route)
                {
                    throw new InvalidOperationException("Toolbar scrolling caused an inspection, layer or route change.");
                }
                model.ResetLayoutCommand.Execute(null); toolbar.ScrollToLeftEnd(); Pump(4);
            }
            string ownedInput = Path.ChangeExtension(outputPath, ".owned-input.png");
            using (Bitmap input = new(32, 24)) { using Graphics graphics = Graphics.FromImage(input); graphics.Clear(DrawingColor.FromArgb(128, 128, 128)); input.Save(ownedInput, ImageFormat.Png); }
            if (!host.LoadMainImageFromFileForTest(ownedInput)) { throw new InvalidOperationException("Layout owned image did not load."); }
            model.Tool.ConfigureAutoRunPreference(() => false, _ => { });
            model.Pipeline.InsertStep(0, VisionPipelineStepBuilder.FromProperty(new MeanProperty { NAME = "Layout Mean", USE_ROI = false, USE_THRESHOLD = false, MEAN_MIN = 0, MEAN_MAX = 255 }, "Main", "Layout_Out"));
            host.RecipeCommands.SaveRecipeCommand.Execute(null);
            if (host.RecipeCommands.HasRecipeSaveFailure) { throw new InvalidOperationException("Layout owned recipe save precondition failed."); }
            model.Pipeline.SelectStepCommand.Execute(0); Pump(4);
            WaitForTaskWithPump(model.Pipeline.RunForTestAsync(), 10000, "layout explicit Mean run"); Pump(4);
            double average = model.Tool.CurrentResult?.Metrics?.TryGetValue("MeanValueAvg", out double meanValue) == true ? meanValue : double.NaN;
            if (average != 128D) { throw new InvalidOperationException("Layout independent gray128 result precondition failed."); }
            SimplePreprocessToolWpfView editorView = (SimplePreprocessToolWpfView)host.ActiveNativeDocumentForTest!.View;
            FindNamedVisualChild<Slider>(editorView, "sliderMeanMin")!.Value = 150D; Pump(4);
            if (editorView.Parameters.GetInt("MeanMin", -1) != 150 || !model.Tool.IsChanged) { throw new InvalidOperationException("Layout unsaved Mean150 precondition failed."); }
            OpenVisionNativeToolDocument document = host.ActiveNativeDocumentForTest;
            object retainedResult = model.Tool.CurrentResult!;
            string recipe = host.RecipeCommands.SelectedRecipeName, pipeline = model.Pipeline.SelectedPipelineName;
            byte[] working = VisionPipelineExecutionPlan.SerializePipeline(model.Pipeline.WorkingCopyForTest);
            string savedPath = RecipeWorkspaceService.GetVisionPipelinePath(recipe, pipeline);
            byte[] savedBytes = File.ReadAllBytes(savedPath);
            string inputPixels = VisionPipelineScaleCalibrationStorage.ComputeBitmapSha256(display.GetLayerImage("Main"));
            string ReadOutputPixels()
            {
                if (!model.Pipeline.TryAcquireResultSnapshot("Layout_Out", out Bitmap snapshot)) { throw new InvalidOperationException("Layout result snapshot did not exist."); }
                using (snapshot) { return VisionPipelineScaleCalibrationStorage.ComputeBitmapSha256(snapshot); }
            }
            string outputPixels = ReadOutputPixels();
            int retainedRuns = host.NativePreviewRunCount, retainedDocumentRuns = document.PreviewRunCount, retainedLayers = host.LayerDocumentCount;
            string retainedActive = host.WorkspaceLayerTitle, retainedRoute = host.DirectResultRouteText;
            List<object> retention = new();
            model.LeftPanelWidth = new GridLength(320D); model.RightPanelWidth = new GridLength(620D); model.BottomPanelHeight = new GridLength(600D);
            foreach (string theme in new[] { "Dark", "Light" })
            {
                (theme == "Dark" ? model.SelectDarkThemeCommand : model.SelectLightThemeCommand).Execute(null);
                foreach ((int nextWidth, int nextHeight) in new[] { (1920, 1032), (1536, 826), (1280, 760), (1920, 1032) })
                {
                    window.Width = nextWidth; window.Height = nextHeight; Pump(6);
                    ExecuteWorkbenchKey(host, Key.D1, ModifierKeys.Control); ExecuteWorkbenchKey(host, Key.D2, ModifierKeys.Control); ExecuteWorkbenchKey(host, Key.D3, ModifierKeys.Control); Pump(2);
                    ExecuteWorkbenchKey(host, Key.D1, ModifierKeys.Control); ExecuteWorkbenchKey(host, Key.D2, ModifierKeys.Control); ExecuteWorkbenchKey(host, Key.D3, ModifierKeys.Control); Pump(4);
                    model.CommitLayoutCommand.Execute(null);
                    global.System.LoadConfig();
                    AssertNear(global.System.WorkbenchLayoutPreferences.WorkbenchLeftWidth, 320D, "actual resize requested left");
                    AssertNear(global.System.WorkbenchLayoutPreferences.WorkbenchRightWidth, 620D, "actual resize requested right");
                    AssertNear(global.System.WorkbenchLayoutPreferences.WorkbenchBottomHeight, 600D, "actual resize requested bottom");
                    Grid center = FindVisualChildren<Grid>(host).Single(grid => AutomationProperties.GetAutomationId(grid) == "WorkbenchCenterPanel");
                    if (center.ActualWidth < 480D) { throw new InvalidOperationException("Layout lost central480 reserve."); }
                    if (recipe != host.RecipeCommands.SelectedRecipeName || pipeline != model.Pipeline.SelectedPipelineName || model.Pipeline.SelectedStepIndex != 0 || !ReferenceEquals(document, host.ActiveNativeDocumentForTest) || editorView.Parameters.GetInt("MeanMin", -1) != 150 || !ReferenceEquals(retainedResult, model.Tool.CurrentResult) || !working.SequenceEqual(VisionPipelineExecutionPlan.SerializePipeline(model.Pipeline.WorkingCopyForTest)) || !savedBytes.SequenceEqual(File.ReadAllBytes(savedPath))) { throw new InvalidOperationException("Layout changed recipe/step/editor/value/result or saved work."); }
                    if (inputPixels != VisionPipelineScaleCalibrationStorage.ComputeBitmapSha256(display.GetLayerImage("Main")) || outputPixels != ReadOutputPixels() || retainedRuns != host.NativePreviewRunCount || retainedDocumentRuns != document.PreviewRunCount || retainedLayers != host.LayerDocumentCount || retainedActive != host.WorkspaceLayerTitle || retainedRoute != host.DirectResultRouteText) { throw new InvalidOperationException("Layout changed image/result pixels or execution/layer/routing state."); }
                    retention.Add(new { theme, nextWidth, nextHeight, Left = left.ActualWidth, Right = right.ActualWidth, Bottom = bottom.ActualHeight, Center = center.ActualWidth, RequestedLeft = global.System.WorkbenchLayoutPreferences.WorkbenchLeftWidth, RequestedRight = global.System.WorkbenchLayoutPreferences.WorkbenchRightWidth, RequestedBottom = global.System.WorkbenchLayoutPreferences.WorkbenchBottomHeight, MeanMin = editorView.Parameters.GetInt("MeanMin", -1), ResultMean = average, retainedRuns, retainedDocumentRuns, retainedLayers, retainedActive, retainedRoute });
                }
            }
            model.ResetLayoutCommand.Execute(null); window.Width = width; window.Height = height; model.SelectDarkThemeCommand.Execute(null); Pump(6);
            if (!ReferenceEquals(document, host.ActiveNativeDocumentForTest) || !ReferenceEquals(retainedResult, model.Tool.CurrentResult) || editorView.Parameters.GetInt("MeanMin", -1) != 150 || model.Viewer.IsSplit2 != true || host.NativePreviewRunCount != retainedRuns || host.LayerDocumentCount != retainedLayers || host.WorkspaceLayerTitle != retainedActive || host.DirectResultRouteText != retainedRoute) { throw new InvalidOperationException("Reset changed retained teaching context."); }
            File.WriteAllText(Path.ChangeExtension(outputPath, ".retention.json"), JsonSerializer.Serialize(retention, new JsonSerializerOptions { WriteIndented = true }));
            File.WriteAllText(Path.ChangeExtension(outputPath, ".layout.json"), JsonSerializer.Serialize(new { width, height, left = left.ActualWidth, right = right.ActualWidth, bottom = bottom.ActualHeight, runs, layerCount, active, route, NativeDpi = VisualTreeHelper.GetDpi(window).PixelsPerInchX, LanguageWidth = language.ActualWidth, LanguageHeight = language.ActualHeight, EnglishRequiredWidth = languageRequired.WidthIncludingTrailingWhitespace, LanguageContentWidth = languageContent.ActualWidth, LanguageContentAvailableWidth = availableLanguageWidth, Cases = "default,key collapse,reset,splitter binding,SYSTEM XML reopen,log tab,language,no side effects" }, new JsonSerializerOptions { WriteIndented = true }));
        });
    }

    private static void ExecuteWorkbenchKey(OpenVisionShellHostView host, Key key, ModifierKeys modifiers)
    {
        KeyBinding binding = host.InputBindings.OfType<KeyBinding>().Single(item => item.Key == key && item.Modifiers == modifiers);
        if (!binding.Command.CanExecute(binding.CommandParameter)) { throw new InvalidOperationException("Layout keyboard command disabled."); }
        binding.Command.Execute(binding.CommandParameter);
    }

    private static void AssertNear(double actual, double expected, string label)
    {
        if (Math.Abs(actual - expected) > 1D) { throw new InvalidOperationException($"{label}: {actual:0.##}, expected {expected:0.##}."); }
    }

    private static CaptureResult CaptureWorkbenchToolTip(string outputPath)
    {
        OpenVisionShellHostWindow window = new(new ApplicationRuntimeContext(new GlobalState(), new DisplayManagerService()));
        return CaptureStandaloneWindow(window, outputPath, 1600, 900, () =>
        {
            TextBlock title = FindVisualChildren<TextBlock>(window).Single(item => AutomationProperties.GetAutomationId(item) == "WorkbenchDocumentTitle");
            ToolTip tooltip = title.ToolTip as ToolTip ?? throw new InvalidOperationException("Workbench document tooltip was not explicitly themed.");
            tooltip.PlacementTarget = title; tooltip.IsOpen = true; Pump(6);
            try
            {
                if (tooltip.Content?.ToString() != window.ShellHostForSmoke.Workbench.DocumentTitle) { throw new InvalidOperationException("Document tooltip lost its view-model title binding."); }
                Border chrome = FindVisualChildren<Border>(tooltip).Single();
                AssertBrushContrast(tooltip.Foreground, chrome.Background, "Workbench tooltip title");
                SolidColorBrush expected = (SolidColorBrush)window.FindResource("OpenVision.Workbench.RaisedBrush");
                if (((SolidColorBrush)chrome.Background).Color != expected.Color) { throw new InvalidOperationException("Document tooltip leaks a platform background."); }
                ScreenshotPngWriter.WriteVisibleElementPng(tooltip, Path.ChangeExtension(outputPath, ".tooltip.png"));
            }
            finally { tooltip.IsOpen = false; }
            OpenVisionWorkbenchViewModel model = window.ShellHostForSmoke.Workbench;
            ComboBox language = FindVisualChildren<ComboBox>(window).Single(item => AutomationProperties.GetAutomationId(item) == "WorkbenchLanguage");
            ToolTip languageTip = language.ToolTip as ToolTip ?? throw new InvalidOperationException("Language tooltip was not explicitly themed.");
            int runs = window.ShellHostForSmoke.NativePreviewRunCount;
            int layers = window.ShellHostForSmoke.LayerDocumentCount;
            string route = window.ShellHostForSmoke.DirectResultRouteText;
            List<object> languageMeasurements = new();
            ResourceDictionary themeOwner = window.Resources.MergedDictionaries.Single(dictionary => dictionary.Source?.OriginalString.EndsWith("OpenVisionLabWpfTheme.xaml", StringComparison.Ordinal) == true);
            OpenVisionWindowTitleBar titleBar = FindVisualChildren<OpenVisionWindowTitleBar>(window).Single();
            foreach (string theme in new[] { "Dark", "Light" })
            {
                ResourceDictionary resources = new() { Source = new Uri($"/OpenVisionLab;component/UI/Wpf/OpenVisionWorkbench{theme}.xaml", UriKind.Relative) };
                themeOwner.MergedDictionaries.Add(resources);
                ResourceDictionary headerResources = new() { Source = resources.Source };
                titleBar.Resources.MergedDictionaries.Add(headerResources);
                try
                {
                    foreach (OpenVisionLanguage locale in new[] { OpenVisionLanguage.Korean, OpenVisionLanguage.English })
                    foreach ((int width, int height) in new[] { (1920, 1032), (1280, 760) })
                    {
                        window.Width = width; window.Height = height;
                        model.Shell.SelectedLanguageOption = model.Shell.LanguageOptions.Single(option => option.Language == locale);
                        Pump(4);
                        languageTip.PlacementTarget = language; languageTip.IsOpen = true; Pump(6);
                        try
                        {
                            if (languageTip.Content?.ToString() != model["Menu.Language.ToolTip"]) { throw new InvalidOperationException("Language tooltip lost its localized binding."); }
                            Border chrome = FindVisualChildren<Border>(languageTip).Single();
                            SolidColorBrush expected = (SolidColorBrush)resources["OpenVision.Workbench.RaisedBrush"];
                            if (((SolidColorBrush)language.FindResource("OpenVision.Workbench.RaisedBrush")).Color != expected.Color) { throw new InvalidOperationException("Language tooltip fixture did not reach its title-bar theme owner."); }
                            File.WriteAllText(Path.ChangeExtension(outputPath, ".language-tooltip-observed.json"), JsonSerializer.Serialize(new { theme, locale = locale.ToString(), width, Expected = expected.Color.ToString(), Actual = chrome.Background?.ToString(), Content = languageTip.Content?.ToString(), DataContext = languageTip.DataContext?.GetType().FullName }, new JsonSerializerOptions { WriteIndented = true }));
                            if (chrome.Background is not SolidColorBrush actual || actual.Color.A != 255 || actual.Color != expected.Color) { throw new InvalidOperationException($"Language tooltip leaks a platform background: {theme}/{locale}/{width}, expected {expected.Color}, actual {chrome.Background}."); }
                            AssertBrushContrast(languageTip.Foreground, chrome.Background, "Workbench language tooltip text");
                            TextBlock caption = FindVisualChildren<TextBlock>(languageTip).Single(item => item.Text == model["Menu.Language.ToolTip"]);
                            AssertElementWithinAncestor("Language tooltip caption", caption, chrome);
                            string capture = Path.ChangeExtension(outputPath, $".language-tooltip-{theme}-{locale}-{width}.png");
                            ScreenshotPngWriter.WriteVisibleElementPng(languageTip, capture);
                            languageMeasurements.Add(new { theme, Language = locale.ToString(), width, height, Text = caption.Text, languageTip.ActualWidth, languageTip.ActualHeight, Background = actual.Color.ToString(), Foreground = languageTip.Foreground.ToString(), Contrast = GetContrastRatio(((SolidColorBrush)languageTip.Foreground).Color, actual.Color), Dpi = VisualTreeHelper.GetDpi(languageTip).PixelsPerInchX, Capture = capture });
                        }
                        finally { languageTip.IsOpen = false; }
                    }
                }
                finally { titleBar.Resources.MergedDictionaries.Remove(headerResources); themeOwner.MergedDictionaries.Remove(resources); }
            }
            model.Shell.SelectedLanguageOption = model.Shell.LanguageOptions.Single(option => option.Language == OpenVisionLanguage.Korean);
            window.Width = 1600; window.Height = 900; Pump(4);
            if (window.ShellHostForSmoke.NativePreviewRunCount != runs || window.ShellHostForSmoke.LayerDocumentCount != layers || window.ShellHostForSmoke.DirectResultRouteText != route) { throw new InvalidOperationException("Language tooltip rendering changed execution, layers or routing."); }
            File.WriteAllText(Path.ChangeExtension(outputPath, ".language-tooltip.json"), JsonSerializer.Serialize(languageMeasurements, new JsonSerializerOptions { WriteIndented = true }));
        });
    }

    private static CaptureResult CaptureWorkbenchViewerToolbarContrast(string outputPath, int width, int height)
    {
        OpenVisionLanguageService.SetLanguage(OpenVisionLanguage.Korean, false);
        OpenVisionShellHostView host = CreateShellHost("Smoke_WorkbenchToolbarContrast", seedMainLayer: false);
        List<string> checks = new();
        return CaptureWindowWithContent(host, outputPath, width, height, () =>
        {
            int runs = host.NativePreviewRunCount;
            int layers = host.LayerDocumentCount;
            string activeLayer = host.ActiveRecipeContextLayerNameForTest;
            ScrollViewer toolbar = FindNamedVisualChild<ScrollViewer>(host, "workbenchViewerToolbarScroll")!;
            MenuItem menu = FindNamedVisualChild<MenuItem>(host, "workbenchLayerMenu")!;
            foreach (bool light in new[] { false, true })
            {
                host.Resources.MergedDictionaries.Add(new ResourceDictionary
                {
                    Source = new Uri("pack://application:,,,/OpenVisionLab;component/UI/Wpf/OpenVisionWorkbench" + (light ? "Light" : "Dark") + ".xaml")
                });
                foreach (OpenVisionLanguage language in new[] { OpenVisionLanguage.Korean, OpenVisionLanguage.English })
                {
                    OpenVisionLanguageService.SetLanguage(language, false);
                    Pump(8);
                    Grid chrome = FindVisualChildren<Grid>(toolbar).First(item => ReferenceEquals(item.TemplatedParent, toolbar));
                    if (chrome.Background is not SolidColorBrush background || background.Color.A != 255
                        || host.FindResource("OpenVision.Workbench.PanelBrush") is not SolidColorBrush panel || background.Color != panel.Color)
                        throw new InvalidOperationException("Viewer toolbar template did not render the opaque semantic panel background.");
                    string header = Convert.ToString(menu.Header) ?? string.Empty;
                    FrameworkElement? caption = FindVisualChildren<TextBlock>(menu).FirstOrDefault(item => item.Text == header);
                    caption ??= FindVisualChildren<AccessText>(menu).FirstOrDefault(item => item.Text == header);
                    if (caption == null || !caption.IsVisible || System.Windows.Documents.TextElement.GetForeground(caption) is not SolidColorBrush foreground)
                        throw new InvalidOperationException("Viewer layer menu caption was not rendered.");
                    double contrast = GetContrastRatio(foreground.Color, background.Color);
                    if (contrast < 4.5D) throw new InvalidOperationException("Viewer layer menu text contrast is below 4.5:1: " + contrast.ToString("0.00", CultureInfo.InvariantCulture));
                    Rect captionBounds = caption.TransformToAncestor(menu).TransformBounds(new Rect(0D, 0D, caption.ActualWidth, caption.ActualHeight));
                    if (captionBounds.Left < -1D || captionBounds.Right > menu.ActualWidth + 1D || captionBounds.Bottom > menu.ActualHeight + 1D)
                        throw new InvalidOperationException("Viewer layer menu caption was clipped.");
                    RenderTargetBitmap pixels = new((int)toolbar.ActualWidth, (int)toolbar.ActualHeight, 96D, 96D, PixelFormats.Pbgra32);
                    pixels.Render(toolbar);
                    byte[] pixel = new byte[4];
                    pixels.CopyPixels(new Int32Rect(2, 2, 1, 1), pixel, 4, 0);
                    if (pixel[0] != background.Color.B || pixel[1] != background.Color.G || pixel[2] != background.Color.R || pixel[3] != 255)
                        throw new InvalidOperationException("Viewer toolbar rendered pixel does not match its template background.");
                    if (toolbar.ScrollableWidth > 0D)
                    {
                        toolbar.ScrollToRightEnd(); Pump(4);
                        Button finalAction = FindVisualChildren<Button>(host).Single(button => AutomationProperties.GetAutomationId(button) == "HostTopDeleteLayerButton");
                        Rect finalBounds = finalAction.TransformToAncestor(toolbar).TransformBounds(new Rect(0D, 0D, finalAction.ActualWidth, finalAction.ActualHeight));
                        if (finalBounds.Left < -1D || finalBounds.Right > toolbar.ActualWidth + 1D)
                            throw new InvalidOperationException("Viewer final layer action is unreachable after horizontal scrolling.");
                        toolbar.ScrollToLeftEnd(); Pump(4);
                    }
                    if (host.NativePreviewRunCount != runs || host.LayerDocumentCount != layers || host.ActiveRecipeContextLayerNameForTest != activeLayer)
                        throw new InvalidOperationException("Theme/language/toolbar scrolling changed execution or layers.");
                    checks.Add($"PASS: {width}x{height}/{(light ? "Light" : "Dark")}/{language}; rendered panel pixel; caption {contrast:0.00}:1; visible; toolbar reachability; no execution/layer change.");
                    ScreenshotPngWriter.WriteElementPng(host, Path.ChangeExtension(outputPath, $".{(light ? "light" : "dark")}.{language}.png"), width, height);
                }
            }
            OpenVisionLanguageService.SetLanguage(OpenVisionLanguage.Korean, false);
            File.WriteAllLines(Path.ChangeExtension(outputPath, ".checks.txt"), checks);
        });
    }

    private static CaptureResult CaptureWorkbenchViewerFit(string outputPath, int width, int height)
    {
        OpenVisionLanguageService.SetLanguage(OpenVisionLanguage.Korean, false);
        OpenVisionShellHostView host = CreateShellHost("Smoke_WorkbenchViewerFit", seedMainLayer: false);
        List<object> cases = new();
        return CaptureWindowWithContent(host, outputPath, width, height, () =>
        {
            using (OpenVisionLayerViewerView emptyViewer = new())
            {
                emptyViewer.FitImageToView();
                if (emptyViewer.HasImage) throw new InvalidOperationException("Fit created an image in an empty viewer.");
            }
            ScrollViewer toolbar = FindNamedVisualChild<ScrollViewer>(host, "workbenchViewerToolbarScroll")!;
            Button fit = FindNamedVisualChild<Button>(host, "btnWorkbenchFitImage")!;
            foreach (bool light in new[] { false, true })
            {
                host.Resources.MergedDictionaries.Add(new ResourceDictionary { Source = new Uri("pack://application:,,,/OpenVisionLab;component/UI/Wpf/OpenVisionWorkbench" + (light ? "Light" : "Dark") + ".xaml") });
                CommandManager.InvalidateRequerySuggested(); Pump(8);
                if (fit.IsEnabled || host.WorkspaceCommands.FitImageCommand.CanExecute(null))
                    throw new InvalidOperationException("Fit is enabled without an image.");
                ScreenshotPngWriter.WriteElementPng(host, Path.ChangeExtension(outputPath, $".{(light ? "light" : "dark")}.empty.png"), width, height);
            }
            using Bitmap input = new(640, 360);
            using (Graphics graphics = Graphics.FromImage(input))
            {
                graphics.Clear(System.Drawing.Color.FromArgb(32, 48, 71));
                graphics.FillRectangle(System.Drawing.Brushes.Turquoise, 20, 20, 260, 140);
                graphics.FillEllipse(System.Drawing.Brushes.Orange, 360, 25, 220, 220);
            }
            string inputPath = Path.ChangeExtension(outputPath, ".owned.png");
            input.Save(inputPath, System.Drawing.Imaging.ImageFormat.Png);
            if (!host.LoadMainImageFromFileForTest(inputPath) || !host.AddLayerImageForTest("FitOther", input) || !host.DockLayerForTest("FitOther"))
                throw new InvalidOperationException("Fit image/second document fixture could not be prepared.");
            if (!host.ActivateDockedLayerForTest("FitOther")) throw new InvalidOperationException("Fit inactive document setup could not be activated.");
            Pump(8);
            OpenVisionLayerViewerView other = FindVisualChildren<OpenVisionLayerViewerView>(host).Single(view => view.IsVisible && view.LayerTitle == "FitOther");
            if (!host.ActivateDockedLayerForTest("Main")) throw new InvalidOperationException("Fit Main document could not be activated.");
            Pump(8);
            OpenVisionLayerViewerView viewer = FindVisualChildren<OpenVisionLayerViewerView>(host).Single(view => view.IsVisible && view.LayerTitle == "Main");
            Image image = FindNamedVisualChild<Image>(viewer, "layerFallbackImage")!;
            TransformGroup transform = (TransformGroup)image.RenderTransform;
            ScaleTransform scale = transform.Children.OfType<ScaleTransform>().Single();
            TranslateTransform pan = transform.Children.OfType<TranslateTransform>().Single();
            Image otherImage = FindNamedVisualChild<Image>(other, "layerFallbackImage")!;
            ScaleTransform otherScale = ((TransformGroup)otherImage.RenderTransform).Children.OfType<ScaleTransform>().Single();
            otherScale.ScaleX = otherScale.ScaleY = 1.7D;
            var workspaceCanvas = FindNamedVisualChild<OpenVisionLab.ImageCanvas.Views.RoiImageCanvasView>(host, "hostWorkspaceCanvas")!;
            var canvas = (OpenVisionLab.ImageCanvas.ViewModels.RoiImageCanvasViewModel)workspaceCanvas.DataContext;
            var dockCanvas = (OpenVisionLab.ImageCanvas.ViewModels.RoiImageCanvasViewModel)FindNamedVisualChild<OpenVisionLab.ImageCanvas.Views.RoiImageCanvasView>(viewer, "layerCanvas")!.DataContext;
            int runs = host.NativePreviewRunCount, layers = host.LayerDocumentCount, documents = host.DockedLayerCount;
            string active = host.WorkspaceLayerTitle, route = host.DirectResultRouteText;
            foreach (bool light in new[] { false, true })
            {
                host.Resources.MergedDictionaries.Add(new ResourceDictionary { Source = new Uri("pack://application:,,,/OpenVisionLab;component/UI/Wpf/OpenVisionWorkbench" + (light ? "Light" : "Dark") + ".xaml") });
                foreach (OpenVisionLanguage language in new[] { OpenVisionLanguage.Korean, OpenVisionLanguage.English })
                {
                    OpenVisionLanguageService.SetLanguage(language, false);
                    CommandManager.InvalidateRequerySuggested(); toolbar.ScrollToLeftEnd(); Pump(8);
                    TextBlock label = FindNamedVisualChild<TextBlock>(fit, "txtWorkbenchFitImageText")!;
                    string expectedLabel = language == OpenVisionLanguage.Korean ? "맞춤" : "Fit";
                    if (!fit.IsEnabled || !host.WorkspaceCommands.FitImageCommand.CanExecute(null) || AutomationProperties.GetName(fit) != expectedLabel || label.Text != expectedLabel)
                        throw new InvalidOperationException("Fit loaded command or localized caption/name is inconsistent.");
                    if (label.IsVisible != (width > 1360)) throw new InvalidOperationException("Fit Wide/Compact caption visibility is inconsistent.");
                    if (FindVisualChildren<MahApps.Metro.IconPacks.PackIconMaterial>(fit).Single().Kind != MahApps.Metro.IconPacks.PackIconMaterialKind.FitToScreenOutline)
                        throw new InvalidOperationException("Fit does not use the canonical screen-fit icon.");
                    AssertElementWithinAncestor("Fit initial toolbar position", fit, toolbar);
                    if (label.IsVisible) AssertElementWithinAncestor("Fit caption", label, fit);
                    double contrast = GetContrastRatio(((SolidColorBrush)fit.Foreground).Color, ((SolidColorBrush)FindVisualChildren<Border>(fit).Single(border => border.Name == "buttonChrome").Background).Color);
                    if (contrast < 4.5D) throw new InvalidOperationException("Fit rendered caption/icon contrast is below 4.5:1.");
                    string routeBeforeFit = host.DirectResultRouteText;
                    var fitted = canvas.CaptureViewState();
                    var dockFitted = dockCanvas.CaptureViewState();
                    canvas.ApplyViewState(new OpenVisionLab.ImageCanvas.Canvas.CanvasViewState(fitted.Zoom * 1.5F, fitted.OffsetSize));
                    dockCanvas.ApplyViewState(new OpenVisionLab.ImageCanvas.Canvas.CanvasViewState(dockFitted.Zoom * 1.5F, dockFitted.OffsetSize));
                    scale.ScaleX = scale.ScaleY = 1.5D; pan.X = 31D; pan.Y = -23D;
                    otherScale.ScaleX = otherScale.ScaleY = 1.7D;
                    host.WorkspaceCommands.FitImageCommand.Execute(null); Pump(4);
                    if (scale.ScaleX != 1D || scale.ScaleY != 1D || pan.X != 0D || pan.Y != 0D || otherScale.ScaleX != 1D || otherScale.ScaleY != 1D
                        || Math.Abs(canvas.CaptureViewState().Zoom - fitted.Zoom) > 0.001F || Math.Abs(dockCanvas.CaptureViewState().Zoom - dockFitted.Zoom) > 0.001F)
                        throw new InvalidOperationException("Fit did not restore all docked image fallback/canvas states.");
                    host.WorkspaceCommands.FitImageCommand.Execute(null); Pump(4);
                    File.WriteAllText(Path.ChangeExtension(outputPath, ".fit-state.json"), JsonSerializer.Serialize(new { Language=language.ToString(), Root=new { runs, layers, documents, active, route }, BeforeFit=new { Route=routeBeforeFit }, AfterFit=new { Runs=host.NativePreviewRunCount, Layers=host.LayerDocumentCount, Documents=host.DockedLayerCount, Active=host.WorkspaceLayerTitle, Route=host.DirectResultRouteText, scale.ScaleX, pan.X, pan.Y, InactiveScale=otherScale.ScaleX } }, new JsonSerializerOptions { WriteIndented = true }));
                    if (scale.ScaleX != 1D || pan.X != 0D || otherScale.ScaleX != 1D || host.NativePreviewRunCount != runs || host.LayerDocumentCount != layers || host.DockedLayerCount != documents || host.WorkspaceLayerTitle != active || host.DirectResultRouteText != routeBeforeFit)
                        throw new InvalidOperationException("Repeated Fit changed execution, documents, selection or route.");
                    cases.Add(new { Width=width, Height=height, Theme=light ? "Light" : "Dark", Language=language.ToString(), State="Loaded", Status="PASS", Label=label.Text, label.IsVisible, Contrast=contrast, scale.ScaleX, pan.X, pan.Y, InactiveScale=otherScale.ScaleX, runs, layers, documents, active, RootRoute=route, RouteBeforeFit=routeBeforeFit, RouteAfterFit=host.DirectResultRouteText, EvidenceKind="in-process WPF; command invocation; synthetic zoom state; not actual pointer input" });
                    File.WriteAllText(Path.ChangeExtension(outputPath, ".fit-cases.json"), JsonSerializer.Serialize(cases, new JsonSerializerOptions { WriteIndented = true }));
                    ScreenshotPngWriter.WriteElementPng(host, Path.ChangeExtension(outputPath, $".{(light ? "light" : "dark")}.{language}.png"), width, height);
                }
            }
            host.ClearDockedLayersForTest(); Pump(8);
            if (!host.WorkspaceCommands.FitImageCommand.CanExecute(null)) throw new InvalidOperationException("Fit fallback command is disabled after clearing documents while retaining Main.");
            var fallbackFitted = canvas.CaptureViewState();
            canvas.ApplyViewState(new OpenVisionLab.ImageCanvas.Canvas.CanvasViewState(fallbackFitted.Zoom * 1.5F, fallbackFitted.OffsetSize));
            host.WorkspaceCommands.FitImageCommand.Execute(null); Pump(4);
            if (Math.Abs(canvas.CaptureViewState().Zoom - fallbackFitted.Zoom) > 0.001F || host.NativePreviewRunCount != runs || host.LayerDocumentCount != layers || host.DockedLayerCount != 0)
                throw new InvalidOperationException("Fit did not restore the existing single canvas without inspection or document creation.");
            cases.Add(new { Width=width, Height=height, State="Single workspace after explicit document clear", Status="PASS", Runs=host.NativePreviewRunCount, Layers=host.LayerDocumentCount, Documents=host.DockedLayerCount, EvidenceKind="in-process WPF; command invocation; synthetic canvas zoom" });
            ScreenshotPngWriter.WriteElementPng(host, Path.ChangeExtension(outputPath, ".single.png"), width, height);
            OpenVisionLanguageService.SetLanguage(OpenVisionLanguage.Korean, false);
            File.WriteAllText(Path.ChangeExtension(outputPath, ".fit-cases.json"), JsonSerializer.Serialize(cases, new JsonSerializerOptions { WriteIndented = true }));
        });
    }

    private static CaptureResult CaptureWorkbenchViewerZoom(string outputPath, int width, int height)
    {
        OpenVisionLanguageService.SetLanguage(OpenVisionLanguage.Korean, false);
        OpenVisionShellHostView host = CreateShellHost("Smoke_WorkbenchViewerZoom", seedMainLayer: false);
        List<object> cases = new();
        IOpenVisionDockedLayerWorkspaceCommands viewport = ReadPrivateField<ShellDockedLayerWorkspaceComposition>(host, "dockedLayerWorkspaceComposition")!.Commands;
        return CaptureWindowWithContent(host, outputPath, width, height, () =>
        {
            ScrollViewer toolbar = FindNamedVisualChild<ScrollViewer>(host, "workbenchViewerToolbarScroll")!;
            Button minus = FindNamedVisualChild<Button>(host, "btnWorkbenchZoomOut")!;
            Button plus = FindNamedVisualChild<Button>(host, "btnWorkbenchZoomIn")!;
            Button original = FindNamedVisualChild<Button>(host, "btnWorkbenchOriginalSize")!;
            Button fit = FindNamedVisualChild<Button>(host, "btnWorkbenchFitImage")!;
            TextBlock percentage = FindNamedVisualChild<TextBlock>(host, "txtWorkbenchZoom")!;
            void Record(string state, object detail) => cases.Add(new { Width=width, Height=height, State=state, Status="PASS", Detail=detail, EvidenceKind="in-process WPF; commands/synthetic wheel state; not actual pointer/native DPI/HTML" });
            void AssertScale(OpenVisionLayerViewerView view, double expected, string name)
            {
                Image image = FindNamedVisualChild<Image>(view, "layerFallbackImage")!;
                GeneralTransform transform = image.TransformToAncestor(host);
                Point a = transform.Transform(new Point(0D, 0D)), b = transform.Transform(new Point(image.ActualWidth, 0D));
                double displayedPixelsPerDip = Math.Abs(b.X - a.X) / 640D;
                if (Math.Abs(view.ZoomScale - expected) > 0.00001D || Math.Abs(displayedPixelsPerDip - expected) > 0.00001D)
                    throw new InvalidOperationException(name + " differs from rendered image width / 640 source pixels.");
            }
            foreach (bool light in new[] { false, true })
            {
                host.Resources.MergedDictionaries.Add(new ResourceDictionary { Source = new Uri("pack://application:,,,/OpenVisionLab;component/UI/Wpf/OpenVisionWorkbench" + (light ? "Light" : "Dark") + ".xaml") });
                CommandManager.InvalidateRequerySuggested(); Pump(6);
                if (minus.IsEnabled || plus.IsEnabled || original.IsEnabled || percentage.Text != "100%")
                    throw new InvalidOperationException("Empty viewer enables zoom or loses the canonical default 100% label.");
                Record("Empty", new { Theme=light ? "Light" : "Dark", percentage.Text, minus.IsEnabled, DefaultNotMeasured=true });
                ScreenshotPngWriter.WriteElementPng(host, Path.ChangeExtension(outputPath, $".{(light ? "light" : "dark")}.empty.png"), width, height);
            }
            using Bitmap input = new(640, 360);
            using (Graphics graphics = Graphics.FromImage(input))
            {
                graphics.Clear(System.Drawing.Color.FromArgb(32, 48, 71));
                graphics.FillRectangle(System.Drawing.Brushes.Turquoise, 20, 20, 260, 140);
                graphics.FillEllipse(System.Drawing.Brushes.Orange, 360, 25, 220, 220);
            }
            string inputPath = Path.ChangeExtension(outputPath, ".owned.png");
            input.Save(inputPath, System.Drawing.Imaging.ImageFormat.Png);
            if (!host.LoadMainImageFromFileForTest(inputPath) || !host.AddLayerImageForTest("ZoomOther", input) || !host.DockLayerForTest("ZoomOther") || !viewport.ActivateLayerDocument("ZoomOther"))
                throw new InvalidOperationException("Zoom two-document input could not be prepared.");
            Pump(6);
            OpenVisionLayerViewerView other = FindVisualChildren<OpenVisionLayerViewerView>(host).Single(view => view.IsVisible && view.LayerTitle == "ZoomOther");
            other.ShowOriginalSize(); other.ZoomImage(1.25D);
            if (!viewport.ActivateLayerDocument("Main")) throw new InvalidOperationException("Main activation failed.");
            Pump(6);
            OpenVisionLayerViewerView viewer = FindVisualChildren<OpenVisionLayerViewerView>(host).Single(view => view.IsVisible && view.LayerTitle == "Main");
            int runs = host.NativePreviewRunCount, layers = host.LayerDocumentCount, documents = host.DockedLayerCount;
            string selected = host.WorkspaceLayerTitle, route = host.DirectResultRouteText;
            foreach (bool light in new[] { false, true })
            {
                host.Resources.MergedDictionaries.Add(new ResourceDictionary { Source = new Uri("pack://application:,,,/OpenVisionLab;component/UI/Wpf/OpenVisionWorkbench" + (light ? "Light" : "Dark") + ".xaml") });
                foreach (OpenVisionLanguage language in new[] { OpenVisionLanguage.Korean, OpenVisionLanguage.English })
                {
                    OpenVisionLanguageService.SetLanguage(language, false); toolbar.ScrollToLeftEnd(); Pump(6);
                    string currentRoute = host.DirectResultRouteText;
                    host.WorkspaceCommands.OriginalSizeImageCommand.Execute(null); Pump(3);
                    AssertScale(viewer, 1D, "1:1");
                    if (percentage.Text != "100%" || !original.IsEnabled || (string)original.Content != "1:1"
                        || AutomationProperties.GetName(original) != (language == OpenVisionLanguage.Korean ? "원본 크기" : "Original size"))
                        throw new InvalidOperationException("Original-size caption, live percent or command state is inconsistent.");
                    host.WorkspaceCommands.ZoomInImageCommand.Execute(null); Pump(3);
                    AssertScale(viewer, 1.25D, "Zoom in");
                    if (percentage.Text != "125%") throw new InvalidOperationException("Plus did not notify rendered 125%.");
                    host.WorkspaceCommands.ZoomOutImageCommand.Execute(null); Pump(3);
                    AssertScale(viewer, 1D, "Zoom out");
                    if (percentage.Text != "100%" || Math.Abs(other.ZoomScale - 1.25D) > 0.00001D)
                        throw new InvalidOperationException($"Minus or inactive-document independence failed: percent={percentage.Text}, Main={viewer.ZoomScale}, inactive={other.ZoomScale}, size={FindNamedVisualChild<Image>(other, "layerFallbackImage")!.RenderSize}, Language={language}, Light={light}.");
                    bool showZoom = host.ActualWidth + 2D > 1360D && toolbar.ActualWidth - 20D > 680D;
                    foreach (Button button in new[] { minus, plus, original })
                    {
                        if (button.Visibility != (showZoom ? Visibility.Visible : Visibility.Collapsed)) throw new InvalidOperationException("Zoom visibility differs from the canonical viewport/content-width rules.");
                        if (showZoom) AssertElementWithinAncestor("zoom toolbar", button, toolbar);
                    }
                    AssertElementWithinAncestor("Fit toolbar", fit, toolbar);
                    AssertElementWithinAncestor("zoom percentage", percentage, toolbar);
                    double previousRight = double.MinValue;
                    foreach (FrameworkElement element in new FrameworkElement[] { minus, percentage, plus, fit, original }.Where(element => element.IsVisible))
                    {
                        Point position = element.TranslatePoint(new Point(), toolbar);
                        if (position.X < previousRight) throw new InvalidOperationException("Canonical minus/percent/plus/Fit/1:1 order overlaps.");
                        previousRight = position.X + element.ActualWidth;
                    }
                    foreach (Button button in new[] { minus, plus, original }.Where(button => button.IsVisible))
                    {
                        Border chrome = FindVisualChildren<Border>(button).Single(border => border.Name == "buttonChrome");
                        if (GetContrastRatio(((SolidColorBrush)button.Foreground).Color, ((SolidColorBrush)chrome.Background).Color) < 4.5D)
                            throw new InvalidOperationException("Zoom button caption/icon contrast is below 4.5:1.");
                    }
                    if (host.NativePreviewRunCount != runs || host.LayerDocumentCount != layers || host.DockedLayerCount != documents || host.WorkspaceLayerTitle != selected || host.DirectResultRouteText != currentRoute)
                        throw new InvalidOperationException("Zoom changed execution, documents, inspection selection or route.");
                    (showZoom ? original : fit).Focus(); Pump(2);
                    if (!(showZoom ? original.IsKeyboardFocused : fit.IsKeyboardFocused)) throw new InvalidOperationException("Visible zoom/Fit focus could not be restored.");
                    Record("Loaded 1:1 -> + -> -; focused", new { Theme=light ? "Light" : "Dark", Language=language.ToString(), percentage.Text, viewer.ZoomScale, InactiveZoom=other.ZoomScale, runs, layers, documents, selected, Route=currentRoute, showZoom, original.IsKeyboardFocused, FitFocused=fit.IsKeyboardFocused });
                    ScreenshotPngWriter.WriteElementPng(host, Path.ChangeExtension(outputPath, $".{(light ? "light" : "dark")}.{language}.png"), width, height);
                }
            }
            viewport.ActivateLayerDocument("ZoomOther"); Pump(4);
            if (percentage.Text != "125%") throw new InvalidOperationException("Active document switch did not update the percentage.");
            host.WorkspaceCommands.ZoomInImageCommand.Execute(null); Pump(3);
            if (percentage.Text != "156%" || Math.Abs(viewer.ZoomScale - 1D) > 0.00001D)
                throw new InvalidOperationException("Zoom did not follow the actual active document.");
            viewport.ActivateLayerDocument("Main"); Pump(4);
            if (percentage.Text != "100%") throw new InvalidOperationException("Main restore lost its independent zoom.");
            Record("Active-document switch", new { percentage.Text, MainZoom=viewer.ZoomScale, OtherZoom=other.ZoomScale, Selection=host.WorkspaceLayerTitle });
            OpenVisionZoomableImageController controller = ReadPrivateField<OpenVisionZoomableImageController>(viewer, "fallbackImageZoomController");
            controller.ZoomAtForTest(new Point(80D, 60D), 1.2D); Pump(3);
            if (percentage.Text != "120%") throw new InvalidOperationException("Synthetic cursor zoom did not update display.");
            Window window = Window.GetWindow(host);
            double initialWidth = window.Width;
            window.Width = width + 120D; Pump(5);
            AssertScale(viewer, 1.2D, "Resized absolute zoom");
            if (percentage.Text != "120%") throw new InvalidOperationException("Resize changed absolute scale label.");
            window.Width = initialWidth; Pump(5); AssertScale(viewer, 1.2D, "Restored absolute zoom");
            Record("Cursor zoom/resize/restore", new { percentage.Text, viewer.ZoomScale, Width=window.Width });
            for (int i = 0; i < 40; i++) host.WorkspaceCommands.ZoomOutImageCommand.Execute(null);
            Pump(3); AssertScale(viewer, 0.05D, "Canonical minimum");
            if (percentage.Text != "5%") throw new InvalidOperationException("Minimum zoom label differs from canonical .05.");
            for (int i = 0; i < 60; i++) host.WorkspaceCommands.ZoomInImageCommand.Execute(null);
            Pump(3); AssertScale(viewer, 40D, "Canonical maximum");
            if (percentage.Text != "4000%") throw new InvalidOperationException("Maximum zoom label differs from canonical 40.");
            ScreenshotPngWriter.WriteElementPng(host, Path.ChangeExtension(outputPath, ".limit.png"), width, height);
            host.WorkspaceCommands.FitImageCommand.Execute(null); Pump(4);
            Image fitted = FindNamedVisualChild<Image>(viewer, "layerFallbackImage")!;
            ScaleTransform fittedScale = ((TransformGroup)fitted.RenderTransform).Children.OfType<ScaleTransform>().Single();
            Image otherImage = FindNamedVisualChild<Image>(other, "layerFallbackImage")!;
            ScaleTransform otherScale = ((TransformGroup)otherImage.RenderTransform).Children.OfType<ScaleTransform>().Single();
            if (fittedScale.ScaleX != 1D || otherScale.ScaleX != 1D || percentage.Text != host.WorkspaceCommands.ZoomText)
                throw new InvalidOperationException("Fit after absolute zoom did not reset all fitted document transforms and display.");
            Record("5%-4000% limits and all-document Fit recovery", new { percentage.Text, fittedScale.ScaleX, OtherRelativeScale=otherScale.ScaleX });
            // Existing non-Main consumers retain their fitted-relative 1..32 policy.
            Image legacyImage = new() { Source = fitted.Source, Stretch = Stretch.Uniform, Width=200D, Height=120D };
            Grid legacySurface = new() { Width=240D, Height=160D }; legacySurface.Children.Add(legacyImage);
            legacySurface.Measure(new Size(240D,160D)); legacySurface.Arrange(new Rect(0D,0D,240D,160D));
            using (OpenVisionZoomableImageController legacy = new(legacySurface, legacyImage))
            {
                legacy.ZoomAtForTest(new Point(120D,80D), 0.1D);
                ScaleTransform legacyScale = ((TransformGroup)legacyImage.RenderTransform).Children.OfType<ScaleTransform>().Single();
                if (legacyScale.ScaleX != 1D) throw new InvalidOperationException("Default consumer now zooms below fitted size.");
                legacy.ZoomAtForTest(new Point(120D,80D), 100D);
                if (legacyScale.ScaleX != 32D) throw new InvalidOperationException("Default consumer lost its existing maximum 32.");
                legacy.Reset();
            }
            Record("Default shared consumer range", new { Minimum=1, Maximum=32, Scope="isolated WPF image, not full tool UI" });
            int notifications = 0;
            host.WorkspaceCommands.PropertyChanged += (_, _) => notifications++;
            host.WorkspaceCommands.Dispose(); int closedNotifications = notifications;
            viewer.ZoomImage(1.25D); Pump(3);
            if (notifications != closedNotifications) throw new InvalidOperationException("Disposed command surface retained viewer event subscriptions.");
            Record("Event subscription release", new { notifications, closedNotifications });
            OpenVisionLanguageService.SetLanguage(OpenVisionLanguage.Korean, false);
            File.WriteAllText(Path.ChangeExtension(outputPath, ".zoom-cases.json"), JsonSerializer.Serialize(cases, new JsonSerializerOptions { WriteIndented = true }));
        });
    }


    private static CaptureResult CaptureWorkbenchViewerPixelBoundaries(string outputPath)
    {
        Grid root = new();
        root.RowDefinitions.Add(new RowDefinition()); root.RowDefinitions.Add(new RowDefinition());
        root.ColumnDefinitions.Add(new ColumnDefinition()); root.ColumnDefinitions.Add(new ColumnDefinition());
        List<object> cases = new();
        List<Bitmap> bitmaps = new();
        List<OpenVisionZoomableImageController> controllers = new();
        var geometries = new[] { (Width: 640, Height: 360, SurfaceWidth: 377D, SurfaceHeight: 479D), (Width: 641, Height: 361, SurfaceWidth: 377D, SurfaceHeight: 479D), (Width: 360, Height: 640, SurfaceWidth: 479D, SurfaceHeight: 377D), (Width: 361, Height: 641, SurfaceWidth: 479D, SurfaceHeight: 377D) };
        try
        {
            for (int index = 0; index < geometries.Length; index++)
            {
                var geometry = geometries[index];
                Bitmap bitmap = new(geometry.Width, geometry.Height); bitmaps.Add(bitmap);
                for (int y = 0; y < bitmap.Height; y++) for (int x = 0; x < bitmap.Width; x++) bitmap.SetPixel(x, y, DrawingColor.FromArgb(x % 256, y % 256, (x + y) % 256));
                bitmap.Save(Path.ChangeExtension(outputPath, $".input-{index}.png"), ImageFormat.Png);
                Image image = new() { Source = OpenVisionBitmapImagePreviewFactory.Create(bitmap), Stretch = Stretch.Uniform };
                Grid surface = new() { Width = geometry.SurfaceWidth, Height = geometry.SurfaceHeight }; surface.Children.Add(image);
                Grid.SetRow(surface, index / 2); Grid.SetColumn(surface, index % 2); root.Children.Add(surface);
                OpenVisionZoomableImageController controller = new(surface, image, usePixelZoomRange: true);
                controller.SetStatusBitmap(bitmap); controllers.Add(controller);
            }
            return CaptureWindowWithContent(root, outputPath, 1040, 1000, () =>
            {
                void Record() => File.WriteAllText(Path.ChangeExtension(outputPath, ".pixel-cases.json"), JsonSerializer.Serialize(cases, new JsonSerializerOptions { WriteIndented = true }));
                for (int index = 0; index < geometries.Length; index++)
                {
                    var geometry = geometries[index]; Bitmap bitmap = bitmaps[index]; OpenVisionZoomableImageController controller = controllers[index];
                    Grid surface = (Grid)root.Children[index]; Image image = (Image)surface.Children[0];
                    Rect ImageRect() => (Rect)typeof(OpenVisionZoomableImageController).GetMethod("GetDisplayedImageRect", BindingFlags.Instance | BindingFlags.NonPublic)!.Invoke(controller, null)!;
                    Point Input(double sourceX, double sourceY)
                    {
                        Rect rect = ImageRect();
                        return image.TransformToAncestor(surface).Transform(new Point(rect.Left + sourceX * rect.Width / bitmap.Width, rect.Top + sourceY * rect.Height / bitmap.Height));
                    }
                    void Check(string id, Point input, int expectedX, int expectedY, bool expectedPixel = true)
                    {
                        bool found = controller.TryGetPointerStatusForTest(input, out OpenVisionZoomableImageStatus actual);
                        int red = expectedX % 256, green = expectedY % 256, blue = (expectedX + expectedY) % 256;
                        int gray = (int)Math.Round(red * 0.299D + green * 0.587D + blue * 0.114D);
                        bool pass = found == expectedPixel && actual.HasPixel == expectedPixel && (!expectedPixel || actual.ImageX == expectedX && actual.ImageY == expectedY && actual.Red == red && actual.Green == green && actual.Blue == blue && actual.GrayValue == gray);
                        Rect? diagnosticRect = ReadPrivateField<Bitmap>(controller, "statusBitmap") != null ? ImageRect() : null;
                        cases.Add(new { Case = id, Geometry = new { geometry.Width, geometry.Height, geometry.SurfaceWidth, geometry.SurfaceHeight }, Input = input, Expected = new { HasPixel = expectedPixel, X = expectedX, Y = expectedY, R = red, G = green, B = blue, GV = gray }, Actual = actual, DisplayedImage = diagnosticRect, SurfaceDisplayedImage = diagnosticRect.HasValue ? (Rect?)image.TransformToAncestor(surface).TransformBounds(diagnosticRect.Value) : null, Transform = image.TransformToAncestor(surface) is Transform affine ? affine.Value : Matrix.Identity, Status = pass ? "PASS" : "FAIL", EvidenceKind = "in-process WPF; independently fixed source pixel indices and coordinate-coded RGB; no native pointer/DPI claim" });
                        Record();
                        if (!pass) throw new InvalidOperationException($"Pixel boundary {index}/{id}: expected {expectedX},{expectedY}/{expectedPixel}, actual {actual.ImageX},{actual.ImageY}/{found}.");
                    }
                    void CheckSource(string id, double sourceX, double sourceY, int expectedX, int expectedY) => Check(id, Input(sourceX, sourceY), expectedX, expectedY);
                    int middleX = bitmap.Width / 2, middleY = bitmap.Height / 2;
                    foreach (string state in new[] { "fit", "zoom", "pan", "fit-recovery" })
                    {
                        if (state == "zoom") controller.ZoomAtForTest(new Point(surface.ActualWidth / 2D, surface.ActualHeight / 2D), 1.25D);
                        if (state == "pan") controller.PanByForTest(24D, -18D);
                        if (state == "fit-recovery") controller.Reset();
                        CheckSource(state + "/pixel-center", middleX + 0.5D, middleY + 0.5D, middleX, middleY);
                        CheckSource(state + "/integer-below", 20.75D, 179.75D, 20, 179);
                        CheckSource(state + "/integer-above", 21.25D, 180.25D, 21, 180);
                        CheckSource(state + "/first-pixel", 0.25D, 0.25D, 0, 0);
                        CheckSource(state + "/last-pixel", bitmap.Width - 0.25D, bitmap.Height - 0.25D, bitmap.Width - 1, bitmap.Height - 1);
                        CheckSource(state + "/left-edge-inclusive", 0D, middleY + 0.5D, 0, middleY);
                        CheckSource(state + "/right-edge-inclusive", bitmap.Width, middleY + 0.5D, bitmap.Width - 1, middleY);
                        Check(state + "/outside-left", Input(-0.25D, middleY + 0.5D), 0, 0, false);
                        Check(state + "/outside-bottom", Input(middleX + 0.5D, bitmap.Height + 0.25D), 0, 0, false);
                    }
                    controller.Reset();
                    if (index == 0)
                    {
                        Point center = new(surface.ActualWidth / 2D, surface.ActualHeight / 2D);
                        Check("377x479/640x360/exact-center-before", center, 320, 180);
                        controller.ZoomAtForTest(center, 1.25D); Check("377x479/640x360/exact-center-after", center, 320, 180); controller.Reset();
                        controller.ZoomAtForTest(center, 0.0001D);
                        string minimum = (controller.PixelZoomScale * 100D).ToString("0", CultureInfo.InvariantCulture);
                        controller.ZoomAtForTest(center, 1000000D);
                        string maximum = (controller.PixelZoomScale * 100D).ToString("0", CultureInfo.InvariantCulture);
                        if (minimum != "5" || maximum != "4000") throw new InvalidOperationException("Shared Main pixel zoom limits changed.");
                        controller.Reset(); CheckSource("range-fit-recovery", 21.25D, 180.25D, 21, 180);
                        cases.Add(new { Case = "Main-pixel-zoom-range", MinimumPercent = minimum, MaximumPercent = maximum, Status = "PASS" }); Record();
                    }
                    foreach (var transform in new[] { (Id: "mirror", Value: new Matrix(-1D, 0D, 0D, 1D, 0D, 0D)), (Id: "rotation", Value: new Matrix(0D, 1D, -1D, 0D, 0D, 0D)), (Id: "skew", Value: new Matrix(1D, 0.2D, 0.15D, 1D, 0D, 0D)) })
                    {
                        image.LayoutTransform = new MatrixTransform(transform.Value); root.UpdateLayout(); Pump(2);
                        CheckSource(transform.Id + "/existing-inverse-path", 21.25D, 180.25D, 21, 180);
                    }
                    image.LayoutTransform = Transform.Identity; root.UpdateLayout(); Pump(2);
                    image.Visibility = Visibility.Hidden; Check("hidden", new Point(0D, 0D), 0, 0, false);
                    image.Visibility = Visibility.Visible; controller.SetStatusBitmap(null); Check("empty-bitmap", new Point(0D, 0D), 0, 0, false);
                    controller.SetStatusBitmap(bitmap); image.Source = null; Check("empty-source", new Point(0D, 0D), 0, 0, false);
                    image.Source = OpenVisionBitmapImagePreviewFactory.Create(bitmap); root.UpdateLayout(); Pump(2); controller.Reset();
                    CheckSource("empty-hidden-recovery", 21.25D, 180.25D, 21, 180);
                    controller.Dispose(); Check("disposed", new Point(0D, 0D), 0, 0, false);
                    _ = bitmap.GetPixel(21, 180); // The borrowed bitmap remains owned by the fixture.
                }
            });
        }
        finally
        {
            foreach (OpenVisionZoomableImageController controller in controllers) controller.Dispose();
            foreach (Bitmap bitmap in bitmaps) bitmap.Dispose();
        }
    }


    private static CaptureResult CaptureWorkbenchViewerResponsive(string outputPath)
    {
        OpenVisionLanguageService.SetLanguage(OpenVisionLanguage.Korean, false);
        OpenVisionShellHostView host = CreateShellHost("Smoke_WorkbenchViewerResponsive", seedMainLayer: false);
        List<object> cases = new();
        return CaptureWindowWithContent(host, outputPath, 1920, 1032, () =>
        {
            Window window = Window.GetWindow(host);
            ScrollViewer toolbar = FindNamedVisualChild<ScrollViewer>(host, "workbenchViewerToolbarScroll")!;
            Button minus = FindNamedVisualChild<Button>(host, "btnWorkbenchZoomOut")!;
            Button plus = FindNamedVisualChild<Button>(host, "btnWorkbenchZoomIn")!;
            Button original = FindNamedVisualChild<Button>(host, "btnWorkbenchOriginalSize")!;
            Button fit = FindNamedVisualChild<Button>(host, "btnWorkbenchFitImage")!;
            TextBlock caption = FindNamedVisualChild<TextBlock>(host, "txtWorkbenchFitImageText")!;
            TextBlock percentage = FindNamedVisualChild<TextBlock>(host, "txtWorkbenchZoom")!;
            void SetViewport(double expected)
            {
                window.Width += expected - (host.ActualWidth + 2D); Pump(8);
                if (Math.Abs(host.ActualWidth + 2D - expected) > 0.01D) throw new InvalidOperationException("Responsive viewport boundary could not be arranged.");
            }
            void SetContentWidth(double expected)
            {
                host.Workbench.LeftPanelWidth = new GridLength(host.Workbench.LeftPanelWidth.Value + toolbar.ActualWidth - 20D - expected); Pump(8);
                if (Math.Abs(toolbar.ActualWidth - 20D - expected) > 0.01D) throw new InvalidOperationException("Responsive toolbar content boundary could not be arranged.");
            }
            void Check(string id, bool expectedCaption, bool expectedZoom, string theme, OpenVisionLanguage language, bool loaded)
            {
                toolbar.ScrollToLeftEnd(); CommandManager.InvalidateRequerySuggested(); Pump(3);
                if (caption.IsVisible != expectedCaption || host.Workbench.ShowViewerFitCaption != expectedCaption || host.Workbench.ShowViewerZoomControls != expectedZoom)
                    throw new InvalidOperationException(id + " caption or presentation state differs from canonical CSS.");
                foreach (Button button in new[] { minus, plus, original })
                {
                    if (button.Visibility != (expectedZoom ? Visibility.Visible : Visibility.Collapsed) || button.IsEnabled != loaded)
                        throw new InvalidOperationException(id + " zoom visibility or command state changed.");
                    if (expectedZoom) AssertElementWithinAncestor(id, button, toolbar);
                }
                if (!fit.IsVisible || fit.IsEnabled != loaded || !percentage.IsVisible || percentage.Text != host.WorkspaceCommands.ZoomText)
                    throw new InvalidOperationException(id + " hid the persistent Fit/percentage or lost live zoom binding.");
                AssertElementWithinAncestor(id + " Fit", fit, toolbar); AssertElementWithinAncestor(id + " percent", percentage, toolbar);
                if (expectedCaption) AssertElementWithinAncestor(id + " caption", caption, fit);
                foreach (string name in new[] { "workbenchLayerMenu", "cbHostLayer", "txtHostTopLayerNameEditor", "btnHostRenameLayer", "btnHostCreateLayer", "btnHostLoadImageIntoLayer", "btnHostDeleteLayer" })
                    if (FindNamedVisualChild<FrameworkElement>(host, name)?.Visibility != Visibility.Visible) throw new InvalidOperationException(id + " removed an existing layer control.");
                cases.Add(new { Id=id, Status="PASS", Theme=theme, Language=language.ToString(), Loaded=loaded, ViewportDip=host.ActualWidth+2D, ToolbarDip=toolbar.ActualWidth, ContentDip=toolbar.ActualWidth-20D, Caption=caption.IsVisible, Zoom=expectedZoom, percentage.Text, Runs=host.NativePreviewRunCount, host.LayerDocumentCount, host.DockedLayerCount, host.WorkspaceLayerTitle, Route=host.DirectResultRouteText, EvidenceKind="in-process WPF; actual arranged SizeChanged/bindings; programmatic focus; no actual pointer/native DPI/HTML" });
                File.WriteAllText(Path.ChangeExtension(outputPath, ".responsive-cases.json"), JsonSerializer.Serialize(cases, new JsonSerializerOptions { WriteIndented=true }));
                ScreenshotPngWriter.WriteElementPng(host, Path.ChangeExtension(outputPath, "." + id + ".png"), (int)host.ActualWidth, (int)host.ActualHeight);
            }
            SetViewport(1920D); SetContentWidth(861D);
            Check("empty-wide", true, true, "Dark", OpenVisionLanguage.Korean, false);
            SetViewport(1280D);
            Check("empty-compact", false, false, "Dark", OpenVisionLanguage.Korean, false);
            using Bitmap input = new(640, 360);
            using (Graphics graphics = Graphics.FromImage(input)) { graphics.Clear(System.Drawing.Color.DarkSlateBlue); graphics.FillRectangle(System.Drawing.Brushes.Turquoise, 20, 20, 240, 140); }
            string inputPath = Path.ChangeExtension(outputPath, ".owned.png"); input.Save(inputPath, System.Drawing.Imaging.ImageFormat.Png);
            if (!host.LoadMainImageFromFileForTest(inputPath)) throw new InvalidOperationException("Responsive valid input could not be prepared.");
            Pump(8); host.WorkspaceCommands.OriginalSizeImageCommand.Execute(null); Pump(3);
            int runs = host.NativePreviewRunCount, layers = host.LayerDocumentCount, documents = host.DockedLayerCount;
            string selected = host.WorkspaceLayerTitle;
            foreach (bool light in new[] { false, true })
            {
                string theme = light ? "Light" : "Dark";
                OpenVisionLanguage language = light ? OpenVisionLanguage.English : OpenVisionLanguage.Korean;
                host.Resources.MergedDictionaries.Add(new ResourceDictionary { Source = new Uri("pack://application:,,,/OpenVisionLab;component/UI/Wpf/OpenVisionWorkbench" + theme + ".xaml") });
                OpenVisionLanguageService.SetLanguage(language, false); Pump(6);
                string route = host.DirectResultRouteText;
                SetViewport(1920D);
                foreach (double content in new[] { 861D, 860D, 681D, 680D, 861D })
                {
                    SetContentWidth(content);
                    if (content == 861D && !original.Focus()) throw new InvalidOperationException("Responsive original-size focus could not be set.");
                    Check(theme + "-content-" + content + "-" + cases.Count, content > 860D, content > 680D, theme, language, true);
                    if (content <= 680D && original.IsKeyboardFocused) throw new InvalidOperationException("Collapsed zoom control retained keyboard focus.");
                    if (!fit.Focus()) throw new InvalidOperationException("Persistent Fit focus could not be restored.");
                }
                host.Workbench.IsRightCollapsed = true; host.Workbench.LeftPanelWidth = new GridLength(248D); Pump(6);
                SetViewport(1361D); Check(theme + "-viewport-1361", true, true, theme, language, true);
                SetViewport(1360D); Check(theme + "-viewport-1360", false, false, theme, language, true);
                SetViewport(1280D); Check(theme + "-viewport-1280", false, false, theme, language, true);
                host.Workbench.IsRightCollapsed = false; SetViewport(1920D); SetContentWidth(861D);
                Check(theme + "-restore", true, true, theme, language, true);
                if (host.NativePreviewRunCount != runs || host.LayerDocumentCount != layers || host.DockedLayerCount != documents || host.WorkspaceLayerTitle != selected || host.DirectResultRouteText != route || percentage.Text != "100%")
                    throw new InvalidOperationException("Responsive resize/restoration changed execution, image, selection, route or zoom.");
            }
            OpenVisionLanguageService.SetLanguage(OpenVisionLanguage.Korean, false);
        });
    }

    private static CaptureResult CaptureWorkbenchViewerZoomSingle(string outputPath)
    {
        OpenVisionLanguageService.SetLanguage(OpenVisionLanguage.Korean, false);
        OpenVisionShellHostView host = CreateShellHost("Smoke_WorkbenchViewerZoomSingle", seedMainLayer: false);
        return CaptureWindowWithContent(host, outputPath, 1280, 760, () =>
        {
            using Bitmap input = new(640, 360);
            using (Graphics graphics = Graphics.FromImage(input)) { graphics.Clear(System.Drawing.Color.CadetBlue); }
            string inputPath = Path.ChangeExtension(outputPath, ".owned.png");
            input.Save(inputPath, ImageFormat.Png);
            if (!host.LoadMainImageFromFileForTest(inputPath)) throw new InvalidOperationException("Single zoom input failed.");
            host.ClearDockedLayersForTest(); Pump(6);
            int runs = host.NativePreviewRunCount, layers = host.LayerDocumentCount;
            string selected = host.WorkspaceLayerTitle, route = host.DirectResultRouteText;
            TextBlock percentage = FindNamedVisualChild<TextBlock>(host, "txtWorkbenchZoom")!;
            Image image = FindNamedVisualChild<Image>(host, "hostWorkspaceFallbackImage")!;
            if (host.DockedLayerCount != 0 || !image.IsVisible || !host.WorkspaceCommands.OriginalSizeImageCommand.CanExecute(null))
                throw new InvalidOperationException("Single visible fallback or zoom command is unavailable after document clear.");
            host.WorkspaceCommands.OriginalSizeImageCommand.Execute(null); Pump(3);
            host.WorkspaceCommands.ZoomInImageCommand.Execute(null); Pump(3);
            if (percentage.Text != "125%") throw new InvalidOperationException("Single fallback plus did not notify 125%.");
            host.WorkspaceCommands.ZoomOutImageCommand.Execute(null); Pump(3);
            ScaleTransform scale = ((TransformGroup)image.RenderTransform).Children.OfType<ScaleTransform>().Single();
            if (percentage.Text != "100%" || Math.Abs(image.ActualWidth * scale.ScaleX / 640D - 1D) > 0.00001D)
                throw new InvalidOperationException("Single fallback 1:1 differs from visible DIP/image pixels or bound percent.");
            ScreenshotPngWriter.WriteElementPng(host, Path.ChangeExtension(outputPath, ".original.png"), 1280, 760);
            host.WorkspaceCommands.FitImageCommand.Execute(null); Pump(3);
            if (scale.ScaleX != 1D || percentage.Text != host.WorkspaceCommands.ZoomText || host.NativePreviewRunCount != runs || host.LayerDocumentCount != layers || host.DockedLayerCount != 0 || host.WorkspaceLayerTitle != selected || host.DirectResultRouteText != route)
                throw new InvalidOperationException("Single fallback Fit recovery changed execution, layers, selection, route or display.");
            File.WriteAllText(Path.ChangeExtension(outputPath, ".zoom-single.json"), JsonSerializer.Serialize(new { Status="PASS", Scope="Single visible Main WPF fallback after explicit document clear", Width=1280, Height=760, percentage.Text, scale.ScaleX, runs, layers, Documents=host.DockedLayerCount, selected, route, EvidenceKind="in-process WPF; no actual pointer/native DPI/HTML" }, new JsonSerializerOptions { WriteIndented=true }));
        });
    }

    private static CaptureResult CaptureWorkbenchToolbarResize(string outputPath)
    {
        DisplayManagerService display = new();
        GlobalState global = new();
        global.Recipe.Name = "Smoke_WorkbenchToolbarResize";
        global.System.SaveWorkbenchLayout(new SystemStateConfig { WorkbenchLayoutVersion = 1, WorkbenchRightWidth = 720D });
        OpenVisionShellHostWindow window = new(new ApplicationRuntimeContext(global, display));
        return CaptureStandaloneWindow(window, outputPath, 1600, 900, () =>
        {
            Pump(30);
            ScrollViewer toolbar = FindNamedVisualChild<ScrollViewer>(window, "workbenchViewerToolbarScroll")!;
            window.Width = 1280D; window.Height = 760D; Pump(12);
            ScrollContentPresenter presenter = FindVisualChildren<ScrollContentPresenter>(toolbar).First(item => ReferenceEquals(item.TemplatedParent, toolbar));
            ScrollBar bar = FindVisualChildren<ScrollBar>(toolbar).Single(item => ReferenceEquals(item.TemplatedParent, toolbar));
            File.WriteAllText(Path.ChangeExtension(outputPath, ".resize.json"), JsonSerializer.Serialize(new { window.ActualWidth, window.ActualHeight, ToolbarWidth=toolbar.ActualWidth, toolbar.ExtentWidth, toolbar.ViewportWidth, toolbar.ScrollableWidth, Visibility=toolbar.ComputedHorizontalScrollBarVisibility.ToString(), bar.IsVisible, ContentWidth=((FrameworkElement)toolbar.Content).ActualWidth, ContentDesiredWidth=((FrameworkElement)toolbar.Content).DesiredSize.Width, presenter.CanHorizontallyScroll, PresenterExtent=presenter.ExtentWidth, PresenterViewport=presenter.ViewportWidth }, new JsonSerializerOptions { WriteIndented = true }));
            Thumb thumb = FindVisualChildren<Thumb>(bar).Single();
            Border thumbChrome = FindVisualChildren<Border>(thumb).Single();
            Point hitPoint = new Point(toolbar.ActualWidth - 20D, toolbar.ActualHeight - 5D);
            DependencyObject hit = toolbar.InputHitTest(hitPoint) as DependencyObject;
            string hitPath = string.Empty;
            while (hit is Visual) { hitPath += hit.GetType().Name + "/"; hit = VisualTreeHelper.GetParent(hit); }
            File.WriteAllText(Path.ChangeExtension(outputPath, ".initial-thumb.json"), JsonSerializer.Serialize(new { ThumbBackground=thumb.Background?.ToString(), ChromeBackground=thumbChrome.Background?.ToString(), ChromeWidth=thumbChrome.ActualWidth, ChromeHeight=thumbChrome.ActualHeight, HitPath=hitPath }, new JsonSerializerOptions { WriteIndented = true }));
            if (thumbChrome.Background == null || !hitPath.Contains("RepeatButton", StringComparison.Ordinal)) { throw new InvalidOperationException("Horizontal scrollbar has an invisible initial thumb or misses the page-button hit region."); }
            RenderTargetBitmap toolbarPixels = new((int)toolbar.ActualWidth, (int)toolbar.ActualHeight, 96D, 96D, PixelFormats.Pbgra32);
            toolbarPixels.Render(toolbar);
            byte[] thumbPixel = new byte[4];
            Point thumbCenter = thumb.TranslatePoint(new Point(thumb.ActualWidth / 2D, thumb.ActualHeight / 2D), toolbar);
            toolbarPixels.CopyPixels(new Int32Rect((int)thumbCenter.X, (int)thumbCenter.Y, 1, 1), thumbPixel, 4, 0);
            Color expectedThumb = ((SolidColorBrush)thumbChrome.Background).Color;
            if (thumbPixel[0] != expectedThumb.B || thumbPixel[1] != expectedThumb.G || thumbPixel[2] != expectedThumb.R) { throw new InvalidOperationException("Initial horizontal scroll thumb does not render its semantic field-border color."); }
            ScreenshotPngWriter.WriteElementPng(window, Path.ChangeExtension(outputPath, ".resized.png"), 1280, 760);
            if (toolbar.ScrollableWidth <= 0D || !bar.IsVisible) { throw new InvalidOperationException("Restored wide inspector hides the horizontal scrollbar after native window resize."); }
            window.Width = 1600D; window.Height = 900D; Pump(6);
        });
    }


    private static CaptureResult CaptureApprovedRecipeRevision(string outputPath)
    {
        GlobalState global = new(); global.Recipe.Name = "Smoke_ApprovedRevision_" + Guid.NewGuid().ToString("N");
        string name = global.Recipe.Name;
        Require(global.Recipe.SaveTools(), "seed legacy tools");
        VisionPipelineStorage.Save(name, new VisionPipeline { Name = "Main" }); VisionPipelineStorage.SaveActivePipelineName(name, "Main");
        List<object> cases = new();
        void Require(bool ok, string label) { if (!ok) throw new InvalidOperationException("Saved revision: " + label); }
        void Check(bool ok, string label) { Require(ok, label); cases.Add(new { Case = label, Revision = global.Data.SavedRevision, PASS = true }); File.WriteAllText(Path.ChangeExtension(outputPath, ".checks.json"), JsonSerializer.Serialize(cases)); }
        OpenVisionRecipePendingEditDecision decision = OpenVisionRecipePendingEditDecision.ApplyAndContinue;
        OpenVisionShellHostRecipeCommandSurface recipes = new(() => name, _ => { }, () => { },
            saveRecipe: () => RecipeRuntimeStorage.SaveWithRevision(name, () => global.Data, () => global.VisionTools),
            prepareRecipeSave: () => RecipeRuntimeStorage.PrepareSavedRevision(name, global.Data), savedRevisionProvider: () => global.Data.SavedRevision);
        using DisplayManagerService display = new(); using OpenVisionWorkbenchPipelineViewModel pipeline = new(recipes, display, action => Application.Current.Dispatcher.Invoke(action), _ => decision, _ => true, Array.Empty<OpenVisionShellNavGroup>());
        recipes.AttachWorkbenchPipeline(pipeline);
        int notices = 0; recipes.PropertyChanged += (_, e) => { if (e.PropertyName == nameof(OpenVisionShellHostRecipeCommandSurface.SaveActionKey)) notices++; };
        return CaptureWindowWithContent(new TextBlock { Text = "Persisted recipe revision: legacy / equality / failure / retry / pending Save" }, outputPath, 900, 130, () =>
        {
            Check(global.Data.SavedRevision == 0 && string.IsNullOrEmpty(global.Data.SavedContentHash), "legacy absent metadata r0");
            byte[] legacyData = File.ReadAllBytes(RecipeWorkspaceService.GetVisionDataPath(name));
            pipeline.CanCommitToolEdits = () => false; recipes.SaveRecipeCommand.Execute(null);
            Check(global.Data.SavedRevision == 0 && string.IsNullOrEmpty(global.Data.SavedContentHash) && legacyData.SequenceEqual(File.ReadAllBytes(RecipeWorkspaceService.GetVisionDataPath(name))) && notices == 0, "invalid editor guard precedes legacy bootstrap/no XML publication");
            pipeline.CanCommitToolEdits = () => true;
            recipes.SaveRecipeCommand.Execute(null); Check(global.Data.SavedRevision == 0 && !recipes.HasRecipeSaveFailure, "unchanged legacy save r0");
            VisionPipelineStep initialMean = VisionPipelineStepBuilder.FromProperty(new MeanProperty { NAME = "Mean", USE_ROI = false, USE_THRESHOLD = false, MEAN_MIN = 0, MEAN_MAX = 255 }, "Main", "Out"); initialMean.UseAcceptance = false; pipeline.InsertStep(0, initialMean);
            recipes.SaveRecipeCommand.Execute(null); Check(global.Data.SavedRevision == 1 && !pipeline.IsDirty && !recipes.HasRecipeSaveFailure, "changed whole save r1");
            global.Data = new DataState().LoadConfig(name); Check(global.Data.SavedRevision == 1, "persisted reopen r1");
            recipes.SaveRecipeCommand.Execute(null); Check(global.Data.SavedRevision == 1, "unchanged repeat no increment");
            byte[] beforeRunData = File.ReadAllBytes(RecipeWorkspaceService.GetVisionDataPath(name));
            Bitmap input = new(32, 24); using (Graphics graphics = Graphics.FromImage(input)) { graphics.Clear(DrawingColor.FromArgb(180, 180, 180)); }
            display.CreateLayerDisplay(OpenVisionLab.ImageSpace.Core.ImageSpaceFrame.TakeOwnership(input), "Main"); display.NotifyParameterChanged();
            Check(pipeline.RunCommand.CanExecute(null), "owned valid Mean explicit Run enabled");
            WaitForTaskWithPump(pipeline.RunForTestAsync(), 10000, "revision explicit Run");
            File.WriteAllText(Path.ChangeExtension(outputPath, ".explicit-run.json"), JsonSerializer.Serialize(new { pipeline.SingleRunCompleted, pipeline.SingleRunResultKind, pipeline.StatusText, Revision = global.Data.SavedRevision, MetadataUnchanged = beforeRunData.SequenceEqual(File.ReadAllBytes(RecipeWorkspaceService.GetVisionDataPath(name))), Results = pipeline.Rows.Select(row => new { row.Name, row.ResultStatusKind, row.ResultValueText }) }));
            Check(pipeline.SingleRunCompleted && pipeline.SingleRunResultKind == "Ok" && global.Data.SavedRevision == 1 && beforeRunData.SequenceEqual(File.ReadAllBytes(RecipeWorkspaceService.GetVisionDataPath(name))), "explicit Run completion leaves saved revision metadata unchanged");
            recipes.SaveRecipeCommand.Execute(null); Check(global.Data.SavedRevision == 1, "unchanged save after Run excludes run evidence");
            pipeline.InsertStep(1, new VisionPipelineStep { Name = "Undo", ToolType = "Mean", InputLayer = "Main", OutputLayer = "UndoOut" }); pipeline.UndoCommand.Execute(null);
            recipes.SaveRecipeCommand.Execute(null); Check(global.Data.SavedRevision == 1, "edit then undo content equality no increment");
            pipeline.RedoCommand.Execute(null); int before = notices;
            string toolPath = RecipeWorkspaceService.GetVisionConfigPath(name, "Blob_1");
            using (FileStream locked = new(toolPath, FileMode.Open, FileAccess.Read, FileShare.Read)) { recipes.SaveRecipeCommand.Execute(null); }
            Check(global.Data.SavedRevision == 1 && recipes.HasRecipeSaveFailure && pipeline.IsDirty && notices == before, "tool failure after pipeline publication retains revision and dirty baseline");
            global.Data = new DataState().LoadConfig(name); Check(global.Data.SavedRevision == 1 && !string.IsNullOrEmpty(global.Data.SavedContentHash), "partial publication reopen durable baseline remains r1");
            OpenVisionShellHostRecipeCommandSurface reopened = new(() => name, _ => { }, () => { },
                saveRecipe: () => RecipeRuntimeStorage.SaveWithRevision(name, () => global.Data, () => global.VisionTools),
                prepareRecipeSave: () => RecipeRuntimeStorage.PrepareSavedRevision(name, global.Data));
            using (OpenVisionWorkbenchPipelineViewModel cleanReopen = new(reopened, display, action => action(), _ => OpenVisionRecipePendingEditDecision.Cancel, _ => true, Array.Empty<OpenVisionShellNavGroup>()))
            {
                reopened.AttachWorkbenchPipeline(cleanReopen);
                Check(!cleanReopen.IsDirty && cleanReopen.WorkingCopyForTest.Steps.Count == 2, "partial reopen pipeline already clean/published");
                reopened.SaveRecipeCommand.Execute(null); Check(global.Data.SavedRevision == 2 && !reopened.HasRecipeSaveFailure, "clean reopened copy retry detects durable unsaved difference");
                reopened.DetachWorkbenchPipeline(cleanReopen);
            }
            recipes.SaveRecipeCommand.Execute(null); Check(global.Data.SavedRevision == 2 && !recipes.HasRecipeSaveFailure && !pipeline.IsDirty && notices == before + 1, "failed retry exactly one increment");
            pipeline.InsertStep(2, new VisionPipelineStep { Name = "DataFailure", ToolType = "Mean", InputLayer = "Main", OutputLayer = "DataOut" }); before = notices;
            string dataPath = RecipeWorkspaceService.GetVisionDataPath(name);
            using (FileStream locked = new(dataPath, FileMode.Open, FileAccess.Read, FileShare.Read)) { recipes.SaveRecipeCommand.Execute(null); }
            Check(global.Data.SavedRevision == 2 && recipes.HasRecipeSaveFailure && pipeline.IsDirty && notices == before, "final CData failure rolls back in-memory revision");
            global.Data = new DataState().LoadConfig(name); Check(global.Data.SavedRevision == 2, "final metadata failure reopen previous rN");
            recipes.SaveRecipeCommand.Execute(null); Check(global.Data.SavedRevision == 3 && notices == before + 1 && !pipeline.IsDirty, "metadata retry exactly one increment");
            pipeline.InsertStep(3, new VisionPipelineStep { Name = "PipelineFailure", ToolType = "Mean", InputLayer = "Main", OutputLayer = "PipelineFailureOut" }); before = notices;
            using (FileStream locked = new(RecipeWorkspaceService.GetVisionPipelinePath(name, "Main"), FileMode.Open, FileAccess.Read, FileShare.Read)) { recipes.SaveRecipeCommand.Execute(null); }
            Check(global.Data.SavedRevision == 3 && pipeline.IsDirty && recipes.HasRecipeSaveFailure && notices == before, "pipeline failure emits no revision or success");
            pipeline.UndoCommand.Execute(null); recipes.SaveRecipeCommand.Execute(null);
            Check(global.Data.SavedRevision == 3 && !recipes.HasRecipeSaveFailure, "failed pipeline undone to saved content recovery no increment");
            pipeline.InsertStep(3, new VisionPipelineStep { Name = "Pending", ToolType = "Mean", InputLayer = "Main", OutputLayer = "PendingOut" });
            before = notices;
            using (FileStream locked = new(dataPath, FileMode.Open, FileAccess.Read, FileShare.Read))
            {
                Check(!pipeline.TryLeave(new OpenVisionRecipePendingEditRequest { Kind = OpenVisionRecipePendingEditTransitionKind.Pipeline, TargetName = "Other" }) && global.Data.SavedRevision == 3 && pipeline.IsDirty && notices == before, "pending transition failed Save keeps context/revision/no success");
            }
            Check(pipeline.TryLeave(new OpenVisionRecipePendingEditRequest { Kind = OpenVisionRecipePendingEditTransitionKind.Pipeline, TargetName = "Other" }) && global.Data.SavedRevision == 4 && !pipeline.IsDirty && notices == before + 1, "pending transition Save retry shares full-save rN boundary exactly once");
            pipeline.InsertStep(4, new VisionPipelineStep { Name = "Cancel", ToolType = "Mean", InputLayer = "Main", OutputLayer = "CancelOut" }); decision = OpenVisionRecipePendingEditDecision.Cancel;
            Check(!pipeline.TryLeave(new OpenVisionRecipePendingEditRequest { Kind = OpenVisionRecipePendingEditTransitionKind.Pipeline }) && global.Data.SavedRevision == 4 && pipeline.IsDirty, "pending Cancel does not increment");
            pipeline.UndoCommand.Execute(null);
            string baseline = global.Data.SavedContentHash;
            Directory.CreateDirectory(RecipeWorkspaceService.GetVisionPipelineImageDirectory(name, "Main")); File.WriteAllText(Path.Combine(RecipeWorkspaceService.GetVisionPipelineImageDirectory(name, "Main"), "ignored.txt"), "not recipe content");
            recipes.SaveRecipeCommand.Execute(null); Check(global.Data.SavedRevision == 4 && global.Data.SavedContentHash == baseline, "image/evidence directory excluded from equality");
            foreach (string metadata in new[] { "<SavedRevision>-1</SavedRevision>", "<SavedContentHash>broken</SavedContentHash>", "<SavedRevision>1</SavedRevision>" })
            {
                string invalidRecipe = "Smoke_InvalidRevision_" + Guid.NewGuid().ToString("N");
                string invalidPath = RecipeWorkspaceService.GetVisionDataPath(invalidRecipe);
                File.WriteAllText(invalidPath, "<CData>" + metadata + "</CData>"); byte[] invalidBytes = File.ReadAllBytes(invalidPath);
                DataState fallback = new DataState().LoadConfig(invalidRecipe);
                Check(fallback.SavedRevision == 0 && RecipeDataStorage.TryGetPersistenceState(invalidRecipe, out var failure) && failure.IsFailure && invalidBytes.SequenceEqual(File.ReadAllBytes(invalidPath)), "invalid metadata uses existing load failure/backup contract " + metadata);
                DataState validMetadata = new() { SavedRevision = 2, SavedContentHash = new string('A', 64) }; validMetadata.SaveConfig(invalidRecipe);
                DataState restoredMetadata = new DataState().LoadConfig(invalidRecipe);
                Check(restoredMetadata.SavedRevision == 2 && restoredMetadata.SavedContentHash == new string('A', 64) && (!RecipeDataStorage.TryGetPersistenceState(invalidRecipe, out var restoredState) || !restoredState.IsFailure), "explicit valid metadata reload recovery " + metadata);
            }
            recipes.DetachWorkbenchPipeline(pipeline);
        });
    }

    private static CaptureResult CaptureThresholdInputChrome(string outputPath)
    {
        OpenVisionShellHostView host = CreateShellHost("Smoke_ThresholdInputChrome", true);
        List<object> checks = new();
        void Require(bool passed, string name) { if (!passed) throw new InvalidOperationException("Threshold input: " + name); checks.Add(new { Case = name, PASS = true }); }
        return CaptureWindowWithContent(host, outputPath, 1600, 900, () =>
        {
            host.Workbench.Tool.ConfigureAutoRunPreference(() => false, _ => { }); host.SelectToolForTest(VISION_MENU.Threshold); Pump(8);
            FrameworkElement view = host.ActiveNativeDocumentForTest!.View;
            VisionToolDebouncedPreviewScheduler.SetAllowAutoPreview(view, false);
            FrameworkElement shell = (FrameworkElement)view.FindName("toolShell"), panel = (FrameworkElement)shell.FindName("parameterPanel");
            int runs = host.NativePreviewRunCount, layers = host.LayerDocumentCount; string route = host.DirectResultRouteText;
            object presenter = view.DataContext;
            foreach (string theme in new[] { "Dark", "Light", "Dark" })
            {
                (theme == "Dark" ? host.Workbench.SelectDarkThemeCommand : host.Workbench.SelectLightThemeCommand).Execute(null); Pump(5);
                foreach (string mode in new[] { "Basic", "Range", "Adaptive" })
                {
                    ((RadioButton)view.FindName("rb" + mode)).IsChecked = true; Pump(5);
                    TextBox[] inputs = new[] { "txtThreshold", "txtMaxValue", "txtRangeMin", "txtRangeMax", "txtAdaptiveMaxValue", "txtWeight", "txtBlockSize" }.Select(name => (TextBox)view.FindName(name)).Where(box => box.IsVisible).ToArray();
                    Require(inputs.Length == (mode == "Adaptive" ? 3 : 2), mode + " original numeric fields visible");
                    foreach (int inspector in new[] { 480, 720 })
                    {
                        host.Workbench.RightPanelWidth = new GridLength(inspector); Pump(5);
                        foreach (TextBox box in inputs)
                        {
                            Border chrome = (Border)box.Template.FindName("fieldChrome", box);
                            Rect bounds = box.TransformToAncestor(panel).TransformBounds(new Rect(box.RenderSize));
                            Require(box.ActualWidth == 76D && box.ActualHeight == 29D && box.MinWidth == 72D && chrome.BorderThickness.Left == 1D
                                && bounds.Left >= 0 && bounds.Right <= panel.ActualWidth && GetContrastRatio(((SolidColorBrush)box.Foreground).Color, ((SolidColorBrush)chrome.Background).Color) >= 4.5D, box.Name + " original76/29/min72 editable field has visible semantic chrome inside viewport");
                        }
                        Require(FindVisualChildren<ScrollViewer>(panel).Where(scroll => scroll.IsVisible).All(scroll => scroll.ScrollableWidth <= 1D), "numeric fields remain horizontally reachable");
                        ScreenshotPngWriter.WriteVisibleElementPng(panel, Path.ChangeExtension(outputPath, $".{theme}.{mode}.{inspector}.png"));
                    }
                    TextBox input = inputs[0]; string original = input.Text; BindingExpression binding = input.GetBindingExpression(TextBox.TextProperty)!;
                    string property = mode == "Basic" ? "Threshold" : mode == "Range" ? "RangeMin" : "AdaptiveMaxValue";
                    input.Text = mode == "Range" ? "13" : "141"; binding.UpdateSource(); Pump(4);
                    Require(Convert.ToDouble(presenter.GetType().GetProperty(property)!.GetValue(presenter), CultureInfo.InvariantCulture) == (mode == "Range" ? 13D : 141D), mode + " TextBox to original presenter binding");
                    if (mode != "Adaptive")
                    {
                        ((Slider)view.FindName(mode == "Basic" ? "sliderThreshold" : "sliderRangeMin")).Value = 19D; Pump(4);
                        Require(input.Text == "19", mode + " existing slider/model to TextBox binding");
                    }
                    else
                    {
                        TextBox block = (TextBox)view.FindName("txtBlockSize"); block.Text = "17"; block.GetBindingExpression(TextBox.TextProperty)!.UpdateSource(); Pump(4);
                        Require(((Slider)view.FindName("sliderBlockSize")).Value == 17D, "adaptive block numeric to slider binding");
                    }
                    input.Text = original; binding.UpdateSource(); host.Workbench.RightPanelWidth = new GridLength(480); Pump(4);
                    foreach (string state in new[] { "focused", "disabled", "readonly", "error", "recovered" })
                    {
                        input.IsEnabled = state != "disabled"; input.IsReadOnly = state == "readonly";
                        input.Text = state == "error" ? "not-a-number" : original; binding.UpdateSource();
                        if (state == "focused") { input.Focus(); Keyboard.Focus(input); } Pump(4);
                        Border chrome = (Border)input.Template.FindName("fieldChrome", input);
                        if (state == "focused") Require(((FrameworkElement)input.Template.FindName("focusCue", input)).IsVisible, "real keyboard focus cue");
                        if (state is "disabled" or "readonly") Require(((SolidColorBrush)chrome.Background).Color == ((SolidColorBrush)view.FindResource("OpenVision.Workbench.PanelAltBrush")).Color, "disabled/read-only field follows theme without white leak");
                        if (state == "error") Require(Validation.GetHasError(input) && ((SolidColorBrush)chrome.BorderBrush).Color == ((SolidColorBrush)view.FindResource("OpenVision.Workbench.NgBrush")).Color, "conversion error uses existing validation plus semantic rendered border");
                        if (state == "recovered") Require(!Validation.GetHasError(input) && input.IsEnabled && !input.IsReadOnly, "valid input recovers numeric control");
                        ScreenshotPngWriter.WriteVisibleElementPng(panel, Path.ChangeExtension(outputPath, $".{theme}.{mode}.{state}.png"));
                    }
                }
            }
            Require(host.NativePreviewRunCount == runs && host.LayerDocumentCount == layers && host.DirectResultRouteText == route, "AUTO-off fixture mode/input/theme/resize has no run/layer/route side effects");
            File.WriteAllText(Path.ChangeExtension(outputPath, ".checks.json"), JsonSerializer.Serialize(new { Checks = checks, Scope = "Automated WPF host; Basic/Range/Adaptive, Dark/Light/Dark,480/720,DPI96. AUTO off; not actualEXE/physicalinput/125 proof." }, new JsonSerializerOptions { WriteIndented = true }));
        }, captureFloatingToolWindow: false);
    }

    private static CaptureResult CaptureMainAddShortcut(string outputPath)
    {
        GlobalState global = new(); global.Recipe.Name = "Smoke_AddShortcut_" + Guid.NewGuid().ToString("N");
        VisionPipeline saved = new() { Name = "Main" }; VisionPipelineStorage.Save(global.Recipe.Name, saved); VisionPipelineStorage.SaveActivePipelineName(global.Recipe.Name, "Main");
        using DisplayManagerService display = new();
        OpenVisionShellHostWindow window = new(new ApplicationRuntimeContext(global, display)); window.ClearValue(OpenVisionShellHostWindow.ClosingCommandProperty);
        OpenVisionShellHostView host = window.ShellHostForSmoke; List<object> checks = new(), events = new();
        void Require(bool passed, string name) { if (!passed) throw new InvalidOperationException("Add shortcut: " + name); checks.Add(new { Case = name, PASS = true }); }
        return CaptureStandaloneWindow(window, outputPath, 1600, 900, () =>
        {
            var tool = host.Workbench.Tool; var pipeline = host.Workbench.Pipeline;
            bool autoPreference = false; host.Workbench.Tool.ConfigureAutoRunPreference(() => autoPreference, value => autoPreference = value);
            string path = RecipeWorkspaceService.GetVisionPipelinePath(global.Recipe.Name, "Main"); byte[] disk = File.ReadAllBytes(path);
            int runs = host.NativePreviewRunCount, layers = host.LayerDocumentCount;
            KeyBinding binding = window.InputBindings.OfType<KeyBinding>().Single(key => key.Key == Key.Enter && key.Modifiers == ModifierKeys.Control);
            Require(Keyboard.Modifiers == ModifierKeys.None, "fixture starts without physical modifier keys; OS keyboard state is never changed");
            File.WriteAllText(Path.ChangeExtension(outputPath, ".identity.json"), JsonSerializer.Serialize(new { ProductAssembly = typeof(OpenVisionShellHostWindow).Assembly.Location, ProductSHA256 = Convert.ToHexString(SHA256.HashData(File.ReadAllBytes(typeof(OpenVisionShellHostWindow).Assembly.Location))), RunnerAssembly = typeof(Program).Assembly.Location }, new JsonSerializerOptions { WriteIndented = true }));
            ShortcutTestKeyboardDevice keyboard = new();
            DependencyProperty acceptsReturn = (DependencyProperty)typeof(KeyboardNavigation).GetField("AcceptsReturnProperty", BindingFlags.Static | BindingFlags.Public | BindingFlags.NonPublic)!.GetValue(null)!;
            (bool Preview, bool Down) Send(UIElement target, ModifierKeys modifiers, string name, bool focus = true, Func<int>? readClicks = null, ModifierKeys? releaseModifiers = null)
            {
                if (focus) { window.Activate(); target.Focus(); Keyboard.Focus(target); Pump(3); Require(Keyboard.FocusedElement == target, name + " actual focused target"); }
                keyboard.TestModifiers = modifiers;
                var preview = new KeyEventArgs(keyboard, PresentationSource.FromVisual(window)!, Environment.TickCount, Key.Enter) { RoutedEvent = Keyboard.PreviewKeyDownEvent };
                target.RaiseEvent(preview);
                var down = new KeyEventArgs(keyboard, PresentationSource.FromVisual(window)!, Environment.TickCount, Key.Enter) { RoutedEvent = Keyboard.KeyDownEvent, Handled = preview.Handled };
                target.RaiseEvent(down);
                keyboard.TestModifiers = releaseModifiers ?? modifiers;
                UIElement releaseTarget = Keyboard.FocusedElement is UIElement focused && Window.GetWindow(focused) == window ? focused : window;
                var previewUp = new KeyEventArgs(keyboard, PresentationSource.FromVisual(window)!, Environment.TickCount, Key.Enter) { RoutedEvent = Keyboard.PreviewKeyUpEvent };
                releaseTarget.RaiseEvent(previewUp);
                var up = new KeyEventArgs(keyboard, PresentationSource.FromVisual(window)!, Environment.TickCount, Key.Enter) { RoutedEvent = Keyboard.KeyUpEvent, Handled = previewUp.Handled };
                releaseTarget.RaiseEvent(up); Pump(4);
                string capture = Path.ChangeExtension(outputPath, $".route{events.Count + 1:00}.png"); ScreenshotPngWriter.WriteVisibleElementPng(window, capture);
                events.Add(new { Case = name, Modifiers = modifiers.ToString(), EventDevice = preview.KeyboardDevice.GetType().Name, PrimaryModifiers = Keyboard.Modifiers.ToString(), PreviewHandled = preview.Handled, DownHandled = down.Handled, PreviewUpHandled = previewUp.Handled, UpHandled = up.Handled, ReleaseModifiers = keyboard.TestModifiers.ToString(), KeyIsDown = down.IsDown, OriginalSource = down.OriginalSource?.GetType().FullName, target.IsEnabled, AcceptsReturn = target.GetValue(acceptsReturn), AutoChecked = (target as ToggleButton)?.IsChecked, Clicks = readClicks?.Invoke(), pipeline.StepCount, pipeline.SelectedStepIndex, tool.IsNewTest, tool.IsAutoRunEnabled, tool.StatusText, Capture = capture });
                File.WriteAllText(Path.ChangeExtension(outputPath, ".events.json"), JsonSerializer.Serialize(events, new JsonSerializerOptions { WriteIndented = true }));
                return (preview.Handled, down.Handled);
            }
            host.SelectToolForTest(VISION_MENU.Filter); Pump(7);
            foreach (bool enabled in new[] { false, true })
            {
                if (tool.IsStepEditing) { tool.NewTestCommand.Execute(null); Pump(7); }
                FrameworkElement view = host.ActiveNativeDocumentForTest!.View; VisionToolDebouncedPreviewScheduler.SetAllowAutoPreview(view, false);
                ToggleButton auto = FindVisualChildren<ToggleButton>(view).Single(button => AutomationProperties.GetAutomationId(button) == "WorkbenchAutoRun");
                tool.IsAutoRunEnabled = enabled; Pump(4); Require(auto.IsChecked == enabled && tool.IsNewTest && ReferenceEquals(binding.Command, tool.AddAfterCommand), "AUTO input is bound to current fresh trial and existing command");
                int before = pipeline.StepCount, clicks = 0; RoutedEventHandler clicked = (_, _) => clicks++; auto.Click += clicked;
                try
                {
                    var routed = Send(auto, ModifierKeys.Control, "AUTO " + enabled + " Control+Enter", readClicks: () => clicks);
                    Require(routed.Preview && routed.Down && pipeline.StepCount == before + 1 && pipeline.SelectedStepIndex == before && clicks == 0 && auto.IsChecked == enabled && tool.IsAutoRunEnabled == enabled, "AUTO " + enabled + " adds once in Window preview; ButtonBase click/toggle never runs");
                    var repeated = Send(auto, ModifierKeys.Control, "stored-step repeated Control+Enter", readClicks: () => clicks);
                    Require(repeated.Preview && repeated.Down && pipeline.StepCount == before + 1 && !tool.IsNewTest && !binding.Command.CanExecute(binding.CommandParameter) && clicks == 0 && auto.IsChecked == enabled, "stored-step repeat stays consumed without duplicate or AUTO change");
                }
                finally { auto.Click -= clicked; }
            }
            tool.NewTestCommand.Execute(null); Pump(7);
            FrameworkElement pendingView = host.ActiveNativeDocumentForTest!.View; VisionToolDebouncedPreviewScheduler.SetAllowAutoPreview(pendingView, false);
            ToggleButton pendingAuto = FindVisualChildren<ToggleButton>(pendingView).Single(button => AutomationProperties.GetAutomationId(button) == "WorkbenchAutoRun");
            tool.IsAutoRunEnabled = false; Pump(3); int pendingCount = pipeline.StepCount;
            pipeline.SetImageEditPending(true);
            try { var busy = Send(pendingAuto, ModifierKeys.Control, "busy forced route", false); Require(busy.Preview && busy.Down && pipeline.StepCount == pendingCount && !binding.Command.CanExecute(binding.CommandParameter) && pendingAuto.IsChecked == false, "busy consumes shortcut with no add or AUTO click"); }
            finally { pipeline.SetImageEditPending(false); }
            host.Workbench.OpenMainNewRecipeCommand.Execute(null); Pump(4);
            try { var modal = Send(pendingAuto, ModifierKeys.Control, "noninteractive forced route", false); Require(!host.Workbench.IsMainInteractive && modal.Preview && modal.Down && pipeline.StepCount == pendingCount && pendingAuto.IsChecked == false, "existing Main noninteractive barrier consumes forced underlying route"); }
            finally { host.Workbench.CloseMainRecipeCommand.Execute(null); Pump(4); }
            foreach (ModifierKeys modifiers in new[] { ModifierKeys.None, ModifierKeys.Control | ModifierKeys.Shift, ModifierKeys.Control | ModifierKeys.Alt })
            {
                bool? before = pendingAuto.IsChecked; int clicks = 0; RoutedEventHandler clicked = (_, _) => clicks++; pendingAuto.Click += clicked;
                try { var other = Send(pendingAuto, modifiers, "non-exact Enter " + modifiers); Require(!other.Preview && other.Down && pipeline.StepCount == pendingCount && clicks == 1 && pendingAuto.IsChecked != before, "non-exact synthetic Enter preserves framework ButtonBase behavior instead of Add"); }
                finally { pendingAuto.Click -= clicked; }
            }
            foreach (string focus in new[] { "navigation", "numeric" })
            {
                if (focus == "numeric")
                {
                    host.SelectToolForTest(VISION_MENU.Threshold); Pump(6); FrameworkElement duplicateView = host.ActiveNativeDocumentForTest!.View;
                    byte[] beforeDuplicate = VisionPipelineExecutionPlan.SerializePipeline(pipeline.WorkingCopyForTest); int count = pipeline.StepCount;
                    var duplicate = Send((TextBox)duplicateView.FindName("txtThreshold"), ModifierKeys.Control, "cached duplicate-output draft");
                    Require(duplicate.Preview && pipeline.StepCount == count && tool.IsNewTest && !string.IsNullOrEmpty(tool.StatusText) && beforeDuplicate.SequenceEqual(VisionPipelineExecutionPlan.SerializePipeline(pipeline.WorkingCopyForTest)), "existing duplicate-output rejection preserves working pipeline");
                }
                host.SelectToolForTest(focus == "navigation" ? VISION_MENU.Threshold : VISION_MENU.Filter); Pump(7); FrameworkElement view = host.ActiveNativeDocumentForTest!.View;
                VisionToolDebouncedPreviewScheduler.SetAllowAutoPreview(view, false);
                UIElement target = focus == "navigation" ? FindVisualChildren<Button>(host).Single(button => AutomationProperties.GetAutomationId(button) == "HostToolNav_Threshold") : (TextBox)view.FindName("txtWidth");
                Require(tool.IsNewTest && ReferenceEquals(binding.Command, tool.AddAfterCommand) && binding.Command.CanExecute(binding.CommandParameter), "same registered AddAfter command from " + focus);
                int before = pipeline.StepCount; var routed = Send(target, ModifierKeys.Control, focus + " Control+Enter");
                Require(routed.Preview && routed.Down && pipeline.StepCount == before + 1 && pipeline.SelectedStepIndex == before && !tool.IsNewTest, "Window preview adds once from " + focus + " without local Enter action");
                Send(target, ModifierKeys.Control, focus + " repeated Control+Enter"); Require(pipeline.StepCount == before + 1, "repeated route never duplicates stored step");
            }
            host.SelectToolForTest(VISION_MENU.Blob); Pump(7);
            FrameworkElement blobView = host.ActiveNativeDocumentForTest!.View; VisionToolDebouncedPreviewScheduler.SetAllowAutoPreview(blobView, false); tool.IsAutoRunEnabled = false;
            var blobGrid = FindVisualChildren<System.Windows.Controls.WpfPropertyGrid.PropertyGrid>(blobView).Single(grid => grid.IsVisible && grid.SelectedObject is BlobProperty);
            BlobProperty blob = (BlobProperty)blobGrid.SelectedObject; blob.USE_ROI = false; Pump(4);
            TextBox scale = FindVisualChildren<TextBox>(blobGrid).Single(box => box.IsVisible && box.IsEnabled && !box.IsReadOnly && box.Text == blob.PIXELPERMM.ToString(System.Globalization.CultureInfo.CurrentCulture));
            scale.Focus(); Keyboard.Focus(scale); Pump(3); double originalScale = blob.PIXELPERMM;
            scale.SetCurrentValue(TextBox.TextProperty, "333");
            Require(scale.IsKeyboardFocused && scale.Text == "333" && blob.PIXELPERMM == originalScale && scale.GetBindingExpression(TextBox.TextProperty) != null, "Blob LostFocus editor displays333 while model still has prior value");
            ScreenshotPngWriter.WriteVisibleElementPng(window, Path.ChangeExtension(outputPath, ".pending-333-before.png"));
            int beforeBlob = pipeline.StepCount;
            var pending = Send(scale, ModifierKeys.Control, "Blob pending valid scale333 Control+Enter");
            VisionPipelineStep insertedBlob = pipeline.WorkingCopyForTest.Steps.Last();
            File.WriteAllText(Path.ChangeExtension(outputPath, ".pending-blob.json"), JsonSerializer.Serialize(new { Displayed = "333", OriginalModel = originalScale, ModelAfter = blob.PIXELPERMM, pipeline.StepCount, StepParameters = insertedBlob.Parameters }, new JsonSerializerOptions { WriteIndented = true }));
            Require(pending.Preview && pipeline.StepCount == beforeBlob + 1 && blob.PIXELPERMM == 333D && insertedBlob.Parameters["PIXELPERMM"] == "333", "CtrlEnter captures pending PG numeric input into inserted step XML");
            tool.NewTestCommand.Execute(null); Pump(7); blobView = host.ActiveNativeDocumentForTest!.View; VisionToolDebouncedPreviewScheduler.SetAllowAutoPreview(blobView, false);
            blobGrid = FindVisualChildren<System.Windows.Controls.WpfPropertyGrid.PropertyGrid>(blobView).Single(grid => grid.IsVisible && grid.SelectedObject is BlobProperty); blob = (BlobProperty)blobGrid.SelectedObject; blob.USE_ROI = false; Pump(3);
            scale = FindVisualChildren<TextBox>(blobGrid).Single(box => box.IsVisible && box.IsEnabled && !box.IsReadOnly && box.Text == blob.PIXELPERMM.ToString(System.Globalization.CultureInfo.CurrentCulture));
            scale.Focus(); Keyboard.Focus(scale); Pump(3); scale.SetCurrentValue(TextBox.TextProperty, "invalid"); byte[] beforeInvalid = VisionPipelineExecutionPlan.SerializePipeline(pipeline.WorkingCopyForTest); int invalidCount = pipeline.StepCount;
            Send(scale, ModifierKeys.Control, "Blob pending invalid scale Control+Enter", releaseModifiers: ModifierKeys.None);
            Require(pipeline.StepCount == invalidCount && tool.IsNewTest && scale.Text == "invalid" && Validation.GetHasError(scale) && beforeInvalid.SequenceEqual(VisionPipelineExecutionPlan.SerializePipeline(pipeline.WorkingCopyForTest)), "invalid pending PG input refuses add and preserves text and pipeline");
            scale.SetCurrentValue(TextBox.TextProperty, "350"); Send(scale, ModifierKeys.Control, "Blob pending numeric recovery350 Control+Enter");
            Require(pipeline.StepCount == invalidCount + 1 && !tool.IsNewTest && !Validation.GetHasError(scale) && pipeline.WorkingCopyForTest.Steps.Last().Parameters["PIXELPERMM"] == "350", "valid pending PG recovery adds latest350 exactly once");
            tool.NewTestCommand.Execute(null); Pump(7); blobView = host.ActiveNativeDocumentForTest!.View; VisionToolDebouncedPreviewScheduler.SetAllowAutoPreview(blobView, false);
            blobGrid = FindVisualChildren<System.Windows.Controls.WpfPropertyGrid.PropertyGrid>(blobView).Single(grid => grid.IsVisible && grid.SelectedObject is BlobProperty); blob = (BlobProperty)blobGrid.SelectedObject;
            scale = FindVisualChildren<TextBox>(blobGrid).Single(box => box.IsVisible && box.IsEnabled && !box.IsReadOnly && box.Text == blob.PIXELPERMM.ToString(System.Globalization.CultureInfo.CurrentCulture));
            int normalCount = pipeline.StepCount; scale.Focus(); Keyboard.Focus(scale); Pump(3); scale.SetCurrentValue(TextBox.TextProperty, "351");
            Send(scale, ModifierKeys.None, "ordinary Blob Enter commit351");
            Require(blob.PIXELPERMM == 351D && pipeline.StepCount == normalCount && tool.IsNewTest, "ordinary Enter still commits numeric input without adding a step");
            scale.SetCurrentValue(TextBox.TextProperty, "352");
            var tab = new KeyEventArgs(keyboard, PresentationSource.FromVisual(window)!, Environment.TickCount, Key.Tab) { RoutedEvent = Keyboard.PreviewKeyDownEvent };
            scale.RaiseEvent(tab); Pump(4);
            Require(!scale.IsKeyboardFocused && blob.PIXELPERMM == 352D && pipeline.StepCount == normalCount, "ordinary Tab still leaves numeric input and commits through LostFocus without adding");
            Require(disk.SequenceEqual(File.ReadAllBytes(path)) && host.NativePreviewRunCount == runs && host.LayerDocumentCount == layers, "routed keys never implicitly save/run/create layers");
            File.WriteAllText(Path.ChangeExtension(outputPath, ".checks.json"), JsonSerializer.Serialize(new { Checks = checks, Scope = "Automated WPF Window PreviewKeyDown→target KeyDown and PreviewKeyUp→KeyUp with shared handled state per pair; test-only KeyboardDevice modifiers, real ButtonBase/ToggleButton class handlers, actual focus. No PrimaryDevice/OS keyboard-state mutation or physical input. Control+Alt case is synthetic Enter, not native WM_SYSKEY promotion. Actual new-product keyboard flow and125% remain separate." }, new JsonSerializerOptions { WriteIndented = true }));
        });
    }

    private static CaptureResult CaptureKernelControls(string outputPath)
    {
        OpenVisionShellHostView host = CreateShellHost("Smoke_KernelControls", true);
        List<object> checks = new();
        void Require(bool passed, string name) { if (!passed) throw new InvalidOperationException("Kernel controls: " + name); checks.Add(new { Case = name, PASS = true }); }
        return CaptureWindowWithContent(host, outputPath, 1920, 1032, () =>
        {
            host.Workbench.Tool.ConfigureAutoRunPreference(() => false, _ => { });
            foreach (string theme in new[] { "Dark", "Light", "Dark" })
            foreach (OpenVisionLanguage language in new[] { OpenVisionLanguage.Korean, OpenVisionLanguage.English })
            {
                (theme == "Dark" ? host.Workbench.SelectDarkThemeCommand : host.Workbench.SelectLightThemeCommand).Execute(null);
                OpenVisionLanguageService.SetLanguage(language, false); Pump(5);
                foreach (VISION_MENU menu in new[] { VISION_MENU.Filter, VISION_MENU.Morphology })
                {
                    host.SelectToolForTest(menu); Pump(8);
                    OpenVisionNativeToolDocument document = host.ActiveNativeDocumentForTest!;
                    FrameworkElement view = document.View;
                    VisionToolDebouncedPreviewScheduler.SetAllowAutoPreview(view, false);
                    FrameworkElement shell = (FrameworkElement)view.FindName("toolShell"), panel = (FrameworkElement)shell.FindName("parameterPanel");
                    TextBox width = (TextBox)view.FindName("txtWidth"), height = (TextBox)view.FindName("txtHeight");
                    CheckBox locked = (CheckBox)view.FindName("chkLockSize");
                    Button[] presets = new[] { 3, 5, 7 }.Select(n => (Button)view.FindName((menu == VISION_MENU.Filter ? "btnFilterKernelPreset" : "btnKernelPreset") + n)).ToArray();
                    foreach (string name in menu == VISION_MENU.Filter ? new[] { "gbFilterOptions", "gbKernel" } : new[] { "gbOperation", "gbKernel" })
                    {
                        GroupBox group = (GroupBox)view.FindName(name);
                        Brush[] headerBrushes = FindVisualChildren<TextBlock>(group).Where(label => label.Text == group.Header.ToString()).Select(label => label.Foreground)
                            .Concat(FindVisualChildren<AccessText>(group).Where(label => label.Text == group.Header.ToString()).Select(label => label.Foreground)).ToArray();
                        Color text = ((SolidColorBrush)view.FindResource("OpenVision.Workbench.TextBrush")).Color;
                        Require(headerBrushes.Length > 0 && headerBrushes.All(brush => brush is SolidColorBrush solid && solid.Color == text), menu + " " + theme + " generated group captions follow current theme");
                    }
                    if (menu == VISION_MENU.Morphology)
                        foreach (Button operation in FindVisualChildren<Button>(view).Where(button => button.Name.StartsWith("btnMorphOperation", StringComparison.Ordinal)))
                        {
                            Color front = ((SolidColorBrush)operation.Background).Color, back = FindOpaqueVisualBackground(operation)!.Color;
                            double alpha = front.A / 255D;
                            Color rendered = Color.FromRgb((byte)Math.Round(front.R * alpha + back.R * (1D - alpha)), (byte)Math.Round(front.G * alpha + back.G * (1D - alpha)), (byte)Math.Round(front.B * alpha + back.B * (1D - alpha)));
                            Require(GetContrastRatio(((SolidColorBrush)operation.Foreground).Color, rendered) >= 4.5D, "Morphology selected/unselected operation text remains legible after theme return");
                        }
                    int runs = host.NativePreviewRunCount, layers = host.LayerDocumentCount; string route = host.DirectResultRouteText;
                    void Selected(int expected)
                    {
                        Pump(3);
                        for (int i = 0; i < presets.Length; i++)
                        {
                            Button button = presets[i]; int size = new[] { 3, 5, 7 }[i];
                            Border chrome = (Border)button.Template.FindName("buttonChrome", button);
                            Require((button.Content?.ToString()?.Contains("✓") == true) == (size == expected)
                                && button.BorderThickness.Left == (size == expected ? 2D : 1D) && chrome.BorderThickness == button.BorderThickness,
                                $"{menu}/{theme}/{language} preset{size} current selection={expected} has actual outline and redundant check mark");
                        }
                    }
                    void Set(TextBox box, string value) { box.Text = value; box.GetBindingExpression(TextBox.TextProperty)!.UpdateSource(); Pump(3); }
                    if (menu == VISION_MENU.Filter) SelectComboBoxItemText((ComboBox)view.FindName("cbFilterType"), "Blur", "kernel size mode");
                    presets[0].RaiseEvent(new RoutedEventArgs(Button.ClickEvent)); Selected(3);
                    foreach (int inspector in new[] { 480, 520, 720 })
                    {
                        host.Workbench.RightPanelWidth = new GridLength(inspector); Pump(6);
                        foreach (TextBox box in new[] { width, height })
                        {
                            Border chrome = (Border)box.Template.FindName("fieldChrome", box);
                            Rect bounds = box.TransformToAncestor(panel).TransformBounds(new Rect(box.RenderSize));
                            Require(box.ActualWidth == 72D && box.ActualHeight == 30D && chrome.BorderThickness.Left >= 1D
                                && bounds.Left >= 0D && bounds.Right <= panel.ActualWidth && GetContrastRatio(((SolidColorBrush)box.Foreground).Color, ((SolidColorBrush)chrome.Background).Color) >= 4.5D,
                                $"{menu}/{theme}/{language}/{inspector}/{box.Name}72x30 input chrome and text legible inside viewport");
                        }
                        FrameworkElement separator = (FrameworkElement)view.FindName("kernelDimensionSeparator");
                        Rect a = width.TransformToAncestor(panel).TransformBounds(new Rect(width.RenderSize)), b = height.TransformToAncestor(panel).TransformBounds(new Rect(height.RenderSize));
                        Require(separator.IsVisible && Math.Abs(a.Y - b.Y) < 1D && b.Left > a.Right && b.Left - a.Right < 75D, "dimensions remain one compact labelled group");
                        foreach (TextBlock label in new[] { (TextBlock)view.FindName("lblKernelWidth"), (TextBlock)view.FindName("lblKernelHeight") })
                            Require(label.ActualWidth >= new FormattedText(label.Text, CultureInfo.CurrentCulture, FlowDirection.LeftToRight, new Typeface(label.FontFamily, label.FontStyle, label.FontWeight, label.FontStretch), label.FontSize, label.Foreground, VisualTreeHelper.GetDpi(label).PixelsPerDip).Width - 1D, "localized caption fits without clipping");
                        Require(FindVisualChildren<ScrollViewer>(panel).Where(s => s.IsVisible).All(s => s.ScrollableWidth <= 1D), "kernel panel has no horizontal overflow");
                        ScreenshotPngWriter.WriteVisibleElementPng(panel, Path.ChangeExtension(outputPath, $".{menu}.{theme}.{language}.{inspector}.png"));
                    }
                    locked.IsChecked = true; Set(width, "9"); Require(height.Text == "9", "explicit locked input synchronizes height"); Selected(0);
                    presets[1].RaiseEvent(new RoutedEventArgs(Button.ClickEvent)); Require(width.Text == "5" && height.Text == "5", "preset changes both inputs"); Selected(5);
                    locked.IsChecked = false; Set(width, "3"); Selected(0); Set(height, "3"); Selected(3);
                    Set(height, "5"); Selected(0);
                    Set(width, "not-a-number"); Require(Validation.GetHasError(width), "invalid conversion keeps existing validation indication");
                    Set(width, "5"); Require(!Validation.GetHasError(width), "valid edit clears conversion error"); Selected(5);
                    if (menu == VISION_MENU.Filter)
                    {
                        ComboBox mode = (ComboBox)view.FindName("cbFilterType");
                        SelectComboBoxItemText(mode, "MedianBlur", "median selected preset");
                        TextBox median = (TextBox)view.FindName("txtMedianKernel"); Set(median, "7"); Selected(7); Set(median, "9"); Selected(0);
                        presets[0].RaiseEvent(new RoutedEventArgs(Button.ClickEvent)); Require(median.Text == "3", "median preset still writes median binding"); Selected(3);
                        foreach (string value in new[] { "GaussianBlur", "MedianBlur", "BilateralFilter", "Blur" })
                        {
                            SelectComboBoxItemText(mode, value, "mode visibility"); Pump(4);
                            Require(((FrameworkElement)view.FindName("kernelDimensionSeparator")).IsVisible == (value is "GaussianBlur" or "Blur"), "separator follows dimensional mode without ghost gap");
                            foreach (TextBox visible in FindVisualChildren<TextBox>((FrameworkElement)view.FindName("parameterContentHost")).Where(box => box.IsVisible))
                            {
                                Rect visibleBounds = visible.TransformToAncestor(panel).TransformBounds(new Rect(visible.RenderSize));
                                Require(visible.ActualWidth == 72D && visible.ActualHeight == 30D && visibleBounds.Left >= 0D && visibleBounds.Right <= panel.ActualWidth, "mode numeric editor fits without horizontal clipping");
                            }
                            if (language == OpenVisionLanguage.Korean) ScreenshotPngWriter.WriteVisibleElementPng(panel, Path.ChangeExtension(outputPath, $".{menu}.{theme}.{value}.png"));
                        }
                    }
                    presets[0].RaiseEvent(new RoutedEventArgs(Button.ClickEvent)); Selected(3);
                    host.Workbench.RightPanelWidth = new GridLength(480); Pump(5);
                    if (language == OpenVisionLanguage.Korean)
                    {
                        Button button = presets[0];
                        DependencyPropertyKey hover = (DependencyPropertyKey)typeof(UIElement).GetField("IsMouseOverPropertyKey", BindingFlags.Static | BindingFlags.NonPublic)!.GetValue(null)!;
                        DependencyPropertyKey pressed = (DependencyPropertyKey)typeof(ButtonBase).GetField("IsPressedPropertyKey", BindingFlags.Static | BindingFlags.NonPublic)!.GetValue(null)!;
                        foreach (string state in new[] { "synthetic-hover", "synthetic-pressed", "focused", "button-focused", "disabled", "recovered" })
                        {
                            button.SetValue(hover, state == "synthetic-hover"); button.SetValue(pressed, state == "synthetic-pressed");
                            button.IsEnabled = state != "disabled"; width.IsEnabled = state != "disabled";
                            if (state == "focused") { width.Focus(); Keyboard.Focus(width); }
                            if (state == "button-focused") { button.Focus(); Keyboard.Focus(button); }
                            Pump(4);
                            if (state is "focused" or "button-focused")
                                Require(((FrameworkElement)(state == "focused" ? width.Template.FindName("focusCue", width) : button.Template.FindName("focusCue", button))).Visibility == Visibility.Visible, "actual keyboard focus cue rendered");
                            Border fieldChrome = (Border)width.Template.FindName("fieldChrome", width);
                            if (state == "disabled") File.WriteAllText(Path.ChangeExtension(outputPath, $".{menu}.{theme}.disabled-colors.json"), JsonSerializer.Serialize(new { ActualBackground = fieldChrome.Background.ToString(), ActualForeground = width.Foreground.ToString(), ResourceBackground = width.FindResource("OpenVision.ControlDisabledBrush").ToString(), StyleBackground = width.Style.Resources["OpenVision.ControlDisabledBrush"]?.ToString(), ExpectedBackground = view.FindResource("OpenVision.Workbench.PanelAltBrush").ToString(), ExpectedForeground = view.FindResource("OpenVision.Workbench.MutedTextBrush").ToString() }, new JsonSerializerOptions { WriteIndented = true }));
                            if (state == "disabled") Require(((SolidColorBrush)fieldChrome.Background).Color == ((SolidColorBrush)view.FindResource("OpenVision.Workbench.PanelAltBrush")).Color
                                && ((SolidColorBrush)width.Foreground).Color == ((SolidColorBrush)view.FindResource("OpenVision.Workbench.MutedTextBrush")).Color, "disabled numeric field has no platform-white leak");
                            Border chrome = (Border)button.Template.FindName("buttonChrome", button);
                            string key = state == "synthetic-hover" ? "HoverBrush" : state == "synthetic-pressed" ? "PressedBrush" : state == "disabled" ? "PanelAltBrush" : "AccentSoftBrush";
                            Require(((SolidColorBrush)chrome.Background).Color == ((SolidColorBrush)view.FindResource("OpenVision.Workbench." + key)).Color, "rendered " + state + " uses semantic button fill");
                            ScreenshotPngWriter.WriteVisibleElementPng(panel, Path.ChangeExtension(outputPath, $".{menu}.{theme}.{state}.png"));
                        }
                        button.ClearValue(hover); button.ClearValue(pressed);
                    }
                    Require(host.NativePreviewRunCount == runs && host.LayerDocumentCount == layers && host.DirectResultRouteText == route, "AUTO-off kernel fixture editing/theme/resize changes no run/layers/routes");
                    string parameters = JsonSerializer.Serialize(host.Workbench.Tool.CurrentStep!.Parameters);
                    Require(host.FloatDockedWpfToolWindowForTest(), "existing float action succeeds"); Pump(6);
                    ScreenshotPngWriter.WriteVisibleElementPng(Window.GetWindow(view)!, Path.ChangeExtension(outputPath, $".{menu}.{theme}.{language}.floating.png"));
                    Require(host.DockActiveWpfToolWindowForTest(), "existing dock action succeeds"); Pump(6);
                    Require(parameters == JsonSerializer.Serialize(host.Workbench.Tool.CurrentStep!.Parameters) && host.NativePreviewRunCount == runs && host.LayerDocumentCount == layers && host.DirectResultRouteText == route, "dock/float preserves settings and no-run boundary");
                }
            }
            File.WriteAllText(Path.ChangeExtension(outputPath, ".checks.json"), JsonSerializer.Serialize(new { Checks = checks, Scope = "Automated WPF host, DPI96; hover/press synthetic dependency states, not physical pointer proof. AUTO disabled fixture; no actualEXE/ComputerUse/125 claim." }, new JsonSerializerOptions { WriteIndented = true }));
        }, captureFloatingToolWindow: false);
    }

    private static CaptureResult CaptureToolParameterLayout(string outputPath)
    {
        OpenVisionLanguageService.SetLanguage(OpenVisionLanguage.Korean, false);
        OpenVisionShellHostView host = CreateShellHost("Smoke_ParameterLayout_" + Guid.NewGuid().ToString("N"));
        List<object> checks = new();
        void Require(bool pass, string name) { if (!pass) throw new InvalidOperationException("Parameter layout: " + name); checks.Add(new { Case = name, PASS = true }); }
        return CaptureWindowWithContent(host, outputPath, 1920, 1032, () =>
        {
            host.Workbench.Tool.ConfigureAutoRunPreference(() => false, _ => { });
            int runs = host.NativePreviewRunCount, layers = host.LayerDocumentCount;
            foreach (int width in new[] { 1920, 1280 })
            foreach (string theme in new[] { "Dark", "Light" })
            {
                Window window = Window.GetWindow(host); window.Width = width; window.Height = width == 1280 ? 760 : 1032;
                (theme == "Dark" ? host.Workbench.SelectDarkThemeCommand : host.Workbench.SelectLightThemeCommand).Execute(null); Pump(5);
                foreach (VISION_MENU menu in new[] { VISION_MENU.Blob, VISION_MENU.Contour, VISION_MENU.Line, VISION_MENU.Matching, VISION_MENU.EdgeBasedMatching, VISION_MENU.FeatureMatching, VISION_MENU.AffineTransform })
                {
                    host.SelectToolForTest(menu); Pump(8);
                    OpenVisionNativeToolDocument document = host.ActiveNativeDocumentForTest!;
                    VisionToolDebouncedPreviewScheduler.SetAllowAutoPreview(document.View, false);
                    VisionToolSingleInputPropertyToolShell shell = (VisionToolSingleInputPropertyToolShell)document.View.FindName("toolShell");
                    var grid = FindVisualChildren<System.Windows.Controls.WpfPropertyGrid.PropertyGrid>(shell.PropertyGridHost).Single();
                    ScrollViewer horizontal = (ScrollViewer)shell.FindName("propertyGridScrollViewer");
                    string parameters = JsonSerializer.Serialize(host.Workbench.Tool.CurrentStep.Parameters), route = host.DirectResultRouteText;
                    object selected = grid.SelectedObject;
                    foreach (int inspector in new[] { 480, 520, 720, 480 })
                    {
                        host.Workbench.IsLeftCollapsed = width == 1280 && inspector == 720;
                        host.Workbench.RightPanelWidth = new GridLength(inspector); Pump(10);
                        Require(Math.Abs(host.Workbench.RightPanelWidth.Value - inspector) < 1D, $"{menu}/{theme}/{width} actual inspector {inspector}");
                        Require(horizontal.ScrollableWidth <= 1D && horizontal.HorizontalOffset <= 1D, $"{menu}/{theme}/{width}/{inspector} horizontal viewport contains the whole form (viewport={horizontal.ViewportWidth}, extent={horizontal.ExtentWidth}, hostMin={shell.PropertyGridHost.MinWidth})");
                        foreach (Border border in FindVisualChildren<Border>(grid).Where(item => item.Name == "RowBorder" && item.IsVisible && item.Child is Grid))
                        {
                            Grid row = (Grid)border.Child;
                            if (row.ColumnDefinitions.Count != 2) continue;
                            Border? editor = row.Children.OfType<Border>().FirstOrDefault(item => item.Name != "NameCell" && item.Name != "RowAccent");
                            TextBlock? caption = row.Children.OfType<TextBlock>().FirstOrDefault(item => item.GetType().Name == "PropertyNameTextBlock");
                            if (editor == null || caption == null) continue;
                            bool range = FindVisualChildren<Grid>(editor).Any(item => item.GetType().Name == "RangeEditorBase");
                            bool stacked = Grid.GetRow(editor) == 1 && Grid.GetColumnSpan(editor) == 2;
                            Require(range ? stacked == (inspector < 720) : !stacked && Grid.GetColumn(editor) == 1, $"{menu}/{theme}/{width}/{inspector} range-only responsive row");
                            Rect bounds = caption.TransformToAncestor(horizontal).TransformBounds(new Rect(caption.RenderSize));
                            Require(bounds.Left >= -1D && bounds.Right <= horizontal.ViewportWidth + 1D && caption.TextTrimming == TextTrimming.None, $"{menu}/{inspector} caption fits horizontal viewport without ellipsis");
                        }
                        if (FindVisualChildren<Grid>(grid).Any(item => item.GetType().Name == "RangeEditorBase" && item.IsVisible)) AssertPropertyGridRangeEditorLayout(grid, menu + " existing numeric/slider bounds " + inspector);
                        string afterParameters = JsonSerializer.Serialize(host.Workbench.Tool.CurrentStep.Parameters);
                        if (parameters != afterParameters || route != host.DirectResultRouteText || host.NativePreviewRunCount != runs || host.LayerDocumentCount != layers)
                            File.WriteAllText(Path.ChangeExtension(outputPath, ".state-difference.json"), JsonSerializer.Serialize(new { Tool = menu.ToString(), theme, width, inspector, SameSelectedObject = ReferenceEquals(selected, grid.SelectedObject), Before = parameters, After = afterParameters, RouteBefore = route, RouteAfter = host.DirectResultRouteText, RunsBefore = runs, RunsAfter = host.NativePreviewRunCount, LayersBefore = layers, LayersAfter = host.LayerDocumentCount }, new JsonSerializerOptions { WriteIndented = true }));
                        Require(ReferenceEquals(selected, grid.SelectedObject) && parameters == afterParameters
                            && route == host.DirectResultRouteText && host.NativePreviewRunCount == runs && host.LayerDocumentCount == layers, menu + " resize/theme does not edit/run/change layers or route");
                        if (menu == VISION_MENU.Blob && width == 1920) ScreenshotPngWriter.WriteVisibleElementPng((FrameworkElement)shell.FindName("parameterPanel"), Path.ChangeExtension(outputPath, $".{theme}.{inspector}.png"));
                    }
                    if (menu == VISION_MENU.Blob && width == 1920 && theme == "Dark")
                    {
                        AssertFloatingRangeEditorEndpointAllowsTransientText("reflow invalid text", "MIN_AREA", 0, "-", 200D);
                        TextBox invalid = FindRangeEditorValueTextBoxes(GetFloatingRangeEditorForProperty("conversion recovery", "MIN_AREA"))[0];
                        invalid.Focus(); invalid.Text = "not-a-number"; invalid.GetBindingExpression(TextBox.TextProperty)!.UpdateSource(); Pump(3);
                        Require(Validation.GetHasError(invalid), "existing numeric conversion error remains visible after reflow");
                        SetFloatingRangeEditorEndpointTextValue("reflow valid lower", "MIN_AREA", 0, 350D);
                        Require(!Validation.GetHasError(invalid), "valid numeric input clears the existing conversion error");
                        AssertFloatingSelectedObjectNumericProperty("reflow lower model", "MIN_AREA", 350D);
                        SetFloatingRangeEditorEndpointSliderValue("reflow lower slider", "MIN_AREA", 0, 300D);
                        AssertFloatingSelectedObjectNumericProperty("reflow slider model", "MIN_AREA", 300D);
                        SetFloatingRangeEditorEndpointTextValue("reflow restore lower", "MIN_AREA", 0, 200D);
                        Border owner = (Border)grid.Parent;
                        grid.ThemeVariant = System.Windows.Controls.WpfPropertyGrid.PropertyGridThemeVariant.Default;
                        owner.Child = null; Pump(6);
                        Require(ReadPrivateField<ScrollViewer>(grid, "horizontalViewport") == null && ReadPrivateField<Control>(grid, "innerPropertyGrid")!.MinWidth == 0D, "unloaded viewport unhooks and stale dispatch leaves restored minimum");
                        Require(FindVisualChildren<Border>(grid).Where(item => item.Name == "RowBorder" && item.Child is Grid).All(item => ((Grid)item.Child).Children.OfType<Border>().All(child => Grid.GetRow(child) == 0 && Grid.GetColumnSpan(child) == 1)), "unloaded rows restore original two columns");
                        owner.Child = grid; Pump(10);
                        Require(horizontal.ScrollableWidth <= 1D && ReferenceEquals(selected, grid.SelectedObject), "reload reattaches viewport without replacing selected object");
                        owner.Child = null; Pump(3);
                        var ordinary = new System.Windows.Controls.WpfPropertyGrid.PropertyGrid();
                        ordinary.ApplyDisplayOptions(OpenVisionLab.PropertyGrid.PropertyGridDisplayOptions.Pipeline); ordinary.SelectedObject = selected;
                        owner.Child = ordinary; Pump(8);
                        Require(ReadPrivateField<ScrollViewer>(ordinary, "horizontalViewport") == null && (double)ReadPrivateField<Control>(ordinary, "innerPropertyGrid")!.GetType().GetProperty("EditorColumnMinWidth")!.GetValue(ReadPrivateField<Control>(ordinary, "innerPropertyGrid"))! == 360D, "non-ToolForm profile retains original editor minimum and lifetime");
                        owner.Child = grid; Pump(8);
                    }
                }
                host.Workbench.IsLeftCollapsed = false; host.Workbench.RightPanelWidth = new GridLength(480);
                foreach (VISION_MENU menu in new[] { VISION_MENU.Filter, VISION_MENU.Morphology })
                {
                    host.SelectToolForTest(menu); Pump(8);
                    FrameworkElement view = host.ActiveNativeDocumentForTest!.View;
                    string route = host.DirectResultRouteText;
                    string[] modes = menu == VISION_MENU.Filter ? new[] { "Blur", "GaussianBlur", "MedianBlur", "BilateralFilter" } : new[] { "Erode", "Open", "Gradient" };
                    foreach (string mode in modes)
                    {
                        if (menu == VISION_MENU.Filter) SelectComboBoxItemText((ComboBox)view.FindName("cbFilterType"), mode, "Filter layout mode");
                        else ((Button)view.FindName("btnMorphOperation" + mode)).RaiseEvent(new RoutedEventArgs(Button.ClickEvent));
                        Pump(6);
                        foreach (string name in new[] { "txtWidth", "txtHeight", "txtMedianKernel", "txtDiameter", "txtSigmaColor", "txtSigmaSpace" })
                        {
                            if (view.FindName(name) is not TextBox box || !box.IsVisible) continue;
                            Require(Math.Abs(box.ActualWidth - 72D) < 1D && box.ActualHeight >= 24D, $"{menu}/{theme}/{width}/{mode}/{name} original numeric input has readable72px inline layout");
                        }
                        FrameworkElement[] panels = FindVisualChildren<StackPanel>(view).Where(item => item.IsVisible && new[] { "panelWidth", "panelHeight", "panelKernelWidth", "panelKernelHeight", "panelMedian", "panelDiameter", "panelSigmaColor", "panelSigmaSpace" }.Contains(item.Name)).Cast<FrameworkElement>().ToArray();
                        foreach (FrameworkElement panel in panels) Require(((StackPanel)panel).Orientation == Orientation.Horizontal && panel.ActualHeight < 45D, panel.Name + " inline label/value compact height");
                        Require(host.NativePreviewRunCount == runs && host.LayerDocumentCount == layers && route == host.DirectResultRouteText, menu + " layout/mode does not run or alter layers/routes");
                    }
                    if (menu == VISION_MENU.Filter) SelectComboBoxItemText((ComboBox)view.FindName("cbFilterType"), "Blur", "Filter kernel editing mode");
                    CheckBox locked = (CheckBox)view.FindName("chkLockSize"); TextBox widthBox = (TextBox)view.FindName("txtWidth"), heightBox = (TextBox)view.FindName("txtHeight");
                    locked.IsChecked = true; widthBox.Text = "9"; widthBox.GetBindingExpression(TextBox.TextProperty)!.UpdateSource(); Pump(4);
                    Require(heightBox.Text == "9", menu + " inline input preserves W=H companion binding");
                    ((Button)view.FindName(menu == VISION_MENU.Filter ? "btnFilterKernelPreset5" : "btnKernelPreset5")).RaiseEvent(new RoutedEventArgs(Button.ClickEvent)); Pump(4);
                    Require(widthBox.Text == "5" && heightBox.Text == "5", menu + " existing preset updates both visible inputs");
                    locked.IsChecked = false; widthBox.Text = "3"; heightBox.Text = "5"; widthBox.GetBindingExpression(TextBox.TextProperty)!.UpdateSource(); heightBox.GetBindingExpression(TextBox.TextProperty)!.UpdateSource(); Pump(4);
                    Require(widthBox.Text == "3" && heightBox.Text == "5" && host.NativePreviewRunCount == runs && host.LayerDocumentCount == layers && route == host.DirectResultRouteText, menu + " unequal inputs keep values without implicit run/layer/route change");
                    ScreenshotPngWriter.WriteVisibleElementPng((FrameworkElement)((FrameworkElement)view.FindName("toolShell")).FindName("parameterPanel"), Path.ChangeExtension(outputPath, $".{menu}.{theme}.{width}.png"));
                }
            }
            File.WriteAllText(Path.ChangeExtension(outputPath, ".checks.json"), JsonSerializer.Serialize(new { Checks = checks, ProductSHA256 = Convert.ToHexString(SHA256.HashData(File.ReadAllBytes(typeof(FilterToolWpfView).Assembly.Location))), Scope = "Automated visible WPF host; seven PG tools and kernel modes, 480/520/720 inspector transitions, Dark/Light Wide/Compact96dpi. Compact720 uses supported collapsed-left layout. No actual mouse/productEXE/125dpi proof." }, new JsonSerializerOptions { WriteIndented = true }));
        }, captureFloatingToolWindow: false);
    }

    private static CaptureResult CaptureWorkbenchParameterAccess(string outputPath)
    {
        OpenVisionShellHostView host = CreateShellHost("Smoke_VM02_ParameterAccess", false);
        List<object> cases = new(); string directory = Path.GetDirectoryName(outputPath)!;
        return CaptureWindowWithContent(host, outputPath, 1280, 760, () =>
        {
            host.Workbench.ResetLayoutCommand.Execute(null); host.Workbench.Tool.ConfigureAutoRunPreference(() => false, _ => { }); Pump(5);
            int runs = host.NativePreviewRunCount, layers = host.LayerDocumentCount; string route = host.DirectResultRouteText;
            Grid unmeasured = (Grid)Activator.CreateInstance(Assembly.Load("System.Windows.Controls.WpfPropertyGrid").GetType("System.Windows.Controls.WpfPropertyGrid.Controls.RangeEditorBase")!);
            cases.Add(new { Case = "vendor Range before measure/load", Endpoints = FindRangeEditorValueTextBoxes(unmeasured).Count, PreservedEmptyTemplateFallback = true });
            foreach (VISION_MENU tool in new[] { VISION_MENU.Blob, VISION_MENU.Contour, VISION_MENU.Matching, VISION_MENU.Line })
            {
                host.SelectToolForTest(tool); Pump(6);
                if (tool == VISION_MENU.Matching) { SetFloatingPropertyGridPropertyValue("parameter angle row", "USE_FIND_ANGLE", true); Pump(5); }
                string toolRoute = host.DirectResultRouteText;
                System.Windows.Controls.WpfPropertyGrid.PropertyGrid grid = GetActiveFloatingPropertyGrid("parameter " + tool);
                Control inner = ReadPrivateField<Control>(grid, "innerPropertyGrid"); object selected = grid.SelectedObject;
                VisionToolSingleInputPropertyToolShell shell = FindVisualChildren<VisionToolSingleInputPropertyToolShell>(host).Single(item => item.IsVisible);
                ScrollViewer horizontal = (ScrollViewer)shell.FindName("propertyGridScrollViewer");
                foreach (string theme in new[] { "Dark", "Light" })
                {
                    (theme == "Dark" ? host.Workbench.SelectDarkThemeCommand : host.Workbench.SelectLightThemeCommand).Execute(null); Pump(5);
                    AssertNear(host.Workbench.RightPanelWidth.Value, 480D, "parameter Compact outer480");
                    AssertDockedSingleInputToolLayout("parameter " + tool + " " + theme);
                    if (tool != VISION_MENU.Line)
                    {
                        if (tool == VISION_MENU.Matching)
                        {
                            AssertFloatingRangeEditorEndpointAllowsTransientText("parameter empty transient", "FIND_ANGLE_MIN", 0, string.Empty, -45D);
                            AssertFloatingRangeEditorEndpointAllowsTransientText("parameter signed transient", "FIND_ANGLE_MIN", 0, "-", -45D);
                            SetFloatingRangeEditorEndpointTextValue("parameter signed max", "FIND_ANGLE_MIN", 1, 45D);
                            SetFloatingRangeEditorEndpointSliderValue("parameter max slider", "FIND_ANGLE_MIN", 1, 60D);
                            AssertFloatingSelectedObjectNumericProperty("parameter immediate slider binding", "FIND_ANGLE_MAX", 60D);
                            SetFloatingRangeEditorEndpointTextValue("parameter max restore", "FIND_ANGLE_MIN", 1, 45D);
                            TextBox minEndpoint = FindRangeEditorValueTextBoxes(GetFloatingRangeEditorForProperty("parameter min focus-loss", "FIND_ANGLE_MIN"))[0];
                            minEndpoint.Focus(); minEndpoint.Text = "-44"; shell.InputLayerComboBox.Focus(); Pump(5);
                            AssertFloatingSelectedObjectNumericProperty("parameter focus-loss binding", "FIND_ANGLE_MIN", -44D);
                            SetFloatingRangeEditorEndpointTextValue("parameter min restore", "FIND_ANGLE_MIN", 0, -45D);
                        }
                        AssertPropertyGridRangeEditorLayout(grid, "parameter " + tool + " " + theme + " initial");
                    }
                    double requiredWidth = inner.MinWidth, extent = horizontal.ExtentWidth;
                    TextBox? endpoint = FindVisualChildren<Grid>(grid).Where(item => item.GetType().Name == "RangeEditorBase" && item.IsVisible).SelectMany(FindRangeEditorValueTextBoxes).FirstOrDefault();
                    string pending = endpoint?.Text ?? string.Empty;
                    if (endpoint != null) { endpoint.Focus(); endpoint.Text = "-"; }
                    SetActivePropertyGridSearchText("parameter search", "__vm02_no_match__"); Pump(5);
                    AssertActivePropertyGridSearchEmptyMessageVisible("parameter empty search", true);
                    host.Workbench.IsRightCollapsed = true; Pump(4);
                    (theme == "Dark" ? host.Workbench.SelectLightThemeCommand : host.Workbench.SelectDarkThemeCommand).Execute(null); Pump(4);
                    host.Workbench.IsRightCollapsed = false; Pump(5);
                    SetActivePropertyGridSearchText("parameter search restore", string.Empty); Pump(5);
                    (theme == "Dark" ? host.Workbench.SelectDarkThemeCommand : host.Workbench.SelectLightThemeCommand).Execute(null); Pump(5);
                    if (!ReferenceEquals(selected, grid.SelectedObject) || (endpoint != null && !string.Equals(endpoint.Text, pending, StringComparison.Ordinal)))
                        throw new InvalidOperationException("Search/visibility/theme did not preserve the selected model and valid endpoint after transient focus loss.");
                    AssertNear(inner.MinWidth, requiredWidth, "parameter reveal required width");
                    AssertNear(horizontal.ExtentWidth, extent, "parameter reveal extent without growth");
                    AssertDockedSingleInputToolLayout("parameter reveal " + tool + " " + theme);
                    if (tool != VISION_MENU.Line) AssertPropertyGridRangeEditorLayout(grid, "parameter " + tool + " " + theme + " reveal");
                    if (tool == VISION_MENU.Matching)
                    {
                        SetFloatingPropertyGridPropertyValue("parameter angle hide", "USE_FIND_ANGLE", false); Pump(5);
                        if (inner.MinWidth != 0D) throw new InvalidOperationException("Hidden Matching Range retained a stale content minimum.");
                        SetFloatingPropertyGridPropertyValue("parameter angle reveal", "USE_FIND_ANGLE", true); Pump(5);
                        AssertNear(inner.MinWidth, requiredWidth, "angle reveal required width");
                        AssertPropertyGridRangeEditorLayout(grid, "parameter angle reveal " + theme);
                    }
                    if (host.NativePreviewRunCount != runs || host.LayerDocumentCount != layers || host.DirectResultRouteText != toolRoute)
                        throw new InvalidOperationException("Parameter editing/search/theme/visibility changed execution/layers or the selected Tool route.");
                    if (horizontal.ScrollableWidth > 0D) horizontal.ScrollToRightEnd();
                    ScrollViewer? vertical = FindPrimaryPropertyGridScrollViewer(grid); vertical?.ScrollToBottom(); Pump(4);
                    string capture = Path.Combine(directory, "parameter-" + tool + "-" + theme + ".png");
                    ScreenshotPngWriter.WriteElementPng(host, capture, 1280, 760);
                    horizontal.ScrollToLeftEnd(); vertical?.ScrollToTop(); Pump(3);
                    cases.Add(new { Tool = tool.ToString(), Theme = theme, Outer = host.Workbench.RightPanelWidth.Value, HostWidth = shell.PropertyGridHost.ActualWidth, HostHeight = shell.PropertyGridHost.ActualHeight, ContentMinimum = inner.MinWidth, horizontal.ExtentWidth, horizontal.ViewportWidth, RequiredBefore = requiredWidth, ExtentBefore = extent, NoGrowthAfterSearchCollapseThemeReveal = true, Capture = capture });
                }
            }
            host.SelectToolForTest(VISION_MENU.Matching); Pump(5); SetFloatingPropertyGridPropertyValue("parameter float angle", "USE_FIND_ANGLE", true); Pump(5);
            System.Windows.Controls.WpfPropertyGrid.PropertyGrid matchingGrid = GetActiveFloatingPropertyGrid("parameter float");
            object matchingObject = matchingGrid.SelectedObject;
            string parameterMatchingRoute = host.DirectResultRouteText;
            if (!host.FloatDockedWpfToolWindowForTest()) throw new InvalidOperationException("Parameter access could not float the existing editor.");
            Pump(6); AssertPropertyGridRangeEditorLayout(matchingGrid, "parameter float Range");
            if (!host.DockActiveWpfToolWindowForTest()) throw new InvalidOperationException("Parameter access could not redock the existing editor.");
            Pump(6); AssertPropertyGridRangeEditorLayout(matchingGrid, "parameter redock Range"); AssertDockedSingleInputToolLayout("parameter redock");
            if (!ReferenceEquals(matchingObject, matchingGrid.SelectedObject) || host.NativePreviewRunCount != runs || host.LayerDocumentCount != layers || host.DirectResultRouteText != parameterMatchingRoute)
                throw new InvalidOperationException("Parameter access changed model/execution/layer/route during scroll/search/visibility/theme/dock/float: " + JsonSerializer.Serialize(new { SameModel = ReferenceEquals(matchingObject, matchingGrid.SelectedObject), RunsBefore = runs, RunsAfter = host.NativePreviewRunCount, LayersBefore = layers, LayersAfter = host.LayerDocumentCount, RouteBefore = parameterMatchingRoute, RouteAfter = host.DirectResultRouteText }));
            System.Windows.Controls.WpfPropertyGrid.PropertyGrid unwrapped = new() { SelectedObject = new BlobProperty(), IsCompactDensity = true };
            unwrapped.ApplyDisplayOptions(OpenVisionLab.PropertyGrid.PropertyGridDisplayOptions.ToolForm);
            Window probeWindow = new() { Content = unwrapped, Width = 680D, Height = 540D, Owner = Window.GetWindow(host), ShowInTaskbar = false };
            probeWindow.Show();
            try
            {
                Pump(6); Control probeInner = ReadPrivateField<Control>(unwrapped, "innerPropertyGrid"); object rangeModel = unwrapped.SelectedObject;
                double requiredWidth = probeInner.MinWidth;
                foreach (System.Windows.Controls.WpfPropertyGrid.PropertyGridThemeVariant theme in new[] { System.Windows.Controls.WpfPropertyGrid.PropertyGridThemeVariant.Dark, System.Windows.Controls.WpfPropertyGrid.PropertyGridThemeVariant.Default })
                {
                    unwrapped.ThemeVariant = theme; Pump(5); AssertPropertyGridRangeEditorLayout(unwrapped, "unwrapped bridge " + theme);
                    AssertNear(probeInner.MinWidth, requiredWidth, "unwrapped bridge stable width");
                    unwrapped.SelectedObject = new { Value = 1D }; Pump(5);
                    AssertNear(probeInner.MinWidth, 0D, "unwrapped bridge non-Range rebind releases minimum");
                    unwrapped.SelectedObject = rangeModel; Pump(5); AssertPropertyGridRangeEditorLayout(unwrapped, "unwrapped bridge rebind " + theme);
                    AssertNear(probeInner.MinWidth, requiredWidth, "unwrapped bridge restored width");
                    cases.Add(new { Case = "unwrapped bridge theme/rebind", Theme = theme.ToString(), RequiredWidth = requiredWidth, Actual = probeInner.MinWidth, NonRangeMinimumReleased = true, NoToolShellWrapper = true });
                }
            }
            finally { probeWindow.Close(); }
            File.WriteAllText(Path.ChangeExtension(outputPath, ".cases.json"), JsonSerializer.Serialize(new { Cases = cases, NativeRuns = runs, Layers = layers, Route = route, NoImplicitExecution = true, Scope = "Current-source in-process Compact480 Range/access/height/footer/normalization; separate from actual EXE input/native DPI" }, new JsonSerializerOptions { WriteIndented = true }));
        });
    }

    private static CaptureResult CaptureApprovedPoliciesUi(string outputPath, bool compact)
    {
        GlobalState global = new(); global.Recipe.Name = "Smoke_ApprovedUi_" + Guid.NewGuid().ToString("N"); global.Recipe.SaveTools();
        VisionPipelineStorage.Save(global.Recipe.Name, new VisionPipeline { Name = "Main" }); VisionPipelineStorage.SaveActivePipelineName(global.Recipe.Name, "Main");
        global.System.SaveWorkbenchLayout(new SystemStateConfig { WorkbenchLayoutVersion = 1, WorkbenchRightWidth = compact ? 480D : 0D });
        using DisplayManagerService display = new(); OpenVisionShellHostWindow window = new(new ApplicationRuntimeContext(global, display)); window.ClearValue(OpenVisionShellHostWindow.ClosingCommandProperty);
        OpenVisionShellHostView host = window.ShellHostForSmoke;
        return CaptureStandaloneWindow(window, outputPath, compact ? 1280 : 1600, compact ? 760 : 900, () =>
        {
            var model = host.Workbench; List<object> checks = new(); OpenVisionLanguage initial = OpenVisionLanguageService.CurrentLanguage;
            void Check(bool ok, string label) { if (!ok) throw new InvalidOperationException("Approved UI: " + label); checks.Add(new { Case = label, PASS = true }); File.WriteAllText(Path.ChangeExtension(outputPath, ".checks.json"), JsonSerializer.Serialize(checks)); }
            try
            {
                model.Tool.ConfigureAutoRunPreference(() => false, _ => { });
                double expected = compact ? 480D : 520D;
                Check(model.RightPanelWidth.Value == expected && model.RightPanelMinimum == 480D, "Compact default/request480 and Wide unchanged");
                if (compact) { model.RightPanelWidth = new GridLength(480D); Check(model.RightPanelWidth.Value == 480D, "Compact resize floor480"); }
                int runs = host.NativePreviewRunCount, layers = host.LayerDocumentCount; string route = host.DirectResultRouteText; string draft = host.RecipeCommands.LlmXmlDraftText;
                TextBlock revision = FindVisualChildren<TextBlock>(host).Single(x => AutomationProperties.GetAutomationId(x) == "WorkbenchStatusRecipeRevision");
                TextBlock saved = FindNamedVisualChild<TextBlock>(host, "mainRecipeSaveStatusText");
                Check(revision.Text == "r0" && saved.Text.EndsWith(" · r0", StringComparison.Ordinal), "actual W09/W02 legacy r0 binding");
                model.Pipeline.InsertStep(0, new VisionPipelineStep { Name = "Mean", ToolType = "Mean", InputLayer = "Main", OutputLayer = "Out" }); host.RecipeCommands.SaveRecipeCommand.Execute(null); Pump(3);
                Check(revision.Text == "r1" && saved.Text.EndsWith(" · r1", StringComparison.Ordinal) && !host.RecipeCommands.HasRecipeSaveFailure, "actual W09/W02 successful r1 binding");
                File.WriteAllText(Path.ChangeExtension(outputPath, ".save-boundary.json"), JsonSerializer.Serialize(new { RunsBefore = runs, RunsAfter = host.NativePreviewRunCount, LayersBefore = layers, LayersAfter = host.LayerDocumentCount, RouteBefore = route, RouteAfter = host.DirectResultRouteText }));
                Check(host.NativePreviewRunCount == runs, "explicit recipe save does not run");
                runs = host.NativePreviewRunCount; layers = host.LayerDocumentCount; route = host.DirectResultRouteText;
                string recipeDirectory = Path.GetDirectoryName(RecipeWorkspaceService.GetVisionDataPath(global.Recipe.Name));
                var beforeXml = Directory.EnumerateFiles(recipeDirectory, "*.xml", SearchOption.AllDirectories).ToDictionary(path => path, path => Convert.ToHexString(System.Security.Cryptography.SHA256.HashData(File.ReadAllBytes(path))));
                foreach (var pair in new[] { (VISION_MENU.Line, OpenVisionGuidedSetupCatalog.PinGapTemplate), (VISION_MENU.Blob, OpenVisionGuidedSetupCatalog.BlobTemplate), (VISION_MENU.Contour, OpenVisionGuidedSetupCatalog.ContourTemplate), (VISION_MENU.Matching, OpenVisionGuidedSetupCatalog.MatchingTemplate), (VISION_MENU.FeatureMatching, OpenVisionGuidedSetupCatalog.FeatureMatchingTemplate), (VISION_MENU.EdgeBasedMatching, OpenVisionGuidedSetupCatalog.EdgeBasedMatchingTemplate), (VISION_MENU.Mean, OpenVisionGuidedSetupCatalog.MeanTemplate) })
                {
                    typeof(OpenVisionShellHostView).GetMethod("OpenGuidedSetupForTool", BindingFlags.Instance | BindingFlags.NonPublic)!.Invoke(host, new object[] { pair.Item1 }); Pump(3);
                    Check(FindNamedVisualChild<TabItem>(host, "tabRecipeGuidedSetup").IsSelected && host.RecipeCommands.SelectedLlmToolTemplate == pair.Item2 && host.RecipeCommands.LlmXmlDraftText == draft, "Builder mapped intent " + pair.Item1);
                }
                Check(!OpenVisionGuidedSetupCatalog.TryResolveTemplate(VISION_MENU.Threshold, out _), "unsupported Threshold absent");
                Check(host.RecipeCommands.IsRecipeManagerDetailContextActive && FindNamedVisualChild<TabItem>(host, "tabRecipeGuidedSetup").IsVisible, "actual Builder detail is visible");
                ScreenshotPngWriter.WriteElementPng(window, Path.ChangeExtension(outputPath, ".Builder.png"), compact ? 1280 : 1600, compact ? 760 : 900);
                ClickVisibleButtonByAutomationId(host, "HostRecipeManagerCloseButton", "Builder return"); Pump(3);
                if (FindVisualChildren<Button>(host).Any(button => button.IsVisible && AutomationProperties.GetAutomationId(button) == "HostRecipeManagerCloseButton")) { ClickVisibleButtonByAutomationId(host, "HostRecipeManagerCloseButton", "Library close"); Pump(3); }
                foreach (string theme in new[] { "Dark", "Light" })
                {
                    (theme == "Dark" ? model.SelectDarkThemeCommand : model.SelectLightThemeCommand).Execute(null); OpenVisionLanguageService.SetLanguage(theme == "Dark" ? OpenVisionLanguage.Korean : OpenVisionLanguage.English, false); Pump(3);
                    File.WriteAllText(Path.ChangeExtension(outputPath, "." + theme + ".rN-raw.json"), JsonSerializer.Serialize(new { Theme = theme, RevisionText = revision.Text, RevisionWidth = revision.ActualWidth, RevisionDesired = revision.DesiredSize.Width, RevisionVisible = revision.IsVisible, SavedText = saved.Text, SavedWidth = saved.ActualWidth, SavedDesired = saved.DesiredSize.Width, SavedVisible = saved.IsVisible, model.HasRecipeSaveStatus, CurrentRecipe = global.Recipe.Name, Main = host.RecipeCommands.MainRecipeName, Selected = host.RecipeCommands.SelectedRecipeName, Pipeline = host.RecipeCommands.SelectedPipelineOption?.PipelineName, global.Data.SavedRevision, host.RecipeCommands.IsSwitchingRecipe }));
                    ScreenshotPngWriter.WriteElementPng(window, Path.ChangeExtension(outputPath, "." + theme + ".pre-assert.png"), compact ? 1280 : 1600, compact ? 760 : 900);
                    Check(revision.IsVisible && revision.ActualWidth + revision.Margin.Left + revision.Margin.Right >= revision.DesiredSize.Width && saved.ActualWidth >= saved.DesiredSize.Width && revision.Text == "r1" && saved.Text.EndsWith(" · r1", StringComparison.Ordinal), "locale/theme current rN " + theme);
                    ScreenshotPngWriter.WriteElementPng(window, Path.ChangeExtension(outputPath, "." + theme + ".png"), compact ? 1280 : 1600, compact ? 760 : 900);
                }
                File.WriteAllText(Path.ChangeExtension(outputPath, ".guided-boundary.json"), JsonSerializer.Serialize(new { RunsBefore = runs, RunsAfter = host.NativePreviewRunCount, LayersBefore = layers, LayersAfter = host.LayerDocumentCount, RouteBefore = route, RouteAfter = host.DirectResultRouteText }));
                Check(host.NativePreviewRunCount == runs && host.LayerDocumentCount == layers && host.DirectResultRouteText == route && global.Data.SavedRevision == 1, "Guided no implicit Run/layer/route mutation");
                Check(beforeXml.Count == Directory.EnumerateFiles(recipeDirectory, "*.xml", SearchOption.AllDirectories).Count() && beforeXml.All(entry => entry.Value == Convert.ToHexString(System.Security.Cryptography.SHA256.HashData(File.ReadAllBytes(entry.Key)))), "Guided recipe XML bytes unchanged");
                if (compact)
                {
                    host.SelectToolForTest(VISION_MENU.Line); Pump(5);
                    VisionToolSingleInputPropertyToolShell shell = (VisionToolSingleInputPropertyToolShell)host.ActiveNativeDocumentForTest!.View.FindName("toolShell");
                    File.WriteAllText(Path.ChangeExtension(outputPath, ".pg-bounds.json"), JsonSerializer.Serialize(new { Right = model.RightPanelWidth.Value, HostWidth = shell.PropertyGridHost.ActualWidth, HostHeight = shell.PropertyGridHost.ActualHeight, shell.PropertyGridHost.IsVisible }));
                    Check(shell.PropertyGridHost.IsVisible && shell.PropertyGridHost.ActualWidth >= 480D, "Compact Line actual PG host keeps existing480 guard");
                    AssertDockedSingleInputToolLayout("Compact480 Line");
                    ScreenshotPngWriter.WriteElementPng(window, Path.ChangeExtension(outputPath, ".Compact-PG.png"), 1280, 760);
                    foreach (VISION_MENU tool in new[] { VISION_MENU.Blob, VISION_MENU.Contour, VISION_MENU.Matching })
                    {
                        host.SelectToolForTest(tool); Pump(5);
                        if (tool == VISION_MENU.Matching) { SetFloatingPropertyGridPropertyValue("Compact480 angle row", "USE_FIND_ANGLE", true); Pump(5); }
                        AssertDockedSingleInputToolLayout("Compact480 " + tool);
                        AssertPropertyGridRangeEditorLayout(GetActiveFloatingPropertyGrid("Compact480 " + tool), "Compact480 " + tool + " range");
                        ScreenshotPngWriter.WriteElementPng(window, Path.ChangeExtension(outputPath, ".Compact-PG-" + tool + ".png"), 1280, 760);
                    }
                    Check(host.NativePreviewRunCount == runs && host.LayerDocumentCount == layers && host.DirectResultRouteText == route, "Compact480 scroll/edit access does not run or change layers/routes");
                }
            }
            finally { OpenVisionLanguageService.SetLanguage(initial, false); }
        });
    }

    private static CaptureResult CaptureWorkbenchLayoutPolicy(string outputPath)
    {
        int saves = 0;
        bool allowSave = true;
        SystemStateConfig saved = new();
        using OpenVisionWorkbenchViewModel model = new(new SystemStateConfig(), value => { saves++; saved = value; return allowSave; });
        model.UpdateViewport(1536D, 826D);
        AssertNear(model.LeftPanelWidth.Value, 264D, "responsive left");
        AssertNear(model.RightPanelWidth.Value, 488D, "responsive right");
        if (!model.IsToolPaletteCollapsed || saves != 0) { throw new InvalidOperationException("First-use display restore saved/executed or ignored height rule."); }
        model.UpdateViewport(1600D, 900D);
        if (model.IsToolPaletteCollapsed || saves != 0) { throw new InvalidOperationException("Intermediate first-use size survived final layout."); }
        model.LeftPanelWidth = new GridLength(320D);
        model.RightPanelWidth = new GridLength(530D);
        model.BottomPanelHeight = new GridLength(240D);
        if (saves != 0) { throw new InvalidOperationException("Drag delta persisted before explicit completion."); }
        model.CommitLayoutCommand.Execute(null);
        using (OpenVisionWorkbenchViewModel restored = new(saved, _ => throw new InvalidOperationException("Restore must not save.")))
        {
            restored.UpdateViewport(1280D, 760D);
            AssertNear(saved.WorkbenchLeftWidth, 320D, "policy requested left");
            AssertNear(saved.WorkbenchRightWidth, 530D, "policy requested right");
            AssertNear(restored.LeftPanelWidth.Value, 308D, "policy reopen left display");
            AssertNear(restored.RightPanelWidth.Value, 480D, "policy reopen right display");
            AssertNear(restored.BottomPanelHeight.Value, 240D, "policy reopen bottom");
        }
        foreach (SystemStateConfig invalid in new[] { new SystemStateConfig { WorkbenchLayoutVersion = 99 }, new SystemStateConfig { WorkbenchLayoutVersion = 1, WorkbenchLeftWidth = double.NaN, WorkbenchRightWidth = double.PositiveInfinity, WorkbenchBottomHeight = -20D, WorkbenchBottomTab = 50 } })
        {
            using OpenVisionWorkbenchViewModel recovered = new(invalid, _ => throw new InvalidOperationException("Invalid restore must not save."));
            recovered.UpdateViewport(1280D, 760D);
            AssertNear(recovered.LeftPanelWidth.Value, 248D, "invalid left recovery");
            AssertNear(recovered.RightPanelWidth.Value, 480D, "invalid right recovery");
            AssertNear(recovered.BottomPanelHeight.Value, 200D, "invalid bottom recovery");
            if (!recovered.HasLayoutStatus) { throw new InvalidOperationException("Invalid restore did not expose default-layout status."); }
        }
        allowSave = false;
        model.ToggleLeftPanelCommand.Execute(null);
        if (!model.IsLeftCollapsed || !model.HasLayoutStatus || model.LayoutStatusText != OpenVisionLanguageService.T("Main.LayoutSaveFailed")) { throw new InvalidOperationException("Save failure lost visible state or its failure status."); }
        allowSave = true;
        model.ResetLayoutCommand.Execute(null);
        if (model.HasLayoutStatus || model.IsLeftCollapsed) { throw new InvalidOperationException("Valid retry/reset did not recover save state."); }
        foreach ((double width, double height, double left, double right, double bottom) in new[] { (1920D, 1032D, 296D, 520D, 256D), (1536D, 826D, 264D, 488D, 256D), (1280D, 760D, 248D, 480D, 200D), (1920D, 1032D, 296D, 520D, 256D) })
        {
            model.UpdateViewport(width, height);
            AssertNear(model.LeftPanelWidth.Value, left, "reset responsive left");
            AssertNear(model.RightPanelWidth.Value, right, "reset responsive right");
            AssertNear(model.BottomPanelHeight.Value, bottom, "reset responsive bottom");
            model.CommitLayoutCommand.Execute(null);
            if (saved.WorkbenchLeftWidth != 0D || saved.WorkbenchRightWidth != 0D || saved.WorkbenchBottomHeight != 0D) { throw new InvalidOperationException("Display/commit replaced default sentinels."); }
            using OpenVisionWorkbenchViewModel defaults = new(saved, _ => throw new InvalidOperationException("Default restore must not save."));
            defaults.UpdateViewport(width, height);
            AssertNear(defaults.LeftPanelWidth.Value, left, "reopened default left");
            AssertNear(defaults.RightPanelWidth.Value, right, "reopened default right");
            AssertNear(defaults.BottomPanelHeight.Value, bottom, "reopened default bottom");
        }
        model.LeftPanelWidth = new GridLength(320D);
        model.RightPanelWidth = new GridLength(500D);
        model.BottomPanelHeight = new GridLength(600D);
        foreach ((double width, double height) in new[] { (1920D, 1032D), (1536D, 826D), (1280D, 760D), (1920D, 1032D) })
        {
            model.UpdateViewport(width, height);
            model.CommitLayoutCommand.Execute(null);
            AssertNear(saved.WorkbenchLeftWidth, 320D, "resize retains left request");
            AssertNear(saved.WorkbenchRightWidth, 500D, "resize retains right request");
            AssertNear(saved.WorkbenchBottomHeight, 600D, "resize retains bottom request");
            using OpenVisionWorkbenchViewModel restored = new(saved, _ => throw new InvalidOperationException("Requested restore must not save."));
            restored.UpdateViewport(width, height);
            double expectedLeft = Math.Min(320D, width - 12D - 480D - 480D);
            AssertNear(restored.LeftPanelWidth.Value, expectedLeft, "resize/reopen displayed left");
            AssertNear(restored.RightPanelWidth.Value, Math.Min(500D, width - 12D - expectedLeft - 480D), "resize/reopen displayed right");
            AssertNear(restored.BottomPanelHeight.Value, Math.Min(600D, height - 241D - 120D), "resize/reopen displayed bottom");
        }
        model.RightPanelWidth = new GridLength(480D);
        model.UpdateViewport(1280D, 760D);
        model.CommitLayoutCommand.Execute(null);
        AssertNear(saved.WorkbenchRightWidth, 480D, "Compact display floor retains accepted480 request");
        model.UpdateViewport(1920D, 1032D);
        AssertNear(model.RightPanelWidth.Value, 480D, "Wide restores accepted480 request");
        TextBlock result = new() { Text = "Workbench layout policy PASS", FontSize = 16 };
        File.WriteAllText(Path.ChangeExtension(outputPath, ".policy.json"), JsonSerializer.Serialize(new { saves, Cases = "viewport,save-on-completion,restore0save,invalid version/nonfinite/negative,save-failure retry" }));
        return CaptureElement(result, outputPath, 520, 100);
    }

    private static CaptureResult CaptureShellHostWindowMinimum(string outputPath)
    {
        OpenVisionShellHostWindow window = new(ApplicationRuntimeContext.CreateDefault());
        return CaptureStandaloneWindow(window, outputPath, 1600, 900, () =>
        {
            IntPtr hwnd = new System.Windows.Interop.WindowInteropHelper(window).Handle;
            DpiScale dpi = VisualTreeHelper.GetDpi(window);
            MethodInfo hook = typeof(OpenVisionShellHostWindow).GetMethod("WindowProc", BindingFlags.Static | BindingFlags.Instance | BindingFlags.NonPublic)!;
            Type adapter = typeof(OpenVisionShellHostWindow).Assembly.GetType("OpenVisionLab.OpenVisionWindowWorkArea", true)!;
            MethodInfo apply = adapter.GetMethod("Apply", BindingFlags.Static | BindingFlags.NonPublic)!;
            IntPtr buffer = Marshal.AllocHGlobal(40);
            List<object> cases = new();
            bool valid = true;
            try
            {
                int[] initial = { 13, 17, 0, 0, 0, 0, 200, 120, 5000, 4000 };
                Marshal.Copy(initial, 0, buffer, initial.Length);
                object[] args = { hwnd, 0x0024, IntPtr.Zero, buffer, false };
                hook.Invoke(hook.IsStatic ? null : window, args);
                int[] actual = new int[10]; Marshal.Copy(buffer, actual, 0, actual.Length);
                int expectedWidth = (int)Math.Ceiling(window.MinWidth * dpi.DpiScaleX), expectedHeight = (int)Math.Ceiling(window.MinHeight * dpi.DpiScaleY);
                bool current = (bool)args[4] && actual[6] >= expectedWidth && actual[7] >= expectedHeight;
                valid &= current;
                cases.Add(new { Case = "current-window-hook", DeclaredWidth = window.MinWidth, DeclaredHeight = window.MinHeight, dpi.DpiScaleX, dpi.DpiScaleY, Before = initial, Actual = actual, ExpectedWidth = expectedWidth, ExpectedHeight = expectedHeight, Handled = args[4], Pass = current });
                Marshal.Copy(initial, 0, buffer, initial.Length);
                apply.Invoke(null, apply.GetParameters().Length == 2 ? new object[] { hwnd, buffer } : new object[] { hwnd, buffer, 0D, 0D });
                int[] defaults = new int[10]; Marshal.Copy(buffer, defaults, 0, defaults.Length);
                bool same = defaults[6] == initial[6] && defaults[7] == initial[7] && defaults[2] == actual[2] && defaults[3] == actual[3] && defaults[4] == actual[4] && defaults[5] == actual[5] && defaults[8] == initial[8] && defaults[9] == initial[9];
                valid &= same;
                cases.Add(new { Case = "existing-default-consumer", Actual = defaults, Pass = same, Boundary = "existing SamplePicker default-call adapter behavior; not SamplePicker UI" });
                if (apply.GetParameters().Length == 4)
                {
                    foreach (double scale in new[] { 1D, 1.25D })
                    {
                        Marshal.Copy(initial, 0, buffer, initial.Length);
                        apply.Invoke(null, new object[] { hwnd, buffer, window.MinWidth * scale, window.MinHeight * scale });
                        int[] converted = new int[10]; Marshal.Copy(buffer, converted, 0, converted.Length);
                        int x = (int)Math.Ceiling(window.MinWidth * scale), y = (int)Math.Ceiling(window.MinHeight * scale);
                        bool pass = converted[6] == x && converted[7] == y; valid &= pass;
                        cases.Add(new { Case = "pure-DPI-conversion", Scale = scale, ExpectedWidth = x, ExpectedHeight = y, Actual = converted, Pass = pass, Boundary = "synthetic conversion only; not native125 runtime" });
                    }
                }
                File.WriteAllText(Path.ChangeExtension(outputPath, ".cases.json"), JsonSerializer.Serialize(cases, new JsonSerializerOptions { WriteIndented = true }));
                Size renderSize = window.RenderSize;
                ScreenshotPngWriter.WriteDpiAwareWindowPng(window, Path.ChangeExtension(outputPath, ".observed.png"));
                if (window.RenderSize != renderSize) throw new InvalidOperationException("Minimum observation capture changed Window layout.");
                if (!valid) throw new InvalidOperationException("Main native minimum track does not preserve declared Window minimum.");
            }
            finally { Marshal.FreeHGlobal(buffer); }
        });
    }

    private static CaptureResult CaptureShellHostWindowChrome(string outputPath)
    {
        OpenVisionLanguageService.SetLanguage(OpenVisionLanguage.Korean, false);
        OpenVisionShellHostWindow window = new(ApplicationRuntimeContext.CreateDefault());
        return CaptureStandaloneWindow(window, outputPath, 1600, 900, () =>
        {
            if (Math.Abs(window.ResponsiveScaleForSmoke - 1D) > 0.01D)
            {
                throw new InvalidOperationException(
                    $"WPF shell host reference scale was {window.ResponsiveScaleForSmoke:0.000}, expected 1.000.");
