            AssertVisibleAutomationIds(
                window,
                "WPF shell host window chrome",
                "OpenVisionWindowMinimizeButton",
                "OpenVisionWindowMaximizeRestoreButton",
                "OpenVisionWindowCloseButton");
        });
    }

