            if (!shellHost.HasDockingGuideOverlayForTest
                || !shellHost.IsDockingGuideOverlayHitTestSafeForTest
                || shellHost.IsDockingGuideOverlayVisibleForTest
                || shellHost.DockingGuideZoneCountForTest < 5)
