    private static CaptureResult CaptureShellHostWorkspaceAvalonDockTabs(string outputPath)
    {
        OpenVisionLanguageService.SetLanguage(OpenVisionLanguage.Korean, false);
        OpenVisionShellHostView shellHost = CreateShellHost("Smoke_WpfShellHostWorkspaceAvalonDockTabs");
        return CaptureWindowWithContent(shellHost, outputPath, 1600, 900, () =>
        {
            if (!shellHost.HasMainLayer
                || !shellHost.HasWorkspaceLayerPreview
                || !shellHost.IsDockedWorkspaceVisibleForTest
                || shellHost.IsSingleWorkspaceVisibleForTest
                || shellHost.DockedLayerCount < 1
                || shellHost.DockedLayerPaneCount != 1)
            {
                throw new InvalidOperationException(
                    "Main layer did not start as an AvalonDock workspace tab. "
                    + $"Main={shellHost.HasMainLayer}, WorkspacePreview={shellHost.HasWorkspaceLayerPreview}, "
                    + $"DockedVisible={shellHost.IsDockedWorkspaceVisibleForTest}, SingleVisible={shellHost.IsSingleWorkspaceVisibleForTest}, "
                    + $"Count={shellHost.DockedLayerCount}, Panes={shellHost.DockedLayerPaneCount}, Titles={shellHost.DockedLayerTitles}");
            }

            shellHost.SelectToolForTest(VISION_MENU.HSV);
            Pump(16);
            shellHost.RunActiveNativePreviewForTest();
            Pump(40);
            if (!shellHost.HasNativePreviewResult
                || !shellHost.DockedLayerTitles.Contains("Main", StringComparison.OrdinalIgnoreCase)
                || !shellHost.DockedLayerTitles.Contains("HSV_Preview", StringComparison.OrdinalIgnoreCase)
                || !string.Equals(shellHost.WorkspaceLayerTitle, "HSV_Preview", StringComparison.OrdinalIgnoreCase)
                || shellHost.DockedLayerCount < 2
                || shellHost.DockedLayerPaneCount != 1
                || shellHost.DockedLayerTabHeaderCount < 2
                || !shellHost.AreDockedLayerTabHeadersGestureReadyForTest)
            {
                throw new InvalidOperationException(
                    "Preview result layer did not join the AvalonDock workspace as a same-pane tab. "
                    + $"Result={shellHost.HasNativePreviewResult}, Count={shellHost.DockedLayerCount}, "
                    + $"Workspace={shellHost.WorkspaceLayerTitle}, Panes={shellHost.DockedLayerPaneCount}, Headers={shellHost.DockedLayerTabHeaderCount}, Titles={shellHost.DockedLayerTitles}");
            }

            if (!shellHost.ShowDockedLayerTabDragGuideForTest())
            {
                throw new InvalidOperationException("AvalonDock workspace tab was not available as a drag source.");
            }

            Pump(20);
            if (!shellHost.IsDockingGuideOverlayVisibleForTest || shellHost.DockingGuideZoneCountForTest < 5)
            {
                throw new InvalidOperationException("AvalonDock workspace tab drag guide did not become visible.");
            }
        }, captureFloatingToolWindow: false);
    }

    private static CaptureResult CaptureWorkbenchReadyStatus(string outputPath, int width, int height, string theme, bool routeOnly = false)
    {
        GlobalState global = new();
        global.Recipe.Name = "Smoke_WorkbenchReadyStatus";
        global.System.SaveWorkbenchLayout(new SystemStateConfig());
        OpenVisionShellHostWindow window = new(new ApplicationRuntimeContext(global, new DisplayManagerService()));
        OpenVisionShellHostView host = window.ShellHostForSmoke;
        List<object> cases = new();
        List<string> failures = new();
        return CaptureStandaloneWindow(window, outputPath, width, height, () =>
        {
            OpenVisionWindowTitleBar titleBar = FindVisualChildren<OpenVisionWindowTitleBar>(window).Single();
            foreach (FrameworkElement owner in new FrameworkElement[] { titleBar, host, window })
                owner.Resources.MergedDictionaries.Add(new ResourceDictionary { Source = new Uri($"/OpenVisionLab;component/UI/Wpf/OpenVisionWorkbench{theme}.xaml", UriKind.Relative) });
            Pump(12);
            OpenVisionLanguageService.SetLanguage(OpenVisionLanguage.Korean, false);
            using (Bitmap input = new(640, 360))
            {
                using Graphics graphics = Graphics.FromImage(input);
                graphics.Clear(DrawingColor.FromArgb(32, 48, 71));
                graphics.FillRectangle(System.Drawing.Brushes.Turquoise, 20, 20, 260, 140);
                graphics.FillEllipse(System.Drawing.Brushes.Orange, 360, 25, 220, 220);
                string inputPath = Path.Combine(Path.GetDirectoryName(outputPath)!, "Main_ready_owned.png");
                input.Save(inputPath, ImageFormat.Png);
                if (!host.LoadMainImageFromFileForTest(inputPath)) throw new InvalidOperationException("Owned ready-state input failed.");
            }
            Pump(12);
            AssertLoadedMainBannerAbsent(host);
            TextBlock title = (TextBlock)host.FindName("txtHostSelectedTool");
            TextBlock route = (TextBlock)host.FindName("txtHostSelectedRoute");
            TextBlock meta = (TextBlock)host.FindName("txtHostDirectStatus");
            TextBlock status = (TextBlock)host.FindName("txtHostWorkspaceStatus");
            int runs = host.NativePreviewRunCount;
            int layers = host.LayerDocumentCount;
            int docked = host.DockedLayerCount;
            string pipelineRoute = string.Join("|", host.Workbench.Pipeline.Rows.Select(row => row.Index + ":" + row.InputLayer + "->" + row.OutputLayer));
            if (!host.Workbench.Shell.HasWorkspaceInputImage || host.Workbench.Shell.WorkspaceInputSizeText != "640×360") throw new InvalidOperationException("Ready-state fixture did not show one Main document.");
            if (routeOnly)
            {
                OpenVisionShellHostChromeController chrome = (OpenVisionShellHostChromeController)typeof(OpenVisionShellHostView).GetField("chromeController", BindingFlags.NonPublic | BindingFlags.Instance)!.GetValue(host)!;
                TextBlock directRoute = (TextBlock)host.FindName("txtHostSelectedRoute");
                BitmapSource input = host.Workbench.Shell.WorkspaceInputPreview;
                byte[] working = VisionPipelineExecutionPlan.SerializePipeline(host.Workbench.Pipeline.WorkingCopyForTest);
                byte[] saved = File.ReadAllBytes(RecipeWorkspaceService.GetVisionPipelinePath(global.Recipe.Name, host.Workbench.Pipeline.SelectedPipelineName));
                if (host.Workbench.Shell.SelectedItem != null) throw new InvalidOperationException("Route localization fixture must start with no tool selected.");
                foreach (string paletteName in new[] { "Dark", "Light" })
                {
                    ResourceDictionary[] palettes = new FrameworkElement[] { titleBar, host, window }.Select(_ => new ResourceDictionary { Source = new Uri($"/OpenVisionLab;component/UI/Wpf/OpenVisionWorkbench{paletteName}.xaml", UriKind.Relative) }).ToArray();
                    FrameworkElement[] owners = new FrameworkElement[] { titleBar, host, window };
                    for (int owner = 0; owner < owners.Length; owner++) owners[owner].Resources.MergedDictionaries.Add(palettes[owner]);
                    try
                    {
                        foreach ((string state, Action apply, string key) in new (string, Action, string)[]
                        {
                            ("WorkspaceEmpty", chrome.SetWorkspaceEmptyStatus, "Shell.WorkspaceStatus.EmptyRoute"),
                            ("ImageReady", chrome.SetWorkspaceImageReadyStatus, "Shell.MainAction.ImageReadyRoute"),
                            ("SampleReady", chrome.SetWorkspaceSampleReadyStatus, "Shell.WorkspaceStatus.SampleRoute"),
                            ("Pending", chrome.SetDirectRunPending, ""),
                            ("Succeeded", () => chrome.SetDirectRunSucceeded(), "")
                        })
                        {
                            OpenVisionLanguageService.SetLanguage(OpenVisionLanguage.Korean, false); apply();
                            int localeIndex = 0;
                            foreach (OpenVisionLanguage locale in new[] { OpenVisionLanguage.Korean, OpenVisionLanguage.English, OpenVisionLanguage.Korean })
                            {
                                OpenVisionLanguageService.SetLanguage(locale, false); Pump(8);
                                string expected = key.Length == 0 ? locale == OpenVisionLanguage.English ? "Select a tool to preview a route." : "도구를 선택하면 예상 경로가 표시됩니다." : OpenVisionLanguageService.T(key);
                                string capture = Path.ChangeExtension(outputPath, $".{paletteName}-{state}-{localeIndex++}-{locale}.png");
                                ScreenshotPngWriter.WriteElementPng(window, capture, width, height);
                                bool matched = directRoute.Text == expected;
                                cases.Add(new { Theme = paletteName, State = state, Language = locale.ToString(), Width = width, Height = height, Expected = expected, Rendered = directRoute.Text, Getter = host.Workbench.Shell.SelectedRouteText, Status = matched ? "PASS" : "FAIL", Capture = capture, EvidenceKind = "in-process presentation state/localization refresh; Succeeded is synthetic, no inspection Run" });
                                if (!matched) failures.Add(paletteName + "/" + state + "/" + locale + " route stale: " + directRoute.Text);
                                if (host.NativePreviewRunCount != runs || host.LayerDocumentCount != layers || !ReferenceEquals(input, host.Workbench.Shell.WorkspaceInputPreview)
                                    || !working.SequenceEqual(VisionPipelineExecutionPlan.SerializePipeline(host.Workbench.Pipeline.WorkingCopyForTest)) || !saved.SequenceEqual(File.ReadAllBytes(RecipeWorkspaceService.GetVisionPipelinePath(global.Recipe.Name, host.Workbench.Pipeline.SelectedPipelineName))))
                                    throw new InvalidOperationException("Route localization changed execution/image/layer/working or saved pipeline state.");
                                TextBlock currentAction = FindVisualChildren<TextBlock>(host).Single(item => AutomationProperties.GetAutomationId(item) == "WorkbenchActionStatus");
                                if (!currentAction.IsVisible || currentAction.Text != OpenVisionLanguageService.T("Workbench.Action.ImageOpened") || host.Workbench.Shell.WorkspaceInputSizeText != "640×360")
                                    throw new InvalidOperationException("Chrome route refresh changed the visible current Main input/action.");
                                AssertElementWithinAncestor("Current Main action", currentAction, window); AssertLoadedMainBannerAbsent(host);
                            }
                        }
                    }
                    finally { for (int owner = 0; owner < owners.Length; owner++) owners[owner].Resources.MergedDictionaries.Remove(palettes[owner]); }
                }
                File.WriteAllText(Path.ChangeExtension(outputPath, ".route-cases.json"), JsonSerializer.Serialize(new { Cases = cases, Failures = failures, ProductAssembly = typeof(OpenVisionShellHostView).Assembly.Location, ProductSHA256 = Convert.ToHexString(SHA256.HashData(File.ReadAllBytes(typeof(OpenVisionShellHostView).Assembly.Location))) }, new JsonSerializerOptions { WriteIndented = true }));
                if (failures.Count > 0) throw new InvalidOperationException(string.Join(" | ", failures));
                return;
            }
            int index = 0;
            foreach (OpenVisionLanguage locale in new[] { OpenVisionLanguage.Korean, OpenVisionLanguage.English, OpenVisionLanguage.Korean })
            {
                OpenVisionLanguageService.SetLanguage(locale, false); Pump(8);
                string expected = string.Format(CultureInfo.CurrentCulture, OpenVisionLanguageService.T("Shell.DockedLayerStatusFormat"), docked);
                if (status.Text != expected) failures.Add(locale + " count stale: " + status.Text + " / " + expected);
                if (title.Text != OpenVisionLanguageService.T("Shell.MainAction.ImageReadyTitle") || route.Text != OpenVisionLanguageService.T("Shell.MainAction.ImageReadyRoute") || meta.Text != OpenVisionLanguageService.T("Shell.MainAction.ImageReadyStatus"))
                    failures.Add(locale + " ready state did not follow localization.");
                List<object> textBounds = new();
                foreach (string id in new[] { "WorkbenchStatusInputName", "WorkbenchStatusInputSize", "WorkbenchActionStatus" })
                {
                    TextBlock label = FindVisualChildren<TextBlock>(host).Single(item => AutomationProperties.GetAutomationId(item) == id);
                    string currentExpected = id == "WorkbenchStatusInputName" ? host.Workbench.Shell.WorkspaceInputStatusName
                        : id == "WorkbenchStatusInputSize" ? "640×360" : OpenVisionLanguageService.T("Workbench.Action.ImageOpened");
                    if (!label.IsVisible || label.Text != currentExpected) failures.Add(locale + " Main current-input binding stale: " + id + "=" + label.Text);
                    AssertElementWithinAncestor(id, label, window);
                    textBounds.Add(new { ID = id, label.Text, label.ActualWidth, label.ActualHeight, label.IsVisible, Expected = currentExpected });
                }
                AssertLoadedMainBannerAbsent(host);
                if (host.NativePreviewRunCount != runs || host.LayerDocumentCount != layers || host.DockedLayerCount != docked || host.IsNativeDocumentActive || host.IsActiveWpfToolWindowVisibleForTest || pipelineRoute != string.Join("|", host.Workbench.Pipeline.Rows.Select(row => row.Index + ":" + row.InputLayer + "->" + row.OutputLayer)))
                    failures.Add(locale + " presentation refresh changed execution, layer, tool or routing state.");
                string capture = Path.Combine(Path.GetDirectoryName(outputPath)!, Path.GetFileNameWithoutExtension(outputPath) + "_" + index++ + "_" + locale + ".png");
                ScreenshotPngWriter.WriteElementPng(window, capture, width, height);
                cases.Add(new { Theme = theme, Language = locale.ToString(), Width = width, Height = height, CountText = status.Text, ExpectedCount = expected, TextBounds = textBounds, Capture = capture, host.DockedLayerCount, host.NativePreviewRunCount, NoExecution = host.NativePreviewRunCount == runs });
            }
            File.WriteAllText(Path.ChangeExtension(outputPath, ".json"), JsonSerializer.Serialize(new { Cases = cases, Failures = failures, ProductAssembly = typeof(OpenVisionShellHostView).Assembly.Location, ProductSHA256 = Convert.ToHexString(SHA256.HashData(File.ReadAllBytes(typeof(OpenVisionShellHostView).Assembly.Location))) }, new JsonSerializerOptions { WriteIndented = true }));
            if (failures.Count > 0) throw new InvalidOperationException(string.Join(" | ", failures));
        });
    }

    private static CaptureResult CaptureWorkbenchLoadedInput(string outputPath, int width, int height, string theme)
    {
        GlobalState global = new();
        global.Recipe.Name = "Smoke_WorkbenchLoadedInput";
        global.System.SaveWorkbenchLayout(new SystemStateConfig());
        OpenVisionShellHostWindow window = new(new ApplicationRuntimeContext(global, new DisplayManagerService()));
        OpenVisionShellHostView host = window.ShellHostForSmoke;
        string inputPath = Path.Combine(Path.GetDirectoryName(outputPath)!, "Main_이미지_로드_취소_복구_640x360_20261009.png");
        string truncatedPath = Path.Combine(Path.GetDirectoryName(outputPath)!, "Main_truncated_owned.png");
        using (Bitmap input = new(640, 360))
        {
            using Graphics graphics = Graphics.FromImage(input);
            graphics.Clear(DrawingColor.FromArgb(32, 48, 71));
            graphics.FillRectangle(System.Drawing.Brushes.Turquoise, 20, 20, 260, 140);
            graphics.FillEllipse(System.Drawing.Brushes.Orange, 360, 25, 220, 220);
            input.Save(inputPath, ImageFormat.Png);
        }
        File.WriteAllBytes(truncatedPath, File.ReadAllBytes(inputPath).Take(32).ToArray());
        List<object> cases = new();
        return CaptureStandaloneWindow(window, outputPath, width, height, () =>
        {
            OpenVisionWindowTitleBar titleBar = FindVisualChildren<OpenVisionWindowTitleBar>(window).Single();
            foreach (FrameworkElement owner in new FrameworkElement[] { titleBar, host, window })
            {
                owner.Resources.MergedDictionaries.Add(new ResourceDictionary { Source = new Uri($"/OpenVisionLab;component/UI/Wpf/OpenVisionWorkbench{theme}.xaml", UriKind.Relative) });
            }
            Pump(12);
            FrameworkElement empty = FindVisualChildren<FrameworkElement>(host).Single(element => AutomationProperties.GetAutomationId(element) == "WorkbenchImagesEmpty");
            FrameworkElement loaded = FindVisualChildren<FrameworkElement>(host).Single(element => AutomationProperties.GetAutomationId(element) == "WorkbenchImagesLoaded");
            int runs = host.NativePreviewRunCount;
            string route = string.Join("|", host.Workbench.Pipeline.Rows.Select(row => row.Index + ":" + row.InputLayer + "->" + row.OutputLayer));
            if (!empty.IsVisible || loaded.IsVisible || host.Workbench.Shell.HasWorkspaceInputImage)
                throw new InvalidOperationException("Current-input projection must start empty.");
            if (!host.LoadMainImageFromFileForTest(inputPath)) throw new InvalidOperationException("Valid owned input failed.");
            Pump(12);
            Image thumbnail = FindVisualChildren<Image>(host).Single(element => AutomationProperties.GetAutomationId(element) == "WorkbenchCurrentInputPreview");
            TextBlock name = FindVisualChildren<TextBlock>(host).Single(element => AutomationProperties.GetAutomationId(element) == "WorkbenchCurrentInputName");
            BitmapSource current = host.Workbench.Shell.WorkspaceInputPreview;
            if (empty.IsVisible || !loaded.IsVisible || !host.Workbench.Shell.HasWorkspaceInputImage || !ReferenceEquals(thumbnail.Source, current) || !current.IsFrozen || current.PixelWidth != 640 || current.PixelHeight != 360 || name.Text != Path.GetFileName(inputPath))
                throw new InvalidOperationException("Loaded input did not replace the bottom empty state through the existing binding.");
            // Displaying a different output layer must not relabel or replace the source input.
            using (Bitmap output = new(80, 40))
            {
                using Graphics graphics = Graphics.FromImage(output);
                graphics.Clear(DrawingColor.Red);
                if (!host.AddLayerImageForTest("Owned_Output", output)) throw new InvalidOperationException("Owned output setup failed.");
            }
            if (!host.ActivateHostLayerForTest("Owned_Output")) throw new InvalidOperationException("Owned output activation failed.");
            Pump(8);
            if (!ReferenceEquals(current, host.Workbench.Shell.WorkspaceInputPreview) || name.Text != Path.GetFileName(inputPath))
                throw new InvalidOperationException("Output-layer state contaminated the source input projection.");
            if (host.LoadMainImageFromFileForTest(truncatedPath)) throw new InvalidOperationException("Truncated input was accepted.");
            Pump(8);
            if (!ReferenceEquals(current, host.Workbench.Shell.WorkspaceInputPreview) || name.Text != Path.GetFileName(inputPath) || !loaded.IsVisible)
                throw new InvalidOperationException("Decode failure replaced the valid input projection.");
            if (!host.LoadMainImageFromFileForTest(inputPath)) throw new InvalidOperationException("Valid retry failed.");
            Pump(8);
            foreach (OpenVisionLanguage locale in new[] { OpenVisionLanguage.Korean, OpenVisionLanguage.English })
            {
                OpenVisionLanguageService.SetLanguage(locale, false); Pump(8);
                if (empty.IsVisible || !loaded.IsVisible || name.Text != Path.GetFileName(inputPath) || thumbnail.Source == null)
                    throw new InvalidOperationException("Localization lost the current input state.");
                AssertElementWithinAncestor("current input preview", thumbnail, loaded);
                AssertElementWithinAncestor("current input full filename", name, loaded);
                if (name.TextTrimming != TextTrimming.CharacterEllipsis || Convert.ToString(name.ToolTip) != Path.GetFileName(inputPath)) throw new InvalidOperationException("Intentional filename trimming lost the full source name.");
                AssertBrushContrast(name.Foreground, (Brush)host.FindResource("OpenVision.Workbench.PanelBrush"), "Current input filename " + theme + " " + locale);
                ScreenshotPngWriter.WriteElementPng(window, Path.Combine(Path.GetDirectoryName(outputPath)!, Path.GetFileNameWithoutExtension(outputPath) + "_" + locale + ".png"), width, height);
                cases.Add(new { Theme = theme, Language = locale.ToString(), Width = width, Height = height, Filename = name.Text, PreviewFrozen = ((BitmapSource)thumbnail.Source).IsFrozen, EmptyVisible = empty.IsVisible, LoadedVisible = loaded.IsVisible, OutputIndependent = true, DecodeFailurePreserved = true, ValidRetry = true });
            }
            // Non-file Main updates use the current Main image rather than stale file metadata.
            using (Bitmap replacement = new(320, 180)) { host.SetMainLayerImageForTest(replacement); }
            Pump(8);
            if (host.Workbench.Shell.WorkspaceInputName != "Main" || host.Workbench.Shell.WorkspaceInputPreview.PixelWidth != 320 || host.Workbench.Shell.WorkspaceInputPreview.PixelHeight != 180)
                throw new InvalidOperationException("Main replacement retained stale input metadata.");
            if (!host.LoadMainImageFromFileForTest(inputPath)) throw new InvalidOperationException("Final input restore failed.");
            OpenVisionLanguageService.SetLanguage(OpenVisionLanguage.Korean, false); Pump(8);
            if (host.NativePreviewRunCount != runs || host.IsNativeDocumentActive || host.IsActiveWpfToolWindowVisibleForTest || route != string.Join("|", host.Workbench.Pipeline.Rows.Select(row => row.Index + ":" + row.InputLayer + "->" + row.OutputLayer)))
                throw new InvalidOperationException("Input presentation caused execution, tool opening or pipeline routing changes.");
            cases.Add(new { MainReplacement = true, NoExecution = true, PipelineRoutePreserved = true, ProductAssembly = typeof(OpenVisionShellHostView).Assembly.Location, ProductSHA256 = Convert.ToHexString(SHA256.HashData(File.ReadAllBytes(typeof(OpenVisionShellHostView).Assembly.Location))) });
            File.WriteAllText(Path.ChangeExtension(outputPath, ".json"), JsonSerializer.Serialize(cases, new JsonSerializerOptions { WriteIndented = true }));
        });
    }

    private static CaptureResult CaptureWorkbenchExecutionStatusGuards(string outputPath, bool formatterOnly = false)
    {
        GlobalState global = new(); global.Recipe.Name = "Smoke_ExecutionGuard_" + Guid.NewGuid().ToString("N")[..12]; VisionPipeline pipeline = new() { Name = "Main" };
        pipeline.Steps.Add(new VisionPipelineStep { Name = "Captured guard name", ToolType = "Threshold", InputLayer = "Main", OutputLayer = "GuardStepOut" });
        VisionPipelineStorage.Save(global.Recipe.Name, pipeline); VisionPipelineStorage.SaveActivePipelineName(global.Recipe.Name, "Main"); global.System.SaveWorkbenchLayout(new SystemStateConfig());
        OpenVisionShellHostWindow window = new(new ApplicationRuntimeContext(global, new DisplayManagerService())) { WindowStartupLocation = WindowStartupLocation.Manual, Left = -10000, Top = -10000, ShowActivated = false, ShowInTaskbar = false }; window.ClearValue(OpenVisionShellHostWindow.ClosingCommandProperty);
        OpenVisionShellHostView host = window.ShellHostForSmoke;
        return CaptureStandaloneWindow(window, outputPath, 1600, 900, () =>
        {
            List<object> cases = new(); var tool = host.Workbench.Tool; int actions = 0; bool auto = false; OpenVisionLanguageService.SetLanguage(OpenVisionLanguage.English, false); tool.ConfigureAutoRunPreference(() => auto, value => auto = value);
            tool.PropertyChanged += (_, e) => { if (e.PropertyName == nameof(tool.ExecutionActionKey)) actions++; };
            void Require(bool value, string label) { if (!value) throw new InvalidOperationException("ExecutionGuards: " + label); }
            void Record(object data) { cases.Add(data); File.WriteAllText(Path.ChangeExtension(outputPath, ".checks.json"), JsonSerializer.Serialize(cases, new JsonSerializerOptions { WriteIndented = true })); }
            long Token() => (long)typeof(OpenVisionWorkbenchToolViewModel).GetField("generation", BindingFlags.Instance | BindingFlags.NonPublic)!.GetValue(tool)!;
            using Bitmap seed = new(32, 24); using (Graphics graphics = Graphics.FromImage(seed)) graphics.Clear(DrawingColor.FromArgb(192, 192, 192)); string input = Path.ChangeExtension(outputPath, ".input.png"); seed.Save(input, ImageFormat.Png); Require(host.LoadMainImageFromFileForTest(input), "owned input");
            if (formatterOnly)
            {
                foreach (bool editing in new[] { true, false })
                {
                    OpenVisionLanguageService.SetLanguage(editing ? OpenVisionLanguage.Korean : OpenVisionLanguage.English, false);
                    if (editing) { tool.OpenStepRequested!(0); } else { host.SelectToolForTest(VISION_MENU.Threshold); }
                    Pump(3); VisionPipelineStep captured = VisionPipelineStepEditService.CopyStep(tool.CurrentStep); long token = Token();
                    for (int phase = 0; phase < 2; phase++)
                    {
                        if (phase == 0) { tool.NotifyExecutionStarted(token, captured); }
                        else { tool.PublishResult(token, new VisionPipelineStepResultSummary { Success = true, Executed = true, ToolType = "Threshold" }, captured); }
                        Pump(3); TextBlock text = FindVisualChildren<TextBlock>(host).Single(t => AutomationProperties.GetAutomationId(t) == "WorkbenchActionStatus");
                        string expected = editing ? phase == 0 ? "‘Captured guard name’ 단계 실행 중…" : "단계 실행 완료 · Captured guard name · 완료" : phase == 0 ? "Running Threshold tool…" : "Tool run completed · Threshold · Done";
                        string kind = phase == 0 ? "Running" : editing ? "Ok" : "";
                        Require(text.Text == expected && host.Workbench.MainActionKind == kind, "final formatter four branches");
                        string capture = Path.ChangeExtension(outputPath, "." + (editing ? "step" : "trial") + "-" + phase + ".png"); ScreenshotPngWriter.WriteDpiAwareWindowPng(window, capture);
                        Record(new { Case = "formatter-" + (editing ? "step" : "trial") + "-" + phase, Expected = expected, Actual = text.Text, Kind = kind, Capture = capture, DLLSHA256 = Convert.ToHexString(SHA256.HashData(File.ReadAllBytes(typeof(OpenVisionShellHostView).Assembly.Location))), ComponentRender = true, PASS = true });
                    }
                }
                return;
            }
            tool.OpenStepRequested!(0); Pump(3); long session = Token(); VisionPipelineStep step = VisionPipelineStepEditService.CopyStep(tool.CurrentStep);
            foreach (string result in new[] { "Done", "Ok", "Ng", "Error", "Cancelled", "Disabled", "NotRun" })
            {
                step.UseAcceptance = result == "Ok"; int before = actions; tool.NotifyExecutionStarted(session, step);
                tool.PublishResult(session, new VisionPipelineStepResultSummary { ToolType = "Threshold", Name = step.Name, Executed = result != "NotRun", Success = result is "Done" or "Ok" or "Ng", IsAcceptanceNg = result == "Ng", IsToolError = result == "Error", Skipped = result == "Disabled", ExecutionState = result == "Cancelled" ? VisionPipelineResultSummaryService.CancelledState : result == "NotRun" ? VisionPipelineResultSummaryService.NotRunAfterFailureState : string.Empty }, step); Pump(2);
                string expectedKind = result is "Done" or "Ok" ? "Ok" : result == "Ng" ? "Ng" : result == "Error" ? "Error" : "Warning";
                string expected = result is "Cancelled" or "Disabled" or "NotRun" ? "Run ended." : "Step run completed · Captured guard name · " + (result == "Ng" ? "NG" : result == "Error" ? "Error" : result == "Ok" ? "OK" : "Done");
                TextBlock status = FindVisualChildren<TextBlock>(host).Single(t => AutomationProperties.GetAutomationId(t) == "WorkbenchActionStatus");
                Require(actions == before + 2 && host.Workbench.MainActionKind == expectedKind && status.Text == expected, "step terminal " + result);
                Record(new { Case = "step-summary-" + result, ComponentSummaryBoundary = true, StartCount = 1, TerminalCount = 1, Expected = expected, Actual = status.Text, ExpectedKind = expectedKind, ActualKind = host.Workbench.MainActionKind, PASS = true });
            }
            host.SelectToolForTest(VISION_MENU.Mean); Pump(3); var doc = host.ActiveNativeDocumentForTest!; tool.SetRoute(Token(), "Main", null, "GuardTrialOut"); Require(tool.HasAcceptance, "Mean existing acceptance owner");
            tool.UseAcceptance = true; tool.UseAcceptanceMinimum = true; tool.AcceptanceMinimumText = "bad-owned-input"; int rejected = actions; doc.RunPreview(); Require(tool.HasAcceptanceError && !tool.RunCommand.CanExecute(null) && actions == rejected && !doc.IsPreviewRunning, "invalid acceptance prevents execution notification");
            tool.CancelAcceptanceEditCommand.Execute(nameof(tool.AcceptanceMinimumText)); tool.UseAcceptance = false; Require(!tool.HasAcceptanceError && tool.RunCommand.CanExecute(null), "acceptance recovery"); Record(new { Case = "invalid-acceptance", ExecutionActions = 0, ValidRecovery = true, PASS = true });
            host.SelectToolForTest(VISION_MENU.Matching); Pump(3); var matching = host.ActiveNativeDocumentForTest!; var binding = ReadPrivateField<OpenVisionWorkbenchToolViewModel.EditorBinding>(tool, "editor")!;
            Require(binding.AutoPreviewOptedIn != null && !binding.AutoPreviewOptedIn() && !tool.HasAutoRunOption && !tool.IsAutoRunEnabled && !matching.IsPreviewRunning, "Matching existing opt-in gate/OFF"); Record(new { Case = "Matching-opt-in-preserved", AutoOptedIn = false, AutoRunPreference = false, NoExecution = true, PASS = true });
            host.SelectToolForTest(VISION_MENU.Threshold); Pump(3); doc = host.ActiveNativeDocumentForTest!; tool.SetRoute(Token(), "Main", null, "DisposedStatusOut");
            using ManualResetEventSlim gate = new(false), returned = new(false), entered = new(false); OpenCvSharp.Mat? ownedOutput = null; var boundary = ReadPrivateField<OpenVisionNativePreviewExecutionBoundary>(doc, "previewExecutionBoundary")!;
            doc.SetPreviewExecutionOverrideForTest(mat => { try { entered.Set(); if (!gate.Wait(10000)) throw new TimeoutException("Owned disposal gate"); ownedOutput = mat.Clone(); return VisionToolResult.Passed(ownedOutput, TimeSpan.Zero); } finally { returned.Set(); } });
            int beforeDispose = actions; tool.RunCommand.Execute(null); Require(actions == beforeDispose + 1 && entered.Wait(3000), "dispose case actual start/worker entered"); long oldSession = Token(); doc.Dispose(); gate.Set(); Require(returned.Wait(3000), "owned worker returned");
            Stopwatch clock = Stopwatch.StartNew(); while ((ownedOutput == null || !ownedOutput.IsDisposed) && clock.ElapsedMilliseconds < 10000) { Pump(2); Thread.Sleep(2); }
            Require(actions == beforeDispose + 1 && !boundary.IsRunning && ownedOutput?.IsDisposed == true && ReadPrivateField<CancellationTokenSource>(boundary, "activeCancellationSource") == null, "disposed obsolete terminal ignored/owned Mat and CTS released");
            tool.NotifyExecutionStarted(oldSession, step); tool.PublishResult(oldSession, new VisionPipelineStepResultSummary { Success = true, Executed = true }, step); Require(actions == beforeDispose + 1, "disposed document session ignored");
            Record(new { Case = "document-dispose-worker", StartCount = 1, TerminalCount = 0, ReturnedWorker = true, OwnedMatDisposed = true, CTSReleased = true, PASS = true });
            string last = host.Workbench.MainActionText; host.Workbench.Dispose(); Require(host.Workbench.MainActionText == last, "Root dispose does not invent terminal");
            Record(new { Case = "root-dispose", NoSyntheticTerminal = true, ProductDLLSHA256 = Convert.ToHexString(SHA256.HashData(File.ReadAllBytes(typeof(OpenVisionShellHostView).Assembly.Location))), PASS = true });
        });
    }
