                icon.Visibility = Visibility.Hidden; Elapse(100); before = Angle(); Elapse(180); after = Angle(); Check(!icon.Spin && before == after, "hidden Running stopped"); Record(new { Case = "hidden-running", Spin = icon.Spin, Before = before, After = after, PASS = !icon.Spin && before == after });
                icon.Visibility = Visibility.Visible; Elapse(100); before = Angle(); Elapse(180); after = Angle(); bool visibleResume = icon.Spin && before != after && icon.TranslatePoint(new System.Windows.Point(), host) == origin && new Size(icon.ActualWidth, icon.ActualHeight) == size; Check(visibleResume, "visible Running resumed with unchanged bounds"); Record(new { Case = "visible-running-resumed", Spin = icon.Spin, Before = before, After = after, Origin = origin.ToString(), Size = size.ToString(), PASS = visibleResume });
                Panel parent = (Panel)VisualTreeHelper.GetParent(icon); int iconIndex = parent.Children.IndexOf(icon); parent.Children.Remove(icon); Elapse(100); before = Angle(); Elapse(180); after = Angle();
                bool unloadedStop = before == after; Check(unloadedStop, "unloaded clock stopped"); Record(new { Case = "unloaded-running", Loaded = icon.IsLoaded, Spin = icon.Spin, Before = before, After = after, PASS = unloadedStop }); parent.Children.Insert(iconIndex, icon); Elapse(100); before = Angle(); Elapse(180); after = Angle(); bool reloadResume = icon.IsLoaded && icon.Spin && before != after; Check(reloadResume, "reloaded Running resumed"); Record(new { Case = "reloaded-running", Loaded = icon.IsLoaded, Spin = icon.Spin, Before = before, After = after, PASS = reloadResume });
