                before = Angle(); Elapse(240); after = Angle(); Check(!icon.Spin && before == after, "terminal motion stopped"); Record(new { Case = "terminal", Kind = host.Workbench.MainActionKind, Spin = icon.Spin, Before = before, After = after, Runs = doc.PreviewRunCount, PASS = !icon.Spin && before == after });
                if (!motionOnly) foreach (OpenVisionLanguage locale in new[] { OpenVisionLanguage.Korean, OpenVisionLanguage.English })
