        VisionPipelineStorage.Save(global.Recipe.Name, new VisionPipeline { Name = "Main" }); VisionPipelineStorage.SaveActivePipelineName(global.Recipe.Name, "Main"); global.System.SaveWorkbenchLayout(new SystemStateConfig());
        OpenVisionShellHostWindow window = new(new ApplicationRuntimeContext(global, new DisplayManagerService())) { WindowStartupLocation = WindowStartupLocation.Manual, Left = -10000, Top = -10000, ShowActivated = false, ShowInTaskbar = false };
        window.ClearValue(OpenVisionShellHostWindow.ClosingCommandProperty); OpenVisionShellHostView host = window.ShellHostForSmoke;
        return CaptureStandaloneWindow(window, outputPath, width, height, () =>
        {
            var tool = host.Workbench.Tool; var pipeline = host.Workbench.Pipeline; List<object> cases = new(); List<string> failures = new(); List<OpenVisionNativeToolDocument> documents = new(); int sequence = 0;
            void Require(bool value, string label) { if (!value) throw new InvalidOperationException("ThresholdSelection: " + label); }
            void Record(object value) { cases.Add(value); File.WriteAllText(Path.ChangeExtension(outputPath, ".checks.json"), JsonSerializer.Serialize(cases, new JsonSerializerOptions { WriteIndented = true })); }
            OpenVisionWorkbenchToolViewModel.EditorBinding Editor() => ReadPrivateField<OpenVisionWorkbenchToolViewModel.EditorBinding>(tool, "editor")!;
            ThresholdToolWpfView View() => (ThresholdToolWpfView)host.ActiveNativeDocumentForTest!.View;
            RadioButton Radio(string name) => FindNamedVisualChild<RadioButton>(View(), name)!;
            long Token() => (long)typeof(OpenVisionWorkbenchToolViewModel).GetField("generation", BindingFlags.Instance | BindingFlags.NonPublic)!.GetValue(tool)!;
            void Click(string name)
            {
                RadioButton radio = Radio(name); Require(radio != null && radio.IsEnabled && radio.IsVisible, "framework click target " + name);
                typeof(RadioButton).GetMethod("OnClick", BindingFlags.Instance | BindingFlags.NonPublic)!.Invoke(radio, null); Pump(3);
            }
            string[] all = { "rbBasic", "rbRange", "rbAdaptive", "rbBasicBinary", "rbBasicInvert", "rbAdaptiveMean", "rbAdaptiveGaussian", "rbAdaptiveBinary", "rbAdaptiveInvert" };
            void Observe(string state, ThresholdToolMode mode, bool basicInvert, bool gaussian, bool adaptiveInvert)
            {
                Pump(4); ThresholdToolWpfView view = View(); var settings = (ThresholdToolSettings)Editor().CaptureParameters();
                string[] expected = { mode == ThresholdToolMode.Range ? "rbRange" : mode == ThresholdToolMode.Adaptive ? "rbAdaptive" : "rbBasic", basicInvert ? "rbBasicInvert" : "rbBasicBinary", gaussian ? "rbAdaptiveGaussian" : "rbAdaptiveMean", adaptiveInvert ? "rbAdaptiveInvert" : "rbAdaptiveBinary" };
                string[] actual = all.Where(name => Radio(name).IsChecked == true).ToArray();
                var indicators = all.Select(name => new { Name = name, Checked = Radio(name).IsChecked, Indicator = ((Border)Radio(name).Template.FindName("selectionIndicator", Radio(name)))?.Visibility.ToString(), Visible = Radio(name).IsVisible, Binding = BindingOperations.IsDataBound(Radio(name), ToggleButton.IsCheckedProperty) }).ToArray();
                bool binding = new[] { "rbBasicInvert", "rbAdaptiveGaussian", "rbAdaptiveInvert" }.All(name => BindingOperations.IsDataBound(Radio(name), ToggleButton.IsCheckedProperty));
                bool panels = FindNamedVisualChild<FrameworkElement>(view, "panelBasic")!.Visibility == (mode == ThresholdToolMode.Threshold ? Visibility.Visible : Visibility.Collapsed)
                    && FindNamedVisualChild<FrameworkElement>(view, "panelRange")!.Visibility == (mode == ThresholdToolMode.Range ? Visibility.Visible : Visibility.Collapsed)
                    && FindNamedVisualChild<FrameworkElement>(view, "panelAdaptive")!.Visibility == (mode == ThresholdToolMode.Adaptive ? Visibility.Visible : Visibility.Collapsed);
                bool values = settings.Mode == mode && settings.BasicInvert == basicInvert && settings.AdaptiveGaussian == gaussian && settings.AdaptiveInvert == adaptiveInvert;
                bool selected = expected.OrderBy(name => name).SequenceEqual(actual.OrderBy(name => name));
                bool template = indicators.All(row => !row.Visible || row.Indicator == (row.Checked == true ? "Visible" : "Collapsed"));
                bool pass = selected && panels && values && binding && template;
                string capture = Path.ChangeExtension(outputPath, "." + (++sequence) + "." + state + ".png"); if (!dataOnly) ScreenshotPngWriter.WriteDpiAwareWindowPng(window, capture);
                Record(new { State = state, Theme = host.Workbench.ThemeName, Locale = OpenVisionLanguageService.CurrentLanguage.ToString(), Width = width, Height = height, Expected = expected, Actual = actual, Indicators = indicators, Panels = panels, Binding = binding, Values = values, Mode = settings.Mode.ToString(), settings.BasicInvert, settings.AdaptiveGaussian, settings.AdaptiveInvert, settings.Threshold, Capture = dataOnly ? null : capture, PASS = pass });
                if (!pass) failures.Add(state);
            }
            string input = Path.ChangeExtension(outputPath, ".input.png"); using (Bitmap image = CreateWorkspaceSeedSmokeBitmap()) image.Save(input, ImageFormat.Png);
            Require(host.LoadMainImageFromFileForTest(input), "owned input"); Pump(5); byte[] bytes = File.ReadAllBytes(input);
            tool.ConfigureAutoRunPreference(() => false, _ => { }); host.SelectToolForTest(VISION_MENU.Threshold); Pump(5);
            var document = host.ActiveNativeDocumentForTest!; documents.Add(document); int layers = host.LayerDocumentCount; byte[] empty = VisionPipelineExecutionPlan.SerializePipeline(pipeline.WorkingCopyForTest), emptySaved = VisionPipelineExecutionPlan.SerializePipeline(VisionPipelineStorage.Load(global.Recipe.Name, "Main"));
            if (autoOnly)
            {
                bool auto = true; tool.ConfigureAutoRunPreference(() => auto, value => auto = value); Pump(3);
                var scheduler = ReadPrivateField<VisionToolDebouncedPreviewScheduler>(View(), "previewScheduler")!;
                var timer = ReadPrivateField<System.Windows.Threading.DispatcherTimer>(scheduler, "timer")!;
                Require(tool.IsAutoRunEnabled && VisionToolDebouncedPreviewScheduler.GetAllowAutoPreview(View()) && BindingOperations.IsDataBound(View(), VisionToolDebouncedPreviewScheduler.AllowAutoPreviewProperty), "existing AUTO preference binding enabled");
                // Execute the normal framework click without a dispatcher turn so Defaults can cancel the genuinely pending debounce.
                typeof(RadioButton).GetMethod("OnClick", BindingFlags.Instance | BindingFlags.NonPublic)!.Invoke(Radio("rbBasicInvert"), null);
                Require(timer.IsEnabled && ((ThresholdToolSettings)Editor().CaptureParameters()).BasicInvert, "actual Checked path armed pending debounce");
                tool.RestoreDefaultsCommand.Execute(null); Require(!timer.IsEnabled, "restore cancels pending debounce"); Pump(25);
                Require(document.PreviewRunCount == 0 && !document.IsPreviewRunning, "restoration under AUTO does not run"); Observe("auto-pending-defaults", ThresholdToolMode.Threshold, false, false, false);
                Click("rbBasicInvert"); Record(new { State = "auto-approved-pending", TimerEnabled = timer.IsEnabled, Runs = document.PreviewRunCount, Input = tool.InputLayer, Status = document.LastStatusText });
                Stopwatch autoClock = Stopwatch.StartNew(); while ((timer.IsEnabled || document.IsPreviewRunning || document.PreviewRunCount == 0) && autoClock.ElapsedMilliseconds < 10000) { Pump(2); Thread.Sleep(5); } Pump(4);
                Record(new { State = "auto-approved-observed", Elapsed = autoClock.ElapsedMilliseconds, TimerEnabled = timer.IsEnabled, Runs = document.PreviewRunCount, Running = document.IsPreviewRunning, Input = tool.InputLayer, Status = document.LastStatusText });
                Require(document.PreviewRunCount == 1 && !document.IsPreviewRunning, "approved AUTO editor change runs exactly once");
