                foreach ((double requested, string expected) in new[] { (Math.BitDecrement(1.035D), "103%"), (1.035D, "103%"), (Math.BitIncrement(1.035D), "104%"), (1.045D, "105%"), (1.5625D, "156%"), (1D, "100%") })
                {
                    OpenVisionZoomableImageController controller = ReadPrivateField<OpenVisionZoomableImageController>(original, "fallbackImageZoomController")!;
                    Require(controller.ApplyViewport(new OpenVisionImageViewport(requested, 160D, 120D, false)), "existing viewport seam"); Pump(4);
                    double actual = original.ZoomScale;
                    bool representable = requested < 1.035D ? actual * 100D < 103.5D : requested == 1.035D ? actual * 100D < 103.5D : requested == Math.BitIncrement(1.035D) ? actual * 100D > 103.5D : true;
                    bool pass = representable && upper.Text == expected && Footer(original).Text == expected && host.WorkspaceCommands.ZoomText == expected;
                    Record(new { State = "fractional", WorkspaceGetter = host.WorkspaceCommands.ZoomText, Theme = theme, Requested = requested.ToString("R", CultureInfo.InvariantCulture), Raw = actual.ToString("R", CultureInfo.InvariantCulture), Percent = (actual * 100D).ToString("R", CultureInfo.InvariantCulture), Expected = expected, Upper = upper.Text, Footer = Footer(original).Text, SameViewer = original.MainPane.IsActive, Pane = original.MainPane.Id, ActivePane = host.Workbench.Viewer.ActivePaneId, Representable = representable, ExistingControllerViewportSeam = true, NativeWheel = false, PASS = pass });
                    if (!pass) failures.Add(theme + ":" + requested.ToString("R", CultureInfo.InvariantCulture));
                }
            }
            host.SelectToolForTest(VISION_MENU.Threshold); Pump(5); OpenVisionNativeToolDocument document = host.ActiveNativeDocumentForTest!;
            Require(document.PreviewRunCount == 0 && host.Workbench.Tool.RunCommand.CanExecute(null), "unrun Threshold"); host.Workbench.Tool.RunCommand.Execute(null);
            Stopwatch wait = Stopwatch.StartNew(); while (document.IsPreviewRunning && wait.Elapsed < TimeSpan.FromSeconds(8)) { Pump(2); Thread.Sleep(5); } Pump(6);
            OpenVisionLayerViewerView output = Pane(1); Require(output.HasImage && document.PreviewRunCount == 1, "explicit output bitmap");
            int layersAfterRun = host.LayerDocumentCount; Record(new { State = "explicit-Run-boundary", LayersBeforeRun = layers, LayersAfterRun = layersAfterRun, DocumentRuns = document.PreviewRunCount });
            output.ShowOriginalSize(); Pump(4); Observe("output-100", output, "100%");
            Require(ReadPrivateField<ShellDockedLayerWorkspaceComposition>(host, "dockedLayerWorkspaceComposition")!.Commands.ActivateLayerDocument(output.MainPane.Id), "activate output dock document"); host.Workbench.Viewer.Activate(output.MainPane.Id); host.WorkspaceCommands.RefreshCanExecute(); Pump(3);
            host.CloseActiveWpfToolWindowForTest(); Pump(5); Require(!output.HasImage && !output.MainPane.HasImage, "tool close removes output"); Observe("closed-empty", output, "");
            host.SelectToolForTest(VISION_MENU.Threshold); Pump(5); Require(output.HasImage && ReferenceEquals(document, host.ActiveNativeDocumentForTest), "retained output restored without Run");
            output.ShowOriginalSize(); Pump(4); Observe("restored-100", output, "100%"); output.PanImageByForTest(11D, -7D); Pump(3); Observe("pan-100", output, "100%");
            Require(host.WorkspaceCommands.FitImageCommand.CanExecute(null), "active output Fit enabled"); host.WorkspaceCommands.FitImageCommand.Execute(null); Pump(4); Require(Footer(output).Text == output.ZoomText && output.ViewportForTest?.Fit == true, "bound Fit recovery"); Record(new { State = "fit", output.HasImage, Bound = Footer(output).Text, Getter = output.ZoomText, PASS = Footer(output).Text == output.ZoomText });
            host.CloseActiveWpfToolWindowForTest(); Pump(4); Observe("closed-empty-repeat", output, ""); Require(ReadPrivateField<ShellDockedLayerWorkspaceComposition>(host, "dockedLayerWorkspaceComposition")!.Commands.ActivateLayerDocument(original.MainPane.Id), "activate Original dock document"); host.Workbench.Viewer.Activate(original.MainPane.Id); host.WorkspaceCommands.RefreshCanExecute(); Pump(3);
            original.ShowOriginalSize(); Pump(3); Observe("original-active-100", original, "100%");
            Require(document.PreviewRunCount == 1 && host.LayerDocumentCount == layersAfterRun && bytes.SequenceEqual(File.ReadAllBytes(input)) && working.SequenceEqual(VisionPipelineExecutionPlan.SerializePipeline(host.Workbench.Pipeline.WorkingCopyForTest)) && saved.SequenceEqual(VisionPipelineExecutionPlan.SerializePipeline(VisionPipelineStorage.Load(global.Recipe.Name, "Main"))), "display has no execution/layer/working/saved/source mutation");
            Record(new { State = "invariants", DocumentRuns = document.PreviewRunCount, LayerCountBeforeExplicitRun = layers, LayerCountAfterExplicitRun = layersAfterRun, NoImplicitRun = true, WorkingSavedSourceUnchanged = true, Failures = failures.ToArray() });
            if (failures.Count > 0) throw new InvalidOperationException("ZoomReadout failures: " + string.Join(", ", failures));
        });
    }

    private static CaptureResult CaptureWorkbenchTrialRunCounts(string outputPath)
    {
        GlobalState global = new(); global.Recipe.Name = "Smoke_TrialCounts119_" + Guid.NewGuid().ToString("N")[..12];
        VisionPipelineStorage.Save(global.Recipe.Name, new VisionPipeline { Name = "Main" }); VisionPipelineStorage.SaveActivePipelineName(global.Recipe.Name, "Main"); global.System.SaveWorkbenchLayout(new SystemStateConfig());
        OpenVisionShellHostWindow window = new(new ApplicationRuntimeContext(global, new DisplayManagerService())) { WindowStartupLocation = WindowStartupLocation.Manual, Left = -10000, Top = -10000, ShowActivated = false, ShowInTaskbar = false };
        OpenVisionShellHostView host = window.ShellHostForSmoke;
        return CaptureStandaloneWindow(window, outputPath, 1600, 900, () =>
        {
            void Require(bool value, string name) { if (!value) throw new InvalidOperationException("TrialCounts119: " + name); }
            string input = Path.ChangeExtension(outputPath, ".input.png"); using (Bitmap image = CreateWorkspaceSeedSmokeBitmap()) image.Save(input, ImageFormat.Png);
            Require(host.LoadMainImageFromFileForTest(input), "owned input"); Pump(5);
            byte[] working = VisionPipelineExecutionPlan.SerializePipeline(host.Workbench.Pipeline.WorkingCopyForTest), saved = VisionPipelineExecutionPlan.SerializePipeline(VisionPipelineStorage.Load(global.Recipe.Name, "Main")), bytes = File.ReadAllBytes(input);
            host.SelectToolForTest(VISION_MENU.Threshold); Pump(5); OpenVisionNativeToolDocument threshold = host.ActiveNativeDocumentForTest!;
            Require(threshold.PreviewRunCount == 0 && host.Workbench.Tool.RunCommand.CanExecute(null), "Threshold starts unrun");
            host.Workbench.Tool.RunCommand.Execute(null); Stopwatch wait = Stopwatch.StartNew();
            while (threshold.IsPreviewRunning && wait.Elapsed < TimeSpan.FromSeconds(8)) { Pump(2); Thread.Sleep(5); }
            Pump(5); Require(threshold.HasPreviewResult && threshold.PreviewRunCount == 1, "one explicit Threshold Run");
            host.CloseActiveWpfToolWindowForTest(); Pump(3); host.SelectToolForTest(VISION_MENU.Matching); Pump(4); OpenVisionNativeToolDocument matching = host.ActiveNativeDocumentForTest!;
            Require(!host.Workbench.Tool.HasTemplate && matching.PreviewRunCount == 0 && host.Workbench.Tool.RunCommand.CanExecute(null), "Matching no-template/unrun prerequisite");
            host.Workbench.Tool.RunCommand.Execute(null); Pump(5);
            Require(!matching.HasPreviewResult && matching.PreviewRunCount == 0 && matching.LastStatusText.Contains("Matching template image is not loaded.", StringComparison.Ordinal), "template rejection does not increment success execution");
            host.CloseActiveWpfToolWindowForTest(); Pump(3);
            host.Workbench.Pipeline.InsertStep(0, new VisionPipelineStep { Name = "Unmade", ToolType = "Mean", InputLayer = "Main", OutputLayer = "Out" }); Pump(4);
            Require((bool)typeof(OpenVisionWorkbenchPipelineViewModel).GetMethod("TrySave", BindingFlags.Instance | BindingFlags.NonPublic)!.Invoke(host.Workbench.Pipeline, null)!, "owned saved step setup");
            OpenVisionNativeToolDocument mean = host.ActiveNativeDocumentForTest!;
            Require(threshold.PreviewRunCount == 1 && matching.PreviewRunCount == 0 && mean.PreviewRunCount == 0, "document-specific execution counts survive activation changes");
            VisionPipelineStorage.Save(global.Recipe.Name, new VisionPipeline { Name = "Main" }); typeof(OpenVisionWorkbenchPipelineViewModel).GetMethod("Reload", BindingFlags.Instance | BindingFlags.NonPublic)!.Invoke(host.Workbench.Pipeline, null); Pump(3);
            Require(working.SequenceEqual(VisionPipelineExecutionPlan.SerializePipeline(host.Workbench.Pipeline.WorkingCopyForTest)) && saved.SequenceEqual(VisionPipelineExecutionPlan.SerializePipeline(VisionPipelineStorage.Load(global.Recipe.Name, "Main"))) && bytes.SequenceEqual(File.ReadAllBytes(input)), "owned setup restored/bytes unchanged");
            File.WriteAllText(Path.ChangeExtension(outputPath, ".checks.json"), JsonSerializer.Serialize(new { ThresholdDocumentRuns = threshold.PreviewRunCount, MatchingDocumentRuns = matching.PreviewRunCount, SavedMeanDocumentRuns = mean.PreviewRunCount, ActiveDocumentRuns = host.NativePreviewRunCount, MatchingStatus = matching.LastStatusText, CounterContract = "ActiveNativeDocument counter is not an aggregate", NoImplicitRun = true, WorkingSavedSourceRestored = true, PASS = true }, new JsonSerializerOptions { WriteIndented = true }));
        });
    }

    private static CaptureResult CaptureWorkbenchTrialEmpty(string outputPath, int width, int height, bool boundariesOnly = false, bool savedStepOnly = false)
