                        Require(title.Text == (ko ? "실행 전" : "Not run") && inlineText == (ko ? "툴 실행(F8)을 누르세요." : "Press Run tool (F8).") && (!detail.IsVisible || new TextRange(detail.ContentStart, detail.ContentEnd).Text == inlineText), state + " independent canonical wording");
                        Require(FindNamedVisualChild<MahApps.Metro.IconPacks.PackIconMaterial>(view, "mainPaneEmptyIcon")!.Kind.ToString() == "ImageOffOutline" && !pane.ShowOpenActions && FindVisualChildren<Button>(card).All(button => !button.IsVisible), state + " icon/no extra command");
                        Run[] runs = detail.Inlines.OfType<Run>().ToArray();
                        Require(runs.Length == 3 && runs[1].FontWeight == FontWeights.Bold && runs[1].Text == (ko ? "툴 실행(F8)" : "Run tool (F8)") && runs[0].FontWeight == FontWeights.Normal && runs[2].FontWeight == FontWeights.Normal, state + " only action bold");
