                    Require(host.NativePreviewRunCount == runs && host.LayerDocumentCount == layers && working.SequenceEqual(VisionPipelineExecutionPlan.SerializePipeline(host.Workbench.Pipeline.WorkingCopyForTest)) && saved.SequenceEqual(VisionPipelineExecutionPlan.SerializePipeline(VisionPipelineStorage.Load(global.Recipe.Name, "Main"))) && sourceBytes.SequenceEqual(File.ReadAllBytes(imagePath)), "activation/display leaves execution/layers/working/saved/source unchanged " + tool);
