                long generation = (long)typeof(OpenVisionWorkbenchToolViewModel).GetField("generation", BindingFlags.Instance | BindingFlags.NonPublic)!.GetValue(toolModel)!;
                const string longName = "Trial_Output_긴이름_Threshold_ABCDEFGHIJKLMNOPQRSTUVWXYZ";
                Require((bool)typeof(OpenVisionWorkbenchToolViewModel).GetMethod("SetRoute", BindingFlags.Instance | BindingFlags.NonPublic)!.Invoke(toolModel, new object[] { generation, "Main", null!, longName })!, "owned output rename");
                Observe("rename", true, false);
                OpenVisionWorkbenchViewerPane output = Output().MainPane; output.Source = "layer:" + longName; Observe("fixed-test-output", true, false);
                output.Source = "layer:Main"; Pump(4); Require(output.HasImage && !output.IsTrialEmpty && !output.Title.Contains(" · Test", StringComparison.Ordinal), "fixed Main excluded");
                output.Source = "final"; Pump(4); Require(!output.IsTrialEmpty && output.Title == OpenVisionLanguageService.T("Workbench.Pane.FinalName"), "final excluded");
                output.Source = "follow:out";
                host.Workbench.Viewer.Split4Command.Execute(null); Pump(5); Observe("four-split", true, false);
                OpenVisionLayerViewerView shortView = Output(); Grid shortRoot = FindNamedVisualChild<Grid>(shortView, "viewerRootGrid")!;
                shortView.Height = 220 + shortView.ActualHeight - shortRoot.ActualHeight; Pump(4); Require(shortView.MainPane.IsShort, "actual short size"); Observe("short-220", true, false);
                shortView.ClearValue(FrameworkElement.HeightProperty); host.Workbench.Viewer.Split2Command.Execute(null); Pump(5);
                Require(host.NativePreviewRunCount == runs && host.LayerDocumentCount == layers && working.SequenceEqual(VisionPipelineExecutionPlan.SerializePipeline(host.Workbench.Pipeline.WorkingCopyForTest)) && saved.SequenceEqual(VisionPipelineExecutionPlan.SerializePipeline(VisionPipelineStorage.Load(global.Recipe.Name, "Main"))) && sourceBytes.SequenceEqual(File.ReadAllBytes(imagePath)), "rename/source/layout display has no implicit execution or persistence");
                Require(toolModel.RunCommand.CanExecute(null), "explicit Threshold Run enabled"); toolModel.RunCommand.Execute(null);
                OpenVisionNativeToolDocument document = host.ActiveNativeDocumentForTest!; Stopwatch wait = Stopwatch.StartNew();
                while (document.IsPreviewRunning && wait.Elapsed < TimeSpan.FromSeconds(8)) { Pump(2); Thread.Sleep(5); }
                Pump(8); OpenVisionNativeToolDocument thresholdDocument = document; Require(document.HasPreviewResult && !document.IsPreviewRunning && host.NativePreviewRunCount == runs + 1, "explicit Threshold creates real output"); Observe("explicit-threshold-output", true, true);
                output = Output().MainPane;
                PropertyInfo saveProperty = typeof(OpenVisionWorkbenchViewerViewModel).GetProperty("SaveImage", BindingFlags.Instance | BindingFlags.NonPublic)!;
                object? previousSave = saveProperty.GetValue(host.Workbench.Viewer); string? saveDefaultName = null;
                try
                {
                    saveProperty.SetValue(host.Workbench.Viewer, new Action<string, Bitmap>((name, image) => saveDefaultName = name));
                    Require(output.SaveCommand.CanExecute(null), "save-image existing command enabled"); output.SaveCommand.Execute(null);
                    Require(saveDefaultName == longName, "save-image raw default name has no test suffix");
                }
                finally { saveProperty.SetValue(host.Workbench.Viewer, previousSave); }
                output.SnapshotCommand.Execute(null); Pump(4); string snapshotTitle = output.Title;
                Require(snapshotTitle.StartsWith(longName + " · ", StringComparison.Ordinal) && !snapshotTitle.Contains(" · Test", StringComparison.Ordinal) && !snapshotTitle.Contains(" · 테스트", StringComparison.Ordinal), "snapshot preserves raw name without header test suffix");
                Record(new { State = "snapshot-save-name", RawOutput = longName, SnapshotTitle = snapshotTitle, SaveImageDefaultName = saveDefaultName, PASS = true });
                Require(output.Source.StartsWith("snap:", StringComparison.Ordinal) && output.HasImage && !output.IsTrialEmpty, "snapshot frozen image excluded");
                host.CloseActiveWpfToolWindowForTest(); Pump(4); Require(output.Title == snapshotTitle && output.HasImage && !output.IsTrialEmpty, "snapshot preserved on close");
                host.Workbench.Viewer.ClearSnapshotsCommand.Execute(null); Pump(4);
                host.SelectToolForTest(VISION_MENU.Matching); Pump(5); document = host.ActiveNativeDocumentForTest!;
                Require(!toolModel.HasTemplate && toolModel.RunCommand.CanExecute(null), "unregistered Matching template precondition");
                OpenVisionNativeToolDocument matchingDocument = document; int beforeRejected = document.PreviewRunCount; toolModel.RunCommand.Execute(null); Pump(8);
                Require(!document.HasPreviewResult && host.NativePreviewRunCount == beforeRejected, "Matching missing template rejected without output");
                string failedToolStatus = toolModel.StatusText, failedMainStatus = host.Workbench.MainActionText, failedMainKind = host.Workbench.MainActionKind;
                Observe("matching-rejected", true, false);
                Require(toolModel.StatusText == failedToolStatus && host.Workbench.MainActionText == failedMainStatus && host.Workbench.MainActionKind == failedMainKind, "pane display preserves failure owner/status");
                Record(new { State = "matching-rejection-status", ToolStatus = failedToolStatus, DocumentStatus = document.LastStatusText, MainStatus = failedMainStatus, MainKind = failedMainKind, StatusUnchangedByPane = true, PASS = true });
                host.Workbench.Images.SelectAllCommand.Execute(null); Pump(3);
                Require(host.Workbench.Images.SelectedCount == 1 && host.Workbench.Images.RemoveCommand.CanExecute(null), "owned image selected for removal");
                host.Workbench.Images.RemoveCommand.Execute(null); Pump(6); output = Output().MainPane;
                Require(!output.IsTrialEmpty && output.EmptyTitle == OpenVisionLanguageService.T("Workbench.Viewer.NoImage") && output.ShowOpenActions, "input removal wins over trial");
                Require(host.LoadMainImageFromFileForTest(imagePath), "valid input recovery"); Pump(5); Observe("input-recovery", true, false);
                host.CloseActiveWpfToolWindowForTest(); Pump(3);
                Require(saved.SequenceEqual(VisionPipelineExecutionPlan.SerializePipeline(VisionPipelineStorage.Load(global.Recipe.Name, "Main"))), "display and explicit run preserve saved pipeline");
                VerifySavedStep();
                Require(thresholdDocument.PreviewRunCount == 1 && matchingDocument.PreviewRunCount == 0, "document-specific count boundary");
                Record(new { State = "boundary-summary", ExplicitThresholdRuns = thresholdDocument.PreviewRunCount, MatchingRuns = matchingDocument.PreviewRunCount, ActiveDocumentRuns = host.NativePreviewRunCount, NoImplicitRun = thresholdDocument.PreviewRunCount == 1 && matchingDocument.PreviewRunCount == 0, SavedUnchanged = saved.SequenceEqual(VisionPipelineExecutionPlan.SerializePipeline(VisionPipelineStorage.Load(global.Recipe.Name, "Main"))), SourceBytesUnchanged = sourceBytes.SequenceEqual(File.ReadAllBytes(imagePath)), PASS = true });
            }
            finally
            {
                if (host.Workbench.Pipeline.IsDirty) typeof(OpenVisionWorkbenchPipelineViewModel).GetMethod("Reload", BindingFlags.Instance | BindingFlags.NonPublic)!.Invoke(host.Workbench.Pipeline, null);
                OpenVisionLanguageService.SetLanguage(initial, false);
            }
        });
    }

    private static CaptureResult CaptureWorkbenchEmptyCanonical(string outputPath, int width, int height, bool statesOnly = false)
    {
        GlobalState global = new(); global.Recipe.Name = "Smoke_Empty119_" + Guid.NewGuid().ToString("N")[..12];
        foreach (string name in new[] { "Main", "Other" }) VisionPipelineStorage.Save(global.Recipe.Name, new VisionPipeline { Name = name });
        VisionPipelineStorage.SaveActivePipelineName(global.Recipe.Name, "Main"); global.System.SaveWorkbenchLayout(new SystemStateConfig());
        OpenVisionShellHostWindow window = new(new ApplicationRuntimeContext(global, new DisplayManagerService())) { WindowStartupLocation = WindowStartupLocation.Manual, Left = -10000, Top = -10000, ShowActivated = false, ShowInTaskbar = false };
        OpenVisionShellHostView host = window.ShellHostForSmoke;
        return CaptureStandaloneWindow(window, outputPath, width, height, () =>
        {
            List<object> cases = new(); OpenVisionLanguage initial = OpenVisionLanguageService.CurrentLanguage;
            host.Workbench.IsToolPaletteCollapsed = true;
            OpenVisionLayerViewerView[] panes = FindVisualChildren<OpenVisionLayerViewerView>(host).Where(view => view.MainPane != null).ToArray();
            if (panes.Length != 2) throw new InvalidOperationException("Canonical empty fixture needs two actual Main panes.");
            FrameworkElement dock = FindNamedVisualChild<FrameworkElement>(host, "dockedWorkspaceView")!;
            Grid legacyStatus = (Grid)FindNamedVisualChild<TextBlock>(host, "txtHostWorkspaceCoordinates")!.Parent;
            if (dock.Margin != new Thickness(4) || legacyStatus.Visibility != Visibility.Collapsed || ((Grid)legacyStatus.Parent).RowDefinitions[2].Height.Value != 0) throw new InvalidOperationException("120 Host margin/legacy status row.");
            int runs = host.NativePreviewRunCount, layers = host.LayerDocumentCount; byte[] working = VisionPipelineExecutionPlan.SerializePipeline(host.Workbench.Pipeline.WorkingCopyForTest);
            void Require(bool value, string name) { if (!value) throw new InvalidOperationException("Empty119: " + name); }
            void WriteCrop(FrameworkElement element, string path)
            {
                Size before = element.RenderSize; Visual parent = (Visual)VisualTreeHelper.GetParent(element); System.Windows.Point origin = element.TranslatePoint(new System.Windows.Point(), (UIElement)parent);
                Rect bounds = element.TransformToAncestor(window).TransformBounds(new Rect(before));
                RenderTargetBitmap bitmap = new((int)Math.Ceiling(window.ActualWidth), (int)Math.Ceiling(window.ActualHeight), 96, 96, PixelFormats.Pbgra32); bitmap.Render(window);
                Int32Rect crop = new((int)Math.Floor(bounds.Left), (int)Math.Floor(bounds.Top), (int)Math.Ceiling(bounds.Right) - (int)Math.Floor(bounds.Left), (int)Math.Ceiling(bounds.Bottom) - (int)Math.Floor(bounds.Top));
                PngBitmapEncoder encoder = new(); encoder.Frames.Add(BitmapFrame.Create(new CroppedBitmap(bitmap, crop))); using (FileStream file = File.Create(path)) encoder.Save(file);
                Require(element.RenderSize == before && element.TranslatePoint(new System.Windows.Point(), (UIElement)parent) == origin, "crop preserves actual layout");
            }
            void ObserveReadouts(OpenVisionLayerViewerView pane)
            {
                Grid footer = FindNamedVisualChild<Grid>(pane, "mainPaneFooter")!, surface = FindNamedVisualChild<Grid>(pane, "layerImageSurface")!, root = FindNamedVisualChild<Grid>(pane, "viewerRootGrid")!;
                TextBlock pointer = FindNamedVisualChild<TextBlock>(pane, "mainPanePointerText")!, zoom = FindNamedVisualChild<TextBlock>(pane, "mainPaneZoomText")!;
                Require(ReferenceEquals(footer.Parent, surface) && footer.IsVisible && !footer.IsHitTestVisible && root.RowDefinitions[2].Height.Value == 0 && footer.Margin == new Thickness(6, 0, 6, 6), "120 footer overlay and zero body row");
                Require(Math.Abs(footer.TranslatePoint(new System.Windows.Point(), surface).Y + footer.ActualHeight - surface.ActualHeight + 6) < 1, "120 footer bottom six");
                Require(pointer.Text == pane.PointerText && zoom.Text == pane.ZoomText && BindingOperations.IsDataBound(pointer, TextBlock.TextProperty) && BindingOperations.IsDataBound(zoom, TextBlock.TextProperty), "120 existing readout bindings");
                foreach (TextBlock text in new[] { pointer, zoom })
                {
                    Border readout = (Border)text.Parent;
                    Require(text.FontSize == 11 && text.FontFamily.Source == "Cascadia Mono, D2Coding, Consolas" && text.Foreground.ToString() == "#FFCFD6E0" && readout.Background.ToString() == "#B8080A0E" && readout.Padding == new Thickness(7, 2, 7, 2) && readout.CornerRadius == new CornerRadius(4), "120 canonical readout palette/type/padding");
                    if (text.Text.Length > 0) AssertElementWithinAncestor("120 readout caption", text, readout); AssertElementWithinAncestor("120 readout", readout, surface);
                }
                Border left = (Border)pointer.Parent, right = (Border)zoom.Parent;
                Require(left.TranslatePoint(new System.Windows.Point(left.ActualWidth, 0), footer).X + 7 <= right.TranslatePoint(new System.Windows.Point(), footer).X, "120 readouts do not overlap");
            }
            void Observe(string theme, OpenVisionLanguage language, string state, double? expectedHeight = null)
            {
                foreach (OpenVisionLayerViewerView pane in panes)
                {
                    ObserveReadouts(pane);
                    OpenVisionWorkbenchViewerPane model = pane.MainPane; bool noStep = model.Source == "follow:out";
                    Border card = FindNamedVisualChild<Border>(pane, "mainPaneEmpty")!;
                    Grid root = FindNamedVisualChild<Grid>(pane, "viewerRootGrid")!;
                    TextBlock title = FindNamedVisualChild<TextBlock>(pane, "mainPaneEmptyTitleText")!, detail = FindNamedVisualChild<TextBlock>(pane, "mainPaneEmptyDetailText")!;
                    MahApps.Metro.IconPacks.PackIconMaterial icon = FindNamedVisualChild<MahApps.Metro.IconPacks.PackIconMaterial>(pane, "mainPaneEmptyIcon")!;
                    bool shortPane = root.ActualHeight <= 220, medium = root.ActualHeight <= 300;
                    Require(!expectedHeight.HasValue || Math.Abs(root.ActualHeight - expectedHeight.Value) < .6, "actual pane height " + state);
                    Require(model.IsShort == shortPane && model.IsMediumHeight == medium && model.IsEmptyActionsStacked == (shortPane && root.ActualWidth <= 260), "actual SizeChanged boundary " + state);
                    string expectedTitle = language == OpenVisionLanguage.Korean ? noStep ? "선택한 단계 없음" : "이미지 없음" : noStep ? "No step selected" : "No image";
                    string expectedDetail = language == OpenVisionLanguage.Korean ? noStep ? "파이프라인에서 단계를 선택하세요." : "이미지나 폴더를 열거나 여기로 끌어다 놓으세요." : noStep ? "Select a step in the pipeline." : "Open an image or folder, or drag and drop it here.";
                    Require(title.Text == expectedTitle && detail.Text == expectedDetail && icon.Kind.ToString() == (noStep ? "CursorDefaultOutline" : "ImagePlusOutline"), "independent canonical text/icon " + state);
                    Require(card.Background.ToString() == "#EB161920" && card.BorderBrush.ToString() == "#FF2C323C" && title.Foreground.ToString() == "#FFE8EBF1" && detail.Foreground.ToString() == "#FFAEB6C3" && icon.Foreground.ToString() == "#FFAEB6C3", "canonical card colors after production theme switch");
                    Require(card.CornerRadius == new CornerRadius(10) && card.MaxWidth == 380 && title.FontWeight == FontWeights.Bold && title.FontSize == (shortPane ? 12.5 : medium ? 13.5 : 15) && title.LineHeight == (shortPane ? 18.125 : medium ? 19.575 : 21.75) && card.Margin == (shortPane ? new Thickness(8, 6, 8, 30) : new Thickness(10, 10, 10, 34)) && card.Padding == (shortPane ? new Thickness(10, 6, 10, 6) : medium ? new Thickness(14, 10, 14, 10) : new Thickness(20, 16, 20, 16)), "canonical declared geometry " + state);
                    FrameworkElement surface = (FrameworkElement)card.Parent;
                    double centerOffset = card.TranslatePoint(new System.Windows.Point(card.ActualWidth / 2, card.ActualHeight / 2), surface).Y - surface.ActualHeight / 2;
                    Require(Math.Abs(centerOffset + 12) < 1, "canonical overlay center excludes footer padding");
                    Require(icon.Visibility == (shortPane ? Visibility.Collapsed : Visibility.Visible) && detail.Visibility == (shortPane ? Visibility.Collapsed : Visibility.Visible) && (shortPane || icon.Width == (medium ? 20 : 28)), "canonical short priority " + state);
                    AssertElementWithinAncestor("empty title", title, card); AssertElementWithinAncestor("empty card", card, root); AssertBrushContrast(title.Foreground, card.Background, "empty title");
                    foreach (Button action in FindVisualChildren<Button>(card))
                    {
                        string id = AutomationProperties.GetAutomationId(action); bool image = id.EndsWith("OpenImage"), folder = id.EndsWith("OpenFolder");
                        ICommand expected = image ? host.WorkspaceCommands.LoadImageCommand : folder ? host.WorkspaceCommands.OpenFolderCommand : host.WorkspaceCommands.OpenSampleCommand;
                        Require(ReferenceEquals(action.Command, expected) && action.IsEnabled == expected.CanExecute(null), "existing command and CanExecute");
                        if (noStep) { Require(!action.IsVisible, "no-step has no new actions"); continue; }
                        Require(action.IsVisible == (!shortPane || image), "short keeps only primary");
                        if (!action.IsVisible) continue;
                        Require(action.ActualHeight == (shortPane ? 24 : 26), "canonical action height"); AssertElementWithinAncestor(id, action, card);
                        TextBlock label = FindVisualChildren<TextBlock>(action).Single(); AssertElementWithinAncestor(id + " caption", label, action);
                        Border chrome = FindNamedVisualChild<Border>(action, "buttonChrome")!; AssertBrushContrast(label.Foreground, chrome.Background, id + " caption");
                        if (image || folder) { Require(FindVisualChildren<MahApps.Metro.IconPacks.PackIconMaterial>(action).Single().Width == 16, "action icon16"); }
                    }
                    cases.Add(new { Theme = theme, Language = language.ToString(), State = state, Source = model.Source, PaneWidth = root.ActualWidth, PaneHeight = root.ActualHeight, model.IsShort, model.IsMediumHeight, model.IsEmptyActionsStacked, Title = title.Text, Detail = detail.Text, Icon = icon.Kind.ToString(), Background = card.Background.ToString(), card.Padding, card.Margin, CardWidth = card.ActualWidth, CardHeight = card.ActualHeight, CenterOffset = centerOffset, TitleFont = title.FontFamily.Source, TitleSize = title.FontSize, TitleLineHeight = title.LineHeight, DetailFont = detail.FontFamily.Source, DetailSize = detail.FontSize, DetailLineHeight = detail.LineHeight, WidthParity = "UNVERIFIED: no pixel tolerance or HTML glyph-font inference", PASS = true });
                }
                Require(host.NativePreviewRunCount == runs && host.LayerDocumentCount == layers && working.SequenceEqual(VisionPipelineExecutionPlan.SerializePipeline(host.Workbench.Pipeline.WorkingCopyForTest)), "display has no execution/layer/working-copy effects");
                string capture = Path.Combine(Path.GetDirectoryName(outputPath)!, Path.GetFileNameWithoutExtension(outputPath) + "." + theme + "." + language + "." + state + ".png");
                if (state == "default") ScreenshotPngWriter.WriteElementPng(window, capture, width, height);
                else if (state.StartsWith("height-", StringComparison.Ordinal))
                    foreach (OpenVisionLayerViewerView pane in panes) WriteCrop(pane, Path.ChangeExtension(capture, "." + pane.MainPane.Id.Replace(':', '-') + ".png"));
                else if (state.StartsWith("width-", StringComparison.Ordinal))
                    foreach (OpenVisionLayerViewerView pane in panes) WriteCrop(pane, Path.ChangeExtension(capture, "." + pane.MainPane.Id.Replace(':', '-') + ".png"));
            }
            try
            {
                foreach (string theme in new[] { "Dark", "Light" })
                {
                    (theme == "Dark" ? host.Workbench.SelectDarkThemeCommand : host.Workbench.SelectLightThemeCommand).Execute(null); Pump(6);
                    Require(host.Workbench.ThemeName == theme && OpenVisionWorkbenchThemeBehavior.GetThemeName(window) == theme, "production theme binding");
                    foreach (OpenVisionLanguage language in statesOnly ? new[] { OpenVisionLanguage.Korean } : new[] { OpenVisionLanguage.Korean, OpenVisionLanguage.English })
                    {
                        OpenVisionLanguageService.SetLanguage(language, false); Pump(4); Observe(theme, language, "default");
                        foreach (double size in statesOnly ? Array.Empty<double>() : new[] { 301D, 300D, 221D, 220D })
                        {
                            foreach (OpenVisionLayerViewerView pane in panes) { Grid root = FindNamedVisualChild<Grid>(pane, "viewerRootGrid")!; pane.Height = size + pane.ActualHeight - root.ActualHeight; pane.Width = size == 220 ? 190 : 320; }
                            Pump(5); Observe(theme, language, "height-" + size, size);
                        }
                        foreach (double size in statesOnly ? Array.Empty<double>() : new[] { 259D, 260D, 261D, 320D })
                        {
                            foreach (OpenVisionLayerViewerView pane in panes) { Grid root = FindNamedVisualChild<Grid>(pane, "viewerRootGrid")!; pane.Width = size + pane.ActualWidth - root.ActualWidth; }
                            Pump(4); Observe(theme, language, "width-" + size, 220);
                            OpenVisionLayerViewerView input = panes.Single(p => p.MainPane.Source == "follow:in");
                            TextBlock title = FindNamedVisualChild<TextBlock>(input, "mainPaneEmptyTitleText")!;
                            Button action = FindVisualChildren<Button>(input).Single(b => AutomationProperties.GetAutomationId(b) == "MainPaneEmptyOpenImage");
                            System.Windows.Point titleCenter = title.TranslatePoint(new System.Windows.Point(title.ActualWidth / 2, title.ActualHeight / 2), input), actionCenter = action.TranslatePoint(new System.Windows.Point(action.ActualWidth / 2, action.ActualHeight / 2), input);
                            Require(size <= 260 ? Math.Abs(titleCenter.X - actionCenter.X) < 1 : Math.Abs(titleCenter.Y - actionCenter.Y) < 1, "short centered stacked/inline rows at actual width " + size);
                        }
                        foreach (OpenVisionLayerViewerView pane in panes) { pane.ClearValue(FrameworkElement.HeightProperty); pane.ClearValue(FrameworkElement.WidthProperty); }
                        Pump(5); Observe(theme, language, "resize-recovery");
                        if (!statesOnly)
                        {
                            host.Workbench.Viewer.Split4Command.Execute(null); Pump(5);
                            OpenVisionLayerViewerView[] four = FindVisualChildren<OpenVisionLayerViewerView>(host).Where(view => view.MainPane != null && view.IsVisible).ToArray();
                            Require(four.Length == 4, "120 actual four split");
                            foreach (OpenVisionLayerViewerView pane in four)
                            {
                                typeof(OpenVisionLayerViewerView).GetMethod("ApplyPointerStatus", BindingFlags.Instance | BindingFlags.NonPublic)!.Invoke(pane, new object[] { new OpenVisionZoomableImageStatus(true, int.MaxValue, int.MaxValue, 255, 255, 255, 255) }); Pump(2);
                                ObserveReadouts(pane);
                                WriteCrop(pane, Path.Combine(Path.GetDirectoryName(outputPath)!, Path.GetFileNameWithoutExtension(outputPath) + "." + theme + "." + language + ".readout-long-" + pane.MainPane.Id.Replace(':', '-') + ".png"));
                                typeof(OpenVisionLayerViewerView).GetMethod("ApplyPointerStatus", BindingFlags.Instance | BindingFlags.NonPublic)!.Invoke(pane, new object[] { OpenVisionZoomableImageStatus.Empty });
                            }
                            host.Workbench.Viewer.Split2Command.Execute(null); Pump(5);
                            panes = FindVisualChildren<OpenVisionLayerViewerView>(host).Where(view => view.MainPane != null && view.IsVisible).ToArray();
                            cases.Add(new { Theme = theme, Language = language.ToString(), State = "120-four-split-long-coordinate", SyntheticPresentationInput = true, PASS = true });
                        }
                        Button primary = FindVisualChildren<Button>(panes.Single(p => p.MainPane.Source == "follow:in")).Single(b => AutomationProperties.GetAutomationId(b) == "MainPaneEmptyOpenImage");
                        Require(primary.Focus(), "primary focus"); Pump(2);
                        Require(FindNamedVisualChild<Border>(primary, "focusCue")!.Visibility == Visibility.Visible, "rendered focus cue");
                        if (statesOnly)
                        {
                            DependencyPropertyKey hoverKey = (DependencyPropertyKey)typeof(UIElement).GetField("IsMouseOverPropertyKey", BindingFlags.Static | BindingFlags.NonPublic)!.GetValue(null)!;
                            DependencyPropertyKey pressedKey = (DependencyPropertyKey)typeof(ButtonBase).GetField("IsPressedPropertyKey", BindingFlags.Static | BindingFlags.NonPublic)!.GetValue(null)!;
                            OpenVisionLayerViewerView input = panes.Single(p => p.MainPane.Source == "follow:in"); Border card = FindNamedVisualChild<Border>(input, "mainPaneEmpty")!;
                            foreach (Button action in FindVisualChildren<Button>(card))
                            {
                                string id = AutomationProperties.GetAutomationId(action); bool isPrimary = id.EndsWith("OpenImage");
                                foreach (string state in new[] { "normal", "synthetic-hover", "synthetic-pressed", "synthetic-mouse-leave", "focus" })
                                {
                                    action.SetValue(hoverKey, state is "synthetic-hover" or "synthetic-pressed");
                                    action.SetValue(pressedKey, state == "synthetic-pressed");
                                    if (state == "focus") Require(action.Focus(), "button focus"); Pump(2);
                                    Border chrome = FindNamedVisualChild<Border>(action, "buttonChrome")!; TextBlock caption = FindVisualChildren<TextBlock>(action).Single();
                                    string brushKey = isPrimary ? state is "synthetic-hover" or "synthetic-pressed" ? "AccentHoverBrush" : "AccentBrush" : state == "synthetic-pressed" ? "PressedBrush" : state == "synthetic-hover" ? "HoverBrush" : "PanelAltBrush";
                                    Require(chrome.Background.ToString() == action.FindResource("OpenVision.Workbench." + brushKey).ToString(), "existing runtime button state brush");
                                    AssertBrushContrast(caption.Foreground, chrome.Background, id + " " + state); AssertElementWithinAncestor("button state caption", caption, action);
                                    foreach (MahApps.Metro.IconPacks.PackIconMaterial icon in FindVisualChildren<MahApps.Metro.IconPacks.PackIconMaterial>(action)) Require(icon.Foreground.ToString() == caption.Foreground.ToString(), "state icon and caption agree");
                                    string capture = Path.Combine(Path.GetDirectoryName(outputPath)!, Path.GetFileNameWithoutExtension(outputPath) + "." + theme + "." + id + "." + state + ".png");
                                    WriteCrop(card, capture);
                                    cases.Add(new { Theme = theme, Language = language.ToString(), State = state, Action = id, Foreground = caption.Foreground.ToString(), Background = chrome.Background.ToString(), CaptionFont = caption.FontFamily.Source, CaptionSize = caption.FontSize, CaptionLineHeight = double.IsNaN(caption.LineHeight) ? "Auto" : caption.LineHeight.ToString(CultureInfo.InvariantCulture), SyntheticStateOnly = true, PASS = true });
                                }
                                action.SetValue(pressedKey, false); action.SetValue(hoverKey, false);
                            }
                        }
                    }
                }
                string imagePath = Path.ChangeExtension(outputPath, ".owned-input.png"); using (Bitmap image = CreateWorkspaceSeedSmokeBitmap()) image.Save(imagePath, ImageFormat.Png);
                Require(host.LoadMainImageFromFileForTest(imagePath), "valid image entry"); Pump(5);
                Require(FindNamedVisualChild<Border>(panes.Single(p => p.MainPane.Source == "follow:in"), "mainPaneEmpty")!.Visibility == Visibility.Collapsed && FindNamedVisualChild<Border>(panes.Single(p => p.MainPane.Source == "follow:out"), "mainPaneEmpty")!.Visibility == Visibility.Visible && host.NativePreviewRunCount == runs, "input hides no-image and retains no-step without run");
                OpenVisionLayerViewerView inputView = panes.Single(p => p.MainPane.Source == "follow:in");
                OpenVisionZoomableImageController controller = ReadPrivateField<OpenVisionZoomableImageController>(inputView, "fallbackImageZoomController");
                Grid inputSurface = FindNamedVisualChild<Grid>(inputView, "layerImageSurface")!; System.Windows.Controls.Image inputImage = FindNamedVisualChild<System.Windows.Controls.Image>(inputView, "layerFallbackImage")!;
                foreach (string state in new[] { "fit", "zoom", "outside", "leave", "recovery" })
                {
                    if (state == "zoom") inputView.ZoomImage(2);
                    if (state is "fit" or "recovery") inputView.FitImageToView(); Pump(3);
                    Rect imageBounds = inputImage.TransformToAncestor(inputSurface).TransformBounds(new Rect(inputImage.RenderSize));
                    if (state == "leave") inputSurface.RaiseEvent(new MouseEventArgs(Mouse.PrimaryDevice, 0) { RoutedEvent = Mouse.MouseLeaveEvent });
                    else Require(controller.UpdatePointerStatusForTest(state == "outside" ? new System.Windows.Point(-1000000, -1000000) : new System.Windows.Point(imageBounds.Left + imageBounds.Width / 2, imageBounds.Top + imageBounds.Height / 2)) == (state != "outside"), "120 actual image pixel probe " + state);
                    Pump(2); ObserveReadouts(inputView);
                    Require(state is "outside" or "leave" ? inputView.PointerText == "X —  Y —  GV —" : inputView.PointerText.Contains("GV", StringComparison.Ordinal) && host.Workbench.Workspace.PointerCoordinatesText != "X:- Y:-", "120 pointer/W09 recovery " + state);
                    cases.Add(new { State = "120-image-" + state, Pointer = inputView.PointerText, Zoom = inputView.ZoomText, NativeComputerUse = false, PASS = true });
                }
                foreach (string theme in new[] { "Dark", "Light" })
                {
                    (theme == "Dark" ? host.Workbench.SelectDarkThemeCommand : host.Workbench.SelectLightThemeCommand).Execute(null); Pump(3);
                    foreach (OpenVisionLanguage language in new[] { OpenVisionLanguage.Korean, OpenVisionLanguage.English })
                    {
                        OpenVisionLanguageService.SetLanguage(language, false); Pump(2);
                        foreach (int count in new[] { 2, 4 })
                        {
                            (count == 2 ? host.Workbench.Viewer.Split2Command : host.Workbench.Viewer.Split4Command).Execute(null); Pump(4);
                            OpenVisionLayerViewerView view = FindVisualChildren<OpenVisionLayerViewerView>(host).First(p => p.MainPane?.Source == "follow:in" && p.IsVisible);
                            view.ShowOriginalSize(); view.ZoomImage(40); Pump(3);
                            typeof(OpenVisionLayerViewerView).GetMethod("ApplyPointerStatus", BindingFlags.Instance | BindingFlags.NonPublic)!.Invoke(view, new object[] { new OpenVisionZoomableImageStatus(true, int.MaxValue, int.MaxValue, 255, 255, 255, 255) }); Pump(2);
                            Require(view.ZoomText == "4000%", "120 maximum supported nonempty zoom"); ObserveReadouts(view);
                            WriteCrop(FindNamedVisualChild<Grid>(view, "mainPaneFooter")!, Path.Combine(Path.GetDirectoryName(outputPath)!, Path.GetFileNameWithoutExtension(outputPath) + "." + theme + "." + language + ".readout-long-zoom-" + count + ".png"));
                            cases.Add(new { Theme = theme, Language = language.ToString(), State = "120-long-coordinate-and-zoom", Split = count, Pointer = view.PointerText, Zoom = view.ZoomText, SyntheticCoordinate = true, ExistingZoomController = true, PASS = true });
                            view.FitImageToView(); typeof(OpenVisionLayerViewerView).GetMethod("ApplyPointerStatus", BindingFlags.Instance | BindingFlags.NonPublic)!.Invoke(view, new object[] { OpenVisionZoomableImageStatus.Empty });
                        }
                    }
                }
                host.Workbench.Viewer.Split2Command.Execute(null); Pump(4); panes = FindVisualChildren<OpenVisionLayerViewerView>(host).Where(view => view.MainPane != null && view.IsVisible).ToArray();
                host.Workbench.Pipeline.InsertStep(0, new VisionPipelineStep { Name = "Unmade", ToolType = "Mean", InputLayer = "Main", OutputLayer = "Out" }); Pump(5);
                OpenVisionLayerViewerView output = panes.Single(p => p.MainPane.Source == "follow:out");
                Require(output.MainPane.EmptyIcon.ToString() == "ImageOffOutline" && output.MainPane.EmptyDetail.Contains(OpenVisionLanguageService.CurrentLanguage == OpenVisionLanguage.English ? "has not been produced" : "생성 전", StringComparison.Ordinal) && !output.MainPane.ShowOpenActions && host.NativePreviewRunCount == runs, "not-made shared card preserves text/icon/action policy");
                Border notMadeCard = FindNamedVisualChild<Border>(output, "mainPaneEmpty")!;
                Require(notMadeCard.IsVisible && FindNamedVisualChild<TextBlock>(output, "mainPaneEmptyDetailText")!.Text == output.MainPane.EmptyDetail && FindNamedVisualChild<MahApps.Metro.IconPacks.PackIconMaterial>(output, "mainPaneEmptyIcon")!.Kind.ToString() == "ImageOffOutline", "not-made actual shared card binding");
                WriteCrop(output, Path.Combine(Path.GetDirectoryName(outputPath)!, Path.GetFileNameWithoutExtension(outputPath) + "_not-made.png"));
                typeof(OpenVisionWorkbenchPipelineViewModel).GetMethod("Reload", BindingFlags.Instance | BindingFlags.NonPublic)!.Invoke(host.Workbench.Pipeline, null); Pump(4);
                Require(!host.Workbench.Pipeline.IsDirty && working.SequenceEqual(VisionPipelineExecutionPlan.SerializePipeline(host.Workbench.Pipeline.WorkingCopyForTest)) && host.NativePreviewRunCount == runs, "owned fixture reload restores original edit state without run");
                File.WriteAllText(Path.ChangeExtension(outputPath, ".checks.json"), JsonSerializer.Serialize(new { Cases = cases, OriginalEditStateRestored = true, ValidInputAndNotMadeRecovery = true, ProductSHA256 = Convert.ToHexString(SHA256.HashData(File.ReadAllBytes(typeof(OpenVisionShellHostView).Assembly.Location))), Scope = "Actual Main controls and production theme commands, in-process render; no CU/native DPI/hover/held pressed/disabled input proof." }, new JsonSerializerOptions { WriteIndented = true }));
            }
            finally
            {
                if (host.Workbench.Pipeline.IsDirty) typeof(OpenVisionWorkbenchPipelineViewModel).GetMethod("Reload", BindingFlags.Instance | BindingFlags.NonPublic)!.Invoke(host.Workbench.Pipeline, null);
                OpenVisionLanguageService.SetLanguage(initial, false);
            }
        });
    }

    private static CaptureResult CaptureWorkbenchEmpty(string outputPath, int width, int height, string theme)
    {
        GlobalState global = new();
        global.Recipe.Name = "Smoke_WorkbenchEmpty";
        global.System.SaveWorkbenchLayout(new SystemStateConfig());
        OpenVisionShellHostWindow window = new(new ApplicationRuntimeContext(global, new DisplayManagerService()));
        OpenVisionShellHostView host = window.ShellHostForSmoke;
        ResourceDictionary themeOwner = host.Resources.MergedDictionaries.Single(dictionary => dictionary.Source?.OriginalString.EndsWith("OpenVisionLabWpfTheme.xaml", StringComparison.Ordinal) == true);
        themeOwner.MergedDictionaries.Add(new ResourceDictionary { Source = new Uri($"/OpenVisionLab;component/UI/Wpf/OpenVisionWorkbench{theme}.xaml", UriKind.Relative) });
        ResourceDictionary windowThemeOwner = window.Resources.MergedDictionaries.Single(dictionary => dictionary.Source?.OriginalString.EndsWith("OpenVisionLabWpfTheme.xaml", StringComparison.Ordinal) == true);
        windowThemeOwner.MergedDictionaries.Add(new ResourceDictionary { Source = new Uri($"/OpenVisionLab;component/UI/Wpf/OpenVisionWorkbench{theme}.xaml", UriKind.Relative) });
        List<object> cases = new();
        return CaptureStandaloneWindow(window, outputPath, width, height, () =>
        {
            OpenVisionWindowTitleBar titleBar = FindVisualChildren<OpenVisionWindowTitleBar>(window).Single();
            titleBar.Resources.MergedDictionaries.Add(new ResourceDictionary { Source = new Uri($"/OpenVisionLab;component/UI/Wpf/OpenVisionWorkbench{theme}.xaml", UriKind.Relative) });
            host.Resources.MergedDictionaries.Add(new ResourceDictionary { Source = new Uri($"/OpenVisionLab;component/UI/Wpf/OpenVisionWorkbench{theme}.xaml", UriKind.Relative) });
            window.Resources.MergedDictionaries.Add(new ResourceDictionary { Source = new Uri($"/OpenVisionLab;component/UI/Wpf/OpenVisionWorkbench{theme}.xaml", UriKind.Relative) });
            Pump(20);
            int runs = host.NativePreviewRunCount;
            int layers = host.LayerDocumentCount;
            string route = host.DirectResultRouteText;
            string routing = string.Join("|", host.Workbench.Pipeline.Rows.Select(row => row.Index + ":" + row.InputLayer + "->" + row.OutputLayer));
            string active = host.WorkspaceLayerTitle;
            OpenVisionLayerViewerView paneView = FindVisualChildren<OpenVisionLayerViewerView>(host).First(view => view.MainPane?.ShowOpenActions == true);
            Border empty = FindNamedVisualChild<Border>(paneView, "mainPaneEmpty")!;
            FrameworkElement bottom = FindVisualChildren<FrameworkElement>(host).Single(element => AutomationProperties.GetAutomationId(element) == "WorkbenchImagesEmpty");
            string[] actions = { "MainPaneEmptyOpenImage", "MainPaneEmptyOpenFolder", "MainPaneEmptyOpenSamples", "WorkbenchImagesEmptyOpenImage", "WorkbenchImagesEmptyOpenFolder", "WorkbenchImagesEmptyOpenSamples" };
            foreach (OpenVisionLanguage locale in new[] { OpenVisionLanguage.Korean, OpenVisionLanguage.English })
            {
                OpenVisionLanguageService.SetLanguage(locale, false); Pump(8);
                if (!empty.IsVisible || host.HasMainLayer || host.IsNativeDocumentActive || host.IsActiveWpfToolWindowVisibleForTest)
                    throw new InvalidOperationException("Compact image prompt must stay empty without opening a tool.");
                if (host.WorkspaceEmptyTitle != OpenVisionLanguageService.T("Workbench.Viewer.NoImage") || host.WorkspaceEmptyDetail != OpenVisionLanguageService.T("Workbench.Viewer.EmptyDetail"))
                    throw new InvalidOperationException("Image prompt failed the current locale.");
                TextBlock emptyTitle = FindNamedVisualChild<TextBlock>(paneView, "mainPaneEmptyTitleText")!;
                TextBlock bottomTitle = FindVisualChildren<TextBlock>(bottom).Single(label => label.Text == OpenVisionLanguageService.T("Workbench.Viewer.NoImage"));
                File.WriteAllText(Path.ChangeExtension(outputPath, ".palette-" + locale + ".json"), JsonSerializer.Serialize(new
                {
                    Theme = theme, Language = locale.ToString(), TitleForeground = emptyTitle.Foreground.ToString(),
                    TitleResource = emptyTitle.FindResource("OpenVision.Workbench.TextBrush").ToString(),
                    HostResource = host.FindResource("OpenVision.Workbench.TextBrush").ToString(),
                    LocalValue = emptyTitle.ReadLocalValue(TextBlock.ForegroundProperty).ToString(),
                    ValueSource = DependencyPropertyHelper.GetValueSource(emptyTitle, TextBlock.ForegroundProperty).BaseValueSource.ToString(),
                    Background = empty.Background.ToString(),
                    ProductAssembly = typeof(OpenVisionShellHostView).Assembly.Location,
                    ProductSHA256 = Convert.ToHexString(SHA256.HashData(File.ReadAllBytes(typeof(OpenVisionShellHostView).Assembly.Location)))
                }, new JsonSerializerOptions { WriteIndented = true }));
                AssertBrushContrast(emptyTitle.Foreground, empty.Background, "Viewer empty title " + theme + " " + locale);
                AssertBrushContrast(bottomTitle.Foreground, (Brush)host.FindResource("OpenVision.Workbench.PanelBrush"), "Bottom empty title " + theme + " " + locale);
                foreach (string actionId in actions)
                {
                    Button action = FindVisualChildren<Button>(actionId.StartsWith("MainPane", StringComparison.Ordinal) ? paneView : host).Single(button => AutomationProperties.GetAutomationId(button) == actionId);
                    AssertElementWithinAncestor(actionId, action, actionId.StartsWith("MainPane", StringComparison.Ordinal) ? empty : bottom);
                    bool imageAction = actionId.EndsWith("OpenImage", StringComparison.Ordinal);
                    bool folderAction = actionId.EndsWith("OpenFolder", StringComparison.Ordinal);
                    ICommand expected = imageAction ? host.WorkspaceCommands.LoadImageCommand : folderAction ? host.WorkspaceCommands.OpenFolderCommand : host.WorkspaceCommands.OpenSampleCommand;
                    if (!ReferenceEquals(action.Command, expected) || action.IsEnabled != expected.CanExecute(null))
                        throw new InvalidOperationException(actionId + " lost its existing command/CanExecute contract.");
                    TextBlock label = FindVisualChildren<TextBlock>(action).Single();
                    string key = imageAction ? "Workbench.Viewer.OpenImage" : folderAction ? "Workbench.Viewer.OpenFolder" : "Workbench.Viewer.OpenSamples";
                    if (label.Text != OpenVisionLanguageService.T(key)) throw new InvalidOperationException(actionId + " label is stale.");
                    AssertElementWithinAncestor(actionId + " label", label, action);
                    Border chrome = FindNamedVisualChild<Border>(action, "buttonChrome")!;
                    AssertBrushContrast(label.Foreground, chrome.Background, actionId + " " + theme + " " + locale);
                    if ((imageAction || folderAction) && !action.Focus()) throw new InvalidOperationException(actionId + " cannot receive keyboard focus.");
                    cases.Add(new { Theme = theme, Language = locale.ToString(), Width = width, Height = height, Action = actionId, action.IsEnabled, action.ActualWidth, action.ActualHeight, ExpectedCommandPreserved = true, RenderedLabel = label.Text });
                }
                string localePath = Path.Combine(Path.GetDirectoryName(outputPath)!, Path.GetFileNameWithoutExtension(outputPath) + "_" + locale + ".png");
                ScreenshotPngWriter.WriteElementPng(window, localePath, width, height);
                string currentRouting = string.Join("|", host.Workbench.Pipeline.Rows.Select(row => row.Index + ":" + row.InputLayer + "->" + row.OutputLayer));
                cases.Add(new { Language = locale.ToString(), BeforeRuns = runs, AfterRuns = host.NativePreviewRunCount, BeforeLayers = layers, AfterLayers = host.LayerDocumentCount, BeforeWorkspace = active, AfterWorkspace = host.WorkspaceLayerTitle, BeforeRouting = routing, AfterRouting = currentRouting, InitialDisplayRoute = route, LocalizedDisplayRoute = host.DirectResultRouteText });
                if (host.NativePreviewRunCount != runs || host.LayerDocumentCount != layers || host.WorkspaceLayerTitle != active || currentRouting != routing)
                    throw new InvalidOperationException("Empty prompt localization/focus caused execution, layer or route changes.");
                if (host.DirectResultRouteText != OpenVisionLanguageService.T("Shell.WorkspaceStatus.EmptyRoute"))
                    throw new InvalidOperationException("Empty-state display guidance did not follow the selected language.");
            }
            OpenVisionLanguageService.SetLanguage(OpenVisionLanguage.Korean, false); Pump(4);
            File.WriteAllText(Path.ChangeExtension(outputPath, ".json"), JsonSerializer.Serialize(cases, new JsonSerializerOptions { WriteIndented = true }));
        });
    }

    private static CaptureResult CaptureShellHostWorkspaceEmpty(string outputPath)
    {
        return CaptureShellHostWorkspaceEmpty(outputPath, OpenVisionLanguage.Korean);
    }

    private static CaptureResult CaptureShellHostWorkspaceEmpty(
        string outputPath,
        OpenVisionLanguage language)
    {
        OpenVisionLanguageService.SetLanguage(language, false);
        OpenVisionShellHostView shellHost = CreateShellHost("Smoke_WpfShellHostWorkspaceEmpty", seedMainLayer: false);
        OpenVisionLanguageService.SetLanguage(language, false);
        return CaptureWindowWithContent(shellHost, outputPath, 1600, 900, () =>
        {
            if (shellHost.HasMainLayer || shellHost.HasWorkspaceLayerPreview)
            {
                throw new InvalidOperationException("WPF workspace empty state must start without a seeded Main image.");
            }

            if (shellHost.IsActiveWpfToolWindowVisibleForTest || shellHost.IsNativeDocumentActive)
            {
                throw new InvalidOperationException("WPF workspace empty state must not auto-open a tool window.");
            }

            if (!shellHost.IsWorkspaceEmptyPromptVisible
                || !shellHost.WorkspaceEmptyTitle.Contains(OpenVisionLanguageService.T("Workbench.Viewer.NoImage"), StringComparison.Ordinal)
                || !shellHost.WorkspaceEmptyDetail.Contains(OpenVisionLanguageService.T("Workbench.Viewer.EmptyDetail"), StringComparison.Ordinal)
                || !shellHost.WorkspaceLoadImageButtonText.Contains(OpenVisionLanguageService.T("Workbench.Viewer.OpenImage"), StringComparison.Ordinal))
            {
                throw new InvalidOperationException("WPF workspace empty image prompt was not visible or localized.");
            }

            if (!shellHost.DirectResultTitleText.Contains(OpenVisionLanguageService.T("Shell.WorkspaceStatus.EmptyTitle"), StringComparison.Ordinal)
                || !shellHost.DirectResultRouteText.Contains(OpenVisionLanguageService.T("Shell.WorkspaceStatus.EmptyRoute"), StringComparison.Ordinal)
                || !shellHost.DirectResultStatusText.Contains(OpenVisionLanguageService.T("Shell.WorkspaceStatus.EmptyStatus"), StringComparison.Ordinal))
            {
                throw new InvalidOperationException(
                    "WPF workspace empty top status banner did not describe the image-load start state. "
                    + $"Title='{shellHost.DirectResultTitleText}', Route='{shellHost.DirectResultRouteText}', Status='{shellHost.DirectResultStatusText}'");
            }

            AssertToolRailReadiness(
                shellHost,
                OpenVisionLanguageService.T("Shell.ToolReadiness.InputMissingBadge"),
                OpenVisionLanguageService.T("Shell.ToolReadiness.InputMissingDescription"));

            AssertVisibleAutomationIds(
                shellHost,
                "WPF workspace compact image prompt",
                "WorkspaceEmptyImageActions",
                "WorkspaceEmptyOpenImage",
                "WorkspaceEmptyOpenFolder",
                "WorkbenchImagesEmpty",
                "WorkbenchImagesEmptyOpenImage",
                "WorkbenchImagesEmptyOpenFolder",
                "WorkbenchImagesEmptyOpenSamples",
                "WorkspaceEmptySampleButton",
                "HostGuideButton",
                "WorkbenchBottomPanel",
                "WorkbenchLogTab",
                "ShellLogToggleButton");
            AssertVisibleTextContains(
                shellHost,
                "WPF workspace empty localized compact image prompt",
                OpenVisionLanguageService.T("Workbench.Viewer.OpenFolder"),
                OpenVisionLanguageService.T("Workbench.Viewer.OpenImage"),
                OpenVisionLanguageService.T("Workbench.Viewer.OpenSamples"),
                OpenVisionLanguageService.T("Workbench.Viewer.EmptyDetail"),
                OpenVisionLanguageService.T("Workbench.Bottom.Log"));
            AssertVisibleTextDoesNotContain(
                shellHost,
                "WPF workspace empty stale language copy",
                language == OpenVisionLanguage.English ? "이미지 없음" : "No image");

            if (shellHost.RecipeCommands.LlmXmlDraftDependencyRows.Count == 0)
            {
                throw new InvalidOperationException("Recipe manager LLM XML dependency path drilldown did not expose any rows.");
            }

            if (language == OpenVisionLanguage.Korean)
            {
                OpenVisionLanguageService.SetLanguage(OpenVisionLanguage.English, false);
                Pump(8);
                AssertVisibleTextContains(
                    shellHost,
                    "WPF workspace empty English copy",
                    OpenVisionLanguageService.T("Shell.WorkspaceStatus.EmptyTitle"),
                    OpenVisionLanguageService.T("Workbench.Viewer.OpenFolder"),
                    OpenVisionLanguageService.T("Workbench.Viewer.OpenImage"),
                    OpenVisionLanguageService.T("Workbench.Viewer.OpenSamples"),
                    OpenVisionLanguageService.T("Workbench.Viewer.EmptyDetail"));
                if (shellHost.IsActiveWpfToolWindowVisibleForTest || shellHost.IsNativeDocumentActive)
                {
                    throw new InvalidOperationException("Changing workspace empty language must not open a tool window.");
                }

                OpenVisionLanguageService.SetLanguage(OpenVisionLanguage.Korean, false);
                Pump(8);
                AssertVisibleTextContains(
                    shellHost,
                    "WPF workspace empty Korean copy after language restore",
                    OpenVisionLanguageService.T("Shell.WorkspaceStatus.EmptyTitle"),
                    OpenVisionLanguageService.T("Workbench.Viewer.OpenFolder"),
                    OpenVisionLanguageService.T("Workbench.Viewer.OpenImage"),
                    OpenVisionLanguageService.T("Workbench.Viewer.OpenSamples"),
                    OpenVisionLanguageService.T("Workbench.Viewer.EmptyDetail"));
            }
        }, captureFloatingToolWindow: false);
    }

    private static CaptureResult CaptureShellHostLearnEntry(string outputPath)
    {
        OpenVisionLanguageService.SetLanguage(OpenVisionLanguage.Korean, false);
        OpenVisionShellHostView shellHost = CreateShellHost("Smoke_WpfShellHostLearnEntry", seedMainLayer: false);
        Window hostWindow = new()
        {
            Content = shellHost,
            Width = 1600,
            Height = 900,
            WindowStyle = WindowStyle.None,
            ResizeMode = ResizeMode.NoResize,
            ShowInTaskbar = false,
            Topmost = true
        };

        DateTime started = DateTime.UtcNow;
        hostWindow.Show();
        hostWindow.Activate();
        try
        {
            Pump(20);
            int beforeRuns = shellHost.NativePreviewRunCount;
            int beforeLayerDocumentCount = shellHost.LayerDocumentCount;
            string beforeWorkspaceLayerTitle = shellHost.WorkspaceLayerTitle;
            if (!shellHost.ChromeCommands.OpenLearnCommand.CanExecute(null))
                throw new InvalidOperationException("Main Help/Learn command is unavailable.");
            string hostOutputPath = Path.Combine(
                Path.GetDirectoryName(outputPath) ?? ".",
                Path.GetFileNameWithoutExtension(outputPath) + "_host.png");
            ScreenshotPngWriter.WriteElementPng(hostWindow, hostOutputPath, 1600, 900);

            shellHost.ChromeCommands.OpenLearnCommand.Execute(null);
            Pump(12);
            OpenVisionLearnWindow learnWindow = GetVisibleLearnWindow("top Learn button");
            if (learnWindow.SelectedTopicIndexForTest != 0)
            {
                throw new InvalidOperationException("Top Learn button did not open Learn at topic 1.");
            }
            AssertInitialKeyboardFocus(learnWindow, "OpenVisionLearnTopicList");
            OpenVisionLearnWindow firstLearnWindow = learnWindow;

            if (!learnWindow.CanOpenPracticeSamplesForTest)
            {
                throw new InvalidOperationException("Top Learn button did not attach Practice Samples action.");
            }

            string topPracticeLearnPathId = ClickPracticeSamplesAndCaptureSelectedLearnPath(
                learnWindow,
                "top Learn Practice Samples button");
            if (!string.Equals(topPracticeLearnPathId, "all", StringComparison.OrdinalIgnoreCase))
            {
                throw new InvalidOperationException(
                    "Top Learn Practice Samples did not open Sample Picker at the expected Learn path. "
                    + "Expected='all', Actual='"
                    + topPracticeLearnPathId
                    + "'.");
            }

            AssertVisibleTextContains(
                learnWindow,
                "OpenVision Learn topic 1 path overview",
                "추천 학습 경로",
                "Layer의 기본 구조");
            if (!learnWindow.FoundationToolLocationTitleForTest.Contains("Blob > ROI", StringComparison.Ordinal)
                || !learnWindow.FoundationToolLocationTitleForTest.Contains("Filter > Kernel", StringComparison.Ordinal)
                || !learnWindow.FoundationToolLocationTitleForTest.Contains("Rotate/Scale > Angle/Scale", StringComparison.Ordinal)
                || !learnWindow.FoundationToolLocationDetailForTest.Contains("Preview를 눌러", StringComparison.Ordinal))
            {
                throw new InvalidOperationException("Shell Learn did not expose the initial related Tool View parameter paths.");
            }

            learnWindow.Width = 1040;
            learnWindow.Height = 980;
            learnWindow.BringFoundationToolLocationIntoViewForTest();
            learnWindow.Activate();
            Pump(12);
            learnWindow.InvalidateVisual();
            learnWindow.UpdateLayout();
            Pump(8);
            SaveVisibleAutomationElementPng(
                learnWindow,
                "OpenVisionLearnFoundationToolLocationPanel",
                outputPath,
                "foundation-tool-location-panel.png");
            ScreenshotPngWriter.WriteElementPng(learnWindow, outputPath, 1040, 980);
            learnWindow.Close();
            Pump(8);
            if (firstLearnWindow.IsVisible)
            {
                throw new InvalidOperationException("Top Learn window remained visible after Close.");
            }

            shellHost.ChromeCommands.OpenLearnCommand.Execute(null);
            Pump(12);
            learnWindow = GetVisibleLearnWindow("Main Help/Learn command");
            if (ReferenceEquals(firstLearnWindow, learnWindow))
            {
                throw new InvalidOperationException("Shell reused the closed Learn window instance.");
            }

            if (learnWindow.SelectedTopicIndexForTest != 0)
            {
                throw new InvalidOperationException("Workspace empty Learn button did not open Learn at topic 1.");
            }
            AssertInitialKeyboardFocus(learnWindow, "OpenVisionLearnTopicList");

            if (!learnWindow.CanOpenPracticeSamplesForTest)
            {
                throw new InvalidOperationException("Workspace empty Learn button did not attach Practice Samples action.");
            }

            if (!learnWindow.CanOpenRelatedToolsForTest)
            {
                throw new InvalidOperationException("Shell Learn did not enable the related Tool View actions.");
            }

            if (!learnWindow.CanOpenColorHsvToolForTest)
            {
                throw new InvalidOperationException("Shell Learn did not enable the Color / HSV Tool View action.");
            }

            if (!learnWindow.CanOpenBrightnessToolsForTest)
            {
                throw new InvalidOperationException("Shell Learn did not enable the Mean / Histogram Tool View actions.");
            }

            if (!learnWindow.CanOpenArithmeticToolForTest)
            {
                throw new InvalidOperationException("Shell Learn did not enable the Arithmetic Tool View action.");
            }

            if (!learnWindow.CanOpenGeometryToolForTest)
            {
                throw new InvalidOperationException("Shell Learn did not enable the Rotate / Scale Tool View action.");
            }

            if (!learnWindow.CanOpenFilteringToolForTest)
            {
                throw new InvalidOperationException("Shell Learn did not enable the Filter Tool View action.");
            }

            if (!learnWindow.CanOpenMorphologyToolForTest)
            {
                throw new InvalidOperationException("Shell Learn did not enable the Morphology Tool View action.");
            }

            if (!learnWindow.CanOpenBlobToolForTest)
            {
                throw new InvalidOperationException("Shell Learn did not enable the Blob Tool View action.");
            }

            if (!learnWindow.CanOpenContourToolForTest)
            {
                throw new InvalidOperationException("Shell Learn did not enable the Contour Tool View action.");
            }

            if (!learnWindow.CanOpenEdgeLineToolsForTest)
            {
                throw new InvalidOperationException("Shell Learn did not enable the EdgeDetection and Line Tool View actions.");
            }

            if (!learnWindow.CanOpenLineDistanceToolForTest)
            {
                throw new InvalidOperationException("Shell Learn did not enable the LineDistance Line Tool View action.");
            }

            if (!learnWindow.CanOpenMatchingToolForTest)
            {
                throw new InvalidOperationException("Shell Learn did not enable the Matching Tool View action.");
            }

            if (!learnWindow.CanOpenFeatureMatchingToolForTest)
            {
                throw new InvalidOperationException("Shell Learn did not enable the FeatureMatching Tool View action.");
            }

            if (shellHost.NativePreviewRunCount != beforeRuns
                || shellHost.IsActiveWpfToolWindowVisibleForTest
                || shellHost.IsNativeDocumentActive)
            {
                throw new InvalidOperationException("Opening Learn or Practice Samples triggered tool Preview/Run or opened a tool document.");
            }

            ClickVisibleButtonByAutomationId(
                learnWindow,
                "OpenVisionLearnFoundationOpenRoiToolButton",
                "foundation CvROI Blob tool button");
            Pump(32);
            AssertLearnRelatedToolOpenedWithoutRun(
                shellHost,
                beforeRuns,
                beforeLayerDocumentCount,
                beforeWorkspaceLayerTitle,
                "BlobToolWpfView",
                VISION_MENU.Blob,
                "foundation CvROI");
            if (!learnWindow.FoundationToolLocationTitleForTest.Contains("PropertyGrid > ROI > Use ROI / ROI (CvROI)", StringComparison.Ordinal)
                || !learnWindow.FoundationToolLocationDetailForTest.Contains("강조된 PropertyGrid", StringComparison.Ordinal))
            {
                throw new InvalidOperationException("Foundation CvROI action did not expose the Blob PropertyGrid location guide.");
            }

            ClickVisibleButtonByAutomationId(
                learnWindow,
                "OpenVisionLearnFoundationOpenKernelToolButton",
                "foundation Kernel Filter tool button");
            Pump(32);
            AssertLearnRelatedToolOpenedWithoutRun(
                shellHost,
                beforeRuns,
                beforeLayerDocumentCount,
                beforeWorkspaceLayerTitle,
                "FilterToolWpfView",
                VISION_MENU.Filter,
                "foundation Kernel");
            if (!learnWindow.FoundationToolLocationTitleForTest.Contains("Filter options > Kernel Width / Kernel Height", StringComparison.Ordinal))
            {
                throw new InvalidOperationException("Foundation Kernel action did not expose the Filter parameter location guide.");
            }

            ClickVisibleButtonByAutomationId(
                learnWindow,
                "OpenVisionLearnFoundationOpenOutputSizeToolButton",
                "foundation OutputSize Rotate tool button");
            Pump(32);
            AssertLearnRelatedToolOpenedWithoutRun(
                shellHost,
                beforeRuns,
                beforeLayerDocumentCount,
                beforeWorkspaceLayerTitle,
                "SimplePreprocessToolWpfView",
                VISION_MENU.RotateAndScale,
                "foundation OutputSize");
            if (!learnWindow.FoundationToolLocationTitleForTest.Contains("Angle / Scale X / Scale Y", StringComparison.Ordinal)
                || !learnWindow.FoundationToolLocationDetailForTest.Contains("Preview 결과에서 OutputSize", StringComparison.Ordinal))
            {
                throw new InvalidOperationException("Foundation OutputSize action did not expose the Rotate/Scale parameter location guide.");
            }

            ListBox? topicList = FindVisualChildren<ListBox>(learnWindow)
                .FirstOrDefault(item => string.Equals(
                    AutomationProperties.GetAutomationId(item),
                    "OpenVisionLearnTopicList",
                    StringComparison.Ordinal));
            if (topicList == null)
            {
                throw new InvalidOperationException("Shell Learn topic list was not visible for Color / HSV navigation.");
            }

            topicList.SelectedIndex = (int)OpenVisionLearnTopicIndex.Threshold;
            topicList.ScrollIntoView(topicList.SelectedItem);
            Pump(16);
            if (!learnWindow.CanOpenThresholdToolForTest)
            {
                throw new InvalidOperationException("Threshold Learn did not enable its related Tool View action.");
            }

            string thresholdPracticePathId = ClickPracticeSamplesAndCaptureSelectedLearnPath(
