            if (!learnWindow.GeometryToolLocationTitleForTest.Contains("Angle, Scale X, Scale Y", StringComparison.Ordinal)
                || !learnWindow.GeometryToolLocationDetailForTest.Contains("OutputSize", StringComparison.Ordinal)
