        pipeline.Steps.Add(step);

        object mappedProperty = VisionPipelineStepPropertyMapper.CreateProperty(step)
            ?? throw new InvalidOperationException("PinArrayGap PropertyGrid mapper returned no property object.");
        VisionPipelineStep roundTrip = new()
        {
            Name = step.Name,
            ToolType = step.ToolType,
            InputLayer = step.InputLayer,
            OutputLayer = step.OutputLayer
        };
        if (!VisionPipelineStepPropertyMapper.ApplyProperty(roundTrip, mappedProperty)
            || !string.Equals(roundTrip.Parameters.GetValueOrDefault("MeasurementMode"), "CenterPitch", StringComparison.Ordinal)
            || !string.Equals(roundTrip.Parameters.GetValueOrDefault("CvROI"), "50,50,540,140", StringComparison.Ordinal)
            || !string.Equals(roundTrip.Parameters.GetValueOrDefault("ALLOW_BRANCH_INPUT"), "true", StringComparison.OrdinalIgnoreCase))
        {
            throw new InvalidOperationException("PinArrayGap PropertyGrid direct round trip lost mode, ROI, or an unrepresented parameter.");
        }

        VisionPipelineStep aliasStep = new()
        {
            Name = "Adjacent alias",
            ToolType = "AdjacentPinGapTool",
            InputLayer = "Main",
            OutputLayer = "Alias_Result"
        };
        aliasStep.Parameters["UnrepresentedParameter"] = "preserved";
        object aliasProperty = VisionPipelineStepPropertyMapper.CreateProperty(aliasStep)
            ?? throw new InvalidOperationException("AdjacentPinGapTool alias returned no property object.");
        VisionPipelineStep aliasRoundTrip = new();
        if (!VisionPipelineStepPropertyMapper.ApplyProperty(aliasRoundTrip, aliasProperty)
            || !string.Equals(aliasRoundTrip.ToolType, "AdjacentPinGapTool", StringComparison.Ordinal)
            || !string.Equals(aliasRoundTrip.Parameters.GetValueOrDefault("MeasurementMode"), "EdgeGap", StringComparison.Ordinal)
            || !string.Equals(aliasRoundTrip.Parameters.GetValueOrDefault("DarkThreshold"), "128", StringComparison.Ordinal)
            || !string.Equals(aliasRoundTrip.Parameters.GetValueOrDefault("UnrepresentedParameter"), "preserved", StringComparison.Ordinal))
        {
            throw new InvalidOperationException("AdjacentPinGapTool alias/default/baseline round trip changed.");
        }

        VisionPipelineStorage.Save(recipeName, pipeline);
        VisionPipelineStorage.SaveActivePipelineName(recipeName, pipeline.Name);
        OpenVisionShellHostView shellHost = CreateShellHost(recipeName, seedMainLayer: false);
        try
        {
            return CaptureWindowWithContent(shellHost, outputPath, 1600, 900, () =>
            {
                ToggleButton recipeManagerButton = FindNamedVisualChild<ToggleButton>(shellHost, "btnHostRecipeManager")
                    ?? throw new InvalidOperationException("PinArrayGap PropertyGrid smoke could not find Recipe Manager.");
                recipeManagerButton.IsChecked = true;
                Pump(100);

                FindNamedVisualChild<ToggleButton>(shellHost, "recipeAdvancedReviewToggle")!.IsChecked = true;
                Pump(60);
                FindNamedVisualChild<TabItem>(shellHost, "tabRecipePipeline")!.IsSelected = true;
                Pump(40);
                FindNamedVisualChild<TabItem>(shellHost, "tabRecipePipelineStepSettings")!.IsSelected = true;
                Pump(40);

                OpenVisionRecipePipelineStepPreview preview = shellHost.RecipeCommands.SelectedRecipeSummary.PipelinePreviewSteps.Single();
                shellHost.RecipeCommands.SelectedPipelinePreviewStep = preview;
                if (!shellHost.RecipeCommands.LoadSelectedStepParametersCommand.CanExecute(null))
                {
                    throw new InvalidOperationException("PinArrayGap PropertyGrid load command remained disabled.");
                }

                shellHost.RecipeCommands.LoadSelectedStepParametersCommand.Execute(null);
                Pump(180);

                FrameworkElement propertyGridHost = FindVisualChildren<FrameworkElement>(shellHost)
                    .FirstOrDefault(item => item.IsVisible && string.Equals(
                        AutomationProperties.GetAutomationId(item),
                        "HostRecipeSelectedStepPropertyGridHost",
                        StringComparison.Ordinal))
                    ?? throw new InvalidOperationException("PinArrayGap PropertyGrid host was not visible.");
                System.Windows.Controls.WpfPropertyGrid.PropertyGrid grid =
                    FindVisualChildren<System.Windows.Controls.WpfPropertyGrid.PropertyGrid>(propertyGridHost)
                        .FirstOrDefault(item => item.IsVisible && item.SelectedObject != null)
                    ?? throw new InvalidOperationException("PinArrayGap PropertyGrid did not load.");
                string[] requiredProperties =
                {
                    "MeasurementMode", "UseRoi", "Roi", "DarkThreshold", "MinimumDarkCoverageRatio",
                    "MinimumPinWidth", "MaximumPinBreakWidth", "MinimumGapWidth", "AcceptanceMetricName"
                };
                PropertyDescriptorCollection descriptors = TypeDescriptor.GetProperties(grid.SelectedObject);
                string[] missingProperties = requiredProperties
                    .Where(propertyName => descriptors.Find(propertyName, true) == null)
                    .ToArray();
                if (missingProperties.Length > 0)
                {
                    throw new InvalidOperationException("PinArrayGap PropertyGrid missed: " + string.Join(",", missingProperties));
                }

                int previewRunsBeforeApply = shellHost.NativePreviewRunCount;
                shellHost.RecipeCommands.ApplySelectedStepParametersCommand.Execute(null);
                Pump(220);
                VisionPipeline savedPipeline = VisionPipelineStorage.Load(recipeName, pipeline.Name);
                VisionPipelineStep savedStep = savedPipeline.Steps.Single();
                if (!string.Equals(savedStep.Parameters.GetValueOrDefault("MeasurementMode"), "CenterPitch", StringComparison.Ordinal)
                    || !string.Equals(savedStep.Parameters.GetValueOrDefault("CvROI"), "50,50,540,140", StringComparison.Ordinal)
                    || !string.Equals(savedStep.Parameters.GetValueOrDefault("ALLOW_BRANCH_INPUT"), "true", StringComparison.OrdinalIgnoreCase)
                    || !string.Equals(savedStep.AcceptanceMetricName, "PitchPxRange", StringComparison.Ordinal)
                    || shellHost.NativePreviewRunCount != previewRunsBeforeApply)
                {
                    throw new InvalidOperationException("Recipe Manager PinArrayGap apply/save/reload lost its contract or triggered Preview/Run.");
                }

                TextBox searchTextBox = GetActivePropertyGridSearchTextBox(grid, "PinArrayGap recipe step");
                searchTextBox.Text = "Measurement";
                searchTextBox.GetBindingExpression(TextBox.TextProperty)?.UpdateSource();
                grid.UpdateLayout();
                Pump(60);

                ScrollViewer pipelineScrollViewer = FindNamedVisualChild<ScrollViewer>(
                    shellHost,
                    "recipePipelineTabScrollViewer")
                    ?? throw new InvalidOperationException("PinArrayGap Pipeline scroll viewer was not found.");
                pipelineScrollViewer.ScrollToBottom();
                pipelineScrollViewer.UpdateLayout();
                Pump(80);
                BringPropertyGridPropertyIntoView(grid, "MeasurementMode", "PinArrayGap recipe step", 0D);
                if (grid.IsSearchEmptyMessageVisibleForTest || shellHost.NativePreviewRunCount != 0)
                {
                    throw new InvalidOperationException("PinArrayGap PropertyGrid Pitch search failed or changed Preview/Run state.");
                }
            }, captureFloatingToolWindow: false, captureScreen: true);
        }
        finally
        {
            RecipeWorkspaceService.DeleteVisionWorkspace(recipeName);
        }
    }

    private static CaptureResult CaptureShellHostRecipeLinePairProperties(string outputPath)
    {
        OpenVisionLanguageService.SetLanguage(OpenVisionLanguage.English, false);
        SmokeRecipeWorkspaceCleanup.DeleteTransient();

        string recipeName = "Smoke_RecipeLinePair_" + Guid.NewGuid().ToString("N").Substring(0, 12);
        VisionPipeline pipeline = new() { Name = "LinePair_PropertyGrid" };
        VisionPipelineStep step = new()
        {
            Name = "01 Asymmetric Line Pair",
            ToolType = "LineDistance",
            InputLayer = "Main",
            OutputLayer = "LinePair_Result"
        };
        step.Parameters["LeftUSE_ROI"] = "true";
        step.Parameters["LeftCvROI"] = "430,170,55,145";
        step.Parameters["LeftPRJ_PORALITY"] = "WTOB";
        step.Parameters["LeftPRJ_DIR"] = "X_LTOR";
        step.Parameters["LeftVER_PRJ_DIR"] = "Y_TTOB";
        step.Parameters["LeftUSE_MANUAL_ANGLE"] = "true";
        step.Parameters["LeftMANUAL_ANGLE_VALUE"] = "89";
        step.Parameters["LeftCONTRAST"] = "18";
        step.Parameters["LeftTHICKNESS"] = "2";
        step.Parameters["LeftUSE_THRESHOLD"] = "false";
        step.Parameters["LeftUSE_AVERAGE_FILTER"] = "true";
        step.Parameters["LeftAVERAGE_Diff"] = "73";
        step.Parameters["LeftAVERAGE_FILTER_TYPE"] = "X";
        step.Parameters["LeftSHOW_VERTICAL_LINE"] = "false";
        step.Parameters["LeftSHOW_EDGE"] = "true";
        step.Parameters["LeftSHOW_CONTOUR"] = "false";
        step.Parameters["LeftSHOW_FITLINE"] = "true";
        step.Parameters["RightUSE_ROI"] = "true";
        step.Parameters["RightCvROI"] = "485,170,70,145";
        step.Parameters["RightPRJ_PORALITY"] = "BTOW";
        step.Parameters["RightPRJ_DIR"] = "X_RTOL";
        step.Parameters["RightVER_PRJ_DIR"] = "Y_BTOT";
        step.Parameters["RightUSE_MANUAL_ANGLE"] = "false";
        step.Parameters["RightMANUAL_ANGLE_VALUE"] = "-7";
        step.Parameters["RightCONTRAST"] = "44";
        step.Parameters["RightTHICKNESS"] = "7";
        step.Parameters["RightUSE_THRESHOLD"] = "true";
        step.Parameters["RightUSE_AVERAGE_FILTER"] = "false";
        step.Parameters["RightAVERAGE_Diff"] = "91";
        step.Parameters["RightAVERAGE_FILTER_TYPE"] = "Y";
        step.Parameters["RightSHOW_VERTICAL_LINE"] = "true";
        step.Parameters["RightSHOW_EDGE"] = "false";
        step.Parameters["RightSHOW_CONTOUR"] = "true";
        step.Parameters["RightSHOW_FITLINE"] = "false";
        pipeline.Steps.Add(step);

        object mappedProperty = VisionPipelineStepPropertyMapper.CreateProperty(step)
            ?? throw new InvalidOperationException("Line pair PropertyGrid mapper returned no property object.");
        VisionPipelineStep roundTrip = new()
        {
            Name = step.Name,
            ToolType = step.ToolType,
            InputLayer = step.InputLayer,
            OutputLayer = step.OutputLayer
        };
        if (!VisionPipelineStepPropertyMapper.ApplyProperty(roundTrip, mappedProperty))
        {
            throw new InvalidOperationException("Line pair PropertyGrid mapper could not apply its property object.");
        }

        string[] asymmetricParameters =
        {
            "LeftUSE_ROI", "LeftCvROI", "LeftPRJ_PORALITY", "LeftPRJ_DIR", "LeftVER_PRJ_DIR",
            "LeftUSE_MANUAL_ANGLE", "LeftMANUAL_ANGLE_VALUE", "LeftCONTRAST", "LeftTHICKNESS", "LeftUSE_THRESHOLD",
            "LeftUSE_AVERAGE_FILTER", "LeftAVERAGE_Diff", "LeftAVERAGE_FILTER_TYPE",
            "LeftSHOW_VERTICAL_LINE", "LeftSHOW_EDGE", "LeftSHOW_CONTOUR", "LeftSHOW_FITLINE",
            "RightUSE_ROI", "RightCvROI", "RightPRJ_PORALITY", "RightPRJ_DIR", "RightVER_PRJ_DIR",
            "RightUSE_MANUAL_ANGLE", "RightMANUAL_ANGLE_VALUE", "RightCONTRAST", "RightTHICKNESS", "RightUSE_THRESHOLD",
            "RightUSE_AVERAGE_FILTER", "RightAVERAGE_Diff", "RightAVERAGE_FILTER_TYPE",
            "RightSHOW_VERTICAL_LINE", "RightSHOW_EDGE", "RightSHOW_CONTOUR", "RightSHOW_FITLINE"
        };
        string[] lostParameters = asymmetricParameters
            .Where(key => !roundTrip.Parameters.TryGetValue(key, out string? actual)
                || !string.Equals(actual, step.Parameters[key], StringComparison.OrdinalIgnoreCase))
            .Select(key => key + "='" + roundTrip.Parameters.GetValueOrDefault(key, "<missing>")
                + "' expected '" + step.Parameters[key] + "'")
            .ToArray();
        if (lostParameters.Length > 0)
        {
            throw new InvalidOperationException(
                "Line pair PropertyGrid mapper lost asymmetric A/B parameters: "
                + string.Join("; ", lostParameters));
        }

        VisionPipelineStep aliasStep = new()
        {
            Name = "Line intersection alias",
            ToolType = "LineIntersectionTool",
            InputLayer = "Main",
            OutputLayer = "Intersection_Result"
        };
        object aliasProperty = VisionPipelineStepPropertyMapper.CreateProperty(aliasStep)
            ?? throw new InvalidOperationException("LineIntersectionTool alias returned no property object.");
        VisionPipelineStep aliasRoundTrip = new();
        if (!VisionPipelineStepPropertyMapper.ApplyProperty(aliasRoundTrip, aliasProperty)
            || !string.Equals(aliasRoundTrip.ToolType, "LineIntersectionTool", StringComparison.Ordinal)
            || !string.Equals(aliasRoundTrip.Parameters.GetValueOrDefault("LeftPRJ_DIR"), "X_LTOR", StringComparison.Ordinal)
            || !string.Equals(aliasRoundTrip.Parameters.GetValueOrDefault("RightPRJ_DIR"), "X_RTOL", StringComparison.Ordinal))
        {
            throw new InvalidOperationException("LineIntersectionTool alias/default direction round trip changed.");
        }

        PropertyDescriptorCollection editDescriptors = TypeDescriptor.GetProperties(mappedProperty);
        editDescriptors["RightRoi"]?.SetValue(mappedProperty, new OpenCvSharp.Rect(500, 175, 72, 140));
        editDescriptors["RightManualAngleValue"]?.SetValue(mappedProperty, -11D);
        editDescriptors["Contrast"]?.SetValue(mappedProperty, 21D);
        VisionPipelineStep editedRoundTrip = new()
        {
            Name = step.Name,
            ToolType = step.ToolType,
            InputLayer = step.InputLayer,
            OutputLayer = step.OutputLayer
        };
        if (!VisionPipelineStepPropertyMapper.ApplyProperty(editedRoundTrip, mappedProperty)
            || !string.Equals(editedRoundTrip.Parameters["LeftCvROI"], "430,170,55,145", StringComparison.Ordinal)
            || !string.Equals(editedRoundTrip.Parameters["RightCvROI"], "500,175,72,140", StringComparison.Ordinal)
            || !string.Equals(editedRoundTrip.Parameters["LeftMANUAL_ANGLE_VALUE"], "89", StringComparison.Ordinal)
            || !string.Equals(editedRoundTrip.Parameters["RightMANUAL_ANGLE_VALUE"], "-11", StringComparison.Ordinal)
            || !string.Equals(editedRoundTrip.Parameters["LeftCONTRAST"], "21", StringComparison.Ordinal)
            || !string.Equals(editedRoundTrip.Parameters["RightCONTRAST"], "21", StringComparison.Ordinal))
        {
            throw new InvalidOperationException("Line pair PropertyGrid mapper did not edit Line B independently of Line A.");
        }

        VisionPipelineStorage.Save(recipeName, pipeline);
        VisionPipelineStorage.SaveActivePipelineName(recipeName, pipeline.Name);
        OpenVisionShellHostView shellHost = CreateShellHost(recipeName, seedMainLayer: false);
        try
        {
            return CaptureWindowWithContent(shellHost, outputPath, 1600, 900, () =>
            {
                ToggleButton recipeManagerButton = FindNamedVisualChild<ToggleButton>(shellHost, "btnHostRecipeManager")
                    ?? throw new InvalidOperationException("Line pair PropertyGrid smoke could not find Recipe Manager.");
                recipeManagerButton.IsChecked = true;
                Pump(100);

                FindNamedVisualChild<ToggleButton>(shellHost, "recipeAdvancedReviewToggle")!.IsChecked = true;
                Pump(60);
                FindNamedVisualChild<TabItem>(shellHost, "tabRecipePipeline")!.IsSelected = true;
                Pump(40);
                FindNamedVisualChild<TabItem>(shellHost, "tabRecipePipelineStepSettings")!.IsSelected = true;
                Pump(40);

                OpenVisionRecipePipelineStepPreview preview = shellHost.RecipeCommands.SelectedRecipeSummary.PipelinePreviewSteps.Single();
                shellHost.RecipeCommands.SelectedPipelinePreviewStep = preview;
                shellHost.RecipeCommands.LoadSelectedStepParametersCommand.Execute(null);
                Pump(180);

                FrameworkElement propertyGridHost = FindVisualChildren<FrameworkElement>(shellHost)
                    .FirstOrDefault(item => item.IsVisible && string.Equals(
                        AutomationProperties.GetAutomationId(item),
                        "HostRecipeSelectedStepPropertyGridHost",
                        StringComparison.Ordinal))
                    ?? throw new InvalidOperationException("Line pair PropertyGrid host was not visible.");
                propertyGridHost.BringIntoView();
                propertyGridHost.UpdateLayout();
                Pump(80);

                System.Windows.Controls.WpfPropertyGrid.PropertyGrid grid =
                    FindVisualChildren<System.Windows.Controls.WpfPropertyGrid.PropertyGrid>(propertyGridHost)
                        .FirstOrDefault(item => item.IsVisible && item.SelectedObject != null)
                    ?? throw new InvalidOperationException("Line pair PropertyGrid did not load.");
                string[] requiredProperties =
                {
                    "UseRoi", "Roi", "LeftDirection", "Polarity", "VerticalProjectionDirection",
                    "UseManualAngle", "ManualAngleValue", "RightUseRoi", "RightRoi", "RightDirection",
                    "RightPolarity", "RightVerticalProjectionDirection", "RightUseManualAngle", "RightManualAngleValue",
                    "UseAverageFilter", "AverageDiff", "AverageFilterType",
                    "ShowVerticalLine", "ShowEdge", "ShowContour", "ShowFitLine"
                };
                PropertyDescriptorCollection descriptors = TypeDescriptor.GetProperties(grid.SelectedObject);
                string[] missingProperties = requiredProperties
                    .Where(name => descriptors.Find(name, true) == null)
                    .ToArray();
                if (missingProperties.Length > 0)
                {
                    throw new InvalidOperationException(
                        "Line pair PropertyGrid missed independent A/B properties: "
                        + string.Join(",", missingProperties));
                }
                string[] editableCompatibilityProperties = new[]
                    {
                        "UseAverageFilter",
                        "AverageDiff",
                        "AverageFilterType",
                        "ShowVerticalLine",
                        "ShowEdge",
                        "ShowContour",
                        "ShowFitLine"
                    }
                    .Where(name => !IsCompatibilityReadOnlyProperty(grid.SelectedObject, name))
                    .ToArray();
                if (editableCompatibilityProperties.Length > 0)
                {
                    throw new InvalidOperationException(
                        "Recipe Manager exposed inactive/legacy Line values as editable: "
                        + string.Join(",", editableCompatibilityProperties));
                }

                int previewRunsBeforeApply = shellHost.NativePreviewRunCount;
                shellHost.RecipeCommands.ApplySelectedStepParametersCommand.Execute(null);
                Pump(220);
                VisionPipeline savedPipeline = VisionPipelineStorage.Load(recipeName, pipeline.Name);
                VisionPipelineStep savedStep = savedPipeline.Steps.Single();
                string[] savedLosses = asymmetricParameters
                    .Where(key => !savedStep.Parameters.TryGetValue(key, out string? actual)
                        || !string.Equals(actual, step.Parameters[key], StringComparison.OrdinalIgnoreCase))
                    .Select(key => key + "='" + savedStep.Parameters.GetValueOrDefault(key, "<missing>")
                        + "' expected '" + step.Parameters[key] + "'")
                    .ToArray();
                if (savedLosses.Length > 0
                    || shellHost.NativePreviewRunCount != previewRunsBeforeApply)
                {
                    throw new InvalidOperationException(
                        "Recipe Manager Line pair apply/save/reload lost A/B parameters or triggered Preview/Run. "
                        + "Lost=" + string.Join("; ", savedLosses)
                        + $", Runs={shellHost.NativePreviewRunCount}/{previewRunsBeforeApply}");
                }

                TextBox searchTextBox = GetActivePropertyGridSearchTextBox(grid, "Line pair recipe step");
                searchTextBox.Text = "ROI";
                searchTextBox.GetBindingExpression(TextBox.TextProperty)?.UpdateSource();
                grid.UpdateLayout();
                Pump(60);
                ScrollViewer pipelineScrollViewer = FindNamedVisualChild<ScrollViewer>(
                    shellHost,
                    "recipePipelineTabScrollViewer")
                    ?? throw new InvalidOperationException("Line pair Pipeline scroll viewer was not found.");
                pipelineScrollViewer.ScrollToBottom();
                pipelineScrollViewer.UpdateLayout();
                Pump(60);
                BringPropertyGridPropertyIntoView(grid, "RightRoi", "Line pair recipe step", 0D);
                if (grid.IsSearchEmptyMessageVisibleForTest || shellHost.NativePreviewRunCount != 0)
                {
                    throw new InvalidOperationException(
                        "Line pair PropertyGrid ROI search failed or loading parameters triggered Preview/Run.");
                }
            }, captureFloatingToolWindow: false, captureScreen: true);
        }
        finally
        {
            RecipeWorkspaceService.DeleteVisionWorkspace(recipeName);
        }
    }

    private static CaptureResult CaptureCvr20OverlayRendering(string outputPath)
    {
        OpenVisionLanguageService.SetLanguage(OpenVisionLanguage.English, false);
        SmokeRecipeWorkspaceCleanup.DeleteTransient();
        VerifyCvr20OverlayRenderingContract(outputPath);
        string recipeName = "Smoke_Cvr20Overlay_" + Guid.NewGuid().ToString("N").Substring(0, 12);
        VisionPipeline pipeline = new VisionPipeline { Name = "CVR20_Overlay_Rendering" };
        VisionPipelineStep threshold = new VisionPipelineStep
        {
            Name = "01 Threshold Source",
            ToolType = "Threshold",
            InputLayer = "Main",
            OutputLayer = "Threshold_Result"
        };
        threshold.Parameters["THRESHOLD"] = "128";
        VisionPipelineStep overlay = new VisionPipelineStep
        {
            Name = "02 Review Overlay",
            ToolType = "OverlayMerge",
            InputLayer = "Main",
            OutputLayer = "Overlay_Result"
        };
        overlay.Parameters["SourceSteps"] = threshold.Name;
        overlay.Parameters["BurnIn"] = "true";
        overlay.Parameters["DrawLabels"] = "true";
        overlay.Parameters["CVR20_PRESERVE_UNKNOWN"] = "retained";
        pipeline.Steps.Add(threshold);
        pipeline.Steps.Add(overlay);
        VisionPipelineStorage.Save(recipeName, pipeline);
        VisionPipelineStorage.SaveActivePipelineName(recipeName, pipeline.Name);

        OpenVisionShellHostView shellHost = CreateShellHost(recipeName, seedMainLayer: false);
        try
        {
            return CaptureWindowWithContent(shellHost, outputPath, 1600, 900, () =>
            {
                ToggleButton recipeManagerButton =
                    FindNamedVisualChild<ToggleButton>(shellHost, "btnHostRecipeManager")
                    ?? throw new InvalidOperationException("CVR-20 baseline could not find Recipe Manager.");
                recipeManagerButton.IsChecked = true;
                Pump(100);
                ToggleButton advanced =
                    FindNamedVisualChild<ToggleButton>(shellHost, "recipeAdvancedReviewToggle")
                    ?? throw new InvalidOperationException("CVR-20 baseline could not find Advanced Review.");
                advanced.IsChecked = true;
                Pump(60);
                TabItem pipelineTab = FindNamedVisualChild<TabItem>(shellHost, "tabRecipePipeline")
                    ?? throw new InvalidOperationException("CVR-20 baseline could not find Pipeline tab.");
                pipelineTab.IsSelected = true;
                Pump(40);
                TabItem stepsTab = FindNamedVisualChild<TabItem>(shellHost, "tabRecipePipelineStepSettings")
                    ?? throw new InvalidOperationException("CVR-20 baseline could not find XML/Steps tab.");
                stepsTab.IsSelected = true;
                Pump(80);

                OpenVisionRecipePipelineStepPreview preview =
                    shellHost.RecipeCommands.SelectedRecipeSummary.PipelinePreviewSteps
                        .Single(item => string.Equals(item.ToolType, "OverlayMerge", StringComparison.OrdinalIgnoreCase));
                shellHost.RecipeCommands.SelectedPipelinePreviewStep = preview;
                shellHost.RecipeCommands.LoadSelectedStepParametersCommand.Execute(null);
                Pump(180);
                if (!shellHost.RecipeCommands.HasSelectedStepEditObject
                    || !shellHost.RecipeCommands.HasSelectedOverlayMergeEditObject)
                {
                    throw new InvalidOperationException(
                        "CVR-20 OverlayMerge PropertyGrid was not exposed.");
                }

                FrameworkElement propertyGridHost = FindVisualChildren<FrameworkElement>(shellHost)
                    .FirstOrDefault(item => item.IsVisible && string.Equals(
                        AutomationProperties.GetAutomationId(item),
                        "HostRecipeSelectedStepPropertyGridHost",
                        StringComparison.Ordinal))
                    ?? throw new InvalidOperationException("CVR-20 OverlayMerge PropertyGrid host was not visible.");
                System.Windows.Controls.WpfPropertyGrid.PropertyGrid grid =
                    FindVisualChildren<System.Windows.Controls.WpfPropertyGrid.PropertyGrid>(propertyGridHost)
                        .FirstOrDefault(item => item.IsVisible && item.SelectedObject != null)
                    ?? throw new InvalidOperationException("CVR-20 OverlayMerge PropertyGrid did not load.");
                PropertyDescriptorCollection descriptors = TypeDescriptor.GetProperties(grid.SelectedObject);
                string[] requiredProperties =
                {
                    "SourceLayers", "SourceSteps", "RenderPreset", "LabelMode", "LineWidth",
                    "PointSize", "LabelBackground", "LabelMargin", "MaxPoints", "BurnIn", "AllowEmpty"
                };
                string[] missingProperties = requiredProperties
                    .Where(name => descriptors.Find(name, true) == null)
                    .ToArray();
                if (missingProperties.Length > 0)
                {
                    throw new InvalidOperationException(
                        "CVR-20 OverlayMerge PropertyGrid missed: "
                        + string.Join(",", missingProperties));
                }
                int previewRunsBefore = shellHost.NativePreviewRunCount;
                int layerCountBefore = shellHost.LayerDocumentCount;
                string activeLayerBefore = shellHost.ActiveHostLayerTitle;
                string inputRouteBefore = shellHost.ActiveNativeRouteInputLayerNameForTest;
                string outputRouteBefore = shellHost.ActiveNativeRouteOutputLayerNameForTest;

                descriptors["RenderPreset"]!.SetValue(
                    grid.SelectedObject,
                    VisionPipelineOverlayRenderPreset.HighContrast);
                descriptors["LabelMode"]!.SetValue(
                    grid.SelectedObject,
                    VisionPipelineOverlayLabelMode.NameWithCoordinates);
                descriptors["LineWidth"]!.SetValue(grid.SelectedObject, 4);
                descriptors["PointSize"]!.SetValue(grid.SelectedObject, 6);
                descriptors["LabelBackground"]!.SetValue(grid.SelectedObject, true);
                descriptors["LabelMargin"]!.SetValue(grid.SelectedObject, 3);
                grid.RefreshSelectedObject();
                Pump(60);
                shellHost.RecipeCommands.MarkSelectedStepEditDirty();
                shellHost.RecipeCommands.ApplySelectedStepParametersCommand.Execute(null);
                Pump(220);

                VisionPipeline savedPipeline = VisionPipelineStorage.Load(recipeName, pipeline.Name);
                VisionPipelineStep savedOverlay = savedPipeline.Steps.Single(
                    item => VisionPipelineOverlayMergeService.IsMergeTool(item.ToolType));
                if (!string.Equals(
                        savedOverlay.Parameters.GetValueOrDefault(
                            VisionPipelineOverlayMergeService.RenderPresetParameter),
                        "HighContrast",
                        StringComparison.Ordinal)
                    || !string.Equals(
                        savedOverlay.Parameters.GetValueOrDefault(
                            VisionPipelineOverlayMergeService.LabelModeParameter),
                        "NameWithCoordinates",
                        StringComparison.Ordinal)
                    || !string.Equals(
                        savedOverlay.Parameters.GetValueOrDefault(
                            VisionPipelineOverlayMergeService.LineWidthParameter),
                        "4",
                        StringComparison.Ordinal)
                    || !string.Equals(
                        savedOverlay.Parameters.GetValueOrDefault(
                            VisionPipelineOverlayMergeService.PointSizeParameter),
                        "6",
                        StringComparison.Ordinal)
                    || !string.Equals(
                        savedOverlay.Parameters.GetValueOrDefault(
                            VisionPipelineOverlayMergeService.LabelBackgroundParameter),
                        "True",
                        StringComparison.OrdinalIgnoreCase)
                    || !string.Equals(
                        savedOverlay.Parameters.GetValueOrDefault(
                            VisionPipelineOverlayMergeService.LabelMarginParameter),
                        "3",
                        StringComparison.Ordinal)
                    || !string.Equals(
                        savedOverlay.Parameters.GetValueOrDefault("CVR20_PRESERVE_UNKNOWN"),
                        "retained",
                        StringComparison.Ordinal))
                {
                    throw new InvalidOperationException(
                        "CVR-20 display settings or an unrepresented parameter were lost on apply/save/reload. "
                        + string.Join(
                            ", ",
                            new[]
                            {
                                VisionPipelineOverlayMergeService.RenderPresetParameter,
                                VisionPipelineOverlayMergeService.LabelModeParameter,
                                VisionPipelineOverlayMergeService.LineWidthParameter,
                                VisionPipelineOverlayMergeService.PointSizeParameter,
                                VisionPipelineOverlayMergeService.LabelBackgroundParameter,
                                VisionPipelineOverlayMergeService.LabelMarginParameter,
                                "CVR20_PRESERVE_UNKNOWN"
                            }.Select(key => key + "=" + savedOverlay.Parameters.GetValueOrDefault(key, "<missing>"))));
                }

                if (!shellHost.RecipeCommands.ResetSelectedStepDisplayDefaultsCommand.CanExecute(null))
                {
                    throw new InvalidOperationException("CVR-20 explicit display-default reset command was disabled.");
                }

                shellHost.RecipeCommands.ResetSelectedStepDisplayDefaultsCommand.Execute(null);
                Pump(80);
                object resetObject = shellHost.RecipeCommands.SelectedStepEditObject;
                PropertyDescriptorCollection resetDescriptors = TypeDescriptor.GetProperties(resetObject);
                if ((VisionPipelineOverlayRenderPreset)resetDescriptors["RenderPreset"]!.GetValue(resetObject)!
                        != VisionPipelineOverlayRenderPreset.LegacyDefault
                    || (VisionPipelineOverlayLabelMode)resetDescriptors["LabelMode"]!.GetValue(resetObject)!
                        != VisionPipelineOverlayLabelMode.None
                    || (int)resetDescriptors["LineWidth"]!.GetValue(resetObject)!
                        != VisionPipelineOverlayMergeService.DefaultLineWidth
                    || (int)resetDescriptors["PointSize"]!.GetValue(resetObject)!
                        != VisionPipelineOverlayMergeService.DefaultPointSize
                    || (bool)resetDescriptors["LabelBackground"]!.GetValue(resetObject)!
                    || (int)resetDescriptors["LabelMargin"]!.GetValue(resetObject)!
                        != VisionPipelineOverlayMergeService.DefaultLabelMargin
                    || !shellHost.RecipeCommands.IsSelectedStepEditDirty)
                {
                    throw new InvalidOperationException(
                        "CVR-20 display-default reset did not restore the documented defaults.");
                }

                shellHost.RecipeCommands.ApplySelectedStepParametersCommand.Execute(null);
                Pump(220);
                VisionPipeline resetPipeline = VisionPipelineStorage.Load(recipeName, pipeline.Name);
                VisionPipelineStep resetOverlay = resetPipeline.Steps.Single(
                    item => VisionPipelineOverlayMergeService.IsMergeTool(item.ToolType));
                if (!string.Equals(
                        resetOverlay.Parameters.GetValueOrDefault(
                            VisionPipelineOverlayMergeService.RenderPresetParameter),
                        "LegacyDefault",
                        StringComparison.Ordinal)
                    || !string.Equals(
                        resetOverlay.Parameters.GetValueOrDefault(
                            VisionPipelineOverlayMergeService.LabelModeParameter),
                        "None",
                        StringComparison.Ordinal)
                    || !string.Equals(
                        resetOverlay.Parameters.GetValueOrDefault("DrawLabels"),
                        "False",
                        StringComparison.OrdinalIgnoreCase))
                {
                    throw new InvalidOperationException(
                        "CVR-20 reset defaults were not persisted through save/reload.");
                }

                object finalObject = shellHost.RecipeCommands.SelectedStepEditObject;
                PropertyDescriptorCollection finalDescriptors = TypeDescriptor.GetProperties(finalObject);
                finalDescriptors["RenderPreset"]!.SetValue(
                    finalObject,
                    VisionPipelineOverlayRenderPreset.HighContrast);
                finalDescriptors["LabelMode"]!.SetValue(
                    finalObject,
                    VisionPipelineOverlayLabelMode.NameWithCoordinates);
                finalDescriptors["LineWidth"]!.SetValue(finalObject, 4);
                finalDescriptors["PointSize"]!.SetValue(finalObject, 6);
                finalDescriptors["LabelBackground"]!.SetValue(finalObject, true);
                finalDescriptors["LabelMargin"]!.SetValue(finalObject, 3);
                grid.RefreshSelectedObject();
                Pump(60);
                shellHost.RecipeCommands.MarkSelectedStepEditDirty();
                shellHost.RecipeCommands.ApplySelectedStepParametersCommand.Execute(null);
                Pump(220);

                object reopenedObject = shellHost.RecipeCommands.SelectedStepEditObject;
                PropertyDescriptorCollection reopenedDescriptors = TypeDescriptor.GetProperties(reopenedObject);
                if ((VisionPipelineOverlayRenderPreset)reopenedDescriptors["RenderPreset"]!.GetValue(reopenedObject)!
                        != VisionPipelineOverlayRenderPreset.HighContrast
                    || (VisionPipelineOverlayLabelMode)reopenedDescriptors["LabelMode"]!.GetValue(reopenedObject)!
                        != VisionPipelineOverlayLabelMode.NameWithCoordinates
                    || (int)reopenedDescriptors["LineWidth"]!.GetValue(reopenedObject)! != 4
                    || (int)reopenedDescriptors["PointSize"]!.GetValue(reopenedObject)! != 6
                    || !(bool)reopenedDescriptors["LabelBackground"]!.GetValue(reopenedObject)!
                    || (int)reopenedDescriptors["LabelMargin"]!.GetValue(reopenedObject)! != 3
                    || shellHost.NativePreviewRunCount != previewRunsBefore
                    || shellHost.LayerDocumentCount != layerCountBefore
                    || !string.Equals(shellHost.ActiveHostLayerTitle, activeLayerBefore, StringComparison.Ordinal)
                    || !string.Equals(shellHost.ActiveNativeRouteInputLayerNameForTest, inputRouteBefore, StringComparison.Ordinal)
                    || !string.Equals(shellHost.ActiveNativeRouteOutputLayerNameForTest, outputRouteBefore, StringComparison.Ordinal))
                {
                    throw new InvalidOperationException(
                        "CVR-20 restoration changed Preview/Run, layers, active layer, routing, or persisted display values.");
                }

                System.Windows.Controls.WpfPropertyGrid.PropertyGrid reopenedGrid =
                    FindVisualChildren<System.Windows.Controls.WpfPropertyGrid.PropertyGrid>(propertyGridHost)
                        .FirstOrDefault(item => item.IsVisible && item.SelectedObject != null)
                    ?? throw new InvalidOperationException("CVR-20 reopened PropertyGrid was not visible.");
                TextBox searchTextBox = GetActivePropertyGridSearchTextBox(
                    reopenedGrid,
                    "CVR-20 OverlayMerge recipe step");
                searchTextBox.Text = "Label";
                searchTextBox.GetBindingExpression(TextBox.TextProperty)?.UpdateSource();
                reopenedGrid.UpdateLayout();
                Pump(80);
                ScrollViewer pipelineScrollViewer = FindNamedVisualChild<ScrollViewer>(
                    shellHost,
                    "recipePipelineTabScrollViewer")
                    ?? throw new InvalidOperationException("CVR-20 Pipeline scroll viewer was not found.");
                pipelineScrollViewer.ScrollToBottom();
                pipelineScrollViewer.UpdateLayout();
                Pump(80);
                BringPropertyGridPropertyIntoView(
                    reopenedGrid,
                    "LabelMode",
                    "CVR-20 OverlayMerge recipe step",
                    0D);
            }, captureFloatingToolWindow: false, captureScreen: true);
        }
        finally
        {
            RecipeWorkspaceService.DeleteVisionWorkspace(recipeName);
        }
    }

    private static OpenVisionLanguage? ResolveManualCaptureLanguage(string[] args)
    {
        if (args.Length >= 2 &&
            string.Equals(args[0], "--target", StringComparison.OrdinalIgnoreCase) &&
            ScreenshotSmokeTargetRunner.SplitNames(args[1]).Any(name => name.StartsWith("manual_en_", StringComparison.OrdinalIgnoreCase)))
        {
            return OpenVisionLanguage.English;
        }

        return null;
    }

    private static void VerifyCvr20OverlayRenderingContract(string outputPath)
    {
        string evidenceDirectory = Path.Combine(
            Path.GetDirectoryName(outputPath) ?? Environment.CurrentDirectory,
            "runtime");
        Directory.CreateDirectory(evidenceDirectory);
        using CvMat input = new CvMat(
            240,
            360,
            OpenCvSharp.MatType.CV_8UC3,
            new OpenCvSharp.Scalar(35, 35, 35));
        Cv.Rectangle(
            input,
            new OpenCvSharp.Rect(30, 30, 300, 180),
            new OpenCvSharp.Scalar(80, 80, 80),
            -1);

        VisionPipelineStep sourceStep = new VisionPipelineStep
        {
            Name = "Detected objects",
            ToolType = "Blob",
            InputLayer = "Main",
            OutputLayer = "Blob_Result"
        };
        VisionToolOverlay[] overlays =
        {
            new VisionToolOverlay
            {
                Kind = VisionToolOverlayKind.Rectangle,
                Label = "Object A",
                Bounds = new System.Drawing.RectangleF(70, 55, 100, 80),
                Center = new System.Drawing.PointF(120, 95)
            },
            new VisionToolOverlay
            {
                Kind = VisionToolOverlayKind.Line,
                Label = "Datum",
                Start = new System.Drawing.PointF(45, 175),
                End = new System.Drawing.PointF(310, 175),
                Center = new System.Drawing.PointF(177.5F, 175)
            },
            new VisionToolOverlay
            {
                Kind = VisionToolOverlayKind.Point,
                Label = "Center",
                Center = new System.Drawing.PointF(240, 100)
            }
        };
        VisionToolResult sourceToolResult = VisionToolResult.Passed(
            input.Clone(),
            TimeSpan.Zero,
            new Dictionary<string, double> { [VisionPipelineKnownMetrics.ResultCount] = overlays.Length },
            overlays);
        VisionPipelineRunResult priorRun = new VisionPipelineRunResult();
        priorRun.StepResults.Add(new VisionPipelineStepResult
        {
            Step = sourceStep,
            ToolResult = sourceToolResult,
            AcceptancePassed = true
        });

        VisionPipelineStep legacyStep = CreateCvr20OverlayStep("Legacy");
        legacyStep.Parameters["DrawLabels"] = "true";
        VisionPipelineStep explicitLegacyStep = CreateCvr20OverlayStep("Explicit legacy");
        explicitLegacyStep.Parameters["DrawLabels"] = "true";
        explicitLegacyStep.Parameters[VisionPipelineOverlayMergeService.RenderPresetParameter] =
            VisionPipelineOverlayRenderPreset.LegacyDefault.ToString();
        explicitLegacyStep.Parameters[VisionPipelineOverlayMergeService.LabelModeParameter] =
            VisionPipelineOverlayLabelMode.Name.ToString();
        explicitLegacyStep.Parameters[VisionPipelineOverlayMergeService.LineWidthParameter] =
            VisionPipelineOverlayMergeService.DefaultLineWidth.ToString(CultureInfo.InvariantCulture);
        explicitLegacyStep.Parameters[VisionPipelineOverlayMergeService.PointSizeParameter] =
            VisionPipelineOverlayMergeService.DefaultPointSize.ToString(CultureInfo.InvariantCulture);
        explicitLegacyStep.Parameters[VisionPipelineOverlayMergeService.LabelBackgroundParameter] = "false";
        explicitLegacyStep.Parameters[VisionPipelineOverlayMergeService.LabelMarginParameter] =
            VisionPipelineOverlayMergeService.DefaultLabelMargin.ToString(CultureInfo.InvariantCulture);
        VisionPipelineStep highContrastStep = CreateCvr20OverlayStep("High contrast");
        highContrastStep.Parameters[VisionPipelineOverlayMergeService.RenderPresetParameter] =
            VisionPipelineOverlayRenderPreset.HighContrast.ToString();
        highContrastStep.Parameters[VisionPipelineOverlayMergeService.LabelModeParameter] =
            VisionPipelineOverlayLabelMode.NameWithCoordinates.ToString();
        highContrastStep.Parameters[VisionPipelineOverlayMergeService.LineWidthParameter] = "4";
        highContrastStep.Parameters[VisionPipelineOverlayMergeService.PointSizeParameter] = "6";
        highContrastStep.Parameters[VisionPipelineOverlayMergeService.LabelBackgroundParameter] = "true";
        highContrastStep.Parameters[VisionPipelineOverlayMergeService.LabelMarginParameter] = "3";
        VisionPipelineStep colorBlindStep = CreateCvr20OverlayStep("Color blind safe");
        colorBlindStep.Parameters[VisionPipelineOverlayMergeService.RenderPresetParameter] =
            VisionPipelineOverlayRenderPreset.ColorBlindSafe.ToString();
        colorBlindStep.Parameters[VisionPipelineOverlayMergeService.LabelModeParameter] =
            VisionPipelineOverlayLabelMode.Name.ToString();

        VisionToolResult legacy = VisionPipelineOverlayMergeService.Execute(legacyStep, input, priorRun);
        VisionToolResult explicitLegacy = VisionPipelineOverlayMergeService.Execute(explicitLegacyStep, input, priorRun);
        VisionToolResult highContrast = VisionPipelineOverlayMergeService.Execute(highContrastStep, input, priorRun);
        VisionToolResult colorBlind = VisionPipelineOverlayMergeService.Execute(colorBlindStep, input, priorRun);
        try
        {
            if (!legacy.Success || !explicitLegacy.Success || !highContrast.Success || !colorBlind.Success)
            {
                throw new InvalidOperationException("CVR-20 runtime rendering case failed unexpectedly.");
            }

            double legacyDelta = Cv.Norm(
                legacy.ResultImage,
                explicitLegacy.ResultImage,
                OpenCvSharp.NormTypes.L1);
            double displayDelta = Cv.Norm(
                legacy.ResultImage,
                highContrast.ResultImage,
                OpenCvSharp.NormTypes.L1);
            if (legacyDelta != 0D || displayDelta <= 0D)
            {
                throw new InvalidOperationException(
                    $"CVR-20 legacy compatibility/display delta failed. Legacy={legacyDelta}, Display={displayDelta}");
            }

            string[] metricNames =
            {
                VisionPipelineKnownMetrics.ResultCount,
                VisionPipelineKnownMetrics.MergeOverlayCount,
                VisionPipelineKnownMetrics.MergeSourceCount
            };
            foreach (string metricName in metricNames)
            {
                double expected = legacy.Metrics[metricName];
                if (explicitLegacy.Metrics[metricName] != expected
                    || highContrast.Metrics[metricName] != expected
                    || colorBlind.Metrics[metricName] != expected)
                {
                    throw new InvalidOperationException(
                        "CVR-20 display-only settings changed metric " + metricName + ".");
                }
            }

            bool[] acceptance =
            {
                VisionPipelineAcceptanceEvaluator.Evaluate(legacyStep, legacy).Passed,
                VisionPipelineAcceptanceEvaluator.Evaluate(explicitLegacyStep, explicitLegacy).Passed,
                VisionPipelineAcceptanceEvaluator.Evaluate(highContrastStep, highContrast).Passed,
                VisionPipelineAcceptanceEvaluator.Evaluate(colorBlindStep, colorBlind).Passed
            };
            if (acceptance.Any(value => !value)
                || new[] { legacy, explicitLegacy, highContrast, colorBlind }
                    .Any(result => result.Overlays.Count != overlays.Length))
            {
                throw new InvalidOperationException(
                    "CVR-20 display-only settings changed acceptance or overlay evidence.");
            }

            Cv.ImWrite(Path.Combine(evidenceDirectory, "legacy.png"), legacy.ResultImage);
            Cv.ImWrite(Path.Combine(evidenceDirectory, "high_contrast_coordinates.png"), highContrast.ResultImage);
            Cv.ImWrite(Path.Combine(evidenceDirectory, "color_blind_safe.png"), colorBlind.ResultImage);

            string reportRecipeName =
                "Smoke_Cvr20Runtime_" + Guid.NewGuid().ToString("N").Substring(0, 12);
            try
            {
                VisionPipeline reportPipeline = new VisionPipeline { Name = "CVR20_Rendering_Evidence" };
                reportPipeline.Steps.Add(sourceStep);
                reportPipeline.Steps.Add(highContrastStep);
                VisionPipelineRunResult reportRun = new VisionPipelineRunResult();
                reportRun.StepResults.Add(new VisionPipelineStepResult
                {
                    Step = sourceStep,
                    ToolResult = sourceToolResult,
                    AcceptancePassed = true
                });
                reportRun.StepResults.Add(new VisionPipelineStepResult
                {
                    Step = highContrastStep,
                    ToolResult = highContrast,
                    AcceptancePassed = true
                });
                DateTime reportStartedAt = DateTime.UtcNow;
                string reportPath = VisionPipelineRunReportStorage.Save(
                    reportRecipeName,
                    reportPipeline,
                    reportRun,
                    reportStartedAt,
                    reportStartedAt.AddMilliseconds(1),
                    false,
                    "CVR20");
                VisionPipelineRunReport storedReport =
                    VisionPipelineRunReportStorage.Load(reportPath)
                    ?? throw new InvalidOperationException(
                        "CVR-20 saved Run Report could not be reloaded.");
                VisionPipelineStepRunReport storedOverlay =
                    storedReport.Steps.Single(step => VisionPipelineOverlayMergeService.IsMergeTool(step.ToolType));
                Dictionary<string, string> storedParameters = storedOverlay.Parameters
                    .ToDictionary(parameter => parameter.Key, parameter => parameter.Value, StringComparer.OrdinalIgnoreCase);
                if (!string.Equals(
                        storedParameters.GetValueOrDefault(
                            VisionPipelineOverlayMergeService.RenderPresetParameter),
                        VisionPipelineOverlayRenderPreset.HighContrast.ToString(),
                        StringComparison.Ordinal)
                    || !string.Equals(
                        storedParameters.GetValueOrDefault(
                            VisionPipelineOverlayMergeService.LabelModeParameter),
                        VisionPipelineOverlayLabelMode.NameWithCoordinates.ToString(),
                        StringComparison.Ordinal)
                    || !string.Equals(
                        storedParameters.GetValueOrDefault(
                            VisionPipelineOverlayMergeService.LineWidthParameter),
                        "4",
                        StringComparison.Ordinal))
                {
                    throw new InvalidOperationException(
                        "CVR-20 Run Report did not retain rendering parameters.");
                }

                File.Copy(
                    reportPath,
                    Path.Combine(evidenceDirectory, "run_report.xml"),
                    true);
                File.Copy(
                    Path.Combine(
                        Path.GetDirectoryName(reportPath) ?? string.Empty,
                        storedReport.PipelineSnapshotFile),
                    Path.Combine(evidenceDirectory, "pipeline_snapshot.xml"),
                    true);
            }
            finally
            {
                RecipeWorkspaceService.DeleteVisionWorkspace(reportRecipeName);
            }

            VisionPipeline invalidPipeline = new VisionPipeline { Name = "Invalid overlay rendering" };
            invalidPipeline.Steps.Add(sourceStep);
            VisionPipelineStep invalidOverlay = CreateCvr20OverlayStep("Invalid width");
            invalidOverlay.Parameters[VisionPipelineOverlayMergeService.LineWidthParameter] = "9";
            invalidPipeline.Steps.Add(invalidOverlay);
            VisionPipelineValidationResult invalidValidation =
                VisionPipelineValidator.Validate(invalidPipeline, new[] { "Main" });
            if (invalidValidation.Success
                || !invalidValidation.Errors.Any(error => error.Contains(
                    VisionPipelineOverlayMergeService.LineWidthParameter,
                    StringComparison.Ordinal)))
            {
                throw new InvalidOperationException(
                    "CVR-20 invalid rendering bound did not fail closed.");
            }

            File.WriteAllLines(
                Path.Combine(evidenceDirectory, "overlay_rendering_contract.txt"),
                new[]
                {
                    "LegacyMissingKeysPixelDelta=" + legacyDelta.ToString(CultureInfo.InvariantCulture),
                    "HighContrastPixelDelta=" + displayDelta.ToString(CultureInfo.InvariantCulture),
                    "MetricsUnchanged=true",
                    "AcceptanceUnchanged=true",
                    "OverlayEvidenceUnchanged=true",
                    "RunReportRenderingParametersRetained=true",
                    "InvalidLineWidthRejected=true"
                });
        }
        finally
        {
            legacy.ResultImage?.Dispose();
            explicitLegacy.ResultImage?.Dispose();
            highContrast.ResultImage?.Dispose();
            colorBlind.ResultImage?.Dispose();
            sourceToolResult.ResultImage?.Dispose();
        }
    }

    private static VisionPipelineStep CreateCvr20OverlayStep(string name)
    {
        VisionPipelineStep step = new VisionPipelineStep
        {
            Name = name,
            ToolType = "OverlayMerge",
            InputLayer = "Main",
            OutputLayer = name.Replace(" ", "_") + "_Result",
            UseAcceptance = true,
            ExpectedSuccess = true,
            AcceptanceMetricName = VisionPipelineKnownMetrics.MergeOverlayCount,
            UseAcceptanceMetricMinimum = true,
            AcceptanceMetricMinimum = 3,
            UseAcceptanceMetricMaximum = true,
            AcceptanceMetricMaximum = 3
        };
        step.Parameters["SourceSteps"] = "Detected objects";
        step.Parameters["BurnIn"] = "true";
        return step;
    }

    private static void CaptureRecipeFixturePropertyStep(
        OpenVisionShellHostView shellHost,
        OpenVisionRecipePipelineStepPreview step,
        string outputPath,
        string fileName)
    {
        shellHost.RecipeCommands.SelectedPipelinePreviewStep = step;
        Pump(40);
        if (!shellHost.RecipeCommands.LoadSelectedStepParametersCommand.CanExecute(null))
        {
            throw new InvalidOperationException("Fixture PropertyGrid parameter load command was disabled for " + step.DisplayText);
        }

        shellHost.RecipeCommands.LoadSelectedStepParametersCommand.Execute(null);
        Pump(180);
        FrameworkElement propertyGridHost = FindVisualChildren<FrameworkElement>(shellHost)
            .FirstOrDefault(item => item.IsVisible && string.Equals(
                System.Windows.Automation.AutomationProperties.GetAutomationId(item),
                "HostRecipeSelectedStepPropertyGridHost",
                StringComparison.Ordinal))
            ?? throw new InvalidOperationException("Fixture PropertyGrid host was not visible for " + step.DisplayText);
        propertyGridHost.BringIntoView();
        propertyGridHost.UpdateLayout();
        Pump(80);

        System.Windows.Controls.WpfPropertyGrid.PropertyGrid grid = FindVisualChildren<System.Windows.Controls.WpfPropertyGrid.PropertyGrid>(propertyGridHost)
            .FirstOrDefault(item => item.IsVisible && item.SelectedObject != null)
            ?? throw new InvalidOperationException("Fixture PropertyGrid did not load for " + step.DisplayText);
        if (grid.ThemeVariant != System.Windows.Controls.WpfPropertyGrid.PropertyGridThemeVariant.Dark)
        {
            throw new InvalidOperationException("Recipe Manager PropertyGrid did not select the dark host theme.");
        }
        TextBox searchTextBox = GetActivePropertyGridSearchTextBox(grid, "Fixture recipe step");
        searchTextBox.Text = "Fixture";
        searchTextBox.GetBindingExpression(TextBox.TextProperty)?.UpdateSource();
        grid.UpdateLayout();
        Pump(40);
        string[] requiredProperties = string.Equals(step.ToolType, "Matching", StringComparison.OrdinalIgnoreCase)
            ? new[]
            {
                "USE_AS_FIXTURE_FRAME",
                "FIXTURE_FRAME_NAME",
                "FIXTURE_REFERENCE_X",
                "FIXTURE_REFERENCE_Y",
                "FIXTURE_REFERENCE_ANGLE",
                "FIXTURE_REFERENCE_SCALE",
                "FIXTURE_MAX_ANGLE_DELTA",
                "FIXTURE_MIN_SCALE_RATIO",
                "FIXTURE_MAX_SCALE_RATIO",
                "FIXTURE_REFERENCE_IMAGE_WIDTH",
                "FIXTURE_REFERENCE_IMAGE_HEIGHT",
                "USE_FIND_SCALE",
                "FIND_SCALE_MIN",
                "FIND_SCALE_MAX",
                "FIND_SCALE_STEP"
            }
            : new[]
            {
                "USE_FIXTURE_FRAME",
                "FIXTURE_FRAME_NAME",
                "FIXTURE_APPLY_MODE",
                "FIXTURE_MIN_VALID_PIXEL_RATIO",
                "ALLOW_BRANCH_INPUT"
            };
        PropertyDescriptorCollection descriptors = TypeDescriptor.GetProperties(grid.SelectedObject);
        string[] missingProperties = requiredProperties
            .Where(propertyName => descriptors.Find(propertyName, true) == null)
            .ToArray();
        if (missingProperties.Length > 0 || grid.IsSearchEmptyMessageVisibleForTest)
        {
            throw new InvalidOperationException(
                "Fixture PropertyGrid did not expose the expected parameters for " + step.DisplayText + ". "
                + "Missing=" + string.Join(",", missingProperties)
                + ", EmptySearch=" + grid.IsSearchEmptyMessageVisibleForTest);
        }

        searchTextBox.Clear();
        searchTextBox.GetBindingExpression(TextBox.TextProperty)?.UpdateSource();
        grid.UpdateLayout();
        Pump(40);

        foreach (string propertyName in requiredProperties)
        {
            OpenVisionLab.PropertyGrid.IPropertyGridProperty? gridProperty = grid.Properties[propertyName];
            if (gridProperty == null || !gridProperty.IsBrowsable)
            {
                throw new InvalidOperationException(
                    "Fixture PropertyGrid property was not browsable for "
                    + step.DisplayText
                    + ". Property="
                    + propertyName
                    + ", Found="
                    + (gridProperty != null).ToString(CultureInfo.InvariantCulture)
                    + ", Browsable="
                    + (gridProperty?.IsBrowsable ?? false).ToString(CultureInfo.InvariantCulture));
            }

            BringPropertyGridPropertyIntoView(grid, propertyName, step.DisplayText, 0D);
        }

        bool matchingStep = string.Equals(step.ToolType, "Matching", StringComparison.OrdinalIgnoreCase);
        string captureProperty = matchingStep ? "FIXTURE_MIN_SCALE_RATIO" : requiredProperties[0];
        double captureAdvance = matchingStep ? 20D : 120D;
        BringPropertyGridPropertyIntoView(grid, captureProperty, step.DisplayText, captureAdvance);
        SaveCurrentWindowPng(shellHost, outputPath, fileName);
    }

    private static void BringPropertyGridPropertyIntoView(
        System.Windows.Controls.WpfPropertyGrid.PropertyGrid grid,
        string propertyName,
        string stepName,
        double additionalOffset)
    {
        ScrollViewer scrollViewer = FindPrimaryPropertyGridScrollViewer(grid)
            ?? throw new InvalidOperationException("Fixture PropertyGrid scroll viewer was not available for " + stepName);
        double step = Math.Max(40D, scrollViewer.ViewportHeight * 0.45D);
        double maximum = Math.Max(0D, scrollViewer.ScrollableHeight);
        for (double offset = 0D; offset <= maximum + 1D; offset += step)
        {
            scrollViewer.ScrollToVerticalOffset(Math.Min(offset, maximum));
            grid.UpdateLayout();
            Pump(12);
            FrameworkElement? propertyElement = FindVisualChildren<FrameworkElement>(grid)
                .FirstOrDefault(item => item.IsVisible && string.Equals(
                    ResolvePropertyGridPropertyName(item.DataContext),
                    propertyName,
                    StringComparison.OrdinalIgnoreCase));
            if (propertyElement == null)
            {
                continue;
            }

            propertyElement.BringIntoView();
            grid.UpdateLayout();
            Pump(20);
            scrollViewer.ScrollToVerticalOffset(Math.Min(scrollViewer.VerticalOffset + Math.Max(0D, additionalOffset), maximum));
            grid.UpdateLayout();
            Pump(20);
            return;
        }

        throw new InvalidOperationException(
            "Fixture PropertyGrid could not bring property '" + propertyName + "' into view for " + stepName + ".");
    }

    private static void AssertFixturePropertyMapperRoundTrip(VisionPipeline pipeline)
    {
        if (pipeline?.Steps == null || pipeline.Steps.Count != 2)
        {
            throw new InvalidOperationException("Fixture PropertyGrid round-trip requires the two-step fixture pipeline.");
        }

        VisionPipelineStep matching = ClonePipelineStep(pipeline.Steps[0]);
        object matchingProperty = VisionPipelineStepPropertyMapper.CreateProperty(matching)
            ?? throw new InvalidOperationException("Matching Fixture property object was not created.");
        AssertPropertyValue(matchingProperty, "USE_AS_FIXTURE_FRAME", true);
        AssertPropertyValue(matchingProperty, "FIXTURE_FRAME_NAME", "PartFrame");
        AssertPropertyValue(matchingProperty, "FIXTURE_REFERENCE_X", 60D);
        AssertPropertyValue(matchingProperty, "FIXTURE_REFERENCE_Y", 70D);
        AssertPropertyValue(matchingProperty, "FIXTURE_REFERENCE_ANGLE", 0D);
        AssertPropertyValue(matchingProperty, "FIXTURE_REFERENCE_SCALE", 1D);
        AssertPropertyValue(matchingProperty, "FIXTURE_MAX_ANGLE_DELTA", 2D);
        AssertPropertyValue(matchingProperty, "FIXTURE_MIN_SCALE_RATIO", 0.8D);
        AssertPropertyValue(matchingProperty, "FIXTURE_MAX_SCALE_RATIO", 1.8D);
        AssertPropertyValue(matchingProperty, "FIXTURE_REFERENCE_IMAGE_WIDTH", 640);
        AssertPropertyValue(matchingProperty, "FIXTURE_REFERENCE_IMAGE_HEIGHT", 480);
        AssertPropertyValue(matchingProperty, "USE_FIND_SCALE", true);
        AssertPropertyValue(matchingProperty, "FIND_SCALE_MIN", 0.75D);
        AssertPropertyValue(matchingProperty, "FIND_SCALE_MAX", 1.35D);
        AssertPropertyValue(matchingProperty, "FIND_SCALE_STEP", 0.05D);
        if (!VisionPipelineStepPropertyMapper.ApplyProperty(matching, matchingProperty))
        {
            throw new InvalidOperationException("Matching Fixture property object did not apply back to the pipeline step.");
        }

        AssertParameterValue(matching, "USE_AS_FIXTURE_FRAME", true);
        AssertParameterValue(matching, "FIXTURE_FRAME_NAME", "PartFrame");
        AssertParameterValue(matching, "FIXTURE_REFERENCE_X", 60D);
        AssertParameterValue(matching, "FIXTURE_REFERENCE_Y", 70D);
        AssertParameterValue(matching, "FIXTURE_REFERENCE_ANGLE", 0D);
        AssertParameterValue(matching, "FIXTURE_REFERENCE_SCALE", 1D);
        AssertParameterValue(matching, "FIXTURE_MAX_ANGLE_DELTA", 2D);
        AssertParameterValue(matching, "FIXTURE_MIN_SCALE_RATIO", 0.8D);
        AssertParameterValue(matching, "FIXTURE_MAX_SCALE_RATIO", 1.8D);
        AssertParameterValue(matching, "FIXTURE_REFERENCE_IMAGE_WIDTH", 640D);
        AssertParameterValue(matching, "FIXTURE_REFERENCE_IMAGE_HEIGHT", 480D);
        AssertParameterValue(matching, "NUM_MATCH", 1D);
        AssertParameterValue(matching, "USE_FIND_SCALE", true);
        AssertParameterValue(matching, "FIND_SCALE_MIN", 0.75D);
        AssertParameterValue(matching, "FIND_SCALE_MAX", 1.35D);
        AssertParameterValue(matching, "FIND_SCALE_STEP", 0.05D);

        VisionPipelineStep matchingAlias = ClonePipelineStep(pipeline.Steps[0]);
        matchingAlias.ToolType = "TemplateMatchingTool";
        object matchingAliasProperty = VisionPipelineStepPropertyMapper.CreateProperty(matchingAlias)
            ?? throw new InvalidOperationException(
                "TemplateMatchingTool alias property object was not created.");
        if (!VisionPipelineStepPropertyMapper.ApplyProperty(
                matchingAlias,
                matchingAliasProperty))
        {
            throw new InvalidOperationException(
                "TemplateMatchingTool alias property object did not apply back.");
        }

        if (!string.Equals(matchingAlias.ToolType, "Matching", StringComparison.Ordinal))
        {
            throw new InvalidOperationException(
                "TemplateMatchingTool alias did not reconstruct canonical Matching. "
                + $"ToolType={matchingAlias.ToolType}");
        }

        AssertParameterValue(matchingAlias, "USE_AS_FIXTURE_FRAME", true);
        AssertParameterValue(matchingAlias, "FIXTURE_FRAME_NAME", "PartFrame");
        AssertParameterValue(matchingAlias, "FIXTURE_REFERENCE_X", 60D);
        AssertParameterValue(matchingAlias, "FIXTURE_REFERENCE_Y", 70D);

        VisionPipelineStep normalize = ClonePipelineStep(pipeline.Steps[1]);
        object normalizeProperty = VisionPipelineStepPropertyMapper.CreateProperty(normalize)
            ?? throw new InvalidOperationException("NormalizeImage Fixture property object was not created.");
        AssertPropertyValue(normalizeProperty, "USE_FIXTURE_FRAME", true);
        AssertPropertyValue(normalizeProperty, "FIXTURE_FRAME_NAME", "PartFrame");
        AssertPropertyValue(normalizeProperty, "FIXTURE_APPLY_MODE", VisionPipelineFixtureApplyMode.NormalizeImage);
        AssertPropertyValue(normalizeProperty, "FIXTURE_MIN_VALID_PIXEL_RATIO", 0.25D);
        AssertPropertyValue(normalizeProperty, "ALLOW_BRANCH_INPUT", true);
        if (!VisionPipelineStepPropertyMapper.ApplyProperty(normalize, normalizeProperty))
        {
            throw new InvalidOperationException("NormalizeImage Fixture property object did not apply back to the pipeline step.");
        }

        AssertParameterValue(normalize, "USE_FIXTURE_FRAME", true);
        AssertParameterValue(normalize, "FIXTURE_FRAME_NAME", "PartFrame");
        AssertParameterValue(normalize, "FIXTURE_APPLY_MODE", "NormalizeImage");
        AssertParameterValue(normalize, "FIXTURE_MIN_VALID_PIXEL_RATIO", 0.25D);
        AssertParameterValue(normalize, "ALLOW_BRANCH_INPUT", true);
        if (!string.Equals(normalize.InputLayer, "Main", StringComparison.Ordinal)
            || !string.Equals(normalize.OutputLayer, "DeviceAligned", StringComparison.Ordinal))
        {
            throw new InvalidOperationException(
                "NormalizeImage Fixture property round-trip changed layer routing. "
                + $"Input={normalize.InputLayer}, Output={normalize.OutputLayer}");
        }
    }

    private static VisionPipelineStep ClonePipelineStep(VisionPipelineStep source)
    {
        VisionPipelineStep clone = new()
        {
            Name = source.Name,
            ToolType = source.ToolType,
            Enabled = source.Enabled,
            InputLayer = source.InputLayer,
            OutputLayer = source.OutputLayer,
            UseAcceptance = source.UseAcceptance,
            ExpectedSuccess = source.ExpectedSuccess,
            MaxElapsedMilliseconds = source.MaxElapsedMilliseconds,
            RequiredMessageText = source.RequiredMessageText,
            AcceptanceMetricName = source.AcceptanceMetricName,
            UseAcceptanceMetricMinimum = source.UseAcceptanceMetricMinimum,
            AcceptanceMetricMinimum = source.AcceptanceMetricMinimum,
            UseAcceptanceMetricMaximum = source.UseAcceptanceMetricMaximum,
            AcceptanceMetricMaximum = source.AcceptanceMetricMaximum
        };
        foreach ((string key, string value) in source.Parameters)
        {
            clone.Parameters[key] = value;
        }

        return clone;
    }

    private static void AssertPropertyValue(object target, string propertyName, object expected)
    {
        PropertyDescriptor descriptor = TypeDescriptor.GetProperties(target).Find(propertyName, true)
            ?? throw new InvalidOperationException("Fixture property object is missing " + propertyName + ".");
        AssertFixtureValue(propertyName, descriptor.GetValue(target), expected);
    }

    private static void AssertParameterValue(VisionPipelineStep step, string parameterName, object expected)
    {
        if (!step.Parameters.TryGetValue(parameterName, out string? actual))
        {
            throw new InvalidOperationException("Fixture round-trip step is missing parameter " + parameterName + ".");
        }

        AssertFixtureValue(parameterName, actual, expected);
    }

    private static void AssertFixtureValue(string name, object? actual, object expected)
    {
        bool matches = expected switch
        {
            bool expectedBool => bool.TryParse(Convert.ToString(actual, CultureInfo.InvariantCulture), out bool actualBool)
                && actualBool == expectedBool,
            double expectedDouble => double.TryParse(
                    Convert.ToString(actual, CultureInfo.InvariantCulture),
                    NumberStyles.Float,
                    CultureInfo.InvariantCulture,
                    out double actualDouble)
                && Math.Abs(actualDouble - expectedDouble) < 0.0001D,
            _ => string.Equals(
                Convert.ToString(actual, CultureInfo.InvariantCulture),
                Convert.ToString(expected, CultureInfo.InvariantCulture),
                StringComparison.Ordinal)
        };
        if (!matches)
        {
            throw new InvalidOperationException(
                "Fixture value mismatch for " + name + ". "
                + $"Expected='{expected}', Actual='{actual}'");
        }
    }

    private static void SaveCurrentWindowPng(FrameworkElement content, string outputPath, string fileName)
    {
        Window window = Window.GetWindow(content)
            ?? throw new InvalidOperationException("Fixture PropertyGrid capture window was not available.");
        window.Activate();
        window.UpdateLayout();
        Pump(80);
        string parentDirectory = Path.GetDirectoryName(outputPath) ?? ".";
        string outputName = Path.GetFileNameWithoutExtension(outputPath);
        string diagnosticsDirectory = Path.Combine(parentDirectory, outputName + ".diagnostics");
        Directory.CreateDirectory(diagnosticsDirectory);
        string diagnosticPath = Path.Combine(diagnosticsDirectory, fileName);
        ScreenshotPngWriter.WriteScreenPng(window, diagnosticPath);
    }

    private static void SaveRecipeToolSettings<TSettings>(string recipeName, string toolName, TSettings settings)
        where TSettings : class
    {
        string configName = OpenVisionNativeToolSettingsStore.CreateConfigName(toolName);
        string path = RecipeWorkspaceService.GetVisionConfigPath(recipeName, configName);
        SerializeHelper.SaveXmlFile(path, settings);
    }

    private static CaptureResult CaptureShellHostRecipeReviewBundle(string outputPath)
    {
        OpenVisionLanguageService.SetLanguage(OpenVisionLanguage.Korean, false);
        string recipeName = "Smoke_RecipeReviewBundle_" + Guid.NewGuid().ToString("N");
        string pipelineName = "Matching_Review_Bundle";
        string dependencyPath = Path.Combine(
            Path.GetTempPath(),
            "OpenVisionLab_review_dependency_" + Guid.NewGuid().ToString("N") + ".png");
        string bundlePath = Path.Combine(
            Path.GetTempPath(),
            "OpenVisionLab_recipe_review_" + Guid.NewGuid().ToString("N") + ".review.zip");

        using (Bitmap dependencyImage = CreateDockingPanelSmokeBitmap(41))
        {
            dependencyImage.Save(dependencyPath, ImageFormat.Png);
        }

        VisionPipeline pipeline = RecipeContextFixture.CreatePipeline(pipelineName, 1);
        VisionPipelineStep step = pipeline.Steps[0];
        step.Name = "01 Match Review Target";
        step.ToolType = "Matching";
        step.Enabled = true;
        step.Parameters["TemplatePath"] = dependencyPath;
        step.Parameters["SCORE_MIN"] = "0.80";
        step.Parameters["NUM_MATCH"] = "1";
        step.UseAcceptance = true;
        step.ExpectedSuccess = true;
        step.AcceptanceMetricName = "ScoreMax";
        step.UseAcceptanceMetricMinimum = true;
        step.AcceptanceMetricMinimum = 0.80;
        step.MaxElapsedMilliseconds = 500;
        VisionPipelineStorage.Save(recipeName, pipeline);
        VisionPipelineStorage.SaveActivePipelineName(recipeName, pipelineName);

        OpenVisionShellHostView shellHost = CreateShellHost(recipeName, seedMainLayer: false);
        try
        {
            return CaptureWindowWithContent(shellHost, outputPath, 1600, 900, () =>
            {
                OpenVisionRecipeSampleOption? selectedSample = shellHost.RecipeCommands.SampleOptions
                    .FirstOrDefault(option => option?.Sample?.CanOpen == true);
                if (selectedSample != null)
                {
                    shellHost.RecipeCommands.SelectedSampleOption = selectedSample;
                }

                int previewRunsBefore = shellHost.NativePreviewRunCount;
                int layerCountBefore = shellHost.LayerDocumentCount;
                string workspaceLayerBefore = shellHost.WorkspaceLayerTitle;
                string inputRouteBefore = shellHost.ActiveNativeRouteInputLayerNameForTest;
                string outputRouteBefore = shellHost.ActiveNativeRouteOutputLayerNameForTest;
                if (!shellHost.RecipeCommands.ExportRecipeReviewBundleCommand.CanExecute(null)
                    || !shellHost.RecipeCommands.ExportActivePipelineReviewBundleToPath(bundlePath)
                    || !File.Exists(bundlePath))
                {
                    throw new InvalidOperationException(
                        "Recipe review bundle export did not create the requested package. "
                        + $"Path='{bundlePath}', Status='{shellHost.RecipeCommands.StatusText}'");
                }

                using (ZipArchive archive = ZipFile.OpenRead(bundlePath))
                {
                    if (archive.Entries.Count != 2)
                    {
                        throw new InvalidOperationException(
                            "Recipe review bundle must contain only pipeline XML and manifest in the first slice. "
                            + $"Entries='{string.Join(", ", archive.Entries.Select(entry => entry.FullName))}'");
                    }

                    ZipArchiveEntry? pipelineEntry = archive.GetEntry(OpenVisionRecipeReviewBundleExporter.PipelineEntryName);
                    ZipArchiveEntry? manifestEntry = archive.GetEntry(OpenVisionRecipeReviewBundleExporter.ManifestEntryName);
                    if (pipelineEntry == null || manifestEntry == null)
                    {
                        throw new InvalidOperationException("Recipe review bundle entries were missing.");
                    }

                    byte[] pipelineBytes;
                    using (Stream entryStream = pipelineEntry.Open())
                    using (MemoryStream buffer = new MemoryStream())
                    {
                        entryStream.CopyTo(buffer);
                        pipelineBytes = buffer.ToArray();
                    }

                    using Stream manifestStream = manifestEntry.Open();
                    using JsonDocument manifest = JsonDocument.Parse(manifestStream);
                    JsonElement root = manifest.RootElement;
                    JsonElement dependency = root.GetProperty("dependencies").EnumerateArray().Single();
                    JsonElement packagePolicy = root.GetProperty("packagePolicy");
                    string expectedPipelineHash = Convert.ToHexString(SHA256.HashData(pipelineBytes)).ToLowerInvariant();
                    string expectedDependencyHash;
                    using (FileStream dependencyStream = File.OpenRead(dependencyPath))
                    using (SHA256 sha256 = SHA256.Create())
                    {
                        expectedDependencyHash = Convert.ToHexString(sha256.ComputeHash(dependencyStream)).ToLowerInvariant();
                    }

                    bool hasMatchingTool = root.GetProperty("toolTypes")
                        .EnumerateArray()
                        .Any(item => string.Equals(item.GetProperty("toolType").GetString(), "Matching", StringComparison.OrdinalIgnoreCase));
                    bool hasScoreAcceptance = root.GetProperty("acceptanceMetrics")
                        .EnumerateArray()
                        .Any(item => string.Equals(item.GetProperty("metricName").GetString(), "ScoreMax", StringComparison.OrdinalIgnoreCase));
                    if (!string.Equals(root.GetProperty("format").GetString(), "OpenVisionLab.RecipeReviewBundle", StringComparison.Ordinal)
                        || root.GetProperty("schemaVersion").GetInt32() != 1
                        || !string.Equals(root.GetProperty("recipeName").GetString(), recipeName, StringComparison.Ordinal)
                        || !string.Equals(root.GetProperty("pipelineName").GetString(), pipelineName, StringComparison.Ordinal)
                        || !string.Equals(root.GetProperty("validation").GetProperty("status").GetString(), "OK", StringComparison.Ordinal)
                        || !string.Equals(root.GetProperty("pipelineXml").GetProperty("sha256").GetString(), expectedPipelineHash, StringComparison.Ordinal)
                        || !hasMatchingTool
                        || !hasScoreAcceptance
                        || !dependency.GetProperty("exists").GetBoolean()
                        || !string.Equals(dependency.GetProperty("pathKind").GetString(), "Absolute", StringComparison.Ordinal)
                        || dependency.GetProperty("sizeBytes").GetInt64() != new FileInfo(dependencyPath).Length
                        || !string.Equals(dependency.GetProperty("sha256").GetString(), expectedDependencyHash, StringComparison.Ordinal)
                        || packagePolicy.GetProperty("referencedFilesCopied").GetBoolean()
                        || packagePolicy.GetProperty("importExecuted").GetBoolean()
                        || packagePolicy.GetProperty("previewOrRunExecuted").GetBoolean())
                    {
                        throw new InvalidOperationException("Recipe review manifest did not preserve validation, tool, metric, dependency, hash, and no-execution contracts.");
                    }
                }

                if (shellHost.NativePreviewRunCount != previewRunsBefore
                    || shellHost.LayerDocumentCount != layerCountBefore
                    || !string.Equals(shellHost.WorkspaceLayerTitle, workspaceLayerBefore, StringComparison.Ordinal)
                    || !string.Equals(shellHost.ActiveNativeRouteInputLayerNameForTest, inputRouteBefore, StringComparison.Ordinal)
                    || !string.Equals(shellHost.ActiveNativeRouteOutputLayerNameForTest, outputRouteBefore, StringComparison.Ordinal)
                    || shellHost.IsActiveWpfToolWindowVisibleForTest
                    || shellHost.IsNativeDocumentActive
                    || shellHost.HasNativePreviewResult)
                {
                    throw new InvalidOperationException("Recipe review bundle export changed runtime, layer, workspace, or route state.");
                }

                ToggleButton? recipeManagerButton = FindNamedVisualChild<ToggleButton>(shellHost, "btnHostRecipeManager");
                if (recipeManagerButton == null)
                {
                    throw new InvalidOperationException("Recipe manager button was not found for review bundle evidence.");
                }

                recipeManagerButton.IsChecked = true;
                Pump(80);
                AssertVisibleAutomationIds(
                    shellHost,
                    "WPF recipe review bundle export",
                    "HostRecipeManagerPanel",
                    "HostRecipeManagerCommandStrip",
                    "HostRecipeExportXmlButton",
                    "HostRecipeExportReviewBundleButton");
            }, captureFloatingToolWindow: false, captureScreen: true);
        }
        finally
        {
            File.Delete(bundlePath);
            File.Delete(dependencyPath);
            RecipeWorkspaceService.DeleteVisionWorkspace(recipeName);
        }
    }

    private static CaptureResult CaptureShellHostRecipeReviewBundleImport(string outputPath)
    {
        OpenVisionLanguageService.SetLanguage(OpenVisionLanguage.Korean, false);
        string recipeName = "Smoke_RecipeReviewBundleImport_" + Guid.NewGuid().ToString("N");
        string pipelineName = "Matching_Review_Import";
        string temporaryRoot = Path.Combine(
            Path.GetTempPath(),
            "OpenVisionLab_review_import_" + Guid.NewGuid().ToString("N"));
        string sourceDirectory = Path.Combine(temporaryRoot, "export-source");
        string dependencyPath = Path.Combine(sourceDirectory, "review-template.png");
        string relocatedDependencyPath = Path.Combine(temporaryRoot, Path.GetFileName(dependencyPath));
        string bundlePath = Path.Combine(temporaryRoot, pipelineName + ".review.zip");
        string tamperedBundlePath = Path.Combine(temporaryRoot, pipelineName + ".tampered.review.zip");
        Directory.CreateDirectory(sourceDirectory);

        using (Bitmap dependencyImage = CreateDockingPanelSmokeBitmap(53))
        {
            dependencyImage.Save(dependencyPath, ImageFormat.Png);
        }

        VisionPipeline pipeline = RecipeContextFixture.CreatePipeline(pipelineName, 1);
        VisionPipelineStep step = pipeline.Steps[0];
        step.Name = "01 Review Bundle Match";
        step.ToolType = "Matching";
        step.Enabled = true;
        step.InputLayer = "Main";
        step.OutputLayer = "ReviewMatch";
        step.Parameters["TemplatePath"] = dependencyPath;
        step.Parameters["SCORE_MIN"] = "0.80";
        step.Parameters["NUM_MATCH"] = "1";
        step.UseAcceptance = true;
        step.ExpectedSuccess = true;
        step.AcceptanceMetricName = "ScoreMax";
        step.UseAcceptanceMetricMinimum = true;
        step.AcceptanceMetricMinimum = 0.80;
        step.MaxElapsedMilliseconds = 500;
        VisionPipelineStorage.Save(recipeName, pipeline);
        VisionPipelineStorage.SaveActivePipelineName(recipeName, pipelineName);

        OpenVisionShellHostView shellHost = CreateShellHost(recipeName, seedMainLayer: false);
        try
        {
            return CaptureWindowWithContent(shellHost, outputPath, 1600, 900, () =>
            {
                if (!shellHost.RecipeCommands.ExportActivePipelineReviewBundleToPath(bundlePath))
                {
                    throw new InvalidOperationException(
                        "Recipe review bundle setup export failed. Status='" + shellHost.RecipeCommands.StatusText + "'.");
                }

                CreateTamperedReviewBundle(bundlePath, tamperedBundlePath);
                if (OpenVisionRecipeReviewBundleInspector.TryInspect(tamperedBundlePath, out OpenVisionRecipeReviewBundleInspection tamperedInspection)
                    || !ContainsAny(tamperedInspection.IntegrityReport, "SHA-256", "무결성"))
                {
                    throw new InvalidOperationException(
                        "Tampered recipe review bundle was not rejected by integrity validation. Report='"
                        + tamperedInspection.IntegrityReport + "'.");
                }

                File.Move(dependencyPath, relocatedDependencyPath);
                if (!OpenVisionRecipeReviewBundleInspector.TryInspect(bundlePath, out OpenVisionRecipeReviewBundleInspection inspection)
                    || !inspection.PathReviews.Any(item =>
                        item.IsDependency
                        && item.State == OpenVisionRecipeReviewBundlePathState.RelocationCandidate
                        && string.Equals(item.ReviewedPath, relocatedDependencyPath, StringComparison.OrdinalIgnoreCase)))
                {
                    throw new InvalidOperationException(
                        "Recipe review bundle did not find the deterministic adjacent relocation candidate. Report='"
                        + inspection.PathReport + "'.");
                }

                int previewRunsBefore = shellHost.NativePreviewRunCount;
                int layerCountBefore = shellHost.LayerDocumentCount;
                int pipelineCountBefore = shellHost.RecipeCommands.PipelineOptions.Count;
                string activePipelineBefore = VisionPipelineStorage.LoadActivePipelineName(recipeName, string.Empty);
                string workspaceLayerBefore = shellHost.WorkspaceLayerTitle;
                string inputRouteBefore = shellHost.ActiveNativeRouteInputLayerNameForTest;
                string outputRouteBefore = shellHost.ActiveNativeRouteOutputLayerNameForTest;
                string templateDirectory = RecipeWorkspaceService.GetTemplateDirectory(recipeName);
                int templateFileCountBefore = Directory.Exists(templateDirectory)
                    ? Directory.GetFiles(templateDirectory, "*", SearchOption.AllDirectories).Length
                    : 0;

                if (!shellHost.RecipeCommands.ImportPipelineXmlFromPath(bundlePath))
                {
                    throw new InvalidOperationException(
                        "Recipe review bundle dry-run did not load into the existing review surface. Status='"
                        + shellHost.RecipeCommands.StatusText + "'.");
                }

                Pump(80);
                TabItem? llmXmlTab = FindNamedVisualChild<TabItem>(shellHost, "tabRecipeLlmXml");
                OpenVisionRecipeDependencyReviewRow? relocationRow = shellHost.RecipeCommands.LlmXmlDraftDependencyRows
                    .FirstOrDefault(item => ContainsAny(item.Status, "재배치", "Relocation"));
                int templateFileCountAfter = Directory.Exists(templateDirectory)
                    ? Directory.GetFiles(templateDirectory, "*", SearchOption.AllDirectories).Length
                    : 0;
                if (llmXmlTab?.IsSelected != true
                    || relocationRow == null
                    || !string.Equals(relocationRow.Path, relocatedDependencyPath, StringComparison.OrdinalIgnoreCase)
                    || !shellHost.RecipeCommands.LlmXmlDraftText.Contains(pipelineName, StringComparison.Ordinal)
                    || !ContainsAny(shellHost.RecipeCommands.LlmXmlDraftValidationReport, "검토 번들 dry-run: OK", "Review bundle dry-run: OK")
                    || !ContainsAny(shellHost.RecipeCommands.LlmXmlDraftDependencyReport, "재배치 후보=1", "relocation candidate=1")
                    || shellHost.RecipeCommands.ImportLlmXmlDraftCommand.CanExecute(null)
                    || !ContainsAny(shellHost.RecipeCommands.StatusText, "가져오기/Preview/Run은 실행하지 않았습니다", "Import, Preview, and Run were not executed"))
                {
                    throw new InvalidOperationException(
                        "Recipe review bundle dry-run did not expose integrity, relocation, and explicit next-action evidence. "
                        + $"TabSelected={llmXmlTab?.IsSelected}, Row='{relocationRow?.Status}/{relocationRow?.Path}', "
                        + $"Status='{shellHost.RecipeCommands.StatusText}', Validation='{shellHost.RecipeCommands.LlmXmlDraftValidationReport}', "
                        + $"Dependencies='{shellHost.RecipeCommands.LlmXmlDraftDependencyReport}'.");
                }

                if (shellHost.RecipeCommands.ValidateLlmXmlDraftTextForTest()
                    || shellHost.NativePreviewRunCount != previewRunsBefore
                    || shellHost.LayerDocumentCount != layerCountBefore
                    || shellHost.RecipeCommands.PipelineOptions.Count != pipelineCountBefore
                    || !string.Equals(VisionPipelineStorage.LoadActivePipelineName(recipeName, string.Empty), activePipelineBefore, StringComparison.Ordinal)
                    || !string.Equals(shellHost.WorkspaceLayerTitle, workspaceLayerBefore, StringComparison.Ordinal)
                    || !string.Equals(shellHost.ActiveNativeRouteInputLayerNameForTest, inputRouteBefore, StringComparison.Ordinal)
                    || !string.Equals(shellHost.ActiveNativeRouteOutputLayerNameForTest, outputRouteBefore, StringComparison.Ordinal)
                    || templateFileCountAfter != templateFileCountBefore
                    || shellHost.IsActiveWpfToolWindowVisibleForTest
                    || shellHost.IsNativeDocumentActive
                    || shellHost.HasNativePreviewResult)
                {
                    throw new InvalidOperationException(
                        "Recipe review bundle dry-run imported, copied, ran, or changed pipeline/layer/routing state. "
                        + $"Runs={previewRunsBefore}->{shellHost.NativePreviewRunCount}, Layers={layerCountBefore}->{shellHost.LayerDocumentCount}, "
                        + $"Pipelines={pipelineCountBefore}->{shellHost.RecipeCommands.PipelineOptions.Count}, "
                        + $"Templates={templateFileCountBefore}->{templateFileCountAfter}.");
                }

                AssertVisibleAutomationIds(
                    shellHost,
                    "WPF recipe review bundle dry-run",
                    "HostRecipeManagerPanel",
                    "HostRecipeLlmXmlTab",
                    "HostRecipeLlmXmlDraftPanel",
                    "HostRecipeLlmDraftValidationReport",
                    "HostRecipeLlmDependencyReport",
                    "HostRecipeLlmDependencyPathList",
                    "HostRecipeImportLlmXmlDraftButton");
            }, captureFloatingToolWindow: false, captureScreen: true);
        }
        finally
        {
            RecipeWorkspaceService.DeleteVisionWorkspace(recipeName);
            if (Directory.Exists(temporaryRoot))
            {
                Directory.Delete(temporaryRoot, recursive: true);
            }
        }
    }

    private static void CreateTamperedReviewBundle(string sourcePath, string targetPath)
    {
        Dictionary<string, byte[]> entries = new Dictionary<string, byte[]>(StringComparer.Ordinal);
        using (ZipArchive source = ZipFile.OpenRead(sourcePath))
        {
            foreach (ZipArchiveEntry entry in source.Entries)
            {
                using Stream entryStream = entry.Open();
                using MemoryStream buffer = new MemoryStream();
                entryStream.CopyTo(buffer);
                entries[entry.FullName] = buffer.ToArray();
            }
        }

        byte[] pipelineBytes = entries[OpenVisionRecipeReviewBundleExporter.PipelineEntryName];
        pipelineBytes[pipelineBytes.Length - 1] ^= 0x01;
        using FileStream stream = new FileStream(targetPath, FileMode.CreateNew, FileAccess.ReadWrite, FileShare.None);
        using ZipArchive target = new ZipArchive(stream, ZipArchiveMode.Create, leaveOpen: false);
        foreach (KeyValuePair<string, byte[]> entry in entries)
        {
            ZipArchiveEntry targetEntry = target.CreateEntry(entry.Key, CompressionLevel.Optimal);
            using Stream targetStream = targetEntry.Open();
            targetStream.Write(entry.Value, 0, entry.Value.Length);
        }
    }

    private static CaptureResult CaptureShellHostRecipeLanguageControls(string outputPath)
    {
        OpenVisionLanguageService.SetLanguage(OpenVisionLanguage.Korean, false);
        SmokeRecipeWorkspaceCleanup.DeleteTransient();

        string recipeA = "Smoke_RecipeControls_A_" + Guid.NewGuid().ToString("N");
        string recipeB = "Smoke_RecipeControls_B_" + Guid.NewGuid().ToString("N");
        VisionPipelineStorage.Save(recipeA, RecipeContextFixture.CreatePipeline("Inspection_A", 1));
        VisionPipelineStorage.SaveActivePipelineName(recipeA, "Inspection_A");
        VisionPipelineStorage.Save(recipeB, RecipeContextFixture.CreatePipeline("Inspection_B", 1));
        VisionPipelineStorage.SaveActivePipelineName(recipeB, "Inspection_B");

        OpenVisionShellHostView shellHost = CreateShellHost(recipeA, seedMainLayer: false);
        return CaptureWindowWithContent(shellHost, outputPath, 1600, 900, () =>
        {
            AssertHostComboBoxInteraction(shellHost, "cbHostLanguage", "Host language combo");
            AssertHostComboBoxInteraction(shellHost, "cbHostRecipe", "Host recipe combo");

            const string koreanDisplayName = "\uD55C\uAD6D\uC5B4";
            if (!string.Equals(shellHost.SelectedLanguageDisplayNameForTest, koreanDisplayName, StringComparison.Ordinal))
            {
                throw new InvalidOperationException(
                    "Language selector did not expose a readable Korean display name. "
                    + $"Actual='{shellHost.SelectedLanguageDisplayNameForTest}'");
            }

            shellHost.SelectLanguageForTest(OpenVisionLanguage.English);
            Pump(40);
            if (OpenVisionLanguageService.CurrentLanguage != OpenVisionLanguage.English
                || !string.Equals(shellHost.SelectedLanguageDisplayNameForTest, "English", StringComparison.Ordinal)
                || shellHost.IsActiveWpfToolWindowVisibleForTest
                || shellHost.IsNativeDocumentActive
                || shellHost.HasNativePreviewResult)
            {
                throw new InvalidOperationException(
                    "Language selector did not switch to English through the Shell binding path without side effects. "
                    + $"Language={OpenVisionLanguageService.CurrentLanguage}, Display='{shellHost.SelectedLanguageDisplayNameForTest}', "
                    + $"ToolVisible={shellHost.IsActiveWpfToolWindowVisibleForTest}, NativeActive={shellHost.IsNativeDocumentActive}, Preview={shellHost.HasNativePreviewResult}");
            }

            shellHost.SelectLanguageForTest(OpenVisionLanguage.Korean);
            Pump(40);
            if (OpenVisionLanguageService.CurrentLanguage != OpenVisionLanguage.Korean
                || !string.Equals(shellHost.SelectedLanguageDisplayNameForTest, koreanDisplayName, StringComparison.Ordinal))
            {
                throw new InvalidOperationException(
                    "Language selector did not switch back to Korean. "
                    + $"Language={OpenVisionLanguageService.CurrentLanguage}, Display='{shellHost.SelectedLanguageDisplayNameForTest}'");
            }

            if (!shellHost.RecipeOptionsForTest.Contains(recipeA, StringComparer.OrdinalIgnoreCase)
                || !shellHost.RecipeOptionsForTest.Contains(recipeB, StringComparer.OrdinalIgnoreCase))
            {
                throw new InvalidOperationException(
                    "Recipe selector did not list existing recipe workspaces. "
                    + $"Options='{string.Join(", ", shellHost.RecipeOptionsForTest)}'");
            }

            ComboBox hostRecipeCombo = FindNamedVisualChild<ComboBox>(shellHost, "cbHostRecipe")
                ?? throw new InvalidOperationException("Host recipe combo was not found for recipe switching.");
            SelectComboBoxItemText(hostRecipeCombo, recipeB, "Host recipe combo switch to recipe B");
            Pump(100);
            AssertRecipeContext(shellHost, recipeB, "Inspection_B");
            SelectComboBoxItemText(hostRecipeCombo, recipeA, "Host recipe combo switch back to recipe A");
            Pump(100);
            AssertRecipeContext(shellHost, recipeA, "Inspection_A");

            shellHost.RecipeCommands.RecipeFilterText = recipeB;
            Pump(20);
            if (!shellHost.RecipeCommands.FilteredRecipeOptions.Contains(recipeB, StringComparer.OrdinalIgnoreCase)
                || shellHost.RecipeCommands.FilteredRecipeOptions.Contains(recipeA, StringComparer.OrdinalIgnoreCase))
            {
                throw new InvalidOperationException(
                    "Recipe manager filter did not narrow the visible recipe list. "
                    + $"Filter='{shellHost.RecipeCommands.RecipeFilterText}', Results='{string.Join(", ", shellHost.RecipeCommands.FilteredRecipeOptions)}'");
            }

            shellHost.RecipeCommands.RecipeFilterText = string.Empty;
            string managedRecipe = "Smoke_RecipeManager_" + Guid.NewGuid().ToString("N");
            shellHost.RecipeCommands.EditRecipeName = managedRecipe;
            if (!shellHost.RecipeCommands.CreateNamedRecipeCommand.CanExecute(null))
            {
                throw new InvalidOperationException("Recipe manager named create command was disabled for " + managedRecipe);
            }

            shellHost.RecipeCommands.CreateNamedRecipeCommand.Execute(null);
            Pump(80);
            if (!string.Equals(shellHost.RecipeCommands.RecipeManagerSelectedRecipeName, managedRecipe, StringComparison.OrdinalIgnoreCase)
                || !string.Equals(shellHost.SelectedRecipeNameForTest, recipeA, StringComparison.OrdinalIgnoreCase)
                || !shellHost.RecipeOptionsForTest.Contains(managedRecipe, StringComparer.OrdinalIgnoreCase))
            {
                throw new InvalidOperationException(
                    "Recipe manager named create did not select the requested recipe while preserving Main. "
                    + $"Selected='{shellHost.SelectedRecipeNameForTest}', Options='{string.Join(", ", shellHost.RecipeOptionsForTest)}'");
            }

            string renamedManagedRecipe = managedRecipe + "_Renamed";
            shellHost.RecipeCommands.EditRecipeName = renamedManagedRecipe;
            if (!shellHost.RecipeCommands.RenameRecipeCommand.CanExecute(null))
            {
                throw new InvalidOperationException("Recipe manager rename command was disabled for " + renamedManagedRecipe);
            }

            shellHost.RecipeCommands.RenameRecipeCommand.Execute(null);
            Pump(80);
            if (!string.Equals(shellHost.RecipeCommands.RecipeManagerSelectedRecipeName, renamedManagedRecipe, StringComparison.OrdinalIgnoreCase)
                || !string.Equals(shellHost.SelectedRecipeNameForTest, recipeA, StringComparison.OrdinalIgnoreCase)
                || shellHost.RecipeOptionsForTest.Contains(managedRecipe, StringComparer.OrdinalIgnoreCase)
                || !shellHost.RecipeOptionsForTest.Contains(renamedManagedRecipe, StringComparer.OrdinalIgnoreCase)
