            bool hasSavedRunSelection = shellHost.RecipeCommands.SelectedRecentBatchRunOption != null
                && !string.IsNullOrWhiteSpace(shellHost.RecipeCommands.SelectedRecentBatchRunOption.SummaryPath);
            bool canCopySelectedRunReview = shellHost.RecipeCommands.CopySelectedRecentBatchRunReviewCommand.CanExecute(null);
            if (hasSavedRunSelection && !canCopySelectedRunReview)
            {
                throw new InvalidOperationException("Recipe manager selected run review copy command was disabled for a saved run.");
            }

            if (canCopySelectedRunReview)
            {
                shellHost.RecipeCommands.CopySelectedRecentBatchRunReviewCommand.Execute(null);
                Pump(40);
                if (!ContainsAny(shellHost.RecipeCommands.SelectedRecentBatchRunReviewCopyStatusText, "copied", "복사"))
                {
                    throw new InvalidOperationException(
                        "Recipe manager selected run review copy command did not report success. "
                        + $"Status='{shellHost.RecipeCommands.SelectedRecentBatchRunReviewCopyStatusText}'");
                }
            }

            TabItem? xmlStepsTab = FindNamedVisualChild<TabItem>(shellHost, "tabRecipePipelineXmlSteps");
            if (xmlStepsTab == null)
            {
                throw new InvalidOperationException("Recipe manager XML/steps sub-tab was not found.");
            }

            xmlStepsTab.IsSelected = true;
            Pump(40);
            AssertVisibleAutomationIds(
                shellHost,
                "WPF recipe manager pipeline XML/steps sub-tab",
                "HostRecipePipelineXmlStepsTab",
                "HostRecipePipelineInlineValidationReport",
                "HostRecipePipelineValidationIssueList",
                "HostRecipePipelineStepComparisonGrid",
                "HostRecipePipelineStepFlowFocus",
                "HostRecipePipelineStepFlowReview",
                "HostRecipePipelineStepFlowSlots",
                "HostRecipePreviousPipelineStepButton",
                "HostRecipeNextPipelineStepButton",
                "HostRecipeBranchOutputComparisonPanel",
                "HostRecipeBranchOutputComparisonText",
                "HostRecipeBranchOutputComparisonList",
                "HostRecipePipelineInlinePreviewStepList");
            TabItem stepSettingsTab = FindNamedVisualChild<TabItem>(shellHost, "tabRecipePipelineStepSettings")
                ?? throw new InvalidOperationException("Current Step tab was not found.");
            stepSettingsTab.IsSelected = true;
            Pump(40);
            AssertVisibleAutomationIds(
                shellHost,
                "WPF recipe current Step tab",
                "HostRecipePipelineStepSettingsTab",
                "HostRecipePipelineSelectedStepDetailPanel",
                "HostRecipePipelineSelectedStepOperatorContext",
                "HostRecipePipelineSelectedStepRoute",
                "HostRecipePipelineSelectedStepInputLayer",
                "HostRecipePipelineSelectedStepInputLayerThumbnail",
                "HostRecipePipelineSelectedStepOutputLayer",
                "HostRecipePipelineSelectedStepOutputLayerThumbnail",
                "HostRecipePipelineSelectedStepAcceptance",
                "HostRecipePipelineSelectedStepRoiTemplate",
                "HostRecipeOpenSelectedStepToolButton",
                "HostRecipePipelineSelectedStepParameters",
                "HostRecipeLoadSelectedStepParametersButton",
                "HostRecipeApplySelectedStepParametersButton",
                "HostRecipeSelectedStepEditStatus",
                "HostRecipeCorrectedOutputReviewPanel",
                "HostRecipeCorrectedOutputReviewText",
                "HostRecipeCorrectedOutputViewButton",
                "HostRecipeCorrectedOutputRerunButton");
            xmlStepsTab.IsSelected = true;
            Pump(40);
            shellHost.RecipeCommands.SelectedPipelinePreviewStep = shellHost.RecipeCommands.SelectedRecipeSummary.PipelinePreviewSteps[0];
            Pump(40);
            if (!shellHost.RecipeCommands.CurrentPipelineStepText.Contains("Imported_Manager_Step_1", StringComparison.OrdinalIgnoreCase)
                || !shellHost.RecipeCommands.NextPipelineStepText.Contains("Imported_Manager_Step_2", StringComparison.OrdinalIgnoreCase)
                || !shellHost.RecipeCommands.PipelineStepFlowReviewText.Contains("Imported_Manager_Preview_1", StringComparison.OrdinalIgnoreCase)
                || !ContainsAny(shellHost.RecipeCommands.BranchOutputComparisonText, "output consumers 1", "출력 소비 Step 1")
                || !shellHost.RecipeCommands.BranchOutputComparisonRows.Any(row => row.Route.Contains("Imported_Manager_Preview_1", StringComparison.OrdinalIgnoreCase))
                || !shellHost.RecipeCommands.SelectNextPipelinePreviewStepCommand.CanExecute(null))
            {
                throw new InvalidOperationException(
                    "Recipe manager step flow focus did not expose the selected step and next step. "
                    + $"Current='{shellHost.RecipeCommands.CurrentPipelineStepText}', "
                    + $"Next='{shellHost.RecipeCommands.NextPipelineStepText}', "
                    + $"Review='{shellHost.RecipeCommands.PipelineStepFlowReviewText}', "
                    + $"Branch='{shellHost.RecipeCommands.BranchOutputComparisonText}'");
            }

            string selectedStepOperatorContext = shellHost.RecipeCommands.PipelineSelectedStepOperatorContextText;
            if (string.IsNullOrWhiteSpace(selectedStepOperatorContext)
                || !ContainsAny(selectedStepOperatorContext, "Selected step", "선택 Step")
                || !ContainsAny(selectedStepOperatorContext, "Next", "다음"))
            {
                throw new InvalidOperationException(
                    "Recipe manager step flow focus did not expose selected-step operator context. "
                    + $"Context='{selectedStepOperatorContext}'");
            }

            int beforeStepFlowNavigationRuns = shellHost.NativePreviewRunCount;
            shellHost.RecipeCommands.SelectNextPipelinePreviewStepCommand.Execute(null);
            Pump(40);
            if (shellHost.RecipeCommands.SelectedPipelinePreviewStep?.Index != 2
                || !shellHost.RecipeCommands.PreviousPipelineStepText.Contains("Imported_Manager_Step_1", StringComparison.OrdinalIgnoreCase)
                || shellHost.NativePreviewRunCount != beforeStepFlowNavigationRuns)
            {
                throw new InvalidOperationException(
                    "Recipe manager next-step flow navigation did not select step 2 without running Preview. "
                    + $"Selected={shellHost.RecipeCommands.SelectedPipelinePreviewStep?.Index}, "
                    + $"Previous='{shellHost.RecipeCommands.PreviousPipelineStepText}', "
                    + $"RunsBefore={beforeStepFlowNavigationRuns}, RunsAfter={shellHost.NativePreviewRunCount}");
            }

            SaveVisibleAutomationElementPng(
                shellHost,
                "HostRecipeManagerPanel",
                outputPath,
                "recipe-manager-panel.png");
            SaveVisibleAutomationElementPng(
                shellHost,
                "HostRecipeBranchOutputComparisonPanel",
                outputPath,
                "recipe-branch-output-comparison-panel.png");

            TabItem? llmXmlTab = FindNamedVisualChild<TabItem>(shellHost, "tabRecipeLlmXml");
            if (llmXmlTab == null)
            {
                throw new InvalidOperationException("Recipe manager LLM XML tab was not found.");
            }

            llmXmlTab.IsSelected = true;
            Pump(40);
            AssertVisibleAutomationIds(
                shellHost,
                "WPF recipe manager LLM XML tab",
                "HostRecipeLlmXmlTab",
                "HostRecipeLlmAssistantPanel",
                "HostRecipeLlmTemplateSelector",
                "HostRecipeLlmGoalText",
                "HostRecipeLlmDetectionPointsText",
                "HostRecipeLlmResultChannelContract",
                "HostRecipeGuidedSetupSummary",
                "HostRecipeGuidedSetupReadiness",
                "HostRecipeBuildLlmPromptButton",
                "HostRecipeCopyLlmPromptButton",
                "HostRecipeCreateLlmTemplateXmlButton",
                "HostRecipeRefreshLlmDraftReviewButton",
                "HostRecipeLlmPromptPreview",
                "HostRecipeLlmXmlDraftPanel",
                "HostRecipeCopyLlmReviewBundleButton",
                "HostRecipePasteLlmXmlDraftButton",
                "HostRecipeLlmXmlDraftText",
                "HostRecipeLoadLlmXmlDraftButton",
                "HostRecipeValidateLlmXmlDraftButton",
                "HostRecipeImportLlmXmlDraftButton",
                "HostRecipeLlmReferenceImagePath",
                "HostRecipeUseSampleReferenceButton",
                "HostRecipeLlmDraftValidationReport",
                "HostRecipeLlmDependencyReport",
                "HostRecipeLlmDependencyPathList",
                "HostRecipeLlmDraftReviewReport",
                "HostRecipeLlmDiffReport",
                "HostRecipeLlmValidationReport",
                "HostRecipeLlmValidationIssueList");
            TabItem? previewTab = FindNamedVisualChild<TabItem>(shellHost, "tabRecipePreview");
            if (previewTab == null)
            {
                throw new InvalidOperationException("Recipe manager Preview tab was not found.");
            }

            previewTab.IsSelected = true;
            Pump(40);
            AssertVisibleAutomationIds(
                shellHost,
                "WPF recipe manager Preview tab",
                "HostRecipePreviewTab",
                "HostRecipePipelinePreviewStepList");
            TabItem? pipelineTab = FindNamedVisualChild<TabItem>(shellHost, "tabRecipePipeline");
            if (pipelineTab == null)
            {
                throw new InvalidOperationException("Recipe manager Pipeline tab was not found.");
            }

            pipelineTab.IsSelected = true;
            stepSettingsTab.IsSelected = true;
            shellHost.RecipeCommands.SelectedPipelinePreviewStep = shellHost.RecipeCommands.SelectedRecipeSummary.PipelinePreviewSteps.FirstOrDefault();
            Pump(40);
            Button? loadSelectedStepParametersButton = FindVisualChildren<Button>(shellHost)
                .FirstOrDefault(button => string.Equals(
                    System.Windows.Automation.AutomationProperties.GetAutomationId(button),
                    "HostRecipeLoadSelectedStepParametersButton",
                    StringComparison.Ordinal));
            if (loadSelectedStepParametersButton?.Command == null
                || !loadSelectedStepParametersButton.Command.CanExecute(loadSelectedStepParametersButton.CommandParameter))
            {
                throw new InvalidOperationException(
                    $"Selected step parameter load command was not available. Button={loadSelectedStepParametersButton != null}, Step={shellHost.RecipeCommands.SelectedPipelinePreviewStep?.DisplayText}, Detail={shellHost.RecipeCommands.IsRecipeManagerDetailContextActive}");
            }

            int beforeStepParameterApplyRuns = shellHost.NativePreviewRunCount;
            loadSelectedStepParametersButton.Command.Execute(loadSelectedStepParametersButton.CommandParameter);
            Pump(180);
            if (shellHost.RecipeCommands.SelectedStepEditObject == null
                || !shellHost.RecipeCommands.ApplySelectedStepParametersCommand.CanExecute(null))
            {
                throw new InvalidOperationException("Selected step parameters did not load into the recipe PropertyGrid edit object.");
            }

            shellHost.RecipeCommands.ApplySelectedStepParametersCommand.Execute(null);
            Pump(260);
            if (!ContainsAny(shellHost.RecipeCommands.CorrectedOutputReviewText, "corrected output", "수정")
                || !ContainsAny(shellHost.RecipeCommands.CorrectedOutputReviewText, "Rerun", "재검사"))
            {
                throw new InvalidOperationException(
                    "Recipe manager corrected-output review did not update after XML apply. "
                    + $"Text='{shellHost.RecipeCommands.CorrectedOutputReviewText}'");
            }

            if (shellHost.NativePreviewRunCount != beforeStepParameterApplyRuns)
            {
                throw new InvalidOperationException(
                    "Selected step parameter XML apply triggered preview/run. "
                    + $"RunsBefore={beforeStepParameterApplyRuns}, RunsAfter={shellHost.NativePreviewRunCount}");
            }

            AssertVisibleTextContains(
                shellHost,
                "WPF selected step XML apply status",
                "XML 반영 완료");
            AssertHostedPropertyGridRowsRendered(shellHost, "WPF selected step PropertyGrid");
            Point recipeManagerOffsetBefore = shellHost.RecipeManagerPanelOffsetForTest;
            if (!shellHost.MoveRecipeManagerPanelForTest(-220D, 16D))
            {
                throw new InvalidOperationException("Recipe manager panel did not move through the title-bar move path.");
            }

            Pump(40);
            Point recipeManagerOffsetAfter = shellHost.RecipeManagerPanelOffsetForTest;
            if (recipeManagerOffsetAfter.X >= recipeManagerOffsetBefore.X - 10D
                || recipeManagerOffsetAfter.Y <= recipeManagerOffsetBefore.Y)
            {
                throw new InvalidOperationException(
                    "Recipe manager panel movement was too small. "
                    + $"Before={recipeManagerOffsetBefore.X:0.0},{recipeManagerOffsetBefore.Y:0.0}; "
                    + $"After={recipeManagerOffsetAfter.X:0.0},{recipeManagerOffsetAfter.Y:0.0}");
            }

            shellHost.MoveRecipeManagerPanelForTest(
                recipeManagerOffsetBefore.X - recipeManagerOffsetAfter.X,
                recipeManagerOffsetBefore.Y - recipeManagerOffsetAfter.Y);
            Pump(40);
            if (shellHost.RecipeManagerPanelOffsetForTest != recipeManagerOffsetBefore)
            {
                throw new InvalidOperationException("Recipe manager panel did not recover its starting position after the movement check.");
            }

            AssertHiddenAutomationIds(shellHost, "WPF recipe/language context chip", "HostRecipeContext");
            AssertVisibleTextDoesNotContain(shellHost, "WPF recipe/language scope hint", "범위:");
            xmlStepsTab.IsSelected = true;
            shellHost.RecipeCommands.SelectedPipelinePreviewStep = shellHost.RecipeCommands.SelectedRecipeSummary.PipelinePreviewSteps[0];
            Pump(80);
            FrameworkElement? branchOutputPanel = FindVisualChildren<FrameworkElement>(shellHost)
                .FirstOrDefault(item => string.Equals(
                    System.Windows.Automation.AutomationProperties.GetAutomationId(item),
                    "HostRecipeBranchOutputComparisonPanel",
                    StringComparison.Ordinal));
            if (branchOutputPanel != null)
            {
                branchOutputPanel.BringIntoView();
                branchOutputPanel.UpdateLayout();
                Pump(80);
            }
        }, captureFloatingToolWindow: false, captureScreen: true);
    }

    private static CaptureResult CaptureShellHostRecipeLocalValidationSet(
        string outputPath,
        bool captureReviewQueue = false)
    {
        OpenVisionLanguageService.SetLanguage(OpenVisionLanguage.English, false);
        AssertApprovedValidationVariants();
        string recipeName = "Smoke_LocalValidationSet_" + Guid.NewGuid().ToString("N");
        const string pipelineName = "Local_Set_Pipeline";
        VisionPipelineSampleCatalogItem sample = VisionPipelineSampleCatalogItem.LoadRunnable()
            .FirstOrDefault(item => item != null && item.CanOpen)
            ?? throw new InvalidOperationException("No runnable image was available for local validation set smoke.");
        VisionPipelineStorage.Save(recipeName, RecipeContextFixture.CreatePipeline(pipelineName, 1));
        VisionPipelineStorage.SaveActivePipelineName(recipeName, pipelineName);
        File.WriteAllText(
            RecipeWorkspaceService.GetVisionConfigPath(recipeName, "Arithmetic_ToolState_Probe"),
            "<?xml version=\"1.0\" encoding=\"utf-8\"?><ArithmeticToolSettings />");
        File.WriteAllText(
            RecipeWorkspaceService.GetVisionConfigPath(recipeName, "Malformed_Pipeline_Probe"),
            "<VisionPipeline");

        string setImageDirectory = RecipeWorkspaceService.GetVisionPipelineSampleSetDirectory(
            recipeName,
            pipelineName,
            "Local_Set_Evidence");
        string ngImagePath = Path.Combine(setImageDirectory, "expected-ng" + Path.GetExtension(sample.ImageFullPath));
        string repairedNgImagePath = Path.Combine(setImageDirectory, "expected-ng-repaired" + Path.GetExtension(sample.ImageFullPath));
        File.Copy(sample.ImageFullPath, ngImagePath, overwrite: true);
        string folderBatchDirectory = Path.Combine(setImageDirectory, "folder-batch");
        string nestedFolderBatchDirectory = Path.Combine(folderBatchDirectory, "nested");
        Directory.CreateDirectory(nestedFolderBatchDirectory);
        string folderImageA = Path.Combine(folderBatchDirectory, "01-folder-ok" + Path.GetExtension(sample.ImageFullPath));
        string folderImageB = Path.Combine(folderBatchDirectory, "02-folder-ok" + Path.GetExtension(sample.ImageFullPath));
        string nestedFolderImage = Path.Combine(nestedFolderBatchDirectory, "nested-must-not-register" + Path.GetExtension(sample.ImageFullPath));
        File.Copy(sample.ImageFullPath, folderImageA, overwrite: true);
        File.Copy(sample.ImageFullPath, folderImageB, overwrite: true);
        File.Copy(sample.ImageFullPath, nestedFolderImage, overwrite: true);
        File.WriteAllText(Path.Combine(folderBatchDirectory, "unsupported.txt"), "not an image");

        OpenVisionShellHostView shellHost = CreateShellHost(recipeName, seedMainLayer: false);
        try
        {
            return CaptureWindowWithContent(shellHost, outputPath, 1600, 900, () =>
            {
                string[] listedPipelineNames = RecipeWorkspaceService.GetVisionPipelineNames(recipeName);
                string[] visiblePipelineNames = shellHost.RecipeCommands.PipelineOptions
                    .Select(option => option.PipelineName)
                    .ToArray();
                if (!listedPipelineNames.SequenceEqual(new[] { pipelineName }, StringComparer.OrdinalIgnoreCase)
                    || !visiblePipelineNames.SequenceEqual(new[] { pipelineName }, StringComparer.OrdinalIgnoreCase))
                {
                    throw new InvalidOperationException(
                        "Recipe pipeline inventory included tool-state or malformed XML. "
                        + $"Storage=[{string.Join(", ", listedPipelineNames)}], UI=[{string.Join(", ", visiblePipelineNames)}]");
                }

                int previewRunsBefore = shellHost.NativePreviewRunCount;
                int layerCountBefore = shellHost.LayerDocumentCount;
                string workspaceLayerBefore = shellHost.WorkspaceLayerTitle;
                string inputRouteBefore = shellHost.ActiveNativeRouteInputLayerNameForTest;
                string outputRouteBefore = shellHost.ActiveNativeRouteOutputLayerNameForTest;

                OpenVisionRecipeValidationSuiteScopeOption localScope = shellHost.RecipeCommands.ValidationSuiteScopeOptions
                    .FirstOrDefault(option => string.Equals(
                        option.Key,
                        OpenVisionRecipeValidationSuiteScopeOption.LocalValidationSetKey,
                        StringComparison.OrdinalIgnoreCase))
                    ?? throw new InvalidOperationException("Local validation set scope was not available.");
                shellHost.RecipeCommands.SelectedValidationSuiteScopeOption = localScope;
                shellHost.RecipeCommands.NewValidationSetName = "Fixture OK-NG";
                if (!shellHost.RecipeCommands.CreateValidationSetCommand.CanExecute(null))
                {
                    throw new InvalidOperationException("Create local validation set command was disabled.");
                }

                shellHost.RecipeCommands.CreateValidationSetCommand.Execute(null);
                if (!shellHost.RecipeCommands.AddValidationSetImagesForTest(
                        OpenVisionRecipeValidationSetImage.ExpectedOk,
                        new[] { sample.ImageFullPath },
                        "Known-good reference",
                        "FixtureReference",
                        "",
                        "",
                        "")
                    || !shellHost.RecipeCommands.AddValidationSetImagesForTest(
                        OpenVisionRecipeValidationSetImage.ExpectedNg,
                        new[] { ngImagePath },
                        "Expected rejection probe",
                        "FixtureReject",
                        "",
                        "",
                        ""))
                {
                    throw new InvalidOperationException(
                        "Local validation set image registration failed. "
                        + $"Selected={shellHost.RecipeCommands.SelectedValidationSetOption?.Name ?? "<null>"}, "
                        + $"Options={shellHost.RecipeCommands.ValidationSetOptions.Count}, "
                        + $"Rows={shellHost.RecipeCommands.ValidationSetImageRows.Count}, "
                        + $"Status={shellHost.RecipeCommands.ValidationSuiteStatusText}");
                }

                if (!shellHost.RecipeCommands.AddValidationSetFolderForTest(
                        OpenVisionRecipeValidationSetImage.ExpectedOk,
                        folderBatchDirectory,
                        "Folder batch OK")
                    || shellHost.RecipeCommands.ValidationSetImageRows.Count != 4
                    || shellHost.RecipeCommands.SelectedValidationSetOption?.OkCount != 3
                    || shellHost.RecipeCommands.SelectedValidationSetOption?.NgCount != 1
                    || shellHost.RecipeCommands.ValidationSetImageRows.Any(row =>
                        string.Equals(row.Path, nestedFolderImage, StringComparison.OrdinalIgnoreCase)))
                {
                    throw new InvalidOperationException(
                        "Top-level validation folder registration included unsupported/nested files or wrong roles. "
                        + shellHost.RecipeCommands.ValidationSetSelectionSummaryText);
                }

                if (!shellHost.RecipeCommands.AddValidationSetFolderForTest(
                        OpenVisionRecipeValidationSetImage.ExpectedNg,
                        folderBatchDirectory,
                        "Folder batch role update")
                    || shellHost.RecipeCommands.ValidationSetImageRows.Count != 4
                    || shellHost.RecipeCommands.SelectedValidationSetOption?.OkCount != 1
                    || shellHost.RecipeCommands.SelectedValidationSetOption?.NgCount != 3
                    || shellHost.RecipeCommands.ValidationSetImageRows.Count(row =>
                        string.Equals(row.Notes, "Folder batch role update", StringComparison.Ordinal)) != 2
                    || !shellHost.RecipeCommands.AddValidationSetFolderForTest(
                        OpenVisionRecipeValidationSetImage.ExpectedOk,
                        folderBatchDirectory,
                        "Folder batch OK"))
                {
                    throw new InvalidOperationException("Validation folder role update duplicated rows or lost notes.");
                }

                if (!File.Exists(OpenVisionRecipeValidationSetStorage.GetPath(recipeName))
                    || shellHost.RecipeCommands.ValidationSetImageRows.Count != 4
                    || shellHost.RecipeCommands.SelectedValidationSetOption?.OkCount != 3
                    || shellHost.RecipeCommands.SelectedValidationSetOption?.NgCount != 1
                    || shellHost.RecipeCommands.PipelineOptions.Any(option =>
                        string.Equals(option.PipelineName, "validation-sets", StringComparison.OrdinalIgnoreCase)))
                {
                    throw new InvalidOperationException(
                        "Local validation set did not persist one OK and one NG image. "
                        + shellHost.RecipeCommands.ValidationSetSelectionSummaryText);
                }

                File.Delete(ngImagePath);
                shellHost.RecipeCommands.RefreshOptions();
                OpenVisionRecipeValidationSetImageRow missingRow = shellHost.RecipeCommands.ValidationSetImageRows
                    .Single(row => string.Equals(row.Path, ngImagePath, StringComparison.OrdinalIgnoreCase));
                shellHost.RecipeCommands.SelectedValidationSetImageRow = missingRow;
                if (shellHost.RecipeCommands.SelectedValidationSetOption?.MissingCount != 1
                    || !shellHost.RecipeCommands.RepairValidationSetImagePathCommand.CanExecute(null)
                    || shellHost.RecipeCommands.RunValidationSuiteCommand.CanExecute(null))
                {
                    throw new InvalidOperationException(
                        "Missing local validation image did not block explicit suite run. "
                        + shellHost.RecipeCommands.ValidationSetSelectionSummaryText);
                }

                if (shellHost.RecipeCommands.RepairValidationSetImagePathForTest(sample.ImageFullPath)
                    || !string.Equals(missingRow.Path, ngImagePath, StringComparison.OrdinalIgnoreCase))
                {
                    throw new InvalidOperationException("Validation path repair accepted an image already registered in the set.");
                }

                File.Copy(sample.ImageFullPath, repairedNgImagePath, overwrite: true);
                if (!shellHost.RecipeCommands.RepairValidationSetImagePathForTest(repairedNgImagePath))
                {
                    throw new InvalidOperationException(
                        "Explicit validation path repair failed. "
                        + shellHost.RecipeCommands.ValidationSuiteStatusText);
                }

                OpenVisionRecipeValidationSetImageRow repairedRow = shellHost.RecipeCommands.ValidationSetImageRows
                    .Single(row => string.Equals(row.Path, repairedNgImagePath, StringComparison.OrdinalIgnoreCase));
                shellHost.RecipeCommands.SelectedValidationSetImageRow = repairedRow;
                if (shellHost.RecipeCommands.SelectedValidationSetOption?.MissingCount != 0
                    || !string.Equals(repairedRow.Expected, OpenVisionRecipeValidationSetImage.ExpectedNg, StringComparison.Ordinal)
                    || !string.Equals(repairedRow.Notes, "Expected rejection probe", StringComparison.Ordinal)
                    || !string.Equals(repairedRow.VariantId, "FixtureReject", StringComparison.Ordinal)
                    || !string.IsNullOrWhiteSpace(repairedRow.ExpectedMetricText)
                    || !string.Equals(shellHost.RecipeCommands.ValidationSetPendingVariantId, "FixtureReject", StringComparison.Ordinal)
                    || !string.IsNullOrWhiteSpace(shellHost.RecipeCommands.ValidationSetPendingMetricName)
                    || !string.IsNullOrWhiteSpace(shellHost.RecipeCommands.ValidationSetPendingMetricMinimum)
                    || !string.IsNullOrWhiteSpace(shellHost.RecipeCommands.ValidationSetPendingMetricMaximum)
                    || shellHost.RecipeCommands.ValidationSetImageRows.Any(row =>
                        string.Equals(row.Path, ngImagePath, StringComparison.OrdinalIgnoreCase))
                    || shellHost.RecipeCommands.RepairValidationSetImagePathCommand.CanExecute(null)
                    || !shellHost.RecipeCommands.RunValidationSuiteCommand.CanExecute(null))
                {
                    throw new InvalidOperationException(
                        "Repaired local validation image did not preserve metadata or re-enable explicit suite run. "
                        + shellHost.RecipeCommands.ValidationSetSelectionSummaryText);
                }

                shellHost.RecipeCommands.ValidationSetPendingMetricName = "ResultCount";
                shellHost.RecipeCommands.ValidationSetPendingMetricMinimum = "10";
                shellHost.RecipeCommands.ValidationSetPendingMetricMaximum = "1";
                shellHost.RecipeCommands.ApplyValidationSetVariantContractCommand.Execute(null);
                if (!shellHost.RecipeCommands.ValidationSuiteStatusText.Contains("ERROR", StringComparison.OrdinalIgnoreCase)
                    || !string.IsNullOrWhiteSpace(repairedRow.ExpectedMetricText))
                {
                    throw new InvalidOperationException("Invalid Validation Variant range did not fail closed.");
                }

                shellHost.RecipeCommands.ResetValidationSetVariantContractCommand.Execute(null);
                OpenVisionRecipeValidationSetImageRow resetRow = shellHost.RecipeCommands.ValidationSetImageRows
                    .Single(row => string.Equals(row.Path, repairedNgImagePath, StringComparison.OrdinalIgnoreCase));
                if (!string.Equals(resetRow.VariantId, "Default", StringComparison.Ordinal)
                    || !string.IsNullOrWhiteSpace(resetRow.ExpectedMetricText))
                {
                    throw new InvalidOperationException("Validation Variant reset did not restore Default/no-gate.");
                }

                shellHost.RecipeCommands.SelectedValidationSetImageRow = resetRow;
                shellHost.RecipeCommands.ValidationSetPendingVariantId = "FixtureReject";
                shellHost.RecipeCommands.ApplyValidationSetVariantContractCommand.Execute(null);
                repairedRow = shellHost.RecipeCommands.ValidationSetImageRows
                    .Single(row => string.Equals(row.Path, repairedNgImagePath, StringComparison.OrdinalIgnoreCase));
                if (!string.Equals(repairedRow.VariantId, "FixtureReject", StringComparison.Ordinal))
                {
                    throw new InvalidOperationException("Validation Variant explicit Apply did not persist after Reset.");
                }

                if (shellHost.NativePreviewRunCount != previewRunsBefore
                    || shellHost.LayerDocumentCount != layerCountBefore
                    || !string.Equals(shellHost.WorkspaceLayerTitle, workspaceLayerBefore, StringComparison.Ordinal)
                    || !string.Equals(shellHost.ActiveNativeRouteInputLayerNameForTest, inputRouteBefore, StringComparison.Ordinal)
                    || !string.Equals(shellHost.ActiveNativeRouteOutputLayerNameForTest, outputRouteBefore, StringComparison.Ordinal))
                {
                    throw new InvalidOperationException("Local validation set registration changed Preview/Run, layers, workspace, or routing.");
                }

                shellHost.RecipeCommands.RunValidationSuiteCommand.Execute(null);
                DateTime fullRunDeadline = DateTime.UtcNow.AddSeconds(30);
                while (DateTime.UtcNow < fullRunDeadline)
                {
                    Pump(10);
                    if (shellHost.RecipeCommands.RunValidationSuiteCommand.CanExecute(null)
                        && shellHost.RecipeCommands.RecentBatchRunOptions.Any(option =>
                            !string.IsNullOrWhiteSpace(option?.SummaryPath)))
                    {
                        break;
                    }
                }

                if (!shellHost.RecipeCommands.RunValidationSuiteCommand.CanExecute(null))
                {
                    throw new InvalidOperationException(
                        "Local validation set did not finish within 30 seconds. Status='"
                        + shellHost.RecipeCommands.ValidationSuiteStatusText
                        + "'.");
                }

                OpenVisionRecipeBatchRunOption? savedRun = shellHost.RecipeCommands.RecentBatchRunOptions.FirstOrDefault();
                VisionPipelineBatchRunSummary? savedSummary = string.IsNullOrWhiteSpace(savedRun?.SummaryPath)
                    ? null
                    : VisionPipelineBatchRunSummaryStorage.Load(savedRun.SummaryPath);
                if (savedSummary == null
                    || savedSummary.SchemaVersion != VisionPipelineBatchRunSummaryStorage.CurrentSchemaVersion
                    || !string.Equals(savedSummary.SuiteName, "Fixture OK-NG", StringComparison.Ordinal)
                    || !string.Equals(savedSummary.SuiteKind, "LocalValidationSet", StringComparison.Ordinal)
                    || savedSummary.Results.Count != 4
                    || savedSummary.PassCount != 3
                    || savedSummary.FailCount != 1
                    || savedSummary.JudgmentCount != 4
                    || savedSummary.JudgmentCorrectCount != 3
                    || savedSummary.FalseAcceptCount != 1
                    || savedSummary.FalseRejectCount != 0
                    || savedSummary.ExecutionErrorCount != 0
                    || savedSummary.LegacyAmbiguousCount != 0
                    || savedSummary.Results.Count(result => result.Success) != 3
                    || savedSummary.Results.Count(result => !result.Success) != 1
                    || savedSummary.Results.Any(result =>
                        result.OutcomeSchemaVersion != VisionPipelineBatchOutcomeContract.CurrentVersion
                        || !string.Equals(
                            result.ExecutionState,
                            VisionPipelineBatchOutcomeContract.CompletedState,
                            StringComparison.Ordinal)
                        || !string.Equals(
                            result.ActualOutcome,
                            VisionPipelineBatchOutcomeContract.OkOutcome,
                            StringComparison.Ordinal))
                    || savedSummary.Results.Count(result =>
                        string.Equals(result.VariantId, "FixtureReference", StringComparison.Ordinal)
                        && string.IsNullOrWhiteSpace(result.ExpectedMetricName)) != 1
                    || savedSummary.Results.Count(result =>
                        string.Equals(result.VariantId, "FixtureReject", StringComparison.Ordinal)
                        && string.IsNullOrWhiteSpace(result.ExpectedMetricName)) != 1
                    || savedSummary.Results.Count(result => result.HasJudgment && result.JudgmentCorrect) != 3
                    || savedSummary.Results.Count(result =>
                        result.HasJudgment
                        && !result.JudgmentCorrect
                        && string.Equals(
                            result.ExpectedOutcome,
                            VisionPipelineBatchOutcomeContract.NgOutcome,
                            StringComparison.Ordinal)
                        && string.Equals(
                            result.ActualOutcome,
                            VisionPipelineBatchOutcomeContract.OkOutcome,
                            StringComparison.Ordinal)) != 1
                    || !savedSummary.Results.Any(result => result.ExpectedText.Contains("Expected NG", StringComparison.OrdinalIgnoreCase))
                    || savedRun?.JudgmentCorrectCount != 3
                    || savedRun.MisclassificationCount != 1
                    || savedRun.FalseAcceptCount != 1
                    || savedRun.FalseRejectCount != 0
                    || savedRun.ExecutionErrorCount != 0
                    || !savedRun.AnalyticsText.Contains("25.0%", StringComparison.Ordinal))
                {
                    throw new InvalidOperationException(
                        "Local validation set did not reuse saved history with expected OK/NG judgments. Status='"
                        + shellHost.RecipeCommands.ValidationSuiteStatusText
                        + "'.");
                }

                VisionPipelineBatchRunSummaryStorage.BatchReviewQueue rebuiltReviewQueue =
                    VisionPipelineBatchRunSummaryStorage.BuildReviewQueue(savedSummary.Results);
                VisionPipelineBatchReviewQueueEntry? falseAcceptReview = savedSummary.ReviewQueue
                    .FirstOrDefault(entry => entry?.Reasons?.Contains("false-accept", StringComparer.Ordinal) == true);
                if (!string.Equals(savedSummary.ReviewQueuePolicy, VisionPipelineBatchRunSummaryStorage.ReviewQueuePolicyV2, StringComparison.Ordinal)
                    || savedSummary.ReviewQueueSha256.Length != 64
                    || savedSummary.ReviewQueue.Count != 4
                    || falseAcceptReview == null
                    || falseAcceptReview.Reasons.Contains("runtime-failure", StringComparer.Ordinal)
                    || falseAcceptReview.Reasons.Contains("execution-error", StringComparer.Ordinal)
                    || !string.Equals(savedSummary.ReviewQueueSha256, rebuiltReviewQueue.Sha256, StringComparison.Ordinal)
                    || rebuiltReviewQueue.Entries.Count != savedSummary.ReviewQueue.Count)
                {
                    throw new InvalidOperationException(
                        "Local validation set did not persist a deterministic review queue. "
                        + $"Policy='{savedSummary.ReviewQueuePolicy}', Hash='{savedSummary.ReviewQueueSha256}', "
                        + $"Rows={savedSummary.ReviewQueue.Count}, RebuiltHash='{rebuiltReviewQueue.Sha256}'.");
                }
                AssertReviewQueueMetricExtremes(savedSummary);
                VisionPipelineBatchRunSummary incompatibleSummary =
                    VisionPipelineBatchRunSummaryStorage.Load(savedRun.SummaryPath);
                incompatibleSummary.Results[0].VariantId = "DifferentVariant";
                IReadOnlyList<OpenVisionRecipeBatchRunComparisonRow> incompatibleRows =
                    OpenVisionRecipeRunHistoryPresenter.BuildComparisonRows(
                        savedRun,
                        savedRun,
                        savedSummary,
                        incompatibleSummary);
                if (incompatibleRows.Any(row => row?.IsComparable == true))
                {
                    throw new InvalidOperationException(
                        "Run History merged incompatible Validation Variant contracts.");
                }

                VisionPipelineBatchSampleRunResult[] judgmentCases =
                {
                    CreateExplicitJudgmentProbe("correct-accept", expectedSuccess: true, actualSuccess: true),
                    CreateExplicitJudgmentProbe("false-reject", expectedSuccess: true, actualSuccess: false),
                    CreateExplicitJudgmentProbe("false-accept", expectedSuccess: false, actualSuccess: true),
                    CreateExplicitJudgmentProbe("correct-reject", expectedSuccess: false, actualSuccess: false)
                };
                OpenVisionRecipeBatchSampleResultOption[] judgmentOptions = judgmentCases
                    .Select(result => OpenVisionRecipeBatchSampleResultOption.Create(result))
                    .ToArray();
                if (!judgmentOptions[0].JudgmentCorrect
                    || judgmentOptions[0].IsFalseAccept
                    || judgmentOptions[0].IsFalseReject
                    || !judgmentOptions[1].IsFalseReject
                    || !judgmentOptions[2].IsFalseAccept
                    || !judgmentOptions[3].JudgmentCorrect
                    || !judgmentOptions[0].Success
                    || judgmentOptions[1].Success
                    || !judgmentOptions[2].Success
                    || judgmentOptions[3].Success
                    || judgmentOptions[3].IsFalseAccept
                    || judgmentOptions[3].IsFalseReject)
                {
                    throw new InvalidOperationException("Expected/actual judgment classification did not cover all four outcomes.");
                }

                VisionPipelineBatchSampleRunResult legacyCorrectReject =
                    new VisionPipelineBatchSampleRunResult
                    {
                        SampleName = "legacy-correct-reject",
                        PairRole = "NG",
                        ExpectedText = "ExpectedActual: Expected NG",
                        Success = false
                    };
                OpenVisionRecipeBatchSampleResultOption legacyOption =
                    OpenVisionRecipeBatchSampleResultOption.Create(legacyCorrectReject);
                if (!legacyOption.ExecutionCompleted
                    || !legacyOption.HasExpectedOutcome
                    || !legacyOption.JudgmentCorrect
                    || legacyOption.Success
                    || legacyOption.IsFalseAccept
                    || legacyOption.IsFalseReject)
                {
                    throw new InvalidOperationException(
                        "Legacy expected/actual rows did not retain their read-only fallback interpretation.");
                }

                VisionPipelineBatchSampleRunResult unsupportedOutcome =
                    CreateExplicitJudgmentProbe("unsupported-outcome", expectedSuccess: true, actualSuccess: true);
                unsupportedOutcome.OutcomeSchemaVersion =
                    VisionPipelineBatchOutcomeContract.CurrentVersion + 1;
                OpenVisionRecipeBatchSampleResultOption unsupportedOption =
                    OpenVisionRecipeBatchSampleResultOption.Create(unsupportedOutcome);
                if (unsupportedOption.ExecutionCompleted
                    || unsupportedOption.HasExpectedOutcome
                    || VisionPipelineBatchOutcomeContract.TryResolveActualSuccess(
                        unsupportedOutcome,
                        out _))
                {
                    throw new InvalidOperationException(
                        "Unsupported outcome schema did not fail closed.");
                }

                VisionPipelineBatchSampleRunResult executionError =
                    CreateExplicitJudgmentProbe("execution-error", expectedSuccess: true, actualSuccess: false);
                VisionPipelineBatchOutcomeContract.Apply(
                    executionError,
                    executionCompleted: false,
                    actualSuccess: false,
                    hasJudgment: true,
                    expectedSuccess: true,
                    judgmentCorrect: false);
                VisionPipelineBatchRunSummaryStorage.BatchReviewQueue executionErrorQueue =
                    VisionPipelineBatchRunSummaryStorage.BuildReviewQueue(new[] { executionError });
                VisionPipelineBatchReviewQueueEntry executionErrorEntry =
                    executionErrorQueue.Entries.Single(entry => entry.ResultIndex == 0);
                OpenVisionRecipeBatchSampleResultOption executionErrorOption =
                    OpenVisionRecipeBatchSampleResultOption.Create(
                        executionError,
                        executionErrorEntry.Reasons);
                if (executionErrorOption.ExecutionCompleted
                    || executionErrorOption.JudgmentCorrect
                    || executionErrorOption.IsFalseAccept
                    || executionErrorOption.IsFalseReject
                    || !executionErrorEntry.Reasons.Contains("execution-error", StringComparer.Ordinal)
                    || executionErrorEntry.Reasons.Contains("false-reject", StringComparer.Ordinal))
                {
                    throw new InvalidOperationException(
                        "Execution error was not kept separate from expected/actual misclassification.");
                }

                string outcomeSummaryTsvPath = Path.Combine(
                    Path.GetDirectoryName(savedRun.SummaryPath) ?? string.Empty,
                    "summary.tsv");
                string summaryTsvHeader = File.Exists(outcomeSummaryTsvPath)
                    ? File.ReadLines(outcomeSummaryTsvPath).FirstOrDefault() ?? string.Empty
                    : string.Empty;
                if (!summaryTsvHeader.Contains("ExecutionState", StringComparison.Ordinal)
                    || !summaryTsvHeader.Contains("ExpectedOutcome", StringComparison.Ordinal)
                    || !summaryTsvHeader.Contains("ActualOutcome", StringComparison.Ordinal)
                    || !summaryTsvHeader.Contains("JudgmentCorrect", StringComparison.Ordinal))
                {
                    throw new InvalidOperationException(
                        "Saved summary.tsv did not expose the explicit outcome contract.");
                }

                VisionPipelineBatchRunSummaryStorage.BatchRunStatistics savedStatistics =
                    savedRun?.Statistics ?? new VisionPipelineBatchRunSummaryStorage.BatchRunStatistics();
                string analyticsText = shellHost.RecipeCommands.RecentBatchRunComparisonSummaryText ?? string.Empty;
                if (savedStatistics.ResultCount != 4
                    || savedStatistics.TimingCount != 4
                    || savedStatistics.FailureCount != 1
                    || Math.Abs(savedStatistics.FailureRatePercent - 25D) > 0.001D
                    || savedStatistics.P95Milliseconds > savedStatistics.MaximumMilliseconds
                    || !analyticsText.Contains("p95", StringComparison.OrdinalIgnoreCase)
                    || !analyticsText.Contains("ms", StringComparison.OrdinalIgnoreCase)
                    || !analyticsText.Contains("%", StringComparison.Ordinal))
                {
                    throw new InvalidOperationException(
                        "Run History did not expose persisted batch performance analytics. "
                        + $"Results={savedStatistics.ResultCount}, Timings={savedStatistics.TimingCount}, "
                        + $"Failures={savedStatistics.FailureCount}, FailureRate={savedStatistics.FailureRatePercent:0.0}, "
                        + $"P95={savedStatistics.P95Milliseconds:0.0}, Max={savedStatistics.MaximumMilliseconds:0.0}, "
                        + $"Text='{analyticsText}'");
                }

                VisionPipelineBatchRunSummaryStorage.BatchStepTimingAnalysis savedStepTiming =
                    savedRun?.StepTimingAnalysis ?? new VisionPipelineBatchRunSummaryStorage.BatchStepTimingAnalysis();
                VisionPipelineBatchRunSummaryStorage.BatchStepTimingStatistics? savedStep =
                    savedStepTiming.Steps.SingleOrDefault();
                if (!savedStepTiming.IsAvailable
                    || savedStepTiming.SampleCount != 4
                    || savedStepTiming.ReportCount != 4
                    || savedStep == null
                    || savedStep.TimingCount != 4
                    || savedStep.AverageMilliseconds <= 0D
                    || savedStep.P95Milliseconds > savedStep.MaximumMilliseconds
                    || !(savedRun?.StepTimingStatusText ?? string.Empty).Contains("4/4", StringComparison.Ordinal)
                    || !(savedRun?.StepTimingStatusText ?? string.Empty).Contains("p95", StringComparison.OrdinalIgnoreCase))
                {
                    throw new InvalidOperationException(
                        "Run History did not expose complete linked-report Step timing. "
                        + $"Availability={savedStepTiming.Availability}, Samples={savedStepTiming.SampleCount}, "
                        + $"Reports={savedStepTiming.ReportCount}, Steps={savedStepTiming.Steps.Count}, "
                        + $"Timings={savedStep?.TimingCount ?? 0}, Status='{savedRun?.StepTimingStatusText}'");
                }

                VisionPipelineBatchRunSummaryStorage.BatchRunStatistics defensiveStatistics =
                    VisionPipelineBatchRunSummaryStorage.CalculateStatistics(new[]
                    {
                        new VisionPipelineBatchSampleRunResult { Success = true, TotalMilliseconds = 4D },
                        new VisionPipelineBatchSampleRunResult { Success = false, TotalMilliseconds = 0D },
                        new VisionPipelineBatchSampleRunResult { Success = false, TotalMilliseconds = -1D },
                        new VisionPipelineBatchSampleRunResult { Success = true, TotalMilliseconds = double.NaN },
                        new VisionPipelineBatchSampleRunResult { Success = true, TotalMilliseconds = double.PositiveInfinity }
                    });
                if (defensiveStatistics.ResultCount != 5
                    || defensiveStatistics.TimingCount != 1
                    || defensiveStatistics.FailureCount != 2
                    || Math.Abs(defensiveStatistics.FailureRatePercent - 40D) > 0.001D
                    || Math.Abs(defensiveStatistics.AverageMilliseconds - 4D) > 0.001D)
                {
                    throw new InvalidOperationException(
                        "Batch analytics did not separate invalid timing rows from correctness outcomes. "
                        + $"Results={defensiveStatistics.ResultCount}, Timings={defensiveStatistics.TimingCount}, "
                        + $"Failures={defensiveStatistics.FailureCount}, FailureRate={defensiveStatistics.FailureRatePercent:0.0}, "
                        + $"Average={defensiveStatistics.AverageMilliseconds:0.0}");
                }

                VisionPipelineBatchRunSummaryStorage.BatchStepTimingAnalysis unavailableStepTiming =
                    VisionPipelineBatchRunSummaryStorage.CalculateStepTimingAnalysis(
                        new VisionPipelineBatchRunSummary
                        {
                            RecipeName = recipeName,
                            PipelineName = pipelineName,
                            Results = new List<VisionPipelineBatchSampleRunResult>
                            {
                                new VisionPipelineBatchSampleRunResult { SampleName = "missing-report" }
                            }
                        });
                if (unavailableStepTiming.IsAvailable
                    || unavailableStepTiming.Availability
                        != VisionPipelineBatchRunSummaryStorage.StepTimingAvailability.MissingReportPath
                    || unavailableStepTiming.Steps.Count != 0)
                {
                    throw new InvalidOperationException(
                        "Step timing analysis did not reject incomplete linked-report coverage. "
                        + unavailableStepTiming.Availability);
                }

                if (shellHost.NativePreviewRunCount != previewRunsBefore
                    || shellHost.LayerDocumentCount != layerCountBefore
                    || !string.Equals(shellHost.WorkspaceLayerTitle, workspaceLayerBefore, StringComparison.Ordinal)
                    || !string.Equals(shellHost.ActiveNativeRouteInputLayerNameForTest, inputRouteBefore, StringComparison.Ordinal)
                    || !string.Equals(shellHost.ActiveNativeRouteOutputLayerNameForTest, outputRouteBefore, StringComparison.Ordinal))
                {
                    throw new InvalidOperationException("Explicit local validation suite changed workspace Preview/Run, layers, or routing.");
                }

                shellHost.RecipeCommands.RunValidationSuiteCommand.Execute(null);
                if (!shellHost.RecipeCommands.StopValidationSuiteCommand.CanExecute(null))
                {
                    throw new InvalidOperationException("Local validation stop command was not available during execution.");
                }

                shellHost.RecipeCommands.StopValidationSuiteCommand.Execute(null);
                DateTime partialRunDeadline = DateTime.UtcNow.AddSeconds(30);
                while (DateTime.UtcNow < partialRunDeadline)
                {
                    Pump(10);
                    if (shellHost.RecipeCommands.RunValidationSuiteCommand.CanExecute(null)
                        && shellHost.RecipeCommands.RecentBatchRunOptions.Any(option =>
                            !string.IsNullOrWhiteSpace(option?.SummaryPath)
                            && !string.Equals(option.SummaryPath, savedRun?.SummaryPath, StringComparison.OrdinalIgnoreCase)))
                    {
                        break;
                    }
                }

                OpenVisionRecipeBatchRunOption? partialRun = shellHost.RecipeCommands.RecentBatchRunOptions.FirstOrDefault();
                VisionPipelineBatchRunSummary? partialSummary = string.IsNullOrWhiteSpace(partialRun?.SummaryPath)
                    ? null
                    : VisionPipelineBatchRunSummaryStorage.Load(partialRun.SummaryPath);
                if (partialRun == null
                    || partialSummary == null
                    || !partialRun.IsPartialRun
                    || !string.Equals(partialSummary.SuiteKind, "LocalValidationSetPartial", StringComparison.Ordinal)
                    || partialSummary.Results.Count <= 0
                    || partialSummary.Results.Count >= 4
                    || !partialSummary.Notes.Contains("not a full-set accuracy or timing baseline", StringComparison.OrdinalIgnoreCase))
                {
                    throw new InvalidOperationException(
                        "Stopped local validation did not persist an explicit partial result. Status='"
                        + shellHost.RecipeCommands.ValidationSuiteStatusText
                        + "'.");
                }

                shellHost.RecipeCommands.SelectedRecentBatchRunOption = savedRun;

                File.Delete(repairedNgImagePath);
                shellHost.RecipeCommands.RefreshOptions();
                OpenVisionRecipeBatchRunOption captureRun = shellHost.RecipeCommands.RecentBatchRunOptions
                    .FirstOrDefault(option => string.Equals(
                        option?.SummaryPath,
                        savedRun?.SummaryPath,
                        StringComparison.OrdinalIgnoreCase))
                    ?? throw new InvalidOperationException("Completed local validation run was not retained for capture.");
                shellHost.RecipeCommands.SelectedRecentBatchRunOption = captureRun;
                string judgmentFilterText = shellHost.RecipeCommands.RecentBatchRunNgOnlyText;
                string judgmentFilterSummary = shellHost.RecipeCommands.RecentBatchRunNgFilterSummaryText;
                if ((!judgmentFilterText.Contains("Misclassified", StringComparison.OrdinalIgnoreCase)
                        && !judgmentFilterText.Contains("오판", StringComparison.Ordinal))
                    || (!judgmentFilterSummary.Contains("misclassified 1", StringComparison.OrdinalIgnoreCase)
                        && !judgmentFilterSummary.Contains("오판 1", StringComparison.Ordinal)))
                {
                    throw new InvalidOperationException(
                        "Local validation Run History did not present expected/actual misclassification semantics. "
                        + judgmentFilterSummary);
                }

                shellHost.RecipeCommands.ShowRecentBatchNgOnly = true;
                if (shellHost.RecipeCommands.FilteredRecentBatchRunSampleResults.Count != 1
                    || shellHost.RecipeCommands.FilteredRecentBatchRunSampleResults[0].IsFalseAccept != true)
                {
                    throw new InvalidOperationException("Misclassification filter did not isolate the expected-NG false accept.");
                }

                shellHost.RecipeCommands.ShowRecentBatchNgOnly = false;
                int reviewQueuePreviewRunsBefore = shellHost.NativePreviewRunCount;
                int reviewQueueLayerCountBefore = shellHost.LayerDocumentCount;
                string reviewQueueInputBefore = shellHost.ActiveNativeRouteInputLayerNameForTest;
                string reviewQueueOutputBefore = shellHost.ActiveNativeRouteOutputLayerNameForTest;
                shellHost.RecipeCommands.ShowRecentBatchReviewQueueOnly = true;
                Pump(40);
                IReadOnlyList<OpenVisionRecipeBatchSampleResultOption> reviewQueueRows =
                    shellHost.RecipeCommands.FilteredRecentBatchRunSampleResults;
                if (shellHost.RecipeCommands.ShowRecentBatchNgOnly
                    || reviewQueueRows.Count != savedSummary.ReviewQueue.Count
                    || reviewQueueRows.Any(result => result?.IsInReviewQueue != true)
                    || shellHost.RecipeCommands.SelectedRecentBatchSampleResultOption?.IsInReviewQueue != true
                    || !shellHost.RecipeCommands.RecentBatchRunReviewQueueSummaryText.Contains(
                        savedSummary.ReviewQueueSha256.Substring(0, 12),
                        StringComparison.Ordinal)
                    || !shellHost.RecipeCommands.OpenSelectedRecentBatchRunEvidenceCommand.CanExecute(null)
                    || shellHost.NativePreviewRunCount != reviewQueuePreviewRunsBefore
                    || shellHost.LayerDocumentCount != reviewQueueLayerCountBefore
                    || !string.Equals(shellHost.ActiveNativeRouteInputLayerNameForTest, reviewQueueInputBefore, StringComparison.Ordinal)
                    || !string.Equals(shellHost.ActiveNativeRouteOutputLayerNameForTest, reviewQueueOutputBefore, StringComparison.Ordinal))
                {
                    throw new InvalidOperationException(
                        "Run History deterministic review-queue filter or drawing navigation failed. "
                        + $"Rows={reviewQueueRows.Count}, Summary='{shellHost.RecipeCommands.RecentBatchRunReviewQueueSummaryText}'.");
                }

                if (!OpenVisionRecipeRunEvidence.TryCreate(
                        shellHost.RecipeCommands.SelectedRecentBatchSampleResultOption,
                        out OpenVisionRecipeRunEvidence reviewQueueEvidence,
                        out string reviewQueueEvidenceReason))
                {
                    throw new InvalidOperationException(
                        "Review-queue selection could not resolve its retained drawing: " + reviewQueueEvidenceReason);
                }

                string recipeBeforeReviewQueueHandoff = shellHost.SelectedRecipeNameForTest;
                shellHost.RecipeCommands.OpenSelectedRecentBatchRunEvidenceCommand.Execute(null);
                Pump(100);
                Button historicalRunButton = FindVisualChildren<Button>(shellHost).FirstOrDefault(element =>
                    string.Equals(
                        AutomationProperties.GetAutomationId(element),
                        "PipelineReviewRunReviewButton",
                        StringComparison.Ordinal))
                    ?? throw new InvalidOperationException("Historical Pipeline Review Run button was not found.");
                if (!shellHost.HasPipelineReviewDocumentForTest
                    || !shellHost.IsDockedDocumentWorkspaceVisibleForTest
                    || !string.Equals(shellHost.ActiveWpfToolWindowTypeName, "OpenVisionPipelineReviewView", StringComparison.Ordinal)
                    || !shellHost.HasPipelineReviewInputPreview
                    || !shellHost.HasPipelineReviewOutputPreview
                    || !shellHost.PipelineReviewProgressText.Contains("Historical result · no inspection rerun", StringComparison.Ordinal)
                    || !string.Equals(shellHost.PipelineReviewSelectedStepName, reviewQueueEvidence.DefaultDrawing.StepText, StringComparison.Ordinal)
                    || !shellHost.PipelineReviewRunLogText.Contains(reviewQueueEvidence.RunRecordId, StringComparison.Ordinal)
                    || historicalRunButton.IsEnabled
                    || shellHost.NativePreviewRunCount != reviewQueuePreviewRunsBefore
                    || shellHost.LayerDocumentCount != reviewQueueLayerCountBefore
                    || !string.Equals(shellHost.SelectedRecipeNameForTest, recipeBeforeReviewQueueHandoff, StringComparison.Ordinal)
                    || !string.Equals(shellHost.ActiveNativeRouteInputLayerNameForTest, reviewQueueInputBefore, StringComparison.Ordinal)
                    || !string.Equals(shellHost.ActiveNativeRouteOutputLayerNameForTest, reviewQueueOutputBefore, StringComparison.Ordinal))
                {
                    throw new InvalidOperationException(
                        "Selected Run History evidence did not open as read-only docked Pipeline Review without changing the current workspace. "
                        + $"Type={shellHost.ActiveWpfToolWindowTypeName}, Docked={shellHost.IsDockedDocumentWorkspaceVisibleForTest}, "
                        + $"Progress='{shellHost.PipelineReviewProgressText}', Step='{shellHost.PipelineReviewSelectedStepName}', "
                        + $"RunEnabled={historicalRunButton.IsEnabled}.");
                }

                ClickVisibleButtonByAutomationId(
                    shellHost,
                    "PipelineReviewReturnToRecipeButton",
                    "Historical Run History return-to-Recipe button");
                Pump(100);
                if (!shellHost.IsRecipeManagerOpenForTest
                    || !string.Equals(shellHost.SelectedRecipeNameForTest, recipeBeforeReviewQueueHandoff, StringComparison.Ordinal)
                    || !string.Equals(
                        shellHost.RecipeCommands.SelectedRecentBatchSampleResultOption?.SampleName,
                        reviewQueueEvidence.SampleName,
                        StringComparison.Ordinal)
                    || shellHost.NativePreviewRunCount != reviewQueuePreviewRunsBefore
                    || shellHost.LayerDocumentCount != reviewQueueLayerCountBefore)
                {
                    throw new InvalidOperationException(
                        "Returning from historical Pipeline Review did not restore the selected Run History item without execution side effects.");
                }

                shellHost.RecipeCommands.ShowRecentBatchReviewQueueOnly = false;
                OpenVisionRecipeValidationSetImageRow captureMissingRow = shellHost.RecipeCommands.ValidationSetImageRows
                    .Single(row => string.Equals(row.Path, repairedNgImagePath, StringComparison.OrdinalIgnoreCase));
                shellHost.RecipeCommands.SelectedValidationSetImageRow = captureMissingRow;
                if (!shellHost.RecipeCommands.RepairValidationSetImagePathCommand.CanExecute(null))
                {
                    throw new InvalidOperationException("Missing validation image repair action was not available for capture.");
                }

                ToggleButton recipeManagerButton = FindNamedVisualChild<ToggleButton>(shellHost, "btnHostRecipeManager")
                    ?? throw new InvalidOperationException("Recipe manager button was not found.");
                recipeManagerButton.IsChecked = false;
                Pump(80);

                ToggleButton advancedToggle = FindNamedVisualChild<ToggleButton>(shellHost, "recipeAdvancedReviewToggle")
                    ?? throw new InvalidOperationException("Recipe advanced review toggle was not found.");
                int navigationPreviewRunsBefore = shellHost.NativePreviewRunCount;
                int navigationLayerCountBefore = shellHost.LayerDocumentCount;
                ClickVisibleButtonByAutomationId(
                    shellHost,
                    "HostMainRecipeValidationButton",
                    "main validation and history entry");
                Pump(100);
                TabItem pipelineTab = FindNamedVisualChild<TabItem>(shellHost, "tabRecipePipeline")
                    ?? throw new InvalidOperationException("Recipe pipeline tab was not found after image-list navigation.");
                TabItem runHistoryTab = FindNamedVisualChild<TabItem>(shellHost, "tabRecipePipelineRunHistory")
                    ?? throw new InvalidOperationException("Recipe run-history tab was not found after image-list navigation.");
                if (advancedToggle.IsChecked != true
                    || !pipelineTab.IsSelected
                    || !runHistoryTab.IsSelected
                    || !shellHost.RecipeCommands.IsLocalValidationSetSelected
                    || shellHost.NativePreviewRunCount != navigationPreviewRunsBefore
                    || shellHost.LayerDocumentCount != navigationLayerCountBefore)
                {
                    throw new InvalidOperationException(
                        "Image-list validation entry did not navigate without running or changing layers.");
                }

                string expectedEvidence = shellHost.RecipeCommands.ValidationSetExpectedText;
                string acceptanceEvidence = shellHost.RecipeCommands.ValidationSetAcceptanceText;
                string calibrationEvidence = shellHost.RecipeCommands.ValidationSetCalibrationText;
                string nextActionEvidence = shellHost.RecipeCommands.ValidationSetNextActionText;
                if (!expectedEvidence.Contains("OK 3", StringComparison.OrdinalIgnoreCase)
                    || !expectedEvidence.Contains("NG 1", StringComparison.OrdinalIgnoreCase)
                    || (!expectedEvidence.Contains("Missing 1", StringComparison.OrdinalIgnoreCase)
                        && !expectedEvidence.Contains("누락 1", StringComparison.OrdinalIgnoreCase))
                    || (!acceptanceEvidence.Contains("No metric gate", StringComparison.OrdinalIgnoreCase)
                        && !acceptanceEvidence.Contains("Metric 기준 없음", StringComparison.OrdinalIgnoreCase))
                    || (!calibrationEvidence.Contains("Not required", StringComparison.OrdinalIgnoreCase)
                        && !calibrationEvidence.Contains("해당 없음", StringComparison.OrdinalIgnoreCase))
                    || (!nextActionEvidence.Contains("Repair missing", StringComparison.OrdinalIgnoreCase)
                        && !nextActionEvidence.Contains("복구", StringComparison.OrdinalIgnoreCase)))
                {
                    throw new InvalidOperationException(
                        "Local validation set evidence did not state the expected roles, gate, calibration applicability, and repair-first action. "
                        + $"Expected='{expectedEvidence}', Gate='{acceptanceEvidence}', Calibration='{calibrationEvidence}', Next='{nextActionEvidence}'.");
                }

                AssertVisibleAutomationIds(
                    shellHost,
                    "WPF recipe local validation set",
                    "HostRecipeValidationSuitePanel",
                    "HostRecipeValidationSuiteScopeCombo",
                    "HostRecipeRunValidationSuiteButton",
                    "HostRecipeValidationSetEvidenceBoard",
                    "HostRecipeValidationSetExpectedEvidence",
                    "HostRecipeValidationSetAcceptanceEvidence",
                    "HostRecipeValidationSetCalibrationEvidence",
                    "HostRecipeValidationSetNextActionEvidence",
                    "HostRecipeLocalValidationSetEditor",
                    "HostRecipeValidationSetCombo",
                    "HostRecipeNewValidationSetNameTextBox",
                    "HostRecipeCreateValidationSetButton",
                    "HostRecipeDeleteValidationSetButton",
                    "HostRecipeValidationSetNotesTextBox",
                    "HostRecipeValidationVariantIdTextBox",
                    "HostRecipeValidationMetricNameTextBox",
                    "HostRecipeValidationMetricMinimumTextBox",
                    "HostRecipeValidationMetricMaximumTextBox",
                    "HostRecipeApplyValidationVariantButton",
                    "HostRecipeResetValidationVariantButton",
                    "HostRecipeAddValidationSetOkImagesButton",
                    "HostRecipeAddValidationSetNgImagesButton",
                    "HostRecipeAddValidationSetOkFolderButton",
                    "HostRecipeAddValidationSetNgFolderButton",
                    "HostRecipeRepairValidationSetImagePathButton",
                    "HostRecipeRemoveValidationSetImageButton",
                    "HostRecipeValidationSetImageList",
                    "HostRecipeRecentBatchRunList",
                    "HostRecipeRecentBatchReviewQueuePanel",
                    "HostRecipeRecentBatchReviewQueueOnlyToggle",
                    "HostRecipeRecentBatchReviewQueueSummary",
                    "HostRecipeRecentBatchStepTimingPanel",
                    "HostRecipeRecentBatchStepTimingSummary",
                    "HostRecipeRecentBatchStepTimingList");

                shellHost.RecipeCommands.ShowRecentBatchReviewQueueOnly = true;
                FrameworkElement reviewQueuePanel = FindVisualChildren<FrameworkElement>(shellHost)
                    .First(element => string.Equals(
                        AutomationProperties.GetAutomationId(element),
                        "HostRecipeRecentBatchReviewQueuePanel",
                        StringComparison.Ordinal));
                reviewQueuePanel.BringIntoView();
                shellHost.UpdateLayout();
                Pump(80);
                shellHost.RecipeCommands.ShowRecentBatchReviewQueueOnly = false;

                FrameworkElement panel = FindVisualChildren<FrameworkElement>(shellHost)
                    .FirstOrDefault(element => string.Equals(
                        AutomationProperties.GetAutomationId(element),
                        "HostRecipeValidationSuitePanel",
                        StringComparison.Ordinal))
                    ?? throw new InvalidOperationException("Local validation set panel was not found.");
                FrameworkElement evidenceBoard = FindVisualChildren<FrameworkElement>(shellHost)
                    .First(element => string.Equals(
                        AutomationProperties.GetAutomationId(element),
                        "HostRecipeValidationSetEvidenceBoard",
                        StringComparison.Ordinal));
                FrameworkElement editor = FindVisualChildren<FrameworkElement>(shellHost)
                    .First(element => string.Equals(
                        AutomationProperties.GetAutomationId(element),
                        "HostRecipeLocalValidationSetEditor",
                        StringComparison.Ordinal));
                FrameworkElement imageList = FindVisualChildren<FrameworkElement>(shellHost)
                    .First(element => string.Equals(
                        AutomationProperties.GetAutomationId(element),
                        "HostRecipeValidationSetImageList",
                        StringComparison.Ordinal));
                FrameworkElement summary = FindVisualChildren<FrameworkElement>(shellHost)
                    .First(element => string.Equals(
                        AutomationProperties.GetAutomationId(element),
                        "HostRecipeValidationSuiteSummary",
                        StringComparison.Ordinal));
                Rect evidenceBounds = GetElementBounds(panel, evidenceBoard);
                Rect editorBounds = GetElementBounds(panel, editor);
                Rect listBounds = GetElementBounds(panel, imageList);
                Rect summaryBounds = GetElementBounds(panel, summary);
                if (evidenceBounds.Bottom > editorBounds.Top + 1D
                    || editorBounds.Bottom > listBounds.Top + 1D
                    || listBounds.Bottom > summaryBounds.Top + 1D)
                {
                    throw new InvalidOperationException(
                        "Local validation set evidence, editor, image list, and summary overlap. "
                        + $"Evidence={FormatRect(evidenceBounds)}, Editor={FormatRect(editorBounds)}, List={FormatRect(listBounds)}, Summary={FormatRect(summaryBounds)}");
                }

                if (captureReviewQueue)
                {
                    string evidenceDirectory = Path.Combine(
                        Path.GetDirectoryName(outputPath) ?? ".",
                        Path.GetFileNameWithoutExtension(outputPath) + ".evidence");
                    Directory.CreateDirectory(evidenceDirectory);
                    string savedSummaryPath = savedRun?.SummaryPath
                        ?? throw new InvalidOperationException("Review-queue evidence summary path is missing.");
                    File.Copy(savedSummaryPath, Path.Combine(evidenceDirectory, "summary.xml"), overwrite: true);
                    string summaryTsvPath = Path.Combine(Path.GetDirectoryName(savedSummaryPath) ?? string.Empty, "summary.tsv");
                    if (File.Exists(summaryTsvPath))
                    {
                        File.Copy(summaryTsvPath, Path.Combine(evidenceDirectory, "summary.tsv"), overwrite: true);
                    }
                    File.WriteAllLines(
                        Path.Combine(evidenceDirectory, "review-queue-contract.txt"),
                        new[]
                        {
                            "Policy=" + savedSummary.ReviewQueuePolicy,
                            "Sha256=" + savedSummary.ReviewQueueSha256,
                            "Rows=" + savedSummary.ReviewQueue.Count.ToString(CultureInfo.InvariantCulture),
                            "Total=" + savedSummary.Results.Count.ToString(CultureInfo.InvariantCulture),
                            "SummarySchemaVersion=" + savedSummary.SchemaVersion.ToString(CultureInfo.InvariantCulture),
                            "OutcomeSchemaVersion=" + VisionPipelineBatchOutcomeContract.CurrentVersion.ToString(CultureInfo.InvariantCulture),
                            "JudgmentCorrect=" + savedSummary.JudgmentCorrectCount.ToString(CultureInfo.InvariantCulture),
                            "FalseAccept=" + savedSummary.FalseAcceptCount.ToString(CultureInfo.InvariantCulture),
                            "FalseReject=" + savedSummary.FalseRejectCount.ToString(CultureInfo.InvariantCulture),
                            "ExecutionError=" + savedSummary.ExecutionErrorCount.ToString(CultureInfo.InvariantCulture),
                            "LegacyAmbiguous=" + savedSummary.LegacyAmbiguousCount.ToString(CultureInfo.InvariantCulture),
                            "FalseAcceptIncluded=" + (falseAcceptReview != null),
                            "DrawingResolved=true",
                            "PreviewRunCountUnchanged=" + (shellHost.NativePreviewRunCount == reviewQueuePreviewRunsBefore),
                            "LayerCountUnchanged=" + (shellHost.LayerDocumentCount == reviewQueueLayerCountBefore)
                    });
                    shellHost.RecipeCommands.ShowRecentBatchReviewQueueOnly = true;
                    reviewQueuePanel.BringIntoView();
                    SaveVisibleAutomationElementPng(
                        shellHost,
                        "HostRecipeRecentBatchReviewQueuePanel",
                        outputPath,
                        "recipe-review-queue-panel.png");
                }
                else
                {
                    editor.BringIntoView();
                }
                shellHost.UpdateLayout();
                Pump(100);
            }, captureFloatingToolWindow: false, captureScreen: true);
        }
        finally
        {
            RecipeWorkspaceService.DeleteVisionWorkspace(recipeName);
        }
    }

    private static CaptureResult CaptureP250CatalogPairValidationSet(string outputPath)
    {
        OpenVisionLanguageService.SetLanguage(OpenVisionLanguage.English, false);
        string recipeName = "Smoke_CatalogPairSet_" + Guid.NewGuid().ToString("N");
        const string pipelineName = "Catalog_Pair_Pipeline";
        const string sampleName = "Public_Matching_DiePad_Good";
        VisionPipelineSampleCatalogItem sample = VisionPipelineSampleCatalogItem
            .LoadRunnable(VisionPipelineSampleCatalogSourceKind.Public)
            .FirstOrDefault(item => string.Equals(
                item?.SampleName,
                sampleName,
                StringComparison.Ordinal))
            ?? throw new InvalidOperationException(
                "P250 public multi-metric pair sample is missing: " + sampleName);
        if (!SerializeHelper.TryLoadFromXmlFile(
                sample.PipelineFullPath,
                out VisionPipeline pipeline)
            || pipeline == null)
        {
            throw new InvalidOperationException(
                "P250 sample pipeline could not be loaded: " + sample.PipelineFullPath);
        }

        pipeline.Name = pipelineName;
        VisionPipelineStorage.Save(recipeName, pipeline);
        VisionPipelineStorage.SaveActivePipelineName(recipeName, pipelineName);

        OpenVisionShellHostView shellHost =
            CreateShellHost(recipeName, seedMainLayer: false);
        return CaptureWindowWithContent(
                shellHost,
                outputPath,
                1600,
                900,
                () =>
                {
                    OpenVisionRecipeSampleOption sampleOption =
                        shellHost.RecipeCommands.SampleOptions.FirstOrDefault(option =>
                            string.Equals(
                                option?.SampleName,
                                sampleName,
                                StringComparison.Ordinal))
                        ?? throw new InvalidOperationException(
                            "P250 Recipe Manager sample selector did not expose "
                            + sampleName);
                    shellHost.RecipeCommands.SelectedSampleOption = sampleOption;
                    Pump(40);

                    int previewRunsBefore = shellHost.NativePreviewRunCount;
                    int layerCountBefore = shellHost.LayerDocumentCount;
                    string workspaceLayerBefore = shellHost.WorkspaceLayerTitle;
                    string inputRouteBefore =
                        shellHost.ActiveNativeRouteInputLayerNameForTest;
                    string outputRouteBefore =
                        shellHost.ActiveNativeRouteOutputLayerNameForTest;

                    if (!shellHost.RecipeCommands
                        .CreateValidationSetFromSelectedPairCommand
                        .CanExecute(null))
                    {
                        throw new InvalidOperationException(
                            "P250 save-pair-as-set command was disabled for "
                            + sampleName);
                    }

                    if (!shellHost.RecipeCommands
                        .CreateValidationSetFromSelectedPairForTest())
                    {
                        throw new InvalidOperationException(
                            "P250 catalog pair import failed: "
                            + shellHost.RecipeCommands.ValidationSuiteStatusText);
                    }

                    string importedSetName =
                        shellHost.RecipeCommands.SelectedValidationSetOption?.Name
                        ?? string.Empty;
                    IReadOnlyList<OpenVisionRecipeValidationSetImageRow> rows =
                        shellHost.RecipeCommands.ValidationSetImageRows;
                    OpenVisionRecipeValidationSetImageRow goodRow =
                        rows.SingleOrDefault(row => string.Equals(
                            row.VariantId,
                            sampleName,
                            StringComparison.Ordinal))
                        ?? throw new InvalidOperationException(
                            "P250 imported Good row is missing.");
                    if (rows.Count != 2
                        || shellHost.RecipeCommands.SelectedValidationSetOption?.OkCount != 1
                        || shellHost.RecipeCommands.SelectedValidationSetOption?.NgCount != 1
                        || sample.ExpectedMetrics.Count != 2
                        || string.IsNullOrWhiteSpace(goodRow.Image.Sha256)
                        || !string.Equals(
                            goodRow.Image.Sha256,
                            OpenVisionRecipeValidationSetStorage.ComputeFileSha256(
                                goodRow.Path),
                            StringComparison.OrdinalIgnoreCase)
                        || !string.Equals(
                            goodRow.Image.ExpectedMetricName,
                            "ResultCount;ScoreMax",
                            StringComparison.Ordinal)
                        || !string.Equals(
                            goodRow.Image.ExpectedMetricMinimum,
                            "3;80",
                            StringComparison.Ordinal)
                        || !string.Equals(
                            goodRow.Image.ExpectedMetricMaximum,
                            "3;100",
                            StringComparison.Ordinal)
                        || !goodRow.ExpectedMetricText.Contains(
                            "ResultCount [3..3]",
                            StringComparison.Ordinal)
                        || !goodRow.ExpectedMetricText.Contains(
                            "ScoreMax [80..100]",
                            StringComparison.Ordinal))
                    {
                        throw new InvalidOperationException(
                            "P250 imported set lost pair roles, SHA-256, or multi-metric gates. "
                            + shellHost.RecipeCommands.ValidationSetSelectionSummaryText);
                    }

                    QualifiedRecipeValidationImageSource qualifiedMetricProbe =
                        new QualifiedRecipeValidationImageSource
                        {
                            VariantId = goodRow.Image.VariantId,
                            ExpectedMetricName = goodRow.Image.ExpectedMetricName,
                            ExpectedMetricMinimum = goodRow.Image.ExpectedMetricMinimum,
                            ExpectedMetricMaximum = goodRow.Image.ExpectedMetricMaximum
                        };
                    QualifiedRecipeValidationImageSource invalidQualifiedMetricProbe =
                        new QualifiedRecipeValidationImageSource
                        {
                            VariantId = goodRow.Image.VariantId,
                            ExpectedMetricName = "ResultCount;ScoreMax",
                            ExpectedMetricMinimum = "3;80;999",
                            ExpectedMetricMaximum = "3;100"
                        };
                    if (!QualifiedRecipeSnapshotPreflight.TryValidateVariantContract(
                            qualifiedMetricProbe,
                            out string qualifiedMetricError)
                        || QualifiedRecipeSnapshotPreflight.TryValidateVariantContract(
                            invalidQualifiedMetricProbe,
                            out _))
                    {
                        throw new InvalidOperationException(
                            "P250 Qualified Snapshot multi-metric preflight contract failed: "
                            + qualifiedMetricError);
                    }

                    if (!OpenVisionRecipeValidationSetStorage.TryLoad(
                            recipeName,
                            out OpenVisionRecipeValidationSetDocument reloaded,
                            out string reloadError))
                    {
                        throw new InvalidOperationException(
                            "P250 validation set reload failed: " + reloadError);
                    }

                    OpenVisionRecipeValidationSet persistedSet =
                        reloaded.Sets.SingleOrDefault(set => string.Equals(
                            set?.Name,
                            importedSetName,
                            StringComparison.Ordinal))
                        ?? throw new InvalidOperationException(
                            "P250 imported set was not persisted.");
                    if (persistedSet.Images.Count != 2
                        || persistedSet.Images.Any(image =>
                            string.IsNullOrWhiteSpace(image?.Sha256)))
                    {
                        throw new InvalidOperationException(
                            "P250 persisted set did not retain both image hashes.");
                    }

                    if (!shellHost.RecipeCommands
                        .CreateValidationSetFromSelectedPairForTest()
                        || shellHost.RecipeCommands.ValidationSetOptions.Count(option =>
                            string.Equals(
                                option.Name,
                                importedSetName,
                                StringComparison.Ordinal)) != 1
                        || shellHost.RecipeCommands.ValidationSetImageRows.Count != 2
                        || (!shellHost.RecipeCommands.ValidationSuiteStatusText.Contains(
                                "Updated",
                                StringComparison.OrdinalIgnoreCase)
                            && !shellHost.RecipeCommands.ValidationSuiteStatusText.Contains(
                                "갱신",
                                StringComparison.Ordinal)))
                    {
                        throw new InvalidOperationException(
                            "P250 repeat import duplicated the set or did not report an update. "
                            + "Sets="
                            + string.Join(
                                ",",
                                shellHost.RecipeCommands.ValidationSetOptions
                                    .Select(option => option.Name))
                            + " | Rows="
                            + shellHost.RecipeCommands.ValidationSetImageRows.Count
                            + " | Status="
                            + shellHost.RecipeCommands.ValidationSuiteStatusText);
                    }

                    if (shellHost.NativePreviewRunCount != previewRunsBefore
                        || shellHost.LayerDocumentCount != layerCountBefore
                        || !string.Equals(
                            shellHost.WorkspaceLayerTitle,
                            workspaceLayerBefore,
                            StringComparison.Ordinal)
                        || !string.Equals(
                            shellHost.ActiveNativeRouteInputLayerNameForTest,
                            inputRouteBefore,
                            StringComparison.Ordinal)
                        || !string.Equals(
                            shellHost.ActiveNativeRouteOutputLayerNameForTest,
                            outputRouteBefore,
                            StringComparison.Ordinal))
                    {
                        throw new InvalidOperationException(
                            "P250 pair import changed Preview/Run, layers, workspace, or routing.");
                    }

                    ToggleButton recipeManagerButton =
                        FindNamedVisualChild<ToggleButton>(
                            shellHost,
                            "btnHostRecipeManager")
                        ?? throw new InvalidOperationException(
                            "P250 Recipe Manager button is missing.");
                    recipeManagerButton.IsChecked = true;
                    Pump(80);
                    ToggleButton advancedToggle =
                        FindNamedVisualChild<ToggleButton>(
                            shellHost,
                            "recipeAdvancedReviewToggle")
                        ?? throw new InvalidOperationException(
                            "P250 advanced review toggle is missing.");
                    advancedToggle.IsChecked = true;
                    TabItem pipelineTab =
                        FindNamedVisualChild<TabItem>(
                            shellHost,
                            "tabRecipePipeline")
                        ?? throw new InvalidOperationException(
                            "P250 Pipeline tab is missing.");
                    pipelineTab.IsSelected = true;
                    Pump(80);

                    FrameworkElement importButton =
                        FindVisualChildren<FrameworkElement>(shellHost)
                            .FirstOrDefault(element => string.Equals(
                                System.Windows.Automation.AutomationProperties
                                    .GetAutomationId(element),
                                "HostRecipeCreateValidationSetFromPairButton",
                                StringComparison.Ordinal))
                        ?? throw new InvalidOperationException(
                            "P250 pair import button is missing from Recipe Manager.");
                    importButton.BringIntoView();
                    shellHost.UpdateLayout();
                    Pump(80);
                    TabItem runHistoryTab =
                        FindNamedVisualChild<TabItem>(
                            shellHost,
                            "tabRecipePipelineRunHistory")
                        ?? throw new InvalidOperationException(
                            "P250 Run History tab is missing.");
                    runHistoryTab.IsSelected = true;
                    Pump(80);
                    pipelineTab.IsSelected = true;
                    importButton.BringIntoView();
                    shellHost.UpdateLayout();
                    Pump(80);
                },
                captureFloatingToolWindow: false,
                captureScreen: true);
    }

    private static CaptureResult CaptureP253WorkspaceSampleRecipeContextSync(
        string outputPath)
    {
        OpenVisionLanguageService.SetLanguage(OpenVisionLanguage.English, false);
        string recipeName =
            "Smoke_WorkspaceSampleSync_" + Guid.NewGuid().ToString("N");
        const string sampleName = "Public_Matching_DiePad_Good";
        const string expectedPipelineName =
            "Sample_Public_Matching_DiePad_Good";
        const string cancelledSampleName = "Public_Blob_Particles_Good";

        OpenVisionShellHostView shellHost =
            CreateShellHost(recipeName, seedMainLayer: false);
        try
        {
            return CaptureWindowWithContent(
                shellHost,
                outputPath,
                1600,
                900,
                () =>
                {
                    int previewRunsBefore = shellHost.NativePreviewRunCount;

                    if (!shellHost.OpenWorkspaceSampleForTest(sampleName))
                    {
                        throw new InvalidOperationException(
                            "P253 could not open the public Matching sample.");
                    }

                    if (!string.Equals(
                            shellHost.ActivePipelineNameForTest,
                            expectedPipelineName,
                            StringComparison.Ordinal)
                        || !string.Equals(
                            shellHost.RecipeManagerSelectedPipelineNameForTest,
                            expectedPipelineName,
                            StringComparison.Ordinal)
                        || !string.Equals(
                            shellHost.RecipeManagerSelectedSampleNameForTest,
                            sampleName,
                            StringComparison.Ordinal))
                    {
                        throw new InvalidOperationException(
                            "P253 workspace sample did not synchronize the "
                            + "Recipe Manager sample/pipeline context. Active="
                            + shellHost.ActivePipelineNameForTest
                            + " | SelectedPipeline="
                            + shellHost.RecipeManagerSelectedPipelineNameForTest
                            + " | SelectedSample="
                            + shellHost.RecipeManagerSelectedSampleNameForTest);
                    }
                    if (shellHost.NativePreviewRunCount != previewRunsBefore)
                    {
                        throw new InvalidOperationException(
                            "P253 opening and synchronizing a workspace sample "
                            + "ran Preview/Run automatically.");
                    }

                    int layerCountAfterSampleOpen =
                        shellHost.LayerDocumentCount;
                    string routeInputAfterSampleOpen =
                        shellHost.ActiveNativeRouteInputLayerNameForTest;
                    string routeOutputAfterSampleOpen =
                        shellHost.ActiveNativeRouteOutputLayerNameForTest;

                    if (!shellHost.RecipeCommands
                        .CreateValidationSetFromSelectedPairForTest())
                    {
                        throw new InvalidOperationException(
                            "P253 synchronized catalog pair import failed: "
                            + shellHost.RecipeCommands.ValidationSuiteStatusText);
                    }

                    IReadOnlyList<OpenVisionRecipeValidationSetImageRow> rows =
                        shellHost.RecipeCommands.ValidationSetImageRows;
                    if (rows.Count != 2
                        || !rows.Any(row => string.Equals(
                            row?.VariantId,
                            sampleName,
                            StringComparison.Ordinal))
                        || !rows.Any(row => string.Equals(
                            row?.VariantId,
                            "Public_Matching_DiePad_NoTarget_Bad",
                            StringComparison.Ordinal)))
                    {
                        throw new InvalidOperationException(
                            "P253 imported the wrong catalog pair after "
                            + "workspace sample synchronization. Rows="
                            + string.Join(
                                ",",
                                rows.Select(row => row?.VariantId ?? "-")));
                    }

                    OpenVisionRecipePipelineStepPreview firstStep =
                        shellHost.RecipeCommands.SelectedRecipeSummary
                            .PipelinePreviewSteps
                            .FirstOrDefault()
                        ?? throw new InvalidOperationException(
                            "P253 synchronized sample pipeline has no Step.");
                    shellHost.RecipeCommands.SelectedPipelinePreviewStep =
                        firstStep;
                    shellHost.RecipeCommands.LoadSelectedStepParametersCommand
                        .Execute(null);
                    shellHost.RecipeCommands
                        .MarkSelectedStepEditDirtyForQualificationTest();
                    shellHost.QueuePendingRecipeEditDecisionForTest(
                        OpenVisionRecipePendingEditDecision.Cancel);

                    if (shellHost.OpenWorkspaceSampleForTest(
                            cancelledSampleName)
                        || !shellHost.RecipeCommands.IsSelectedStepEditDirty
                        || !string.Equals(
                            shellHost.ActivePipelineNameForTest,
                            expectedPipelineName,
                            StringComparison.Ordinal)
                        || !string.Equals(
                            shellHost.RecipeManagerSelectedSampleNameForTest,
                            sampleName,
                            StringComparison.Ordinal))
                    {
                        throw new InvalidOperationException(
                            "P253 pending-edit cancellation did not fail closed "
                            + "before changing the workspace sample context.");
                    }

                    shellHost.RecipeCommands
                        .DiscardSelectedStepEditForQualificationTest();

                    if (shellHost.NativePreviewRunCount != previewRunsBefore
                        || shellHost.LayerDocumentCount
                            != layerCountAfterSampleOpen
                        || !string.Equals(
                            shellHost.ActiveNativeRouteInputLayerNameForTest,
                            routeInputAfterSampleOpen,
                            StringComparison.Ordinal)
                        || !string.Equals(
                            shellHost.ActiveNativeRouteOutputLayerNameForTest,
                            routeOutputAfterSampleOpen,
                            StringComparison.Ordinal))
                    {
                        throw new InvalidOperationException(
                            "P253 context synchronization or pair persistence "
                            + "changed Preview/Run, layers, or routing.");
                    }

                    ToggleButton recipeManagerButton =
                        FindNamedVisualChild<ToggleButton>(
                            shellHost,
                            "btnHostRecipeManager")
                        ?? throw new InvalidOperationException(
                            "P253 Recipe Manager button is missing.");
                    recipeManagerButton.IsChecked = true;
                    Pump(80);
                    ToggleButton advancedToggle =
                        FindNamedVisualChild<ToggleButton>(
                            shellHost,
                            "recipeAdvancedReviewToggle")
                        ?? throw new InvalidOperationException(
                            "P253 advanced review toggle is missing.");
                    advancedToggle.IsChecked = true;
                    TabItem pipelineTab =
                        FindNamedVisualChild<TabItem>(
                            shellHost,
                            "tabRecipePipeline")
                        ?? throw new InvalidOperationException(
                            "P253 Pipeline tab is missing.");
                    pipelineTab.IsSelected = true;
                    Pump(80);

                    FrameworkElement pairButton =
                        FindVisualChildren<FrameworkElement>(shellHost)
                            .First(element => string.Equals(
                                System.Windows.Automation.AutomationProperties
                                    .GetAutomationId(element),
                                "HostRecipeCreateValidationSetFromPairButton",
                                StringComparison.Ordinal));
                    pairButton.BringIntoView();
                    shellHost.UpdateLayout();
                    Pump(80);
                },
                captureFloatingToolWindow: false,
                captureScreen: true);
        }
        finally
        {
            RecipeWorkspaceService.DeleteVisionWorkspace(recipeName);
        }
    }

    private static CaptureResult CaptureP254DirectTeachingPipelinePersistence(
        string outputPath)
    {
        OpenVisionLanguageService.SetLanguage(OpenVisionLanguage.Korean, false);
        string recipeName =
            "Smoke_DirectTeachingPersistence_" + Guid.NewGuid().ToString("N");
        const string sampleName = "Public_Blob_Particles_Good";
        const string expectedPipelineName =
            "Sample_Public_Blob_Particles_Good";

        OpenVisionShellHostView shellHost =
            CreateShellHost(recipeName, seedMainLayer: false);
        try
        {
            return CaptureWindowWithContent(
                shellHost,
                outputPath,
                1600,
                900,
                () =>
                {
                    if (!shellHost.OpenWorkspaceSampleForTest(sampleName))
                    {
                        throw new InvalidOperationException(
                            "P254 could not open the public Blob sample.");
                    }

                    string activeRecipeName =
                        shellHost.ActiveRecipeContextNameForTest;
                    int originalStepCount =
                        shellHost.ActivePipelineStepCountForTest;
                    if (string.IsNullOrWhiteSpace(activeRecipeName)
                        || !string.Equals(
                            shellHost.ActivePipelineNameForTest,
                            expectedPipelineName,
                            StringComparison.Ordinal)
                        || originalStepCount < 2)
                    {
                        throw new InvalidOperationException(
                            "P254 public Blob sample did not establish the "
                            + "expected Recipe/Pipeline context. Recipe="
                            + activeRecipeName
                            + " | Pipeline="
                            + shellHost.ActivePipelineNameForTest
                            + " | Steps="
                            + originalStepCount.ToString(
                                CultureInfo.InvariantCulture));
                    }

                    shellHost.SelectToolForTest(VISION_MENU.Blob);
                    Pump(80);
                    ClickFloatingButtonByName(
                        "btnPresetBasic",
                        "P254 Blob Basic preset");
                    Button addButton = GetActiveToolButtonByName(
                        "btnAddPipeline",
                        "P254 add-and-save button");
                    string expectedAddText =
                        OpenVisionLanguageService.T("ToolView.AddPipeline");
                    if (!FindVisualChildren<TextBlock>(addButton)
                        .Any(text => string.Equals(
                            text.Text,
                            expectedAddText,
                            StringComparison.Ordinal)))
                    {
                        throw new InvalidOperationException(
                            "P254 add action does not state that it saves. "
                            + "Expected=" + expectedAddText);
                    }

                    shellHost.RunActiveNativePreviewForTest();
                    Pump(80);
                    if (!shellHost.HasNativePreviewResult)
                    {
                        throw new InvalidOperationException(
                            "P254 explicit Blob Preview produced no result: "
                            + shellHost.ActiveNativeStatusText);
                    }

                    int previewRunsBeforeAdd =
                        shellHost.NativePreviewRunCount;
                    int layerCountBeforeAdd = shellHost.LayerDocumentCount;
                    string activeLayerBeforeAdd =
                        shellHost.ActiveHostLayerTitle;
                    string inputRouteBeforeAdd =
                        shellHost.ActiveNativeRouteInputLayerNameForTest;
                    string outputRouteBeforeAdd =
                        shellHost.ActiveNativeRouteOutputLayerNameForTest;

                    VisionPipelineStep addedStep =
                        shellHost.AddActiveNativePipelineStepForTest();
                    if (addedStep == null)
                    {
                        throw new InvalidOperationException(
                            "P254 direct Blob Step add/save failed: "
                            + shellHost.ActiveNativeStatusText);
                    }

                    VisionPipeline? reopenedPipeline =
                        VisionPipelineStorage.Load(
                            activeRecipeName,
                            expectedPipelineName);
                    VisionPipelineStep? reopenedStep =
                        reopenedPipeline?.Steps?.LastOrDefault();
                    if (reopenedPipeline?.Steps?.Count
                            != originalStepCount + 1
                        || reopenedStep == null
                        || !string.Equals(
                            reopenedStep.Name,
                            addedStep.Name,
                            StringComparison.Ordinal)
                        || !string.Equals(
                            reopenedStep.ToolType,
                            "Blob",
                            StringComparison.Ordinal))
                    {
                        throw new InvalidOperationException(
                            "P254 persisted Pipeline did not reopen with the "
                            + "new Blob Step.");
                    }

                    string savedStatus = shellHost.ActiveNativeStatusText;
                    if (!savedStatus.Contains(
                            addedStep.Name,
                            StringComparison.Ordinal)
                        || !savedStatus.Contains(
                            activeRecipeName,
                            StringComparison.Ordinal)
                        || !savedStatus.Contains(
                            expectedPipelineName,
                            StringComparison.Ordinal)
                        || !savedStatus.Contains(
                            "Pipeline 보기",
                            StringComparison.Ordinal))
                    {
                        throw new InvalidOperationException(
                            "P254 save status did not expose the exact "
                            + "Recipe/Pipeline and next action. Status="
                            + savedStatus);
                    }

                    if (shellHost.NativePreviewRunCount
                            != previewRunsBeforeAdd
                        || shellHost.LayerDocumentCount
                            != layerCountBeforeAdd
                        || !string.Equals(
                            shellHost.ActiveHostLayerTitle,
                            activeLayerBeforeAdd,
                            StringComparison.Ordinal)
                        || !string.Equals(
                            shellHost.ActiveNativeRouteInputLayerNameForTest,
                            inputRouteBeforeAdd,
                            StringComparison.Ordinal)
                        || !string.Equals(
                            shellHost.ActiveNativeRouteOutputLayerNameForTest,
                            outputRouteBeforeAdd,
                            StringComparison.Ordinal))
                    {
                        throw new InvalidOperationException(
                            "P254 add/save changed Preview/Run, layers, "
                            + "active layer, or routing.");
                    }

                    WriteFloatingToolWindowCapture(outputPath);
                    shellHost.CloseActiveWpfToolWindowForTest();
                    Pump(60);
                    shellHost.RecipeCommands.RefreshOptions();
                    Pump(80);
                    if (!string.Equals(
                            shellHost.RecipeManagerSelectedPipelineNameForTest,
                            expectedPipelineName,
                            StringComparison.Ordinal)
                        || shellHost.RecipeCommands.SelectedRecipeSummary
                            ?.PipelinePreviewSteps?.Count
                            != originalStepCount + 1)
                    {
                        throw new InvalidOperationException(
                            "P254 Recipe Manager refresh/reopen did not "
                            + "retain the saved Pipeline and Step.");
                    }

                    shellHost.OpenSamplePipelineForTest();
                    Pump(120);
                    if (shellHost.PipelineReviewStepCount
                            != originalStepCount + 1)
                    {
                        throw new InvalidOperationException(
                            "P254 Pipeline Review did not reopen the saved "
                            + "Step list.");
                    }

                    WaitForTaskWithPump(
                        shellHost.RunPipelineReviewForTestAsync(),
                        30000,
                        "P254 explicit Run Review");
                    Pump(120);
                    shellHost.SelectPipelineReviewStepForTest(
                        originalStepCount,
                        OpenVisionLab.Pipeline.Controls
                            .PipelineFlowPreviewMode.Output);
                    Pump(80);
                    if (!shellHost.HasPipelineReviewOutputPreview
                        || string.IsNullOrWhiteSpace(
                            shellHost.PipelineReviewResultSummaryText)
                        || !shellHost.PipelineReviewSelectedStepName
                            .Contains(
                                addedStep.Name,
                                StringComparison.Ordinal))
                    {
                        throw new InvalidOperationException(
                            "P254 explicit Run Review did not retain the "
                            + "added Step result/drawing. Selected="
                            + shellHost.PipelineReviewSelectedStepName
                            + " | Summary="
                            + shellHost.PipelineReviewResultSummaryText);
                    }
                },
                captureFloatingToolWindow: true,
                captureScreen: false);
        }
        finally
        {
            RecipeWorkspaceService.DeleteVisionWorkspace(recipeName);
        }
    }

    private static CaptureResult CaptureP251FailureCorrectionHandoff(
        string outputPath,
        bool rerunSameValidationSet)
    {
        OpenVisionLanguageService.SetLanguage(OpenVisionLanguage.English, false);
        string recipeName =
            "Smoke_FailureCorrection_" + Guid.NewGuid().ToString("N");
        const string pipelineName = "Failure_Correction_Pipeline";
        const string sampleName = "Public_Matching_DiePad_Good";
        VisionPipelineSampleCatalogItem sample = VisionPipelineSampleCatalogItem
            .LoadRunnable(VisionPipelineSampleCatalogSourceKind.Public)
            .FirstOrDefault(item => string.Equals(
                item?.SampleName,
                sampleName,
                StringComparison.Ordinal))
            ?? throw new InvalidOperationException(
                "P251 public sample is missing: " + sampleName);
        if (!SerializeHelper.TryLoadFromXmlFile(
                sample.PipelineFullPath,
                out VisionPipeline pipeline)
            || pipeline == null)
        {
            throw new InvalidOperationException(
                "P251 sample pipeline could not be loaded: "
                + sample.PipelineFullPath);
        }

        pipeline.Name = pipelineName;
        VisionPipelineStorage.Save(recipeName, pipeline);
        VisionPipelineStorage.SaveActivePipelineName(recipeName, pipelineName);

        OpenVisionShellHostView shellHost =
            CreateShellHost(recipeName, seedMainLayer: true);
        try
        {
            return CaptureWindowWithContent(
                shellHost,
                outputPath,
                1600,
                900,
                () =>
                {
                    ToggleButton recipeManagerButton =
                        FindNamedVisualChild<ToggleButton>(
                            shellHost,
                            "btnHostRecipeManager")
                        ?? throw new InvalidOperationException(
                            "P251 Recipe Manager button is missing.");
                    recipeManagerButton.IsChecked = true;
                    Pump(80);
                    ToggleButton advancedToggle =
                        FindNamedVisualChild<ToggleButton>(
                            shellHost,
                            "recipeAdvancedReviewToggle")
                        ?? throw new InvalidOperationException(
                            "P251 advanced review toggle is missing.");
                    advancedToggle.IsChecked = true;
                    TabItem pipelineTab =
                        FindNamedVisualChild<TabItem>(
                            shellHost,
                            "tabRecipePipeline")
                        ?? throw new InvalidOperationException(
                            "P251 Pipeline tab is missing.");
                    pipelineTab.IsSelected = true;
                    Pump(80);

                    OpenVisionRecipeSampleOption sampleOption =
                        shellHost.RecipeCommands.SampleOptions.FirstOrDefault(
                            option => string.Equals(
                                option?.SampleName,
                                sampleName,
                                StringComparison.Ordinal))
                        ?? throw new InvalidOperationException(
                            "P251 Recipe Manager sample selector did not expose "
                            + sampleName);
                    shellHost.RecipeCommands.SelectedSampleOption = sampleOption;
                    if (!shellHost.RecipeCommands
                        .CreateValidationSetFromSelectedPairForTest())
                    {
                        throw new InvalidOperationException(
                            "P251 could not save the catalog pair as a Validation Set: "
                            + shellHost.RecipeCommands.ValidationSuiteStatusText);
                    }

                    int previewRunsBefore = shellHost.NativePreviewRunCount;
                    int layerCountBefore = shellHost.LayerDocumentCount;
                    string workspaceLayerBefore = shellHost.WorkspaceLayerTitle;
                    string inputRouteBefore =
                        shellHost.ActiveNativeRouteInputLayerNameForTest;
                    string outputRouteBefore =
                        shellHost.ActiveNativeRouteOutputLayerNameForTest;

                    if (!shellHost.RecipeCommands.RunValidationSuiteCommand
                        .CanExecute(null))
                    {
                        throw new InvalidOperationException(
                            "P251 explicit Validation Set run was disabled: "
                            + shellHost.RecipeCommands.ValidationSuiteSummaryText);
                    }

                    shellHost.RecipeCommands.RunValidationSuiteCommand.Execute(null);
                    DateTime deadline = DateTime.UtcNow.AddSeconds(30);
                    while (DateTime.UtcNow < deadline)
                    {
                        Pump(10);
                        if (shellHost.RecipeCommands.RunValidationSuiteCommand
                                .CanExecute(null)
                            && shellHost.RecipeCommands.RecentBatchRunOptions.Any(
                                option => !string.IsNullOrWhiteSpace(
                                    option?.SummaryPath)))
                        {
                            break;
                        }
                    }

                    OpenVisionRecipeBatchRunOption savedRun =
                        shellHost.RecipeCommands.RecentBatchRunOptions
                            .FirstOrDefault(option =>
                                !string.IsNullOrWhiteSpace(option?.SummaryPath))
                        ?? throw new InvalidOperationException(
                            "P251 Validation Set run did not persist Run History.");
                    shellHost.RecipeCommands.SelectedRecentBatchRunOption = savedRun;
                    OpenVisionRecipeBatchSampleResultOption failedSample =
                        savedRun.SampleResults.FirstOrDefault(result =>
                            result != null
                            && result.HasExpectedOutcome
                            && !result.ExpectedSuccess
                            && !string.IsNullOrWhiteSpace(result.FailedStep))
                        ?? throw new InvalidOperationException(
                            "P251 retained pair did not expose an NG row with a linked failed Step.");
                    shellHost.RecipeCommands.SelectedRecentBatchSampleResultOption =
                        failedSample;
                    Pump(40);

                    TabItem runHistoryTab =
                        FindNamedVisualChild<TabItem>(
                            shellHost,
                            "tabRecipePipelineRunHistory")
                        ?? throw new InvalidOperationException(
                            "P251 Run History tab is missing.");
                    runHistoryTab.IsSelected = true;
                    Pump(80);
                    AssertVisibleAutomationIds(
                        shellHost,
                        "P251 explicit correction action",
                        "HostRecipeRunHistoryFailureActionPanel",
                        "HostRecipeRunHistoryPrepareCorrectionButton");
                    FrameworkElement correctionButton =
                        FindVisualChildren<FrameworkElement>(shellHost)
                            .First(element => string.Equals(
                                System.Windows.Automation.AutomationProperties
                                    .GetAutomationId(element),
                                "HostRecipeRunHistoryPrepareCorrectionButton",
                                StringComparison.Ordinal));
                    correctionButton.BringIntoView();
                    shellHost.UpdateLayout();
                    Pump(80);
                    SaveVisibleAutomationElementPng(
                        shellHost,
                        "HostRecipeRunHistoryFailureActionPanel",
                        outputPath,
                        "p251-failure-action-panel.png");
                    SaveVisibleAutomationElementPng(
                        shellHost,
                        "HostRecipeManagerPanel",
                        outputPath,
                        "p251-run-history-before-action.png");

                    string failedInputLayer =
                        shellHost.RecipeCommands.SelectedPipelinePreviewStep
                            ?.InputLayer
                        ?? "Main";
                    if (!shellHost.LoadImageIntoLayerForTest(
                            failedInputLayer,
                            sample.ImageFullPath))
                    {
                        throw new InvalidOperationException(
                            "P251 could not seed the pre-correction input image.");
                    }

                    shellHost.RecipeCommands.LoadSelectedStepParametersCommand
                        .Execute(null);
                    shellHost.RecipeCommands.MarkSelectedStepEditDirty();
                    using Bitmap beforeCancelledPrepare =
                        shellHost.GetLayerImageCloneForTest(failedInputLayer);
                    string beforeCancelledPrepareHash =
                        VisionPipelineScaleCalibrationStorage
                            .ComputeBitmapSha256(beforeCancelledPrepare);
                    shellHost.QueuePendingRecipeEditDecisionForTest(
                        OpenVisionRecipePendingEditDecision.Cancel);
                    shellHost.RecipeCommands
                        .PrepareSelectedRunFailureCorrectionCommand.Execute(null);
                    using Bitmap afterCancelledPrepare =
                        shellHost.GetLayerImageCloneForTest(failedInputLayer);
                    string afterCancelledPrepareHash =
                        VisionPipelineScaleCalibrationStorage
                            .ComputeBitmapSha256(afterCancelledPrepare);
                    if (!shellHost.RecipeCommands.IsSelectedStepEditDirty
                        || !string.Equals(
                            beforeCancelledPrepareHash,
                            afterCancelledPrepareHash,
                            StringComparison.OrdinalIgnoreCase)
                        || (!shellHost.RecipeCommands.StatusText.Contains(
                                "stopped",
                                StringComparison.OrdinalIgnoreCase)
                            && !shellHost.RecipeCommands.StatusText.Contains(
                                "중단",
                                StringComparison.Ordinal)))
                    {
                        throw new InvalidOperationException(
                            "P251 cancelled pending-edit transition changed the input image or discarded the edit.");
                    }

                    shellHost.QueuePendingRecipeEditDecisionForTest(
                        OpenVisionRecipePendingEditDecision.Discard);
                    if (!shellHost.RecipeCommands
                        .PrepareSelectedRunFailureCorrectionCommand
                        .CanExecute(null))
                    {
                        throw new InvalidOperationException(
                            "P251 prepare-correction command was disabled for the retained failed row.");
                    }

                    shellHost.RecipeCommands
                        .PrepareSelectedRunFailureCorrectionCommand.Execute(null);
                    Pump(100);

                    OpenVisionRecipePipelineStepPreview? selectedStep =
                        shellHost.RecipeCommands.SelectedPipelinePreviewStep;
                    TabItem xmlStepsTab =
                        FindNamedVisualChild<TabItem>(
                            shellHost,
                            "tabRecipePipelineStepSettings")
                        ?? throw new InvalidOperationException(
                            "P251 XML/Steps tab is missing.");
                    string failedSamplePath = !string.IsNullOrWhiteSpace(
                        failedSample.SampleImagePath)
                        ? failedSample.SampleImagePath
                        : failedSample.ReportPath;
                    using Bitmap expectedImage = new Bitmap(failedSamplePath);
                    using Bitmap loadedImage =
                        shellHost.GetLayerImageCloneForTest(
                            selectedStep?.InputLayer ?? string.Empty);
                    string expectedHash =
                        VisionPipelineScaleCalibrationStorage
                            .ComputeBitmapSha256(expectedImage);
                    string loadedHash =
                        VisionPipelineScaleCalibrationStorage
                            .ComputeBitmapSha256(loadedImage);
                    bool statusReady =
                        shellHost.RecipeCommands.StatusText.Contains(
                            "Correction preparation complete",
                            StringComparison.OrdinalIgnoreCase)
                        || shellHost.RecipeCommands.StatusText.Contains(
                            "실패 수정 준비 완료",
                            StringComparison.Ordinal);

                    if (selectedStep == null
                        || !failedSample.FailedStep.Contains(
                            selectedStep.Name,
                            StringComparison.Ordinal)
                        || shellHost.RecipeCommands.SelectedStepEditObject == null
                        || shellHost.RecipeCommands.IsSelectedStepEditDirty
                        || xmlStepsTab.IsSelected != true
                        || !string.Equals(
                            expectedHash,
                            loadedHash,
                            StringComparison.OrdinalIgnoreCase)
                        || !statusReady)
                    {
                        throw new InvalidOperationException(
                            "P251 did not prepare the failed sample, Step parameters, and XML/Steps editor together. "
                            + $"Selected={selectedStep?.Name}; Failed={failedSample.FailedStep}; "
                            + $"Edit={(shellHost.RecipeCommands.SelectedStepEditObject != null)}; "
                            + $"Dirty={shellHost.RecipeCommands.IsSelectedStepEditDirty}; "
                            + $"XmlTab={xmlStepsTab.IsSelected}; "
                            + $"Hash={string.Equals(expectedHash, loadedHash, StringComparison.OrdinalIgnoreCase)}; "
                            + shellHost.RecipeCommands.StatusText);
                    }

                    if (shellHost.NativePreviewRunCount != previewRunsBefore
                        || shellHost.LayerDocumentCount != layerCountBefore
                        || !string.Equals(
                            shellHost.WorkspaceLayerTitle,
                            workspaceLayerBefore,
                            StringComparison.Ordinal)
                        || !string.Equals(
                            shellHost.ActiveNativeRouteInputLayerNameForTest,
                            inputRouteBefore,
                            StringComparison.Ordinal)
                        || !string.Equals(
                            shellHost.ActiveNativeRouteOutputLayerNameForTest,
                            outputRouteBefore,
                            StringComparison.Ordinal))
                    {
                        throw new InvalidOperationException(
                            "P251 correction preparation changed Preview/Run, layers, workspace selection, or routing.");
                    }

                    if (rerunSameValidationSet)
                    {
                        string sourceSetName =
                            savedRun.RunSummary?.SuiteName
                            ?? string.Empty;
                        OpenVisionRecipePairRunSummary pairBeforeRerun =
                            shellHost.RecipeCommands.LatestPairRunSummary;
                        if (!ContainsAny(
                                shellHost.RecipeCommands.CorrectedOutputRerunText,
                                "동일 세트 재검사",
                                "Rerun same set")
                            || !shellHost.RecipeCommands
                                .CorrectedOutputRerunToolTipText.Contains(
                                    sourceSetName,
                                    StringComparison.Ordinal)
                            || !shellHost.RecipeCommands
                                .RerunCorrectedOutputCommand.CanExecute(null))
                        {
                            throw new InvalidOperationException(
                                "P252 corrected-output action did not resolve the source Validation Set. "
                                + $"Text='{shellHost.RecipeCommands.CorrectedOutputRerunText}', "
                                + $"Tip='{shellHost.RecipeCommands.CorrectedOutputRerunToolTipText}', "
                                + $"Set='{sourceSetName}'.");
                        }

                        FrameworkElement rerunButton =
                            FindVisualChildren<FrameworkElement>(shellHost)
                                .FirstOrDefault(element => string.Equals(
                                    AutomationProperties.GetAutomationId(element),
                                    "HostRecipeCorrectedOutputRerunButton",
                                    StringComparison.Ordinal))
                            ?? throw new InvalidOperationException(
                                "P252 corrected-output rerun button is missing.");
                        rerunButton.BringIntoView();
                        shellHost.UpdateLayout();
                        Pump(80);
                        SaveVisibleAutomationElementPng(
                            shellHost,
                            "HostRecipeManagerPanel",
                            outputPath,
                            "p252-same-validation-rerun-action.png");

                        int recentRunCountBeforeApply =
                            shellHost.RecipeCommands.RecentBatchRunOptions.Count;
                        shellHost.RecipeCommands
                            .ApplySelectedStepParametersCommand.Execute(null);
                        Pump(100);
                        if (shellHost.NativePreviewRunCount != previewRunsBefore
                            || shellHost.LayerDocumentCount != layerCountBefore
                            || shellHost.RecipeCommands
                                .RecentBatchRunOptions.Count
                                != recentRunCountBeforeApply
                            || !ReferenceEquals(
                                shellHost.RecipeCommands.LatestPairRunSummary,
                                pairBeforeRerun))
                        {
                            throw new InvalidOperationException(
                                "P252 no-op XML apply executed a run or changed layers.");
                        }

                        HashSet<string> previousSummaryPaths =
                            shellHost.RecipeCommands.RecentBatchRunOptions
                                .Select(option => option?.SummaryPath ?? string.Empty)
                                .Where(path => !string.IsNullOrWhiteSpace(path))
                                .ToHashSet(StringComparer.OrdinalIgnoreCase);
                        shellHost.RecipeCommands
                            .RerunCorrectedOutputCommand.Execute(null);
                        DateTime rerunDeadline = DateTime.UtcNow.AddSeconds(30);
                        OpenVisionRecipeBatchRunOption? correctedRun = null;
                        while (DateTime.UtcNow < rerunDeadline)
                        {
                            Pump(10);
                            correctedRun = shellHost.RecipeCommands
                                .RecentBatchRunOptions
                                .FirstOrDefault(option =>
                                    !string.IsNullOrWhiteSpace(option?.SummaryPath)
                                    && !previousSummaryPaths.Contains(
                                        option.SummaryPath));
                            if (correctedRun != null
                                && shellHost.RecipeCommands
                                    .RunValidationSuiteCommand.CanExecute(null))
                            {
                                break;
                            }
                        }

                        if (correctedRun?.RunSummary == null
                            || !string.Equals(
                                correctedRun.RunSummary.SuiteKind,
                                "LocalValidationSet",
                                StringComparison.Ordinal)
                            || !string.Equals(
                                correctedRun.RunSummary.SuiteName,
                                sourceSetName,
                                StringComparison.Ordinal)
                            || correctedRun.SampleResults.Count != 2
                            || !ReferenceEquals(
                                shellHost.RecipeCommands.LatestPairRunSummary,
                                pairBeforeRerun)
                            || !shellHost.RecipeCommands.IsLocalValidationSetSelected
                            || !string.Equals(
                                shellHost.RecipeCommands
                                    .SelectedValidationSetOption?.Name,
                                sourceSetName,
                                StringComparison.Ordinal)
                            || shellHost.NativePreviewRunCount != previewRunsBefore
                            || shellHost.LayerDocumentCount != layerCountBefore
                            || !string.Equals(
                                shellHost.ActiveNativeRouteInputLayerNameForTest,
                                inputRouteBefore,
                                StringComparison.Ordinal)
                            || !string.Equals(
                                shellHost.ActiveNativeRouteOutputLayerNameForTest,
                                outputRouteBefore,
                                StringComparison.Ordinal)
                            || !string.Equals(
                                shellHost.WorkspaceLayerTitle,
                                workspaceLayerBefore,
                                StringComparison.Ordinal))
                        {
                            throw new InvalidOperationException(
                                "P252 did not persist a second run of the same Validation Set without pair/Preview/layer/route side effects. "
                                + $"Run='{correctedRun?.RunSummary?.SuiteKind}/{correctedRun?.RunSummary?.SuiteName}', "
                                + $"Rows={correctedRun?.SampleResults.Count}, "
                                + $"Set='{shellHost.RecipeCommands.SelectedValidationSetOption?.Name}', "
                                + $"PairChanged={!ReferenceEquals(shellHost.RecipeCommands.LatestPairRunSummary, pairBeforeRerun)}.");
                        }

                        shellHost.RecipeCommands.SelectedRecentBatchRunOption =
                            correctedRun;
                        OpenVisionRecipeBatchRunOption baselineRun =
                            shellHost.RecipeCommands.RecentBatchRunOptions
                                .First(option => string.Equals(
                                    option?.SummaryPath,
                                    savedRun.SummaryPath,
                                    StringComparison.OrdinalIgnoreCase));
                        shellHost.RecipeCommands
                            .SelectedBenchmarkBaselineRunOption = baselineRun;
                        if (shellHost.RecipeCommands
                                .RecentBatchRunComparisonRows.Count != 2)
                        {
                            throw new InvalidOperationException(
                                "P252 same-set rerun did not expose the two source rows for baseline comparison.");
                        }

                        if (!OpenVisionRecipeValidationSetStorage.TryLoad(
                                recipeName,
                                out OpenVisionRecipeValidationSetDocument document,
                                out string loadError))
                        {
                            throw new InvalidOperationException(
                                "P252 could not load the Validation Set for missing-source rejection: "
                                + loadError);
                        }

                        OpenVisionRecipeValidationSet removedSet =
                            document.Sets.First(set => string.Equals(
                                set?.Name,
                                sourceSetName,
                                StringComparison.Ordinal));
                        document.Sets.Remove(removedSet);
                        if (!OpenVisionRecipeValidationSetStorage.TrySave(
                                recipeName,
                                document,
                                out string removeError))
                        {
                            throw new InvalidOperationException(
                                "P252 could not stage a missing source Validation Set: "
                                + removeError);
                        }

                        shellHost.RecipeCommands.RefreshOptions();
                        shellHost.RecipeCommands.SelectedRecentBatchRunOption =
                            shellHost.RecipeCommands.RecentBatchRunOptions
                                .First(option => string.Equals(
                                    option?.SummaryPath,
                                    correctedRun.SummaryPath,
                                    StringComparison.OrdinalIgnoreCase));
                        if (shellHost.RecipeCommands
                                .RerunCorrectedOutputCommand.CanExecute(null)
                            || !shellHost.RecipeCommands
                                .CorrectedOutputRerunToolTipText.Contains(
                                    sourceSetName,
                                    StringComparison.Ordinal))
                        {
                            throw new InvalidOperationException(
                                "P252 missing source set silently fell back to the catalog pair.");
                        }

                        document.Sets.Add(removedSet);
                        if (!OpenVisionRecipeValidationSetStorage.TrySave(
                                recipeName,
                                document,
                                out string restoreError))
                        {
                            throw new InvalidOperationException(
                                "P252 could not restore the source Validation Set: "
                                + restoreError);
                        }

                        shellHost.RecipeCommands.RefreshOptions();
                        string correctedSummaryPath = correctedRun.SummaryPath;
                        correctedRun = shellHost.RecipeCommands
                            .RecentBatchRunOptions
                            .First(option => string.Equals(
                                option?.SummaryPath,
                                correctedSummaryPath,
                                StringComparison.OrdinalIgnoreCase));
                        shellHost.RecipeCommands.SelectedRecentBatchRunOption =
                            correctedRun;
                        shellHost.RecipeCommands
                            .SelectedBenchmarkBaselineRunOption =
                            shellHost.RecipeCommands.RecentBatchRunOptions
                                .First(option => string.Equals(
                                    option?.SummaryPath,
                                    savedRun.SummaryPath,
                                    StringComparison.OrdinalIgnoreCase));
                        pipelineTab.IsSelected = true;
                        runHistoryTab.IsSelected = true;
                        Pump(100);
                        FrameworkElement comparisonPanel =
                            FindVisualChildren<FrameworkElement>(shellHost)
                                .FirstOrDefault(element => string.Equals(
                                    AutomationProperties.GetAutomationId(element),
                                    "HostRecipeRecentBatchRunComparisonPanel",
                                    StringComparison.Ordinal))
                            ?? throw new InvalidOperationException(
                                "P252 Run History comparison panel is missing.");
                        comparisonPanel.BringIntoView();
                        shellHost.UpdateLayout();
                        Pump(100);
                        SaveVisibleAutomationElementPng(
                            shellHost,
                            "HostRecipeManagerPanel",
                            outputPath,
                            "p252-same-validation-rerun-history.png");
                        return;
                    }

                    pipelineTab.IsSelected = true;
                    xmlStepsTab.IsSelected = true;
                    Pump(100);

                    AssertVisibleAutomationIds(
                        shellHost,
                        "P251 failure correction handoff",
                        "HostRecipeManagerPanel",
                        "HostRecipePipelineStepSettingsTab",
                        "HostRecipePipelineSelectedStepDetailPanel",
                        "HostRecipeSelectedStepPropertyGridHost");
                    FrameworkElement editor =
                        FindVisualChildren<FrameworkElement>(shellHost)
                            .FirstOrDefault(element => string.Equals(
                                System.Windows.Automation.AutomationProperties
                                    .GetAutomationId(element),
                                "HostRecipeSelectedStepPropertyGridHost",
                                StringComparison.Ordinal))
                        ?? throw new InvalidOperationException(
                            "P251 selected-Step editor is missing.");
                    editor.BringIntoView();
                    shellHost.UpdateLayout();
                    Pump(100);
                },
                captureFloatingToolWindow: false,
                captureScreen: true);
        }
        finally
        {
            RecipeWorkspaceService.DeleteVisionWorkspace(recipeName);
        }
    }

    private static void AssertApprovedValidationVariants()
    {
        Dictionary<string, (string Minimum, string Maximum)> approved =
            new Dictionary<string, (string Minimum, string Maximum)>(StringComparer.Ordinal)
            {
                ["Product_Field_FilmStripe_SurfaceReview"] = ("3", "8"),
                ["Product_Field_TexturedRoller_SurfaceReview"] = ("1", "4")
            };
        Dictionary<string, VisionPipelineSampleCatalogItem> samples =
            VisionPipelineSampleCatalogItem.LoadRunnable(VisionPipelineSampleCatalogSourceKind.Product)
                .Where(item => item != null && approved.ContainsKey(item.SampleName))
                .ToDictionary(item => item.SampleName, StringComparer.Ordinal);
        foreach (KeyValuePair<string, (string Minimum, string Maximum)> variant in approved)
        {
            if (!samples.TryGetValue(variant.Key, out VisionPipelineSampleCatalogItem? sample)
                || sample == null
                || !string.Equals(sample.ExpectedMetricName, "ResultCount", StringComparison.Ordinal)
                || !string.Equals(sample.ExpectedMetricMinimum, variant.Value.Minimum, StringComparison.Ordinal)
                || !string.Equals(sample.ExpectedMetricMaximum, variant.Value.Maximum, StringComparison.Ordinal))
            {
                throw new InvalidOperationException(
                    "Approved Validation Variant is missing or its catalog gate changed: " + variant.Key);
            }

            VisionPipelineSampleCheckResult result =
                VisionPipelineSampleCheckService.RunSampleCheckSafe(sample);
            if (!result.ExecutionCompleted || !result.Success)
            {
                throw new InvalidOperationException(
                    "Approved Validation Variant failed its existing deterministic pipeline/gate: "
                    + variant.Key
                    + " | "
                    + result.Message
                    + " | "
                    + result.MetricReviewText);
            }
        }
    }

    private static VisionPipelineBatchSampleRunResult CreateExplicitJudgmentProbe(
        string sampleName,
        bool expectedSuccess,
        bool actualSuccess)
    {
        VisionPipelineBatchSampleRunResult result = new VisionPipelineBatchSampleRunResult
        {
            SampleName = sampleName ?? string.Empty,
            PairRole = expectedSuccess
                ? VisionPipelineBatchOutcomeContract.OkOutcome
                : VisionPipelineBatchOutcomeContract.NgOutcome,
            ExpectedText = "ExpectedActual: Expected "
                + VisionPipelineBatchOutcomeContract.ToOutcome(expectedSuccess),
            Success = expectedSuccess == actualSuccess,
            Status = expectedSuccess == actualSuccess ? "OK" : "NG"
        };
        VisionPipelineBatchOutcomeContract.Apply(
            result,
            executionCompleted: true,
            actualSuccess,
            hasJudgment: true,
            expectedSuccess,
            judgmentCorrect: expectedSuccess == actualSuccess);
        return result;
    }

    private static CaptureResult CaptureShellHostRecipeQualifiedSnapshot(
        string outputPath)
    {
        OpenVisionLanguageService.SetLanguage(OpenVisionLanguage.English, false);
        string suffix = Guid.NewGuid().ToString("N");
        string recipeName = "Smoke_Qualified_" + suffix;
        string workingRecipeName = "Smoke_Qualified_Work_" + suffix;
        const string pipelineName = "Qualified_Locator_Pipeline";
        const string validationSetName = "Qualified Locator Evidence";
        VisionPipelineSampleCatalogItem sample =
            VisionPipelineSampleCatalogItem.LoadRunnable()
                .FirstOrDefault(item => item != null && item.CanOpen)
            ?? throw new InvalidOperationException(
                "No runnable image was available for qualified Snapshot smoke.");
        VisionPipelineStorage.Save(
            recipeName,
            RecipeContextFixture.CreatePipeline(pipelineName, 1));
        VisionPipelineStorage.SaveActivePipelineName(recipeName, pipelineName);

        List<string> createdSnapshotIds = new();
        string openedEvidenceDirectory = string.Empty;
        bool allowLifecycle = false;
        OpenVisionShellHostView shellHost =
            CreateShellHost(recipeName, seedMainLayer: false);
        shellHost.QualifiedSnapshotLifecycleConfirmationForTest =
            (_, _, _) => allowLifecycle;
        shellHost.QualifiedSnapshotEvidenceOpenerForTest = directory =>
        {
            openedEvidenceDirectory = directory;
            return Directory.Exists(directory);
        };

        try
        {
            return CaptureWindowWithContent(
                shellHost,
                outputPath,
                1600,
                900,
                () =>
                {
                    int previewRunsBefore = shellHost.NativePreviewRunCount;
                    int layerCountBefore = shellHost.LayerDocumentCount;
                    string workspaceLayerBefore = shellHost.WorkspaceLayerTitle;
                    string inputRouteBefore =
                        shellHost.ActiveNativeRouteInputLayerNameForTest;
                    string outputRouteBefore =
                        shellHost.ActiveNativeRouteOutputLayerNameForTest;

                    OpenVisionRecipeValidationSuiteScopeOption localScope =
                        shellHost.RecipeCommands.ValidationSuiteScopeOptions
                            .First(option => string.Equals(
                                option.Key,
                                OpenVisionRecipeValidationSuiteScopeOption
                                    .LocalValidationSetKey,
                                StringComparison.OrdinalIgnoreCase));
                    shellHost.RecipeCommands.SelectedValidationSuiteScopeOption =
                        localScope;
                    shellHost.RecipeCommands.NewValidationSetName =
                        validationSetName;
                    shellHost.RecipeCommands.CreateValidationSetCommand
                        .Execute(null);
                    if (!shellHost.RecipeCommands.AddValidationSetImagesForTest(
                            OpenVisionRecipeValidationSetImage.ExpectedOk,
                            new[] { sample.ImageFullPath },
                            "Frozen locator replay"))
                    {
                        throw new InvalidOperationException(
                            "Qualified Snapshot validation image registration failed.");
                    }

                    if (!shellHost.RecipeCommands.RunValidationSuiteCommand
                        .CanExecute(null))
                    {
                        throw new InvalidOperationException(
                            "Qualified Snapshot Local Validation Set run was disabled: "
                            + shellHost.RecipeCommands.ValidationSuiteSummaryText);
                    }

                    shellHost.RecipeCommands.RunValidationSuiteCommand
                        .Execute(null);
                    DateTime deadline = DateTime.UtcNow.AddSeconds(30);
                    while (DateTime.UtcNow < deadline)
                    {
                        Pump(10);
                        if (shellHost.RecipeCommands.RunValidationSuiteCommand
                                .CanExecute(null)
                            && shellHost.RecipeCommands.RecentBatchRunOptions
                                .Any(option =>
                                    !string.IsNullOrWhiteSpace(
                                        option?.SummaryPath)))
                        {
                            break;
                        }
                    }

                    OpenVisionRecipeBatchRunOption savedRun =
                        shellHost.RecipeCommands.RecentBatchRunOptions
                            .FirstOrDefault(option =>
                                !string.IsNullOrWhiteSpace(option?.SummaryPath))
                        ?? throw new InvalidOperationException(
                            "Qualified Snapshot Local Validation Set did not finish.");
                    VisionPipelineBatchRunSummary savedSummary =
                        VisionPipelineBatchRunSummaryStorage.Load(
                            savedRun.SummaryPath)
                        ?? throw new InvalidOperationException(
                            "Qualified Snapshot summary could not be reloaded.");
                    if (!string.Equals(
                            savedSummary.SuiteKind,
                            "LocalValidationSet",
                            StringComparison.Ordinal)
                        || savedSummary.TotalCount != 1
                        || savedSummary.JudgmentCorrectCount != 1
                        || savedSummary.FalseAcceptCount != 0
                        || savedSummary.FalseRejectCount != 0
                        || savedSummary.ExecutionErrorCount != 0)
                    {
                        throw new InvalidOperationException(
                            "Locator qualification fixture did not produce one "
                            + "completed correct judgment.");
                    }

                    shellHost.RecipeCommands.SelectedRecentBatchRunOption =
                        savedRun;
                    shellHost.RecipeCommands
                        .SelectedQualificationScopeOption =
                        shellHost.RecipeCommands.QualificationScopeOptions
                            .Last();
                    shellHost.RecipeCommands.QualificationNote =
                        "One frozen Expected-OK locator replay; no unseen-data claim.";

                    shellHost.RecipeCommands.SelectedPipelinePreviewStep =
                        shellHost.RecipeCommands.SelectedRecipeSummary
                            .PipelinePreviewSteps.Single();
                    shellHost.RecipeCommands.LoadSelectedStepParametersCommand
                        .Execute(null);
                    if (shellHost.RecipeCommands.SelectedStepEditObject == null)
                    {
                        throw new InvalidOperationException(
                            "Qualified Snapshot dirty-edit probe did not load.");
                    }

                    shellHost.RecipeCommands
                        .MarkSelectedStepEditDirtyForQualificationTest();
                    Pump(40);
                    if (!shellHost.RecipeCommands.IsSelectedStepEditDirty
                        || shellHost.RecipeCommands.CreateQualifiedSnapshotCommand
                            .CanExecute(null)
                        || !shellHost.RecipeCommands
                            .QualifiedSnapshotPreflightText.Contains(
                                "pending Step edit",
                                StringComparison.OrdinalIgnoreCase)
                            && !shellHost.RecipeCommands
                                .QualifiedSnapshotPreflightText.Contains(
                                    "저장하지 않은 Step 편집",
                                    StringComparison.Ordinal))
                    {
                        throw new InvalidOperationException(
                            "Pending Step edit did not fail-close Snapshot creation. "
                            + $"Dirty={shellHost.RecipeCommands.IsSelectedStepEditDirty}, "
                            + $"CanCreate={shellHost.RecipeCommands.CreateQualifiedSnapshotCommand.CanExecute(null)}, "
                            + $"Preflight='{shellHost.RecipeCommands.QualifiedSnapshotPreflightText}'.");
                    }

                    shellHost.RecipeCommands
                        .DiscardSelectedStepEditForQualificationTest();
                    if (!shellHost.RecipeCommands.CreateQualifiedSnapshotCommand
                        .CanExecute(null))
                    {
                        throw new InvalidOperationException(
                            "Exact qualified Snapshot preconditions remained disabled: "
                            + shellHost.RecipeCommands
                                .QualifiedSnapshotPreflightText
                            + $" | Set='{shellHost.RecipeCommands.SelectedValidationSetOption?.Name}', "
                            + $"SetPipeline='{shellHost.RecipeCommands.SelectedValidationSetOption?.Set?.PipelineName}', "
                            + $"RunSuite='{shellHost.RecipeCommands.SelectedRecentBatchRunOption?.RunSummary?.SuiteName}', "
                            + $"Pipeline='{shellHost.RecipeCommands.SelectedPipelineOption?.PipelineName}'.");
                    }

                    shellHost.RecipeCommands.CreateQualifiedSnapshotCommand
                        .Execute(null);
                    OpenVisionRecipeQualifiedSnapshotOption first =
                        shellHost.RecipeCommands.SelectedQualifiedSnapshotOption
                        ?? throw new InvalidOperationException(
                            "Created qualified Snapshot was not selected. Status='"
                            + shellHost.RecipeCommands
                                .QualifiedSnapshotStatusText
                            + "'.");
                    createdSnapshotIds.Add(first.SnapshotId);
                    if (!first.PayloadIntegrityValid
                        || !first.RuntimeFingerprintMatches
                        || !string.Equals(
                            first.LifecycleState,
                            "Qualified",
                            StringComparison.Ordinal))
                    {
                        throw new InvalidOperationException(
                            "Created qualified Snapshot did not reload valid.");
                    }

                    shellHost.RecipeCommands.VerifyQualifiedSnapshotCommand
                        .Execute(null);
                    shellHost.RecipeCommands
                        .OpenQualifiedSnapshotEvidenceCommand.Execute(null);
                    if (string.IsNullOrWhiteSpace(openedEvidenceDirectory)
                        || !Directory.Exists(openedEvidenceDirectory))
                    {
                        throw new InvalidOperationException(
                            "Qualified Snapshot evidence folder was not resolved.");
                    }

                    shellHost.RecipeCommands
                        .QualifiedSnapshotWorkingCopyName = workingRecipeName;
                    shellHost.RecipeCommands
                        .CreateQualifiedSnapshotWorkingCopyCommand.Execute(null);
                    if (!File.Exists(
                            RecipeWorkspaceService.GetVisionPipelinePath(
                                workingRecipeName,
                                pipelineName))
                        || File.Exists(
                            OpenVisionRecipeValidationSetStorage.GetPath(
                                workingRecipeName))
                        || Directory.Exists(Path.Combine(
                            RecipeWorkspaceService.GetRecipeWorkspaceDirectory(
                                workingRecipeName),
                            "QUALIFIED_RECIPE")))
                    {
                        throw new InvalidOperationException(
                            "Working copy did not preserve the editable-only boundary.");
                    }

                    shellHost.RecipeCommands.QualificationNote =
                        "Successor replay with an explicit operator note change.";
                    shellHost.RecipeCommands
                        .QualifiedSnapshotLifecycleReason =
                        "Reviewed successor evidence.";
                    allowLifecycle = false;
                    int snapshotCountBeforeCancel =
                        shellHost.RecipeCommands.QualifiedSnapshotOptions.Count;
                    shellHost.RecipeCommands.SupersedeQualifiedSnapshotCommand
                        .Execute(null);
                    if (shellHost.RecipeCommands.QualifiedSnapshotOptions.Count
                            != snapshotCountBeforeCancel
                        || !string.Equals(
                            shellHost.RecipeCommands
                                .SelectedQualifiedSnapshotOption?.SnapshotId,
                            first.SnapshotId,
                            StringComparison.Ordinal))
                    {
                        throw new InvalidOperationException(
                            "Cancelled supersede changed Snapshot state.");
                    }

                    allowLifecycle = true;
                    shellHost.RecipeCommands.SupersedeQualifiedSnapshotCommand
                        .Execute(null);
                    OpenVisionRecipeQualifiedSnapshotOption successor =
                        shellHost.RecipeCommands.SelectedQualifiedSnapshotOption
                        ?? throw new InvalidOperationException(
                            "Successor Snapshot was not selected.");
                    if (string.Equals(
                            successor.SnapshotId,
                            first.SnapshotId,
                            StringComparison.Ordinal))
                    {
                        throw new InvalidOperationException(
                            "Supersede reused the predecessor identity.");
                    }

                    createdSnapshotIds.Add(successor.SnapshotId);
                    OpenVisionRecipeQualifiedSnapshotOption predecessor =
                        shellHost.RecipeCommands.QualifiedSnapshotOptions
                            .Single(option => string.Equals(
                                option.SnapshotId,
                                first.SnapshotId,
                                StringComparison.Ordinal));
                    if (!string.Equals(
                            predecessor.LifecycleState,
                            "Superseded",
                            StringComparison.Ordinal)
                        || !string.Equals(
                            successor.LifecycleState,
                            "Qualified",
                            StringComparison.Ordinal))
                    {
                        throw new InvalidOperationException(
                            "Supersede lifecycle did not reload exactly.");
                    }

                    shellHost.RecipeCommands
                        .QualifiedSnapshotLifecycleReason =
                        "Operator revoked successor after review.";
                    shellHost.RecipeCommands.RevokeQualifiedSnapshotCommand
                        .Execute(null);
                    if (!string.Equals(
                            shellHost.RecipeCommands
                                .SelectedQualifiedSnapshotOption
                                ?.LifecycleState,
                            "Revoked",
                            StringComparison.Ordinal))
                    {
                        throw new InvalidOperationException(
                            "Revoke lifecycle did not reload exactly.");
                    }

                    if (shellHost.NativePreviewRunCount != previewRunsBefore
                        || shellHost.LayerDocumentCount != layerCountBefore
                        || !string.Equals(
                            shellHost.WorkspaceLayerTitle,
                            workspaceLayerBefore,
                            StringComparison.Ordinal)
                        || !string.Equals(
                            shellHost.ActiveNativeRouteInputLayerNameForTest,
                            inputRouteBefore,
                            StringComparison.Ordinal)
                        || !string.Equals(
                            shellHost.ActiveNativeRouteOutputLayerNameForTest,
                            outputRouteBefore,
                            StringComparison.Ordinal))
                    {
                        throw new InvalidOperationException(
                            "Qualified Snapshot actions changed Preview/Run, "
                            + "layers, workspace, or routing.");
                    }

                    ToggleButton recipeManagerButton =
                        FindNamedVisualChild<ToggleButton>(
                            shellHost,
                            "btnHostRecipeManager")
                        ?? throw new InvalidOperationException(
                            "Recipe Manager button was not found.");
                    recipeManagerButton.IsChecked = true;
                    Pump(80);
                    FindNamedVisualChild<ToggleButton>(
                        shellHost,
                        "recipeAdvancedReviewToggle")!.IsChecked = true;
                    Pump(60);
                    FindNamedVisualChild<TabItem>(
                        shellHost,
                        "tabRecipePipeline")!.IsSelected = true;
                    Pump(60);
                    FindNamedVisualChild<TabItem>(
                        shellHost,
                        "tabRecipePipelineRunHistory")!.IsSelected = true;
                    Pump(100);

                    AssertVisibleAutomationIds(
                        shellHost,
                        "WPF qualified Recipe Snapshot",
                        "HostRecipeQualifiedSnapshotPanel",
                        "HostRecipeQualificationScopeCombo",
                        "HostRecipeQualificationNoteTextBox",
                        "HostRecipeCreateQualifiedSnapshotButton",
                        "HostRecipeQualifiedSnapshotPreflight",
                        "HostRecipeQualifiedSnapshotCombo",
                        "HostRecipeVerifyQualifiedSnapshotButton",
                        "HostRecipeOpenQualifiedSnapshotEvidenceButton",
                        "HostRecipeQualifiedSnapshotWorkingCopyNameTextBox",
                        "HostRecipeCreateQualifiedSnapshotWorkingCopyButton",
                        "HostRecipeQualifiedSnapshotLifecycleReasonTextBox",
                        "HostRecipeSupersedeQualifiedSnapshotButton",
                        "HostRecipeRevokeQualifiedSnapshotButton",
                        "HostRecipeQualifiedSnapshotStatus");
                    FrameworkElement panel =
                        FindVisualChildren<FrameworkElement>(shellHost)
                            .First(element => string.Equals(
                                AutomationProperties.GetAutomationId(element),
                                "HostRecipeQualifiedSnapshotPanel",
                                StringComparison.Ordinal));
                    panel.BringIntoView();
                    shellHost.UpdateLayout();
                    Pump(100);

                    string evidenceDirectory = Path.Combine(
                        Path.GetDirectoryName(outputPath) ?? ".",
                        Path.GetFileNameWithoutExtension(outputPath)
                            + ".evidence");
                    Directory.CreateDirectory(evidenceDirectory);
                    File.Copy(
                        Path.Combine(
                            openedEvidenceDirectory,
                            QualifiedRecipeSnapshotStore
                                .SnapshotManifestFileName),
                        Path.Combine(evidenceDirectory, "snapshot.xml"),
                        overwrite: true);
                    File.Copy(
                        Path.Combine(
                            openedEvidenceDirectory,
                            QualifiedRecipeSnapshotStore.InventoryFileName),
                        Path.Combine(evidenceDirectory, "inventory.sha256"),
                        overwrite: true);
                    File.WriteAllLines(
                        Path.Combine(
                            evidenceDirectory,
                            "qualified-snapshot-ui-contract.txt"),
                        new[]
                        {
                            "Predecessor=" + first.SnapshotId,
                            "PredecessorState=Superseded",
                            "Successor=" + successor.SnapshotId,
                            "SuccessorState=Revoked",
                            "PayloadIntegrityValid="
                                + successor.PayloadIntegrityValid,
                            "RuntimeFingerprintMatches="
                                + successor.RuntimeFingerprintMatches,
                            "WorkingRecipe=" + workingRecipeName,
                            "WorkingCopyHasQualification=false",
                            "CancelledSupersedeNoChange=true",
                            "EvidenceFolderResolved=true",
                            "PreviewRunCountUnchanged=true",
                            "LayerCountUnchanged=true",
                            "WorkspaceLayerUnchanged=true",
                            "RoutesUnchanged=true"
                        });
                },
                captureFloatingToolWindow: false,
                captureScreen: true);
        }
        finally
        {
            RecipeWorkspaceService.DeleteVisionWorkspace(recipeName);
            RecipeWorkspaceService.DeleteVisionWorkspace(workingRecipeName);
            string qualifiedRoot =
                AppPathService.QualifiedRecipeRootDirectory;
            foreach (string snapshotId in createdSnapshotIds
                .Where(QualifiedRecipeSnapshotPreflight.IsSha256)
                .Distinct(StringComparer.Ordinal))
            {
                string snapshotDirectory =
                    Path.Combine(qualifiedRoot, snapshotId);
                if (Directory.Exists(snapshotDirectory))
                {
                    Directory.Delete(snapshotDirectory, recursive: true);
                }

                string lifecycleDirectory = Path.Combine(
                    qualifiedRoot,
                    "lifecycle",
                    snapshotId + ".events");
                if (Directory.Exists(lifecycleDirectory))
                {
                    Directory.Delete(lifecycleDirectory, recursive: true);
                }
            }
        }
    }

    private static CaptureResult CaptureShellHostRecipeLocalValidationDataset(
        string outputPath,
        bool openDrawingEvidence = false,
        bool captureReviewQueue = false)
    {
        string repoRoot = Directory.GetCurrentDirectory();
        ValidationDatasetSmokeConfiguration configuration =
            ValidationDatasetSmokeConfiguration.LoadFromEnvironment(repoRoot);
        string recipeName = "Smoke_LocalValidationDataset_" + Guid.NewGuid().ToString("N");
        string pipelinePath = RecipeWorkspaceService.GetVisionPipelinePath(recipeName, configuration.PipelineName);
        Directory.CreateDirectory(Path.GetDirectoryName(pipelinePath)!);
        File.WriteAllText(pipelinePath, configuration.PipelineXml);
        VisionPipelineStorage.SaveActivePipelineName(recipeName, configuration.PipelineName);

        OpenVisionShellHostView shellHost = CreateShellHost(recipeName, seedMainLayer: false);
        try
        {
            return CaptureWindowWithContent(shellHost, outputPath, 1600, 900, () =>
            {
                string artifactDirectory = Path.GetDirectoryName(outputPath) ?? repoRoot;
                Directory.CreateDirectory(artifactDirectory);
                string progressPath = Path.Combine(artifactDirectory, "progress.txt");
                shellHost.RecipeCommands.SelectLocalValidationSetScope();
                shellHost.RecipeCommands.NewValidationSetName = configuration.SuiteName;
                if (!shellHost.RecipeCommands.CreateValidationSetCommand.CanExecute(null))
                {
                    throw new InvalidOperationException("Dataset validation set create command was disabled.");
                }

                shellHost.RecipeCommands.CreateValidationSetCommand.Execute(null);
                string[] okPaths = Directory.GetFiles(configuration.OkFolder)
                    .OrderBy(path => path, StringComparer.OrdinalIgnoreCase)
                    .Take(configuration.MaximumPerRole)
                    .ToArray();
                string[] ngPaths = Directory.GetFiles(configuration.NgFolder)
                    .OrderBy(path => path, StringComparer.OrdinalIgnoreCase)
                    .Take(configuration.MaximumPerRole)
                    .ToArray();
                if (!shellHost.RecipeCommands.AddValidationSetImagesForTest(
                        OpenVisionRecipeValidationSetImage.ExpectedOk,
                        okPaths,
                        "Provided OK folder")
                    || !shellHost.RecipeCommands.AddValidationSetImagesForTest(
                        OpenVisionRecipeValidationSetImage.ExpectedNg,
                        ngPaths,
                        "Provided NG folder"))
                {
                    throw new InvalidOperationException(
                        "Dataset folder registration failed. " + shellHost.RecipeCommands.ValidationSuiteStatusText);
                }

                int okCount = shellHost.RecipeCommands.SelectedValidationSetOption?.OkCount ?? 0;
                int ngCount = shellHost.RecipeCommands.SelectedValidationSetOption?.NgCount ?? 0;
                int expectedOkCount = okPaths.Length;
                int expectedNgCount = ngPaths.Length;
                if (okCount != expectedOkCount
                    || ngCount != expectedNgCount
                    || !shellHost.RecipeCommands.RunValidationSuiteCommand.CanExecute(null))
                {
                    throw new InvalidOperationException(
                        $"Dataset registration expected OK {expectedOkCount} / NG {expectedNgCount}, actual OK {okCount} / NG {ngCount}. "
                        + shellHost.RecipeCommands.ValidationSetSelectionSummaryText);
                }

                ValidationDatasetExecutionProgress.Run(
                    progressPath,
                    okCount,
                    ngCount,
                    canExecute: () => shellHost.RecipeCommands.RunValidationSuiteCommand.CanExecute(null),
                    execute: () => shellHost.RecipeCommands.RunValidationSuiteCommand.Execute(null),
                    statusText: () => shellHost.RecipeCommands.ValidationSuiteStatusText,
                    hasSavedRun: () => shellHost.RecipeCommands.RecentBatchRunOptions.Any(option =>
                        !string.IsNullOrWhiteSpace(option?.SummaryPath)),
                    pump: Pump,
                    utcNow: () => DateTime.UtcNow,
                    localNow: () => DateTime.Now,
                    timeout: TimeSpan.FromMinutes(10),
                    progressInterval: TimeSpan.FromSeconds(2));

                OpenVisionRecipeBatchRunOption run = shellHost.RecipeCommands.RecentBatchRunOptions.FirstOrDefault()
                    ?? throw new InvalidOperationException("Dataset validation did not create a saved Run History row.");
                VisionPipelineBatchRunSummary? summary = string.IsNullOrWhiteSpace(run.SummaryPath)
                    ? null
                    : VisionPipelineBatchRunSummaryStorage.Load(run.SummaryPath);
                int expectedTotal = expectedOkCount + expectedNgCount;
                if (summary?.Results == null || summary.Results.Count != expectedTotal)
                {
                    throw new InvalidOperationException(
                        "Dataset validation did not save the expected result count. Status='"
                        + shellHost.RecipeCommands.ValidationSuiteStatusText
                        + "'.");
                }

                ValidationDatasetArtifactWriter.WriteValidationDatasetArtifacts(
                    artifactDirectory,
                    configuration.PipelineXml,
                    summary,
                    configuration.DatasetRoot,
                    configuration.TemplatePath,
                    configuration.PipelineName,
                    configuration.Boundary);

                ToggleButton recipeManagerButton = FindNamedVisualChild<ToggleButton>(shellHost, "btnHostRecipeManager")
                    ?? throw new InvalidOperationException("Recipe manager button was not found.");
                recipeManagerButton.IsChecked = true;
                Pump(60);
                ToggleButton advancedToggle = FindNamedVisualChild<ToggleButton>(shellHost, "recipeAdvancedReviewToggle")
                    ?? throw new InvalidOperationException("Recipe advanced review toggle was not found.");
                advancedToggle.IsChecked = true;
                Pump(60);
                FindNamedVisualChild<TabItem>(shellHost, "tabRecipePipeline")!.IsSelected = true;
                Pump(40);
                FindNamedVisualChild<TabItem>(shellHost, "tabRecipePipelineRunHistory")!.IsSelected = true;
                Pump(80);

                if (captureReviewQueue)
                {
                    FrameworkElement reviewQueuePanel = FindVisualChildren<FrameworkElement>(shellHost)
                        .First(element => string.Equals(
                            AutomationProperties.GetAutomationId(element),
                            "HostRecipeRecentBatchReviewQueuePanel",
                            StringComparison.Ordinal));
                    ValidationDatasetReviewQueueEvidence.VerifyAndWrite(
                        shellHost,
                        run,
                        summary,
                        artifactDirectory,
                        reviewQueuePanel,
                        Pump);
                }

                if (openDrawingEvidence)
                {
                    ValidationDatasetDrawingEvidence.VerifyAndWrite(
                        shellHost,
                        recipeName,
                        configuration.PipelineXml,
                        okPaths[0],
                        artifactDirectory,
                        (root, automationId) => FindVisualChildren<FrameworkElement>(root).FirstOrDefault(element =>
                            string.Equals(
                                AutomationProperties.GetAutomationId(element),
                                automationId,
                                StringComparison.Ordinal)),
                        (root, elementName) =>
                        {
                            OpenVisionPipelineReviewView? reviewView = root as OpenVisionPipelineReviewView
                                ?? FindVisualChildren<OpenVisionPipelineReviewView>(root).FirstOrDefault();
                            FrameworkElement? reviewElement = reviewView?.FindName(elementName) as FrameworkElement;
                            return reviewElement
                                ?? (root is FrameworkElement frameworkRoot
                                    ? FindVisualChildren<FrameworkElement>(frameworkRoot).FirstOrDefault(element =>
                                        string.Equals(element.Name, elementName, StringComparison.Ordinal))
                                    : null);
                        },
                        ClickVisibleButtonByAutomationId,
                        Pump);
                }
            }, captureFloatingToolWindow: false, captureScreen: true);
        }
        finally
        {
            RecipeWorkspaceService.DeleteVisionWorkspace(recipeName);
        }
    }

    private static void AssertReviewQueueMetricExtremes(VisionPipelineBatchRunSummary summary)
    {
        List<VisionPipelineBatchSampleRunResult> sourceRows = summary?.Results?
            .Where(result => result != null
                && !string.IsNullOrWhiteSpace(result.RunReportPath)
                && File.Exists(result.RunReportPath))
            .Take(2)
            .ToList() ?? new List<VisionPipelineBatchSampleRunResult>();
        if (sourceRows.Count != 2)
        {
            throw new InvalidOperationException("Review-queue metric-extreme probe requires two linked reports.");
        }

        string probeDirectory = Path.Combine(Path.GetTempPath(), "OpenVisionLabReviewQueue_" + Guid.NewGuid().ToString("N"));
        Directory.CreateDirectory(probeDirectory);
        try
        {
            List<VisionPipelineBatchSampleRunResult> probeRows = new List<VisionPipelineBatchSampleRunResult>();
            int metricStepIndex = 0;
            for (int index = 0; index < sourceRows.Count; index++)
            {
                VisionPipelineRunReport report = VisionPipelineRunReportStorage.Load(sourceRows[index].RunReportPath)
                    ?? throw new InvalidOperationException("Review-queue metric-extreme probe could not load a linked report.");
                VisionPipelineStepRunReport step = report.Steps?.FirstOrDefault(item => item != null)
                    ?? throw new InvalidOperationException("Review-queue metric-extreme probe report has no Step.");
                metricStepIndex = step.Index;
                step.Metrics ??= new List<VisionPipelineMetricRunReport>();
                step.Metrics.Add(new VisionPipelineMetricRunReport
                {
                    Name = "ReviewQueueProbe",
                    Value = index == 0 ? 10D : 20D
                });
                report.SourceImageSha256 = (index + 1).ToString("X64", CultureInfo.InvariantCulture);
                string reportPath = Path.Combine(probeDirectory, "report-" + index.ToString(CultureInfo.InvariantCulture) + ".xml");
                SerializeHelper.SaveXmlFile(reportPath, report);
                probeRows.Add(new VisionPipelineBatchSampleRunResult
                {
                    SampleName = "metric-probe-" + index.ToString(CultureInfo.InvariantCulture),
                    SampleImagePath = sourceRows[index].SampleImagePath,
                    RunReportPath = reportPath,
                    Success = true,
                    PairRole = index == 0 ? "A" : "B"
                });
            }

            VisionPipelineBatchRunSummaryStorage.BatchReviewQueue queue =
                VisionPipelineBatchRunSummaryStorage.BuildReviewQueue(probeRows);
            string minimumReason = "metric-min:" + metricStepIndex.ToString(CultureInfo.InvariantCulture) + ":ReviewQueueProbe";
            string maximumReason = "metric-max:" + metricStepIndex.ToString(CultureInfo.InvariantCulture) + ":ReviewQueueProbe";
            if (queue.Entries.FirstOrDefault(entry => entry.ResultIndex == 0)?.Reasons.Contains(minimumReason, StringComparer.Ordinal) != true
                || queue.Entries.FirstOrDefault(entry => entry.ResultIndex == 1)?.Reasons.Contains(maximumReason, StringComparer.Ordinal) != true
                || queue.Entries.Any(entry => !entry.Reasons.Contains("evidence-gap", StringComparer.Ordinal))
                || !string.Equals(
                    queue.Sha256,
                    VisionPipelineBatchRunSummaryStorage.BuildReviewQueue(probeRows).Sha256,
                    StringComparison.Ordinal))
            {
                throw new InvalidOperationException(
                    "Review-queue metric extrema, copied-report evidence gaps, or deterministic hash were not preserved.");
            }

            VisionPipelineBatchRunSummaryStorage.BatchReviewQueue evidenceGapQueue =
                VisionPipelineBatchRunSummaryStorage.BuildReviewQueue(new[]
                {
                    new VisionPipelineBatchSampleRunResult { SampleName = "missing-pass", Success = true },
                    new VisionPipelineBatchSampleRunResult { SampleName = "missing-fail", Success = false }
                });
            if (evidenceGapQueue.Entries.Count != 2
                || evidenceGapQueue.Entries.Any(entry => !entry.Reasons.Contains("evidence-gap", StringComparer.Ordinal))
                || evidenceGapQueue.Entries.First(entry => entry.ResultIndex == 1)
                    .Reasons.Contains("runtime-failure", StringComparer.Ordinal) != true)
            {
                throw new InvalidOperationException("Review-queue runtime failure or missing-evidence coverage was not preserved.");
            }

            List<VisionPipelineBatchSampleRunResult> scaleRows = Enumerable.Range(0, 500)
                .Select(index => new VisionPipelineBatchSampleRunResult
                {
                    SampleName = "scale-" + index.ToString("D4", CultureInfo.InvariantCulture),
                    SampleImagePath = "scale-" + index.ToString("D4", CultureInfo.InvariantCulture) + ".png",
                    RunReportPath = sourceRows[0].RunReportPath,
                    Success = true,
                    PairRole = index < 250 ? "OK" : "NG"
                })
                .ToList();
            VisionPipelineBatchRunSummaryStorage.BatchReviewQueue scaleQueue =
                VisionPipelineBatchRunSummaryStorage.BuildReviewQueue(scaleRows);
            if (scaleQueue.Entries.Count != 6
                || scaleQueue.Entries.Count(entry =>
                    entry.Reasons.Contains("hash-audit:VARIANT:Default|ROLE:OK", StringComparer.Ordinal)) != 3
                || scaleQueue.Entries.Count(entry =>
                    entry.Reasons.Contains("hash-audit:VARIANT:Default|ROLE:NG", StringComparer.Ordinal)) != 3)
            {
                throw new InvalidOperationException(
                    "Review-queue 500-row bounded hash audit was not 3 rows per declared stratum. "
                    + "Rows=" + scaleQueue.Entries.Count.ToString(CultureInfo.InvariantCulture));
            }

            VisionPipelineBatchRunSummaryStorage.BatchReviewQueue legacyScaleQueue =
                VisionPipelineBatchRunSummaryStorage.BuildReviewQueue(
                    scaleRows,
                    VisionPipelineBatchRunSummaryStorage.LegacyReviewQueuePolicyV2);
            if (!string.Equals(
                    legacyScaleQueue.Policy,
                    VisionPipelineBatchRunSummaryStorage.LegacyReviewQueuePolicyV2,
                    StringComparison.Ordinal)
                || legacyScaleQueue.Entries.Count(entry =>
                    entry.Reasons.Contains("hash-audit:OK", StringComparer.Ordinal)) != 3
                || legacyScaleQueue.Entries.Count(entry =>
                    entry.Reasons.Contains("hash-audit:NG", StringComparer.Ordinal)) != 3)
            {
                throw new InvalidOperationException(
                    "Legacy review-queue v2 strata no longer rebuild for backward compatibility.");
            }
        }
        finally
        {
            if (Directory.Exists(probeDirectory))
            {
                Directory.Delete(probeDirectory, recursive: true);
            }
        }
    }

    private static CaptureResult CaptureShellHostRecipeOperatorDecisionBoard(string outputPath)
    {
        OpenVisionLanguageService.SetLanguage(OpenVisionLanguage.English, false);
        SmokeRecipeWorkspaceCleanup.DeleteTransient();

        string recipe = "Smoke_DecisionBoard_" + Guid.NewGuid().ToString("N");
        VisionPipelineStorage.Save(recipe, RecipeContextFixture.CreatePipeline("Decision_Board_Source", 1));
        VisionPipelineStorage.SaveActivePipelineName(recipe, "Decision_Board_Source");

        OpenVisionShellHostView shellHost = CreateShellHost(recipe, seedMainLayer: false);
        return CaptureWindowWithContent(shellHost, outputPath, 1600, 900, () =>
        {
            ToggleButton? recipeManagerButton = FindNamedVisualChild<ToggleButton>(shellHost, "btnHostRecipeManager");
            if (recipeManagerButton == null)
            {
                throw new InvalidOperationException("Recipe manager button was not found.");
            }

            recipeManagerButton.IsChecked = true;
            Pump(100);

            FrameworkElement managerPanel = FindVisualChildren<FrameworkElement>(shellHost)
                .First(item => string.Equals(
                    AutomationProperties.GetAutomationId(item),
                    "HostRecipeManagerPanel",
                    StringComparison.Ordinal));
            FrameworkElement nameStrip = FindVisualChildren<FrameworkElement>(shellHost)
                .First(item => string.Equals(
                    AutomationProperties.GetAutomationId(item),
                    "HostRecipeManagerNameStrip",
                    StringComparison.Ordinal));
            FrameworkElement workbench = FindVisualChildren<FrameworkElement>(shellHost)
                .First(item => string.Equals(
                    AutomationProperties.GetAutomationId(item),
                    "HostRecipeManagerWorkbenchGrid",
                    StringComparison.Ordinal));
            TextBox nameEditor = FindVisualChildren<TextBox>(shellHost)
                .First(item => string.Equals(
                    AutomationProperties.GetAutomationId(item),
                    "HostRecipeNameEditor",
                    StringComparison.Ordinal));
            nameEditor.ApplyTemplate();
            Border? fieldChrome = nameEditor.Template.FindName("fieldChrome", nameEditor) as Border;
            HashSet<DependencyProperty> fieldStateTriggers = nameEditor.Template.Triggers
                .OfType<Trigger>()
                .Select(trigger => trigger.Property)
                .Where(property => property != null)
                .ToHashSet();
            Point nameStripPosition = nameStrip.TranslatePoint(new Point(0D, 0D), managerPanel);
            Point workbenchPosition = workbench.TranslatePoint(new Point(0D, 0D), managerPanel);
            if (nameStripPosition.Y >= workbenchPosition.Y
                || fieldChrome?.Background is not SolidColorBrush fieldBackground
                || nameEditor.Foreground is not SolidColorBrush fieldForeground
                || !fieldStateTriggers.Contains(UIElement.IsMouseOverProperty)
                || !fieldStateTriggers.Contains(UIElement.IsKeyboardFocusWithinProperty)
                || !fieldStateTriggers.Contains(TextBoxBase.IsReadOnlyProperty)
                || !fieldStateTriggers.Contains(UIElement.IsEnabledProperty)
                || !fieldStateTriggers.Contains(Validation.HasErrorProperty)
                || Math.Abs(fieldBackground.Color.R - fieldForeground.Color.R)
                    + Math.Abs(fieldBackground.Color.G - fieldForeground.Color.G)
                    + Math.Abs(fieldBackground.Color.B - fieldForeground.Color.B) < 180)
            {
                throw new InvalidOperationException(
                    "Recipe manager lifecycle controls were not above the workbench with a readable themed name field. "
                    + $"NameY={nameStripPosition.Y:0.0}, WorkbenchY={workbenchPosition.Y:0.0}, "
                    + $"Chrome={fieldChrome != null}, Text='{nameEditor.Text}'.");
            }

            ToggleButton advancedToggle = FindNamedVisualChild<ToggleButton>(shellHost, "recipeAdvancedReviewToggle")
                ?? throw new InvalidOperationException("Recipe advanced review toggle was not found.");
            advancedToggle.IsChecked = true;
            Pump(80);

            OpenVisionRecipeSampleOption? sampleOption = shellHost.RecipeCommands.SampleOptions.FirstOrDefault();
            if (sampleOption == null)
            {
                throw new InvalidOperationException("Recipe manager did not expose a sample option for the decision board capture.");
            }

            shellHost.RecipeCommands.SelectedSampleOption = sampleOption;
            if (!shellHost.RecipeCommands.DuplicateFromSampleCommand.CanExecute(null))
            {
                throw new InvalidOperationException("Duplicate-from-sample command was disabled for the decision board capture.");
            }

            shellHost.RecipeCommands.DuplicateFromSampleCommand.Execute(null);
            Pump(120);

            TabItem? pipelineTab = FindNamedVisualChild<TabItem>(shellHost, "tabRecipePipeline");
            if (pipelineTab == null)
            {
                throw new InvalidOperationException("Recipe manager Pipeline tab was not found.");
            }

            pipelineTab.IsSelected = true;
            Pump(80);
            TabItem? reviewTab = FindNamedVisualChild<TabItem>(shellHost, "tabRecipePipelineReview");
            TabItem? reportTab = FindNamedVisualChild<TabItem>(shellHost, "tabRecipePipelineReport");
            if (reviewTab == null || reportTab == null)
            {
                throw new InvalidOperationException("Recipe manager pipeline decision tabs were not found.");
            }

            reviewTab.IsSelected = true;
            Pump(80);

            List<OpenVisionRecipeSampleMatrixRow> matrixRows = shellHost.RecipeCommands.SampleMatrixRows
                .Where(row => row != null && !row.IsPlaceholder)
                .ToList();
            if (matrixRows.Count == 0)
            {
                throw new InvalidOperationException("Recipe sample matrix did not expose rows for the decision board capture.");
            }

            OpenVisionRecipePipelineStepPreview? failedStep =
                shellHost.RecipeCommands.SelectedRecipeSummary.PipelinePreviewSteps.Skip(1).FirstOrDefault()
                ?? shellHost.RecipeCommands.SelectedRecipeSummary.PipelinePreviewSteps.FirstOrDefault();
            string failedStepText = failedStep?.DisplayText ?? "02 Match [NG]";

            List<OpenVisionRecipePairSampleRunSummary> injectedResults = new List<OpenVisionRecipePairSampleRunSummary>
            {
                OpenVisionRecipePairSampleRunSummary.CreateForTest(
                    matrixRows[0].Role,
                    matrixRows[0].SampleName,
                    matrixRows.Count > 1 ? "OK" : "NG",
                    matrixRows.Count > 1,
                    "DistanceMmAvg=0.24 DistanceMmRange=0.01",
                    string.Empty,
                    matrixRows.Count > 1 ? string.Empty : failedStepText)
            };
            if (matrixRows.Count > 1)
            {
                injectedResults.Add(OpenVisionRecipePairSampleRunSummary.CreateForTest(
                    matrixRows[1].Role,
                    matrixRows[1].SampleName,
                    "NG",
                    false,
                    "DistanceMmAvg=0.31 DistanceMmRange=0.09",
                    "Injected operator-board NG evidence",
                    failedStepText));
            }

            shellHost.RecipeCommands.SetPairRunSummaryForTest(injectedResults);
            if (failedStep != null)
            {
                shellHost.RecipeCommands.SelectedPipelinePreviewStep = failedStep;
            }
            reportTab.IsSelected = true;
            Pump(120);

            AssertVisibleAutomationIds(
                shellHost,
                "WPF recipe operator decision board",
                "HostRecipePipelineReportTab",
                "HostRecipeOperatorDecisionSummaryBand",
                "HostRecipeOperatorDecisionSummaryStatus",
                "HostRecipeOperatorDecisionSummaryMetric",
                "HostRecipeOperatorDecisionSummaryNextAction",
                "HostRecipeOperatorValidationChecklistPanel",
                "HostRecipeOperatorResultChannelsPanel");

            if (!ContainsAny(shellHost.RecipeCommands.OperatorDecisionEvidenceText, "Metric review")
                || !ContainsAny(shellHost.RecipeCommands.OperatorDecisionEvidenceText, "expected")
                || !ContainsAny(shellHost.RecipeCommands.OperatorDecisionEvidenceText, "actual")
                || !ContainsAny(shellHost.RecipeCommands.OperatorDecisionEvidenceText, "evidence"))
            {
                throw new InvalidOperationException(
                    "Operator decision board did not expose consolidated metric evidence. "
                    + $"Text='{shellHost.RecipeCommands.OperatorDecisionEvidenceText}'");
            }
        }, captureFloatingToolWindow: false, captureScreen: true);
    }

    private static CaptureResult CaptureShellHostRecipeManagerSummary(string outputPath)
    {
        return CaptureShellHostRecipeManagerSummary(outputPath, OpenVisionLanguage.Korean);
    }

    private static CaptureResult CaptureShellHostRecipeManagerFileTarget(string outputPath)
    {
        OpenVisionLanguageService.SetLanguage(OpenVisionLanguage.Korean, false);
        SmokeRecipeWorkspaceCleanup.DeleteTransient();
        string suffix = Guid.NewGuid().ToString("N").Substring(0, 12);
        string mainRecipe = "Smoke_FileMain_" + suffix;
        string browsedRecipe = "Smoke_FileBrowse_" + suffix + "_저장된검사레시피_긴이름과선택대상확인";
        string sourceRecipe = "Smoke_FileSource_" + suffix;
        string mainPipeline = "Main_Inspection";
        string browsedPipeline = "Browse_Inspection";
        string importedPipeline = "Imported_Inspection";
        VisionPipelineStorage.Save(mainRecipe, RecipeContextFixture.CreatePipeline(mainPipeline, 1));
        VisionPipelineStorage.SaveActivePipelineName(mainRecipe, mainPipeline);
        VisionPipelineStorage.Save(browsedRecipe, RecipeContextFixture.CreatePipeline(browsedPipeline, 2));
        VisionPipelineStorage.SaveActivePipelineName(browsedRecipe, browsedPipeline);
        VisionPipelineStorage.Save(sourceRecipe, RecipeContextFixture.CreatePipeline(importedPipeline, 1));
        VisionPipelineStorage.SaveActivePipelineName(sourceRecipe, importedPipeline);

        SerializeHelper.SaveXmlFile(RecipeWorkspaceService.GetVisionDataPath(browsedRecipe),
            new DataState { Description = "VM11 관리 선택 설명 검색", SavedRevision = 7, SavedContentHash = new string('A', 64) });
        OpenVisionRecipeValidationSetDocument managerSets = OpenVisionRecipeValidationSetStorage.CreateEmpty();
        managerSets.Sets.Add(new OpenVisionRecipeValidationSet { Name = "VM11_saved_set", PipelineName = browsedPipeline });
        if (!OpenVisionRecipeValidationSetStorage.TrySave(browsedRecipe, managerSets, out string setError))
            throw new InvalidOperationException(setError);
        VisionPipelineBatchRunSummaryStorage.Save(browsedRecipe, browsedPipeline,
            DateTime.UtcNow.AddMinutes(-1), DateTime.UtcNow,
            new[] { new VisionPipelineBatchSampleRunResult { SampleName = "VM11_saved_result", Success = true, TotalMilliseconds = 12 } });

        string evidenceDirectory = Path.GetDirectoryName(outputPath)
            ?? throw new InvalidOperationException("Recipe file-target evidence directory is missing.");
        string exportedPath = Path.Combine(evidenceDirectory, "browsed-inspection.xml");
        string stalePath = Path.Combine(evidenceDirectory, "stale-target.xml");
        string bundlePath = Path.Combine(evidenceDirectory, "browsed-inspection.review.zip");
        OpenVisionShellHostView shellHost = CreateShellHost(mainRecipe, seedMainLayer: false);
        return CaptureWindowWithContent(shellHost, outputPath, 1600, 900, () =>
        {
            ToggleButton managerButton = FindNamedVisualChild<ToggleButton>(shellHost, "btnHostRecipeManager")
                ?? throw new InvalidOperationException("Recipe Manager button was not found.");
            managerButton.IsChecked = true;
            Pump(80);
            ListBox list = FindVisualChildren<ListBox>(shellHost)
                .FirstOrDefault(item => string.Equals(
                    AutomationProperties.GetAutomationId(item), "HostRecipeManagerList", StringComparison.Ordinal))
                ?? throw new InvalidOperationException("Recipe Manager list was not found.");
            list.SelectedItem = browsedRecipe;
            Pump(50);
            TextBox search = FindVisualChildren<TextBox>(shellHost).First(item => AutomationProperties.GetAutomationId(item) == "HostRecipeFilterTextBox");
            search.Text = "관리 선택 설명";
            Pump(30);
            ComboBox sort = FindVisualChildren<ComboBox>(shellHost).First(item => AutomationProperties.GetAutomationId(item) == "HostRecipeManagerSort");
            sort.SelectedIndex = 1;
            Pump(30);
            if (shellHost.RecipeCommands.RecipeFilterText != search.Text
                || shellHost.RecipeCommands.FilteredRecipeOptions.Count != 1
                || shellHost.RecipeCommands.FilteredRecipeOptions[0] != browsedRecipe
                || shellHost.RecipeCommands.RecipeManagerSortIndex != 1
                || shellHost.RecipeCommands.MainRecipeName != mainRecipe
                || shellHost.RecipeCommands.RecipeManagerValidationSets.Count != 1
                || shellHost.RecipeCommands.RecipeManagerRecentRuns.Count != 1
                || shellHost.RecipeCommands.RecipeManagerTotalSteps != 2)
                throw new InvalidOperationException("VM11 search/sort or stored management projections changed the work identity.");
            shellHost.RecipeCommands.RecipeFilterText = string.Empty;
            Pump(30);
            if (search.Text != string.Empty || shellHost.RecipeCommands.RecipeManagerSelectedRecipeName != browsedRecipe)
                throw new InvalidOperationException("VM11 clearing search did not round-trip or preserve browse selection.");
            list.ScrollIntoView(browsedRecipe); Pump(30);
            if (!shellHost.RecipeCommands.RecipeManagerLibraryDetails[browsedRecipe].Contains("r7", StringComparison.Ordinal)
                || !FindVisualChildren<TextBlock>(list).Any(text => text.Text.StartsWith("r7 /", StringComparison.Ordinal)))
                throw new InvalidOperationException("VM11 library string item did not render its stored row metadata.");
            ToggleButton fileActions = FindVisualChildren<ToggleButton>(shellHost)
                .FirstOrDefault(item => string.Equals(
                    AutomationProperties.GetAutomationId(item), "HostRecipeManagerFileActions", StringComparison.Ordinal))
                ?? throw new InvalidOperationException("Recipe Manager file actions were not found.");
            fileActions.IsChecked = true;
            Pump(50);

            int runsBefore = shellHost.NativePreviewRunCount;
            int layersBefore = shellHost.LayerDocumentCount;
            if (!shellHost.RecipeCommands.ExportBrowsedPipelineXmlCommand.CanExecute(null)
                || !shellHost.RecipeCommands.ExportBrowsedPipelineXmlToPath(
                    browsedRecipe, browsedPipeline, exportedPath)
                || !VisionPipelineStorage.TryLoadFromFile(
                    exportedPath, out VisionPipeline exported, out string xmlMessage)
                || !string.Equals(exported.Name, browsedPipeline, StringComparison.Ordinal)
                || shellHost.RecipeCommands.ExportBrowsedPipelineXmlToPath(
                    mainRecipe, mainPipeline, stalePath)
                || File.Exists(stalePath))
            {
                throw new InvalidOperationException("Recipe Manager file export used the wrong or a stale browse target.");
            }

            string importPath = RecipeWorkspaceService.GetVisionPipelinePath(sourceRecipe, importedPipeline);
            TextBox recipeNameEditor = FindVisualChildren<TextBox>(shellHost)
                .FirstOrDefault(item => string.Equals(
                    AutomationProperties.GetAutomationId(item), "HostRecipeNameEditor", StringComparison.Ordinal))
                ?? throw new InvalidOperationException("Recipe Manager name editor was not found.");
            if (!shellHost.RecipeCommands.ImportBrowsedPipelineXmlFromPath(browsedRecipe, importPath)
                || !shellHost.RecipeCommands.ExportBrowsedReviewBundleToPath(
                    browsedRecipe, importedPipeline, bundlePath)
                || !File.Exists(bundlePath)
                || !string.Equals(shellHost.RecipeCommands.MainRecipeName, mainRecipe, StringComparison.Ordinal)
                || !string.Equals(shellHost.RecipeCommands.RecipeManagerSelectedRecipeName, browsedRecipe, StringComparison.Ordinal)
                || !string.Equals(shellHost.RecipeCommands.RecipeManagerSelectedPipelineName, importedPipeline, StringComparison.Ordinal)
                || !string.Equals(recipeNameEditor.Text, browsedRecipe, StringComparison.Ordinal)
                || !string.Equals(VisionPipelineStorage.LoadActivePipelineName(
                    mainRecipe, mainPipeline), mainPipeline, StringComparison.Ordinal)
                || shellHost.NativePreviewRunCount != runsBefore
                || shellHost.LayerDocumentCount != layersBefore)
            {
                throw new InvalidOperationException(
                    "Recipe Manager file import changed the main work or failed to update the browsed inspection. "
                    + $"Status='{shellHost.RecipeCommands.StatusText}', Main='{shellHost.RecipeCommands.MainRecipeName}', "
                    + $"Browse='{shellHost.RecipeCommands.RecipeManagerSelectedRecipeName}', "
                    + $"Pipeline='{shellHost.RecipeCommands.RecipeManagerSelectedPipelineName}'.");
            }

            AssertVisibleAutomationIds(shellHost, "Recipe Manager file target",
                "HostRecipeManagerFileActions", "HostRecipeManagerFileActionsPanel", "HostRecipeManagerFileTarget",
                "HostRecipeManagerImportXmlButton", "HostRecipeManagerExportXmlButton",
                "HostRecipeManagerExportReviewBundleButton");
            if (shellHost.RecipeCommands.RecipeManagerTotalSteps != 3
                || shellHost.RecipeCommands.RecipeManagerValidationSets.Count != 1
                || shellHost.RecipeCommands.RecipeManagerRecentRuns.Count != 1)
                throw new InvalidOperationException("VM11 imported pipeline did not refresh whole-recipe step summary.");
            AssertVisibleAutomationIds(shellHost, "VM11 management content",
                "HostRecipeManagerSummaryCards", "HostRecipeManagerValidationContents", "HostRecipeManagerRecentContents");
            string setPath = OpenVisionRecipeValidationSetStorage.GetPath(browsedRecipe);
            byte[] validSets = File.ReadAllBytes(setPath);
            File.WriteAllText(setPath, "<OpenVisionValidationSets>");
            shellHost.RecipeCommands.RefreshOptions();
            if (string.IsNullOrWhiteSpace(shellHost.RecipeCommands.RecipeManagerValidationReadStatus)
                || shellHost.RecipeCommands.RecipeManagerValidationSets.Count != 0
                || File.ReadAllText(setPath) != "<OpenVisionValidationSets>"
                || shellHost.RecipeCommands.MainRecipeName != mainRecipe)
                throw new InvalidOperationException("VM11 invalid saved-set read hid the error or mutated the selected work/data.");
            File.WriteAllBytes(setPath, validSets);
            shellHost.RecipeCommands.RefreshOptions();
            if (shellHost.RecipeCommands.RecipeManagerValidationSets.Count != 1
                || shellHost.RecipeCommands.RecipeManagerRecentRuns.Count != 1
                || recipeNameEditor.Text != browsedRecipe)
                throw new InvalidOperationException("VM11 stored content did not recover after a valid snapshot was restored.");
            string dataPath = RecipeWorkspaceService.GetVisionDataPath(browsedRecipe);
            byte[] validData = File.ReadAllBytes(dataPath);
            const string missingBaseline = "<CData><SavedRevision>7</SavedRevision></CData>";
            File.WriteAllText(dataPath, missingBaseline);
            shellHost.RecipeCommands.RefreshOptions();
            if (!shellHost.RecipeCommands.RecipeManagerLibraryDetails[browsedRecipe].StartsWith("r- /", StringComparison.Ordinal)
                || !shellHost.RecipeCommands.RecipeManagerSavedVersion.StartsWith("- /", StringComparison.Ordinal)
                || File.ReadAllText(dataPath) != missingBaseline
                || recipeNameEditor.Text != browsedRecipe)
                throw new InvalidOperationException("VM11 metadata read accepted an unproved saved revision or changed its bytes/target.");
            File.WriteAllBytes(dataPath, validData);
            shellHost.RecipeCommands.RefreshOptions();
            if (!shellHost.RecipeCommands.RecipeManagerSavedVersion.StartsWith("r7 /", StringComparison.Ordinal))
                throw new InvalidOperationException("VM11 metadata did not recover from a valid stored baseline.");
            ScrollViewer overview = FindNamedVisualChild<ScrollViewer>(shellHost, "recipeManagerOverviewScrollViewer")!;
            Window managerWindow = Window.GetWindow(shellHost);
            foreach (string theme in new[] { "Dark", "Light" })
            {
                (theme == "Dark" ? shellHost.Workbench.SelectDarkThemeCommand : shellHost.Workbench.SelectLightThemeCommand).Execute(null);
                foreach (int width in new[] { 1600, 1280 })
                {
                    managerWindow.Width = width;
                    managerWindow.Height = width == 1600 ? 900 : 760;
                    Pump(30);
                    overview.ScrollToTop(); Pump(10);
                    if (sort.SelectedItem is not ComboBoxItem sortItem || string.IsNullOrWhiteSpace(sortItem.Content?.ToString()))
                        throw new InvalidOperationException("VM11 sort caption was not rendered.");
                    if (!FindVisualChildren<TextBlock>(sort).Any(text => text.Text == sortItem.Content?.ToString() && text.ActualWidth > 0))
                        throw new InvalidOperationException("VM11 selected sort caption is missing from the rendered template.");
                    string stem = Path.Combine(evidenceDirectory, "manager-" + theme + "-" + width);
                    ScreenshotPngWriter.WriteDpiAwareWindowPng(managerWindow, stem + "-top.png");
                    overview.ScrollToBottom(); Pump(10);
                    ScreenshotPngWriter.WriteDpiAwareWindowPng(managerWindow, stem + "-bottom.png");
                }
            }
            OpenVisionLanguageService.SetLanguage(OpenVisionLanguage.English, false); Pump(30);
            overview.ScrollToTop(); Pump(10);
            if (!FindVisualChildren<TextBlock>(sort).Any(text => text.Text == "Name order" && text.ActualWidth > 0)
                || !shellHost.RecipeCommands.RecipeManagerLibraryDetails[browsedRecipe].Contains("Validation sets", StringComparison.Ordinal))
                throw new InvalidOperationException("VM11 language change did not refresh the rendered sort or stored-row projection.");
            ScreenshotPngWriter.WriteDpiAwareWindowPng(managerWindow, Path.Combine(evidenceDirectory, "manager-English-Light-1280.png"));
            OpenVisionLanguageService.SetLanguage(OpenVisionLanguage.Korean, false); Pump(30);
            shellHost.Workbench.SelectDarkThemeCommand.Execute(null);
            managerWindow.Width = 1600; managerWindow.Height = 900;
            overview.ScrollToTop(); Pump(30);
            File.WriteAllText(Path.Combine(evidenceDirectory, "manager-source-cases.json"), JsonSerializer.Serialize(new
            {
                Scope = "인프로세스 WPF 렌더링과 바인딩 검사. 실제 제품 EXE 입력과 native DPI 검증은 수행하지 않았다.",
                DescriptionSearch = true, SortBinding = true, BrowseRetained = true, MainRetained = true,
                WholeRecipeSteps = 3, StoredSets = 1, StoredRuns = 1, InvalidSetReadPreserved = true,
                ValidSnapshotRecovery = true, Themes = new[] { "Dark", "Light" }, Widths = new[] { 1600, 1280 },
                NativeRunsBefore = runsBefore, NativeRunsAfter = shellHost.NativePreviewRunCount
            }, new JsonSerializerOptions { WriteIndented = true }));
        }, captureFloatingToolWindow: false);
    }

    private static CaptureResult CaptureShellHostMainRecipeWorkEntry(string outputPath) =>
        CaptureShellHostMainRecipeWorkEntry(outputPath, "Pipeline");

    private static CaptureResult CaptureShellHostMainRecipeWorkEntry(string outputPath, string section)
    {
        OpenVisionLanguageService.SetLanguage(OpenVisionLanguage.Korean, false);
        SmokeRecipeWorkspaceCleanup.DeleteTransient();

        string recipe = "Smoke_MainRecipeWork_" + Guid.NewGuid().ToString("N").Substring(0, 12);
        VisionPipelineStorage.Save(recipe, RecipeContextFixture.CreatePipeline("Work_Source", 2));
        VisionPipelineStorage.SaveActivePipelineName(recipe, "Work_Source");
        OpenVisionShellHostView shellHost = CreateShellHost(recipe, seedMainLayer: true);
        return CaptureWindowWithContent(shellHost, outputPath, 1600, 900, () =>
        {
            int runsBefore = shellHost.NativePreviewRunCount;
            int layersBefore = shellHost.LayerDocumentCount;
            string layerBefore = shellHost.ActiveHostLayerTitle;
            string pipelineBefore = shellHost.ActiveRecipeContextPipelineNameForTest;
            if (section == "Pipeline")
            {
                // Retained legacy command contract; the approved Main header has no navigation command.
                shellHost.RecipeCommands.OpenMainRecipeWorkCommand.Execute("Pipeline");
            }
            else ClickVisibleButtonByAutomationId(
                shellHost,
                section switch
                {
                    "Validation" => "HostMainRecipeValidationButton",
                    "Builder" => "HostMainRecipeBuilderButton",
                    "Llm" => "HostMainRecipeLlmButton",
                    _ => throw new InvalidOperationException("Unsupported legacy section: " + section)
                },
                "main Recipe " + section + " button");
            Pump(60);

            ToggleButton managerButton = FindNamedVisualChild<ToggleButton>(shellHost, "btnHostRecipeManager")
                ?? throw new InvalidOperationException("Recipe manager button was not found.");
            TabItem pipelineTab = FindNamedVisualChild<TabItem>(shellHost, "tabRecipePipeline")
                ?? throw new InvalidOperationException("Inspection work Pipeline tab was not found.");
            TabItem expectedTab = FindNamedVisualChild<TabItem>(
                shellHost,
                section switch
                {
                    "Validation" => "tabRecipePipelineRunHistory",
                    "Builder" => "tabRecipeGuidedSetup",
                    "Llm" => "tabRecipeLlmXml",
                    _ => "tabRecipePipelineReview"
                })
                ?? throw new InvalidOperationException("Requested inspection work tab was not found.");
            bool expectsPipeline = section == "Pipeline" || section == "Validation";
            if (managerButton.IsChecked == true
                || !shellHost.RecipeCommands.IsRecipeManagerDetailContextActive
                || pipelineTab.IsSelected != expectsPipeline
                || !expectedTab.IsSelected
                || !string.Equals(shellHost.RecipeCommands.RecipeManagerSelectedRecipeName, recipe, StringComparison.Ordinal)
                || !string.Equals(shellHost.RecipeCommands.SelectedPipelineOption?.PipelineName, pipelineBefore, StringComparison.Ordinal)
                || shellHost.NativePreviewRunCount != runsBefore
                || shellHost.LayerDocumentCount != layersBefore
                || !string.Equals(shellHost.ActiveHostLayerTitle, layerBefore, StringComparison.Ordinal))
            {
                throw new InvalidOperationException(
                    "Main inspection work changed the active Recipe/Pipeline, execution, or layer state. "
                    + $"Manager={managerButton.IsChecked}, Detail={shellHost.RecipeCommands.IsRecipeManagerDetailContextActive}, "
                    + $"SelectedRecipe='{shellHost.RecipeCommands.RecipeManagerSelectedRecipeName}', "
                    + $"SelectedPipeline='{shellHost.RecipeCommands.SelectedPipelineOption?.PipelineName}', ActivePipeline='{pipelineBefore}', "
                    + $"Runs={runsBefore}->{shellHost.NativePreviewRunCount}, Layers={layersBefore}->{shellHost.LayerDocumentCount}");
            }

            AssertVisibleAutomationIds(
                shellHost,
                "main inspection work",
                "HostRecipeManagerPanel",
                "HostRecipeAdvancedReviewToggle",
                "HostRecipePipelineTab",
                "HostRecipeGuidedSetupTab",
                "HostRecipeLlmXmlTab");
            if (expectsPipeline)
            {
                AssertVisibleAutomationIds(shellHost, "main Pipeline work",
                    "HostRecipePipelineReviewTab", "HostRecipePipelineReportTab",
                    "HostRecipePipelineRunHistoryTab", "HostRecipePipelineStepSettingsTab",
                    "HostRecipePipelineXmlStepsTab");
            }
            else
            {
                AssertVisibleAutomationIds(shellHost, "main Recipe work section",
                    section == "Builder" ? "HostRecipeGuidedSetupPanel" : "HostRecipeLlmAssistantPanel");
            }
            AssertHiddenAutomationIds(
                shellHost,
                "main inspection work management separation",
                "HostRecipeManagerLibraryPane",
                "HostRecipeFilterTextBox",
                "HostRecipeManagerCommandStrip");
            if (section == "Pipeline")
            {
                shellHost.RecipeCommands.OpenPipelineReviewCommand.Execute(null);
                Pump(80);
                if (!shellHost.IsActiveWpfToolWindowVisibleForTest
                    || !string.Equals(shellHost.PipelineReviewRecipeContextNameForTest, recipe, StringComparison.Ordinal)
                    || !string.Equals(shellHost.PipelineReviewRecipeContextPipelineNameForTest, pipelineBefore, StringComparison.Ordinal))
                {
                    throw new InvalidOperationException("Main inspection work did not open Pipeline Review for the current Recipe/Pipeline.");
                }

                ClickVisibleButtonByAutomationId(shellHost, "PipelineReviewReturnToRecipeButton", "main Pipeline Review return button");
                Pump(80);
                if (managerButton.IsChecked == true
                    || !shellHost.RecipeCommands.IsRecipeManagerDetailContextActive
                    || !pipelineTab.IsSelected
                    || !expectedTab.IsSelected
                    || !string.Equals(shellHost.RecipeCommands.RecipeManagerSelectedRecipeName, recipe, StringComparison.Ordinal)
                    || !string.Equals(shellHost.RecipeCommands.SelectedPipelineOption?.PipelineName, pipelineBefore, StringComparison.Ordinal)
                    || shellHost.IsActiveWpfToolWindowVisibleForTest
                    || shellHost.NativePreviewRunCount != runsBefore
                    || shellHost.LayerDocumentCount != layersBefore
                    || !string.Equals(shellHost.ActiveHostLayerTitle, layerBefore, StringComparison.Ordinal))
                {
                    throw new InvalidOperationException("Pipeline Review did not return to main inspection work without changing Recipe, Pipeline, execution, or layer state.");
                }
            }
        }, captureFloatingToolWindow: false);
    }

    private static CaptureResult CaptureShellHostRecipeManagerSummary(
        string outputPath,
        OpenVisionLanguage language)
    {
        OpenVisionLanguageService.SetLanguage(language, false);
        SmokeRecipeWorkspaceCleanup.DeleteTransient();

        string recipe = "Smoke_RecipeSummary_" + Guid.NewGuid().ToString("N");
        VisionPipelineStorage.Save(recipe, RecipeContextFixture.CreatePipeline("Summary_Source", 2));
        VisionPipelineStorage.SaveActivePipelineName(recipe, "Summary_Source");

        OpenVisionShellHostView shellHost = CreateShellHost(recipe, seedMainLayer: true);
        OpenVisionLanguageService.SetLanguage(language, false);
        return CaptureWindowWithContent(shellHost, outputPath, 1600, 900, () =>
        {
            ToggleButton recipeManagerButton = FindNamedVisualChild<ToggleButton>(shellHost, "btnHostRecipeManager")
                ?? throw new InvalidOperationException("Recipe manager button was not found.");
            int beforeRuns = shellHost.NativePreviewRunCount;
            int beforeLayerCount = shellHost.LayerDocumentCount;
            string beforeActiveLayer = shellHost.ActiveHostLayerTitle;
            string beforeRecipeLayer = shellHost.ActiveRecipeContextLayerNameForTest;
            string beforePipeline = shellHost.ActiveRecipeContextPipelineNameForTest;
            recipeManagerButton.IsChecked = true;
            Pump(100);

            Button saveRecipeButton = FindVisualChildren<Button>(shellHost)
                .FirstOrDefault(button => string.Equals(
                    AutomationProperties.GetAutomationId(button),
                    "HostRecipeSaveButton",
                    StringComparison.Ordinal))
                ?? throw new InvalidOperationException("Recipe save button was not found in the top command bar.");
            KeyBinding saveRecipeBinding = shellHost.InputBindings
                .OfType<KeyBinding>()
                .FirstOrDefault(binding => binding.Key == Key.S && binding.Modifiers == ModifierKeys.Control)
                ?? throw new InvalidOperationException("Recipe Ctrl+S binding was not found.");
            if (!ReferenceEquals(saveRecipeButton.Command, shellHost.RecipeCommands.SaveRecipeCommand)
                || !ReferenceEquals(saveRecipeBinding.Command, shellHost.RecipeCommands.SaveRecipeCommand)
                || !string.Equals(saveRecipeButton.ToolTip?.ToString(), shellHost.RecipeCommands.SaveRecipeToolTipText, StringComparison.Ordinal))
            {
                throw new InvalidOperationException("Recipe Save button, Ctrl+S, and localized tooltip do not share the save command.");
            }

            shellHost.RecipeCommands.SaveRecipeCommand.Execute(null);
            Pump(20);
            string expectedSaveStatus = language == OpenVisionLanguage.English ? "Recipe saved:" : "레시피 저장 완료:";
            if (!shellHost.RecipeCommands.StatusText.Contains(expectedSaveStatus, StringComparison.Ordinal)
                || shellHost.NativePreviewRunCount != beforeRuns
                || shellHost.LayerDocumentCount != beforeLayerCount)
            {
                throw new InvalidOperationException(
                    "Explicit Recipe Save did not complete cleanly. "
                    + $"Status='{shellHost.RecipeCommands.StatusText}', Runs={beforeRuns}->{shellHost.NativePreviewRunCount}, "
                    + $"Layers={beforeLayerCount}->{shellHost.LayerDocumentCount}");
            }

            ToggleButton advancedToggle = FindNamedVisualChild<ToggleButton>(shellHost, "recipeAdvancedReviewToggle")
                ?? throw new InvalidOperationException("Recipe manager advanced review toggle was not found.");
            TabItem overviewTab = FindNamedVisualChild<TabItem>(shellHost, "tabRecipeOverview")
                ?? throw new InvalidOperationException("Recipe manager summary tab was not found.");
            TabItem guidedSetupTab = FindNamedVisualChild<TabItem>(shellHost, "tabRecipeGuidedSetup")
                ?? throw new InvalidOperationException("Recipe manager Guided setup tab was not found.");
            TabItem pipelineTab = FindNamedVisualChild<TabItem>(shellHost, "tabRecipePipeline")
                ?? throw new InvalidOperationException("Recipe manager Pipeline tab was not found.");
            TabItem llmXmlTab = FindNamedVisualChild<TabItem>(shellHost, "tabRecipeLlmXml")
                ?? throw new InvalidOperationException("Recipe manager LLM XML tab was not found.");
            TabItem previewTab = FindNamedVisualChild<TabItem>(shellHost, "tabRecipePreview")
                ?? throw new InvalidOperationException("Recipe manager Preview tab was not found.");

            if (!overviewTab.IsSelected
                || advancedToggle.IsChecked == true
                || advancedToggle.Visibility != Visibility.Collapsed
                || guidedSetupTab.Visibility != Visibility.Collapsed
                || pipelineTab.Visibility != Visibility.Collapsed
                || llmXmlTab.Visibility != Visibility.Collapsed
                || previewTab.Visibility != Visibility.Collapsed
                || !shellHost.RecipeCommands.OpenPipelineReviewCommand.CanExecute(null))
            {
                throw new InvalidOperationException(
                    "Recipe manager did not open on the simplified summary state. "
                    + $"SummarySelected={overviewTab.IsSelected}, Advanced={advancedToggle.IsChecked}, "
                    + $"Guided={guidedSetupTab.Visibility}, Pipeline={pipelineTab.Visibility}, "
                    + $"Llm={llmXmlTab.Visibility}, Preview={previewTab.Visibility}, "
                    + $"OpenPipeline={shellHost.RecipeCommands.OpenPipelineReviewCommand.CanExecute(null)}");
            }

            string workSampleName = shellHost.RecipeCommands.SelectedSampleOption?.SampleName ?? string.Empty;
            bool hasExpectedSummaryCopy = language == OpenVisionLanguage.English
                ? !string.IsNullOrWhiteSpace(shellHost.RecipeCommands.RecipeOverviewSelectedSampleText)
                    && !string.IsNullOrWhiteSpace(shellHost.RecipeCommands.RecipeOverviewSelectedSampleContextText)
                    && !string.IsNullOrWhiteSpace(shellHost.RecipeCommands.RecipeOverviewLastResultText)
                    && !string.IsNullOrWhiteSpace(shellHost.RecipeCommands.RecipeOverviewLastResultValueText)
                : shellHost.RecipeCommands.RecipeOverviewSelectedSampleText.Contains("작업 샘플", StringComparison.Ordinal)
                    && shellHost.RecipeCommands.RecipeOverviewSelectedSampleContextText.Contains("샘플 검사 실행 후", StringComparison.Ordinal)
                    && shellHost.RecipeCommands.RecipeOverviewLastResultText.Contains("현재 레시피", StringComparison.Ordinal)
                    && shellHost.RecipeCommands.RecipeOverviewLastResultValueText.Contains("검사하지 않음", StringComparison.Ordinal);
            if (string.IsNullOrWhiteSpace(workSampleName)
                || !hasExpectedSummaryCopy
                || shellHost.RecipeCommands.HasCurrentRecipeSampleExecution
                || shellHost.RecipeCommands.RecipeOverviewLastResultValueText.Contains(workSampleName, StringComparison.OrdinalIgnoreCase))
            {
                throw new InvalidOperationException(
                    "Recipe manager summary presented a workspace sample as recipe validation evidence before an explicit sample run. "
                    + $"Sample='{workSampleName}', Label='{shellHost.RecipeCommands.RecipeOverviewSelectedSampleText}', "
                    + $"Context='{shellHost.RecipeCommands.RecipeOverviewSelectedSampleContextText}', "
                    + $"LatestLabel='{shellHost.RecipeCommands.RecipeOverviewLastResultText}', "
                    + $"Latest='{shellHost.RecipeCommands.RecipeOverviewLastResultValueText}', "
                    + $"HasExecution={shellHost.RecipeCommands.HasCurrentRecipeSampleExecution}");
            }

            shellHost.RecipeCommands.OpenPipelineReviewCommand.Execute(null);
            Pump(100);
            if (recipeManagerButton.IsChecked == true
                || !shellHost.IsActiveWpfToolWindowVisibleForTest
                || shellHost.PipelineReviewStepCount != 2
                || !string.Equals(shellHost.PipelineReviewRecipeContextNameForTest, recipe, StringComparison.Ordinal)
                || !string.Equals(shellHost.PipelineReviewRecipeContextPipelineNameForTest, beforePipeline, StringComparison.Ordinal)
                || shellHost.NativePreviewRunCount != beforeRuns
                || shellHost.HasNativePreviewResult
                || shellHost.RecipeCommands.HasCurrentRecipeSampleExecution
                || shellHost.RecipeCommands.RecipeOverviewLastResultValueText.Contains(workSampleName, StringComparison.OrdinalIgnoreCase))
            {
                throw new InvalidOperationException(
                    "Recipe manager Pipeline entry did not open the existing Pipeline Review without execution. "
                    + $"ManagerOpen={recipeManagerButton.IsChecked}, ToolVisible={shellHost.IsActiveWpfToolWindowVisibleForTest}, "
                    + $"Steps={shellHost.PipelineReviewStepCount}, Recipe='{shellHost.PipelineReviewRecipeContextNameForTest}', "
                    + $"Pipeline='{shellHost.PipelineReviewRecipeContextPipelineNameForTest}', RunsBefore={beforeRuns}, "
                    + $"RunsAfter={shellHost.NativePreviewRunCount}, Preview={shellHost.HasNativePreviewResult}");
            }

            DependencyObject pipelineReviewRoot = FindVisualChildren<OpenVisionPipelineReviewView>(shellHost)
                .FirstOrDefault(view => view.IsVisible)
                ?? throw new InvalidOperationException(
                    "Recipe manager Pipeline Review did not expose its active document view.");
            AssertVisibleAutomationIds(
                pipelineReviewRoot,
                "Recipe manager Pipeline Review header",
                "PipelineReviewReturnToRecipeButton",
                "PipelineReviewRecipeContext",
                "PipelineReviewRunReviewButton");
            string pipelineReviewText = string.Join(
                " | ",
                FindVisualChildren<TextBlock>(pipelineReviewRoot)
                    .Select(item => item.Text)
                    .Where(item => !string.IsNullOrWhiteSpace(item)));
            if (!pipelineReviewText.Contains(recipe, StringComparison.Ordinal))
            {
                throw new InvalidOperationException(
                    "Recipe manager Pipeline Review context did not show the owning recipe. "
                    + $"Recipe='{recipe}', Text='{pipelineReviewText}'");
            }

            WaitForTaskWithPump(shellHost.RunPipelineReviewForTestAsync(), 30000, "Recipe manager explicit Pipeline Review execution");
            Pump(100);
            if (!shellHost.PipelineReviewResultSummaryText.Contains("OK", StringComparison.OrdinalIgnoreCase))
            {
                throw new InvalidOperationException(
                    "Recipe manager Pipeline Review did not expose an OK result after explicit Run Review. "
                    + $"Result='{shellHost.PipelineReviewResultSummaryText}', Detail='{shellHost.PipelineReviewResultDetailText}'");
            }

            if (!shellHost.IsDockedDocumentWorkspaceVisibleForTest
                && !shellHost.DockActiveWpfToolWindowForTest())
            {
                throw new InvalidOperationException("Recipe manager Pipeline Review could not be docked before return.");
            }

            Pump(80);
            if (!shellHost.IsDockedDocumentWorkspaceVisibleForTest
                || shellHost.IsDockedToolInspectorVisibleForTest)
            {
                throw new InvalidOperationException("Recipe manager Pipeline Review central docked return precondition was not visible.");
            }

            ClickVisibleButtonByName("btnReturnToRecipe", "Pipeline Review return-to-recipe button");
            Pump(100);
            if (recipeManagerButton.IsChecked != true
                || shellHost.IsActiveWpfToolWindowVisibleForTest
                || !string.Equals(shellHost.SelectedRecipeNameForTest, recipe, StringComparison.Ordinal)
                || !string.Equals(shellHost.ActiveRecipeContextNameForTest, recipe, StringComparison.Ordinal)
                || !string.Equals(shellHost.ActiveRecipeContextPipelineNameForTest, beforePipeline, StringComparison.Ordinal)
                || !string.Equals(shellHost.ActiveRecipeContextLayerNameForTest, beforeRecipeLayer, StringComparison.Ordinal)
                || shellHost.LayerDocumentCount != beforeLayerCount
                || !string.Equals(shellHost.ActiveHostLayerTitle, beforeActiveLayer, StringComparison.Ordinal)
                || shellHost.NativePreviewRunCount != beforeRuns
                || shellHost.HasNativePreviewResult)
            {
                throw new InvalidOperationException(
                    "Pipeline Review did not return to the same recipe summary without native Preview, layer, or routing side effects. "
                    + $"ManagerOpen={recipeManagerButton.IsChecked}, ToolVisible={shellHost.IsActiveWpfToolWindowVisibleForTest}, "
                    + $"SelectedRecipe='{shellHost.SelectedRecipeNameForTest}', Context='{shellHost.ActiveRecipeContextNameForTest}', "
                    + $"Pipeline='{shellHost.ActiveRecipeContextPipelineNameForTest}', RecipeLayer='{shellHost.ActiveRecipeContextLayerNameForTest}', "
                    + $"Layers={shellHost.LayerDocumentCount}/{beforeLayerCount}, ActiveLayer='{shellHost.ActiveHostLayerTitle}/{beforeActiveLayer}', "
                    + $"Runs={shellHost.NativePreviewRunCount}/{beforeRuns}, Preview={shellHost.HasNativePreviewResult}, "
                    + $"SampleExecution={shellHost.RecipeCommands.HasCurrentRecipeSampleExecution}, "
                    + $"SampleResult='{shellHost.RecipeCommands.RecipeOverviewLastResultValueText}'");
            }

            recipeManagerButton.IsChecked = false;
            Pump(40);
            shellHost.RecipeCommands.OpenMainRecipeWorkCommand.Execute("Pipeline"); // Legacy contract fixture, independent of the display-only Main title.
            Pump(40);
            if (recipeManagerButton.IsChecked == true
                || !shellHost.RecipeCommands.IsRecipeManagerDetailContextActive
                || advancedToggle.IsChecked != true
                || !string.Equals(shellHost.RecipeCommands.RecipeManagerSelectedRecipeName, recipe, StringComparison.Ordinal)
                || !string.Equals(shellHost.RecipeCommands.SelectedPipelineOption?.PipelineName, beforePipeline, StringComparison.Ordinal)
                || !pipelineTab.IsSelected
                || overviewTab.Visibility != Visibility.Collapsed
                || guidedSetupTab.Visibility != Visibility.Visible
                || pipelineTab.Visibility != Visibility.Visible
                || llmXmlTab.Visibility != Visibility.Visible
                || previewTab.Visibility != Visibility.Visible
                || shellHost.NativePreviewRunCount != beforeRuns
                || shellHost.LayerDocumentCount != beforeLayerCount)
            {
                throw new InvalidOperationException(
                    "Main inspection work did not open the current Recipe/Pipeline without execution. "
                    + $"ManagerOpen={recipeManagerButton.IsChecked}, Detail={shellHost.RecipeCommands.IsRecipeManagerDetailContextActive}, "
                    + $"Recipe='{shellHost.RecipeCommands.RecipeManagerSelectedRecipeName}', Pipeline='{shellHost.RecipeCommands.SelectedPipelineOption?.PipelineName}', "
                    + $"Overview={overviewTab.Visibility}, PipelineSelected={pipelineTab.IsSelected}, "
                    + $"Guided={guidedSetupTab.Visibility}, Pipeline={pipelineTab.Visibility}, "
                    + $"Llm={llmXmlTab.Visibility}, Preview={previewTab.Visibility}, "
                    + $"Runs={beforeRuns}->{shellHost.NativePreviewRunCount}, Layers={beforeLayerCount}->{shellHost.LayerDocumentCount}");
            }
            AssertHiddenAutomationIds(
                shellHost,
                "WPF main inspection work file-action separation",
                "HostRecipeAdvancedTransferCommands",
                "HostRecipeImportXmlButton",
                "HostRecipeExportXmlButton",
                "HostRecipeExportReviewBundleButton");
            AssertHiddenAutomationIds(
                shellHost,
                "WPF recipe manager separated advanced workspace",
                "HostRecipeManagerLibraryPane",
                "HostRecipeFilterTextBox",
                "HostRecipeManagerList",
                "HostRecipeManagerCommandStrip",
                "HostRecipeNameEditor",
                "HostRecipeCreateNamedButton",
                "HostRecipeDuplicateButton",
                "HostRecipeRenameButton",
                "HostRecipeDeleteButton");

            guidedSetupTab.IsSelected = true;
            ClickVisibleButtonByAutomationId(shellHost, "HostRecipeManagerCloseButton", "inspection work close button");
            Pump(40);
            if (shellHost.RecipeCommands.IsRecipeManagerDetailContextActive
                || advancedToggle.IsChecked == true
                || recipeManagerButton.IsChecked == true
                || shellHost.NativePreviewRunCount != beforeRuns
                || shellHost.HasNativePreviewResult)
            {
                throw new InvalidOperationException(
                    "Closing main inspection work kept the detail context or changed execution state. "
                    + $"Detail={shellHost.RecipeCommands.IsRecipeManagerDetailContextActive}, Advanced={advancedToggle.IsChecked}, "
                    + $"RunsBefore={beforeRuns}, RunsAfter={shellHost.NativePreviewRunCount}, Preview={shellHost.HasNativePreviewResult}");
            }

            recipeManagerButton.IsChecked = true;
            Pump(40);
            if (!overviewTab.IsSelected
                || guidedSetupTab.Visibility != Visibility.Collapsed
                || advancedToggle.Visibility != Visibility.Collapsed)
            {
                throw new InvalidOperationException(
                    "Recipe manager did not reopen on management summary after main work. "
                    + $"SummarySelected={overviewTab.IsSelected}, Guided={guidedSetupTab.Visibility}, Advanced={advancedToggle.Visibility}");
            }

            AssertVisibleAutomationIds(
                shellHost,
                "WPF recipe manager simplified summary",
                "HostRecipeOverviewPanel",
                "HostRecipeOverviewName",
                "HostRecipeOverviewPipelineCard",
                "HostRecipeManagerFileActions",
                "HostRecipeStoredInspectionSelector",
                "HostRecipeStoredStepList",
                "HostRecipeManagerLibraryPane",
                "HostRecipeFilterTextBox",
                "HostRecipeManagerList",
                "HostRecipeManagerCommandStrip",
                "HostRecipeNameEditor",
                "HostRecipeCreateNamedButton");
            AssertHiddenAutomationIds(
                shellHost,
                "WPF recipe manager summary lifecycle separation",
                "HostRecipeAdvancedTransferCommands",
                "HostRecipeAdvancedReviewToggle",
                "HostRecipeOverviewValidationCard",
                "HostRecipeOpenPipelineReviewButton",
                "HostRecipeOpenImageListValidationButton",
                "HostRecipeEditSavedStepButton",
                "HostRecipeImportXmlButton",
                "HostRecipeExportXmlButton",
                "HostRecipeExportReviewBundleButton");
        }, captureFloatingToolWindow: false);
    }

    private static CaptureResult CaptureShellHostRecipeHybridRelativeRoiGuidedSetup(string outputPath)
    {
        OpenVisionLanguageService.SetLanguage(OpenVisionLanguage.Korean, false);
        SmokeRecipeWorkspaceCleanup.DeleteTransient();

        string recipe = "Smoke_HybridRelativeRoi_" + Guid.NewGuid().ToString("N").Substring(0, 12);
        VisionPipelineStorage.Save(recipe, RecipeContextFixture.CreatePipeline("Hybrid_Relative_Roi_Source", 1));
        VisionPipelineStorage.SaveActivePipelineName(recipe, "Hybrid_Relative_Roi_Source");
        OpenVisionShellHostView shellHost = CreateShellHost(recipe, seedMainLayer: false);
        try
        {
            return CaptureWindowWithContent(shellHost, outputPath, 1600, 900, () =>
            {
                ToggleButton recipeManagerButton = FindNamedVisualChild<ToggleButton>(shellHost, "btnHostRecipeManager")
                    ?? throw new InvalidOperationException("Hybrid relative-ROI smoke could not find Recipe Manager.");
                recipeManagerButton.IsChecked = true;
                Pump(100);
                TabItem guidedSetupTab = FindNamedVisualChild<TabItem>(shellHost, "tabRecipeGuidedSetup")
                    ?? throw new InvalidOperationException("Hybrid relative-ROI smoke could not find Guided Setup.");
                guidedSetupTab.IsSelected = true;

                string templatePath = Path.GetFullPath(Path.Combine(
                    "docs",
                    "samples",
                    "public",
                    "templates",
                    "Matching_DiePad_Synthetic_Template.png"));
                if (!File.Exists(templatePath))
                {
                    throw new InvalidOperationException("Hybrid relative-ROI smoke locator template is missing: " + templatePath);
                }

                int runsBefore = shellHost.NativePreviewRunCount;
                int layersBefore = shellHost.LayerDocumentCount;
                shellHost.RecipeCommands.SelectedLlmToolTemplate = OpenVisionGuidedSetupCatalog.HybridRelativeRoiGapTemplate;
                shellHost.RecipeCommands.LlmReferenceImagePath = templatePath;
                shellHost.RecipeCommands.MatchingIntentSearchRoiText = "0,0,572,420";
                shellHost.RecipeCommands.HybridReferencePoseText = "286,210,0,1,572,420";
                shellHost.RecipeCommands.HybridRelativeRoiText = "100,80,300,100";
                shellHost.RecipeCommands.MatchingIntentScoreMinText = "0.8";
                shellHost.RecipeCommands.HybridScoreMarginText = "10";
                shellHost.RecipeCommands.HybridAngleMinimumText = "-5";
                shellHost.RecipeCommands.HybridAngleMaximumText = "5";
                shellHost.RecipeCommands.HybridScaleRatioMinimumText = "0.8";
                shellHost.RecipeCommands.HybridScaleRatioMaximumText = "1.8";
                shellHost.RecipeCommands.HybridMinimumValidPixelRatioText = "0.25";
                Pump(80);

                FrameworkElement panel = FindVisualChildren<FrameworkElement>(shellHost)
                    .First(item => string.Equals(
                        AutomationProperties.GetAutomationId(item),
                        "HostRecipeGuidedSetupHybridRelativeRoiInputs",
                        StringComparison.Ordinal));
                panel.BringIntoView();
                shellHost.UpdateLayout();
                Pump(80);

                AssertVisibleAutomationIds(
                    shellHost,
                    "Hybrid relative-ROI Guided Setup inputs",
                    "HostRecipeGuidedSetupHybridRelativeRoiInputs",
                    "HostRecipeGuidedSetupHybridLocatorTemplatePath",
                    "HostRecipeGuidedSetupHybridSearchRoiText",
                    "HostRecipeGuidedSetupHybridReferencePoseText",
                    "HostRecipeGuidedSetupHybridMeasurementRoiText",
                    "HostRecipeGuidedSetupHybridScoreMinimumText",
                    "HostRecipeGuidedSetupHybridScoreMarginText",
                    "HostRecipeGuidedSetupHybridAngleMinimumText",
                    "HostRecipeGuidedSetupHybridAngleMaximumText",
                    "HostRecipeGuidedSetupHybridScaleRatioMinimumText",
                    "HostRecipeGuidedSetupHybridScaleRatioMaximumText",
                    "HostRecipeGuidedSetupHybridMinimumValidPixelRatioText",
                    "HostRecipeGuidedSetupHybridBoundary");
                if (!shellHost.RecipeCommands.IsGuidedSetupIntentInputReady
                    || !shellHost.RecipeCommands.GuidedSetupIntentInputStatusText.Contains("LOCATION GATED", StringComparison.OrdinalIgnoreCase)
                    || !shellHost.RecipeCommands.CreateGuidedSetupStarterXmlCommand.CanExecute(null))
                {
                    throw new InvalidOperationException(
                        "Hybrid relative-ROI Guided Setup did not become ready. "
                        + shellHost.RecipeCommands.GuidedSetupIntentInputStatusText);
                }

                shellHost.RecipeCommands.CreateGuidedSetupStarterXmlCommand.Execute(null);
                Pump(120);
                string validXml = shellHost.RecipeCommands.LlmXmlDraftText;
                if (!SerializeHelper.TryLoadFromXmlText(validXml, out VisionPipeline validPipeline, out string parseError))
                {
                    throw new InvalidOperationException("Hybrid relative-ROI starter XML could not be parsed: " + parseError);
                }

                string[] expectedTools = { "Matching", "Matching", "RotateScale", "LineDistance" };
                string[] actualTools = validPipeline.Steps.Where(step => step != null && step.Enabled).Select(step => step.ToolType).ToArray();
                if (!actualTools.SequenceEqual(expectedTools, StringComparer.OrdinalIgnoreCase)
                    || !string.Equals(validPipeline.Steps[2].InputLayer, "Main", StringComparison.OrdinalIgnoreCase)
                    || !string.Equals(validPipeline.Steps[2].OutputLayer, "DeviceAligned", StringComparison.OrdinalIgnoreCase)
                    || !string.Equals(validPipeline.Steps[3].InputLayer, "DeviceAligned", StringComparison.OrdinalIgnoreCase)
                    || !validPipeline.Steps[3].Parameters.TryGetValue("CvROI", out string? measurementRoi)
                    || !string.Equals(measurementRoi, "100,80,300,100", StringComparison.Ordinal)
                    || !shellHost.RecipeCommands.LlmXmlDraftValidationReport.Contains("Hybrid relative-ROI contract: OK", StringComparison.OrdinalIgnoreCase)
                    || !shellHost.RecipeCommands.LlmXmlDraftValidationReport.Contains("LOCATION GATED / MEASURE ONLY / NOT JUDGED", StringComparison.OrdinalIgnoreCase)
                    || !shellHost.RecipeCommands.LlmXmlDraftValidationReport.Contains("drawings: WAIT", StringComparison.OrdinalIgnoreCase)
                    || !shellHost.RecipeCommands.ImportLlmXmlDraftCommand.CanExecute(null)
                    || shellHost.NativePreviewRunCount != runsBefore
                    || shellHost.LayerDocumentCount != layersBefore)
                {
                    throw new InvalidOperationException(
                        "Hybrid relative-ROI starter did not preserve its locked four-Step route or no-auto-run contract. "
                        + shellHost.RecipeCommands.LlmXmlDraftValidationReport);
                }

                Func<VisionPipeline, string> serializeMutation = pipeline =>
                {
                    string tempPath = Path.Combine(Path.GetTempPath(), "OpenVisionLab_hybrid_relative_roi_" + Guid.NewGuid().ToString("N") + ".xml");
                    try
                    {
                        if (!SerializeHelper.SaveXmlFile(tempPath, pipeline))
                        {
                            throw new InvalidOperationException("Could not serialize a hybrid relative-ROI mutation.");
                        }

                        return File.ReadAllText(tempPath);
                    }
                    finally
                    {
                        TryDeleteFile(tempPath);
                    }
                };

                if (!SerializeHelper.TryLoadFromXmlText(validXml, out VisionPipeline wrongToolPipeline, out _))
                {
                    throw new InvalidOperationException("Could not clone the hybrid relative-ROI starter for tool mutation.");
                }

                wrongToolPipeline.Steps[2].ToolType = "Threshold";
                shellHost.RecipeCommands.LlmXmlDraftText = serializeMutation(wrongToolPipeline);
                if (shellHost.RecipeCommands.ValidateLlmXmlDraftTextForTest()
                    || !shellHost.RecipeCommands.LlmXmlDraftValidationReport.Contains("Hybrid relative-ROI contract: NG", StringComparison.OrdinalIgnoreCase))
                {
                    throw new InvalidOperationException("Hybrid relative-ROI validation accepted a changed NormalizeImage tool family.");
                }

                if (!SerializeHelper.TryLoadFromXmlText(validXml, out VisionPipeline wrongRoiPipeline, out _))
                {
                    throw new InvalidOperationException("Could not clone the hybrid relative-ROI starter for ROI mutation.");
                }

                wrongRoiPipeline.Steps[3].Parameters["CvROI"] = "101,80,300,100";
                shellHost.RecipeCommands.LlmXmlDraftText = serializeMutation(wrongRoiPipeline);
                if (shellHost.RecipeCommands.ValidateLlmXmlDraftTextForTest())
                {
                    throw new InvalidOperationException("Hybrid relative-ROI validation accepted a changed measurement ROI.");
                }

                if (!SerializeHelper.TryLoadFromXmlText(validXml, out VisionPipeline weakGatePipeline, out _))
                {
                    throw new InvalidOperationException("Could not clone the hybrid relative-ROI starter for gate mutation.");
                }

                weakGatePipeline.Steps[0].AcceptanceMetricMinimum = 1D;
                shellHost.RecipeCommands.LlmXmlDraftText = serializeMutation(weakGatePipeline);
                if (shellHost.RecipeCommands.ValidateLlmXmlDraftTextForTest())
                {
                    throw new InvalidOperationException("Hybrid relative-ROI validation accepted a weakened ambiguity gate.");
                }

                shellHost.RecipeCommands.LlmXmlDraftText = validXml;
                if (!shellHost.RecipeCommands.ValidateLlmXmlDraftTextForTest()
                    || shellHost.NativePreviewRunCount != runsBefore
                    || shellHost.LayerDocumentCount != layersBefore)
                {
                    throw new InvalidOperationException("Hybrid relative-ROI valid starter did not restore import readiness without side effects.");
                }

                panel.BringIntoView();
                shellHost.UpdateLayout();
                Pump(80);
            }, captureFloatingToolWindow: false, captureScreen: false);
        }
        finally
        {
            RecipeWorkspaceService.DeleteVisionWorkspace(recipe);
        }
    }

    private static CaptureResult CaptureShellHostRecipeLocatorRelativeBlobGuidedSetup(string outputPath)
    {
