                viewModel.RecommendedStartText,
                viewModel.ResultExplanationText,
                viewModel.FailureCauseText,
                viewModel.BenchmarkOutcomeText,
                viewModel.BenchmarkPairText,
                viewModel.SelectedSample.ExpectedText,
                viewModel.SelectedSample.PairGroup,
                "Preview",
                "Run"
            };
            string? missing = requiredTokens.FirstOrDefault(token => !visibleText.Contains(token, StringComparison.Ordinal));
            if (!string.IsNullOrWhiteSpace(missing))
            {
                throw new InvalidOperationException(
                    "Workspace sample pair picker did not show expected pair token '" + missing + "'. Text='" + visibleText + "'");
            }

            VisionPipelineSampleCatalogItem originalSample = viewModel.SelectedSample;
            if (!viewModel.SelectCounterpartSampleCommand.CanExecute(null))
            {
                throw new InvalidOperationException("Workspace sample pair picker did not enable the explicit opposite-reference selection command.");
            }

            viewModel.SelectCounterpartSampleCommand.Execute(null);
            Pump(40);
            if (viewModel.SelectedSample == null
                || ReferenceEquals(viewModel.SelectedSample, originalSample)
                || !viewModel.SelectedSample.ExpectsFailure
                || !string.Equals(viewModel.SelectedSample.PairGroup, originalSample.PairGroup, StringComparison.OrdinalIgnoreCase))
            {
                throw new InvalidOperationException(
                    "Workspace sample pair picker did not switch from the Good sample to the paired NG reference. "
                    + $"Original={originalSample.SampleName}, Selected={viewModel.SelectedSample?.SampleName ?? "-"}");
            }

            viewModel.SelectCounterpartSampleCommand.Execute(null);
            Pump(40);
            if (!ReferenceEquals(viewModel.SelectedSample, originalSample))
            {
                throw new InvalidOperationException(
                    "Workspace sample pair picker did not switch back from the NG reference to the original Good sample. "
                    + $"Original={originalSample.SampleName}, Selected={viewModel.SelectedSample?.SampleName ?? "-"}");
            }
        });
    }

    private static CaptureResult CaptureShellHostWorkspaceSampleFixturePicker(string outputPath)
    {
        OpenVisionLanguageService.SetLanguage(OpenVisionLanguage.Korean, false);
        List<VisionPipelineSampleCatalogItem> samples = VisionPipelineSampleCatalogItem.LoadRunnable()
            .Where(item => item.CanOpen)
            .ToList();
        OpenVisionWorkspaceSamplePickerViewModel viewModel = new(samples);
        OpenVisionWorkspaceSamplePickerWindow window = new(viewModel);
        return CaptureStandaloneWindow(window, outputPath, 1040, 742, () =>
        {
            viewModel.SearchText = "Fixture";
            Pump(60);

            AssertVisibleAutomationIds(
                window,
                "WPF workspace Fixture sample picker",
                "WorkspaceSamplePickerTitleBar",
                "WorkspaceSamplePickerView",
                "WorkspaceSamplePickerSearchBox",
                "WorkspaceSamplePickerCatalogSourceList",
                "WorkspaceSamplePickerSampleFocusList",
                "WorkspaceSamplePickerLearnPathList",
                "WorkspaceSamplePickerList",
                "WorkspaceSamplePickerCancelButton");

            ListBox? sampleList = FindVisualChildren<ListBox>(window)
                .FirstOrDefault(item => string.Equals(
                    System.Windows.Automation.AutomationProperties.GetAutomationId(item),
                    "WorkspaceSamplePickerList",
                    StringComparison.Ordinal));
            if (sampleList == null || sampleList.Items.Count != viewModel.VisibleSampleCount)
            {
                throw new InvalidOperationException(
                    "Workspace Fixture search result count does not match the rendered list. "
                    + $"ViewModel={viewModel.VisibleSampleCount}, List={sampleList?.Items.Count ?? -1}");
            }

            VisionPipelineSampleCatalogItem? fixtureGood = samples.FirstOrDefault(item =>
                string.Equals(item.SampleName, "Public_Fixture_Pad_Good", StringComparison.OrdinalIgnoreCase));
            if (fixtureGood == null)
            {
                if (viewModel.VisibleSampleCount != 0 || viewModel.SelectedSample != null)
                {
                    throw new InvalidOperationException(
                        "Fixture baseline capture expected no public Fixture sample before catalog registration.");
                }

                return;
            }

            viewModel.SelectedSample = fixtureGood;
            Pump(40);
            List<VisionPipelineSampleCatalogItem> fixturePair = samples
                .Where(item => string.Equals(
                    item.PairGroup?.Trim(),
                    fixtureGood.PairGroup?.Trim(),
                    StringComparison.OrdinalIgnoreCase))
                .ToList();
            int visibleFixturePairCount = sampleList.Items
                .OfType<VisionPipelineSampleCatalogItem>()
                .Count(item => string.Equals(
                    item.PairGroup?.Trim(),
                    fixtureGood.PairGroup?.Trim(),
                    StringComparison.OrdinalIgnoreCase));
            if (fixturePair.Count != 2
                || !fixturePair.Any(IsSamplePairGood)
                || !fixturePair.Any(IsSamplePairBad)
                || !fixtureGood.HasPair
                || visibleFixturePairCount != fixturePair.Count
                || !string.Equals(fixtureGood.PairGroup, "Public_Fixture_Pad", StringComparison.OrdinalIgnoreCase))
            {
                throw new InvalidOperationException(
                    "Public Fixture search must expose one runnable Good/Bad pair. "
                    + $"Visible={viewModel.VisibleSampleCount}, VisiblePair={visibleFixturePairCount}, Pair={fixtureGood.PairGroup}");
            }

            string visibleText = string.Join(
                " | ",
                FindVisualChildren<TextBlock>(window)
                    .Select(item => item.Text)
                    .Where(text => !string.IsNullOrWhiteSpace(text)));
            string[] requiredTokens =
            {
                fixtureGood.SampleName,
                fixtureGood.PairGroup,
                "Matching",
                "Blob",
                fixtureGood.ExpectedText
            };
            string? missing = requiredTokens.FirstOrDefault(token =>
                !visibleText.Contains(token, StringComparison.OrdinalIgnoreCase));
            if (!string.IsNullOrWhiteSpace(missing))
            {
                throw new InvalidOperationException(
                    "Workspace Fixture sample picker did not show token '" + missing + "'. Text='" + visibleText + "'");
            }
        });
    }

    private static CaptureResult CaptureShellHostWorkspaceSamplePairCoverage(string outputPath)
    {
        OpenVisionLanguageService.SetLanguage(OpenVisionLanguage.Korean, false);
        DateTime started = DateTime.UtcNow;
        List<VisionPipelineSampleCatalogItem> samples = VisionPipelineSampleCatalogItem.LoadRunnable()
            .Where(item => item.CanOpen)
            .ToList();
        if (samples.Count == 0)
        {
            throw new InvalidOperationException("Workspace sample pair coverage could not find runnable catalog samples.");
        }

        List<IGrouping<string, VisionPipelineSampleCatalogItem>> pairGroups = samples
            .Where(item => item.HasPair && !string.IsNullOrWhiteSpace(item.PairGroup))
            .GroupBy(item => item.PairGroup.Trim(), StringComparer.OrdinalIgnoreCase)
            .Where(group => group.Any(IsSamplePairGood) && group.Any(IsSamplePairBad))
            .OrderBy(group => group.Key, StringComparer.OrdinalIgnoreCase)
            .ToList();
        string[] requiredPairGroups =
        {
            "Public_Blob_Particles",
            "Public_Contour_Shapes",
            "Public_Line_Pins",
            "Public_Matching_DiePad",
            "Public_Fixture_Pad",
            "Public_Edge_Fiducial",
            "Public_Feature_Card",
            "Public_Mean_BrightnessDrift",
            "Public_Threshold_BandPads",
            "Battery_TabGap",
            "Display_Particle",
            "Semiconductor_PackagePolarity"
        };

        foreach (string requiredPairGroup in requiredPairGroups)
        {
            if (!pairGroups.Any(group => string.Equals(group.Key, requiredPairGroup, StringComparison.OrdinalIgnoreCase)))
            {
                throw new InvalidOperationException("Sample catalog is missing required Good/Bad pair group: " + requiredPairGroup);
            }
        }

        foreach (IGrouping<string, VisionPipelineSampleCatalogItem> group in pairGroups)
        {
            ValidateSamplePairGroup(group.Key, group.ToList());
        }

        string[] executionGroups =
        {
            "Public_Blob_Particles",
            "Public_Line_Pins",
            "Public_Matching_DiePad",
            "Public_Fixture_Pad",
            "Public_Mean_BrightnessDrift",
            "Display_Particle"
        };
        List<string> executionLines = new();
        foreach (string groupName in executionGroups)
        {
            List<VisionPipelineSampleCatalogItem> groupSamples = pairGroups
                .First(group => string.Equals(group.Key, groupName, StringComparison.OrdinalIgnoreCase))
                .OrderBy(item => IsSamplePairGood(item) ? 0 : 1)
                .ThenBy(item => item.SampleName, StringComparer.OrdinalIgnoreCase)
                .ToList();
            foreach (VisionPipelineSampleCatalogItem sample in groupSamples.Where(item => IsSamplePairGood(item)).Take(1)
                .Concat(groupSamples.Where(item => IsSamplePairBad(item)).Take(1)))
            {
                VisionPipelineSampleCheckResult result = VisionPipelineSampleCheckService.RunSampleCheckSafe(sample);
                if (!result.Success)
                {
                    throw new InvalidOperationException(
                        "Sample pair execution failed. "
                        + $"Group={groupName}, Sample={sample.SampleName}, Status={result.Status}, Message={result.Message}, Metrics={result.MetricText}");
                }

                executionLines.Add($"{groupName} / {sample.PairRole}: {sample.SampleName} / {result.MetricText}");
            }
        }

        string reportText =
            "Good/Bad Sample Pair Coverage OK"
            + Environment.NewLine
            + $"Runnable samples: {samples.Count}"
            + Environment.NewLine
            + $"Pair groups: {pairGroups.Count}"
            + Environment.NewLine
            + $"Required groups: {requiredPairGroups.Length}"
            + Environment.NewLine
            + $"Executed reference samples: {executionLines.Count}"
            + Environment.NewLine
            + Environment.NewLine
            + string.Join(Environment.NewLine, executionLines);

        Border report = new()
        {
            Background = Brushes.White,
            Padding = new Thickness(24),
            Child = new TextBlock
            {
                Text = reportText,
                FontSize = 15,
                FontFamily = new FontFamily("Consolas"),
                Foreground = Brushes.DarkSlateGray,
                TextWrapping = TextWrapping.Wrap
            }
        };

        CaptureResult capture = CaptureElement(report, outputPath, 1120, 620);
        return new CaptureResult(capture.Width, capture.Height, (DateTime.UtcNow - started).TotalMilliseconds);
    }

    private static CaptureResult CaptureThresholdSignalGoodBadReplay(string outputPath)
    {
        const string goodSampleName = "Public_Threshold_BandPads_Good";
        const string badSampleName = "Public_Threshold_BandPads_Missing_Bad";
        const string expectedPairGroup = "Public_Threshold_BandPads";
        const double frozenThreshold = 130D;

        DateTime started = DateTime.UtcNow;
        VisionPipelineSampleCatalogItem goodSample = FindRunnableCatalogSample(goodSampleName);
        VisionPipelineSampleCatalogItem badSample = FindRunnableCatalogSample(badSampleName);
        AssertSampleSourceKind(goodSample, goodSampleName, VisionPipelineSampleCatalogSourceKind.Public);
        AssertSampleSourceKind(badSample, badSampleName, VisionPipelineSampleCatalogSourceKind.Public);
        if (!string.Equals(goodSample.PairGroup, expectedPairGroup, StringComparison.OrdinalIgnoreCase)
            || !string.Equals(badSample.PairGroup, expectedPairGroup, StringComparison.OrdinalIgnoreCase)
            || !string.Equals(
                Path.GetFullPath(goodSample.PipelineFullPath),
                Path.GetFullPath(badSample.PipelineFullPath),
                StringComparison.OrdinalIgnoreCase))
        {
            throw new InvalidOperationException(
                "Threshold signal Good/Bad replay must use one public pair and the same frozen Pipeline. "
                + $"GoodGroup={goodSample.PairGroup}, BadGroup={badSample.PairGroup}, "
                + $"GoodPipeline={goodSample.PipelineFullPath}, BadPipeline={badSample.PipelineFullPath}");
        }

        if (!VisionPipelineStorage.TryLoadFromFile(
                goodSample.PipelineFullPath,
                out VisionPipeline pipeline,
                out string pipelineLoadMessage)
            || pipeline == null)
        {
            throw new InvalidOperationException(
                "Threshold signal Good/Bad replay could not load the frozen Pipeline: " + pipelineLoadMessage);
        }

        VisionPipelineStep thresholdStep = pipeline.Steps.SingleOrDefault(step =>
            string.Equals(step.ToolType, "Threshold", StringComparison.OrdinalIgnoreCase))
            ?? throw new InvalidOperationException("Threshold signal Good/Bad replay Pipeline has no Threshold Step.");
        string mode = thresholdStep.Parameters.TryGetValue("Mode", out string? modeValue)
            ? modeValue ?? string.Empty
            : string.Empty;
        string thresholdText = thresholdStep.Parameters.TryGetValue("Threshold", out string? thresholdValue)
            ? thresholdValue ?? string.Empty
            : string.Empty;
        string maxValueText = thresholdStep.Parameters.TryGetValue("MaxValue", out string? maxValue)
            ? maxValue ?? string.Empty
            : string.Empty;
        string thresholdType = thresholdStep.Parameters.TryGetValue("ThresholdType", out string? thresholdTypeValue)
            ? thresholdTypeValue ?? string.Empty
            : string.Empty;
        if (!string.Equals(mode, "Threshold", StringComparison.OrdinalIgnoreCase)
            || !double.TryParse(thresholdText, NumberStyles.Float, CultureInfo.InvariantCulture, out double parsedThreshold)
            || Math.Abs(parsedThreshold - frozenThreshold) > 0.000001D
            || !double.TryParse(maxValueText, NumberStyles.Float, CultureInfo.InvariantCulture, out double parsedMaxValue)
            || Math.Abs(parsedMaxValue - 255D) > 0.000001D
            || !string.Equals(thresholdType, "Binary", StringComparison.OrdinalIgnoreCase))
        {
            throw new InvalidOperationException(
                "Threshold signal Good/Bad replay frozen parameter contract changed. "
                + $"Mode={mode}, Threshold={thresholdText}, MaxValue={maxValueText}, Type={thresholdType}");
        }

        ThresholdToolProperty initialProperty = new()
        {
            Mode = ThresholdToolMode.Threshold,
            Threshold = 127D,
            MaxValue = 255D,
            ThresholdType = OpenCvSharp.ThresholdTypes.Binary
        };
        VisionToolSignalEvidence initialGoodEvidence =
            CreateThresholdReplaySignalEvidence(goodSample, initialProperty);
        VisionToolSignalInspectorView teachingInspector = new();
        double requestedThreshold = double.NaN;
        teachingInspector.MarkerValueChangeRequested += (_, args) =>
        {
            if (string.Equals(
                    args.MarkerId,
                    OpenVisionNativeThresholdSignalEvidenceFactory.ThresholdMarkerId,
                    StringComparison.Ordinal))
            {
                requestedThreshold = args.Value;
            }
        };
        teachingInspector.ShowEvidence(initialGoodEvidence);
        teachingInspector.CommitMarkerForTest(
            OpenVisionNativeThresholdSignalEvidenceFactory.ThresholdMarkerId,
            frozenThreshold);
        if (!double.IsFinite(requestedThreshold)
            || Math.Abs(requestedThreshold - frozenThreshold) > 0.000001D)
        {
            throw new InvalidOperationException(
                "Threshold signal chart did not commit the evidence-backed T=127 -> T=130 teaching change. "
                + $"Requested={requestedThreshold}");
        }

        ThresholdToolProperty property = new()
        {
            Mode = ThresholdToolMode.Threshold,
            Threshold = requestedThreshold,
            MaxValue = 255D,
            ThresholdType = OpenCvSharp.ThresholdTypes.Binary
        };
        VisionToolSignalEvidence goodEvidence = CreateThresholdReplaySignalEvidence(goodSample, property);
        VisionToolSignalEvidence badEvidence = CreateThresholdReplaySignalEvidence(badSample, property);
        if (initialGoodEvidence.Markers.Count != 1
            || Math.Abs(initialGoodEvidence.Markers[0].X - 127D) > 0.000001D
            || goodEvidence.Markers.Count != 1
            || badEvidence.Markers.Count != 1
            || Math.Abs(goodEvidence.Markers[0].X - frozenThreshold) > 0.000001D
            || Math.Abs(badEvidence.Markers[0].X - frozenThreshold) > 0.000001D
            || !string.Equals(
                initialGoodEvidence.SourceSha256,
                goodEvidence.SourceSha256,
                StringComparison.Ordinal)
            || string.Equals(
                initialGoodEvidence.EvidenceId,
                goodEvidence.EvidenceId,
                StringComparison.Ordinal)
            || !string.Equals(goodEvidence.RegionDescription, "Full image", StringComparison.Ordinal)
            || !string.Equals(badEvidence.RegionDescription, "Full image", StringComparison.Ordinal))
        {
            throw new InvalidOperationException(
                "Threshold signal evidence did not retain the full-image T=127 -> T=130 teaching identity. "
                + $"BeforeMarker={initialGoodEvidence.Markers.FirstOrDefault()?.X}, "
                + $"GoodMarker={goodEvidence.Markers.FirstOrDefault()?.X}, BadMarker={badEvidence.Markers.FirstOrDefault()?.X}, "
                + $"GoodRegion={goodEvidence.RegionDescription}, BadRegion={badEvidence.RegionDescription}");
        }

        VisionPipelineSampleCheckResult goodCheck = VisionPipelineSampleCheckService.RunSampleCheckSafe(goodSample);
        VisionPipelineSampleCheckResult badCheck = VisionPipelineSampleCheckService.RunSampleCheckSafe(badSample);
        if (!goodCheck.Success
            || !goodCheck.ActualSuccess
            || !goodCheck.MetricText.Contains("ResultCount=4", StringComparison.OrdinalIgnoreCase)
            || !badCheck.Success
            || badCheck.ActualSuccess
            || !badSample.ExpectsFailure
            || !badCheck.MetricText.Contains("ResultCount=1", StringComparison.OrdinalIgnoreCase))
        {
            throw new InvalidOperationException(
                "Threshold signal Good/Bad replay did not preserve the frozen T=130 decision. "
                + $"GoodStatus={goodCheck.Status}, GoodActual={goodCheck.ActualSuccess}, GoodMetrics='{goodCheck.MetricText}', "
                + $"BadStatus={badCheck.Status}, BadActual={badCheck.ActualSuccess}, BadExpectedFailure={badSample.ExpectsFailure}, "
                + $"BadMetrics='{badCheck.MetricText}'");
        }

        string artifactDirectory = Path.GetDirectoryName(Path.GetFullPath(outputPath))
            ?? throw new InvalidOperationException("Threshold replay output directory could not be resolved.");
        Directory.CreateDirectory(artifactDirectory);
        string beforeGoodTsvPath = Path.Combine(artifactDirectory, "ThresholdSignal_Good_Before_T127.tsv");
        string goodTsvPath = Path.Combine(artifactDirectory, "ThresholdSignal_Good_T130.tsv");
        string badTsvPath = Path.Combine(artifactDirectory, "ThresholdSignal_Bad_T130.tsv");
        string diagnosticsPath = Path.Combine(artifactDirectory, "Threshold_GoodBad_Replay_T130.txt");
        VisionToolSignalEvidenceExporter.ExportTsv(initialGoodEvidence, beforeGoodTsvPath);
        VisionToolSignalEvidenceExporter.ExportTsv(goodEvidence, goodTsvPath);
        VisionToolSignalEvidenceExporter.ExportTsv(badEvidence, badTsvPath);

        double goodSelectedPercent = SumSignalAboveThreshold(goodEvidence, frozenThreshold);
        double badSelectedPercent = SumSignalAboveThreshold(badEvidence, frozenThreshold);
        string[] reportLines =
        {
            "Threshold Signal Good/Bad Replay: PASS",
            "",
            $"Pipeline: {pipeline.Name}",
            $"Pair: {expectedPairGroup}",
            "Chart teaching change: Basic T=127 -> T=130 (marker commit request)",
            "Frozen decision: Basic / T=130 / Binary / Max=255",
            "Reviewed region: Full image (Threshold Tool has no ROI contract)",
            "",
            $"Good: {goodSample.SampleName}",
            $"  Runtime decision: {goodCheck.Status} / ActualSuccess={goodCheck.ActualSuccess}",
            $"  Metrics: {goodCheck.MetricText}",
            $"  Population above T: {goodSelectedPercent:0.###}%",
            $"  Source SHA-256: {goodEvidence.SourceSha256}",
            "",
            $"Bad: {badSample.SampleName}",
            $"  Runtime decision: {badCheck.Status} / ActualSuccess={badCheck.ActualSuccess}",
            $"  Metrics: {badCheck.MetricText}",
            $"  Population above T: {badSelectedPercent:0.###}%",
            $"  Source SHA-256: {badEvidence.SourceSha256}",
            "",
            "Evidence boundary: the chart explains the frozen cutoff and this public pair replay.",
            "It does not prove automatic threshold optimization, ROI teaching, unseen-data robustness, or field qualification.",
            "",
            $"Before TSV: {Path.GetFileName(beforeGoodTsvPath)}",
            $"Good TSV: {Path.GetFileName(goodTsvPath)}",
            $"Bad TSV: {Path.GetFileName(badTsvPath)}"
        };
        File.WriteAllLines(diagnosticsPath, reportLines);

        Border report = new()
        {
            Background = Brushes.White,
            Padding = new Thickness(24),
            Child = new TextBlock
            {
                Text = string.Join(Environment.NewLine, reportLines),
                FontSize = 14,
                FontFamily = new FontFamily("Consolas"),
                Foreground = Brushes.DarkSlateGray,
                TextWrapping = TextWrapping.Wrap
            }
        };
        CaptureResult capture = CaptureElement(report, outputPath, 1180, 760);
        return new CaptureResult(capture.Width, capture.Height, (DateTime.UtcNow - started).TotalMilliseconds);
    }

    private static VisionToolSignalEvidence CreateThresholdReplaySignalEvidence(
        VisionPipelineSampleCatalogItem sample,
        ThresholdToolProperty property)
    {
        using CvMat source = Cv.ImRead(sample.ImageFullPath, CvImreadModes.Unchanged);
        if (source.Empty())
        {
            throw new InvalidOperationException("Threshold signal replay could not load image: " + sample.ImageFullPath);
        }

        ThresholdTool tool = new();
        tool.SetProperty(property);
        VisionToolResult result = tool.Execute(source);
        try
        {
            if (result?.Success != true || result.ResultImage == null || result.ResultImage.Empty())
            {
                throw new InvalidOperationException(
                    "Threshold signal replay execution failed. "
                    + $"Sample={sample.SampleName}, Error={result?.ErrorName}, Message={result?.Message}");
            }

            return OpenVisionNativeThresholdSignalEvidenceFactory.Create(
                source,
                result.ResultImage,
                property,
                "Main");
        }
        finally
        {
            result?.ResultImage?.Dispose();
        }
    }

    private static double SumSignalAboveThreshold(VisionToolSignalEvidence evidence, double threshold)
    {
        VisionToolSignalSeries series = evidence.Series.Single();
        double sum = 0D;
        for (int index = 0; index < series.Values.Count; index++)
        {
            double x = series.XStart + (index * series.XStep);
            if (x > threshold)
            {
                sum += series.Values[index];
            }
        }

        return sum;
    }

    private static CaptureResult CaptureShellHostWorkspaceSampleBadReferenceAudit(string outputPath)
    {
        OpenVisionLanguageService.SetLanguage(OpenVisionLanguage.Korean, false);
        DateTime started = DateTime.UtcNow;
        List<VisionPipelineSampleCatalogItem> badSamples = VisionPipelineSampleCatalogItem.LoadRunnable()
            .Where(item => item.CanOpen && IsSamplePairBad(item))
            .OrderBy(item => item.PairGroup, StringComparer.OrdinalIgnoreCase)
            .ThenBy(item => item.SampleName, StringComparer.OrdinalIgnoreCase)
            .ToList();
        if (badSamples.Count == 0)
        {
            throw new InvalidOperationException("Workspace sample bad-reference audit could not find runnable Bad references.");
        }

        List<string> reportLines = new();
        int controlledNgCount = 0;
        int comparativeBadCount = 0;
        foreach (VisionPipelineSampleCatalogItem sample in badSamples)
        {
            VisionPipelineSampleCheckResult result = VisionPipelineSampleCheckService.RunSampleCheckSafe(sample);
            if (!result.Success)
            {
                throw new InvalidOperationException(
                    "Bad reference audit failed sample execution or expected metric check. "
                    + $"Sample={sample.SampleName}, Mode={sample.ValidationMode}, Group={sample.PairGroup}, "
                    + $"Status={result.Status}, Message={result.Message}, Metrics={result.MetricText}");
            }

            string classification;
            if (sample.ExpectsFailure)
            {
                classification = "Controlled NG";
                controlledNgCount++;
            }
            else
            {
                classification = "Comparative Bad";
                comparativeBadCount++;
            }

            reportLines.Add(
                $"{classification,-16} | {sample.PairGroup,-28} | {sample.SampleName,-42} | {result.MetricText}");
        }

        if (!badSamples.Any(item => string.Equals(item.SampleName, "Public_Mean_Brightness_Dark_Bad", StringComparison.OrdinalIgnoreCase)
            && item.ExpectsFailure
            && item.CatalogSourceKind == VisionPipelineSampleCatalogSourceKind.Public))
        {
            throw new InvalidOperationException("Bad reference audit requires Public_Mean_Brightness_Dark_Bad to remain a public controlled NG ExpectedFailure sample.");
        }

        if (controlledNgCount == 0)
        {
            throw new InvalidOperationException(
                "Bad reference audit expects public/product Bad references to be controlled NG ExpectedFailure samples. "
                + $"ControlledNG={controlledNgCount}, ComparativeBad={comparativeBadCount}");
        }

        string reportText =
            "Good/Bad Bad Reference Audit OK"
            + Environment.NewLine
            + $"Runnable Bad references: {badSamples.Count}"
            + Environment.NewLine
            + $"Controlled NG: {controlledNgCount}"
            + Environment.NewLine
            + $"Comparative Bad (legacy/private): {comparativeBadCount}"
            + Environment.NewLine
            + "Rule: public/product Bad references should be ExpectedFailure samples rejected through a stable metric acceptance gate."
            + Environment.NewLine
            + Environment.NewLine
            + string.Join(Environment.NewLine, reportLines);

        Border report = new()
        {
            Background = Brushes.White,
            Padding = new Thickness(24),
            Child = new TextBlock
            {
                Text = reportText,
                FontSize = 13,
                FontFamily = new FontFamily("Consolas"),
                Foreground = Brushes.DarkSlateGray,
                TextWrapping = TextWrapping.Wrap
            }
        };

        CaptureResult capture = CaptureElement(report, outputPath, 1360, 760);
        return new CaptureResult(capture.Width, capture.Height, (DateTime.UtcNow - started).TotalMilliseconds);
    }

    private static void ValidateSamplePairGroup(string groupName, IReadOnlyList<VisionPipelineSampleCatalogItem> samples)
    {
        if (!samples.Any(IsSamplePairGood) || !samples.Any(IsSamplePairBad))
        {
            throw new InvalidOperationException("Sample pair group must include both Good and Bad references. Group=" + groupName);
        }

        HashSet<string> pipelines = new(samples
            .Select(item => item.BaselinePipeline?.Trim() ?? string.Empty)
            .Where(value => !string.IsNullOrWhiteSpace(value)), StringComparer.OrdinalIgnoreCase);
        if (pipelines.Count != 1)
        {
            throw new InvalidOperationException(
                "Sample pair group must share one baseline pipeline. "
                + $"Group={groupName}, Pipelines={string.Join(", ", pipelines)}");
        }

        HashSet<string> goodMetricNames = new(samples
            .Where(IsSamplePairGood)
            .SelectMany(item => item.ExpectedMetrics)
            .Where(metric => metric != null && !string.IsNullOrWhiteSpace(metric.Name))
            .Select(metric => metric.Name.Trim()), StringComparer.OrdinalIgnoreCase);
        HashSet<string> badMetricNames = new(samples
            .Where(IsSamplePairBad)
            .SelectMany(item => item.ExpectedMetrics)
            .Where(metric => metric != null && !string.IsNullOrWhiteSpace(metric.Name))
            .Select(metric => metric.Name.Trim()), StringComparer.OrdinalIgnoreCase);
        if (!goodMetricNames.Any(goodMetricName => badMetricNames.Any(badMetricName => AreComparableMetricNames(goodMetricName, badMetricName))))
        {
            throw new InvalidOperationException(
                "Sample pair group must expose at least one shared Good/Bad metric. "
                + $"Group={groupName}, Good={string.Join(", ", goodMetricNames)}, Bad={string.Join(", ", badMetricNames)}");
        }

        foreach (VisionPipelineSampleCatalogItem sample in samples)
        {
            if (sample.ExpectedMetrics.Count == 0)
            {
                throw new InvalidOperationException("Sample pair row is missing expected metrics. Sample=" + sample.SampleName);
            }

            foreach (VisionPipelineSampleExpectedMetric metric in sample.ExpectedMetrics)
            {
                if (string.IsNullOrWhiteSpace(metric.Minimum) || string.IsNullOrWhiteSpace(metric.Maximum))
                {
                    throw new InvalidOperationException(
                        "Sample pair metric must have min/max bounds. "
                        + $"Sample={sample.SampleName}, Metric={metric.Name}");
                }
            }
        }
    }

    private static bool AreComparableMetricNames(string first, string second)
    {
        if (string.Equals(first, second, StringComparison.OrdinalIgnoreCase))
        {
            return true;
        }

        return IsDistanceMetricFamily(first, "DistanceMm") && IsDistanceMetricFamily(second, "DistanceMm")
            || IsDistanceMetricFamily(first, "DistancePx") && IsDistanceMetricFamily(second, "DistancePx");
    }

    private static bool IsDistanceMetricFamily(string metricName, string familyPrefix)
    {
        return !string.IsNullOrWhiteSpace(metricName)
            && metricName.StartsWith(familyPrefix, StringComparison.OrdinalIgnoreCase)
            && metricName.Length > familyPrefix.Length;
    }

    private static bool IsSamplePairGood(VisionPipelineSampleCatalogItem item)
    {
        return item != null
            && !item.ExpectsFailure
            && string.Equals(item.PairRole?.Trim(), "Good", StringComparison.OrdinalIgnoreCase);
    }

    private static bool IsSamplePairBad(VisionPipelineSampleCatalogItem item)
    {
        return item != null
            && (item.ExpectsFailure
                || string.Equals(item.PairRole?.Trim(), "Bad", StringComparison.OrdinalIgnoreCase));
    }

    private static CaptureResult CaptureShellHostFileLoadBlobE2E(string outputPath)
    {
        OpenVisionLanguageService.SetLanguage(OpenVisionLanguage.Korean, false);
        OpenVisionShellHostView shellHost = CreateShellHost("Smoke_WpfShellHostFileLoadBlobE2E", seedMainLayer: false);
        string imagePath = CreateWorkspaceLoadSmokeImageFile();
        try
        {
            return CaptureWindowWithContent(shellHost, outputPath, 1600, 900, () =>
            {
                // Keep this close to the operator flow: file load, tool open, PropertyGrid, preview, and visible workspace capture.
                if (!shellHost.IsWorkspaceEmptyPromptVisible)
                {
                    throw new InvalidOperationException("File-load Blob E2E must start from the empty workspace prompt.");
                }

                if (!shellHost.LoadMainImageFromFileForTest(imagePath))
                {
                    throw new InvalidOperationException("File-load Blob E2E could not load the smoke image into Main.");
                }

                Pump(20);
                if (!shellHost.HasWorkspaceLayerPreview
                    || !string.Equals(shellHost.WorkspaceLayerTitle, "Main", StringComparison.OrdinalIgnoreCase)
                    || !shellHost.WorkspaceLayerMeta.Contains("640x360", StringComparison.Ordinal))
                {
                    throw new InvalidOperationException(
                        "File-load Blob E2E did not show the loaded Main image before opening the tool. "
                        + $"Title={shellHost.WorkspaceLayerTitle}, Meta={shellHost.WorkspaceLayerMeta}");
                }

                shellHost.SelectToolForTest(VISION_MENU.Blob);
                Pump(24);

                ComboBox inputLayerCombo = FindFloatingComboBox("cbInputLayer");
                ComboBox outputLayerCombo = FindFloatingComboBox("cbOutputLayer");
                AssertVisionToolComboTemplate(inputLayerCombo, "File-load Blob E2E input layer combo");
                AssertComboBoxPopupLayout(inputLayerCombo, "File-load Blob E2E input layer combo");
                AssertVisionToolComboTemplate(outputLayerCombo, "File-load Blob E2E output layer combo");
                AssertComboBoxPopupLayout(outputLayerCombo, "File-load Blob E2E output layer combo");
                AssertFloatingPropertyGridVisible("File-load Blob E2E PropertyGrid");
                if (!HasFloatingToolPreviewImageSource()
                    || !string.Equals(GetComboBoxCurrentText(inputLayerCombo), "Main", StringComparison.OrdinalIgnoreCase)
                    || !string.Equals(shellHost.ActiveNativeRouteInputLayerNameForTest, "Main", StringComparison.OrdinalIgnoreCase)
                    || !shellHost.ActiveNativeDocumentTypeName.Contains("BlobToolWpfView", StringComparison.Ordinal))
                {
                    throw new InvalidOperationException(
                        "File-load Blob E2E did not open Blob with the loaded Main input preview. "
                        + $"Document={shellHost.ActiveNativeDocumentTypeName}, Combo={GetComboBoxCurrentText(inputLayerCombo)}, Input={shellHost.ActiveNativeRouteInputLayerNameForTest}");
                }

                shellHost.RunActiveNativePreviewForTest();
                Pump(28);
                if (!shellHost.IsNativeDocumentActive
                    || !shellHost.HasNativePreviewResult
                    || !string.Equals(shellHost.ActiveNativeRouteOutputLayerNameForTest, "Blob_Preview", StringComparison.OrdinalIgnoreCase))
                {
                    throw new InvalidOperationException(
                        "File-load Blob E2E did not produce a Blob preview result. "
                        + $"Output={shellHost.ActiveNativeRouteOutputLayerNameForTest}, Status={shellHost.ActiveNativeStatusText}");
                }

                AssertResultReviewVisible("File-load Blob E2E", "Blob /", "검출", "최대 면적", "중심", "박스");
                WriteFloatingToolWindowCapture(outputPath);
            }, captureFloatingToolWindow: false, verifyCapture: AssertWorkspaceLoadImageVisibleInCapture);
        }
        finally
        {
            TryDeleteFile(imagePath);
        }
    }

