    private static CaptureResult CaptureRecipePendingEditDialog(string outputPath)
    {
        OpenVisionLanguageService.SetLanguage(OpenVisionLanguage.Korean, false);
        OpenVisionRecipePendingEditDialog dialog = new(
            new OpenVisionRecipePendingEditRequest
            {
                Kind = OpenVisionRecipePendingEditTransitionKind.Pipeline,
                RecipeName = "Connector_Pin_Inspection",
                PipelineName = "Pin_Gap_Review",
                StepName = "02 Pin row Blob / Blob",
                TargetName = "Pin_Pitch_Alternative"
            });
        return CaptureStandaloneWindow(dialog, outputPath, 560, 330, () =>
        {
            File.WriteAllText(Path.ChangeExtension(outputPath, ".monitor.txt"), SmokeWindowMonitorPlacement.PlaceOnLeftmostMonitor(dialog));
            AssertVisibleAutomationIds(
                dialog,
                "Recipe pending-edit decision",
                "RecipePendingEditDialog",
                "RecipePendingEditCloseButton",
                "RecipePendingEditCancelButton",
                "RecipePendingEditDiscardButton",
                "RecipePendingEditApplyButton");
            AssertVisibleTextContains(
                dialog,
                "Recipe pending-edit decision copy",
                "Step",
                "Connector_Pin_Inspection",
                "Pin_Gap_Review",
                "Pin_Pitch_Alternative");
            AssertButtonTextContrast(dialog, "RecipePendingEditCancelButton", "Recipe pending-edit cancel");
            AssertButtonTextContrast(dialog, "RecipePendingEditDiscardButton", "Recipe pending-edit discard");
            AssertButtonTextContrast(dialog, "RecipePendingEditApplyButton", "Recipe pending-edit apply");
            foreach (string palette in new[] { "Light", "Dark" })
            foreach (OpenVisionLanguage language in new[] { OpenVisionLanguage.Korean, OpenVisionLanguage.English })
            {
                OpenVisionLanguageService.SetLanguage(language, false);
                OpenVisionWorkbenchThemeBehavior.SetThemeName(dialog, palette);
                OpenVisionRecipePendingEditDialog? child = null; Exception? failure = null;
                dialog.Dispatcher.BeginInvoke(System.Windows.Threading.DispatcherPriority.ContextIdle, new Action(() =>
                {
                    child = Application.Current.Windows.OfType<OpenVisionRecipePendingEditDialog>().Single(item => ReferenceEquals(item.Owner, dialog));
                    try
                    {
                        Pump(3);
                        if (OpenVisionWorkbenchThemeBehavior.GetThemeName(child) != palette || !BindingOperations.IsDataBound(child, OpenVisionWorkbenchThemeBehavior.ThemeNameProperty))
                            throw new InvalidOperationException("Pending dialog does not follow owner theme.");
                        var model = (OpenVisionRecipePendingEditDialogViewModel)child.DataContext;
                        model.SaveCommand.Execute(null); Pump(3);
                        if (!model.HasError || !child.IsVisible) throw new InvalidOperationException("Pending save failure did not retain visible error.");
                        AssertButtonTextContrast(child, "RecipePendingEditCancelButton", "Pending owner palette cancel");
                        AssertButtonTextContrast(child, "RecipePendingEditDiscardButton", "Pending owner palette discard");
                        AssertButtonTextContrast(child, "RecipePendingEditApplyButton", "Pending owner palette save");
                        ScreenshotPngWriter.WriteElementPng(child, Path.ChangeExtension(outputPath, $".{palette}-{language}-failure.png"), 560, 330);
                    }
                    catch (Exception error) { failure = error; }
                    finally { ((OpenVisionRecipePendingEditDialogViewModel)child.DataContext).CancelCommand.Execute(null); }
                }));
                RecipeDialogAdapter adapter = new(() => dialog);
                var decision = adapter.DecidePendingEdit(new OpenVisionRecipePendingEditRequest { IsWorkbenchCopy = true, RecipeName = new string(language == OpenVisionLanguage.Korean ? '가' : 'N', 60), ChangeCount = 1, TrySave = () => false, SaveError = () => "Owned save failure: retry remains available." });
                if (failure != null) throw failure;
                if (decision != OpenVisionRecipePendingEditDecision.Cancel || child == null || BindingOperations.IsDataBound(child, OpenVisionWorkbenchThemeBehavior.ThemeNameProperty))
                    throw new InvalidOperationException("Pending cancel/theme binding lifetime changed.");
            }
            foreach (string palette in new[] { "Dark", "Light" })
            foreach (OpenVisionLanguage language in new[] { OpenVisionLanguage.Korean, OpenVisionLanguage.English })
            foreach (bool confirm in new[] { false, true })
            {
                OpenVisionLanguageService.SetLanguage(language, false);
                OpenVisionWorkbenchThemeBehavior.SetThemeName(dialog, palette);
                string recipeName = new string(language == OpenVisionLanguage.Korean ? '가' : 'N', 60);
                OpenVisionRecipePendingEditDialog? child = null; Exception? failure = null;
                dialog.Dispatcher.BeginInvoke(System.Windows.Threading.DispatcherPriority.ContextIdle, new Action(() =>
                {
                    child = Application.Current.Windows.OfType<OpenVisionRecipePendingEditDialog>().Single(item => ReferenceEquals(item.Owner, dialog));
                    try
                    {
                        Pump(3);
                        var model = (OpenVisionRecipePendingEditDialogViewModel)child.DataContext;
                        File.WriteAllText(Path.ChangeExtension(outputPath, $".{palette}-{language}-{confirm}-recipe-delete.monitor.txt"), SmokeWindowMonitorPlacement.PlaceOnLeftmostMonitor(child));
                        Button cancel = FindVisualChildren<Button>(child).Single(item => AutomationProperties.GetAutomationId(item) == "RecipePendingEditCancelButton");
                        Button apply = FindVisualChildren<Button>(child).Single(item => AutomationProperties.GetAutomationId(item) == "RecipePendingEditApplyButton");
                        if (!model.IsRecipeDelete || model.ShowDiscard || model.ShowLegacyContext
                            || !cancel.IsDefault || apply.IsDefault || !cancel.IsKeyboardFocused
                            || OpenVisionWorkbenchThemeBehavior.GetThemeName(child) != palette)
                            throw new InvalidOperationException("VM12 recipe deletion did not preserve owner palette or safe default/focus.");
                        AssertVisibleTextContains(child, "VM12 recipe deletion target and effect", recipeName, OpenVisionLanguageService.T("Workbench.Recipe.DeleteDetail"));
                        AssertButtonTextContrast(child, "RecipePendingEditCancelButton", "VM12 recipe cancel");
                        AssertButtonTextContrast(child, "RecipePendingEditApplyButton", "VM12 recipe delete");
                        if (!confirm) ScreenshotPngWriter.WriteElementPng(child, Path.ChangeExtension(outputPath, $".{palette}-{language}-recipe-delete.png"), 560, 330);
                        (confirm ? model.SaveCommand : model.CancelCommand).Execute(null);
                    }
                    catch (Exception error) { failure = error; }
                    finally { if (child.IsVisible) ((OpenVisionRecipePendingEditDialogViewModel)child.DataContext).CancelCommand.Execute(null); }
                }));
                RecipeDialogAdapter adapter = new(() => dialog);
                bool result = adapter.ConfirmDeleteRecipe(recipeName);
                if (failure != null) throw failure;
                if (result != confirm || child == null || child.IsVisible || BindingOperations.IsDataBound(child, OpenVisionWorkbenchThemeBehavior.ThemeNameProperty))
                    throw new InvalidOperationException("VM12 recipe deletion result or modal/theme release differs.");
            }
            var stepDelete = OpenVisionRecipePendingEditDialogViewModel.Create(new OpenVisionRecipePendingEditRequest { IsStepDelete = true, StepName = "VM12_neighbor_step" });
            if (!stepDelete.IsApplyDefault || stepDelete.IsCancelDefault || stepDelete.ShowDiscard
                || !stepDelete.DetailText.Contains("Ctrl+Z", StringComparison.Ordinal))
                throw new InvalidOperationException("VM12 changed the existing Step-delete result/default contract.");
            string guardRecipe = "Smoke_VM12Guard_" + Guid.NewGuid().ToString("N");
            string otherRecipe = guardRecipe + "_Other";
            VisionPipelineStorage.Save(guardRecipe, RecipeContextFixture.CreatePipeline("Guard", 1));
            VisionPipelineStorage.Save(otherRecipe, RecipeContextFixture.CreatePipeline("Other", 1));
            int confirmations = 0;
            OpenVisionShellHostRecipeCommandSurface commands = new(() => guardRecipe, _ => { }, () => { }, confirmDeleteRecipe: _ => { confirmations++; return false; });
            {
                commands.RecipeManagerSelectedRecipeName = guardRecipe;
                if (commands.DeleteRecipeCommand.CanExecute(null)) throw new InvalidOperationException("VM12 current Main recipe deletion is enabled.");
                commands.DeleteRecipeCommand.Execute(null);
                if (confirmations != 0 || !RecipeWorkspaceService.GetRecipeNames().Contains(guardRecipe))
                    throw new InvalidOperationException("VM12 direct delete execution bypassed the current Main guard.");
                commands.RecipeManagerSelectedRecipeName = otherRecipe;
                if (!commands.DeleteRecipeCommand.CanExecute(null)) throw new InvalidOperationException("VM12 browsed non-Main recipe deletion is disabled.");
                commands.DeleteRecipeCommand.Execute(null);
                if (confirmations != 1 || !RecipeWorkspaceService.GetRecipeNames().Contains(otherRecipe))
                    throw new InvalidOperationException("VM12 other recipe cancel changed stored identity.");
            }
            File.WriteAllText(Path.ChangeExtension(outputPath, ".vm12.json"), JsonSerializer.Serialize(new
            {
                Scope = "기존 공유 모달과 새 Recipe 삭제의 인프로세스 WPF/명령 검사. 실제 제품 EXE 입력/native DPI 검증은 아니다.",
                OwnerPalette = true, CancelDefaultAndFocus = true, RecipeDeleteResults = true, ModalThemeRelease = true,
                CurrentMainCanExecuteAndExecuteGuard = true, OtherRecipeCancelRetained = true, ExistingStepDeleteDefaultRetained = true,
                Themes = new[] { "Dark", "Light" }, Languages = new[] { "Korean", "English" }, NameLength = 60
            }, new JsonSerializerOptions { WriteIndented = true }));
            OpenVisionLanguageService.SetLanguage(OpenVisionLanguage.Korean, false);
        });
    }

    private static CaptureResult CaptureShellHostRecipeChangeSafety(string outputPath)
    {
        OpenVisionLanguageService.SetLanguage(OpenVisionLanguage.Korean, false);
        SmokeRecipeWorkspaceCleanup.DeleteTransient();

        string recipeA = "Smoke_RecipeSafety_A_" + Guid.NewGuid().ToString("N").Substring(0, 10);
        string recipeB = "Smoke_RecipeSafety_B_" + Guid.NewGuid().ToString("N").Substring(0, 10);
        const string pipelineA = "Inspection_A";
        const string pipelineAAlternative = "Inspection_A_Alternative";
        const string pipelineB = "Inspection_B";
        const int originalMinArea = 321;
        const int editedMinArea = 987;

        VisionPipeline CreateBlobPipeline(string name, int stepCount)
        {
            VisionPipeline pipeline = new() { Name = name };
            for (int index = 0; index < stepCount; index++)
            {
                VisionPipelineStep step = new()
                {
                    Name = $"{name}_Blob_{index + 1}",
                    ToolType = "Blob",
                    InputLayer = index == 0 ? "Main" : $"{name}_Preview_{index}",
                    OutputLayer = $"{name}_Preview_{index + 1}"
                };
                step.Parameters["MIN_AREA"] = (originalMinArea + index).ToString(CultureInfo.InvariantCulture);
                step.Parameters["MAX_AREA"] = "1000000";
                pipeline.Steps.Add(step);
            }

            return pipeline;
        }

        VisionPipelineStorage.Save(recipeA, CreateBlobPipeline(pipelineA, 2));
        VisionPipelineStorage.Save(recipeA, CreateBlobPipeline(pipelineAAlternative, 1));
        VisionPipelineStorage.SaveActivePipelineName(recipeA, pipelineA);
        VisionPipelineStorage.Save(recipeB, CreateBlobPipeline(pipelineB, 1));
        VisionPipelineStorage.SaveActivePipelineName(recipeB, pipelineB);

        string lifetimeRecipe = recipeA;
        TaskCompletionSource<bool> recipePreparationGate = new(
            TaskCreationOptions.RunContinuationsAsynchronously);
        OpenVisionShellHostRecipeCommandSurface lifetimeSurface = new(
            () => lifetimeRecipe,
            name => lifetimeRecipe = name,
            () => { },
            waitForRecipeSwitchCompletion: () => recipePreparationGate.Task);
        lifetimeSurface.SelectedRecipeName = recipeB;
        Pump(120);
        if (!lifetimeSurface.IsSwitchingRecipe
            || !string.Equals(lifetimeRecipe, recipeB, StringComparison.Ordinal))
        {
            throw new InvalidOperationException(
                "Recipe loading state ended before deferred Recipe preparation completed.");
        }

        recipePreparationGate.SetResult(true);
        Pump(80);
        if (lifetimeSurface.IsSwitchingRecipe)
        {
            throw new InvalidOperationException(
                "Recipe loading state remained visible after Recipe preparation completed.");
        }

        OpenVisionShellHostView shellHost = CreateShellHost(recipeA, seedMainLayer: true);
        try
        {
            return CaptureWindowWithContent(shellHost, outputPath, 1600, 900, () =>
            {
                int previewRunsBefore = shellHost.NativePreviewRunCount;
                int layerCountBefore = shellHost.LayerDocumentCount;
                string activeLayerBefore = shellHost.ActiveHostLayerTitle;
                string routeInputBefore = shellHost.ActiveNativeRouteInputLayerNameForTest;
                string routeOutputBefore = shellHost.ActiveNativeRouteOutputLayerNameForTest;

                void AssertNoWorkspaceSideEffects(string scenario)
                {
                    if (shellHost.NativePreviewRunCount != previewRunsBefore
                        || shellHost.HasNativePreviewResult
                        || shellHost.LayerDocumentCount != layerCountBefore
                        || !string.Equals(shellHost.ActiveHostLayerTitle, activeLayerBefore, StringComparison.Ordinal)
                        || !string.Equals(shellHost.ActiveNativeRouteInputLayerNameForTest, routeInputBefore, StringComparison.Ordinal)
                        || !string.Equals(shellHost.ActiveNativeRouteOutputLayerNameForTest, routeOutputBefore, StringComparison.Ordinal))
                    {
                        throw new InvalidOperationException(
                            scenario + " changed Preview/Run, layers, active layer, or routing. "
                            + $"Runs={previewRunsBefore}->{shellHost.NativePreviewRunCount}, "
                            + $"Layers={layerCountBefore}->{shellHost.LayerDocumentCount}, "
                            + $"Active='{activeLayerBefore}'->'{shellHost.ActiveHostLayerTitle}', "
                            + $"Route='{routeInputBefore}->{routeOutputBefore}'->"
                            + $"'{shellHost.ActiveNativeRouteInputLayerNameForTest}->{shellHost.ActiveNativeRouteOutputLayerNameForTest}'.");
                    }
                }

                void SelectPipeline(string name)
                {
                    OpenVisionRecipePipelineOption option = shellHost.RecipeCommands.PipelineOptions
                        .FirstOrDefault(item => string.Equals(item.PipelineName, name, StringComparison.Ordinal))
                        ?? throw new InvalidOperationException("Recipe change-safety pipeline was not found: " + name);
                    shellHost.RecipeCommands.SelectedPipelineOption = option;
                    Pump(80);
                }

                BlobProperty LoadBlobStep(int zeroBasedIndex)
                {
                    IReadOnlyList<OpenVisionRecipePipelineStepPreview> steps =
                        shellHost.RecipeCommands.SelectedRecipeSummary.PipelinePreviewSteps;
                    if (zeroBasedIndex < 0 || zeroBasedIndex >= steps.Count)
                    {
                        throw new InvalidOperationException(
                            $"Recipe change-safety Step index was invalid: {zeroBasedIndex}/{steps.Count}.");
                    }

                    shellHost.RecipeCommands.SelectedPipelinePreviewStep = steps[zeroBasedIndex];
                    shellHost.RecipeCommands.LoadSelectedStepParametersCommand.Execute(null);
                    Pump(80);
                    return shellHost.RecipeCommands.SelectedStepEditObject as BlobProperty
                        ?? throw new InvalidOperationException("Recipe change-safety Blob editor did not load.");
                }

                void MakeDirty(BlobProperty property, int value = editedMinArea)
                {
                    property.MIN_AREA = value;
                    shellHost.RecipeCommands.MarkSelectedStepEditDirty();
                    Pump(40);
                    if (!shellHost.RecipeCommands.IsSelectedStepEditDirty
                        || property.MIN_AREA != value)
                    {
                        throw new InvalidOperationException(
                            "Recipe change-safety could not establish a dirty edit session.");
                    }
                }

                shellHost.SetRecipeManagerOpenForTest(true);
                Pump(100);
                ToggleButton advancedToggle = FindNamedVisualChild<ToggleButton>(
                    shellHost,
                    "recipeAdvancedReviewToggle")
                    ?? throw new InvalidOperationException("Recipe change-safety advanced review toggle was not found.");

                int browsePreviewRunsBefore = shellHost.NativePreviewRunCount;
                int browseLayerCountBefore = shellHost.LayerDocumentCount;
                string browseActiveLayerBefore = shellHost.ActiveHostLayerTitle;
                string browseRouteInputBefore = shellHost.ActiveNativeRouteInputLayerNameForTest;
                string browseRouteOutputBefore = shellHost.ActiveNativeRouteOutputLayerNameForTest;
                ListBox recipeManagerList = FindVisualChildren<ListBox>(shellHost)
                    .FirstOrDefault(element => string.Equals(
                        AutomationProperties.GetAutomationId(element),
                        "HostRecipeManagerList",
                        StringComparison.Ordinal))
                    ?? throw new InvalidOperationException("Recipe change-safety browse list was not found.");
                recipeManagerList.SelectedItem = recipeB;
                Pump(80);
                if (!string.Equals(shellHost.RecipeCommands.MainRecipeName, recipeA, StringComparison.Ordinal)
                    || !string.Equals(shellHost.RecipeCommands.RecipeManagerSelectedRecipeName, recipeB, StringComparison.Ordinal)
                    || !string.Equals(shellHost.RecipeCommands.RecipeManagerSelectedSummary.RecipeName, recipeB, StringComparison.Ordinal)
                    || shellHost.RecipeCommands.RecipeManagerSelectedSummary.PipelinePreviewSteps.Count != 1
                    || !shellHost.RecipeCommands.RecipeManagerSelectedSummary.PipelinePreviewSteps[0]
                        .FullParameterTextWithUnits.Contains(originalMinArea.ToString(CultureInfo.InvariantCulture), StringComparison.Ordinal)
                    || shellHost.NativePreviewRunCount != browsePreviewRunsBefore
                    || shellHost.LayerDocumentCount != browseLayerCountBefore
                    || !string.Equals(shellHost.ActiveHostLayerTitle, browseActiveLayerBefore, StringComparison.Ordinal)
                    || !string.Equals(shellHost.ActiveNativeRouteInputLayerNameForTest, browseRouteInputBefore, StringComparison.Ordinal)
                    || !string.Equals(shellHost.ActiveNativeRouteOutputLayerNameForTest, browseRouteOutputBefore, StringComparison.Ordinal))
                {
                    throw new InvalidOperationException(
                        "Browsing a saved Recipe changed the main Recipe/workspace or failed to show its stored Step values. "
                        + $"Main={shellHost.RecipeCommands.MainRecipeName}, Browse={shellHost.RecipeCommands.RecipeManagerSelectedRecipeName}, "
                        + $"Steps={shellHost.RecipeCommands.RecipeManagerSelectedSummary.PipelinePreviewSteps.Count}, "
                        + $"Parameters='{shellHost.RecipeCommands.RecipeManagerSelectedSummary.PipelinePreviewSteps.FirstOrDefault()?.FullParameterTextWithUnits}'.");
                }

                ClickVisibleButtonByAutomationId(
                    shellHost,
                    "HostRecipeApplyToMainButton",
                    "Recipe Manager apply-to-main button");
                Pump(160);
                if (!string.Equals(shellHost.RecipeCommands.MainRecipeName, recipeB, StringComparison.Ordinal)
                    || shellHost.IsRecipeManagerOpenForTest
                    || shellHost.NativePreviewRunCount != browsePreviewRunsBefore
                    || shellHost.LayerDocumentCount != browseLayerCountBefore
                    || !string.Equals(shellHost.ActiveHostLayerTitle, browseActiveLayerBefore, StringComparison.Ordinal))
                {
                    throw new InvalidOperationException(
                        "Explicit apply did not switch the main Recipe without re-running inspection or replacing image layers.");
                }

                shellHost.SetRecipeManagerOpenForTest(true);
                Pump(100);
                recipeManagerList = FindVisualChildren<ListBox>(shellHost)
                    .FirstOrDefault(element => string.Equals(
                        AutomationProperties.GetAutomationId(element),
                        "HostRecipeManagerList",
                        StringComparison.Ordinal))
                    ?? throw new InvalidOperationException("Recipe change-safety browse list was not found after apply.");
                recipeManagerList.SelectedItem = recipeA;
                Pump(80);
                ClickVisibleButtonByAutomationId(
                    shellHost,
                    "HostRecipeApplyToMainButton",
                    "Recipe Manager restore-main button");
                Pump(160);
                if (!string.Equals(shellHost.RecipeCommands.MainRecipeName, recipeA, StringComparison.Ordinal)
                    || shellHost.IsRecipeManagerOpenForTest
                    || shellHost.NativePreviewRunCount != browsePreviewRunsBefore
                    || shellHost.LayerDocumentCount != browseLayerCountBefore
                    || !string.Equals(shellHost.ActiveHostLayerTitle, browseActiveLayerBefore, StringComparison.Ordinal))
                {
                    throw new InvalidOperationException(
                        "Recipe change-safety could not restore the original main Recipe after explicit apply.");
                }

                shellHost.SetRecipeManagerOpenForTest(true);
                Pump(100);
                recipeManagerList = FindVisualChildren<ListBox>(shellHost)
                    .FirstOrDefault(element => string.Equals(
                        AutomationProperties.GetAutomationId(element),
                        "HostRecipeManagerList",
                        StringComparison.Ordinal))
                    ?? throw new InvalidOperationException("Recipe change-safety browse list was not found before detail entry.");
                recipeManagerList.SelectedItem = recipeB;
                Pump(80);
                Expander storedStep = FindVisualChildren<Expander>(shellHost)
                    .FirstOrDefault(element => string.Equals(
                        AutomationProperties.GetAutomationId(element),
                        "HostRecipeStoredStepExpander",
                        StringComparison.Ordinal))
                    ?? throw new InvalidOperationException("Recipe change-safety stored Step was not found.");
                storedStep.IsExpanded = true;
                Pump(40);
                AssertHiddenAutomationIds(shellHost, "Recipe Manager saved Step is read-only", "HostRecipeEditSavedStepButton");

                recipeManagerList.SelectedItem = recipeA;
                Pump(80);
                if (shellHost.RecipeCommands.IsRecipeManagerDetailContextActive
                    || !string.Equals(shellHost.RecipeCommands.MainRecipeName, recipeA, StringComparison.Ordinal)
                    || !string.Equals(shellHost.RecipeCommands.RecipeManagerSelectedRecipeName, recipeA, StringComparison.Ordinal)
                    || shellHost.NativePreviewRunCount != browsePreviewRunsBefore
                    || shellHost.LayerDocumentCount != browseLayerCountBefore)
                {
                    throw new InvalidOperationException(
                        "Recipe browse did not return to its original main Recipe without execution side effects.");
                }

                shellHost.SetRecipeManagerOpenForTest(false);
                Pump(80);
                shellHost.RecipeCommands.OpenMainRecipeWorkCommand.Execute("Pipeline"); // Legacy contract fixture, independent of the display-only Main title.
                Pump(100);
                if (!shellHost.RecipeCommands.IsRecipeManagerDetailContextActive
                    || !string.Equals(shellHost.RecipeCommands.SelectedRecipeName, recipeA, StringComparison.Ordinal)
                    || shellHost.NativePreviewRunCount != browsePreviewRunsBefore
                    || shellHost.LayerDocumentCount != browseLayerCountBefore)
                {
                    throw new InvalidOperationException("Main Step editing did not keep the selected Recipe and workspace unchanged.");
                }
                TabItem pipelineTab = FindNamedVisualChild<TabItem>(shellHost, "tabRecipePipeline")
                    ?? throw new InvalidOperationException("Recipe change-safety Pipeline tab was not found.");
                TabItem xmlStepsTab = FindNamedVisualChild<TabItem>(shellHost, "tabRecipePipelineStepSettings")
                    ?? throw new InvalidOperationException("Recipe change-safety XML/Step tab was not found.");
                ScrollViewer pipelineScrollViewer = FindNamedVisualChild<ScrollViewer>(
                    shellHost,
                    "recipePipelineTabScrollViewer")
                    ?? throw new InvalidOperationException("Recipe change-safety Pipeline scroll viewer was not found.");
                pipelineTab.IsSelected = true;
                xmlStepsTab.IsSelected = true;
                Pump(80);
                ComboBox stepSelector = FindNamedVisualChild<ComboBox>(shellHost, "recipePipelineCurrentStepSelector")
                    ?? throw new InvalidOperationException("Recipe change-safety current Step selector was not found.");
                if (!stepSelector.IsVisible || stepSelector.Items.Count != 2)
                {
                    throw new InvalidOperationException("Recipe change-safety current Step selector was not available.");
                }

                void MakeDirtyThroughPropertyGrid(BlobProperty property, int value)
                {
                    TextBox editor = FindVisualChildren<TextBox>(shellHost)
                        .Single(item => item.IsVisible
                            && item.IsEnabled
                            && string.Equals(
                                item.Text,
                                property.MIN_AREA.ToString(CultureInfo.InvariantCulture),
                                StringComparison.Ordinal));
                    editor.Focus();
                    editor.Text = value.ToString(CultureInfo.InvariantCulture);
                    Pump(40);
                    advancedToggle.Focus();
                    Pump(80);
                    if (!shellHost.RecipeCommands.IsSelectedStepEditDirty
                        || property.MIN_AREA != value)
                    {
                        throw new InvalidOperationException(
                            "Recipe change-safety could not commit the visible PropertyGrid edit. "
                            + $"Dirty={shellHost.RecipeCommands.IsSelectedStepEditDirty}, "
                            + $"Model={property.MIN_AREA}, Editor='{editor.Text}', Expected={value}.");
                    }
                }

                SelectPipeline(pipelineA);
                BlobProperty stepEdit = LoadBlobStep(0);
                MakeDirty(stepEdit);
                OpenVisionRecipePipelineStepPreview originalStep =
                    shellHost.RecipeCommands.SelectedPipelinePreviewStep;
                object originalEditObject = shellHost.RecipeCommands.SelectedStepEditObject;
                OpenVisionRecipePipelineStepPreview nextStep =
                    shellHost.RecipeCommands.SelectedRecipeSummary.PipelinePreviewSteps[1];

                shellHost.QueuePendingRecipeEditDecisionForTest(
                    OpenVisionRecipePendingEditDecision.Cancel);
                stepSelector.SelectedValue = nextStep.Index;
                Pump(80);
                if (shellHost.RecipeCommands.SelectedPipelinePreviewStep?.Index != originalStep.Index
                    || stepSelector.SelectedValue is not int canceledStepIndex || canceledStepIndex != originalStep.Index
                    || !ReferenceEquals(shellHost.RecipeCommands.SelectedStepEditObject, originalEditObject)
                    || !shellHost.RecipeCommands.IsSelectedStepEditDirty
                    || stepEdit.MIN_AREA != editedMinArea)
                {
                    throw new InvalidOperationException(
                        "Cancel did not preserve the selected Step and dirty editor.");
                }
                pipelineScrollViewer.ScrollToBottom();
                Pump(80);
                SaveVisibleAutomationElementPng(
                    shellHost,
                    "HostRecipeManagerPanel",
                    outputPath,
                    "01-step-cancel-preserves-dirty.png");

                shellHost.QueuePendingRecipeEditDecisionForTest(
                    OpenVisionRecipePendingEditDecision.Discard);
                stepSelector.SelectedValue = nextStep.Index;
                Pump(80);
                if (shellHost.RecipeCommands.SelectedPipelinePreviewStep?.Index != nextStep.Index
                    || stepSelector.SelectedValue is not int discardedStepIndex || discardedStepIndex != nextStep.Index
                    || shellHost.RecipeCommands.IsSelectedStepEditDirty
                    || shellHost.RecipeCommands.SelectedStepEditObject != null
                    || VisionPipelineStorage.Load(recipeA, pipelineA).Steps[0].Parameters["MIN_AREA"]
                        != originalMinArea.ToString(CultureInfo.InvariantCulture))
                {
                    throw new InvalidOperationException(
                        "Discard did not move to the requested Step while preserving stored XML.");
                }

                const int stepAppliedMinArea = 401;
                BlobProperty stepApplyEdit = LoadBlobStep(0);
                stepApplyEdit.USE_ROI = false;
                MakeDirtyThroughPropertyGrid(stepApplyEdit, stepAppliedMinArea);
                nextStep = shellHost.RecipeCommands.SelectedRecipeSummary.PipelinePreviewSteps[1];
                shellHost.QueuePendingRecipeEditDecisionForTest(
                    OpenVisionRecipePendingEditDecision.ApplyAndContinue);
                stepSelector.SelectedValue = nextStep.Index;
                Pump(100);
                if (shellHost.RecipeCommands.SelectedPipelinePreviewStep?.Index != nextStep.Index
                    || stepSelector.SelectedValue is not int appliedStepIndex || appliedStepIndex != nextStep.Index
                    || shellHost.RecipeCommands.IsSelectedStepEditDirty
                    || VisionPipelineStorage.Load(recipeA, pipelineA).Steps[0].Parameters["MIN_AREA"]
                        != stepAppliedMinArea.ToString(CultureInfo.InvariantCulture))
                {
                    throw new InvalidOperationException(
                        "Apply and continue did not persist XML before the Step transition. "
                        + $"Selected={shellHost.RecipeCommands.SelectedPipelinePreviewStep?.Index}, "
                        + $"Selector={stepSelector.SelectedValue}, "
                        + $"Dirty={shellHost.RecipeCommands.IsSelectedStepEditDirty}, "
                        + $"Stored={VisionPipelineStorage.Load(recipeA, pipelineA).Steps[0].Parameters["MIN_AREA"]}, "
                        + $"Status='{shellHost.RecipeCommands.SelectedStepEditStatusText}'.");
                }
                if (shellHost.RecipeCommands.SelectedRecipeSummary.PipelinePreviewSteps[0].RoiMetadataText
                    != "ROI: 전체 이미지")
                {
                    throw new InvalidOperationException(
                        "A saved Blob Step with ROI disabled did not show full-image use in the current Step review. "
                        + $"Actual='{shellHost.RecipeCommands.SelectedRecipeSummary.PipelinePreviewSteps[0].RoiMetadataText}', "
                        + $"Parameters='{string.Join(",", VisionPipelineStorage.Load(recipeA, pipelineA).Steps[0].Parameters.Where(item => item.Key.Contains("ROI")).Select(item => item.Key + "=" + item.Value))}'.");
                }

                SelectPipeline(pipelineA);
                BlobProperty pipelineEdit = LoadBlobStep(0);
                MakeDirty(pipelineEdit);
                OpenVisionRecipePipelineOption alternativeOption = shellHost.RecipeCommands.PipelineOptions
                    .First(item => string.Equals(
                        item.PipelineName,
                        pipelineAAlternative,
                        StringComparison.Ordinal));
                shellHost.QueuePendingRecipeEditDecisionForTest(
                    OpenVisionRecipePendingEditDecision.Cancel);
                shellHost.RecipeCommands.SelectedPipelineOption = alternativeOption;
                Pump(80);
                if (!string.Equals(
                        shellHost.RecipeCommands.SelectedPipelineOption?.PipelineName,
                        pipelineA,
                        StringComparison.Ordinal)
                    || !shellHost.RecipeCommands.IsSelectedStepEditDirty
                    || !ReferenceEquals(shellHost.RecipeCommands.SelectedStepEditObject, pipelineEdit))
                {
                    throw new InvalidOperationException(
                        "Cancel did not preserve the Pipeline and dirty editor.");
                }

                shellHost.QueuePendingRecipeEditDecisionForTest(
                    OpenVisionRecipePendingEditDecision.Discard);
                shellHost.RecipeCommands.SelectedPipelineOption = alternativeOption;
                Pump(80);
                if (!string.Equals(
                        shellHost.RecipeCommands.SelectedPipelineOption?.PipelineName,
                        pipelineAAlternative,
                        StringComparison.Ordinal)
                    || shellHost.RecipeCommands.IsSelectedStepEditDirty
                    || shellHost.RecipeCommands.SelectedStepEditObject != null)
                {
                    throw new InvalidOperationException(
                        "Discard did not move to the requested Pipeline.");
                }

                const int pipelineAppliedMinArea = 402;
                SelectPipeline(pipelineA);
                BlobProperty pipelineApplyEdit = LoadBlobStep(0);
                MakeDirtyThroughPropertyGrid(pipelineApplyEdit, pipelineAppliedMinArea);
                shellHost.QueuePendingRecipeEditDecisionForTest(
                    OpenVisionRecipePendingEditDecision.ApplyAndContinue);
                shellHost.RecipeCommands.SelectedPipelineOption = alternativeOption;
                Pump(100);
                if (!string.Equals(
                        shellHost.RecipeCommands.SelectedPipelineOption?.PipelineName,
                        pipelineAAlternative,
                        StringComparison.Ordinal)
                    || shellHost.RecipeCommands.IsSelectedStepEditDirty
                    || VisionPipelineStorage.Load(recipeA, pipelineA).Steps[0].Parameters["MIN_AREA"]
                        != pipelineAppliedMinArea.ToString(CultureInfo.InvariantCulture))
                {
                    throw new InvalidOperationException(
                        "Apply and continue did not persist XML before the Pipeline transition.");
                }

                SelectPipeline(pipelineA);
                BlobProperty recipeApplyEdit = LoadBlobStep(0);
                pipelineScrollViewer.ScrollToBottom();
                Pump(80);
                MakeDirtyThroughPropertyGrid(recipeApplyEdit, editedMinArea);
                bool switchingBeforeRecipeRequest = shellHost.RecipeCommands.IsSwitchingRecipe;
                shellHost.QueuePendingRecipeEditDecisionForTest(
                    OpenVisionRecipePendingEditDecision.ApplyAndContinue);
                shellHost.RecipeCommands.SelectedRecipeName = recipeB;
                bool switchingImmediatelyAfterRecipeRequest = shellHost.RecipeCommands.IsSwitchingRecipe;
                for (int attempt = 0; attempt < 100
                    && (shellHost.RecipeCommands.IsSwitchingRecipe
                        || !string.Equals(shellHost.SelectedRecipeNameForTest, recipeB, StringComparison.Ordinal)); attempt++)
                {
                    Pump(50);
                }
                string savedRecipeAValue = VisionPipelineStorage.Load(recipeA, pipelineA)
                    .Steps[0]
                    .Parameters["MIN_AREA"];
                if (!string.Equals(shellHost.SelectedRecipeNameForTest, recipeB, StringComparison.Ordinal)
                    || !string.Equals(shellHost.RecipeCommands.MainRecipeName, recipeB, StringComparison.Ordinal)
                    || !string.Equals(shellHost.RecipeCommands.RecipeManagerSelectedRecipeName, recipeB, StringComparison.Ordinal)
                    || !string.Equals(shellHost.RecipeCommands.RecipeManagerSelectedPipelineName, pipelineB, StringComparison.Ordinal)
                    || !string.Equals(shellHost.RecipeCommands.SelectedPipelineOption?.PipelineName, pipelineB, StringComparison.Ordinal)
                    || shellHost.RecipeCommands.SelectedPipelinePreviewStep != null
                    || shellHost.RecipeCommands.SelectedStepEditObject != null
                    || shellHost.RecipeCommands.IsSelectedStepEditDirty
                    || savedRecipeAValue != editedMinArea.ToString(CultureInfo.InvariantCulture))
                {
                    throw new InvalidOperationException(
                        "Apply and continue did not persist XML before the Recipe transition. "
                        + $"Selected='{shellHost.SelectedRecipeNameForTest}/{recipeB}', Main='{shellHost.RecipeCommands.MainRecipeName}', "
                        + $"Browse='{shellHost.RecipeCommands.RecipeManagerSelectedRecipeName}/{shellHost.RecipeCommands.RecipeManagerSelectedPipelineName}', "
                        + $"Pipeline='{shellHost.RecipeCommands.SelectedPipelineOption?.PipelineName}', Step='{shellHost.RecipeCommands.SelectedPipelinePreviewStep?.Index}', "
                        + $"Switching={switchingBeforeRecipeRequest}->{switchingImmediatelyAfterRecipeRequest}->{shellHost.RecipeCommands.IsSwitchingRecipe}, "
                        + $"Dirty={shellHost.RecipeCommands.IsSelectedStepEditDirty}, "
                        + $"Stored={savedRecipeAValue}/{editedMinArea}, "
                        + $"Status='{shellHost.RecipeCommands.SelectedStepEditStatusText}'.");
                }

                SelectPipeline(pipelineB);
                BlobProperty recipeCancelEdit = LoadBlobStep(0);
                MakeDirty(recipeCancelEdit, editedMinArea + 10);
                object? recipeCancelEditObject = shellHost.RecipeCommands.SelectedStepEditObject;
                shellHost.QueuePendingRecipeEditDecisionForTest(
                    OpenVisionRecipePendingEditDecision.Cancel);
                shellHost.RecipeCommands.SelectedRecipeName = recipeA;
                Pump(100);
                if (!string.Equals(shellHost.SelectedRecipeNameForTest, recipeB, StringComparison.Ordinal)
                    || !shellHost.RecipeCommands.IsSelectedStepEditDirty
                    || !ReferenceEquals(shellHost.RecipeCommands.SelectedStepEditObject, recipeCancelEditObject)
                    || recipeCancelEdit.MIN_AREA != editedMinArea + 10)
                {
                    throw new InvalidOperationException(
                        "Cancel did not preserve the Recipe and dirty editor.");
                }

                shellHost.QueuePendingRecipeEditDecisionForTest(
                    OpenVisionRecipePendingEditDecision.Discard);
                shellHost.RecipeCommands.SelectedRecipeName = recipeA;
                Pump(100);
                if (!string.Equals(shellHost.SelectedRecipeNameForTest, recipeA, StringComparison.Ordinal)
                    || shellHost.RecipeCommands.IsSelectedStepEditDirty
                    || VisionPipelineStorage.Load(recipeB, pipelineB).Steps[0].Parameters["MIN_AREA"]
                        != originalMinArea.ToString(CultureInfo.InvariantCulture))
                {
                    throw new InvalidOperationException(
                        "Discard did not move to the requested Recipe while preserving stored XML.");
                }

                shellHost.RecipeCommands.SelectedRecipeName = recipeB;
                Pump(100);
                SelectPipeline(pipelineB);
                BlobProperty workEdit = LoadBlobStep(0);
                MakeDirty(workEdit, editedMinArea + 1);
                object? workEditObject = shellHost.RecipeCommands.SelectedStepEditObject;
                shellHost.QueuePendingRecipeEditDecisionForTest(
                    OpenVisionRecipePendingEditDecision.Cancel);
                ClickVisibleButtonByAutomationId(shellHost, "HostRecipeManagerCloseButton", "main Step work close button");
                Pump(100);
                if (!shellHost.RecipeCommands.IsRecipeManagerDetailContextActive
                    || advancedToggle.IsChecked != true
                    || shellHost.IsRecipeManagerOpenForTest
                    || !shellHost.RecipeCommands.IsSelectedStepEditDirty
                    || !ReferenceEquals(shellHost.RecipeCommands.SelectedStepEditObject, workEditObject)
                    || workEdit.MIN_AREA != editedMinArea + 1)
                {
                    throw new InvalidOperationException(
                        "Cancel did not keep main Step work and its dirty editor open.");
                }

                shellHost.QueuePendingRecipeEditDecisionForTest(
                    OpenVisionRecipePendingEditDecision.Discard);
                ClickVisibleButtonByAutomationId(shellHost, "HostRecipeManagerCloseButton", "main Step work discard button");
                Pump(100);
                if (shellHost.IsRecipeManagerOpenForTest
                    || shellHost.RecipeCommands.IsRecipeManagerDetailContextActive
                    || advancedToggle.IsChecked == true
                    || shellHost.RecipeCommands.IsSelectedStepEditDirty
                    || shellHost.RecipeCommands.SelectedStepEditObject != null
                    || VisionPipelineStorage.Load(recipeB, pipelineB).Steps[0].Parameters["MIN_AREA"]
                        != originalMinArea.ToString(CultureInfo.InvariantCulture))
                {
                    throw new InvalidOperationException(
                        "Discard did not close main Step work while preserving stored XML.");
                }

                shellHost.RecipeCommands.OpenMainRecipeWorkCommand.Execute("Pipeline"); // Legacy contract fixture, independent of the display-only Main title.
                Pump(100);
                pipelineTab.IsSelected = true;
                xmlStepsTab.IsSelected = true;
                SelectPipeline(pipelineB);
                const int workAppliedMinArea = 403;
                BlobProperty workApplyEdit = LoadBlobStep(0);
                MakeDirtyThroughPropertyGrid(workApplyEdit, workAppliedMinArea);
                shellHost.QueuePendingRecipeEditDecisionForTest(
                    OpenVisionRecipePendingEditDecision.ApplyAndContinue);
                ClickVisibleButtonByAutomationId(shellHost, "HostRecipeManagerCloseButton", "main Step work apply button");
                Pump(120);
                if (shellHost.IsRecipeManagerOpenForTest
                    || shellHost.RecipeCommands.IsRecipeManagerDetailContextActive
                    || shellHost.RecipeCommands.IsSelectedStepEditDirty
                    || VisionPipelineStorage.Load(recipeB, pipelineB).Steps[0].Parameters["MIN_AREA"]
                        != workAppliedMinArea.ToString(CultureInfo.InvariantCulture))
                {
                    throw new InvalidOperationException(
                        "Apply and continue did not persist XML before closing main Step work.");
                }

                VisionPipelineStorage.Save(recipeB, CreateBlobPipeline(pipelineB, 1));
                shellHost.RecipeCommands.OpenMainRecipeWorkCommand.Execute("Pipeline"); // Legacy contract fixture, independent of the display-only Main title.
                Pump(100);
                pipelineTab.IsSelected = true;
                xmlStepsTab.IsSelected = true;
                SelectPipeline(pipelineB);
                BlobProperty failedApplyEdit = LoadBlobStep(0);
                MakeDirty(failedApplyEdit, editedMinArea + 2);
                object? failedEditObject = shellHost.RecipeCommands.SelectedStepEditObject;
                shellHost.FailNextRecipeStepEditCommitForTest();
                shellHost.QueuePendingRecipeEditDecisionForTest(
                    OpenVisionRecipePendingEditDecision.ApplyAndContinue);
                shellHost.RecipeCommands.SelectedRecipeName = recipeA;
                Pump(120);
                if (!string.Equals(shellHost.SelectedRecipeNameForTest, recipeB, StringComparison.Ordinal)
                    || !shellHost.RecipeCommands.IsSelectedStepEditDirty
                    || !ReferenceEquals(shellHost.RecipeCommands.SelectedStepEditObject, failedEditObject)
                    || failedApplyEdit.MIN_AREA != editedMinArea + 2
                    || VisionPipelineStorage.Load(recipeB, pipelineB).Steps[0].Parameters["MIN_AREA"]
                        != originalMinArea.ToString(CultureInfo.InvariantCulture))
                {
                    throw new InvalidOperationException(
                        "A failed apply did not keep the current Recipe and dirty editor unchanged.");
                }
                pipelineScrollViewer.ScrollToBottom();
                Pump(80);
                SaveVisibleAutomationElementPng(
                    shellHost,
                    "HostRecipeManagerPanel",
                    outputPath,
                    "02-failed-apply-keeps-dirty.png");

                shellHost.QueuePendingRecipeEditDecisionForTest(
                    OpenVisionRecipePendingEditDecision.Discard);
                shellHost.RecipeCommands.SelectedRecipeName = recipeA;
                Pump(120);
                shellHost.RecipeCommands.SelectedRecipeName = recipeB;
                Pump(120);
                SelectPipeline(pipelineB);
                BlobProperty failedSaveEdit = LoadBlobStep(0);
                pipelineScrollViewer.ScrollToBottom();
                Pump(80);
                int failedRoundTripMinArea = editedMinArea + 3;
                MakeDirtyThroughPropertyGrid(failedSaveEdit, failedRoundTripMinArea);
                object? failedSaveEditObject = shellHost.RecipeCommands.SelectedStepEditObject;

                shellHost.FailNextRecipeStepSaveForTest();
                shellHost.QueuePendingRecipeEditDecisionForTest(
                    OpenVisionRecipePendingEditDecision.ApplyAndContinue);
                shellHost.RecipeCommands.SelectedRecipeName = recipeA;
                Pump(140);
                string storedAfterFailedSave = VisionPipelineStorage.Load(recipeB, pipelineB)
                    .Steps[0]
                    .Parameters["MIN_AREA"];
                if (!string.Equals(shellHost.SelectedRecipeNameForTest, recipeB, StringComparison.Ordinal)
                    || !shellHost.RecipeCommands.IsSelectedStepEditDirty
                    || !ReferenceEquals(shellHost.RecipeCommands.SelectedStepEditObject, failedSaveEditObject)
                    || failedSaveEdit.MIN_AREA != failedRoundTripMinArea
                    || storedAfterFailedSave != originalMinArea.ToString(CultureInfo.InvariantCulture)
                    || shellHost.RecipeCommands.SelectedStepEditStatusText.IndexOf(
                        "Forced XML save failure",
                        StringComparison.Ordinal) < 0)
                {
                    throw new InvalidOperationException(
                        "A failed XML save did not block the transition, retain the dirty editor, "
                        + "and preserve the previous stored XML. "
                        + $"Selected='{shellHost.SelectedRecipeNameForTest}/{recipeB}', "
                        + $"Dirty={shellHost.RecipeCommands.IsSelectedStepEditDirty}, "
                        + $"Model={failedSaveEdit.MIN_AREA}/{failedRoundTripMinArea}, "
                        + $"Stored={storedAfterFailedSave}/{originalMinArea}, "
                        + $"Status='{shellHost.RecipeCommands.SelectedStepEditStatusText}'.");
                }
                pipelineScrollViewer.ScrollToBottom();
                Pump(80);
                SaveVisibleAutomationElementPng(
                    shellHost,
                    "HostRecipeManagerPanel",
                    outputPath,
                    "03-failed-save-keeps-dirty.png");

                shellHost.QueuePendingRecipeEditDecisionForTest(
                    OpenVisionRecipePendingEditDecision.Discard);
                shellHost.RecipeCommands.SelectedRecipeName = recipeA;
                Pump(120);
                shellHost.RecipeCommands.SelectedRecipeName = recipeB;
                Pump(120);
                SelectPipeline(pipelineB);
                BlobProperty failedRoundTripEdit = LoadBlobStep(0);
                pipelineScrollViewer.ScrollToBottom();
                Pump(80);
                int failedValidationMinArea = editedMinArea + 4;
                MakeDirtyThroughPropertyGrid(failedRoundTripEdit, failedValidationMinArea);
                object? failedRoundTripEditObject = shellHost.RecipeCommands.SelectedStepEditObject;

                shellHost.FailNextRecipeStepRoundTripValidationForTest();
                shellHost.QueuePendingRecipeEditDecisionForTest(
                    OpenVisionRecipePendingEditDecision.ApplyAndContinue);
                shellHost.RecipeCommands.SelectedRecipeName = recipeA;
                Pump(140);
                string restoredRecipeBValue = VisionPipelineStorage.Load(recipeB, pipelineB)
                    .Steps[0]
                    .Parameters["MIN_AREA"];
                if (!string.Equals(shellHost.SelectedRecipeNameForTest, recipeB, StringComparison.Ordinal)
                    || !shellHost.RecipeCommands.IsSelectedStepEditDirty
                    || !ReferenceEquals(shellHost.RecipeCommands.SelectedStepEditObject, failedRoundTripEditObject)
                    || failedRoundTripEdit.MIN_AREA != failedValidationMinArea
                    || restoredRecipeBValue != originalMinArea.ToString(CultureInfo.InvariantCulture)
                    || shellHost.RecipeCommands.SelectedStepEditStatusText.IndexOf(
                        "복원",
                        StringComparison.Ordinal) < 0)
                {
                    throw new InvalidOperationException(
                        "A failed XML round-trip did not block the transition, retain the dirty editor, "
                        + "and restore the previous stored XML. "
                        + $"Selected='{shellHost.SelectedRecipeNameForTest}/{recipeB}', "
                        + $"Dirty={shellHost.RecipeCommands.IsSelectedStepEditDirty}, "
                        + $"Model={failedRoundTripEdit.MIN_AREA}/{failedValidationMinArea}, "
                        + $"Stored={restoredRecipeBValue}/{originalMinArea}, "
                        + $"Status='{shellHost.RecipeCommands.SelectedStepEditStatusText}'.");
                }
                pipelineScrollViewer.ScrollToBottom();
                Pump(80);
                SaveVisibleAutomationElementPng(
                    shellHost,
                    "HostRecipeManagerPanel",
                    outputPath,
                    "04-failed-roundtrip-restores-xml.png");

                AssertNoWorkspaceSideEffects("Recipe change-safety decisions");
                string diagnosticsDirectory = Path.Combine(
                    Path.GetDirectoryName(outputPath) ?? ".",
                    Path.GetFileNameWithoutExtension(outputPath) + ".diagnostics");
                Directory.CreateDirectory(diagnosticsDirectory);
                File.WriteAllLines(
                    Path.Combine(diagnosticsDirectory, "recipe_change_safety_results.txt"),
                    new[]
                    {
                        "StepCancel=Preserved",
                        "StepDiscard=TransitionedWithoutSave",
                        "StepApplyAndContinue=SavedThenTransitioned",
                        "PipelineCancel=Preserved",
                        "PipelineDiscard=TransitionedWithoutSave",
                        "PipelineApplyAndContinue=SavedThenTransitioned",
                        "RecipeCancel=Preserved",
                        "RecipeDiscard=TransitionedWithoutSave",
                        "RecipeApplyAndContinue=SavedThenTransitioned",
                        "MainWorkCloseCancel=StayedOpen",
                        "MainWorkCloseDiscard=ClosedWithoutSave",
                        "MainWorkCloseApplyAndContinue=SavedThenClosed",
                        "FailedApply=TransitionBlockedAndDirtyPreserved",
                        "FailedSave=TransitionBlockedAndStoredXmlPreserved",
                        "FailedRoundTrip=TransitionBlockedAndStoredXmlRestored",
                        "RecipeLoadingOverlay=HeldUntilPreparationComplete",
                        "PreviewRunSideEffects=None",
                        "LayerSideEffects=None",
                        "RouteSideEffects=None"
                    });
            }, captureFloatingToolWindow: false, captureScreen: true);
        }
        finally
        {
            RecipeWorkspaceService.DeleteVisionWorkspace(recipeA);
            RecipeWorkspaceService.DeleteVisionWorkspace(recipeB);
        }
    }

    private static void AssertBasicImagePropertyMapperRoundTrip()
    {
        VisionPipelineStep threshold = CreateBasicImageRoundTripStep(
            "ThresholdTool",
            "ThresholdInput",
            "ThresholdOutput");
        threshold.Enabled = false;
        threshold.UseAcceptance = true;
        threshold.ExpectedSuccess = false;
        threshold.MaxElapsedMilliseconds = 91D;
        threshold.RequiredMessageText = "threshold-reviewed";
        threshold.AcceptanceMetricName = "ThresholdValue";
        threshold.UseAcceptanceMetricMinimum = true;
        threshold.AcceptanceMetricMinimum = 33D;
        threshold.UseAcceptanceMetricMaximum = true;
        threshold.AcceptanceMetricMaximum = 144D;
        SetParameters(
            threshold,
            (nameof(ThresholdToolProperty.Mode), ThresholdToolMode.Range),
            (nameof(ThresholdToolProperty.Threshold), 101D),
            (nameof(ThresholdToolProperty.MaxValue), 240D),
            (nameof(ThresholdToolProperty.ThresholdType), OpenCvSharp.ThresholdTypes.BinaryInv),
            (nameof(ThresholdToolProperty.RangeMin), 33),
            (nameof(ThresholdToolProperty.RangeMax), 144),
            (nameof(ThresholdToolProperty.Invert), true),
            (nameof(ThresholdToolProperty.AdaptiveType), OpenCvSharp.AdaptiveThresholdTypes.GaussianC),
            (nameof(ThresholdToolProperty.AdaptiveThresholdType), OpenCvSharp.ThresholdTypes.BinaryInv),
            (nameof(ThresholdToolProperty.BlockSize), 31),
            (nameof(ThresholdToolProperty.Weight), 7));
        AssertBasicImageRoundTrip(threshold, "Threshold");

        VisionPipelineStep morphology = CreateBasicImageRoundTripStep(
            "MorphologyTool",
            "MorphologyInput",
            "MorphologyOutput");
        SetParameters(
            morphology,
            (nameof(MorphologyToolProperty.Shape), OpenCvSharp.MorphShapes.Ellipse),
            (nameof(MorphologyToolProperty.Operator), OpenCvSharp.MorphTypes.Close),
            (nameof(MorphologyToolProperty.KernelWidth), 5),
            (nameof(MorphologyToolProperty.KernelHeight), 7),
            (nameof(MorphologyToolProperty.Iterations), 2));
        AssertBasicImageRoundTrip(morphology, "Morphology");

        VisionPipelineStep filter = CreateBasicImageRoundTripStep(
            "FilterTool",
            "FilterInput",
            "FilterOutput");
        SetParameters(
            filter,
            (nameof(FilterToolProperty.FilterType), FilterToolType.BilateralFilter),
            (nameof(FilterToolProperty.KernelWidth), 5),
            (nameof(FilterToolProperty.KernelHeight), 7),
            (nameof(FilterToolProperty.MedianKernelSize), 9),
            (nameof(FilterToolProperty.Diameter), 11),
            (nameof(FilterToolProperty.SigmaColor), 13),
            (nameof(FilterToolProperty.SigmaSpace), 17),
            (nameof(FilterToolProperty.BorderType), OpenCvSharp.BorderTypes.Reflect));
        AssertBasicImageRoundTrip(filter, "Filter");

        VisionPipelineStep edge = CreateBasicImageRoundTripStep(
            "EdgeTool",
            "EdgeInput",
            "EdgeOutput");
        SetParameters(
            edge,
            (nameof(EdgeDetectionToolProperty.EdgeType), EdgeDetectionToolType.Scharr),
            (nameof(EdgeDetectionToolProperty.CannyThresholdLow), 44),
            (nameof(EdgeDetectionToolProperty.CannyThresholdHigh), 188),
            (nameof(EdgeDetectionToolProperty.CannyApertureSize), 5),
            (nameof(EdgeDetectionToolProperty.UseL2Gradient), false),
            (nameof(EdgeDetectionToolProperty.SobelDegreeX), 1),
            (nameof(EdgeDetectionToolProperty.SobelDegreeY), 0),
            (nameof(EdgeDetectionToolProperty.SobelKernelSize), 3),
            (nameof(EdgeDetectionToolProperty.ScharrDegreeX), 0),
            (nameof(EdgeDetectionToolProperty.ScharrDegreeY), 1),
            (nameof(EdgeDetectionToolProperty.LaplacianKernelSize), 3));
        AssertBasicImageRoundTrip(edge, "EdgeDetection");
    }

    private static VisionPipelineStep CreateBasicImageRoundTripStep(
        string toolType,
        string inputLayer,
        string outputLayer)
    {
        return new VisionPipelineStep
        {
            Name = toolType + " Round Trip",
            ToolType = toolType,
            InputLayer = inputLayer,
            OutputLayer = outputLayer
        };
    }

    private static void SetParameters(
        VisionPipelineStep step,
        params (string Key, object Value)[] values)
    {
        foreach ((string key, object value) in values)
        {
            step.Parameters[key] = Convert.ToString(
                value,
                CultureInfo.InvariantCulture) ?? string.Empty;
        }
    }

    private static void AssertBasicImageRoundTrip(
        VisionPipelineStep step,
        string expectedToolType)
    {
        string inputLayer = step.InputLayer;
        string outputLayer = step.OutputLayer;
        bool enabled = step.Enabled;
        bool useAcceptance = step.UseAcceptance;
        bool expectedSuccess = step.ExpectedSuccess;
        double maxElapsedMilliseconds = step.MaxElapsedMilliseconds;
        string requiredMessageText = step.RequiredMessageText;
        string acceptanceMetricName = step.AcceptanceMetricName;
        bool useMinimum = step.UseAcceptanceMetricMinimum;
        double minimum = step.AcceptanceMetricMinimum;
        bool useMaximum = step.UseAcceptanceMetricMaximum;
        double maximum = step.AcceptanceMetricMaximum;
        Dictionary<string, string> expectedParameters = new(
            step.Parameters,
            StringComparer.OrdinalIgnoreCase);

        object property = VisionPipelineStepPropertyMapper.CreateProperty(step)
            ?? throw new InvalidOperationException(
                step.ToolType + " selected-Step property object was not created.");
        foreach ((string key, string value) in expectedParameters)
        {
            AssertPropertyValue(property, key, value);
        }

        if (!VisionPipelineStepPropertyMapper.ApplyProperty(step, property))
        {
            throw new InvalidOperationException(
                step.ToolType + " selected-Step property object did not apply back.");
        }

        if (!string.Equals(step.ToolType, expectedToolType, StringComparison.Ordinal)
            || !string.Equals(step.InputLayer, inputLayer, StringComparison.Ordinal)
            || !string.Equals(step.OutputLayer, outputLayer, StringComparison.Ordinal)
            || step.Enabled != enabled
            || step.UseAcceptance != useAcceptance
            || step.ExpectedSuccess != expectedSuccess
            || Math.Abs(step.MaxElapsedMilliseconds - maxElapsedMilliseconds) > 0.0001D
            || !string.Equals(step.RequiredMessageText, requiredMessageText, StringComparison.Ordinal)
            || !string.Equals(step.AcceptanceMetricName, acceptanceMetricName, StringComparison.Ordinal)
            || step.UseAcceptanceMetricMinimum != useMinimum
            || Math.Abs(step.AcceptanceMetricMinimum - minimum) > 0.0001D
            || step.UseAcceptanceMetricMaximum != useMaximum
            || Math.Abs(step.AcceptanceMetricMaximum - maximum) > 0.0001D)
        {
            throw new InvalidOperationException(
                expectedToolType + " selected-Step metadata or routing did not round-trip.");
        }

        foreach ((string key, string value) in expectedParameters)
        {
            AssertParameterValue(step, key, value);
        }
    }

    private static CaptureResult CaptureShellHostPipelineLifecycleRecovery(string outputPath)
    {
        OpenVisionLanguageService.SetLanguage(OpenVisionLanguage.Korean, false);
        SmokeRecipeWorkspaceCleanup.DeleteTransient();

        string recipeName = "Smoke_PipelineLifecycleRecovery_" + Guid.NewGuid().ToString("N").Substring(0, 12);
        const string oldPipelineName = "Lifecycle_A";
        const string newPipelineName = "Lifecycle_B";
        VisionPipelineStorage.Save(
            recipeName,
            RecipeContextFixture.CreatePipeline(oldPipelineName, 1));
        VisionPipelineStorage.SaveActivePipelineName(recipeName, oldPipelineName);

        using (VisionPipelineStorage.BeginLifecycleFailureInjectionForTest(
            VisionPipelineLifecycleFailureStage.AfterSourceRemoved))
        {
            if (VisionPipelineStorage.TryRenamePipeline(
                    recipeName,
                    oldPipelineName,
                    newPipelineName,
                    out string failureMessage))
            {
                throw new InvalidOperationException(
                    "Lifecycle recovery smoke did not retain an interrupted rename: " + failureMessage);
            }
        }

        VisionPipelineStorage.ResetRuntimePersistenceStateForTest();
        OpenVisionShellHostView shellHost;
        try
        {
            shellHost = CreateShellHost(recipeName, seedMainLayer: true);
            return CaptureWindowWithContent(
                shellHost,
                outputPath,
                1600,
                900,
                () =>
                {
                    Pump(100);
                    int previewRunsBefore = shellHost.NativePreviewRunCount;
                    int layerCountBefore = shellHost.LayerDocumentCount;
                    string activeLayerBefore = shellHost.ActiveHostLayerTitle;
                    string routeInputBefore = shellHost.ActiveNativeRouteInputLayerNameForTest;
                    string routeOutputBefore = shellHost.ActiveNativeRouteOutputLayerNameForTest;
                    ToggleButton recipeManagerButton = FindNamedVisualChild<ToggleButton>(
                            shellHost,
                            "btnHostRecipeManager")
                        ?? throw new InvalidOperationException(
                            "Recipe manager button was not found for lifecycle recovery smoke.");
                    recipeManagerButton.IsChecked = true;
                    Pump(80);
                    string statusText = shellHost.RecipeCommands.SelectedRecipePersistenceStatusText;
                    if (!shellHost.RecipeCommands.HasSelectedRecipePersistenceStatus
                        || shellHost.RecipeCommands.HasSelectedRecipePersistenceFailure
                        || !statusText.Contains("Pipeline 변경 복구 완료", StringComparison.Ordinal))
                    {
                        throw new InvalidOperationException(
                            "Recipe Manager did not render the recovered Pipeline lifecycle state. "
                            + $"HasStatus={shellHost.RecipeCommands.HasSelectedRecipePersistenceStatus}, "
                            + $"HasFailure={shellHost.RecipeCommands.HasSelectedRecipePersistenceFailure}, "
                            + $"Status='{statusText}'");
                    }

                    AssertVisibleAutomationIds(
                        shellHost,
                        "WPF Pipeline lifecycle recovery status",
                        "HostRecipeManagerPanel",
                        "HostRecipePersistenceStatus");
                    Border statusBorder = FindVisualChildren<Border>(shellHost)
                            .FirstOrDefault(border => string.Equals(
                                AutomationProperties.GetAutomationId(border),
                                "HostRecipePersistenceStatus",
                                StringComparison.Ordinal))
                        ?? throw new InvalidOperationException(
                            "Recipe lifecycle recovery status border was not found.");
                    if (statusBorder.Visibility != Visibility.Visible
                        || !FindVisualChildren<TextBlock>(statusBorder)
                            .Any(item => item.Text.Contains("Pipeline 변경 복구 완료", StringComparison.Ordinal)))
                    {
                        throw new InvalidOperationException(
                            "Recipe lifecycle recovery status was not visibly rendered in the current WPF surface.");
                    }

                    if (!string.Equals(
                            VisionPipelineStorage.LoadActivePipelineName(recipeName, newPipelineName),
                            oldPipelineName,
                            StringComparison.OrdinalIgnoreCase)
                        || File.Exists(RecipeWorkspaceService.GetVisionPipelinePath(recipeName, newPipelineName))
                        || File.Exists(RecipeWorkspaceService.GetVisionConfigPath(recipeName, "pipeline.lifecycle.json")))
                    {
                        throw new InvalidOperationException(
                            "Recipe lifecycle recovery did not leave the prior Pipeline and clean journal state.");
                    }

                    if (shellHost.NativePreviewRunCount != previewRunsBefore
                        || shellHost.LayerDocumentCount != layerCountBefore
                        || !string.Equals(shellHost.ActiveHostLayerTitle, activeLayerBefore, StringComparison.Ordinal)
                        || !string.Equals(shellHost.ActiveNativeRouteInputLayerNameForTest, routeInputBefore, StringComparison.Ordinal)
                        || !string.Equals(shellHost.ActiveNativeRouteOutputLayerNameForTest, routeOutputBefore, StringComparison.Ordinal)
                        || shellHost.HasNativePreviewResult
                        || shellHost.IsActiveWpfToolWindowVisibleForTest
                        || shellHost.IsNativeDocumentActive)
                    {
                        throw new InvalidOperationException(
                            "Recipe lifecycle recovery changed Preview/Run, layer, document, or route state. "
                            + $"Runs={previewRunsBefore}->{shellHost.NativePreviewRunCount}, "
                            + $"Layers={layerCountBefore}->{shellHost.LayerDocumentCount}");
                    }
                },
                captureFloatingToolWindow: false,
                captureScreen: true);
        }
        finally
        {
            RecipeWorkspaceService.DeleteVisionWorkspace(recipeName);
        }
    }

    private static CaptureResult CaptureShellHostPipelineReviewInputState(string outputPath)
    {
        OpenVisionLanguageService.SetLanguage(OpenVisionLanguage.Korean, false);
        string recipeName = "Smoke_Workbench_InputState_" + Guid.NewGuid().ToString("N");
        OpenVisionShellHostView host = CreateShellHost(recipeName);
        VisionPipeline source = CreatePipelineReviewInputStatePipeline();
        VisionPipelineStorage.Save(recipeName, source);
        VisionPipelineStorage.SaveActivePipelineName(recipeName, source.Name);
        host.RecipeCommands.RefreshOptions();
        host.RecipeCommands.SelectedPipelineOption = host.RecipeCommands.PipelineOptions.Single(option => option.PipelineName == source.Name);
        return CaptureWindowWithContent(host, outputPath, 1600, 900, () =>
        {
            OpenVisionWorkbenchPipelineViewModel model = host.Workbench.Pipeline;
            ListBox list = FindVisualChildren<ListBox>(host).Single(item => AutomationProperties.GetAutomationId(item) == "WorkbenchPipelineSteps");
            List<object> cases = new();
            void AssertReadiness(int index, string expected, bool visible, string id)
            {
                Pump(6);
                ListBoxItem item = (ListBoxItem)list.ItemContainerGenerator.ContainerFromIndex(index);
                TextBlock text = FindNamedVisualChild<TextBlock>(item, "workbenchStepReadiness");
                OpenVisionWorkbenchStepViewModel row = model.Rows[index];
                if (text.Text != expected || text.IsVisible != visible || row.ShowReadiness != visible)
                    throw new InvalidOperationException("Rendered input readiness/visibility mismatch: " + id);
                if (visible)
                {
                    if (text.ActualWidth <= 0D || text.ActualHeight <= 0D) throw new InvalidOperationException("Input readiness has no rendered area: " + id);
                    AssertElementWithinAncestor("Input readiness", text, item);
                    string brush = row.IsInputMissing ? "Error" : "MutedText";
                    if (((SolidColorBrush)text.Foreground).Color != ((SolidColorBrush)host.FindResource("OpenVision.Workbench." + brush + "Brush")).Color)
                        throw new InvalidOperationException("Input readiness lost semantic foreground: " + id);
                }
                cases.Add(new { Id = id, Text = text.Text, Visible = text.IsVisible, row.StatusKind, row.ResultStatusKind, row.IsInputMissing, EvidenceKind = "in-process WPF rendered readiness; not actual desktop input/native DPI" });
            }
            list.SelectedIndex = 1;
            Pump(8);
            VisionPipeline selected = new(); selected.Steps.Add(model.GetStep(1));
            VisionPipeline editor = new(); editor.Steps.Add(host.Workbench.Tool.CurrentStep);
            if (model.Rows.Count != 2 || model.SelectedRow?.Index != 1
                || !model.SelectedRow.IsInputMissing
                || model.SelectedRow.ReadinessText != OpenVisionLanguageService.T("PipelineReview.Status.InputMissing")
                || model.SelectedRow.Number != "02" || model.SelectedRow.Name.StartsWith("02 ", StringComparison.Ordinal)
                || !model.SelectedRow.HasError || model.ValidationSucceeded || model.RunCommand.CanExecute(null)
                || model.ResultCountForTest != 0 || host.NativePreviewRunCount != 0 || !host.IsNativeDocumentActive || !host.Workbench.Tool.IsStepEditing
                || !VisionPipelineExecutionPlan.SerializePipeline(selected).SequenceEqual(VisionPipelineExecutionPlan.SerializePipeline(editor)))
            {
                throw new InvalidOperationException($"Main pipeline rows must preserve missing-input semantics, binding selection, unique numbering, fail-closed validation, and zero execution. rows={model.Rows.Count}; selected={model.SelectedRow?.Index}; missing={model.SelectedRow?.IsInputMissing}; readiness={model.SelectedRow?.ReadinessText}; number={model.SelectedRow?.Number}; name={model.SelectedRow?.Name}; error={model.SelectedRow?.HasError}; valid={model.ValidationSucceeded}; run={model.RunCommand.CanExecute(null)}; results={model.ResultCountForTest}; previews={host.NativePreviewRunCount}; editor={host.IsNativeDocumentActive}.");
            }

            AssertReadiness(1, OpenVisionLanguageService.T("PipelineReview.Status.InputMissing"), true, "missing-external-input");
            source.Steps[1].InputLayer = source.Steps[0].OutputLayer;
            VisionPipelineStorage.Save(recipeName, source);
            host.RecipeCommands.RefreshOptions();
            Pump(8);
            if (model.Rows[1].IsInputMissing || model.Rows[1].ReadinessText != "WAIT"
                || !model.ValidationSucceeded || model.ResultCountForTest != 0 || host.NativePreviewRunCount != 0)
            {
                throw new InvalidOperationException("An earlier enabled producer must be WAIT, with no implicit execution.");
            }

            list.SelectedIndex = 1;
            AssertReadiness(1, "WAIT", true, "earlier-enabled-producer");
            if (model.Rows[1].HasStatus || model.Rows[1].ResultStatusKind != string.Empty)
                throw new InvalidOperationException("WAIT readiness must not manufacture a result chip.");
            byte[] working = VisionPipelineExecutionPlan.SerializePipeline(model.WorkingCopyForTest);
            int layers = host.LayerDocumentCount, runs = host.NativePreviewRunCount;
            string route = host.WorkspaceLayerTitle;
            Window window = Window.GetWindow(host);
            foreach (string theme in new[] { "Dark", "Light" })
            {
                ResourceDictionary palette = new() { Source = new Uri($"pack://application:,,,/OpenVisionLab;component/UI/Wpf/OpenVisionWorkbench{theme}.xaml") };
                host.Resources.MergedDictionaries.Add(palette);
                try
                {
                    foreach (int width in new[] { 1920, 1280 })
                    foreach (OpenVisionLanguage language in new[] { OpenVisionLanguage.Korean, OpenVisionLanguage.English })
                    {
                        window.Width = width; window.Height = width == 1920 ? 1032 : 760;
                        OpenVisionLanguageService.SetLanguage(language, false);
                        string id = theme + "-" + width + "-" + language + "-WAIT";
                        AssertReadiness(1, "WAIT", true, id);
                        if (model.SelectedStepIndex != 1 || !working.SequenceEqual(VisionPipelineExecutionPlan.SerializePipeline(model.WorkingCopyForTest))
                            || host.NativePreviewRunCount != runs || host.LayerDocumentCount != layers || host.WorkspaceLayerTitle != route)
                            throw new InvalidOperationException("Readiness layout/language refresh changed selection, working copy, execution, layers or route.");
                        ScreenshotPngWriter.WriteElementPng(host, Path.ChangeExtension(outputPath, "." + id + ".png"), (int)host.ActualWidth, (int)host.ActualHeight);
                    }
                }
                finally { host.Resources.MergedDictionaries.Remove(palette); }
            }
            OpenVisionLanguageService.SetLanguage(OpenVisionLanguage.Korean, false);
            source.Steps[0].Enabled = false;
            VisionPipelineStorage.Save(recipeName, source); host.RecipeCommands.RefreshOptions(); list.SelectedIndex = 1;
            AssertReadiness(0, "OFF", false, "disabled-producer");
            AssertReadiness(1, OpenVisionLanguageService.T("PipelineReview.Status.InputMissing"), true, "disabled-producer-missing-input");
            source.Steps[0].Enabled = true;
            VisionPipelineStorage.Save(recipeName, source); host.RecipeCommands.RefreshOptions(); list.SelectedIndex = 1;
            AssertReadiness(1, "WAIT", true, "enabled-producer-recovery");
            foreach (string kind in new[] { "Done", "Ng", "Error", "NotRun", "Previous" })
            {
                VisionPipelineStep step = model.GetStep(1);
                VisionPipelineStepResultSummary summary = new() { Executed = kind != "NotRun", Success = kind != "Error", IsAcceptanceNg = kind == "Ng",
                    ExecutionState = kind == "NotRun" ? VisionPipelineResultSummaryService.NotRunAfterFailureState : VisionPipelineResultSummaryService.ExecutedState,
                    Message = "Owned retained result reason" };
                PipelineFlowStepItem flow = new() { Index = 1, InputLayer = step.InputLayer, OutputLayer = step.OutputLayer, IsInputMissing = true,
                    StatusText = OpenVisionLanguageService.T("PipelineReview.Status.InputMissing") };
                model.Rows[1].UpdateFrom(new OpenVisionWorkbenchStepViewModel(flow, step, summary, kind == "Previous", false, false, Array.Empty<string>(), null));
                AssertReadiness(1, flow.StatusText, false, "retained-" + kind);
                if (model.Rows[1].StatusKind != kind) throw new InvalidOperationException("Retained result state lost priority over current readiness: " + kind);
            }
            model.RefreshInputState();
            AssertReadiness(1, "WAIT", true, "projection-reset");
            if (model.ResultCountForTest != 0 || host.NativePreviewRunCount != runs || host.LayerDocumentCount != layers || host.WorkspaceLayerTitle != route)
                throw new InvalidOperationException("Readiness and retained display checks caused execution, results, layers or route changes.");
            File.WriteAllText(Path.ChangeExtension(outputPath, ".readiness-cases.json"), JsonSerializer.Serialize(cases, new JsonSerializerOptions { WriteIndented = true }));
            source.Steps[1].InputLayer = "Unloaded_External";
            VisionPipelineStorage.Save(recipeName, source);
            host.RecipeCommands.RefreshOptions();
            list.SelectedIndex = 1;
            Pump(8);
            AssertVisibleAutomationIds(host, "Main pipeline input state", "WorkbenchPipelinePanel", "WorkbenchPipelineSteps", "WorkbenchFinalVerdict");
            AssertVisibleTextDoesNotContain(host, "Workbench main pipeline input state", "Workbench.", "PipelineReview.");
        }, captureFloatingToolWindow: false);
    }

    private static void AssertWorkbenchMenuPopup(ItemsControl menu, string? diagnosticsPath = null)
    {
        Pump(10);
        menu.UpdateLayout();
        foreach (object item in menu.Items)
        {
            if (item is FrameworkElement hidden && hidden.Visibility != Visibility.Visible) { continue; }
            if (item is Separator separator)
            {
                if (!separator.IsVisible || separator.ActualWidth <= 0D || separator.ActualHeight != 1D
                    || separator.Style?.TargetType != typeof(Separator))
                {
                    if (diagnosticsPath != null) WriteSeparatorEvidence(separator, diagnosticsPath);
                    throw new InvalidOperationException($"Workbench menu separator did not render with its typed theme style: visible={separator.IsVisible}, size={separator.ActualWidth}x{separator.ActualHeight}, target={separator.Style?.TargetType}, background={separator.Background}, localStyle={separator.ReadLocalValue(FrameworkElement.StyleProperty)}.");
                }
                string expectedBrush = ((Brush)separator.FindResource("OpenVision.Workbench.LineAltBrush")).ToString();
                if (separator.Background.ToString() != expectedBrush || !FindVisualChildren<Border>(separator).Any(border => border.Background?.ToString() == expectedBrush))
                    throw new InvalidOperationException("Workbench separator template must render its semantic line brush.");
                continue;
            }
            if (item is not MenuItem child) { continue; }
            if (!child.IsVisible || child.ActualWidth <= 0D || child.ActualHeight < 30D
                || child.Style?.TargetType != typeof(MenuItem) || child.Header == null)
            {
                if (diagnosticsPath != null) WriteMenuItemFailureEvidence(menu, child, diagnosticsPath);
                throw new InvalidOperationException("Workbench submenu did not render its typed MenuItem style.");
            }
            AssertBrushContrast(child.Foreground, (Brush)child.FindResource("OpenVision.Workbench.RaisedBrush"), "Workbench popup caption");
            if (child.Items.Count == 0) { continue; }
            child.IsSubmenuOpen = true;
            try { AssertWorkbenchMenuPopup(child, diagnosticsPath); }
            finally { child.IsSubmenuOpen = false; }
        }
    }

    private static void WriteMenuItemFailureEvidence(ItemsControl menu, MenuItem child, string outputPath)
    {
        object Describe(FrameworkElement element) => new
        {
            Type = element.GetType().FullName, element.Name, Header = element is MenuItem item ? item.Header?.ToString() : null,
            element.IsLoaded, element.IsVisible, Visibility = element.Visibility.ToString(), element.IsEnabled,
            element.ActualWidth, element.ActualHeight, element.Width, element.Height, element.MinHeight,
            element.IsMeasureValid, element.IsArrangeValid, element.IsKeyboardFocused, element.IsKeyboardFocusWithin, element.IsMouseOver,
            StyleTarget = element.Style?.TargetType?.FullName, BasedOnTarget = element.Style?.BasedOn?.TargetType?.FullName,
            StyleSource = DependencyPropertyHelper.GetValueSource(element, FrameworkElement.StyleProperty).BaseValueSource.ToString(),
            PresentationSource = PresentationSource.FromVisual(element)?.GetType().FullName,
            VisualParent = VisualTreeHelper.GetParent(element)?.GetType().FullName,
            IsOpen = element is ContextMenu context ? (bool?)context.IsOpen : element is MenuItem header ? header.IsSubmenuOpen : null
        };
        var popup = menu.Template?.FindName("PART_Popup", menu) as System.Windows.Controls.Primitives.Popup;
        File.WriteAllText(Path.ChangeExtension(outputPath, ".menu-item-failure.json"), JsonSerializer.Serialize(new
        {
            At = DateTimeOffset.Now, Owner = Describe(menu), Child = Describe(child), ChildIndex = menu.Items.IndexOf(child),
            Items = menu.Items.Count, GeneratorStatus = menu.ItemContainerGenerator.Status.ToString(),
            Popup = popup == null ? null : new { popup.IsOpen, popup.IsLoaded, popup.IsVisible, Child = popup.Child is FrameworkElement content ? Describe(content) : null },
            KeyboardFocus = Keyboard.FocusedElement?.GetType().FullName + "/" + (Keyboard.FocusedElement as FrameworkElement)?.Name,
            Predicates = new { Visible = child.IsVisible, PositiveWidth = child.ActualWidth > 0D, HeightAtLeast30 = child.ActualHeight >= 30D, TypedStyle = child.Style?.TargetType == typeof(MenuItem), HeaderPresent = child.Header != null },
            Boundary = "Read-only failure diagnostics. Original MenuItem visibility/size/style/header oracle is unchanged."
        }, new JsonSerializerOptions { WriteIndented = true, NumberHandling = System.Text.Json.Serialization.JsonNumberHandling.AllowNamedFloatingPointLiterals }));
    }

    private static void WriteSeparatorEvidence(Separator separator, string outputPath)
    {
        object localStyle = separator.ReadLocalValue(FrameworkElement.StyleProperty);
        object? key = localStyle.GetType().GetProperty("ResourceKey", BindingFlags.Instance | BindingFlags.Public | BindingFlags.NonPublic)?.GetValue(localStyle)
            ?? localStyle.GetType().GetField("_resourceKey", BindingFlags.Instance | BindingFlags.NonPublic)?.GetValue(localStyle);
        var named = separator.TryFindResource("OpenVision.Workbench.MenuSeparatorStyle") as Style;
        var system = separator.TryFindResource(MenuItem.SeparatorStyleKey) as Style;
        var childBorders = FindVisualChildren<Border>(separator).Select(border => new { border.ActualHeight, Background = border.Background?.ToString() }).ToArray();
        File.WriteAllText(Path.ChangeExtension(outputPath, ".separator-state.json"), JsonSerializer.Serialize(new
        {
            separator.ActualHeight, separator.Height, separator.MinHeight, Background = separator.Background?.ToString(),
            HeightSource = DependencyPropertyHelper.GetValueSource(separator, FrameworkElement.HeightProperty).BaseValueSource.ToString(),
            StyleKey = key?.ToString(), UsesMenuKey = ReferenceEquals(separator.Style, system), UsesNamed = ReferenceEquals(separator.Style, named),
            StyleSetters = separator.Style?.Setters.OfType<Setter>().Select(item => item.Property.Name + "=" + item.Value).ToArray(),
            NamedSetters = named?.Setters.OfType<Setter>().Select(item => item.Property.Name + "=" + item.Value).ToArray(), ChildBorders = childBorders
        }, new JsonSerializerOptions { WriteIndented = true, NumberHandling = System.Text.Json.Serialization.JsonNumberHandling.AllowNamedFloatingPointLiterals }));
        FrameworkElement root = separator;
        while (VisualTreeHelper.GetParent(root) is FrameworkElement parent) { root = parent; }
        var bitmap = new RenderTargetBitmap(Math.Max(1, (int)Math.Ceiling(root.ActualWidth)), Math.Max(1, (int)Math.Ceiling(root.ActualHeight)), 96, 96, PixelFormats.Pbgra32);
        bitmap.Render(root);
        using var stream = File.Create(Path.ChangeExtension(outputPath, ".separator-state.png"));
        var encoder = new PngBitmapEncoder(); encoder.Frames.Add(BitmapFrame.Create(bitmap)); encoder.Save(stream);
    }

    private static CaptureResult CaptureWorkbenchPipelineBranchRoute(string outputPath, bool baselineOnly = false, bool quickActionsOnly = false)
    {
        OpenVisionLanguageService.SetLanguage(OpenVisionLanguage.Korean, false);
        string recipeName = "Smoke_Workbench_BranchRoute_" + Guid.NewGuid().ToString("N");
        OpenVisionShellHostView host = CreateShellHost(recipeName);
        VisionPipeline source = CreatePipelineReviewInputStatePipeline();
        source.Steps[1].InputLayer = source.Steps[0].OutputLayer;
        VisionPipelineStorage.Save(recipeName, source);
        VisionPipelineStorage.SaveActivePipelineName(recipeName, source.Name);
        host.RecipeCommands.RefreshOptions();
        host.RecipeCommands.SelectedPipelineOption = host.RecipeCommands.PipelineOptions.Single(option => option.PipelineName == source.Name);
        return CaptureWindowWithContent(host, outputPath, 1920, 1032, () =>
        {
            Window window = Window.GetWindow(host);
            ListBox list = FindVisualChildren<ListBox>(host).Single(item => AutomationProperties.GetAutomationId(item) == "WorkbenchPipelineSteps");
            list.SelectedIndex = 1; Pump(8);
            byte[] saved = File.ReadAllBytes(RecipeWorkspaceService.GetVisionPipelinePath(recipeName, source.Name));
            byte[] memory = VisionPipelineExecutionPlan.SerializePipeline(host.Workbench.Pipeline.WorkingCopyForTest);
            int runs = host.NativePreviewRunCount, layers = host.LayerDocumentCount;
            List<object> cases = new();
            var combinations = new[]
            {
                (Theme: "Dark", Width: 1920, Language: OpenVisionLanguage.Korean),
                (Theme: "Dark", Width: 1280, Language: OpenVisionLanguage.English),
                (Theme: "Light", Width: 1920, Language: OpenVisionLanguage.English),
                (Theme: "Light", Width: 1280, Language: OpenVisionLanguage.Korean)
            };
            foreach (var combination in combinations.Take(baselineOnly ? 1 : combinations.Length))
            {
                ResourceDictionary palette = new() { Source = new Uri($"pack://application:,,,/OpenVisionLab;component/UI/Wpf/OpenVisionWorkbench{combination.Theme}.xaml") };
                host.Resources.MergedDictionaries.Add(palette);
                try
                {
                    window.Width = combination.Width; window.Height = combination.Width == 1920 ? 1032 : 760;
                    OpenVisionLanguageService.SetLanguage(combination.Language, false); Pump(8);
                    string[] kinds = quickActionsOnly ? new[] { "LongBranch", "Disabled" } : new[] { "Branch", "LongBranch", "Linear", "Disabled", "RestoredBranch" };
                    foreach (string kind in kinds.Take(baselineOnly ? 1 : kinds.Length))
                    {
                        VisionPipeline display = VisionPipelineStepEditService.Copy(source);
                        VisionPipelineStep step = display.Steps[1];
                        step.Enabled = kind != "Disabled";
                        step.InputLayer = kind == "Linear" ? display.Steps[0].OutputLayer : "Main";
                        if (kind == "LongBranch")
                        {
                            step.Name = "Long branch route with a workflow name that must remain available through trimming";
                            step.OutputLayer = "Inspection_Output_With_A_Long_Layer_Name_For_Compact_Route_Readability_And_Recovery";
                        }
                        PipelineFlowStepItem flow = OpenVisionPipelineReviewFlowPresenter.CreateItems(display.Steps, name => name == "Main", _ => null)[1];
                        OpenVisionWorkbenchStepViewModel row = new(flow, step, null, false, false, false, Array.Empty<string>(), null);
                        host.Workbench.Pipeline.Rows[1].UpdateFrom(row); Pump(8);
                        ListBoxItem item = (ListBoxItem)list.ItemContainerGenerator.ContainerFromIndex(1);
                        TextBlock tool = FindVisualChildren<TextBlock>(item).Single(block => block.Text == row.ToolName);
                        TextBlock route = FindVisualChildren<TextBlock>(item).Single(block => block.Text.EndsWith(row.PathText, StringComparison.Ordinal));
                        var branch = FindVisualChildren<MahApps.Metro.IconPacks.PackIconMaterial>(item).Single(icon => icon.Kind == MahApps.Metro.IconPacks.PackIconMaterialKind.SourceBranch);
                        Rect Bounds(FrameworkElement element) => new(element.TranslatePoint(new Point(0, 0), item), new Size(element.ActualWidth, element.ActualHeight));
                        Rect routeBounds = Bounds(route), branchBounds = Bounds(branch), toolBounds = Bounds(tool);
                        if (quickActionsOnly)
                        {
                            StackPanel actions = FindNamedVisualChild<StackPanel>(item, "quickActions");
                            StackPanel side = FindNamedVisualChild<StackPanel>(item, "workbenchStepStatusSide");
                            TextBlock name = FindNamedVisualChild<TextBlock>(item, "workbenchStepName");
                            Rect normalPath = routeBounds, normalName = Bounds(name);
                            foreach (string frame in new[] { "Normal", "Visible", "Leave" })
                            {
                                if (frame == "Visible") { actions.Visibility = Visibility.Visible; side.Visibility = Visibility.Hidden; }
                                else { actions.ClearValue(UIElement.VisibilityProperty); side.ClearValue(UIElement.VisibilityProperty); }
                                Pump(8);
                                Rect pathBounds = Bounds(route), nameBounds = Bounds(name), actionBounds = Bounds(actions);
                                Point pathCenter = new(pathBounds.Left + pathBounds.Width / 2, pathBounds.Top + pathBounds.Height / 2);
                                DependencyObject hit = item.InputHitTest(pathCenter) as DependencyObject;
                                string hitPath = string.Empty;
                                while (hit is Visual) { hitPath += hit.GetType().Name + "/"; hit = VisualTreeHelper.GetParent(hit); }
                                bool stable = pathBounds == normalPath && nameBounds == normalName;
                                bool separate = !actions.IsVisible || !actionBounds.IntersectsWith(pathBounds) && !actionBounds.IntersectsWith(Bounds(tool)) && !actionBounds.IntersectsWith(nameBounds);
                                bool pathClick = !hitPath.Contains("Button/", StringComparison.Ordinal);
                                string inputPrefix = row.PathText[..(row.PathText.IndexOf('→') + 1)];
                                TextBlock prefix = new() { Text = inputPrefix, FontFamily = route.FontFamily, FontSize = route.FontSize, FontWeight = route.FontWeight };
                                prefix.Measure(new Size(double.PositiveInfinity, double.PositiveInfinity));
                                bool inputReadable = pathBounds.Width >= prefix.DesiredSize.Width;
                                string frameId = combination.Theme + "-" + combination.Width + "-" + combination.Language + "-" + kind + "-" + frame;
                                string frameCapture = Path.ChangeExtension(outputPath, "." + frameId + ".png");
                                ScreenshotPngWriter.WriteElementPng(host, frameCapture, (int)host.ActualWidth, (int)host.ActualHeight);
                                cases.Add(new { Id = frameId, Status = stable && separate && pathClick && inputReadable ? "PASS" : "FAIL", Capture = frameCapture, StableBounds = stable, ReadAreaSeparate = separate, PathHitsRow = pathClick, InputPrefixFits = inputReadable, InputPrefix = inputPrefix, RequiredPrefixWidth = prefix.DesiredSize.Width,
                                    PathBounds = pathBounds.ToString(CultureInfo.InvariantCulture), NameBounds = nameBounds.ToString(CultureInfo.InvariantCulture), ActionBounds = actionBounds.ToString(CultureInfo.InvariantCulture), HitPath = hitPath,
                                    ActionsVisible = actions.IsVisible, row.IsEnabled, row.PathText, EvidenceKind = "Local Visibility projection; not actual pointer hover/pressed input" });
                                File.WriteAllText(Path.ChangeExtension(outputPath, ".quick-actions-cases.json"), JsonSerializer.Serialize(new { Cases = cases, runs, layers, EvidenceKind = "in-process WPF geometry/hit; actual pointer verification is separate" }, new JsonSerializerOptions { WriteIndented = true }));
                                if (!stable || !separate || !pathClick || !inputReadable) throw new InvalidOperationException($"Quick actions must replace the status region without shifting/intercepting row text: {frameId}, stable={stable}, separate={separate}, pathClick={pathClick}, inputReadable={inputReadable}.");
                                AssertElementWithinAncestor("Route text", route, item);
                                AssertElementWithinAncestor("Tool caption", tool, item);
                            }
                            actions.ClearValue(UIElement.VisibilityProperty); side.ClearValue(UIElement.VisibilityProperty);
                            continue;
                        }

                        bool expectedBranch = kind != "Linear" && kind != "Disabled";
                        Color expectedColor = combination.Theme == "Dark" ? Color.FromRgb(0x6A, 0xAE, 0xFF) : Color.FromRgb(0x24, 0x64, 0xC9);
                        string id = combination.Theme + "-" + combination.Width + "-" + combination.Language + "-" + kind;
                        string capture = Path.ChangeExtension(outputPath, "." + id + ".png");
                        ScreenshotPngWriter.WriteElementPng(host, capture, (int)host.ActualWidth, (int)host.ActualHeight);
                        bool inline = !expectedBranch || branch.Parent == route.Parent && branchBounds.Top + branchBounds.Height / 2 >= routeBounds.Top
                            && branchBounds.Top + branchBounds.Height / 2 <= routeBounds.Bottom && branchBounds.Left >= toolBounds.Right && branchBounds.Right <= routeBounds.Left;
                        bool displayMatches = row.IsBranch == expectedBranch && branch.IsVisible == expectedBranch && route.Text == row.PathText
                            && branch.ToolTip?.ToString() == row.BranchTooltip && route.ToolTip?.ToString() == row.PathText
                            && route.TextTrimming == TextTrimming.CharacterEllipsis && ((SolidColorBrush)branch.Foreground).Color == expectedColor;
                        cases.Add(new { Id = id, Status = inline && displayMatches ? "PASS" : "FAIL", Capture = capture, row.IsBranch, BranchVisible = branch.IsVisible,
                            Inline = inline, DisplayMatches = displayMatches, ToolBounds = toolBounds.ToString(CultureInfo.InvariantCulture), RouteBounds = routeBounds.ToString(CultureInfo.InvariantCulture),
                            BranchBounds = branchBounds.ToString(CultureInfo.InvariantCulture), Color = branch.Foreground.ToString(), row.PathText, row.BranchTooltip });
                        File.WriteAllText(Path.ChangeExtension(outputPath, ".branch-route-cases.json"), JsonSerializer.Serialize(new { Cases = cases, runs, layers, EvidenceKind = "in-process WPF projection/inline branch display; no actual execution, native input/DPI or same-state HTML" }, new JsonSerializerOptions { WriteIndented = true }));
                        if (!inline || !displayMatches) throw new InvalidOperationException($"Branch route must share the tool/path line and canonical info hue: {id}, inline={inline}, display={displayMatches}, branch={branchBounds}, path={routeBounds}, color={branch.Foreground}.");
                        AssertElementWithinAncestor("Branch route", route, item);
                        AssertElementWithinAncestor("Tool caption", tool, item);
                        if (expectedBranch) AssertElementWithinAncestor("Inline branch icon", branch, item);
                    }
                }
                finally { host.Resources.MergedDictionaries.Remove(palette); }
            }
            if (!VisionPipelineExecutionPlan.SerializePipeline(host.Workbench.Pipeline.WorkingCopyForTest).SequenceEqual(memory)
                || !File.ReadAllBytes(RecipeWorkspaceService.GetVisionPipelinePath(recipeName, source.Name)).SequenceEqual(saved)
                || host.NativePreviewRunCount != runs || host.LayerDocumentCount != layers || list.SelectedIndex != 1)
                throw new InvalidOperationException("Branch display fixture changed working/saved recipe, execution, layers or selection.");
            OpenVisionLanguageService.SetLanguage(OpenVisionLanguage.Korean, false);
        }, captureFloatingToolWindow: false);
    }

    private static CaptureResult CaptureWorkbenchPipelineRowStatus(string outputPath)
    {
        OpenVisionLanguageService.SetLanguage(OpenVisionLanguage.Korean, false);
        string recipeName = "Smoke_Workbench_RowStatus_" + Guid.NewGuid().ToString("N");
        OpenVisionShellHostView host = CreateShellHost(recipeName);
        VisionPipeline source = CreatePipelineReviewInputStatePipeline();
        source.Steps[1].InputLayer = source.Steps[0].OutputLayer;
        VisionPipelineStorage.Save(recipeName, source);
        VisionPipelineStorage.SaveActivePipelineName(recipeName, source.Name);
        host.RecipeCommands.RefreshOptions();
        host.RecipeCommands.SelectedPipelineOption = host.RecipeCommands.PipelineOptions.Single(option => option.PipelineName == source.Name);
        return CaptureWindowWithContent(host, outputPath, 1920, 1032, () =>
        {
            Window window = Window.GetWindow(host);
            ListBox list = FindVisualChildren<ListBox>(host).Single(item => AutomationProperties.GetAutomationId(item) == "WorkbenchPipelineSteps");
            byte[] saved = File.ReadAllBytes(RecipeWorkspaceService.GetVisionPipelinePath(recipeName, source.Name));
            byte[] memory = VisionPipelineExecutionPlan.SerializePipeline(host.Workbench.Pipeline.WorkingCopyForTest);
            int runs = host.NativePreviewRunCount, layers = host.LayerDocumentCount;
            string[][] pairs = { new[] { "Ok", "Ng" }, new[] { "Error", "Done" }, new[] { "Running", "Previous" }, new[] { "NotRun", "Disabled" }, new[] { "Cancelled", "" } };
            Dictionary<string, (MahApps.Metro.IconPacks.PackIconMaterialKind Icon, string Brush)> expected = new()
            {
                ["Ok"] = (MahApps.Metro.IconPacks.PackIconMaterialKind.CheckCircle, "Ok"),
                ["Ng"] = (MahApps.Metro.IconPacks.PackIconMaterialKind.CloseCircle, "Ng"),
                ["Error"] = (MahApps.Metro.IconPacks.PackIconMaterialKind.AlertCircle, "Error"),
                ["Done"] = (MahApps.Metro.IconPacks.PackIconMaterialKind.CheckCircleOutline, "Done"),
                ["Running"] = (MahApps.Metro.IconPacks.PackIconMaterialKind.TimerOutline, "Accent"),
                ["Previous"] = (MahApps.Metro.IconPacks.PackIconMaterialKind.AlertOutline, "Stale"),
                ["NotRun"] = (MahApps.Metro.IconPacks.PackIconMaterialKind.CircleSmall, "MutedText"),
                ["Disabled"] = (MahApps.Metro.IconPacks.PackIconMaterialKind.MinusCircleOutline, "Skip"),
                ["Cancelled"] = (MahApps.Metro.IconPacks.PackIconMaterialKind.MinusCircleOutline, "Skip")
            };
            OpenVisionWorkbenchStepViewModel MakeRow(int index, string kind)
            {
                VisionPipelineStep step = VisionPipelineStepEditService.Copy(source).Steps[index];
                step.Enabled = kind != "Disabled";
                step.UseAcceptance = kind == "Ok" || kind == "Ng";
                step.AcceptanceMetricName = VisionPipelineKnownMetrics.ResultImageWidth;
                step.UseAcceptanceMetricMaximum = true; step.AcceptanceMetricMaximum = 1;
                VisionPipelineStepResultSummary summary = kind is "Running" or "Disabled" or "" ? null : new()
                {
                    Success = kind != "Error", IsAcceptanceNg = kind == "Ng", ElapsedMilliseconds = 12.5,
                    Executed = kind is not "NotRun" and not "Cancelled",
                    ExecutionState = kind == "NotRun" ? VisionPipelineResultSummaryService.NotRunAfterFailureState : kind == "Cancelled" ? VisionPipelineResultSummaryService.CancelledState : VisionPipelineResultSummaryService.ExecutedState,
                    Message = "Owned display fixture: a long failure reason must wrap without covering the state or actions.",
                    Metrics = new Dictionary<string, double> { [VisionPipelineKnownMetrics.ResultImageWidth] = 640 }
                };
                PipelineFlowStepItem flow = new() { Index = index, InputLayer = step.InputLayer, OutputLayer = step.OutputLayer, StatusText = "Ready" };
                return new OpenVisionWorkbenchStepViewModel(flow, step, summary, kind == "Previous", false, kind == "Running", Array.Empty<string>(), null);
            }
            foreach (int width in new[] { 1920, 1280 })
            {
                window.Width = width; window.Height = width == 1920 ? 1032 : 760;
                for (int index = 0; index < 2; index++) host.Workbench.Pipeline.Rows[index].UpdateFrom(MakeRow(index, pairs[0][index]));
                Pump(8);
                ScreenshotPngWriter.WriteElementPng(host, Path.ChangeExtension(outputPath, ".initial-" + width + ".png"), (int)host.ActualWidth, (int)host.ActualHeight);
            }
            List<object> cases = new();
            foreach (string theme in new[] { "Dark", "Light" })
            {
                ResourceDictionary palette = new() { Source = new Uri($"pack://application:,,,/OpenVisionLab;component/UI/Wpf/OpenVisionWorkbench{theme}.xaml") };
                host.Resources.MergedDictionaries.Add(palette);
                try
                {
                    foreach (int width in new[] { 1920, 1280 })
                    foreach (OpenVisionLanguage language in new[] { OpenVisionLanguage.Korean, OpenVisionLanguage.English })
                    {
                        window.Width = width; window.Height = width == 1920 ? 1032 : 760;
                        OpenVisionLanguageService.SetLanguage(language, false); Pump(8);
                        foreach (string[] pair in pairs)
                        {
                            for (int index = 0; index < 2; index++) host.Workbench.Pipeline.Rows[index].UpdateFrom(MakeRow(index, pair[index]));
                            Pump(8);
                            for (int index = 0; index < 2; index++)
                            {
                                OpenVisionWorkbenchStepViewModel row = host.Workbench.Pipeline.Rows[index];
                                ListBoxItem item = (ListBoxItem)list.ItemContainerGenerator.ContainerFromIndex(index);
                                Border chip = FindVisualChildren<Border>(item).Single(border => border.Name == "statusChip");
                                TextBlock text = FindVisualChildren<TextBlock>(item).Single(block => block.Name == "statusText");
                                var icon = FindVisualChildren<MahApps.Metro.IconPacks.PackIconMaterial>(item).SingleOrDefault(value => value.Name == "workbenchStepStatusIcon");
                                Grid columns = FindVisualChildren<Grid>(item).SingleOrDefault(grid => grid.Name == "workbenchStepColumns");
                                Border tile = FindVisualChildren<Border>(item).SingleOrDefault(border => border.Name == "workbenchStepToolTile");
                                StackPanel main = FindVisualChildren<StackPanel>(item).SingleOrDefault(panel => panel.Name == "workbenchStepMain");
                                StackPanel side = FindVisualChildren<StackPanel>(item).Single(panel => panel.Name == "workbenchStepStatusSide");
                                if (columns == null || columns.ColumnDefinitions.Count != 4 || columns.ColumnDefinitions[0].ActualWidth != 28 || columns.ColumnDefinitions[1].ActualWidth != 32
                                    || tile == null || tile.ActualWidth != 26 || tile.ActualHeight != 26 || main == null || Grid.GetColumn(main) != 2 || Grid.GetColumn(side) != 3)
                                    throw new InvalidOperationException("Canonical four-column row/tile contract mismatch (22/26 plus6gap).");
                                bool compactPrevious = row.StatusKind == "Previous" && host.Workbench.IsCompact;
                                if (text.IsVisible != (row.HasStatus && !compactPrevious) || icon.Margin != (compactPrevious ? new Thickness(0) : new Thickness(0, 0, 4, 0))
                                    || chip.ToolTip?.ToString() != row.StatusText)
                                    throw new InvalidOperationException("Compact Previous caption/icon recovery or accessible status mismatch.");
                                AssertElementWithinAncestor("Row tool tile", tile, item);
                                AssertElementWithinAncestor("Row main column", main, item);
                                if (row.HasStatus || row.HasElapsed) AssertElementWithinAncestor("Row status side", side, item);
                                if (row.StatusKind != pair[index] || text.Text != row.StatusText || chip.IsVisible != row.HasStatus || icon == null)
                                    throw new InvalidOperationException("Row status binding/icon mismatch for " + pair[index]);
                                if (row.HasStatus)
                                {
                                    var requirement = expected[row.StatusKind];
                                    if (icon.Kind != requirement.Icon || !Equals(((SolidColorBrush)icon.Foreground).Color, ((SolidColorBrush)text.Foreground).Color)
                                        || !Equals(((SolidColorBrush)text.Foreground).Color, ((SolidColorBrush)host.FindResource("OpenVision.Workbench." + requirement.Brush + "Brush")).Color))
                                        throw new InvalidOperationException("Row semantic icon/foreground mismatch for " + row.StatusKind);
                                    if (row.StatusKind is "Running" or "Previous")
                                    {
                                        Color expectedBackground = ((SolidColorBrush)host.FindResource("OpenVision.Workbench." + requirement.Brush + "SoftBrush")).Color;
                                        if (((SolidColorBrush)chip.Background).Color != expectedBackground) throw new InvalidOperationException("Row semantic background mismatch for " + row.StatusKind);
                                    }
                                    if (text.IsVisible) AssertElementWithinAncestor("Row status caption", text, chip);
                                }
                                TextBlock elapsed = FindVisualChildren<TextBlock>(item).SingleOrDefault(block => block.Name == "workbenchStepElapsed");
                                if (elapsed == null || elapsed.Text != row.ElapsedText || elapsed.IsVisible != row.HasElapsed
                                    || (elapsed.Parent as StackPanel)?.Name != "workbenchStepStatusSide")
                                    throw new InvalidOperationException("Elapsed binding/side placement mismatch for " + row.StatusKind);
                                if (row.HasElapsed)
                                {
                                    AssertElementWithinAncestor("Row elapsed", elapsed, (FrameworkElement)elapsed.Parent);
                                    if (elapsed.TranslatePoint(new Point(0, 0), item).Y < chip.TranslatePoint(new Point(0, chip.ActualHeight), item).Y)
                                        throw new InvalidOperationException("Elapsed must render below its status chip.");
                                }
                                var acceptanceIcon = FindVisualChildren<MahApps.Metro.IconPacks.PackIconMaterial>(item).SingleOrDefault(value => value.Name == "workbenchStepAcceptanceIcon");
                                var errorIcon = FindVisualChildren<MahApps.Metro.IconPacks.PackIconMaterial>(item).SingleOrDefault(value => value.Name == "workbenchStepErrorIcon");
                                if (acceptanceIcon == null || acceptanceIcon.IsVisible != row.HasAcceptance || errorIcon == null || errorIcon.IsVisible != row.HasError
                                    || row.HasError && errorIcon.Kind != (row.StatusKind == "Ng" ? MahApps.Metro.IconPacks.PackIconMaterialKind.CloseCircleOutline : MahApps.Metro.IconPacks.PackIconMaterialKind.AlertCircleOutline))
                                    throw new InvalidOperationException("Acceptance/error icon binding mismatch for " + row.StatusKind);
                            }
                            string id = theme + "-" + width + "-" + language + "-" + string.Join("_", pair);
                            string capture = string.Empty;
                            if (pair[0] is "Ok" or "Error" or "Running")
                            {
                                capture = Path.ChangeExtension(outputPath, "." + id + ".png");
                                ScreenshotPngWriter.WriteElementPng(host, capture, (int)host.ActualWidth, (int)host.ActualHeight);
                            }
                            cases.Add(new { Id = id, Status = "PASS", Kinds = pair, Capture = capture });
                        }
                    }
                }
                finally { host.Resources.MergedDictionaries.Remove(palette); }
            }
            if (!VisionPipelineExecutionPlan.SerializePipeline(host.Workbench.Pipeline.WorkingCopyForTest).SequenceEqual(memory)
                || !File.ReadAllBytes(RecipeWorkspaceService.GetVisionPipelinePath(recipeName, source.Name)).SequenceEqual(saved)
                || host.NativePreviewRunCount != runs || host.LayerDocumentCount != layers)
                throw new InvalidOperationException("Row display fixture changed working/saved recipe, execution or layers.");
            File.WriteAllText(Path.ChangeExtension(outputPath, ".row-status-cases.json"), JsonSerializer.Serialize(new { Cases = cases, runs, layers, EvidenceKind = "in-process WPF four-column layout/26DIP tile and Compact Previous recovery with affected synthetic row states; not actual execution/input/native DPI/HTML" }, new JsonSerializerOptions { WriteIndented = true }));
            OpenVisionLanguageService.SetLanguage(OpenVisionLanguage.Korean, false);
        }, captureFloatingToolWindow: false);
    }

    private static CaptureResult CaptureWorkbenchStepNumberPrefix(string outputPath)
    {
        OpenVisionLanguageService.SetLanguage(OpenVisionLanguage.Korean, false);
        string recipeName = "Smoke_Workbench_Prefix_" + Guid.NewGuid().ToString("N");
        OpenVisionShellHostView host = CreateShellHost(recipeName);
        VisionPipeline source = CreatePipelineReviewInputStatePipeline();
        source.Steps[0].Name = "1  .__-Noise cleanup with a deliberately long workflow name";
        source.Steps[1].Name = "123___Threshold_검사 이름";
        source.Steps[1].InputLayer = source.Steps[0].OutputLayer;
        VisionPipelineStorage.Save(recipeName, source);
        VisionPipelineStorage.SaveActivePipelineName(recipeName, source.Name);
        host.RecipeCommands.RefreshOptions();
        host.RecipeCommands.SelectedPipelineOption = host.RecipeCommands.PipelineOptions.Single(option => option.PipelineName == source.Name);
        return CaptureWindowWithContent(host, outputPath, 1920, 1032, () =>
        {
            Window window = Window.GetWindow(host);
            byte[] saved = File.ReadAllBytes(RecipeWorkspaceService.GetVisionPipelinePath(recipeName, source.Name));
            byte[] memory = VisionPipelineExecutionPlan.SerializePipeline(host.Workbench.Pipeline.WorkingCopyForTest);
            int runs = host.NativePreviewRunCount, layers = host.LayerDocumentCount;
            foreach (int width in new[] { 1920, 1280 })
            {
                window.Width = width; window.Height = width == 1920 ? 1032 : 760; Pump(8);
                ScreenshotPngWriter.WriteElementPng(host, Path.ChangeExtension(outputPath, ".initial-" + width + ".png"), (int)host.ActualWidth, (int)host.ActualHeight);
            }
            (string Input, string Expected)[] expected =
            {
                (null, ""), ("", ""), ("1 Name", "Name"), ("01 Name", "Name"), ("123 Name", "Name"),
                ("01  .__-Name", "Name"), ("1.2 Part", "2 Part"), ("123___Name", "Name"),
                ("1234 Name", "1234 Name"), ("01Name", "01Name"), ("01", "01"), ("٢١ Name", "٢١ Name")
            };
            foreach (var item in expected)
                if (OpenVisionWorkbenchStepViewModel.DisplayName(item.Input) != item.Expected)
                    throw new InvalidOperationException("Prefix contract mismatch for '" + item.Input + "'; canonical accepts1..3ASCII digits and all following separators.");
            string[] display = { "Noise cleanup with a deliberately long workflow name", "Threshold_검사 이름" };
            List<object> cases = new();
            foreach (string theme in new[] { "Dark", "Light" })
            {
                ResourceDictionary palette = new() { Source = new Uri($"pack://application:,,,/OpenVisionLab;component/UI/Wpf/OpenVisionWorkbench{theme}.xaml") };
                host.Resources.MergedDictionaries.Add(palette);
                try
                {
                    foreach (int width in new[] { 1920, 1280 })
                    foreach (OpenVisionLanguage language in new[] { OpenVisionLanguage.Korean, OpenVisionLanguage.English })
                    {
                        window.Width = width; window.Height = width == 1920 ? 1032 : 760;
                        OpenVisionLanguageService.SetLanguage(language, false); Pump(8);
                        TextBlock[] names = FindVisualChildren<TextBlock>(host).Where(text => text.Name == "workbenchStepName").ToArray();
                        if (names.Length != 2 || !names.Select(text => text.Text).SequenceEqual(display)
                            || !host.Workbench.Pipeline.Rows.Select(row => row.Name).SequenceEqual(display)
                            || !host.Workbench.Pipeline.WorkingCopyForTest.Steps.Select(step => step.Name).SequenceEqual(source.Steps.Select(step => step.Name)))
                            throw new InvalidOperationException("Prefix display or raw working copy names changed.");
                        foreach (TextBlock name in names) AssertElementWithinAncestor("Step prefix name", name, (FrameworkElement)name.Parent);
                        if (!VisionPipelineExecutionPlan.SerializePipeline(host.Workbench.Pipeline.WorkingCopyForTest).SequenceEqual(memory)
                            || !File.ReadAllBytes(RecipeWorkspaceService.GetVisionPipelinePath(recipeName, source.Name)).SequenceEqual(saved)
                            || host.NativePreviewRunCount != runs || host.LayerDocumentCount != layers)
                            throw new InvalidOperationException("Prefix display changed saved data, working copy, execution or layers.");
                        string id = theme + "-" + width + "-" + language;
                        string capture = Path.ChangeExtension(outputPath, "." + id + ".png");
                        ScreenshotPngWriter.WriteElementPng(host, capture, (int)host.ActualWidth, (int)host.ActualHeight);
                        cases.Add(new { Id = id, Status = "PASS", Names = names.Select(text => text.Text).ToArray(), RawNames = source.Steps.Select(step => step.Name).ToArray(), runs, layers, Capture = capture });
                    }
                }
                finally { host.Resources.MergedDictionaries.Remove(palette); }
            }
            File.WriteAllText(Path.ChangeExtension(outputPath, ".prefix-cases.json"), JsonSerializer.Serialize(new { PurePrefixCases = expected.Length, Rendered = cases, EvidenceKind = "in-process WPF, not native DPI/HTML/actual input" }, new JsonSerializerOptions { WriteIndented = true }));
        }, captureFloatingToolWindow: false);
    }

    private static CaptureResult CaptureWorkbenchPipelineSelectorIcon(string outputPath, bool single, bool badgeOnly = false)
    {
        OpenVisionLanguageService.SetLanguage(OpenVisionLanguage.Korean, false);
        string recipeName = "Smoke_Workbench_Selector_" + Guid.NewGuid().ToString("N");
        OpenVisionShellHostView host = CreateShellHost(recipeName);
        VisionPipeline longName = new() { Name = "Pipeline_긴_파이프라인_이름_Long_selected_value_123456789_End" };
        VisionPipeline shortName = new() { Name = "Selector_원본검사" };
        VisionPipeline[] sources = single ? new[] { longName } : new[] { shortName, longName };
        foreach (VisionPipeline source in sources) VisionPipelineStorage.Save(recipeName, source);
        foreach (string seededName in RecipeWorkspaceService.GetVisionPipelineNames(recipeName).Except(sources.Select(source => source.Name), StringComparer.OrdinalIgnoreCase))
            if (!VisionPipelineStorage.TryDeletePipeline(recipeName, seededName, out _, out string message)) throw new InvalidOperationException("Owned selector fixture setup: " + message);
        VisionPipelineStorage.SaveActivePipelineName(recipeName, sources[0].Name);
        host.RecipeCommands.RefreshOptions();
        host.RecipeCommands.SelectedPipelineOption = host.RecipeCommands.PipelineOptions.Single(option => option.PipelineName == sources[0].Name);
        if (host.RecipeCommands.PipelineOptions.Count != sources.Length) throw new InvalidOperationException("Owned selector fixture pipeline count is incorrect.");
        return CaptureWindowWithContent(host, outputPath, 1920, 1032, () =>
        {
            Window window = Window.GetWindow(host);
            Grid panel = FindVisualChildren<Grid>(host).Single(item => AutomationProperties.GetAutomationId(item) == "WorkbenchPipelinePanel");
            ComboBox combo = FindVisualChildren<ComboBox>(panel).Single(item => AutomationProperties.GetAutomationId(item) == "WorkbenchPipelineCombo");
            if (!OpenVisionLab.Mvvm.Behaviors.ComboBoxInteractionBehavior.GetOpenOnFieldClick(combo)) throw new InvalidOperationException("Pipeline selector lost its existing field-click behavior.");
            TextBlock singleName = FindVisualChildren<TextBlock>(panel).Single(item => AutomationProperties.GetAutomationId(item) == "WorkbenchSinglePipelineName");
            FrameworkElement selector = single ? (FrameworkElement)singleName.Parent : combo;
            int runs = host.NativePreviewRunCount, layers = host.LayerDocumentCount;
            Dictionary<string, byte[]> savedXml = sources.ToDictionary(source => source.Name, source => File.ReadAllBytes(RecipeWorkspaceService.GetVisionPipelinePath(recipeName, source.Name)));
            List<object> cases = new();
            if (badgeOnly)
            {
                TextBlock badgeText = FindVisualChildren<TextBlock>(panel).Single(item => AutomationProperties.GetAutomationId(item) == "WorkbenchDefaultPipelineBadge");
                Border badge = (Border)badgeText.Parent;
                Grid header = (Grid)badge.Parent;
                void CaptureBadgeCase(string id, bool expected, string sourceName)
                {
                    Pump(8);
                    string capture = Path.ChangeExtension(outputPath, "." + id + ".png");
                    ScreenshotPngWriter.WriteElementPng(host, capture, (int)host.ActualWidth, (int)host.ActualHeight);
                    bool visible = badge.IsVisible;
                    bool collapsed = badge.Visibility == Visibility.Collapsed && header.ColumnDefinitions[1].ActualWidth == 0D;
                    cases.Add(new { Id = id, Status = expected ? visible ? "PASS" : "FAIL" : collapsed ? "PASS" : "FAIL", ExpectedVisible = expected, ActualVisibility = badge.Visibility.ToString(), BadgeColumnWidth = header.ColumnDefinitions[1].ActualWidth, Text = badgeText.Text, Source = sourceName, runs, layers, Capture = capture, EvidenceKind = "in-process WPF; projection and selection refresh; no actual pointer/native DPI/HTML" });
                    File.WriteAllText(Path.ChangeExtension(outputPath, ".badge-cases.json"), JsonSerializer.Serialize(cases, new JsonSerializerOptions { WriteIndented = true }));
                    if (expected ? !visible : !collapsed) throw new InvalidOperationException("Default badge count/active display condition failed: " + id);
                    if (host.Workbench.Pipeline.SelectedPipelineName != sourceName || combo.IsVisible != host.Workbench.Pipeline.HasMultiplePipelines || singleName.IsVisible != host.Workbench.Pipeline.HasSinglePipeline)
                        throw new InvalidOperationException("Default badge changed selector visibility or selected projection.");
                    if (expected)
                    {
                        if (badgeText.Text != OpenVisionLanguageService.T("Workbench.Pipeline.Default") || badgeText.ActualWidth <= 0D) throw new InvalidOperationException("Default badge lost its localized caption.");
                        AssertElementWithinAncestor("Default badge", badge, header);
                        AssertElementWithinAncestor("Default badge text", badgeText, badge);
                        if (new Rect(combo.TranslatePoint(new Point(), header), new System.Windows.Size(combo.ActualWidth, combo.ActualHeight)).IntersectsWith(new Rect(badge.TranslatePoint(new Point(), header), new System.Windows.Size(badge.ActualWidth, badge.ActualHeight))))
                            throw new InvalidOperationException("Default badge overlaps the selected pipeline.");
                    }
                    if (host.NativePreviewRunCount != runs || host.LayerDocumentCount != layers || savedXml.Any(entry => !File.ReadAllBytes(RecipeWorkspaceService.GetVisionPipelinePath(recipeName, entry.Key)).SequenceEqual(entry.Value)))
                        throw new InvalidOperationException("Default badge display caused execution, layer or saved pipeline mutation.");
                }
                foreach (string theme in new[] { "Dark", "Light" })
                {
                    ResourceDictionary palette = new() { Source = new Uri($"pack://application:,,,/OpenVisionLab;component/UI/Wpf/OpenVisionWorkbench{theme}.xaml") };
                    host.Resources.MergedDictionaries.Add(palette); window.Resources.MergedDictionaries.Add(palette);
                    try
                    {
                        foreach (int width in new[] { 1920, 1280 })
                        foreach (OpenVisionLanguage language in new[] { OpenVisionLanguage.Korean, OpenVisionLanguage.English })
                        foreach (VisionPipeline source in sources)
                        {
                            window.Width = width; window.Height = width == 1920 ? 1032 : 760;
                            OpenVisionLanguageService.SetLanguage(language, false);
                            host.RecipeCommands.SelectedPipelineOption = host.RecipeCommands.PipelineOptions.Single(option => option.PipelineName == source.Name); Pump(8);
                            byte[] working = VisionPipelineExecutionPlan.SerializePipeline(host.Workbench.Pipeline.WorkingCopyForTest);
                            CaptureBadgeCase(theme + "-" + width + "-" + language + "-" + (source == sources[0] ? "Active" : "Other"), !single && source == sources[0], source.Name);
                            if (!working.SequenceEqual(VisionPipelineExecutionPlan.SerializePipeline(host.Workbench.Pipeline.WorkingCopyForTest))) throw new InvalidOperationException("Default badge display changed the working pipeline.");
                        }
                    }
                    finally { window.Resources.MergedDictionaries.Remove(palette); host.Resources.MergedDictionaries.Remove(palette); }
                }
                host.RecipeCommands.SelectedPipelineOption = host.RecipeCommands.PipelineOptions.Single(option => option.PipelineName == sources[0].Name);
                if (single)
                {
                    VisionPipelineStorage.Save(recipeName, shortName); host.RecipeCommands.RefreshOptions();
                    host.RecipeCommands.SelectedPipelineOption = host.RecipeCommands.PipelineOptions.Single(option => option.PipelineName == sources[0].Name);
                    CaptureBadgeCase("CountRefresh-1to2-active", true, sources[0].Name);
                    combo.SelectedItem = host.RecipeCommands.PipelineOptions.Single(option => option.PipelineName == shortName.Name);
                    CaptureBadgeCase("CountRefresh-1to2-other", false, shortName.Name);
                    host.RecipeCommands.SelectedPipelineOption = host.RecipeCommands.PipelineOptions.Single(option => option.PipelineName == sources[0].Name);
                    if (!VisionPipelineStorage.TryDeletePipeline(recipeName, shortName.Name, out _, out string message)) throw new InvalidOperationException("Owned badge count restore: " + message);
                    host.RecipeCommands.RefreshOptions();
                    CaptureBadgeCase("CountRefresh-2to1-active", false, sources[0].Name);
                }
                else
                {
                    CaptureBadgeCase("SelectionRestore-active", true, sources[0].Name);
                }
                return;
            }
            if (!FindVisualChildren<MahApps.Metro.IconPacks.PackIconMaterial>(selector).Any(icon => icon.Kind == MahApps.Metro.IconPacks.PackIconMaterialKind.ChartTimelineVariant))
            {
                foreach (int width in new[] { 1920, 1280 })
                {
                    window.Width = width; window.Height = width == 1920 ? 1032 : 760; Pump(8);
                    ScreenshotPngWriter.WriteElementPng(host, Path.ChangeExtension(outputPath, ".baseline-" + width + ".png"), (int)host.ActualWidth, (int)host.ActualHeight);
                }
                throw new InvalidOperationException("Baseline: canonical pipeline selector ChartTimelineVariant is absent.");
            }
            foreach (string theme in new[] { "Dark", "Light" })
            {
                ResourceDictionary palette = new() { Source = new Uri($"pack://application:,,,/OpenVisionLab;component/UI/Wpf/OpenVisionWorkbench{theme}.xaml") };
                host.Resources.MergedDictionaries.Add(palette);
                window.Resources.MergedDictionaries.Add(palette);
                try
                {
                    foreach (int width in new[] { 1920, 1280 })
                    foreach (OpenVisionLanguage language in new[] { OpenVisionLanguage.Korean, OpenVisionLanguage.English })
                    foreach (VisionPipeline source in sources)
                    {
                        window.Width = width; window.Height = width == 1920 ? 1032 : 760;
                        OpenVisionLanguageService.SetLanguage(language, false);
                        host.RecipeCommands.SelectedPipelineOption = host.RecipeCommands.PipelineOptions.Single(option => option.PipelineName == source.Name); Pump(8);
                        byte[] working = VisionPipelineExecutionPlan.SerializePipeline(host.Workbench.Pipeline.WorkingCopyForTest);
                        if (combo.IsVisible == single || singleName.IsVisible != single || host.Workbench.Pipeline.SelectedPipelineName != source.Name || !single && combo.SelectedItem != host.RecipeCommands.SelectedPipelineOption)
                            throw new InvalidOperationException("Pipeline selector lost its count-dependent visibility or selected value.");
                        if (!single)
                        {
                            var alternate = host.RecipeCommands.PipelineOptions.Single(option => option.PipelineName != source.Name);
                            combo.SelectedItem = alternate; Pump(8);
                            if (host.RecipeCommands.SelectedPipelineOption != alternate) throw new InvalidOperationException("Pipeline selector control-to-model binding failed.");
                            host.RecipeCommands.SelectedPipelineOption = host.RecipeCommands.PipelineOptions.Single(option => option.PipelineName == source.Name); Pump(8);
                        }
                        foreach (string state in single ? new[] { "ReadOnly" } : width == 1280 && language == OpenVisionLanguage.Korean && source == longName ? new[] { "Normal", "Focus", "Disabled", "Popup" } : new[] { "Normal" })
                        {
                            combo.SetCurrentValue(UIElement.IsEnabledProperty, state != "Disabled");
                            if (state == "Focus") combo.Focus();
                            combo.IsDropDownOpen = state == "Popup"; Pump(8);
                            var icon = FindVisualChildren<MahApps.Metro.IconPacks.PackIconMaterial>(selector).Single(item => item.Kind == MahApps.Metro.IconPacks.PackIconMaterialKind.ChartTimelineVariant);
                            TextBlock name = single ? singleName : FindVisualChildren<TextBlock>(combo).Single(item => AutomationProperties.GetAutomationId(item) == "WorkbenchPipelineSelectedName");
                            if (!icon.IsVisible || icon.ActualWidth != 16D || icon.ActualHeight != 16D || name.Text != source.Name || name.ActualWidth <= 0D || name.TextTrimming != TextTrimming.CharacterEllipsis)
                                throw new InvalidOperationException("Pipeline selector icon/name is hidden, missing or not intentionally trimmed.");
                            AssertElementWithinAncestor("Pipeline selector icon", icon, selector);
                            AssertElementWithinAncestor("Pipeline selected name", name, selector);
                            if (new Rect(icon.TranslatePoint(new Point(), selector), new System.Windows.Size(icon.ActualWidth, icon.ActualHeight)).IntersectsWith(new Rect(name.TranslatePoint(new Point(), selector), new System.Windows.Size(name.ActualWidth, name.ActualHeight))))
                                throw new InvalidOperationException("Pipeline selector icon overlaps selected name.");
                            AssertBrushContrast(icon.Foreground, (Brush)host.FindResource(single ? "OpenVision.Workbench.PanelBrush" : "OpenVision.Workbench.PanelAltBrush"), "Pipeline selector icon " + theme);
                            if (state == "Popup")
                            {
                                AssertComboBoxPopupLayout(combo, "Pipeline selector icon popup");
                                combo.IsDropDownOpen = true; Pump(8);
                                Popup popup = (Popup)combo.Template.FindName("PART_Popup", combo);
                                if (FindVisualChildren<MahApps.Metro.IconPacks.PackIconMaterial>(popup.Child).Count(item => item.Kind == MahApps.Metro.IconPacks.PackIconMaterialKind.ChartTimelineVariant) != sources.Length)
                                    throw new InvalidOperationException("Pipeline selector popup lost its pipeline icons.");
                                ScreenshotPngWriter.WriteElementPng((FrameworkElement)popup.Child, Path.ChangeExtension(outputPath, "." + theme + ".popup.png"), (int)((FrameworkElement)popup.Child).ActualWidth, (int)((FrameworkElement)popup.Child).ActualHeight);
                                foreach (TextBlock popupName in FindVisualChildren<TextBlock>(popup.Child).Where(item => AutomationProperties.GetAutomationId(item) == "WorkbenchPipelineSelectedName"))
                                    AssertElementWithinAncestor("Pipeline popup name", popupName, (FrameworkElement)popup.Child);
                                foreach (ComboBoxItem popupItem in Enumerable.Range(0, combo.Items.Count).Select(index => (ComboBoxItem)combo.ItemContainerGenerator.ContainerFromIndex(index)))
                                {
                                    var popupIcon = FindVisualChildren<MahApps.Metro.IconPacks.PackIconMaterial>(popupItem).Single();
                                    Border itemChrome = (Border)popupItem.Template.FindName("itemChrome", popupItem);
                                    SolidColorBrush popupBackground = FindOpaqueVisualBackground(itemChrome) ?? throw new InvalidOperationException("Pipeline popup opaque background is absent.");
                                    if (itemChrome.Background is SolidColorBrush { Color.A: > 0 and < 255 } overlay)
                                    {
                                        double alpha = overlay.Color.A / 255D;
                                        popupBackground = new SolidColorBrush(System.Windows.Media.Color.FromRgb(
                                            (byte)Math.Round(overlay.Color.R * alpha + popupBackground.Color.R * (1 - alpha)),
                                            (byte)Math.Round(overlay.Color.G * alpha + popupBackground.Color.G * (1 - alpha)),
                                            (byte)Math.Round(overlay.Color.B * alpha + popupBackground.Color.B * (1 - alpha))));
                                    }
                                    File.AppendAllText(Path.ChangeExtension(outputPath, ".popup-brushes.log"), theme + " " + popupIcon.Foreground + " / " + itemChrome.Background + " / rendered " + popupBackground + Environment.NewLine);
                                    AssertBrushContrast(popupIcon.Foreground, popupBackground, "Pipeline popup icon " + theme);
                                    foreach (TextBlock popupName in FindVisualChildren<TextBlock>(popupItem)) AssertBrushContrast(popupName.Foreground, popupBackground, "Pipeline popup name " + theme);
                                }
                            }
                            if (host.NativePreviewRunCount != runs || host.LayerDocumentCount != layers || !working.SequenceEqual(VisionPipelineExecutionPlan.SerializePipeline(host.Workbench.Pipeline.WorkingCopyForTest)) || savedXml.Any(entry => !File.ReadAllBytes(RecipeWorkspaceService.GetVisionPipelinePath(recipeName, entry.Key)).SequenceEqual(entry.Value)))
                                throw new InvalidOperationException("Pipeline selector presentation caused execution, layer, working-copy or save mutation.");
                            string id = theme + "-" + width + "-" + language + "-" + (source == longName ? "Long" : "Short") + "-" + state;
                            string capture = Path.ChangeExtension(outputPath, "." + id + ".png");
                            ScreenshotPngWriter.WriteElementPng(host, capture, (int)host.ActualWidth, (int)host.ActualHeight);
                            cases.Add(new { Id = id, Status = "PASS", Source = source.Name, State = state, Icon = icon.Kind.ToString(), NameWidth = name.ActualWidth, runs, layers, Capture = capture, EvidenceKind = "in-process WPF; synthetic focus/disabled/popup and selection; no actual pointer/native DPI/HTML" });
                            File.WriteAllText(Path.ChangeExtension(outputPath, ".selector-cases.json"), JsonSerializer.Serialize(cases, new JsonSerializerOptions { WriteIndented = true }));
                        }
                        combo.IsDropDownOpen = false; combo.SetCurrentValue(UIElement.IsEnabledProperty, host.Workbench.Pipeline.CanEdit); Pump(8);
                    }
                }
                finally { combo.IsDropDownOpen = false; window.Resources.MergedDictionaries.Remove(palette); host.Resources.MergedDictionaries.Remove(palette); }
            }
        }, captureFloatingToolWindow: false);
    }

    private static CaptureResult CaptureWorkbenchPipelineMetadata(string outputPath)
    {
        OpenVisionLanguageService.SetLanguage(OpenVisionLanguage.Korean, false);
        string recipeName = "Smoke_Workbench_Metadata_" + Guid.NewGuid().ToString("N");
        OpenVisionShellHostView host = CreateShellHost(recipeName);
        VisionPipeline populated = CreatePipelineReviewInputStatePipeline();
        populated.Name = "Metadata_Populated";
        populated.Steps[1].InputLayer = populated.Steps[0].OutputLayer;
        foreach (VisionPipelineStep step in populated.Steps) { step.Enabled = true; step.UseAcceptance = true; }
        VisionPipeline empty = new() { Name = "Metadata_Empty" };
        foreach (VisionPipeline source in new[] { empty, populated }) VisionPipelineStorage.Save(recipeName, source);
        VisionPipelineStorage.SaveActivePipelineName(recipeName, empty.Name);
        host.RecipeCommands.RefreshOptions();
        host.RecipeCommands.SelectedPipelineOption = host.RecipeCommands.PipelineOptions.Single(option => option.PipelineName == empty.Name);
        return CaptureWindowWithContent(host, outputPath, 1920, 1032, () =>
        {
            Window window = Window.GetWindow(host);
            if (FindNamedVisualChild<WrapPanel>(host, "workbenchPipelineMeta") == null)
            {
                foreach (var boundary in new[] { (Width: 1920, Language: OpenVisionLanguage.English), (Width: 1280, Language: OpenVisionLanguage.Korean) })
                {
                    window.Width = boundary.Width; window.Height = boundary.Width == 1920 ? 1032 : 760;
                    OpenVisionLanguageService.SetLanguage(boundary.Language, false); Pump(8);
                    ScreenshotPngWriter.WriteElementPng(host, Path.ChangeExtension(outputPath, $".baseline-{boundary.Language}-{boundary.Width}.png"), (int)host.ActualWidth, (int)host.ActualHeight);
                }
                throw new InvalidOperationException("Baseline: canonical pipeline metadata chips and top empty card are absent.");
            }
            WrapPanel meta = FindNamedVisualChild<WrapPanel>(host, "workbenchPipelineMeta")!;
            Grid card = FindNamedVisualChild<Grid>(host, "workbenchPipelineEmptyCard")!;
            TextBlock title = FindNamedVisualChild<TextBlock>(host, "workbenchPipelineEmptyTitle")!;
            TextBlock detail = FindNamedVisualChild<TextBlock>(host, "workbenchPipelineEmptyDetail")!;
            var outline = FindNamedVisualChild<System.Windows.Shapes.Rectangle>(host, "workbenchPipelineEmptyOutline")!;
            Border[] chips = new[] { "workbenchPipelineInputChip", "workbenchPipelineStepChip", "workbenchPipelineJudgedChip" }.Select(name => FindNamedVisualChild<Border>(host, name)!).ToArray();
            TextBlock[] values = new[] { "workbenchPipelineInputText", "workbenchPipelineStepText", "workbenchPipelineJudgedText" }.Select(name => FindNamedVisualChild<TextBlock>(host, name)!).ToArray();
            int runs = host.NativePreviewRunCount, layers = host.LayerDocumentCount;
            Dictionary<string, byte[]> savedXml = new[] { empty, populated }.ToDictionary(source => source.Name, source => File.ReadAllBytes(RecipeWorkspaceService.GetVisionPipelinePath(recipeName, source.Name)));
            List<object> cases = new();
            foreach (string theme in new[] { "Dark", "Light" })
            {
                ResourceDictionary palette = new() { Source = new Uri($"pack://application:,,,/OpenVisionLab;component/UI/Wpf/OpenVisionWorkbench{theme}.xaml") };
                host.Resources.MergedDictionaries.Add(palette);
                try
                {
                    foreach (VisionPipeline source in new[] { empty, populated })
                    {
                        host.RecipeCommands.SelectedPipelineOption = host.RecipeCommands.PipelineOptions.Single(option => option.PipelineName == source.Name); Pump(8);
                        byte[] workingCopy = VisionPipelineExecutionPlan.SerializePipeline(host.Workbench.Pipeline.WorkingCopyForTest);
                        foreach (int width in new[] { 1920, 1280 })
                        foreach (OpenVisionLanguage language in new[] { OpenVisionLanguage.Korean, OpenVisionLanguage.English })
                        {
                            window.Width = width; window.Height = width == 1920 ? 1032 : 760;
                            OpenVisionLanguageService.SetLanguage(language, false); Pump(8);
                            string[] expected = { OpenVisionLanguageService.T("Workbench.Pipeline.Input"), string.Format(OpenVisionLanguageService.T("Workbench.Pipeline.StepCountFormat"), source.Steps.Count), string.Format(OpenVisionLanguageService.T("Workbench.Pipeline.JudgedCountFormat"), source.Steps.Count) };
                            for (int index = 0; index < chips.Length; index++)
                            {
                                if (values[index].Text != expected[index] || chips[index].ActualHeight != 20D || chips[index].CornerRadius.TopLeft != 10D || values[index].FontSize != 11D)
                                    throw new InvalidOperationException("Pipeline metadata lost its localized values or canonical chip dimensions.");
                                AssertElementWithinAncestor("Pipeline metadata chip", chips[index], meta);
                                AssertElementWithinAncestor("Pipeline metadata value", values[index], chips[index]);
                                AssertBrushContrast(values[index].Foreground, (Brush)host.FindResource("OpenVision.Workbench.PanelBrush"), "Pipeline metadata " + theme);
                            }
                            var chipBounds = chips.Select(chip => new Rect(chip.TranslatePoint(new Point(), meta), new System.Windows.Size(chip.ActualWidth, chip.ActualHeight))).ToArray();
                            for (int index = 1; index < chipBounds.Length; index++)
                                if (chipBounds[index].IntersectsWith(chipBounds[index - 1])) throw new InvalidOperationException("Pipeline metadata chips overlap after wrapping.");
                            if (card.IsVisible != (source.Steps.Count == 0) || host.Workbench.Pipeline.Rows.Count != source.Steps.Count)
                                throw new InvalidOperationException("Pipeline empty card did not follow the selected working copy.");
                            if (card.IsVisible)
                            {
                                AssertElementWithinAncestor("Pipeline empty card", card, (FrameworkElement)card.Parent);
                                foreach (TextBlock text in new[] { title, detail }) AssertElementWithinAncestor("Pipeline empty text", text, card);
                                if (title.Text != OpenVisionLanguageService.T("Workbench.Pipeline.Empty") || detail.Text != OpenVisionLanguageService.T("Workbench.Pipeline.EmptyDetail")
                                    || card.VerticalAlignment != VerticalAlignment.Top || card.TranslatePoint(new Point(), (UIElement)card.Parent).Y != 14D
                                    || outline.StrokeDashArray.Count != 2 || title.FontSize != 12.5D || detail.TextWrapping != TextWrapping.Wrap)
                                    throw new InvalidOperationException("Pipeline empty card lost its localized top-aligned dashed presentation.");
                                foreach (TextBlock text in new[] { title, detail }) AssertBrushContrast(text.Foreground, (Brush)host.FindResource("OpenVision.Workbench.PanelBrush"), "Pipeline empty " + theme);
                            }
                            if (host.NativePreviewRunCount != runs || host.LayerDocumentCount != layers || !VisionPipelineExecutionPlan.SerializePipeline(host.Workbench.Pipeline.WorkingCopyForTest).SequenceEqual(workingCopy)
                                || savedXml.Any(entry => !File.ReadAllBytes(RecipeWorkspaceService.GetVisionPipelinePath(recipeName, entry.Key)).SequenceEqual(entry.Value)))
                                throw new InvalidOperationException("Pipeline metadata display changed execution, layers, working copy or saved recipe.");
                            string id = theme + "-" + source.Name + "-" + language + "-" + width;
                            string capture = Path.ChangeExtension(outputPath, "." + id + ".png");
                            ScreenshotPngWriter.WriteElementPng(host, capture, (int)host.ActualWidth, (int)host.ActualHeight);
                            cases.Add(new { Id = id, Status = "PASS", Width = host.ActualWidth, Height = host.ActualHeight, Values = values.Select(value => value.Text).ToArray(), ChipBounds = chipBounds.Select(bounds => bounds.ToString()).ToArray(), MetaHeight = meta.ActualHeight, EmptyVisible = card.IsVisible, runs, layers, Capture = capture, EvidenceKind = "in-process WPF; live resources and selected test pipeline; no actual input/native DPI/HTML" });
                            File.WriteAllText(Path.ChangeExtension(outputPath, ".metadata-cases.json"), JsonSerializer.Serialize(cases, new JsonSerializerOptions { WriteIndented = true }));
                        }
                    }
                }
                finally { host.Resources.MergedDictionaries.Remove(palette); }
            }
            host.RecipeCommands.SelectedPipelineOption = host.RecipeCommands.PipelineOptions.Single(option => option.PipelineName == empty.Name);
            OpenVisionLanguageService.SetLanguage(OpenVisionLanguage.Korean, false); Pump(8);
            if (!card.IsVisible || host.Workbench.Pipeline.Rows.Count != 0 || host.NativePreviewRunCount != runs || host.LayerDocumentCount != layers)
                throw new InvalidOperationException("Pipeline empty state did not recover without execution after the populated state.");
        }, captureFloatingToolWindow: false);
    }

    private static CaptureResult CaptureWorkbenchPipelinePresentation(string outputPath)
    {
        OpenVisionLanguageService.SetLanguage(OpenVisionLanguage.Korean, false);
        string recipeName = "Smoke_Workbench_Presentation_" + Guid.NewGuid().ToString("N");
        OpenVisionShellHostView host = CreateShellHost(recipeName);
        VisionPipeline source = CreatePipelineReviewInputStatePipeline();
        source.Steps[1].InputLayer = source.Steps[0].OutputLayer;
        VisionPipelineStorage.Save(recipeName, source);
        VisionPipelineStorage.SaveActivePipelineName(recipeName, source.Name);
        host.RecipeCommands.RefreshOptions();
        host.RecipeCommands.SelectedPipelineOption = host.RecipeCommands.PipelineOptions.Single(option => option.PipelineName == source.Name);
        return CaptureWindowWithContent(host, outputPath, 1920, 1032, () =>
        {
            Window window = Window.GetWindow(host);
            Button add = FindNamedVisualChild<Button>(host, "workbenchPipelineAddTool")!;
            TextBlock caption = FindNamedVisualChild<TextBlock>(host, "workbenchPipelineAddToolCaption")!;
            FrameworkElement panel = FindVisualChildren<FrameworkElement>(host).Single(item => AutomationProperties.GetAutomationId(item) == "WorkbenchPipelinePanel");
            TextBlock title = FindVisualChildren<TextBlock>(panel).Single(item => AutomationProperties.GetAutomationId(item) == "WorkbenchPipelineTitle");
            byte[] workingCopy = VisionPipelineExecutionPlan.SerializePipeline(host.Workbench.Pipeline.WorkingCopyForTest);
            int runs = host.NativePreviewRunCount, layers = host.LayerDocumentCount;
            List<object> cases = new();
            foreach (string theme in new[] { "Dark", "Light" })
            {
                ResourceDictionary palette = new() { Source = new Uri($"pack://application:,,,/OpenVisionLab;component/UI/Wpf/OpenVisionWorkbench{theme}.xaml") };
                host.Resources.MergedDictionaries.Add(palette);
                try
                {
                    foreach (int width in new[] { 1920, 1280 })
                    foreach (OpenVisionLanguage language in new[] { OpenVisionLanguage.Korean, OpenVisionLanguage.English })
                    {
                        window.Width = width; window.Height = width == 1920 ? 1032 : 760;
                        OpenVisionLanguageService.SetLanguage(language, false); Pump(8);
                        bool expectedCaption = width > 1360;
                        if (caption.IsVisible != expectedCaption || caption.Text != OpenVisionLanguageService.T("Workbench.Pipeline.AddTool")
                            || !ReferenceEquals(add.Command, host.Workbench.FocusToolPaletteCommand) || !add.IsEnabled)
                            throw new InvalidOperationException("Pipeline Add Tool lost its canonical caption, responsive visibility or existing command.");
                        AssertElementWithinAncestor("Pipeline Add Tool", add, panel);
                        if (expectedCaption) AssertElementWithinAncestor("Pipeline Add Tool caption", caption, add);
                        if (add.TranslatePoint(new Point(), panel).X < title.TranslatePoint(new Point(), panel).X + title.ActualWidth - 1D)
                            throw new InvalidOperationException("Pipeline Add Tool overlaps the pipeline title.");
                        host.Workbench.IsToolPaletteCollapsed = true;
                        add.Command.Execute(add.CommandParameter); Pump(4);
                        if (host.Workbench.IsToolPaletteCollapsed || !add.Focus()) throw new InvalidOperationException("Pipeline Add Tool cannot reopen the existing palette or receive focus.");
                        Pump(3);
                        Border chrome = FindVisualChildren<Border>(add).Single(item => item.Name == "buttonChrome");
                        double contrast = GetContrastRatio(((SolidColorBrush)add.Foreground).Color, ((SolidColorBrush)chrome.Background).Color);
                        if (contrast < 4.5D) throw new InvalidOperationException("Pipeline Add Tool caption is unreadable in the live palette.");
                        AssertWorkbenchVerdictPresentation(host);
                        if (host.NativePreviewRunCount != runs || host.LayerDocumentCount != layers
                            || !VisionPipelineExecutionPlan.SerializePipeline(host.Workbench.Pipeline.WorkingCopyForTest).SequenceEqual(workingCopy))
                            throw new InvalidOperationException("Pipeline presentation/focus changed execution, layers or working copy.");
                        string id = theme + "-" + language + "-" + width;
                        string capture = Path.ChangeExtension(outputPath, "." + id + ".png");
                        ScreenshotPngWriter.WriteElementPng(host, capture, (int)host.ActualWidth, (int)host.ActualHeight);
                        cases.Add(new { Id = id, Status = "PASS", Width = host.ActualWidth, Height = host.ActualHeight, Caption = caption.Text, Visible = caption.IsVisible, add.IsKeyboardFocused, Contrast = contrast, runs, layers, Capture = capture, EvidenceKind = "in-process WPF; programmatic command/focus; no actual pointer/native DPI/HTML" });
                        File.WriteAllText(Path.ChangeExtension(outputPath, ".presentation-cases.json"), JsonSerializer.Serialize(cases, new JsonSerializerOptions { WriteIndented = true }));
                    }
                }
                finally { host.Resources.MergedDictionaries.Remove(palette); }
            }
            OpenVisionLanguageService.SetLanguage(OpenVisionLanguage.Korean, false);
        }, captureFloatingToolWindow: false);
    }

    private static void AssertWorkbenchVerdictPresentation(OpenVisionShellHostView host)
    {
        Grid content = FindNamedVisualChild<Grid>(host, "workbenchVerdictContent")!;
        TextBlock value = FindNamedVisualChild<TextBlock>(host, "workbenchVerdictValue")!;
        TextBlock title = FindNamedVisualChild<TextBlock>(host, "workbenchVerdictTitle")!;
        TextBlock detail = FindNamedVisualChild<TextBlock>(host, "workbenchVerdictDetail")!;
        Pump(4);
        foreach (TextBlock text in new[] { value, title, detail }) AssertElementWithinAncestor("Final verdict " + text.Name, text, content);
        if (value.Text != host.Workbench.Pipeline.VerdictValue || detail.Text != host.Workbench.Pipeline.VerdictDetail
            || title.Text != OpenVisionLanguageService.T("Workbench.Verdict.Title") || value.FontSize != 17D || value.MinWidth != 34D
            || title.TranslatePoint(new Point(), content).X < value.TranslatePoint(new Point(), content).X + value.ActualWidth)
            throw new InvalidOperationException("Final verdict lost its live values or canonical horizontal value/title layout.");
        Border card = (Border)content.Parent;
        foreach (TextBlock text in new[] { title, detail })
            if (GetContrastRatio(((SolidColorBrush)text.Foreground).Color, ((SolidColorBrush)card.Background).Color) < 4.5D)
                throw new InvalidOperationException("Final verdict caption/detail is unreadable in the live palette.");
        AssertMainStatusVerdict(host);
    }

    private static void AssertMainStatusVerdict(OpenVisionShellHostView host)
    {
        Grid footer = FindVisualChildren<Grid>(host).Single(item => AutomationProperties.GetAutomationId(item) == "WorkbenchStatusBar");
        StackPanel verdict = FindVisualChildren<StackPanel>(footer).Single(item => AutomationProperties.GetAutomationId(item) == "WorkbenchStatusVerdict");
        TextBlock value = FindVisualChildren<TextBlock>(verdict).Single(item => AutomationProperties.GetAutomationId(item) == "WorkbenchStatusVerdictValue");
        TextBlock previous = FindVisualChildren<TextBlock>(verdict).Single(item => AutomationProperties.GetAutomationId(item) == "WorkbenchStatusVerdictPrevious");
        TextBlock dirty = FindVisualChildren<TextBlock>(footer).Single(item => AutomationProperties.GetAutomationId(item) == "WorkbenchStatusRecipeDirty");
        OpenVisionWorkbenchPipelineViewModel model = host.Workbench.Pipeline;
        string expected = model.VerdictValue == "—" ? OpenVisionLanguageService.T("Workbench.Status.NoVerdict") : model.VerdictValue;
        bool isDirty = host.RecipeCommands.IsSelectedStepEditDirty || host.RecipeCommands.IsWorkbenchPipelineDirty;
        Pump(4);
        if (value.Text != expected || previous.IsVisible != model.IsVerdictPrevious || dirty.IsVisible != isDirty
            || Convert.ToString(value.ToolTip) != model.VerdictDetail || (dirty.IsVisible && dirty.Text != OpenVisionLanguageService.T("Workbench.Tool.BadgeChanged")))
            throw new InvalidOperationException("Main status verdict/previous/dirty display diverged from existing owner state.");
        AssertElementWithinAncestor("Main status verdict", verdict, footer);
        foreach (TextBlock label in new[] { value, previous, dirty }.Where(label => label.IsVisible))
        {
            AssertElementWithinAncestor("Main status " + AutomationProperties.GetAutomationId(label), label, footer);
            double textWidth = new FormattedText(label.Text, System.Globalization.CultureInfo.CurrentCulture, FlowDirection.LeftToRight,
                new Typeface(label.FontFamily, label.FontStyle, label.FontWeight, label.FontStretch), label.FontSize, label.Foreground, VisualTreeHelper.GetDpi(label).PixelsPerDip).Width;
            if (Math.Round(label.ActualWidth, 6) < Math.Round(textWidth, 6)
                || GetContrastRatio(((SolidColorBrush)label.Foreground).Color, ((SolidColorBrush)footer.Background).Color) < 3D)
                throw new InvalidOperationException("Main status verdict/dirty caption clipped or lost semantic contrast.");
        }
        string colorKey = model.VerdictKind switch { "Ok" => "Ok", "Ng" => "Ng", "Error" => "Error", "Done" => "Done", "Previous" => "Skip", _ => "SecondaryText" };
        if (((SolidColorBrush)value.Foreground).Color != ((SolidColorBrush)host.FindResource("OpenVision.Workbench." + colorKey + "Brush")).Color)
            throw new InvalidOperationException("Main status verdict semantic brush disagrees with existing result kind.");
    }

    private static CaptureResult CaptureWorkbenchPipelineEditing(string outputPath, bool compact)
    {
        OpenVisionLanguageService.SetLanguage(OpenVisionLanguage.Korean, false);
        string recipeName = "Smoke_Workbench_Editing_" + Guid.NewGuid().ToString("N");
        OpenVisionShellHostView host = CreateShellHost(recipeName);
        VisionPipeline source = CreatePipelineReviewInputStatePipeline();
        source.Steps[1].InputLayer = source.Steps[0].OutputLayer;
        VisionPipelineStorage.Save(recipeName, source);
        VisionPipelineStorage.SaveActivePipelineName(recipeName, source.Name);
        host.RecipeCommands.RefreshOptions();
        host.RecipeCommands.SelectedPipelineOption = host.RecipeCommands.PipelineOptions.Single(option => option.PipelineName == source.Name);
        return CaptureWindowWithContent(host, outputPath, compact ? 1280 : 1920, compact ? 760 : 1032, () =>
        {
            OpenVisionWorkbenchPipelineViewModel model = host.Workbench.Pipeline;
            string path = RecipeWorkspaceService.GetVisionPipelinePath(recipeName, source.Name);
            byte[] originalXml = File.ReadAllBytes(path);
            ListBox list = FindVisualChildren<ListBox>(host).Single(item => AutomationProperties.GetAutomationId(item) == "WorkbenchPipelineSteps");
            byte[] beforeSelection = VisionPipelineExecutionPlan.SerializePipeline(model.WorkingCopyForTest);
            int selectionRuns = host.NativePreviewRunCount;
            int selectionLayers = host.LayerDocumentCount;
            var selectionDiagnostics = new List<object>();
            void RecordSelection(string phase)
            {
                byte[] xml = File.ReadAllBytes(path);
                byte[] workingCopy = VisionPipelineExecutionPlan.SerializePipeline(model.WorkingCopyForTest);
                selectionDiagnostics.Add(new
                {
                    Phase = phase, model.SelectedStepIndex, AutoRunEnabled = host.Workbench.Tool.IsAutoRunEnabled, NativeRuns = host.NativePreviewRunCount, Layers = host.LayerDocumentCount,
                    XmlUnchanged = xml.SequenceEqual(originalXml), WorkingCopyUnchanged = workingCopy.SequenceEqual(beforeSelection),
                    Xml = Convert.ToBase64String(xml), WorkingCopy = Convert.ToBase64String(workingCopy)
                });
            }
            RecordSelection("Before");
            Border SelectedStepRow() => FindVisualChildren<Border>(list).Single(item => item.Name == "stepRow"
                && item.DataContext is OpenVisionWorkbenchStepViewModel selected && selected.Index == model.SelectedStepIndex);
            void ClickSelectedStep(bool handled = false)
            {
                SelectedStepRow().RaiseEvent(new MouseButtonEventArgs(Mouse.PrimaryDevice, Environment.TickCount, MouseButton.Left)
                    { RoutedEvent = UIElement.MouseLeftButtonUpEvent, Handled = handled });
                Pump(8);
                RecordSelection("AfterRowClick handled=" + handled);
            }
            if (model.SelectedStepIndex != 0) { throw new InvalidOperationException("Reopened pipeline must retain its first selection before the row click."); }
            ClickSelectedStep();
            FrameworkElement selectedView = host.ActiveNativeDocumentForTest?.View;
            if (!host.Workbench.Tool.IsStepEditing || host.Workbench.Tool.ToolName != source.Steps[0].ToolType || selectedView == null
                || !host.IsDockedToolCloseButtonVisibleForTest)
                throw new InvalidOperationException("Clicking the already selected first row must open its native step editor.");
            ClickSelectedStep();
            if (!ReferenceEquals(selectedView, host.ActiveNativeDocumentForTest?.View))
                throw new InvalidOperationException("Repeated row selection must reuse the existing native view.");
            host.CloseActiveWpfToolWindowForTest();
            Pump(4);
            ClickSelectedStep(true);
            if (host.IsDockedToolCloseButtonVisibleForTest)
                throw new InvalidOperationException("A child control's handled mouse-up must not reopen the row tool.");
            ClickSelectedStep();
            if (!host.IsDockedToolCloseButtonVisibleForTest || !ReferenceEquals(selectedView, host.ActiveNativeDocumentForTest?.View))
                throw new InvalidOperationException("The same row must reopen its cached editor after close.");
            host.SelectToolForTest(VISION_MENU.Filter);
            Pump(6);
            if (!host.Workbench.Tool.IsNewTest) { throw new InvalidOperationException("Tool selection must enter test mode before step reselect."); }
            ClickSelectedStep();
            if (!host.Workbench.Tool.IsStepEditing || host.Workbench.Tool.ToolName != source.Steps[0].ToolType)
                throw new InvalidOperationException("The same row must return from test mode to step editing.");
            model.RenameCommand.Execute(null);
            ClickSelectedStep();
            if (!model.IsRenaming || model.SelectStepCommand.CanExecute(model.SelectedStepIndex))
                throw new InvalidOperationException("Row reselect must leave inline name editing active.");
            model.CancelRenameCommand.Execute(null);
            foreach (int invalidIndex in new[] { -1, model.Rows.Count })
            {
                if (model.SelectStepCommand.CanExecute(invalidIndex)) { throw new InvalidOperationException("An invalid row must reject selection."); }
                model.SelectStepCommand.Execute(invalidIndex);
            }
            RecordSelection("After");
            File.WriteAllText(Path.ChangeExtension(outputPath, ".selection-state.json"), System.Text.Json.JsonSerializer.Serialize(new
            {
                Product = typeof(OpenVisionShellHostView).Assembly.Location, ExpectedIndex = 0, ExpectedRuns = selectionRuns,
                ExpectedLayers = selectionLayers, States = selectionDiagnostics
            }, new System.Text.Json.JsonSerializerOptions { WriteIndented = true }));
            if (model.SelectedStepIndex != 0 || !File.ReadAllBytes(path).SequenceEqual(originalXml)
                || !VisionPipelineExecutionPlan.SerializePipeline(model.WorkingCopyForTest).SequenceEqual(beforeSelection)
                || host.NativePreviewRunCount != selectionRuns || host.LayerDocumentCount != selectionLayers)
                throw new InvalidOperationException("Row selection/reopen must preserve selection, XML, working copy, execution and layers.");
            list.SelectedIndex = 1;
            Pump(8);
            Border row = FindVisualChildren<Border>(list).Single(item => item.Name == "stepRow"
                && item.DataContext is OpenVisionWorkbenchStepViewModel selected && selected.Index == model.SelectedStepIndex);
            ContextMenu stepMenu = row.ContextMenu;
            Button stepMenuButton = FindVisualChildren<Button>(row).Single(item => ReferenceEquals(item.ContextMenu, stepMenu));
            int menuRuns = host.NativePreviewRunCount;
            int menuLayers = host.LayerDocumentCount;
            byte[] beforeMenuXml = VisionPipelineExecutionPlan.SerializePipeline(model.WorkingCopyForTest);
            foreach (string theme in new[] { "Dark", "Light" })
            {
                ResourceDictionary palette = new() { Source = new Uri($"pack://application:,,,/OpenVisionLab;component/UI/Wpf/OpenVisionWorkbench{theme}.xaml") };
                host.Resources.MergedDictionaries.Add(palette);
                try
                {
                    foreach (OpenVisionLanguage language in new[] { OpenVisionLanguage.Korean, OpenVisionLanguage.English })
                    {
                        OpenVisionLanguageService.SetLanguage(language, false);
                        stepMenuButton.RaiseEvent(new RoutedEventArgs(Button.ClickEvent));
                        try
                        {
                            AssertWorkbenchMenuPopup(stepMenu, outputPath);
                            if (!ReferenceEquals(stepMenu.DataContext, model)
                                || stepMenu.Items.OfType<MenuItem>().Any(item => string.IsNullOrWhiteSpace(item.Header?.ToString())))
                                throw new InvalidOperationException("Step menu button lost its owner, translated captions or command context.");
                        }
                        finally { stepMenu.IsOpen = false; }
                        foreach (Menu visibleMenu in FindVisualChildren<Menu>(host).Where(item => item.IsVisible))
                        {
                            foreach (MenuItem header in visibleMenu.Items.OfType<MenuItem>())
                            {
                                if (header.Items.Count == 0) { continue; }
                                header.IsSubmenuOpen = true;
                                try
                                {
                                    AssertWorkbenchMenuPopup(header, outputPath);
                                    string separatorPath = Path.ChangeExtension(outputPath, $".{theme}.{language}.png");
                                    if (header.Name == "mainPaneMenu" && !File.Exists(Path.ChangeExtension(separatorPath, ".separator-state.png")))
                                        WriteSeparatorEvidence(header.Items.OfType<Separator>().First(), separatorPath);
                                }
                                finally { header.IsSubmenuOpen = false; }
                            }
                        }
                        if (!File.ReadAllBytes(path).SequenceEqual(originalXml)
                            || !VisionPipelineExecutionPlan.SerializePipeline(model.WorkingCopyForTest).SequenceEqual(beforeMenuXml)
                            || host.NativePreviewRunCount != menuRuns || host.LayerDocumentCount != menuLayers)
                            throw new InvalidOperationException("Opening/closing a step popup changed XML, working copy, execution or layers.");
                    }
                }
                finally { host.Resources.MergedDictionaries.Remove(palette); }
            }
            OpenVisionLanguageService.SetLanguage(OpenVisionLanguage.Korean, false);
            model.RenameCommand.Execute(null);
            Pump(8);
            TextBox editor = FindVisualChildren<TextBox>(host).Single(item => item.IsVisible && AutomationProperties.GetAutomationId(item) == "WorkbenchStepRenameEditor");
            const string newName = "검사 영역의 긴 이름 0123456789 ABCDEFGHIJKLMNOPQRSTUVWXYZ";
            editor.Text = newName;
            editor.GetBindingExpression(TextBox.TextProperty).UpdateSource();
            model.CommitRenameCommand.Execute(null);
            Pump(8);
            if (!model.IsDirty || model.SelectedRow?.Index != 1 || model.SelectedRow.Name != newName
                || model.Rows[0].IsDirty || !model.Rows[1].IsDirty || !File.ReadAllBytes(path).SequenceEqual(originalXml))
            {
                throw new InvalidOperationException("Inline edit must update the working copy, retain selection, mark only changed rows, and leave XML intact.");
            }

            if (list.SelectedItem is not OpenVisionWorkbenchStepViewModel boundRow || boundRow.Index != model.SelectedRow.Index)
            {
                throw new InvalidOperationException("Edited selection must render back into the ListBox.");
            }
            TextBlock stepName = FindNamedVisualChild<TextBlock>(SelectedStepRow(), "workbenchStepName")!;
            if (stepName.Text != newName || stepName.ToolTip?.ToString() != newName || stepName.TextWrapping != TextWrapping.NoWrap
                || stepName.TextTrimming != TextTrimming.CharacterEllipsis || stepName.ActualHeight > 20D)
                throw new InvalidOperationException("Long step name must remain one line with its complete name available, without changing the stored value.");
            AssertElementWithinAncestor("Long step name", stepName, SelectedStepRow());
            model.MoveUpCommand.Execute(null);
            Pump(8);
            if (model.ValidationSucceeded || model.RunCommand.CanExecute(null) || !model.Rows[0].HasError || model.SelectedRow?.Index != 0)
            {
                throw new InvalidOperationException("Move must retain selected row and expose broken references without repairing them.");
            }
            model.UndoCommand.Execute(null);
            Pump(8);
            if (!model.ValidationSucceeded || model.SelectedRow?.Index != 1) { throw new InvalidOperationException("Undo must restore ordering and selection."); }
            model.DuplicateCommand.Execute(null);
            Pump(8);
            if (model.ValidationSucceeded || !model.Rows[2].HasError) { throw new InvalidOperationException("Duplicate output names must block run."); }
            model.UndoCommand.Execute(null);
            model.ToggleEnabledCommand.Execute(null);
            Pump(8);
            if (model.Rows[1].IsEnabled || model.Rows[1].StatusText != OpenVisionLanguageService.T("Workbench.Status.Disabled")) { throw new InvalidOperationException("Disabled row must remain identifiable."); }
            model.UndoCommand.Execute(null);
            host.QueuePendingRecipeEditDecisionForTest(OpenVisionRecipePendingEditDecision.Cancel);
            model.DeleteCommand.Execute(null);
            if (model.Rows.Count != 2 || model.SelectedRow?.Index != 1) { throw new InvalidOperationException("Cancel deletion must retain rows and selection."); }
            host.QueuePendingRecipeEditDecisionForTest(OpenVisionRecipePendingEditDecision.ApplyAndContinue);
            model.DeleteCommand.Execute(null);
            Pump(8);
            if (model.Rows.Count != 1 || model.SelectedRow?.Index != 0 || list.SelectedIndex != 0) { throw new InvalidOperationException($"Deletion must select the remaining row through the binding. Rows={model.Rows.Count}, VM={model.SelectedRow?.Index}, View={list.SelectedIndex}, Items={list.Items.Count}, Loaded={list.IsLoaded}, Binding={list.GetBindingExpression(ListBox.SelectedItemProperty)?.Status}, Context={ReferenceEquals(list.DataContext, model)}, SameRow={list.Items.Contains(model.SelectedRow)}."); }
            model.UndoCommand.Execute(null);
            Pump(8);
            if (model.Rows.Count != 2 || model.SelectedRow?.Index != 1 || list.SelectedIndex != 1) { throw new InvalidOperationException("Undo deletion must restore rows and visible selection."); }
            host.FailNextRecipeStepSaveForTest();
            host.RecipeCommands.SaveRecipeCommand.Execute(null);
            Pump(8);
            if (!model.IsDirty || !File.ReadAllBytes(path).SequenceEqual(originalXml)) { throw new InvalidOperationException("Failed save must preserve pending working copy and original XML."); }
            host.FailNextRecipeStepRoundTripValidationForTest();
            host.RecipeCommands.SaveRecipeCommand.Execute(null);
            Pump(8);
            if (!model.IsDirty || !File.ReadAllBytes(path).SequenceEqual(originalXml)) { throw new InvalidOperationException("Failed round trip must restore original XML and retain working copy."); }
            host.RecipeCommands.SaveRecipeCommand.Execute(null);
            Pump(8);
            VisionPipeline loaded = VisionPipelineStorage.Load(recipeName, source.Name);
            if (model.IsDirty || model.Rows.Any(row => row.IsDirty) || loaded.Steps[1].Name != newName || !VisionPipelineStorage.TryValidateRoundTrip(recipeName, loaded, out _)
                || model.ResultCountForTest != 0 || host.NativePreviewRunCount != 0)
            {
                throw new InvalidOperationException("Explicit save/reload must preserve the edited XML and execute nothing.");
            }
            if (list.SelectedItem is not OpenVisionWorkbenchStepViewModel savedRow || savedRow.Index != model.SelectedRow.Index)
            {
                throw new InvalidOperationException($"Explicit save must retain visible selection. VM={model.SelectedRow?.Index}, View={list.SelectedIndex}, Item={(list.SelectedItem as OpenVisionWorkbenchStepViewModel)?.Index}, Type={list.SelectedItem?.GetType().FullName}, Items={list.Items.Count}, Binding={list.GetBindingExpression(ListBox.SelectedIndexProperty)?.Status}, Context={ReferenceEquals(list.DataContext, model)}, SameRow={list.Items.Contains(model.SelectedRow)}.");
            }

            VisionPipeline routing = VisionPipelineStepEditService.Copy(source);
            routing.Steps[1] = VisionPipelineStepBuilder.FromProperty(new BlobProperty { NAME = "블롭", USE_ROI = false }, "Main", "Blob_Output");
            VisionPipelineStorage.Save(recipeName, routing);
            host.RecipeCommands.RefreshOptions();
            Pump(8);
            if (!model.ValidationSucceeded || model.Rows[1].InputLayer != routing.Steps[0].OutputLayer || model.Rows[1].IsBranch
                || model.WorkingCopyForTest.Steps[1].InputLayer != "Main"
                || !VisionPipelineExecutionPlan.SerializePipeline(model.WorkingCopyForTest).SequenceEqual(VisionPipelineExecutionPlan.SerializePipeline(routing)))
            {
                throw new InvalidOperationException("Legacy effective sequential links must display without modifying the raw working copy.");
            }
            routing.Steps[1].Parameters[VisionPipelineNormalizer.AllowBranchInputParameter] = "true";
            VisionPipelineStorage.Save(recipeName, routing);
            host.RecipeCommands.RefreshOptions();
            Pump(8);
            if (!model.ValidationSucceeded || model.Rows[1].InputLayer != "Main" || !model.Rows[1].IsBranch
                || model.ResultCountForTest != 0 || host.NativePreviewRunCount != 0)
            {
                throw new InvalidOperationException("Explicit ALLOW_BRANCH_INPUT must retain the Main branch without execution.");
            }
            VisionPipelineStorage.Save(recipeName, loaded);
            host.RecipeCommands.RefreshOptions();
            list.SelectedIndex = 1;
            Pump(8);
            host.Workbench.IsToolPaletteCollapsed = true;
            byte[] beforeLanguageXml = VisionPipelineExecutionPlan.SerializePipeline(model.WorkingCopyForTest);
            OpenVisionLanguageService.SetLanguage(OpenVisionLanguage.English, false);
            Pump(8);
            if (model.Rows[0].ToolName != "Threshold" || model.Rows[1].ToolName != "Filter"
                || model.SelectedRow?.Index != 1 || model.ResultCountForTest != 0 || host.NativePreviewRunCount != 0
                || !VisionPipelineExecutionPlan.SerializePipeline(model.WorkingCopyForTest).SequenceEqual(beforeLanguageXml))
            {
                throw new InvalidOperationException("Workbench tool labels must refresh in English without changing selection, XML, or execution.");
            }
            OpenVisionLanguageService.SetLanguage(OpenVisionLanguage.Korean, false);
            Pump(8);
            if (model.Rows[0].ToolName != "이진화" || model.Rows[1].ToolName != "필터")
            {
                throw new InvalidOperationException("Workbench tool labels must restore in Korean.");
            }
            AssertVisibleTextDoesNotContain(host, "Workbench pipeline editing", "Workbench.", "PipelineReview.");
        }, captureFloatingToolWindow: false);
    }

    private static CaptureResult CaptureWorkbenchPipelineValidation(string outputPath)
    {
        OpenVisionLanguageService.SetLanguage(OpenVisionLanguage.Korean, false);
        string recipeName = "Smoke_Workbench_Validation_" + Guid.NewGuid().ToString("N");
        OpenVisionShellHostView host = CreateShellHost(recipeName);
        VisionPipeline baseline = CreatePipelineReviewInputStatePipeline();
        baseline.Steps[1].InputLayer = baseline.Steps[0].OutputLayer;
        VisionPipelineStorage.Save(recipeName, baseline);
        VisionPipelineStorage.SaveActivePipelineName(recipeName, baseline.Name);
        host.RecipeCommands.RefreshOptions();
        host.RecipeCommands.SelectedPipelineOption = host.RecipeCommands.PipelineOptions.Single(option => option.PipelineName == baseline.Name);
        return CaptureWindowWithContent(host, outputPath, 1920, 1032, () =>
        {
            OpenVisionWorkbenchPipelineViewModel model = host.Workbench.Pipeline;
            Button run = FindVisualChildren<Button>(host).Single(item => AutomationProperties.GetAutomationId(item) == "WorkbenchRunPipeline");
            (string Id, Action<VisionPipeline> Mutate, string Korean, string English)[] cases =
            {
                ("empty-name", pipeline => pipeline.Steps[0].Name = "", "단계 이름이 없습니다.", "Name is required."),
                ("unsupported-tool", pipeline => pipeline.Steps[0].ToolType = "UnsupportedType", "파이프라인에서 쓸 수 없는 툴입니다.", "This tool cannot run in a pipeline."),
                ("invalid-integer", pipeline => pipeline.Steps[0].Parameters["NUM_MATCH"] = "bad", "정수가 필요합니다.", "expects an integer value."),
                ("invalid-numeric", pipeline => pipeline.Steps[0].Parameters["Threshold"] = "bad", "숫자가 필요합니다.", "expects a numeric value."),
                ("invalid-boolean", pipeline => pipeline.Steps[0].Parameters["USE_ROI"] = "bad", "True 또는 False", "expects True or False."),
                ("min-max", pipeline => { pipeline.Steps[0].Parameters["RangeMin"] = "180"; pipeline.Steps[0].Parameters["RangeMax"] = "40"; }, "RangeMin가 RangeMax보다 큽니다.", "RangeMin is greater than RangeMax."),
                ("acceptance-range", pipeline => { pipeline.Steps[0].UseAcceptance = true; pipeline.Steps[0].UseAcceptanceMetricMinimum = true; pipeline.Steps[0].UseAcceptanceMetricMaximum = true; pipeline.Steps[0].AcceptanceMetricMinimum = 20; pipeline.Steps[0].AcceptanceMetricMaximum = 10; }, "판정 하한이 상한보다 큽니다.", "acceptance metric minimum is greater than maximum."),
                ("time-limit", pipeline => pipeline.Steps[0].MaxElapsedMilliseconds = -1, "처리 시간 상한은 0 이상이어야 합니다.", "MaxElapsedMilliseconds cannot be negative."),
                ("roi-size", pipeline => pipeline.Steps[0] = VisionPipelineStepBuilder.FromProperty(new BlobProperty { NAME = "이름: 따옴표 ' 포함", USE_ROI = true, CvROI = new OpenCvSharp.Rect(0, 0, 0, 10) }, "Main", baseline.Steps[0].OutputLayer), "폭과 높이는 0보다 커야 합니다.", "width and height must be greater than zero."),
                ("missing-B", pipeline => pipeline.Steps[1] = VisionPipelineStepBuilder.FromArithmetic("이미지 연산", "ADD", baseline.Steps[0].OutputLayer, "MissingB", "Sum", false, false, 0, 0, 0, 0, 0, 0), "입력 B를 만드는 앞 단계가 없습니다.", "No earlier step creates input B."),
                ("missing-frame", pipeline => { pipeline.Steps[1].Parameters[VisionPipelineFixtureFrameService.ConsumeParameter] = "true"; pipeline.Steps[1].Parameters[VisionPipelineFixtureFrameService.FrameNameParameter] = "MissingFrame"; }, "좌표 기준 ‘MissingFrame’를 만드는 앞의 사용 단계가 없습니다.", "fixture frame 'MissingFrame' must be published by an earlier enabled fixture producer."),
                ("all-disabled", pipeline => { foreach (VisionPipelineStep step in pipeline.Steps) { step.Enabled = false; } }, "사용 중인 단계가 없습니다.", "Pipeline has no enabled steps.")
            };
            foreach (OpenVisionLanguage language in new[] { OpenVisionLanguage.Korean, OpenVisionLanguage.English })
            {
                OpenVisionLanguageService.SetLanguage(language, false);
                foreach (var item in cases)
                {
                    VisionPipeline candidate = VisionPipelineStepEditService.Copy(baseline);
                    item.Mutate(candidate);
                    VisionPipelineStorage.Save(recipeName, candidate);
                    host.RecipeCommands.RefreshOptions();
                    Pump(8);
                    string expected = language == OpenVisionLanguage.Korean ? item.Korean : item.English;
                    string observed = string.Join(" | ", model.Rows.Select(row => row.ErrorText)) + " | " + model.RunDisabledReason;
                    if (model.ValidationSucceeded || model.RunCommand.CanExecute(null) || run.IsEnabled || !observed.Contains(expected, StringComparison.Ordinal)
                        || model.ResultCountForTest != 0 || host.NativePreviewRunCount != 0
                        || !VisionPipelineExecutionPlan.SerializePipeline(candidate).SequenceEqual(VisionPipelineExecutionPlan.SerializePipeline(model.WorkingCopyForTest)))
                    {
                        throw new InvalidOperationException($"Workbench validation {language}/{item.Id} must preserve raw XML, display '{expected}', and block execution without running. Actual='{observed}'.");
                    }
                    if (item.Id != "all-disabled" && !FindVisualChildren<TextBlock>(host).Any(text => text.IsVisible && text.Text.Contains(expected, StringComparison.Ordinal)))
                    {
                        throw new InvalidOperationException($"Workbench validation {language}/{item.Id} was not rendered through the row binding.");
                    }
                }
            }
            OpenVisionLanguageService.SetLanguage(OpenVisionLanguage.Korean, false);
            VisionPipeline final = VisionPipelineStepEditService.Copy(baseline);
            final.Steps[0].Parameters["RangeMin"] = "180";
            final.Steps[0].Parameters["RangeMax"] = "40";
            VisionPipelineStorage.Save(recipeName, final);
            host.RecipeCommands.RefreshOptions();
            Pump(8);
            File.WriteAllText(Path.ChangeExtension(outputPath, ".validation.json"), JsonSerializer.Serialize(new { Cases = cases.Select(item => item.Id), Languages = "ko/en", ExecutionCount = host.NativePreviewRunCount }));
        }, captureFloatingToolWindow: false);
    }

    private static CaptureResult CaptureWorkbenchResultsReasonReachability(string outputPath)
    {
        OpenVisionShellHostView host = CreateShellHost("Smoke_Results_Reachability_" + Guid.NewGuid().ToString("N"), seedMainLayer: false);
        string input = Path.ChangeExtension(outputPath, ".input.bmp");
        using (Bitmap image = new(640, 360)) { using Graphics graphics = Graphics.FromImage(image); graphics.Clear(DrawingColor.FromArgb(128, 128, 128)); image.Save(input, ImageFormat.Bmp); }
        List<object> cases = new();
        return CaptureWindowWithContent(host, outputPath, 1600, 900, () =>
        {
            Window window = Window.GetWindow(host);
            OpenVisionWorkbenchPipelineViewModel pipeline = host.Workbench.Pipeline;
            host.LoadMainImageFromFileForTest(input);
            pipeline.InsertStep(0, VisionPipelineStepBuilder.FromProperty(new MeanProperty { NAME = "Mean reachability", USE_ROI = false, USE_THRESHOLD = false, MEAN_MIN = 200, MEAN_MAX = 255 }, "Main", "Mean_Reachability"));
            pipeline.SelectStepCommand.Execute(0); host.Workbench.Tool.IsAutoRunEnabled = false; Pump(4);
            WaitForTaskWithPump(pipeline.RunForTestAsync(), 12000, "Owned results reachability NG");
            byte[] working = VisionPipelineExecutionPlan.SerializePipeline(pipeline.WorkingCopyForTest);
            host.Workbench.IsBottomCollapsed = false; host.Workbench.SelectedBottomTab = 1;
            foreach (string theme in new[] { "Dark", "Light" })
            foreach (int width in new[] { 1600, 1280 })
            {
                (theme == "Dark" ? host.Workbench.SelectDarkThemeCommand : host.Workbench.SelectLightThemeCommand).Execute(null);
                window.Width = width; window.Height = width == 1600 ? 900 : 760; Pump(5);
                Grid panel = FindVisualChildren<Grid>(host).Single(item => AutomationProperties.GetAutomationId(item) == "MainResultsView");
                ScrollViewer outer = FindVisualChildren<ScrollViewer>(panel).Single(item => AutomationProperties.GetAutomationId(item) == "MainResultsScroll");
                ScrollViewer detail = FindVisualChildren<ScrollViewer>(panel).Single(item => AutomationProperties.GetAutomationId(item) == "MainResultsDetailScroll");
                DataGrid metricGrid = FindVisualChildren<DataGrid>(panel).Single(item => AutomationProperties.GetAutomationId(item) == "MainResultsMetrics");
                ScrollViewer? metrics = null;
                for (DependencyObject parent = VisualTreeHelper.GetParent(metricGrid); parent != null; parent = VisualTreeHelper.GetParent(parent))
                    if (parent is ScrollViewer scroll) { metrics = scroll; break; }
                TextBlock reason = FindVisualChildren<TextBlock>(detail).Single(text => text.Text == host.Workbench.Results.ReasonText);
                TextBlock statistics = FindVisualChildren<TextBlock>(detail).Single(text => text.Text == host.Workbench.Results.OutputStatisticsText);
                metrics!.ScrollToBottom(); detail.ScrollToBottom(); outer.ScrollToBottom(); outer.ScrollToRightEnd(); Pump(5);
                Rect reasonBounds = new(reason.TranslatePoint(new Point(), panel), new Size(reason.ActualWidth, reason.ActualHeight));
                Rect statisticsBounds = new(statistics.TranslatePoint(new Point(), panel), new Size(statistics.ActualWidth, statistics.ActualHeight));
                bool reachable = reason.IsVisible && reasonBounds.Top >= 0 && reasonBounds.Bottom <= panel.ActualHeight + 1D && reasonBounds.Left >= 0 && reasonBounds.Right <= panel.ActualWidth + 1D
                    && statistics.IsVisible && statisticsBounds.Top >= 0 && statisticsBounds.Bottom <= panel.ActualHeight + 1D;
                string capture = Path.ChangeExtension(outputPath, "." + theme + "." + width + ".png");
                ScreenshotPngWriter.WriteDpiAwareWindowPng(window, capture);
                string? clippedBy = GetFirstAncestorClippingElement(reason, panel);
                int reasonPixels = 0;
                using (Bitmap bitmap = new(capture))
                {
                    Point origin = reason.TranslatePoint(new Point(), host);
                    Color foreground = ((SolidColorBrush)reason.Foreground).Color;
                    for (int y = Math.Max(0, (int)origin.Y); y < Math.Min(bitmap.Height, (int)Math.Ceiling(origin.Y + reason.ActualHeight)); y++)
                    for (int x = Math.Max(0, (int)origin.X); x < Math.Min(bitmap.Width, (int)Math.Ceiling(origin.X + reason.ActualWidth)); x++)
                    {
                        DrawingColor pixel = bitmap.GetPixel(x, y);
                        if (Math.Abs(pixel.R - foreground.R) < 25 && Math.Abs(pixel.G - foreground.G) < 25 && Math.Abs(pixel.B - foreground.B) < 25) { reasonPixels++; }
                    }
                }
                reachable &= clippedBy == null && reasonPixels > 0;
                cases.Add(new { Theme = theme, Width = width, Reachable = reachable, MetricCount = host.Workbench.Results.Metrics.Count, Reason = reason.Text, PanelHeight = panel.ActualHeight, ReasonBounds = reasonBounds.ToString(CultureInfo.InvariantCulture), StatisticsBounds = statisticsBounds.ToString(CultureInfo.InvariantCulture),
                    Outer = new { outer.ActualHeight, outer.ViewportHeight, outer.ExtentHeight, outer.ScrollableHeight, outer.VerticalOffset }, Detail = new { detail.ActualHeight, detail.ViewportHeight, detail.ExtentHeight, detail.ScrollableHeight, detail.VerticalOffset }, Metrics = new { metrics.ActualHeight, metrics.ViewportHeight, metrics.ExtentHeight, metrics.ScrollableHeight, metrics.VerticalOffset }, ClippedBy = clippedBy, ReasonForegroundPixels = reasonPixels, Capture = capture, EvidenceKind = "in-process actual retained metrics; programmatic ScrollToBottom; native wheel/keyboard proof is separate" });
                File.WriteAllText(Path.ChangeExtension(outputPath, ".cases.json"), JsonSerializer.Serialize(cases, new JsonSerializerOptions { WriteIndented = true }));
                if (!reachable || host.Workbench.Results.Metrics.Count < 16 || host.NativePreviewRunCount != 0 || !working.SequenceEqual(VisionPipelineExecutionPlan.SerializePipeline(pipeline.WorkingCopyForTest)))
                    throw new InvalidOperationException("The actual retained Mean reason and output statistics must enter the results viewport without execution or data changes.");
                outer.ScrollToLeftEnd(); detail.ScrollToTop(); metrics.ScrollToTop(); Pump(3);
            }
        }, captureFloatingToolWindow: false);
    }

    private static CaptureResult CaptureWorkbenchPipelineMeanFailure(string outputPath)
    {
        string recipe = "Smoke_Mean_Failure_" + Guid.NewGuid().ToString("N");
        OpenVisionShellHostView host = CreateShellHost(recipe, seedMainLayer: false);
        VisionPipeline source = new() { Name = "Mean_Failure" };
        source.Steps.Add(VisionPipelineStepBuilder.FromProperty(new MeanProperty { NAME = "01 Mean intrinsic", USE_ROI = false, USE_THRESHOLD = false, MEAN_MIN = 200, MEAN_MAX = 255 }, "Main", "Mean_First"));
        source.Steps.Add(VisionPipelineStepBuilder.FromProperty(new MeanProperty { NAME = "02 Downstream Mean", USE_ROI = false, USE_THRESHOLD = false, MEAN_MIN = 0, MEAN_MAX = 255 }, "Mean_First", "Mean_Second"));
        string input = Path.ChangeExtension(outputPath, ".input.bmp");
        using (Bitmap image = new(640, 360)) { using Graphics graphics = Graphics.FromImage(image); graphics.Clear(DrawingColor.FromArgb(128, 128, 128)); image.Save(input, ImageFormat.Bmp); }
        List<object> cases = new();
        return CaptureWindowWithContent(host, outputPath, 1600, 900, () =>
        {
            OpenVisionWorkbenchPipelineViewModel model = host.Workbench.Pipeline;
            Window window = Window.GetWindow(host);
            host.LoadMainImageFromFileForTest(input); Pump(4);
            foreach (string boundary in new[] { "lower", "upper" })
            {
                source.Steps[0].Parameters["MEAN_MIN"] = boundary == "lower" ? "200" : "0";
                source.Steps[0].Parameters["MEAN_MAX"] = boundary == "lower" ? "255" : "100";
                VisionPipelineStorage.Save(recipe, source); VisionPipelineStorage.SaveActivePipelineName(recipe, source.Name);
                host.RecipeCommands.RefreshOptions(); host.RecipeCommands.SelectedPipelineOption = host.RecipeCommands.PipelineOptions.Single(option => option.PipelineName == source.Name);
                model.SelectStepCommand.Execute(0); host.Workbench.Tool.IsAutoRunEnabled = false; Pump(4);
                byte[] authored = VisionPipelineExecutionPlan.SerializePipeline(model.WorkingCopyForTest);
                byte[] saved = File.ReadAllBytes(RecipeWorkspaceService.GetVisionPipelinePath(recipe, source.Name));
                WaitForTaskWithPump(model.RunForTestAsync(), 12000, "Mean intrinsic " + boundary);
                if (model.VerdictValue != "NG" || model.Rows[0].StatusKind != "Ng" || model.Rows[1].StatusKind != "NotRun" || model.GetResult(0).Metrics["MeanValueAvg"] != 128D)
                    throw new InvalidOperationException("Intrinsic Mean must preserve the real GV128 NG and fail-fast result.");
                foreach (string theme in new[] { "Dark", "Light" })
                foreach (int width in new[] { 1600, 1280 })
                foreach (OpenVisionLanguage language in new[] { OpenVisionLanguage.Korean, OpenVisionLanguage.English })
                {
                    (theme == "Dark" ? host.Workbench.SelectDarkThemeCommand : host.Workbench.SelectLightThemeCommand).Execute(null);
                    window.Width = width; window.Height = width == 1600 ? 900 : 760;
                    OpenVisionLanguageService.SetLanguage(language, false); Pump(5);
                    string expected = language == OpenVisionLanguage.Korean
                        ? boundary == "lower" ? "평균 밝기 128.0 GV · 하한 200.0 GV 미달" : "평균 밝기 128.0 GV · 상한 100.0 GV 초과"
                        : boundary == "lower" ? "Mean brightness 128.0 GV · below Lower 200.0 GV" : "Mean brightness 128.0 GV · above Upper 100.0 GV";
                    bool shared = model.Rows[0].ErrorText == expected && host.Workbench.Tool.ResultReason == expected && host.Workbench.Results.ReasonText == expected;
                    TextBlock rendered = FindVisualChildren<TextBlock>(host).First(text => text.IsVisible && text.Text == expected);
                    ListBox list = FindVisualChildren<ListBox>(host).Single(item => AutomationProperties.GetAutomationId(item) == "WorkbenchPipelineSteps");
                    AssertElementWithinAncestor("Intrinsic Mean reason", rendered, list);
                    string capture = Path.ChangeExtension(outputPath, "." + boundary + "." + theme + "." + width + "." + language + ".png");
                    ScreenshotPngWriter.WriteDpiAwareWindowPng(window, capture);
                    cases.Add(new { Boundary = boundary, Theme = theme, Width = width, Language = language.ToString(), Expected = expected, RowReason = model.Rows[0].ErrorText, ToolReason = host.Workbench.Tool.ResultReason, ResultsReason = host.Workbench.Results.ReasonText, SharedProjection = shared, Capture = capture });
                    File.WriteAllText(Path.ChangeExtension(outputPath, ".cases.json"), JsonSerializer.Serialize(cases, new JsonSerializerOptions { WriteIndented = true }));
                    if (!shared || host.NativePreviewRunCount != 0 || !authored.SequenceEqual(VisionPipelineExecutionPlan.SerializePipeline(model.WorkingCopyForTest)) || !saved.SequenceEqual(File.ReadAllBytes(RecipeWorkspaceService.GetVisionPipelinePath(recipe, source.Name))))
                        throw new InvalidOperationException("Intrinsic Mean localized reason must agree across callers without mutating or executing from display changes.");
                }
                model.RenameCommand.Execute(null); model.RenameText = "Mean renamed without run"; model.CommitRenameCommand.Execute(null); Pump(4);
                if (!model.IsVerdictPrevious || model.Rows[0].StatusKind != "Previous" || model.Rows.Any(row => row.HasError))
                    throw new InvalidOperationException("Editing must hide the previous intrinsic Mean failure reason without running.");
                model.UndoCommand.Execute(null); Pump(3);
                if (model.IsDirty) throw new InvalidOperationException("Owned rename fixture must restore its authored source before the next boundary.");
            }
            source.Steps[0].Parameters["MEAN_MIN"] = "0"; source.Steps[0].Parameters["MEAN_MAX"] = "255";
            VisionPipelineStorage.Save(recipe, source); host.RecipeCommands.RefreshOptions();
            model.SelectStepCommand.Execute(0); Pump(3);
            WaitForTaskWithPump(model.RunForTestAsync(), 12000, "Mean valid recovery"); Pump(4);
            if (model.VerdictValue != "OK" || model.IsVerdictPrevious || model.Rows.Any(row => row.HasError) || !model.CanEdit)
                throw new InvalidOperationException("Valid Mean rerun must restore fresh results and commands.");
            VisionPipelineStep explicitStep = VisionPipelineStepEditService.CopyStep(source.Steps[0]);
            explicitStep.UseAcceptance = true; explicitStep.AcceptanceMetricName = "MeanValueAvg"; explicitStep.UseAcceptanceMetricMaximum = true; explicitStep.AcceptanceMetricMaximum = 100;
            VisionPipelineStepResultSummary explicitNg = new() { IsAcceptanceNg = true }; explicitNg.Metrics["MeanValueAvg"] = 128;
            if (!OpenVisionPipelineReviewResultPresenter.FormatWorkbenchFailure(explicitStep, explicitNg).Contains("100.0 GV", StringComparison.Ordinal))
                throw new InvalidOperationException("Explicit Mean acceptance must keep its authored acceptance range.");
            VisionPipelineStepResultSummary error = new() { Message = "Owned distinct runtime error" };
            if (OpenVisionPipelineReviewResultPresenter.FormatWorkbenchFailure(source.Steps[0], error) != error.Message)
                throw new InvalidOperationException("Mean runtime errors must not be recast as acceptance NG.");
            File.WriteAllText(Path.ChangeExtension(outputPath, ".recovery.json"), JsonSerializer.Serialize(new { Verdict = model.VerdictValue, Fresh = !model.IsVerdictPrevious, RowReasonsHidden = model.Rows.All(row => !row.HasError), ExplicitAcceptancePreserved = true, ErrorPreserved = true, NativePreviewRunCount = host.NativePreviewRunCount, Scope = "in-process real execution/row rendering/shared projection; actual EXE input/DPI are separate" }));
        }, captureFloatingToolWindow: false);
    }

    private static CaptureResult CaptureWorkbenchPipelineRowRunSelection(string outputPath, bool compact)
    {
        string recipe = "Smoke_Pipeline_RowRun_" + Guid.NewGuid().ToString("N");
        OpenVisionShellHostView host = CreateShellHost(recipe);
        VisionPipeline source = CreatePipelineReviewInputStatePipeline();
        source.Steps[1].InputLayer = source.Steps[0].OutputLayer;
        VisionPipelineStorage.Save(recipe, source);
        VisionPipelineStorage.SaveActivePipelineName(recipe, source.Name);
        host.RecipeCommands.RefreshOptions();
        host.RecipeCommands.SelectedPipelineOption = host.RecipeCommands.PipelineOptions.Single(option => option.PipelineName == source.Name);
        return CaptureWindowWithContent(host, outputPath, compact ? 1280 : 1920, compact ? 760 : 1032, () =>
        {
            OpenVisionWorkbenchPipelineViewModel model = host.Workbench.Pipeline;
            model.SelectStepCommand.Execute(0); Pump(8);
            model.RenameCommand.Execute(null);
            if (model.RunToRowCommand.CanExecute(1)) throw new InvalidOperationException("Row run-to must be blocked while the current stage name is being edited.");
            model.CancelRenameCommand.Execute(null);
            int selectionEvents = 0, nativeRuns = host.NativePreviewRunCount;
            byte[] working = VisionPipelineExecutionPlan.SerializePipeline(model.WorkingCopyForTest);
            EventHandler observer = (_, _) => selectionEvents++;
            model.StepSelected += observer;
            try { model.RunToRowCommand.Execute(1); }
            finally { model.StepSelected -= observer; }
            Stopwatch timer = Stopwatch.StartNew();
            while (model.IsRunning && timer.ElapsedMilliseconds < 12000) { Pump(1); }
            Pump(8);
            string expectedTitle = "02 · " + model.Rows[1].Name;
            bool identity = model.SelectedStepIndex == 1 && model.SelectedRow.Index == 1 && host.Workbench.Tool.Title == expectedTitle
                && host.Workbench.Viewer.ResolveLayer("follow:in") == source.Steps[1].InputLayer && host.Workbench.Viewer.ResolveLayer("follow:out") == source.Steps[1].OutputLayer;
            File.WriteAllText(Path.ChangeExtension(outputPath, ".selection.json"), JsonSerializer.Serialize(new { SelectionEvents = selectionEvents, model.SelectedStepIndex, ToolTitle = host.Workbench.Tool.Title, ExpectedToolTitle = expectedTitle, Identity = identity, model.IsRunning, NativeRunsBefore = nativeRuns, NativeRunsAfter = host.NativePreviewRunCount, WorkingUnchanged = working.SequenceEqual(VisionPipelineExecutionPlan.SerializePipeline(model.WorkingCopyForTest)), EvidenceKind = "in-process public command; actual pointer input is separate" }));
            ScreenshotPngWriter.WriteDpiAwareWindowPng(Window.GetWindow(host), Path.ChangeExtension(outputPath, ".observed.png"));
            if (!identity || selectionEvents != 1 || model.IsRunning || host.NativePreviewRunCount != nativeRuns || !working.SequenceEqual(VisionPipelineExecutionPlan.SerializePipeline(model.WorkingCopyForTest)))
                throw new InvalidOperationException("Row run-to must synchronize its selected stage and existing tool editor exactly once before explicit execution.");
        }, captureFloatingToolWindow: false);
    }

    private static CaptureResult CaptureWorkbenchPipelineExecution(string outputPath, bool compact)
    {
        OpenVisionLanguageService.SetLanguage(OpenVisionLanguage.Korean, false);
        string recipeName = "Smoke_Workbench_Execution_" + Guid.NewGuid().ToString("N");
        OpenVisionShellHostView host = CreateShellHost(recipeName, seedMainLayer: false);
        VisionPipeline source = CreatePipelineReviewInputStatePipeline();
        source.Steps[1].InputLayer = source.Steps[0].OutputLayer;
        VisionPipelineStorage.Save(recipeName, source);
        VisionPipelineStorage.SaveActivePipelineName(recipeName, source.Name);
        host.RecipeCommands.RefreshOptions();
        host.RecipeCommands.SelectedPipelineOption = host.RecipeCommands.PipelineOptions.Single(option => option.PipelineName == source.Name);
        return CaptureWindowWithContent(host, outputPath, compact ? 1280 : 1920, compact ? 760 : 1032, () =>
        {
            OpenVisionWorkbenchPipelineViewModel model = host.Workbench.Pipeline;
            OpenVisionLanguageService.SetLanguage(OpenVisionLanguage.Korean, false);
            if (model.RunCommand.CanExecute(null)) { throw new InvalidOperationException("An empty workspace must block pipeline execution."); }
            AssertMainStatusVerdict(host);
            string workspaceInput = CreateWorkspaceLoadSmokeImageFile();
            if (!host.LoadMainImageFromFileForTest(workspaceInput)) { throw new InvalidOperationException("The actual workspace load path must accept the owned input."); }
            Pump(8);
            if (!model.RunCommand.CanExecute(null) || !model.ValidationSucceeded || model.ResultCountForTest != 0 || host.NativePreviewRunCount != 0)
            {
                throw new InvalidOperationException("Workspace image load must refresh pipeline readiness without executing.");
            }
            Task unjudgedRun = model.RunForTestAsync();
            if (!model.IsRunning || model.CanEdit || model.RunCommand.CanExecute(null) || model.RenameCommand.CanExecute(null))
            {
                throw new InvalidOperationException("Running must disable editing and repeated execution.");
            }
            Task repeatedRun = model.RunForTestAsync();
            if (!repeatedRun.IsCompleted || !model.IsRunning) { throw new InvalidOperationException("Repeated run must return without starting another run."); }
            model.StopCommand.Execute(null);
            if (model.StopCommand.CanExecute(null)) { throw new InvalidOperationException("Repeated stop must be disabled while this image finishes."); }
            WaitForTaskWithPump(unjudgedRun, 12000, "Workbench unjudged run and stop-after-current-image");
            Pump(8);
            if (model.VerdictValue != OpenVisionLanguageService.T("Workbench.Status.Done") || model.VerdictDetail != OpenVisionLanguageService.T("Workbench.Status.NoVerdict")
                || model.Rows.Any(row => row.StatusText != OpenVisionLanguageService.T("Workbench.Status.Done")) || model.ResultCountForTest != 2)
            {
                throw new InvalidOperationException("Unjudged successful execution must be Done, never OK.");
            }
            ListBox runList = FindVisualChildren<ListBox>(host).Single(item => AutomationProperties.GetAutomationId(item) == "WorkbenchPipelineSteps");
            if (runList.SelectedItem is not OpenVisionWorkbenchStepViewModel runSelection || runSelection.Index != model.SelectedRow?.Index)
            {
                throw new InvalidOperationException("Progress and final-result updates must retain visible row selection.");
            }
            AssertWorkbenchVerdictPresentation(host);
            ScreenshotPngWriter.WriteDpiAwareWindowPng(Window.GetWindow(host), Path.ChangeExtension(outputPath, ".unjudged-done.png"));
            model.SelectedRow = model.Rows[1];
            model.RenameCommand.Execute(null);
            model.RenameText = "필터 결과";
            model.CommitRenameCommand.Execute(null);
            if (!model.IsVerdictPrevious || model.Rows[1].StatusText != OpenVisionLanguageService.T("Workbench.Status.Previous")) { throw new InvalidOperationException("Edit must stale affected rows and verdict."); }
            AssertMainStatusVerdict(host);
            model.UndoCommand.Execute(null);
            if (!model.IsVerdictPrevious || model.Rows.Any(row => row.StatusText != OpenVisionLanguageService.T("Workbench.Status.Previous"))) { throw new InvalidOperationException("Undo must not refresh results."); }
            AssertWorkbenchVerdictPresentation(host);
            ScreenshotPngWriter.WriteDpiAwareWindowPng(Window.GetWindow(host), Path.ChangeExtension(outputPath, ".previous.png"));
            string priorVerdict = model.VerdictValue;
            model.SelectedRow = model.Rows[0];
            WaitForTaskWithPump(model.RunForTestAsync(true), 12000, "Workbench prefix run");
            if (model.VerdictValue != priorVerdict || !model.IsVerdictPrevious || model.Rows[1].StatusText != OpenVisionLanguageService.T("Workbench.Status.Previous")) { throw new InvalidOperationException("Prefix run must not update final verdict or downstream results."); }
            source.Steps[0].UseAcceptance = true;
            source.Steps[0].AcceptanceMetricName = VisionPipelineKnownMetrics.ResultImageWidth;
            source.Steps[0].UseAcceptanceMetricMaximum = true;
            source.Steps[0].AcceptanceMetricMaximum = 1;
            VisionPipelineStorage.Save(recipeName, source);
            host.RecipeCommands.RefreshOptions();
            WaitForTaskWithPump(model.RunForTestAsync(), 12000, "Workbench acceptance NG");
            Pump(8);
            File.WriteAllText(Path.ChangeExtension(outputPath, ".ng-diagnostics.json"), JsonSerializer.Serialize(new { Locale = OpenVisionLanguageService.CurrentLanguage.ToString(), Verdict = model.VerdictValue, Detail = model.VerdictDetail, Rows = model.Rows.Select(row => new { row.Name, row.StatusKind, row.ErrorText }), Dirty = model.IsDirty, Acceptance = model.WorkingCopyForTest.Steps[0].UseAcceptance }));
            if (model.VerdictValue != "NG" || model.Rows[0].StatusKind != "Ng" || model.Rows[1].StatusKind != "NotRun"
                || !model.VerdictDetail.Contains("이후 1단계 미실행", StringComparison.Ordinal)) { throw new InvalidOperationException("NG must retain indexed results and stop subsequent steps."); }
            if (model.Rows[1].HasError || !model.Rows[0].ErrorText.Contains("결과 폭", StringComparison.Ordinal)
                || !model.Rows[0].ErrorText.Contains("px", StringComparison.Ordinal) || model.Rows[0].ErrorText.Contains("ResultImageWidth", StringComparison.Ordinal))
            {
                throw new InvalidOperationException("NG must show localized measured values and units; unexecuted rows have no failure reason.");
            }
            AssertWorkbenchVerdictPresentation(host);
            ScreenshotPngWriter.WriteDpiAwareWindowPng(Window.GetWindow(host), Path.ChangeExtension(outputPath, ".acceptance-ng.png"));
            OpenVisionLanguageService.SetLanguage(OpenVisionLanguage.English, false);
            Pump(8);
            if (!model.VerdictDetail.Contains("1 later steps not run", StringComparison.Ordinal) || model.ResultCountForTest != 2) { throw new InvalidOperationException("Language must translate verdict without rerunning."); }
            AssertWorkbenchVerdictPresentation(host);
            ScreenshotPngWriter.WriteDpiAwareWindowPng(Window.GetWindow(host), Path.ChangeExtension(outputPath, ".ng-English.png"));
            OpenVisionLanguageService.SetLanguage(OpenVisionLanguage.Korean, false);
            source.Steps[0].AcceptanceMetricMaximum = 100000;
            VisionPipelineStorage.Save(recipeName, source);
            host.RecipeCommands.RefreshOptions();
            WaitForTaskWithPump(model.RunForTestAsync(), 12000, "Workbench judged OK recovery");
            if (model.VerdictValue != "OK" || model.Rows[1].StatusKind != "Done") { throw new InvalidOperationException("Valid recovery must replace NG and unexecuted states."); }
            VisionPipeline runtimeError = VisionPipelineStepEditService.Copy(source);
            runtimeError.Steps[0].ToolType = "Matching";
            runtimeError.Steps[0].UseAcceptance = false;
            runtimeError.Steps[0].Parameters.Clear();
            VisionPipelineStorage.Save(recipeName, runtimeError);
            host.RecipeCommands.RefreshOptions();
            if (!model.ValidationSucceeded) { throw new InvalidOperationException("Missing runtime template must reach the existing tool execution contract."); }
            WaitForTaskWithPump(model.RunForTestAsync(), 12000, "Workbench runtime tool error");
            if (model.VerdictValue != OpenVisionLanguageService.T("Workbench.Status.Error") || model.Rows[0].StatusKind != "Error"
                || model.Rows[1].StatusKind != "NotRun" || model.Rows[1].HasError)
            {
                throw new InvalidOperationException("Tool error must remain distinct from NG and stop later steps.");
            }
            AssertWorkbenchVerdictPresentation(host);
            ScreenshotPngWriter.WriteDpiAwareWindowPng(Window.GetWindow(host), Path.ChangeExtension(outputPath, ".tool-error.png"));
            VisionPipeline mean = VisionPipelineStepEditService.Copy(source);
            mean.Steps.Clear();
            mean.Steps.Add(VisionPipelineStepBuilder.FromProperty(new MeanProperty { NAME = "평균 밝기", USE_ROI = false, MEAN_MIN = 0, MEAN_MAX = 255 }, "Main", "Mean_Output"));
            VisionPipelineStorage.Save(recipeName, mean);
            host.RecipeCommands.RefreshOptions();
            WaitForTaskWithPump(model.RunForTestAsync(), 12000, "Workbench Mean intrinsic judgment");
            if (model.VerdictValue != "OK" || model.JudgedCountText != string.Format(OpenVisionLanguageService.T("Workbench.Pipeline.JudgedCountFormat"), 1))
            {
                throw new InvalidOperationException("Mean intrinsic range judgment must contribute to final OK without UseAcceptance.");
            }
            VisionPipelineStorage.Save(recipeName, source);
            host.RecipeCommands.RefreshOptions();
            WaitForTaskWithPump(model.RunForTestAsync(), 12000, "Workbench recovery after tool error and Mean");
            if (model.IsRunning || !model.CanEdit || model.VerdictValue != "OK" || model.Rows[1].StatusKind != "Done")
            {
                throw new InvalidOperationException("Valid recovery must restore commands and replace error/unexecuted results.");
            }
            AssertWorkbenchVerdictPresentation(host);
            host.Workbench.IsToolPaletteCollapsed = true;
            AssertVisibleTextDoesNotContain(host, "Workbench pipeline execution", "Workbench.", "PipelineReview.");
        }, captureFloatingToolWindow: false);
    }

