    private static CaptureResult CaptureToolWindowReopenSameTool(string outputPath)
    {
        OpenVisionLanguageService.SetLanguage(OpenVisionLanguage.Korean, false);
        OpenVisionShellHostView shellHost = CreateShellHost("Smoke_WpfToolWindowReopenSameTool");
        return CaptureWindowWithContent(shellHost, outputPath, 1600, 900, () =>
        {
            shellHost.SelectToolForTest(VISION_MENU.Matching);
            Pump(16);

            if (!shellHost.IsActiveWpfToolWindowVisibleForTest || !shellHost.IsNativeDocumentActive)
            {
                throw new InvalidOperationException("Matching tool window did not open before the reopen check.");
            }

            if (!shellHost.CloseActiveWpfToolWindowForTest())
            {
                throw new InvalidOperationException("Matching tool window could not be closed for the reopen check.");
            }

            Pump(16);
            if (shellHost.IsActiveWpfToolWindowVisibleForTest || shellHost.IsNativeDocumentActive)
            {
                throw new InvalidOperationException("Closing the matching tool window did not detach the active document.");
            }

            // A second click on the already-selected menu must reopen the tool;
            // V2 opens it docked, and the floating popup guard follows explicit Float.
            shellHost.SelectToolForTest(VISION_MENU.Matching);
            Pump(16);

            if (!shellHost.IsActiveWpfToolWindowVisibleForTest
                || !shellHost.IsNativeDocumentActive
                || !shellHost.ActiveNativeDocumentTypeName.Contains("MatchingToolWpfView", StringComparison.Ordinal))
            {
                throw new InvalidOperationException("Re-clicking the selected Matching menu did not reopen the WPF tool window.");
            }

            AssertActiveToolWindowState(shellHost, "MatchingToolWpfView", true, 0, "Matching reopened docked");
            if (!shellHost.FloatDockedWpfToolWindowForTest())
                throw new InvalidOperationException("Reopened Matching did not accept explicit Float for the popup guard.");
            Pump(16);
            ComboBox inputLayerCombo = FindFloatingComboBox("cbInputLayer");
            AssertVisionToolComboTemplate(inputLayerCombo, "Reopened matching input layer combo");
            AssertComboBoxPopupLayout(inputLayerCombo, "Reopened matching input layer combo");
        });
    }

    private static CaptureResult CaptureMatchingWorkspaceReloadCloseCycle(string outputPath)
    {
        OpenVisionLanguageService.SetLanguage(OpenVisionLanguage.Korean, false);
        OpenVisionShellHostView shellHost = CreateShellHost("Smoke_WpfMatchingWorkspaceReloadCloseCycle");
        using Bitmap firstImage = CreateMatchingSmokeBitmap();
        using Bitmap secondImage = CreateMatchingSmokeBitmap();
        secondImage.SetPixel(0, 0, System.Drawing.Color.White);
        string templatePath = CreateMatchingTemplateFile(firstImage);
        try
        {
            shellHost.SetMainLayerImageForTest(firstImage);
            return CaptureWindowWithContent(shellHost, outputPath, 1600, 900, () =>
            {
                shellHost.SelectToolForTest(VISION_MENU.Matching);
                Pump(16);
                shellHost.SetActiveMatchingTemplatePathForTest(templatePath);
                int runsBeforePreview = shellHost.NativePreviewRunCount;
                shellHost.RunActiveNativePreviewForTest();
                Stopwatch previewCompletion = Stopwatch.StartNew();
                while (shellHost.NativePreviewRunCount == runsBeforePreview && previewCompletion.Elapsed < TimeSpan.FromSeconds(5))
                {
                    Pump(2);
                    Thread.Sleep(10);
                }
                if (!shellHost.IsActiveWpfToolWindowVisibleForTest
                    || !shellHost.IsNativeDocumentActive
                    || !shellHost.HasNativePreviewResult)
                {
                    throw new InvalidOperationException(
                        "Matching did not reach an explicit preview result before the workspace reload cycle.");
                }

                int previewRuns = shellHost.NativePreviewRunCount;
                shellHost.SetMainLayerImageForTest(secondImage);
                Pump(24);
                if (!shellHost.IsActiveWpfToolWindowVisibleForTest
                    || !shellHost.IsNativeDocumentActive
                    || shellHost.HasNativePreviewResult
                    || shellHost.NativePreviewRunCount != previewRuns
                    || !string.Equals(shellHost.ActiveHostLayerTitle, "Main", StringComparison.OrdinalIgnoreCase))
                {
                    throw new InvalidOperationException(
                        "Loading a new Main image while Matching was open left stale preview or window state. "
                        + $"Visible={shellHost.IsActiveWpfToolWindowVisibleForTest}, Active={shellHost.IsNativeDocumentActive}, "
                        + $"Preview={shellHost.HasNativePreviewResult}, Runs={previewRuns}->{shellHost.NativePreviewRunCount}, "
                        + $"ActiveLayer={shellHost.ActiveHostLayerTitle}");
                }

                if (!shellHost.CloseActiveWpfToolWindowForTest())
                {
                    throw new InvalidOperationException("Matching window did not close after the workspace image changed.");
                }

                Pump(16);
                if (shellHost.IsActiveWpfToolWindowVisibleForTest || shellHost.IsNativeDocumentActive)
                {
                    throw new InvalidOperationException("Closing Matching left a stale active Tool document.");
                }

                shellHost.SelectToolForTest(VISION_MENU.Matching);
                Pump(20);
                if (!shellHost.IsActiveWpfToolWindowVisibleForTest
                    || !shellHost.IsNativeDocumentActive
                    || shellHost.HasNativePreviewResult
                    || !shellHost.ActiveNativeDocumentTypeName.Contains("MatchingToolWpfView", StringComparison.Ordinal))
                {
                    throw new InvalidOperationException("Matching did not reopen cleanly after image reload and close.");
                }

                shellHost.SelectToolForTest(VISION_MENU.Line);
                Pump(20);
                if (!shellHost.IsActiveWpfToolWindowVisibleForTest
                    || !shellHost.IsNativeDocumentActive
                    || !shellHost.ActiveNativeDocumentTypeName.Contains("LineToolWpfView", StringComparison.Ordinal)
                    || shellHost.HasNativePreviewResult)
                {
                    throw new InvalidOperationException(
                        "Switching from reopened Matching to Line left stale panel state or ran Preview unexpectedly.");
                }
            });
        }
        finally
        {
            TryDeleteFile(templatePath);
        }
    }

    private static CaptureResult CapturePersistedWorkspacePreferencesContract(string outputPath)
    {
        string recipeName = "RememberedRecipe";
        RecipeWorkspaceService.EnsureVisionWorkspace(recipeName);
        string imagePath = Path.Combine(AppPathService.DataRootDirectory, "remembered-image.png");
        using (Bitmap image = new Bitmap(16, 12))
        {
            image.SetPixel(0, 0, System.Drawing.Color.White);
            image.Save(imagePath, ImageFormat.Png);
        }

        GlobalState saved = new GlobalState();
        saved.System.LastRecipe = recipeName;
        saved.System.LastWorkspaceImagePath = imagePath;
        if (!saved.System.SaveConfig())
        {
            throw new InvalidOperationException("Could not save remembered workspace preferences.");
        }

        GlobalState restored = new GlobalState();
        restored.RestoreLastRecipe();
        string restoredImageDirectory =
            OpenVisionShellHostCommandController.ResolveExistingImageDirectory(
                restored.System.LastWorkspaceImagePath);
        if (!string.Equals(restored.Recipe.Name, recipeName, StringComparison.Ordinal)
            || !string.Equals(restored.System.LastWorkspaceImagePath, imagePath, StringComparison.OrdinalIgnoreCase)
            || !string.Equals(
                restoredImageDirectory,
                Path.GetDirectoryName(imagePath),
                StringComparison.OrdinalIgnoreCase))
        {
            throw new InvalidOperationException(
                "Saved recipe or workspace image path did not survive a config reload.");
        }

        if (!RecipeWorkspaceService.DeleteVisionWorkspace(recipeName))
        {
            throw new InvalidOperationException("Could not remove the remembered recipe for stale-state validation.");
        }

        GlobalState staleRecipe = new GlobalState();
        staleRecipe.RestoreLastRecipe();
        if (!string.Equals(staleRecipe.Recipe.Name, "Default", StringComparison.Ordinal)
            || !string.Equals(staleRecipe.System.LastRecipe, "Default", StringComparison.Ordinal))
        {
            throw new InvalidOperationException("A deleted remembered recipe did not fall back to Default.");
        }

        File.Delete(imagePath);
        if (OpenVisionShellHostCommandController.ResolveExistingImageDirectory(imagePath) != null)
        {
            throw new InvalidOperationException("A deleted remembered image path did not fall back safely.");
        }

        Border report = new Border
        {
            Background = Brushes.White,
            Padding = new Thickness(24),
            Child = new TextBlock
            {
                Text = string.Join(
                    Environment.NewLine,
                    "Persisted workspace preferences: OK",
                    "Recipe reload: RememberedRecipe",
                    "Deleted recipe fallback: Default",
                    "Image directory reload: " + restoredImageDirectory,
                    "Deleted image fallback: default resolver"),
                FontSize = 16,
                Foreground = Brushes.DarkSlateGray
            }
        };
        return CaptureElement(report, outputPath, 760, 300);
    }

    private static CaptureResult CaptureToolPropertyGridKeyboard(string outputPath)
    {
        OpenVisionLanguageService.SetLanguage(OpenVisionLanguage.Korean, false);
        OpenVisionShellHostView host = CreateShellHost("Smoke_ToolGridKeyboard");
        return CaptureWindowWithContent(host, outputPath, 1600, 900, () =>
        {
            List<string> keyboardResults = new();
            foreach (VISION_MENU menu in new[] { VISION_MENU.Matching, VISION_MENU.EdgeBasedMatching })
            {
                host.SelectToolForTest(menu);
                Pump(24);
                System.Windows.Controls.WpfPropertyGrid.PropertyGrid grid = FindVisualChildren<System.Windows.Controls.WpfPropertyGrid.PropertyGrid>(GetActiveToolVisualRoot("Tool keyboard"))
                    .Single(item => item.IsVisible);
                object property = grid.SelectedObject;
                MatchingProperty matching = property as MatchingProperty;
                if (matching?.AUTO_PREVIEW == true) throw new InvalidOperationException("The Matching keyboard fixture requires its documented default AUTO_PREVIEW=false.");
                Func<double> currentScore = matching != null ? () => matching.SCORE_MIN : () => ((EdgeBasedMatchingProperty)property).SCORE_MIN;
                int runs = host.NativePreviewRunCount;
                int layers = host.HostLayerRowCount;
                string route = host.DirectResultRouteText;
                string activeLayer = host.ActiveRecipeContextLayerNameForTest;
                string result = host.ActiveNativeResultReviewText;
                string viewType = menu == VISION_MENU.Matching ? "MatchingToolWpfView" : "EdgeBasedMatchingToolWpfView";
                foreach (string placement in new[] { "Docked", "Floating", "Redocked" })
                {
                    if (placement == "Floating" && !host.FloatDockedWpfToolWindowForTest())
                        throw new InvalidOperationException("Tool keyboard test could not float the docked view.");
                    if (placement == "Redocked" && !host.DockActiveWpfToolWindowForTest())
                        throw new InvalidOperationException("Tool keyboard test could not redock the floating view.");
                    Pump(20);
                    AssertActiveToolWindowState(host, viewType, placement != "Floating", placement == "Floating" ? 1 : 0, placement + " keyboard");
                    System.Windows.Controls.WpfPropertyGrid.PropertyGrid activeGrid = FindVisualChildren<System.Windows.Controls.WpfPropertyGrid.PropertyGrid>(GetActiveToolVisualRoot("Tool keyboard " + placement))
                        .Single(item => item.IsVisible);
                    if (!ReferenceEquals(grid, activeGrid) || !ReferenceEquals(property, activeGrid.SelectedObject))
                        throw new InvalidOperationException("Tool keyboard placement replaced the PropertyGrid or parameter object.");
                    if (host.ActiveNativeResultReviewText != result)
                        throw new InvalidOperationException("Floating or redocking changed the result before keyboard input.");
                    foreach (System.Windows.Controls.WpfPropertyGrid.PropertyGridThemeVariant theme in new[]
                    {
                        System.Windows.Controls.WpfPropertyGrid.PropertyGridThemeVariant.Dark,
                        System.Windows.Controls.WpfPropertyGrid.PropertyGridThemeVariant.Default
                    })
                    {
                        grid.ThemeVariant = theme;
                        Pump(12);
                        TextBox editor = FindVisualChildren<TextBox>(grid).Single(item => item.IsVisible
                            && System.Windows.Automation.AutomationProperties.GetAutomationId(item) == "SCORE_MIN");
                        editor.Focus();
                        Pump(8);
                        if (!editor.IsKeyboardFocused) throw new InvalidOperationException("Tool numeric editor did not receive focus.");
                        // Matching has an explicit AUTO_PREVIEW=false fixture. Edge matching keeps
                        // its value unchanged so this probe isolates Tab/placement from its legacy debounce.
                        double score = matching != null ? 0.83D - keyboardResults.Count * 0.04D : currentScore();
                        editor.Text = score.ToString("0.00", CultureInfo.InvariantCulture);
                        KeyEventArgs tab = new(Keyboard.PrimaryDevice, PresentationSource.FromVisual(editor), Environment.TickCount, Key.Tab)
                        {
                            RoutedEvent = Keyboard.PreviewKeyDownEvent
                        };
                        editor.RaiseEvent(tab);
                        Pump(16);
                        if (!tab.Handled || editor.IsKeyboardFocused || Math.Abs(currentScore() - score) > 0.0001D)
                            throw new InvalidOperationException($"Tool Tab did not commit and move focus: {menu}/{placement}/{theme}, Handled={tab.Handled}, Focus={editor.IsKeyboardFocused}, Score={currentScore()}/{score}.");
                        if (host.NativePreviewRunCount != runs || host.HostLayerRowCount != layers || host.DirectResultRouteText != route
                            || host.ActiveRecipeContextLayerNameForTest != activeLayer || host.ActiveNativeResultReviewText != result)
                            throw new InvalidOperationException($"Tool keyboard navigation state changed: {menu}/{placement}/{theme}; Runs={host.NativePreviewRunCount}/{runs}; Layers={host.HostLayerRowCount}/{layers}; Route='{host.DirectResultRouteText}'/'{route}'; Active='{host.ActiveRecipeContextLayerNameForTest}'/'{activeLayer}'; Review='{host.ActiveNativeResultReviewText}'/'{result}'.");
                        keyboardResults.Add($"PASS: {menu}/{placement}/{theme}; SCORE_MIN {score:0.00}; Tab handled; focus moved; same grid/parameter; execution/layers/routing/result unchanged.");
                    }
                }
            }
            File.WriteAllLines(Path.ChangeExtension(outputPath, ".keyboard.txt"), keyboardResults);
        });
    }

    private static CaptureResult CaptureToolPanelEmptyQuick(string outputPath, int width, int height)
    {
        OpenVisionLanguageService.SetLanguage(OpenVisionLanguage.Korean, false);
        OpenVisionShellHostView host = CreateShellHost("Smoke_WorkbenchEmptyQuick", seedMainLayer: false);
        VISION_MENU[] expectedMenus = { VISION_MENU.Threshold, VISION_MENU.Filter, VISION_MENU.Blob, VISION_MENU.Matching, VISION_MENU.Line };
        List<string> checks = new();
        return CaptureWindowWithContent(host, outputPath, width, height, () =>
        {
            int runs = host.NativePreviewRunCount;
            int layers = host.LayerDocumentCount;
            string activeLayer = host.ActiveRecipeContextLayerNameForTest;
            foreach (bool light in new[] { false, true })
            {
                host.Resources.MergedDictionaries.Add(new ResourceDictionary
                {
                    Source = new Uri("pack://application:,,,/OpenVisionLab;component/UI/Wpf/OpenVisionWorkbench" + (light ? "Light" : "Dark") + ".xaml")
                });
                foreach (OpenVisionLanguage language in new[] { OpenVisionLanguage.Korean, OpenVisionLanguage.English })
                {
                    OpenVisionLanguageService.SetLanguage(language, false);
                    Pump(8);
                    OpenVisionShellPreviewViewModel model = (OpenVisionShellPreviewViewModel)host.DataContext;
                    if (!model.QuickToolItems.Select(item => item.Menu).SequenceEqual(expectedMenus))
                        throw new InvalidOperationException("Empty panel quick tool order changed.");
                    foreach (VISION_MENU menu in expectedMenus)
                    {
                        Button button = FindVisualChildren<Button>(host).Single(item => AutomationProperties.GetAutomationId(item) == "WorkbenchQuickTool_" + menu);
                        OpenVisionShellNavItem canonical = model.NavigationGroups.SelectMany(group => group.Items).Single(item => item.Menu == menu);
                        if (!button.IsVisible || !button.IsEnabled || !ReferenceEquals(button.Command, model.SelectToolCommand)
                            || !ReferenceEquals(button.CommandParameter, canonical) || AutomationProperties.GetName(button) != canonical.Title)
                            throw new InvalidOperationException("Quick tool lost its canonical binding: " + menu);
                        ItemsControl quickTools = FindVisualChildren<ItemsControl>(host).Single(item => AutomationProperties.GetAutomationId(item) == "WorkbenchQuickTools");
                        Rect bounds = button.TransformToAncestor(quickTools).TransformBounds(new Rect(0D, 0D, button.ActualWidth, button.ActualHeight));
                        if (bounds.Left < -1D || bounds.Top < -1D || bounds.Right > quickTools.ActualWidth + 1D || bounds.Bottom > quickTools.ActualHeight + 1D)
                            throw new InvalidOperationException("Quick tool is outside its wrapping container: " + menu);
                        if (!button.Focus() || !button.IsKeyboardFocused) throw new InvalidOperationException("Quick tool cannot receive keyboard focus: " + menu);
                        button.Command.Execute(button.CommandParameter);
                        Pump(12);
                        if (!ReferenceEquals(model.SelectedItem, canonical) || !host.IsDockedToolInspectorVisibleForTest
                            || CountVisibleFloatingToolWindows() != 0)
                            throw new InvalidOperationException("Quick tool did not open one default docked view: " + menu);
                        if (host.NativePreviewRunCount != runs || host.LayerDocumentCount != layers || host.ActiveRecipeContextLayerNameForTest != activeLayer)
                            throw new InvalidOperationException("Quick tool selection executed or changed layers: " + menu);
                        if (!host.CloseActiveWpfToolWindowForTest()) throw new InvalidOperationException("Quick tool failed to close: " + menu);
                        Pump(8);
                        checks.Add($"PASS: {width}x{height}/{(light ? "Light" : "Dark")}/{language}/{menu}; canonical localized command; visible wrap; focus; one docked view; no execution/layer change; close.");
                    }
                    ScreenshotPngWriter.WriteElementPng(host, Path.ChangeExtension(outputPath, $".{(light ? "light" : "dark")}.{language}.png"), width, height);
                }
            }
            OpenVisionLanguageService.SetLanguage(OpenVisionLanguage.Korean, false);
            host.Resources.MergedDictionaries.Add(new ResourceDictionary { Source = new Uri("pack://application:,,,/OpenVisionLab;component/UI/Wpf/OpenVisionWorkbenchDark.xaml") });
            Pump(8);
            Button toggle = FindVisualChildren<Button>(host).Single(item => AutomationProperties.GetAutomationId(item) == "WorkbenchEmptyToolPanelToggle");
            if (!ReferenceEquals(toggle.Command, host.Workbench.ToggleRightPanelCommand)) throw new InvalidOperationException("Empty panel toggle lost its layout command.");
            toggle.Command.Execute(null); Pump(4);
            if (!host.Workbench.IsRightCollapsed) throw new InvalidOperationException("Empty panel did not collapse.");
            host.Workbench.ToggleRightPanelCommand.Execute(null); Pump(4);
            if (host.Workbench.IsRightCollapsed || host.NativePreviewRunCount != runs || host.LayerDocumentCount != layers)
                throw new InvalidOperationException("Empty panel expansion changed execution or layers.");
            File.WriteAllLines(Path.ChangeExtension(outputPath, ".checks.txt"), checks);
        });
    }

    private static CaptureResult CaptureWorkbenchSimpleChoiceInteraction(string outputPath, bool lightMeanOnly = false)
    {
        OpenVisionLanguageService.SetLanguage(OpenVisionLanguage.Korean, false);
        string recipeName = "Smoke_SimpleChoice_" + Guid.NewGuid().ToString("N");
        OpenVisionShellHostView host = CreateShellHost(recipeName, seedMainLayer: false);
        return CaptureWindowWithContent(host, outputPath, 1920, 1032, () =>
        {
            string recipeRoot = RecipeWorkspaceService.GetRecipeWorkspaceDirectory(recipeName);
            Dictionary<string, string> beforeFiles = Directory.EnumerateFiles(recipeRoot, "*", SearchOption.AllDirectories)
                .ToDictionary(Path.GetFullPath, path => Convert.ToHexString(SHA256.HashData(File.ReadAllBytes(path))));
            int layers = host.LayerDocumentCount;
            int steps = host.Workbench.Pipeline.StepCount;
            string routeBeforeToolSelection = host.DirectResultRouteText;
            List<string> checks = new();
            IEnumerable<ResourceDictionary> ThemeDictionaries(ResourceDictionary current)
            {
                yield return current;
                foreach (ResourceDictionary merged in current.MergedDictionaries)
                    foreach (ResourceDictionary nested in ThemeDictionaries(merged)) yield return nested;
            }
            foreach (string theme in new[] { "Dark", "Light" })
            foreach (OpenVisionLanguage language in new[] { OpenVisionLanguage.Korean, OpenVisionLanguage.English })
            foreach ((int width, int height) in new[] { (1920, 1032), (1280, 760) })
            foreach ((VISION_MENU menu, string name) in new[] { (VISION_MENU.EdgeDetection, "cbEdgeType"), (VISION_MENU.Mean, "cbMeanType"), (VISION_MENU.Histogram, "cbHistogramType") })
            {
                if (lightMeanOnly && (theme != "Light" || language != OpenVisionLanguage.Korean || width != 1920 || menu != VISION_MENU.Mean)) { continue; }
                Window window = Window.GetWindow(host);
                window.Width = width; window.Height = height;
                (theme == "Light" ? host.Workbench.SelectLightThemeCommand : host.Workbench.SelectDarkThemeCommand).Execute(null); Pump(4);
                OpenVisionLanguageService.SetLanguage(language, false);
                host.SelectToolForTest(menu); Pump(10);
                OpenVisionNativeToolDocument document = host.ActiveNativeDocumentForTest!;
                SimplePreprocessToolWpfView view = (SimplePreprocessToolWpfView)document.View;
                ComboBox choice = FindNamedVisualChild<ComboBox>(view, name) ?? throw new InvalidOperationException(menu + ": choice missing");
                ResourceDictionary themeOwner = ThemeDictionaries(view.Resources).First(dictionary => dictionary.Source?.OriginalString.EndsWith("OpenVisionLabWpfTheme.xaml", StringComparison.Ordinal) == true);
                ResourceDictionary toolThemeOwner = ThemeDictionaries(view.Resources).First(dictionary => dictionary.Source?.OriginalString.EndsWith("VisionToolWpfTheme.xaml", StringComparison.Ordinal) == true);
                ResourceDictionary palette = new() { Source = new Uri($"pack://application:,,,/OpenVisionLab;component/UI/Wpf/OpenVisionWorkbench{theme}.xaml") };
                toolThemeOwner.MergedDictionaries.Add(palette);
                themeOwner.MergedDictionaries.Add(palette);
                view.Resources.MergedDictionaries.Add(palette);
                Application.Current.Resources.MergedDictionaries.Add(palette);
                try
                {
                    Pump(6);
                    string route = host.DirectResultRouteText;
                    int runs = document.PreviewRunCount;
                    object selected = choice.SelectedItem;
                    string settings = JsonSerializer.Serialize(view.Parameters.CaptureSettings());
                    MouseButtonEventArgs click = new(Mouse.PrimaryDevice, Environment.TickCount, MouseButton.Left) { RoutedEvent = UIElement.PreviewMouseLeftButtonDownEvent, Source = choice };
                    choice.RaiseEvent(click); Pump(8);
                    if (!choice.IsDropDownOpen || !click.Handled) { throw new InvalidOperationException(menu + ": field PreviewDown did not open and consume the click"); }
                    Popup popup = (Popup)choice.Template.FindName("PART_Popup", choice);
                    if (!ReferenceEquals(popup.PlacementTarget, choice) || popup.Child is not Grid popupRoot || popupRoot.ActualWidth < choice.ActualWidth - 1D)
                        throw new InvalidOperationException(menu + ": popup lost its owner or width");
                    Border chrome = popupRoot.Children.OfType<Border>().Single();
                    Color expected = ((SolidColorBrush)palette["OpenVision.Workbench.PanelAltBrush"]).Color;
                    string suffix = $".{theme}.{language}.{width}.{menu}";
                    ScreenshotPngWriter.WriteVisibleElementPng(popupRoot, Path.ChangeExtension(outputPath, suffix + ".popup.png"));
                    File.WriteAllText(Path.ChangeExtension(outputPath, suffix + ".theme-owner.json"), JsonSerializer.Serialize(new {
                        Theme = theme, Tool = menu.ToString(), ToolThemeSource = toolThemeOwner.Source?.OriginalString,
                        ExpectedPanelColor = expected.ToString(), ChoiceColor = choice.FindResource("OpenVision.Workbench.PanelAltBrush.Color").ToString(),
                        ToolPanelBrush = ((SolidColorBrush)toolThemeOwner["VisionTool.PanelBrush"]).Color.ToString(), PopupBackground = chrome.Background?.ToString(),
                        SameToolPanelBrush = ReferenceEquals(chrome.Background, toolThemeOwner["VisionTool.PanelBrush"])
                    }, new JsonSerializerOptions { WriteIndented = true }));
                    if ((Color)choice.FindResource("OpenVision.Workbench.PanelAltBrush.Color") != expected) { throw new InvalidOperationException(menu + ": theme fixture did not reach the actual choice resource scope"); }
                    if (chrome.Background is not SolidColorBrush background || background.Color != expected) { throw new InvalidOperationException(menu + ": popup theme fixture/background mismatch: " + theme + "/" + chrome.Background); }
                    foreach (ComboBoxItem item in Enumerable.Range(0, choice.Items.Count).Select(index => choice.ItemContainerGenerator.ContainerFromIndex(index)).OfType<ComboBoxItem>())
                    {
                        TextBlock caption = FindVisualChildren<TextBlock>(item).First();
                        Border itemChrome = (Border)item.Template.FindName("itemChrome", item);
                        if (caption.Foreground is not SolidColorBrush foreground || itemChrome.Background is not SolidColorBrush itemBrush || chrome.Background is not SolidColorBrush popupBrush)
                            throw new InvalidOperationException(menu + ": popup item brush unavailable");
                        double alpha = itemBrush.Color.A / 255D;
                        Color renderedBackground = Color.FromRgb(
                            (byte)Math.Round(itemBrush.Color.R * alpha + popupBrush.Color.R * (1D - alpha)),
                            (byte)Math.Round(itemBrush.Color.G * alpha + popupBrush.Color.G * (1D - alpha)),
                            (byte)Math.Round(itemBrush.Color.B * alpha + popupBrush.Color.B * (1D - alpha)));
                        if (GetContrastRatio(foreground.Color, renderedBackground) < 4.5D)
                            throw new InvalidOperationException(menu + ": unreadable popup item");
                        FormattedText size = new(caption.Text, CultureInfo.CurrentCulture, caption.FlowDirection, new Typeface(caption.FontFamily, caption.FontStyle, caption.FontWeight, caption.FontStretch), caption.FontSize, caption.Foreground, VisualTreeHelper.GetDpi(caption).PixelsPerDip);
                        if (caption.ActualWidth + 1D < size.Width || caption.ActualHeight + 1D < size.Height) { throw new InvalidOperationException(menu + ": clipped popup caption"); }
                    }
                    choice.IsDropDownOpen = false; Pump(4);
                    choice.IsEnabled = false;
                    choice.RaiseEvent(new MouseButtonEventArgs(Mouse.PrimaryDevice, Environment.TickCount, MouseButton.Left) { RoutedEvent = UIElement.PreviewMouseLeftButtonDownEvent, Source = choice }); Pump(4);
                    if (choice.IsDropDownOpen) { throw new InvalidOperationException(menu + ": disabled choice opened"); }
                    choice.IsEnabled = true;
                    AssertComboBoxOpensFromPreviewMouseClick(choice, menu + " enabled recovery");
                    AssertComboBoxSelectionTextVisible(choice, menu + " selection after close");
                    File.WriteAllText(Path.ChangeExtension(outputPath, suffix + ".state.json"), JsonSerializer.Serialize(new {
                        RouteBeforeToolSelection = routeBeforeToolSelection, RouteBeforeOpen = route, RouteAfterClose = host.DirectResultRouteText,
                        SelectedBefore = selected.ToString(), SelectedAfter = choice.SelectedItem?.ToString(), SettingsBefore = settings, SettingsAfter = JsonSerializer.Serialize(view.Parameters.CaptureSettings()),
                        RunsBefore = runs, RunsAfter = document.PreviewRunCount, LayersBefore = layers, LayersAfter = host.LayerDocumentCount, StepsBefore = steps, StepsAfter = host.Workbench.Pipeline.StepCount
                    }, new JsonSerializerOptions { WriteIndented = true }));
                    if (!Equals(choice.SelectedItem, selected) || JsonSerializer.Serialize(view.Parameters.CaptureSettings()) != settings || document.PreviewRunCount != runs
                        || host.LayerDocumentCount != layers || host.Workbench.Pipeline.StepCount != steps || host.DirectResultRouteText != route)
                        throw new InvalidOperationException(menu + ": open/close/disabled/recovery changed selection, settings, execution, layers or route");
                    Dictionary<string, string> afterFiles = Directory.EnumerateFiles(recipeRoot, "*", SearchOption.AllDirectories)
                        .ToDictionary(Path.GetFullPath, path => Convert.ToHexString(SHA256.HashData(File.ReadAllBytes(path))));
                    if (beforeFiles.Count != afterFiles.Count || beforeFiles.Any(pair => !afterFiles.TryGetValue(pair.Key, out string? hash) || pair.Value != hash))
                        throw new InvalidOperationException(menu + ": opening wrote recipe files");
                    checks.Add(suffix + ": PASS; in-process routed PreviewDown/disabled/recovery, actual popup palette/caption bounds/contrast, unchanged selection/settings/run/layers/route/files; native mouse and key states reported separately");
                    File.WriteAllLines(Path.ChangeExtension(outputPath, ".checks.txt"), checks);
                }
                finally { choice.IsDropDownOpen = false; choice.IsEnabled = true; Application.Current.Resources.MergedDictionaries.Remove(palette); view.Resources.MergedDictionaries.Remove(palette); themeOwner.MergedDictionaries.Remove(palette); toolThemeOwner.MergedDictionaries.Remove(palette); }
            }
            OpenVisionLanguageService.SetLanguage(OpenVisionLanguage.Korean, false);
            File.WriteAllLines(Path.ChangeExtension(outputPath, ".checks.txt"), checks);
        });
    }

    private static CaptureResult CaptureWorkbenchChoiceKeyboardInput(string outputPath, VISION_MENU menu, string choiceKey, string modelKey, string expected)
    {
        OpenVisionLanguageService.SetLanguage(OpenVisionLanguage.Korean, false);
        string recipeName = "Smoke_" + menu + "ChoiceInput_" + Guid.NewGuid().ToString("N")[..12];
        OpenVisionShellHostView host = CreateShellHost(recipeName, seedMainLayer: false);
        return CaptureWindowWithContent(host, outputPath, 1280, 760, () =>
        {
            Window window = Window.GetWindow(host);
            window.Title = edgeTitle();
            window.ShowInTaskbar = true;
            host.SelectToolForTest(menu); Pump(12);
            OpenVisionNativeToolDocument document = host.ActiveNativeDocumentForTest!;
            SimplePreprocessToolWpfView view = (SimplePreprocessToolWpfView)document.View;
            ComboBox choice = FindNamedVisualChild<ComboBox>(view, "cb" + choiceKey)!;
            bool edge = menu == VISION_MENU.EdgeDetection;
            string[] visibleKeys = expected switch
            {
                nameof(EdgeDetectionToolType.Scharr) => new[] { "EdgeType", "ScharrDegreeX", "ScharrDegreeY" },
                nameof(EdgeDetectionToolType.Laplacian) => new[] { "EdgeType", "LaplacianKernelSize" },
                _ => new[] { "EdgeType", "SobelDegreeX", "SobelDegreeY", "SobelKernelSize" }
            };
            Dictionary<string, int> expectedValues = expected switch
            {
                nameof(EdgeDetectionToolType.Scharr) => new() { ["ScharrDegreeX"] = 0, ["ScharrDegreeY"] = 1 },
                nameof(EdgeDetectionToolType.Laplacian) => new() { ["LaplacianKernelSize"] = 7 },
                _ => new() { ["SobelDegreeX"] = 2, ["SobelDegreeY"] = 0, ["SobelKernelSize"] = 3 }
            };
            string[] edgeKeys = { "EdgeType", "CannyThresholdLow", "CannyThresholdHigh", "CannyApertureSize", "UseL2Gradient", "SobelDegreeX", "SobelDegreeY", "SobelKernelSize", "ScharrDegreeX", "ScharrDegreeY", "LaplacianKernelSize" };
            IReadOnlyDictionary<FrameworkElement, string> parameterControls = view.Parameters.CreateParameterGuideBindings(edge ? edgeKeys : Array.Empty<string>());
            bool initialParameters = !edge || VisibleParametersMatch("EdgeType", "CannyThresholdLow", "CannyThresholdHigh", "CannyApertureSize", "UseL2Gradient");
            bool restoredParameters = !edge;
            string recipeRoot = RecipeWorkspaceService.GetRecipeWorkspaceDirectory(recipeName);
            Dictionary<string, string> files = Directory.EnumerateFiles(recipeRoot, "*", SearchOption.AllDirectories)
                .ToDictionary(Path.GetFullPath, path => Convert.ToHexString(SHA256.HashData(File.ReadAllBytes(path))));
            int runs = document.PreviewRunCount;
            int layers = host.LayerDocumentCount;
            int steps = host.Workbench.Pipeline.StepCount;
            string route = host.DirectResultRouteText;
            string status = document.LastStatusText;
            List<object> observations = new();
            List<string> keys = new();
            bool seenAway = false;
            bool seenReturn = false;
            bool finished = false;
            var frame = new System.Windows.Threading.DispatcherFrame();
            var timer = new System.Windows.Threading.DispatcherTimer { Interval = TimeSpan.FromMilliseconds(100) };
            DateTime deadline = DateTime.UtcNow.AddMinutes(8);
            KeyEventHandler input = (_, e) =>
            {
                keys.Add(e.Key.ToString());
                if (e.Key == Key.F9) { e.Handled = true; window.Dispatcher.BeginInvoke(new Action(() => Observe("checkpoint"))); }
                if (e.Key == Key.F12 && Keyboard.Modifiers == (ModifierKeys.Control | ModifierKeys.Shift))
                {
                    e.Handled = true;
                    finished = true;
                    frame.Continue = false;
                }
            };
            EventHandler changed = (_, _) => Observe("parameter-changed");
            timer.Tick += (_, _) =>
            {
                if (host.ActiveNativeDocumentForTest?.ToolName != document.ToolName) seenAway = true;
                else if (seenAway && !seenReturn)
                {
                    seenReturn = true;
                    restoredParameters = !edge || VisibleParametersMatch(visibleKeys) && ParameterValuesMatch();
                    Observe("returned");
                }
                if (DateTime.UtcNow >= deadline) frame.Continue = false;
            };
            window.AddHandler(Keyboard.PreviewKeyDownEvent, input, true);
            view.ParameterChanged += changed;
            try
            {
                Observe("normal");
                File.WriteAllText(Path.ChangeExtension(outputPath, ".input-ready.json"), JsonSerializer.Serialize(new
                {
                    ProcessId = Environment.ProcessId, Assembly = typeof(Program).Assembly.Location, ProductAssembly = typeof(OpenVisionShellHostView).Assembly.Location,
                    DataRoot = AppPathService.DataRootDirectory, RecipeName = recipeName, WpfDpi = VisualTreeHelper.GetDpi(view),
                    WindowTitle = window.Title, ExpectedChoice = expected, ExpectedDependentKeys = visibleKeys, ExpectedValues = expectedValues, Input = "Official Computer Use only; observer injects no input.",
                    Workflow = edge
                        ? $"Use Manual; choose {expected} with keyboard, F9; set {string.Join(", ", expectedValues.Select(pair => pair.Key + "=" + pair.Value))}, F9; visit Filter and return, F9; reopen, highlight an alternate then Esc, F9; Ctrl+Shift+F12 to finish."
                        : "Switch AUTO off with the real control; choose the first non-default Mean enum with keyboard, F9; visit another Tool and return, F9; reopen/Esc, F9; Ctrl+Shift+F12 to finish.",
                    Boundary = "Current in-process WPF test host, Dark/ko/Compact. Actual product EXE and other theme/language/layout/DPI states remain separate."
                }, new JsonSerializerOptions { WriteIndented = true }));
                timer.Start();
                System.Windows.Threading.Dispatcher.PushFrame(frame);
                Observe("final");
                string selected = choice.SelectedItem?.ToString() ?? string.Empty;
                string model = host.Workbench.Tool.CurrentStep?.Parameters.GetValueOrDefault(modelKey) ?? string.Empty;
                bool filesUnchanged = files.Count == Directory.EnumerateFiles(recipeRoot, "*", SearchOption.AllDirectories).Count()
                    && files.All(file => File.Exists(file.Key) && Convert.ToHexString(SHA256.HashData(File.ReadAllBytes(file.Key))) == file.Value);
                bool noAction = !host.Workbench.Tool.IsAutoRunEnabled && document.LastStatusText == status
                    && document.PreviewRunCount == runs && host.LayerDocumentCount == layers && host.Workbench.Pipeline.StepCount == steps && host.DirectResultRouteText == route;
                bool dependentParameters = !edge || VisibleParametersMatch(visibleKeys);
                bool numberValue = !edge || ParameterValuesMatch();
                bool passed = initialParameters && restoredParameters && dependentParameters && numberValue && finished && selected == expected && model == expected && seenReturn && keys.Contains(nameof(Key.Escape))
                    && keys.Contains(nameof(Key.Return)) && filesUnchanged && noAction;
                File.WriteAllText(Path.ChangeExtension(outputPath, ".input-checks.json"), JsonSerializer.Serialize(new
                {
                    Passed = passed, Finished = finished, InitialParameters = initialParameters, RestoredParameters = restoredParameters, DependentParameters = dependentParameters, NumberValue = numberValue, ExpectedChoice = expected, Selected = selected, Model = model, SeenAway = seenAway, SeenReturn = seenReturn,
                    Keys = keys, NoAction = noAction, FilesUnchanged = filesUnchanged, RunsBefore = runs, RunsAfter = document.PreviewRunCount,
                    AutoEnabled = host.Workbench.Tool.IsAutoRunEnabled, StatusBefore = status, StatusAfter = document.LastStatusText,
                    LayersBefore = layers, LayersAfter = host.LayerDocumentCount, StepsBefore = steps, StepsAfter = host.Workbench.Pipeline.StepCount,
                    RouteBefore = route, RouteAfter = host.DirectResultRouteText, Observations = observations
                }, new JsonSerializerOptions { WriteIndented = true }));
                if (!passed) throw new InvalidOperationException($"{menu} choice keyboard selection, dependent parameters, workbench restoration, cancel or no-action check failed; see input-checks.json.");
            }
            finally
            {
                timer.Stop();
                view.ParameterChanged -= changed;
                window.RemoveHandler(Keyboard.PreviewKeyDownEvent, input);
            }
            string edgeTitle() => menu == VISION_MENU.EdgeDetection && expected != nameof(EdgeDetectionToolType.Sobel)
                ? $"OpenVisionLab {menu} {expected} choice keyboard verification" : $"OpenVisionLab {menu} choice keyboard verification";
            bool ParameterValuesMatch() => expectedValues.All(pair => view.Parameters.GetInt(pair.Key, int.MinValue) == pair.Value
                && host.Workbench.Tool.CurrentStep?.Parameters.GetValueOrDefault(pair.Key) == pair.Value.ToString(CultureInfo.InvariantCulture));
            bool VisibleParametersMatch(params string[] expectedKeys)
            {
                return parameterControls.Count == edgeKeys.Length && parameterControls
                    .Where(pair => pair.Key.IsVisible).Select(pair => pair.Value).OrderBy(key => key)
                    .SequenceEqual(expectedKeys.OrderBy(key => key));
            }
            void Observe(string state)
            {
                string path = Path.ChangeExtension(outputPath, $".{observations.Count:D2}.{state}.png");
                if (view.IsVisible) ScreenshotPngWriter.WriteVisibleElementPng(view, path);
                observations.Add(new
                {
                    State = state, Utc = DateTime.UtcNow, Selected = choice.SelectedItem?.ToString(), Open = choice.IsDropDownOpen,
                    Model = host.Workbench.Tool.CurrentStep?.Parameters.GetValueOrDefault(modelKey),
                    Tool = host.ActiveNativeDocumentForTest?.ToolName, SameView = ReferenceEquals(host.ActiveNativeDocumentForTest?.View, view),
                    Runs = document.PreviewRunCount, Layers = host.LayerDocumentCount, Steps = host.Workbench.Pipeline.StepCount, Route = host.DirectResultRouteText,
                    AutoEnabled = host.Workbench.Tool.IsAutoRunEnabled, Status = document.LastStatusText,
                    Parameters = host.Workbench.Tool.CurrentStep?.Parameters.ToDictionary(pair => pair.Key, pair => pair.Value),
                    DependentControls = parameterControls.ToDictionary(pair => pair.Value, pair => new
                    {
                        pair.Key.Name, pair.Key.IsVisible, Value = pair.Key is TextBox number ? number.Text : pair.Key is CheckBox check ? check.IsChecked?.ToString() : null
                    }),
                    Capture = File.Exists(path) ? path : null
                });
                File.WriteAllText(Path.ChangeExtension(outputPath, ".observations.json"), JsonSerializer.Serialize(observations, new JsonSerializerOptions { WriteIndented = true }));
            }
        });
    }

