    private static CaptureResult CaptureWorkbenchFilterRestore(string outputPath)
    {
        List<object> checks = new();
        void Require(bool passed, string name) { if (!passed) { throw new InvalidOperationException("Filter restore: " + name); } checks.Add(new { Case = name, PASS = true }); }
        var groups = OpenVisionShellCommandCatalog.CreateNavigationGroups();
        OpenVisionShellNavItem item = groups.SelectMany(group => group.Items).Single(tool => tool.Menu == VISION_MENU.Filter);
        foreach ((int width, int height) in new[] { (2, 3), (3, 5) })
        {
            string recipe = "Smoke_FilterRestore_" + width + "x" + height + "_" + Guid.NewGuid().ToString("N");
            VisionPipeline saved = new() { Name = "Main" };
            saved.Steps.Add(new VisionPipelineStep { Name = "Owned Gaussian", ToolType = "Filter", InputLayer = "Main", OutputLayer = "OwnedFilter", Parameters = { ["FilterType"] = "GaussianBlur", ["KernelWidth"] = width.ToString(CultureInfo.InvariantCulture), ["KernelHeight"] = height.ToString(CultureInfo.InvariantCulture), ["BorderType"] = "Default" } });
            VisionPipelineStorage.Save(recipe, saved); VisionPipelineStorage.SaveActivePipelineName(recipe, "Main");
            OpenVisionShellHostRecipeCommandSurface recipes = new(() => recipe, name => recipe = name, () => { });
            using DisplayManagerService display = new();
            Bitmap image = new(32, 24); using (Graphics graphics = Graphics.FromImage(image)) { graphics.Clear(DrawingColor.Gray); }
            display.CreateLayerDisplay(OpenVisionLab.ImageSpace.Core.ImageSpaceFrame.TakeOwnership(image), "Main");
            using OpenVisionWorkbenchPipelineViewModel pipeline = new(recipes, display, action => action(), _ => OpenVisionRecipePendingEditDecision.Cancel, _ => true, groups);
            recipes.AttachWorkbenchPipeline(pipeline);
            using OpenVisionWorkbenchToolViewModel tool = new(pipeline);
            using OpenVisionNativeToolDocument document = OpenVisionNativeCustomToolFactory.CreateFilter(display, forWorkbench: true);
            document.ApplyRecipeContext(new OpenVisionRecipeContext(recipe, recipe, "Main", RecipeWorkspaceService.GetVisionPipelinePath(recipe, "Main"), false, "Main", string.Empty));
            FilterToolWpfView view = (FilterToolWpfView)document.View;
            VisionToolSingleInputPropertyToolShell shell = (VisionToolSingleInputPropertyToolShell)view.FindName("toolShell");
            TextBox widthBox = (TextBox)view.FindName("txtWidth"), heightBox = (TextBox)view.FindName("txtHeight"); CheckBox locked = (CheckBox)view.FindName("chkLockSize");
            string path = RecipeWorkspaceService.GetVisionPipelinePath(recipe, "Main"); byte[] disk = File.ReadAllBytes(path), working = VisionPipelineExecutionPlan.SerializePipeline(pipeline.WorkingCopyForTest);
            VisionPipelineStepResultSummary retained = new() { Executed = true, Success = false }; pipeline.PublishToolResult(0, retained);
            int layers = display.LayerCount; long revision = pipeline.RecipeRevision;
            foreach (bool reopen in new[] { false, true })
            {
                if (reopen) { document.DeactivateWorkbenchEditor(); }
                document.ActivateWorkbenchEditor(tool, item, 0); shell.IsDockedInspectorMode = false; shell.IsDockedInspectorMode = true; Pump(12);
                foreach (string theme in new[] { "Dark", "Light", "Dark" })
                {
                    OpenVisionWorkbenchThemeBehavior.SetThemeName(view, theme);
                    OpenVisionWorkbenchThemeBehavior.SetThemeName((FrameworkElement)view.FindName("toolShell"), theme); Pump(6);
                    string capturePath = Path.ChangeExtension(outputPath, $".{width}x{height}.{(reopen ? "reopen" : "open")}.{theme}.png");
                    CaptureElement(view, capturePath, 1000, 760); Pump(6);
                    foreach (ComboBox combo in new[] { (ComboBox)view.FindName("cbFilterType"), (ComboBox)view.FindName("cbBorderType"), (ComboBox)shell.FindName("cbInputLayer"), (ComboBox)shell.FindName("cbOutputLayer") })
                    {
                        bool editable = combo.IsEditable;
                        foreach (bool mode in new[] { false, true })
                        {
                            combo.IsEditable = mode; view.UpdateLayout(); Pump(2);
                            ToggleButton toggle = (ToggleButton)combo.Template.FindName("toggleButton", combo);
                            Rect bounds = toggle.TransformToAncestor(combo).TransformBounds(new Rect(0, 0, toggle.ActualWidth, toggle.ActualHeight));
                            DependencyObject arrow = VisualTreeHelper.HitTest(combo, new System.Windows.Point(combo.ActualWidth - 15, combo.ActualHeight / 2))?.VisualHit ?? throw new InvalidOperationException(combo.Name + " arrow has no visual hit.");
                            DependencyObject field = VisualTreeHelper.HitTest(combo, new System.Windows.Point(10, combo.ActualHeight / 2))?.VisualHit ?? throw new InvalidOperationException(combo.Name + " field has no visual hit.");
                            Require(toggle.ActualHeight == combo.ActualHeight && Math.Abs(bounds.Y) < 0.1 && IsVisualAncestorOrSelf(toggle, arrow)
                                && (mode ? toggle.Width == 30 && toggle.HorizontalAlignment == HorizontalAlignment.Right && Math.Abs(bounds.Right - combo.ActualWidth) < 0.1 && !IsVisualAncestorOrSelf(toggle, field)
                                    : Math.Abs(bounds.X) < 0.1 && toggle.ActualWidth == combo.ActualWidth && IsVisualAncestorOrSelf(toggle, field)),
                                combo.Name + " " + theme + " editable=" + mode + " computed toggle covers intended field/arrow hit area; editable keeps Width30/Right");
                        }
                        combo.IsEditable = editable; view.UpdateLayout(); Pump(2);
                    }
                    FilterToolProperty property = view.CreateProperty();
                    Require(property.KernelWidth == width && property.KernelHeight == height && widthBox.Text == width.ToString(CultureInfo.InvariantCulture) && heightBox.Text == height.ToString(CultureInfo.InvariantCulture) && locked.IsChecked == false, $"{width}x{height} {reopen} {theme} native settings and controls preserve non-square dimensions");
                    Require(!pipeline.IsDirty && working.SequenceEqual(VisionPipelineExecutionPlan.SerializePipeline(pipeline.WorkingCopyForTest)) && disk.SequenceEqual(File.ReadAllBytes(path)) && pipeline.RecipeRevision == revision && ReferenceEquals(retained, pipeline.GetResult(0)) && !pipeline.IsResultPrevious(0), $"{width}x{height} {reopen} {theme} hydration leaves XML working baseline and retained result unchanged");
                    Require(document.PreviewRunCount == 0 && !pipeline.IsRunning && display.LayerCount == layers && pipeline.GetStep(0).InputLayer == "Main" && pipeline.GetStep(0).OutputLayer == "OwnedFilter", $"{width}x{height} {reopen} {theme} direct view restoration does not execute or alter layers/routes");
                    Color text = ((SolidColorBrush)view.FindResource("OpenVision.Workbench.TextBrush")).Color, secondary = ((SolidColorBrush)view.FindResource("OpenVision.Workbench.SecondaryTextBrush")).Color;
                    foreach (string name in new[] { "gbFilterOptions", "gbKernel" })
                    {
                        GroupBox group = (GroupBox)view.FindName(name);
                        Brush[] headerBrushes = FindVisualChildren<TextBlock>(group).Where(label => label.Text == group.Header.ToString()).Select(label => label.Foreground)
                            .Concat(FindVisualChildren<AccessText>(group).Where(label => label.Text == group.Header.ToString()).Select(label => label.Foreground)).ToArray();
                        Require(((SolidColorBrush)group.Foreground).Color == text && headerBrushes.Length > 0 && headerBrushes.All(brush => brush is SolidColorBrush solid && solid.Color == text), name + " " + theme + " actual generated header uses semantic foreground");
                    }
                    Require(((SolidColorBrush)((TextBlock)view.FindName("lblFilterType")).Foreground).Color == secondary && ((SolidColorBrush)((TextBlock)view.FindName("lblBorderType")).Foreground).Color == secondary, theme + " Filter/Border captions use semantic foreground");
                    Require(locked.ReadLocalValue(FrameworkElement.StyleProperty) is Style && locked.Template.FindName("checkChrome", locked) is Border, theme + " existing VisionTool checkbox template applied explicitly");
                    Border checkChrome = (Border)locked.Template.FindName("checkChrome", locked);
                    Require(((SolidColorBrush)checkChrome.Background).Color == ((SolidColorBrush)view.FindResource("OpenVision.Workbench.PanelAltBrush")).Color, theme + " unchecked checkbox chrome follows the local semantic panel color");
                }
            }
            locked.IsChecked = true; Pump(4);
            Require(view.CreateProperty().KernelHeight == width && pipeline.IsDirty, $"{width}x{height} explicit lock-on keeps existing height-to-width edit");
            widthBox.Text = "7"; widthBox.GetBindingExpression(TextBox.TextProperty)!.UpdateSource(); Pump(4);
            Require(view.CreateProperty().KernelWidth == 7 && view.CreateProperty().KernelHeight == 7 && pipeline.GetStep(0).Parameters["KernelHeight"] == "7", "explicit width edit under lock keeps coupled dimensions");
            locked.IsChecked = false; heightBox.Text = "9"; heightBox.GetBindingExpression(TextBox.TextProperty)!.UpdateSource(); Pump(4);
            Require(view.CreateProperty().KernelWidth == 7 && view.CreateProperty().KernelHeight == 9 && pipeline.GetStep(0).Parameters["KernelHeight"] == "9" && disk.SequenceEqual(File.ReadAllBytes(path)), "explicit unlocked height edit preserves independent width and never saves implicitly");
            CaptureElement(view, Path.ChangeExtension(outputPath, $".{width}x{height}.explicit-edits.png"), 1000, 760);
            recipes.DetachWorkbenchPipeline(pipeline);
        }
        File.WriteAllText(Path.ChangeExtension(outputPath, ".checks.json"), JsonSerializer.Serialize(new { Checks = checks, ProductSHA256 = Convert.ToHexString(SHA256.HashData(File.ReadAllBytes(typeof(FilterToolWpfView).Assembly.Location))), Scope = "Direct in-process STA Factory/Document/View/Tool/Pipeline binding and RenderTargetBitmap; no Window.Show/desktop EXE or real input. Unloaded scheduler cannot prove loaded auto-preview timing; parent owns actual runtime follow-up." }, new JsonSerializerOptions { WriteIndented = true }));
        return CaptureElement(new TextBlock { Text = "Filter non-square restore, explicit edit and local theme checks passed.", Foreground = Brushes.Black, Background = Brushes.White }, outputPath, 720, 100);
    }

    private static CaptureResult CaptureWorkbenchPropertyGridCollectionInputStates(string outputPath)
    {
        OpenVisionLanguageService.SetLanguage(OpenVisionLanguage.English, false);
        string recipeName = "Smoke_PgCollectionInput_" + Guid.NewGuid().ToString("N");
        OpenVisionShellHostView host = CreateShellHost(recipeName, seedMainLayer: false);
        return CaptureWindowWithContent(host, outputPath, 1920, 1032, () =>
        {
            Window inputWindow = Window.GetWindow(host);
            inputWindow.Title = "OpenVisionLab collection input verification";
            inputWindow.ShowInTaskbar = true;
            host.SelectToolForTest(VISION_MENU.Blob);
            Pump(18);
            OpenVisionLanguageService.SetLanguage(OpenVisionLanguage.English, false);
            Pump(18);
            OpenVisionNativeToolDocument document = host.ActiveNativeDocumentForTest!;
            var grid = FindVisualChildren<System.Windows.Controls.WpfPropertyGrid.PropertyGrid>(document.View).Single();
            VisionToolDebouncedPreviewScheduler.SetAllowAutoPreview(document.View, false);
            BlobProperty property = (BlobProperty)grid.SelectedObject;
            bool originalMultiRoi = property.USE_MULTI_ROI;
            List<OpenCvSharp.Rect> originalRois = property.CvROIS;
            property.USE_MULTI_ROI = true;
            property.CvROIS = new List<OpenCvSharp.Rect> { new(10, 20, 32, 44) };
            new PropertyGridEventBinder(null).ApplyVisibilityRules(grid);
            grid.RefreshSelectedObject();
            Pump(18);
            grid.ThemeVariant = System.Windows.Controls.WpfPropertyGrid.PropertyGridThemeVariant.Dark;
            Pump(18);
            if (!grid.FocusProperty("CvROIS")) throw new InvalidOperationException("ROI list row could not be focused.");
            Pump(12);
            Border row = FindVisualChildren<Border>(grid).Single(item => item.Name == "RowBorder"
                && (item.DataContext?.GetType().GetProperty("PropertyDescriptor")?.GetValue(item.DataContext) as PropertyDescriptor)?.Name == "CvROIS");
            Expander expander = FindVisualChildren<Expander>(row).Single(item => item.Header is TextBlock);
            TextBlock header = (TextBlock)expander.Header;
            ToggleButton toggle = FindVisualChildren<ToggleButton>(expander).Single(item => item.Name == "ExpanderToggleButton");
            ControlTemplate expanderTemplate = expander.Template;
            ControlTemplate toggleTemplate = toggle.Template;
            string valuesBefore = JsonSerializer.Serialize(property);
            int runs = document.PreviewRunCount;
            int layers = host.LayerDocumentCount;
            string route = host.DirectResultRouteText;
            string recipeDirectory = RecipeWorkspaceService.GetRecipeWorkspaceDirectory(recipeName);
            Dictionary<string, string> files = Directory.EnumerateFiles(recipeDirectory, "*", SearchOption.AllDirectories)
                .ToDictionary(Path.GetFullPath, path => Convert.ToHexString(SHA256.HashData(File.ReadAllBytes(path))));
            List<object> states = new();
            HashSet<string> captured = new();
            List<string> failures = new();
            bool actualPointerDown = false;
            bool actualKeyboardDown = false;
            bool realInputReady = false;
            DateTime? focusCaptureAt = null;
            DateTime? expandedCaptureAt = null;
            DateTime? collapsedCaptureAt = null;
            List<object> inputTrace = new();
            KeyboardFocusChangedEventHandler traceFocus = (_, args) => TraceInput("focus", args.NewFocus as FrameworkElement);
            KeyEventHandler traceKey = (_, args) => TraceInput("key:" + args.Key, Keyboard.FocusedElement as FrameworkElement);
            inputWindow.AddHandler(Keyboard.GotKeyboardFocusEvent, traceFocus, true);
            inputWindow.AddHandler(Keyboard.PreviewKeyDownEvent, traceKey, true);
            int valueChanges = 0;
            EventHandler<OpenVisionLab.PropertyGrid.PropertyGridPropertyValueChangedEventArgs> valueChanged = (_, _) => valueChanges++;
            var downDescriptor = DependencyPropertyDescriptor.FromProperty(ButtonBase.IsPressedProperty, typeof(ToggleButton));
            EventHandler down = (_, _) =>
            {
                if (!toggle.IsPressed) return;
                bool pointer = Mouse.LeftButton == MouseButtonState.Pressed;
                actualPointerDown |= pointer;
                actualKeyboardDown |= !pointer && Keyboard.IsKeyDown(Key.Space);
                Capture(pointer ? "pointer-down" : "keyboard-down");
            };
            MouseEventHandler enter = (_, _) => Capture("hover");
            MouseEventHandler leave = (_, _) => Capture("mouse-leave");
            KeyboardFocusChangedEventHandler focus = (_, _) => { if (realInputReady) focusCaptureAt = DateTime.UtcNow.AddMilliseconds(100); };
            RoutedEventHandler expanded = (_, _) => expandedCaptureAt = DateTime.UtcNow.AddMilliseconds(100);
            RoutedEventHandler collapsed = (_, _) => collapsedCaptureAt = DateTime.UtcNow.AddMilliseconds(100);
            var frame = new System.Windows.Threading.DispatcherFrame();
            var timer = new System.Windows.Threading.DispatcherTimer { Interval = TimeSpan.FromMilliseconds(100) };
            DateTime deadline = DateTime.UtcNow.AddMinutes(4);
            timer.Tick += (_, _) =>
            {
                DateTime now = DateTime.UtcNow;
                if (focusCaptureAt.HasValue && now >= focusCaptureAt.Value && toggle.IsKeyboardFocused && !toggle.IsPressed)
                {
                    Capture("focused");
                    focusCaptureAt = null;
                }
                if (expandedCaptureAt.HasValue && now >= expandedCaptureAt.Value && expander.IsExpanded)
                {
                    Capture("expanded");
                    expandedCaptureAt = null;
                }
                if (collapsedCaptureAt.HasValue && now >= collapsedCaptureAt.Value && !expander.IsExpanded)
                {
                    Capture("collapsed");
                    collapsedCaptureAt = null;
                }
                if (now >= deadline || actualPointerDown && actualKeyboardDown && !expander.IsExpanded
                    && new[] { "hover", "focused", "expanded", "collapsed", "mouse-leave" }.All(captured.Contains)
                    && Mouse.LeftButton == MouseButtonState.Released) frame.Continue = false;
            };
            grid.PropertyValueChanged += valueChanged;
            downDescriptor.AddValueChanged(toggle, down);
            toggle.MouseEnter += enter;
            toggle.MouseLeave += leave;
            toggle.GotKeyboardFocus += focus;
            expander.Expanded += expanded;
            expander.Collapsed += collapsed;
            try
            {
                Capture("normal");
                expander.IsEnabled = false;
                Pump(12);
                Capture("disabled");
                expander.IsEnabled = true;
                Pump(12);
                Capture("enabled-restored");
                if (!toggle.Focus() || !toggle.IsKeyboardFocused) throw new InvalidOperationException("Collection header could not receive the fixture starting focus.");
                Capture("starting-focus-fixture");
                realInputReady = true;
                File.WriteAllText(Path.ChangeExtension(outputPath, ".input-ready.json"), JsonSerializer.Serialize(new
                {
                    ProcessId = Environment.ProcessId, Assembly = typeof(Program).Assembly.Location,
                    Bridge = typeof(System.Windows.Controls.WpfPropertyGrid.PropertyGrid).Assembly.Location,
                    Input = "Official Computer Use only; observer creates no pointer or keyboard input.",
                    WindowTitle = inputWindow.Title, AutoPreviewSuppressedForVisualFixture = true,
                    StartingFocusFixture = "Header focus set before real input observation; this does not count as Computer Use focus verification.",
                    Expected = "Tab away and Shift+Tab back; Space to expand; click Details to collapse; click a neutral pane area to leave."
                }, new JsonSerializerOptions { WriteIndented = true }));
                timer.Start();
                System.Windows.Threading.Dispatcher.PushFrame(frame);
                if (!actualPointerDown || !actualKeyboardDown || expander.IsExpanded
                    || !new[] { "hover", "focused", "expanded", "collapsed", "mouse-leave" }.All(captured.Contains))
                    failures.Add("Required real collection input states or collapsed recovery missing.");
                grid.ThemeVariant = System.Windows.Controls.WpfPropertyGrid.PropertyGridThemeVariant.Default;
                Pump(18);
                Capture("default-restored");
                bool noAction = runs == document.PreviewRunCount && layers == host.LayerDocumentCount && route == host.DirectResultRouteText
                    && valueChanges == 0 && valuesBefore == JsonSerializer.Serialize(property);
                bool templatesStable = ReferenceEquals(expanderTemplate, expander.Template) && ReferenceEquals(toggleTemplate, toggle.Template);
                bool filesUnchanged = files.Count == Directory.EnumerateFiles(recipeDirectory, "*", SearchOption.AllDirectories).Count()
                    && files.All(file => File.Exists(file.Key) && Convert.ToHexString(SHA256.HashData(File.ReadAllBytes(file.Key))) == file.Value);
                if (!noAction || !templatesStable || !filesUnchanged) failures.Add("Collection input changed values, templates, execution, layers, route or recipe files.");
                File.WriteAllText(Path.ChangeExtension(outputPath, ".input-checks.json"), JsonSerializer.Serialize(new
                {
                    States = states, ActualPointerDown = actualPointerDown, ActualKeyboardDown = actualKeyboardDown,
                    NoAction = noAction, TemplatesStable = templatesStable, FilesUnchanged = filesUnchanged, ValueChanges = valueChanges, Failures = failures,
                    Boundary = "Real Computer Use on current test-host collection header; disabled/default are explicit render fixtures; production EXE, native125 and full-app Light are separate."
                }, new JsonSerializerOptions { WriteIndented = true }));
                if (failures.Count != 0) throw new InvalidOperationException(string.Join(Environment.NewLine, failures));
            }
            finally
            {
                timer.Stop();
                inputWindow.RemoveHandler(Keyboard.GotKeyboardFocusEvent, traceFocus);
                inputWindow.RemoveHandler(Keyboard.PreviewKeyDownEvent, traceKey);
                downDescriptor.RemoveValueChanged(toggle, down);
                toggle.MouseEnter -= enter;
                toggle.MouseLeave -= leave;
                toggle.GotKeyboardFocus -= focus;
                expander.Expanded -= expanded;
                expander.Collapsed -= collapsed;
                grid.PropertyValueChanged -= valueChanged;
                property.USE_MULTI_ROI = originalMultiRoi;
                property.CvROIS = originalRois;
            }
            void TraceInput(string action, FrameworkElement? focused)
            {
                inputTrace.Add(new { Action = action, Utc = DateTime.UtcNow, Name = focused?.Name, Type = focused?.GetType().FullName, HeaderFocused = ReferenceEquals(focused, toggle), inputWindow.IsActive, Stack = focused is Window ? Environment.StackTrace : null });
                File.WriteAllText(Path.ChangeExtension(outputPath, ".input-trace.json"), JsonSerializer.Serialize(inputTrace, new JsonSerializerOptions { WriteIndented = true }));
            }
            void Capture(string state)
            {
                if (!captured.Add(state)) return;
                List<object> textChecks = new();
                foreach (TextBlock text in FindVisualChildren<TextBlock>(expander).Where(item => item.IsVisible && !string.IsNullOrWhiteSpace(item.Text)))
                {
                    bool icon = text.FontFamily.Source == "pack://application:,,,/Wpf.Ui;component/Resources/Fonts/#FluentSystemIcons-Regular"
                        && text.Text.All(character => character >= '\uE000' && character <= '\uF8FF');
                    SolidColorBrush? background = FindOpaqueVisualBackground(text);
                    double ratio = text.Foreground is SolidColorBrush foreground && background != null ? GetContrastRatio(foreground.Color, background.Color) : 0;
                    textChecks.Add(new { text.Text, Icon = icon, Foreground = text.Foreground.ToString(), Background = background?.ToString(), Contrast = ratio, Font = text.FontFamily.Source });
                    if (ratio < (icon ? 3D : 4.5D)) failures.Add(state + ": collection text/icon contrast failed: " + text.Text + " = " + ratio.ToString("F3", CultureInfo.InvariantCulture));
                }
                Border[] focusBorders = (System.Windows.Documents.AdornerLayer.GetAdornerLayer(toggle)?.GetAdorners(toggle) ?? Array.Empty<System.Windows.Documents.Adorner>())
                    .SelectMany(adorner => FindVisualChildren<Border>(adorner))
                    .Where(item => item.IsVisible && item.BorderThickness.Left > 0 && item.BorderBrush is SolidColorBrush).ToArray();
                SolidColorBrush? focusBackground = FindOpaqueVisualBackground(toggle);
                var focusCues = focusBorders.Select(border => new
                {
                    Brush = border.BorderBrush.ToString(), border.BorderThickness,
                    Contrast = focusBackground == null ? 0 : GetContrastRatio(((SolidColorBrush)border.BorderBrush).Color, focusBackground.Color)
                }).ToArray();
                if (state == "focused" && !focusCues.Any(cue => cue.Contrast >= 3D)) failures.Add("Focused collection header has no readable rendered focus cue.");
                string capture = Path.ChangeExtension(outputPath, "." + state + ".png");
                ScreenshotPngWriter.WriteDpiAwareWindowPng(inputWindow, capture);
                states.Add(new { State = state, FocusCues = focusCues, ActualPointerDown = Mouse.LeftButton == MouseButtonState.Pressed, KeyboardSpaceDown = Keyboard.IsKeyDown(Key.Space),
                    toggle.IsPressed, toggle.IsMouseOver, toggle.IsKeyboardFocused, expander.IsExpanded, expander.IsEnabled, Header = header.Text, Text = textChecks, Capture = capture,
                    FocusedElement = (Keyboard.FocusedElement as FrameworkElement)?.Name, ExpanderForeground = expander.Foreground.ToString(), ToggleForeground = toggle.Foreground.ToString(),
                    HeaderControlAttached = FindVisualChildren<ToggleButton>(expander).Any(item => ReferenceEquals(item, toggle)) });
            }
        }, captureFloatingToolWindow: false);
    }

    private static CaptureResult CaptureWorkbenchButtonInputStates(string outputPath, string theme)
    {
        OpenVisionLanguageService.SetLanguage(OpenVisionLanguage.Korean, false);
        StackPanel content = new() { Margin = new Thickness(24) };
        content.Resources.MergedDictionaries.Add(new ResourceDictionary { Source = new Uri("pack://application:,,,/OpenVisionLab;component/UI/VisionTest/Wpf/Tooling/Presentation/VisionToolWpfTheme.xaml") });
        content.Resources.MergedDictionaries.Add(new ResourceDictionary { Source = new Uri($"pack://application:,,,/OpenVisionLab;component/UI/Wpf/OpenVisionWorkbench{theme}.xaml") });
        Border root = new() { Child = content };
        root.Background = (Brush)content.FindResource("VisionTool.SurfaceBrush");
        TextBlock heading = new() { Text = theme + " / actual button input", FontSize = 18, Margin = new Thickness(0, 0, 0, 16) };
        heading.SetResourceReference(TextBlock.ForegroundProperty, "VisionTool.PrimaryTextBrush");
        content.Children.Add(heading);
        List<Button> buttons = new();
        foreach (bool enabled in new[] { true, false })
        {
            StackPanel row = new() { Orientation = Orientation.Horizontal, Margin = new Thickness(0, 0, 0, 20) };
            content.Children.Add(row);
            foreach ((string name, bool primary, object key) in new (string, bool, object)[]
            {
                ("ToolSecondary", false, typeof(Button)), ("ToolPrimary", true, "VisionTool.PrimaryActionButtonStyle"),
                ("WorkbenchSecondary", false, "OpenVision.Workbench.ButtonStyle"), ("WorkbenchPrimary", true, "OpenVision.Workbench.PrimaryButtonStyle")
            })
            {
                TextBlock caption = new() { Text = OpenVisionLanguageService.T(primary ? "Workbench.Tool.RunTool" : "Workbench.Tool.NTest") };
                caption.SetBinding(TextBlock.ForegroundProperty, new Binding("Foreground") { RelativeSource = new RelativeSource(RelativeSourceMode.FindAncestor, typeof(Button), 1) });
                var icon = new MahApps.Metro.IconPacks.PackIconMaterial { Kind = primary ? MahApps.Metro.IconPacks.PackIconMaterialKind.Play : MahApps.Metro.IconPacks.PackIconMaterialKind.ImageMultiple, Width = 16, Height = 16, Margin = new Thickness(0, 0, 7, 0) };
                icon.SetBinding(Control.ForegroundProperty, new Binding("Foreground") { RelativeSource = new RelativeSource(RelativeSourceMode.FindAncestor, typeof(Button), 1) });
                StackPanel label = new() { Orientation = Orientation.Horizontal };
                label.Children.Add(icon);
                label.Children.Add(caption);
                Button button = new() { Name = name + (enabled ? "" : "Disabled"), Content = label,
                    Width = 230, Height = 42, Margin = new Thickness(0, 0, 24, 0), IsEnabled = enabled,
                    Style = (Style)content.FindResource(key) };
                row.Children.Add(button);
                buttons.Add(button);
            }
        }
        return CaptureWindowWithContent(root, outputPath, 1100, 340, () =>
        {
            Window window = Window.GetWindow(root);
            window.Title = "OpenVisionLab shared button input " + theme;
            window.ShowInTaskbar = true;
            List<object> states = new();
            List<string> failures = new();
            HashSet<string> captured = new();
            Dictionary<string, int> clicks = buttons.ToDictionary(button => button.Name, _ => 0);
            HashSet<string> pointerDown = new();
            HashSet<string> keyboardDown = new();
            HashSet<string> disabledInputs = new();
            List<Action> release = new();
            var frame = new System.Windows.Threading.DispatcherFrame();
            var timer = new System.Windows.Threading.DispatcherTimer { Interval = TimeSpan.FromMilliseconds(100) };
            DateTime deadline = DateTime.UtcNow.AddMinutes(4);
            foreach (Button button in buttons)
            {
                Capture(button, button.IsEnabled ? "normal" : "disabled");
                MouseEventHandler enter = (_, _) => Capture(button, "hover");
                MouseEventHandler leave = (_, _) => Capture(button, "mouse-leave");
                KeyboardFocusChangedEventHandler focus = (_, _) => Capture(button, "focused");
                RoutedEventHandler click = (_, _) => clicks[button.Name]++;
                button.MouseEnter += enter;
                button.MouseLeave += leave;
                button.GotKeyboardFocus += focus;
                button.Click += click;
                release.Add(() => { button.MouseEnter -= enter; button.MouseLeave -= leave; button.GotKeyboardFocus -= focus; button.Click -= click; });
                var descriptor = DependencyPropertyDescriptor.FromProperty(ButtonBase.IsPressedProperty, typeof(Button));
                EventHandler changed = (_, _) =>
                {
                    if (!button.IsPressed) return;
                    bool pointer = Mouse.LeftButton == MouseButtonState.Pressed;
                    if (pointer) pointerDown.Add(button.Name); else if (Keyboard.IsKeyDown(Key.Space)) keyboardDown.Add(button.Name);
                    Capture(button, pointer ? "pointer-down" : "keyboard-down");
                };
                descriptor.AddValueChanged(button, changed);
                release.Add(() => descriptor.RemoveValueChanged(button, changed));
            }
            MouseButtonEventHandler disabledPointer = (_, args) =>
            {
                if (args.ChangedButton != MouseButton.Left || Mouse.LeftButton != MouseButtonState.Pressed) return;
                foreach (Button button in buttons.Where(item => !item.IsEnabled))
                {
                    Point origin = button.TranslatePoint(new Point(0, 0), root);
                    if (!new Rect(origin, new System.Windows.Size(button.ActualWidth, button.ActualHeight)).Contains(args.GetPosition(root))) continue;
                    disabledInputs.Add(button.Name);
                    Capture(button, "disabled-pointer");
                }
            };
            root.AddHandler(UIElement.PreviewMouseLeftButtonDownEvent, disabledPointer, true);
            release.Add(() => root.RemoveHandler(UIElement.PreviewMouseLeftButtonDownEvent, disabledPointer));
            timer.Tick += (_, _) =>
            {
                bool done = pointerDown.Count == 4 && keyboardDown.Count == 4 && disabledInputs.Count == 4
                    && buttons.Where(button => button.IsEnabled).All(button => captured.Contains(button.Name + "/mouse-leave") && clicks[button.Name] == 2);
                if (DateTime.UtcNow >= deadline || done && Mouse.LeftButton == MouseButtonState.Released) frame.Continue = false;
            };
            File.WriteAllText(Path.ChangeExtension(outputPath, ".input-ready.json"), JsonSerializer.Serialize(new
            {
                ProcessId = Environment.ProcessId, Assembly = typeof(Program).Assembly.Location, Theme = theme,
                Input = "Official external Computer Use only. This fixture generates no input, IsPressed state or product command.",
                Buttons = buttons.Select(button => new { button.Name, button.IsEnabled, Caption = ((StackPanel)button.Content).Children.OfType<TextBlock>().Single().Text }).ToArray()
            }, new JsonSerializerOptions { WriteIndented = true }));
            try { timer.Start(); System.Windows.Threading.Dispatcher.PushFrame(frame); }
            finally { timer.Stop(); foreach (Action detach in release) detach(); }
            if (pointerDown.Count != 4 || keyboardDown.Count != 4 || disabledInputs.Count != 4) failures.Add("Actual mouse/Space/disabled inputs missing.");
            foreach (Button button in buttons)
            {
                if (clicks[button.Name] != (button.IsEnabled ? 2 : 0)) failures.Add(button.Name + ": click count changed.");
                if (button.IsEnabled && !captured.Contains(button.Name + "/mouse-leave")) failures.Add(button.Name + ": mouse-leave recovery missing.");
            }
            File.WriteAllText(Path.ChangeExtension(outputPath, ".input-checks.json"), JsonSerializer.Serialize(new
            {
                Theme = theme, States = states, PointerDown = pointerDown, KeyboardDown = keyboardDown, DisabledInputs = disabledInputs,
                Clicks = clicks, Failures = failures, Boundary = "Shared-style fixture; no product execution, no pointer hold duration, native125 or whole-consumer proof."
            }, new JsonSerializerOptions { WriteIndented = true }));
            if (failures.Count != 0) throw new InvalidOperationException(string.Join(Environment.NewLine, failures));

            void Capture(Button button, string state)
            {
                if (!captured.Add(button.Name + "/" + state)) return;
                button.UpdateLayout();
                Border chrome = (Border)button.Template.FindName("buttonChrome", button);
                Border focus = (Border)button.Template.FindName("focusCue", button);
                var foreground = (SolidColorBrush)button.Foreground;
                var background = (SolidColorBrush)chrome.Background;
                TextBlock caption = ((StackPanel)button.Content).Children.OfType<TextBlock>().Single();
                var icon = ((StackPanel)button.Content).Children.OfType<MahApps.Metro.IconPacks.PackIconMaterial>().Single();
                double contrast = GetContrastRatio(foreground.Color, background.Color);
                string capture = Path.ChangeExtension(outputPath, "." + theme + "-" + button.Name + "-" + state + ".png");
                ScreenshotPngWriter.WriteVisibleElementPng(button, capture);
                states.Add(new { button.Name, State = state, button.IsPressed, button.IsMouseOver, button.IsKeyboardFocused, button.IsEnabled,
                    MouseLeftButton = Mouse.LeftButton.ToString(), SpaceDown = Keyboard.IsKeyDown(Key.Space), Foreground = foreground.Color.ToString(),
                    CaptionForeground = caption.Foreground.ToString(), IconForeground = icon.Foreground.ToString(), Background = background.Color.ToString(), Border = chrome.BorderBrush.ToString(),
                    FocusVisibility = focus.Visibility.ToString(), FocusBorder = focus.BorderBrush.ToString(), TextContrast = contrast, FontFamily = button.FontFamily.Source, Capture = capture });
                if (contrast < 4.5D || caption.Foreground.ToString() != foreground.ToString() || icon.Foreground.ToString() != foreground.ToString()) failures.Add(button.Name + "/" + state + ": text contrast or caption inheritance failed.");
                if (state.EndsWith("-down", StringComparison.Ordinal) && !button.IsPressed) failures.Add(button.Name + "/" + state + ": actual press not observed.");
                if (state == "focused" && focus.Visibility != Visibility.Visible) failures.Add(button.Name + ": focus cue not visible.");
            }
        }, captureFloatingToolWindow: false);
    }

    private static CaptureResult CaptureWorkbenchPropertyGridInputStates(string outputPath)
    {
        OpenVisionLanguageService.SetLanguage(OpenVisionLanguage.English, false);
        string recipeName = "Smoke_PgActualInput_" + Guid.NewGuid().ToString("N");
        OpenVisionShellHostView host = CreateShellHost(recipeName, seedMainLayer: false);
        return CaptureWindowWithContent(host, outputPath, 1920, 1032, () =>
        {
            Window inputWindow = Window.GetWindow(host);
            inputWindow.Title = "OpenVisionLab PropertyGrid input verification";
            inputWindow.ShowInTaskbar = true;
            host.SelectToolForTest(VISION_MENU.Blob);
            Pump(18);
            OpenVisionNativeToolDocument document = host.ActiveNativeDocumentForTest!;
            var grid = FindVisualChildren<System.Windows.Controls.WpfPropertyGrid.PropertyGrid>(document.View).Single();
            grid.ThemeVariant = System.Windows.Controls.WpfPropertyGrid.PropertyGridThemeVariant.Dark;
            VisionToolDebouncedPreviewScheduler.SetAllowAutoPreview(document.View, false);
            Pump(18);
            object selected = grid.SelectedObject;
            int runs = document.PreviewRunCount;
            int layers = host.LayerDocumentCount;
            string route = host.DirectResultRouteText;
            string recipeDirectory = RecipeWorkspaceService.GetRecipeWorkspaceDirectory(recipeName);
            Dictionary<string, string> files = Directory.EnumerateFiles(recipeDirectory, "*", SearchOption.AllDirectories)
                .ToDictionary(Path.GetFullPath, path => Convert.ToHexString(SHA256.HashData(File.ReadAllBytes(path))));
            CheckBox check = FindVisualChildren<CheckBox>(grid).First(item => item.IsVisible);
            Slider slider = FindVisualChildren<Slider>(grid).First(item => item.IsVisible);
            Thumb thumb = FindVisualChildren<Thumb>(slider).First();
            RepeatButton track = FindVisualChildren<RepeatButton>(slider).Last();
            Button dialog = FindVisualChildren<Button>(grid).First(item => item.IsVisible && item.Template.FindName("DialogChrome", item) is Border);
            ComboBox combo = FindVisualChildren<ComboBox>(grid).First(item => item.IsVisible);
            bool? initialCheck = check.IsChecked;
            double initialSlider = slider.Value;
            object initialCombo = combo.SelectedItem;
            List<object> states = new();
            HashSet<string> captured = new();
            HashSet<string> pressed = new();
            HashSet<string> pointerInputs = new();
            HashSet<string> keyboardPressed = new();
            List<Action> release = new();
            HashSet<Control> observed = new();
            bool hadResult = host.Workbench.Tool.HasResult;
            List<string> failures = new();
            var frame = new System.Windows.Threading.DispatcherFrame();
            var timer = new System.Windows.Threading.DispatcherTimer { Interval = TimeSpan.FromMilliseconds(100) };
            DateTime deadline = DateTime.UtcNow.AddMinutes(4);
            Observe(check, "checkbox", "CheckChrome", ButtonBase.IsPressedProperty);
            Observe(dialog, "dialog", "DialogChrome", ButtonBase.IsPressedProperty);
            Observe(track, "track", "TrackLine", ButtonBase.IsPressedProperty);
            Observe(thumb, "thumb", "ThumbChrome", Thumb.IsDraggingProperty);
            Observe(combo, "combo", "ComboChrome", null);
            MouseButtonEventHandler pointerInput = (_, args) =>
            {
                if (args.ChangedButton != MouseButton.Left || Mouse.LeftButton != MouseButtonState.Pressed) return;
                RefreshControls();
                if (dialog.IsMouseOver) Capture(dialog, "dialog", "DialogChrome", "pointer-input", true);
                if (track.IsMouseOver) Capture(track, "track", "TrackLine", "pointer-input", true);
                if (thumb.IsMouseOver) pointerInputs.Add("thumb");
                if (check.IsMouseOver) pointerInputs.Add("checkbox");
                if (combo.IsMouseOver) pointerInputs.Add("combo");
            };
            grid.AddHandler(UIElement.PreviewMouseLeftButtonDownEvent, pointerInput, true);
            release.Add(() => grid.RemoveHandler(UIElement.PreviewMouseLeftButtonDownEvent, pointerInput));
            timer.Tick += (_, _) =>
            {
                RefreshControls();
                if (DateTime.UtcNow >= deadline || pointerInputs.Count == 5 && pressed.Contains("checkbox") && pressed.Contains("thumb")
                    && keyboardPressed.Contains("dialog") && Mouse.LeftButton == MouseButtonState.Released
                    && check.IsChecked == initialCheck && slider.Value == initialSlider && Equals(combo.SelectedItem, initialCombo)
                    && !combo.IsDropDownOpen && Application.Current.Windows.OfType<Window>().Count(item => item.IsVisible) == 1)
                    frame.Continue = false;
            };
            File.WriteAllText(Path.ChangeExtension(outputPath, ".input-ready.json"), JsonSerializer.Serialize(new
            {
                ProcessId = Environment.ProcessId, Assembly = typeof(Program).Assembly.Location,
                Bridge = typeof(System.Windows.Controls.WpfPropertyGrid.PropertyGrid).Assembly.Location,
                InitialCheck = initialCheck, InitialSlider = initialSlider, InitialCombo = initialCombo?.ToString(),
                Controls = new[] { "checkbox", "dialog", "track", "thumb", "combo" },
                DialogClickMode = dialog.ClickMode.ToString(), SliderMoveToPoint = slider.IsMoveToPointEnabled,
                DialogPointerContract = "Existing bridge PreviewMouseDown opens dialog before ButtonBase mouse IsPressed; keyboard Space tests real IsPressed.",
                Input = "External official Computer Use only; this observer generates no input or visual state.",
                AutoPreviewSuppressedForVisualFixture = true
            }, new JsonSerializerOptions { WriteIndented = true }));
            try
            {
                timer.Start();
                System.Windows.Threading.Dispatcher.PushFrame(frame);
            }
            finally
            {
                timer.Stop();
                foreach (Action detach in release) detach();
            }
            if (pointerInputs.Count != 5) failures.Add("Actual pointer inputs missing: " + string.Join(",", new[] { "checkbox", "dialog", "track", "thumb", "combo" }.Except(pointerInputs)));
            if (!pressed.Contains("checkbox") || !pressed.Contains("thumb") || !keyboardPressed.Contains("dialog"))
                failures.Add("Actual checkbox press, thumb drag or dialog keyboard press missing.");
            if (check.IsChecked != initialCheck || slider.Value != initialSlider || !Equals(combo.SelectedItem, initialCombo))
                failures.Add("Actual input values were not restored.");
            RefreshControls();
            if (!ReferenceEquals(selected, grid.SelectedObject) || document.PreviewRunCount != runs || host.Workbench.Tool.HasResult != hadResult
                || host.LayerDocumentCount != layers || host.DirectResultRouteText != route)
                failures.Add("Pointer input changed selected model, execution, layers or route.");
            if (files.Count != Directory.EnumerateFiles(recipeDirectory, "*", SearchOption.AllDirectories).Count()
                || files.Any(file => !File.Exists(file.Key) || Convert.ToHexString(SHA256.HashData(File.ReadAllBytes(file.Key))) != file.Value))
                failures.Add("Pointer input changed recipe files.");
            File.WriteAllText(Path.ChangeExtension(outputPath, ".input-checks.json"), JsonSerializer.Serialize(new
            {
                States = states, Pressed = pressed, PointerInputs = pointerInputs, KeyboardPressed = keyboardPressed, Failures = failures,
                Boundary = "Actual Computer Use input on current WPF test-host controls; synchronous render at real pointer-down. Auto preview is explicitly suppressed for this visual fixture. Default auto policy, production EXE and native125 remain separate."
            }, new JsonSerializerOptions { WriteIndented = true }));
            if (failures.Count != 0) throw new InvalidOperationException(string.Join(Environment.NewLine, failures));

            void RefreshControls()
            {
                CheckBox? currentCheck = FindVisualChildren<CheckBox>(grid).FirstOrDefault(item => item.IsVisible && item.Template?.FindName("CheckChrome", item) is Border);
                if (currentCheck != null) { check = currentCheck; Observe(check, "checkbox", "CheckChrome", ButtonBase.IsPressedProperty); }
                Slider? currentSlider = FindVisualChildren<Slider>(grid).FirstOrDefault(item => item.IsVisible);
                if (currentSlider != null)
                {
                    slider = currentSlider;
                    Thumb? currentThumb = FindVisualChildren<Thumb>(slider).FirstOrDefault(item => item.Template?.FindName("ThumbChrome", item) is Border);
                    RepeatButton? currentTrack = FindVisualChildren<RepeatButton>(slider).LastOrDefault(item => item.Template?.FindName("TrackLine", item) is Border);
                    if (currentThumb != null) { thumb = currentThumb; Observe(thumb, "thumb", "ThumbChrome", Thumb.IsDraggingProperty); }
                    if (currentTrack != null) { track = currentTrack; Observe(track, "track", "TrackLine", ButtonBase.IsPressedProperty); }
                }
                Button? currentDialog = FindVisualChildren<Button>(grid).FirstOrDefault(item => item.IsVisible && item.Template?.FindName("DialogChrome", item) is Border);
                ComboBox? currentCombo = FindVisualChildren<ComboBox>(grid).FirstOrDefault(item => item.IsVisible && item.Template?.FindName("ComboChrome", item) is Border);
                if (currentDialog != null) { dialog = currentDialog; Observe(dialog, "dialog", "DialogChrome", ButtonBase.IsPressedProperty); }
                if (currentCombo != null) { combo = currentCombo; Observe(combo, "combo", "ComboChrome", null); }
            }
            void Observe(Control control, string name, string chromeName, DependencyProperty? downProperty)
            {
                if (!observed.Add(control)) return;
                if (control is ComboBox)
                {
                    MouseButtonEventHandler mouseDown = (_, args) =>
                    {
                        if (args.ChangedButton == MouseButton.Left && Mouse.LeftButton == MouseButtonState.Pressed)
                            Capture(control, name, chromeName, "pointer-down", true);
                    };
                    control.AddHandler(UIElement.PreviewMouseLeftButtonDownEvent, mouseDown, true);
                    release.Add(() => control.RemoveHandler(UIElement.PreviewMouseLeftButtonDownEvent, mouseDown));
                }
                Capture(control, name, chromeName, "normal", false);
                MouseEventHandler enter = (_, _) => Capture(control, name, chromeName, "hover", false);
                MouseEventHandler leave = (_, _) => Capture(control, name, chromeName, "mouse-leave", false);
                KeyboardFocusChangedEventHandler focus = (_, _) => Capture(control, name, chromeName, "focused", false);
                control.MouseEnter += enter;
                control.MouseLeave += leave;
                control.GotKeyboardFocus += focus;
                release.Add(() => { control.MouseEnter -= enter; control.MouseLeave -= leave; control.GotKeyboardFocus -= focus; });
                if (downProperty == null) return;
                var descriptor = DependencyPropertyDescriptor.FromProperty(downProperty, control.GetType());
                EventHandler changed = (_, _) =>
                {
                    if (Equals(control.GetValue(downProperty), true))
                        Capture(control, name, chromeName, Mouse.LeftButton == MouseButtonState.Pressed ? "pointer-down" : "keyboard-down", Mouse.LeftButton == MouseButtonState.Pressed);
                };
                descriptor.AddValueChanged(control, changed);
                release.Add(() => descriptor.RemoveValueChanged(control, changed));
            }
            void Capture(Control control, string name, string chromeName, string state, bool actualDown)
            {
                if (!captured.Add(name + "/" + state)) return;
                control.UpdateLayout();
                Border chrome = (Border)control.Template.FindName(chromeName, control);
                var background = (SolidColorBrush)chrome.Background;
                SolidColorBrush? border = chrome.BorderBrush as SolidColorBrush;
                Brush foreground = control.Foreground;
                bool hasText = control is Button && control is not RepeatButton || control is ComboBox;
                if (control is CheckBox && control.Template.FindName("CheckMark", control) is System.Windows.Shapes.Path mark) foreground = mark.Stroke;
                double textContrast = foreground is SolidColorBrush fg ? GetContrastRatio(fg.Color, background.Color) : 0;
                double borderContrast = GetContrastRatio((border ?? background).Color, System.Windows.Media.Color.FromRgb(20, 23, 29));
                string capture = Path.ChangeExtension(outputPath, "." + name + "-" + state + ".png");
                ScreenshotPngWriter.WriteVisibleElementPng(control, capture);
                if (actualDown) pointerInputs.Add(name);
                if (actualDown && state == "pointer-down") pressed.Add(name);
                if (state == "keyboard-down" && control is ButtonBase { IsPressed: true }) keyboardPressed.Add(name);
                states.Add(new { Name = name, State = state, ControlType = control.GetType().FullName, ActualPointerDown = actualDown,
                    ActualKeyboardDown = state == "keyboard-down" && (Keyboard.IsKeyDown(Key.Space) || Keyboard.IsKeyDown(Key.Enter)), MouseLeftButton = Mouse.LeftButton.ToString(),
                    IsPressed = control is ButtonBase button && button.IsPressed, IsDragging = control is Thumb handle && handle.IsDragging,
                    control.IsMouseOver, control.IsKeyboardFocused, control.IsEnabled, Foreground = foreground.ToString(),
                    Background = background.Color.ToString(), Border = border?.Color.ToString(), TextContrast = textContrast, BorderContrast = borderContrast, Capture = capture });
                if ((hasText || control is CheckBox { IsChecked: true }) && textContrast < 4.5D || borderContrast < 3D)
                    failures.Add(name + "/" + state + ": rendered contrast below4.5:1 /3:1.");
            }
        }, captureFloatingToolWindow: false);
    }

    private static CaptureResult CaptureWorkbenchPreviewTheme(string outputPath)
    {
        OpenVisionLanguageService.SetLanguage(OpenVisionLanguage.Korean, false);
        string recipeName = "Smoke_PreviewTheme_" + Guid.NewGuid().ToString("N");
        OpenVisionShellHostView host = CreateShellHost(recipeName, seedMainLayer: false);
        List<string> failures = new();
        List<object> checks = new();
        return CaptureWindowWithContent(host, outputPath, 1920, 1032, () =>
        {
            foreach (VISION_MENU menu in new[] { VISION_MENU.Blob, VISION_MENU.Arithmetic })
            {
                host.SelectToolForTest(menu);
                Pump(12);
                OpenVisionNativeToolDocument document = host.ActiveNativeDocumentForTest!;
                VisionToolDebouncedPreviewScheduler.SetAllowAutoPreview(document.View, false);
                int runs = document.PreviewRunCount;
                bool hadResult = host.Workbench.Tool.HasResult;
                int layers = host.LayerDocumentCount;
                string route = host.DirectResultRouteText;
                OpenVisionLanguage initialLanguage = OpenVisionLanguageService.CurrentLanguage;
                string recipeDirectory = RecipeWorkspaceService.GetRecipeWorkspaceDirectory(recipeName);
                Dictionary<string, string> files = Directory.EnumerateFiles(recipeDirectory, "*", SearchOption.AllDirectories)
                    .ToDictionary(Path.GetFullPath, path => Convert.ToHexString(SHA256.HashData(File.ReadAllBytes(path))));
                if (!host.FloatDockedWpfToolWindowForTest()) throw new InvalidOperationException("Preview theme fixture could not float " + menu);
                Pump(12);
                Window floating = Window.GetWindow(document.View);
                Border[] frames = FindVisualChildren<Border>(document.View).Where(frame => frame.Child is Grid content
                    && content.Children.OfType<VisionToolInlinePreviewSlot>().Any()).ToArray();
                if (frames.Length != (menu == VISION_MENU.Blob ? 2 : 3)) throw new InvalidOperationException("Missing preview frames for " + menu);
                foreach (string theme in new[] { "Dark", "Light" })
                {
                    ResourceDictionary palette = new() { Source = new Uri($"pack://application:,,,/OpenVisionLab;component/UI/Wpf/OpenVisionWorkbench{theme}.xaml") };
                    foreach (Border frame in frames) frame.Resources.MergedDictionaries.Add(palette);
                    try
                    {
                        foreach (OpenVisionLanguage language in new[] { OpenVisionLanguage.Korean, OpenVisionLanguage.English })
                        {
                            OpenVisionLanguageService.SetLanguage(language, false);
                            Pump(12);
                            string expectedBeforeRun = language == OpenVisionLanguage.Korean ? "실행 전" : "Not run";
                            FrameworkElement toolShell = (FrameworkElement)document.View.FindName("toolShell");
                            TextBlock runCaption = (TextBlock)toolShell.FindName("txtRunPreviewText");
                            if (host.Workbench.Tool.HasResult || host.Workbench.Tool.ResultStatusText != expectedBeforeRun
                                || runCaption.Text != host.Workbench.Tool.RunText || runCaption.GetBindingExpression(TextBlock.TextProperty) == null)
                                failures.Add(theme + "/" + language + "/" + menu + ": before-run status or locale run binding changed.");
                            checks.Add(new { Name = theme + "/" + language + "/" + menu + "/before-run-captions", Status = host.Workbench.Tool.ResultStatusText, Run = runCaption.Text, Expected = expectedBeforeRun });
                            VisionToolDoubleInputCustomToolShell? arithmetic = document.View as VisionToolDoubleInputCustomToolShell
                                ?? FindVisualChildren<VisionToolDoubleInputCustomToolShell>(document.View).SingleOrDefault();
                            if (menu == VISION_MENU.Arithmetic && (arithmetic == null
                                || arithmetic.InputAGroup.Header?.ToString() != OpenVisionLanguageService.T("Workbench.Tool.InputA")
                                    || arithmetic.InputBGroup.Header?.ToString() != OpenVisionLanguageService.T("Workbench.Tool.InputB")
                                    || arithmetic.InputAGroup.GetBindingExpression(HeaderedContentControl.HeaderProperty) == null
                                    || arithmetic.InputBGroup.GetBindingExpression(HeaderedContentControl.HeaderProperty) == null))
                                failures.Add(theme + "/" + language + "/Arithmetic: input header binding changed after localization.");
                            if (menu == VISION_MENU.Blob)
                            {
                                string caption = OpenVisionLanguageService.T("PropertyGrid.Property.USE_ADAPTIVE_THRESHOLD.DisplayName");
                                TextBlock[] parameterTexts = FindVisualChildren<TextBlock>(document.View).ToArray();
                                File.WriteAllText(Path.ChangeExtension(outputPath, "." + theme + "-" + language + "-labels.json"), JsonSerializer.Serialize(new { Expected = caption, Actual = parameterTexts.Select(text => new { text.Name, text.Text, text.ActualWidth, text.ActualHeight }).ToArray() }, new JsonSerializerOptions { WriteIndented = true }));
                                TextBlock label = parameterTexts.FirstOrDefault(text => text.Text == caption)
                                    ?? throw new InvalidOperationException("Missing actual adaptive label: " + caption);
                                FormattedText required = new(label.Text, CultureInfo.CurrentCulture, label.FlowDirection,
                                    new Typeface(label.FontFamily, label.FontStyle, label.FontWeight, label.FontStretch), label.FontSize, label.Foreground, VisualTreeHelper.GetDpi(label).PixelsPerDip);
                                checks.Add(new { Name = theme + "/" + language + "/adaptive-label", label.Text, Width = label.ActualWidth, RequiredWidth = required.Width, Height = label.ActualHeight, RequiredHeight = required.Height });
                                if (label.ActualWidth + 1D < required.Width || label.ActualHeight + 1D < required.Height)
                                    failures.Add(theme + "/" + language + ": adaptive threshold label clipped in retained parameter geometry.");
                                ScreenshotPngWriter.WriteVisibleElementPng(label, Path.ChangeExtension(outputPath, "." + theme + "-" + language + "-adaptive-label.png"));
                            }
                            foreach (Border frame in frames)
                            {
                                string prefix = theme + "-" + language + "-" + menu + "-" + frame.Name;
                                Grid content = (Grid)frame.Child;
                                VisionToolInlinePreviewSlot slot = content.Children.OfType<VisionToolInlinePreviewSlot>().Single();
                                Border empty = content.Children.OfType<Border>().Single(item => item.Child is StackPanel);
                                Border hint = content.Children.OfType<Border>().Single(item => item.Name == "bdPreviewRouteOverlay");
                                TextBlock title = FindVisualChildren<TextBlock>(empty).Single(item => item.Name == "txtPreviewEmptyTitle");
                                TextBlock? detail = FindVisualChildren<TextBlock>(empty).SingleOrDefault(item => item.Name == "txtPreviewEmptyDetail");
                                Button? load = FindVisualChildren<Button>(empty).SingleOrDefault();
                                bool input = !frame.Name.Contains("Output", StringComparison.Ordinal);
                                if (input != (load != null) || frame.ContextMenu?.Items.Count != (input ? 2 : 1)
                                    || title.Text != OpenVisionLanguageService.T(input ? "ToolView.NoInputImageTitle" : "ToolView.NoOutputImageTitle")
                                    || (input ? detail != null : detail?.Text != (language == OpenVisionLanguage.Korean ? "툴 실행(F8)을 누르세요." : "Press Run tool (F8).")))
                                    failures.Add(prefix + ": load/save roles or localized empty captions changed.");
                                CheckBrush(empty.Background, palette["OpenVision.Workbench.PanelBrush"], prefix + "/surface");
                                CheckBrush(empty.BorderBrush, palette["OpenVision.Workbench.FieldBorderBrush"], prefix + "/border");
                                CheckBrush(title.Foreground, palette["OpenVision.Workbench.TextBrush"], prefix + "/title");
                                if (detail != null) CheckBrush(detail.Foreground, palette["OpenVision.Workbench.SecondaryTextBrush"], prefix + "/detail");
                                RecordText(title, empty.Background, prefix + "/title");
                                if (detail != null) RecordText(detail, empty.Background, prefix + "/detail");
                                ScreenshotPngWriter.WriteVisibleElementPng(frame, Path.ChangeExtension(outputPath, "." + prefix + "-empty.png"));
                                if (load != null)
                                {
                                    RecordButton(load, prefix + "/normal");
                                    load.Focus();
                                    Pump(4);
                                    RecordButton(load, prefix + "/focused");
                                    load.IsEnabled = false;
                                    Pump(4);
                                    RecordButton(load, prefix + "/disabled");
                                    load.IsEnabled = true;
                                    ToolTip tooltip = new() { Content = load.ToolTip, PlacementTarget = load, Style = (Style)load.FindResource(typeof(ToolTip)) };
                                    tooltip.Resources.MergedDictionaries.Add(palette);
                                    try
                                    {
                                        tooltip.IsOpen = true;
                                        Pump(8);
                                        CheckBrush(tooltip.Background, palette["OpenVision.Workbench.RaisedBrush"], prefix + "/tooltip-surface");
                                        CheckBrush(tooltip.BorderBrush, palette["OpenVision.Workbench.FieldBorderBrush"], prefix + "/tooltip-border");
                                        TextBlock caption = FindVisualChildren<TextBlock>(tooltip).FirstOrDefault(text => !string.IsNullOrEmpty(text.Text))
                                            ?? throw new InvalidOperationException("Tooltip has no rendered caption: " + prefix + "; content=" + tooltip.Content);
                                        CheckBrush(caption.Foreground, palette["OpenVision.Workbench.TextBrush"], prefix + "/tooltip-text");
                                        RecordText(caption, tooltip.Background, prefix + "/tooltip");
                                        if (tooltip.FontSize != 12 || !tooltip.FontFamily.Source.Contains("Pretendard", StringComparison.Ordinal) || tooltip.ActualWidth > 420)
                                            failures.Add(prefix + ": tooltip font or bounds changed.");
                                        ScreenshotPngWriter.WriteVisibleElementPng(tooltip, Path.ChangeExtension(outputPath, "." + prefix + "-tooltip.png"));
                                    }
                                    finally { tooltip.IsOpen = false; tooltip.Resources.MergedDictionaries.Remove(palette); }
                                }
                                double height = frame.Height;
                                try
                                {
                                    frame.Height = 90;
                                    using Bitmap image = new(13, 9);
                                    using (Graphics graphics = Graphics.FromImage(image)) graphics.Clear(DrawingColor.MediumPurple);
                                    slot.SetImage(image);
                                    Pump(8);
                                    if (!slot.HasImage || slot.ImagePixelWidth != 13 || slot.ImagePixelHeight != 9
                                        || empty.IsVisible || !hint.IsVisible || frame.Cursor != Cursors.Hand)
                                        failures.Add(prefix + ": image/compact route-hint transition changed.");
                                    CheckBrush(hint.Background, palette["OpenVision.Workbench.PanelAltBrush"], prefix + "/hint-surface");
                                    CheckBrush(hint.BorderBrush, palette["OpenVision.Workbench.FieldBorderBrush"], prefix + "/hint-border");
                                    ScreenshotPngWriter.WriteVisibleElementPng(frame, Path.ChangeExtension(outputPath, "." + prefix + "-route.png"));
                                    slot.ClearImage();
                                    Pump(8);
                                    if (!empty.IsVisible || hint.IsVisible || detail?.IsVisible == true || load?.IsVisible == true || title.FontSize != 11)
                                        failures.Add(prefix + ": compact empty recovery changed.");
                                    ScreenshotPngWriter.WriteVisibleElementPng(frame, Path.ChangeExtension(outputPath, "." + prefix + "-compact-empty.png"));
                                }
                                finally { slot.ClearImage(); frame.Height = height; Pump(6); }
                                if (detail?.IsVisible == false || load?.IsVisible == false || title.FontSize != 13)
                                    failures.Add(prefix + ": floating empty-card density did not restore.");
                            }
                            ScreenshotPngWriter.WriteVisibleElementPng(floating, Path.ChangeExtension(outputPath, "." + theme + "-" + language + "-" + menu + "-floating.png"));
                        }
                    }
                    finally { foreach (Border frame in frames) frame.Resources.MergedDictionaries.Remove(palette); }
                }
                OpenVisionLanguageService.SetLanguage(initialLanguage, false);
                if (!host.DockActiveWpfToolWindowForTest() || !ReferenceEquals(document, host.ActiveNativeDocumentForTest))
                    failures.Add(menu + ": redocking changed the document or failed.");
                Pump(12);
                checks.Add(new { Name = menu + "/invariants", RunsBefore = runs, RunsAfter = document.PreviewRunCount, ResultBefore = hadResult, ResultAfter = host.Workbench.Tool.HasResult, LayersBefore = layers, LayersAfter = host.LayerDocumentCount, RouteBefore = route, RouteAfter = host.DirectResultRouteText,
                    FilesBefore = files.Count, FilesAfter = Directory.EnumerateFiles(recipeDirectory, "*", SearchOption.AllDirectories).Count(), ChangedFiles = files.Where(file => !File.Exists(file.Key) || Convert.ToHexString(SHA256.HashData(File.ReadAllBytes(file.Key))) != file.Value).Select(file => file.Key).ToArray() });
                if (document.PreviewRunCount != runs || host.Workbench.Tool.HasResult != hadResult || host.LayerDocumentCount != layers || host.DirectResultRouteText != route
                    || files.Any(file => !File.Exists(file.Key) || Convert.ToHexString(SHA256.HashData(File.ReadAllBytes(file.Key))) != file.Value)
                    || files.Count != Directory.EnumerateFiles(recipeDirectory, "*", SearchOption.AllDirectories).Count())
                    failures.Add(menu + ": visual fixture changed run/result/layers/route/recipe files.");
            }
            Button guide = FindVisualChildren<Button>(host).Single(button => AutomationProperties.GetAutomationId(button) == "HostGuideButton");
            Button stop = FindVisualChildren<Button>(host).First(button => ReferenceEquals(button.Command, host.Workbench.Pipeline.StopCommand));
            foreach (string theme in new[] { "Dark", "Light" })
            {
                ResourceDictionary palette = new() { Source = new Uri($"pack://application:,,,/OpenVisionLab;component/UI/Wpf/OpenVisionWorkbench{theme}.xaml") };
                foreach (Button button in new[] { guide, stop })
                {
                    button.Resources.MergedDictionaries.Add(palette);
                    try
                    {
                        foreach (bool enabled in new[] { true, false })
                        {
                            button.IsEnabled = enabled;
                            Pump(4);
                            Border chrome = (Border)button.Template.FindName("buttonChrome", button);
                            double outline = GetContrastRatio(((SolidColorBrush)chrome.BorderBrush).Color, ((SolidColorBrush)chrome.Background).Color);
                            string name = theme + "-shared-" + (button == guide ? "guide" : "stop") + "-" + (enabled ? "normal" : "disabled");
                            string capture = Path.ChangeExtension(outputPath, "." + name + ".png");
                            checks.Add(new { Name = name, Border = chrome.BorderBrush.ToString(), Background = chrome.Background.ToString(), BorderContrast = outline, Capture = capture });
                            if (outline < 3D) failures.Add(name + ": shared button border below3:1.");
                            ScreenshotPngWriter.WriteVisibleElementPng(button, capture);
                        }
                    }
                    finally { button.ClearValue(UIElement.IsEnabledProperty); button.Resources.MergedDictionaries.Remove(palette); }
                }
            }
            File.WriteAllText(Path.ChangeExtension(outputPath, ".preview-theme.json"), JsonSerializer.Serialize(new
            {
                Checks = checks, Failures = failures,
                Boundary = "In-process Blob/Arithmetic and ko/en; Light is a local resource fixture, not whole-app theme adoption. Compact card height90 and tooltip popup with explicit reused style are fixtures; native automatic tooltip is separate. Auto preview explicitly suppressed; real input/native125/current EXE separate."
            }, new JsonSerializerOptions { WriteIndented = true }));
            if (failures.Count != 0) throw new InvalidOperationException(string.Join(Environment.NewLine, failures));
        });

        void CheckBrush(Brush actual, object expected, string name)
        {
            if (actual.ToString() != expected.ToString()) failures.Add(name + ": resource mismatch " + actual + " != " + expected);
        }
        void RecordText(TextBlock text, Brush background, string name)
        {
            double contrast = GetContrastRatio(((SolidColorBrush)text.Foreground).Color, ((SolidColorBrush)background).Color);
            checks.Add(new { Name = name, text.Text, Foreground = text.Foreground.ToString(), Background = background.ToString(), Contrast = contrast, text.ActualWidth, text.ActualHeight });
            if (contrast < 4.5D) failures.Add(name + ": text contrast below4.5:1.");
        }
        void RecordButton(Button button, string name)
        {
            Border chrome = (Border)button.Template.FindName("buttonChrome", button);
            TextBlock label = FindVisualChildren<TextBlock>(button).Single(item => item.Name == "txtPreviewLoadImageButton");
            Control icon = FindVisualChildren<Control>(button).Single(item => item.GetType().Name == "PackIconMaterial");
            double contrast = GetContrastRatio(((SolidColorBrush)label.Foreground).Color, ((SolidColorBrush)chrome.Background).Color);
            double borderContrast = GetContrastRatio(((SolidColorBrush)chrome.BorderBrush).Color, ((SolidColorBrush)chrome.Background).Color);
            checks.Add(new { Name = name, Border = chrome.BorderBrush.ToString(), BorderContrast = borderContrast, Foreground = label.Foreground.ToString(), Background = chrome.Background.ToString(), Contrast = contrast, ButtonForeground = button.Foreground.ToString(), IconForeground = icon.Foreground.ToString(), button.IsEnabled,
                Capture = Path.ChangeExtension(outputPath, "." + name.Replace('/', '-') + ".png") });
            if (contrast < 4.5D || borderContrast < 3D || label.Foreground.ToString() != button.Foreground.ToString() || icon.Foreground.ToString() != button.Foreground.ToString())
                failures.Add(name + ": button child contrast/state inheritance failed.");
            ScreenshotPngWriter.WriteVisibleElementPng(button, Path.ChangeExtension(outputPath, "." + name.Replace('/', '-') + ".png"));
        }
    }

    private static CaptureResult CaptureWorkbenchPropertyGridSearchTransition(string outputPath)
    {
        OpenVisionLanguageService.SetLanguage(OpenVisionLanguage.Korean, false);
        string recipeName = "Smoke_WorkbenchPgSearch_" + Guid.NewGuid().ToString("N");
        OpenVisionShellHostView host = CreateShellHost(recipeName, seedMainLayer: false);
        List<string> failures = new();
        List<object> transitions = new();
        return CaptureWindowWithContent(host, outputPath, 1920, 1032, () =>
        {
            string recipeDirectory = RecipeWorkspaceService.GetRecipeWorkspaceDirectory(recipeName);
            Dictionary<string, string> files = Directory.EnumerateFiles(recipeDirectory, "*", SearchOption.AllDirectories)
                .ToDictionary(Path.GetFullPath, path => Convert.ToHexString(SHA256.HashData(File.ReadAllBytes(path))));
            host.SelectToolForTest(VISION_MENU.Contour);
            Pump(18);
            OpenVisionNativeToolDocument document = host.ActiveNativeDocumentForTest!;
            System.Windows.Controls.WpfPropertyGrid.PropertyGrid grid = FindVisualChildren<System.Windows.Controls.WpfPropertyGrid.PropertyGrid>(document.View).Single();
            VisionToolDebouncedPreviewScheduler.SetAllowAutoPreview(document.View, false);
            object selected = grid.SelectedObject;
            int runs = host.NativePreviewRunCount;
            int layers = host.LayerDocumentCount;
            string route = host.DirectResultRouteText;
            string stepBefore = JsonSerializer.Serialize(host.Workbench.Tool.CurrentStep);
            string[] Rows() => FindVisualChildren<Border>(grid).Where(item => item.Name == "RowBorder" && item.IsVisible && item.ActualHeight > 1)
                .Select(item => (item.DataContext?.GetType().GetProperty("PropertyDescriptor")?.GetValue(item.DataContext) as PropertyDescriptor)?.Name)
                .Where(name => name != null).Cast<string>().Distinct().OrderBy(name => name, StringComparer.Ordinal).ToArray();
            void Search(string text)
            {
                TextBox search = GetActivePropertyGridSearchTextBox(grid, "Contour search transition");
                search.Text = text;
                search.GetBindingExpression(TextBox.TextProperty)?.UpdateSource();
                Pump(24);
            }
            int propertyValueChanges = 0;
            List<object> propertyChangeEvents = new();
            EventHandler<OpenVisionLab.PropertyGrid.PropertyGridPropertyValueChangedEventArgs> valueChanged = (_, args) =>
            {
                propertyValueChanges++;
                propertyChangeEvents.Add(new { Name = args.Property?.Name, OldValue = args.OldValue?.ToString(), NewValue = args.NewValue?.ToString(), Stack = Environment.StackTrace });
            };
            string[] baseline = Rows();
            void Observe(string state, string expectedQuery, bool expectEmpty = false, bool expectCleared = false)
            {
                string[] names = Rows();
                string query = grid.SearchTextForTest;
                bool validRows = expectCleared ? baseline.SequenceEqual(names) : expectEmpty ? names.Length == 0
                    : names.Contains("CvROI") && !names.Contains("NAME") && !names.Contains("PIXELPERMM") && names.Length < baseline.Length;
                string expectedEmptyText = string.Format(CultureInfo.CurrentCulture, OpenVisionLanguageService.CurrentLanguage == OpenVisionLanguage.Korean ? "\u2018{0}\u2019 \uAC80\uC0C9 \uACB0\uACFC \uC5C6\uC74C (Esc: \uC9C0\uC6B0\uAE30)" : "No match for \u2018{0}\u2019 (Esc: clear)", expectedQuery);
                bool valid = query == expectedQuery && grid.IsSearchEmptyMessageVisibleForTest == expectEmpty && validRows
                    && (!expectEmpty || FindVisualChildren<TextBlock>(grid).Any(text => text.IsVisible && text.Text == expectedEmptyText))
                    && ReferenceEquals(selected, grid.SelectedObject) && ReferenceEquals(document, host.ActiveNativeDocumentForTest);
                string[] rowBackgrounds = FindVisualChildren<Border>(grid).Where(item => item.Name == "RowBorder" && item.IsVisible && item.ActualHeight > 1)
                    .Select(item => item.Background?.ToString() ?? string.Empty).Distinct().ToArray();
                bool darkPalette = grid.ThemeVariant != System.Windows.Controls.WpfPropertyGrid.PropertyGridThemeVariant.Dark
                    || rowBackgrounds.All(color => color == "#FF14171D" || color == "#FF1B1F27");
                if (!darkPalette) failures.Add(state + ": regenerated Dark rows have a light background: " + string.Join(",", rowBackgrounds));
                string capture = Path.ChangeExtension(outputPath, "." + state + ".png");
                ScreenshotPngWriter.WriteVisibleElementPng(document.View, capture);
                object? inner = grid.GetType().GetField("innerPropertyGrid", BindingFlags.Instance | BindingFlags.NonPublic)?.GetValue(grid);
                object? filter = inner?.GetType().GetProperty("PropertyFilter")?.GetValue(inner);
                object[] rowFilters = FindVisualChildren<Border>(grid).Where(item => item.Name == "RowBorder").Select(item => new
                    { Name = (item.DataContext?.GetType().GetProperty("PropertyDescriptor")?.GetValue(item.DataContext) as PropertyDescriptor)?.Name, item.IsVisible,
                        MatchesFilter = item.DataContext?.GetType().GetProperty("MatchesFilter")?.GetValue(item.DataContext), DataContext = item.DataContext?.GetType().FullName }).Cast<object>().ToArray();
                transitions.Add(new { State = state, DarkPalette = darkPalette, RowBackgrounds = rowBackgrounds, PropertyValueChanges = propertyValueChanges, ExpectedEmptyText = expectEmpty ? expectedEmptyText : null, Query = query, ExpectedQuery = expectedQuery, Rows = names, EmptyOverlay = grid.IsSearchEmptyMessageVisibleForTest, Valid = valid, Capture = capture,
                    FilterType = filter?.GetType().FullName, FilterText = filter?.ToString(), FilterEmpty = filter?.GetType().GetProperty("IsEmpty")?.GetValue(filter), RowFilters = rowFilters,
                    HasCategories = inner?.GetType().GetProperty("HasCategories")?.GetValue(inner),
                    CategoriesCount = (inner?.GetType().GetProperty("Categories")?.GetValue(inner) as System.Collections.ICollection)?.Count,
                    PropertiesCount = (inner?.GetType().GetProperty("Properties")?.GetValue(inner) as System.Collections.ICollection)?.Count });
                if (!valid) failures.Add(state + ": visible query/filter/empty state differs; query=" + query + "; rows=" + string.Join(",", names));
            }
            grid.PropertyValueChanged += valueChanged;
            try
            {
                Search("ROI");
                Observe("ko-filtered", "ROI");
                OpenVisionLanguageService.SetLanguage(OpenVisionLanguage.English, false);
                Pump(36);
                Observe("en-language-restore", "ROI");
                grid.ThemeVariant = System.Windows.Controls.WpfPropertyGrid.PropertyGridThemeVariant.Dark;
                Pump(18);
                Observe("dark-theme-restore", "ROI");
                grid.RefreshSelectedObject();
                Pump(36);
                Observe("refresh-restore", "ROI");
                host.SelectToolForTest(VISION_MENU.Blob);
                Pump(18);
                VisionToolDebouncedPreviewScheduler.SetAllowAutoPreview(host.ActiveNativeDocumentForTest!.View, false);
                host.SelectToolForTest(VISION_MENU.Contour);
                Pump(36);
                Observe("tool-switch-restore", "ROI");
                if (!host.FloatDockedWpfToolWindowForTest()) failures.Add("Float entry failed.");
                Pump(24);
                Observe("float-restore", "ROI");
                if (!host.DockActiveWpfToolWindowForTest()) failures.Add("Redock entry failed.");
                Pump(24);
                Observe("redock-restore", "ROI");
                Search("OVL_NO_VISIBLE_PROPERTY_20261008");
                Observe("en-no-match", "OVL_NO_VISIBLE_PROPERTY_20261008", expectEmpty: true);
                Search("ROI");
                Observe("en-filter-recovery", "ROI");
                OpenVisionLanguageService.SetLanguage(OpenVisionLanguage.Korean, false);
                Pump(36);
                Observe("ko-language-restore", "ROI");
                Search("OVL_NO_VISIBLE_PROPERTY_20261008");
                Observe("no-match", "OVL_NO_VISIBLE_PROPERTY_20261008", expectEmpty: true);
                Search(string.Empty);
                Observe("clear-recovery", string.Empty, expectCleared: true);
                bool noParameterEdits = propertyValueChanges == 0;
                if (!noParameterEdits) failures.Add("Search transitions raised parameter value changes: " + propertyValueChanges);
                if (!grid.FocusProperty("DrawColor")) throw new InvalidOperationException("Draw color editor could not be focused.");
                Pump(12);
                Border colorRow = FindVisualChildren<Border>(grid).Single(item => item.Name == "RowBorder"
                    && (item.DataContext?.GetType().GetProperty("PropertyDescriptor")?.GetValue(item.DataContext) as PropertyDescriptor)?.Name == "DrawColor");
                ComboBox colorCombo = FindVisualChildren<ComboBox>(colorRow).Single();
                object originalColorItem = colorCombo.SelectedItem;
                DrawingColor originalColor = ((ContourProperty)selected).DrawColor;
                object redItem = colorCombo.Items.Cast<object>().Single(item => item.ToString() == "Red");
                int beforeRealEdit = propertyValueChanges;
                colorCombo.SelectedItem = redItem;
                colorCombo.GetBindingExpression(Selector.SelectedItemProperty)?.UpdateSource();
                Pump(18);
                bool realColorEdit = ((ContourProperty)selected).DrawColor == DrawingColor.Red && colorCombo.SelectedItem?.ToString() == "Red" && propertyValueChanges > beforeRealEdit;
                ScreenshotPngWriter.WriteVisibleElementPng(colorRow, Path.ChangeExtension(outputPath, ".color-red-row.png"));
                colorCombo.SelectedItem = originalColorItem;
                colorCombo.GetBindingExpression(Selector.SelectedItemProperty)?.UpdateSource();
                Pump(18);
                bool colorRestored = ((ContourProperty)selected).DrawColor == originalColor && Equals(colorCombo.SelectedItem, originalColorItem);
                ScreenshotPngWriter.WriteVisibleElementPng(colorRow, Path.ChangeExtension(outputPath, ".color-restored-row.png"));
                if (!realColorEdit || !colorRestored) failures.Add("Real color selector edit or restoration did not update the binding and model.");
                bool noAction = host.NativePreviewRunCount == runs && host.LayerDocumentCount == layers && host.DirectResultRouteText == route
                    && JsonSerializer.Serialize(host.Workbench.Tool.CurrentStep) == stepBefore;
                bool filesUnchanged = files.Count == Directory.EnumerateFiles(recipeDirectory, "*", SearchOption.AllDirectories).Count()
                    && files.All(file => File.Exists(file.Key) && Convert.ToHexString(SHA256.HashData(File.ReadAllBytes(file.Key))) == file.Value);
                if (!noAction || !filesUnchanged) failures.Add("Search/language/theme/refresh/placement changed execution, values, layers, route or recipe files.");
                host.SelectToolForTest(VISION_MENU.EdgeBasedMatching);
                Pump(18);
                OpenVisionNativeToolDocument matchingDocument = host.ActiveNativeDocumentForTest!;
                VisionToolDebouncedPreviewScheduler.SetAllowAutoPreview(matchingDocument.View, false);
                System.Windows.Controls.WpfPropertyGrid.PropertyGrid matchingGrid = FindVisualChildren<System.Windows.Controls.WpfPropertyGrid.PropertyGrid>(matchingDocument.View).Single();
                matchingGrid.ThemeVariant = System.Windows.Controls.WpfPropertyGrid.PropertyGridThemeVariant.Dark;
                Pump(18);
                int matchingRuns = host.NativePreviewRunCount;
                int matchingLayers = host.LayerDocumentCount;
                string matchingRoute = host.DirectResultRouteText;
                using Bitmap templateSource = CreateMatchingSmokeBitmap();
                string matchingTemplatePath = CreateMatchingTemplateFile(templateSource);
                matchingDocument.SetTemplateSelectionForTest(fromFile => fromFile ? matchingTemplatePath : null);
                try { host.Workbench.Tool.TemplateFileCommand.Execute(null); }
                finally { matchingDocument.SetTemplateSelectionForTest(null); }
                Pump(36);
                object[] matchingRows = FindVisualChildren<Border>(matchingGrid).Where(item => item.Name == "RowBorder" && item.IsVisible && item.ActualHeight > 1)
                    .Select(item => new { Name = (item.DataContext?.GetType().GetProperty("PropertyDescriptor")?.GetValue(item.DataContext) as PropertyDescriptor)?.Name,
                        Background = item.Background?.ToString() ?? string.Empty }).Cast<object>().ToArray();
                bool matchingDarkPalette = matchingRows.Length > 0 && FindVisualChildren<Border>(matchingGrid)
                    .Where(item => item.Name == "RowBorder" && item.IsVisible && item.ActualHeight > 1)
                    .All(item => item.Background?.ToString() == "#FF14171D" || item.Background?.ToString() == "#FF1B1F27");
                bool matchingNoAction = host.NativePreviewRunCount == matchingRuns && host.LayerDocumentCount == matchingLayers && host.DirectResultRouteText == matchingRoute;
                string matchingCapture = Path.ChangeExtension(outputPath, ".matching-template-refresh.png");
                ScreenshotPngWriter.WriteVisibleElementPng(matchingDocument.View, matchingCapture);
                transitions.Add(new { State = "matching-template-refresh", DarkPalette = matchingDarkPalette, NoAction = matchingNoAction, Rows = matchingRows, Capture = matchingCapture });
                if (!matchingDarkPalette || !matchingNoAction) failures.Add("Template registration regenerated light rows or executed with fixture Auto OFF.");
                File.WriteAllText(Path.ChangeExtension(outputPath, ".search-checks.json"), JsonSerializer.Serialize(new
                { BaselineRows = baseline, Transitions = transitions, NoAction = noAction, NoParameterEdits = noParameterEdits, RealColorEdit = realColorEdit, ColorRestored = colorRestored, IntentionalColorEditEvents = propertyValueChanges - beforeRealEdit, PropertyValueChanges = propertyValueChanges, PropertyChangeEvents = propertyChangeEvents, FilesUnchanged = filesUnchanged, Failures = failures,
                    Boundary = "In-process visible row/filter transitions; fixture Auto OFF; parameter-change event count independently checks the edit/Auto trigger boundary; native input and DPI are separate." }, new JsonSerializerOptions { WriteIndented = true }));
                if (failures.Count != 0) throw new InvalidOperationException(string.Join(Environment.NewLine, failures));
            }
            finally
            {
                grid.PropertyValueChanged -= valueChanged;
            }
        });
    }

    private static CaptureResult CaptureWorkbenchMatchingContainer(string outputPath, int width, int height)
    {
        OpenVisionLanguageService.SetLanguage(OpenVisionLanguage.Korean, false);
        string recipeName = "Smoke_WorkbenchMatchingContainer_" + Guid.NewGuid().ToString("N");
        OpenVisionShellHostView host = CreateShellHost(recipeName, seedMainLayer: false);
        using Bitmap source = CreateMatchingSmokeBitmap();
        string templatePath = CreateMatchingTemplateFile(source);
        host.SetMainLayerImageForTest(source);
        List<object> states = new();
        List<string> failures = new();
        return CaptureWindowWithContent(host, outputPath, width, height, () =>
        {
            host.SelectToolForTest(VISION_MENU.EdgeBasedMatching);
            Pump(18);
            OpenVisionNativeToolDocument document = host.ActiveNativeDocumentForTest!;
            VisionToolDebouncedPreviewScheduler.SetAllowAutoPreview(document.View, false);
            SelectComboBoxItemText(FindFloatingComboBox("cbInputLayer"), "Main", "Matching container owned input");
            document.SetTemplateSelectionForTest(fromFile => fromFile ? templatePath : null);
            try { host.Workbench.Tool.TemplateFileCommand.Execute(null); }
            finally { document.SetTemplateSelectionForTest(null); }
            Pump(24);
            VisionToolSingleInputPropertyToolShell shell = (VisionToolSingleInputPropertyToolShell)document.View.FindName("toolShell");
            AutoMPointTeachingPanel panel = FindVisualChildren<AutoMPointTeachingPanel>(shell).Single();
            Expander expander = (Expander)panel.FindName("detailsExpander");
            ScrollViewer body = (ScrollViewer)shell.FindName("parameterBodyScrollViewer");
            FrameworkElement header = (FrameworkElement)shell.FindName("txtParameterHeader");
            FrameworkElement result = (FrameworkElement)shell.FindName("workbenchResultHost");
            System.Windows.Controls.WpfPropertyGrid.PropertyGrid grid = FindVisualChildren<System.Windows.Controls.WpfPropertyGrid.PropertyGrid>(shell).Single();
            string Rectangle(FrameworkElement item) => GetElementBounds(document.View, item).ToString(CultureInfo.InvariantCulture);
            bool HeaderInViewport()
            {
                Rect viewport = GetElementBounds(document.View, body);
                Rect bounds = GetElementBounds(document.View, header);
                return bounds.Top >= viewport.Top - 1D && bounds.Bottom <= viewport.Bottom + 1D;
            }
            void Observe(string state, string theme)
            {
                expander.ApplyTemplate();
                Border? contentChrome = expander.Template.FindName("ContentPresenterBorder", expander) as Border;
                Border? headerChrome = expander.Template.FindName("ToggleButtonBorder", expander) as Border;
                Stopwatch animation = Stopwatch.StartNew();
                while (contentChrome != null && headerChrome != null && animation.Elapsed < TimeSpan.FromSeconds(1)
                    && (expander.IsExpanded ? GetElementBounds(expander, contentChrome).Top < GetElementBounds(expander, headerChrome).Bottom - 1D : contentChrome.IsVisible))
                {
                    Pump(2);
                    Thread.Sleep(10);
                }
                if (expander.IsExpanded)
                {
                    Brush expectedBackground = (Brush)expander.FindResource("ExpanderContentBackground");
                    if (contentChrome == null || contentChrome.Background?.ToString() != expectedBackground.ToString())
                        failures.Add(theme + "/" + state + ": suggestion content used the platform palette.");
                    if (contentChrome != null && headerChrome != null && GetElementBounds(expander, contentChrome).Top < GetElementBounds(expander, headerChrome).Bottom - 1D)
                        failures.Add(theme + "/" + state + ": suggestion controls remain hidden behind the header after animation completion.");
                }
                object[] captions = new[] { (Button: "representativeImagesButton", Text: "representativeImagesText"), (Button: "analyzeButton", Text: "analyzeText"),
                    (Button: "usePatternButton", Text: "usePatternText"), (Button: "reportButton", Text: "reportText") }
                    .Select(pair =>
                    {
                        string name = pair.Button;
                        Button button = (Button)panel.FindName(name);
                        TextBlock caption = (TextBlock)panel.FindName(pair.Text);
                        if (expander.IsExpanded && caption.Foreground.ToString() != button.Foreground.ToString()) failures.Add(theme + "/" + state + ": " + name + " caption ignores its button state.");
                        if (expander.IsExpanded && !button.IsEnabled && caption.Foreground.ToString() != ((Brush)button.FindResource("VisionTool.DisabledTextBrush")).ToString())
                            failures.Add(theme + "/" + state + ": " + name + " disabled caption uses a different palette.");
                        return new { Button = name, button.IsEnabled, ButtonForeground = button.Foreground.ToString(), CaptionForeground = caption.Foreground.ToString(), Bounds = button.IsVisible ? Rectangle(button) : "not rendered" };
                    }).Cast<object>().ToArray();
                body.ApplyTemplate();
                System.Windows.Controls.Primitives.ScrollBar? bodyScrollBar = body.Template.FindName("PART_VerticalScrollBar", body) as System.Windows.Controls.Primitives.ScrollBar;
                bodyScrollBar?.ApplyTemplate();
                System.Windows.Controls.Primitives.Track? bodyTrack = bodyScrollBar?.Template.FindName("PART_Track", bodyScrollBar) as System.Windows.Controls.Primitives.Track;
                bodyTrack?.Thumb.ApplyTemplate();
                Border? bodyThumb = bodyTrack == null ? null : FindVisualChildren<Border>(bodyTrack.Thumb)
                    .FirstOrDefault(border => border.Background != null && border.ActualWidth > 1D && border.ActualHeight > 1D);
                string expectedThumb = ((Brush)body.FindResource("ScrollBarThumbFill")).ToString();
                if (body.ScrollableHeight > 1D && (bodyThumb == null || bodyThumb.Background?.ToString() != expectedThumb))
                    failures.Add(theme + "/" + state + ": the visible outer scrollbar uses a different palette.");
                object scrollChrome = new { ExpectedThumb = expectedThumb, ActualThumb = bodyThumb?.Background?.ToString(), Template = bodyScrollBar?.Template.GetType().Name,
                    Thumb = bodyThumb == null ? string.Empty : Rectangle(bodyThumb), bodyScrollBar?.IsVisible };
                string capture = Path.ChangeExtension(outputPath, "." + theme.ToLowerInvariant() + "." + state + ".png");
                ScreenshotPngWriter.WriteVisibleElementPng(document.View, capture);
                object[] chrome = FindVisualChildren<Border>(expander).Where(border => border.IsVisible && border.ActualHeight > 2D && border.ActualWidth > 2D)
                    .Select(border => new { border.Name, Background = border.Background?.ToString(), Border = border.BorderBrush?.ToString(),
                        Source = DependencyPropertyHelper.GetValueSource(border, Border.BackgroundProperty).BaseValueSource.ToString(),
                        TemplateParent = border.TemplatedParent?.GetType().FullName, Bounds = Rectangle(border) }).Cast<object>().ToArray();
                states.Add(new { State = state, ThemeRequest = theme, AppliedPanelBrush = ((Brush)expander.FindResource("VisionTool.PanelBrush")).ToString(), Capture = capture, expander.IsExpanded, HeaderInViewport = HeaderInViewport(),
                    ScrollBar = body.VerticalScrollBarVisibility.ToString(), body.VerticalOffset, body.ScrollableHeight, body.ViewportHeight, body.ExtentHeight,
                    Body = Rectangle(body), Header = Rectangle(header), Result = Rectangle(result), Chrome = chrome, Captions = captions, ScrollChrome = scrollChrome, Runs = host.NativePreviewRunCount, Layers = host.LayerDocumentCount });
            }
            foreach (string theme in new[] { "Dark", "Light" })
            {
                ResourceDictionary palette = new() { Source = new Uri($"pack://application:,,,/OpenVisionLab;component/UI/Wpf/OpenVisionWorkbench{theme}.xaml") };
                host.Resources.MergedDictionaries.Add(palette);
                try
                {
                    grid.ThemeVariant = theme == "Dark" ? System.Windows.Controls.WpfPropertyGrid.PropertyGridThemeVariant.Dark : System.Windows.Controls.WpfPropertyGrid.PropertyGridThemeVariant.Default;
                    expander.IsExpanded = false;
                    body.ScrollToHome();
                    Pump(20);
                    Observe("collapsed", theme);
                    int runs = host.NativePreviewRunCount;
                    int layers = host.LayerDocumentCount;
                    string route = host.DirectResultRouteText;
                    string step = JsonSerializer.Serialize(host.Workbench.Tool.CurrentStep);
                    expander.IsExpanded = true;
                    Pump(20);
                    Observe("expanded", theme);
                    if (host.NativePreviewRunCount != runs || host.LayerDocumentCount != layers || host.DirectResultRouteText != route
                        || JsonSerializer.Serialize(host.Workbench.Tool.CurrentStep) != step) failures.Add(theme + ": expanding suggestion executed or changed the working parameters/route/layers.");
                    host.RunActiveNativePreviewForTest();
                    Stopwatch wait = Stopwatch.StartNew();
                    while (host.NativePreviewRunCount == runs && wait.Elapsed < TimeSpan.FromSeconds(6)) { Pump(2); Thread.Sleep(10); }
                    Pump(24);
                    Observe("result-revealed", theme);
                    if (host.NativePreviewRunCount != runs + 1 || !host.Workbench.Tool.HasResult || host.Workbench.Tool.IsResultPrevious)
                        failures.Add(theme + ": explicit Run did not produce one current result.");
                    runs = host.NativePreviewRunCount;
                    layers = host.LayerDocumentCount;
                    step = JsonSerializer.Serialize(host.Workbench.Tool.CurrentStep);
                    body.ScrollToHome();
                    Pump(20);
                    Observe("scroll-top", theme);
                    if (!HeaderInViewport()) failures.Add(theme + ": the parameter header cannot be reached at scroll top.");
                    body.ScrollToEnd();
                    Pump(20);
                    Observe("scroll-bottom", theme);
                    if (host.NativePreviewRunCount != runs || host.LayerDocumentCount != layers || JsonSerializer.Serialize(host.Workbench.Tool.CurrentStep) != step)
                        failures.Add(theme + ": scroll changed execution, layers or parameters.");
                    expander.IsExpanded = false;
                    body.ScrollToHome();
                    Pump(20);
                    Observe("collapse-recovery", theme);
                    if (!HeaderInViewport()) failures.Add(theme + ": collapsing the suggestion left the parameter header hidden.");
                }
                finally { host.Resources.MergedDictionaries.Remove(palette); }
            }
            File.WriteAllText(Path.ChangeExtension(outputPath, ".container-checks.json"), JsonSerializer.Serialize(new
            { Width = width, Height = height, States = states, Failures = failures,
                Boundary = "In-process rendered container and explicit Run; original parameter editors/geometry remain unchanged; Light here requests only palette/fallback resources; complete Light theme belongs to Phase 10; native pointer/DPI verification is separate." }, new JsonSerializerOptions { WriteIndented = true }));
            if (failures.Count != 0) throw new InvalidOperationException(string.Join(Environment.NewLine, failures));
        });
    }

    private static CaptureResult CaptureMainLayoutIoRecovery(string outputPath)
    {
        DisplayManagerService display = new(); GlobalState global = new();
        global.Recipe.Name = "Smoke_LayoutIo_" + Guid.NewGuid().ToString("N");
        PropertyGridEditorFactory.SetRuntimeContext(() => display);
        PropertyGridEditorFactory.SetRecipeNameContext(() => global.Recipe.Name);
        if (!global.System.SaveWorkbenchLayout(new SystemStateConfig { WorkbenchLayoutVersion = 1, WorkbenchThemeName = "Dark" })) throw new InvalidOperationException("Initial owned layout save failed.");
        OpenVisionShellHostView host = new(new ApplicationRuntimeContext(global, display));
        return CaptureWindowWithContent(host, outputPath, 1280, 760, () =>
        {
            OpenVisionLanguageService.SetLanguage(OpenVisionLanguage.Korean, false);
            string path = RecipeWorkspaceService.GetSystemConfigPath("SYSTEM");
            byte[] before = File.ReadAllBytes(path);
            int runs = host.NativePreviewRunCount, layers = host.LayerDocumentCount;
            using (FileStream held = File.Open(path, FileMode.Open, FileAccess.ReadWrite, FileShare.None))
            {
                host.Workbench.SelectLightThemeCommand.Execute(null); Pump(4);
                if (host.Workbench.LayoutStatusText != OpenVisionLanguageService.T("Main.LayoutSaveFailed") || !host.Workbench.HasLayoutStatus)
                    throw new InvalidOperationException("Production layout I/O failure did not become the existing W09 failed-save state.");
                if (global.System.WorkbenchLayoutPreferences.WorkbenchThemeName != "Light") throw new InvalidOperationException("Failed save changed the established in-memory preference policy.");
                ScreenshotPngWriter.WriteVisibleElementPng(host, Path.ChangeExtension(outputPath, ".failed.png"));
            }
            if (!before.SequenceEqual(File.ReadAllBytes(path))) throw new InvalidOperationException("Failed layout save replaced persisted bytes.");
            host.Workbench.SelectDarkThemeCommand.Execute(null); Pump(4);
            if (host.Workbench.HasLayoutStatus || !string.IsNullOrEmpty(host.Workbench.LayoutStatusText)) throw new InvalidOperationException("Valid layout retry retained stale save-error state.");
            if (!SerializeHelper.TryLoadFromXmlFile(path, out SystemStateConfig persisted) || persisted.WorkbenchThemeName != "Dark" || persisted.WorkbenchLayoutVersion != 1) throw new InvalidOperationException("Valid retry did not persist the requested layout.");
            if (runs != host.NativePreviewRunCount || layers != host.LayerDocumentCount) throw new InvalidOperationException("Layout failure/recovery ran a tool or changed layers.");
            File.WriteAllText(Path.ChangeExtension(outputPath, ".checks.json"), JsonSerializer.Serialize(new { FailureState = OpenVisionLanguageService.T("Main.LayoutSaveFailed"), DiskBytesPreserved = true, MemoryPreferenceAfterFailure = "Light", Recovery = "Dark persisted; error cleared", runs, layers, Scope = "production callback with owned file-share lock; in-process WPF, not actual input" }, new JsonSerializerOptions { WriteIndented = true }));
        });
    }

    private static CaptureResult CaptureToolSegmentCaptionContract(string outputPath)
    {
        StackPanel panel = new();
        panel.Resources.MergedDictionaries.Add(new ResourceDictionary { Source = new Uri("/OpenVisionLab;component/UI/VisionTest/Wpf/Tooling/Presentation/VisionToolWpfTheme.xaml", UriKind.Relative) });
        panel.Resources.MergedDictionaries.Add(new ResourceDictionary { Source = new Uri("/OpenVisionLab;component/UI/Wpf/OpenVisionWorkbenchLight.xaml", UriKind.Relative) });
        Style style = (Style)panel.FindResource("VisionTool.SegmentedRadioButtonStyle");
        RadioButton formatted = new() { Content = 42, ContentStringFormat = "Value {0}", Style = style };
        Grid content = new(); content.Children.Add(new MahApps.Metro.IconPacks.PackIconMaterial { Kind = MahApps.Metro.IconPacks.PackIconMaterialKind.VectorLine, Width = 16, Height = 16 });
        RadioButton visual = new() { Content = content, Style = style };
        FrameworkElementFactory text = new(typeof(TextBlock)); text.SetValue(TextBlock.TextProperty, "Explicit template");
        RadioButton templated = new() { Content = "ignored", ContentTemplate = new DataTemplate { VisualTree = text }, Style = style };
        RadioButton mnemonic = new() { Content = "_Edge", Style = style };
        foreach (RadioButton button in new[] { formatted, visual, templated, mnemonic }) panel.Children.Add(button);
        return CaptureWindowWithContent(panel, outputPath, 600, 240, () =>
        {
            string rendered = string.Join("|", FindVisualChildren<TextBlock>(panel).Select(item => item.Text));
            if (!rendered.Contains("Value 42") || !rendered.Contains("Explicit template")) throw new InvalidOperationException("Segment caption format/template text lost: " + rendered);
            if (!FindVisualChildren<Grid>(visual).Contains(content) || !FindVisualChildren<MahApps.Metro.IconPacks.PackIconMaterial>(visual).Any()) throw new InvalidOperationException("Segment UIElement/icon content lost.");
            if (!FindVisualChildren<AccessText>(mnemonic).Any(item => item.Text == "_Edge")) throw new InvalidOperationException("Segment access-key path lost.");
        });
    }

    private static CaptureResult CaptureMainPropertyGridTheme(string outputPath, int width, int height)
    {
        OpenVisionLanguageService.SetLanguage(OpenVisionLanguage.Korean, false);
        OpenVisionShellHostView host = CreateShellHost("Smoke_MainPgTheme_" + Guid.NewGuid().ToString("N"), seedMainLayer: false);
        List<object> checks = new();
        return CaptureWindowWithContent(host, outputPath, width, height, () =>
        {
            OpenVisionLanguageService.SetLanguage(OpenVisionLanguage.Korean, false);
            host.Workbench.Tool.ConfigureAutoRunPreference(() => false, _ => { });
            foreach (VISION_MENU menu in new[] { VISION_MENU.Line, VISION_MENU.Blob, VISION_MENU.Contour, VISION_MENU.Matching })
            {
                host.SelectToolForTest(menu); Pump(18);
                OpenVisionNativeToolDocument document = host.ActiveNativeDocumentForTest!;
                var grid = FindVisualChildren<System.Windows.Controls.WpfPropertyGrid.PropertyGrid>(document.View).Single();
                var shell = FindVisualChildren<VisionToolSingleInputPropertyToolShell>(document.View).Single();
                Panel panel = (Panel)shell.FindName("parameterPanel");
                object selected = grid.SelectedObject;
                string model = JsonSerializer.Serialize(host.Workbench.Tool.CurrentStep);
                string rows = string.Join("|", FindVisualChildren<TextBlock>(grid).Where(text => text.IsVisible && text.GetType().Name == "PropertyNameTextBlock").Select(text => text.Text));
                int runs = document.PreviewRunCount, layers = host.LayerDocumentCount;
                string route = host.DirectResultRouteText;
                foreach (string theme in new[] { "Light", "Dark", "Light" })
                {
                    (theme == "Light" ? host.Workbench.SelectLightThemeCommand : host.Workbench.SelectDarkThemeCommand).Execute(null); Pump(18);
                    var expected = theme == "Light" ? System.Windows.Controls.WpfPropertyGrid.PropertyGridThemeVariant.Default : System.Windows.Controls.WpfPropertyGrid.PropertyGridThemeVariant.Dark;
                    if (grid.ThemeVariant != expected) throw new InvalidOperationException(menu + "/" + theme + ": PropertyGrid did not follow Main theme.");
                    if (panel.Background.ToString() != ((Brush)host.FindResource("OpenVision.Workbench.PanelBrush")).ToString()) throw new InvalidOperationException(menu + "/" + theme + ": parameter panel surface did not follow Main theme.");
                    Border presets = (Border)shell.FindName("bdPresetHost");
                    if (presets.Background.ToString() != ((Brush)host.FindResource("OpenVision.Workbench.RaisedBrush")).ToString()) throw new InvalidOperationException(menu + "/" + theme + ": preset surface did not follow Main theme: " + presets.Background + " expected " + host.FindResource("OpenVision.Workbench.RaisedBrush"));
                    if (menu == VISION_MENU.Line)
                    {
                        Border purpose = (Border)((FrameworkElement)document.View).FindName("purposeContentHost");
                        ScreenshotPngWriter.WriteVisibleElementPng(purpose, Path.ChangeExtension(outputPath, ".purpose-" + theme + ".png"));
                        File.WriteAllText(Path.ChangeExtension(outputPath, ".purpose-" + theme + ".json"), JsonSerializer.Serialize(FindVisualChildren<TextBlock>(purpose).Where(text => text.IsVisible && !string.IsNullOrWhiteSpace(text.Text)).Select(text => new { text.Text, Foreground = text.Foreground.ToString(), Resource = text.FindResource("OpenVision.Workbench.TextBrush").ToString(), Source = DependencyPropertyHelper.GetValueSource(text, TextBlock.ForegroundProperty).BaseValueSource.ToString(), Parent = VisualTreeHelper.GetParent(text)?.GetType().Name }), new JsonSerializerOptions { WriteIndented = true }));
                        if (purpose.Background.ToString() != ((Brush)host.FindResource("OpenVision.Workbench.PanelAltBrush")).ToString()) throw new InvalidOperationException("Line purpose surface did not follow Main theme.");
                        foreach (TextBlock caption in FindVisualChildren<TextBlock>(purpose).Where(text => text.IsVisible && !string.IsNullOrWhiteSpace(text.Text)))
                        {
                            System.Windows.Media.Color captionBackground = ((SolidColorBrush)purpose.Background).Color;
                            for (DependencyObject? parent = VisualTreeHelper.GetParent(caption); parent != null && !ReferenceEquals(parent, purpose); parent = VisualTreeHelper.GetParent(parent))
                                if (parent is Border { Name: "segmentChrome", Background: SolidColorBrush chrome })
                                {
                                    double alpha = chrome.Color.A / 255D;
                                    captionBackground = System.Windows.Media.Color.FromRgb((byte)Math.Round(chrome.Color.R * alpha + captionBackground.R * (1D - alpha)), (byte)Math.Round(chrome.Color.G * alpha + captionBackground.G * (1D - alpha)), (byte)Math.Round(chrome.Color.B * alpha + captionBackground.B * (1D - alpha)));
                                    break;
                                }
                            if (caption.Foreground is not SolidColorBrush fg || GetContrastRatio(fg.Color, captionBackground) < 4.5D)
                                throw new InvalidOperationException("Line/" + theme + " purpose rendered caption contrast below 4.5:1: " + caption.Text + " foreground=" + caption.Foreground + " background=" + captionBackground);
                        }
                    }
                    TextBox name = FindVisualChildren<TextBox>(grid).First(text => text.IsVisible && AutomationProperties.GetAutomationId(text) == "NAME");
                    if (name.Foreground is not SolidColorBrush foreground || FindOpaqueVisualBackground(name) is not SolidColorBrush background
                        || GetContrastRatio(foreground.Color, background.Color) < 4.5D) throw new InvalidOperationException(menu + "/" + theme + ": rendered name contrast below 4.5:1.");
                    if (!ReferenceEquals(selected, grid.SelectedObject) || model != JsonSerializer.Serialize(host.Workbench.Tool.CurrentStep)
                        || rows != string.Join("|", FindVisualChildren<TextBlock>(grid).Where(text => text.IsVisible && text.GetType().Name == "PropertyNameTextBlock").Select(text => text.Text))
                        || runs != document.PreviewRunCount || layers != host.LayerDocumentCount || route != host.DirectResultRouteText)
                        throw new InvalidOperationException(menu + "/" + theme + ": theme transition changed model, rows, execution, layers or routing.");
                    checks.Add(new { Tool = menu.ToString(), Theme = theme, GridTheme = grid.ThemeVariant.ToString(), PanelBackground = panel.Background.ToString(), NameBackground = background.ToString(), NameForeground = foreground.ToString(), Contrast = GetContrastRatio(foreground.Color, background.Color), width, height, Scope = "in-process WPF; no actual input/native DPI" });
                    ScreenshotPngWriter.WriteVisibleElementPng(host, Path.ChangeExtension(outputPath, "." + menu + "-" + theme + ".png"));
                }
            }
            File.WriteAllText(Path.ChangeExtension(outputPath, ".checks.json"), JsonSerializer.Serialize(checks, new JsonSerializerOptions { WriteIndented = true }));
        });
    }

    private static CaptureResult CaptureWorkbenchPropertyGridTheme(string outputPath, int width, int height, bool inspectAllEditors = false, bool inspectConditionalEditors = false)
    {
        OpenVisionLanguageService.SetLanguage(OpenVisionLanguage.Korean, false);
        string recipeName = "Smoke_WorkbenchPgTheme_" + Guid.NewGuid().ToString("N");
        OpenVisionShellHostView host = CreateShellHost(recipeName, seedMainLayer: false);
        List<string> failures = new();
        List<object> measurements = new();
        List<object> popupChecks = new();
        List<object> editorRows = new();
        List<object> invariants = new();
        string rowCapture = string.Empty;
        return CaptureWindowWithContent(host, outputPath, width, height, () =>
        {
            string recipeDirectory = RecipeWorkspaceService.GetRecipeWorkspaceDirectory(recipeName);
            Dictionary<string, string> files = Directory.EnumerateFiles(recipeDirectory, "*", SearchOption.AllDirectories)
                .ToDictionary(Path.GetFullPath, path => Convert.ToHexString(SHA256.HashData(File.ReadAllBytes(path))));
            foreach (OpenVisionLanguage language in new[] { OpenVisionLanguage.Korean, OpenVisionLanguage.English })
            {
                OpenVisionLanguageService.SetLanguage(language, false);
                foreach (VISION_MENU menu in new[] { VISION_MENU.Blob, VISION_MENU.Contour, VISION_MENU.Line,
                    VISION_MENU.Matching, VISION_MENU.EdgeBasedMatching, VISION_MENU.FeatureMatching, VISION_MENU.AffineTransform })
                {
                    host.SelectToolForTest(menu);
                    Pump(18);
                    OpenVisionNativeToolDocument document = host.ActiveNativeDocumentForTest!;
                    System.Windows.Controls.WpfPropertyGrid.PropertyGrid grid = FindVisualChildren<System.Windows.Controls.WpfPropertyGrid.PropertyGrid>(document.View).Single();
                    if (inspectAllEditors) VisionToolDebouncedPreviewScheduler.SetAllowAutoPreview(document.View, false);
                    object selected = grid.SelectedObject;
                    int runs = document.PreviewRunCount;
                    int layers = host.LayerDocumentCount;
                    string route = host.DirectResultRouteText;
                    string prefix = language + "-" + menu;
                    if (language == OpenVisionLanguage.Korean && (grid.ThemeVariant != System.Windows.Controls.WpfPropertyGrid.PropertyGridThemeVariant.Dark
                        || (System.Windows.Controls.WpfPropertyGrid.PropertyGridThemeVariant)host.FindResource("OpenVision.Workbench.PropertyGridTheme")
                            != System.Windows.Controls.WpfPropertyGrid.PropertyGridThemeVariant.Dark))
                        failures.Add(prefix + ": initial Tool PropertyGrid did not select the D-08 Dark instance resource.");
                    string Rows() => string.Join("|", FindVisualChildren<TextBlock>(grid)
                        .Where(text => text.IsVisible && text.GetType().Name == "PropertyNameTextBlock").Select(text => text.Text));
                    void Capture(string state) => ScreenshotPngWriter.WriteVisibleElementPng(host,
                        Path.ChangeExtension(outputPath, "." + prefix + "-" + state + ".png"));
                    TextBox NameEditor() => FindVisualChildren<TextBox>(grid).First(text => text.IsVisible
                        && string.Equals(AutomationProperties.GetAutomationId(text), "NAME", StringComparison.OrdinalIgnoreCase));
                    grid.ThemeVariant = System.Windows.Controls.WpfPropertyGrid.PropertyGridThemeVariant.Default;
                    Pump(18);
                    TextBox defaultEditor = NameEditor();
                    string defaultBackground = defaultEditor.Background.ToString();
                    string defaultForeground = defaultEditor.Foreground.ToString();
                    Dictionary<string, string> RangeSurfaces()
                    {
                        Dictionary<string, string> surfaces = new();
                        foreach (Border row in FindVisualChildren<Border>(grid).Where(item => item.Name == "RowBorder"))
                        {
                            string property = (row.DataContext?.GetType().GetProperty("PropertyDescriptor")?.GetValue(row.DataContext) as PropertyDescriptor)?.Name ?? string.Empty;
                            foreach (Grid range in FindVisualChildren<Grid>(row).Where(item => item.GetType().FullName == "System.Windows.Controls.WpfPropertyGrid.Controls.RangeEditorBase"))
                            {
                                foreach (TextBlock caption in range.Children.OfType<TextBlock>())
                                    surfaces[property + "/caption-" + Grid.GetRow(caption) + "-" + Grid.GetColumn(caption)] = caption.Foreground?.ToString() ?? "null";
                                int sliderIndex = 0;
                                foreach (Slider slider in FindVisualChildren<Slider>(range))
                                {
                                    string key = property + "/slider-" + sliderIndex++;
                                    surfaces[key + "/foreground"] = slider.Foreground?.ToString() ?? "null";
                                    surfaces[key + "/background"] = slider.Background?.ToString() ?? "null";
                                }
                            }
                        }
                        return surfaces;
                    }
                    Dictionary<string, string> defaultRangeSurfaces = RangeSurfaces();
                    string rows = Rows();
                    Capture("default-before");
                    grid.ThemeVariant = System.Windows.Controls.WpfPropertyGrid.PropertyGridThemeVariant.Dark;
                    Pump(18);
                    Capture("dark-normal");
                    if (!ReferenceEquals(selected, grid.SelectedObject) || rows != Rows())
                        failures.Add(prefix + ": theme changed selected model or visible row order.");
                    if (inspectAllEditors)
                    {
                        string stepBefore = JsonSerializer.Serialize(host.Workbench.Tool.CurrentStep);
                        bool hadResult = host.Workbench.Tool.HasResult;
                        PropertyDescriptor[] descriptors = TypeDescriptor.GetProperties(selected).Cast<PropertyDescriptor>().ToArray();
                        HashSet<string> companionNames = descriptors.Select(item => item.Attributes[typeof(System.Windows.Controls.WpfPropertyGrid.RangeEditorAttribute)] as System.Windows.Controls.WpfPropertyGrid.RangeEditorAttribute)
                            .Where(item => item != null).Select(item => item!.MaxPropertyName).ToHashSet(StringComparer.Ordinal);
                        string[] baselineNames = descriptors.Where(item => item.IsBrowsable && grid.Properties[item.Name]?.IsBrowsable == true && !companionNames.Contains(item.Name)).Select(item => item.Name).ToArray();
                        Dictionary<PropertyInfo, object?> fixtureValues = new();
                        List<(Expander View, TextBlock Header, ToggleButton? Toggle, ControlTemplate ViewTemplate,
                            ControlTemplate? ToggleTemplate, string HeaderForeground, string? ToggleForeground)> collectionDefaults = new();
                        bool collectionDefaultRestored = true;
                        bool collectionTemplatesStable = true;
                        string expandedRows = rows;
                        string[] expandedNames = baselineNames;
                        string[] names = baselineNames;
                        try
                        {
                            if (inspectConditionalEditors)
                            {
                                foreach (string setting in new[] { "USE_THRESHOLD", "USE_ADAPTIVE_THRESHOLD", "USE_ROI", "USE_MULTI_ROI", "USE_MASKING", "USE_APPROXPOLYDP",
                                    "USE_FIND_ANGLE", "USE_FIND_SCALE", "USE_COARSE_TO_FINE_ANGLE_SEARCH", "USE_PYRAMID_POSITION_PROPOSAL", "USE_CANNY",
                                    "USE_MANUAL_ANGLE", "USE_EXTEND_FIT_LINE", "ShowAdvancedSettings", "USE_UNIQUE_MATCH_VALIDATION", "AUTO_MPOINT_USE_ANALYSIS_ROI", "USE_HYBRID_VERIFY", "UseDetectedSourcePoints" })
                                {
                                    PropertyInfo? settingProperty = selected.GetType().GetProperty(setting);
                                    if (settingProperty?.PropertyType != typeof(bool) || !settingProperty.CanWrite) continue;
                                    fixtureValues.Add(settingProperty, settingProperty.GetValue(selected));
                                    settingProperty.SetValue(selected, setting != "UseDetectedSourcePoints");
                                }
                                PropertyInfo? borderSetting = selected.GetType().GetProperty("BorderType");
                                if (borderSetting?.PropertyType == typeof(OpenCvSharp.BorderTypes) && borderSetting.CanWrite)
                                {
                                    fixtureValues.Add(borderSetting, borderSetting.GetValue(selected));
                                    borderSetting.SetValue(selected, OpenCvSharp.BorderTypes.Constant);
                                }
                                new PropertyGridEventBinder(null).ApplyVisibilityRules(grid);
                                grid.RefreshSelectedObject();
                                Pump(18);
                                grid.ThemeVariant = System.Windows.Controls.WpfPropertyGrid.PropertyGridThemeVariant.Default;
                                Pump(18);
                                Capture("conditional-default-expanded");
                                foreach (Expander expander in FindVisualChildren<Expander>(grid))
                                {
                                    if (expander.Header is not TextBlock header) continue;
                                    ToggleButton? toggle = FindVisualChildren<ToggleButton>(expander).FirstOrDefault(item => item.Name == "ExpanderToggleButton");
                                    collectionDefaults.Add((expander, header, toggle, expander.Template, toggle?.Template, header.Foreground.ToString(), toggle?.Foreground.ToString()));
                                }
                                expandedRows = Rows();
                                grid.ThemeVariant = System.Windows.Controls.WpfPropertyGrid.PropertyGridThemeVariant.Dark;
                                Pump(18);
                                Capture("conditional-dark-expanded");
                                if (!ReferenceEquals(selected, grid.SelectedObject) || expandedRows != Rows()) failures.Add(prefix + ": expanded theme changed model or row order.");
                                descriptors = TypeDescriptor.GetProperties(selected).Cast<PropertyDescriptor>().ToArray();
                                companionNames = descriptors.Select(item => item.Attributes[typeof(System.Windows.Controls.WpfPropertyGrid.RangeEditorAttribute)] as System.Windows.Controls.WpfPropertyGrid.RangeEditorAttribute)
                                    .Where(item => item != null).Select(item => item!.MaxPropertyName).ToHashSet(StringComparer.Ordinal);
                            }
                            expandedNames = descriptors.Where(item => item.IsBrowsable && grid.Properties[item.Name]?.IsBrowsable == true && !companionNames.Contains(item.Name)).Select(item => item.Name).ToArray();
                            names = inspectConditionalEditors ? expandedNames.Except(baselineNames, StringComparer.Ordinal).ToArray() : baselineNames;
                            if (!inspectConditionalEditors && names.Length == 0) failures.Add(prefix + ": no rendered baseline rows selected.");
                            foreach (string propertyName in names)
                            {
                                if (!grid.FocusProperty(propertyName)) { failures.Add(prefix + "/" + propertyName + ": browsable row could not be brought into view."); continue; }
                                Pump(6);
                                Border? row = FindVisualChildren<Border>(grid).FirstOrDefault(item => item.Name == "RowBorder"
                                    && (item.DataContext?.GetType().GetProperty("PropertyDescriptor")?.GetValue(item.DataContext) as PropertyDescriptor)?.Name == propertyName);
                                if (row == null || !row.IsVisible || row.ActualWidth <= 0 || row.ActualHeight <= 0) { failures.Add(prefix + "/" + propertyName + ": rendered descriptor row missing or collapsed."); continue; }
                                rowCapture = Path.ChangeExtension(outputPath, "." + prefix + "-" + propertyName + "-row.png");
                                ScreenshotPngWriter.WriteVisibleElementPng(row, rowCapture);
                                FrameworkElement[] children = FindVisualChildren<FrameworkElement>(row).Where(item => item.IsVisible && item.ActualWidth > 0 && item.ActualHeight > 0).ToArray();
                                List<object> texts = new();
                                foreach (Grid range in children.OfType<Grid>().Where(item => item.GetType().FullName == "System.Windows.Controls.WpfPropertyGrid.Controls.RangeEditorBase"))
                                {
                                    for (int endpoint = 0; endpoint < 2; endpoint++)
                                    {
                                        TextBlock? caption = range.Children.OfType<TextBlock>().SingleOrDefault(item => Grid.GetColumn(item) == 0 && Grid.GetRow(item) == endpoint);
                                        string expected = language == OpenVisionLanguage.Korean ? endpoint == 0 ? "하한" : "상한" : endpoint == 0 ? "Lower" : "Upper";
                                        if (caption?.Text != expected) failures.Add(prefix + "/" + propertyName + ": range endpoint caption failed: " + caption?.Text + " != " + expected);
                                    }
                                }
                                foreach (TextBlock text in children.OfType<TextBlock>().Where(item => !string.IsNullOrWhiteSpace(item.Text)))
                                {
                                    bool icon = text.FontFamily.Source == "pack://application:,,,/Wpf.Ui;component/Resources/Fonts/#FluentSystemIcons-Regular"
                                        && text.Text.All(character => character >= '\uE000' && character <= '\uF8FF');
                                    double minimumContrast = icon ? 3D : 4.5D;
                                    List<object> ancestors = new();
                                    for (DependencyObject? parent = VisualTreeHelper.GetParent(text); parent is FrameworkElement element && !ReferenceEquals(parent, row); parent = VisualTreeHelper.GetParent(parent))
                                        ancestors.Add(new { Type = element.GetType().FullName, element.Name, Header = (element as HeaderedContentControl)?.Header?.ToString(), Foreground = (element as Control)?.Foreground?.ToString() });
                                    SolidColorBrush? background = FindOpaqueVisualBackground(text);
                                    double contrast = text.Foreground is SolidColorBrush fg && background != null ? GetContrastRatio(fg.Color, background.Color) : 0;
                                    FormattedText required = new(text.Text, CultureInfo.CurrentCulture, text.FlowDirection,
                                        new Typeface(text.FontFamily, text.FontStyle, text.FontWeight, text.FontStretch), text.FontSize, text.Foreground, VisualTreeHelper.GetDpi(text).PixelsPerDip);
                                    Rect bounds = text.TransformToAncestor(grid).TransformBounds(new Rect(text.RenderSize));
                                    Rect visible = bounds; visible.Intersect(new Rect(grid.RenderSize));
                                    texts.Add(new { text.Text, Type = text.GetType().Name, Foreground = text.Foreground?.ToString(), Background = background?.ToString(), Contrast = contrast,
                                        FontFamily = text.FontFamily.Source, text.FontSize, text.Opacity, text.ActualWidth, text.ActualHeight, RequiredWidth = required.Width, RequiredHeight = required.Height,
                                        Bounds = bounds.ToString(), VisibleBounds = visible.ToString(), WidthClipped = text.ActualWidth + 2D < required.Width, IsIcon = icon, MinimumContrast = minimumContrast, Ancestors = ancestors });
                                    if (contrast < minimumContrast) failures.Add(prefix + "/" + propertyName + ": rendered text/icon contrast below " + minimumContrast + ":1: " + text.Text);
                                    if (text.ActualWidth + 2D < required.Width) failures.Add(prefix + "/" + propertyName + ": label clipped: " + text.Text);
                                    if (!icon && text.FontFamily.Source != grid.FontFamily.Source) failures.Add(prefix + "/" + propertyName + ": text font differs from grid: " + text.FontFamily.Source);
                                }
                                int index = 0;
                                foreach (Control control in children.OfType<Control>().Where(item => item is TextBox or CheckBox or ComboBox or Button or Slider))
                                {
                                    string childName = prefix + "/" + propertyName + "/" + control.GetType().Name + "-" + index++;
                                    try
                                    {
                                        if (control is TextBox textBox) RecordContrast(textBox, childName);
                                        else if (control is CheckBox) RecordControl(control, childName, "CheckChrome");
                                        else if (control is ComboBox) RecordControl(control, childName, "ComboChrome");
                                        else if (control is Button && control.Template?.FindName("DialogChrome", control) is Border) RecordControl(control, childName, "DialogChrome");
                                        else if (control is Slider rowSlider) foreach (Thumb thumb in FindVisualChildren<Thumb>(rowSlider)) RecordControl(thumb, childName + "/thumb", "ThumbChrome");
                                    }
                                    catch (InvalidOperationException ex) { failures.Add(childName + ": " + ex.Message); }
                                }
                                editorRows.Add(new { Name = prefix + "/" + propertyName, row.ActualWidth, row.ActualHeight, Capture = rowCapture, Texts = texts,
                                    ChildTypes = children.OfType<Control>().Select(item => item.GetType().FullName).Distinct().ToArray() });
                            }
                            Capture("all-editors-bottom-context");
                            if (inspectConditionalEditors)
                            {
                                collectionTemplatesStable = collectionDefaults.All(item => ReferenceEquals(item.View.Template, item.ViewTemplate) && ReferenceEquals(item.Toggle?.Template, item.ToggleTemplate));
                                grid.ThemeVariant = System.Windows.Controls.WpfPropertyGrid.PropertyGridThemeVariant.Default;
                                Pump(18);
                                collectionDefaultRestored = collectionDefaults.All(item => item.Header.Foreground.ToString() == item.HeaderForeground && item.Toggle?.Foreground.ToString() == item.ToggleForeground);
                                collectionTemplatesStable &= collectionDefaults.All(item => ReferenceEquals(item.View.Template, item.ViewTemplate) && ReferenceEquals(item.Toggle?.Template, item.ToggleTemplate));
                                Capture("conditional-default-expanded-restored");
                                if (!collectionDefaultRestored || !collectionTemplatesStable) failures.Add(prefix + ": collection header Default palette or template identity did not restore.");
                            }
                        }
                        finally
                        {
                            foreach (KeyValuePair<PropertyInfo, object?> setting in fixtureValues) setting.Key.SetValue(selected, setting.Value);
                            if (inspectConditionalEditors)
                            {
                                new PropertyGridEventBinder(null).ApplyVisibilityRules(grid);
                                grid.RefreshSelectedObject();
                                Pump(18);
                            }
                        }
                        bool configurationRestored = fixtureValues.All(setting => Equals(setting.Key.GetValue(selected), setting.Value));
                        grid.FocusProperty("NAME");
                        Pump(6);
                        Capture("all-editors-top-context");
                        grid.ThemeVariant = System.Windows.Controls.WpfPropertyGrid.PropertyGridThemeVariant.Default;
                        Pump(18);
                        TextBox restoredEditor = NameEditor();
                        bool valuesUnchanged = ReferenceEquals(selected, grid.SelectedObject) && stepBefore == JsonSerializer.Serialize(host.Workbench.Tool.CurrentStep);
                        bool stateUnchanged = document.PreviewRunCount == runs && host.Workbench.Tool.HasResult == hadResult && host.LayerDocumentCount == layers && host.DirectResultRouteText == route;
                        bool defaultRestored = restoredEditor.Background.ToString() == defaultBackground && restoredEditor.Foreground.ToString() == defaultForeground;
                        bool rowsUnchanged = rows == Rows();
                        invariants.Add(new { Name = prefix, BrowsableNames = names, ExcludedNames = descriptors.Select(item => item.Name).Except(names).ToArray(), ValuesUnchanged = valuesUnchanged,
                            StateUnchanged = stateUnchanged, DefaultRestored = defaultRestored, RowsUnchanged = rowsUnchanged, RangeCompanions = companionNames.ToArray(),
                            ConditionalRows = inspectConditionalEditors, BaselineNames = baselineNames, ExpandedNames = expandedNames, ConfigurationRestored = configurationRestored,
                            FixtureSettings = fixtureValues.Select(setting => new { Name = setting.Key.Name, Original = setting.Value?.ToString() }).ToArray(),
                            CollectionCount = collectionDefaults.Count, CollectionDefaultRestored = collectionDefaultRestored, CollectionTemplatesStable = collectionTemplatesStable });
                        if (!valuesUnchanged || !stateUnchanged || !defaultRestored || !rowsUnchanged || !configurationRestored) failures.Add(prefix + ": row inventory changed values/state/order or failed Default/configuration restore.");
                        continue;
                    }
                    TextBox editor = NameEditor();
                    editor.Focus();
                    Pump(6);
                    Capture("dark-focused");
                    grid.FocusProperty("NAME");
                    Border? selectedRow = FindVisualChildren<Border>(grid).FirstOrDefault(item => item.Name == "RowBorder" && item.IsAncestorOf(editor));
                    if (selectedRow == null) throw new InvalidOperationException(prefix + ": WPG row container missing.");
                    Pump(12);
                    Capture("dark-selected");
                    TextBlock selectedLabel = FindVisualChildren<TextBlock>(selectedRow).First(item => item.GetType().Name == "PropertyNameTextBlock");
                    Border selectedCell = FindVisualChildren<Border>(selectedRow).First(item => item.Name == "NameCell");
                    if (selectedLabel.Foreground is not SolidColorBrush selectedForeground || selectedCell.Background is not SolidColorBrush selectedBackground)
                        throw new InvalidOperationException(prefix + ": selected row palette missing.");
                    double selectedContrast = GetContrastRatio(selectedForeground.Color, selectedBackground.Color);
                    measurements.Add(new { Name = prefix + "/selected-label", Foreground = selectedForeground.Color.ToString(), Background = selectedBackground.Color.ToString(),
                        TextContrast = selectedContrast, NameColumnWidth = selectedCell.ActualWidth, LabelOpacity = selectedLabel.Opacity,
                        Capture = CaptureControl(selectedRow, prefix + "/selected-label") });
                    if (selectedContrast < 4.5D) failures.Add(prefix + ": selected row label contrast below 4.5:1.");

                    RecordContrast(editor, prefix + "/normal");
                    editor.IsEnabled = false;
                    Pump(6);
                    Capture("dark-disabled");
                    RecordContrast(editor, prefix + "/disabled");
                    editor.IsEnabled = true;
                    editor.IsReadOnly = true;
                    Pump(6);
                    RecordContrast(editor, prefix + "/read-only");
                    editor.IsReadOnly = false;
                    BindingExpression? nameBinding = editor.GetBindingExpression(TextBox.TextProperty);
                    if (nameBinding != null)
                    {
                        Validation.MarkInvalid(nameBinding, new ValidationError(new ExceptionValidationRule(), nameBinding, "SmokeValidation", null));
                        Pump(6);
                        RecordContrast(editor, prefix + "/validation-error");
                        Validation.ClearInvalid(nameBinding);
                    }
                    CheckBox? checkBox = FindVisualChildren<CheckBox>(grid).FirstOrDefault(item => item.IsVisible);
                    if (checkBox != null)
                    {
                        RecordControl(checkBox, prefix + "/checkbox-normal", "CheckChrome");
                        checkBox.IsEnabled = false;
                        Pump(6);
                        RecordControl(checkBox, prefix + "/checkbox-disabled", "CheckChrome");
                        checkBox.IsEnabled = true;
                    }
                    Slider? slider = FindVisualChildren<Slider>(grid).FirstOrDefault(item => item.IsVisible);
                    if (slider != null)
                    {
                        Thumb thumb = FindVisualChildren<Thumb>(slider).First();
                        RecordControl(thumb, prefix + "/slider-normal", "ThumbChrome");
                        slider.IsEnabled = false;
                        Pump(6);
                        RecordControl(thumb, prefix + "/slider-disabled", "ThumbChrome");
                        slider.IsEnabled = true;
                    }
                    Button? dialogButton = FindVisualChildren<Button>(grid).FirstOrDefault(item => item.IsVisible
                        && item.Template?.FindName("DialogChrome", item) is Border);
                    if (dialogButton != null)
                    {
                        RecordControl(dialogButton, prefix + "/dialog-normal", "DialogChrome");
                        dialogButton.IsEnabled = false;
                        Pump(6);
                        RecordControl(dialogButton, prefix + "/dialog-disabled", "DialogChrome");
                        dialogButton.IsEnabled = true;
                    }
                    ComboBox? combo = FindVisualChildren<ComboBox>(grid).FirstOrDefault(item => item.IsVisible);
                    if (combo != null)
                    {
                        ControlTemplate comboTemplate = combo.Template;
                        object popupBeforeFocus = combo.Template.FindName("PART_Popup", combo);
                        grid.FocusProperty("NAME");
                        Pump(6);
                        combo.Focus();
                        combo.IsDropDownOpen = true;
                        Pump(12);
                        bool templateStable = ReferenceEquals(comboTemplate, combo.Template);
                        bool popupStable = ReferenceEquals(popupBeforeFocus, combo.Template.FindName("PART_Popup", combo));
                        popupChecks.Add(new { Name = prefix, TemplateStable = templateStable, PopupStable = popupStable, combo.IsKeyboardFocusWithin, combo.IsDropDownOpen,
                            FocusedElement = Keyboard.FocusedElement?.GetType().FullName });
                        if (!templateStable || !popupStable) failures.Add(prefix + ": focus/selection replaced an open ComboBox template or popup.");
                        combo.IsDropDownOpen = false;
                        Pump(6);
                        RecordControl(combo, prefix + "/combo-normal", "ComboChrome");
                        combo.IsEnabled = false;
                        Pump(6);
                        RecordControl(combo, prefix + "/combo-disabled", "ComboChrome");
                        combo.IsEnabled = true;
                        combo.IsDropDownOpen = true;
                        Pump(8);
                        Capture("dark-dropdown");
                        if (combo.Template.FindName("PART_Popup", combo) is Popup { Child: FrameworkElement popup })
                            ScreenshotPngWriter.WriteVisibleElementPng(popup, Path.ChangeExtension(outputPath, "." + prefix + "-dark-popup.png"));
                        combo.IsDropDownOpen = false;
                    }
                    TextBox search = GetActivePropertyGridSearchTextBox(grid, prefix);
                    search.Text = "ROI";
                    search.GetBindingExpression(TextBox.TextProperty)?.UpdateSource();
                    Pump(15);
                    Capture("dark-search-roi");
                    search.Text = "OVL_PG_NO_MATCH_20261008";
                    search.GetBindingExpression(TextBox.TextProperty)?.UpdateSource();
                    Pump(15);
                    Capture("dark-search-empty");
                    search.Clear();
                    search.GetBindingExpression(TextBox.TextProperty)?.UpdateSource();
                    Pump(15);
                    foreach (string placement in new[] { "Floating", "Redocked" })
                    {
                        bool moved = placement == "Floating" ? host.FloatDockedWpfToolWindowForTest() : host.DockActiveWpfToolWindowForTest();
                        if (!moved) throw new InvalidOperationException(prefix + ": " + placement + " placement failed.");
                        Pump(18);
                        if (!ReferenceEquals(document, host.ActiveNativeDocumentForTest) || !ReferenceEquals(grid, FindVisualChildren<System.Windows.Controls.WpfPropertyGrid.PropertyGrid>(document.View).Single())
                            || grid.ThemeVariant != System.Windows.Controls.WpfPropertyGrid.PropertyGridThemeVariant.Dark)
                            failures.Add(prefix + ": " + placement + " changed the native document/grid or Dark variant.");
                        if (placement == "Floating")
                        {
                            Window floating = Window.GetWindow(document.View);
                            if (floating?.Content is not Border frame || frame.Background?.ToString() != floating.FindResource("OpenVision.Workbench.PanelBrush").ToString()
                                || frame.BorderBrush?.ToString() != floating.FindResource("OpenVision.Workbench.AccentLineBrush").ToString()
                                || floating.FontFamily.Source != ((FontFamily)floating.FindResource("OpenVision.Workbench.FontFamily")).Source)
                                failures.Add(prefix + ": floating frame palette/font differs from Workbench resources.");
                            if (menu == VISION_MENU.Blob)
                                ScreenshotPngWriter.WriteVisibleElementPng(floating, Path.ChangeExtension(outputPath, "." + prefix + "-dark-floating-frame.png"));
                        }
                        ScreenshotPngWriter.WriteVisibleElementPng(document.View, Path.ChangeExtension(outputPath, "." + prefix + "-dark-" + placement + ".png"));
                        RecordContrast(NameEditor(), prefix + "/" + placement + "-name");
                        ComboBox? movedCombo = FindVisualChildren<ComboBox>(grid).FirstOrDefault(item => item.IsVisible);
                        if (movedCombo != null) RecordControl(movedCombo, prefix + "/" + placement + "-combo", "ComboChrome");
                    }
                    grid.ThemeVariant = System.Windows.Controls.WpfPropertyGrid.PropertyGridThemeVariant.Default;
                    Pump(18);
                    Capture("default-restored");
                    Dictionary<string, string> restoredRangeSurfaces = RangeSurfaces();
                    string[] rangeDifferences = defaultRangeSurfaces.Keys.Union(restoredRangeSurfaces.Keys).Where(key =>
                        !defaultRangeSurfaces.TryGetValue(key, out string before) || !restoredRangeSurfaces.TryGetValue(key, out string after) || before != after).ToArray();
                    measurements.Add(new { Name = prefix + "/default-range-restoration", Before = defaultRangeSurfaces, After = restoredRangeSurfaces, Differences = rangeDifferences });
                    if (rangeDifferences.Length != 0) failures.Add(prefix + ": Default range colors did not restore: " + string.Join(", ", rangeDifferences));
                    TextBox restored = NameEditor();
                    if (restored.Background.ToString() != defaultBackground || restored.Foreground.ToString() != defaultForeground)
                        failures.Add(prefix + ": Default color did not restore; before=" + defaultBackground + "/" + defaultForeground
                            + "; after=" + restored.Background + "/" + restored.Foreground);
                    if (!ReferenceEquals(selected, grid.SelectedObject) || rows != Rows() || document.PreviewRunCount != runs
                        || host.LayerDocumentCount != layers || host.DirectResultRouteText != route)
                        failures.Add(prefix + ": theme/search/selection changed model, row order, execution, layers or route.");
                }
            }
            if (files.Count != Directory.EnumerateFiles(recipeDirectory, "*", SearchOption.AllDirectories).Count()
                || files.Any(file => !File.Exists(file.Key) || Convert.ToHexString(SHA256.HashData(File.ReadAllBytes(file.Key))) != file.Value))
                failures.Add("Theme/search/selection changed recipe files.");
            File.WriteAllText(Path.ChangeExtension(outputPath, ".theme-checks.json"), JsonSerializer.Serialize(new
            {
                Width = width, Height = height, Measurements = measurements, PopupChecks = popupChecks, EditorRows = editorRows, Invariants = invariants, Failures = failures,
                Boundary = "In-process live visual tree and captures. Native pointer-down, native DPI, Computer Use input and full pixel contrast remain separate."
            }, new JsonSerializerOptions { WriteIndented = true }));
            if (failures.Count != 0) throw new InvalidOperationException(string.Join(Environment.NewLine, failures));
        });

        void RecordContrast(TextBox editor, string name)
        {
            if (editor.Foreground is not SolidColorBrush foreground || editor.Background is not SolidColorBrush background
                || editor.BorderBrush is not SolidColorBrush border) throw new InvalidOperationException(name + ": opaque editor palette missing.");
            double text = GetContrastRatio(foreground.Color, background.Color);
            double outline = GetContrastRatio(border.Color, background.Color);
            measurements.Add(new { Name = name, Foreground = foreground.Color.ToString(), Background = background.Color.ToString(),
                Border = border.Color.ToString(), TextContrast = text, BorderContrast = outline, FontFamily = editor.FontFamily.Source, editor.FontSize, Capture = CaptureControl(editor, name),
                Chrome = FindVisualChildren<Border>(editor).Where(item => item.IsVisible).Select(item => new { item.Name, Background = item.Background?.ToString(), Border = item.BorderBrush?.ToString(), item.Opacity, item.ActualWidth, item.ActualHeight }).ToArray() });
            if (text < 4.5D || outline < 3D) failures.Add(name + ": live editor brush contrast below 4.5:1 / 3:1.");
            if (FindVisualChildren<Border>(editor).Any(chrome => chrome.IsVisible && chrome.Opacity < 0.99D))
                failures.Add(name + ": vendor chrome opacity dimmed the rendered palette.");
        }
        string CaptureControl(FrameworkElement control, string name)
        {
            if (inspectAllEditors) return rowCapture;
            string capture = Path.ChangeExtension(outputPath, "." + name.Replace('/', '-') + "-palette.png");
            ScreenshotPngWriter.WriteVisibleElementPng(control, capture);
            return capture;
        }

        void RecordControl(Control control, string name, string chromeName)
        {
            control.ApplyTemplate();
            if (control.Template.FindName(chromeName, control) is not Border chrome
                || chrome.Background is not SolidColorBrush background || chrome.BorderBrush is not SolidColorBrush border)
                throw new InvalidOperationException(name + ": rendered template palette missing.");
            Brush foreground = control.Foreground;
            if (control is CheckBox && control.Template.FindName("CheckMark", control) is System.Windows.Shapes.Path mark)
                foreground = mark.Stroke;
            double text = foreground is SolidColorBrush fg ? GetContrastRatio(fg.Color, background.Color) : 0;
            double outline = GetContrastRatio(border.Color, System.Windows.Media.Color.FromRgb(20, 23, 29));
            double opacity = chrome.Opacity;
            List<string> opacityChain = new() { chrome.GetType().Name + ":" + chrome.Opacity };
            for (DependencyObject? parent = VisualTreeHelper.GetParent(chrome); parent is FrameworkElement element; parent = VisualTreeHelper.GetParent(parent))
            {
                opacity *= element.Opacity;
                if (element.Opacity < 0.99D) opacityChain.Add(element.GetType().Name + ":" + element.Opacity);
            }
            measurements.Add(new { Name = name, Foreground = foreground.ToString(), Background = background.Color.ToString(), Border = border.Color.ToString(),
                TextContrast = text, BorderContrast = outline, Opacity = opacity, OpacityChain = opacityChain, control.IsEnabled, IsReadOnly = control is ComboBox comboBox && comboBox.IsReadOnly,
                StyleType = control.Style?.TargetType.FullName, Capture = CaptureControl(control, name) });
            if ((control is ComboBox || control is Button || control is CheckBox { IsChecked: true }) && text < 4.5D || outline < 3D || opacity < 0.99D)
                failures.Add(name + ": rendered template contrast/opacity below the dark palette gate.");
        }

    }

    private static CaptureResult CaptureWorkbenchToolMenuState(string outputPath, VISION_MENU[]? selectedMenus = null, int width = 1920, int height = 1032, bool testFooter = false, bool acceptance = false, bool routeEditing = false, bool routeCandidates = false, bool resultSummary = false, bool autoRun = false, bool presets = false, bool templates = false)
    {
        OpenVisionLanguageService.SetLanguage(OpenVisionLanguage.Korean, false);
        string recipeName = "Smoke_WorkbenchToolMenuState_" + Guid.NewGuid().ToString("N");
        OpenVisionShellHostView host = CreateShellHost(recipeName, seedMainLayer: false);
        VisionPipeline pipeline = new() { Name = "Tool menu state" };
        if (routeCandidates)
        {
            pipeline.Steps.Add(new VisionPipelineStep { Name = "Candidate first", ToolType = "Threshold", InputLayer = "Main", OutputLayer = "Candidate_First" });
            pipeline.Steps.Add(new VisionPipelineStep { Name = "Candidate disabled", ToolType = "Mean", InputLayer = "Main", OutputLayer = "Candidate_Disabled", Enabled = false });
            pipeline.Steps.Add(new VisionPipelineStep { Name = "Candidate current", ToolType = "Mean", InputLayer = "Candidate_First", OutputLayer = "Candidate_Current" });
            pipeline.Steps.Add(new VisionPipelineStep { Name = "Candidate future", ToolType = "Mean", InputLayer = "Candidate_First", OutputLayer = "Candidate_Future" });
        }
        VisionPipelineStorage.Save(recipeName, pipeline);
        VisionPipelineStorage.SaveActivePipelineName(recipeName, pipeline.Name);
        host.RecipeCommands.RefreshOptions();
        host.RecipeCommands.SelectedPipelineOption = host.RecipeCommands.PipelineOptions.Single(option => option.PipelineName == pipeline.Name);
        using Bitmap template = CreateMatchingSmokeBitmap();
        string templatePath = CreateMatchingTemplateFile(template);
        return CaptureWindowWithContent(host, outputPath, width, height, () =>
        {
            if (templates)
            {
                WorkbenchToolWorkingCopySmoke.RunTemplates(host, outputPath, templatePath, Pump,
                    suffix => ScreenshotPngWriter.WriteVisibleElementPng(host, Path.ChangeExtension(outputPath, "." + suffix + ".png")));
            }
            else if (presets)
            {
                WorkbenchToolWorkingCopySmoke.RunPresets(host, outputPath, templatePath, Pump,
                    suffix => ScreenshotPngWriter.WriteVisibleElementPng(host, Path.ChangeExtension(outputPath, "." + suffix + ".png")), selectedMenus);
            }
            else if (autoRun)
            {
                WorkbenchToolWorkingCopySmoke.RunAutoRun(host, outputPath, Pump,
                    suffix => ScreenshotPngWriter.WriteVisibleElementPng(host, Path.ChangeExtension(outputPath, "." + suffix + ".png")));
            }
            else if (resultSummary)
            {
                WorkbenchToolWorkingCopySmoke.RunResultSummary(host, outputPath, Pump,
                    suffix => ScreenshotPngWriter.WriteVisibleElementPng(host, Path.ChangeExtension(outputPath, "." + suffix + ".png")));
            }
            else if (routeCandidates)
            {
                WorkbenchToolWorkingCopySmoke.RunRouteCandidates(host, outputPath, Pump,
                    suffix => ScreenshotPngWriter.WriteVisibleElementPng(host, Path.ChangeExtension(outputPath, "." + suffix + ".png")));
            }
            else if (routeEditing)
            {
                WorkbenchToolWorkingCopySmoke.RunRouteEditing(host, outputPath, Pump,
                    suffix => ScreenshotPngWriter.WriteVisibleElementPng(host, Path.ChangeExtension(outputPath, "." + suffix + ".png")));
            }
            else if (acceptance)
            {
                WorkbenchToolWorkingCopySmoke.RunAcceptance(host, outputPath, Pump,
                    suffix => ScreenshotPngWriter.WriteVisibleElementPng(host, Path.ChangeExtension(outputPath, "." + suffix + ".png")));
            }
            else if (testFooter)
            {
                WorkbenchToolWorkingCopySmoke.RunTestFooter(host, outputPath, Pump,
                    suffix => ScreenshotPngWriter.WriteVisibleElementPng(host, Path.ChangeExtension(outputPath, "." + suffix + ".png")));
            }
            else { WorkbenchToolWorkingCopySmoke.RunMenuState(host, outputPath, templatePath, Pump, selectedMenus); }
        });
    }

