    private static CaptureResult CaptureWorkbenchToolMenu(string outputPath, int width, int height)
    {
        OpenVisionLanguageService.SetLanguage(OpenVisionLanguage.Korean, false);
        string recipeName = "Smoke_WorkbenchToolMenu_" + Guid.NewGuid().ToString("N");
        OpenVisionShellHostView host = CreateShellHost(recipeName, seedMainLayer: false);
        VisionPipeline source = CreatePipelineReviewInputStatePipeline();
        source.Steps[1].InputLayer = source.Steps[0].OutputLayer;
        VisionPipelineStorage.Save(recipeName, source);
        VisionPipelineStorage.SaveActivePipelineName(recipeName, source.Name);
        host.RecipeCommands.RefreshOptions();
        host.RecipeCommands.SelectedPipelineOption = host.RecipeCommands.PipelineOptions.Single(option => option.PipelineName == source.Name);
        List<string> checks = new();
        return CaptureWindowWithContent(host, outputPath, width, height, () =>
        {
            OpenVisionWorkbenchPipelineViewModel pipeline = host.Workbench.Pipeline;
            string path = RecipeWorkspaceService.GetVisionPipelinePath(recipeName, source.Name);
            byte[] saved = File.ReadAllBytes(path);
            int layers = host.LayerDocumentCount;
            foreach (string theme in new[] { "Dark", "Light" })
            {
                ResourceDictionary palette = new() { Source = new Uri($"pack://application:,,,/OpenVisionLab;component/UI/Wpf/OpenVisionWorkbench{theme}.xaml") };
                host.Resources.MergedDictionaries.Add(palette);
                try
                {
                    foreach (OpenVisionLanguage language in new[] { OpenVisionLanguage.Korean, OpenVisionLanguage.English })
                    {
                        OpenVisionLanguageService.SetLanguage(language, false);
                        pipeline.SelectStepCommand.Execute(0);
                        Pump(6);
                        ListBox list = (ListBox)host.FindName("workbenchPipelineSteps");
                        Border secondRow = FindVisualChildren<Border>(list).Single(item => item.Name == "stepRow" && item.DataContext is OpenVisionWorkbenchStepViewModel row && row.Index == 1);
                        Button rowMenuButton = FindVisualChildren<Button>(secondRow).Single(item => ReferenceEquals(item.ContextMenu, secondRow.ContextMenu));
                        typeof(ButtonBase).GetMethod("OnClick", BindingFlags.Instance | BindingFlags.NonPublic)!.Invoke(rowMenuButton, null);
                        Pump(6);
                        if (pipeline.SelectedStepIndex != 1 || !host.Workbench.Tool.IsStepEditing || host.Workbench.Tool.ToolName != source.Steps[1].ToolType)
                            throw new InvalidOperationException("A row menu button must select and target its own row before a command is used.");
                        rowMenuButton.ContextMenu.IsOpen = false;
                        Button toolButton = FindVisualChildren<Button>(host).Single(item => AutomationProperties.GetAutomationId(item) == "WorkbenchToolMenuButton");
                        foreach (bool testing in new[] { false, true })
                        {
                            if (testing) { host.Workbench.Tool.NewTestCommand.Execute(null); Pump(6); }
                            toolButton.RaiseEvent(new RoutedEventArgs(Button.ClickEvent));
                            ContextMenu menu = toolButton.ContextMenu;
                            try
                            {
                                AssertWorkbenchMenuPopup(menu);
                                MenuItem[] visible = menu.Items.OfType<MenuItem>().Where(item => item.IsVisible).ToArray();
                                if (!ReferenceEquals(menu.DataContext, host.Workbench.Tool) || visible.Length != (testing ? 3 : 6)
                                    || visible.Any(item => string.IsNullOrEmpty(item.Header?.ToString()) || item.Header!.ToString()!.StartsWith("Workbench.", StringComparison.Ordinal)))
                                    throw new InvalidOperationException("Tool menu lost translated captions, current mode or its command owner.");
                                foreach (MenuItem item in visible)
                                {
                                    foreach (TextBlock label in FindVisualChildren<TextBlock>(item).Where(text => text.Text == item.Header?.ToString()))
                                    {
                                        FormattedText expected = new(label.Text, CultureInfo.CurrentCulture, label.FlowDirection,
                                            new Typeface(label.FontFamily, label.FontStyle, label.FontWeight, label.FontStretch), label.FontSize, label.Foreground, VisualTreeHelper.GetDpi(label).PixelsPerDip);
                                        if (label.ActualWidth + 2D < expected.Width || label.ActualHeight + 2D < expected.Height)
                                            throw new InvalidOperationException("Tool menu caption is clipped: " + label.Text);
                                    }
                                }
                                string suffix = "." + theme + "." + language + (testing ? ".test" : ".step");
                                FrameworkElement popupRoot = PresentationSource.FromVisual(menu)?.RootVisual as FrameworkElement
                                    ?? throw new InvalidOperationException("Tool menu popup has no rendered root.");
                                checks.Add(suffix + ": root=" + popupRoot.GetType().Name + ", rootSize=" + popupRoot.RenderSize + ", menuOffset=" + VisualTreeHelper.GetOffset(menu) + ", menuBounds=" + VisualTreeHelper.GetDescendantBounds(menu));
                                ScreenshotPngWriter.WriteVisibleElementPng(popupRoot, Path.ChangeExtension(outputPath, suffix + ".menu.png"));
                                ScreenshotPngWriter.WriteElementPng(host, Path.ChangeExtension(outputPath, suffix + ".png"), width, height);
                                checks.Add(theme + "/" + language + "/" + (testing ? "test" : "step") + ": translated menu, correct row target, typed separators, no clipping PASS");
                            }
                            finally { menu.IsOpen = false; }
                        }
                        if (!File.ReadAllBytes(path).SequenceEqual(saved) || host.LayerDocumentCount != layers || host.NativePreviewRunCount != 0)
                            throw new InvalidOperationException("Tool menu must not write XML, create layers or execute.");
                    }
                }
                finally { host.Resources.MergedDictionaries.Remove(palette); }
            }
            File.WriteAllText(Path.ChangeExtension(outputPath, ".menu.txt"), string.Join(Environment.NewLine, checks));
        });
    }

    private static CaptureResult CaptureWorkbenchToolGuide(string outputPath, int width, int height)
    {
        OpenVisionLanguageService.SetLanguage(OpenVisionLanguage.Korean, false);
        string recipeName = "Smoke_WorkbenchToolGuide_" + Guid.NewGuid().ToString("N");
        OpenVisionShellHostView host = CreateShellHost(recipeName, seedMainLayer: false);
        List<string> checks = new();
        return CaptureWindowWithContent(host, outputPath, width, height, () =>
        {
            string recipeDirectory = RecipeWorkspaceService.GetRecipeWorkspaceDirectory(recipeName);
            Dictionary<string, string> files = Directory.EnumerateFiles(recipeDirectory, "*", SearchOption.AllDirectories)
                .ToDictionary(path => path, path => Convert.ToHexString(SHA256.HashData(File.ReadAllBytes(path))));
            int layers = host.LayerDocumentCount;
            Window? previousGuide = null;
            foreach (string theme in new[] { "Dark", "Light" })
            {
                ResourceDictionary palette = new() { Source = new Uri($"pack://application:,,,/OpenVisionLab;component/UI/Wpf/OpenVisionWorkbench{theme}.xaml") };
                host.Resources.MergedDictionaries.Add(palette);
                try
                {
                    foreach (VISION_MENU menu in new[] { VISION_MENU.Threshold, VISION_MENU.Matching, VISION_MENU.Arithmetic, VISION_MENU.HSV, VISION_MENU.Histogram })
                    {
                        host.SelectToolForTest(menu);
                        Pump(12);
                        if (previousGuide?.IsVisible == true) throw new InvalidOperationException("Switching tools left an old parameter guide visible.");
                        OpenVisionNativeToolDocument document = host.ActiveNativeDocumentForTest!;
                        FrameworkElement view = document.View;
                        object shell = view.FindName("toolShell");
                        VisionToolParameterGuideView guide = shell is VisionToolSingleInputPropertyToolShell single ? single.ParameterGuide
                            : ((VisionToolDoubleInputCustomToolShell)shell).ParameterGuide;
                        guide.Resources.MergedDictionaries.Add(palette);
                        try
                        {
                            foreach (string token in new[] { "TextBrush", "SecondaryTextBrush", "PanelAltBrush", "RaisedBrush", "FieldBorderBrush", "AccentBrush", "HoverBrush", "PressedBrush", "StaleBrush" })
                                if (guide.TryFindResource("OpenVision.Workbench." + token) is not Brush)
                                    throw new InvalidOperationException("Guide theme token missing: " + token);
                            foreach (OpenVisionLanguage language in new[] { OpenVisionLanguage.Korean, OpenVisionLanguage.English })
                            {
                                OpenVisionLanguageService.SetLanguage(language, false);
                                Pump(4);
                                if (!host.Workbench.Tool.ParameterGuideCommand.CanExecute(null)) throw new InvalidOperationException(menu + ": parameter guide command unavailable.");
                                host.Workbench.Tool.ParameterGuideCommand.Execute(null);
                                Pump(6);
                                Window guideWindow = Window.GetWindow(guide) ?? throw new InvalidOperationException(menu + ": parameter guide has no window.");
                                previousGuide = guideWindow;
                                if (!guide.IsVisible || !guide.IsExpandedForTest || !ReferenceEquals(guideWindow.Owner, Window.GetWindow(host)))
                                    throw new InvalidOperationException(menu + ": explicit guide open must show expanded content owned by the current host.");
                                if (menu == VISION_MENU.Threshold && language == OpenVisionLanguage.Korean)
                                    ScreenshotPngWriter.WriteVisibleElementPng(guide, Path.ChangeExtension(outputPath, "." + theme + ".prompt.png"));
                                string expectedIdentity;
                                if (menu == VISION_MENU.Matching)
                                {
                                    System.Windows.Controls.WpfPropertyGrid.PropertyGrid grid = (System.Windows.Controls.WpfPropertyGrid.PropertyGrid)((VisionToolSingleInputPropertyToolShell)shell).PropertyGridHost.Child;
                                    if (!grid.FocusProperty("SCORE_MIN")) throw new InvalidOperationException("Matching parameter guide focus failed.");
                                    expectedIdentity = "SCORE_MIN";
                                }
                                else if (view is SimplePreprocessToolWpfView simple)
                                {
                                    expectedIdentity = menu == VISION_MENU.HSV ? "HueMin" : "HistogramType";
                                    FrameworkElement parameter = simple.Parameters.CreateParameterGuideBindings(new[] { expectedIdentity }).Keys.First();
                                    parameter.RaiseEvent(new KeyboardFocusChangedEventArgs(Keyboard.PrimaryDevice, 0, null, parameter) { RoutedEvent = Keyboard.GotKeyboardFocusEvent });
                                }
                                else
                                {
                                    FrameworkElement parameter = (FrameworkElement)view.FindName(menu == VISION_MENU.Threshold ? "txtThreshold" : "cbArithmeticType");
                                    parameter.RaiseEvent(new KeyboardFocusChangedEventArgs(Keyboard.PrimaryDevice, 0, null, parameter) { RoutedEvent = Keyboard.GotKeyboardFocusEvent });
                                    expectedIdentity = menu == VISION_MENU.Threshold ? nameof(ThresholdToolProperty.Threshold) : nameof(ArithmeticToolSettings.SelectedOperation);
                                }
                                Pump(6);
                                if (!guide.IdentityForTest.Contains(expectedIdentity, StringComparison.Ordinal) || !guide.IsExpandedForTest
                                    || guideWindow.Title != OpenVisionLanguageService.T("VisionTool.ParameterGuide.Header"))
                                    throw new InvalidOperationException(menu + ": guide selection, expansion or localized window title failed: " + guide.IdentityForTest);
                                ToggleButton header = FindVisualChildren<ToggleButton>(guide).Single(button => button.Name == "guideHeaderToggle");
                                if (header.ActualWidth < guide.ActualWidth - 4D || ((ScrollViewer)guide.FindName("guideScroll")).ActualHeight <= 184D
                                    || !((TextBlock)guide.FindName("txtHeader")).FontFamily.Source.Contains("Pretendard", StringComparison.OrdinalIgnoreCase))
                                    throw new InvalidOperationException(menu + ": guide header width, content height or font failed.");
                                if (menu == VISION_MENU.Arithmetic || language == OpenVisionLanguage.Korean)
                                    ScreenshotPngWriter.WriteVisibleElementPng(guide, Path.ChangeExtension(outputPath, "." + theme + "." + language + "." + menu + ".png"));
                                foreach (TextBlock text in FindVisualChildren<TextBlock>(guide).Where(text => text.IsVisible && !string.IsNullOrEmpty(text.Text)))
                                {
                                    Brush background = (Brush)guide.FindResource("VisionTool.PanelBrush");
                                    bool isRendered = true;
                                    bool backgroundResolved = false;
                                    for (DependencyObject parent = text; parent != null; parent = VisualTreeHelper.GetParent(parent))
                                    {
                                        if (parent is FrameworkElement { Opacity: <= 0 })
                                        {
                                            isRendered = false;
                                            break;
                                        }
                                        if (!backgroundResolved && parent is Border border && border.Background is SolidColorBrush { Color.A: > 0 } brush)
                                        {
                                            background = brush;
                                            backgroundResolved = true;
                                        }
                                    }
                                    if (!isRendered) continue;
                                    if (text.Foreground is SolidColorBrush foregroundBrush && background is SolidColorBrush backgroundBrush
                                        && GetContrastRatio(foregroundBrush.Color, backgroundBrush.Color) < 3.0D)
                                    {
                                        List<string> visualPath = new();
                                        for (DependencyObject parent = text; parent != null; parent = VisualTreeHelper.GetParent(parent))
                                        {
                                            if (parent is FrameworkElement element)
                                                visualPath.Add(element.GetType().Name + "/" + element.Name + "/opacity=" + element.Opacity + "/size=" + element.ActualWidth + "x" + element.ActualHeight);
                                        }
                                        File.WriteAllText(Path.ChangeExtension(outputPath, ".contrast.txt"), text.Text + "/font=" + text.FontFamily + "/foreground=" + foregroundBrush.Color + "/background=" + backgroundBrush.Color + Environment.NewLine + string.Join(Environment.NewLine, visualPath));
                                    }
                                    AssertBrushContrast(text.Foreground, background, "Guide " + theme + "/" + language + "/" + menu + "/" + text.Name + ": " + text.Text);
                                }
                                host.Workbench.Tool.ParameterGuideCommand.Execute(null);
                                Pump(3);
                                if (guideWindow.IsVisible) throw new InvalidOperationException(menu + ": guide toggle did not hide the window.");
                                checks.Add(theme + "/" + language + "/" + menu + ": expanded open, selected parameter, localized caption, contrast, close PASS (in-process focus)");
                            }
                        }
                        finally { guide.Resources.MergedDictionaries.Remove(palette); }
                    }
                }
                finally { host.Resources.MergedDictionaries.Remove(palette); }
            }
            if (host.LayerDocumentCount != layers || host.NativePreviewRunCount != 0
                || Directory.EnumerateFiles(recipeDirectory, "*", SearchOption.AllDirectories).Count() != files.Count
                || files.Any(pair => !File.Exists(pair.Key) || Convert.ToHexString(SHA256.HashData(File.ReadAllBytes(pair.Key))) != pair.Value))
                throw new InvalidOperationException("Guide open/focus/language/toggle changed XML, layers or execution.");
            File.WriteAllText(Path.ChangeExtension(outputPath, ".guide.txt"), string.Join(Environment.NewLine, checks));
        });
    }

    private static CaptureResult CaptureWorkbenchToolHeader(string outputPath, int width, int height)
    {
        OpenVisionLanguageService.SetLanguage(OpenVisionLanguage.Korean, false);
        string recipeName = "Smoke_WorkbenchToolHeader_" + Guid.NewGuid().ToString("N");
        OpenVisionShellHostView host = CreateShellHost(recipeName, seedMainLayer: false);
        VisionPipeline source = CreatePipelineReviewInputStatePipeline();
        source.Steps.RemoveAt(1);
        source.Steps[0].Name = "01 Saved threshold";
        VisionPipelineStorage.Save(recipeName, source);
        VisionPipelineStorage.SaveActivePipelineName(recipeName, source.Name);
        host.RecipeCommands.RefreshOptions();
        host.RecipeCommands.SelectedPipelineOption = host.RecipeCommands.PipelineOptions.Single(option => option.PipelineName == source.Name);
        List<string> checks = new();
        return CaptureWindowWithContent(host, outputPath, width, height, () =>
        {
            OpenVisionWorkbenchPipelineViewModel pipeline = host.Workbench.Pipeline;
            string path = RecipeWorkspaceService.GetVisionPipelinePath(recipeName, source.Name);
            foreach (string theme in new[] { "Dark", "Light" })
            {
                ResourceDictionary palette = new() { Source = new Uri($"pack://application:,,,/OpenVisionLab;component/UI/Wpf/OpenVisionWorkbench{theme}.xaml") };
                host.Resources.MergedDictionaries.Add(palette);
                try
                {
                    foreach (OpenVisionLanguage language in new[] { OpenVisionLanguage.Korean, OpenVisionLanguage.English })
                    {
                        OpenVisionLanguageService.SetLanguage(language, false);
                        VisionPipelineStorage.Save(recipeName, source);
                        host.RecipeCommands.RefreshOptions();
                        Pump(8);
                        byte[] originalXml = File.ReadAllBytes(path);
                        byte[] originalMemory = VisionPipelineExecutionPlan.SerializePipeline(pipeline.WorkingCopyForTest);
                        int runs = host.NativePreviewRunCount;
                        int layers = host.LayerDocumentCount;
                        foreach (VISION_MENU menu in new[] { VISION_MENU.EdgeBasedMatching, VISION_MENU.Arithmetic, VISION_MENU.Threshold })
                        {
                            host.SelectToolForTest(menu);
                            Pump(10);
                            try { AssertWorkbenchToolHeader(host, menu, "Testing"); }
                            catch
                            {
                                ScreenshotPngWriter.WriteElementPng(host, Path.ChangeExtension(outputPath, $".failed.{theme}.{language}.{menu}.png"), width, height);
                                throw;
                            }
                            if (theme == "Light" && language == OpenVisionLanguage.English && menu != VISION_MENU.Threshold)
                                ScreenshotPngWriter.WriteElementPng(host, Path.ChangeExtension(outputPath, $".{theme}.{language}.{menu}.png"), width, height);
                        }
                        ScreenshotPngWriter.WriteElementPng(host, Path.ChangeExtension(outputPath, $".{theme}.{language}.test.png"), width, height);
                        pipeline.SelectStepCommand.Execute(0);
                        Pump(10);
                        AssertWorkbenchToolHeader(host, VISION_MENU.Threshold, "Saved");
                        if (host.Workbench.Tool.Title != "01 · Saved threshold")
                            throw new InvalidOperationException("Outer header must reuse the canonical removal of a stored numeric name prefix.");
                        ScreenshotPngWriter.WriteElementPng(host, Path.ChangeExtension(outputPath, $".{theme}.{language}.saved.png"), width, height);
                        if (!File.ReadAllBytes(path).SequenceEqual(originalXml)
                            || !VisionPipelineExecutionPlan.SerializePipeline(pipeline.WorkingCopyForTest).SequenceEqual(originalMemory))
                            throw new InvalidOperationException("Opening header modes must not edit disk or pipeline memory.");
                        OpenVisionWorkbenchNameText title = (OpenVisionWorkbenchNameText)host.FindName("txtDockedToolTitle");
                        ContentControl titleControl = FindVisualChildren<ContentControl>(host).Single(control => ReferenceEquals(control.Content, title));
                        titleControl.RaiseEvent(new MouseButtonEventArgs(Mouse.PrimaryDevice, Environment.TickCount, MouseButton.Left)
                            { RoutedEvent = Control.MouseDoubleClickEvent });
                        if (!pipeline.IsRenaming) { throw new InvalidOperationException("Double-clicking the outer step title must use the existing inline rename command."); }
                        const string longName = "검사 영역의 긴 이름 0123456789 ABCDEFGHIJKLMNOPQRSTUVWXYZ";
                        pipeline.RenameText = longName;
                        pipeline.CommitRenameCommand.Execute(null);
                        Pump(8);
                        AssertWorkbenchToolHeader(host, VISION_MENU.Threshold, "Changed");
                        if (title.Text != "01 · " + longName || !File.ReadAllBytes(path).SequenceEqual(originalXml))
                            throw new InvalidOperationException("Changed header must show the full working-copy name without saving it.");
                        ScreenshotPngWriter.WriteElementPng(host, Path.ChangeExtension(outputPath, $".{theme}.{language}.changed.png"), width, height);
                        host.RecipeCommands.SaveRecipeCommand.Execute(null);
                        Pump(8);
                        AssertWorkbenchToolHeader(host, VISION_MENU.Threshold, "Saved");
                        FrameworkElement originalView = host.ActiveNativeDocumentForTest.View;
                        if (!host.FloatDockedWpfToolWindowForTest()) { throw new InvalidOperationException("Header test could not float its native tool."); }
                        Pump(8);
                        Window floating = Window.GetWindow(originalView);
                        if (floating?.Title != host.Workbench.Tool.Title) { throw new InvalidOperationException("Floating caption must retain the full step mode title."); }
                        pipeline.RenameCommand.Execute(null);
                        pipeline.RenameText = longName + " · B";
                        pipeline.CommitRenameCommand.Execute(null);
                        Pump(8);
                        if (floating.Title != host.Workbench.Tool.Title) { throw new InvalidOperationException("A floating step caption must follow its working-copy rename."); }
                        if (!host.DockActiveWpfToolWindowForTest()) { throw new InvalidOperationException("Header test could not redock its native tool."); }
                        Pump(8);
                        AssertWorkbenchToolHeader(host, VISION_MENU.Threshold, "Changed");
                        if (!ReferenceEquals(originalView, host.ActiveNativeDocumentForTest.View) || host.NativePreviewRunCount != runs || host.LayerDocumentCount != layers)
                            throw new InvalidOperationException("Header language/mode/float changes must preserve the native view, execution and layers.");
                        pipeline.UndoCommand.Execute(null);
                        Pump(6);
                        AssertWorkbenchToolHeader(host, VISION_MENU.Threshold, "Saved");
                        checks.Add($"{theme}/{language}/{width}x{height}: test/saved/changed/long name/rename binding/float caption/no implicit run PASS");
                    }
                }
                finally { host.Resources.MergedDictionaries.Remove(palette); }
            }
            OpenVisionLanguageService.SetLanguage(OpenVisionLanguage.Korean, false);
            File.WriteAllLines(Path.ChangeExtension(outputPath, ".checks.txt"), checks);
        });
    }

    private static void AssertWorkbenchToolHeader(OpenVisionShellHostView host, VISION_MENU menu, string badgeKind)
    {
        Border header = FindVisualChildren<Border>(host).Single(item => AutomationProperties.GetAutomationId(item) == "WorkbenchToolHeader");
        OpenVisionWorkbenchNameText title = (OpenVisionWorkbenchNameText)host.FindName("txtDockedToolTitle");
        TextBlock subtitle = FindVisualChildren<TextBlock>(header).Single(item => AutomationProperties.GetAutomationId(item) == "WorkbenchToolSubtitle");
        Border badge = FindVisualChildren<Border>(header).Single(item => AutomationProperties.GetAutomationId(item) == "WorkbenchToolBadge");
        TextBlock badgeText = FindVisualChildren<TextBlock>(badge).Single();
        MahApps.Metro.IconPacks.PackIconMaterial icon = FindVisualChildren<MahApps.Metro.IconPacks.PackIconMaterial>(header).Single(item => AutomationProperties.GetAutomationId(item) == "WorkbenchToolIcon");
        OpenVisionShellNavItem canonical = host.Workbench.Shell.NavigationGroups.SelectMany(group => group.Items).Single(item => item.Menu == menu);
        string english = OpenVisionLanguageService.GetEntries().Single(entry => entry.Key == "VisionMenu." + menu).English;
        string expectedSubtitle = OpenVisionLanguageService.CurrentLanguage == OpenVisionLanguage.English ? english : OpenVisionShellCommandCatalog.DisplayName(menu) + " · " + english;
        if (!header.IsVisible || title.Text != host.Workbench.Tool.Title || !BindingOperations.IsDataBound(title, TextBlock.TextProperty)
            || host.DockedToolTitleForTest != title.Text || subtitle.Text != expectedSubtitle
            || host.Workbench.Tool.BadgeKind != badgeKind || badgeText.Text != OpenVisionLanguageService.T("Workbench.Tool.Badge" + badgeKind)
            || icon.Kind != canonical.IconKind || title.FontSize != 15D || subtitle.FontSize != 11.5D || !title.FontFamily.Source.Contains("Pretendard", StringComparison.OrdinalIgnoreCase))
            throw new InvalidOperationException("Visible outer tool header lost its mode, translated name, badge, canonical icon, font or live binding.");
        Color panelColor = ((SolidColorBrush)header.Background).Color;
        Color badgeColor = ((SolidColorBrush)badge.Background).Color;
        double alpha = badgeColor.A / 255D;
        Color badgeBackground = Color.FromRgb((byte)Math.Round(badgeColor.R * alpha + panelColor.R * (1D - alpha)),
            (byte)Math.Round(badgeColor.G * alpha + panelColor.G * (1D - alpha)), (byte)Math.Round(badgeColor.B * alpha + panelColor.B * (1D - alpha)));
        foreach (FrameworkElement text in new FrameworkElement[] { title, subtitle, badgeText })
        {
            AssertElementWithinAncestor("Tool header " + badgeKind, text, header);
            string content = (string)text.GetValue(TextBlock.TextProperty);
            Brush foregroundBrush = TextElement.GetForeground(text);
            FormattedText required = new(content, CultureInfo.CurrentCulture, text.FlowDirection,
                new Typeface(TextElement.GetFontFamily(text), TextElement.GetFontStyle(text), TextElement.GetFontWeight(text), TextElement.GetFontStretch(text)), TextElement.GetFontSize(text),
                foregroundBrush, VisualTreeHelper.GetDpi(text).PixelsPerDip) { MaxTextWidth = Math.Max(1D, text.ActualWidth) };
            Color background = ReferenceEquals(text, badgeText) ? badgeBackground : panelColor;
            double contrast = foregroundBrush is SolidColorBrush foreground ? GetContrastRatio(foreground.Color, background) : 0D;
            if (text.ActualHeight + 2D < required.Height || (TextTrimming)text.GetValue(TextBlock.TextTrimmingProperty) != TextTrimming.None || contrast < 4.5D)
                throw new InvalidOperationException($"Tool header text was clipped or below 4.5:1 contrast: {content}; actual={text.ActualWidth:F2}x{text.ActualHeight:F2}, requiredHeight={required.Height:F2}, trimming={text.GetValue(TextBlock.TextTrimmingProperty)}, wrapping={text.GetValue(TextBlock.TextWrappingProperty)}, foreground={foregroundBrush}, background={background}, contrast={contrast:F2}");
        }
        foreach (Button button in FindVisualChildren<Button>(header).Where(button => button.IsVisible))
            AssertElementWithinAncestor("Tool header button", button, header);
    }

    private static CaptureResult CaptureWorkbenchToolPalette(string outputPath, int width, int height)
    {
        OpenVisionLanguageService.SetLanguage(OpenVisionLanguage.Korean, false);
        OpenVisionShellHostView host = CreateShellHost("Smoke_WorkbenchToolPalette", seedMainLayer: false);
        VISION_MENU[][] expectedGroups =
        {
            new[] { VISION_MENU.Threshold, VISION_MENU.Filter, VISION_MENU.Morphology, VISION_MENU.Arithmetic, VISION_MENU.EdgeDetection, VISION_MENU.HSV, VISION_MENU.Histogram },
            new[] { VISION_MENU.Matching, VISION_MENU.EdgeBasedMatching, VISION_MENU.FeatureMatching, VISION_MENU.RotateAndScale, VISION_MENU.AffineTransform },
            new[] { VISION_MENU.Blob, VISION_MENU.Contour, VISION_MENU.Line, VISION_MENU.Mean }
        };
        string[] groupKeys = { "Workbench.Tools.GroupPre", "Workbench.Tools.GroupLocate", "Workbench.Tools.GroupInspect" };
        List<string> checks = new();
        return CaptureWindowWithContent(host, outputPath, width, height, () =>
        {
            host.Workbench.ResetLayoutCommand.Execute(null);
            host.Workbench.IsToolPaletteCollapsed = false;
            Pump(8);
            double expectedLeftWidth = width <= 1360 ? 248D : 296D;
            double expectedRightWidth = width <= 1360 ? 480D : 520D;
            if (Math.Abs(host.Workbench.LeftPanelWidth.Value - expectedLeftWidth) > 1D
                || Math.Abs(host.Workbench.RightPanelWidth.Value - expectedRightWidth) > 1D)
                throw new InvalidOperationException("Palette comparison did not start from the default layout.");
            int runs = host.NativePreviewRunCount;
            int layers = host.LayerDocumentCount;
            string activeLayer = host.ActiveRecipeContextLayerNameForTest;
            ScrollViewer scroll = FindNamedVisualChild<ScrollViewer>(host, "toolRailScroll")!;
            ItemsControl palette = FindNamedVisualChild<ItemsControl>(host, "navHostToolViews")!;
            Border rail = FindNamedVisualChild<Border>(host, "toolRailBorder")!;
            FrameworkElement left = FindVisualChildren<FrameworkElement>(host).Single(item => AutomationProperties.GetAutomationId(item) == "WorkbenchLeftPanel");
            TextBlock summary = FindVisualChildren<TextBlock>(host).Single(item => AutomationProperties.GetAutomationId(item) == "HostToolSearchSummary");
            foreach (bool light in new[] { false, true })
            {
                host.Resources.MergedDictionaries.Add(new ResourceDictionary
                {
                    Source = new Uri("pack://application:,,,/OpenVisionLab;component/UI/Wpf/OpenVisionWorkbench" + (light ? "Light" : "Dark") + ".xaml")
                });
                foreach (OpenVisionLanguage language in new[] { OpenVisionLanguage.Korean, OpenVisionLanguage.English })
                {
                    OpenVisionLanguageService.SetLanguage(language, false);
                    Pump(8);
                    OpenVisionShellPreviewViewModel model = (OpenVisionShellPreviewViewModel)host.DataContext;
                    IReadOnlyList<OpenVisionShellNavGroup> groups = model.WorkbenchToolGroups;
                    if (groups.Count != 3 || model.VisibleToolCount != 16 || rail.ActualHeight > left.ActualHeight * 0.42D + 1D)
                        throw new InvalidOperationException("Workbench tool palette lost its three groups, sixteen tools, or 42% height limit.");
                    for (int index = 0; index < 3; index++)
                    {
                        if (!groups[index].Items.Select(item => item.Menu).SequenceEqual(expectedGroups[index])
                            || groups[index].Title != OpenVisionLanguageService.T(groupKeys[index]) || groups[index].VisibleItemCount != expectedGroups[index].Length)
                            throw new InvalidOperationException("Workbench tool group order/title/count changed.");
                    }
                    List<UniformGrid> tiles = FindVisualChildren<UniformGrid>(palette).Where(item => item.IsVisible).ToList();
                    if (tiles.Count != 3 || tiles.Any(item => item.Columns != 2)) throw new InvalidOperationException("Normal palette is not two columns.");
                    List<Button> buttons = FindVisualChildren<Button>(palette).Where(item => AutomationProperties.GetAutomationId(item).StartsWith("HostToolNav_", StringComparison.Ordinal)).ToList();
                    if (buttons.Count != 16 || buttons.Any(item => item.CommandParameter is OpenVisionShellNavItem tool && tool.Menu == VISION_MENU.Pipeline))
                        throw new InvalidOperationException("Workbench tool palette retained a workspace navigation entry.");
                    foreach (Button button in buttons)
                    {
                        OpenVisionShellNavItem item = (OpenVisionShellNavItem)button.CommandParameter;
                        if (!ReferenceEquals(model.NavigationGroups.SelectMany(group => group.Items).Single(tool => tool.Menu == item.Menu), item)
                            || !ReferenceEquals(button.Command, model.SelectToolCommand) || !button.IsEnabled || AutomationProperties.GetName(button) != item.Title)
                            throw new InvalidOperationException("Palette tile lost its canonical enabled command/name: " + item.Menu);
                        TextBlock title = FindVisualChildren<TextBlock>(button).Single(text => text.Name == "navItemTitle");
                        Border chrome = FindVisualChildren<Border>(button).Single(border => border.Name == "navItemChrome");
                        if (Math.Abs(title.FontSize - 12.5D) > 0.01D || !title.FontFamily.Source.Contains("Pretendard", StringComparison.OrdinalIgnoreCase)
                            || chrome.Background is not SolidColorBrush tileBrush || host.FindResource("OpenVision.Workbench.PanelAltBrush") is not SolidColorBrush expectedTileBrush
                            || tileBrush.Color != expectedTileBrush.Color)
                            throw new InvalidOperationException("Palette title font/card background does not match the proposal: " + item.Menu);
                        Rect bounds = title.TransformToAncestor(chrome).TransformBounds(new Rect(0D, 0D, title.ActualWidth, title.ActualHeight));
                        FormattedText required = new(title.Text, CultureInfo.CurrentCulture, title.FlowDirection,
                            new Typeface(title.FontFamily, title.FontStyle, title.FontWeight, title.FontStretch), title.FontSize,
                            title.Foreground, VisualTreeHelper.GetDpi(title).PixelsPerDip) { MaxTextWidth = Math.Max(1D, title.ActualWidth), LineHeight = title.LineHeight };
                        if (title.TextWrapping != TextWrapping.Wrap || title.TextTrimming != TextTrimming.None || title.ActualHeight + 2D < required.Height
                            || bounds.Left < -1D || bounds.Top < -1D || bounds.Right > chrome.ActualWidth + 1D || bounds.Bottom > chrome.ActualHeight + 1D)
                            throw new InvalidOperationException("Palette tool title was clipped: " + item.Menu);
                        if (title.Foreground is not SolidColorBrush foreground || chrome.Background is not SolidColorBrush background
                            || GetContrastRatio(foreground.Color, background.Color) < 4.5D)
                            throw new InvalidOperationException("Palette tool title contrast is below 4.5:1: " + item.Menu);
                        System.Windows.Shapes.Ellipse notice = FindVisualChildren<System.Windows.Shapes.Ellipse>(button).Single(ellipse => ellipse.Name == "navItemStatus");
                        if (notice.IsVisible != item.HasWorkbenchNotice || Convert.ToString(notice.ToolTip) != item.WorkbenchNoticeText)
                            throw new InvalidOperationException("Palette preparation dot lost its state/tooltip: " + item.Menu);
                        if (!button.Focus() || !button.IsKeyboardFocused || button.Template.FindName("focusCue", button) is not Border focus || focus.Visibility != Visibility.Visible)
                            throw new InvalidOperationException("Palette tile lost its visible keyboard focus: " + item.Menu);
                    }
                    if (model.WorkbenchToolGroups.SelectMany(group => group.Items).Count(item => item.HasWorkbenchNotice) != 6)
                        throw new InvalidOperationException("Missing-template/two-input/not-addable dots do not match the six required tools.");
                    scroll.ScrollToTop(); Pump(4);
                    ScreenshotPngWriter.WriteElementPng(host, Path.ChangeExtension(outputPath, $".{(light ? "light" : "dark")}.{language}.top.png"), width, height);
                    scroll.ScrollToBottom(); Pump(4);
                    ScreenshotPngWriter.WriteElementPng(host, Path.ChangeExtension(outputPath, $".{(light ? "light" : "dark")}.{language}.bottom.png"), width, height);
                    if (language == OpenVisionLanguage.English)
                    {
                        buttons.Single(button => ((OpenVisionShellNavItem)button.CommandParameter).Menu == VISION_MENU.EdgeBasedMatching).BringIntoView();
                        Pump(4);
                        ScreenshotPngWriter.WriteElementPng(host, Path.ChangeExtension(outputPath, $".{(light ? "light" : "dark")}.{language}.matching.png"), width, height);
                    }
                    model.ToolSearchText = "__no_such_workbench_tool__"; Pump(4);
                    if (model.VisibleToolCount != 0 || summary.Text != OpenVisionLanguageService.T("Workbench.Tools.NoMatch") || !summary.IsVisible)
                        throw new InvalidOperationException("Empty tool search did not show the localized No results state.");
                    model.ToolSearchText = "blob"; Pump(4);
                    if (model.VisibleToolCount != 1 || model.VisibleToolCommandIds != "Blob" || summary.Visibility != Visibility.Collapsed
                        || FindVisualChildren<UniformGrid>(palette).Any(item => item.IsVisible && item.Columns != 1))
                        throw new InvalidOperationException("Search did not recover into the preserved single-column assistance path.");
                    model.ToolSearchText = "스레시홀드"; Pump(4);
                    if (model.VisibleToolCount != 1 || model.VisibleToolCommandIds != "Threshold")
                        throw new InvalidOperationException("The documented legacy Threshold name was not searchable.");
                    model.ToolSearchText = "DistanceMmRange"; Pump(4);
                    ScreenshotPngWriter.WriteElementPng(host, Path.ChangeExtension(outputPath, $".{(light ? "light" : "dark")}.{language}.search.png"), width, height);
                    OpenVisionShellNavItem line = model.NavigationGroups.SelectMany(group => group.Items).Single(item => item.Menu == VISION_MENU.Line);
                    foreach ((string name, ICommand command) in new[]
                    {
                        ("navItemLearnButton", host.ChromeCommands.OpenToolLearnCommand),
                        ("navItemSamplesButton", host.ChromeCommands.OpenToolSamplesCommand),
                        ("navItemGuidedSetupButton", host.ChromeCommands.OpenToolGuidedSetupCommand)
                    })
                    {
                        Button assistance = FindVisualChildren<Button>(palette).Single(button => button.Name == name && ReferenceEquals(button.DataContext, line));
                        Rect bounds = assistance.TransformToAncestor(rail).TransformBounds(new Rect(0D, 0D, assistance.ActualWidth, assistance.ActualHeight));
                        if (!assistance.IsVisible || !assistance.IsEnabled || !ReferenceEquals(assistance.Command, command)
                            || !ReferenceEquals(assistance.CommandParameter, line) || bounds.Left < 0D || bounds.Right > rail.ActualWidth + 1D
                            || bounds.Top < 0D || bounds.Bottom > rail.ActualHeight + 1D)
                            throw new InvalidOperationException($"Tool search assistance lost its command, parameter, or reachable bounds: {name};Visible={assistance.IsVisible};Enabled={assistance.IsEnabled};Command={ReferenceEquals(assistance.Command, command)};Parameter={ReferenceEquals(assistance.CommandParameter, line)};Bounds={bounds};RailWidth={rail.ActualWidth};RailHeight={rail.ActualHeight};ScrollOffset={scroll.VerticalOffset}.");
                    }
                    model.ToolSearchText = string.Empty; Pump(4);
                    if (model.VisibleToolCount != 16 || FindVisualChildren<UniformGrid>(palette).Any(item => item.IsVisible && item.Columns != 2))
                        throw new InvalidOperationException("Clearing search did not restore the normal two-column palette.");
                    checks.Add($"PASS: {width}x{height}/{(light ? "Light" : "Dark")}/{language}; default widths {expectedLeftWidth}/{expectedRightWidth};groups7/5/4;16 canonical enabled tiles;two columns;Pretendard12.5/PanelAlt;wrapped captions/contrast;focus;6 preparation dots;no-results/recovery;legacy-name search;three assistance commands/parameters/bounds preserved (Guided Setup entry behavior tracked separately in PL-0122).");
                }
            }
            string templatePath = Path.ChangeExtension(outputPath, ".template.png");
            using Bitmap template = CreateWorkspaceSeedSmokeBitmap();
            template.Save(templatePath, ImageFormat.Png);
            MatchingProperty matching = new("Palette_Matching") { PATTERN_PATH = templatePath };
            EdgeBasedMatchingProperty edge = new("Palette_Edge") { PATTERN_PATH = templatePath };
            FeatureMatchingProperty feature = new("Palette_Feature") { PATTERN_PATH = templatePath };
            VisionToolRepository repository = new();
            repository.Matchings.Add(matching); repository.EdgeBasedMatchings.Add(edge); repository.Features.Add(feature);
            try
            {
                matching.ReloadTemplateImage(); edge.ReloadTemplateImage(); feature.ReloadTemplateImage();
                OpenVisionShellPreviewViewModel model = (OpenVisionShellPreviewViewModel)host.DataContext;
                model.SetToolReadiness(false, false, false, repository); Pump(4);
                if (model.WorkbenchToolGroups.SelectMany(group => group.Items).Count(item => item.HasWorkbenchNotice) != 3)
                    throw new InvalidOperationException("Registered templates did not remove only the three matching-family dots.");
                model.SetToolReadiness(false, false, false, null); Pump(4);
                if (model.WorkbenchToolGroups.SelectMany(group => group.Items).Count(item => item.HasWorkbenchNotice) != 6)
                    throw new InvalidOperationException("Missing template state did not recover its preparation dots.");
                checks.Add("PASS: template-ready/missing round trip updates only the three matching-family preparation dots without requiring an input image.");
            }
            finally { matching.ImageTemplate?.Dispose(); edge.ImageTemplate?.Dispose(); feature.ImageTemplate?.Dispose(); }
            if (host.NativePreviewRunCount != runs || host.LayerDocumentCount != layers || host.ActiveRecipeContextLayerNameForTest != activeLayer
                || host.IsActiveWpfToolWindowVisibleForTest || host.IsNativeDocumentActive)
                throw new InvalidOperationException("Palette display/search/focus/template readiness executed or opened a tool/changed layers.");
            OpenVisionLanguageService.SetLanguage(OpenVisionLanguage.Korean, false);
            scroll.ScrollToTop(); Pump(4);
            File.WriteAllLines(Path.ChangeExtension(outputPath, ".checks.txt"), checks);
        });
    }

    private static CaptureResult CaptureToolWindowDockFloatCycle(string outputPath, int width = 1600, int height = 900, bool captureToolPanel = false)
    {
        OpenVisionLanguageService.SetLanguage(OpenVisionLanguage.Korean, false);
        OpenVisionShellHostView shellHost = CreateShellHost("Smoke_WpfToolWindowDockFloatCycle");
        using Bitmap mainBitmap = CreateWorkspaceSeedSmokeBitmap();
        shellHost.SetMainLayerImageForTest(mainBitmap);
        return CaptureWindowWithContent(shellHost, outputPath, width, height, () =>
        {
            shellHost.SelectToolForTest(VISION_MENU.Blob);
            Pump(16);
            AssertActiveToolWindowState(shellHost, "BlobToolWpfView", true, 0, "Blob initial docked");
            if (captureToolPanel)
            {
                ScreenshotPngWriter.WriteElementPng(shellHost, Path.ChangeExtension(outputPath, ".initial.png"), width, height);
            }
            AssertDockedSingleInputToolLayout("Blob initial docked");
            System.Windows.Controls.WpfPropertyGrid.PropertyGrid blobGrid = FindVisualChildren<System.Windows.Controls.WpfPropertyGrid.PropertyGrid>(GetActiveToolVisualRoot("Blob identity setup"))
                .Single(grid => grid.IsVisible);
            object blobProperty = blobGrid.SelectedObject;
            int blobRuns = shellHost.NativePreviewRunCount;
            int blobLayers = shellHost.HostLayerRowCount;
            string blobRoute = shellHost.DirectResultRouteText;
            string blobActiveLayer = shellHost.ActiveRecipeContextLayerNameForTest;
            string blobResult = shellHost.ActiveNativeResultReviewText;

            shellHost.SetDockedToolInspectorWidthForTest(680D);
            Pump(8);
            AssertDockedToolInspectorWidth(shellHost, 680D, "Blob adjusted dock width");

            if (!shellHost.FloatDockedWpfToolWindowForTest())
            {
                throw new InvalidOperationException("Docked Blob tool did not accept the float request.");
            }

            Pump(24);
            AssertActiveToolWindowState(shellHost, "BlobToolWpfView", false, 1, "Blob after float");

            if (!shellHost.DockActiveWpfToolWindowForTest())
            {
                throw new InvalidOperationException("Floated Blob tool did not accept the second dock request.");
            }

            Pump(24);
            AssertActiveToolWindowState(shellHost, "BlobToolWpfView", true, 0, "Blob after re-dock");
            AssertDockedToolInspectorWidth(shellHost, 680D, "Blob re-dock width");
            AssertDockedSingleInputToolLayout("Blob after re-dock");
            System.Windows.Controls.WpfPropertyGrid.PropertyGrid restoredGrid = FindVisualChildren<System.Windows.Controls.WpfPropertyGrid.PropertyGrid>(GetActiveToolVisualRoot("Blob identity restore"))
                .Single(grid => grid.IsVisible);
            if (!ReferenceEquals(blobGrid, restoredGrid) || !ReferenceEquals(blobProperty, restoredGrid.SelectedObject)
                || shellHost.NativePreviewRunCount != blobRuns || shellHost.HostLayerRowCount != blobLayers
                || shellHost.DirectResultRouteText != blobRoute || shellHost.ActiveRecipeContextLayerNameForTest != blobActiveLayer
                || shellHost.ActiveNativeResultReviewText != blobResult)
                throw new InvalidOperationException("Dock/float changed the hosted PropertyGrid, parameter object, execution, route, active layer, or result.");
            OpenVisionLanguageService.SetLanguage(OpenVisionLanguage.English, false);
            Pump(16);
            if (shellHost.DockedToolTitleForTest != shellHost.Workbench.Tool.Title)
                throw new InvalidOperationException("Docked native title did not follow the current language.");
            OpenVisionLanguageService.SetLanguage(OpenVisionLanguage.Korean, false);
            Pump(16);
            if (shellHost.NativePreviewRunCount != blobRuns || !ReferenceEquals(blobProperty, restoredGrid.SelectedObject))
                throw new InvalidOperationException("Language change executed the tool or replaced its parameter object.");

            shellHost.SelectToolForTest(VISION_MENU.Matching);
            Pump(24);
            AssertActiveToolWindowState(shellHost, "MatchingToolWpfView", true, 0, "Matching after switching from docked Blob");
            AssertDockedSingleInputToolLayout("Matching after docked switch");

            shellHost.SelectToolForTest(VISION_MENU.Matching);
            Pump(16);
            AssertActiveToolWindowState(shellHost, "MatchingToolWpfView", true, 0, "Matching after repeated docked selection");
            AssertDockedToolInspectorWidth(shellHost, 680D, "Matching repeated selection width");
            AssertDockedSingleInputToolLayout("Matching after repeated docked selection");

            double savedOffset = ScrollActivePropertyGridForNavigationRestore("Matching docked navigation restore setup", 160D);
            shellHost.SelectToolForTest(VISION_MENU.Blob);
            Pump(24);
            AssertActiveToolWindowState(shellHost, "BlobToolWpfView", true, 0, "Blob after leaving scrolled Matching");
            AssertDockedSingleInputToolLayout("Blob after leaving scrolled Matching");

            shellHost.SelectToolForTest(VISION_MENU.Matching);
            Pump(36);
            AssertActiveToolWindowState(shellHost, "MatchingToolWpfView", true, 0, "Matching after navigation restore");
            AssertDockedToolInspectorWidth(shellHost, 680D, "Matching navigation restore width");
            AssertDockedSingleInputToolLayout("Matching after navigation restore");
            AssertActivePropertyGridVerticalOffsetAtLeast(
                "Matching docked navigation restore",
                Math.Min(60D, savedOffset * 0.5D));

            SetActivePropertyGridSearchText("Matching docked search restore setup", "angle");
            AssertActivePropertyGridSearchText("Matching docked search before switch", "angle");
            shellHost.SelectToolForTest(VISION_MENU.Blob);
            Pump(24);
            AssertActiveToolWindowState(shellHost, "BlobToolWpfView", true, 0, "Blob after leaving searched Matching");
            AssertDockedSingleInputToolLayout("Blob after leaving searched Matching");

            shellHost.SelectToolForTest(VISION_MENU.Matching);
            Pump(36);
            AssertActiveToolWindowState(shellHost, "MatchingToolWpfView", true, 0, "Matching after search restore");
            AssertDockedSingleInputToolLayout("Matching after search restore");
            AssertActivePropertyGridSearchText("Matching docked search restore", "angle");
            SetActivePropertyGridSearchText("Matching docked empty search setup", "__no_property_match__");
            AssertActivePropertyGridSearchEmptyMessageVisible("Matching docked empty search", true);
            SetActivePropertyGridSearchText("Matching docked empty search clear", string.Empty);
            AssertActivePropertyGridSearchEmptyMessageVisible("Matching docked empty search cleared", false);
            if (captureToolPanel) { return; }

            int layerCountBeforePipeline = shellHost.HostLayerRowCount;
            string workspaceLayerBeforePipeline = shellHost.WorkspaceLayerTitle;
            string activeLayerBeforePipeline = shellHost.ActiveRecipeContextLayerNameForTest;
            shellHost.SelectToolForTest(VISION_MENU.Pipeline);
            Pump(36);
            if (!shellHost.IsDockedDocumentWorkspaceVisibleForTest
                || shellHost.IsDockedToolInspectorVisibleForTest
                || CountVisibleFloatingToolWindows() != 0
                || !string.Equals(shellHost.ActiveWpfToolWindowTypeName, "OpenVisionPipelineReviewView", StringComparison.Ordinal))
            {
                throw new InvalidOperationException(
                    "Pipeline Review must use the central document workspace when opened from a docked native tool. "
                    + $"Central={shellHost.IsDockedDocumentWorkspaceVisibleForTest}, Inspector={shellHost.IsDockedToolInspectorVisibleForTest}, "
                    + $"Floating={CountVisibleFloatingToolWindows()}, Type={shellHost.ActiveWpfToolWindowTypeName}");
            }

            string executionStateBeforeDockCycle = shellHost.PipelineReviewExecutionState;
            if (!shellHost.FloatDockedWpfToolWindowForTest())
            {
                throw new InvalidOperationException("Central Pipeline Review did not accept the float request.");
            }

            Pump(24);
            if (shellHost.IsDockedDocumentWorkspaceVisibleForTest || CountVisibleFloatingToolWindows() != 1)
            {
                throw new InvalidOperationException("Floated Pipeline Review did not leave the central workspace cleanly.");
            }

            if (!shellHost.DockActiveWpfToolWindowForTest())
            {
                throw new InvalidOperationException("Floated Pipeline Review did not accept the central dock request.");
            }

            Pump(24);
            if (!shellHost.IsDockedDocumentWorkspaceVisibleForTest
                || shellHost.IsDockedToolInspectorVisibleForTest
                || CountVisibleFloatingToolWindows() != 0)
            {
                throw new InvalidOperationException("Pipeline Review did not return to the central document workspace.");
            }

            ClickVisibleButtonByAutomationId(
                shellHost,
                "PipelineReviewReturnToRecipeButton",
                "Central Pipeline Review return-to-recipe button");
            Pump(24);
            if (shellHost.IsDockedDocumentWorkspaceVisibleForTest || CountVisibleFloatingToolWindows() != 0)
            {
                throw new InvalidOperationException("Return to Recipe did not suspend the central Pipeline Review workspace.");
            }

            shellHost.SelectToolForTest(VISION_MENU.Pipeline);
            Pump(24);
            if (!shellHost.IsDockedDocumentWorkspaceVisibleForTest
                || shellHost.IsDockedToolInspectorVisibleForTest
                || CountVisibleFloatingToolWindows() != 0)
            {
                throw new InvalidOperationException("Reopened Pipeline Review did not restore its central docked workspace.");
            }

            if (!shellHost.FloatDockedWpfToolWindowForTest())
            {
                throw new InvalidOperationException("Reopened Pipeline Review did not accept the second float request.");
            }

            Pump(24);
            if (!shellHost.CloseActiveWpfToolWindowForTest())
            {
                throw new InvalidOperationException("Floated Pipeline Review could not be closed before its reopen check.");
            }

            shellHost.SelectToolForTest(VISION_MENU.Pipeline);
            Pump(24);
            if (!shellHost.IsDockedDocumentWorkspaceVisibleForTest
                || shellHost.IsDockedToolInspectorVisibleForTest
                || CountVisibleFloatingToolWindows() != 0)
            {
                throw new InvalidOperationException("Pipeline Review reopened outside the central workspace after its floating window was closed.");
            }

            if (!shellHost.CloseActiveWpfToolWindowForTest())
            {
                throw new InvalidOperationException("Central Pipeline Review could not be closed before its reopen check.");
            }

            shellHost.SelectToolForTest(VISION_MENU.Pipeline);
            Pump(24);
            if (!shellHost.IsDockedDocumentWorkspaceVisibleForTest
                || shellHost.IsDockedToolInspectorVisibleForTest
                || CountVisibleFloatingToolWindows() != 0)
            {
                throw new InvalidOperationException("Pipeline Review reopened outside the central workspace after its docked document was closed.");
            }

            if (shellHost.HostLayerRowCount != layerCountBeforePipeline
                || !string.Equals(shellHost.WorkspaceLayerTitle, workspaceLayerBeforePipeline, StringComparison.Ordinal)
                || !string.Equals(shellHost.ActiveRecipeContextLayerNameForTest, activeLayerBeforePipeline, StringComparison.Ordinal)
                || !string.Equals(shellHost.PipelineReviewExecutionState, executionStateBeforeDockCycle, StringComparison.Ordinal))
            {
                throw new InvalidOperationException(
                    "Pipeline Review open/float/dock changed execution or layer state without an explicit Run action.");
            }
        });
    }

    private static CaptureResult CaptureShellHostMatchingTool(string outputPath)
    {
        OpenVisionLanguageService.SetLanguage(OpenVisionLanguage.Korean, false);
        OpenVisionShellHostView shellHost = CreateShellHost("Smoke_WpfShellHostMatching");
        using Bitmap matchingBitmap = CreateMatchingSmokeBitmap();
        string templatePath = CreateMatchingTemplateFile(matchingBitmap);
        try
        {
            shellHost.SetMainLayerImageForTest(matchingBitmap);
            return CaptureWindowWithContent(shellHost, outputPath, 1600, 900, () =>
            {
                shellHost.SelectToolForTest(VISION_MENU.Matching);
                Pump(16);
                AssertToolHeaderLearnOpensTopic(shellHost, 9, "Matching header Learn");
                ComboBox inputLayerCombo = FindFloatingComboBox("cbInputLayer");
                AssertVisionToolComboTemplate(inputLayerCombo, "Matching input layer combo");
                AssertComboBoxPopupLayout(inputLayerCombo, "Matching input layer combo");
                AssertComboBoxSelectionCanChange(inputLayerCombo, "Matching input layer combo");
                ComboBox outputLayerCombo = FindFloatingComboBox("cbOutputLayer");
                AssertVisionToolComboTemplate(outputLayerCombo, "Matching output layer combo");
                AssertComboBoxPopupLayout(outputLayerCombo, "Matching output layer combo");
                SelectComboBoxItemText(FindFloatingComboBox("cbInputLayer"), "Main", "Matching owned input");
                if (shellHost.ActiveNativeRouteInputLayerNameForTest != "Main" || shellHost.ActiveNativeRouteOutputLayerNameForTest != "Matching_1")
                    throw new InvalidOperationException("Matching fixture must select its owned Main image and retain the V2 test output Matching_1.");
                AssertFloatingPropertyGridRowsRendered("Matching property grid");
                AssertFloatingPropertyGridMinimumSize("Matching property grid", 600D, 380D);
                System.Windows.Controls.WpfPropertyGrid.PropertyGridThemeVariant expectedTheme = (System.Windows.Controls.WpfPropertyGrid.PropertyGridThemeVariant)shellHost.FindResource("OpenVision.Workbench.PropertyGridTheme");
                if (GetActiveFloatingPropertyGrid("Matching property grid").ThemeVariant != expectedTheme)
                    throw new InvalidOperationException("Matching Tool View must select the instance theme resource required by D-08.");
                SetFloatingPropertyGridPropertyValue("Matching auto preview off by default", "AUTO_PREVIEW", false);
                SetFloatingPropertyGridPropertyValue("Matching reset angle search", "USE_FIND_ANGLE", true);
                SetFloatingPropertyGridPropertyValue("Matching reset canny", "USE_CANNY", false);
                Thread.Sleep(180);
                Pump(30);
                int beforeVisibilityToggleRuns = shellHost.NativePreviewRunCount;
                AssertFloatingPropertyBrowsable("Matching angle step before disable", "FIND_ANGLE", true);
                AssertFloatingPropertyBrowsable("Matching min angle before disable", "FIND_ANGLE_MIN", true);
                AssertFloatingPropertyBrowsable("Matching max angle before disable", "FIND_ANGLE_MAX", true);
                AssertFloatingRangeEditorEndpointAllowsTransientText(
                    "Matching angle min range editor transient clear",
                    "FIND_ANGLE_MIN",
                    endpointIndex: 0,
                    transientText: string.Empty,
                    restoreValue: -10D);
                double maxAngleSliderTarget = Math.Abs(GetFloatingSelectedObjectNumericProperty("FIND_ANGLE_MAX") - 90D) < 0.5D ? 120D : 90D;
                SetFloatingRangeEditorEndpointSliderValue(
                    "Matching angle max range editor",
                    "FIND_ANGLE_MIN",
                    endpointIndex: 1,
                    maxAngleSliderTarget);
                AssertFloatingSelectedObjectNumericProperty("Matching angle max range editor", "FIND_ANGLE_MAX", maxAngleSliderTarget);
                SetFloatingPropertyGridPropertyValue("Matching disable angle search", "USE_FIND_ANGLE", false);
                Thread.Sleep(180);
                Pump(30);
                AssertFloatingPropertyBrowsable("Matching angle step after disable", "FIND_ANGLE", false);
                AssertFloatingPropertyBrowsable("Matching min angle after disable", "FIND_ANGLE_MIN", false);
                AssertFloatingPropertyBrowsable("Matching max angle after disable", "FIND_ANGLE_MAX", false);
                if (shellHost.NativePreviewRunCount != beforeVisibilityToggleRuns)
                {
                    throw new InvalidOperationException("Matching USE_FIND_ANGLE should only update angle rows, not run auto-preview.");
                }

                SetFloatingPropertyGridPropertyValue("Matching enable angle search", "USE_FIND_ANGLE", true);
                Thread.Sleep(180);
                Pump(30);
                AssertFloatingPropertyBrowsable("Matching angle step after enable", "FIND_ANGLE", true);
                AssertFloatingPropertyBrowsable("Matching min angle after enable", "FIND_ANGLE_MIN", true);
                AssertFloatingPropertyBrowsable("Matching max angle after enable", "FIND_ANGLE_MAX", true);
                if (shellHost.NativePreviewRunCount != beforeVisibilityToggleRuns)
                {
                    throw new InvalidOperationException("Matching USE_FIND_ANGLE enable should not run auto-preview.");
                }

                AssertFloatingPropertyBrowsable("Matching canny low before enable", "CANNY_LOW", false);
                AssertFloatingPropertyBrowsable("Matching canny high before enable", "CANNY_HIGH", false);
                SetFloatingPropertyGridPropertyValue("Matching enable canny", "USE_CANNY", true);
                Thread.Sleep(180);
                Pump(30);
                AssertFloatingPropertyBrowsable("Matching canny low after enable", "CANNY_LOW", true);
                AssertFloatingPropertyBrowsable("Matching canny high after enable", "CANNY_HIGH", true);
                if (shellHost.NativePreviewRunCount != beforeVisibilityToggleRuns)
                {
                    throw new InvalidOperationException("Matching USE_CANNY should only update canny rows, not run auto-preview.");
                }

                SetFloatingPropertyGridPropertyValue("Matching disable canny", "USE_CANNY", false);
                Thread.Sleep(180);
                Pump(30);
                AssertFloatingPropertyBrowsable("Matching canny low after disable", "CANNY_LOW", false);
                AssertFloatingPropertyBrowsable("Matching canny high after disable", "CANNY_HIGH", false);
                if (shellHost.NativePreviewRunCount != beforeVisibilityToggleRuns)
                {
                    throw new InvalidOperationException("Matching USE_CANNY disable should not run auto-preview.");
                }

                int beforeManualParameterRuns = shellHost.NativePreviewRunCount;
                SetFloatingPropertyGridPropertyValue("Matching angle step manual mode", "FIND_ANGLE", 1D);
                Thread.Sleep(180);
                Pump(30);
                if (shellHost.NativePreviewRunCount != beforeManualParameterRuns)
                {
                    throw new InvalidOperationException("Matching angle edits must not auto-preview while AUTO_PREVIEW is false.");
                }

                int beforeTemplateRegistrationRuns = shellHost.NativePreviewRunCount;
                shellHost.SetActiveMatchingTemplatePathForTest(templatePath);
                Thread.Sleep(180);
                Pump(30);
                AssertFloatingPropertyGridDialogButtonsReady("Matching property grid dialog button");
                if (shellHost.NativePreviewRunCount != beforeTemplateRegistrationRuns)
                {
                    throw new InvalidOperationException("Matching template registration must not auto-preview while AUTO_PREVIEW is false.");
                }

                SetFloatingPropertyGridTextBoxTextWithoutCommit(
                    "Matching min score command commit",
                    "SCORE_MIN",
                    "0.57");
                int beforeExplicitPreviewRuns = shellHost.NativePreviewRunCount;
                shellHost.RunActiveNativePreviewForTest();
                Stopwatch explicitPreviewWait = Stopwatch.StartNew();
                while (shellHost.NativePreviewRunCount <= beforeExplicitPreviewRuns
                    && explicitPreviewWait.ElapsedMilliseconds < 5000)
                {
                    Pump(2);
                    Thread.Sleep(10);
                }
                AssertFloatingSelectedObjectNumericProperty("Matching min score command commit", "SCORE_MIN", 0.57D);
                if (shellHost.NativePreviewRunCount <= beforeExplicitPreviewRuns
                    || !shellHost.IsNativeDocumentActive || !shellHost.HasNativePreviewResult)
                {
                    throw new InvalidOperationException("Native WPF Matching tool did not preview after explicit run: " + shellHost.ActiveNativeStatusText);
                }

                if (!shellHost.ActiveNativeDocumentTypeName.Contains("MatchingToolWpfView", StringComparison.Ordinal))
                {
                    throw new InvalidOperationException("Matching did not open the WPF Matching tool view.");
                }

                if (!string.Equals(shellHost.ActiveNativeRouteInputLayerNameForTest, "Main", StringComparison.OrdinalIgnoreCase)
                    || !string.Equals(shellHost.ActiveNativeRouteOutputLayerNameForTest, "Matching_1", StringComparison.OrdinalIgnoreCase)
                    || !string.Equals(shellHost.ActiveHostLayerTitle, "Main", StringComparison.OrdinalIgnoreCase)
                    || !string.Equals(shellHost.WorkspaceLayerTitle, "Matching_1", StringComparison.OrdinalIgnoreCase))
                {
                    throw new InvalidOperationException(
                        "Matching template registration changed the route or active input layer. "
                        + $"Input={shellHost.ActiveNativeRouteInputLayerNameForTest}, Output={shellHost.ActiveNativeRouteOutputLayerNameForTest}, "
                        + $"Active={shellHost.ActiveHostLayerTitle}, Workspace={shellHost.WorkspaceLayerTitle}, Status={shellHost.ActiveNativeStatusText}");
                }

                AssertNoAutoDockedLayers(shellHost, "Matching explicit preview");
                AssertMatchingWorkbenchResult(shellHost, "Matching", "Template Match /", "검출", "점수", "중심", "박스", "처리");
                AssertMatchingWorkbenchResult(shellHost, "Matching result guidance", "미리보기 OK", "합격 기준:", "최고 점수", ">=", "검출", "다음:");
                AssertRetainedMatchingTeaching(shellHost, "Matching retained decision", "미리보기 OK", "합격 기준", "다음:");
                AssertRetainedMatchingTeaching(shellHost, "Matching teaching summary", "템플릿 준비", "점수 >=", "원본", "전체 이미지");
                AssertActiveFloatingInlinePreviewSlotCount("Matching explicit preview input/output", 2);
                AssertActiveFloatingInlinePreviewZoomAnchors("Matching inline preview zoom/pan");

                int beforeOptInAutoPreviewRuns = shellHost.NativePreviewRunCount;
                SetFloatingPropertyGridPropertyValue("Matching auto preview on", "AUTO_PREVIEW", true);
                Thread.Sleep(180);
                Pump(30);
                if (shellHost.NativePreviewRunCount != beforeOptInAutoPreviewRuns)
                {
                    throw new InvalidOperationException("Enabling Matching AUTO_PREVIEW must not run preview by itself.");
                }

                System.Windows.Controls.WpfPropertyGrid.PropertyGrid previewGrid = GetActiveFloatingPropertyGrid("Matching min score auto-preview");
                List<string> previewEditEvents = new();
                EventHandler<OpenVisionLab.PropertyGrid.PropertyGridPropertyValueChangedEventArgs> recordPreviewEdit =
                    (_, e) => previewEditEvents.Add(e.PropertyName ?? "<null>");
                previewGrid.PropertyValueChanged += recordPreviewEdit;
                Stopwatch autoPreviewWait = Stopwatch.StartNew();
                try
                {
                    SetFloatingPropertyGridPropertyValue("Matching min score auto-preview", "SCORE_MIN", 0.56D);
                }
                finally
                {
                    previewGrid.PropertyValueChanged -= recordPreviewEdit;
                }
                while (shellHost.NativePreviewRunCount <= beforeOptInAutoPreviewRuns
                    && autoPreviewWait.ElapsedMilliseconds < 5000)
                {
                    Pump(2);
                    Thread.Sleep(10);
                }

                File.WriteAllText(Path.ChangeExtension(outputPath, ".auto-preview.txt"),
                    $"ElapsedMs={autoPreviewWait.ElapsedMilliseconds}, Events={string.Join(',', previewEditEvents)}, "
                    + $"Auto={GetFloatingSelectedObjectPropertyValue("AUTO_PREVIEW")}, Score={GetFloatingSelectedObjectNumericProperty("SCORE_MIN")}, "
                    + $"Runs={beforeOptInAutoPreviewRuns}->{shellHost.NativePreviewRunCount}, Status={shellHost.ActiveNativeStatusText}");
                if (!previewEditEvents.Contains("SCORE_MIN")
                    || GetFloatingSelectedObjectPropertyValue("AUTO_PREVIEW") is not true
                    || Math.Abs(GetFloatingSelectedObjectNumericProperty("SCORE_MIN") - 0.56D) > 0.000001D)
                {
                    throw new InvalidOperationException("Matching auto-preview edit did not reach the selected PropertyGrid model.");
                }

                if (shellHost.NativePreviewRunCount <= beforeOptInAutoPreviewRuns)
                {
                    throw new InvalidOperationException("Matching parameter edit did not auto-preview after AUTO_PREVIEW was enabled. "
                        + $"Events={string.Join(',', previewEditEvents)}, Auto={GetFloatingSelectedObjectNumericProperty("AUTO_PREVIEW")}, "
                        + $"Score={GetFloatingSelectedObjectNumericProperty("SCORE_MIN")}, Runs={beforeOptInAutoPreviewRuns}->{shellHost.NativePreviewRunCount}, "
                        + $"ElapsedMs={autoPreviewWait.ElapsedMilliseconds}, Status={shellHost.ActiveNativeStatusText}");
                }

                AssertPreviewClickActivatesWorkspaceLayer(
                    shellHost,
                    "VisionToolOutputPreviewSlot",
                    "Matching_1",
                    "Matching output preview click");
                AssertPreviewClickActivatesWorkspaceLayer(
                    shellHost,
                    "VisionToolInputPreviewSlot",
                    "Main",
                    "Matching input preview click");

                OpenVisionNativeToolDocument beforeAddDocument = shellHost.ActiveNativeDocumentForTest!;
                int beforeAddRuns = beforeAddDocument.PreviewRunCount;
                VisionPipelineStep step = shellHost.AddActiveNativePipelineStepForTest();
                if (step == null
                    || !string.Equals(step.ToolType, "Matching", StringComparison.Ordinal)
                    || !string.Equals(step.InputLayer, "Main", StringComparison.Ordinal)
                    || !string.Equals(step.OutputLayer, "Matching_1", StringComparison.Ordinal)
                    || step.Parameters == null
                    || !step.Parameters.ContainsKey("PATTERN_PATH")
                    || !step.Parameters.ContainsKey("SCORE_MIN")
                    || !step.Parameters.ContainsKey("MATCH_MODE"))
                {
                    throw new InvalidOperationException("Matching WPF tool did not create a valid pipeline step.");
                }

                OpenVisionNativeToolDocument addedDocument = shellHost.ActiveNativeDocumentForTest!;
                File.WriteAllText(Path.ChangeExtension(outputPath, ".add-dock-checks.json"), JsonSerializer.Serialize(new
                { SameCachedDocument = ReferenceEquals(beforeAddDocument, addedDocument), BeforeAddRuns = beforeAddRuns, AfterDockRuns = addedDocument.PreviewRunCount,
                    addedDocument.HasPreviewResult, addedDocument.IsPreviewRunning, CurrentResult = shellHost.Workbench.Tool.HasResult }, new JsonSerializerOptions { WriteIndented = true }));
                if (!ReferenceEquals(beforeAddDocument, addedDocument) || addedDocument.PreviewRunCount != beforeAddRuns || addedDocument.IsPreviewRunning)
                    throw new InvalidOperationException("Matching step creation executed implicitly or replaced the cached document.");
                AssertDockActiveNativeTool(shellHost, "MatchingToolWpfView", "Docked Matching tool layout");
                if (!ReferenceEquals(addedDocument, shellHost.ActiveNativeDocumentForTest) || addedDocument.PreviewRunCount != beforeAddRuns || addedDocument.IsPreviewRunning)
                    throw new InvalidOperationException("Matching docking executed or replaced the active step editor.");
                shellHost.RunActiveNativePreviewForTest();
                Pump(24);
                if (addedDocument.PreviewRunCount != beforeAddRuns + 1 || !addedDocument.HasPreviewResult || !shellHost.Workbench.Tool.HasResult || shellHost.Workbench.Tool.IsResultPrevious)
                    throw new InvalidOperationException("Matching explicit post-add Run did not publish one current result.");
                ScreenshotPngWriter.WriteElementPng(shellHost, Path.Combine(Path.GetDirectoryName(outputPath)!, Path.GetFileNameWithoutExtension(outputPath) + ".docked.png"), 1600, 900);
                AssertFloatingPropertyGridMinimumSize("Docked Matching property grid", 480D, 160D);
                AssertMatchingWorkbenchResult(shellHost, "Docked Matching", "Template Match /", "검출", "점수", "처리");
                AssertMatchingWorkbenchResult(shellHost, "Docked Matching result guidance", "미리보기 OK", "합격 기준:", "최고 점수", ">=", "검출", "다음:");
                AssertRetainedMatchingTeaching(shellHost, "Docked Matching retained decision", "미리보기 OK", "합격 기준", "다음:");
                AssertRetainedMatchingTeaching(shellHost, "Docked Matching teaching summary", "템플릿 준비", "점수 >=", "원본", "전체 이미지");
            });
        }
        finally
        {
            TryDeleteFile(templatePath);
        }
    }

    private static CaptureResult CaptureShellHostMatchingPresets(string outputPath)
    {
        OpenVisionLanguageService.SetLanguage(OpenVisionLanguage.Korean, false);
        OpenVisionShellHostView shellHost = CreateShellHost("Smoke_WpfShellHostMatchingPresets");
        using Bitmap matchingBitmap = CreateMatchingSmokeBitmap();
        string templatePath = CreateMatchingTemplateFile(matchingBitmap);
        try
        {
            shellHost.SetMainLayerImageForTest(matchingBitmap);
            return CaptureWindowWithContent(shellHost, outputPath, 1600, 900, () =>
            {
                shellHost.SelectToolForTest(VISION_MENU.Matching);
                Pump(16);
                AssertFloatingPropertyGridRowsRendered("Matching preset property grid");
                AssertFloatingPropertyGridMinimumSize("Matching preset property grid", 600D, 380D);
                AssertActiveToolTextsVisible("Matching preset controls", "프리셋", "기본", "빠른", "정밀");

                SetFloatingPropertyGridPropertyValue("Matching preset auto preview off", "AUTO_PREVIEW", false);
                int beforeTemplateRuns = shellHost.NativePreviewRunCount;
                shellHost.SetActiveMatchingTemplatePathForTest(templatePath);
                Thread.Sleep(180);
                Pump(30);
                if (shellHost.NativePreviewRunCount != beforeTemplateRuns)
                {
                    throw new InvalidOperationException("Matching preset setup template registration must not auto-preview while AUTO_PREVIEW is false.");
                }

                SetFloatingPropertyGridPropertyValue("Matching preset auto preview on", "AUTO_PREVIEW", true);
                Thread.Sleep(180);
                Pump(30);
                int beforePresetRuns = shellHost.NativePreviewRunCount;
                ClickFloatingButtonByName("btnPresetFast", "Matching fast preset");
                Thread.Sleep(180);
                Pump(30);
                AssertFloatingSelectedObjectBooleanProperty("Matching fast preset auto preview", "AUTO_PREVIEW", false);
                AssertFloatingSelectedObjectBooleanProperty("Matching fast preset angle search", "USE_FIND_ANGLE", false);
                AssertFloatingSelectedObjectBooleanProperty("Matching fast preset scale search", "USE_FIND_SCALE", false);
                AssertFloatingSelectedObjectNumericPropertyWithin("Matching fast preset min score", "SCORE_MIN", 0.7D, 0.001D);
                AssertFloatingSelectedObjectNumericPropertyWithin("Matching fast preset count", "NUM_MATCH", 1D, 0.001D);
                AssertFloatingSelectedObjectNumericPropertyWithin("Matching fast preset magnification", "MAGNIFIATION", 0.5D, 0.001D);
                AssertFloatingPropertyBrowsable("Matching fast preset angle step hidden", "FIND_ANGLE", false);
                if (shellHost.NativePreviewRunCount != beforePresetRuns || shellHost.HasNativePreviewResult)
                {
                    throw new InvalidOperationException("Matching fast preset must update PropertyGrid only, not run preview.");
                }

                ClickFloatingButtonByName("btnPresetPrecise", "Matching precise preset");
                Thread.Sleep(180);
                Pump(30);
                AssertFloatingSelectedObjectBooleanProperty("Matching precise preset auto preview", "AUTO_PREVIEW", false);
                AssertFloatingSelectedObjectBooleanProperty("Matching precise preset angle search", "USE_FIND_ANGLE", true);
                AssertFloatingSelectedObjectBooleanProperty("Matching precise preset scale search", "USE_FIND_SCALE", false);
                AssertFloatingSelectedObjectNumericPropertyWithin("Matching precise preset min score", "SCORE_MIN", 0.6D, 0.001D);
                AssertFloatingSelectedObjectNumericPropertyWithin("Matching precise preset count", "NUM_MATCH", 3D, 0.001D);
                AssertFloatingSelectedObjectNumericPropertyWithin("Matching precise preset magnification", "MAGNIFIATION", 1.0D, 0.001D);
                AssertFloatingSelectedObjectNumericPropertyWithin("Matching precise preset angle min", "FIND_ANGLE_MIN", -10D, 0.001D);
                AssertFloatingSelectedObjectNumericPropertyWithin("Matching precise preset angle max", "FIND_ANGLE_MAX", 10D, 0.001D);
                AssertFloatingSelectedObjectNumericPropertyWithin("Matching precise preset angle step", "FIND_ANGLE", 0.5D, 0.001D);
                AssertFloatingPropertyBrowsable("Matching precise preset angle step visible", "FIND_ANGLE", true);
                if (shellHost.NativePreviewRunCount != beforePresetRuns || shellHost.HasNativePreviewResult)
                {
                    throw new InvalidOperationException("Matching precise preset must update PropertyGrid only, not run preview.");
                }

                ClickFloatingButtonByName("btnPresetBasic", "Matching basic preset");
                Thread.Sleep(180);
                Pump(30);
                AssertFloatingSelectedObjectBooleanProperty("Matching basic preset auto preview", "AUTO_PREVIEW", false);
                AssertFloatingSelectedObjectBooleanProperty("Matching basic preset angle search", "USE_FIND_ANGLE", false);
                AssertFloatingSelectedObjectBooleanProperty("Matching basic preset scale search", "USE_FIND_SCALE", false);
                AssertFloatingSelectedObjectNumericPropertyWithin("Matching basic preset min score", "SCORE_MIN", 0.6D, 0.001D);
                AssertFloatingSelectedObjectNumericPropertyWithin("Matching basic preset count", "NUM_MATCH", 1D, 0.001D);
                AssertFloatingSelectedObjectNumericPropertyWithin("Matching basic preset magnification", "MAGNIFIATION", 1.0D, 0.001D);
                AssertFloatingPropertyBrowsable("Matching basic preset angle step hidden", "FIND_ANGLE", false);
                AssertActiveToolPresetControls("Matching preset applied controls");
                if (shellHost.NativePreviewRunCount != beforePresetRuns || shellHost.HasNativePreviewResult)
                {
                    throw new InvalidOperationException("Matching basic preset must update PropertyGrid only, not run preview.");
                }

                AssertDockActiveNativeTool(shellHost, "MatchingToolWpfView", "Docked Matching preset menu");
                AssertActiveToolPresetControls("Docked Matching presets");
                AssertFloatingPropertyGridMinimumSize("Docked Matching preset property grid", 600D, 380D);

                int beforeDockedPresetRuns = shellHost.NativePreviewRunCount;
                ClickActiveToolPresetMenuItem("fast", "Docked Matching fast preset");
                Thread.Sleep(180);
                Pump(30);
                AssertFloatingSelectedObjectBooleanProperty("Docked Matching fast preset auto preview", "AUTO_PREVIEW", false);
                AssertFloatingSelectedObjectBooleanProperty("Docked Matching fast preset angle search", "USE_FIND_ANGLE", false);
                AssertFloatingSelectedObjectNumericPropertyWithin("Docked Matching fast preset min score", "SCORE_MIN", 0.7D, 0.001D);
                AssertFloatingSelectedObjectNumericPropertyWithin("Docked Matching fast preset magnification", "MAGNIFIATION", 0.5D, 0.001D);
                AssertFloatingPropertyBrowsable("Docked Matching fast preset angle step hidden", "FIND_ANGLE", false);
                AssertFloatingPropertyGridMinimumSize("Docked Matching preset property grid after menu", 600D, 380D);
                if (shellHost.NativePreviewRunCount != beforeDockedPresetRuns || shellHost.HasNativePreviewResult)
                {
                    throw new InvalidOperationException("Docked Matching fast preset menu must update PropertyGrid only, not run preview.");
                }
            });
        }
        finally
        {
            TryDeleteFile(templatePath);
        }
