    private static CaptureResult CaptureEdgeBasedPropertyGridBottomLayout(string outputPath)
    {
        OpenVisionLanguageService.SetLanguage(OpenVisionLanguage.Korean, false);
        OpenVisionShellHostView shellHost = CreateShellHost(
            "Smoke_EdgeBasedPropertyGridBottom_" + Guid.NewGuid().ToString("N").Substring(0, 12));
        return CaptureWindowWithContent(shellHost, outputPath, 1180, 720, () =>
        {
            shellHost.SelectToolForTest(VISION_MENU.EdgeBasedMatching);
            Pump(16);
            AssertDockActiveNativeTool(
                shellHost,
                "EdgeBasedMatchingToolWpfView",
                "EdgeBasedMatching PropertyGrid bottom layout");
            shellHost.SetDockedToolInspectorWidthForTest(620D);
            Pump(12);

            DependencyObject root = GetActiveToolVisualRoot(
                "EdgeBasedMatching PropertyGrid bottom layout");
            VisionToolSingleInputPropertyToolShell shell =
                FindVisualChildren<VisionToolSingleInputPropertyToolShell>(root)
                    .FirstOrDefault(item => item.IsVisible)
                ?? throw new InvalidOperationException(
                    "EdgeBasedMatching PropertyGrid bottom layout did not contain the shared inspector shell.");
            System.Windows.Controls.WpfPropertyGrid.PropertyGrid propertyGrid =
                FindVisualChildren<System.Windows.Controls.WpfPropertyGrid.PropertyGrid>(shell.PropertyGridHost)
                    .FirstOrDefault(item => item.IsVisible)
                ?? throw new InvalidOperationException(
                    "EdgeBasedMatching PropertyGrid bottom layout did not contain the generated PropertyGrid.");

            TextBox searchTextBox = GetActivePropertyGridSearchTextBox(
                propertyGrid,
                "EdgeBasedMatching bottom-layout search");
            searchTextBox.Text = "Canny";
            searchTextBox.CaretIndex = searchTextBox.Text.Length;
            Pump(8);
            if (!string.Equals(searchTextBox.Text, "Canny", StringComparison.Ordinal)
                || !searchTextBox.IsVisible
                || searchTextBox.ActualWidth < 120D)
            {
                throw new InvalidOperationException(
                    "EdgeBasedMatching PropertyGrid search text was not visibly retained in the docked inspector.");
            }

            string evidenceDirectory = Path.GetDirectoryName(outputPath) ?? Directory.GetCurrentDirectory();
            ScreenshotPngWriter.WriteElementPng(
                root as FrameworkElement
                    ?? throw new InvalidOperationException("EdgeBasedMatching docked root is not renderable."),
                Path.Combine(evidenceDirectory, "edge_property_grid_search_text.png"),
                620,
                650);

            searchTextBox.Clear();
            Pump(8);
            ScrollViewer scrollViewer = FindPrimaryPropertyGridScrollViewer(propertyGrid)
                ?? throw new InvalidOperationException(
                    "EdgeBasedMatching PropertyGrid did not expose its parameter ScrollViewer.");
            scrollViewer.ScrollToEnd();
            propertyGrid.UpdateLayout();
            Pump(8);
            AssertPropertyGridBottomRowFullyVisible(
                "EdgeBasedMatching docked PropertyGrid",
                shell,
                propertyGrid,
                scrollViewer);
        });
    }

    private static CaptureResult CaptureToolNImageVerificationWindow(string outputPath)
    {
        OpenVisionLanguageService.SetLanguage(OpenVisionLanguage.Korean, false);
        string recipeName = "Smoke_NImageWindow_" + Guid.NewGuid().ToString("N").Substring(0, 12);
        string inputDirectory = Path.Combine(
            Path.GetDirectoryName(outputPath) ?? Path.GetTempPath(),
            "n_image_window_inputs");
        Directory.CreateDirectory(inputDirectory);
        List<string> imagePaths = new List<string>();
        for (int index = 0; index < 8; index++)
        {
            string path = Path.Combine(inputDirectory, $"threshold_{index + 1:00}.png");
            using Bitmap bitmap = new Bitmap(320, 220, System.Drawing.Imaging.PixelFormat.Format24bppRgb);
            using Graphics graphics = Graphics.FromImage(bitmap);
            graphics.Clear(DrawingColor.FromArgb(28 + (index * 2), 34 + (index * 2), 42 + (index * 2)));
            using System.Drawing.SolidBrush objectBrush =
                new System.Drawing.SolidBrush(DrawingColor.FromArgb(205, 220, 235));
            graphics.FillRectangle(objectBrush, 46 + (index * 3), 52, 112, 82);
            graphics.FillEllipse(objectBrush, 205, 74 + (index % 3), 44, 44);
            bitmap.Save(path, ImageFormat.Png);
            imagePaths.Add(path);
        }

        AssertNImageToolFailureClassification(imagePaths[0], recipeName + "_Error");

        VisionToolNImageVerificationController controller =
            new VisionToolNImageVerificationController(
                "Threshold",
                recipeName,
                () =>
                {
                    VisionPipelineStep step = VisionPipelineStepBuilder.FromThresholdProperty(
                        new ThresholdToolProperty(),
                        "Threshold",
                        "Main",
                        "NImageResult");
                    step.UseAcceptance = true;
                    step.ExpectedSuccess = true;
                    step.AcceptanceMetricName = VisionPipelineKnownMetrics.ResultImageWidth;
                    step.UseAcceptanceMetricMinimum = true;
                    step.AcceptanceMetricMinimum = 400D;
                    return step;
                },
                normalizeInputToGray: true);
        try
        {
            controller.AddImagePaths(imagePaths);
            if (controller.Rows.Count != imagePaths.Count
                || controller.Rows.Any(row => row.IsCompleted)
                || controller.SelectedRow == null
                || controller.SelectedSourceImage == null)
            {
                throw new InvalidOperationException(
                    "N-image verification did not expose the selected file list before Run. "
                    + $"Rows={controller.Rows.Count}, Completed={controller.Rows.Count(row => row.IsCompleted)}, "
                    + $"Selected={controller.SelectedRow?.FileName ?? "<none>"}, Source={controller.SelectedSourceImage != null}.");
            }

            Task.Run(controller.RunAsync).GetAwaiter().GetResult();
            VisionToolNImageVerificationWindow window =
                new VisionToolNImageVerificationWindow(controller);
            return CaptureStandaloneWindow(window, outputPath, 1380, 840, () =>
            {
                if (controller.Rows.Count != imagePaths.Count)
                {
                    throw new InvalidOperationException(
                        $"N-image verification window retained {controller.Rows.Count} rows; expected {imagePaths.Count}.");
                }

                if (!controller.CanExport
                    || controller.SelectedRow == null
                    || !controller.SelectedRow.IsNg
                    || string.IsNullOrWhiteSpace(controller.SelectedRow.ReviewDetailText)
                    || controller.SelectedSourceImage == null
                    || controller.SelectedDrawingImage == null)
                {
                    throw new InvalidOperationException(
                        "N-image verification window did not retain a selected NG reason with source/drawing/report evidence.");
                }

                Button addFilesButton = FindVisualChildren<Button>(window)
                    .FirstOrDefault(button => string.Equals(
                        AutomationProperties.GetName(button),
                        controller.AddFilesText,
                        StringComparison.Ordinal))
                    ?? throw new InvalidOperationException("Localized N-image Add files button was not rendered.");
                if (!string.Equals(addFilesButton.ToolTip?.ToString(), controller.AddFilesToolTipText, StringComparison.Ordinal)
                    || !FindVisualChildren<TextBlock>(window).Any(text => string.Equals(text.Text, controller.ImageListTitleText, StringComparison.Ordinal))
                    || !FindVisualChildren<TextBlock>(window).Any(text => string.Equals(text.Text, controller.ReviewReasonHeaderText, StringComparison.Ordinal)))
                {
                    throw new InvalidOperationException("Korean N-image labels, tooltip, or result-reason header did not render.");
                }

                Border sourceSurface = window.FindName("sourceImageSurface") as Border
                    ?? throw new InvalidOperationException("N-image source image navigation surface was not rendered.");
                Border drawingSurface = window.FindName("drawingImageSurface") as Border
                    ?? throw new InvalidOperationException("N-image drawing image navigation surface was not rendered.");
                System.Windows.Controls.Image sourcePreview = window.FindName("sourceImagePreview") as System.Windows.Controls.Image
                    ?? throw new InvalidOperationException("N-image source image preview was not rendered.");
                System.Windows.Controls.Image drawingPreview = window.FindName("drawingImagePreview") as System.Windows.Controls.Image
                    ?? throw new InvalidOperationException("N-image drawing image preview was not rendered.");
                if (!string.Equals(
                        AutomationProperties.GetHelpText(sourceSurface),
                        controller.ImageNavigationHintText,
                        StringComparison.Ordinal)
                    || !string.Equals(
                        AutomationProperties.GetHelpText(drawingSurface),
                        controller.ImageNavigationHintText,
                        StringComparison.Ordinal)
                    || FindVisualChildren<TextBlock>(window).Count(text => string.Equals(
                        text.Text,
                        controller.ImageNavigationHintText,
                        StringComparison.Ordinal)) < 2)
                {
                    throw new InvalidOperationException("N-image image navigation guidance was not visible and accessible.");
                }

                DataGrid resultGrid = window.FindName("resultGrid") as DataGrid
                    ?? throw new InvalidOperationException("N-image result grid was not rendered.");
                window.Width = window.MinWidth;
                window.Height = window.MinHeight;
                Pump(12);
                List<StackPanel> navigationHeaders = FindVisualChildren<StackPanel>(window)
                    .Where(panel => panel.Children.OfType<TextBlock>().Any(text => string.Equals(
                        text.Text,
                        controller.ImageNavigationHintText,
                        StringComparison.Ordinal)))
                    .ToList();
                if (sourceSurface.ActualWidth < 320D
                    || sourceSurface.ActualHeight < 100D
                    || drawingSurface.ActualWidth < 320D
                    || drawingSurface.ActualHeight < 100D
                    || resultGrid.ActualWidth < 420D
                    || navigationHeaders.Count != 2
                    || navigationHeaders.Any(header => header.ActualWidth > sourceSurface.ActualWidth + 1D))
                {
                    throw new InvalidOperationException(
                        "N-image navigation previews or guidance did not remain usable at the minimum window size. "
                        + $"Source={sourceSurface.ActualWidth:0.0}x{sourceSurface.ActualHeight:0.0}; "
                        + $"Drawing={drawingSurface.ActualWidth:0.0}x{drawingSurface.ActualHeight:0.0}; "
                        + $"Grid={resultGrid.ActualWidth:0.0}; Headers={navigationHeaders.Count}.");
                }

                string compactOutputPath = Path.Combine(
                    Path.GetDirectoryName(outputPath) ?? ".",
                    Path.GetFileNameWithoutExtension(outputPath) + "_compact.png");
                ScreenshotPngWriter.WriteElementPng(
                    window,
                    compactOutputPath,
                    Math.Max(1, (int)Math.Round(window.ActualWidth)),
                    Math.Max(1, (int)Math.Round(window.ActualHeight)));
                window.Width = 1380D;
                window.Height = 840D;
                Pump(12);

                (double initialSourceZoom, double initialSourcePanX, double initialSourcePanY) =
                    GetImageNavigationState(sourcePreview);
                (double initialDrawingZoom, double initialDrawingPanX, double initialDrawingPanY) =
                    GetImageNavigationState(drawingPreview);
                if (Math.Abs(initialSourceZoom - 1D) > 0.001D
                    || Math.Abs(initialSourcePanX) > 0.001D
                    || Math.Abs(initialSourcePanY) > 0.001D
                    || Math.Abs(initialDrawingZoom - 1D) > 0.001D
                    || Math.Abs(initialDrawingPanX) > 0.001D
                    || Math.Abs(initialDrawingPanY) > 0.001D)
                {
                    throw new InvalidOperationException("N-image previews did not start fitted at their neutral transforms.");
                }

                window.ZoomSourceImageForTest(1.5D);
                (double sourceZoomBeforePan, double sourcePanXBeforePan, double sourcePanYBeforePan) =
                    GetImageNavigationState(sourcePreview);
                window.PanSourceImageForTest(36D, 18D);
                window.ZoomDrawingImageForTest(1.25D);
                Pump(8);
                (double sourceZoom, double sourcePanX, double sourcePanY) = GetImageNavigationState(sourcePreview);
                var (drawingZoom, _, _) = GetImageNavigationState(drawingPreview);
                if (sourceZoom < 1.49D
                    || drawingZoom < 1.24D
                    || Math.Abs(sourcePanX - sourcePanXBeforePan) < 0.01D
                    || Math.Abs(sourcePanY - sourcePanYBeforePan) < 0.01D
                    || Math.Abs(sourceZoom - sourceZoomBeforePan) > 0.001D)
                {
                    throw new InvalidOperationException(
                        "N-image previews did not support independent zoom and pan. "
                        + $"Source={sourceZoom:0.###}/{sourcePanX:0.###},{sourcePanY:0.###}; Drawing={drawingZoom:0.###}.");
                }

                window.ResetSourceImageForTest();
                (double resetSourceZoom, double resetSourcePanX, double resetSourcePanY) =
                    GetImageNavigationState(sourcePreview);
                var (retainedDrawingZoom, _, _) = GetImageNavigationState(drawingPreview);
                if (Math.Abs(resetSourceZoom - 1D) > 0.001D
                    || Math.Abs(resetSourcePanX) > 0.001D
                    || Math.Abs(resetSourcePanY) > 0.001D
                    || retainedDrawingZoom < 1.24D)
                {
                    throw new InvalidOperationException("Resetting the source preview also changed the independent drawing preview.");
                }

                controller.SelectedRow = controller.Rows[1];
                Pump(8);
                (double selectedSourceZoom, double selectedSourcePanX, double selectedSourcePanY) =
                    GetImageNavigationState(sourcePreview);
                (double selectedDrawingZoom, double selectedDrawingPanX, double selectedDrawingPanY) =
                    GetImageNavigationState(drawingPreview);
                if (Math.Abs(selectedSourceZoom - 1D) > 0.001D
                    || Math.Abs(selectedSourcePanX) > 0.001D
                    || Math.Abs(selectedSourcePanY) > 0.001D
                    || Math.Abs(selectedDrawingZoom - 1D) > 0.001D
                    || Math.Abs(selectedDrawingPanX) > 0.001D
                    || Math.Abs(selectedDrawingPanY) > 0.001D
                    || controller.SelectedSourceImage == null
                    || controller.SelectedDrawingImage == null)
                {
                    throw new InvalidOperationException("Changing the selected N-image row did not restore both previews to fit.");
                }

                OpenVisionLanguageService.SetLanguage(OpenVisionLanguage.English, false);
                Pump(8);
                if (!string.Equals(AutomationProperties.GetName(addFilesButton), "Add files", StringComparison.Ordinal)
                    || !string.Equals(addFilesButton.ToolTip?.ToString(), "Select image files to verify.", StringComparison.Ordinal)
                    || !controller.WindowTitle.Contains("N-image verification", StringComparison.Ordinal)
                    || !AutomationProperties.GetHelpText(sourceSurface).Contains("Wheel zoom", StringComparison.Ordinal))
                {
                    throw new InvalidOperationException("N-image labels and tooltip did not switch to English.");
                }

                OpenVisionLanguageService.SetLanguage(OpenVisionLanguage.Korean, false);
                Pump(8);
                controller.SelectedRow = controller.Rows[0];
                Pump(8);
                window.ZoomSourceImageForTest(1.5D);
                window.PanSourceImageForTest(24D, 10D);
                window.ZoomDrawingImageForTest(1.25D);
            });
        }
        finally
        {
            controller.Dispose();
            RecipeWorkspaceService.DeleteVisionWorkspace(recipeName);
        }
    }

    private static void AssertNImageToolFailureClassification(string imagePath, string recipeName)
    {
        string missingTemplatePath = Path.Combine(
            Path.GetDirectoryName(imagePath) ?? string.Empty,
            "missing-template-" + Guid.NewGuid().ToString("N") + ".png");
        VisionToolNImageVerificationController controller =
            new VisionToolNImageVerificationController(
                "Matching",
                recipeName,
                () => VisionPipelineStepBuilder.FromProperty(
                    new MatchingProperty("Matching")
                    {
                        PATTERN_PATH = missingTemplatePath,
                        USE_ROI = false,
                        SCORE_MIN = 0.5D,
                        NUM_MATCH = 1,
                        USE_FIND_ANGLE = false,
                        USE_FIND_SCALE = false,
                        USE_CANNY = false
                    },
                    "Main",
                    "NImageResult"),
                normalizeInputToGray: false);
        try
        {
            controller.AddImagePaths(new[] { imagePath });
            Task.Run(controller.RunAsync).GetAwaiter().GetResult();
            VisionToolNImageVerificationRow row = controller.Rows.Single();
            if (!row.IsError
                || row.IsUngated
                || row.Success
                || !controller.ResultCountText.Contains("오류 1", StringComparison.Ordinal)
                || !row.ReviewDetailText.Contains("template", StringComparison.OrdinalIgnoreCase))
            {
                throw new InvalidOperationException(
                    "N-image verification classified a Tool execution error as an ungated successful run. "
                    + $"Status={row.Status}, Success={row.Success}, Counts='{controller.ResultCountText}', Detail='{row.ReviewDetailText}'");
            }
        }
        finally
        {
            controller.Dispose();
            RecipeWorkspaceService.DeleteVisionWorkspace(recipeName);
        }
    }

    private static (double Zoom, double PanX, double PanY) GetImageNavigationState(
        System.Windows.Controls.Image image)
    {
        if (image?.RenderTransform is not TransformGroup transformGroup
            || transformGroup.Children.OfType<ScaleTransform>().FirstOrDefault() is not ScaleTransform scale
            || transformGroup.Children.OfType<TranslateTransform>().FirstOrDefault() is not TranslateTransform pan)
        {
            throw new InvalidOperationException("Zoomable image did not expose the expected scale and pan transforms.");
        }

        return (scale.ScaleX, pan.X, pan.Y);
    }

    private static CaptureResult CaptureToolNImageLocatorPromotionWindow(string outputPath)
    {
        OpenVisionLanguageService.SetLanguage(OpenVisionLanguage.Korean, false);
        string recipeName = "Smoke_NImageLocatorPromotion_" + Guid.NewGuid().ToString("N");
        string inputDirectory = Path.Combine(
            Path.GetDirectoryName(outputPath) ?? Path.GetTempPath(),
            "locator_promotion_inputs");
        Directory.CreateDirectory(inputDirectory);
        using Bitmap source = CreateMatchingSmokeBitmap();
        string templatePath = CreateMatchingTemplateFile(source);
        List<string> imagePaths = new List<string>();
        for (int index = 0; index < 6; index++)
        {
            string path = Path.Combine(inputDirectory, $"locator_{index + 1:00}.jpg");
            source.Save(path, ImageFormat.Jpeg);
            imagePaths.Add(path);
        }

        VisionToolNImageVerificationController controller =
            new VisionToolNImageVerificationController(
                "Matching",
                recipeName,
                () =>
                {
                    MatchingProperty property = new MatchingProperty("Matching")
                    {
                        PATTERN_PATH = templatePath,
                        SCORE_MIN = 0.5D,
                        NUM_MATCH = 1,
                        USE_FIND_ANGLE = false,
                        USE_FIND_SCALE = false,
                        USE_CANNY = false
                    };
                    return VisionPipelineStepBuilder.FromProperty(
                        property,
                        "Main",
                        "NImageResult");
                },
                normalizeInputToGray: false);
        try
        {
            controller.AddImagePaths(imagePaths);
            Task.Run(controller.RunAsync).GetAwaiter().GetResult();
            if (!controller.CanPromoteLocatorValidation
                || !controller.PromoteLocatorValidation()
                || controller.LastPromotionResult?.ImageCount != imagePaths.Count)
            {
                throw new InvalidOperationException(
                    "N-image locator promotion action was not available after a complete locator run. "
                    + controller.StatusText);
            }

            VisionToolNImageVerificationWindow window =
                new VisionToolNImageVerificationWindow(controller);
            return CaptureStandaloneWindow(window, outputPath, 1380, 840, () =>
            {
                Button promoteButton = FindVisualChildren<Button>(window)
                    .FirstOrDefault(item => string.Equals(
                        AutomationProperties.GetAutomationId(item),
                        "VisionToolNImagePromoteLocatorValidationButton",
                        StringComparison.Ordinal))
                    ?? throw new InvalidOperationException(
                        "N-image locator promotion button was not visible.");
                if (!promoteButton.IsVisible
                    || !promoteButton.IsEnabled
                    || !controller.StatusText.Contains("승격 완료", StringComparison.Ordinal)
                    || controller.Rows.Count != imagePaths.Count
                    || controller.Rows.Any(row => !row.Success))
                {
                    throw new InvalidOperationException(
                        "N-image locator promotion window did not retain its actionable completed state.");
                }
            });
        }
        finally
        {
            controller.Dispose();
            RecipeWorkspaceService.DeleteVisionWorkspace(recipeName);
            TryDeleteFile(templatePath);
        }
    }

    private static CaptureResult CaptureP235LocatorValidationPromotion(string outputPath)
    {
        OpenVisionLanguageService.SetLanguage(OpenVisionLanguage.Korean, false);
        string retainedRoot = Path.Combine(
            Directory.GetCurrentDirectory(),
            "artifacts",
            "p234_tool_n_image_real_folder_acceptance_20260724");
        string summaryPath = Path.Combine(retainedRoot, "summary.xml");
        string pipelinePath = Path.Combine(retainedRoot, "pipeline.xml");
        VisionPipelineBatchRunSummary summary = VisionPipelineBatchRunSummaryStorage.Load(summaryPath)
            ?? throw new InvalidOperationException("P234 retained summary could not be loaded.");
        string pipelineXml = File.ReadAllText(pipelinePath);
        const string expectedDefinitionSha256 =
            "7CEAEC5D50259ED1337AB912F0F0A63C673F4A74E692DCDEA01BAA14FC25658F";
        string definitionSha256 = OpenVisionRecipeValidationSetStorage.ComputeTextSha256(pipelineXml);
        if (summary.Results.Count != 24
            || summary.Results.Any(item => item?.Success != true)
            || !string.Equals(definitionSha256, expectedDefinitionSha256, StringComparison.Ordinal))
        {
            throw new InvalidOperationException(
                "P234 retained identity changed before promotion. "
                + $"Rows={summary.Results.Count}, StepSHA={definitionSha256}.");
        }

        List<VisionToolNImageVerificationRow> rows = new List<VisionToolNImageVerificationRow>();
        for (int index = 0; index < summary.Results.Count; index++)
        {
            VisionPipelineBatchSampleRunResult retained = summary.Results[index]
                ?? throw new InvalidOperationException("P234 retained row is null.");
            VisionPipelineRunReport report = VisionPipelineRunReportStorage.Load(retained.RunReportPath)
                ?? throw new InvalidOperationException("P234 retained report could not be loaded: " + retained.RunReportPath);
            string reportDirectory = Path.GetDirectoryName(retained.RunReportPath) ?? string.Empty;
            string sourcePath = Path.IsPathRooted(report.SourceImageFile)
                ? report.SourceImageFile
                : Path.Combine(reportDirectory, report.SourceImageFile ?? string.Empty);
            if (!File.Exists(retained.SampleImagePath)
                || !VisionPipelineRunReportStorage.IsFileSha256Match(
                    sourcePath,
                    report.SourceImageSha256))
            {
                throw new InvalidOperationException(
                    "P234 retained source identity mismatch: " + retained.SampleImagePath);
            }

            rows.Add(new VisionToolNImageVerificationRow
            {
                Index = index + 1,
                ImagePath = retained.SampleImagePath,
                Status = retained.Status,
                Success = retained.Success,
                TotalMilliseconds = retained.TotalMilliseconds,
                Message = retained.Message,
                MetricText = retained.MetricText,
                RunReportPath = retained.RunReportPath,
                SourceSnapshotPath = sourcePath,
                SourceSha256 = report.SourceImageSha256,
                FailedStep = retained.FailedStep
            });
        }

        VisionToolNImageVerificationSession session = new VisionToolNImageVerificationSession
        {
            ToolName = "EdgeBasedMatching",
            PipelineName = summary.PipelineName,
            PipelineXml = pipelineXml,
            StepDefinitionSha256 = definitionSha256,
            BatchSummaryPath = summaryPath,
            WasCancelled = false,
            StartedAt = DateTime.Parse(summary.StartedAt, CultureInfo.InvariantCulture),
            FinishedAt = DateTime.Parse(summary.FinishedAt, CultureInfo.InvariantCulture),
            Rows = rows
        };

        string recipeName = "Smoke_P235LocatorPromotion_" + Guid.NewGuid().ToString("N");
        const string sentinelPipelineName = "Sentinel_Active_Pipeline";
        VisionPipelineStorage.Save(
            recipeName,
            RecipeContextFixture.CreatePipeline(sentinelPipelineName, 1));
        VisionPipelineStorage.SaveActivePipelineName(recipeName, sentinelPipelineName);
        try
        {
            if (!VisionToolNImageValidationPromotionService.TryPromoteLocatorExpectedSuccess(
                    recipeName,
                    session,
                    out VisionToolNImageValidationPromotionResult promoted,
                    out string promotionError))
            {
                throw new InvalidOperationException("P235 promotion failed: " + promotionError);
            }

            if (!VisionToolNImageValidationPromotionService.TryPromoteLocatorExpectedSuccess(
                    recipeName,
                    session,
                    out VisionToolNImageValidationPromotionResult reused,
                    out string reuseError)
                || !reused.ReusedExistingIdentity
                || !string.Equals(reused.ValidationSetName, promoted.ValidationSetName, StringComparison.Ordinal))
            {
                throw new InvalidOperationException("P235 idempotent promotion failed: " + reuseError);
            }

            if (!string.Equals(
                    VisionPipelineStorage.LoadActivePipelineName(recipeName, sentinelPipelineName),
                    sentinelPipelineName,
                    StringComparison.Ordinal)
                || Directory.EnumerateFiles(
                        RecipeWorkspaceService.GetRecipeWorkspaceDirectory(recipeName),
                        "summary.xml",
                        SearchOption.AllDirectories)
                    .Any())
            {
                throw new InvalidOperationException(
                    "P235 promotion changed the active Pipeline or executed a validation run.");
            }

            if (!OpenVisionRecipeValidationSetStorage.TryLoad(
                    recipeName,
                    out OpenVisionRecipeValidationSetDocument document,
                    out string loadError))
            {
                throw new InvalidOperationException("P235 validation set reload failed: " + loadError);
            }

            OpenVisionRecipeValidationSet set = document.Sets.Single(item =>
                string.Equals(item.Name, promoted.ValidationSetName, StringComparison.Ordinal));
            string savedPipelineXml = File.ReadAllText(promoted.PipelinePath);
            bool frozenIdentityValid =
                OpenVisionRecipeValidationSetStorage.TryValidateFrozenIdentity(
                    set,
                    summary.PipelineName,
                    savedPipelineXml,
                    out string identityError);
            if (!set.IsIdentityLocked
                || set.Images.Count != 24
                || set.Images.Any(item =>
                    !string.Equals(
                        item.Expected,
                        OpenVisionRecipeValidationSetImage.ExpectedOk,
                        StringComparison.Ordinal))
                || !string.Equals(
                    set.PipelineDefinitionSha256,
                    expectedDefinitionSha256,
                    StringComparison.Ordinal)
                || !frozenIdentityValid)
            {
                throw new InvalidOperationException(
                    "P235 reloaded identity did not preserve the exact P234 Step/images: " + identityError);
            }

            string retainedImageSha = set.Images[0].Sha256;
            set.Images[0].Sha256 = new string('0', 64);
            if (OpenVisionRecipeValidationSetStorage.TryValidateFrozenIdentity(
                    set,
                    summary.PipelineName,
                    savedPipelineXml,
                    out _))
            {
                throw new InvalidOperationException("P235 image hash tamper was not rejected.");
            }

            set.Images[0].Sha256 = retainedImageSha;
            if (!OpenVisionRecipeValidationSetStorage.TryValidateFrozenIdentity(
                    set,
                    summary.PipelineName,
                    savedPipelineXml,
                    out string restoredIdentityError))
            {
                throw new InvalidOperationException(
                    "P235 restored image hash did not revalidate: " + restoredIdentityError);
            }

            OpenVisionShellHostView shellHost = CreateShellHost(recipeName, seedMainLayer: false);
            CaptureResult capture = CaptureWindowWithContent(shellHost, outputPath, 1600, 900, () =>
            {
                OpenVisionRecipeValidationSetOption lockedOption =
                    shellHost.RecipeCommands.ValidationSetOptions.Single(option =>
                        string.Equals(
                            option.Name,
                            promoted.ValidationSetName,
                            StringComparison.Ordinal));
                shellHost.RecipeCommands.SelectedValidationSetOption = lockedOption;
                shellHost.RecipeCommands.SelectedValidationSuiteScopeOption =
                    shellHost.RecipeCommands.ValidationSuiteScopeOptions.Single(option =>
                        string.Equals(
                            option.Key,
                            OpenVisionRecipeValidationSuiteScopeOption.LocalValidationSetKey,
                            StringComparison.OrdinalIgnoreCase));

                OpenVisionRecipePipelineOption sentinelOption =
                    shellHost.RecipeCommands.PipelineOptions.Single(option =>
                        string.Equals(
                            option.PipelineName,
                            sentinelPipelineName,
                            StringComparison.Ordinal));
                shellHost.RecipeCommands.SelectedPipelineOption = sentinelOption;
                if (shellHost.RecipeCommands.RunValidationSuiteCommand.CanExecute(null))
                {
                    throw new InvalidOperationException(
                        "P235 locked set allowed execution with the wrong Pipeline.");
                }

                OpenVisionRecipePipelineOption locatorOption =
                    shellHost.RecipeCommands.PipelineOptions.Single(option =>
                        string.Equals(
                            option.PipelineName,
                            summary.PipelineName,
                            StringComparison.Ordinal));
                shellHost.RecipeCommands.SelectedPipelineOption = locatorOption;
                if (!shellHost.RecipeCommands.RunValidationSuiteCommand.CanExecute(null)
                    || shellHost.RecipeCommands.AddValidationSetOkImagesCommand.CanExecute(null)
                    || shellHost.RecipeCommands.AddValidationSetNgImagesCommand.CanExecute(null)
                    || shellHost.RecipeCommands.RemoveValidationSetImageCommand.CanExecute(null)
                    || shellHost.RecipeCommands.RepairValidationSetImagePathCommand.CanExecute(null)
                    || lockedOption.ImageCount != 24
                    || lockedOption.OkCount != 24
                    || lockedOption.NgCount != 0
                    || !lockedOption.DisplayText.Contains("해시 잠금", StringComparison.Ordinal))
                {
                    throw new InvalidOperationException(
                        "P235 Recipe Manager locked-set state was incomplete: "
                        + shellHost.RecipeCommands.ValidationSetSelectionSummaryText);
                }

                int previewRunsBefore = shellHost.NativePreviewRunCount;
                int layerCountBefore = shellHost.LayerDocumentCount;
                ToggleButton recipeManagerButton =
                    FindNamedVisualChild<ToggleButton>(shellHost, "btnHostRecipeManager")
                    ?? throw new InvalidOperationException("P235 Recipe Manager button was not found.");
                recipeManagerButton.IsChecked = true;
                Pump(80);
                FindNamedVisualChild<ToggleButton>(shellHost, "recipeAdvancedReviewToggle")!.IsChecked = true;
                Pump(40);
                FindNamedVisualChild<TabItem>(shellHost, "tabRecipePipeline")!.IsSelected = true;
                Pump(30);
                FindNamedVisualChild<TabItem>(shellHost, "tabRecipePipelineRunHistory")!.IsSelected = true;
                Pump(60);
                FrameworkElement evidence =
                    FindVisualChildren<FrameworkElement>(shellHost).FirstOrDefault(item =>
                        string.Equals(
                            AutomationProperties.GetAutomationId(item),
                            "HostRecipeValidationSetEvidenceBoard",
                            StringComparison.Ordinal))
                    ?? throw new InvalidOperationException("P235 Validation Set evidence board was not found.");
                evidence.BringIntoView();
                evidence.UpdateLayout();
                Pump(60);
                if (shellHost.NativePreviewRunCount != previewRunsBefore
                    || shellHost.LayerDocumentCount != layerCountBefore
                    || !shellHost.RecipeCommands.ValidationSetExpectedText.Contains(
                        "위치검출 기대 성공",
                        StringComparison.Ordinal)
                    || !shellHost.RecipeCommands.ValidationSetNextActionText.Contains(
                        summary.PipelineName,
                        StringComparison.Ordinal))
                {
                    throw new InvalidOperationException(
                        "P235 Recipe Manager presentation changed state or lost locator semantics.");
                }
            }, captureFloatingToolWindow: false, captureScreen: true);

            string evidenceDirectory =
                Path.GetDirectoryName(outputPath) ?? Directory.GetCurrentDirectory();
            Directory.CreateDirectory(evidenceDirectory);
            File.Copy(
                promoted.PipelinePath,
                Path.Combine(evidenceDirectory, "promoted-pipeline.xml"),
                overwrite: true);
            File.Copy(
                promoted.ValidationSetPath,
                Path.Combine(evidenceDirectory, "promoted-validation-sets.xml"),
                overwrite: true);
            File.WriteAllLines(
                Path.Combine(evidenceDirectory, "completion_record.txt"),
                new[]
                {
                    "Status: Complete",
                    "Scope: Exact retained P234 EdgeBasedMatching one-Step/24-image promotion into a hash-locked Recipe Manager locator expected-success Validation Set.",
                    "Acceptance criteria: exact Step SHA -> PASS "
                        + promoted.PipelineDefinitionSha256
                        + "; images -> 24/24 Expected OK; idempotent repeat -> PASS; wrong Pipeline blocked -> PASS; image-hash tamper rejected -> PASS; active Pipeline unchanged -> PASS; automatic Preview/Run -> 0.",
                    "Verification: current-build p235_locator_validation_promotion screenshot smoke; legacy Validation Set, N-image window, and entry side-effect regressions.",
                    "Evidence: promoted-pipeline.xml; promoted-validation-sets.xml; p235_locator_validation_promotion.png; image-set SHA-256 "
                        + promoted.ImageSetSha256
                        + "; dependency count "
                        + promoted.DependencyCount.ToString(CultureInfo.InvariantCulture)
                        + ".",
                    "Boundary / next dependency: Every row means locator expected success, not defect OK/NG classification. This promotion does not rerun or semantically requalify P234, add parallel execution, or prove field robustness."
                },
                new System.Text.UTF8Encoding(false));
            return capture;
        }
        finally
        {
            RecipeWorkspaceService.DeleteVisionWorkspace(recipeName);
        }
    }

    private static CaptureResult CaptureToolNImageEntrySideEffectContract(string outputPath)
    {
        OpenVisionLanguageService.SetLanguage(OpenVisionLanguage.Korean, false);
        OpenVisionShellHostView shellHost = CreateShellHost("Smoke_ToolNImageEntrySideEffects");
        return CaptureWindowWithContent(shellHost, outputPath, 1600, 900, () =>
        {
            shellHost.SelectToolForTest(VISION_MENU.Threshold);
            Pump(16);
            int previewRuns = shellHost.NativePreviewRunCount;
            int layerCount = shellHost.LayerDocumentCount;
            string inputRoute = shellHost.ActiveNativeRouteInputLayerNameForTest;
            string outputRoute = shellHost.ActiveNativeRouteOutputLayerNameForTest;
            string activeLayer = shellHost.ActiveHostLayerTitle;
            Button button = FindActiveToolVisualRoots()
                .SelectMany(FindVisualChildren<Button>)
                .FirstOrDefault(item => string.Equals(
                    AutomationProperties.GetAutomationId(item),
                    "VisionToolNImageVerificationButton",
                    StringComparison.Ordinal))
                ?? throw new InvalidOperationException("N-image verification entry button was not visible.");
            if (!button.IsVisible || !button.IsEnabled)
            {
                throw new InvalidOperationException("N-image verification entry button was not actionable.");
            }

            Exception? nestedFailure = null;
            Application.Current.Dispatcher.BeginInvoke(new Action(() =>
            {
                try
                {
                    VisionToolNImageVerificationWindow verificationWindow =
                        Application.Current.Windows
                            .OfType<VisionToolNImageVerificationWindow>()
                            .FirstOrDefault(item => item.IsVisible)
                        ?? throw new InvalidOperationException(
                            "N-image verification window did not open from the Tool View entry.");
                    if (verificationWindow.DataContext is not VisionToolNImageVerificationController)
                    {
                        throw new InvalidOperationException(
                            "N-image verification window did not receive the shared controller.");
                    }

                    AssertNImageEntryTheme(verificationWindow, outputPath);
                    verificationWindow.Close();
                }
                catch (Exception ex)
                {
                    nestedFailure = ex;
                    Application.Current.Windows
                        .OfType<VisionToolNImageVerificationWindow>()
                        .FirstOrDefault(item => item.IsVisible)
                        ?.Close();
                }
            }));
            button.RaiseEvent(new RoutedEventArgs(Button.ClickEvent, button));
            Pump(8);
            if (nestedFailure != null)
            {
                throw nestedFailure;
            }

            if (shellHost.NativePreviewRunCount != previewRuns
                || shellHost.LayerDocumentCount != layerCount
                || !string.Equals(
                    shellHost.ActiveNativeRouteInputLayerNameForTest,
                    inputRoute,
                    StringComparison.Ordinal)
                || !string.Equals(
                    shellHost.ActiveNativeRouteOutputLayerNameForTest,
                    outputRoute,
                    StringComparison.Ordinal)
                || !string.Equals(shellHost.ActiveHostLayerTitle, activeLayer, StringComparison.Ordinal))
            {
                throw new InvalidOperationException(
                    "Opening and closing N-image verification changed Preview/Run, layers, or routing. "
                    + $"Runs={previewRuns}->{shellHost.NativePreviewRunCount}, "
                    + $"Layers={layerCount}->{shellHost.LayerDocumentCount}, "
                    + $"Input={inputRoute}->{shellHost.ActiveNativeRouteInputLayerNameForTest}, "
                    + $"Output={outputRoute}->{shellHost.ActiveNativeRouteOutputLayerNameForTest}, "
                    + $"Active={activeLayer}->{shellHost.ActiveHostLayerTitle}.");
            }
        });
    }

    private static void AssertNImageEntryTheme(VisionToolNImageVerificationWindow window, string outputPath)
    {
        VisionToolNImageVerificationController controller = (VisionToolNImageVerificationController)window.DataContext;
        DataGrid grid = (DataGrid)window.FindName("resultGrid");
        string directory = Path.GetDirectoryName(outputPath) ?? Path.GetTempPath();
        string[] inputs = new[] { Path.Combine(directory, "n-entry-input-a.png"), Path.Combine(directory, "n-entry-input-b.png") };
        using (Bitmap bitmap = new Bitmap(160, 100, System.Drawing.Imaging.PixelFormat.Format24bppRgb))
        using (Graphics graphics = Graphics.FromImage(bitmap))
        {
            graphics.Clear(DrawingColor.FromArgb(24, 30, 40));
            graphics.FillRectangle(System.Drawing.Brushes.White, 30, 25, 80, 45);
            foreach (string input in inputs) bitmap.Save(input, ImageFormat.Png);
        }

        List<object> measurements = new();
        List<string> failures = new();
        ResourceDictionary? themeDictionary = null;
        foreach (string theme in new[] { "Dark", "Light" })
        {
            if (themeDictionary != null) window.Resources.MergedDictionaries.Remove(themeDictionary);
            themeDictionary = new ResourceDictionary
            {
                Source = new Uri("pack://application:,,,/OpenVisionLab;component/UI/Wpf/OpenVisionWorkbench" + theme + ".xaml")
            };
            window.Resources.MergedDictionaries.Add(themeDictionary);
            foreach (OpenVisionLanguage language in new[] { OpenVisionLanguage.Korean, OpenVisionLanguage.English })
            {
                OpenVisionLanguageService.SetLanguage(language, false);
                foreach ((int width, int height) in new[] { (1380, 840), (1280, 760) })
                {
                    window.Width = width;
                    window.Height = height;
                    controller.ClearImagesCommand.Execute(window);
                    Pump(12);
                    Record("empty");
                    controller.AddImagePaths(inputs);
                    Pump(12);
                    Record("pending");
                    grid.SelectedItem = controller.Rows[1];
                    Pump(8);
                    if (!ReferenceEquals(controller.SelectedRow, controller.Rows[1])) failures.Add("View-to-controller selection binding failed.");
                    controller.SelectedRow = controller.Rows[0];
                    Pump(8);
                    if (!ReferenceEquals(grid.SelectedItem, controller.Rows[0])) failures.Add("Controller-to-view selection binding failed.");
                    Record("selected");
                    if (controller.IsRunning || controller.Rows.Any(row => row.IsCompleted)) failures.Add("Adding or selecting inputs executed verification.");

                    void Record(string state)
                    {
                        string prefix = theme + "-" + language + "-" + width + "x" + height + "-" + state;
                        window.UpdateLayout();
                        ScreenshotPngWriter.WriteVisibleElementPng(window, Path.ChangeExtension(outputPath, "." + prefix + ".png"));
                        SolidColorBrush expectedSurface = (SolidColorBrush)window.FindResource("OpenVision.Workbench.PanelBrush");
                        SolidColorBrush expectedHeader = (SolidColorBrush)window.FindResource("OpenVision.Workbench.RaisedBrush");
                        SolidColorBrush expectedText = (SolidColorBrush)window.FindResource("OpenVision.Workbench.TextBrush");
                        SolidColorBrush expectedSelection = (SolidColorBrush)window.FindResource("OpenVision.Workbench.AccentSoftBrush");
                        string Color(Brush? brush) => brush is SolidColorBrush value ? value.Color.ToString() : "<missing>";
                        if (Color(grid.Background) != Color(expectedSurface) || Color(window.Background) != Color(expectedSurface)) failures.Add(prefix + ": result grid/window surface mismatch.");
                        List<DataGridColumnHeader> headers = FindVisualChildren<DataGridColumnHeader>(grid)
                            .Where(header => header.IsVisible && header.Column != null).ToList();
                        if (headers.Count != 6) failures.Add(prefix + ": six result headers were not visible.");
                        List<object> headerEvidence = new();
                        foreach (DataGridColumnHeader header in headers)
                        {
                            TextBlock? text = FindVisualChildren<TextBlock>(header).FirstOrDefault(item => !string.IsNullOrWhiteSpace(item.Text));
                            Brush foreground = text?.Foreground ?? header.Foreground;
                            double contrast = foreground is SolidColorBrush fg && header.Background is SolidColorBrush bg ? GetContrastRatio(fg.Color, bg.Color) : 0;
                            if (Color(header.Background) != Color(expectedHeader) || Color(foreground) != Color(expectedText) || contrast < 4.5D)
                                failures.Add(prefix + ": header " + text?.Text + " palette/contrast mismatch.");
                            headerEvidence.Add(new { Text = text?.Text, Foreground = Color(foreground), Background = Color(header.Background), Contrast = contrast, Width = text?.ActualWidth, Height = text?.ActualHeight });
                        }

                        List<object> rowEvidence = new();
                        foreach (DataGridRow row in FindVisualChildren<DataGridRow>(grid).Where(row => row.IsVisible))
                        {
                            Brush expectedRow = row.IsSelected ? expectedSelection : expectedSurface;
                            if (Color(row.Background) != Color(expectedRow)) failures.Add(prefix + ": row surface mismatch.");
                            List<object> cells = new();
                            foreach (DataGridCell cell in FindVisualChildren<DataGridCell>(row).Where(cell => cell.IsVisible))
                            {
                                foreach (TextBlock text in FindVisualChildren<TextBlock>(cell).Where(text => !string.IsNullOrWhiteSpace(text.Text)))
                                {
                                    System.Windows.Media.Color renderedBackground = expectedSurface.Color;
                                    foreach (SolidColorBrush layer in new[] { row.Background, cell.Background }.OfType<SolidColorBrush>())
                                    {
                                        double alpha = layer.Color.A / 255D;
                                        renderedBackground = System.Windows.Media.Color.FromRgb((byte)Math.Round(layer.Color.R * alpha + renderedBackground.R * (1D - alpha)),
                                            (byte)Math.Round(layer.Color.G * alpha + renderedBackground.G * (1D - alpha)), (byte)Math.Round(layer.Color.B * alpha + renderedBackground.B * (1D - alpha)));
                                    }
                                    double contrast = text.Foreground is SolidColorBrush fg ? GetContrastRatio(fg.Color, renderedBackground) : 0;
                                    if (Color(text.Foreground) != Color(cell.Foreground) || contrast < 4.5D) failures.Add(prefix + ": cell foreground/contrast mismatch " + text.Text);
                                    cells.Add(new { text.Text, Foreground = Color(text.Foreground), CellForeground = Color(cell.Foreground), RenderedBackground = renderedBackground.ToString(), Contrast = contrast });
                                }
                            }
                            rowEvidence.Add(new { row.IsSelected, Background = Color(row.Background), Cells = cells });
                        }
                        measurements.Add(new { Theme = theme, Language = language.ToString(), Width = width, Height = height, State = state, GridBackground = Color(grid.Background), Headers = headerEvidence, Rows = rowEvidence, controller.IsRunning, Completed = controller.Rows.Count(row => row.IsCompleted) });
                    }
                }
            }
        }
        File.WriteAllText(Path.ChangeExtension(outputPath, ".theme.json"), JsonSerializer.Serialize(new { Measurements = measurements, Failures = failures }, new JsonSerializerOptions { WriteIndented = true }));
        if (failures.Count > 0) throw new InvalidOperationException("N-image entry theme failed: " + string.Join("; ", failures.Distinct()));
    }

    private static CaptureResult CaptureShellHostEdgeBasedMatchingToolCore(string outputPath, bool dockAfterVerification)
    {
        OpenVisionLanguageService.SetLanguage(OpenVisionLanguage.Korean, false);
        string recipeName = "Smoke_EdgeBasedMatching_" + Guid.NewGuid().ToString("N").Substring(0, 12);
        OpenVisionShellHostView shellHost = CreateShellHost(recipeName);
        using Bitmap matchingBitmap = CreateMatchingSmokeBitmap();
        string templatePath = CreateMatchingTemplateFile(matchingBitmap);
        List<string> autoMPointRepresentativePaths =
            CreateAutoMPointRepresentativeFiles(matchingBitmap, 3);
        List<string> autoMPointBulkReportPaths = new List<string>();
        string autoMPointTemplatePath = string.Empty;
        try
        {
            shellHost.SetMainLayerImageForTest(matchingBitmap);
            return CaptureWindowWithContent(shellHost, outputPath, 1600, 900, () =>
            {
                shellHost.SelectToolForTest(VISION_MENU.EdgeBasedMatching);
                Pump(16);
                if (!shellHost.FloatDockedWpfToolWindowForTest())
                    throw new InvalidOperationException("EdgeBasedMatching legacy floating verification could not float the default docked tool.");
                Pump(16);
                ComboBox inputLayerCombo = FindFloatingComboBox("cbInputLayer");
                AssertVisionToolComboTemplate(inputLayerCombo, "EdgeBasedMatching input layer combo");
                AssertComboBoxPopupLayout(inputLayerCombo, "EdgeBasedMatching input layer combo");
                AssertComboBoxSelectionCanChange(inputLayerCombo, "EdgeBasedMatching input layer combo");
                ComboBox outputLayerCombo = FindFloatingComboBox("cbOutputLayer");
                AssertVisionToolComboTemplate(outputLayerCombo, "EdgeBasedMatching output layer combo");
                AssertComboBoxPopupLayout(outputLayerCombo, "EdgeBasedMatching output layer combo");
                SelectComboBoxItemText(FindFloatingComboBox("cbInputLayer"), "Main", "EdgeBasedMatching owned input");
                if (shellHost.ActiveNativeRouteInputLayerNameForTest != "Main" || shellHost.ActiveNativeRouteOutputLayerNameForTest != "EdgeBasedMatching_1")
                    throw new InvalidOperationException("EdgeBasedMatching fixture must select its owned Main image and retain the V2 test output EdgeBasedMatching_1.");
                int beforeAutoPreviewRuns = shellHost.NativePreviewRunCount;
                shellHost.SetActiveEdgeBasedMatchingTemplatePathForTest(templatePath);
                Stopwatch autoPreviewWait = Stopwatch.StartNew();
                while (shellHost.NativePreviewRunCount <= beforeAutoPreviewRuns
                    && autoPreviewWait.ElapsedMilliseconds < 5000)
                {
                    Pump(2);
                    Thread.Sleep(10);
                }

                AssertFloatingPropertyGridDialogButtonsReady("EdgeBasedMatching property grid dialog button");
                AssertToolHeaderLearnOpensTopic(shellHost, 12, "EdgeBasedMatching header Learn");
                if (!shellHost.IsNativeDocumentActive || !shellHost.HasNativePreviewResult)
                {
                    throw new InvalidOperationException("Native WPF EdgeBasedMatching tool did not auto-preview after template registration: " + shellHost.ActiveNativeStatusText);
                }

                if (shellHost.NativePreviewRunCount <= beforeAutoPreviewRuns)
                {
                    throw new InvalidOperationException("Native WPF EdgeBasedMatching template registration did not request an auto-preview.");
                }

                if (!shellHost.ActiveNativeDocumentTypeName.Contains("EdgeBasedMatchingToolWpfView", StringComparison.Ordinal))
                {
                    throw new InvalidOperationException("EdgeBasedMatching did not open the WPF EdgeBasedMatching tool view.");
                }

                if (!string.Equals(shellHost.ActiveNativeRouteInputLayerNameForTest, "Main", StringComparison.OrdinalIgnoreCase)
                    || !string.Equals(shellHost.ActiveNativeRouteOutputLayerNameForTest, "EdgeBasedMatching_1", StringComparison.OrdinalIgnoreCase)
                    || !string.Equals(shellHost.ActiveHostLayerTitle, "Main", StringComparison.OrdinalIgnoreCase))
                {
                    throw new InvalidOperationException(
                        "EdgeBasedMatching template registration changed the route or active input layer. "
                        + $"Input={shellHost.ActiveNativeRouteInputLayerNameForTest}, Output={shellHost.ActiveNativeRouteOutputLayerNameForTest}, Active={shellHost.ActiveHostLayerTitle}, Status={shellHost.ActiveNativeStatusText}");
                }

                AssertNoAutoDockedLayers(shellHost, "EdgeBasedMatching template auto-preview");
                AssertMatchingWorkbenchResult(shellHost, "EdgeBasedMatching", "Edge Match /", "검출", "점수");
                AssertRetainedMatchingTeaching(shellHost, "EdgeBasedMatching verification guide", "엣지", "Canny", "포인트", "미리보기 OK");
                AssertFloatingPropertyBrowsable(
                    "EdgeBasedMatching advanced switch visible",
                    "ShowAdvancedSettings",
                    true);
                AssertFloatingPropertyBrowsable(
                    "EdgeBasedMatching unique validation compact default",
                    "USE_UNIQUE_MATCH_VALIDATION",
                    false);
                AssertFloatingPropertyBrowsable(
                    "EdgeBasedMatching Auto MPoint ROI compact default",
                    "AUTO_MPOINT_USE_ANALYSIS_ROI",
                    false);
                AssertFloatingPropertyBrowsable(
                    "EdgeBasedMatching Canny range companion hidden",
                    "CANNY_HIGH",
                    false);
                AssertFloatingPropertyBrowsable(
                    "EdgeBasedMatching scale minimum compact default",
                    "FIND_SCALE_MIN",
                    false);

                int autoMPointPreviewRuns = shellHost.NativePreviewRunCount;
                int autoMPointLayerCount = shellHost.LayerDocumentCount;
                string autoMPointInputRoute = shellHost.ActiveNativeRouteInputLayerNameForTest;
                string autoMPointOutputRoute = shellHost.ActiveNativeRouteOutputLayerNameForTest;
                string autoMPointActiveLayer = shellHost.ActiveHostLayerTitle;
                shellHost.ConfigureActiveEdgeBasedMatchingForTest(property =>
                {
                    property.ShowAdvancedSettings = true;
                    property.USE_FIND_SCALE = true;
                    property.SCORE_MIN = 0.45D;
                    property.NUM_MATCH = 1;
                    property.USE_UNIQUE_MATCH_VALIDATION = true;
                    property.UNIQUE_MATCH_MIN_SCORE_MARGIN = 0.07D;
                    property.ALLOW_GLOBAL_POLARITY_REVERSAL = true;
                    property.SEARCH_STEP = 2;
                    property.USE_POSITION_REFINE = true;
                    property.USE_SUBPIXEL_REFINE = true;
                    property.AUTO_MPOINT_USE_ANALYSIS_ROI = true;
                    property.AUTO_MPOINT_PATTERN_WIDTH = 96;
                    property.AUTO_MPOINT_PATTERN_HEIGHT = 96;
                    property.AUTO_MPOINT_STRIDE = 32;
                    property.AUTO_MPOINT_MAX_RESULTS = 3;
                    property.AUTO_MPOINT_MIN_FEATURE_QUALITY = 0.02D;
                    property.AUTO_MPOINT_MIN_UNIQUENESS = 0D;
                    property.AUTO_MPOINT_MAX_POSITION_ERROR = 10D;
                    property.AUTO_MPOINT_MIN_REPRESENTATIVE_IMAGES = 3;
                    property.AUTO_MPOINT_MIN_REPRESENTATIVE_SUCCESS_RATE = 1D;
                });
                Pump(8);
                if (shellHost.NativePreviewRunCount != autoMPointPreviewRuns)
                {
                    throw new InvalidOperationException("Auto MPoint PropertyGrid teaching settings triggered Preview.");
                }

                AssertFloatingPropertyBrowsable(
                    "EdgeBasedMatching unique validation advanced",
                    "USE_UNIQUE_MATCH_VALIDATION",
                    true);
                AssertFloatingPropertyBrowsable(
                    "EdgeBasedMatching unique margin advanced",
                    "UNIQUE_MATCH_MIN_SCORE_MARGIN",
                    true);
                AssertFloatingPropertyBrowsable(
                    "EdgeBasedMatching scale minimum advanced",
                    "FIND_SCALE_MIN",
                    true);
                AssertFloatingPropertyBrowsable(
                    "EdgeBasedMatching Auto MPoint ROI advanced",
                    "AUTO_MPOINT_USE_ANALYSIS_ROI",
                    true);

                AssertFloatingSelectedObjectBooleanProperty(
                    "EdgeBasedMatching unique-match option",
                    "USE_UNIQUE_MATCH_VALIDATION",
                    true);
                AssertFloatingSelectedObjectNumericPropertyWithin(
                    "EdgeBasedMatching unique-match margin",
                    "UNIQUE_MATCH_MIN_SCORE_MARGIN",
                    0.07D,
                    0.000001D);
                AssertFloatingSelectedObjectBooleanProperty(
                    "EdgeBasedMatching global-polarity option",
                    "ALLOW_GLOBAL_POLARITY_REVERSAL",
                    true);
                AssertFloatingSelectedObjectBooleanProperty(
                    "EdgeBasedMatching grayscale edge default",
                    "USE_THRESHOLD",
                    false);

                AutoMPointTeachingPanel teachingPanel = FindActiveToolVisualRoots()
                    .SelectMany(FindVisualChildren<AutoMPointTeachingPanel>)
                    .FirstOrDefault()
                    ?? throw new InvalidOperationException("Auto MPoint teaching panel was not visible.");
                EdgeBasedMatchingToolWpfView matchingView = FindActiveToolVisualRoots()
                    .OfType<EdgeBasedMatchingToolWpfView>()
                    .Concat(FindActiveToolVisualRoots()
                        .SelectMany(FindVisualChildren<EdgeBasedMatchingToolWpfView>))
                    .FirstOrDefault()
                    ?? throw new InvalidOperationException("Auto MPoint Edge Based Matching view was not visible.");
                VisionToolSingleInputPropertyToolShell teachingShell = matchingView.FindName("toolShell") as VisionToolSingleInputPropertyToolShell
                    ?? throw new InvalidOperationException("EdgeBasedMatching teaching shell was not available.");
                if (teachingShell.ToolContent is not Grid teachingContent || !teachingPanel.IsVisible
                    || teachingContent.Children.OfType<VisionToolVerificationGuideView>().Any(guide => guide.Visibility != Visibility.Collapsed))
                    throw new InvalidOperationException("V2 must show the existing teaching panel and hide the legacy verification guide.");
                ScrollViewer teachingBody = (ScrollViewer)teachingShell.FindName("parameterBodyScrollViewer");
                int beforeLayoutScrollRuns = shellHost.NativePreviewRunCount;
                int beforeLayoutScrollLayers = shellHost.LayerDocumentCount;
                string beforeLayoutScrollStep = JsonSerializer.Serialize(shellHost.Workbench.Tool.CurrentStep);
                teachingBody.ScrollToHome();
                Pump(12);
                Rect panelBounds = GetElementBounds(teachingShell, teachingPanel);
                Rect templateBounds = GetElementBounds(teachingShell, teachingShell.WorkbenchTemplateHost);
                Rect parameterBounds = GetElementBounds(teachingShell, teachingShell.PropertyGridHost);
                Rect viewportBounds = GetElementBounds(teachingShell, teachingBody);
                Rect visibleParameters = Rect.Intersect(parameterBounds, viewportBounds);
                Rect headerBounds = GetElementBounds(teachingShell, (FrameworkElement)teachingShell.FindName("txtParameterHeader"));
                File.WriteAllText(Path.ChangeExtension(outputPath, ".teaching-layout.json"), JsonSerializer.Serialize(new
                {
                    TemplateBottom = templateBounds.Bottom, PanelTop = panelBounds.Top, PanelHeight = panelBounds.Height, ParameterTop = parameterBounds.Top,
                    Viewport = viewportBounds.ToString(CultureInfo.InvariantCulture), VisibleParameters = visibleParameters.ToString(CultureInfo.InvariantCulture), Header = headerBounds.ToString(CultureInfo.InvariantCulture),
                    teachingBody.VerticalOffset, teachingBody.ScrollableHeight, PanelVisible = teachingPanel.IsVisible, ParameterVisible = teachingShell.PropertyGridHost.IsVisible,
                    ShellWidth = teachingShell.ActualWidth, ShellHeight = teachingShell.ActualHeight
                }, new JsonSerializerOptions { WriteIndented = true }));
                ScreenshotPngWriter.WriteVisibleElementPng(matchingView, Path.ChangeExtension(outputPath, ".teaching-layout.png"));
                if (panelBounds.Top < templateBounds.Bottom - 0.5D || viewportBounds.Top < panelBounds.Bottom - 0.5D || visibleParameters.IsEmpty
                    || visibleParameters.Top < panelBounds.Bottom - 0.5D || headerBounds.Top < viewportBounds.Top - 0.5D || headerBounds.Bottom > viewportBounds.Bottom + 0.5D)
                    throw new InvalidOperationException("EdgeBasedMatching teaching panel must not overlap visible parameter content, and the header must be reachable at scroll top.");
                if (shellHost.NativePreviewRunCount != beforeLayoutScrollRuns || shellHost.LayerDocumentCount != beforeLayoutScrollLayers
                    || JsonSerializer.Serialize(shellHost.Workbench.Tool.CurrentStep) != beforeLayoutScrollStep)
                    throw new InvalidOperationException("EdgeBasedMatching layout scroll changed execution, layers or the working step.");

                shellHost.ConfigureActiveEdgeBasedMatchingForTest(property =>
                {
                    property.ShowAdvancedSettings = false;
                    property.USE_FIND_SCALE = false;
                    property.AUTO_MPOINT_USE_ANALYSIS_ROI = false;
                });
                Pump(8);
                if (shellHost.NativePreviewRunCount != autoMPointPreviewRuns)
                {
                    throw new InvalidOperationException(
                        "EdgeBasedMatching advanced visibility settings triggered Preview.");
                }

                AssertFloatingPropertyBrowsable(
                    "EdgeBasedMatching unique validation compact restore",
                    "USE_UNIQUE_MATCH_VALIDATION",
                    false);
                AssertFloatingPropertyBrowsable(
                    "EdgeBasedMatching scale minimum compact restore",
                    "FIND_SCALE_MIN",
                    false);
                teachingPanel.DetailsExpander.IsExpanded = true;
                Pump(4);
                matchingView.SetAutoMPointRepresentativeImagesForTest(autoMPointRepresentativePaths);
                Pump(4);
                if (teachingPanel.RepresentativeCountText.Text.IndexOf(
                        "3",
                        StringComparison.Ordinal) < 0)
                {
                    throw new InvalidOperationException(
                        "Auto MPoint representative-image selection count was not displayed.");
                }

                Button analyzeButton = FindActiveToolVisualRoots()
                    .SelectMany(FindVisualChildren<Button>)
                    .FirstOrDefault(item => string.Equals(
                        AutomationProperties.GetAutomationId(item),
                        "AutoMPointAnalyzeCandidates",
                        StringComparison.Ordinal))
                    ?? throw new InvalidOperationException("Auto MPoint analyze button was not visible.");
                ListBox candidateList = FindActiveToolVisualRoots()
                    .SelectMany(FindVisualChildren<ListBox>)
                    .FirstOrDefault(item => string.Equals(
                        AutomationProperties.GetAutomationId(item),
                        "AutoMPointCandidateList",
                        StringComparison.Ordinal))
                    ?? throw new InvalidOperationException("Auto MPoint candidate list was not visible.");
                Button usePatternButton = FindActiveToolVisualRoots()
                    .SelectMany(FindVisualChildren<Button>)
                    .FirstOrDefault(item => string.Equals(
                        AutomationProperties.GetAutomationId(item),
                        "AutoMPointUsePattern",
                        StringComparison.Ordinal))
                    ?? throw new InvalidOperationException("Auto MPoint use-pattern button was not visible.");
                Button reportButton = FindActiveToolVisualRoots()
                    .SelectMany(FindVisualChildren<Button>)
                    .FirstOrDefault(item => string.Equals(
                        AutomationProperties.GetAutomationId(item),
                        "AutoMPointExportReport",
                        StringComparison.Ordinal))
                    ?? throw new InvalidOperationException("Auto MPoint report button was not visible.");

                analyzeButton.RaiseEvent(new RoutedEventArgs(Button.ClickEvent, analyzeButton));
                Pump(12);
                if (candidateList.Items.Count < 1
                    || candidateList.SelectedIndex < 0
                    || !usePatternButton.IsEnabled
                    || !reportButton.IsEnabled)
                {
                    throw new InvalidOperationException(
                        "Auto MPoint did not expose an operator-reviewable accepted suggestion. "
                        + $"Count={candidateList.Items.Count}, Selected={candidateList.SelectedIndex}, "
                        + $"UseEnabled={usePatternButton.IsEnabled}, ReportEnabled={reportButton.IsEnabled}");
                }
                string bestCandidateText =
                    (candidateList.SelectedItem as ListBoxItem)?.Content?.ToString() ?? string.Empty;
                AutoMPointCandidateResult selectedCandidate =
                    (candidateList.SelectedItem as ListBoxItem)?.Tag as AutoMPointCandidateResult
                    ?? throw new InvalidOperationException("Auto MPoint selected candidate evidence was unavailable.");
                if (!bestCandidateText.Contains("BEST", StringComparison.Ordinal)
                    || !bestCandidateText.Contains("Samples 3/3", StringComparison.Ordinal))
                {
                    throw new InvalidOperationException(
                        "Auto MPoint did not automatically select the representative-image best pattern. "
                        + bestCandidateText);
                }

                usePatternButton.RaiseEvent(new RoutedEventArgs(Button.ClickEvent, usePatternButton));
                Pump(8);
                string reportPath = Path.Combine(
                    Path.GetDirectoryName(outputPath) ?? ".",
                    "auto_mpoint_n_image_report.html");
                if (!matchingView.ExportAutoMPointReportForTest(reportPath) || !File.Exists(reportPath))
                {
                    throw new InvalidOperationException(
                        "Auto MPoint did not export the already-computed N-image report.");
                }

                string reportHtml = File.ReadAllText(reportPath);
                int reportRowCount = Regex.Matches(reportHtml, "<tr data-row=").Count;
                int embeddedImageCount = Regex.Matches(reportHtml, "src=\"data:image/png;base64,").Count;
                if (reportRowCount != autoMPointRepresentativePaths.Count
                    || embeddedImageCount != autoMPointRepresentativePaths.Count + 1
                    || !reportHtml.Contains("결정적 검토 드로잉", StringComparison.Ordinal)
                    || !reportHtml.Contains("매칭을 다시 실행", StringComparison.Ordinal))
                {
                    throw new InvalidOperationException(
                        "Auto MPoint HTML report missed rows, drawings, or the no-rerun boundary. "
                        + $"Rows={reportRowCount}, Embedded={embeddedImageCount}, Path={reportPath}");
                }

                autoMPointBulkReportPaths.AddRange(
                    CreateAutoMPointRepresentativeFiles(matchingBitmap, 30));
                AutoMPointCandidateResult bulkCandidate = new AutoMPointCandidateResult
                {
                    Rank = selectedCandidate.Rank,
                    PatternRoi = selectedCandidate.PatternRoi,
                    RepresentativeImageCount = autoMPointBulkReportPaths.Count,
                    RepresentativeSuccessCount = autoMPointBulkReportPaths.Count - 2
                };
                for (int index = 0; index < autoMPointBulkReportPaths.Count; index++)
                {
                    bool success = index != 6 && index != 22;
                    bulkCandidate.RepresentativeMatches.Add(new AutoMPointRepresentativeMatchResult
                    {
                        ImageIndex = index + 1,
                        Success = success,
                        Outcome = success ? "Success" : "NoMatch",
                        Message = success ? string.Empty : "Synthetic bounded report-queue failure.",
                        Center = selectedCandidate.RepresentativeMatches[0].Center,
                        Score = 80D + index * 0.5D,
                        UniquenessMargin = 0.05D + index * 0.002D,
                        Angle = index % 5 - 2,
                        Scale = 0.96D + (index % 5) * 0.02D,
                        RuntimeMilliseconds = 10D + index
                    });
                }

                string bulkReportPath = Path.Combine(
                    Path.GetDirectoryName(outputPath) ?? ".",
                    "auto_mpoint_n_image_report_30.html");
                if (!AutoMPointHtmlReportExporter.TryExport(
                        matchingBitmap,
                        autoMPointBulkReportPaths,
                        bulkCandidate,
                        "P231 deterministic queue smoke",
                        bulkReportPath,
                        out string bulkReportError))
                {
                    throw new InvalidOperationException(
                        "Auto MPoint 30-image bounded report export failed: " + bulkReportError);
                }

                string bulkReportHtml = File.ReadAllText(bulkReportPath);
                int bulkRowCount = Regex.Matches(bulkReportHtml, "<tr data-row=").Count;
                int bulkEmbeddedImageCount = Regex.Matches(
                    bulkReportHtml,
                    "src=\"data:image/png;base64,").Count;
                if (bulkRowCount != 30
                    || bulkEmbeddedImageCount <= 4
                    || bulkEmbeddedImageCount >= 31
                    || !bulkReportHtml.Contains(">failure<", StringComparison.Ordinal))
                {
                    throw new InvalidOperationException(
                        "Auto MPoint 30-image report did not preserve the full table and bounded review queue. "
                        + $"Rows={bulkRowCount}, Embedded={bulkEmbeddedImageCount}, Path={bulkReportPath}");
                }

                if (shellHost.NativePreviewRunCount != autoMPointPreviewRuns
                    || shellHost.LayerDocumentCount != autoMPointLayerCount
                    || !string.Equals(shellHost.ActiveNativeRouteInputLayerNameForTest, autoMPointInputRoute, StringComparison.Ordinal)
                    || !string.Equals(shellHost.ActiveNativeRouteOutputLayerNameForTest, autoMPointOutputRoute, StringComparison.Ordinal)
                    || !string.Equals(shellHost.ActiveHostLayerTitle, autoMPointActiveLayer, StringComparison.Ordinal))
                {
                    throw new InvalidOperationException(
                        "Auto MPoint analysis/application/report export changed Preview, layers, routing, or the active layer. "
                        + $"Preview={autoMPointPreviewRuns}->{shellHost.NativePreviewRunCount}, "
                        + $"Layers={autoMPointLayerCount}->{shellHost.LayerDocumentCount}, "
                        + $"Route={autoMPointInputRoute}->{autoMPointOutputRoute}/"
                        + $"{shellHost.ActiveNativeRouteInputLayerNameForTest}->{shellHost.ActiveNativeRouteOutputLayerNameForTest}, "
                        + $"Active={autoMPointActiveLayer}->{shellHost.ActiveHostLayerTitle}");
                }

                AssertNoAutoDockedLayers(shellHost, "Auto MPoint analyze/apply/report export");
                AssertActiveToolTextsVisible(
                    "Auto MPoint teaching panel",
                    "최적 패턴 추천",
                    "대표 이미지 선택",
                    "최적 패턴 찾기",
                    "N-이미지 보고서 저장",
                    "이 패턴 사용");

                VisionPipelineStep step = shellHost.AddActiveNativePipelineStepForTest();
                if (step == null
                    || !string.Equals(step.ToolType, "EdgeBasedMatching", StringComparison.Ordinal)
                    || !string.Equals(step.InputLayer, "Main", StringComparison.Ordinal)
                    || !string.Equals(step.OutputLayer, "EdgeBasedMatching_1", StringComparison.Ordinal)
                    || step.Parameters == null
                    || !step.Parameters.ContainsKey("PATTERN_PATH")
                    || !step.Parameters.ContainsKey("SCORE_MIN")
                    || !string.Equals(step.Parameters["USE_UNIQUE_MATCH_VALIDATION"], "true", StringComparison.OrdinalIgnoreCase)
                    || !string.Equals(step.Parameters["UNIQUE_MATCH_MIN_SCORE_MARGIN"], "0.07", StringComparison.Ordinal)
                    || !string.Equals(step.Parameters["ALLOW_GLOBAL_POLARITY_REVERSAL"], "true", StringComparison.OrdinalIgnoreCase)
                    || !string.Equals(step.Parameters["USE_THRESHOLD"], "false", StringComparison.OrdinalIgnoreCase)
                    || !string.Equals(step.Parameters["USE_ADAPTIVE_THRESHOLD"], "false", StringComparison.OrdinalIgnoreCase)
                    || !step.Parameters.ContainsKey("CANNY_LOW"))
                {
                    throw new InvalidOperationException("EdgeBasedMatching WPF tool did not create a valid pipeline step.");
                }

                EdgeBasedMatchingProperty? roundTripProperty =
                    VisionPipelineStepPropertyMapper.CreateProperty(step) as EdgeBasedMatchingProperty;
                if (roundTripProperty == null
                    || !roundTripProperty.USE_UNIQUE_MATCH_VALIDATION
                    || !roundTripProperty.ALLOW_GLOBAL_POLARITY_REVERSAL
                    || roundTripProperty.USE_THRESHOLD
                    || roundTripProperty.USE_ADAPTIVE_THRESHOLD
                    || Math.Abs(roundTripProperty.UNIQUE_MATCH_MIN_SCORE_MARGIN - 0.07D) > 0.000001D)
                {
                    throw new InvalidOperationException(
                        "EdgeBasedMatching unique-match settings did not survive Pipeline PropertyGrid round trip.");
                }

                VisionPipelineStep applyStep = CloneStep(step);
                applyStep.Name = "Edge Based Matching Reviewed";
                applyStep.Parameters["Name"] = applyStep.Name;
                applyStep.ToolType = "EdgeBasedTemplateMatchingTool";
                applyStep.InputLayer = "ReviewedInput";
                applyStep.OutputLayer = "ReviewedEdgeOutput";
                applyStep.Enabled = false;
                applyStep.UseAcceptance = true;
                applyStep.ExpectedSuccess = false;
                applyStep.MaxElapsedMilliseconds = 87;
                applyStep.RequiredMessageText = "edge-reviewed";
                applyStep.AcceptanceMetricName = "ScoreMax";
                applyStep.UseAcceptanceMetricMinimum = true;
                applyStep.AcceptanceMetricMinimum = 0.8;
                applyStep.UseAcceptanceMetricMaximum = true;
                applyStep.AcceptanceMetricMaximum = 1;
                object applyProperty = VisionPipelineStepPropertyMapper.CreateProperty(applyStep);
                applyStep.Name = "Changed";
                applyStep.Parameters["Name"] = applyStep.Name;
                applyStep.InputLayer = "ChangedInput";
                applyStep.OutputLayer = "ChangedOutput";
                applyStep.Enabled = true;
                applyStep.UseAcceptance = false;
                applyStep.ExpectedSuccess = true;
                applyStep.MaxElapsedMilliseconds = 0;
                applyStep.RequiredMessageText = string.Empty;
                applyStep.AcceptanceMetricName = string.Empty;
                applyStep.UseAcceptanceMetricMinimum = false;
                applyStep.AcceptanceMetricMinimum = 0;
                applyStep.UseAcceptanceMetricMaximum = false;
                applyStep.AcceptanceMetricMaximum = 0;
                if (!VisionPipelineStepPropertyMapper.ApplyProperty(applyStep, applyProperty)
                    || !string.Equals(applyStep.Name, "Edge Based Matching Reviewed", StringComparison.Ordinal)
                    || !string.Equals(applyStep.ToolType, "EdgeBasedMatching", StringComparison.Ordinal)
                    || !string.Equals(applyStep.InputLayer, "ReviewedInput", StringComparison.Ordinal)
                    || !string.Equals(applyStep.OutputLayer, "ReviewedEdgeOutput", StringComparison.Ordinal)
                    || applyStep.Enabled
                    || !applyStep.UseAcceptance
                    || applyStep.ExpectedSuccess
                    || Math.Abs(applyStep.MaxElapsedMilliseconds - 87D) > 0.000001D
                    || !string.Equals(applyStep.RequiredMessageText, "edge-reviewed", StringComparison.Ordinal)
                    || !string.Equals(applyStep.AcceptanceMetricName, "ScoreMax", StringComparison.Ordinal)
                    || !applyStep.UseAcceptanceMetricMinimum
                    || Math.Abs(applyStep.AcceptanceMetricMinimum - 0.8D) > 0.000001D
                    || !applyStep.UseAcceptanceMetricMaximum
                    || Math.Abs(applyStep.AcceptanceMetricMaximum - 1D) > 0.000001D
                    || !string.Equals(applyStep.Parameters["PATTERN_PATH"], step.Parameters["PATTERN_PATH"], StringComparison.Ordinal)
                    || !string.Equals(applyStep.Parameters["SCORE_MIN"], step.Parameters["SCORE_MIN"], StringComparison.Ordinal)
                    || !string.Equals(applyStep.Parameters["USE_UNIQUE_MATCH_VALIDATION"], "true", StringComparison.OrdinalIgnoreCase)
                    || !string.Equals(applyStep.Parameters["UNIQUE_MATCH_MIN_SCORE_MARGIN"], "0.07", StringComparison.Ordinal)
                    || !string.Equals(applyStep.Parameters["ALLOW_GLOBAL_POLARITY_REVERSAL"], "true", StringComparison.OrdinalIgnoreCase)
                    || !string.Equals(applyStep.Parameters["USE_THRESHOLD"], "false", StringComparison.OrdinalIgnoreCase)
                    || !string.Equals(applyStep.Parameters["USE_ADAPTIVE_THRESHOLD"], "false", StringComparison.OrdinalIgnoreCase)
                    || !string.Equals(applyStep.Parameters["CANNY_LOW"], step.Parameters["CANNY_LOW"], StringComparison.Ordinal))
                {
                    throw new InvalidOperationException(
                        "EdgeBasedMatching alias/apply metadata and layer round trip changed. "
                        + $"Name={applyStep.Name}; ToolType={applyStep.ToolType}; "
                        + $"Layers={applyStep.InputLayer}->{applyStep.OutputLayer}; Enabled={applyStep.Enabled}; "
                        + $"Acceptance={applyStep.UseAcceptance}/{applyStep.ExpectedSuccess}; "
                        + $"Elapsed={applyStep.MaxElapsedMilliseconds}; Message={applyStep.RequiredMessageText}; "
                        + $"Metric={applyStep.AcceptanceMetricName}; "
                        + $"Min={applyStep.UseAcceptanceMetricMinimum}/{applyStep.AcceptanceMetricMinimum}; "
                        + $"Max={applyStep.UseAcceptanceMetricMaximum}/{applyStep.AcceptanceMetricMaximum}.");
                }

                VisionPipelineStep explicitThresholdStep = CloneStep(step);
                explicitThresholdStep.Parameters["USE_THRESHOLD"] = "true";
                EdgeBasedMatchingProperty? explicitThresholdProperty =
                    VisionPipelineStepPropertyMapper.CreateProperty(explicitThresholdStep) as EdgeBasedMatchingProperty;
                if (explicitThresholdProperty == null || !explicitThresholdProperty.USE_THRESHOLD)
                {
                    throw new InvalidOperationException(
                        "Explicit legacy EdgeBasedMatching USE_THRESHOLD=true was not preserved.");
                }

                VisionPipelineStep legacyStep = CloneStep(step);
                legacyStep.Parameters.Remove("USE_UNIQUE_MATCH_VALIDATION");
                legacyStep.Parameters.Remove("UNIQUE_MATCH_MIN_SCORE_MARGIN");
                legacyStep.Parameters.Remove("ALLOW_GLOBAL_POLARITY_REVERSAL");
                EdgeBasedMatchingProperty? legacyProperty =
                    VisionPipelineStepPropertyMapper.CreateProperty(legacyStep) as EdgeBasedMatchingProperty;
                if (legacyProperty == null
                    || legacyProperty.USE_UNIQUE_MATCH_VALIDATION
                    || legacyProperty.ALLOW_GLOBAL_POLARITY_REVERSAL
                    || Math.Abs(legacyProperty.UNIQUE_MATCH_MIN_SCORE_MARGIN - 0.03D) > 0.000001D)
                {
                    throw new InvalidOperationException(
                        "Legacy EdgeBasedMatching XML without unique-match/polarity keys did not restore disabled defaults.");
                }

                VisionPipeline validPipeline = new VisionPipeline { Name = "P224 Unique Match Valid" };
                validPipeline.Steps.Add(CloneStep(step));
                VisionPipelineValidationResult validDefinition =
                    VisionPipelineValidator.Validate(validPipeline, new[] { "Main" });
                if (!validDefinition.Success)
                {
                    throw new InvalidOperationException(
                        "Valid unique-match pipeline was rejected: " + validDefinition.FormatErrors());
                }

                VisionPipeline invalidPipeline = new VisionPipeline { Name = "P224 Unique Match Invalid" };
                VisionPipelineStep invalidStep = CloneStep(step);
                invalidStep.Parameters["NUM_MATCH"] = "2";
                invalidPipeline.Steps.Add(invalidStep);
                VisionPipelineValidationResult invalidDefinition =
                    VisionPipelineValidator.Validate(invalidPipeline, new[] { "Main" });
                if (invalidDefinition.Success
                    || !invalidDefinition.Errors.Any(error =>
                        error.Contains("requires NUM_MATCH=1", StringComparison.Ordinal)))
                {
                    throw new InvalidOperationException(
                        "Unique-match validator did not fail closed for NUM_MATCH=2.");
                }

                VisionPipeline invalidPolarityPipeline = new VisionPipeline { Name = "CVR-11 Invalid Polarity" };
                VisionPipelineStep invalidPolarityStep = CloneStep(step);
                invalidPolarityStep.Parameters["ALLOW_GLOBAL_POLARITY_REVERSAL"] = "sometimes";
                invalidPolarityPipeline.Steps.Add(invalidPolarityStep);
                VisionPipelineValidationResult invalidPolarityDefinition =
                    VisionPipelineValidator.Validate(invalidPolarityPipeline, new[] { "Main" });
                if (invalidPolarityDefinition.Success
                    || !invalidPolarityDefinition.Errors.Any(error =>
                        error.Contains("must be true or false", StringComparison.Ordinal)))
                {
                    throw new InvalidOperationException(
                        "Global-polarity validator did not fail closed for a non-Boolean value.");
                }

                autoMPointTemplatePath = step.Parameters["PATTERN_PATH"];
                if (string.IsNullOrWhiteSpace(autoMPointTemplatePath)
                    || !File.Exists(autoMPointTemplatePath)
                    || string.Equals(autoMPointTemplatePath, templatePath, StringComparison.OrdinalIgnoreCase))
                {
                    throw new InvalidOperationException(
                        "Auto MPoint did not persist the selected suggestion as a new matching template. "
                        + $"Original={templatePath}, Applied={autoMPointTemplatePath}");
                }

                if (dockAfterVerification)
                {
                    int explicitPreviewRuns = shellHost.NativePreviewRunCount;
                    shellHost.RunActiveNativePreviewForTest();
                    Pump(16);
                    if (shellHost.NativePreviewRunCount != explicitPreviewRuns + 1
                        || !shellHost.HasNativePreviewResult)
                    {
                        throw new InvalidOperationException(
                            "EdgeBasedMatching did not run only after the explicit post-apply Preview action.");
                    }

                    teachingPanel.DetailsExpander.IsExpanded = false;
                    Pump(4);
                    AssertDockActiveNativeTool(shellHost, "EdgeBasedMatchingToolWpfView", "Docked EdgeBasedMatching tool layout");
                    AssertFloatingPropertyGridMinimumSize("Docked EdgeBasedMatching property grid", 480D, 160D);
                    AssertMatchingWorkbenchResult(shellHost, "Docked EdgeBasedMatching", "Edge Match /", "검출", "점수");
                    AssertRetainedMatchingTeaching(shellHost, "Docked EdgeBasedMatching verification guide", "엣지", "Canny", "포인트", "미리보기 OK");
                }
                else
                {
                    int propertyGridLabelCheckRuns = shellHost.NativePreviewRunCount;
                    shellHost.ConfigureActiveEdgeBasedMatchingForTest(property =>
                    {
                        property.ShowAdvancedSettings = true;
                    });
                    Pump(8);
                    if (shellHost.NativePreviewRunCount != propertyGridLabelCheckRuns)
                    {
                        throw new InvalidOperationException(
                            "EdgeBasedMatching PropertyGrid label inspection triggered Preview.");
                    }
                    SetActivePropertyGridSearchText("P227 unique-match PropertyGrid evidence", "고유");
                    Pump(6);
                    AssertActiveToolTextsVisible(
                        "P227 unique-match PropertyGrid rows",
                        "고유 매칭 요구",
                        "최소 고유 점수 여유");
                }
            });
        }
        finally
        {
            RecipeWorkspaceService.DeleteVisionWorkspace(recipeName);
            TryDeleteFile(templatePath);
            TryDeleteFile(autoMPointTemplatePath);
            TryDeleteFile(Path.ChangeExtension(autoMPointTemplatePath, ".roi"));
            foreach (string path in autoMPointRepresentativePaths)
            {
                TryDeleteFile(path);
            }
            foreach (string path in autoMPointBulkReportPaths)
            {
                TryDeleteFile(path);
            }
        }
    }

    private static CaptureResult CaptureShellHostFeatureMatchingTool(string outputPath)
    {
        OpenVisionLanguageService.SetLanguage(OpenVisionLanguage.Korean, false);
        OpenVisionShellHostView shellHost = CreateShellHost("Smoke_WpfShellHostFeatureMatching");
        using Bitmap featureBitmap = CreateFeatureMatchingSmokeBitmap();
        string templatePath = CreateFeatureMatchingTemplateFile(featureBitmap);
        try
        {
            shellHost.SetMainLayerImageForTest(featureBitmap);
            return CaptureWindowWithContent(shellHost, outputPath, 1600, 900, () =>
            {
                shellHost.SelectToolForTest(VISION_MENU.FeatureMatching);
                Pump(16);
                AssertToolHeaderLearnOpensTopic(shellHost, 10, "FeatureMatching header Learn");
                SelectComboBoxItemText(FindFloatingComboBox("cbInputLayer"), "Main", "FeatureMatching owned input");
                if (shellHost.ActiveNativeRouteInputLayerNameForTest != "Main" || shellHost.ActiveNativeRouteOutputLayerNameForTest != "FeatureMatching_1")
                    throw new InvalidOperationException("FeatureMatching fixture must select its owned Main image and retain the V2 test output FeatureMatching_1.");
                int beforeAutoPreviewRuns = shellHost.NativePreviewRunCount;
                shellHost.SetActiveFeatureMatchingTemplatePathForTest(templatePath);
                Stopwatch templatePreviewWait = Stopwatch.StartNew();
                while (shellHost.NativePreviewRunCount <= beforeAutoPreviewRuns
                    && templatePreviewWait.ElapsedMilliseconds < 5000)
                {
                    Pump(2);
                    Thread.Sleep(10);
                }
                if (!shellHost.IsNativeDocumentActive || !shellHost.HasNativePreviewResult)
                {
                    throw new InvalidOperationException("Native WPF FeatureMatching tool did not auto-preview after template registration: " + shellHost.ActiveNativeStatusText);
                }

                if (shellHost.NativePreviewRunCount <= beforeAutoPreviewRuns)
                {
                    throw new InvalidOperationException("Native WPF FeatureMatching template registration did not request an auto-preview.");
                }

                if (!shellHost.ActiveNativeDocumentTypeName.Contains("FeatureMatchingToolWpfView", StringComparison.Ordinal))
                {
                    throw new InvalidOperationException("FeatureMatching did not open the WPF FeatureMatching tool view.");
                }

                if (!string.Equals(shellHost.ActiveNativeRouteInputLayerNameForTest, "Main", StringComparison.OrdinalIgnoreCase)
                    || !string.Equals(shellHost.ActiveNativeRouteOutputLayerNameForTest, "FeatureMatching_1", StringComparison.OrdinalIgnoreCase)
                    || !string.Equals(shellHost.ActiveHostLayerTitle, "Main", StringComparison.OrdinalIgnoreCase))
                {
                    throw new InvalidOperationException(
                        "FeatureMatching template registration changed the route or active input layer. "
                        + $"Input={shellHost.ActiveNativeRouteInputLayerNameForTest}, Output={shellHost.ActiveNativeRouteOutputLayerNameForTest}, Active={shellHost.ActiveHostLayerTitle}, Status={shellHost.ActiveNativeStatusText}");
                }

                AssertNoAutoDockedLayers(shellHost, "FeatureMatching template auto-preview");
                AssertMatchingWorkbenchResult(shellHost, "FeatureMatching", "Feature Match /", "검출", "점수", "중심", "박스");
                AssertMatchingWorkbenchResult(shellHost, "FeatureMatching result guidance", "미리보기 OK", "합격 기준:", "Ratio", "RANSAC", "다음:");
                AssertRetainedMatchingTeaching(shellHost, "FeatureMatching retained decision", "미리보기 OK", "Ratio", "RANSAC");
                AssertRetainedMatchingTeaching(shellHost, "FeatureMatching teaching summary", "템플릿 준비", "Ratio", "RANSAC", "원본", "전체 이미지");
                AssertActiveToolTextsVisible("FeatureMatching ratio PropertyGrid label", "Ratio 기준");

                OpenVisionNativeToolDocument beforeAddDocument = shellHost.ActiveNativeDocumentForTest!;
                int beforeAddRuns = beforeAddDocument.PreviewRunCount;
                VisionPipelineStep step = shellHost.AddActiveNativePipelineStepForTest();
                if (step == null
                    || !string.Equals(step.ToolType, "FeatureMatching", StringComparison.Ordinal)
                    || !string.Equals(step.InputLayer, "Main", StringComparison.Ordinal)
                    || !string.Equals(step.OutputLayer, "FeatureMatching_1", StringComparison.Ordinal)
                    || step.Parameters == null
                    || !step.Parameters.ContainsKey("PATTERN_PATH")
                    || !step.Parameters.ContainsKey("SCORE_MIN")
                    || !step.Parameters.ContainsKey("RANSAC_REPROJ_THRESHOLD"))
                {
                    throw new InvalidOperationException("FeatureMatching WPF tool did not create a valid pipeline step.");
                }

                foreach (string alias in new[] { "FeatureTool", "SiftTool" })
                {
                    VisionPipelineStep aliasStep = CloneStep(step);
                    aliasStep.ToolType = alias;
                    if (VisionPipelineStepPropertyMapper.CreateProperty(aliasStep) is not FeatureMatchingProperty)
                    {
                        throw new InvalidOperationException(
                            $"FeatureMatching alias '{alias}' did not create the PropertyGrid model.");
                    }
                }

                VisionPipelineStep applyStep = CloneStep(step);
                applyStep.Name = "Feature Matching Reviewed";
                applyStep.Parameters["Name"] = applyStep.Name;
                applyStep.ToolType = "SiftTool";
                applyStep.InputLayer = "ReviewedInput";
                applyStep.OutputLayer = "ReviewedFeatureOutput";
                applyStep.Enabled = false;
                applyStep.UseAcceptance = true;
                applyStep.ExpectedSuccess = false;
                applyStep.MaxElapsedMilliseconds = 93;
                applyStep.RequiredMessageText = "feature-reviewed";
                applyStep.AcceptanceMetricName = "ScoreMax";
                applyStep.UseAcceptanceMetricMinimum = true;
                applyStep.AcceptanceMetricMinimum = 70;
                applyStep.UseAcceptanceMetricMaximum = true;
                applyStep.AcceptanceMetricMaximum = 100;
                applyStep.Parameters["SCORE_MIN"] = "0.71";
                applyStep.Parameters["RANSAC_REPROJ_THRESHOLD"] = "4.5";
                applyStep.Parameters["PATTERN_PATH"] = templatePath;
                applyStep.Parameters["TemplatePath"] = templatePath;
                applyStep.Parameters["USE_THRESHOLD"] = "false";
                applyStep.Parameters["USE_ADAPTIVE_THRESHOLD"] = "false";
                applyStep.Parameters["USE_ROI"] = "true";
                applyStep.Parameters["CvROI"] = "12,18,160,120";
                object applyProperty = VisionPipelineStepPropertyMapper.CreateProperty(applyStep);
                applyStep.Name = "Changed";
                applyStep.Parameters["Name"] = applyStep.Name;
                applyStep.InputLayer = "ChangedInput";
                applyStep.OutputLayer = "ChangedOutput";
                applyStep.Enabled = true;
                applyStep.UseAcceptance = false;
                applyStep.ExpectedSuccess = true;
                applyStep.MaxElapsedMilliseconds = 0;
                applyStep.RequiredMessageText = string.Empty;
                applyStep.AcceptanceMetricName = string.Empty;
                applyStep.UseAcceptanceMetricMinimum = false;
                applyStep.AcceptanceMetricMinimum = 0;
                applyStep.UseAcceptanceMetricMaximum = false;
                applyStep.AcceptanceMetricMaximum = 0;
                applyStep.Parameters["SCORE_MIN"] = "0.9";
                applyStep.Parameters["RANSAC_REPROJ_THRESHOLD"] = "1";
                applyStep.Parameters["PATTERN_PATH"] = "changed";
                applyStep.Parameters["TemplatePath"] = "changed";
                applyStep.Parameters["USE_ROI"] = "false";
                if (!VisionPipelineStepPropertyMapper.ApplyProperty(applyStep, applyProperty)
                    || !string.Equals(applyStep.Name, "Feature Matching Reviewed", StringComparison.Ordinal)
                    || !string.Equals(applyStep.ToolType, "FeatureMatching", StringComparison.Ordinal)
                    || !string.Equals(applyStep.InputLayer, "ReviewedInput", StringComparison.Ordinal)
                    || !string.Equals(applyStep.OutputLayer, "ReviewedFeatureOutput", StringComparison.Ordinal)
                    || applyStep.Enabled
                    || !applyStep.UseAcceptance
                    || applyStep.ExpectedSuccess
                    || Math.Abs(applyStep.MaxElapsedMilliseconds - 93D) > 0.000001D
                    || !string.Equals(applyStep.RequiredMessageText, "feature-reviewed", StringComparison.Ordinal)
                    || !string.Equals(applyStep.AcceptanceMetricName, "ScoreMax", StringComparison.Ordinal)
                    || !applyStep.UseAcceptanceMetricMinimum
                    || Math.Abs(applyStep.AcceptanceMetricMinimum - 70D) > 0.000001D
                    || !applyStep.UseAcceptanceMetricMaximum
                    || Math.Abs(applyStep.AcceptanceMetricMaximum - 100D) > 0.000001D
                    || !string.Equals(applyStep.Parameters["SCORE_MIN"], "0.71", StringComparison.Ordinal)
                    || !string.Equals(applyStep.Parameters["RANSAC_REPROJ_THRESHOLD"], "4.5", StringComparison.Ordinal)
                    || !string.Equals(applyStep.Parameters["PATTERN_PATH"], templatePath, StringComparison.Ordinal)
                    || !string.Equals(applyStep.Parameters["TemplatePath"], templatePath, StringComparison.Ordinal)
                    || !string.Equals(applyStep.Parameters["USE_THRESHOLD"], "false", StringComparison.OrdinalIgnoreCase)
                    || !string.Equals(applyStep.Parameters["USE_ADAPTIVE_THRESHOLD"], "false", StringComparison.OrdinalIgnoreCase)
                    || !string.Equals(applyStep.Parameters["USE_ROI"], "true", StringComparison.OrdinalIgnoreCase)
                    || !string.Equals(applyStep.Parameters["CvROI"], "12,18,160,120", StringComparison.Ordinal))
                {
                    throw new InvalidOperationException(
                        "FeatureMatching alias/apply metadata, layer, and parameter round trip changed.");
                }

                OpenVisionNativeToolDocument addedDocument = shellHost.ActiveNativeDocumentForTest!;
                File.WriteAllText(Path.ChangeExtension(outputPath, ".add-dock-checks.json"), JsonSerializer.Serialize(new
                { SameCachedDocument = ReferenceEquals(beforeAddDocument, addedDocument), BeforeAddRuns = beforeAddRuns, AfterDockRuns = addedDocument.PreviewRunCount,
                    addedDocument.HasPreviewResult, addedDocument.IsPreviewRunning, CurrentResult = shellHost.Workbench.Tool.HasResult }, new JsonSerializerOptions { WriteIndented = true }));
                if (!ReferenceEquals(beforeAddDocument, addedDocument) || addedDocument.PreviewRunCount != beforeAddRuns || addedDocument.IsPreviewRunning)
                    throw new InvalidOperationException("FeatureMatching step creation executed implicitly or replaced the cached document.");
                AssertDockActiveNativeTool(shellHost, "FeatureMatchingToolWpfView", "Docked FeatureMatching tool layout");
                if (!ReferenceEquals(addedDocument, shellHost.ActiveNativeDocumentForTest) || addedDocument.PreviewRunCount != beforeAddRuns || addedDocument.IsPreviewRunning)
                    throw new InvalidOperationException("FeatureMatching docking executed or replaced the active step editor.");
                shellHost.RunActiveNativePreviewForTest();
                Pump(24);
                if (addedDocument.PreviewRunCount != beforeAddRuns + 1 || !addedDocument.HasPreviewResult || !shellHost.Workbench.Tool.HasResult || shellHost.Workbench.Tool.IsResultPrevious)
                    throw new InvalidOperationException("FeatureMatching explicit post-add Run did not publish one current result.");
                AssertFloatingPropertyGridMinimumSize("Docked FeatureMatching property grid", 480D, 160D);
                AssertMatchingWorkbenchResult(shellHost, "Docked FeatureMatching", "Feature Match /", "검출", "점수");
                AssertMatchingWorkbenchResult(shellHost, "Docked FeatureMatching result guidance", "미리보기 OK", "합격 기준:", "Ratio", "RANSAC", "다음:");
                AssertRetainedMatchingTeaching(shellHost, "Docked FeatureMatching retained decision", "미리보기 OK", "Ratio", "RANSAC");
            });
        }
        finally
        {
            TryDeleteFile(templatePath);
        }
    }

    private static CaptureResult CaptureShellHostLineTool(string outputPath)
