        AssertParameterGuideDetailedCoverage(property, "EdgeBasedMatching");
        string[] basic = auditedProperties
            .Where(name =>
            {
                VisionToolParameterGuideContent content =
                    VisionToolParameterGuideCatalog.Resolve(property, name);
                return content == null
                    || content.Coverage.Contains("Basic", StringComparison.OrdinalIgnoreCase);
            })
            .ToArray();
        if (basic.Length > 0)
        {
            throw new InvalidOperationException(
                "P268 EdgeBasedMatching properties remained Basic: "
                + string.Join(",", basic));
        }

        VisionToolParameterGuideContent pattern =
            VisionToolParameterGuideCatalog.Resolve(
                property,
                nameof(EdgeBasedMatchingProperty.PATTERN_PATH));
        VisionToolParameterGuideContent draw =
            VisionToolParameterGuideCatalog.Resolve(
                property,
                nameof(EdgeBasedMatchingProperty.USE_DRAW_IMAGE));
        VisionToolParameterGuideContent autoMPoint =
            VisionToolParameterGuideCatalog.Resolve(
                property,
                nameof(EdgeBasedMatchingProperty.AUTO_MPOINT_MAX_RESULTS));
        VisionToolParameterGuideContent aperture =
            VisionToolParameterGuideCatalog.Resolve(
                property,
                nameof(EdgeBasedMatchingProperty.CANNY_APERTURE_SIZE));
        VisionToolParameterGuideContent pyramid =
            VisionToolParameterGuideCatalog.Resolve(
                property,
                nameof(EdgeBasedMatchingProperty.USE_PYRAMID_POSITION_PROPOSAL));
        VisionToolParameterGuideContent hybridWeight =
            VisionToolParameterGuideCatalog.Resolve(
                property,
                nameof(EdgeBasedMatchingProperty.HYBRID_VERIFY_IMAGE_WEIGHT));
        AssertContains(pattern?.Risk ?? string.Empty, "does not prove", "P268 physical-identity boundary");
        AssertContains(draw?.Impact ?? string.Empty, "even when Off", "P268 successful drawing boundary");
        AssertContains(autoMPoint?.Risk ?? string.Empty, "auto-selected", "P268 Suggested-only boundary");
        AssertContains(aperture?.Summary ?? string.Empty, "3, 5, or 7", "P268 Canny normalization");
        AssertContains(pyramid?.Impact ?? string.Empty, "bypassed when scale search", "P268 scale/pyramid boundary");
        AssertContains(hybridWeight?.Summary ?? string.Empty, "public result score remains", "P268 public-score boundary");

        property.AUTO_MPOINT_USE_ANALYSIS_ROI = false;
        property.USE_FIND_ANGLE = true;
        property.USE_COARSE_TO_FINE_ANGLE_SEARCH = false;
        property.USE_PYRAMID_POSITION_PROPOSAL = false;
        property.USE_HYBRID_VERIFY = false;
        foreach (string inactiveProperty in new[]
        {
            nameof(EdgeBasedMatchingProperty.AUTO_MPOINT_ANALYSIS_ROI),
            nameof(EdgeBasedMatchingProperty.COARSE_ANGLE_STEP),
            nameof(EdgeBasedMatchingProperty.PYRAMID_POSITION_MIN_SCORE),
            nameof(EdgeBasedMatchingProperty.HYBRID_VERIFY_IMAGE_WEIGHT)
        })
        {
            VisionToolParameterGuideContent inactive =
                VisionToolParameterGuideCatalog.Resolve(property, inactiveProperty);
            if (inactive == null
                || !inactive.Applicability.Contains(
                    "Currently inactive",
                    StringComparison.OrdinalIgnoreCase))
            {
                throw new InvalidOperationException(
                    "P268 conditional applicability was not explicit for "
                    + inactiveProperty
                    + ".");
            }
        }

        property.USE_FIND_SCALE = true;
        property.FIND_SCALE_MIN = 0.92D;
        property.FIND_SCALE_MAX = 1.08D;
        property.FIND_SCALE_STEP = 0.02D;
        property.USE_SUBPIXEL_REFINE = true;
        property.USE_PYRAMID_POSITION_PROPOSAL = true;
        property.PYRAMID_POSITION_TOP_N = 7;
        property.PYRAMID_POSITION_MIN_SCORE = 0.73D;
        VisionPipelineStep roundTripStep =
            VisionPipelineStepBuilder.FromProperty(property, "Main", "EdgeResult");
        object mappedObject =
            VisionPipelineStepPropertyMapper.CreateProperty(roundTripStep)
            ?? throw new InvalidOperationException(
                "P268 Recipe EdgeBasedMatching PropertyGrid mapping returned no property.");
        EdgeBasedMatchingProperty mapped = mappedObject as EdgeBasedMatchingProperty
            ?? throw new InvalidOperationException(
                "P268 Recipe EdgeBasedMatching PropertyGrid returned the wrong property type.");
        if (!mapped.USE_FIND_SCALE
            || Math.Abs(mapped.FIND_SCALE_MIN - 0.92D) > 0.000001D
            || Math.Abs(mapped.FIND_SCALE_MAX - 1.08D) > 0.000001D
            || Math.Abs(mapped.FIND_SCALE_STEP - 0.02D) > 0.000001D
            || !mapped.USE_SUBPIXEL_REFINE
            || !mapped.USE_PYRAMID_POSITION_PROPOSAL
            || mapped.PYRAMID_POSITION_TOP_N != 7
            || Math.Abs(mapped.PYRAMID_POSITION_MIN_SCORE - 0.73D) > 0.000001D)
        {
            throw new InvalidOperationException(
                "P268 Recipe EdgeBasedMatching scale/subpixel/pyramid values were not restored.");
        }
        if (!VisionPipelineStepPropertyMapper.ApplyProperty(roundTripStep, mapped))
        {
            throw new InvalidOperationException(
                "P268 Recipe EdgeBasedMatching PropertyGrid apply failed.");
        }
        EdgeBasedMatchingProperty reloaded =
            VisionPipelineStepPropertyMapper.CreateProperty(roundTripStep)
                as EdgeBasedMatchingProperty
            ?? throw new InvalidOperationException(
                "P268 Recipe EdgeBasedMatching reload returned no property.");
        if (!reloaded.USE_FIND_SCALE
            || !reloaded.USE_SUBPIXEL_REFINE
            || !reloaded.USE_PYRAMID_POSITION_PROPOSAL
            || reloaded.PYRAMID_POSITION_TOP_N != 7
            || Math.Abs(reloaded.PYRAMID_POSITION_MIN_SCORE - 0.73D) > 0.000001D)
        {
            throw new InvalidOperationException(
                "P268 Recipe EdgeBasedMatching apply/reload lost active runtime values.");
        }
        string[] recipeBasic = auditedProperties
            .Where(name =>
            {
                VisionToolParameterGuideContent content =
                    VisionToolParameterGuideCatalog.Resolve(mappedObject, name);
                return content == null
                    || content.Coverage.Contains("Basic", StringComparison.OrdinalIgnoreCase);
            })
            .ToArray();
        if (recipeBasic.Length > 0)
        {
            throw new InvalidOperationException(
                "P268 Recipe EdgeBasedMatching audited properties remained Basic: "
                + string.Join(",", recipeBasic));
        }

        OpenVisionShellHostView shellHost =
            CreateShellHost("Smoke_P268EdgeBasedMatchingParameterGuide");
        return CaptureWindowWithContent(shellHost, outputPath, 1600, 900, () =>
        {
            shellHost.SelectToolForTest(VISION_MENU.EdgeBasedMatching);
            Pump(24);
            System.Windows.Controls.WpfPropertyGrid.PropertyGrid liveGrid =
                GetActiveFloatingPropertyGrid("P268 EdgeBasedMatching guide");
            EdgeBasedMatchingProperty live =
                liveGrid.SelectedObject as EdgeBasedMatchingProperty
                ?? throw new InvalidOperationException(
                    "P268 EdgeBasedMatching PropertyGrid was not available.");
            live.AUTO_MPOINT_USE_ANALYSIS_ROI = true;
            live.USE_FIND_ANGLE = true;
            live.USE_COARSE_TO_FINE_ANGLE_SEARCH = true;
            live.USE_PYRAMID_POSITION_PROPOSAL = true;
            live.USE_HYBRID_VERIFY = true;
            new OpenVisionLab.Common.PropertyGridEventBinder(null)
                .ApplyVisibilityRules(liveGrid);
            liveGrid.RefreshSelectedObject();
            OpenVisionLanguageService.SetLanguage(OpenVisionLanguage.English, false);
            Pump(16);
            AssertParameterGuideDetailedCoverage(live, "EdgeBasedMatching live");

            AssertParameterGuideSelectionSideEffects(
                shellHost,
                nameof(EdgeBasedMatchingProperty.PATTERN_PATH),
                guide =>
                {
                    AssertContains(guide.SummaryForTest, "directed-edge model", "P268 live pattern model");
                    AssertContains(guide.ImpactForTest, "physical feature", "P268 live physical identity");
                });
            AssertParameterGuideSelectionSideEffects(
                shellHost,
                nameof(EdgeBasedMatchingProperty.AUTO_MPOINT_MAX_RESULTS),
                guide =>
                {
                    AssertContains(guide.SummaryForTest, "Suggested rows", "P268 live Auto MPoint scope");
                    AssertContains(guide.CheckForTest, "explicitly apply", "P268 live explicit apply");
                });
            AssertParameterGuideSelectionSideEffects(
                shellHost,
                nameof(EdgeBasedMatchingProperty.CANNY_APERTURE_SIZE),
                guide => AssertContains(
                    guide.SummaryForTest,
                    "3, 5, or 7",
                    "P268 live Canny normalization"));
            AssertParameterGuideSelectionSideEffects(
                shellHost,
                nameof(EdgeBasedMatchingProperty.USE_DRAW_IMAGE),
                guide => AssertContains(
                    guide.ImpactForTest,
                    "even when Off",
                    "P268 live drawing boundary"));
            AssertParameterGuideSelectionSideEffects(
                shellHost,
                nameof(EdgeBasedMatchingProperty.USE_PYRAMID_POSITION_PROPOSAL),
                guide => AssertContains(
                    guide.ImpactForTest,
                    "bypassed when scale search",
                    "P268 live pyramid boundary"));
            AssertParameterGuideSelectionSideEffects(
                shellHost,
                nameof(EdgeBasedMatchingProperty.HYBRID_VERIFY_IMAGE_WEIGHT),
                guide => AssertContains(
                    guide.SummaryForTest,
                    "public result score remains",
                    "P268 live hybrid score boundary"));

            OpenVisionLanguageService.SetLanguage(OpenVisionLanguage.Korean, false);
            Pump(12);
            string koreanPattern = OpenVisionLanguageService.T(
                "VisionTool.ParameterGuide.EdgeMatching.Pattern.Summary");
            if (string.IsNullOrWhiteSpace(koreanPattern)
                || koreanPattern.StartsWith(
                    "VisionTool.ParameterGuide.",
                    StringComparison.Ordinal))
            {
                throw new InvalidOperationException(
                    "P268 Korean EdgeBasedMatching guide localization was not resolved.");
            }

            string reportDirectory = Path.GetDirectoryName(outputPath) ?? ".";
            File.WriteAllLines(
                Path.Combine(reportDirectory, "p268-edge-based-matching-parameter-guide-smoke.txt"),
                new[]
                {
                    "Status=OK",
                    "DetailedFamily=EdgeBasedMatching",
                    "DetailedProperties=65/65",
                    "AuditedProperties=32/32",
                    "Groups=template-display,auto-mpoint-teaching,edge-model,coarse-refine-pyramid-hybrid-search",
                    "IdentityBoundary=score,margin,rank do not prove physical-feature identity",
                    "AutoMPointBoundary=explicit Analyze candidates; Suggested not Qualified; explicit Use this pattern",
                    "DrawingBoundary=display-only; successful evidence retained when Off",
                    "RuntimeRoundTrip=scale,subpixel,pyramid apply-reload preserved",
                    "Localization=Korean,English",
                    "PreviewRunLayerRouteSideEffects=unchanged"
                });
        });
    }

    private static CaptureResult CaptureP269PropertyPersistenceFeedback(string outputPath)
    {
        OpenVisionLanguageService.SetLanguage(OpenVisionLanguage.English, false);
        OpenVisionShellHostView shellHost =
            CreateShellHost("Smoke_P269PropertyPersistenceFeedback");
        List<OpenVisionNativeToolPropertySavedEventArgs> events = new();
        EventHandler<OpenVisionNativeToolPropertySavedEventArgs> savedHandler =
            (_, args) => events.Add(args);
        OpenVisionNativeToolPropertySessionStore.PropertySaved += savedHandler;
        try
        {
            return CaptureWindowWithContent(shellHost, outputPath, 1600, 900, () =>
            {
                shellHost.SelectToolForTest(VISION_MENU.Blob);
                Pump(24);
                System.Windows.Controls.WpfPropertyGrid.PropertyGrid grid =
                    GetActiveFloatingPropertyGrid("P269 persistence feedback");
                BlobProperty property = grid.SelectedObject as BlobProperty
                    ?? throw new InvalidOperationException(
                        "P269 Blob PropertyGrid was not available.");
                Window toolWindow =
                    GetActiveFloatingToolWindow("P269 persistence feedback");
                OpenVisionLanguageService.SetLanguage(
                    OpenVisionLanguage.English,
                    false);
                Pump(12);
                TextBlock statusText = FindVisualChildren<TextBlock>(toolWindow)
                    .FirstOrDefault(item => string.Equals(
                            item.Name,
                            "txtStatus",
                            StringComparison.Ordinal))
                    ?? throw new InvalidOperationException(
                        "P269 Tool status text was not available.");

                int previewRunsBefore = shellHost.NativePreviewRunCount;
                int layerCountBefore = shellHost.LayerDocumentCount;
                string activeLayerBefore = shellHost.ActiveHostLayerTitle;
                string inputRouteBefore =
                    shellHost.ActiveNativeRouteInputLayerNameForTest;
                string outputRouteBefore =
                    shellHost.ActiveNativeRouteOutputLayerNameForTest;

                OpenVisionNativeToolPropertySessionStore.FailNextSaveForTest = true;
                OpenVisionNativeToolPropertySessionStore.Save("Blob", property);
                Pump(12);
                OpenVisionNativeToolPropertySavedEventArgs failure =
                    events.LastOrDefault()
                    ?? throw new InvalidOperationException(
                        "P269 did not publish the failed persistence result.");
                if (failure.Succeeded
                    || failure.RecoveredFromFailure
                    || !shellHost.ActiveNativeStatusText.Contains(
                        "remain in memory",
                        StringComparison.OrdinalIgnoreCase)
                    || !shellHost.ActiveNativeStatusText.Contains(
                        "lost after reopening",
                        StringComparison.OrdinalIgnoreCase))
                {
                    throw new InvalidOperationException(
                        "P269 English failure feedback did not describe memory-only state and reopen loss. Status='"
                        + shellHost.ActiveNativeStatusText
                        + "'.");
                }
                if (!string.Equals(
                        statusText.ToolTip?.ToString(),
                        shellHost.ActiveNativeStatusText,
                        StringComparison.Ordinal)
                    || !string.Equals(
                        System.Windows.Automation.AutomationProperties.GetHelpText(
                            statusText),
                        shellHost.ActiveNativeStatusText,
                        StringComparison.Ordinal))
                {
                    throw new InvalidOperationException(
                        "P269 full failure message was not available through tooltip and accessibility help.");
                }

                OpenVisionNativeToolPropertySessionStore.Save("Blob", property);
                Pump(12);
                OpenVisionNativeToolPropertySavedEventArgs recovery =
                    events.LastOrDefault()
                    ?? throw new InvalidOperationException(
                        "P269 did not publish the recovery result.");
                if (!recovery.Succeeded
                    || !recovery.RecoveredFromFailure
                    || !shellHost.ActiveNativeStatusText.Contains(
                        "recovered",
                        StringComparison.OrdinalIgnoreCase)
                    || !shellHost.ActiveNativeStatusText.Contains(
                        "persisted",
                        StringComparison.OrdinalIgnoreCase))
                {
                    throw new InvalidOperationException(
                        "P269 recovery feedback was not explicit. Status='"
                        + shellHost.ActiveNativeStatusText
                        + "'.");
                }

                string recoveryStatus = shellHost.ActiveNativeStatusText;
                OpenVisionNativeToolPropertySessionStore.Save("Blob", property);
                Pump(12);
                OpenVisionNativeToolPropertySavedEventArgs ordinarySuccess =
                    events.LastOrDefault()
                    ?? throw new InvalidOperationException(
                        "P269 did not publish the ordinary success result.");
                if (!ordinarySuccess.Succeeded
                    || ordinarySuccess.RecoveredFromFailure
                    || !string.Equals(
                        shellHost.ActiveNativeStatusText,
                        recoveryStatus,
                        StringComparison.Ordinal))
                {
                    throw new InvalidOperationException(
                        "P269 ordinary saves should not repeatedly replace the Tool status.");
                }

                OpenVisionLanguageService.SetLanguage(
                    OpenVisionLanguage.Korean,
                    false);
                OpenVisionNativeToolPropertySessionStore.FailNextSaveForTest = true;
                OpenVisionNativeToolPropertySessionStore.Save("Blob", property);
                Pump(12);
                if (!shellHost.ActiveNativeStatusText.Contains(
                        "메모리에만 유지",
                        StringComparison.Ordinal)
                    || !shellHost.ActiveNativeStatusText.Contains(
                        "재개방 후 손실",
                        StringComparison.Ordinal))
                {
                    throw new InvalidOperationException(
                        "P269 Korean failure feedback was not explicit. Status='"
                        + shellHost.ActiveNativeStatusText
                        + "'.");
                }

                if (shellHost.NativePreviewRunCount != previewRunsBefore
                    || shellHost.LayerDocumentCount != layerCountBefore
                    || !string.Equals(
                        shellHost.ActiveHostLayerTitle,
                        activeLayerBefore,
                        StringComparison.Ordinal)
                    || !string.Equals(
                        shellHost.ActiveNativeRouteInputLayerNameForTest,
                        inputRouteBefore,
                        StringComparison.Ordinal)
                    || !string.Equals(
                        shellHost.ActiveNativeRouteOutputLayerNameForTest,
                        outputRouteBefore,
                        StringComparison.Ordinal))
                {
                    throw new InvalidOperationException(
                        "P269 persistence feedback changed Preview/Run, layers, active layer, or routes.");
                }

                string reportDirectory =
                    Path.GetDirectoryName(outputPath) ?? ".";
                File.WriteAllLines(
                    Path.Combine(
                        reportDirectory,
                        "p269-property-persistence-feedback-smoke.txt"),
                    new[]
                    {
                        "Status=OK",
                        "FailureResult=published",
                        "InMemoryValue=retained",
                        "ReopenLossRisk=visible",
                        "RecoveryResult=published-once",
                        "OrdinarySuccessStatusNoise=none",
                        "FullMessage=tooltip,accessibility-help",
                        "Localization=Korean,English",
                        "PreviewRunLayerRouteSideEffects=unchanged"
                    });
            });
        }
        finally
        {
            OpenVisionNativeToolPropertySessionStore.FailNextSaveForTest = false;
            OpenVisionNativeToolPropertySessionStore.PropertySaved -= savedHandler;
        }
    }

    private static void RaisePropertyGridRowMouseSelection(
        System.Windows.Controls.WpfPropertyGrid.PropertyGrid propertyGrid,
        string propertyName)
    {
        FrameworkElement rowElement = FindVisualChildren<FrameworkElement>(propertyGrid)
            .FirstOrDefault(element => string.Equals(
                ResolvePropertyGridPropertyName(element.DataContext),
                propertyName,
                StringComparison.Ordinal))
            ?? throw new InvalidOperationException(
                "P257 could not find a rendered PropertyGrid row for mouse selection: " + propertyName);
        MouseButtonEventArgs args = new(
            Mouse.PrimaryDevice,
            Environment.TickCount,
            MouseButton.Left)
        {
            RoutedEvent = Mouse.PreviewMouseDownEvent,
            Source = rowElement
        };
        rowElement.RaiseEvent(args);
    }

    private static CaptureResult CaptureLineSignalProfile(string outputPath)
    {
        AssertLineSignalDirectionMatrix();
        OpenVisionLanguageService.SetLanguage(OpenVisionLanguage.Korean, false);
        OpenVisionShellHostView shellHost = CreateShellHost("Smoke_LineSignalProfile", seedMainLayer: false);
        string goodPath = Path.Combine(
            Environment.CurrentDirectory,
            "docs",
            "samples",
            "public",
            "Line_Pins_Synthetic_OK.png");
        string badPath = Path.Combine(
            Environment.CurrentDirectory,
            "docs",
            "samples",
            "public",
            "Line_Pins_Synthetic_WidePin_NG.png");
        if (!File.Exists(goodPath) || !File.Exists(badPath))
        {
            throw new FileNotFoundException("Public Line signal Good/Bad pair was not found.");
        }

        using (Bitmap goodBitmap = new(goodPath))
        {
            shellHost.SetMainLayerImageForTest(goodBitmap);
        }

        return CaptureWindowWithContent(shellHost, outputPath, 1600, 900, () =>
        {
            shellHost.SelectToolForTest(VISION_MENU.Line);
            Pump(16);
            SelectComboBoxItemText(FindFloatingComboBox("cbInputLayer"), "Main", "Line signal owned input");
            ConfigurePinsVerticalDistanceLine(shellHost, "Line A", "X_LTOR");
            ConfigurePinsVerticalDistanceLine(shellHost, "Line B", "X_RTOL");
            shellHost.SetActiveLineSettingForTest("Line A");
            shellHost.SetActiveLinePurposeForTest("Measure");
            Pump(12);

            LineToolWpfView lineSignalView = FindVisualChildren<LineToolWpfView>(shellHost.ActiveNativeDocumentForTest!.View).Prepend(shellHost.ActiveNativeDocumentForTest!.View as LineToolWpfView).OfType<LineToolWpfView>().Single();
            Dictionary<string, string?> Snapshot(LineGaugeProperty property) => new[] { "NAME", "CvROI", "PIXELPERMM", "PRJ_DIR", "PRJ_PORALITY", "VER_PRJ_DIR", "USE_THRESHOLD", "USE_ADAPTIVE_THRESHOLD", "CONTRAST", "THICKNESS", "SAMPLING_STEP", "POINT_RANGE", "USE_MANUAL_ANGLE", "MANUAL_ANGLE_VALUE" }
                .ToDictionary(name => name, name => property.GetType().GetProperty(name)?.GetValue(property)?.ToString());
            File.WriteAllText(Path.ChangeExtension(outputPath, ".line-input-diagnostic.json"), JsonSerializer.Serialize(new
            { Input = shellHost.ActiveNativeRouteInputLayerNameForTest, Output = shellHost.ActiveNativeRouteOutputLayerNameForTest,
                LineA = Snapshot(lineSignalView.CreateLineAProperty()), LineB = Snapshot(lineSignalView.CreateLineBProperty()),
                StepKeys = shellHost.Workbench.Tool.CurrentStep?.Parameters.Keys, GoodSource = goodPath, GoodSourceSha256 = Convert.ToHexString(SHA256.HashData(File.ReadAllBytes(goodPath))) }, new JsonSerializerOptions { WriteIndented = true }));
            shellHost.RunActiveNativePreviewForTest();
            Pump(24);
            AssertLineSignalMeasurementReview(shellHost, "Line signal Good", 0.20, 0.25);
            string goodReview = shellHost.ActiveNativeResultReviewText;
            string goodEvidenceId = AssertLineSignalEvidence(
                shellHost,
                outputPath,
                "good",
                expectedSourceHash: null);
            shellHost.OpenActiveLineSignalInspectorForTest();
            Pump(4);
            string goodSourceHash = shellHost.ActiveLineSignalInspectorSourceSha256ForTest;
            string goodSelectedPoint = shellHost.GetActiveLineSignalInspectorAttributeForTest("SelectedImagePoint");
            DependencyObject goodSignalRoot = (DependencyObject?)Application.Current.Windows
                .OfType<Window>()
                .FirstOrDefault(item => item.IsVisible
                    && item.GetType().Name == "OpenVisionFloatingToolWindow"
                    && FindVisualChildren<LineToolWpfView>(item).Any())
                ?? shellHost;
            SaveVisibleAutomationElementPng(
                goodSignalRoot,
                "LineSignalInspectorOverlay",
                outputPath,
                "line-signal-good.png");
            using (Bitmap goodOutput = shellHost.GetLayerImageCloneForTest("Line_1"))
            {
                ScreenshotBitmapAssertions.AssertBitmapPresent(goodOutput, "Line signal Good output");
                ScreenshotBitmapAssertions.SaveDiagnosticBitmap(outputPath, "line-signal-good-preview.png", goodOutput);
            }

            VisionPipelineStep goodStep = VisionPipelineStepEditService.CopyStep(shellHost.Workbench.Tool.CurrentStep)
                ?? throw new InvalidOperationException("Line signal Good did not create a LineDistance Step.");
            int previewCountBeforeReview = shellHost.NativePreviewRunCount;
            int layerCountBeforeReview = shellHost.LayerDocumentCount;
            string activeLayerBeforeReview = shellHost.ActiveHostLayerTitle;
            string inputRouteBeforeReview = shellHost.ActiveNativeRouteInputLayerNameForTest;
            string outputRouteBeforeReview = shellHost.ActiveNativeRouteOutputLayerNameForTest;
            shellHost.CloseActiveLineSignalInspectorForTest();
            Pump(4);
            if (!shellHost.ActiveLineSignalInspectorHasEvidenceForTest
                || shellHost.ActiveLineSignalInspectorOverlayVisibleForTest)
            {
                throw new InvalidOperationException("Closing Line Signal Inspector changed or failed to hide current evidence.");
            }

            if (!shellHost.ExerciseActiveLineSignalInspectorNavigationForTest())
            {
                throw new InvalidOperationException("Line Signal Inspector zoom/pan/reset navigation did not complete.");
            }

            shellHost.OpenActiveLineSignalInspectorForTest();
            Pump(4);
            AssertLineSignalReviewSideEffectsUnchanged(
                shellHost,
                previewCountBeforeReview,
                layerCountBeforeReview,
                activeLayerBeforeReview,
                inputRouteBeforeReview,
                outputRouteBeforeReview,
                "Line signal Good review controls");

            shellHost.CloseActiveLineSignalInspectorForTest();
            int previewCountBeforeBadLoad = shellHost.NativePreviewRunCount;
            using (Bitmap badBitmap = new(badPath))
            {
                shellHost.SetMainLayerImageForTest(badBitmap);
            }

            Pump(12);
            if (shellHost.ActiveLineSignalInspectorHasEvidenceForTest
                || shellHost.ActiveLineSignalInspectorOverlayVisibleForTest
                || shellHost.HasNativePreviewResult
                || shellHost.NativePreviewRunCount != previewCountBeforeBadLoad)
            {
                throw new InvalidOperationException(
                    "Replacing the Main workspace image retained stale Line evidence/result state or ran Preview implicitly.");
            }

            shellHost.RunActiveNativePreviewForTest();
            Pump(24);
            AssertLineSignalMeasurementReview(shellHost, "Line signal Bad", 0.09, 0.13);
            string badReview = shellHost.ActiveNativeResultReviewText;
            string badEvidenceId = AssertLineSignalEvidence(
                shellHost,
                outputPath,
                "bad",
                expectedSourceHash: null);
            shellHost.OpenActiveLineSignalInspectorForTest();
            Pump(4);
            string badSourceHash = shellHost.ActiveLineSignalInspectorSourceSha256ForTest;
            string badSelectedPoint = shellHost.GetActiveLineSignalInspectorAttributeForTest("SelectedImagePoint");
            if (string.Equals(goodEvidenceId, badEvidenceId, StringComparison.Ordinal)
                || string.Equals(goodSourceHash, badSourceHash, StringComparison.Ordinal))
            {
                throw new InvalidOperationException("Line signal Good/Bad evidence did not retain distinct source identities.");
            }

            DependencyObject badSignalRoot = (DependencyObject?)Application.Current.Windows
                .OfType<Window>()
                .FirstOrDefault(item => item.IsVisible
                    && item.GetType().Name == "OpenVisionFloatingToolWindow"
                    && FindVisualChildren<LineToolWpfView>(item).Any())
                ?? shellHost;
            SaveVisibleAutomationElementPng(
                badSignalRoot,
                "LineSignalInspectorOverlay",
                outputPath,
                "line-signal-bad.png");
            using (Bitmap badOutput = shellHost.GetLayerImageCloneForTest("Line_1"))
            {
                ScreenshotBitmapAssertions.AssertBitmapPresent(badOutput, "Line signal Bad output");
                ScreenshotBitmapAssertions.SaveDiagnosticBitmap(outputPath, "line-signal-bad-preview.png", badOutput);
            }

            VisionPipelineStep badStep = VisionPipelineStepEditService.CopyStep(shellHost.Workbench.Tool.CurrentStep)
                ?? throw new InvalidOperationException("Line signal Bad did not create a LineDistance Step.");
            AssertLineSignalParametersUnchanged(goodStep, badStep);
            int beforeAddRuns = shellHost.NativePreviewRunCount;
            VisionPipelineStep addedStep = shellHost.AddActiveNativePipelineStepForTest()
                ?? throw new InvalidOperationException("Line signal Bad did not create a LineDistance Step.");
            AssertLineSignalParametersUnchanged(badStep, addedStep);
            if (shellHost.NativePreviewRunCount != beforeAddRuns) throw new InvalidOperationException("Adding the reviewed Line step executed implicitly.");
            string? reportDirectory = Path.GetDirectoryName(outputPath);
            File.WriteAllLines(
                Path.Combine(
                    string.IsNullOrWhiteSpace(reportDirectory) ? "." : reportDirectory,
                    "line-signal-replay.txt"),
                new[]
                {
                    "Status=OK",
                    "GoodReview=" + goodReview,
                    "GoodEvidenceId=" + goodEvidenceId,
                    "GoodSourceSha256=" + goodSourceHash,
                    "GoodSelectedPoint=" + goodSelectedPoint,
                    "BadReview=" + badReview,
                    "BadEvidenceId=" + badEvidenceId,
                    "BadSourceSha256=" + badSourceHash,
                    "BadSelectedPoint=" + badSelectedPoint,
                    "FrozenToolType=" + goodStep.ToolType,
                    "FrozenParameters=unchanged",
                    "DirectionMatrix=X_LTOR,X_RTOL,Y_TTOB,Y_BTOT",
                    "WorkspaceInputReplacement=cleared stale evidence without Preview",
                    "ReviewSideEffects=unchanged"
                });
        });
    }

    private static void AssertLineSignalDirectionMatrix()
    {
        using CvMat source = CvMat.Zeros(100, 120, OpenCvSharp.MatType.CV_8UC1);
        Cv.Rectangle(
            source,
            new OpenCvSharp.Rect(30, 24, 50, 52),
            new OpenCvSharp.Scalar(220),
            -1);
        foreach (OpenVisionLab.Core.FormulaUtil.PROJECTION_DIR direction in new[]
        {
            OpenVisionLab.Core.FormulaUtil.PROJECTION_DIR.X_LTOR,
            OpenVisionLab.Core.FormulaUtil.PROJECTION_DIR.X_RTOL,
            OpenVisionLab.Core.FormulaUtil.PROJECTION_DIR.Y_TTOB,
            OpenVisionLab.Core.FormulaUtil.PROJECTION_DIR.Y_BTOT
        })
        {
            LineGaugeProperty property = new("LineSignal_" + direction)
            {
                USE_ROI = true,
                CvROI = new OpenCvSharp.Rect(0, 0, source.Width, source.Height),
                PRJ_DIR = direction,
                PRJ_PORALITY = OpenVisionLab.Core.FormulaUtil.PROJECTION_POLARITY.BTOW,
                CONTRAST = 18,
                THICKNESS = 2,
                SAMPLING_STEP = 10
            };
            LineGaugeTool tool = new();
            tool.SetProperty(property);
            VisionToolResult result = tool.Execute(source);
            try
            {
                string failureReason = result?.Success == true
                    ? string.Empty
                    : result?.Message ?? "LineGauge execution failed.";
                OpenVisionNativeLineSignalProfile? profile = null;
                bool created = result?.Success == true
                    && OpenVisionNativeLineSignalEvidenceFactory.TryCreate(
                        source,
                        property,
                        tool.resultList,
                        direction.ToString(),
                        out profile,
                        out failureReason);
                if (!created)
                {
                    throw new InvalidOperationException(
                        "Line signal direction replay failed for "
                        + direction
                        + ". "
                        + failureReason);
                }

                using CvMat evidenceImage = source.Clone();
                OpenVisionNativeToolPreviewOverlayRenderer.DrawLineSignalDiagnostic(evidenceImage, profile!);
                VisionToolSignalEvidence evidence = profile!.CreateEvidence(source, evidenceImage, "Matrix");
                if (evidence.Series.Count != 2
                    || !evidence.Attributes.TryGetValue("RuntimeCorrespondence", out string? correspondence)
                    || !string.Equals(correspondence, "Matched LineGauge first-stable edge", StringComparison.Ordinal))
                {
                    throw new InvalidOperationException(
                        "Line signal direction replay evidence was incomplete for " + direction + ".");
                }
            }
            finally
            {
                result?.ResultImage?.Dispose();
            }
        }
    }

    private static string AssertLineSignalEvidence(
        OpenVisionShellHostView shellHost,
        string outputPath,
        string role,
        string? expectedSourceHash)
    {
        if (!shellHost.ActiveLineSignalInspectorHasEvidenceForTest
            || shellHost.ActiveLineSignalInspectorOverlayVisibleForTest
            || !shellHost.ActiveLineSignalEvidenceCueVisibleForTest
            || shellHost.ActiveLineSignalInspectorSeriesCountForTest != 2
            || shellHost.ActiveLineSignalInspectorMarkerCountForTest < 2)
        {
            throw new InvalidOperationException(
                "Line signal " + role + " did not retain its parameter view, show the transient cue, and publish the required signal evidence.");
        }

        string evidenceId = shellHost.ActiveLineSignalInspectorEvidenceIdForTest;
        string sourceHash = shellHost.ActiveLineSignalInspectorSourceSha256ForTest;
        if (evidenceId.Length != 64
            || sourceHash.Length != 64
            || (!string.IsNullOrWhiteSpace(expectedSourceHash)
                && !string.Equals(sourceHash, expectedSourceHash, StringComparison.Ordinal)))
        {
            throw new InvalidOperationException("Line signal " + role + " did not retain stable SHA-256 evidence identity.");
        }

        string selectedPoint = shellHost.GetActiveLineSignalInspectorAttributeForTest("SelectedImagePoint");
        string scanStart = shellHost.GetActiveLineSignalInspectorAttributeForTest("ScanStart");
        string scanEnd = shellHost.GetActiveLineSignalInspectorAttributeForTest("ScanEnd");
        string correspondence = shellHost.GetActiveLineSignalInspectorAttributeForTest("RuntimeCorrespondence");
        if (!Regex.IsMatch(selectedPoint, @"^\(\d+,\d+\)$")
            || !Regex.IsMatch(scanStart, @"^\(\d+,\d+\)$")
            || !Regex.IsMatch(scanEnd, @"^\(\d+,\d+\)$")
            || !string.Equals(correspondence, "Matched LineGauge first-stable edge", StringComparison.Ordinal))
        {
            throw new InvalidOperationException(
                "Line signal " + role + " did not retain exact image coordinates and runtime correspondence.");
        }

        string? directory = Path.GetDirectoryName(outputPath);
        string tsvPath = Path.Combine(
            string.IsNullOrWhiteSpace(directory) ? "." : directory,
            "line-signal-" + role + ".tsv");
        shellHost.ExportActiveLineSignalEvidenceForTest(tsvPath);
        string tsv = File.ReadAllText(tsvPath);
        if (!tsv.Contains("Intensity (GV)", StringComparison.Ordinal)
            || !tsv.Contains("Signed edge response (\u0394GV)", StringComparison.Ordinal)
            || !tsv.Contains("#\tAttribute.SelectedImagePoint\t", StringComparison.Ordinal)
            || !tsv.Contains("#\tAttribute.RuntimeCorrespondence\tMatched LineGauge first-stable edge", StringComparison.Ordinal)
            || !TsvContainsPositiveAndNegativeResponse(tsv))
        {
            throw new InvalidOperationException("Line signal " + role + " TSV evidence is incomplete.");
        }

        return evidenceId;
    }

    private static void AssertLineSignalMeasurementReview(
        OpenVisionShellHostView shellHost,
        string name,
        double minimumMm,
        double maximumMm)
    {
        string review = shellHost.ActiveNativeResultReviewText ?? string.Empty;
        Match match = Regex.Match(
            review,
            @"([-+]?\d+(?:\.\d+)?)\s*mm",
            RegexOptions.CultureInvariant | RegexOptions.IgnoreCase);
        if (!match.Success
            || !double.TryParse(match.Groups[1].Value, NumberStyles.Float, CultureInfo.InvariantCulture, out double value)
            || value < minimumMm
            || value > maximumMm)
        {
            throw new InvalidOperationException(
                name
                + " did not retain a successful measurement in range "
                + minimumMm.ToString(CultureInfo.InvariantCulture)
                + ".."
                + maximumMm.ToString(CultureInfo.InvariantCulture)
                + " mm. Review='"
                + review
                + "'.");
        }
    }

    private static bool TsvContainsPositiveAndNegativeResponse(string tsv)
    {
        bool hasPositive = false;
        bool hasNegative = false;
        foreach (string line in (tsv ?? string.Empty).Split(new[] { "\r\n", "\n" }, StringSplitOptions.None))
        {
            if (string.IsNullOrWhiteSpace(line) || line[0] == '#')
            {
                continue;
            }

            string[] cells = line.Split('\t');
            if (cells.Length < 3
                || !double.TryParse(cells[2], NumberStyles.Float, CultureInfo.InvariantCulture, out double response))
            {
                continue;
            }

            hasPositive |= response > 0;
            hasNegative |= response < 0;
        }

        return hasPositive && hasNegative;
    }

    private static void AssertLineSignalReviewSideEffectsUnchanged(
        OpenVisionShellHostView shellHost,
        int previewCount,
        int layerCount,
        string activeLayer,
        string inputRoute,
        string outputRoute,
        string name)
    {
        if (shellHost.NativePreviewRunCount != previewCount
            || shellHost.LayerDocumentCount != layerCount
            || !string.Equals(shellHost.ActiveHostLayerTitle, activeLayer, StringComparison.Ordinal)
            || !string.Equals(shellHost.ActiveNativeRouteInputLayerNameForTest, inputRoute, StringComparison.Ordinal)
            || !string.Equals(shellHost.ActiveNativeRouteOutputLayerNameForTest, outputRoute, StringComparison.Ordinal))
        {
            throw new InvalidOperationException(name + " changed Preview count, layers, active layer, or routing.");
        }
    }

    private static void AssertLineSignalParametersUnchanged(VisionPipelineStep good, VisionPipelineStep bad)
    {
        string[] requiredKeys =
        {
            "LeftCvROI",
            "RightCvROI",
            "LeftPRJ_DIR",
            "RightPRJ_DIR",
            "LeftPRJ_PORALITY",
            "RightPRJ_PORALITY",
            "LeftCONTRAST",
            "RightCONTRAST",
            "LeftTHICKNESS",
            "RightTHICKNESS",
            "LeftSAMPLING_STEP",
            "RightSAMPLING_STEP",
            "LeftPOINT_RANGE",
            "RightPOINT_RANGE",
            "LeftUSE_MANUAL_ANGLE",
            "RightUSE_MANUAL_ANGLE",
            "LeftMANUAL_ANGLE_VALUE",
            "RightMANUAL_ANGLE_VALUE"
        };
        if (!string.Equals(good.ToolType, "LineDistance", StringComparison.Ordinal)
            || !string.Equals(bad.ToolType, "LineDistance", StringComparison.Ordinal))
        {
            throw new InvalidOperationException("Line signal Good/Bad replay did not retain LineDistance.");
        }

        foreach (string key in requiredKeys)
        {
            if (!good.Parameters.TryGetValue(key, out string? goodValue)
                || !bad.Parameters.TryGetValue(key, out string? badValue)
                || !string.Equals(goodValue, badValue, StringComparison.Ordinal))
            {
                throw new InvalidOperationException("Line signal Good/Bad replay changed parameter '" + key + "'.");
            }
        }
    }

    private static void ConfigurePinsVerticalDistanceLine(OpenVisionShellHostView shellHost, string setting, string projectionDirection)
    {
        void SetNumber(string propertyName, double value)
        {
            System.Windows.Controls.WpfPropertyGrid.PropertyGrid grid = GetActiveFloatingPropertyGrid(setting + " numeric input");
            if (!grid.FocusProperty(propertyName)) throw new InvalidOperationException(setting + ": numeric row not found: " + propertyName);
            Pump(4);
            SetFloatingPropertyGridTextBoxTextWithoutCommit(setting + " numeric input", propertyName, value.ToString(CultureInfo.InvariantCulture));
            grid.CommitPendingEdit();
            Pump(8);
            AssertFloatingSelectedObjectNumericPropertyWithin(setting + " numeric input", propertyName, value, 0.001D);
        }
        shellHost.SetActiveLineSettingForTest(setting);
        Pump(4);
        shellHost.SetActiveSelectedLineRoiForTest(430, 170, 125, 145);
        Pump(4);
        shellHost.ConfigureActiveSelectedLineForTest(projectionDirection, "WTOB", "X_RTOL");
        Pump(4);

        SetFloatingPropertyGridPropertyValue(setting + " threshold off", "USE_THRESHOLD", false);
        SetFloatingPropertyGridPropertyValue(setting + " adaptive threshold off", "USE_ADAPTIVE_THRESHOLD", false);
        SetNumber("CONTRAST", 18D);
        SetNumber("THICKNESS", 2D);
        SetNumber("SAMPLING_STEP", 6D);
        SetFloatingPropertyGridPropertyValue(setting + " point range", "POINT_RANGE", 8);
        SetFloatingPropertyGridPropertyValue(setting + " manual angle on", "USE_MANUAL_ANGLE", true);
        Thread.Sleep(180);
        Pump(30);
        SetNumber("MANUAL_ANGLE_VALUE", 89D);
        SetFloatingPropertyGridPropertyValue(setting + " show edge", "SHOW_EDGE", true);
        SetFloatingPropertyGridPropertyValue(setting + " show vertical line", "SHOW_VERTICAL_LINE", true);
        SetFloatingPropertyGridPropertyValue(setting + " show fit line", "SHOW_FITLINE", true);
        Pump(8);
    }

    private static CaptureResult CaptureToolOpenPerf(string outputPath)
    {
        OpenVisionLanguageService.SetLanguage(OpenVisionLanguage.Korean, false);
        OpenVisionShellHostView shellHost = CreateShellHost("Smoke_WpfToolOpenPerf");
        List<string> lines = new()
        {
            "Pass|Tool|SelectMs|ReadyMs|Document|CacheCount|PrewarmCount|PrewarmCompleted|PrewarmElapsedMs|ManagedMemoryMB|WorkingSetMB"
        };

        return CaptureWindowWithContent(shellHost, outputPath, 1600, 900, () =>
        {
            Pump(24);
            WaitForNativeToolPrewarm(shellHost, lines);

            // Measure menu switching only. Preview execution is intentionally excluded
            // so tool-window and property-grid startup regressions are visible.
            shellHost.SelectToolForTest(VISION_MENU.Pipeline);
            Pump(12);

            foreach (VISION_MENU menu in GetToolOpenPerfMenus())
            {
                MeasureToolOpen(shellHost, menu, "Cold", lines);
            }

            foreach (VISION_MENU menu in GetToolOpenPerfMenus())
            {
                MeasureToolOpen(shellHost, menu, "Warm", lines);
            }

            WriteToolOpenPerfReport(outputPath, lines);
        });
    }

    private static CaptureResult CaptureToolOpenFastClickPerf(string outputPath)
    {
        OpenVisionLanguageService.SetLanguage(OpenVisionLanguage.Korean, false);
        OpenVisionShellHostView shellHost = CreateShellHost("Smoke_WpfToolOpenFastClickPerf");
