    private static CaptureResult CaptureShellHostLineMeasureTool(string outputPath)
    {
        OpenVisionLanguageService.SetLanguage(OpenVisionLanguage.Korean, false);
        OpenVisionShellHostView shellHost = CreateShellHost("Smoke_WpfShellHostLineMeasure");
        OpenVisionLanguageService.SetLanguage(OpenVisionLanguage.Korean, false);
        using Bitmap lineBitmap = CreateLineMeasureSmokeBitmap();
        shellHost.SetMainLayerImageForTest(lineBitmap);
        void AssertLineResultEvidence(string name, params string[] requiredTokens)
        {
            string review = shellHost.ActiveNativeResultReviewText ?? string.Empty;
            string missing = requiredTokens.FirstOrDefault(token => !review.Contains(token, StringComparison.Ordinal));
            if (missing != null) { throw new InvalidOperationException(name + " retained SDK result evidence is missing '" + missing + "'. Text='" + review + "'."); }
        }
        void AssertLineWorkbenchCard(string name, params string[] metricNames)
        {
            OpenVisionWorkbenchToolViewModel model = shellHost.Workbench.Tool;
            if (!model.HasResult || model.IsResultPrevious || model.ResultKind != "Done" || model.ResultMetrics.Count is < 1 or > 6)
                throw new InvalidOperationException(name + " must show a current result with no acceptance judgment. Kind=" + model.ResultKind + "; status=" + shellHost.ActiveNativeStatusText + "; review=" + shellHost.ActiveNativeResultReviewText);
            List<string> visibleTexts = FindActiveToolVisualRoots().SelectMany(FindVisualChildren<TextBlock>)
                .Where(text => text.IsVisible).Select(text => text.Text).ToList();
            if (!visibleTexts.Contains("완료") || !metricNames.All(metric => model.ResultMetrics.Any(item => item.Key == metric) && visibleTexts.Contains(metric)))
                throw new InvalidOperationException(name + " Workbench result card is missing its visible status or metric bindings. Text='" + string.Join(" | ", visibleTexts) + "'.");
            foreach (KeyValuePair<string, string> metric in model.ResultMetrics.Where(item => metricNames.Contains(item.Key)))
                if (!visibleTexts.Contains(metric.Value)) { throw new InvalidOperationException(name + " visible metric value is missing: " + metric.Key + "=" + metric.Value); }
        }

        return CaptureWindowWithContent(shellHost, outputPath, 1600, 900, () =>
        {
            shellHost.SelectToolForTest(VISION_MENU.Line);
            Pump(16);
            AssertToolHeaderLearnOpensTopic(shellHost, 8, "Line header Learn");
            SelectComboBoxItemText(FindFloatingComboBox("cbInputLayer"), "Main", "Line measurement owned input");
            if (shellHost.ActiveNativeRouteInputLayerNameForTest != "Main" || shellHost.ActiveNativeRouteOutputLayerNameForTest != "Line_1")
                throw new InvalidOperationException("Line measurement fixture must select its owned Main image and retain the V2 test output Line_1.");
            AssertActiveToolTextsVisible("Line verification guide initial", "Line 검증", "미리보기 전", "대비", "다음:");
            AssertActiveToolTextsVisible("Line purpose controls", "측정 목적", "라인", "에지", "거리 측정", "교차점");
            AssertFloatingPropertyGridRowsRendered("Line property grid");
            AssertFloatingPropertyGridMinimumSize("Line property grid", 600D, 380D);
            System.Windows.Controls.WpfPropertyGrid.PropertyGrid lineGrid =
                GetActiveFloatingPropertyGrid("Line measurement compatibility baseline");
            LineGaugeProperty lineProperty = lineGrid.SelectedObject as LineGaugeProperty
                ?? throw new InvalidOperationException("Line measurement property model was not available.");
            lineProperty.USE_AVERAGE_FILTER = false;
            new OpenVisionLab.Common.PropertyGridEventBinder(null)
                .ApplyVisibilityRules(lineGrid);
            Pump(8);
            int beforeLineVisibilityToggleRuns = shellHost.NativePreviewRunCount;
            AssertFloatingPropertyBrowsable("Line point range before manual angle", "POINT_RANGE", true);
            AssertFloatingPropertyBrowsable("Line manual angle before enable", "MANUAL_ANGLE_VALUE", false);
            SetFloatingPropertyGridPropertyValue("Line enable manual angle", "USE_MANUAL_ANGLE", true);
            Thread.Sleep(180);
            Pump(30);
            AssertFloatingPropertyBrowsable("Line point range after manual angle", "POINT_RANGE", false);
            AssertFloatingPropertyBrowsable("Line manual angle after enable", "MANUAL_ANGLE_VALUE", true);
            if (shellHost.NativePreviewRunCount != beforeLineVisibilityToggleRuns)
            {
                throw new InvalidOperationException("Line USE_MANUAL_ANGLE should only update angle rows, not run auto-preview.");
            }

            SetFloatingPropertyGridPropertyValue("Line disable manual angle", "USE_MANUAL_ANGLE", false);
            Thread.Sleep(180);
            Pump(30);
            AssertFloatingPropertyBrowsable("Line point range after manual angle disable", "POINT_RANGE", true);
            AssertFloatingPropertyBrowsable("Line manual angle after disable", "MANUAL_ANGLE_VALUE", false);
            if (shellHost.NativePreviewRunCount != beforeLineVisibilityToggleRuns)
            {
                throw new InvalidOperationException("Line USE_MANUAL_ANGLE disable should not run auto-preview.");
            }

            AssertFloatingPropertyBrowsable("Line extend length before enable", "EXTEND_FIT_LINE_VALUE", false);
            SetFloatingPropertyGridPropertyValue("Line enable extend fit line", "USE_EXTEND_FIT_LINE", true);
            Thread.Sleep(180);
            Pump(30);
            AssertFloatingPropertyBrowsable("Line extend length after enable", "EXTEND_FIT_LINE_VALUE", true);
            if (shellHost.NativePreviewRunCount != beforeLineVisibilityToggleRuns)
            {
                throw new InvalidOperationException("Line USE_EXTEND_FIT_LINE should only update fit-line rows, not run auto-preview.");
            }

            SetFloatingPropertyGridPropertyValue("Line disable extend fit line", "USE_EXTEND_FIT_LINE", false);
            Thread.Sleep(180);
            Pump(30);
            AssertFloatingPropertyBrowsable("Line extend length after disable", "EXTEND_FIT_LINE_VALUE", false);
            if (shellHost.NativePreviewRunCount != beforeLineVisibilityToggleRuns)
            {
                throw new InvalidOperationException("Line USE_EXTEND_FIT_LINE disable should not run auto-preview.");
            }

            AssertFloatingPropertyBrowsable("Line inactive average diff hidden", "AVERAGE_Diff", false);
            AssertFloatingPropertyBrowsable("Line inactive average filter type hidden", "AVERAGE_FILTER_TYPE", false);
            AssertLineLegacyPropertiesReadOnly("Line measurement");
            if (shellHost.NativePreviewRunCount != beforeLineVisibilityToggleRuns)
            {
                throw new InvalidOperationException("Inspecting Line compatibility fields must not run auto-preview.");
            }

            AssertFloatingInlinePreviewSlotCount("Line input", 1);
            shellHost.SetActiveLineRoiForTest(92, 64, 120, 272);
            Pump(8);
            shellHost.SetActiveLineSettingForTest("Line B");
            Pump(4);
            shellHost.SetActiveSelectedLineRoiForTest(300, 64, 122, 272);
            Pump(4);
            shellHost.SetActiveLineSettingForTest("Line A");
            Pump(4);
            if (shellHost.ActiveLineInputRoiOverlayCount < 2)
            {
                throw new InvalidOperationException("Line OpenGL input preview did not publish both Line A/B ROI overlays.");
            }

            int beforeAutoPreviewRuns = shellHost.NativePreviewRunCount;
            shellHost.ConfigureActiveSelectedLineThresholdForTest(120, false);
            Thread.Sleep(180);
            Pump(30);
            AssertFloatingInlinePreviewSlotCount("Line input/output", 2);
            if (!shellHost.IsNativeDocumentActive || !shellHost.HasNativePreviewResult)
            {
                throw new InvalidOperationException("Native WPF Line tool did not auto-preview after PropertyGrid threshold changes: " + shellHost.ActiveNativeStatusText);
            }

            if (shellHost.NativePreviewRunCount <= beforeAutoPreviewRuns)
            {
                throw new InvalidOperationException("Native WPF Line PropertyGrid threshold change did not request an auto-preview.");
            }

            if (!shellHost.ActiveNativeDocumentTypeName.Contains("LineToolWpfView", StringComparison.Ordinal))
            {
                throw new InvalidOperationException("Line did not open the WPF Line tool view.");
            }

            using (Bitmap mainLayer = shellHost.GetLayerImageCloneForTest("Main"))
            using (Bitmap lineThresholdLayer = shellHost.GetLayerImageCloneForTest("Line_1"))
            {
                ScreenshotBitmapAssertions.AssertBitmapPresent(lineThresholdLayer, "Line_1 layer after threshold auto-preview");
                ScreenshotBitmapAssertions.AssertBitmapVisiblyDifferent(mainLayer, lineThresholdLayer, "Line auto-preview should show threshold teaching image instead of raw Main");
                ScreenshotBitmapAssertions.AssertBitmapBinaryLike(lineThresholdLayer, "Line_1 threshold teaching output");
                ScreenshotBitmapAssertions.SaveDiagnosticBitmap(outputPath, "line-tool-main.png", mainLayer);
                ScreenshotBitmapAssertions.SaveDiagnosticBitmap(outputPath, "line-tool-threshold-preview.png", lineThresholdLayer);
            }

            shellHost.RunActiveNativePreviewForTest();
            Pump(16);
            AssertActiveFloatingInlinePreviewZoomAnchors("Line inline preview zoom/pan");
            AssertPreviewClickActivatesWorkspaceLayer(
                shellHost,
                "VisionToolOutputPreviewSlot",
                "Line_1",
                "Line output preview click");
            AssertPreviewClickActivatesWorkspaceLayer(
                shellHost,
                "VisionToolInputPreviewSlot",
                "Main",
                "Line input preview click");
            AssertLineResultEvidence("Line Edge", "엣지 /", "라인", "엣지", "길이");
            AssertActiveToolTextsVisible("Line verification guide edge", "Line 검증", "미리보기 OK", "대비", "다음:");
            AssertLineWorkbenchCard("Line Edge", "검출 개수", "에지 점 수");
            VisionPipelineStep singleLineStep = shellHost.AddActiveNativePipelineStepForTest();
            AssertSingleLineGaugePropertyMapperRoundTrip(singleLineStep);
            shellHost.SetActiveLinePurposeForTest("Measure");
            Pump(8);
            shellHost.RunActiveNativePreviewForTest();
            Pump(16);
            AssertLineResultEvidence("Line Measure", "측정 /", "거리", "검출");
            AssertLineWorkbenchCard("Line Measure", "평균 거리", "측정 수");
            if (shellHost.ActiveNativeResultReviewText.Contains("거리 없음", StringComparison.Ordinal) || shellHost.ActiveNativeResultReviewText.Contains("검출 0", StringComparison.Ordinal))
                throw new InvalidOperationException("Line distance evidence must retain a detected distance.");
            AssertActiveToolTextsVisible("Line verification guide measure", "Line 검증", "미리보기 OK", "대비", "다음:");
            shellHost.SetActiveLinePurposeForTest("Intersection");
            Pump(8);
            shellHost.RunActiveNativePreviewForTest();
            Pump(16);
            AssertLineResultEvidence("Line Intersection", "교차 /", "교차", "엣지");
            AssertLineWorkbenchCard("Line Intersection", "검출 개수", "교차점 X", "교차점 Y");
            AssertActiveToolTextsVisible("Line verification guide parallel lines", "Line 검증", "미리보기 NG", "다음:");
            shellHost.SetActiveLinePurposeForTest("Measure");
            Pump(8);
            shellHost.RunActiveNativePreviewForTest();
            Pump(16);
            AssertLineResultEvidence("Line Measure", "측정 /", "거리", "검출");
            AssertLineWorkbenchCard("Line Measure", "평균 거리", "측정 수");
            if (shellHost.ActiveNativeResultReviewText.Contains("거리 없음", StringComparison.Ordinal) || shellHost.ActiveNativeResultReviewText.Contains("검출 0", StringComparison.Ordinal))
                throw new InvalidOperationException("Line distance evidence must retain a detected distance.");

            int stepCount = shellHost.Workbench.Pipeline.Rows.Count;
            if (shellHost.AddActiveNativePipelineStepForTest() != null || shellHost.Workbench.Pipeline.Rows.Count != stepCount)
                throw new InvalidOperationException("Editing a saved Line step must not append a second step.");
            VisionPipelineStep step = shellHost.Workbench.Pipeline.GetStep(shellHost.Workbench.Pipeline.SelectedStepIndex);
            if (step == null
                || !string.Equals(step.ToolType, "LineDistance", StringComparison.Ordinal)
                || !string.Equals(step.InputLayer, "Main", StringComparison.Ordinal)
                || !string.Equals(step.OutputLayer, "Line_1", StringComparison.Ordinal)
                || step.Parameters == null
                || !step.Parameters.ContainsKey("LeftPRJ_DIR")
                || !step.Parameters.ContainsKey("RightPRJ_DIR")
                || !step.Parameters.ContainsKey("LeftCONTRAST")
                || !step.Parameters.ContainsKey("RightCONTRAST")
                || !step.Parameters.TryGetValue("RightCvROI", out string? rightRoi)
                || !rightRoi.Contains("300", StringComparison.Ordinal)
                || !step.Parameters.TryGetValue("LinePurpose", out string? purpose)
                || !string.Equals(purpose, "Measure", StringComparison.Ordinal))
            {
                throw new InvalidOperationException("Line WPF tool did not create a valid LineDistance pipeline step.");
            }

            AssertDockActiveNativeTool(shellHost, "LineToolWpfView", "Docked Line tool layout");
            AssertFloatingPropertyGridMinimumSize("Docked Line property grid", 480D, 160D);
            AssertActiveToolTextsVisible("Docked Line verification guide", "Line 검증", "미리보기 OK", "대비", "다음:");
            AssertActiveToolTextsVisible("Docked Line purpose controls", "측정 목적", "라인", "에지", "거리 측정", "교차점");
            AssertActiveToolNamedElementsDoNotOverlap(
                "Docked Line purpose selector layout",
                "rdoPurposeEdge",
                "rdoPurposeMeasure",
                "rdoPurposeIntersection");
            AssertActiveToolNamedElementsVisibleWithinAncestors(
                "Docked Line purpose controls",
                "rdoPurposeEdge",
                "rdoPurposeMeasure",
                "rdoPurposeIntersection",
                "rdoLineA",
                "rdoLineB",
                "btnEditSelectedRoi");
        });
    }

    private static CaptureResult CaptureShellHostLineIntersectionTool(string outputPath)
    {
        OpenVisionLanguageService.SetLanguage(OpenVisionLanguage.Korean, false);
        OpenVisionShellHostView shellHost = CreateShellHost("Smoke_WpfShellHostLineIntersection");
        OpenVisionLanguageService.SetLanguage(OpenVisionLanguage.Korean, false);
        using Bitmap lineBitmap = CreateLineIntersectionSmokeBitmap();
        shellHost.SetMainLayerImageForTest(lineBitmap);
        return CaptureWindowWithContent(shellHost, outputPath, 1600, 900, () =>
        {
            shellHost.SelectToolForTest(VISION_MENU.Line);
            Pump(16);
            int placementRuns = shellHost.NativePreviewRunCount;
            if (!shellHost.FloatDockedWpfToolWindowForTest()) { throw new InvalidOperationException("Line intersection must float the default docked tool for its legacy preview checks."); }
            Pump(16);
            SelectComboBoxItemText(FindFloatingComboBox("cbInputLayer"), "Main", "Line intersection owned input");
            if (shellHost.NativePreviewRunCount != placementRuns || shellHost.ActiveNativeRouteInputLayerNameForTest != "Main"
                || shellHost.ActiveNativeRouteOutputLayerNameForTest != "Line_1")
                throw new InvalidOperationException("Line intersection placement/input selection must preserve the test route without executing.");
            AssertFloatingInlinePreviewSlotCount("Line intersection input", 1);

            shellHost.SetActiveLineSettingForTest("Line A");
            Pump(4);
            shellHost.SetActiveSelectedLineRoiForTest(42, 268, 190, 74);
            Pump(4);
            shellHost.ConfigureActiveSelectedLineForTest("Y_TTOB", "ALL", "Y_BTOT");
            shellHost.ConfigureActiveSelectedLineThresholdForTest(170, false);
            shellHost.ConfigureActiveSelectedLineDrawForTest(false, false, false, true);
            Pump(4);

            shellHost.SetActiveLineSettingForTest("Line B");
            Pump(4);
            shellHost.SetActiveSelectedLineRoiForTest(306, 44, 86, 142);
            Pump(4);
            shellHost.ConfigureActiveSelectedLineForTest("X_LTOR", "ALL", "X_LTOR");
            shellHost.ConfigureActiveSelectedLineThresholdForTest(170, false);
            shellHost.ConfigureActiveSelectedLineDrawForTest(false, false, false, true);
            Pump(4);

            shellHost.SetActiveLineSettingForTest("Line A");
            Pump(4);
            shellHost.SetActiveLinePurposeForTest("Intersection");
            Pump(8);
            if (shellHost.ActiveLineInputRoiOverlayCount < 2)
            {
                throw new InvalidOperationException("Line intersection OpenGL input preview did not publish both Line A/B ROI overlays.");
            }

            shellHost.RunActiveNativePreviewForTest();
            Pump(24);
            AssertFloatingInlinePreviewSlotCount("Line intersection input/output", 2);

            if (!shellHost.IsNativeDocumentActive || !shellHost.HasNativePreviewResult)
            {
                throw new InvalidOperationException("Native WPF Line intersection tool did not produce a preview result: " + shellHost.ActiveNativeStatusText);
            }

            if (!shellHost.ActiveNativeDocumentTypeName.Contains("LineToolWpfView", StringComparison.Ordinal))
            {
                throw new InvalidOperationException("Line intersection did not open the WPF Line tool view.");
            }

            string intersectionReview = shellHost.ActiveNativeResultReviewText;
            if (!new[] { "교차 /", "교차 예", "점" }.All(token => intersectionReview.Contains(token, StringComparison.Ordinal))
                || intersectionReview.Contains("교차 아니오", StringComparison.Ordinal))
                throw new InvalidOperationException("Line intersection must retain its positive crossing evidence: " + intersectionReview);
            OpenVisionWorkbenchToolViewModel intersectionModel = shellHost.Workbench.Tool;
            if (!intersectionModel.HasResult || intersectionModel.IsResultPrevious || intersectionModel.ResultKind != "Done"
                || intersectionModel.ResultMetrics.Count is < 1 or > 6)
                throw new InvalidOperationException("Line intersection without acceptance must show a current Done result.");
            AssertActiveToolTextsVisible("Line intersection Workbench result bindings", "완료", "교차점 X", "교차점 Y");

            VisionPipelineStep step = shellHost.AddActiveNativePipelineStepForTest();
            if (step == null
                || !string.Equals(step.ToolType, "LineIntersection", StringComparison.Ordinal)
                || !string.Equals(step.InputLayer, "Main", StringComparison.Ordinal)
                || !string.Equals(step.OutputLayer, "Line_1", StringComparison.Ordinal)
                || step.Parameters == null
                || !step.Parameters.ContainsKey("LeftPRJ_DIR")
                || !step.Parameters.ContainsKey("RightPRJ_DIR")
                || !step.Parameters.TryGetValue("LinePurpose", out string? purpose)
                || !string.Equals(purpose, "Intersection", StringComparison.Ordinal))
            {
                throw new InvalidOperationException("Line WPF tool did not create a valid LineIntersection pipeline step.");
            }
        });
    }

    private static int CheckLogCopyContract(string outputPath)
    {
        Directory.CreateDirectory(Path.GetDirectoryName(Path.GetFullPath(outputPath))!);
        List<string> copied = new();
        bool failClipboard = false;
        using LogPanelViewModel model = new(text =>
        {
            if (failClipboard) throw new ExternalException("Owned clipboard-busy fixture", unchecked((int)0x800401D0));
            copied.Add(text);
        });
        model.ResetCommand.Execute(null);
        int changes = 0;
        model.CopyCommand.CanExecuteChanged += (_, _) => changes++;
        Require(!model.CopyCommand.CanExecute(null), "empty Copy disabled");
        model.CopyCommand.Execute(null);
        Require(copied.Count == 0, "empty Copy does not call clipboard");
        var first = new OpenVisionLab.Logging.Controls.Model.LogLine(new DateTime(2026, 10, 15, 17, 23, 4, 5), "2026-10-15 17:23:04.005", "System", "Info", "fixture", "한글 검사\tA\nsecond line", "raw-one");
        var second = new OpenVisionLab.Logging.Controls.Model.LogLine(DateTime.MinValue, "", "Vision", "Error", "fixture", "Unicode Ω 中文", "raw-two");
        model.Logs.Add(first); model.Logs.Add(second);
        model.ShowEntireStream = false; model.SelectedLevel = "Error"; model.SearchText = "raw-two";
        Require(model.FilteredLogs.Count == 1 && model.CopyCommand.CanExecute(null), "nonempty Copy independent of filter");
        const string expected = "17:23:04.005\tInfo\tSystem\t한글 검사\tA\nsecond line\n\tError\tVision\tUnicode Ω 中文";
        var before = model.Logs.ToArray(); var filtered = model.FilteredLogs.ToArray();
        model.CopyCommand.Execute(null); model.CopyCommand.Execute(null);
        Require(copied.Count == 2 && copied.All(text => text == expected), "exact tab/LF/Unicode/all-session payload and repeated Copy");
        Require(model.Logs.SequenceEqual(before) && model.FilteredLogs.SequenceEqual(filtered) && model.SearchText == "raw-two" && model.SelectedLevel == "Error" && !model.ShowEntireStream, "Copy does not mutate rows or filters");
        failClipboard = true; model.CopyCommand.Execute(null);
        Require(copied.Count == 2 && model.CopyStatusText == OpenVisionLanguageService.T("Log.CopyFailed") && model.CopyCommand.CanExecute(null), "clipboard busy visible and retry enabled");
        failClipboard = false; model.CopyCommand.Execute(null);
        Require(copied.Count == 3 && model.CopyStatusText == OpenVisionLanguageService.T("Log.CopySucceeded"), "valid retry recovers");
        using OpenVisionShellHostView resourceHost = CreateShellHost("Smoke_LogCopy", false);
        LogPanelView view = new();
        view.Resources.MergedDictionaries.Add(resourceHost.Resources);
        LogPanelViewModel original = (LogPanelViewModel)view.DataContext;
        original.Dispose(); view.DataContext = model;
        model.IsDetailedMode = true; model.SearchText = "raw-two";
        var renderCases = new List<object>();
        OpenVisionLanguage initialLanguage = OpenVisionLanguageService.CurrentLanguage;
        try
        {
            foreach (string theme in new[] { "Dark", "Light" })
            foreach (OpenVisionLanguage language in new[] { OpenVisionLanguage.Korean, OpenVisionLanguage.English })
            foreach (int width in new[] { 1100, 720 })
            {
                OpenVisionLanguageService.SetLanguage(language, false);
                OpenVisionWorkbenchThemeBehavior.SetThemeName(view, theme);
                model.IsCompactLayout = width < 800;
                model.CopyCommand.Execute(null);
                Render("enabled");
                failClipboard = true; model.CopyCommand.Execute(null); failClipboard = false;
                Render("error");
                model.CopyCommand.Execute(null);
                Render("recovery");
                model.Logs.Clear(); model.SearchText = string.Empty;
                Render("disabled");
                Require(!model.CopyCommand.CanExecute(null), "clear disables Copy");
                model.Logs.Add(first); model.Logs.Add(second); model.SearchText = "raw-two";

                void Render(string state)
                {
                    Pump(2);
                    string capture = Path.ChangeExtension(outputPath, $".{theme}.{language}.{width}.{state}.png");
                    ScreenshotPngWriter.WriteElementPng(view, capture, width, 320);
                    Button copy = (Button)view.FindName("copyLogButton");
                    TextBlock feedback = (TextBlock)view.FindName("copyLogStatus");
                    bool enabled = state != "disabled";
                    Require(ReferenceEquals(copy.Command, model.CopyCommand) && copy.IsEnabled == enabled && copy.Content.ToString() == model.CopyText && AutomationProperties.GetName(copy) == model.CopyText, "rendered Copy command/CanExecute/localized accessible name");
                    Rect bounds = copy.TransformToAncestor(view).TransformBounds(new Rect(copy.RenderSize));
                    Require(bounds.Left >= 0 && bounds.Right <= width && bounds.Top >= 0 && bounds.Bottom <= 320 && copy.ActualWidth >= 58, "Copy remains inside toolbar");
                    var formatted = new FormattedText(model.CopyText, CultureInfo.CurrentCulture, FlowDirection.LeftToRight, new Typeface(copy.FontFamily, copy.FontStyle, copy.FontWeight, copy.FontStretch), copy.FontSize, copy.Foreground, 1);
                    Require(formatted.Width + copy.Padding.Left + copy.Padding.Right <= copy.ActualWidth, "Copy label unclipped");
                    Require(feedback.Text == model.CopyStatusText && feedback.Visibility == Visibility.Visible, "visible localized feedback binding");
                    renderCases.Add(new { Theme = theme, Language = language.ToString(), Width = width, State = state, Enabled = copy.IsEnabled, Caption = copy.Content.ToString(), Feedback = feedback.Text, Bounds = bounds.ToString(), Capture = capture, Scope = "in-process 96dpi render; no actual pointer/keyboard/native DPI" });
                }
            }
        }
        finally { OpenVisionLanguageService.SetLanguage(initialLanguage, false); }
        Require(changes >= 4, "collection changes notify Copy CanExecute");
        File.WriteAllText(outputPath, JsonSerializer.Serialize(new { Status = "Pass", Payload = expected, CopyCalls = copied.Count, CanExecuteChanges = changes, RenderCases = renderCases, LogAssemblySHA256 = Convert.ToHexString(SHA256.HashData(File.ReadAllBytes(typeof(LogPanelViewModel).Assembly.Location))), Scope = "empty, all session/filter independent, LF/tab/Unicode/multiline, repeated, external clipboard failure and retry, no mutation, bound KOEN DarkLight WideCompact normal/disabled/error/recovery; no actual clipboard or native input" }, new JsonSerializerOptions { WriteIndented = true }));
        return 0;
        static void Require(bool condition, string message) { if (!condition) throw new InvalidOperationException("Log Copy: " + message); }
    }

    private static CaptureResult CaptureLogPanel(string outputPath)
    {
        OpenVisionShellHostView host = CreateShellHost("Smoke_WorkbenchLog", false);
        return CaptureWindowWithContent(host, outputPath, 1600, 900, () =>
        {
            int runs = host.NativePreviewRunCount;
            int layers = host.LayerDocumentCount;
            string route = host.DirectResultRouteText;
            host.Workbench.OpenLogCommand.Execute(null); Pump(8);
            LogPanelView log = FindVisualChildren<LogPanelView>(host).Single();
            LogPanelViewModel model = (LogPanelViewModel)log.DataContext;
            model.SelectedLevel = "Warning";
            model.SearchText = "K7-tab-lifetime";
            host.Workbench.SelectedBottomTab = 0; Pump(4);
            if (log.IsVisible) { throw new InvalidOperationException("Log did not hide on image tab."); }
            LogManager.GetLogger("OpenVisionLab.K7").Warn("[System][Warning][Workbench] K7-tab-lifetime");
            WaitForTaskWithPump(Task.Delay(350), 2000, "K7 log refresh timer");
            host.Workbench.OpenLogCommand.Execute(null); Pump(8);
            if (!ReferenceEquals(log.DataContext, model) || !log.IsVisible || model.SearchText != "K7-tab-lifetime"
                || model.SelectedLevel != "Warning" || !model.FilteredLogs.Any(row => row.RawText.Contains("K7-tab-lifetime", StringComparison.Ordinal)))
            {
                throw new InvalidOperationException("Log tab switch lost the existing reader, filter or a new log event.");
            }
            host.Workbench.IsBottomCollapsed = true; Pump(4);
            if (log.IsVisible) { throw new InvalidOperationException("Log stayed visible while bottom panel was collapsed."); }
            host.Workbench.OpenLogCommand.Execute(null); Pump(4);
            AssertVisibleAutomationIds(host, "Workbench log tab", "WorkbenchBottomPanel", "WorkbenchLogTab");
            if (host.NativePreviewRunCount != runs || host.LayerDocumentCount != layers || host.DirectResultRouteText != route)
            {
                throw new InvalidOperationException("Log tab/collapse/filter produced an execution, layer or route change.");
            }
        });
    }

    private static CaptureResult CaptureFallbackStatusLanguage(string outputPath, int width, int height)
    {
        OpenVisionShellHostView host = CreateShellHost("Smoke_FallbackLanguage", false);
        List<object> cases = new(); List<string> failures = new();
        return CaptureWindowWithContent(host, outputPath, width, height, () =>
        {
            TextBlock status = FindNamedVisualChild<TextBlock>(host, "txtHostWorkspaceStatus")!;
            Image image = FindNamedVisualChild<Image>(host, "hostWorkspaceFallbackImage")!;
            Grid surface = FindNamedVisualChild<Grid>(host, "hostWorkspaceImageSurface")!;
            OpenVisionZoomableImageController zoom = ReadPrivateField<OpenVisionZoomableImageController>(host, "workspaceFallbackZoomController");
            object presenter = ReadPrivateField<object>(host, "layerWorkspacePresenter");
            Type detailType = typeof(OpenVisionShellHostView).Assembly.GetType("OpenVisionLab.OpenVisionShellHostLayerDetailState", true)!;
            OpenVisionLanguage initial = OpenVisionLanguageService.CurrentLanguage;
            int runs = host.NativePreviewRunCount;
            string route = string.Join("|", host.Workbench.Pipeline.Rows.Select(row => row.Index + ":" + row.InputLayer + "->" + row.OutputLayer));
            byte[] working = VisionPipelineExecutionPlan.SerializePipeline(host.Workbench.Pipeline.WorkingCopyForTest);
            foreach (string paletteName in new[] { "Dark", "Light" })
            {
                ResourceDictionary palette = new() { Source = new Uri($"/OpenVisionLab;component/UI/Wpf/OpenVisionWorkbench{paletteName}.xaml", UriKind.Relative) };
                host.Resources.MergedDictionaries.Add(palette);
                try
                {
                    OpenVisionLanguageService.SetLanguage(OpenVisionLanguage.Korean, false);
                    string inputPath = Path.ChangeExtension(outputPath, $".{paletteName}.input.png");
                    using (Bitmap input = new(640, 360))
                    {
                        using Graphics graphics = Graphics.FromImage(input); graphics.Clear(DrawingColor.Magenta); input.Save(inputPath, ImageFormat.Png);
                    }
                    if (!host.LoadMainImageFromFileForTest(inputPath) || !host.ArrangeDockedLayerPanesForTest("Horizontal", "Main")) throw new InvalidOperationException("Fallback language input setup failed.");
                    host.ClearDockedLayersForTest(); Pump(6);
                    if (host.DockedLayerCount != 0 || !image.IsVisible) throw new InvalidOperationException("Fallback language host transition missing.");
                    zoom.UpdatePointerStatusForTest(image.TransformToAncestor(surface).Transform(new Point(100.5D * image.ActualWidth / 640D, 100.5D * image.ActualHeight / 360D)));
                    Pump(3);
                    object bitmapBefore = image.Source; string pointerBefore = host.Workbench.Workspace.PointerText;
                    Matrix transformBefore = image.RenderTransform.Value; int documentsBefore = host.DockedLayerCount;
                    Observe("loaded-ko", "표시", true);
                    OpenVisionLanguageService.SetLanguage(OpenVisionLanguage.English, false); Observe("loaded-en", "display", true);
                    OpenVisionLanguageService.SetLanguage(OpenVisionLanguage.Korean, false); Observe("loaded-ko-return", "표시", true);
                    ApplySyntheticDetail("OK", null);
                    Observe("raw-ok-ko", "OK", false);
                    OpenVisionLanguageService.SetLanguage(OpenVisionLanguage.English, false); Observe("raw-ok-en", "OK", false);
                    OpenVisionLanguageService.SetLanguage(OpenVisionLanguage.Korean, false);
                    ApplySyntheticDetail("레이어 대기", "Shell.LayerDetailPending"); Observe("pending-ko", "레이어 대기", false);
                    OpenVisionLanguageService.SetLanguage(OpenVisionLanguage.English, false); Observe("pending-en", "Layer pending", false);
                    OpenVisionLanguageService.SetLanguage(OpenVisionLanguage.Korean, false); Observe("pending-ko-return", "레이어 대기", false);

                    void ApplySyntheticDetail(string routeText, string key)
                    {
                        object[] args = detailType.GetConstructors().Single().GetParameters().Length == 5
                            ? new object[] { "Main", "-", routeText, null, key }
                            : new object[] { "Main", "-", routeText, null };
                        object detail = Activator.CreateInstance(detailType, args)!;
                        presenter.GetType().GetMethod("ApplyWorkspace")!.Invoke(presenter, new[] { detail }); Pump(3);
                    }
                    void Observe(string state, string expected, bool retained)
                    {
                        Pump(4);
                        bool matched = status.Text == expected;
                        bool stable = !retained || ReferenceEquals(image.Source, bitmapBefore) && image.RenderTransform.Value == transformBefore && host.DockedLayerCount == documentsBefore && host.Workbench.Workspace.PointerText == pointerBefore;
                        Rect bounds = status.TransformToAncestor(host).TransformBounds(new Rect(status.RenderSize));
                        bool inside = bounds.Left >= 0D && bounds.Right <= host.ActualWidth && bounds.Bottom <= host.ActualHeight;
                        bool full = status.ActualWidth >= new FormattedText(status.Text, CultureInfo.InvariantCulture, FlowDirection.LeftToRight, new Typeface(status.FontFamily, status.FontStyle, status.FontWeight, status.FontStretch), status.FontSize, status.Foreground, VisualTreeHelper.GetDpi(status).PixelsPerDip).Width;
                        if (!matched || !stable || !inside || !full) failures.Add($"{paletteName}/{state}: '{status.Text}' expected '{expected}', retained={stable}, inside={inside}, full={full}");
                        string capture = Path.Combine(Path.GetDirectoryName(outputPath)!, Path.GetFileNameWithoutExtension(outputPath) + $".{paletteName}.{state}.png");
                        ScreenshotPngWriter.WriteElementPng(host, capture, width, height);
                        cases.Add(new { Palette=paletteName, State=state, Expected=expected, Actual=status.Text, Matched=matched, Retained=stable, Inside=inside, FullText=full, Bounds=bounds, Capture=capture, SyntheticDetail=!retained });
                    }
                }
                finally { host.Resources.MergedDictionaries.Remove(palette); }
            }
            OpenVisionLanguageService.SetLanguage(initial, false); Pump(3);
            var invariants = new { RunsUnchanged=host.NativePreviewRunCount == runs, RouteUnchanged=route == string.Join("|", host.Workbench.Pipeline.Rows.Select(row => row.Index + ":" + row.InputLayer + "->" + row.OutputLayer)), WorkingUnchanged=working.SequenceEqual(VisionPipelineExecutionPlan.SerializePipeline(host.Workbench.Pipeline.WorkingCopyForTest)) };
            if (!invariants.RunsUnchanged || !invariants.RouteUnchanged || !invariants.WorkingUnchanged) failures.Add("Fallback localization changed Run/route/working copy.");
            File.WriteAllText(Path.ChangeExtension(outputPath, ".language-cases.json"), JsonSerializer.Serialize(new { Cases=cases, Failures=failures, Invariants=invariants, ProductSHA256=Convert.ToHexString(SHA256.HashData(File.ReadAllBytes(typeof(OpenVisionShellHostView).Assembly.Location))), Scope="new language change while fallback already loaded; rawOK/pending synthetic detail; no actual input/nativeDPI/HTML/finalN" }, new JsonSerializerOptions { WriteIndented=true }));
            if (failures.Count > 0) throw new InvalidOperationException(string.Join("; ", failures));
        });
    }

    private static CaptureResult CaptureWorkbenchFallbackPointer(string outputPath, int width, int height)
    {
        OpenVisionShellHostView host = CreateShellHost("Smoke_W09_FallbackPointer", false);
        List<object> cases = new();
        List<string> failures = new();
        return CaptureWindowWithContent(host, outputPath, width, height, () =>
        {
            Grid statusBar = FindVisualChildren<Grid>(host).Single(item => AutomationProperties.GetAutomationId(item) == "WorkbenchStatusBar");
            TextBlock pointer = FindVisualChildren<TextBlock>(statusBar).Single(item => AutomationProperties.GetAutomationId(item) == "WorkbenchStatusPointer");
            TextBlock coordinates = FindNamedVisualChild<TextBlock>(host, "txtHostWorkspaceCoordinates")!;
            TextBlock pixels = FindNamedVisualChild<TextBlock>(host, "txtHostWorkspacePixel")!;
            Image image = FindNamedVisualChild<Image>(host, "hostWorkspaceFallbackImage")!;
            Grid surface = FindNamedVisualChild<Grid>(host, "hostWorkspaceImageSurface")!;
            OpenVisionZoomableImageController fallback = ReadPrivateField<OpenVisionZoomableImageController>(host, "workspaceFallbackZoomController");
            int runs = host.NativePreviewRunCount;
            string route = string.Join("|", host.Workbench.Pipeline.Rows.Select(row => row.Index + ":" + row.InputLayer + "->" + row.OutputLayer));
            byte[] working = VisionPipelineExecutionPlan.SerializePipeline(host.Workbench.Pipeline.WorkingCopyForTest);
            OpenVisionLanguage initialLanguage = OpenVisionLanguageService.CurrentLanguage;
            foreach (string paletteName in new[] { "Dark", "Light" })
            {
                ResourceDictionary palette = new() { Source = new Uri($"/OpenVisionLab;component/UI/Wpf/OpenVisionWorkbench{paletteName}.xaml", UriKind.Relative) };
                host.Resources.MergedDictionaries.Add(palette);
                try
                {
                    foreach (OpenVisionLanguage language in new[] { OpenVisionLanguage.Korean, OpenVisionLanguage.English })
                    {
                        OpenVisionLanguageService.SetLanguage(language, false);
                        string inputPath = Path.Combine(Path.GetDirectoryName(outputPath)!, Path.GetFileNameWithoutExtension(outputPath) + $".{paletteName}.{language}.input.png");
                        using (Bitmap input = new(640, 360))
                        {
                            using Graphics graphics = Graphics.FromImage(input); graphics.Clear(DrawingColor.FromArgb(32, 48, 71));
                            graphics.FillRectangle(System.Drawing.Brushes.Orange, 20, 20, 210, 150); input.Save(inputPath, ImageFormat.Png);
                        }
                        if (!host.LoadMainImageFromFileForTest(inputPath)) throw new InvalidOperationException("Fallback file input setup failed.");
                        if (!host.ArrangeDockedLayerPanesForTest("Horizontal", "Main")) throw new InvalidOperationException("Existing Main document reopen fixture failed.");
                        Pump(6);
                        OpenVisionLayerViewerView main = FindVisualChildren<OpenVisionLayerViewerView>(host).Single(item => item.LayerTitle == "Main");
                        OpenVisionZoomableImageController docked = ReadPrivateField<OpenVisionZoomableImageController>(main, "fallbackImageZoomController");
                        Image dockedImage = ReadPrivateField<Image>(main, "layerFallbackImage");
                        Grid dockedSurface = ReadPrivateField<Grid>(main, "layerImageSurface");
                        docked.UpdatePointerStatusForTest(dockedImage.TransformToAncestor(dockedSurface).Transform(new Point(400.5D * dockedImage.ActualWidth / 640D, 250.5D * dockedImage.ActualHeight / 360D)));
                        fallback.UpdatePointerStatusForTest(new Point(-10D, -10D));
                        Observe("hidden-fallback-ignored", "X 400  Y 250  GV 46", "X:400 Y:250", "GV 46 | RGB 32,48,71", false);
                        host.ClearDockedLayersForTest(); Pump(6);
                        if (host.DockedLayerCount != 0 || !image.IsVisible || image.ActualWidth <= 0D) throw new InvalidOperationException("Existing visible fallback unavailable after document close.");
                        fallback.UpdatePointerStatusForTest(PixelPoint(100, 100));
                        Observe("closed-to-fallback-orange", "X 100  Y 100  GV 173", "X:100 Y:100", "GV 173 | RGB 255,165,0", true);
                        fallback.UpdatePointerStatusForTest(PixelPoint(400, 250));
                        Observe("fallback-background", "X 400  Y 250  GV 46", "X:400 Y:250", "GV 46 | RGB 32,48,71", true);
                        fallback.UpdatePointerStatusForTest(new Point(-10D, -10D));
                        Observe("outside-clears", "X —  Y —  GV —", "X:- Y:-", "GV - | RGB -", true);
                        fallback.UpdatePointerStatusForTest(PixelPoint(100, 100));
                        surface.RaiseEvent(new MouseEventArgs(Mouse.PrimaryDevice, 0) { RoutedEvent = Mouse.MouseLeaveEvent });
                        Observe("leave-clears", "X —  Y —  GV —", "X:- Y:-", "GV - | RGB -", true);
                        fallback.UpdatePointerStatusForTest(PixelPoint(80, 80));
                        Observe("return-valid", "X 80  Y 80  GV 173", "X:80 Y:80", "GV 173 | RGB 255,165,0", true);
                        using (Bitmap replacement = new(640, 360))
                        {
                            using Graphics graphics = Graphics.FromImage(replacement); graphics.Clear(DrawingColor.Magenta); replacement.Save(Path.ChangeExtension(inputPath, ".replacement.png"), ImageFormat.Png);
                        }
                        if (!host.LoadMainImageFromFileForTest(Path.ChangeExtension(inputPath, ".replacement.png"))) throw new InvalidOperationException("Same-size fallback replacement failed.");
                        host.ClearDockedLayersForTest(); Pump(6);
                        Observe("replacement-clears", "X —  Y —  GV —", "X:- Y:-", "GV - | RGB -", true);
                        fallback.UpdatePointerStatusForTest(PixelPoint(400, 250));
                        Observe("replacement-new-pixels", "X 400  Y 250  GV 105", "X:400 Y:250", "GV 105 | RGB 255,0,255", true);

                        void Observe(string state, string expected, string expectedCoordinates, string expectedPixels, bool fallbackVisible)
                        {
                            Pump(4);
                            bool matched = pointer.Text == expected && coordinates.Text == expectedCoordinates && pixels.Text == expectedPixels;
                            bool bound = new[] { pointer, coordinates, pixels }.All(text => BindingOperations.IsDataBound(text, TextBlock.TextProperty));
                            bool visible = !fallbackVisible || image.IsVisible && host.DockedLayerCount == 0;
                            Rect bounds = pointer.TransformToAncestor(statusBar).TransformBounds(new Rect(pointer.RenderSize));
                            bool inside = bounds.Left >= 0D && bounds.Right <= statusBar.ActualWidth && bounds.Bottom <= statusBar.ActualHeight;
                            bool full = new[] { pointer, coordinates, pixels }.All(text => text.ActualWidth >= new FormattedText(text.Text,
                                CultureInfo.InvariantCulture, FlowDirection.LeftToRight, new Typeface(text.FontFamily, text.FontStyle, text.FontWeight, text.FontStretch),
                                text.FontSize, text.Foreground, VisualTreeHelper.GetDpi(text).PixelsPerDip).Width);
                            if (!matched || !bound || !visible || !inside || !full) failures.Add($"{paletteName}/{language}/{state}: '{pointer.Text}', footer='{coordinates.Text}/{pixels.Text}', expected='{expected}', bound={bound}, visible={visible}, inside={inside}, full={full}");
                            string capture = Path.Combine(Path.GetDirectoryName(outputPath)!, Path.GetFileNameWithoutExtension(outputPath) + $".{paletteName}.{language}.{state}.png");
                            ScreenshotPngWriter.WriteElementPng(host, capture, width, height);
                            cases.Add(new { Palette=paletteName, Language=language.ToString(), State=state, Expected=expected, Actual=pointer.Text, Coordinates=coordinates.Text,
                                Pixels=pixels.Text, Matched=matched, BindingRetained=bound, FallbackVisible=visible, Inside=inside, FullText=full, PointerBounds=bounds, Capture=capture });
                        }
                    }
                }
                finally { host.Resources.MergedDictionaries.Remove(palette); }
            }
            OpenVisionLanguageService.SetLanguage(initialLanguage, false); Pump(4);
            int notifications = 0;
            System.ComponentModel.PropertyChangedEventHandler changed = (_, e) => { if (e.PropertyName == "PointerText") notifications++; };
            host.Workbench.Workspace.PropertyChanged += changed;
            string pointerBefore = pointer.Text, footerBefore = coordinates.Text + "|" + pixels.Text;
            host.Workbench.Workspace.Dispose();
            fallback.UpdatePointerStatusForTest(new Point(-10D, -10D)); Pump(2);
            host.Workbench.Workspace.PropertyChanged -= changed;
            var invariants = new { RunsUnchanged=host.NativePreviewRunCount == runs,
                RouteUnchanged=route == string.Join("|", host.Workbench.Pipeline.Rows.Select(row => row.Index + ":" + row.InputLayer + "->" + row.OutputLayer)),
                WorkingUnchanged=working.SequenceEqual(VisionPipelineExecutionPlan.SerializePipeline(host.Workbench.Pipeline.WorkingCopyForTest)),
                DisposedIgnored=notifications == 0 && pointer.Text == pointerBefore && coordinates.Text + "|" + pixels.Text == footerBefore };
            if (!invariants.RunsUnchanged || !invariants.RouteUnchanged || !invariants.WorkingUnchanged || !invariants.DisposedIgnored) failures.Add("Fallback changed Run/route/working copy or wrote status after disposal.");
            File.WriteAllText(Path.ChangeExtension(outputPath, ".fallback-cases.json"), JsonSerializer.Serialize(new { Cases=cases, Failures=failures, Invariants=invariants,
                ProductSHA256=Convert.ToHexString(SHA256.HashData(File.ReadAllBytes(typeof(OpenVisionShellHostView).Assembly.Location))),
                Scope="last docked document closes into existing fallback; synthetic pointer, hidden callback and disposal; no actual input/nativeDPI/HTML/finalN" }, new JsonSerializerOptions { WriteIndented=true }));
            if (failures.Count > 0) throw new InvalidOperationException(string.Join("; ", failures));

            Point PixelPoint(int x, int y) => image.TransformToAncestor(surface).Transform(new Point((x + 0.5D) * image.ActualWidth / 640D, (y + 0.5D) * image.ActualHeight / 360D));
        });
    }

    private static CaptureResult CaptureWorkbenchPointerStatus(string outputPath, int width, int height)
    {
        OpenVisionShellHostView host = CreateShellHost("Smoke_W09_Pointer", false);
        List<object> cases = new();
        List<string> failures = new();
        return CaptureWindowWithContent(host, outputPath, width, height, () =>
        {
            Grid statusBar = FindVisualChildren<Grid>(host).Single(item => AutomationProperties.GetAutomationId(item) == "WorkbenchStatusBar");
            TextBlock pointer = FindVisualChildren<TextBlock>(statusBar).Single(item => AutomationProperties.GetAutomationId(item) == "WorkbenchStatusPointer");
            TextBlock coordinates = FindVisualChildren<TextBlock>(host).Single(item => item.Name == "txtHostWorkspaceCoordinates");
            TextBlock pixels = FindVisualChildren<TextBlock>(host).Single(item => item.Name == "txtHostWorkspacePixel");
            TextBlock inputName = FindVisualChildren<TextBlock>(statusBar).Single(item => AutomationProperties.GetAutomationId(item) == "WorkbenchStatusInputName");
            Button log = FindVisualChildren<Button>(statusBar).Single(item => AutomationProperties.GetAutomationId(item) == "WorkbenchOpenLog");
            int runs = host.NativePreviewRunCount;
            string route = string.Join("|", host.Workbench.Pipeline.Rows.Select(row => row.Index + ":" + row.InputLayer + "->" + row.OutputLayer));
            byte[] working = VisionPipelineExecutionPlan.SerializePipeline(host.Workbench.Pipeline.WorkingCopyForTest);
            OpenVisionLanguage initialLanguage = OpenVisionLanguageService.CurrentLanguage;
            using (Bitmap other = new(320, 180))
            {
                using Graphics graphics = Graphics.FromImage(other); graphics.Clear(DrawingColor.White);
                if (!host.AddLayerImageForTest("PointerOther", other)) throw new InvalidOperationException("Pointer peer image setup failed.");
            }
            OpenVisionLayerViewerView? lastMain = null;
            OpenVisionZoomableImageController? lastController = null;
            foreach (string paletteName in new[] { "Dark", "Light" })
            {
                ResourceDictionary palette = new() { Source = new Uri($"/OpenVisionLab;component/UI/Wpf/OpenVisionWorkbench{paletteName}.xaml", UriKind.Relative) };
                host.Resources.MergedDictionaries.Add(palette);
                try
                {
                    foreach (OpenVisionLanguage language in new[] { OpenVisionLanguage.Korean, OpenVisionLanguage.English })
                    {
                        OpenVisionLanguageService.SetLanguage(language, false);
                        using (Bitmap input = new(640, 360))
                        {
                            using Graphics graphics = Graphics.FromImage(input); graphics.Clear(DrawingColor.FromArgb(32, 48, 71));
                            graphics.FillRectangle(System.Drawing.Brushes.Orange, 20, 20, 210, 150); host.SetMainLayerImageForTest(input);
                        }
                        Pump(6);
                        if (!host.ArrangeDockedLayerPanesForTest("Horizontal", "Main", "PointerOther")) throw new InvalidOperationException("Existing two-pane fixture setup failed.");
                        Pump(6);
                        OpenVisionLayerViewerView main = FindVisualChildren<OpenVisionLayerViewerView>(host).Single(item => item.LayerTitle == "Main");
                        OpenVisionLayerViewerView other = FindVisualChildren<OpenVisionLayerViewerView>(host).Single(item => item.LayerTitle == "PointerOther");
                        OpenVisionZoomableImageController mainController = ReadPrivateField<OpenVisionZoomableImageController>(main, "fallbackImageZoomController");
                        OpenVisionZoomableImageController otherController = ReadPrivateField<OpenVisionZoomableImageController>(other, "fallbackImageZoomController");
                        lastMain = main; lastController = mainController;
                        Observe("image-reset", "X —  Y —  GV —", "X:- Y:-", "GV - | RGB -", true);
                        Point orange = PixelPoint(main, 100, 100, 640, 360);
                        if (!mainController.UpdatePointerStatusForTest(orange)) failures.Add("Orange pixel status unavailable.");
                        Observe("main-orange", "X 100  Y 100  GV 173", "X:100 Y:100", "GV 173 | RGB 255,165,0", true);
                        if (!mainController.UpdatePointerStatusForTest(PixelPoint(main, 400, 250, 640, 360))) failures.Add("Background pixel status unavailable.");
                        Observe("main-background", "X 400  Y 250  GV 46", "X:400 Y:250", "GV 46 | RGB 32,48,71", true);
                        if (mainController.UpdatePointerStatusForTest(new Point(-10D, -10D))) failures.Add("Outside image unexpectedly yielded a pixel.");
                        Observe("outside-clears", "X —  Y —  GV —", "X:- Y:-", "GV - | RGB -", true);
                        string selectedBefore = host.WorkspaceLayerTitle;
                        if (!otherController.UpdatePointerStatusForTest(PixelPoint(other, 40, 40, 320, 180))) failures.Add("Peer pixel status unavailable.");
                        Observe("other-white-no-selection", "X 40  Y 40  GV 255", "X:40 Y:40", "GV 255 | RGB 255,255,255", selectedBefore == host.WorkspaceLayerTitle);
                        ReadPrivateField<Grid>(other, "layerImageSurface").RaiseEvent(new MouseEventArgs(Mouse.PrimaryDevice, 0) { RoutedEvent = Mouse.MouseLeaveEvent });
                        Observe("leave-clears", "X —  Y —  GV —", "X:- Y:-", "GV - | RGB -", true);
                        mainController.UpdatePointerStatusForTest(PixelPoint(main, 80, 80, 640, 360));
                        Observe("return-main", "X 80  Y 80  GV 173", "X:80 Y:80", "GV 173 | RGB 255,165,0", true);
                        using (Bitmap replacement = new(640, 360))
                        {
                            using Graphics graphics = Graphics.FromImage(replacement); graphics.Clear(DrawingColor.Magenta); host.SetMainLayerImageForTest(replacement);
                        }
                        Pump(6);
                        Observe("replacement-clears", "X —  Y —  GV —", "X:- Y:-", "GV - | RGB -", true);
                        mainController.UpdatePointerStatusForTest(PixelPoint(main, 400, 250, 640, 360));
                        Observe("replacement-new-pixels", "X 400  Y 250  GV 105", "X:400 Y:250", "GV 105 | RGB 255,0,255", true);

                        void Observe(string state, string expected, string expectedCoordinates, string expectedPixels, bool selectionSafe)
                        {
                            Pump(4);
                            bool matched = pointer.Text == expected && coordinates.Text == expectedCoordinates && pixels.Text == expectedPixels;
                            bool bound = BindingOperations.IsDataBound(coordinates, TextBlock.TextProperty) && BindingOperations.IsDataBound(pixels, TextBlock.TextProperty);
                            Rect pointerBounds = pointer.TransformToAncestor(statusBar).TransformBounds(new Rect(pointer.RenderSize));
                            Rect inputBounds = inputName.TransformToAncestor(statusBar).TransformBounds(new Rect(inputName.RenderSize));
                            Rect logBounds = log.TransformToAncestor(statusBar).TransformBounds(new Rect(log.RenderSize));
                            bool inside = pointer.IsVisible && pointerBounds.Top >= 0D && pointerBounds.Bottom <= statusBar.ActualHeight
                                && pointerBounds.Left >= inputBounds.Right && pointerBounds.Right <= logBounds.Left && logBounds.Right <= statusBar.ActualWidth;
                            bool fullText = new[] { pointer, coordinates, pixels }.All(text => text.ActualWidth >= new FormattedText(text.Text,
                                CultureInfo.InvariantCulture, FlowDirection.LeftToRight, new Typeface(text.FontFamily, text.FontStyle, text.FontWeight, text.FontStretch),
                                text.FontSize, text.Foreground, VisualTreeHelper.GetDpi(text).PixelsPerDip).Width);
                            double contrast = GetContrastRatio(((SolidColorBrush)pointer.Foreground).Color, ((SolidColorBrush)statusBar.Background).Color);
                            if (!matched || !bound || !inside || !fullText || contrast < 4.5D || !selectionSafe)
                                failures.Add($"{paletteName}/{language}/{state}: '{pointer.Text}', footer='{coordinates.Text}/{pixels.Text}', expected='{expected}', bound={bound}, inside={inside}, full={fullText}, contrast={contrast:0.00}, selection={selectionSafe}");
                            string capture = Path.Combine(Path.GetDirectoryName(outputPath)!, Path.GetFileNameWithoutExtension(outputPath) + $".{paletteName}.{language}.{state}.png");
                            ScreenshotPngWriter.WriteElementPng(host, capture, width, height);
                            cases.Add(new { Palette = paletteName, Language = language.ToString(), State = state, Expected = expected, Actual = pointer.Text,
                                Coordinates = coordinates.Text, Pixels = pixels.Text, Matched = matched, BindingRetained = bound, Inside = inside, FullText = fullText,
                                Contrast = contrast, SelectionUnchanged = selectionSafe, PointerBounds = pointerBounds, InputBounds = inputBounds, LogBounds = logBounds, Capture = capture });
                        }
                    }
                }
                finally { host.Resources.MergedDictionaries.Remove(palette); }
            }
            OpenVisionLanguageService.SetLanguage(initialLanguage, false); Pump(4);
            host.ClearDockedLayersForTest(); Pump(6);
            bool removedClear = host.Workbench.Workspace.PointerText == "X —  Y —  GV —" && lastMain != null
                && lastMain.GetType().GetField("ownedLayerImage", BindingFlags.Instance | BindingFlags.NonPublic)?.GetValue(lastMain) == null;
            int notifications = 0;
            System.ComponentModel.PropertyChangedEventHandler changed = (_, e) => { if (e.PropertyName == "PointerText") notifications++; };
            host.Workbench.Workspace.PropertyChanged += changed;
            lastController?.UpdatePointerStatusForTest(new Point(1D, 1D)); Pump(2);
            bool removedDetached = notifications == 0;
            host.Workbench.Workspace.Dispose();
            host.Workbench.Workspace.PropertyChanged -= changed;
            bool subscriptionsReleased = ReadPrivateField<List<IOpenVisionDockedLayerViewer>>(host.Workbench.Workspace, "observedPointerViewers").Count == 0;
            var invariants = new { RunsUnchanged = host.NativePreviewRunCount == runs,
                RouteUnchanged = route == string.Join("|", host.Workbench.Pipeline.Rows.Select(row => row.Index + ":" + row.InputLayer + "->" + row.OutputLayer)),
                WorkingUnchanged = working.SequenceEqual(VisionPipelineExecutionPlan.SerializePipeline(host.Workbench.Pipeline.WorkingCopyForTest)), RemovedClear = removedClear,
                RemovedDetached = removedDetached, SubscriptionsReleased = subscriptionsReleased };
            if (!invariants.RunsUnchanged || !invariants.RouteUnchanged || !invariants.WorkingUnchanged || !removedClear || !removedDetached || !subscriptionsReleased)
                failures.Add("Pointer display changed execution/route/working copy or retained a removed viewer subscription.");
            File.WriteAllText(Path.ChangeExtension(outputPath, ".pointer-cases.json"), JsonSerializer.Serialize(new { Cases = cases, Failures = failures, Invariants = invariants,
                ProductSHA256 = Convert.ToHexString(SHA256.HashData(File.ReadAllBytes(typeof(OpenVisionShellHostView).Assembly.Location))),
                Scope = "new pointer data/synthetic movement, two existing visible viewers and W09/footer bindings; no actual input/nativeDPI/HTML/full pane parity" }, new JsonSerializerOptions { WriteIndented = true }));
            if (failures.Count > 0) throw new InvalidOperationException(string.Join("; ", failures));

            Point PixelPoint(OpenVisionLayerViewerView viewer, int x, int y, int inputWidth, int inputHeight)
            {
                Image image = ReadPrivateField<Image>(viewer, "layerFallbackImage");
                Grid surface = ReadPrivateField<Grid>(viewer, "layerImageSurface");
                if (!viewer.IsVisible || image.ActualWidth <= 0D || image.ActualHeight <= 0D) throw new InvalidOperationException("Visible pointer fixture geometry unavailable.");
                return image.TransformToAncestor(surface).Transform(new Point((x + 0.5D) * image.ActualWidth / inputWidth, (y + 0.5D) * image.ActualHeight / inputHeight));
            }
        });
    }


    private static CaptureResult CaptureWorkbenchPaneDimensions(string outputPath, int width, int height)
    {
        OpenVisionShellHostView host = CreateShellHost("Smoke_PaneDimensions", false);
        List<object> cases = new();
        List<string> failures = new();
        return CaptureWindowWithContent(host, outputPath, width, height, () =>
        {
            int runs = host.NativePreviewRunCount;
            string route = string.Join("|", host.Workbench.Pipeline.Rows.Select(row => row.Index + ":" + row.InputLayer + "->" + row.OutputLayer));
            byte[] working = VisionPipelineExecutionPlan.SerializePipeline(host.Workbench.Pipeline.WorkingCopyForTest);
            OpenVisionLanguage initialLanguage = OpenVisionLanguageService.CurrentLanguage;
            object? firstView = null;
            foreach (string paletteName in new[] { "Dark", "Light" })
            {
                ResourceDictionary palette = new() { Source = new Uri($"/OpenVisionLab;component/UI/Wpf/OpenVisionWorkbench{paletteName}.xaml", UriKind.Relative) };
                host.Resources.MergedDictionaries.Add(palette);
                try
                {
                    foreach (OpenVisionLanguage language in new[] { OpenVisionLanguage.Korean, OpenVisionLanguage.English })
                    {
                        OpenVisionLanguageService.SetLanguage(language, false);
                        foreach (var size in new[] { (State: "initial", W: 640, H: 360), (State: "width-only", W: 643, H: 360),
                            (State: "height-only", W: 643, H: 361), (State: "shrink", W: 320, H: 180), (State: "same-size-repeat", W: 320, H: 180) })
                        {
                            using (Bitmap input = new(size.W, size.H))
                            {
                                using Graphics graphics = Graphics.FromImage(input);
                                graphics.Clear(DrawingColor.Teal);
                                graphics.FillRectangle(System.Drawing.Brushes.Orange, 20, 20, size.W / 3, size.H / 3);
                                host.SetMainLayerImageForTest(input);
                            }
                            Pump(6);
                            TextBlock? label = FindVisualChildren<TextBlock>(host).FirstOrDefault(text =>
                            {
                                MultiBinding? binding = BindingOperations.GetMultiBinding(text, TextBlock.TextProperty);
                                if (binding == null || !binding.Bindings.OfType<Binding>().Any(item => item.Path?.Path == "Model.Content.ImagePixelWidth")) return false;
                                object? model = text.TemplatedParent?.GetType().GetProperty("Model")?.GetValue(text.TemplatedParent);
                                return Convert.ToString(model?.GetType().GetProperty("ContentId")?.GetValue(model)) == "Main" && text.IsVisible;
                            });
                            object? model = label?.TemplatedParent?.GetType().GetProperty("Model")?.GetValue(label.TemplatedParent);
                            object? viewer = model?.GetType().GetProperty("Content")?.GetValue(model);
                            firstView ??= viewer;
                            string expected = $"{size.W}×{size.H}";
                            string actual = label?.Text ?? "<missing>";
                            bool valuesMatch = actual.Replace('x', '×') == expected;
                            bool canonicalSeparator = actual == expected;
                            bool gettersMatch = host.GetDockedLayerImagePixelWidthForTest("Main") == size.W && host.GetDockedLayerImagePixelHeightForTest("Main") == size.H;
                            bool sameView = viewer != null && ReferenceEquals(firstView, viewer);
                            Rect? bounds = label?.TransformToAncestor(host).TransformBounds(new Rect(label.RenderSize));
                            bool inside = bounds.HasValue && bounds.Value.Left >= 0D && bounds.Value.Right <= host.ActualWidth
                                && bounds.Value.Top >= 0D && bounds.Value.Bottom <= host.ActualHeight;
                            bool fullText = label != null && label.ActualWidth >= new FormattedText(expected, System.Globalization.CultureInfo.CurrentCulture, FlowDirection.LeftToRight,
                                new Typeface(label.FontFamily, label.FontStyle, label.FontWeight, label.FontStretch), label.FontSize, label.Foreground, VisualTreeHelper.GetDpi(label).PixelsPerDip).Width;
                            if (!valuesMatch || !canonicalSeparator || !gettersMatch || !sameView || !inside || !fullText)
                                failures.Add($"{paletteName}/{language}/{size.State}: '{actual}' expected '{expected}'; getters={gettersMatch}, sameView={sameView}, inside={inside}, fullText={fullText}");
                            string capture = Path.Combine(Path.GetDirectoryName(outputPath)!, Path.GetFileNameWithoutExtension(outputPath) + $".{paletteName}.{language}.{size.State}.png");
                            ScreenshotPngWriter.WriteElementPng(host, capture, width, height);
                            cases.Add(new { Palette = paletteName, Language = language.ToString(), size.State, Expected = expected, Actual = actual,
                                ValuesMatch = valuesMatch, CanonicalSeparator = canonicalSeparator, GettersMatch = gettersMatch, SameView = sameView, Inside = inside, FullText = fullText,
                                Bounds = bounds, ViewType = viewer?.GetType().FullName, Capture = capture });
                        }
                    }
                }
                finally { host.Resources.MergedDictionaries.Remove(palette); }
            }
            OpenVisionLanguageService.SetLanguage(initialLanguage, false); Pump(4);
            var invariants = new { RunsUnchanged = host.NativePreviewRunCount == runs,
                RouteUnchanged = route == string.Join("|", host.Workbench.Pipeline.Rows.Select(row => row.Index + ":" + row.InputLayer + "->" + row.OutputLayer)),
                WorkingUnchanged = working.SequenceEqual(VisionPipelineExecutionPlan.SerializePipeline(host.Workbench.Pipeline.WorkingCopyForTest)) };
            if (!invariants.RunsUnchanged || !invariants.RouteUnchanged || !invariants.WorkingUnchanged) failures.Add("Pane dimension display changed execution, routing or working copy.");
            File.WriteAllText(Path.ChangeExtension(outputPath, ".pane-cases.json"), JsonSerializer.Serialize(new { Cases = cases, Failures = failures, Invariants = invariants,
                ProductSHA256 = Convert.ToHexString(SHA256.HashData(File.ReadAllBytes(typeof(OpenVisionShellHostView).Assembly.Location))),
                DockingSHA256 = Convert.ToHexString(SHA256.HashData(File.ReadAllBytes(typeof(OpenVisionLab.Docking.Controls.OpenVisionDockDocumentController).Assembly.Location))),
                Scope = "new in-process pane-title binding updates on same View only; no old W09/fit/zoom target replay or actual input/nativeDPI/HTML" }, new JsonSerializerOptions { WriteIndented = true }));
            if (failures.Count > 0) throw new InvalidOperationException(string.Join("; ", failures));
        });
    }


    private static CaptureResult CaptureMainPaneOverlays(string outputPath, int width, int height)
    {
        OpenVisionShellHostView host = CreateShellHost("Smoke_MainPaneOverlays", false);
        string directory = Path.GetDirectoryName(outputPath)!;
        string inputPath = Path.Combine(directory, "Main_overlay_owned_640x360.png");
        using (Bitmap image = new(640, 360)) { using Graphics graphics = Graphics.FromImage(image); graphics.Clear(DrawingColor.Teal); image.Save(inputPath, ImageFormat.Png); }
        List<object> cases = new();
        return CaptureWindowWithContent(host, outputPath, width, height, () =>
        {
            if (!host.LoadMainImageFromFileForTest(inputPath)) throw new InvalidOperationException("Overlay input setup failed.");
            VisionPipelineStep step = new() { Name = "Overlay example", ToolType = "Threshold", InputLayer = "Main", OutputLayer = "Overlay_Output", Enabled = true, UseAcceptance = true };
            step.Parameters["USE_ROI"] = "true"; step.Parameters["CvROI"] = "40,30,120,80";
            if (host.Workbench.Pipeline.InsertStep(0, step) == null) throw new InvalidOperationException("Overlay step setup failed.");
            using Bitmap sourceImage = new(inputPath);
            if (!host.AddLayerImageForTest(step.OutputLayer, sourceImage)) throw new InvalidOperationException("Overlay output setup failed.");
            VisionToolOverlay[] geometries = { new() { Kind = VisionToolOverlayKind.Rectangle, Bounds = new System.Drawing.RectangleF(180, 90, 100, 60), Label = "Object A" },
                new() { Kind = VisionToolOverlayKind.Line, Start = new System.Drawing.PointF(80, 220), End = new System.Drawing.PointF(400, 220), Label = "Datum" },
                new() { Kind = VisionToolOverlayKind.Point, Center = new System.Drawing.PointF(320, 120), Label = "Center" } };
            using VisionToolResult toolResult = VisionToolResult.Passed(new OpenCvSharp.Mat(360, 640, OpenCvSharp.MatType.CV_8UC3, new OpenCvSharp.Scalar(128, 128, 0)), TimeSpan.Zero, new Dictionary<string, double>(), geometries);
            VisionPipelineStepResultSummary summary = VisionPipelineResultSummaryService.CreateStepSummary(1, new VisionPipelineStepResult { Step = step, ToolResult = toolResult, AcceptancePassed = true });
            geometries[0].Label = "mutated source";
            if (summary.Overlays[0].Label != "Object A" || ReferenceEquals(summary.Overlays[0], geometries[0])) throw new InvalidOperationException("Result summary did not isolate source overlay geometry.");
            if (JsonSerializer.Serialize(summary).Contains("\"Overlays\"", StringComparison.Ordinal)) throw new InvalidOperationException("Display geometry changed the summary JSON contract.");
            host.Workbench.Pipeline.PublishToolResult(0, summary); host.Workbench.Pipeline.SelectedStepIndex = 0; Pump(8);
            var model = host.Workbench.Viewer;
            var input = model.Panes[0]; var output = model.Panes[1];
            OpenVisionLayerViewerView InputView() => FindVisualChildren<OpenVisionLayerViewerView>(host).Single(view => view.MainPane?.Id == input.Id);
            OpenVisionLayerViewerView OutputView() => FindVisualChildren<OpenVisionLayerViewerView>(host).Single(view => view.MainPane?.Id == output.Id);
            int runs = host.NativePreviewRunCount, layers = host.LayerDocumentCount;
            string route = host.WorkspaceLayerTitle;
            byte[] working = VisionPipelineExecutionPlan.SerializePipeline(host.Workbench.Pipeline.WorkingCopyForTest);
            OpenVisionLanguage initial = OpenVisionLanguageService.CurrentLanguage;
            foreach (string paletteName in new[] { "Dark", "Light" })
            {
                ResourceDictionary palette = new() { Source = new Uri($"/OpenVisionLab;component/UI/Wpf/OpenVisionWorkbench{paletteName}.xaml", UriKind.Relative) };
                host.Resources.MergedDictionaries.Add(palette);
                try
                {
                    foreach (OpenVisionLanguage language in new[] { OpenVisionLanguage.Korean, OpenVisionLanguage.English })
                    {
                        OpenVisionLanguageService.SetLanguage(language, false); Pump(4);
                        model.IsOverlayVisible = model.IsRoiVisible = true; InputView().ShowOriginalSize(); InputView().ZoomImage(1.5D); InputView().PanImageByForTest(17D, -9D); Pump(6);
                        Canvas canvas = FindNamedVisualChild<Canvas>(InputView(), "mainDisplayOverlays")!;
                        System.Windows.Shapes.Rectangle roi = canvas.Children.OfType<System.Windows.Shapes.Rectangle>().Single();
                        if (Math.Abs(roi.Width - 180D) > 0.000001D || roi.StrokeDashArray?.Count != 2 || OutputView().DisplayOverlayVisualCountForTest < 7) throw new InvalidOperationException("ROI/result geometry or source-pixel mapping failed.");
                        model.ToggleOverlayCommand.Execute(null); Pump(4);
                        if (OutputView().DisplayOverlayVisualCountForTest != 0 || InputView().DisplayOverlayVisualCountForTest != 2) throw new InvalidOperationException("Overlay toggle changed holder ROI visibility.");
                        model.ToggleRoiCommand.Execute(null); Pump(4);
                        if (InputView().DisplayOverlayVisualCountForTest != 0) throw new InvalidOperationException("ROI toggle did not hide holder regions.");
                        model.ToggleOverlayCommand.Execute(null); model.ToggleRoiCommand.Execute(null); Pump(4);
                        InputView().FitImageToView(); Pump(4);
                        string capture = Path.Combine(directory, Path.GetFileNameWithoutExtension(outputPath) + "." + paletteName + "." + language + ".png");
                        ScreenshotPngWriter.WriteElementPng(host, capture, width, height);
                        foreach (OpenVisionLayerViewerView overlayView in new[] { InputView(), OutputView() })
                        {
                            Canvas renderedCanvas = FindNamedVisualChild<Canvas>(overlayView, "mainDisplayOverlays")!;
                            foreach (System.Windows.Shapes.Rectangle rectangle in renderedCanvas.Children.OfType<System.Windows.Shapes.Rectangle>())
                            {
                                System.Windows.Point edge = rectangle.TranslatePoint(new System.Windows.Point(), host);
                                bool hasStrokePixel = false;
                                using (Bitmap captured = new(capture))
                                {
                                    for (int x = Math.Max(0, (int)Math.Floor(edge.X)); x <= Math.Min(captured.Width - 1, (int)Math.Ceiling(edge.X + rectangle.StrokeThickness)); x++)
                                        for (int y = Math.Max(0, (int)Math.Ceiling(edge.Y + 2D)); y < Math.Min(captured.Height, (int)Math.Floor(edge.Y + rectangle.Height - 2D)); y++)
                                            hasStrokePixel |= captured.GetPixel(x, y).R > 0;
                                }
                                var rectangleState = new { Palette = paletteName, Language = language.ToString(), Pane = overlayView.MainPane.Id, Width = rectangle.Width, Height = rectangle.Height, RenderSize = rectangle.RenderSize.ToString(), Geometry = rectangle.RenderedGeometry.Bounds.ToString(), Stroke = rectangle.Stroke?.ToString(), Visible = rectangle.IsVisible, Opacity = rectangle.Opacity, HasStrokePixel = hasStrokePixel, Probe = "Left edge interior; uniform owned teal R=0, semantic rectangle strokes R>0; no invented tolerance" };
                                File.AppendAllText(Path.Combine(directory, "rectangle-render-observations.jsonl"), JsonSerializer.Serialize(rectangleState) + Environment.NewLine);
                                if (rectangle.RenderSize.Width <= 0D || rectangle.RenderSize.Height <= 0D || rectangle.RenderedGeometry.Bounds.IsEmpty || rectangle.RenderedGeometry.Bounds.Width <= 0D || rectangle.RenderedGeometry.Bounds.Height <= 0D || rectangle.Stroke == null || !hasStrokePixel)
                                    throw new InvalidOperationException("Main overlay rectangle is not rendered after Fit/locale capture: " + JsonSerializer.Serialize(rectangleState));
                            }
                        }
                        cases.Add(new { Palette = paletteName, Language = language.ToString(), SourceClone = true, Toggles = true, MappedRoiWidth = roi.Width, RenderedRectangles = true, Capture = capture });
                    }
                }
                finally { host.Resources.MergedDictionaries.Remove(palette); }
            }
            OpenVisionLanguageService.SetLanguage(initial, false); Pump(4);
            Window ownerWindow = Window.GetWindow(host);
            ownerWindow.Width = 1536D; ownerWindow.Height = 826D;
            model.SingleCommand.Execute(null); Pump(6);
            foreach (string paletteName in new[] { "Dark", "Light" })
            {
                ResourceDictionary palette = new() { Source = new Uri($"/OpenVisionLab;component/UI/Wpf/OpenVisionWorkbench{paletteName}.xaml", UriKind.Relative) };
                host.Resources.MergedDictionaries.Add(palette);
                try
                {
                    foreach (string source in new[] { "follow:in", "follow:out" })
                    {
                        OpenVisionWorkbenchViewerPane pane = model.Panes[0]; pane.Source = source; Pump(5);
                        OpenVisionLayerViewerView view = FindVisualChildren<OpenVisionLayerViewerView>(host).Single(item => item.MainPane?.Id == pane.Id);
                        Image image = FindNamedVisualChild<Image>(view, "layerFallbackImage")!;
                        Grid surface = FindNamedVisualChild<Grid>(view, "layerImageSurface")!;
                        Canvas canvas = FindNamedVisualChild<Canvas>(view, "mainDisplayOverlays")!;
                        view.ShowOriginalSize(); view.PanImageByForTest(17D, -9D); Pump(5);
                        Size imageSize = image.RenderSize; double expandedWidth = surface.ActualWidth;
                        Point expandedOrigin = image.TranslatePoint(new Point(), surface);
                        OpenVisionImageViewport? viewport = view.ViewportForTest;
                        string pixels; using (Bitmap beforeImage = view.CloneImageForTest()) { pixels = ComputeStreamingBitmapSha256(beforeImage); }
                        VisionToolOverlay geometry = pane.Overlays.Single(item => item.Shape.Kind == VisionToolOverlayKind.Rectangle).Shape;
                        System.Drawing.RectangleF expectedBounds = source == "follow:in" ? new(40, 30, 120, 80) : new(180, 90, 100, 60);
                        if (geometry.Bounds != expectedBounds) throw new InvalidOperationException("Parent-only overlay geometry differs from the owned ROI/result fixture.");
                        Point Expected(double x, double y)
                        {
                            BitmapSource bitmap = (BitmapSource)image.Source;
                            double fit = Math.Min(image.ActualWidth / bitmap.PixelWidth, image.ActualHeight / bitmap.PixelHeight);
                            Point local = new((image.ActualWidth - bitmap.PixelWidth * fit) / 2D + x * fit, (image.ActualHeight - bitmap.PixelHeight * fit) / 2D + y * fit);
                            return image.TransformToVisual(canvas).Transform(local);
                        }
                        foreach (string phase in new[] { "expanded", "collapsed", "reexpanded" })
                        {
                            if (phase != "expanded") { host.Workbench.ToggleRightPanelCommand.Execute(null); Pump(6); }
                            OpenVisionImageViewport? currentViewport = view.ViewportForTest;
                            bool sameViewport = viewport.HasValue && currentViewport.HasValue && viewport.Value.Fit == currentViewport.Value.Fit
                                && Math.Abs(viewport.Value.Scale - currentViewport.Value.Scale) <= 1e-12D
                                && Math.Abs(viewport.Value.CenterX - currentViewport.Value.CenterX) <= 1e-12D
                                && Math.Abs(viewport.Value.CenterY - currentViewport.Value.CenterY) <= 1e-12D;
                            if (image.RenderSize != imageSize || !sameViewport)
                                throw new InvalidOperationException("Parent-only overlay case changed image RenderSize/viewport instead of testing the centered origin: " + JsonSerializer.Serialize(new { source, phase, ExpectedWidth = imageSize.Width, ExpectedHeight = imageSize.Height, ActualWidth = image.RenderSize.Width, ActualHeight = image.RenderSize.Height, ExpectedViewport = viewport, ActualViewport = view.ViewportForTest, SurfaceWidth = surface.ActualWidth, SurfaceHeight = surface.ActualHeight }));
                            if (phase == "collapsed" && (surface.ActualWidth == expandedWidth || image.TranslatePoint(new Point(), surface) == expandedOrigin))
                                throw new InvalidOperationException("Parent-only overlay case did not change the surface width and centered image origin.");
                            System.Windows.Shapes.Rectangle rectangle = canvas.Children.OfType<System.Windows.Shapes.Rectangle>().Single();
                            Point start = Expected(expectedBounds.Left, expectedBounds.Top), end = Expected(expectedBounds.Right, expectedBounds.Bottom);
                            if (Math.Abs(Canvas.GetLeft(rectangle) - Math.Min(start.X, end.X)) > 0.000001D
                                || Math.Abs(Canvas.GetTop(rectangle) - Math.Min(start.Y, end.Y)) > 0.000001D
                                || Math.Abs(rectangle.Width - Math.Abs(end.X - start.X)) > 0.000001D
                                || Math.Abs(rectangle.Height - Math.Abs(end.Y - start.Y)) > 0.000001D)
                                throw new InvalidOperationException("Parent-only ROI/result does not match independently mapped fixture coordinates.");
                            string capture = Path.Combine(directory, "parent-surface-" + paletteName + "-" + source.Replace(':', '-') + "-" + phase + ".png");
                            ScreenshotPngWriter.WriteElementPng(host, capture, (int)Math.Ceiling(host.ActualWidth), (int)Math.Ceiling(host.ActualHeight));
                            Point edge = canvas.TranslatePoint(start, host); bool strokePixel = false;
                            using (Bitmap captured = new(capture))
                            {
                                for (int x = Math.Max(0, (int)Math.Floor(edge.X - rectangle.StrokeThickness / 2D)); x <= Math.Min(captured.Width - 1, (int)Math.Ceiling(edge.X + rectangle.StrokeThickness / 2D)); x++)
                                    for (int y = Math.Max(0, (int)Math.Ceiling(edge.Y + 2D)); y < Math.Min(captured.Height, (int)Math.Floor(edge.Y + rectangle.Height - 2D)); y++)
                                        strokePixel |= captured.GetPixel(x, y).R > 0;
                                int interiorX = (int)Math.Round(edge.X + 6D), interiorY = (int)Math.Round(edge.Y + rectangle.Height / 2D);
                                if (!strokePixel || captured.GetPixel(interiorX, interiorY).R != 0)
                                    throw new InvalidOperationException("Parent-only expected source-coordinate edge has no stroke pixels or adjacent owned teal image is missing.");
                            }
                            using Bitmap afterImage = view.CloneImageForTest();
                            if (pixels != ComputeStreamingBitmapSha256(afterImage)) throw new InvalidOperationException("Parent-size overlay refresh changed source pixels.");
                            cases.Add(new { Palette = paletteName, Source = source, ParentOnlyPhase = phase, ImageSize = imageSize.ToString(), SurfaceWidth = surface.ActualWidth, ImageOrigin = image.TranslatePoint(new Point(), surface).ToString(), ExpectedStart = start.ToString(), ExpectedEnd = end.ToString(), ActualX = Canvas.GetLeft(rectangle), ActualY = Canvas.GetTop(rectangle), rectangle.Width, rectangle.Height, IndependentImageTransform = true, StrokePixel = strokePixel, PixelHash = pixels, Capture = capture });
                        }
                    }
                }
                finally { host.Resources.MergedDictionaries.Remove(palette); }
            }
            ownerWindow.Width = width; ownerWindow.Height = height; host.Workbench.IsBottomCollapsed = false; model.Split2Command.Execute(null); Pump(6);
            output.SnapshotCommand.Execute(null); Pump(4);
            string snapshot = output.Source;
            summary.Overlays[0].Label = "changed later"; host.Workbench.Pipeline.PublishToolResult(0, summary); Pump(4);
            if (output.Overlays[0].Shape.Label != "Object A") throw new InvalidOperationException("Snapshot overlay metadata changed with a later result.");
            output.OpenCommand.Execute(null); Pump(8);
            Window snapshotWindow = Application.Current.Windows.OfType<OpenVisionFloatingToolWindow>().Single(window => window.IsVisible && window.HostedContent is OpenVisionLayerViewerView view && view.Tag == null);
            OpenVisionLayerViewerView detached = (OpenVisionLayerViewerView)((OpenVisionFloatingToolWindow)snapshotWindow).HostedContent;
            if (detached.DisplayOverlayVisualCountForTest < 7) throw new InvalidOperationException("Snapshot window lost frozen display geometry.");
            ScreenshotPngWriter.WriteElementPng(snapshotWindow, Path.Combine(directory, "snapshot-overlay-window.png"), 820, 600);
            snapshotWindow.Close(); Pump(4);
            model.Split4Command.Execute(null); Pump(6);
            var final = model.Panes[3];
            if (final.Source != "final" || final.Overlays.Count != 3) throw new InvalidOperationException("Final pane did not show existing judged-step overlays.");
            if (host.NativePreviewRunCount != runs || host.LayerDocumentCount != layers || host.WorkspaceLayerTitle != route || !working.SequenceEqual(VisionPipelineExecutionPlan.SerializePipeline(host.Workbench.Pipeline.WorkingCopyForTest))) throw new InvalidOperationException("Display controls changed inspection, layers, route or working XML.");
            File.WriteAllText(Path.ChangeExtension(outputPath, ".overlay-cases.json"), JsonSerializer.Serialize(new { Cases = cases, FrozenSnapshot = snapshot, FinalJudgedProjection = true, NoImplicitRun = true, NoRecipeChange = true,
                ProductSHA256 = Convert.ToHexString(SHA256.HashData(File.ReadAllBytes(typeof(OpenVisionShellHostView).Assembly.Location))), Scope = "Synthetic result display only; no algorithm execution/native pointer/DPI/full Main96 proof" }, new JsonSerializerOptions { WriteIndented = true }));
        });
    }



    private static CaptureResult CaptureMainStopAction(string outputPath, int width, int height)
    {
        string recipe = "Smoke_MainStopAction_" + width;
        OpenVisionShellHostView host = CreateShellHost(recipe, false);
        VisionPipeline source = new() { Name = "Pipeline_Stop" };
        source.Steps.Add(VisionPipelineStepBuilder.FromThresholdProperty(new ThresholdToolProperty { Threshold = 112, MaxValue = 255 }, "Threshold_1", "Main", "Threshold_1"));
        source.Steps.Add(VisionPipelineStepBuilder.FromProperty(new MeanProperty { NAME = "Mean_1", USE_ROI = false, MEAN_MIN = 0, MEAN_MAX = 255 }, "Threshold_1", "Mean_1"));
        VisionPipelineStorage.Save(recipe, source); VisionPipelineStorage.SaveActivePipelineName(recipe, source.Name);
        host.RecipeCommands.RefreshOptions(); host.RecipeCommands.SelectedPipelineOption = host.RecipeCommands.PipelineOptions.Single(option => option.PipelineName == source.Name);
        string input = Path.ChangeExtension(outputPath, ".input.png"); using (Bitmap image = new(640, 360)) { using Graphics graphics = Graphics.FromImage(image); graphics.Clear(DrawingColor.Teal); image.Save(input, ImageFormat.Png); }
        List<object> cases = new(); void Record(object value) { cases.Add(value); File.WriteAllText(Path.ChangeExtension(outputPath, ".cases.json"), JsonSerializer.Serialize(cases)); }
        bool before = Environment.GetEnvironmentVariable("OPENVISIONLAB_STOP_BEFORE") == "1";
        return CaptureWindowWithContent(host, outputPath, width, height, () =>
        {
            void Require(bool value, string message) { if (!value) throw new InvalidOperationException("Main stop action: " + message); }
            OpenVisionWorkbenchPipelineViewModel model = host.Workbench.Pipeline; OpenVisionWorkbenchViewModel root = host.Workbench;
            Button stop = FindVisualChildren<Button>(host).Single(item => AutomationProperties.GetAutomationId(item) == "MainStopRun");
            TextBlock status = FindVisualChildren<TextBlock>(host).Single(item => AutomationProperties.GetAutomationId(item) == "WorkbenchActionStatus");
            var icon = FindVisualChildren<MahApps.Metro.IconPacks.PackIconMaterial>(host).Single(item => AutomationProperties.GetAutomationId(item) == "WorkbenchActionIcon");
            Require(ReferenceEquals(stop.Command, model.StopCommand) && BindingOperations.IsDataBound(stop, Button.CommandProperty), "same actual stop binding");
            string idle = root.MainActionText; Require(!stop.IsEnabled && !model.StopCommand.CanExecute(null), "noinput stop disabled"); model.RefreshInputState(); Require(root.MainActionText == idle, "noinput refresh no writer");
            Require(host.LoadMainImageFromFileForTest(input), "owned input load"); Pump(6);
            foreach (var state in Environment.GetEnvironmentVariable("OPENVISIONLAB_STOP_NATIVE_ONLY") == "1" ? Array.Empty<(string, OpenVisionLanguage, bool)>() : before ? new[] { ("Dark", OpenVisionLanguage.Korean, false), ("Dark", OpenVisionLanguage.Korean, true) } : new[] { ("Dark", OpenVisionLanguage.Korean, false), ("Dark", OpenVisionLanguage.English, true), ("Light", OpenVisionLanguage.Korean, true), ("Light", OpenVisionLanguage.English, false) })
            {
                (state.Item1 == "Dark" ? root.SelectDarkThemeCommand : root.SelectLightThemeCommand).Execute(null); OpenVisionLanguageService.SetLanguage(state.Item2, false); model.SelectedRow = model.Rows[0]; Pump(3);
                bool requested = false; int stopWrites = 0, starts = 0; string pending = ""; bool duplicateRunBlocked = false; string expected = state.Item2 == OpenVisionLanguage.Korean ? "현재 이미지 처리 후 중지…" : "Stopping after the current image…";
                byte[] working = VisionPipelineExecutionPlan.SerializePipeline(model.WorkingCopyForTest); string xmlHash = Convert.ToHexString(SHA256.HashData(File.ReadAllBytes(RecipeWorkspaceService.GetVisionPipelinePath(recipe, source.Name))));
                PropertyChangedEventHandler observe = (_, e) =>
                {
                    if (e.PropertyName != nameof(OpenVisionWorkbenchViewModel.MainActionText)) return;
                    if (root.MainActionText == expected) stopWrites++;
                    if (requested || !model.IsSingleRunning || root.MainActionKind != "Running") return;
                    requested = true; starts++; Require(model.StopCommand.CanExecute(null), "first stop enabled"); duplicateRunBlocked = model.RunForTestAsync(state.Item3).IsCompleted;
                    model.StopCommand.Execute(null); pending = root.MainActionText; host.UpdateLayout();
                    string png = Path.ChangeExtension(outputPath, $".{state.Item1}-{state.Item2}-{(state.Item3 ? "prefix" : "full")}-pending.png"); ScreenshotPngWriter.WriteElementPng(host, png, width, height);
                    Record(new { Case = "actual-stop-pending", Theme = state.Item1, Locale = state.Item2.ToString(), Prefix = state.Item3, Pending = pending, Kind = root.MainActionKind, Expected = expected, StopCanExecute = model.StopCommand.CanExecute(null), ButtonEnabled = stop.IsEnabled, Text = status.Text, Icon = icon.Kind.ToString(), PNG = png, Boundary = "actual owner Run start then public Stop; deterministic before worker, no product hook/delay" });
                    Require(!model.StopCommand.CanExecute(null) && !stop.IsEnabled, "repeat Stop disabled actual binding"); model.RefreshInputState(); Require(root.MainActionText == pending, "ordinary refresh retains pending");
                    if (!before)
                    {
                        Require(pending == expected && status.IsVisible && status.Text == expected && root.MainActionKind == "Warning" && BindingOperations.IsDataBound(status, TextBlock.TextProperty) && (string)status.ToolTip == expected, "actual visible stop sentence and tooltip");
                        Record(new { Case = "pending-semantic-colors", Icon = icon.Kind.ToString(), IconColor = ((SolidColorBrush)icon.Foreground).Color.ToString(), ExpectedIconColor = ((SolidColorBrush)host.FindResource("OpenVision.Workbench.StaleBrush")).Color.ToString(), SentenceColor = ((SolidColorBrush)status.Foreground).Color.ToString(), ExpectedSentenceColor = ((SolidColorBrush)host.FindResource("OpenVision.Workbench.SecondaryTextBrush")).Color.ToString() });
                        Require(icon.Kind.ToString() == "AlertOutline" && ((SolidColorBrush)icon.Foreground).Color == ((SolidColorBrush)host.FindResource("OpenVision.Workbench.StaleBrush")).Color && ((SolidColorBrush)status.Foreground).Color == ((SolidColorBrush)host.FindResource("OpenVision.Workbench.SecondaryTextBrush")).Color, "Warning icon and neutral sentence");
                        Rect text = GetElementBounds(host, status), image = GetElementBounds(host, icon); Require(text.Width > 0 && text.Left >= image.Right && text.Right <= host.ActualWidth + .1, "pending within existing action bounds");
                    }
                };
                root.PropertyChanged += observe; try { WaitForTaskWithPump(model.RunForTestAsync(state.Item3), 12000, "actual run and Stop"); } finally { root.PropertyChanged -= observe; }
                Require(requested && starts == 1 && duplicateRunBlocked && !model.IsRunning && !model.StopCommand.CanExecute(null), "one Stop and normal completed recovery");
                Require(working.SequenceEqual(VisionPipelineExecutionPlan.SerializePipeline(model.WorkingCopyForTest)) && xmlHash == Convert.ToHexString(SHA256.HashData(File.ReadAllBytes(RecipeWorkspaceService.GetVisionPipelinePath(recipe, source.Name)))) && host.NativePreviewRunCount == 0, "working/saved/Preview no policy changes");
                string final = root.MainActionText; Require(final.Contains(state.Item3 ? (state.Item2 == OpenVisionLanguage.Korean ? "이 단계까지 실행 완료" : "Run to here completed") : (state.Item2 == OpenVisionLanguage.Korean ? "파이프라인 실행 완료" : "Pipeline run completed")), "FLOW terminal replaces stop"); model.RefreshInputState(); Require(root.MainActionText == final && !stop.IsEnabled, "idle refresh no pending replay");
                if (!before) Require(stopWrites == 1, "single transition notification; normal progress no replay");
                Record(new { Case = "actual-stop-completed", Prefix = state.Item3, StopWrites = stopWrites, Starts = starts, Final = final, Global = model.VerdictKind, Previous = model.IsVerdictPrevious, NativePreviewRuns = host.NativePreviewRunCount, InputSHA = Convert.ToHexString(SHA256.HashData(File.ReadAllBytes(input))), WorkingSavedUnchanged = true });
            }
            if (!before && width == 1600 && Environment.GetEnvironmentVariable("OPENVISIONLAB_STOP_NATIVE_ONLY") == "1")
            {
                VisionPipeline native = new() { Name = "Pipeline_Stop_Native" };
                native.Steps.Add(VisionPipelineStepBuilder.FromThresholdProperty(new ThresholdToolProperty { Threshold = 112, MaxValue = 255 }, "Threshold_Native", "Main", "Threshold_Native"));
                for (int index = 0; index < 16; index++) native.Steps.Add(VisionPipelineStepBuilder.FromFilterProperty(new FilterToolProperty { FilterType = FilterToolType.GaussianBlur, KernelWidth = 201, KernelHeight = 201 }, "Filter_" + (index + 1), index == 0 ? "Threshold_Native" : "Filter_" + index, "Filter_" + (index + 1)));
                VisionPipelineStorage.Save(recipe, native); VisionPipelineStorage.SaveActivePipelineName(recipe, native.Name); host.RecipeCommands.RefreshOptions(); host.RecipeCommands.SelectedPipelineOption = host.RecipeCommands.PipelineOptions.Single(option => option.PipelineName == native.Name);
                string largeInput = Path.ChangeExtension(outputPath, ".native-input.png");
                using (Bitmap large = new(2048, 1024)) { using Graphics graphics = Graphics.FromImage(large); graphics.Clear(DrawingColor.Teal); for (int index = 0; index < 80; index++) { using System.Drawing.SolidBrush brush = new(DrawingColor.FromArgb((index * 41) % 255, (index * 23) % 255, (index * 17) % 255)); graphics.FillRectangle(brush, index * 25, index % 3 * 140, 12, 850); } large.Save(largeInput, ImageFormat.Png); }
                Require(host.LoadMainImageFromFileForTest(largeInput), "bounded native seed input load"); Pump(5); Stopwatch timer = Stopwatch.StartNew(); WaitForTaskWithPump(model.RunForTestAsync(), 60000, "normal supported bounded native workload"); timer.Stop();
                Record(new { Case = "native-seed-before-assert", Completed = model.SingleRunCompleted, Kind = model.SingleRunResultKind, Status = model.StatusText, Verdict = model.VerdictValue, Rows = model.Rows.Select(row => new { row.Name, row.StatusText }).ToArray(), ExpectedDone = OpenVisionLanguageService.T("Workbench.Status.Done"), Summaries = ((Dictionary<int, VisionPipelineStepResultSummary>)typeof(OpenVisionWorkbenchPipelineViewModel).GetField("results", BindingFlags.Instance | BindingFlags.NonPublic)!.GetValue(model)!).Select(item => new { item.Key, item.Value.Success, item.Value.IsAcceptanceNg, item.Value.Message, item.Value.ErrorName, item.Value.Executed }).ToArray(), ObservedMilliseconds = timer.Elapsed.TotalMilliseconds });
                Require(model.SingleRunCompleted && model.SingleRunResultKind == "NoVerdict" && model.Rows.All(row => row.StatusText == OpenVisionLanguageService.T("Workbench.Status.Done")), "bounded native seed executes normally without acceptance judgment");
                Record(new { Case = "native-seed-workload", Recipe = recipe, Pipeline = native.Name, PipelineXml = RecipeWorkspaceService.GetVisionPipelinePath(recipe, native.Name), Input = largeInput, ImageWidth = 2048, ImageHeight = 1024, Tool = "Threshold+GaussianBlur", Steps = native.Steps.Count, Kernel = 201, ObservedMilliseconds = timer.Elapsed.TotalMilliseconds, WallMilliseconds = (double)typeof(OpenVisionWorkbenchPipelineViewModel).GetField("lastRunMilliseconds", BindingFlags.Instance | BindingFlags.NonPublic)!.GetValue(model)!, Kind = model.SingleRunResultKind, Boundary = "actual supported tool run, no delay/hook; native Stop interaction still Astra-only" });
            }
            if (before) throw new InvalidOperationException("Before mismatch: full/prefix Stop retains Running instead of Stopping.");
        });
    }

    private static void AssertMainNImageEngine(string outputPath, IReadOnlyList<string> paths)
    {
        string directory = Path.ChangeExtension(outputPath, ".engine"); Directory.CreateDirectory(directory);
        List<object> records = new();
        void Require(bool value, string message) { if (!value) throw new InvalidOperationException("N-image engine: " + message); }
        void Record(object value) { records.Add(value); File.WriteAllText(Path.Combine(directory, "checks.json"), JsonSerializer.Serialize(records, new JsonSerializerOptions { WriteIndented = true })); }
        var mean = VisionPipelineStepBuilder.FromProperty(new MeanProperty { NAME = "Target", USE_ROI = false, USE_THRESHOLD = false, USE_BITWISENOT = false, MEAN_MIN = 0, MEAN_MAX = 255 }, "Main", "Mean");
        var standalone = Task.Run(() => VisionToolNImageVerificationService.RunAsync("Mean", "Smoke_MainN_Standalone", () => VisionPipelineStepEditService.CopyStep(mean), true, paths.Take(1).ToArray(), null, CancellationToken.None)).GetAwaiter().GetResult();
        var originalReport = VisionPipelineRunReportStorage.Load(standalone.Rows.Single().RunReportPath);
        Require(originalReport.Steps.Count == 1 && originalReport.Steps[0].Metrics.Single(metric => metric.Name == VisionPipelineKnownMetrics.MeanValueAvg).Value == 180, "standalone original single-step pixel 180 and normal history");
        Record(new { Case = "standalone-compatible", Mean = 180, Rows = standalone.Rows.Count, Report = standalone.Rows[0].RunReportPath });
        VisionToolNImageVerificationSession Run(string id, VisionPipeline pipeline)
        {
            var result = Task.Run(() => VisionToolNImageVerificationService.RunAsync("Mean", "Smoke_MainN_Engine", () => mean, true, paths.Take(1).ToArray(), null, CancellationToken.None, pipeline, Path.Combine(directory, id))).GetAwaiter().GetResult();
            Record(new { Case = id, result.PrefixCount, result.StepDefinitionSha256, Rows = result.Rows.Select(row => new { row.Status, row.Message, row.MetricText, row.RunReportPath, row.FailedStep }).ToArray(), result.BatchSummaryPath });
            return result;
        }
        var threshold = VisionPipelineStepBuilder.FromThresholdProperty(new ThresholdToolProperty { Threshold = 100, MaxValue = 255 }, "Binary", "Main", "Binary");
        var pipeline = new VisionPipeline { Name = "Owned" }; pipeline.Steps.Add(threshold); var target = VisionPipelineStepEditService.CopyStep(mean); target.InputLayer = "Binary"; target.UseAcceptance = true; target.AcceptanceMetricName = VisionPipelineKnownMetrics.MeanValueAvg; target.UseAcceptanceMetricMaximum = true; target.AcceptanceMetricMaximum = 200; pipeline.Steps.Add(target);
        var ng = Run("target-gate-preserved", pipeline); Require(ng.Rows.Single().IsNg && !ng.Rows.Single().IsError, "target acceptance NG remains NG after prefix");
        var error = VisionPipelineStepEditService.Copy(pipeline); error.Steps[0] = VisionPipelineStepBuilder.FromProperty(new MatchingProperty("MissingPrefix") { PATTERN_PATH = Path.Combine(directory, "missing-template.png"), USE_ROI = false }, "Main", "Binary");
        var failed = Run("prefix-tool-error", error); var report = VisionPipelineRunReportStorage.Load(failed.Rows[0].RunReportPath);
        Require(failed.Rows.Single().IsError && failed.Rows.Single().Message.StartsWith("Prefix execution failed.") && report.Steps.Last().Executed == false, "prefix error distinguished target not fabricated");
        var retry = Run("error-valid-recovery", pipeline); Require(retry.Rows.Single().IsNg, "error recovery valid result");
        string export = Path.Combine(directory, "export.html");
        Require(VisionToolNImageVerificationHtmlReportExporter.TryExport(retry.BatchSummaryPath, retry.PipelineXml, retry.StepDefinitionSha256, export, OpenVisionLanguage.English, out string exportError), "existing exporter: " + exportError);
        Require(File.Exists(export) && File.ReadAllText(export).Contains("Mean"), "existing export retains transient result"); Record(new { Case = "transient-export", Path = export });
        var native = VisionPipelineStepEditService.Copy(pipeline); native.Name = "MainNPrefix"; native.Steps[0].Name = "Threshold_Predecessor";
        native.Steps[0].UseAcceptance = true; native.Steps[0].AcceptanceMetricName = VisionPipelineKnownMetrics.ResultImageWidth; native.Steps[0].UseAcceptanceMetricMaximum = true; native.Steps[0].AcceptanceMetricMaximum = 1;
        native.Steps[1].UseAcceptance = false; native.Steps[1].Name = "Mean_Target"; native.Steps[1].OutputLayer = "Mean_Output";
        File.WriteAllBytes(Path.ChangeExtension(outputPath, ".native-Pipeline.xml"), VisionPipelineExecutionPlan.SerializePipeline(native));
    }

    private static CaptureResult CaptureMainNImageBefore(string outputPath)
    {
        OpenVisionShellHostView host = CreateShellHost("Smoke_MainNBefore", false);
        string imagePath = Path.ChangeExtension(outputPath, ".input.png");
        using (Bitmap bitmap = new(64, 40)) { using Graphics graphics = Graphics.FromImage(bitmap); graphics.Clear(DrawingColor.FromArgb(180, 180, 180)); bitmap.Save(imagePath, ImageFormat.Png); }
