                ScreenshotPngWriter.WriteElementPng(window, Path.ChangeExtension(outputPath, ".before-modal.png"), (int)window.ActualWidth, (int)window.ActualHeight);
                window.Close();
            }));
            button.RaiseEvent(new RoutedEventArgs(Button.ClickEvent));
        });
    }

    private static void AssertMainNImageAuxExport(string outputPath, string recipe, IReadOnlyList<string> paths, Action<bool, string> Require, Action<object> Record)
    {
        var auxPlan = new VisionPipeline { Name = "AuxSnapshot" };
        auxPlan.Steps.Add(VisionPipelineStepBuilder.FromArithmetic("AuxMix", "Bitwise_AND", "Main", "Aux_B", "Mixed", false, false, 0, 0, 0, 0, 0, 0));
        auxPlan.Steps.Add(VisionPipelineStepBuilder.FromProperty(new MeanProperty { NAME = "AuxMean", USE_ROI = false, USE_THRESHOLD = false }, "Mixed", "NImageResult"));
        string aux = Path.ChangeExtension(outputPath, ".aux-fixed.png");
        using (Bitmap input = new(paths[0]))
        using (Bitmap bitmap = new(input.Width, input.Height)) { using Graphics graphics = Graphics.FromImage(bitmap); graphics.Clear(DrawingColor.FromArgb(128, 128, 128)); bitmap.Save(aux, ImageFormat.Png); }
        string auxSha = Convert.ToHexString(SHA256.HashData(File.ReadAllBytes(aux)));
        var auxPaths = new Dictionary<string, string> { ["Aux_B"] = aux };
        var auxSession = Task.Run(() => VisionToolNImageVerificationService.RunAsync("Mean", recipe, () => auxPlan.Steps.Last(), true, paths.Take(2).ToArray(), null, CancellationToken.None, auxPlan, Path.ChangeExtension(outputPath, ".aux-evidence"), inputSnapshots: auxPaths)).GetAwaiter().GetResult();
        double[] auxMeans = auxSession.Rows.Select(row => VisionPipelineRunReportStorage.Load(row.RunReportPath).Steps.Last().Metrics.Single(metric => metric.Name == VisionPipelineKnownMetrics.MeanValueAvg).Value).ToArray();
        Require(auxMeans.SequenceEqual(new[] { 128D, 0D }) && auxSha == Convert.ToHexString(SHA256.HashData(File.ReadAllBytes(aux))) && auxSession.AdditionalInputSha256["Aux_B"] == auxSha, "fixed Aux B independent per-image values and source SHA unchanged");
        string auxHtml = Path.ChangeExtension(outputPath, ".aux-report.html");
        Require(VisionToolNImageVerificationHtmlReportExporter.TryExport(auxSession.BatchSummaryPath, auxSession.PipelineXml, auxSession.StepDefinitionSha256, auxHtml, OpenVisionLanguage.English, out string auxError, auxSession.AdditionalInputPaths, auxSession.AdditionalInputSha256) && File.ReadAllText(auxHtml).Contains(auxSha) && File.ReadAllText(auxHtml).Contains(Convert.ToBase64String(File.ReadAllBytes(aux))), "Aux frozen evidence exported: " + auxError);
        File.AppendAllText(aux, "owned tamper");
        Require(!VisionToolNImageVerificationHtmlReportExporter.TryExport(auxSession.BatchSummaryPath, auxSession.PipelineXml, auxSession.StepDefinitionSha256, auxHtml + ".invalid.html", OpenVisionLanguage.English, out string auxFailure, auxSession.AdditionalInputPaths, auxSession.AdditionalInputSha256) && auxFailure.Contains("Additional input evidence changed"), "changed Aux evidence rejects export explicitly");
        Record(new { Case = "fixed-aux-input", Expected = new[] { 128, 0 }, Actual = auxMeans, SHA = auxSha, Export = auxHtml, ChangedEvidenceRejected = auxFailure, Boundary = "actual isolated runner with frozen Aux input; no Main source writes" });
    }

    private static CaptureResult CaptureMainNImage(string outputPath, int width, int height, bool retainedOnly = false, bool auxOnly = false, bool tableOnly = false, bool themeOnly = false)
    {
        OpenVisionLanguageService.SetLanguage(OpenVisionLanguage.Korean, false);
        string recipe = "Smoke_MainNImage_" + width;
        OpenVisionShellHostView host = CreateShellHost(recipe, false);
        VisionPipeline source = new() { Name = "MainNPrefix" };
        var threshold = VisionPipelineStepBuilder.FromThresholdProperty(new ThresholdToolProperty { Threshold = 100, MaxValue = 255 }, "Threshold_Predecessor", "Main", "Binary");
        threshold.UseAcceptance = true; threshold.AcceptanceMetricName = VisionPipelineKnownMetrics.ResultImageWidth; threshold.UseAcceptanceMetricMaximum = true; threshold.AcceptanceMetricMaximum = 1;
        source.Steps.Add(threshold);
        VisionPipelineStorage.Save(recipe, source); VisionPipelineStorage.SaveActivePipelineName(recipe, source.Name);
        host.RecipeCommands.RefreshOptions(); host.RecipeCommands.SelectedPipelineOption = host.RecipeCommands.PipelineOptions.Single(option => option.PipelineName == source.Name);
        var paths = new List<string>();
        foreach (int gray in tableOnly ? new[] { 180, 40 } : new[] { 180, 40, 180 })
        {
            string path = Path.ChangeExtension(outputPath, ".input-" + paths.Count + ".png");
            using (Bitmap bitmap = new(retainedOnly ? 64 : 4096, retainedOnly ? 40 : 4096)) { using Graphics graphics = Graphics.FromImage(bitmap); graphics.Clear(DrawingColor.FromArgb(gray, gray, gray)); bitmap.Save(path, ImageFormat.Png); } paths.Add(path);
        }
        if (width == 1600 && !retainedOnly) { AssertMainNImageEngine(outputPath, paths); }
        List<object> cases = new();
        void Require(bool value, string message) { if (!value) throw new InvalidOperationException("Main N-image: " + message); }
        void Record(object value) { cases.Add(value); File.WriteAllText(Path.ChangeExtension(outputPath, ".checks.json"), JsonSerializer.Serialize(cases, new JsonSerializerOptions { WriteIndented = true })); }
        if (auxOnly) { return CaptureWindowWithContent(host, outputPath, width, height, () => AssertMainNImageAuxExport(outputPath, recipe, paths, Require, Record)); }
        return CaptureWindowWithContent(host, outputPath, width, height, () =>
        {
            var loader = ReadPrivateField<OpenVisionShellHostCommandController>(host, "commandController")!;
            Require(loader.AddWorkspaceImages(paths) == paths.Count, "Main three ordered images"); OpenVisionLanguageService.SetLanguage(OpenVisionLanguage.Korean, false); host.SelectToolForTest(VISION_MENU.Mean); Pump(5);
            var root = host.Workbench; var model = root.Pipeline; var tool = root.Tool;
            Require(tool.IsNewTest && tool.SetRoute((long)typeof(OpenVisionWorkbenchToolViewModel).GetField("generation", BindingFlags.Instance | BindingFlags.NonPublic)!.GetValue(tool)!, "Binary", null, "MeanTrial"), "real target route Binary"); Pump(3);
            tool.CurrentStep.Parameters["USE_ROI"] = "False"; tool.CurrentStep.Parameters["USE_THRESHOLD"] = "False"; tool.CurrentStep.Parameters["USE_BITWISENOT"] = "False";
            byte[] working = VisionPipelineExecutionPlan.SerializePipeline(model.WorkingCopyForTest), saved = File.ReadAllBytes(RecipeWorkspaceService.GetVisionPipelinePath(recipe, source.Name));
            string data = Environment.GetEnvironmentVariable("OPENVISIONLAB_DATA_ROOT")!;
            Dictionary<string, string> History() => Directory.GetFiles(data, "*", SearchOption.AllDirectories).Where(path => path.Contains("PipelineRuns") || path.Contains("PipelineBatchRuns")).ToDictionary(path => path, path => Convert.ToHexString(SHA256.HashData(File.ReadAllBytes(path))));
            var retainedBatch = root.Images.Images.ToDictionary(image => image.Path, image => image.Result);
            var history = History(); string current = root.Shell.WorkspaceInputName; int layers = host.LayerDocumentCount, previewRuns = host.NativePreviewRunCount;
            Button button = FindVisualChildren<Button>(host).Single(item => item.Name == "btnNImageVerification" && item.IsVisible);
            Require(button.IsEnabled && button.ToolTip.ToString()!.Contains(paths.Count.ToString()) && button.ToolTip.ToString()!.Contains("Threshold_Predecessor"), "live count and predecessor tooltip");
            string previousDirectory = "";
            VisionToolNImageVerificationSession RunModal(string id, bool stop = false, bool close = false, bool disposeRoot = false)
            {
                Exception? failure = null; VisionToolNImageVerificationSession? retained = null; int stopWrites = 0, stoppedIndex = 0; bool stopping = stop;
                host.Dispatcher.BeginInvoke(new Action(() =>
                {
                    var window = Application.Current.Windows.OfType<VisionToolNImageVerificationWindow>().Single(item => item.IsVisible);
                    var controller = (VisionToolNImageVerificationController)window.DataContext;
                    window.UpdateLayout(); Pump(3);
                    try
                    {
                        Require(controller.ImagePaths.SequenceEqual(paths) && !controller.CanEditImages && ((controller.Rows.Count == paths.Count && controller.Rows.All(row => !row.IsCompleted)) || (controller.Rows.Count == root.Images.NImageTrialSession?.Rows.Count && ReferenceEquals(root.Images.NImageTrialSession, ReadPrivateField<VisionToolNImageVerificationSession>(controller, "session")))), "modal entry frozen or pending snapshot no run " + id);
                        PropertyChangedEventHandler observe = (_, e) =>
                        {
                            if (e.PropertyName != nameof(OpenVisionWorkbenchViewModel.MainActionText)) return;
                            if (root.MainActionText == (OpenVisionLanguageService.CurrentLanguage == OpenVisionLanguage.Korean ? "현재 이미지 처리 후 중지…" : "Stopping after the current image…")) { stopWrites++; }
                            if (root.MainActionKind != "Running") return;
                            Require(model.IsRunning && !model.CanEdit && !tool.CanUseToolActions && !controller.CanRun, "running duplicate/commands disabled");
                            if (stop || close || disposeRoot)
                            {
                                stop = false;
                                if (disposeRoot) { root.Dispose(); disposeRoot = false; }
                                else if (close) { window.Close(); close = false; }
                                else
                                {
                                    // RelayCommand requery is queued at Background. Observe the actual bound control after that UI phase.
                                    window.Dispatcher.BeginInvoke(System.Windows.Threading.DispatcherPriority.Background, new Action(() =>
                                    {
                                        try
                                        {
                                            var stopButton = FindVisualChildren<Button>(window).Single(item => ReferenceEquals(item.Command, controller.StopCommand));
                                            var key = window.InputBindings.OfType<KeyBinding>().Single(binding => binding.Key == Key.F5 && binding.Modifiers == ModifierKeys.Shift);
                                            stoppedIndex = tool.NImageIndex;
                                            Record(new { Case = id + "-stop-binding", SameKey = ReferenceEquals(key.Command, controller.StopCommand), ButtonEnabled = stopButton.IsEnabled, CanStop = controller.CanStop, MainCanStop = model.StopCommand.CanExecute(null), Index = stoppedIndex, KeyCommand = key.Command?.GetType().Name, ButtonCommand = stopButton.Command?.GetType().Name, Phase = "Background after existing RelayCommand requery; normal 4096x4096 data, no product delay" });
                                            Require(ReferenceEquals(key.Command, controller.StopCommand) && stopButton.IsEnabled && stoppedIndex > 0, "modal Stop and Main Shift+F5 use same command");
                                            if (id == "stop-keybinding") { key.Command.Execute(key.CommandParameter); } else { stopButton.Command.Execute(stopButton.CommandParameter); }
                                            Require(!controller.StopCommand.CanExecute(null) && !model.StopCommand.CanExecute(null) && !controller.CanStop, "modal and Main repeated Stop disabled");
                                        }
                                        catch (Exception ex) { failure = ex; controller.Stop(); }
                                    }));
                                }
                            }
                        };
                        root.PropertyChanged += observe;
                        try { WaitForTaskWithPump(controller.RunAsync(), 30000, "Main trial " + id); }
                        finally { root.PropertyChanged -= observe; }
                        Pump(3);
                        if (stopping) { Require(stopWrites == 1, "writer204 exactly once from actual modal command"); }
                        retained = ReadPrivateField<VisionToolNImageVerificationSession>(controller, "session")!;
                        Require(retained != null, "actual completed session required; status=" + controller.StatusText);
                        if (stopping) { Require(retained.WasCancelled && retained.Rows.Count == stoppedIndex && stoppedIndex < retained.PlannedCount, "exact current image completed and next image not executed at actual Stop binding phase"); }
                        if (!string.IsNullOrEmpty(previousDirectory)) Require(!Directory.Exists(previousDirectory), "next trial releases previous retained evidence");
                        previousDirectory = retained?.EvidenceDirectory ?? "";
                        Record(new { Case = id, StopWrites = stopWrites, Text = root.MainActionText, Kind = root.MainActionKind, Prefix = retained?.PrefixCount, Planned = retained?.PlannedCount, Cancelled = retained?.WasCancelled, SHA = retained?.StepDefinitionSha256, XML = retained?.PipelineXml, Rows = retained?.Rows.Select(row => new { row.FileName, row.Status, row.Message, row.MetricText, row.RunReportPath, row.SourceSha256 }).ToArray(), ExportAvailable = controller.CanExport, Closed = !window.IsVisible });
                        if (window.IsVisible)
                        {
                            string png = Path.ChangeExtension(outputPath, "." + id + "-modal.png"); ScreenshotPngWriter.WriteElementPng(window, png, (int)window.ActualWidth, (int)window.ActualHeight);
                        }
                    }
                    catch (Exception ex) { failure = ex; }
                    finally { window.Close(); }
                }));
                button.RaiseEvent(new RoutedEventArgs(Button.ClickEvent));
                if (failure != null) throw failure;
                return retained!;
            }
            var full = RunModal("normal-prefix");
            Require(full.PrefixCount == 1 && full.Rows.Count == paths.Count && !full.WasCancelled && !full.PipelineXml.Contains("<UseAcceptance>true</UseAcceptance>", StringComparison.Ordinal), "prefix gate disabled target default ungated");
            for (int index = 0; index < paths.Count; index++)
            {
                var report = VisionPipelineRunReportStorage.Load(full.Rows[index].RunReportPath);
                Require(report != null, "real report required; actual=" + full.Rows[index].Message);
                double mean = report.Steps.Last().Metrics.Single(metric => metric.Name == VisionPipelineKnownMetrics.MeanValueAvg).Value;
                Require(Math.Abs(mean - (index == 1 ? 0 : 255)) < .000001 && report.Steps.Count == 2 && report.Steps[0].Executed && !report.Steps[0].AcceptanceEvaluated, "independent binary prefix pixels and excluded gate");
            }
            Record(new { Case = "Main-row-projection-before-gate", Rows = root.Images.Images.Select(image => new { image.TrialText, BatchUnchanged = ReferenceEquals(image.Result, retainedBatch[image.Path]) }).ToArray(), EvidenceExists = Directory.Exists(full.EvidenceDirectory) });
            Require(root.Images.Images.All(image => image.TrialText.StartsWith("테스트") && ReferenceEquals(image.Result, retainedBatch[image.Path])) && Directory.Exists(full.EvidenceDirectory), "Main result projection separate from batch and retained after modal close");
            if (themeOnly)
            {
                foreach (string selectedTheme in new[] { "Light", "Dark" })
                {
                    (selectedTheme == "Light" ? root.SelectLightThemeCommand : root.SelectDarkThemeCommand).Execute(null); Pump(3);
                    Require(root.ThemeName == selectedTheme, "actual Main theme owner command changed selected theme");
                    string prior = root.MainActionText; Exception? failure = null; VisionToolNImageVerificationWindow? closed = null;
                    var authority = new ResourceDictionary { Source = new Uri("pack://application:,,,/OpenVisionLab;component/UI/Wpf/OpenVisionWorkbench" + selectedTheme + ".xaml") };
                    string Color(Brush value) => ((SolidColorBrush)value).Color.ToString();
                    host.Dispatcher.BeginInvoke(new Action(() =>
                    {
                        closed = Application.Current.Windows.OfType<VisionToolNImageVerificationWindow>().Single(item => item.IsVisible);
                        var controller = (VisionToolNImageVerificationController)closed.DataContext;
                        try
                        {
                            closed.UpdateLayout(); Pump(3);
                            Binding binding = BindingOperations.GetBinding(closed, OpenVisionWorkbenchThemeBehavior.ThemeNameProperty);
                            var grid = (DataGrid)closed.FindName("resultGrid");
                            string expectedPanel = Color((Brush)authority["OpenVision.Workbench.PanelBrush"]), expectedRaised = Color((Brush)authority["OpenVision.Workbench.RaisedBrush"]), expectedText = Color((Brush)authority["OpenVision.Workbench.TextBrush"]);
                            Require(ReferenceEquals(binding?.Source, root) && binding.Path.Path == nameof(root.ThemeName) && OpenVisionWorkbenchThemeBehavior.GetThemeName(closed) == selectedTheme, "actual N entry binding follows Main source");
                            var headers = FindVisualChildren<DataGridColumnHeader>(grid).Where(item => item.Column != null && item.IsVisible).ToArray();
                            Require(Color(closed.Background) == expectedPanel && Color(grid.Background) == expectedPanel && headers.All(item => Color(item.Background) == expectedRaised && Color(item.Foreground) == expectedText), "Main selected palette compared against independent authoritative dictionary");
                            Require(controller.CanExport && ReferenceEquals(full, ReadPrivateField<VisionToolNImageVerificationSession>(controller, "session")) && !controller.IsRunning && !model.IsRunning && root.MainActionText == prior, "theme-only retained reentry no Run or completion replay");
                            Record(new { Case = "actual-Main-N-theme-follow", selectedTheme, RootTheme = root.ThemeName, AttachedTheme = OpenVisionWorkbenchThemeBehavior.GetThemeName(closed), WindowPanel = Color(closed.Background), GridPanel = Color(grid.Background), expectedPanel, expectedRaised, expectedText, NoWriter = root.MainActionText == prior, PreviewRuns = host.NativePreviewRunCount, BoundSource = "actual Root" });
                            ScreenshotPngWriter.WriteElementPng(closed, Path.ChangeExtension(outputPath, ".Main-" + selectedTheme + "-retained.png"), (int)closed.ActualWidth, (int)closed.ActualHeight);
                        }
                        catch (Exception ex) { failure = ex; }
                        finally { closed.Close(); }
                    }));
                    button.RaiseEvent(new RoutedEventArgs(Button.ClickEvent)); if (failure != null) throw failure;
                    Require(closed != null && !closed.IsVisible && BindingOperations.GetBinding(closed, OpenVisionWorkbenchThemeBehavior.ThemeNameProperty) == null && OpenVisionWorkbenchThemeBehavior.GetThemeName(closed) == null, "normal closed window releases Main binding source");
                    Record(new { Case = "theme-binding-close-release", selectedTheme, BindingCleared = true, Closed = true });
                }
                Require(saved.SequenceEqual(File.ReadAllBytes(RecipeWorkspaceService.GetVisionPipelinePath(recipe, source.Name))) && working.SequenceEqual(VisionPipelineExecutionPlan.SerializePipeline(model.WorkingCopyForTest)) && host.NativePreviewRunCount == previewRuns && current == root.Shell.WorkspaceInputName, "theme reentry preserves saved/working/input/Preview");
                return;
            }
            if (tableOnly)
            {
                root.IsBottomCollapsed = false; root.SelectedBottomTab = 0; root.Images.ListModeCommand.Execute(null); Pump(5);
                var scroll = FindVisualChildren<ScrollViewer>(host).Single(item => AutomationProperties.GetAutomationId(item) == "MainImagesListScroll");
                string[] formalBefore = root.Images.Images.Select(item => item.ResultText).ToArray();
                foreach (var language in new[] { OpenVisionLanguage.Korean, OpenVisionLanguage.English })
