                    var metricBlocks = FindVisualChildren<TextBlock>(scroll).Where(item => item.IsVisible && BindingOperations.GetBinding(item, TextBlock.TextProperty)?.Path.Path == "TrialMetricText").OrderBy(item => ((OpenVisionWorkbenchImageItem)item.DataContext).Index).ToArray();
                    Require(metricBlocks.Length == paths.Count, "actual Main trial metric bound rows");
                    var expected = new[] { 255, 0, 255 };
                    var bounds = metricBlocks.Select(item => new Rect(item.TranslatePoint(new Point(), scroll), item.RenderSize)).ToArray();
                    Record(new { Case = "Main-table-before-bounds-gate", width, language, Texts = metricBlocks.Select(item => item.Text).ToArray(), Bounds = bounds.Select(item => new { item.X, item.Y, item.Width, item.Height }).ToArray(), scroll.ActualHeight, scroll.ViewportHeight, scroll.ActualWidth });
                    for (int index = 0; index < metricBlocks.Length; index++)
                    {
                        var item = (OpenVisionWorkbenchImageItem)metricBlocks[index].DataContext;
                        Require(metricBlocks[index].Text == item.TrialMetricText && item.TrialMetricText.Contains(expected[index].ToString("N1", System.Globalization.CultureInfo.CurrentCulture) + " GV") && !item.TrialMetricText.Contains("BoundsHeight"), "target mean visible localized units, not raw metrics");
                        metricBlocks[index].BringIntoView(); if (index == metricBlocks.Length - 1) { scroll.ScrollToBottom(); } Pump(2); host.UpdateLayout();
                        Rect visible = new Rect(metricBlocks[index].TranslatePoint(new Point(), scroll), metricBlocks[index].RenderSize);
                        Record(new { Case = "Main-table-actual-scroll-reach", language, Index = index + 1, Text = metricBlocks[index].Text, X = visible.X, Y = visible.Y, visible.Width, visible.Height, scroll.ViewportHeight, scroll.ViewportWidth, scroll.VerticalOffset, scroll.HorizontalOffset });
                        var presenter = (ScrollContentPresenter)scroll.Template.FindName("PART_ScrollContentPresenter", scroll);
                        DrawingGroup drawing = VisualTreeHelper.GetDrawing(metricBlocks[index]);
                        Require(drawing != null && !drawing.Bounds.IsEmpty, "actual metric glyph drawing available");
                        Rect ink = metricBlocks[index].TransformToVisual(presenter).TransformBounds(drawing.Bounds);
                        Record(new { Case = "Main-table-glyph-clip", language, Index = index + 1, Ink = new { ink.X, ink.Y, ink.Width, ink.Height }, Clip = new { presenter.ActualWidth, presenter.ActualHeight }, Boundary = "actual glyph ink; layout line-box blank space and binary64 summed edge kept above; no pixel tolerance" });
                        Require(new Rect(presenter.RenderSize).Contains(ink), "all major metric glyphs read inside actual viewport after normal scroll; second row reached");
                    }
                    Require(root.Images.Images.All(item => item.Result == null && item.ResultText == (language == OpenVisionLanguage.Korean ? "검사 전" : "Not inspected") && item.TrialText.StartsWith(language == OpenVisionLanguage.Korean ? "테스트" : "Test")), "official Result label unchanged and trial separate");
                    Record(new { Case = "Main-target-summary-table", Width = width, language, Metric = metricBlocks.Select(item => item.Text).ToArray(), Heights = metricBlocks.Select(item => item.ActualHeight).ToArray(), Bounds = bounds.Select(item => new { item.X, item.Y, item.Width, item.Height }).ToArray(), ViewportHeight = scroll.ActualHeight, Formal = formalBefore, RawMetricCharacters = full.Rows.Select(item => item.MetricText.Length).ToArray() });
                    ScreenshotPngWriter.WriteElementPng(host, Path.ChangeExtension(outputPath, ".table-" + language + ".png"), width, height);
                }
                string html = Path.ChangeExtension(outputPath, ".raw-report.html");
                Require(VisionToolNImageVerificationHtmlReportExporter.TryExport(full.BatchSummaryPath, full.PipelineXml, full.StepDefinitionSha256, html, OpenVisionLanguage.English, out string error) && File.ReadAllText(html).Contains("MeanValueAvg=255") && File.ReadAllText(html).Contains("BoundsHeight"), "raw modal/report metrics preserved: " + error);
                Record(new { Case = "raw-metrics-preserved", Html = html, Raw = full.Rows.Select(row => row.MetricText).ToArray(), PreviewRuns = host.NativePreviewRunCount });
                return;
            }
            Exception? reopenFailure = null; string beforeReopenText = root.MainActionText;
            host.Dispatcher.BeginInvoke(new Action(() =>
            {
                var window = Application.Current.Windows.OfType<VisionToolNImageVerificationWindow>().Single(item => item.IsVisible);
                var controller = (VisionToolNImageVerificationController)window.DataContext;
                try
                {
                    Require(ReferenceEquals(root.Images.NImageTrialSession, ReadPrivateField<VisionToolNImageVerificationSession>(controller, "session")) && controller.CanExport && root.MainActionText == beforeReopenText && !model.IsRunning, "identical reentry restores frozen result and export without writer or run");
                    string export = Path.ChangeExtension(outputPath, ".main-after-close.html");
                    Require(VisionToolNImageVerificationHtmlReportExporter.TryExport(full.BatchSummaryPath, full.PipelineXml, full.StepDefinitionSha256, export, OpenVisionLanguage.Korean, out string exportError, full.AdditionalInputPaths, full.AdditionalInputSha256), "Main after-close export: " + exportError);
                    Record(new { Case = "retained-reentry-export", Export = export, Rows = controller.Rows.Count, NoRun = true, NoWriter = root.MainActionText == beforeReopenText, SHA = full.StepDefinitionSha256 });
                }
                catch (Exception ex) { reopenFailure = ex; }
                finally { window.Close(); }
            }));
            button.RaiseEvent(new RoutedEventArgs(Button.ClickEvent)); if (reopenFailure != null) throw reopenFailure;
            if (retainedOnly)
            {
                void ReentryGuard(string id, bool expectedRestore)
                {
                    Exception? error = null; string prior = root.MainActionText;
                    host.Dispatcher.BeginInvoke(new Action(() =>
                    {
                        var window = Application.Current.Windows.OfType<VisionToolNImageVerificationWindow>().Single(item => item.IsVisible);
                        var controller = (VisionToolNImageVerificationController)window.DataContext;
                        try
                        {
                            bool restored = ReferenceEquals(full, ReadPrivateField<VisionToolNImageVerificationSession>(controller, "session"));
                            Require(restored == expectedRestore && controller.CanExport == expectedRestore && !controller.IsRunning && root.MainActionText == prior, "captured identity strict reentry " + id);
                            Record(new { Case = id, expectedRestore, restored, controller.CanExport, NoWriter = root.MainActionText == prior, NoRun = !model.IsRunning });
                        }
                        catch (Exception ex) { error = ex; }
                        finally { window.Close(); }
                    }));
                    button.RaiseEvent(new RoutedEventArgs(Button.ClickEvent)); if (error != null) throw error;
                }
                long token = (long)typeof(OpenVisionWorkbenchToolViewModel).GetField("generation", BindingFlags.Instance | BindingFlags.NonPublic)!.GetValue(tool)!;
                Require(tool.SetRoute(token, "Main", null, "MeanTrial"), "normal route change"); ReentryGuard("route-changed-refuses-old-result", false);
                Require(tool.SetRoute(token, "Binary", null, "MeanTrial"), "normal route restore"); ReentryGuard("route-restored-frozen-result", true);
                byte[] original = File.ReadAllBytes(paths[1]);
                try { File.AppendAllText(paths[1], "owned input identity change"); ReentryGuard("input-sha-changed-refuses-old-result", false); }
                finally { File.WriteAllBytes(paths[1], original); }
                ReentryGuard("input-sha-restored-frozen-result", true);
                Require(saved.SequenceEqual(File.ReadAllBytes(RecipeWorkspaceService.GetVisionPipelinePath(recipe, source.Name))) && history.OrderBy(item => item.Key).SequenceEqual(History().OrderBy(item => item.Key)) && host.NativePreviewRunCount == previewRuns, "strict guards saved history Run unchanged");
                return;
            }
            var partial = RunModal("stop-after-current", stop: true);
            Require(partial.WasCancelled && partial.Rows.All(row => row.IsCompleted) && root.MainActionText.Contains(partial.Rows.Count + "장") && root.MainActionText.Contains("계획 3장"), "current image completed next images not run actual count");
            OpenVisionLanguageService.SetLanguage(OpenVisionLanguage.English, false); root.SelectLightThemeCommand.Execute(null); Pump(3);
            Require(root.MainActionText.Contains(partial.Rows.Count + " images") && root.MainActionText.Contains("planned 3") && root.Images.Images[0].TrialText.StartsWith("Test"), "locale reprojects captured count and Main row");
            if (width == 1600) { var keyStop = RunModal("stop-keybinding", stop: true); Require(keyStop.WasCancelled && keyStop.Rows.All(row => row.IsCompleted), "bound Shift+F5 same after-current contract; actual key native remains separate"); }
            var recovered = RunModal("valid-recovery"); Require(recovered.Rows.Count == 3 && !recovered.WasCancelled, "repeat retry recovers");
            Require(working.SequenceEqual(VisionPipelineExecutionPlan.SerializePipeline(model.WorkingCopyForTest)) && saved.SequenceEqual(File.ReadAllBytes(RecipeWorkspaceService.GetVisionPipelinePath(recipe, source.Name))) && current == root.Shell.WorkspaceInputName && layers == host.LayerDocumentCount && previewRuns == host.NativePreviewRunCount && history.OrderBy(item => item.Key).SequenceEqual(History().OrderBy(item => item.Key)), "working saved selection layers Preview history invariant");
            if (width == 1600)
            {
                // Test-only owned snapshot assignment exercises the production dependency capture, without a saved-step editor or route mutation.
                var sourceField = typeof(OpenVisionWorkbenchPipelineViewModel).GetField("pipeline", BindingFlags.Instance | BindingFlags.NonPublic)!;
                var selectionField = typeof(OpenVisionWorkbenchPipelineViewModel).GetField("selectedIndex", BindingFlags.Instance | BindingFlags.NonPublic)!;
                var originalSource = (VisionPipeline)sourceField.GetValue(model)!; int originalSelection = (int)selectionField.GetValue(model)!;
                VisionPipeline captured;
                var dependency = new VisionPipeline { Name = "TwoInputs" };
                dependency.Steps.Add(VisionPipelineStepBuilder.FromThresholdProperty(new ThresholdToolProperty { Threshold = 100, MaxValue = 255 }, "A", "Main", "A"));
                dependency.Steps.Add(VisionPipelineStepBuilder.FromThresholdProperty(new ThresholdToolProperty { Threshold = 200, MaxValue = 255 }, "B", "Main", "B"));
                dependency.Steps.Add(VisionPipelineStepBuilder.FromArithmetic("Mix", "Bitwise_AND", "A", "B", "Mix", false, false, 0, 0, 0, 0, 0, 0));
                dependency.Steps.Add(VisionPipelineStepBuilder.FromThresholdProperty(new ThresholdToolProperty { Threshold = 20 }, "Unrelated", "Main", "Unrelated"));
                byte[] dependencyBytes = VisionPipelineExecutionPlan.SerializePipeline(dependency);
                try
                {
                    sourceField.SetValue(model, dependency); selectionField.SetValue(model, 3);
                    var target = VisionPipelineStepBuilder.FromProperty(new MeanProperty { NAME = "Mean", USE_ROI = false, USE_THRESHOLD = false, MEAN_MIN = 0, MEAN_MAX = 255 }, "Mix", "Target");
                    captured = model.CaptureNImagePipeline(target);
                    Require(captured.Steps.Select(step => step.Name).SequenceEqual(new[] { "A", "B", "Mix", "Mean" }) && captured.Steps.Take(3).All(step => !step.UseAcceptance) && dependencyBytes.SequenceEqual(VisionPipelineExecutionPlan.SerializePipeline(dependency)), "two-input dependency snapshot excludes unrelated and preserves source");
                }
                finally { sourceField.SetValue(model, originalSource); selectionField.SetValue(model, originalSelection); }
                var twoInputs = Task.Run(() => VisionToolNImageVerificationService.RunAsync("Mean", recipe, () => captured.Steps.Last(), true, paths.Take(1).ToArray(), null, CancellationToken.None, captured, Path.ChangeExtension(outputPath, ".two-inputs"))).GetAwaiter().GetResult();
                var twoReport = VisionPipelineRunReportStorage.Load(twoInputs.Rows.Single().RunReportPath);
                Require(twoInputs.Rows.Single().IsUngated && twoReport.Steps.Last().Metrics.Single(metric => metric.Name == VisionPipelineKnownMetrics.MeanValueAvg).Value == 0, "two-input 255 AND 0 yields target mean 0");
                Record(new { Case = "two-input-dependencies", Names = captured.Steps.Select(step => step.Name).ToArray(), Mean = 0, SourceUnchanged = true, Boundary = "test-only source assignment; actual production snapshot and engine" });
                AssertMainNImageAuxExport(outputPath, recipe, paths, Require, Record);
                using (Bitmap transient = new(513, 257))
                {
                    using Graphics graphics = Graphics.FromImage(transient); graphics.Clear(DrawingColor.FromArgb(180, 180, 180));
                    Require(host.AddLayerImageForTest("Main", transient), "normal full Main bitmap input"); root.Shell.UpdateWorkspaceInputImage(transient); Pump(4);
                    Require(root.Images.Images.Count(image => string.IsNullOrWhiteSpace(image.Path)) == 1 && root.Images.Count == 4, "one pathless current row source contract");
                    paths.Add(string.Empty);
                    var pathless = RunModal("pathless-original-snapshot"); var row = pathless.Rows.Single(item => string.IsNullOrWhiteSpace(item.ImagePath));
                    using Bitmap original = new(row.SourceSnapshotPath);
                    Require(row.FileName == "Main" && original.Width == 513 && original.Height == 257 && original.GetPixel(200, 200).R == 180 && root.Images.Images.Single(image => string.IsNullOrWhiteSpace(image.Path)).TrialText.Length > 0, "pathless raw name original pixels dimensions and same row mapping");
                    Record(new { Case = "pathless-original", row.FileName, row.ImagePath, OriginalWidth = original.Width, OriginalHeight = original.Height, PreviewWidth = root.Images.Images.Single(image => string.IsNullOrWhiteSpace(image.Path)).Preview.PixelWidth, row.SourceSha256, row.SourceSnapshotPath, EvidenceDirectory = pathless.EvidenceDirectory });
                }
                var closed = RunModal("close-current-image", close: true); Require(closed.WasCancelled && closed.Rows.Count == 1 && !model.IsRunning && Directory.Exists(closed.EvidenceDirectory), "modal close orderly current completion release and result transfer");
                RunModal("close-retry");
                string beforeDispose = "";
                root.PropertyChanged += (_, e) => { if (e.PropertyName == nameof(OpenVisionWorkbenchViewModel.MainActionText) && root.MainActionKind == "Running") beforeDispose = root.MainActionText; };
                var disposed = RunModal("root-dispose-late-callback", disposeRoot: true);
                Require(root.MainActionText == beforeDispose && !Directory.Exists(disposed.EvidenceDirectory), "disposed Root no late terminal and transient cleanup");
            }
            Record(new { Case = "invariants", WorkingSavedHistoryUnchanged = true, CurrentInput = current, PreviewRuns = previewRuns, Layers = layers, NativeDPI = "unverified", Boundary = "in-process actual Main N button + existing modal/controller + real sequential engine; no algorithm qualification" });
        });
    }

    private static CaptureResult CaptureMainCommonGuardLifetime(string outputPath)
    {
        string recipe = "Smoke_CommonGuards_" + Guid.NewGuid().ToString("N")[..12];
        OpenVisionShellHostView host = CreateShellHost(recipe, false);
        VisionPipeline source = new() { Name = "CommonGuard" };
        source.Steps.Add(VisionPipelineStepBuilder.FromThresholdProperty(new ThresholdToolProperty { Threshold = 112, MaxValue = 255 }, "Threshold_1", "Main", "Threshold_1"));
        VisionPipelineStorage.Save(recipe, source); VisionPipelineStorage.SaveActivePipelineName(recipe, source.Name);
        host.RecipeCommands.RefreshOptions(); host.RecipeCommands.SelectedPipelineOption = host.RecipeCommands.PipelineOptions.Single(option => option.PipelineName == source.Name);
        string input = Path.ChangeExtension(outputPath, ".input.png"); using (Bitmap image = new(64, 40)) { image.Save(input, ImageFormat.Png); }
        List<object> cases = new();
        void Require(bool condition, string message) { if (!condition) throw new InvalidOperationException("Common guard/lifetime: " + message); }
        void Record(object value) { cases.Add(value); File.WriteAllText(Path.ChangeExtension(outputPath, ".checks.json"), JsonSerializer.Serialize(cases, new JsonSerializerOptions { WriteIndented = true })); }
        return CaptureWindowWithContent(host, outputPath, 1600, 900, () =>
        {
            Require(host.LoadMainImageFromFileForTest(input), "owned input loaded"); Pump(3);
            var root = host.Workbench; var model = root.Pipeline; var tool = root.Tool;
            byte[] working = VisionPipelineExecutionPlan.SerializePipeline(model.WorkingCopyForTest), saved = File.ReadAllBytes(RecipeWorkspaceService.GetVisionPipelinePath(recipe, source.Name));
            bool busy = false, failPreset = false; int applies = 0, notifications = 0;
            var parameters = new ThresholdToolProperty();
            var binding = new OpenVisionWorkbenchToolViewModel.EditorBinding { ToolName = "Threshold", EnglishName = "Threshold", DisplayName = () => "Threshold", SupportsPipeline = true, LoadParameters = _ => parameters, CaptureParameters = () => parameters, RestoreParameters = _ => { }, ApplyStep = _ => { }, CreateStep = () => source.Steps[0], IsRunning = () => busy };
            tool.Activate(null, binding);
            var shell = new VisionToolSingleInputPropertyToolShell(); shell.WorkbenchStepActions.DataContext = tool;
            var valid = new VisionToolPreset<ThresholdToolProperty>("basic", "VisionTool.Preset.Basic", "Basic", "", "", value => value.Threshold = 100);
            var blank = new VisionToolPreset<ThresholdToolProperty>("blank", "", "Unnamed", "", "", value => value.Threshold = 120);
            using var presenter = VisionToolPresetButtonPresenter<ThresholdToolProperty>.Attach(shell, new[] { valid }, preset => { applies++; if (failPreset) throw new IOException("Owned preset apply failure"); preset.ApplyTo(parameters); });
            var apply = presenter.GetType().GetMethod("ApplyPresetAndRefresh", BindingFlags.Instance | BindingFlags.NonPublic)!;
            PropertyChangedEventHandler presetObserver = (_, e) => { if (e.PropertyName == nameof(tool.AppliedPresetNameKey)) notifications++; };
            tool.PropertyChanged += presetObserver;
            try
            {
                string prior = root.MainActionText; busy = true;
                apply.Invoke(presenter, new object[] { valid });
                Require(!tool.CanEditParameters && applies == 0 && notifications == 0 && root.MainActionText == prior, "preset CanEdit false blocks application and success"); busy = false;
                apply.Invoke(presenter, new object[] { blank });
                Require(applies == 1 && notifications == 0 && root.MainActionText == prior, "empty key never publishes success");
                failPreset = true; bool propagated = false;
                try { apply.Invoke(presenter, new object[] { valid }); } catch (TargetInvocationException ex) when (ex.InnerException is IOException) { propagated = true; }
                Require(propagated && notifications == 0 && root.MainActionText == prior, "apply delegate exception no false success"); failPreset = false;
                shell.PresetBasicButton.RaiseEvent(new RoutedEventArgs(Button.ClickEvent)); Pump(2);
                Require(parameters.Threshold == 100 && notifications == 1 && root.MainActionText == string.Format(OpenVisionLanguageService.T("Workbench.Tool.PresetAppliedFormat"), OpenVisionLanguageService.T("VisionTool.Preset.Basic")), "real presenter button valid recovery");
                Record(new { Case = "preset-guard-recovery", CanEditRefused = true, EmptyKeyNoSuccess = true, DelegateExceptionPropagated = propagated, ValidButtonApplied = parameters.Threshold, notifications, PASS = true });
            }
            finally { tool.PropertyChanged -= presetObserver; }
            var execution = ReadPrivateField<OpenVisionPipelineReviewExecutionController>(model, "execution")!;
            var invokeField = typeof(OpenVisionPipelineReviewExecutionController).GetField("invokeOnUi", BindingFlags.Instance | BindingFlags.NonPublic)!;
            var originalInvoke = (Action<Action>)invokeField.GetValue(execution)!;
            using ManualResetEventSlim entered = new(false), release = new(false);
            int uiThread = Environment.CurrentManagedThreadId, workerThread = 0; bool gated = false;
            Action<Action> gatedInvoke = callback =>
            {
                if (gated && Environment.CurrentManagedThreadId != uiThread && Interlocked.CompareExchange(ref workerThread, Environment.CurrentManagedThreadId, 0) == 0)
                {
                    originalInvoke(callback); entered.Set(); if (!release.Wait(10000)) throw new TimeoutException("Owned worker gate release missing");
                }
                else { originalInvoke(callback); }
            };
            invokeField.SetValue(execution, gatedInvoke);
            void WaitEntered(Task task)
            {
                Stopwatch timer = Stopwatch.StartNew(); while (!entered.IsSet && !task.IsCompleted && timer.ElapsedMilliseconds < 10000) { Pump(1); }
                Require(entered.IsSet && execution.IsRunning && !task.IsCompleted && workerThread != uiThread, "actual worker entered before intervention");
            }
            void Arm() { entered.Reset(); release.Reset(); workerThread = 0; gated = true; }
            try
            {
                Arm(); Task run = model.RunForTestAsync(); WaitEntered(run); execution.Reset(); release.Set(); WaitForTaskWithPump(run, 10000, "superseded model run"); gated = false;
                Require(!model.IsRunning && !model.SingleRunCompleted, "superseded Main run cannot publish fresh completion");
                Record(new { Case = "active-worker-superseded-main", workerThread, uiThread, CompletionSuppressed = !model.SingleRunCompleted, Text = root.MainActionText, PASS = true });
                Arm(); Task<OpenVisionPipelineReviewExecutionResult> direct = execution.RunAsync(model.WorkingCopyForTest, OpenVisionPipelineReviewExecutionController.DefaultStepTimeoutMilliseconds); WaitEntered(direct); execution.Reset(); release.Set(); WaitForTaskWithPump(direct, 10000, "actual superseded result"); gated = false;
                Require(direct.Result.WasSuperseded, "backend actual WasSuperseded returned"); Record(new { Case = "backend-was-superseded", WasSuperseded = direct.Result.WasSuperseded, Boundary = "actual existing backend; direct execution result separate from Main writer", PASS = true });
                Arm(); run = model.RunForTestAsync(); WaitEntered(run); model.StopCommand.Execute(null); release.Set(); WaitForTaskWithPump(run, 10000, "cancelled run completed"); gated = false;
                WaitForTaskWithPump(model.RunForTestAsync(), 10000, "valid run after cancel/supersede"); Pump(2);
                Require(!model.IsRunning && model.SingleRunCompleted && model.SingleRunResultKind == "NoVerdict" && root.MainActionKind != "Warning", "new valid execution excludes stale stop/result");
                Require(working.SequenceEqual(VisionPipelineExecutionPlan.SerializePipeline(model.WorkingCopyForTest)) && saved.SequenceEqual(File.ReadAllBytes(RecipeWorkspaceService.GetVisionPipelinePath(recipe, source.Name))) && host.NativePreviewRunCount == 0, "working/saved/Preview unchanged");
                Record(new { Case = "cancel-new-run-recovery", Kind = model.SingleRunResultKind, Text = root.MainActionText, StaleStopAbsent = root.MainActionKind != "Warning", PASS = true });
                Arm(); run = model.RunForTestAsync(); WaitEntered(run); string retained = root.MainActionText; root.Dispose(); release.Set(); WaitForTaskWithPump(run, 10000, "disposed actual worker returned"); gated = false;
                WaitForTaskWithPump(execution.DisposeAsync(), 10000, "existing deterministic release owner");
                Require(root.MainActionText == retained && !execution.IsRunning && ReadPrivateField<CancellationTokenSource>(execution, "activeCancellationSource") == null, "active worker disposed; no terminal replay; CTS released");
                Record(new { Case = "active-worker-root-dispose", workerThread, uiThread, LateMainActionSuppressed = true, WorkerReturned = run.IsCompleted, CTSReleased = true, PASS = true });
            }
            finally { release.Set(); gated = false; invokeField.SetValue(execution, originalInvoke); }
        });
    }

    private static CaptureResult CaptureMainPipelineAction(string outputPath, int width, int height)
    {
        string recipe = "Smoke_MainPipelineAction_" + width;
        OpenVisionShellHostView host = CreateShellHost(recipe, false);
        VisionPipeline source = new() { Name = "Pipeline_Action" };
        source.Steps.Add(VisionPipelineStepBuilder.FromThresholdProperty(new ThresholdToolProperty { Threshold = 112, MaxValue = 255 }, "Threshold_1", "Main", "Threshold_1"));
        source.Steps.Add(VisionPipelineStepBuilder.FromProperty(new MeanProperty { NAME = "Mean_1", USE_ROI = false, MEAN_MIN = 0, MEAN_MAX = 255 }, "Threshold_1", "Mean_1"));
        VisionPipelineStorage.Save(recipe, source); VisionPipelineStorage.SaveActivePipelineName(recipe, source.Name);
        host.RecipeCommands.RefreshOptions(); host.RecipeCommands.SelectedPipelineOption = host.RecipeCommands.PipelineOptions.Single(option => option.PipelineName == source.Name);
        string input = Path.ChangeExtension(outputPath, ".input.png"); using (Bitmap image = new(640, 360)) { using Graphics graphics = Graphics.FromImage(image); graphics.Clear(DrawingColor.Teal); image.Save(input, ImageFormat.Png); }
        List<object> cases = new(); void Record(object value) { cases.Add(value); File.WriteAllText(Path.ChangeExtension(outputPath, ".cases.json"), JsonSerializer.Serialize(cases)); }
        return CaptureWindowWithContent(host, outputPath, width, height, () =>
        {
            string noInputAction = host.Workbench.MainActionText;
            WaitForTaskWithPump(host.Workbench.Pipeline.RunForTestAsync(), 1000, "no input guard");
            if (host.Workbench.Pipeline.RunCommand.CanExecute(null) || host.Workbench.MainActionText != noInputAction) throw new InvalidOperationException("Main pipeline no-input guard changed action");
            Record(new { Case = "no-input-guard", Preserved = true });
            host.LoadMainImageFromFileForTest(input); Pump(6); OpenVisionLanguageService.SetLanguage(OpenVisionLanguage.Korean, false);
            OpenVisionWorkbenchPipelineViewModel model = host.Workbench.Pipeline;
            void Require(bool condition, string reason) { if (!condition) throw new InvalidOperationException("Main pipeline action: " + reason); }
            void SetSource(VisionPipeline value) { VisionPipelineStorage.Save(recipe, value); host.RecipeCommands.RefreshOptions(); Pump(4); OpenVisionLanguageService.SetLanguage(OpenVisionLanguage.Korean, false); }
            void RunCase(string id, bool prefix, string expectedKind, int selected = 0)
            {
                model.SelectedRow = model.Rows[selected];
                string target = model.SelectedRow.Name, start = ""; int starts = 0; bool repeatReturned = false;
                byte[] working = VisionPipelineExecutionPlan.SerializePipeline(model.WorkingCopyForTest);
                string hash = Convert.ToHexString(SHA256.HashData(File.ReadAllBytes(input)));
                PropertyChangedEventHandler observer = (_, e) => { if (e.PropertyName == nameof(OpenVisionWorkbenchViewModel.MainActionText) && model.IsSingleRunning) { start = host.Workbench.MainActionText; starts++; } };
                Stopwatch timer = Stopwatch.StartNew(); host.Workbench.PropertyChanged += observer;
                try
                {
                    Task run = model.RunForTestAsync(prefix);
                    if (model.IsRunning) { Task repeated = model.RunForTestAsync(prefix); repeatReturned = repeated.IsCompleted; }
                    WaitForTaskWithPump(run, 12000, "Main pipeline action " + id);
                }
                finally { host.Workbench.PropertyChanged -= observer; timer.Stop(); }
                double wall = (double)typeof(OpenVisionWorkbenchPipelineViewModel).GetField("lastRunMilliseconds", BindingFlags.Instance | BindingFlags.NonPublic)!.GetValue(model)!;
                string result = expectedKind == "NoVerdict" ? "판정 없음" : expectedKind == "Error" ? "오류" : expectedKind.ToUpperInvariant();
                string expected = (prefix ? "이 단계까지" : "파이프라인") + " 실행 완료 · " + result + " · " + OpenVisionPipelineReviewResultPresenter.FormatWorkbenchElapsed(wall);
