    private sealed class MainRoiActionProbe : IPropertyGridImageEditorService, IPropertyGridTemplateImageEditView
    {
        private readonly IPropertyGridImageEditorService original;
        private readonly string sourcePath;
        internal bool Accepted;
        internal bool MissingInput;
        internal bool FailCreate;
        internal bool FailShow;
        internal bool FailSave;
        internal Action OnShow;
        internal string Mode;
        internal MatchingProperty Matching;
        internal bool FailSetter;
        public object ParentProperty => new { IsReadOnly = false };
        public string StringValue { get => Matching.PATTERN_PATH; set { if (FailSetter) throw new InvalidOperationException("owned matching setter failure"); Matching.PATTERN_PATH = value; } }
        internal int ViewsCreated;
        internal int ViewsDisposed;
        internal OpenCvSharp.Mat LastSource;
        internal List<OpenCvSharp.Rect> Regions = new() { new(2, 3, 16, 12) };
        internal MainRoiActionProbe(IPropertyGridImageEditorService original, string sourcePath) { this.original = original; this.sourcePath = sourcePath; }
        public IDisplayManager RuntimeContext { get => original.RuntimeContext; set => original.RuntimeContext = value; }
        public void SetRuntimeContext(Func<IDisplayManager> accessor) => original.SetRuntimeContext(accessor);
        public void SetRecipeNameContext(Func<string> accessor) => original.SetRecipeNameContext(accessor);
        public void SetSourceLayerContext(Func<string> accessor) => original.SetSourceLayerContext(accessor);
        public OpenCvSharp.Mat GetSourceImage() { LastSource?.Dispose(); return LastSource = MissingInput ? new OpenCvSharp.Mat() : Cv.ImRead(sourcePath); }
        public IPropertyGridImageEditView CreateImageEditView(OpenCvSharp.Mat source, DrawingRectangle roi, string mode) { if (FailCreate) throw new InvalidOperationException("owned editor create failure"); Mode = mode; ViewsCreated++; return this; }
        public IPropertyGridImageEditView CreateImageEditView(OpenCvSharp.Mat source, List<OpenCvSharp.Rect> roi, string mode) => CreateImageEditView(source, DrawingRectangle.Empty, mode);
        public OpenCvSharp.Rect LoadTemplateRoi(OpenCvSharp.Mat source, string path) => original.LoadTemplateRoi(source, path);
        public double LoadTemplateRotationDegrees(string path) => original.LoadTemplateRotationDegrees(path);
        public string SaveTemplateImage(OpenCvSharp.Mat source, OpenCvSharp.Rect roi) => SaveTemplateImage(source, roi, 0D);
        public string SaveTemplateImage(OpenCvSharp.Mat source, OpenCvSharp.Rect roi, double rotation) { if (FailSave) throw new InvalidOperationException("owned template save failure"); return original.SaveTemplateImage(source, roi, rotation); }
        public OpenCvSharp.Rect SelectedRegion => Regions.FirstOrDefault();
        public List<OpenCvSharp.Rect> SelectedRegions => Regions.ToList();
        public double TemplateRotationDegrees { get; set; }
        public bool ShowDialog() { OnShow?.Invoke(); if (FailShow) throw new InvalidOperationException("owned editor show failure"); return Accepted; }
        public void LoadPatternPreviewImage(string path) { }
        public void Dispose() { ViewsDisposed++; }
    }

    private static CaptureResult CaptureMainRoiAction(string outputPath, int width, int height)
    {
        OpenVisionLanguageService.SetLanguage(OpenVisionLanguage.Korean, false);
        OpenVisionShellHostView host = CreateShellHost("Smoke_MainRoiAction", false);
        string sourcePath = Path.ChangeExtension(outputPath, ".source.png");
        using (Bitmap source = CreateMatchingSmokeBitmap()) { source.Save(sourcePath, ImageFormat.Png); host.SetMainLayerImageForTest(source); }
        List<object> cases = new();
        void Record(object value) { cases.Add(value); File.WriteAllText(Path.ChangeExtension(outputPath, ".cases.json"), JsonSerializer.Serialize(cases)); }
        void Require(bool condition, string reason) { if (!condition) throw new InvalidOperationException("Main ROI action: " + reason); }
        return CaptureWindowWithContent(host, outputPath, width, height, () =>
        {
            PropertyGridEditorRuntime runtime = (PropertyGridEditorRuntime)typeof(PropertyGridEditorFactory).GetField("runtime", BindingFlags.Static | BindingFlags.NonPublic)!.GetValue(null)!;
            IPropertyGridImageEditorService original = runtime.ImageEditorService;
            MainRoiActionProbe probe = new(original, sourcePath);
            PropertyGridEditorFactory.SetImageEditorService(probe);
            string suppress = Environment.GetEnvironmentVariable("OPENVISIONLAB_SUPPRESS_MESSAGEBOX");
            Environment.SetEnvironmentVariable("OPENVISIONLAB_SUPPRESS_MESSAGEBOX", "1");
            try
            {
                host.SelectToolForTest(VISION_MENU.Blob); Pump(10); OpenVisionLanguageService.SetLanguage(OpenVisionLanguage.Korean, false);
                OpenVisionNativeToolDocument document = host.ActiveNativeDocumentForTest!;
                VisionToolDebouncedPreviewScheduler.SetAllowAutoPreview(document.View, false);
                var grid = FindVisualChildren<System.Windows.Controls.WpfPropertyGrid.PropertyGrid>(document.View).Single();
                BlobProperty property = (BlobProperty)grid.SelectedObject;
                property.USE_ROI = true; new PropertyGridEventBinder(null).ApplyVisibilityRules(grid); grid.RefreshSelectedObject(); Pump(6);
                Require(grid.FocusProperty("CvROI"), "existing ROI row"); Pump(4);
                Border row = FindVisualChildren<Border>(grid).Single(item => item.Name == "RowBorder" && (item.DataContext?.GetType().GetProperty("PropertyDescriptor")?.GetValue(item.DataContext) as PropertyDescriptor)?.Name == "CvROI");
                Button button = FindVisualChildren<Button>(row).First(item => item.IsVisible && (item.Content?.ToString() is "..." or "…" || item.DataContext?.GetType().Name == "PropertyItemValue"));
                Action<string> inherited = PropertyGridEditorFactory.GetEditActionCallback(button);
                Require(inherited != null && button.ReadLocalValue(PropertyGridEditorFactory.EditActionCallbackProperty) == DependencyProperty.UnsetValue, "actual Bridge button inherits document callback");
                OpenCvSharp.Rect beforeRoi = property.CvROI;
                probe.Accepted = false;
                probe.OnShow = () => { Require(host.Workbench.MainActionText == "ROI 드래그 · 모서리로 크기 조절 · Enter 적용 · Esc 취소", "PG start before modal"); Record(new { Case = "actual-pg-start", Text = host.Workbench.MainActionText, Kind = host.Workbench.MainActionKind, Mode = probe.Mode, SourceType = button.GetType().FullName, InheritedCallback = true }); };
                button.RaiseEvent(new RoutedEventArgs(Button.ClickEvent)); Pump(3);
                Record(new { Case = "actual-pg-cancel", Text = host.Workbench.MainActionText, Kind = host.Workbench.MainActionKind, Before = beforeRoi.ToString(), After = property.CvROI.ToString(), Views = probe.ViewsCreated, Disposed = probe.ViewsDisposed });
                ScreenshotPngWriter.WriteElementPng(host, Path.ChangeExtension(outputPath, ".pg-cancel.png"), width, height);
                Require(host.Workbench.MainActionText == "ROI 편집을 취소했습니다." && property.CvROI == beforeRoi, "PG cancel no mutation");
                probe.Accepted = true; button.RaiseEvent(new RoutedEventArgs(Button.ClickEvent)); Pump(3);
                Require(property.CvROI == new OpenCvSharp.Rect(2, 3, 16, 12) && host.Workbench.MainActionText == "ROI를 적용했습니다.", "single ROI actual setter then applied");
                Record(new { Case = "actual-single-applied", ROI = property.CvROI.ToString(), Text = host.Workbench.MainActionText, RunCount = document.PreviewRunCount });
                int repeatNotifications = 0; PropertyChangedEventHandler observe = (_, e) => { if (e.PropertyName == nameof(OpenVisionWorkbenchViewModel.MainActionText)) repeatNotifications++; };
                host.Workbench.PropertyChanged += observe;
                try { button.RaiseEvent(new RoutedEventArgs(Button.ClickEvent)); button.RaiseEvent(new RoutedEventArgs(Button.ClickEvent)); }
                finally { host.Workbench.PropertyChanged -= observe; }
                Require(repeatNotifications == 4, "same start/applied re-emits twice");
                string readonlyStatus = host.Workbench.MainActionText; int readonlyViews = probe.ViewsCreated;
                var readOnlyValue = (System.Windows.Controls.WpfPropertyGrid.PropertyItemValue)Activator.CreateInstance(typeof(System.Windows.Controls.WpfPropertyGrid.PropertyItemValue), BindingFlags.Instance | BindingFlags.NonPublic, null, new object[] { new { ParentProperty = new { IsReadOnly = true }, Value = beforeRoi } }, null)!;
                new PropertyGridEditorFactory.WpgROIEditor().ShowDialog(readOnlyValue, button);
                Require(probe.ViewsCreated == readonlyViews && host.Workbench.MainActionText == readonlyStatus, "readonly factory guard no notification");
                probe.MissingInput = true; button.RaiseEvent(new RoutedEventArgs(Button.ClickEvent)); probe.MissingInput = false;
                Require(probe.ViewsCreated == readonlyViews && host.Workbench.MainActionText == readonlyStatus, "missing input guard no start");
                probe.FailCreate = true; button.RaiseEvent(new RoutedEventArgs(Button.ClickEvent)); probe.FailCreate = false;
                Require(host.Workbench.MainActionKind == "Error" && host.Workbench.MainActionText == "오류" && probe.ViewsCreated == readonlyViews, "create failure Error without start");
                probe.FailShow = true; button.RaiseEvent(new RoutedEventArgs(Button.ClickEvent)); probe.FailShow = false;
                Require(host.Workbench.MainActionKind == "Error", "show exception remains Error");
                button.RaiseEvent(new RoutedEventArgs(Button.ClickEvent)); Require(host.Workbench.MainActionText == "ROI를 적용했습니다.", "single retry success");
                probe.Regions = new() { new OpenCvSharp.Rect() }; button.RaiseEvent(new RoutedEventArgs(Button.ClickEvent));
                using (Bitmap actualInput = new(sourcePath)) { Require(property.CvROI == new OpenCvSharp.Rect(0, 0, actualInput.Width, actualInput.Height), "existing zero ROI full-image normalization preserved"); }
                probe.Regions = new() { new(2, 3, 16, 12), new(22, 23, 8, 9) };
                property.USE_MULTI_ROI = true; new PropertyGridEventBinder(null).ApplyVisibilityRules(grid); grid.RefreshSelectedObject(); Pump(4);
                Require(grid.FocusProperty("CvROIS"), "existing multi ROI row"); Pump(3);
