                ScreenshotPngWriter.WriteElementPng(host, Path.ChangeExtension(outputPath, ".matching-factory-recovery.png"), width, height);
                Action<string> active = PropertyGridEditorFactory.GetEditActionCallback(document.View);
                var states = new[]
                {
                    ("Workbench.Action.RoiEditing", "ROI 드래그 · 모서리로 크기 조절 · Enter 적용 · Esc 취소", "Drag ROI · resize from corners · Enter to apply · Esc to cancel"),
