                var icon = FindVisualChildren<MahApps.Metro.IconPacks.PackIconMaterial>(host).Single(item => AutomationProperties.GetAutomationId(item) == "WorkbenchActionIcon");
                foreach (string theme in new[] { "Dark", "Light" })
