                    Require(icon.Kind.ToString() == (error ? "AlertCircle" : "InformationOutline") && host.Workbench.MainActionKind == (error ? "Error" : ""), "projection semantic icon");
                    Require(((SolidColorBrush)status.Foreground).Color == ((SolidColorBrush)host.FindResource("OpenVision.Workbench.SecondaryTextBrush")).Color && ((SolidColorBrush)icon.Foreground).Color == ((SolidColorBrush)host.FindResource(error ? "OpenVision.Workbench.NgBrush" : "OpenVision.Workbench.SecondaryTextBrush")).Color, "projection neutral sentence / semantic Error icon");
                    Rect textBounds = GetElementBounds(host, status), iconBounds = GetElementBounds(host, icon);
                    Require(textBounds.Width > 0 && textBounds.Left >= iconBounds.Right && textBounds.Right <= host.ActualWidth + .1D, "W09 positive bounds/no overlap");
                    string png = Path.ChangeExtension(outputPath, $".{theme}-{locale}-{state.Item1.Split('.').Last()}.png");
                    ScreenshotPngWriter.WriteElementPng(host, png, width, height);
                    Record(new { Case = "projection-display", Width = width, Theme = theme, Locale = locale.ToString(), Key = state.Item1, Expected = expected, Text = status.Text, Icon = icon.Kind.ToString(), TextBounds = textBounds.ToString(), IconBounds = iconBounds.ToString(), PNG = png });
                }
                active("Workbench.Action.RoiApplied"); OpenVisionLanguageService.SetLanguage(OpenVisionLanguage.Korean, false);
                Require(host.Workbench.MainActionText == "ROI를 적용했습니다.", "locale captured key reprojects");
                MethodInfo present = typeof(OpenVisionWorkbenchViewModel).GetMethod("PresentMainAction", BindingFlags.Instance | BindingFlags.NonPublic)!;
                present.Invoke(host.Workbench, new object[] { "Workbench.Action.RecipeSaved", "Ok", "", "", "", "" });
                host.Workbench.Tool.ParametersChanged((long)typeof(OpenVisionWorkbenchToolViewModel).GetField("generation", BindingFlags.Instance | BindingFlags.NonPublic)!.GetValue(host.Workbench.Tool));
                Require(host.Workbench.MainActionText == "레시피를 저장했습니다.", "general refresh does not resurrect old edit");
                document.DeactivateWorkbenchEditor(); string afterClose = host.Workbench.MainActionText; active("Workbench.Action.RoiApplied");
                Require(host.Workbench.MainActionText == afterClose && PropertyGridEditorFactory.GetEditActionCallback(document.View) == null, "inactive captured callback ignored");
                host.Workbench.Dispose(); active("Workbench.Action.TemplateRegistered"); Require(host.Workbench.MainActionText == afterClose, "disposed captured callback ignored");
                Record(new { Case = "lifetime", Locale = true, RefreshNoReplay = true, InactiveIgnored = true, DisposedIgnored = true, ActualLineModal = "U/Astra native" });

