    private static CaptureResult CaptureMainBottomImages(string outputPath)
    {
        OpenVisionShellHostView host = CreateShellHost("Smoke_BottomImages_" + Guid.NewGuid().ToString("N"), false);
        string directory = Path.GetDirectoryName(outputPath)!;
        int[] gray = { 0, 128, 255, 128, 128, 128 };
        string[] names = { "A_gray000.bmp", "B_gray128.bmp", "C_gray255.bmp", "D_gray128.bmp", "E_gray128.bmp", "F_small_gray128.bmp" };
        string[] labels = { "good", "bad", "bad", "good", "", "good" };
        for (int index = 0; index < names.Length; index++)
        {
            using Bitmap bitmap = new(index == 5 ? 80 : 320, index == 5 ? 60 : 240);
            using Graphics graphics = Graphics.FromImage(bitmap);
            graphics.Clear(DrawingColor.FromArgb(gray[index], gray[index], gray[index])); bitmap.Save(Path.Combine(directory, names[index]), ImageFormat.Bmp);
        }
        List<object> cases = new();
        return CaptureWindowWithContent(host, outputPath, 1600, 900, () =>
        {
            OpenVisionLanguageService.SetLanguage(OpenVisionLanguage.Korean, false);
            OpenVisionWorkbenchViewModel model = host.Workbench;
            OpenVisionWorkbenchImagesViewModel images = model.Images;
            OpenVisionWorkbenchPipelineViewModel pipeline = model.Pipeline;
            model.Tool.IsAutoRunEnabled = false; model.IsBottomCollapsed = false; model.SelectedBottomTab = 0;
            VisionPipelineStep step = VisionPipelineStepBuilder.FromProperty(new MeanProperty { NAME = "Six sample mean", USE_ROI = true, CvROI = new OpenCvSharp.Rect(120, 100, 40, 40), USE_THRESHOLD = false, USE_ADAPTIVE_THRESHOLD = false, USE_BITWISENOT = false, MEAN_MIN = 100, MEAN_MAX = 200 }, "Main", "Bottom_Mean");
            if (pipeline.InsertStep(0, step) == null) throw new InvalidOperationException("Bottom Mean ROI definition invalid.");
            pipeline.SelectStepCommand.Execute(0);
            if (!host.LoadMainImageFromFileForTest(Path.Combine(directory, names[0]))) throw new InvalidOperationException("Bottom original input failed.");
            images.AddImages(names.Skip(1).Select(name => new OpenVisionWorkbenchImageItem(Path.Combine(directory, name), name, OpenVisionBitmapImagePreviewFactory.CreateFromPath(Path.Combine(directory, name)))));
            int completions = 0; pipeline.InspectionCompleted += (_, _) => completions++;
            for (int index = 0; index < labels.Length; index++)
            {
                images.Images[index].IsSelected = true; images.LabelCommand.Execute(labels[index]); images.ClearSelectionCommand.Execute(null);
            }
            if (completions != 0 || images.SelectedCount != 0 || !images.HasBeforeImages || images.HasOkImages || images.HasNgImages || images.HasErrorImages) throw new InvalidOperationException("Import/labels must remain unexecuted.");
            foreach (OpenVisionLanguage language in new[] { OpenVisionLanguage.Korean, OpenVisionLanguage.English })
            foreach (string theme in new[] { "Dark", "Light" })
            foreach (int width in new[] { 1600, 1280 })
            {
                OpenVisionLanguageService.SetLanguage(language, false); (theme == "Dark" ? model.SelectDarkThemeCommand : model.SelectLightThemeCommand).Execute(null);
                Window window = Window.GetWindow(host); window.Width = width; window.Height = width == 1600 ? 900 : 760; Pump(4);
                foreach (Border card in FindVisualChildren<Border>(host).Where(item => AutomationProperties.GetAutomationId(item) == "MainImageThumbnail"))
                {
                    OpenVisionWorkbenchImageItem item = (OpenVisionWorkbenchImageItem)card.DataContext;
                    TextBlock verdict = FindVisualChildren<TextBlock>(card).Single(text => text.ToolTip as string == item.ThumbnailResultToolTip && text.Text == item.ThumbnailResultText);
                    TextBlock truth = FindVisualChildren<TextBlock>(card).Single(text => text.Text == item.LabelText && VisualTreeHelper.GetParent(text) is Border);
                    if (verdict.IsVisible || item.ThumbnailResultText.Length != 0 || truth.IsVisible != item.HasLabel || item.ResultText != OpenVisionLanguageService.T("Workbench.Images.Before")) throw new InvalidOperationException("No-result thumbnails must hide verdict and show only explicit truth; list Before semantics preserved.");
                    if (truth.IsVisible)
                    {
                        Rect bounds = truth.TransformToAncestor(card).TransformBounds(new Rect(0, 0, truth.ActualWidth, truth.ActualHeight));
                        if (bounds.Right > card.ActualWidth - 1 || truth.ActualHeight > 20) throw new InvalidOperationException("No-result truth chip must fit fixed136 width.");
                    }
                }
                string capture = Path.ChangeExtension(outputPath, $".before.{language}.{theme}.{width}.png"); ScreenshotPngWriter.WriteDpiAwareWindowPng(window, capture); cases.Add(new { Case = "before-noresult", Language = language.ToString(), Theme = theme, Width = width, Capture = capture });
            }
            OpenVisionLanguageService.SetLanguage(OpenVisionLanguage.Korean, false); Pump(2);
            WaitForTaskWithPump(images.RunBatchForTestAsync(), 20000, "bottom six explicit batch"); Pump(5);
            string[] verdicts = { "Ng", "Ok", "Ng", "Ok", "Ok", "Error" };
            File.WriteAllText(Path.ChangeExtension(outputPath, ".six-diagnostic.json"), JsonSerializer.Serialize(new { completions, Summary = images.BatchSummaryText, CurrentCulture = CultureInfo.CurrentCulture.Name, CatalogPath = OpenVisionLanguageService.CatalogPath, CatalogFormat = OpenVisionLanguageService.T("Workbench.Batch.LabelSummary"), PipelineVerdict = pipeline.VerdictKind, Definition = pipeline.WorkingCopyForTest.Steps.Select(item => new { item.Name, item.Parameters }), Images = images.Images.Select(item => new { item.Name, item.Label, item.ResultKind, item.MismatchKind, ResultVerdict = item.Result?.Verdict, Summaries = item.Result?.Summaries.Select(row => new { row.Key, row.Value.Executed, row.Value.Success, row.Value.IsAcceptanceNg, row.Value.Message, row.Value.Metrics }) }) }, new JsonSerializerOptions { WriteIndented = true }));
            if (completions != 6 || !images.Images.Select(item => item.ResultKind).SequenceEqual(verdicts) || !images.BatchSummaryText.Contains("판정 일치 2/4 (50.0%)") || !images.BatchSummaryText.Contains("과검 1 · 미검 1")) throw new InvalidOperationException("Six verdicts/quality denominator/percentage mismatch.");
            double[] elapsed = images.Images.Select(item => item.Result.ElapsedMilliseconds).OrderBy(value => value).ToArray();
            string expectedTimes = string.Format(CultureInfo.CurrentCulture, OpenVisionLanguageService.T("Workbench.Batch.Times"), OpenVisionPipelineReviewResultPresenter.FormatWorkbenchElapsed(elapsed.Average()), OpenVisionPipelineReviewResultPresenter.FormatWorkbenchElapsed(elapsed[5]), OpenVisionPipelineReviewResultPresenter.FormatWorkbenchElapsed(elapsed[5]));
            if (!images.BatchSummaryText.Contains(expectedTimes)) throw new InvalidOperationException("Independent mean/nearest-rank p95/max elapsed mismatch.");
            string summary = images.BatchSummaryText;
            object[] retained = images.Images.Select(item => (object)item.Result).ToArray();
            int layers = host.LayerDocumentCount, previews = host.NativePreviewRunCount; string route = host.WorkspaceLayerTitle;
            foreach (bool previous in new[] { false, true })
            {
                OpenVisionLanguageService.SetLanguage(OpenVisionLanguage.Korean, false); Pump(2);
                if (previous)
                {
                    images.FilterCommand.Execute("over");
                    VisionPipelineStep edited = VisionPipelineStepEditService.Copy(pipeline.WorkingCopyForTest).Steps[0]; edited.Parameters["MEAN_MIN"] = "101";
                    if (!pipeline.ReplaceStep(0, edited)) throw new InvalidOperationException("Bottom parameter edit failed."); Pump(4);
                    if (!images.IsBatchSummaryStale || images.BatchSummaryText != summary + " · " + OpenVisionLanguageService.T("Workbench.Batch.Stale") || images.HasOkImages || images.HasNgImages || images.HasErrorImages || images.HasOverImages || images.HasUnderImages || images.VisibleImages.Any() || !images.IsOverFilter) throw new InvalidOperationException("Previous must preserve completed summary+timings+warning and the hidden active filter policy.");
                    images.FilterCommand.Execute("before"); if (images.VisibleImages.Count() != 6) throw new InvalidOperationException("Previous images must enter Before."); images.FilterCommand.Execute("all");
                }
                foreach (string theme in new[] { "Dark", "Light" })
                foreach (int width in new[] { 1600, 1280 })
                foreach (OpenVisionLanguage language in new[] { OpenVisionLanguage.Korean, OpenVisionLanguage.English })
                {
                    OpenVisionLanguageService.SetLanguage(language, false);
                    (theme == "Dark" ? model.SelectDarkThemeCommand : model.SelectLightThemeCommand).Execute(null);
                    Window window = Window.GetWindow(host); window.Width = width; window.Height = width == 1600 ? 900 : 760; images.ThumbnailModeCommand.Execute(null); Pump(5);
                    Border[] cards = FindVisualChildren<Border>(host).Where(item => AutomationProperties.GetAutomationId(item) == "MainImageThumbnail").ToArray();
                    if (cards.Length != 6) throw new InvalidOperationException("Six thumbnails must remain realized.");
                    foreach (Border card in cards)
                    {
                        OpenVisionWorkbenchImageItem item = (OpenVisionWorkbenchImageItem)card.DataContext;
                        TextBlock verdict = FindVisualChildren<TextBlock>(card).Single(text => text.Text == item.ThumbnailResultText && text.ToolTip as string == item.ThumbnailResultToolTip);
                        TextBlock truth = FindVisualChildren<TextBlock>(card).Single(text => text.Text == item.LabelText && VisualTreeHelper.GetParent(text) is Border);
                        if (item.MismatchKind.Length > 0 && truth.IsVisible || item.HasLabel && item.MismatchKind.Length == 0 && !truth.IsVisible) throw new InvalidOperationException("Thumbnail must show mismatch instead of truth, else truth beside verdict.");
                        if (truth.IsVisible && !ReferenceEquals(VisualTreeHelper.GetParent(VisualTreeHelper.GetParent(truth)), VisualTreeHelper.GetParent(verdict))) throw new InvalidOperationException("Truth and verdict must share one chip row.");
                        foreach (TextBlock text in new[] { verdict, truth }.Where(text => text.IsVisible && text.Text.Length > 0))
                        {
                            Rect bounds = text.TransformToAncestor(card).TransformBounds(new Rect(0, 0, text.ActualWidth, text.ActualHeight));
                            if (bounds.Right > card.ActualWidth - 1 || bounds.Bottom > card.ActualHeight - 1 || text.ActualHeight > 20) throw new InvalidOperationException("Single thumbnail chip row must not clip/wrap KO/EN Previous Error+Good.");
                            RenderTargetBitmap raster = new((int)Math.Ceiling(card.ActualWidth), (int)Math.Ceiling(card.ActualHeight), 96, 96, PixelFormats.Pbgra32); raster.Render(card);
                            byte[] pixels = new byte[raster.PixelWidth * raster.PixelHeight * 4]; raster.CopyPixels(pixels, raster.PixelWidth * 4, 0); Color ink = ((SolidColorBrush)text.Foreground).Color; int glyphPixels = 0;
                            for (int y = Math.Max(0, (int)bounds.Top + 1); y < Math.Min(raster.PixelHeight, (int)bounds.Bottom - 1); y++)
                            for (int x = Math.Max(0, (int)bounds.Left + (int)text.Padding.Left); x < Math.Min(raster.PixelWidth, (int)bounds.Right - (int)text.Padding.Right); x++)
                            {
                                int pixel = (y * raster.PixelWidth + x) * 4;
                                if (Math.Abs(pixels[pixel] - ink.B) < 20 && Math.Abs(pixels[pixel + 1] - ink.G) < 20 && Math.Abs(pixels[pixel + 2] - ink.R) < 20) glyphPixels++;
                            }
                            if (glyphPixels == 0) throw new InvalidOperationException("Thumbnail chip required glyphs must paint inside their bounds.");
                        }
                        Border inner = FindVisualChildren<Border>(card).Single(border => !border.IsHitTestVisible && border.BorderThickness.Left == 1);
                        Color actual = ((SolidColorBrush)inner.BorderBrush).Color; Color expected = item.MismatchKind.Length > 0 ? ((SolidColorBrush)host.FindResource("OpenVision.Workbench.NgBrush")).Color : Colors.Transparent;
                        if (actual != expected) throw new InvalidOperationException("Mismatch inner border must preserve separate current outline.");
                    }
                    string capture = Path.ChangeExtension(outputPath, $".{(previous ? "previous" : "fresh")}.{theme}.{width}.{language}.png"); ScreenshotPngWriter.WriteDpiAwareWindowPng(window, capture);
                    cases.Add(new { Previous = previous, Theme = theme, Width = width, Language = language.ToString(), Summary = images.BatchSummaryText, Images = images.Images.Select(item => new { item.Name, item.ResultKind, item.MismatchKind, item.LabelText, item.FailedStepText }), Capture = capture });
                }
                if (completions != 6 || host.NativePreviewRunCount != previews || host.LayerDocumentCount != layers || host.WorkspaceLayerTitle != route || !retained.SequenceEqual(images.Images.Select(item => (object)item.Result))) throw new InvalidOperationException("Display/Previous changes must not execute or replace retained image results.");
            }
            OpenVisionLanguageService.SetLanguage(OpenVisionLanguage.Korean, false); Pump(2);
            images.Images[1].IsSelected = true;
            WaitForTaskWithPump(images.RunBatchForTestAsync("selected"), 20000, "bottom fresh selected recovery"); Pump(4);
            if (completions != 7 || images.IsBatchSummaryStale || !images.BatchSummaryText.Contains("1장 · OK 1 · NG 0 · 오류 0") || !images.BatchSummaryText.Contains("판정 일치 0/1 (0.0%)") || images.Images[0].ResultKind != "Previous") throw new InvalidOperationException("Partial fresh summary must exclude stale neighbors.");
            images.SelectAllCommand.Execute(null); images.LabelCommand.Execute(""); images.ClearSelectionCommand.Execute(null); Pump(3);
            if (images.HasGoodImages || images.HasBadImages || images.HasOverImages || images.HasUnderImages || !images.BatchSummaryText.Contains(OpenVisionLanguageService.T("Workbench.Batch.Unlabeled")) || completions != 7) throw new InvalidOperationException("Clear labels must show unspecified summary without Run.");
            WaitForTaskWithPump(images.RunBatchForTestAsync(), 20000, "bottom full valid recovery"); Pump(4);
            if (completions != 13 || !images.Images.Select(item => item.ResultKind).SequenceEqual(verdicts) || images.IsBatchSummaryStale || !images.BatchSummaryText.Contains("6장 · OK 3 · NG 2 · 오류 1")) throw new InvalidOperationException("Explicit full recovery must restore fresh counts.");
            cases.Add(new { Case = "partial-clear-full-recovery", completions, Summary = images.BatchSummaryText });
            File.WriteAllText(Path.ChangeExtension(outputPath, ".cases.json"), JsonSerializer.Serialize(cases, new JsonSerializerOptions { WriteIndented = true }));
        }, captureFloatingToolWindow: false);
    }
    private static CaptureResult CaptureMainBatch(string outputPath, int width, int height, bool layoutOnly = false, bool batchAction = false)
    {
        OpenVisionShellHostView host = CreateShellHost("Smoke_MainBatch", false);
        string directory = Path.GetDirectoryName(outputPath)!;
        string[] paths = new[] { "Batch_64.png", "Batch_128_long_input_name_for_compact_result_list.png", "Batch_200.png" }.Select(name => Path.Combine(directory, name)).ToArray();
        void WriteGray(int index, int value) { using Bitmap image = new(640, 360); using Graphics graphics = Graphics.FromImage(image); graphics.Clear(DrawingColor.FromArgb(value, value, value)); image.Save(paths[index], ImageFormat.Png); }
        for (int index = 0; index < paths.Length; index++) WriteGray(index, new[] { 64, 128, 200 }[index]);
        List<object> cases = new();
        void Record(object value) { cases.Add(value); File.WriteAllText(Path.ChangeExtension(outputPath, ".cases.json"), JsonSerializer.Serialize(cases)); }
        void Require(bool condition, string name) { if (!condition) throw new InvalidOperationException("Main batch: " + name); }
        return CaptureWindowWithContent(host, outputPath, width, height, () =>
        {
            if (batchAction) { OpenVisionLanguageService.SetLanguage(OpenVisionLanguage.Korean, false); }
            OpenVisionWorkbenchPipelineViewModel pipeline = host.Workbench.Pipeline;
            OpenVisionWorkbenchImagesViewModel images = host.Workbench.Images;
            host.Workbench.IsBottomCollapsed = false; host.Workbench.SelectedBottomTab = 0;
            MeanProperty nativeDefaults = new("MainBatch_DefaultProbe");
            File.WriteAllText(Path.ChangeExtension(outputPath, ".defaults.json"), JsonSerializer.Serialize(new { nativeDefaults.USE_THRESHOLD, nativeDefaults.USE_ADAPTIVE_THRESHOLD, nativeDefaults.USE_BITWISENOT, nativeDefaults.USE_ROI }));
            Require(!images.RunBatchCommand.CanExecute("all"), "empty image command");
            if (batchAction)
            {
                string emptyAction = host.Workbench.MainActionText;
                WaitForTaskWithPump(images.RunBatchForTestAsync(), 1000, "empty batch noop");
                Require(host.Workbench.MainActionText == emptyAction, "empty batch keeps action");
                Record(new { Case = "empty-noop", Text = emptyAction });
            }
            Require(host.LoadMainImageFromFileForTest(paths[0]), "owned original image");
            if (batchAction)
            {
                string noSteps = host.Workbench.MainActionText;
                WaitForTaskWithPump(images.RunBatchForTestAsync(), 1000, "no steps batch noop");
                Require(host.Workbench.MainActionText == noSteps, "no steps keeps action");
                Record(new { Case = "no-steps-noop", Text = noSteps });
                images.BatchProgressed += (index, planned, name) =>
                {
                    string expected = $"일괄 검사 중 {index}/{planned} · {name}";
                    if (OpenVisionLanguageService.CurrentLanguage == OpenVisionLanguage.Korean && !pipeline.IsStopRequested) { Require(host.Workbench.MainActionText == expected && host.Workbench.MainActionKind == "Running", "all actual progress after load"); }
                    Record(new { Case = "actual-event-order", Index = index, Planned = planned, Name = name, Text = host.Workbench.MainActionText, Kind = host.Workbench.MainActionKind });
                };
            }
            images.AddImages(paths.Skip(1).Select(path => new OpenVisionWorkbenchImageItem(path, Path.GetFileName(path), OpenVisionBitmapImagePreviewFactory.CreateFromPath(path))));
            for (int index = 0; index < 2; index++)
            {
                VisionPipelineStep step = new() { Name = $"{index + 1:00} Batch mean", ToolType = "Mean", InputLayer = index == 0 ? "Main" : "Batch_Result_1", OutputLayer = $"Batch_Result_{index + 1}" };
                step.Parameters["MEAN_MIN"] = "100"; step.Parameters["MEAN_MAX"] = "180"; step.Parameters["MEAN_TYPES"] = "Mean";
                step.Parameters["USE_THRESHOLD"] = "false"; step.Parameters["USE_ADAPTIVE_THRESHOLD"] = "false"; step.Parameters["USE_BITWISENOT"] = "false"; step.Parameters["USE_ROI"] = "false";
                Require(pipeline.InsertStep(index, step) != null, "two-step setup");
            }
            images.LabelCommand.Execute("good");
            images.Images[1].IsSelected = true; images.Images[2].IsSelected = true; images.LabelCommand.Execute("bad"); images.ClearSelectionCommand.Execute(null);
            int completed = 0, busyObservations = 0;
            pipeline.InspectionCompleted += (_, _) => completed++;
            pipeline.PropertyChanged += (_, _) =>
            {
                if (!pipeline.IsBatchRunning) return;
                busyObservations++;
                Require(!pipeline.CanEdit && !images.CanEdit && !pipeline.RunCommand.CanExecute(null) && !images.RunBatchCommand.CanExecute("all") && !pipeline.TrySave(), "batch edit/re-entry/save guard");
            };
            byte[] working = VisionPipelineExecutionPlan.SerializePipeline(pipeline.WorkingCopyForTest);
            Require(images.RunBatchCommand.CanExecute("all") && !images.RunBatchCommand.CanExecute("selected"), "all/selected command applicability");
            WaitForTaskWithPump(images.RunBatchForTestAsync(), 20000, "Main real three-image batch"); Pump(8);
            File.WriteAllText(Path.ChangeExtension(outputPath, ".all-state.json"), JsonSerializer.Serialize(new { Completed = completed, BusyObservations = busyObservations, images.CurrentIndex, pipeline.IsRunning, images.CanEdit, images.BatchProgressText, images.BatchSummaryText, pipeline.StatusText, Images = images.Images.Select(item => new { item.Name, item.ResultKind, item.FailedStepText, Count = item.Result?.Summaries.Count, Metrics = item.Result?.Summaries.ToDictionary(pair => pair.Key, pair => pair.Value.Metrics) }).ToArray() }));
            Require(completed == 3 && busyObservations > 0 && images.CurrentIndex == 0 && !pipeline.IsRunning && images.CanEdit, "all batch completion/restoration");
            Require(images.Images.Select(item => item.ResultKind).SequenceEqual(new[] { "Ng", "Ok", "Ng" }), "64/128/200 expected verdicts");
            Require(images.Images.Select(item => item.Result.Summaries[0].Metrics["MeanValueAvg"]).SequenceEqual(new[] { 64D, 128D, 200D }), "raw input Mean values with authored preprocessing OFF");
            bool originalPixels = false; host.Workbench.Viewer.ReadImage(host.Workbench.Viewer.Panes[0], image => originalPixels = image?.GetPixel(0, 0).ToArgb() == DrawingColor.FromArgb(64, 64, 64).ToArgb());
            Require(originalPixels, "inspection input copy did not mutate original RGB or alpha");
            Require(images.Images[0].MismatchKind == "over" && images.Images[1].MismatchKind == "under" && images.Images[2].MismatchKind == "", "explicit labels and mismatch");
            Require(images.BatchSummaryText.Contains("OK 1") && images.BatchSummaryText.Contains("NG 2") && working.SequenceEqual(VisionPipelineExecutionPlan.SerializePipeline(pipeline.WorkingCopyForTest)), "held result summary/working copy unchanged");
            if (batchAction)
            {
                Record(new { Case = "actual-all", Text = host.Workbench.MainActionText, Kind = host.Workbench.MainActionKind, OriginalPixels = originalPixels, CurrentIndex = images.CurrentIndex });
                Require(host.Workbench.MainActionText == "일괄 검사 완료 · OK 1 · NG 2 · 오류 0" && host.Workbench.MainActionKind == "Ok", "W09 canonical completion after restore");
            }
            if (!layoutOnly)
            {
                foreach ((string filter, int count) in new[] { ("all", 3), ("ok", 1), ("ng", 2), ("err", 0), ("none", 0), ("over", 1), ("under", 1), ("good", 1), ("bad", 2) })
                {
                    images.FilterCommand.Execute(filter); Require(images.VisibleImages.Count() == count, "filter " + filter); Record(new { Case = "filter", Filter = filter, Count = count });
                }
                images.FilterCommand.Execute("all");
                pipeline.SelectedStepIndex = 1;
                Require(images.TrySelect(images.Images[1]), "restore passed image"); Pump(5);
                bool retainedOutput = false; host.Workbench.Viewer.ReadImage(host.Workbench.Viewer.Panes[1], image => retainedOutput = image?.GetPixel(0, 0).R == 128);
                Require(retainedOutput && pipeline.GetResult(1)?.OutputMean == 128D && completed == 3, "raw per-image output restoration without Run");
                Require(images.TrySelect(images.Images[0]), "restore rejected image"); Pump(5);
                bool skippedEmpty = false; host.Workbench.Viewer.ReadImage(host.Workbench.Viewer.Panes[1], image => skippedEmpty = image == null);
                Require(skippedEmpty && completed == 3, "later skipped output cannot show another image");
                Record(new { Case = "all", Completed = completed, Summary = images.BatchSummaryText, BusyObservations = busyObservations, RetainedOutput = retainedOutput, SkippedEmpty = skippedEmpty });
                OpenVisionWorkbenchImageResult retainedThird = images.Images[2].Result;
                images.Images[1].IsSelected = true; images.Images[2].IsSelected = true;
                EventHandler stopAfterCurrent = (_, _) => pipeline.StopCommand.Execute(null);
                pipeline.InspectionCompleted += stopAfterCurrent;
                try { WaitForTaskWithPump(images.RunBatchForTestAsync("selected"), 20000, "Main stop after current image"); }
                finally { pipeline.InspectionCompleted -= stopAfterCurrent; }
                Pump(5);
                Require(completed == 4 && ReferenceEquals(retainedThird, images.Images[2].Result) && images.CurrentIndex == 0 && !pipeline.IsRunning && !pipeline.StopCommand.CanExecute(null), "selected stop retains unvisited result and recovers commands");
                Require(images.BatchSummaryText.Contains("OK 1") && images.BatchSummaryText.Contains("NG 2"), "stopped summary uses all fresh held results");
                Record(new { Case = "selected-stop", Completed = completed, Summary = images.BatchSummaryText });
                if (batchAction) { Require(host.Workbench.MainActionText == "일괄 검사 중지됨 · OK 1 · NG 2 · 오류 0" && host.Workbench.MainActionKind == "Warning", "W09 stopped retained counts"); }

                images.ClearSelectionCommand.Execute(null); images.Images[1].IsSelected = true;
                VisionPipelineStep changed = VisionPipelineStepEditService.Copy(pipeline.WorkingCopyForTest).Steps[0]; changed.Parameters["MEAN_MIN"] = "80";
                Require(pipeline.ReplaceStep(0, changed), "working parameter change"); Pump(5);
                Require(images.Images.All(item => item.ResultKind == "Previous") && images.IsBatchSummaryStale && !images.HasOkImages && !images.HasNgImages, "recipe change marks every retained result previous");
                images.FilterCommand.Execute("none"); Require(images.VisibleImages.Count() == 3, "previous results counted as before"); images.FilterCommand.Execute("all");
                WaitForTaskWithPump(images.RunBatchForTestAsync("selected"), 20000, "Main fresh selected result after change"); Pump(5);
                Require(completed == 5 && images.Images[1].ResultKind == "Ok" && images.Images[0].ResultKind == "Previous" && images.Images[2].ResultKind == "Previous", "selected fresh result and previous neighbors");
                Require(images.BatchSummaryText.Contains("OK 1") && images.BatchSummaryText.Contains("NG 0"), "previous results excluded from held summary");
                File.WriteAllText(paths[1], "owned invalid image bytes");
                WaitForTaskWithPump(images.RunBatchForTestAsync("selected"), 20000, "Main nonmodal invalid batch image"); Pump(5);
                Require(completed == 5 && images.Images[1].ResultKind == "Error" && images.HasErrorImages && images.CurrentIndex == 0 && images.CanEdit, "decode error retains original input and recovers commands");
                foreach (OpenVisionLanguage language in new[] { OpenVisionLanguage.English, OpenVisionLanguage.Korean })
                {
                    OpenVisionLanguageService.SetLanguage(language, false); Pump(3);
                    Require(images.Images[1].FailedStepText.StartsWith(OpenVisionLanguageService.T("Workbench.Batch.LoadError").Split('{')[0], StringComparison.Ordinal), "decode error language refresh");
                }
                Record(new { Case = "decode-error", Result = images.Images[1].ResultKind, Name = images.Images[1].FailedStepText, CurrentIndex = images.CurrentIndex });
                if (batchAction) { Require(host.Workbench.MainActionText == "일괄 검사 완료 · OK 0 · NG 0 · 오류 1" && host.Workbench.MainActionKind == "Ok", "load error is completed operation with Error count"); }
                WriteGray(1, 128);
                WaitForTaskWithPump(images.RunBatchForTestAsync("selected"), 20000, "Main valid batch retry"); Pump(5);
                Require(completed == 6 && images.Images[1].ResultKind == "Ok" && !images.HasErrorImages, "valid retry replaces error");
            }
            if (batchAction)
            {
                OpenVisionWorkbenchViewModel root = host.Workbench;
                int progressCount = 0;
                Action<int, int, string> progressed = (index, planned, name) =>
                {
                    progressCount++;
                    Require(root.MainActionText == $"일괄 검사 중 {index}/{planned} · {name}" && root.MainActionKind == "Running", "actual progress after load");
                    string beforeGuard = root.MainActionText;
                    WaitForTaskWithPump(images.RunBatchForTestAsync(), 1000, "busy duplicate batch noop");
                    Require(root.MainActionText == beforeGuard, "busy duplicate does not notify");
                    Record(new { Case = "actual-progress", Index = index, Planned = planned, Name = name, Text = root.MainActionText, Kind = root.MainActionKind, BusyNoop = true });
                };
                images.BatchProgressed += progressed;
                try
                {
                    images.ClearSelectionCommand.Execute(null); images.Images[2].IsSelected = true;
                    EventHandler stopLast = (_, _) =>
                    {
                        pipeline.StopCommand.Execute(null);
                        Require(root.MainActionText == "현재 이미지 처리 후 중지…" && root.MainActionKind == "Warning", "actual stop pending false-to-true");
                        Record(new { Case = "actual-stop-pending", Text = root.MainActionText, Kind = root.MainActionKind });
                    };
                    pipeline.InspectionCompleted += stopLast;
                    try { WaitForTaskWithPump(images.RunBatchForTestAsync("selected"), 20000, "batch last-image stop"); }
                    finally { pipeline.InspectionCompleted -= stopLast; }
                    Require(root.MainActionKind == "Ok", "last-image stop retains completed policy");
                    Record(new { Case = "last-image-stop", Text = root.MainActionText, Kind = root.MainActionKind });
                    FieldInfo captureField = typeof(OpenVisionWorkbenchImagesViewModel).GetField("captureInput", BindingFlags.Instance | BindingFlags.NonPublic)!;
                    FieldInfo restoreField = typeof(OpenVisionWorkbenchImagesViewModel).GetField("restoreInput", BindingFlags.Instance | BindingFlags.NonPublic)!;
                    object capture = captureField.GetValue(images), restore = restoreField.GetValue(images);
                    try
                    {
                        captureField.SetValue(images, (Func<Bitmap>)(() => throw new InvalidOperationException("owned snapshot failure")));
                        WaitForTaskWithPump(images.RunBatchForTestAsync("selected"), 20000, "batch snapshot failure");
                        Require(root.MainActionKind == "Error" && !pipeline.IsRunning, "snapshot terminal Error");
                        Record(new { Case = "snapshot-failure", Text = root.MainActionText, Kind = root.MainActionKind });
                        captureField.SetValue(images, capture);
                        FieldInfo loaderField = typeof(OpenVisionWorkbenchImagesViewModel).GetField("loadBatchImage", BindingFlags.Instance | BindingFlags.NonPublic)!;
                        object loader = loaderField.GetValue(images);
                        try
                        {
                            loaderField.SetValue(images, (Func<string, bool>)(_ => throw new InvalidOperationException("owned loader failure")));
                            WaitForTaskWithPump(images.RunBatchForTestAsync("selected"), 20000, "batch loader exception");
                            Require(root.MainActionKind == "Error" && images.CanEdit && images.CurrentIndex == 0, "loader catch Error and original recovery");
                            Record(new { Case = "loader-exception", Text = root.MainActionText, Kind = root.MainActionKind, CurrentIndex = images.CurrentIndex });
                        }
                        finally { loaderField.SetValue(images, loader); }
                        Bitmap ownedSnapshot = null;
                        captureField.SetValue(images, (Func<Bitmap>)(() => ownedSnapshot = ((Func<Bitmap>)capture)()));
                        restoreField.SetValue(images, (Action<Bitmap, string>)((_, _) => throw new InvalidOperationException("owned restore failure")));
                        bool propagated = false;
                        try { WaitForTaskWithPump(images.RunBatchForTestAsync("selected"), 20000, "batch restore failure"); }
                        catch (Exception exception) { propagated = exception.ToString().Contains("owned restore failure", StringComparison.Ordinal); }
                        Require(propagated && root.MainActionKind == "Error" && !pipeline.IsRunning, "restore Error preserves exception propagation");
                        bool snapshotDisposed = false;
                        try { ownedSnapshot.GetPixel(0, 0); } catch (ArgumentException) { snapshotDisposed = true; }
                        Require(snapshotDisposed, "restore throw still disposes owned snapshot");
                        Record(new { Case = "restore-failure", Propagated = propagated, SnapshotDisposed = snapshotDisposed, Text = root.MainActionText, Kind = root.MainActionKind });
                    }
                    finally { captureField.SetValue(images, capture); restoreField.SetValue(images, restore); }
                    WaitForTaskWithPump(images.RunBatchForTestAsync("selected"), 20000, "batch recovery after restore failure");
                    Require(root.MainActionKind == "Ok" && images.CanEdit && !pipeline.IsRunning, "restore failure normal recovery");
                }
                finally { images.BatchProgressed -= progressed; }
                Require(progressCount > 0, "actual progress observed");
                images.ClearSelectionCommand.Execute(null); string noSelection = root.MainActionText;
                WaitForTaskWithPump(images.RunBatchForTestAsync("selected"), 1000, "no selection batch noop");
                Require(root.MainActionText == noSelection, "no selection preserves action");
                VisionPipelineStep noJudgment = new() { Name = "01 Filter no judgment", ToolType = "Filter", InputLayer = "Main", OutputLayer = "Batch_Result_1" };
                Require(pipeline.ReplaceStep(0, noJudgment), "action no judgment setup");
                VisionPipelineStep disabledNeighbor = VisionPipelineStepEditService.Copy(pipeline.WorkingCopyForTest).Steps[1]; disabledNeighbor.Enabled = false;
                Require(pipeline.ReplaceStep(1, disabledNeighbor), "action no judgment disabled neighbor");
                images.Images[2].IsSelected = true;
                WaitForTaskWithPump(images.RunBatchForTestAsync("selected"), 20000, "action no judgment batch");
                Require(images.Images[2].ResultKind == "Done" && root.MainActionText == "일괄 검사 완료 · OK 0 · NG 0 · 오류 0", "Done is not fake OK count");
                Record(new { Case = "no-judgment-action", Text = root.MainActionText, Result = images.Images[2].ResultKind });
                MethodInfo progress = typeof(OpenVisionWorkbenchViewModel).GetMethod("OnBatchProgressed", BindingFlags.Instance | BindingFlags.NonPublic)!;
                MethodInfo finish = typeof(OpenVisionWorkbenchViewModel).GetMethod("OnBatchFinished", BindingFlags.Instance | BindingFlags.NonPublic)!;
                MethodInfo present = typeof(OpenVisionWorkbenchViewModel).GetMethod("PresentMainAction", BindingFlags.Instance | BindingFlags.NonPublic)!;
                TextBlock status = FindVisualChildren<TextBlock>(host).Single(t => AutomationProperties.GetAutomationId(t) == "WorkbenchActionStatus");
                var icon = FindVisualChildren<MahApps.Metro.IconPacks.PackIconMaterial>(host).Single(t => AutomationProperties.GetAutomationId(t) == "WorkbenchActionIcon");
                foreach (string theme in new[] { "Dark", "Light" })
                foreach (OpenVisionLanguage locale in new[] { OpenVisionLanguage.Korean, OpenVisionLanguage.English })
                foreach (string state in new[] { "progress", "stop-pending", "complete", "stopped", "error" })
                {
                    (theme == "Dark" ? root.SelectDarkThemeCommand : root.SelectLightThemeCommand).Execute(null); OpenVisionLanguageService.SetLanguage(locale, false);
                    bool ko = locale == OpenVisionLanguage.Korean;
                    string expected, kind, iconName, brush;
                    if (state == "progress") { progress.Invoke(root, new object[] { 2, 3, "원문_long_batch_image_0123456789.png" }); expected = ko ? "일괄 검사 중 2/3 · 원문_long_batch_image_0123456789.png" : "Batch inspection 2/3 · 원문_long_batch_image_0123456789.png"; kind = "Running"; iconName = "TimerOutline"; brush = "AccentBrush"; }
                    else if (state == "stop-pending") { present.Invoke(root, new object[] { "Workbench.Batch.Stopping", "Warning", "", "", "", "" }); expected = ko ? "현재 이미지 처리 후 중지…" : "Stopping after the current image…"; kind = "Warning"; iconName = "AlertOutline"; brush = "StaleBrush"; }
                    else { string finishKind = state == "error" ? "Error" : state == "stopped" ? "Warning" : "Ok"; finish.Invoke(root, new object[] { finishKind, 1, 2, 3 }); expected = state == "error" ? OpenVisionLanguageService.T("Workbench.Action.RunFailed") : state == "stopped" ? (ko ? "일괄 검사 중지됨 · OK 1 · NG 2 · 오류 3" : "Batch inspection stopped · OK 1 · NG 2 · Errors 3") : (ko ? "일괄 검사 완료 · OK 1 · NG 2 · 오류 3" : "Batch inspection complete · OK 1 · NG 2 · Errors 3"); kind = finishKind; iconName = state == "error" ? "AlertCircle" : state == "stopped" ? "AlertOutline" : "CheckCircle"; brush = state == "error" ? "NgBrush" : state == "stopped" ? "StaleBrush" : "OkBrush"; }
                    Pump(3);
                    Require(status.Text == expected && root.MainActionKind == kind && icon.Kind.ToString() == iconName, "projection independent text/kind/icon " + state);
                    Require(((SolidColorBrush)status.Foreground).Color == ((SolidColorBrush)host.FindResource("OpenVision.Workbench.SecondaryTextBrush")).Color && ((SolidColorBrush)icon.Foreground).Color == ((SolidColorBrush)host.FindResource("OpenVision.Workbench." + brush)).Color, "projection sentence neutral/icon semantic");
                    Require(BindingOperations.IsDataBound(status, TextBlock.TextProperty) && status.TextTrimming == TextTrimming.CharacterEllipsis && (string)status.ToolTip == expected, "bound text/tooltip/ellipsis");
                    Rect textBounds = GetElementBounds(host, status), iconBounds = GetElementBounds(host, icon);
                    Require(textBounds.Width > 0 && textBounds.Left >= iconBounds.Right && textBounds.Right <= host.ActualWidth + .1D, "action positive bounds/no icon overlap");
                    string png = Path.Combine(directory, $"batch-action-{width}-{theme}-{locale}-{state}.png");
                    ScreenshotPngWriter.WriteElementPng(host, png, width, height);
                    Record(new { Case = "projection-display", State = state, Theme = theme, Locale = locale.ToString(), Width = width, Expected = expected, Text = status.Text, Kind = kind, Icon = iconName, TextBounds = textBounds.ToString(), IconBounds = iconBounds.ToString(), PNG = png });
                }
                finish.Invoke(root, new object[] { "Ok", 1, 2, 3 });
                OpenVisionLanguageService.SetLanguage(OpenVisionLanguage.English, false); Require(root.MainActionText == "Batch inspection complete · OK 1 · NG 2 · Errors 3", "captured terminal counts locale");
                OpenVisionLanguageService.SetLanguage(OpenVisionLanguage.Korean, false); Require(root.MainActionText == "일괄 검사 완료 · OK 1 · NG 2 · 오류 3", "captured terminal counts KO recovery");
                string beforeNull = root.MainActionText; bool rejectedNull = false;
                try { root.AttachImages(null); } catch (ArgumentNullException) { rejectedNull = true; }
                Require(rejectedNull && ReferenceEquals(root.Images, images) && root.MainActionText == beforeNull, "null attach preserves publisher");
                var publisher = typeof(OpenVisionWorkbenchImagesViewModel).GetField("BatchFinished", BindingFlags.Instance | BindingFlags.NonPublic)!;
                ((Action<string, int, int, int>)publisher.GetValue(images))?.Invoke("Ok", 4, 5, 6);
                Require(root.MainActionText == "일괄 검사 완료 · OK 4 · NG 5 · 오류 6", "previous publisher after null attach");
                using OpenVisionWorkbenchImagesViewModel replacement = new(root.Shell, _ => false, () => { });
                root.AttachImages(replacement); string beforeDetached = root.MainActionText;
                ((Action<string, int, int, int>)publisher.GetValue(images))?.Invoke("Ok", 7, 8, 9);
                Require(root.MainActionText == beforeDetached, "old publisher detached"); root.AttachImages(images);
                present.Invoke(root, new object[] { "Workbench.Action.RecipeSaved", "Ok", "", "", "", "" });
                string saved = root.MainActionText;
                images.FilterCommand.Execute("all"); OpenVisionLanguageService.SetLanguage(OpenVisionLanguage.English, false);
                Require(root.MainActionText == "Recipe saved.", "followup save projection not replaced by refresh/locale");
                Action<string, int, int, int> heldPublisher = (Action<string, int, int, int>)publisher.GetValue(images);
                root.Dispose(); string closed = root.MainActionText;
                heldPublisher?.Invoke("Ok", 9, 9, 9);
                Require(root.MainActionText == closed && publisher.GetValue(images) == null, "Dispose detaches and suppresses retained callback");
                Record(new { Case = "lifetime-refresh", NullRejected = rejectedNull, OldPublisherDetached = true, DisposeDetached = true, FollowupSave = saved, NoSelectionNoop = true });
                return;
            }
            images.Images[1].IsSelected = true;
            Window window = Window.GetWindow(host);
            foreach (string paletteName in new[] { "Dark", "Light" })
            {
                ResourceDictionary palette = new() { Source = new Uri($"/OpenVisionLab;component/UI/Wpf/OpenVisionWorkbench{paletteName}.xaml", UriKind.Relative) };
                host.Resources.MergedDictionaries.Add(palette);
                try
                {
                    foreach (Size size in new[] { new Size(1920, 1032), new Size(1280, 760) })
                    {
                        window.Width = size.Width; window.Height = size.Height;
                        foreach (OpenVisionLanguage language in new[] { OpenVisionLanguage.Korean, OpenVisionLanguage.English })
                        {
                            OpenVisionLanguageService.SetLanguage(language, false); images.ThumbnailModeCommand.Execute(null); Pump(6);
                            ScrollViewer toolbar = FindVisualChildren<ScrollViewer>(host).Single(item => AutomationProperties.GetAutomationId(item) == "MainImagesToolbarScroll");
                            Require(toolbar.ActualHeight >= 28D + (toolbar.ComputedHorizontalScrollBarVisibility == Visibility.Visible ? 10D : 0D), "image toolbar buttons are not obscured by scrollbar");
                            Button batch = FindVisualChildren<Button>(host).Single(item => AutomationProperties.GetAutomationId(item) == "MainRunBatch");
                            Require(batch.IsEnabled && batch.Command == images.RunBatchCommand && (string)batch.CommandParameter == "all", "rendered batch button binding");
                            batch.ContextMenu.PlacementTarget = batch; batch.ContextMenu.IsOpen = true; Pump(4);
                            MenuItem[] menu = batch.ContextMenu.Items.OfType<MenuItem>().ToArray();
                            Require(menu.Length == 2 && menu.All(item => item.IsEnabled) && menu.Select(item => (string)item.CommandParameter).SequenceEqual(new[] { "all", "selected" }), "batch popup all/selected binding");
                            ScreenshotPngWriter.WriteElementPng(host, Path.Combine(directory, $"batch-cards-{paletteName}-{size.Width}-{language}.png"), (int)size.Width, (int)size.Height);
                            batch.ContextMenu.IsOpen = false; images.ListModeCommand.Execute(null); Pump(6);
                            Require(FindVisualChildren<TextBlock>(host).Any(item => item.IsVisible && item.Text == images.Images[1].ResultText), "rendered retained result badge");
                            ScreenshotPngWriter.WriteElementPng(host, Path.Combine(directory, $"batch-list-{paletteName}-{size.Width}-{language}.png"), (int)size.Width, (int)size.Height);
                            foreach (ScrollBar bar in FindVisualChildren<ScrollBar>(FindVisualChildren<ScrollViewer>(host).Single(item => AutomationProperties.GetAutomationId(item) == "MainImagesListScroll")).Where(item => item.IsVisible && item.ActualWidth > 0D && item.ActualHeight > 0D))
                            {
                                bar.ApplyTemplate(); Track track = bar.Template.FindName("PART_Track", bar) as Track;
                                Require(track?.Thumb?.Background is SolidColorBrush thumb && thumb.Color == ((SolidColorBrush)bar.FindResource("OpenVision.Workbench.FieldBorderBrush")).Color, "regional scrollbar semantic thumb");
                            }
                            Record(new { Case = "display", Palette = paletteName, Width = size.Width, Language = language.ToString(), Summary = images.BatchSummaryText });
                        }
                    }
                }
                finally { host.Resources.MergedDictionaries.Remove(palette); }
            }
            if (layoutOnly)
            {
                OpenVisionWorkbenchImageResult ownedJudged = images.Images[1].Result;
                using (Bitmap retained = ownedJudged.CloneOutput(0)) { Require(retained?.GetPixel(0, 0).R == 128, "judged output exists before item removal"); }
                images.RemoveCommand.Execute(null); Pump(5);
                Require(ownedJudged.CloneOutput(0) == null && images.Count == 2, "item removal releases an actual retained judged bitmap");
                Record(new { Case = "judged-output-release", Released = true });
            }
            if (!layoutOnly)
            {
                VisionPipelineStep nonJudged = new() { Name = "01 Filter no judgment", ToolType = "Filter", InputLayer = "Main", OutputLayer = "Batch_Result_1" };
                Require(pipeline.ReplaceStep(0, nonJudged), "no judgment setup");
                VisionPipelineStep disabled = VisionPipelineStepEditService.Copy(pipeline.WorkingCopyForTest).Steps[1]; disabled.Enabled = false; Require(pipeline.ReplaceStep(1, disabled), "disabled neighbor");
                WaitForTaskWithPump(images.RunBatchForTestAsync("selected"), 20000, "Main no judgment result"); Pump(6);
                Require(images.Images[1].ResultKind == "Done" && !images.HasOkImages && !images.HasNgImages && images.Images[1].MismatchKind == "", "no judgment does not become OK or labeled agreement");
                Record(new { Case = "no-judgment", Result = images.Images[1].ResultKind, Summary = images.BatchSummaryText });
                OpenVisionWorkbenchImageResult ownedResult = images.Images[1].Result; images.RemoveCommand.Execute(null); Pump(5);
                Require(ownedResult.CloneOutput(0) == null && images.Count == 2 && host.NativePreviewRunCount == 0, "removal releases retained output without native preview");
            }
            File.WriteAllText(Path.ChangeExtension(outputPath, ".cases.json"), JsonSerializer.Serialize(cases));
        }, captureFloatingToolWindow: false);
    }

    private static CaptureResult CaptureMainResultOutput(string outputPath, int width, int height)
    {
        OpenVisionShellHostView host = CreateShellHost("Smoke_MainResultOutput", false);
        string directory = Path.GetDirectoryName(outputPath)!;
        string inputPath = Path.Combine(directory, "Main_output_owned_640x360.png");
        using (Bitmap input = new(640, 360)) { using Graphics graphics = Graphics.FromImage(input); graphics.Clear(DrawingColor.FromArgb(128, 128, 128)); input.Save(inputPath, ImageFormat.Png); }
        return CaptureWindowWithContent(host, outputPath, width, height, () =>
        {
            if (!host.LoadMainImageFromFileForTest(inputPath)) throw new InvalidOperationException("Explicit output input setup failed.");
            OpenVisionWorkbenchPipelineViewModel pipeline = host.Workbench.Pipeline;
            for (int index = 0; index < 2; index++)
            {
                VisionPipelineStep step = new() { Name = $"{index + 1:00} Main output mean", ToolType = "Mean", InputLayer = index == 0 ? "Main" : "Mean_Output_1", OutputLayer = $"Mean_Output_{index + 1}" };
                step.Parameters["MEAN_MIN"] = "0"; step.Parameters["MEAN_MAX"] = "255"; step.Parameters["MEAN_TYPES"] = "Mean";
                if (pipeline.InsertStep(index, step) == null) throw new InvalidOperationException("Explicit output step setup failed.");
            }
            byte[] working = VisionPipelineExecutionPlan.SerializePipeline(pipeline.WorkingCopyForTest);
            if (!pipeline.RunCommand.CanExecute(null)) throw new InvalidOperationException("Owned valid input must enable explicit pipeline execution.");
            WaitForTaskWithPump(pipeline.RunForTestAsync(), 12000, "Main explicit two-step output display"); Pump(8);
            if (pipeline.IsRunning || pipeline.ResultCountForTest != 2) throw new InvalidOperationException("Main explicit execution did not retain both step results.");
            host.Workbench.IsBottomCollapsed = false; host.Workbench.SelectedBottomTab = 1;
            pipeline.SelectedStepIndex = 1; Pump(8);
            bool inputPresent = false, outputPresent = false; double? outputMean = pipeline.GetResult(1)?.OutputMean;
            host.Workbench.Viewer.ReadImage(host.Workbench.Viewer.Panes[0], image => inputPresent = image?.Width == 640 && image.Height == 360);
            host.Workbench.Viewer.ReadImage(host.Workbench.Viewer.Panes[1], image => outputPresent = image?.Width == 640 && image.Height == 360 && image.GetPixel(320, 180).R == 128 && image.GetPixel(0, 0).R == 128);
            ScreenshotPngWriter.WriteElementPng(host, Path.Combine(directory, "explicit-output-after-run.png"), width, height);
            File.WriteAllText(Path.ChangeExtension(outputPath, ".output.json"), JsonSerializer.Serialize(new { InputPresent = inputPresent, OutputPresent = outputPresent, OutputMean = outputMean, Count = pipeline.ResultCountForTest, WorkingCopyUnchanged = working.SequenceEqual(VisionPipelineExecutionPlan.SerializePipeline(pipeline.WorkingCopyForTest)), NativePreviewRunCount = host.NativePreviewRunCount }));
            if (!inputPresent || !outputPresent) throw new InvalidOperationException("Main explicit execution retained summaries but follow input/output panes cannot read the produced raw pixels.");
            if (outputMean != 128D || host.NativePreviewRunCount != 0 || !working.SequenceEqual(VisionPipelineExecutionPlan.SerializePipeline(pipeline.WorkingCopyForTest))) throw new InvalidOperationException("Explicit Main output display changed pixels, working recipe or native preview count.");
            var pane = host.Workbench.Viewer.Panes[1];
            host.Workbench.Viewer.Snapshot(pane); Pump(4);
            using (Bitmap changed = new(640, 360)) { using Graphics graphics = Graphics.FromImage(changed); graphics.Clear(DrawingColor.FromArgb(64, 64, 64)); host.AddLayerImageForTest("Mean_Output_2", changed); }
            using (VisionToolResult manual = VisionToolResult.Passed(new OpenCvSharp.Mat(360, 640, OpenCvSharp.MatType.CV_8UC1, new OpenCvSharp.Scalar(64)), TimeSpan.Zero, new Dictionary<string, double>(), Array.Empty<VisionToolOverlay>()))
            {
                pipeline.PublishToolResult(1, VisionPipelineResultSummaryService.CreateStepSummary(2, new VisionPipelineStepResult { Step = pipeline.GetStep(1), ToolResult = manual }));
            }
            bool frozenSame = false;
            host.Workbench.Viewer.ReadImage(pane, image => frozenSame = image?.GetPixel(0, 0).R == 128);
            host.Workbench.Viewer.ClearSnapshotsCommand.Execute(null); Pump(4);
            bool manualCurrent = false;
            host.Workbench.Viewer.ReadImage(pane, image => manualCurrent = image?.GetPixel(0, 0).R == 64);
            if (!frozenSame || !manualCurrent) throw new InvalidOperationException("Frozen Main output or manual result identity fallback is incorrect.");
            WaitForTaskWithPump(pipeline.RunForTestAsync(), 12000, "Main explicit run replaces previous manual output"); Pump(8);
            bool rerunCurrent = false;
            host.Workbench.Viewer.ReadImage(pane, image => rerunCurrent = image?.GetPixel(0, 0).R == 128);
            pipeline.SelectedStepIndex = 0; Pump(4);
            WaitForTaskWithPump(pipeline.RunForTestAsync(true), 12000, "Main prefix preserves later previous output"); Pump(8);
            pipeline.SelectedStepIndex = 1; Pump(4);
            bool prefixPrevious = false;
            host.Workbench.Viewer.ReadImage(pane, image => prefixPrevious = image?.GetPixel(0, 0).R == 128 && pipeline.IsResultPrevious(1));
            if (!rerunCurrent || !prefixPrevious) throw new InvalidOperationException("Main full/prefix run output recovery is incorrect.");

            VisionPipelineStep original = VisionPipelineStepEditService.Copy(pipeline.WorkingCopyForTest).Steps[0];
            VisionPipelineStep failing = VisionPipelineStepEditService.Copy(pipeline.WorkingCopyForTest).Steps[0]; failing.ToolType = "Matching"; failing.Parameters.Clear(); failing.UseAcceptance = false;
            if (!pipeline.ReplaceStep(0, failing)) throw new InvalidOperationException("Main output failure setup could not replace the owned step.");
            WaitForTaskWithPump(pipeline.RunForTestAsync(), 12000, "Main output hides failed and skipped stale pixels"); Pump(8);
            bool errorEmpty = false, skippedEmpty = false;
            pipeline.SelectedStepIndex = 0; Pump(4); host.Workbench.Viewer.ReadImage(pane, image => errorEmpty = image == null);
            pipeline.SelectedStepIndex = 1; Pump(4); host.Workbench.Viewer.ReadImage(pane, image => skippedEmpty = image == null);
            if (!errorEmpty || !skippedEmpty || pipeline.GetResult(0)?.Success != false || pipeline.GetResult(1)?.Executed != false) throw new InvalidOperationException("Main failure/skip displays stale produced pixels as current.");
            ScreenshotPngWriter.WriteElementPng(host, Path.Combine(directory, "explicit-output-failure.png"), width, height);
            if (!pipeline.ReplaceStep(0, original)) throw new InvalidOperationException("Main output recovery setup failed.");
            WaitForTaskWithPump(pipeline.RunForTestAsync(), 12000, "Main valid output recovery after missing runtime template"); Pump(8);
            bool validRecovery = false; host.Workbench.Viewer.ReadImage(pane, image => validRecovery = image?.GetPixel(0, 0).R == 128);
            if (!validRecovery || !pipeline.CanEdit || host.NativePreviewRunCount != 0 || !working.SequenceEqual(VisionPipelineExecutionPlan.SerializePipeline(pipeline.WorkingCopyForTest))) throw new InvalidOperationException("Main failure recovery left stale output, commands or working copy.");
            File.WriteAllText(Path.ChangeExtension(outputPath, ".failure-recovery.json"), JsonSerializer.Serialize(new { ErrorEmpty = errorEmpty, SkippedEmpty = skippedEmpty, ValidRecovery = validRecovery, NativePreviewRunCount = host.NativePreviewRunCount, WorkingCopyUnchanged = true }));
            ScreenshotPngWriter.WriteElementPng(host, Path.Combine(directory, "explicit-output-recovered.png"), width, height);
            File.WriteAllText(Path.ChangeExtension(outputPath, ".recovery.json"), JsonSerializer.Serialize(new { FrozenSame = frozenSame, ManualCurrent = manualCurrent, RerunCurrent = rerunCurrent, PrefixPrevious = prefixPrevious, NativePreviewRunCount = host.NativePreviewRunCount, WorkingCopyUnchanged = working.SequenceEqual(VisionPipelineExecutionPlan.SerializePipeline(pipeline.WorkingCopyForTest)) }));

        }, captureFloatingToolWindow: false);
    }

    private static CaptureResult CaptureMainOutputInput(string outputPath, int width, int height)
    {
        OpenVisionShellHostView host = CreateShellHost("Smoke_MainOutputInput", false);
        string directory = Path.GetDirectoryName(outputPath)!;
        string inputPath = Path.Combine(directory, "Main_input_bridge_owned_640x360.png");
        using (Bitmap input = new(640, 360)) { using Graphics graphics = Graphics.FromImage(input); graphics.Clear(DrawingColor.FromArgb(128, 128, 128)); input.Save(inputPath, ImageFormat.Png); }
        host.Workbench.Tool.ConfigureAutoRunPreference(() => false, _ => { });
        return CaptureWindowWithContent(host, outputPath, width, height, () =>
        {
            if (!host.LoadMainImageFromFileForTest(inputPath)) throw new InvalidOperationException("Input bridge owned image setup failed.");
            OpenVisionWorkbenchPipelineViewModel pipeline = host.Workbench.Pipeline;
            for (int index = 0; index < 2; index++)
            {
                VisionPipelineStep step = new() { Name = $"{index + 1:00} Input bridge mean", ToolType = "Mean", InputLayer = index == 0 ? "Main" : "Main_Result_1", OutputLayer = $"Main_Result_{index + 1}" };
                step.Parameters["MEAN_MIN"] = "0"; step.Parameters["MEAN_MAX"] = "255"; step.Parameters["MEAN_TYPES"] = "Mean";
                step.Parameters["USE_THRESHOLD"] = "false"; step.Parameters["USE_ADAPTIVE_THRESHOLD"] = "false"; step.Parameters["USE_BITWISENOT"] = "false"; step.Parameters["USE_ROI"] = "false";
                if (pipeline.InsertStep(index, step) == null) throw new InvalidOperationException("Input bridge pipeline setup failed.");
            }
            byte[] working = VisionPipelineExecutionPlan.SerializePipeline(pipeline.WorkingCopyForTest);
            WaitForTaskWithPump(pipeline.RunForTestAsync(), 12000, "Main output input explicit setup"); Pump(8);
            OpenVisionNativeToolDocument document = null!;
            ComboBox inputChoice = null!;
            VisionToolInlinePreviewSlot inputPreview = null!;
            int captures = 0, capturedPixel = -1;
            void OpenMean()
            {
                pipeline.SelectedStepIndex = 1; host.SelectToolForTest(VISION_MENU.Mean); Pump(10);
                document = host.ActiveNativeDocumentForTest ?? throw new InvalidOperationException("Main native input bridge document missing.");
                FrameworkElement shell = (FrameworkElement)document.View.FindName("toolShell");
                inputChoice = (ComboBox)shell.FindName("cbInputLayer");
                inputPreview = (VisionToolInlinePreviewSlot)shell.FindName("imgInputPreview");
                document.SetPreviewExecutionOverrideForTest(source =>
                {
                    captures++; capturedPixel = source.At<byte>(180, 320);
                    return VisionToolResult.Passed(source.Clone(), TimeSpan.Zero, new Dictionary<string, double> { ["MeanValueAvg"] = capturedPixel }, Array.Empty<VisionToolOverlay>());
                });
            }
            OpenMean();
            List<string> checks = new();
            void Choose(string key)
            {
                int before = captures;
                inputChoice.SelectedItem = inputChoice.Items.Cast<KeyValuePair<string, string>>().Single(item => item.Key == key);
                Pump(6);
                File.WriteAllText(Path.Combine(directory, "input-choice-current.json"), JsonSerializer.Serialize(new { Key = key, document.RouteInputLayerName, InputLayer = host.Workbench.Tool.InputLayer, host.Workbench.Tool.ToolName, host.Workbench.Tool.IsNewTest, ActiveDocument = ReferenceEquals(document, host.ActiveNativeDocumentForTest), Captures = captures, Before = before }));
                if (document.RouteInputLayerName != key || host.Workbench.Tool.InputLayer != key || captures != before) throw new InvalidOperationException("Input choice changed raw route or executed implicitly: " + key);
            }
            void Run(string label, bool success)
            {
                if (!host.Workbench.Tool.RunCommand.CanExecute(null)) throw new InvalidOperationException("Main explicit input bridge command disabled: " + label);
                int before = document.PreviewRunCount;
                host.Workbench.Tool.RunCommand.Execute(null);
                Stopwatch wait = Stopwatch.StartNew();
                while (document.IsPreviewRunning && wait.Elapsed < TimeSpan.FromSeconds(8)) { Pump(2); Thread.Sleep(5); }
                Pump(8);
                ScreenshotPngWriter.WriteElementPng(host, Path.Combine(directory, "input-bridge-" + label + ".png"), width, height);
                File.WriteAllText(Path.Combine(directory, "input-bridge-" + label + ".json"), JsonSerializer.Serialize(new { document.LastStatusText, document.PreviewRunCount, document.IsPreviewRunning, Captures = captures, CapturedPixel = capturedPixel, host.Workbench.Tool.ResultKind, InputHasImage = inputPreview?.HasImage, InputWidth = inputPreview?.ImagePixelWidth }));
                if (document.IsPreviewRunning || document.HasPreviewResult != success || document.PreviewRunCount != before + (success ? 1 : 0)) throw new InvalidOperationException("Main output -> explicit preview failed: " + label + " / " + document.LastStatusText);
                if (success && (capturedPixel != 128 || inputPreview?.HasImage != true || inputPreview.ImagePixelWidth != 640 || inputPreview.ImagePixelHeight != 360)) throw new InvalidOperationException("Main input capture/preview did not read raw 128GV 640x360: " + label);
                checks.Add(label + ": PASS");
            }
            foreach (string key in new[] { "Main_Result_1", "Main_Result_2", "Main" }) { Choose(key); Run(key, true); }
            VisionPipelineStep original = VisionPipelineStepEditService.CopyStep(pipeline.GetStep(0));
            VisionPipelineStep failing = VisionPipelineStepEditService.CopyStep(original); failing.ToolType = "Matching"; failing.Parameters.Clear(); failing.UseAcceptance = false;
            if (!pipeline.ReplaceStep(0, failing)) throw new InvalidOperationException("Missing output input setup failed.");
            WaitForTaskWithPump(pipeline.RunForTestAsync(), 12000, "Main input bridge failed producer"); Pump(8); OpenMean();
            Choose("Main_Result_1"); int beforeMissing = captures; Run("missing-output", false);
            if (captures != beforeMissing || !document.LastStatusText.Contains("input image missing", StringComparison.Ordinal) || inputPreview?.HasImage == true) throw new InvalidOperationException("Missing output used stale raw pixels or reached the computation delegate.");
            Choose("Main"); Run("Original-recovery", true);
            if (!pipeline.ReplaceStep(0, original)) throw new InvalidOperationException("Main raw output recovery setup failed.");
            WaitForTaskWithPump(pipeline.RunForTestAsync(), 12000, "Main input bridge producer recovery"); Pump(8); OpenMean();
            Choose("Main_Result_2"); Run("output-recovery", true);
            if (!working.SequenceEqual(VisionPipelineExecutionPlan.SerializePipeline(pipeline.WorkingCopyForTest))) throw new InvalidOperationException("Main input bridge changed stored working steps.");
            host.SelectToolForTest(VISION_MENU.Arithmetic); Pump(10);
            OpenVisionNativeToolDocument arithmeticDocument = host.ActiveNativeDocumentForTest!;
            ArithmeticToolWpfView arithmetic = (ArithmeticToolWpfView)arithmeticDocument.View;
            ArithmeticToolSettings settings = arithmetic.CaptureSettings(); settings.UseOffsetMode = false; settings.UseConstantInput = false; settings.SelectedOperation = "ADD";
            arithmetic.ApplyPersistedSettings(settings); arithmeticDocument.RecordParameterChange(null); Pump(8);
            FrameworkElement arithmeticShell = (FrameworkElement)arithmetic.FindName("toolShell");
            foreach (var choice in new[] { ("cbInputA", "Main_Result_2"), ("cbInputB", "Main_Result_1") })
            {
                ComboBox combo = (ComboBox)arithmeticShell.FindName(choice.Item1);
                combo.SelectedItem = combo.Items.Cast<KeyValuePair<string, string>>().Single(item => item.Key == choice.Item2); Pump(5);
            }
            int arithmeticRuns = arithmeticDocument.PreviewRunCount;
            host.Workbench.Tool.RunCommand.Execute(null); Pump(8);
            VisionToolInlinePreviewSlot a = (VisionToolInlinePreviewSlot)arithmeticShell.FindName("imgInputA"), b = (VisionToolInlinePreviewSlot)arithmeticShell.FindName("imgInputB");
            File.WriteAllText(Path.Combine(directory, "input-bridge-arithmetic.json"), JsonSerializer.Serialize(new { arithmeticDocument.LastStatusText, arithmeticDocument.PreviewRunCount, AHasImage = a.HasImage, BHasImage = b.HasImage, RawA = arithmeticDocument.RouteInputLayerName, RawB = arithmeticDocument.RouteInputLayerBName }));
            ScreenshotPngWriter.WriteElementPng(host, Path.Combine(directory, "input-bridge-arithmetic.png"), width, height);
            if (!arithmeticDocument.HasPreviewResult || arithmeticDocument.PreviewRunCount != arithmeticRuns + 1 || !a.HasImage || !b.HasImage || a.ImagePixelWidth != 640 || b.ImagePixelWidth != 640) throw new InvalidOperationException("Main arithmetic A/B cannot resolve both stored output inputs: " + arithmeticDocument.LastStatusText);
            if (!working.SequenceEqual(VisionPipelineExecutionPlan.SerializePipeline(pipeline.WorkingCopyForTest))) throw new InvalidOperationException("Main arithmetic input bridge changed stored working steps.");
            checks.Add("Arithmetic output A/B -> explicit preview: PASS");
            File.WriteAllText(Path.ChangeExtension(outputPath, ".checks.json"), JsonSerializer.Serialize(new { Checks = checks, Captures = captures, WorkingCopyUnchanged = true, AutoRun = false }));
        }, captureFloatingToolWindow: false);
    }

    private static CaptureResult CaptureMainResultsVisual(string outputPath, int width, int height)
    {
        OpenVisionShellHostView host = CreateShellHost("Smoke_MainResultsVisual", false);
        string directory = Path.GetDirectoryName(outputPath)!;
        string inputPath = Path.Combine(directory, "Main_results_visual_owned.png");
        using (Bitmap image = new(640, 360)) { using Graphics graphics = Graphics.FromImage(image); graphics.Clear(DrawingColor.Teal); image.Save(inputPath, ImageFormat.Png); }
        List<object> cases = new();
        return CaptureWindowWithContent(host, outputPath, width, height, () =>
        {
            host.Workbench.IsBottomCollapsed = false; host.Workbench.SelectedBottomTab = 1;
            if (!host.LoadMainImageFromFileForTest(inputPath)) throw new InvalidOperationException("Results visual input setup failed.");
            var pipeline = host.Workbench.Pipeline; var results = host.Workbench.Results;
            VisionPipelineStep[] steps = {
                new() { Name = "01 Very long object result name for exact Main row selection and retained detail", ToolType = "Blob", InputLayer = "Main", OutputLayer = "Visual_Objects", UseAcceptance = true },
                new() { Name = "02 Mean retained result", ToolType = "Mean", InputLayer = "Visual_Objects", OutputLayer = "Visual_Mean" }
            };
            for (int index = 0; index < steps.Length; index++) { pipeline.InsertStep(index, steps[index]); steps[index] = pipeline.GetStep(index); }
            for (int index = 2; index < 24; index++)
            {
                pipeline.InsertStep(index, new VisionPipelineStep { Name = $"{index + 1:00} Additional retained-state row", ToolType = "Mean", InputLayer = "Main", OutputLayer = $"Visual_Long_{index}" });
            }
            using VisionToolResult toolResult = VisionToolResult.Passed(new OpenCvSharp.Mat(360, 640, OpenCvSharp.MatType.CV_8UC1, new OpenCvSharp.Scalar(128)), TimeSpan.FromMilliseconds(12.5D), new Dictionary<string, double> { ["AreaMax"] = 400D, ["MeanValueAvg"] = 128D }, Array.Empty<VisionToolOverlay>());
            var objectResult = VisionPipelineResultSummaryService.CreateStepSummary(1, new VisionPipelineStepResult { Step = steps[0], ToolResult = toolResult, AcceptancePassed = true });
            objectResult.ObjectResults = new[] {
                new VisionPipelineObjectResult { Number = 1, Accepted = true, Area = 120D, CenterX = 90, CenterY = 70, BoundsX = 60, BoundsY = 50, BoundsWidth = 60, BoundsHeight = 40, AppliedMinimumArea = 10, AppliedMaximumArea = 200 },
                new VisionPipelineObjectResult { Accepted = false, Area = 400D, CenterX = 470, CenterY = 260, BoundsX = 420, BoundsY = 220, BoundsWidth = 100, BoundsHeight = 80, RejectReason = "area > 200: rejected candidate retains the measured width, height and applied limits so the operator can compare every recorded reason", AppliedMinimumArea = 10, AppliedMaximumArea = 200 }
            };
            objectResult.ObjectResults = objectResult.ObjectResults.Concat(Enumerable.Range(3, 38).Select(number => new VisionPipelineObjectResult
            {
                Number = number, Accepted = true, Area = 120D, CenterX = number * 10D, CenterY = 70D, BoundsX = number * 10, BoundsY = 50, BoundsWidth = 10, BoundsHeight = 10, AppliedMinimumArea = 10, AppliedMaximumArea = 200
            })).ToArray();
            var meanResult = VisionPipelineResultSummaryService.CreateStepSummary(2, new VisionPipelineStepResult { Step = steps[1], ToolResult = toolResult, AcceptancePassed = true });
            foreach (string key in new[] { "MeanValueMin", "MeanValueMax", "BoundsWidthMin", "BoundsWidthAvg", "BoundsHeightMin", "BoundsHeightAvg", "ResultCount", "AreaMin", "AreaAvg" }) { meanResult.Metrics[key] = 128D; }
            meanResult.Metrics["BoundsWidthAvg"] = 1.2345678901234568E35D;
            pipeline.PublishToolResult(0, objectResult); pipeline.PublishToolResult(1, meanResult); Pump(5);
            DataGrid table = FindVisualChildren<DataGrid>(host).Single(item => AutomationProperties.GetAutomationId(item) == "MainResultsTable");
            if (table.Items.Count != pipeline.Rows.Count) throw new InvalidOperationException("Main results contains an unrun trial row.");
            var binding = new OpenVisionWorkbenchToolViewModel.EditorBinding {
                ToolName = "Mean", DisplayName = () => OpenVisionLanguageService.CurrentLanguage == OpenVisionLanguage.Korean ? "평균 밝기" : "Mean Brightness", EnglishName = "Mean Brightness", LoadParameters = _ => new object(), RestoreParameters = _ => { }, CaptureParameters = () => new object(), ApplyStep = _ => { },
                CreateStep = () => new VisionPipelineStep { ToolType = "Mean", InputLayer = "Main", OutputLayer = "Visual_Trial" }, IsRunning = () => false, SupportsPipeline = true,
                Run = () => throw new InvalidOperationException("Result selection executed the trial")
            };
            long token = host.Workbench.Tool.Activate(null, binding); host.Workbench.Tool.PublishResult(token, meanResult); Pump(5);
            ScreenshotPngWriter.WriteElementPng(host, Path.Combine(directory, "results-trial-in-table.png"), width, height);
            if (table.Items.Count != pipeline.Rows.Count + 1) throw new InvalidOperationException("Canonical trial result is missing from the six-column table.");
            FrameworkElement resultArea = FindVisualChildren<FrameworkElement>(host).Single(item => AutomationProperties.GetAutomationId(item) == "MainResultsView");
            ScrollViewer outer = FindVisualChildren<ScrollViewer>(host).Single(item => AutomationProperties.GetAutomationId(item) == "MainResultsScroll");
            FrameworkElement detailSection = FindVisualChildren<FrameworkElement>(host).Single(item => AutomationProperties.GetAutomationId(item) == "MainResultsDetailSection");
            foreach (double areaWidth in new[] { 780D, 781D, 480D })
            {
                resultArea.Width = areaWidth; resultArea.Height = 160D; Pump(6);
                if (Math.Abs(resultArea.ActualWidth - areaWidth) > 0.1D || results.IsStacked != (areaWidth <= 780D) || Grid.GetRow(detailSection) != (areaWidth <= 780D ? 1 : 0)) throw new InvalidOperationException("Result area780/781 boundary differs from the approved contract.");
                outer.ScrollToBottom(); Pump(3);
                if (outer.ScrollableWidth > 1D || outer.VerticalOffset <= 0D || detailSection.TranslatePoint(new Point(0D, detailSection.ActualHeight), outer).Y > outer.ActualHeight + 1D) throw new InvalidOperationException("Minimum-height result area cannot expose its complete detail section.");
                cases.Add(new { Case = "actual-area-boundary", Width = resultArea.ActualWidth, Height = resultArea.ActualHeight, results.IsStacked, outer.VerticalOffset, outer.ScrollableHeight });
            }
            resultArea.ClearValue(FrameworkElement.WidthProperty); resultArea.ClearValue(FrameworkElement.HeightProperty); Pump(6);
            int runs = host.NativePreviewRunCount, layers = host.LayerDocumentCount; string route = host.WorkspaceLayerTitle;
            byte[] working = VisionPipelineExecutionPlan.SerializePipeline(pipeline.WorkingCopyForTest);
            OpenVisionLanguage initial = OpenVisionLanguageService.CurrentLanguage; Window window = Window.GetWindow(host);
            foreach (string paletteName in new[] { "Dark", "Light" })
            {
                ResourceDictionary palette = new() { Source = new Uri($"/OpenVisionLab;component/UI/Wpf/OpenVisionWorkbench{paletteName}.xaml", UriKind.Relative) }; host.Resources.MergedDictionaries.Add(palette);
                try
                {
                    foreach (Size size in new[] { new Size(1920, 1032), new Size(1280, 760) })
                    {
                        window.Width = size.Width; window.Height = size.Height;
                        foreach (OpenVisionLanguage language in new[] { OpenVisionLanguage.Korean, OpenVisionLanguage.English })
                        {
                            token = host.Workbench.Tool.Activate(null, binding); host.Workbench.Tool.PublishResult(token, meanResult);
                            OpenVisionLanguageService.SetLanguage(language, false); Pump(5);
                            table.SetCurrentValue(Selector.SelectedItemProperty, table.Items[table.Items.Count - 1]); Pump(5);
                            if (!results.IsTrialSelected || !results.IsMetrics || !ReferenceEquals(host.Workbench.Tool.CurrentResult, meanResult)) throw new InvalidOperationException("Trial row selection is disconnected.");
                            var trialRow = table.ItemContainerGenerator.ContainerFromIndex(table.Items.Count - 1) as DataGridRow;
                            if (trialRow == null || !trialRow.IsSelected) throw new InvalidOperationException("Trial row has no selected visual.");
                            double rowBottom = trialRow.TranslatePoint(new Point(0D, trialRow.ActualHeight), table).Y;
                            double bottomBar = FindVisualChildren<ScrollBar>(table).Where(item => item.Orientation == Orientation.Horizontal && item.Visibility == Visibility.Visible).Select(item => item.ActualHeight).DefaultIfEmpty(0D).Max();
                            if (rowBottom > table.ActualHeight - bottomBar) throw new InvalidOperationException("Selected trial row is clipped below the Main result viewport.");
                            DataGrid metricTable = FindVisualChildren<DataGrid>(host).Single(item => AutomationProperties.GetAutomationId(item) == "MainResultsMetrics");
                            string longMetric = results.Metrics.Single(item => item.Value.Length > 35).Value;
                            TextBlock metricValue = FindVisualChildren<TextBlock>(metricTable).Single(item => item.Text == longMetric);
                            ScrollViewer metricDetail = FindVisualChildren<ScrollViewer>(host).Single(item => AutomationProperties.GetAutomationId(item) == "MainResultsDetailScroll");
                            if (!longMetric.EndsWith(" px", StringComparison.Ordinal) || metricValue.TextWrapping != TextWrapping.Wrap || metricValue.ActualHeight < metricValue.FontSize * 2D || metricDetail.ScrollableHeight <= 0D) throw new InvalidOperationException("Long finite metric/unit cannot wrap and scroll inside the bounded detail section.");
                            metricValue.BringIntoView(); Pump(3);
                            ScreenshotPngWriter.WriteElementPng(host, Path.Combine(directory, $"results-long-metric-value-{paletteName}-{(int)size.Width}-{language}.png"), (int)size.Width, (int)size.Height);
                            metricDetail.ScrollToBottom(); outer.ScrollToBottom(); Pump(3);
                            if (metricDetail.VerticalOffset <= 0D) throw new InvalidOperationException("Last retained metric/output aggregate cannot be reached.");
                            string metricCapture = Path.Combine(directory, $"results-long-metrics-{paletteName}-{(int)size.Width}-{language}.png");
                            ScreenshotPngWriter.WriteElementPng(host, metricCapture, (int)size.Width, (int)size.Height);
                            metricDetail.ScrollToTop(); outer.ScrollToTop(); Pump(3);
                            cases.Add(new { Case = "long-finite-metric", Palette = paletteName, Size = size, Language = language.ToString(), Value = longMetric, MetricCount = results.Metrics.Count, metricValue.ActualHeight, metricDetail.ScrollableHeight, Capture = metricCapture });
                            string retainedTrialName = host.Workbench.Tool.CurrentStep.Name;
                            OpenVisionLanguage otherLanguage = language == OpenVisionLanguage.Korean ? OpenVisionLanguage.English : OpenVisionLanguage.Korean;
                            OpenVisionLanguageService.SetLanguage(otherLanguage, false); Pump(4);
                            string otherCaption = otherLanguage == OpenVisionLanguage.Korean ? "평균 밝기" : "Mean Brightness";
                            File.WriteAllText(Path.Combine(directory, "results-language-current-state.json"), JsonSerializer.Serialize(new { language, otherLanguage, otherCaption, results.DetailName, TrialRowName = results.TableRows.Last().Name, ExpectedTrialName = results["Workbench.Results.NewTool"] + " · " + otherCaption, BeforeName = retainedTrialName, AfterName = host.Workbench.Tool.CurrentStep.Name, table.SelectedIndex, Count = table.Items.Count, results.IsTrialSelected, SelectedNumber = results.SelectedTableRow?.Number }));
                            if (results.DetailName != otherCaption || results.TableRows.Last().Name != results["Workbench.Results.NewTool"] + " · " + otherCaption || host.Workbench.Tool.CurrentStep.Name != retainedTrialName || table.SelectedIndex != table.Items.Count - 1) { ScreenshotPngWriter.WriteElementPng(host, Path.Combine(directory, "results-language-reproducer.png"), (int)size.Width, (int)size.Height); throw new InvalidOperationException("Trial language caption is stale or changed the retained step name."); }
                            OpenVisionLanguageService.SetLanguage(language, false); Pump(4);
                            if (size.Width == 1920D)
                            {
                                window.Width = 1280D; window.Height = 760D; Pump(6);
                                var resizedRow = table.ItemContainerGenerator.ContainerFromIndex(table.Items.Count - 1) as DataGridRow;
                                double resizedBar = FindVisualChildren<ScrollBar>(table).Where(item => item.Orientation == Orientation.Horizontal && item.IsVisible).Select(item => item.ActualHeight).DefaultIfEmpty(0D).Max();
                                double resizedBottom = resizedRow?.TranslatePoint(new Point(0D, resizedRow.ActualHeight), table).Y ?? -1D;
                                File.WriteAllText(Path.Combine(directory, "results-resize-current-geometry.json"), JsonSerializer.Serialize(new { Size = size, Language = language.ToString(), RowExists = resizedRow != null, Selected = resizedRow?.IsSelected, RowBottom = resizedBottom, GridHeight = table.ActualHeight, GridWidth = table.ActualWidth, BottomBar = resizedBar, SelectedIndex = table.SelectedIndex, Trial = results.IsTrialSelected, Behavior = OpenVisionLab.Mvvm.Behaviors.InputCommandBehaviors.GetScrollSelectedItemIntoView(table), Scrolls = FindVisualChildren<ScrollViewer>(table).Select(item => new { item.VerticalOffset, item.ViewportHeight, item.ExtentHeight }).ToArray() }));
                                if (resizedRow == null || !resizedRow.IsSelected || resizedBottom > table.ActualHeight - resizedBar) { ScreenshotPngWriter.WriteElementPng(host, Path.Combine(directory, "results-resize-reproducer.png"), 1280, 760); throw new InvalidOperationException("Selected trial row was hidden after resize."); }
                                ScreenshotPngWriter.WriteElementPng(host, Path.Combine(directory, $"results-resize-after-select-{paletteName}-{language}.png"), 1280, 760);
                                window.Width = size.Width; window.Height = size.Height; Pump(5);
                            }
                            trialRow = table.ItemContainerGenerator.ContainerFromIndex(table.Items.Count - 1) as DataGridRow;
                            string rowText = string.Join("|", FindVisualChildren<TextBlock>(trialRow).Select(item => item.Text));
                            string testCaption = language == OpenVisionLanguage.Korean ? "테스트" : "Test";
                            if (!rowText.Contains("＋", StringComparison.Ordinal) || !rowText.Contains(testCaption, StringComparison.Ordinal) || !rowText.Contains("12 ms", StringComparison.Ordinal)) throw new InvalidOperationException("Trial row columns are incomplete: " + rowText);
                            ScrollViewer resultScroll = FindVisualChildren<ScrollViewer>(host).Single(item => AutomationProperties.GetAutomationId(item) == "MainResultsScroll"); resultScroll.ScrollToLeftEnd(); Pump(3);
                            string capture = Path.Combine(directory, $"results-visual-{paletteName}-{(int)size.Width}-{language}-trial.png"); ScreenshotPngWriter.WriteElementPng(host, capture, (int)size.Width, (int)size.Height);
                            table.SetCurrentValue(Selector.SelectedItemProperty, table.Items[0]); Pump(3);
                            pipeline.SelectedStepIndex = 1; pipeline.SelectedStepIndex = 0; Pump(5);
                            if (results.IsTrialSelected || !results.IsObjects || table.SelectedIndex != 0) throw new InvalidOperationException("Pipeline selection did not restore Main object detail.");
                            results.ShowRejected = true; Pump(3);
                            DataGrid objectTable = FindVisualChildren<DataGrid>(host).Single(item => AutomationProperties.GetAutomationId(item) == "MainResultsObjects");
                            ScrollViewer objectScroll = FindVisualChildren<ScrollViewer>(objectTable).First();
                            objectTable.SetCurrentValue(Selector.SelectedItemProperty, results.Objects.Last()); Pump(4);
                            if (!ReferenceEquals(results.SelectedObject, results.Objects.Last()) || objectScroll.VerticalOffset <= 0D || host.Workbench.Viewer.Panes[1].Overlays.All(item => !item.IsSelected)) throw new InvalidOperationException("Last object row cannot scroll, bind and highlight.");
                            objectTable.SetCurrentValue(Selector.SelectedItemProperty, results.Objects[1]); objectScroll.ScrollToRightEnd(); Pump(4);
                            TextBlock reason = FindVisualChildren<TextBlock>(objectTable).Single(item => item.Text == results.Objects[1].Reason);
                            if (reason.TextWrapping != TextWrapping.Wrap || reason.ActualHeight < reason.FontSize * 2D) throw new InvalidOperationException("Long object rejection reason is clipped instead of wrapped.");
                            objectScroll.ScrollToLeftEnd(); Pump(3);
                            var name = FindVisualChildren<TextBlock>(table).FirstOrDefault(item => item.Text == pipeline.Rows[0].Name);
                            if (name == null || name.TextWrapping != TextWrapping.Wrap || name.ActualHeight < name.FontSize * 2D || (string)name.ToolTip != pipeline.Rows[0].Name) throw new InvalidOperationException("Long Main result name does not wrap visibly in its row.");
                            var chips = FindVisualChildren<Border>(host).Where(item => AutomationProperties.GetAutomationId(item) == "MainResultChip" && item.IsVisible).ToArray();
                            if (chips.Length < 4 || chips.Any(item => item.CornerRadius.TopLeft != 10 || item.ActualHeight < 20D)) throw new InvalidOperationException("Main result states have no rendered chip containers.");
                            foreach (Border chip in chips)
                            {
                                string color = chip.Tag?.ToString() switch { "Ok" => "Ok", "Done" => "Done", "Skipped" => "Skip", _ => null };
                                if (color != null && ((SolidColorBrush)System.Windows.Documents.TextElement.GetForeground(chip)).Color != ((SolidColorBrush)chip.FindResource("OpenVision.Workbench." + color + "Brush")).Color) throw new InvalidOperationException("Main result chip foreground does not use the current semantic palette.");
                            }
                            var labels = FindVisualChildren<TextBlock>(host).Where(item => AutomationProperties.GetAutomationId(item).StartsWith("MainArea", StringComparison.Ordinal)).ToArray();
                            if (labels.Length != 2 || labels.Any(item => !item.IsVisible || string.IsNullOrWhiteSpace(item.Text))) throw new InvalidOperationException("Area marker labels are missing.");
                            capture = Path.Combine(directory, $"results-visual-{paletteName}-{(int)size.Width}-{language}-objects.png"); ScreenshotPngWriter.WriteElementPng(host, capture, (int)size.Width, (int)size.Height);
                            cases.Add(new { Palette = paletteName, Size = size, Language = language.ToString(), TrialColumns = rowText, Chips = chips.Select(item => item.Tag?.ToString()).ToArray(), Markers = labels.Select(item => item.Text).ToArray(), Capture = capture });
                        }
                    }
                    foreach (string kind in new[] { "Ng", "Error", "Previous", "Disabled", "Cancelled", "NotRun" })
                    {
                        var state = objectResult.CopyForMainRetention(true);
                        state.IsAcceptanceNg = kind == "Ng"; state.Success = kind != "Error";
                        state.Skipped = kind == "Disabled"; state.Executed = kind is not "Disabled" and not "NotRun";
                        state.ExecutionState = kind == "Cancelled" ? VisionPipelineResultSummaryService.CancelledState : kind == "NotRun" ? VisionPipelineResultSummaryService.NotRunAfterFailureState : VisionPipelineResultSummaryService.ExecutedState;
                        pipeline.PublishToolResult(0, state); if (kind == "Previous") pipeline.InvalidateToolResult(0); Pump(4);
                        var row = table.ItemContainerGenerator.ContainerFromIndex(0) as DataGridRow;
                        Border chip = FindVisualChildren<Border>(row).Single(item => AutomationProperties.GetAutomationId(item) == "MainResultChip");
                        string color = kind switch { "Ng" => "Ng", "Error" => "Error", "Previous" => "Stale", "Disabled" or "Cancelled" => "Skip", _ => "MutedText" };
                        if (chip.Tag?.ToString() != kind || ((SolidColorBrush)System.Windows.Documents.TextElement.GetForeground(chip)).Color != ((SolidColorBrush)chip.FindResource("OpenVision.Workbench." + color + "Brush")).Color) throw new InvalidOperationException("Main result variant chip is stale: " + kind);
                        string capture = Path.Combine(directory, $"results-visual-{paletteName}-{kind}.png"); ScreenshotPngWriter.WriteElementPng(host, capture, 1280, 760);
                        cases.Add(new { Palette = paletteName, Variant = kind, Capture = capture });
                    }
                    pipeline.PublishToolResult(0, objectResult); Pump(3);
                }
                finally { host.Resources.MergedDictionaries.Remove(palette); Pump(2); }
            }
            host.Workbench.Tool.Activate(null, binding, 0); Pump(5);
            if (results.HasTrial || table.Items.Count != pipeline.Rows.Count) throw new InvalidOperationException("Switching to a stored step kept a stale trial row.");
            if (host.NativePreviewRunCount != runs || host.LayerDocumentCount != layers || host.WorkspaceLayerTitle != route || !working.SequenceEqual(VisionPipelineExecutionPlan.SerializePipeline(pipeline.WorkingCopyForTest))) throw new InvalidOperationException("Main result presentation changed execution/data/layers/route.");
            OpenVisionLanguageService.SetLanguage(initial, false); Pump(3);
            File.WriteAllText(Path.ChangeExtension(outputPath, ".visual-cases.json"), JsonSerializer.Serialize(cases, new JsonSerializerOptions { WriteIndented = true }));
        });
    }

    private static CaptureResult CaptureMainResults(string outputPath, int width, int height)
    {
        OpenVisionShellHostView host = CreateShellHost("Smoke_MainResults", false);
        string directory = Path.GetDirectoryName(outputPath)!;
        string inputPath = Path.Combine(directory, "Main_results_owned_640x360.png");
        using (Bitmap image = new(640, 360)) { using Graphics graphics = Graphics.FromImage(image); graphics.Clear(DrawingColor.Teal); image.Save(inputPath, ImageFormat.Png); }
        List<object> cases = new();
        return CaptureWindowWithContent(host, outputPath, width, height, () =>
        {
            OpenVisionWorkbenchPipelineViewModel pipeline = host.Workbench.Pipeline;
            OpenVisionWorkbenchResultsViewModel results = host.Workbench.Results;
            host.Workbench.IsBottomCollapsed = false; host.Workbench.SelectedBottomTab = 1; Pump(6);
            if (results.HasInput || results.HasResult) throw new InvalidOperationException("Empty Main results are not empty.");
            ScreenshotPngWriter.WriteElementPng(host, Path.Combine(directory, "results-empty.png"), width, height);
            if (!host.LoadMainImageFromFileForTest(inputPath)) throw new InvalidOperationException("Results input setup failed.");
            VisionPipelineStep[] steps = {
                new() { Name = "01 Blob objects and rejected candidates", ToolType = "Blob", InputLayer = "Main", OutputLayer = "Results_Objects", UseAcceptance = true, AcceptanceMetricName = "AreaMax" },
                new() { Name = "02 Matching candidates", ToolType = "Matching", InputLayer = "Results_Objects", OutputLayer = "Results_Matches", UseAcceptance = true },
                new() { Name = "03 Mean values", ToolType = "Mean", InputLayer = "Results_Matches", OutputLayer = "Results_Mean", UseAcceptance = true }
            };
            steps[0].Parameters["MIN_AREA"] = "10"; steps[0].Parameters["MAX_AREA"] = "200";
            for (int index = 0; index < steps.Length; index++)
            {
                if (pipeline.InsertStep(index, steps[index]) == null) throw new InvalidOperationException("Results step setup failed.");
                steps[index] = pipeline.GetStep(index);
                using Bitmap layer = new(inputPath);
                if (!host.AddLayerImageForTest(steps[index].OutputLayer, layer)) throw new InvalidOperationException("Results output setup failed.");
            }
            VisionPipelineStepResultSummary[] summaries = new VisionPipelineStepResultSummary[3];
            for (int index = 0; index < summaries.Length; index++)
            {
                using VisionToolResult toolResult = VisionToolResult.Passed(new OpenCvSharp.Mat(360, 640, OpenCvSharp.MatType.CV_8UC1, new OpenCvSharp.Scalar(128)), TimeSpan.FromMilliseconds(12.5D),
                    new Dictionary<string, double> { ["AreaMax"] = 300D, ["MeanValueAvg"] = 128D, ["ResultCount"] = 2D }, Array.Empty<VisionToolOverlay>());
                VisionPipelineMatchResultEvidence captured = new() { NativeIndex = 7, SourceStep = steps[index].Name, CoordinateLayer = steps[index].InputLayer, ImageWidth = 640, ImageHeight = 360,
                    Score = 0.923D, CenterX = 210D, CenterY = 130D, BoundsX = 160D, BoundsY = 100D, BoundsWidth = 100D, BoundsHeight = 60D, Angle = 2.5D, Scale = 1D };
                if (index == 1) VisionPipelineMatchResultStore.Set(toolResult, new[] { captured });
                summaries[index] = VisionPipelineResultSummaryService.CreateStepSummary(index + 1, new VisionPipelineStepResult { Step = steps[index], ToolResult = toolResult, AcceptancePassed = true });
                if (index == 2)
                {
                    foreach (string name in new[] { "MeanValueMin", "MeanValueMax", "MeanValueAvg", "BoundsWidthMin", "BoundsWidthAvg", "BoundsHeightMin", "BoundsHeightAvg" })
                    { summaries[index].Metrics[name] = name.StartsWith("Mean", StringComparison.Ordinal) ? 128D : name.StartsWith("BoundsWidth", StringComparison.Ordinal) ? 640D : 360D; }
                }
                captured.Score = 0D;
                if (index == 1 && summaries[index].MatchResults.Single().Score != 0.923D) throw new InvalidOperationException("Summary does not isolate retained matching evidence.");
                if (summaries[index].OutputMean != 128D || summaries[index].OutputMinimum != 128D || summaries[index].OutputMaximum != 128D) throw new InvalidOperationException("Output pixel statistics do not match supplied image bytes.");
                string serialized = JsonSerializer.Serialize(summaries[index]);
                if (serialized.Contains("\"MatchResults\"", StringComparison.Ordinal) || serialized.Contains("\"OutputMean\"", StringComparison.Ordinal)) throw new InvalidOperationException("Display projection changed persisted summary JSON.");
                if (index == 0) summaries[index].ObjectResults = new[] {
                    new VisionPipelineObjectResult { Number = 1, CandidateId = "11", Accepted = true, Area = 120D, CenterX = 90D, CenterY = 70D, BoundsX = 60, BoundsY = 50, BoundsWidth = 60, BoundsHeight = 40, AppliedMinimumArea = 10, AppliedMaximumArea = 200 },
                    new VisionPipelineObjectResult { Number = 2, CandidateId = "12", Accepted = true, Area = 180D, CenterX = 280D, CenterY = 170D, BoundsX = 240, BoundsY = 140, BoundsWidth = 80, BoundsHeight = 60, AppliedMinimumArea = 10, AppliedMaximumArea = 200 },
                    new VisionPipelineObjectResult { CandidateId = "13", Accepted = false, Area = 5D, CenterX = 30D, CenterY = 25D, BoundsX = 20, BoundsY = 20, BoundsWidth = 20, BoundsHeight = 10, RejectReasonCode = "AreaTooSmall", RejectReason = "area < 10", AppliedMinimumArea = 10, AppliedMaximumArea = 200 },
                    new VisionPipelineObjectResult { CandidateId = "14", Accepted = false, Area = 400D, CenterX = 470D, CenterY = 260D, BoundsX = 420, BoundsY = 220, BoundsWidth = 100, BoundsHeight = 80, RejectReasonCode = "AreaTooLarge", RejectReason = "area > 200", AppliedMinimumArea = 10, AppliedMaximumArea = 200 }
                };
                pipeline.PublishToolResult(index, summaries[index]);
            }
            int runs = host.NativePreviewRunCount, layers = host.LayerDocumentCount;
            string route = host.WorkspaceLayerTitle;
            byte[] working = VisionPipelineExecutionPlan.SerializePipeline(pipeline.WorkingCopyForTest);
            DataGrid Table(string id) => FindVisualChildren<DataGrid>(host).Single(item => AutomationProperties.GetAutomationId(item) == id);
            DataGrid table = Table("MainResultsTable");
            if (table.Columns.Count != 6 || !table.IsReadOnly) throw new InvalidOperationException("Main stage result table is not the required six-column read-only view.");
            table.SetCurrentValue(System.Windows.Controls.Primitives.Selector.SelectedItemProperty, results.TableRows[0]); Pump(6);
            if (pipeline.SelectedStepIndex != 0 || !results.IsObjects || results.Objects.Count != 2) throw new InvalidOperationException("Main row-to-pipeline selection or detected-object filter is disconnected.");
            pipeline.SelectedStepIndex = 1; Pump(6);
            File.WriteAllText(Path.Combine(directory, "results-selection-contract.json"), JsonSerializer.Serialize(new { ReferenceSame = ReferenceEquals(table.SelectedItem, results.TableRows[1]), ValueSame = Equals(table.SelectedItem, results.TableRows[1]), SourceSame = ReferenceEquals((table.SelectedItem as OpenVisionWorkbenchResultRowViewModel)?.Step, pipeline.Rows[1]), pipeline.SelectedStepIndex, results.IsMatching, Scores = results.Objects.Select(item => item.ScoreText).ToArray() }));
            if (!Equals(table.SelectedItem, results.TableRows[1]) || !ReferenceEquals((table.SelectedItem as OpenVisionWorkbenchResultRowViewModel)?.Step, pipeline.Rows[1]) || !results.IsMatching || results.Objects.Single().ScoreText != "0.923") throw new InvalidOperationException("Pipeline-to-Main selection or matching candidate data is disconnected.");
            pipeline.SelectedStepIndex = 0; results.ShowRejected = true; Pump(6);
            if (results.Objects.Count != 4 || results.AreaBins.Count != 48 || !results.ShowMinimumMarker || !results.ShowMaximumMarker
                || Math.Abs(results.MinimumMarkerX - (10D + 10D / 440D * 480D)) > 0.000001D) throw new InvalidOperationException("Object histogram/filter/recorded area limits disagree with supplied candidates.");
            DataGrid objectsTable = Table("MainResultsObjects"); objectsTable.SetCurrentValue(System.Windows.Controls.Primitives.Selector.SelectedItemProperty, results.Objects[2]); Pump(6);
            if (!ReferenceEquals(results.SelectedObject, results.Objects[2])) throw new InvalidOperationException("Object selection binding is disconnected.");
            var output = host.Workbench.Viewer.Panes[1];
            OpenVisionMainPaneOverlay selected = output.Overlays.Single(item => item.IsSelected);
            if (selected.Shape.Bounds != new System.Drawing.RectangleF(20, 20, 20, 10) || output.Overlays.Count(item => item.IsRejected) != 2) throw new InvalidOperationException("Selected/rejected object geometry disagrees with retained result coordinates.");
            host.Workbench.Viewer.Snapshot(output); Pump(4);
            var frozen = output.Overlays.Single(item => item.IsSelected).Shape.Bounds;
            results.SelectedObject = results.Objects[0]; Pump(4);
            if (output.Overlays.Single(item => item.IsSelected).Shape.Bounds != frozen) throw new InvalidOperationException("Changing result selection rewrote a frozen snapshot.");
            output.Source = "follow:out"; results.ShowRejected = false; Pump(4);
            if (results.Objects.Count != 2 || output.Overlays.Any(item => item.IsRejected)) throw new InvalidOperationException("Hidden rejected candidates remain displayed.");
            results.SelectedObject = results.Objects[0]; pipeline.InvalidateToolResult(0); Pump(6);
            if (results.DetailKind != "Previous" || pipeline.Rows[0].ResultElapsedText == string.Empty) throw new InvalidOperationException("Previous result indicator lost the retained elapsed time.");
            pipeline.PublishToolResult(0, summaries[0]); results.ShowRejected = true; Pump(6);
            if (results.SelectedObject != null || output.Overlays.Any(item => item.IsSelected)) throw new InvalidOperationException("Replacing the selected result kept a stale object highlight.");
            OpenVisionLanguage initial = OpenVisionLanguageService.CurrentLanguage;
            Window window = Window.GetWindow(host);
            foreach (string paletteName in new[] { "Dark", "Light" })
            {
                ResourceDictionary palette = new() { Source = new Uri($"/OpenVisionLab;component/UI/Wpf/OpenVisionWorkbench{paletteName}.xaml", UriKind.Relative) };
                host.Resources.MergedDictionaries.Add(palette);
                try
                {
                    foreach (Size size in new[] { new Size(1920, 1032), new Size(1280, 760) })
                    {
                        window.Width = size.Width; window.Height = size.Height;
                        foreach (OpenVisionLanguage language in new[] { OpenVisionLanguage.Korean, OpenVisionLanguage.English })
                        {
                            OpenVisionLanguageService.SetLanguage(language, false); Pump(8);
                            for (int index = 0; index < 3; index++)
                            {
                                table.SetCurrentValue(System.Windows.Controls.Primitives.Selector.SelectedItemProperty, results.TableRows[index]); Pump(6);
                                if (!Equals(table.SelectedItem, results.SelectedTableRow) || pipeline.SelectedStepIndex != index) throw new InvalidOperationException("Locale/layout refresh lost result selection binding.");
                                ScrollViewer resultScroll = FindVisualChildren<ScrollViewer>(host).Single(item => AutomationProperties.GetAutomationId(item) == "MainResultsScroll");
                                FrameworkElement stepSection = FindVisualChildren<FrameworkElement>(host).Single(item => AutomationProperties.GetAutomationId(item) == "MainResultsStepSection");
                                FrameworkElement detailSection = FindVisualChildren<FrameworkElement>(host).Single(item => AutomationProperties.GetAutomationId(item) == "MainResultsDetailSection");
                                FrameworkElement area = FindVisualChildren<FrameworkElement>(host).Single(item => AutomationProperties.GetAutomationId(item) == "MainResultsView");
                                bool stacked = area.ActualWidth <= 780D;
                                if (results.IsStacked != stacked || Grid.GetRow(detailSection) != (stacked ? 1 : 0) || Grid.GetColumn(detailSection) != (stacked ? 0 : 1)) throw new InvalidOperationException("Result layout is not driven by its actual available area width.");
                                if (resultScroll.ScrollableWidth > 1D || stepSection.ActualHeight < 180D || detailSection.ActualHeight < 180D) throw new InvalidOperationException("Main results retained its outer horizontal workaround or lost accessible section height.");
                                ScrollViewer tableScroll = FindVisualChildren<ScrollViewer>(table).First();
                                tableScroll.ScrollToRightEnd(); Pump(3);
                                if (tableScroll.ScrollableWidth > 0D && tableScroll.HorizontalOffset <= 0D) throw new InvalidOperationException("Step result final value/time column cannot be reached.");
                                tableScroll.ScrollToLeftEnd();
                                DataGrid detailTable = Table(index == 0 ? "MainResultsObjects" : index == 1 ? "MainResultsCandidates" : "MainResultsMetrics");
                                ScrollViewer detailTableScroll = FindVisualChildren<ScrollViewer>(detailTable).First();
                                detailTableScroll.ScrollToRightEnd(); Pump(3);
                                if (detailTableScroll.ScrollableWidth > 0D && detailTableScroll.HorizontalOffset <= 0D) throw new InvalidOperationException("Object/candidate/metric final column cannot be reached.");
                                detailTableScroll.ScrollToLeftEnd();
                                resultScroll.ScrollToBottom(); Pump(3);
                                if (resultScroll.ScrollableHeight > 0D && resultScroll.VerticalOffset <= 0D) throw new InvalidOperationException("Stacked detail section has no outer vertical access.");
                                if (detailSection.TranslatePoint(new Point(0D, detailSection.ActualHeight), resultScroll).Y > resultScroll.ActualHeight + 1D) throw new InvalidOperationException("Result detail end remains outside the viewport after scrolling.");
                                resultScroll.ScrollToTop(); Pump(3);
                                foreach (ScrollBar detailBar in FindVisualChildren<ScrollBar>(resultScroll).Where(item => item.IsVisible && item.ActualHeight > 0D && item.ActualWidth > 0D))
                                {
                                    detailBar.ApplyTemplate(); Track detailTrack = detailBar.Template.FindName("PART_Track", detailBar) as Track;
                                    if (detailTrack?.Thumb == null || (detailTrack.Thumb.Background as SolidColorBrush)?.Color != ((SolidColorBrush)detailBar.FindResource("OpenVision.Workbench.FieldBorderBrush")).Color) throw new InvalidOperationException("Main result scrollbar retains its native platform thumb.");
                                }
                                if (index == 2 && results.Metrics.Any(item => item.Name is "MeanValueMin" or "MeanValueMax" or "BoundsWidthMin" or "BoundsWidthAvg" or "BoundsHeightMin" or "BoundsHeightAvg")) throw new InvalidOperationException("Main result labels retain raw metric identifiers.");
                                if (index == 2 && results.Metrics.Count(item => item.Value == "128.0 GV") != 3) throw new InvalidOperationException("Main brightness values lost GV units.");
                                if (index == 0)
                                {
                                    results.ShowRejected = true; results.SelectedObject = results.Objects[0]; Pump(4);
                                    CheckBox rejectedChoice = FindVisualChildren<CheckBox>(host).Single(item => AutomationProperties.GetAutomationId(item) == "MainResultsShowRejected");
                                    rejectedChoice.ApplyTemplate();
                                    Border rejectedBox = rejectedChoice.Template.FindName("box", rejectedChoice) as Border;
                                    if (rejectedBox == null || ((SolidColorBrush)rejectedBox.Background).Color != ((SolidColorBrush)rejectedChoice.FindResource("OpenVision.Workbench.AccentBrush")).Color) throw new InvalidOperationException("Main result checkbox leaks its platform checked background.");
                                    rejectedChoice.SetCurrentValue(System.Windows.Controls.Primitives.ToggleButton.IsCheckedProperty, false); Pump(2);
                                    if (results.ShowRejected || results.Objects.Count != 2 || ((SolidColorBrush)rejectedBox.Background).Color != ((SolidColorBrush)rejectedChoice.FindResource("OpenVision.Workbench.PanelBrush")).Color) throw new InvalidOperationException("Main result checkbox unchecked binding/theme is stale.");
                                    if (size.Width == 1920 && language == OpenVisionLanguage.English) ScreenshotPngWriter.WriteElementPng(host, Path.Combine(directory, $"results-{paletteName}-unchecked.png"), (int)size.Width, (int)size.Height);
                                    rejectedChoice.SetCurrentValue(System.Windows.Controls.Primitives.ToggleButton.IsCheckedProperty, true);
                                    rejectedChoice.IsEnabled = false; Pump(2);
                                    if (rejectedBox.Opacity != 0.55D) throw new InvalidOperationException("Main result checkbox disabled visual is missing.");
                                    if (size.Width == 1920 && language == OpenVisionLanguage.English) ScreenshotPngWriter.WriteElementPng(host, Path.Combine(directory, $"results-{paletteName}-disabled.png"), (int)size.Width, (int)size.Height);
                                    rejectedChoice.IsEnabled = true; Pump(2);
                                    ScrollViewer detailScroll = FindVisualChildren<ScrollViewer>(host).Single(item => AutomationProperties.GetAutomationId(item) == "MainResultsDetailScroll");
                                    if (size.Width == 1280 && detailScroll.ScrollableHeight <= 0D) throw new InvalidOperationException("Compact result objects cannot be reached through scrolling.");
                                    detailScroll.ScrollToBottom(); Pump(3);
                                    if (size.Width == 1280 && detailScroll.VerticalOffset <= 0D) throw new InvalidOperationException("Compact result detail scroll did not expose its lower content.");
                                    detailScroll.ScrollToTop(); Pump(3);
                                    string[] expectedHeaders = { "#", results["Workbench.Results.Step"], results["Workbench.Results.Tool"], results["Workbench.Results.Result"], results["Workbench.Results.Summary"], results["Workbench.Results.Time"] };
                                    foreach (var header in FindVisualChildren<System.Windows.Controls.Primitives.DataGridColumnHeader>(table).Where(item => item.Column != null))
                                    {
                                        string actualHeader = string.Join(string.Empty, FindVisualChildren<TextBlock>(header).Select(item => item.Text));
                                        if (actualHeader != expectedHeaders[header.Column.DisplayIndex]) throw new InvalidOperationException("Rendered Main result header is empty/stale: " + header.Column.DisplayIndex + " / " + actualHeader);
                                    }
                                }
                                if (index == 1 && (Table("MainResultsCandidates").Columns.Count != 6 || results.Objects.Count != 1)) throw new InvalidOperationException("Matching candidate table is incomplete.");
                                if (index == 2 && (!results.IsMetrics || results.OutputStatisticsText.IndexOf("128", StringComparison.Ordinal) < 0)) throw new InvalidOperationException("Metrics/output statistics are disconnected.");
                                FrameworkElement resultView = FindVisualChildren<FrameworkElement>(host).Single(item => AutomationProperties.GetAutomationId(item) == "MainResultsView");
                                if (!new Rect(new Point(), host.RenderSize).Contains(new Rect(resultView.TranslatePoint(new Point(), host), resultView.RenderSize))) throw new InvalidOperationException("Main result region is outside its host.");
                                string capture = Path.Combine(directory, $"results-{paletteName}-{(int)size.Width}-{language}-{index}.png");
                                ScreenshotPngWriter.WriteElementPng(host, capture, (int)size.Width, (int)size.Height);
                                cases.Add(new { Palette = paletteName, Size = size, Language = language.ToString(), Step = index, Result = pipeline.Rows[index].ResultStatusText, Objects = results.Objects.Count, Statistics = results.OutputStatisticsText, Capture = capture });
                            }
                        }
                    }
                }
                finally { host.Resources.MergedDictionaries.Remove(palette); Pump(2); }
            }
            var binding = new OpenVisionWorkbenchToolViewModel.EditorBinding {
                ToolName = "Mean", DisplayName = () => "Mean test", EnglishName = "Mean",
                LoadParameters = _ => new object(), RestoreParameters = _ => { }, CaptureParameters = () => new object(),
                CreateStep = () => new VisionPipelineStep { ToolType = "Mean", InputLayer = "Main", OutputLayer = "Results_Trial" },
                IsRunning = () => false, SupportsPipeline = true, Run = () => throw new InvalidOperationException("Display selection executed the trial")
            };
            long token = host.Workbench.Tool.Activate(null, binding);
            host.Workbench.Tool.PublishResult(token, summaries[2]); Pump(5);
            if (!results.HasTrial || !results.SelectTrialCommand.CanExecute(null)) throw new InvalidOperationException("Retained new-tool result is not selectable in Main.");
            results.SelectTrialCommand.Execute(null); Pump(5);
            if (!results.IsTrialSelected || !results.IsMetrics || !ReferenceEquals(host.Workbench.Tool.CurrentResult, summaries[2])) throw new InvalidOperationException("Main trial selection changed or failed to project retained result.");
            ScreenshotPngWriter.WriteElementPng(host, Path.Combine(directory, "results-trial.png"), 1280, 760);
            table.SetCurrentValue(System.Windows.Controls.Primitives.Selector.SelectedItemProperty, results.TableRows[0]); Pump(5);
            if (results.IsTrialSelected || pipeline.SelectedStepIndex != 0) throw new InvalidOperationException("Returning from trial result did not restore stage detail.");
            if (host.NativePreviewRunCount != runs || host.LayerDocumentCount != layers || host.WorkspaceLayerTitle != route
                || !working.SequenceEqual(VisionPipelineExecutionPlan.SerializePipeline(pipeline.WorkingCopyForTest))) throw new InvalidOperationException("Main result display mutated execution/layer/route/working copy.");
            OpenVisionLanguageService.SetLanguage(initial, false); Pump(4);
            File.WriteAllText(Path.ChangeExtension(outputPath, ".results-cases.json"), JsonSerializer.Serialize(cases, new JsonSerializerOptions { WriteIndented = true }));
        });
    }


    private static CaptureResult CaptureMainRunBar(string outputPath, int width, int height, bool commands = false, bool batchOnly = false)
    {
        GlobalState global = new(); global.Recipe.Name = "Smoke_MainRunBar_" + Guid.NewGuid().ToString("N");
        VisionPipelineStorage.Save(global.Recipe.Name, new VisionPipeline { Name = "Main" }); global.System.SaveWorkbenchLayout(new SystemStateConfig());
        using DisplayManagerService display = new(); OpenVisionShellHostWindow window = new(new ApplicationRuntimeContext(global, display));
        window.ClearValue(OpenVisionShellHostWindow.ClosingCommandProperty); OpenVisionShellHostView host = window.ShellHostForSmoke;
        return CaptureStandaloneWindow(window, outputPath, width, height, () =>
        {
            var model = host.Workbench; model.Tool.ConfigureAutoRunPreference(() => false, _ => { }); var pipeline = model.Pipeline; var images = model.Images;
            Button run = ButtonFor("WorkbenchRunPipeline"), prefix = ButtonFor("MainRunToSelected"), batch = ButtonFor("MainRunBatch"), stop = ButtonFor("MainStopRun");
            FrameworkElement scope = ElementFor("MainRunScope"), single = ElementFor("MainRunProgress"), batchProgress = ElementFor("MainBatchProgress");
            TextBlock count = FindNamedVisualChild<TextBlock>(host, "mainBatchCountText"), scopeText = FindNamedVisualChild<TextBlock>(host, "mainRunScopeText");
            TextBlock singleText = FindNamedVisualChild<TextBlock>(host, "mainRunProgressText"), batchText = FindNamedVisualChild<TextBlock>(host, "mainBatchProgressText");
            ProgressBar singleBar = FindNamedVisualChild<ProgressBar>(host, "mainRunProgressBar"), batchBar = FindNamedVisualChild<ProgressBar>(host, "mainBatchProgressBar");
            List<object> cases = new(); List<string> failures = new(); OpenVisionLanguage initial = OpenVisionLanguageService.CurrentLanguage;
            MethodInfo raise = typeof(OpenVisionWorkbenchPipelineViewModel).GetMethod("RaiseState", BindingFlags.Instance | BindingFlags.NonPublic)!;
            string savedPath = RecipeWorkspaceService.GetVisionPipelinePath(global.Recipe.Name, "Main"); byte[] saved = File.ReadAllBytes(savedPath); int nativeRuns = host.NativePreviewRunCount;
            string[] inputs = Enumerable.Range(0, 2).Select(index => Path.Combine(Path.GetDirectoryName(outputPath)!, "runbar_input_" + index + "_long_image_name.png")).ToArray();
            try
            {
                for (int index = 0; index < 2; index++)
                {
                    using (Bitmap image = new(32, 24)) { using Graphics graphics = Graphics.FromImage(image); graphics.Clear(DrawingColor.FromArgb(128, 128, 128)); image.Save(inputs[index], ImageFormat.Png); }
                    VisionPipelineStep step = new() { Name = "Runbar row " + (index + 1), ToolType = "Mean", InputLayer = "Main", OutputLayer = "Runbar_Output_" + index };
                    step.Parameters["MEAN_TYPES"] = "Mean"; step.Parameters["MEAN_MIN"] = "0"; step.Parameters["MEAN_MAX"] = "255"; step.Parameters["USE_THRESHOLD"] = "False";
                    step.Parameters["USE_ADAPTIVE_THRESHOLD"] = "False"; step.Parameters["USE_ROI"] = "False"; step.Parameters["USE_BITWISENOT"] = "False";
                    Require(pipeline.InsertStep(index, step) != null, "owned Main step setup");
                }
                Func<bool>? originalCommit = pipeline.CanCommitToolEdits; int commitCalls = 0;
                pipeline.CanCommitToolEdits = () => { commitCalls++; return false; };
                Require(!pipeline.RunCommand.CanExecute(null) && commitCalls == 0, "no-image guard short-circuits tool callback");
                pipeline.CanCommitToolEdits = originalCommit;
                byte[] working = VisionPipelineExecutionPlan.SerializePipeline(pipeline.WorkingCopyForTest); string[] bytes = inputs.Select(path => Convert.ToHexString(SHA256.HashData(File.ReadAllBytes(path)))).ToArray();
                pipeline.SelectedStepIndex = -1; Pump(4); if (!batchOnly) Observe("empty", false, false, false, 0D);
                Require(host.LoadMainImageFromFileForTest(inputs[0]), "valid input"); images.AddImages(new[] { new OpenVisionWorkbenchImageItem(inputs[1], Path.GetFileName(inputs[1]), OpenVisionBitmapImagePreviewFactory.CreateFromPath(inputs[1])) }); Pump(4);
                pipeline.CanCommitToolEdits = () => { commitCalls++; return false; }; commitCalls = 0;
                Require(!pipeline.RunCommand.CanExecute(null) && commitCalls == 1 && pipeline.RunDisabledReason == pipeline["Workbench.Command.FixToolSettings"], "acceptance guard reason/callback agreement");
                pipeline.CanCommitToolEdits = originalCommit;
                CommandManager.InvalidateRequerySuggested(); Pump(3);
                if (commands)
                {
                    List<object> observed = new(); int completions = 0; string mode = "full"; bool stopRequested = false;
                    EventHandler completed = (_, _) => completions++;
                    HashSet<string> recipeGuardModes = new();
                    System.ComponentModel.PropertyChangedEventHandler progress = (_, changed) =>
                    {
                        if (pipeline.IsRunning) observed.Add(new { Mode = mode, Single = pipeline.IsSingleRunning, Batch = images.IsBatchRunning, Text = pipeline.RunProgressText, Value = pipeline.RunProgressValue, BatchText = images.BatchProgressText, BatchValue = images.BatchProgressValue });
                        if (!pipeline.IsRunning || recipeGuardModes.Contains(mode) || !string.IsNullOrEmpty(changed.PropertyName)) { return; }
                        recipeGuardModes.Add(mode);
                        CommandManager.InvalidateRequerySuggested(); Pump(2);
                        ComboBox recipeSelector = FindVisualChildren<ComboBox>(host).Single(item => AutomationProperties.GetAutomationId(item) == "HostRecipeSelector");
                        ToggleButton recipeManager = FindVisualChildren<ToggleButton>(host).Single(item => AutomationProperties.GetAutomationId(item) == "HostRecipeManagerButton");
                        Button saveRecipe = ButtonFor("HostRecipeSaveButton");
                        bool recipeBlocked = !recipeSelector.IsEnabled && !model.OpenMainNewRecipeCommand.CanExecute(null) && !model.OpenMainSaveAsCommand.CanExecute(null) && !saveRecipe.IsEnabled;
                        observed.Add(new { Mode = "running-recipe-guards", RunMode = mode, Notification = changed.PropertyName, CanEdit = pipeline.CanEdit, HasSelectorBinding = BindingOperations.IsDataBound(recipeSelector, UIElement.IsEnabledProperty), SelectorBindingStatus = BindingOperations.GetBindingExpression(recipeSelector, UIElement.IsEnabledProperty)?.Status.ToString(), RecipeSelectorEnabled = recipeSelector.IsEnabled, RecipeManagerEnabled = recipeManager.IsEnabled, ManagerCommandEnabled = model.OpenRecipeManagerCommand.CanExecute(null), SaveEnabled = saveRecipe.IsEnabled, RecipeBlocked = recipeBlocked, ViewCommandsAllowed = model.Viewer.Split2Command.CanExecute(null) });
                        ScreenshotPngWriter.WriteElementPng(window, Path.ChangeExtension(outputPath, ".running-recipe-guards-" + mode + ".png"), width, height);
                        if (!recipeBlocked) failures.Add("Running Main recipe selection/save commands are not consistently disabled.");
                        if (!model.Viewer.Split2Command.CanExecute(null)) failures.Add("Running Main view command is unexpectedly disabled.");
                    };
                    System.ComponentModel.PropertyChangedEventHandler batchStop = (_, _) =>
                    {
                        if (mode != "batch-stop" || stopRequested || !images.IsBatchRunning || images.BatchProgressValue <= 0D) return;
                        stopRequested = true; stop.Command.Execute(stop.CommandParameter);
                    };
                    pipeline.InspectionCompleted += completed; pipeline.PropertyChanged += progress; images.PropertyChanged += batchStop;
                    try
                    {
                        pipeline.SelectedStepIndex = 0; Pump(3); Require(run.Command.CanExecute(run.CommandParameter), "full enabled"); run.Command.Execute(run.CommandParameter); WaitIdle("full"); Observe("real-full-restored", true, false, false, 0D);
                        mode = "prefix"; Require(prefix.Command.CanExecute(prefix.CommandParameter), "prefix enabled"); prefix.Command.Execute(prefix.CommandParameter); WaitIdle("prefix"); Observe("real-prefix-restored", true, false, false, 0D);
                        mode = "batch-stop"; Require(batch.Command.CanExecute(batch.CommandParameter), "batch enabled"); batch.Command.Execute(batch.CommandParameter); WaitIdle("batch-stop"); Observe("real-batch-restored", true, false, false, 0D);
                        string events = JsonSerializer.Serialize(observed);
                        Require(events.Contains("Running 0/2", StringComparison.Ordinal) || events.Contains("\\uC2E4\\uD589 \\uC911 0/2", StringComparison.Ordinal), "full progress snapshot count");
                        Require(events.Contains("Running 0/1", StringComparison.Ordinal) || events.Contains("\\uC2E4\\uD589 \\uC911 0/1", StringComparison.Ordinal), "prefix progress snapshot count");
                        Require(stopRequested && completions == 2 && images.CurrentIndex == 0 && images.Images[1].Result == null && !stop.Command.CanExecute(null), "batch stops after current image and restores input");
                        File.WriteAllText(Path.ChangeExtension(outputPath, ".progress-events.json"), JsonSerializer.Serialize(new { Observed = observed, Completions = completions, StopRequested = stopRequested, CurrentIndex = images.CurrentIndex, Policy = "existing explicit commands/current-image stop" }, new JsonSerializerOptions { WriteIndented = true }));
                    }
                    finally { pipeline.InspectionCompleted -= completed; pipeline.PropertyChanged -= progress; images.PropertyChanged -= batchStop; }
                }
                else
                {
                    foreach (string palette in new[] { "Dark", "Light" })
                    foreach (OpenVisionLanguage language in new[] { OpenVisionLanguage.Korean, OpenVisionLanguage.English })
                    {
                        (palette == "Dark" ? model.SelectDarkThemeCommand : model.SelectLightThemeCommand).Execute(null); OpenVisionLanguageService.SetLanguage(language, false); Pump(4);
                        if (!batchOnly)
                        {
                        Set(pipeline, "selectedIndex", -1); raise.Invoke(pipeline, null); Pump(3); Observe(palette + "-" + language + "-loaded-synthetic-no-selection", false, false, false, 0D);
                        pipeline.SelectedStepIndex = 0; Pump(3); Observe(palette + "-" + language + "-selected", true, false, false, 0D);
                        Busy(false, false, 2, 1); Observe(palette + "-" + language + "-synthetic-full", false, true, false, 50D);
                        Busy(false, false, 1, 1); Observe(palette + "-" + language + "-synthetic-prefix", false, true, false, 100D);
                        }
                        Busy(true, false, 2, 1); Observe(palette + "-" + language + "-synthetic-batch", false, false, true, 50D);
                        Busy(true, true, 2, 1); Observe(palette + "-" + language + "-synthetic-stopping", false, false, true, 50D);
                        Reset(); Observe(palette + "-" + language + "-restored", true, false, false, 0D);
                        if (!batchOnly)
                        {
                        Require(images.TrySelect(images.Images[1]), "alternate image"); Pump(3); Observe(palette + "-" + language + "-second-image-scope", true, false, false, 0D);
                        Require(images.TrySelect(images.Images[0]), "original image"); Pump(3);
                        }
                    }
                    Require(host.NativePreviewRunCount == nativeRuns && !pipeline.HasVerdict, "display check must not execute");
                }
                Require(saved.SequenceEqual(File.ReadAllBytes(savedPath)) && working.SequenceEqual(VisionPipelineExecutionPlan.SerializePipeline(pipeline.WorkingCopyForTest)) && inputs.Select(path => Convert.ToHexString(SHA256.HashData(File.ReadAllBytes(path)))).SequenceEqual(bytes), "saved/working/input unchanged");
                File.WriteAllText(Path.ChangeExtension(outputPath, ".checks.json"), JsonSerializer.Serialize(new { Cases = cases, Failures = failures, Width = width, Height = height, RealCommands = commands, Scope = "inprocess WPF Main runbar; synthetic busy separate from explicit command events; no actual pointer/native DPI/HTML", FinalN = (int?)null, LoadedAssembly = typeof(OpenVisionShellHostView).Assembly.Location, LoadedSHA256 = Convert.ToHexString(SHA256.HashData(File.ReadAllBytes(typeof(OpenVisionShellHostView).Assembly.Location))) }, new JsonSerializerOptions { WriteIndented = true }));
                if (failures.Count > 0) throw new InvalidOperationException("Main runbar display: " + string.Join("; ", failures));
            }
            finally { Reset(); OpenVisionLanguageService.SetLanguage(initial, false); }
            Button ButtonFor(string id) => FindVisualChildren<Button>(host).Single(item => AutomationProperties.GetAutomationId(item) == id);
            FrameworkElement ElementFor(string id) => FindVisualChildren<FrameworkElement>(host).Single(item => AutomationProperties.GetAutomationId(item) == id);
            void Require(bool condition, string detail) { if (!condition) throw new InvalidOperationException("Main runbar: " + detail); }
            void Set(object owner, string field, object value) => owner.GetType().GetField(field, BindingFlags.Instance | BindingFlags.NonPublic)!.SetValue(owner, value);
            void Busy(bool batchRunning, bool stopping, int total, int index)
            {
                Set(pipeline, "running", true); Set(pipeline, "batchRunning", batchRunning); Set(pipeline, "stopRequested", stopping); Set(pipeline, "runningStepCount", total); Set(pipeline, "runProgressIndex", index);
                Set(images, "batchPlanned", 2); Set(images, "batchIndex", index); Set(images, "batchImageName", images.CurrentName); raise.Invoke(pipeline, null); CommandManager.InvalidateRequerySuggested(); Pump(4);
            }
            void Reset()
            {
                Set(pipeline, "running", false); Set(pipeline, "batchRunning", false); Set(pipeline, "stopRequested", false); Set(pipeline, "runningStepCount", 0); Set(pipeline, "runProgressIndex", 0); raise.Invoke(pipeline, null); CommandManager.InvalidateRequerySuggested(); Pump(4);
            }
            void WaitIdle(string state)
            {
                Stopwatch watch = Stopwatch.StartNew(); while (pipeline.IsRunning && watch.ElapsedMilliseconds < 12000) { Pump(2); }
                Pump(4); Require(!pipeline.IsRunning, state + " timeout"); Require(!single.IsVisible && !batchProgress.IsVisible && pipeline.RunProgressValue == 0D && images.BatchProgressValue == 0D, state + " progress released");
                if (commands) Require(pipeline.CanEdit && FindVisualChildren<ComboBox>(host).Single(item => AutomationProperties.GetAutomationId(item) == "HostRecipeSelector").IsEnabled, state + " recipe selection restored after run");
            }
            void Observe(string state, bool prefixEnabled, bool singleRunning, bool batchRunning, double value)
            {
                List<string> errors = new(); bool busy = singleRunning || batchRunning; bool loaded = images.HasImages;
                if (!ReferenceEquals(run.Command, pipeline.RunCommand) || !ReferenceEquals(prefix.Command, pipeline.RunToSelectedCommand) || !ReferenceEquals(batch.Command, images.RunBatchCommand) || batch.CommandParameter?.ToString() != "all" || !ReferenceEquals(stop.Command, pipeline.StopCommand)) errors.Add("command/parameter owner");
                if (run.IsEnabled != (loaded && !busy) || prefix.IsEnabled != prefixEnabled || batch.IsEnabled != (loaded && !busy) || stop.IsEnabled != (busy && !pipeline.IsStopRequested)) errors.Add("CanExecute agreement");
                foreach ((Button control, string reason) in new[] { (run, pipeline.RunDisabledReason), (prefix, pipeline.RunToDisabledReason), (batch, images.BatchDisabledReason), (stop, pipeline.StopDisabledReason) })
                {
                    if (!control.IsEnabled && (string.IsNullOrWhiteSpace(reason) || control.ToolTip?.ToString()?.Contains(reason, StringComparison.Ordinal) != true)) errors.Add("disabled reason/tooltip agreement " + AutomationProperties.GetAutomationId(control) + " expected=" + reason + " actual=" + control.ToolTip);
                }
                if (single.IsVisible != singleRunning || batchProgress.IsVisible != batchRunning || singleRunning && (singleText.Text != pipeline.RunProgressText || singleBar.Value != value) || batchRunning && (batchText.Text != images.BatchRunLabelText || batchBar.Value != value)) errors.Add("progress binding");
                TextBlock position = FindNamedVisualChild<TextBlock>(host, "mainBatchProgressPositionText");
                if (batchRunning && (position.Text != images.BatchRunPositionText || position.Text != "1/2" || position.ActualWidth + position.Margin.Left + position.Margin.Right + 0.5D < position.DesiredSize.Width)) errors.Add("required batch ratio hidden");
                if (count.Text != images.BatchCountText || count.IsVisible != loaded || FindVisualChildren<MahApps.Metro.IconPacks.PackIconMaterial>(prefix).Single().Kind != MahApps.Metro.IconPacks.PackIconMaterialKind.DebugStepOver) errors.Add("batch count/canonical icon");
                string expectedScope = images.RunScopeImageText + " · " + pipeline.SelectedPipelineName + " · " + pipeline.StepCountText;
                if (scopeText.Text != expectedScope || scope.IsVisible != model.ShowCommandLabels) errors.Add("scope binding/responsive");
                FrameworkElement[] ordered = { run, prefix, batch, stop };
                for (int index = 0; index < ordered.Length; index++)
                {
                    System.Windows.Point point = ordered[index].TranslatePoint(new System.Windows.Point(), host);
                    double nextX = index + 1 < ordered.Length ? ordered[index + 1].TranslatePoint(new System.Windows.Point(), host).X : (scope.IsVisible ? scope.TranslatePoint(new System.Windows.Point(), host).X : width - 50D);
                    if (point.X < 0D || point.X + ordered[index].ActualWidth > nextX + 0.5D) errors.Add("command bounds overlap " + index);
                    foreach (TextBlock caption in FindVisualChildren<TextBlock>(ordered[index]).Where(text => text.IsVisible)) if (caption.ActualWidth + caption.Margin.Left + caption.Margin.Right + 0.5D < caption.DesiredSize.Width) errors.Add("required command caption clipped");
                }
                FrameworkElement visibleProgress = singleRunning ? single : batchProgress; ProgressBar visibleBar = singleRunning ? singleBar : batchBar;
                if (busy && (visibleProgress.ActualWidth < 24D || visibleBar.ActualWidth <= 0D || visibleBar.Foreground?.ToString() != host.TryFindResource("OpenVision.Workbench.AccentBrush")?.ToString())) errors.Add("progress legibility/theme");
                string capture = Path.Combine(Path.GetDirectoryName(outputPath)!, "runbar-" + (commands ? "commands-" : "") + width + "-" + cases.Count.ToString("00") + "-" + state + ".png"); ScreenshotPngWriter.WriteElementPng(host, capture, width, height);
                cases.Add(new { State = state, Busy = busy, Batch = batchRunning, Count = count.Text, Scope = scopeText.Text, SelectedIndex = pipeline.SelectedStepIndex, RunEnabled = run.IsEnabled, PrefixEnabled = prefix.IsEnabled, RunReason = pipeline.RunDisabledReason, PrefixReason = pipeline.RunToDisabledReason, BatchReason = images.BatchDisabledReason, StopReason = pipeline.StopDisabledReason, SingleText = singleText.Text, BatchText = batchText.Text, BatchPosition = position.Text, Progress = value, Capture = capture, Errors = errors }); failures.AddRange(errors.Select(error => state + ": " + error));
            }
        });
    }

    private static CaptureResult CaptureMainRunBarBefore(string outputPath)
    {
