    private static CaptureResult CaptureMainRecipeSaveStatus(string outputPath, int width, int height)
    {
        GlobalState global = new(); global.Recipe.Name = "Smoke_MainSaveStatus_" + Guid.NewGuid().ToString("N");
        VisionPipelineStorage.Save(global.Recipe.Name, new VisionPipeline { Name = "Main" }); global.System.SaveWorkbenchLayout(new SystemStateConfig());
        using DisplayManagerService display = new(); OpenVisionShellHostWindow window = new(new ApplicationRuntimeContext(global, display));
        window.ClearValue(OpenVisionShellHostWindow.ClosingCommandProperty); OpenVisionShellHostView host = window.ShellHostForSmoke;
        return CaptureStandaloneWindow(window, outputPath, width, height, () =>
        {
            var model = host.Workbench; model.Tool.ConfigureAutoRunPreference(() => false, _ => { });
            var recipes = host.RecipeCommands; var pipeline = model.Pipeline; List<object> cases = new(); List<string> failures = new();
            TextBlock text = FindNamedVisualChild<TextBlock>(host, "mainRecipeSaveStatusText");
            Border badge = FindVisualChildren<Border>(host).Single(item => AutomationProperties.GetAutomationId(item) == "MainRecipeSaveStatus");
            Button save = FindVisualChildren<Button>(host).Single(item => AutomationProperties.GetAutomationId(item) == "HostRecipeSaveButton");
            string savedPath = RecipeWorkspaceService.GetVisionPipelinePath(global.Recipe.Name, "Main"); byte[] original = File.ReadAllBytes(savedPath);
            int runs = host.NativePreviewRunCount; OpenVisionLanguage initial = OpenVisionLanguageService.CurrentLanguage;
            var session = (OpenVisionRecipeStepEditSessionViewModel)typeof(OpenVisionShellHostRecipeCommandSurface).GetField("selectedStepEditSession", BindingFlags.Instance | BindingFlags.NonPublic)!.GetValue(recipes)!;
            FieldInfo running = typeof(OpenVisionWorkbenchPipelineViewModel).GetField("running", BindingFlags.Instance | BindingFlags.NonPublic)!;
            MethodInfo raiseState = typeof(OpenVisionWorkbenchPipelineViewModel).GetMethod("RaiseState", BindingFlags.Instance | BindingFlags.NonPublic)!;
            try
            {
                foreach (string palette in new[] { "Dark", "Light" })
                foreach (OpenVisionLanguage language in new[] { OpenVisionLanguage.Korean, OpenVisionLanguage.English })
                {
                    (palette == "Dark" ? model.SelectDarkThemeCommand : model.SelectLightThemeCommand).Execute(null); OpenVisionLanguageService.SetLanguage(language, false); Pump(4);
                    Observe(palette + "-" + language + "-saved", "Saved", true);
                    pipeline.InsertStep(pipeline.WorkingCopyForTest.Steps.Count, new VisionPipelineStep { Name = "Unsaved " + cases.Count, ToolType = "Mean", InputLayer = "Main", OutputLayer = "Output" + cases.Count }); Pump(4);
                    Observe(palette + "-" + language + "-dirty", "Unsaved", true); pipeline.UndoCommand.Execute(null); Pump(4); Observe(palette + "-" + language + "-undo", "Saved", true);
                    pipeline.InsertStep(pipeline.WorkingCopyForTest.Steps.Count, new VisionPipelineStep { Name = "Retained " + cases.Count, ToolType = "Mean", InputLayer = "Main", OutputLayer = "Output" + cases.Count }); Pump(4);
                    byte[] savedBeforeFault = File.ReadAllBytes(savedPath), workingBeforeFault = VisionPipelineExecutionPlan.SerializePipeline(pipeline.WorkingCopyForTest);
                    using (FileStream locked = new(savedPath, FileMode.Open, FileAccess.Read, FileShare.Read))
                    {
                        save.Command.Execute(save.CommandParameter); Pump(4); Observe(palette + "-" + language + "-locked-save", "Error", true);
                        if (!savedBeforeFault.SequenceEqual(File.ReadAllBytes(savedPath)) || !workingBeforeFault.SequenceEqual(VisionPipelineExecutionPlan.SerializePipeline(pipeline.WorkingCopyForTest)) || !pipeline.IsDirty) failures.Add("locked save changed saved/working source");
                    }
                    save.Command.Execute(save.CommandParameter); Pump(4); Observe(palette + "-" + language + "-retry", "Saved", true);
                    if (!VisionPipelineExecutionPlan.SerializePipeline(VisionPipelineStorage.Load(global.Recipe.Name, "Main")).SequenceEqual(VisionPipelineExecutionPlan.SerializePipeline(pipeline.WorkingCopyForTest))) failures.Add("save retry differs from working copy");
                    session.Load(new object(), "", false); session.MarkDirty(""); Pump(4); Observe(palette + "-" + language + "-parameter-dirty", "Unsaved", true); session.Clear(); Pump(4);
                    running.SetValue(pipeline, true); raiseState.Invoke(pipeline, null); CommandManager.InvalidateRequerySuggested(); Pump(4); Observe(palette + "-" + language + "-synthetic-running", "Saved", false);
                    running.SetValue(pipeline, false); raiseState.Invoke(pipeline, null); CommandManager.InvalidateRequerySuggested(); Pump(4);
                }
                if (host.NativePreviewRunCount != runs || model.Images.Count != 0) failures.Add("status workflow executed Run or changed images");
                File.WriteAllText(Path.ChangeExtension(outputPath, ".checks.json"), JsonSerializer.Serialize(new { Cases = cases, Failures = failures, Scope = "Inprocess WPF Main save status; real working-copy/Undo/locked-file save/retry, synthetic parameter dirty/busy, no actual pointer or native DPI", NoRun = host.NativePreviewRunCount == runs, FinalN = (int?)null, Width = width, Height = height, LoadedAssembly = typeof(OpenVisionShellHostView).Assembly.Location, LoadedSHA256 = Convert.ToHexString(SHA256.HashData(File.ReadAllBytes(typeof(OpenVisionShellHostView).Assembly.Location))) }, new JsonSerializerOptions { WriteIndented = true }));
                if (failures.Count > 0) throw new InvalidOperationException("Main recipe save status: " + string.Join("; ", failures));
            }
            finally { session.Clear(); running.SetValue(pipeline, false); raiseState.Invoke(pipeline, null); OpenVisionLanguageService.SetLanguage(initial, false); }
            void Observe(string state, string expected, bool editable)
            {
                string caption = expected == "Saved" ? (OpenVisionLanguageService.CurrentLanguage == OpenVisionLanguage.Korean ? "저장됨" : "Saved") : expected == "Unsaved" ? (OpenVisionLanguageService.CurrentLanguage == OpenVisionLanguage.Korean ? "저장 안 됨" : "Unsaved") : (OpenVisionLanguageService.CurrentLanguage == OpenVisionLanguage.Korean ? "저장 상태 오류" : "Save error");
                List<string> errors = new();
                if (model.RecipeSaveState != expected || text.Text != caption || !badge.IsVisible || text.ActualWidth + 0.5 < text.DesiredSize.Width) errors.Add("state/caption/visibility/width");
                if (save.IsEnabled != editable || !ReferenceEquals(save.Command, recipes.SaveRecipeCommand)) errors.Add("save command enabled/binding");
                System.Windows.Point statusPoint = badge.TranslatePoint(new System.Windows.Point(), host), savePoint = save.TranslatePoint(new System.Windows.Point(), host);
                if (statusPoint.X < 0 || statusPoint.X + badge.ActualWidth > savePoint.X || savePoint.X + save.ActualWidth > width) errors.Add("status/save bounds overlap");
                string brushKey = expected == "Error" ? "OpenVision.Workbench.NgBrush" : expected == "Unsaved" ? "OpenVision.Workbench.ErrorBrush" : "OpenVision.Workbench.MutedTextBrush";
                if (text.Foreground is not SolidColorBrush rendered || host.TryFindResource(brushKey) is not SolidColorBrush semantic || rendered.Color != semantic.Color) errors.Add("semantic status foreground");
                if (expected == "Unsaved" && editable && save.Background?.ToString() != host.TryFindResource("OpenVision.Workbench.AccentSoftBrush")?.ToString()) errors.Add("dirty save accent");
                string capture = Path.Combine(Path.GetDirectoryName(outputPath)!, "recipe-status-" + width + "-" + cases.Count.ToString("00") + "-" + state + ".png"); ScreenshotPngWriter.WriteElementPng(host, capture, width, height);
                cases.Add(new { State = state, Expected = expected, Caption = text.Text, Foreground = text.Foreground?.ToString(), Editable = save.IsEnabled, StatusX = statusPoint.X, StatusWidth = badge.ActualWidth, SaveX = savePoint.X, Capture = capture, Errors = errors }); failures.AddRange(errors.Select(error => state + ": " + error));
            }
        });
    }

    private static CaptureResult CaptureMainTransitionGuards(string outputPath, bool boundRecovery = false)
    {
        string token = Guid.NewGuid().ToString("N")[..12], recipeA = "Smoke_C118A_" + token, recipeB = "Smoke_C118B_" + token, badRecipe = "Smoke_C118Bad_" + token;
        foreach (string recipe in new[] { recipeA, recipeB, badRecipe })
