                VisionPipelineStorage.Save(recipe, seed);
            }
            VisionPipelineStorage.SaveActivePipelineName(recipe, "Main");
        }
        string current = recipeA; int switchMode = 0, switchCalls = 0, saveCalls = 0, transitions = 0;
