        Task completion = Task.CompletedTask;
        OpenVisionShellHostRecipeCommandSurface recipes = new(() => current, name => { switchCalls++; if (switchMode == 2) throw new IOException("Owned transition fault"); if (switchMode == 0) current = name; }, () => { },
            commitSelectedStepEdit: () => commitAllowed, decidePendingEdit: _ => decision, saveRecipe: () => { saveCalls++; return true; }, waitForRecipeSwitchCompletion: () => completion);
        using DisplayManagerService display = new();
        using OpenVisionWorkbenchPipelineViewModel pipeline = new(recipes, display, action => action(), _ => decision, _ => true, Array.Empty<OpenVisionShellNavGroup>());
        recipes.AttachWorkbenchPipeline(pipeline);
        OpenVisionWorkbenchViewModel model = new(new SystemStateConfig(), _ => true, recipes: recipes);
        List<object> notifications = new();
        recipes.PropertyChanged += (_, e) => { if (e.PropertyName == nameof(OpenVisionShellHostRecipeCommandSurface.TransitionActionKey)) { transitions++; notifications.Add(new { Key = recipes.TransitionActionKey, Name = recipes.TransitionActionName, Provider = current, PendingPreparation = !completion.IsCompleted }); } };
        MethodInfo select = typeof(OpenVisionShellHostRecipeCommandSurface).GetMethod("SelectRecipeAsync", BindingFlags.Instance | BindingFlags.NonPublic)!;
        OpenVisionShellHostView boundHost = boundRecovery ? CreateShellHost(recipeA) : null;
        return CaptureWindowWithContent(boundHost ?? (FrameworkElement)new TextBlock { Text = "Main transition completion/guards/recovery/lifetime contracts" }, outputPath, boundRecovery ? 1600 : 720, boundRecovery ? 900 : 160, () =>
        {
            List<object> cases = new(); OpenVisionLanguage initial = OpenVisionLanguageService.CurrentLanguage;
            void Require(bool value, string name) { if (!value) throw new InvalidOperationException("Main transition: " + name); cases.Add(new { Case = name, PASS = true }); }
            ComboBox boundCombo = null;
            if (boundRecovery)
            {
                Grid panel = FindVisualChildren<Grid>(boundHost).Single(item => AutomationProperties.GetAutomationId(item) == "WorkbenchPipelinePanel");
                panel.DataContext = pipeline; Pump(4);
                boundCombo = FindVisualChildren<ComboBox>(panel).Single(item => AutomationProperties.GetAutomationId(item) == "WorkbenchPipelineCombo");
                Require(BindingOperations.GetBindingExpression(boundCombo, UIElement.IsEnabledProperty)?.ParentBinding.Path.Path == "CanEdit" && boundCombo.IsEnabled, "actual Main Combo retains CanEdit binding and starts enabled");
            }
            Task Start(string name) => (Task)select.Invoke(recipes, new object[] { name })!;
            void Switch(string name) { WaitForTaskWithPump(Start(name), 10000, "Transition " + name); }
            void Choose(string name) { recipes.SelectedPipelineOption = recipes.PipelineOptions.Single(option => option.PipelineName == name); }
            try
            {
                OpenVisionLanguageService.SetLanguage(OpenVisionLanguage.English, false);
                Require(transitions == 0 && model.MainActionText == "Ready", "initial projection has no completion");
                recipes.RefreshOptions(); Switch(recipeA); recipes.SelectedPipelineOption = OpenVisionRecipePipelineOption.Create(recipeA, "Main", "Main");
                Require(transitions == 0 && model.MainActionText == "Ready", "refresh and same-name new option and recipe no-op emit no completion");
                Switch(recipeB); Require(transitions == 1 && recipes.TransitionActionName == recipeB && model.MainActionText == "Recipe '" + recipeB + "' opened." && model.MainActionIcon.ToString() == "InformationOutline", "recipe A to B completes with captured name and information icon");
                Switch(recipeA); Require(transitions == 2 && recipes.TransitionActionName == recipeA, "recipe B to A repeats same completion key");
                Choose("Other"); Require(transitions == 3 && model.MainActionText == "Switched to pipeline 'Other'.", "pipeline Main to Other completes");
                recipes.SaveRecipeCommand.Execute(null); Require(saveCalls == 1 && model.MainActionText == "Recipe saved." && model.MainActionKind == "Ok", "existing save overwrites transition");
                Choose("Main"); Require(transitions == 4 && model.MainActionText == "Switched to pipeline 'Main'." && model.MainActionKind == string.Empty, "pipeline return after save overwrites success icon");
                string captured = model.MainActionText; int calls = switchCalls;
                recipes.RefreshOptions(); recipes.SelectedPipelineOption = OpenVisionRecipePipelineOption.Create(recipeA, "Main", "Main"); Switch(recipeA);
                Require(transitions == 4 && switchCalls == calls && model.MainActionText == captured, "projection refresh preserves last completed action");
                recipes.SelectedPipelinePreviewStep = recipes.SelectedRecipeSummary.PipelinePreviewSteps.First(); recipes.LoadSelectedStepParametersCommand.Execute(null); recipes.MarkSelectedStepEditDirty();
                object edit = recipes.SelectedStepEditObject;
                byte[] beforeCancel = VisionPipelineExecutionPlan.SerializePipeline(pipeline.WorkingCopyForTest);
                Switch(recipeB); Choose("Other"); Require(transitions == 4 && current == recipeA && recipes.SelectedPipelineOption.PipelineName == "Main" && recipes.IsSelectedStepEditDirty && ReferenceEquals(edit, recipes.SelectedStepEditObject), "dirty Step cancel retains context and edit object for recipe and pipeline");
                if (boundRecovery) { Pump(4); Require(boundCombo.IsEnabled == pipeline.CanEdit && !pipeline.CanEdit && beforeCancel.SequenceEqual(VisionPipelineExecutionPlan.SerializePipeline(pipeline.WorkingCopyForTest)), "dirty cancel preserves existing edit guard and working copy in actual binding"); }
                decision = OpenVisionRecipePendingEditDecision.ApplyAndContinue; commitAllowed = false;
                Switch(recipeB); Choose("Other"); Require(transitions == 4 && current == recipeA && recipes.IsSelectedStepEditDirty && ReferenceEquals(edit, recipes.SelectedStepEditObject), "Step commit refusal emits no transition and retains edit");
                decision = OpenVisionRecipePendingEditDecision.Discard; commitAllowed = true; Choose("Other"); Require(transitions == 5 && !recipes.IsSelectedStepEditDirty, "explicit discard permits valid pipeline recovery");
                switchMode = 1; Switch(recipeB); Require(transitions == 5 && current == recipeA && recipes.StatusText.Contains("Recipe load failed", StringComparison.Ordinal), "provider mismatch has existing error and no completion");
                switchMode = 2; Task fault = Start(recipeB); bool observed = false;
                try { WaitForTaskWithPump(fault, 10000, "Owned transition fault"); } catch (IOException ex) { observed = ex.Message == "Owned transition fault"; }
                Require(observed && transitions == 5 && !recipes.IsSwitchingRecipe, "load exception emits no completion and restores switching state");
                if (boundRecovery) { Pump(4); Require(boundCombo.IsEnabled, "bound Combo recovers after load exception without language change"); }
                switchMode = 0; Switch(recipeB); Require(transitions == 6 && current == recipeB, "valid recipe recovers after provider failure and exception");
                string malformed = RecipeWorkspaceService.GetVisionPipelinePath(recipeB, "Other"); byte[] valid = File.ReadAllBytes(malformed);
                File.WriteAllText(malformed, "<VisionPipeline><Steps>"); recipes.RefreshOptions(); Choose("Other");
                Require(transitions == 6 && recipes.SelectedRecipeSummary.XmlValid == false && valid.Length > 0, "malformed Pipeline never announces completed switch");
                VisionPipelineStorage.Save(recipeB, new VisionPipeline { Name = "Other" }); recipes.RefreshOptions(); Choose("Main"); Require(transitions == 7 && recipes.SelectedRecipeSummary.XmlValid, "valid pipeline switch recovers after malformed input");
                string badPath = RecipeWorkspaceService.GetVisionPipelinePath(badRecipe, "Main"); File.WriteAllText(badPath, "<VisionPipeline><Steps>");
                File.WriteAllText(RecipeWorkspaceService.GetVisionPipelinePath(badRecipe, "Other"), "<VisionPipeline><Steps>"); Switch(badRecipe);
                Require(transitions == 7 && recipes.SelectedRecipeSummary.XmlValid == false, "malformed recipe load never announces completion");
                Switch(recipeA); Require(transitions == 8 && current == recipeA, "valid recipe recovers from malformed recipe");
                TaskCompletionSource<bool> gate = new(TaskCreationOptions.RunContinuationsAsynchronously); completion = gate.Task;
                Task pending = Start(recipeB); Pump(4); int before = transitions, switches = switchCalls;
                Require(!pending.IsCompleted && recipes.IsSwitchingRecipe && current == recipeB && transitions == 8, "deferred recipe preparation emits nothing before actual completion");
                if (boundRecovery) { Require(!boundCombo.IsEnabled, "bound Combo disables during real TCS preparation"); }
                Switch(recipeA); Switch(recipeB); Require(switchCalls == switches && transitions == before && !pending.IsCompleted, "repeated selection preserves existing reentry guard");
                gate.SetResult(true); WaitForTaskWithPump(pending, 10000, "Recipe gate release"); Require(transitions == before + 1 && !recipes.IsSwitchingRecipe && recipes.TransitionActionName == recipeB, "TCS completion emits exactly one recipe action");
                if (boundRecovery) { Pump(4); Require(boundCombo.IsEnabled && pipeline.CanEdit, "bound Combo re-enables after TCS completion without refresh or language change"); }
                if (boundRecovery)
                {
                    gate = new(TaskCreationOptions.RunContinuationsAsynchronously); completion = gate.Task; pending = Start(recipeA); Pump(4);
                    byte[] waitingXml = VisionPipelineExecutionPlan.SerializePipeline(pipeline.WorkingCopyForTest);
                    Require(!boundCombo.IsEnabled && !pipeline.SelectStepCommand.CanExecute(0), "bound Combo and command disable while preparation is pending");
                    gate.SetException(new IOException("Owned preparation fault")); observed = false;
                    try { WaitForTaskWithPump(pending, 10000, "Preparation fault"); } catch (IOException ex) { observed = ex.Message == "Owned preparation fault"; }
                    Pump(4); Require(observed && boundCombo.IsEnabled && !recipes.IsSwitchingRecipe && waitingXml.SequenceEqual(VisionPipelineExecutionPlan.SerializePipeline(pipeline.WorkingCopyForTest)) && boundHost.NativePreviewRunCount == 0, "preparation exception restores actual binding without modifying working copy or running");
                    completion = Task.CompletedTask; Switch(recipeB);
                    gate = new(TaskCreationOptions.RunContinuationsAsynchronously); completion = gate.Task; pending = Start(recipeA); Pump(4); gate.SetCanceled(); observed = false;
                    try { WaitForTaskWithPump(pending, 10000, "Preparation cancellation"); } catch (OperationCanceledException) { observed = true; }
                    Pump(4); Require(observed && boundCombo.IsEnabled && !recipes.IsSwitchingRecipe && boundHost.NativePreviewRunCount == 0, "cancelled preparation restores actual binding without running");
                    completion = Task.CompletedTask; Switch(recipeB);
                }
                completion = Task.CompletedTask; Switch(recipeA);
                gate = new(TaskCreationOptions.RunContinuationsAsynchronously); completion = gate.Task; pending = Start(recipeB); before = transitions; current = recipeA; gate.SetResult(true); WaitForTaskWithPump(pending, 10000, "Provider changed during preparation");
                Require(transitions == before, "provider mismatch after await cannot announce success");
                completion = Task.CompletedTask; recipes.RefreshOptions(); Switch(recipeB);
                string name = recipes.TransitionActionName; switches = switchCalls; int saves = saveCalls; OpenVisionLanguageService.SetLanguage(OpenVisionLanguage.Korean, false); Pump(2);
                Require(model.MainActionText == "‘" + name + "’ 레시피를 열었습니다." && recipes.TransitionActionName == name && switchCalls == switches && saveCalls == saves, "KO localization retains captured raw name without transition or save");
                OpenVisionLanguageService.SetLanguage(OpenVisionLanguage.English, false); Require(model.MainActionText == "Recipe '" + name + "' opened." && switchCalls == switches && saveCalls == saves, "EN localization retains captured raw name without transition or save");
                string disposed = model.MainActionText; model.Dispose(); Switch(recipeA); Require(model.MainActionText == disposed, "disposed root ignores subsequent transition notification");
                model = new(new SystemStateConfig(), _ => true, recipes: recipes); Require(model.MainActionText == "Ready" && switchCalls == switches + 1 && saveCalls == saves, "reopened root is transient Ready without additional action");
                File.WriteAllText(Path.ChangeExtension(outputPath, ".checks.json"), JsonSerializer.Serialize(new { Cases = cases, Notifications = notifications, SwitchCalls = switchCalls, SaveCalls = saveCalls, ProductSHA256 = Convert.ToHexString(SHA256.HashData(File.ReadAllBytes(typeof(OpenVisionShellHostView).Assembly.Location))), Scope = "Command-owner calls and actual TCS completion; isolated D files, in-process only. No CU/nativeDPI/full Main score." }, new JsonSerializerOptions { WriteIndented = true }));
            }
            finally { completion = Task.CompletedTask; OpenVisionLanguageService.SetLanguage(initial, false); recipes.DetachWorkbenchPipeline(pipeline); model.Dispose(); }
        });
    }

    private static CaptureResult CaptureMainRecipeSaveFailure(string outputPath)
