        int mode = 0, callbacks = 0, notifications = 0, commits = 0; bool commitAllowed = true, runtimeSucceeded = false, prematureNotification = false; Action saveProbe = () => { };
        OpenVisionShellHostRecipeCommandSurface recipes = new(() => selected, name => selected = name, () => { }, commitSelectedStepEdit: () => { commits++; return commitAllowed; }, saveRecipe: () => { callbacks++; runtimeSucceeded = false; saveProbe(); if (mode == 2) throw new IOException("Owned save fault"); return runtimeSucceeded = mode == 0; });
