        {
            List<object> cases = new();
            void Require(bool value, string name) { if (!value) throw new InvalidOperationException("Main save failure: " + name); cases.Add(new { Case = name, PASS = true }); }
            try
            {
                Require(model.RecipeSaveState == "Saved" && model.MainActionKind == string.Empty && recipes.SaveActionKey == string.Empty, "initial saved without transient action");
                pipeline.InsertStep(0, new VisionPipelineStep { Name = "Pending", ToolType = "Mean", InputLayer = "Main", OutputLayer = "Out" }); mode = 1; recipes.SaveRecipeCommand.Execute(null);
                Require(pipeline.IsDirty && recipes.HasRecipeSaveFailure && model.RecipeSaveState == "Error", "runtime false after pipeline publication retains unsaved baseline and never reports Saved");
                Require(notifications == 0 && model.MainActionKind == string.Empty, "false never announces success");
                pipeline.InsertStep(1, new VisionPipelineStep { Name = "PendingRetry", ToolType = "Mean", InputLayer = "Main", OutputLayer = "RetryOut" }); Require(pipeline.IsDirty, "true-save starts with dirty Pipeline");
                mode = 0; recipes.SaveRecipeCommand.Execute(null); Require(!recipes.HasRecipeSaveFailure && model.RecipeSaveState == "Saved" && !pipeline.IsDirty && VisionPipelineStorage.Load(selected, "Main").Steps.Count == 2, "successful retry persists dirty Pipeline before runtime save");
                Require(notifications == 1 && model.MainActionKind == "Ok" && model.MainActionIcon.ToString() == "CheckCircle", "retry announces success");
                mode = 2; recipes.SaveRecipeCommand.Execute(null); Require(recipes.HasRecipeSaveFailure && model.RecipeSaveState == "Error" && model.RecipeSaveStatusToolTip.Contains("Owned save fault", StringComparison.Ordinal), "runtime exception retains failure detail");
                Require(notifications == 1, "exception emits no success");
                mode = 0; recipes.SaveRecipeCommand.Execute(null); recipes.SaveRecipeCommand.Execute(null); Require(notifications == 3 && !recipes.HasRecipeSaveFailure, "exception recovery and consecutive successes notify");
                int beforeCallback = callbacks; pipeline.CanCommitToolEdits = () => false; recipes.SaveRecipeCommand.Execute(null);
                Require(callbacks == beforeCallback && notifications == 3 && recipes.HasRecipeSaveFailure, "pipeline refusal prevents runtime save and success"); pipeline.CanCommitToolEdits = () => true;
                recipes.RefreshOptions(); recipes.SelectedPipelinePreviewStep = recipes.SelectedRecipeSummary.PipelinePreviewSteps.First(); recipes.LoadSelectedStepParametersCommand.Execute(null);
                pipeline.InsertStep(2, new VisionPipelineStep { Name = "BothDirty", ToolType = "Mean", InputLayer = "Main", OutputLayer = "BothDirtyOut" });
                recipes.MarkSelectedStepEditDirty(); commitAllowed = false; recipes.SaveRecipeCommand.Execute(null);
                Require(commits > 0 && recipes.IsSelectedStepEditDirty && callbacks == beforeCallback && notifications == 3 && recipes.HasRecipeSaveFailure, "step commit refusal preserves edit and prevents downstream save");
                Require(recipes.IsSelectedStepEditDirty && pipeline.IsDirty, "true-save starts with Step and Pipeline both dirty");
                commitAllowed = true; recipes.SaveRecipeCommand.Execute(null);
                Require(!recipes.IsSelectedStepEditDirty && !pipeline.IsDirty && callbacks == beforeCallback + 1 && notifications == 4 && !recipes.HasRecipeSaveFailure && VisionPipelineStorage.Load(selected, "Main").Steps.Count == 3 && !prematureNotification, "both pending edits saved before runtime true and success notification");
                Bitmap input = new(32, 24); using (Graphics graphics = Graphics.FromImage(input)) { graphics.Clear(DrawingColor.FromArgb(180, 180, 180)); }
                display.CreateLayerDisplay(OpenVisionLab.ImageSpace.Core.ImageSpaceFrame.TakeOwnership(input), "Main"); display.NotifyParameterChanged();
                VisionPipelineStep ownedMean = VisionPipelineStepBuilder.FromProperty(new MeanProperty { NAME = "Owned unsaved", USE_ROI = false, USE_THRESHOLD = false, MEAN_MIN = 0, MEAN_MAX = 255 }, "Main", "Out"); ownedMean.UseAcceptance = false;
                bool replaced = pipeline.ReplaceStep(0, ownedMean);
                File.WriteAllText(Path.ChangeExtension(outputPath, ".working-probe.json"), JsonSerializer.Serialize(new { replaced, pipeline.CanEdit, pipeline.IsDirty, pipeline.StepCount, pipeline.StatusText, pipeline.ContextKey, recipes.CanUseWorkbenchContext, recipes.IsSwitchingRecipe, recipes.IsSelectedStepEditDirty, recipes.SelectedRecipeName, Current = selected, Pipeline = recipes.SelectedPipelineOption?.PipelineName, Steps = pipeline.WorkingCopyForTest.Steps }, new JsonSerializerOptions { WriteIndented = true }));
