                    pipeline.RunCommand.Execute(null); pipeline.RunToSelectedCommand.Execute(null); pipeline.RunToRowCommand.Execute(0); tool.RunCommand.Execute(null); tool.RunSelectedStepCommand.Execute(0); tool.RunToCommand.Execute(null);
