                {
                    bool failed = false; try { VisionPipelineStorage.Save(selected, pipeline.CopyWorkingPipeline()); } catch (IOException) { failed = true; }
                    Require(failed && !recipes.HasRecipeSaveFailure && !recipes.HasSelectedRecipePersistenceFailure && pipeline.HasPersistenceFailure && !pipeline.RunCommand.CanExecute(null) && !tool.RunCommand.CanExecute(null) && recoveredBytes.SequenceEqual(File.ReadAllBytes(lockedPath)), "current storage failure gates execution even before immutable option refresh");
                }
                VisionPipelineStorage.Save(selected, pipeline.CopyWorkingPipeline());
                Require(!pipeline.HasPersistenceFailure && pipeline.RunCommand.CanExecute(null) && tool.RunCommand.CanExecute(null), "explicit storage recovery clears live gate without stale projection");
                int beforeDisposedNotices = notifications, beforeDisposedCallbacks = callbacks;
                string disposedText = model.MainActionText; model.Dispose(); recipes.SaveRecipeCommand.Execute(null);
                Require(notifications == beforeDisposedNotices + 1 && model.MainActionText == disposedText, "disposed root ignores save notification");
                model = new(new SystemStateConfig(), _ => true, recipes: recipes);
                Require(model.MainActionKind == string.Empty && callbacks == beforeDisposedCallbacks + 1, "reopened root has ready transient state without extra save");
                recipes.MainRecipeName = other; Pump(4); Require(selected == other && !recipes.HasRecipeSaveFailure && model.RecipeSaveState == "Saved", "recipe switch clears previous failure");
                string inactivePath = RecipeWorkspaceService.GetVisionPipelinePath(other, "Main"); byte[] inactiveValid = File.ReadAllBytes(inactivePath);
                File.WriteAllText(inactivePath, "<VisionPipeline truncated"); recipes.RefreshOptions(); Pump(4);
                Require(recipes.SelectedPipelineOption?.PipelineName != "Main" && model.RecipeSaveState == "Saved", "inactive malformed pipeline does not change current clean status");
                File.WriteAllBytes(inactivePath, inactiveValid); recipes.RefreshOptions(); Pump(4);
                string singleRecipe = "Smoke_SingleReadFault_" + token; VisionPipeline validPipeline = new() { Name = "Pipeline" };
                VisionPipelineStorage.Save(singleRecipe, validPipeline); VisionPipelineStorage.SaveActivePipelineName(singleRecipe, "Pipeline"); recipes.MainRecipeName = singleRecipe; Pump(4);
                if (recipes.PipelineOptions.Count != 1 || recipes.SelectedPipelineOption?.PipelineName != "Pipeline") throw new InvalidOperationException("Single-pipeline load-fault setup changed.");
                string pipelinePath = RecipeWorkspaceService.GetVisionPipelinePath(singleRecipe, recipes.SelectedPipelineOption.PipelineName); byte[] valid = File.ReadAllBytes(pipelinePath);
                File.WriteAllText(pipelinePath, "<VisionPipeline truncated"); recipes.RefreshOptions(); Pump(4);
                File.WriteAllText(Path.ChangeExtension(outputPath, ".load-probe.json"), JsonSerializer.Serialize(new { SelectedRecipe = recipes.SelectedRecipeName, SelectedPipeline = recipes.SelectedPipelineOption?.PipelineName, XmlValid = recipes.SelectedPipelineOption?.XmlValid, HasPersistenceFailure = recipes.HasSelectedRecipePersistenceFailure, DisplayState = model.RecipeSaveState, Detail = model.RecipeSaveStatusToolTip, FaultedPath = pipelinePath }, new JsonSerializerOptions { WriteIndented = true }));
                Require(model.RecipeSaveState == "Error" && (recipes.SelectedPipelineOption?.XmlValid == false || recipes.HasSelectedRecipePersistenceFailure) && !string.IsNullOrWhiteSpace(model.RecipeSaveStatusToolTip), "single current malformed XML never reports Saved");
                VisionPipelineStorage.Save(singleRecipe, validPipeline); recipes.RefreshOptions(); Pump(4);
                Require(recipes.SelectedPipelineOption?.XmlValid == true && !recipes.HasSelectedRecipePersistenceFailure && model.RecipeSaveState == "Saved" && valid.SequenceEqual(File.ReadAllBytes(pipelinePath)), "existing valid save recovery restores status and original bytes");
                File.WriteAllText(Path.ChangeExtension(outputPath, ".checks.json"), JsonSerializer.Serialize(new { Cases = cases, SaveCallbacks = callbacks, SuccessNotifications = notifications, StepCommits = commits, ProductSHA256 = Convert.ToHexString(SHA256.HashData(File.ReadAllBytes(typeof(OpenVisionShellHostView).Assembly.Location))), Scope = "Isolated callback and actual XML file-lock recovery; in-process unsaved Mean Run and command guards; native F8 delegate seam only. No CU/native DPI/full Main verification", ActualInput = false, FinalN = (int?)null }, new JsonSerializerOptions { WriteIndented = true }));
            }
            finally { recipes.DetachWorkbenchPipeline(pipeline); model.Dispose(); }
        });
    }

    private static CaptureResult CaptureMainGuideGlyph(string outputPath, bool baseline = false)
    {
        OpenVisionShellHostView host = CreateShellHost("Smoke_MainGuideGlyph", false);
        return CaptureWindowWithContent(host, outputPath, 1280, 760, () =>
        {
            Button guide = FindVisualChildren<Button>(host).Single(b => AutomationProperties.GetAutomationId(b) == "HostGuideButton");
            List<object> cases = new(); List<string> failures = new(); OpenVisionLanguage initial = OpenVisionLanguageService.CurrentLanguage;
            foreach (int width in new[] { 1280, 1600 })
            foreach (string palette in new[] { "Dark", "Light" })
            foreach (OpenVisionLanguage language in new[] { OpenVisionLanguage.Korean, OpenVisionLanguage.English })
            {
                Window.GetWindow(host).Width = width;
                OpenVisionLanguageService.SetLanguage(language, false);
                (palette == "Dark" ? host.Workbench.SelectDarkThemeCommand : host.Workbench.SelectLightThemeCommand).Execute(null); Pump(8);
                Observe(width + "-" + palette + "-" + language + "-normal");
                if (!baseline)
                {
                    guide.Focus(); Pump(4); Observe(width + "-" + palette + "-" + language + "-inprocess-focus");
                    guide.IsEnabled = false; Pump(4); Observe(width + "-" + palette + "-" + language + "-synthetic-disabled");
                    guide.ClearValue(UIElement.IsEnabledProperty); Pump(4); Observe(width + "-" + palette + "-" + language + "-restored");
                }
            }
            OpenVisionLanguageService.SetLanguage(initial, false);
            File.WriteAllText(Path.ChangeExtension(outputPath, ".checks.json"), JsonSerializer.Serialize(new { Cases = cases, Failures = failures, Scope = "Inprocess Main guide canonical30/16/ghost/.42/KOENF1; focus/disabled synthetic; fresh baseline no inherited-padding reconstruction; no guide invocation/physical input/nativeDPI/Main score", FinalN = (int?)null, LoadedAssembly = typeof(OpenVisionShellHostView).Assembly.Location, LoadedSHA256 = Convert.ToHexString(SHA256.HashData(File.ReadAllBytes(typeof(OpenVisionShellHostView).Assembly.Location))) }, new JsonSerializerOptions { WriteIndented = true }));
            if (failures.Count > 0) throw new InvalidOperationException("Main guide glyph: " + string.Join("; ", failures));
            void Observe(string state)
            {
                var icon = FindVisualChildren<MahApps.Metro.IconPacks.PackIconMaterial>(guide).Single();
                ContentPresenter presenter = FindVisualChildren<ContentPresenter>(guide).First(p => ReferenceEquals(p.TemplatedParent, guide));
                Rect iconBounds = icon.TransformToAncestor(guide).TransformBounds(new Rect(0, 0, icon.ActualWidth, icon.ActualHeight));
                Geometry clip = VisualTreeHelper.GetClip(presenter); Rect clipBounds = clip?.Bounds ?? Rect.Empty; List<string> errors = new();
                if (icon.Kind != MahApps.Metro.IconPacks.PackIconMaterialKind.HelpCircleOutline || icon.ActualWidth != 16 || icon.ActualHeight != 16) errors.Add("kind/size");
                if (presenter.ActualWidth + 0.5 < icon.ActualWidth || presenter.ActualHeight + 0.5 < icon.ActualHeight || (!clipBounds.IsEmpty && (clipBounds.Width + 0.5 < icon.ActualWidth || clipBounds.Height + 0.5 < icon.ActualHeight))) errors.Add("content clipped");
                if (iconBounds.X < 0 || iconBounds.Y < 0 || iconBounds.Right > guide.ActualWidth || iconBounds.Bottom > guide.ActualHeight) errors.Add("icon outside button");
                if (!ReferenceEquals(guide.Command, host.ChromeCommands.OpenTutorialCommand)) errors.Add("existing tutorial command");
                if (guide.ActualWidth != 30 || guide.ActualHeight != 30) errors.Add("canonical button size");
                string expectedTip = OpenVisionLanguageService.CurrentLanguage == OpenVisionLanguage.Korean ? "사용 설명서 (F1)" : "User manual (F1)";
                if (!Equals(guide.ToolTip, expectedTip)) errors.Add("localized F1 tooltip");
                Border chrome = (Border)guide.Template.FindName("buttonChrome", guide);
                bool disabled = state.EndsWith("synthetic-disabled", StringComparison.Ordinal);
                if (guide.Background is not SolidColorBrush bg || bg.Color.A != 0 || chrome.BorderBrush is not SolidColorBrush border || border.Color.A != 0) errors.Add("ghost normal frame");
                if (guide.Opacity != (disabled ? 0.42 : 1.0)) errors.Add("disabled/recovery opacity");
                string capture = Path.Combine(Path.GetDirectoryName(outputPath)!, "guide-context-" + cases.Count + "-" + state + ".png"); ScreenshotPngWriter.WriteElementPng(host, capture, (int)Math.Ceiling(host.ActualWidth), (int)Math.Ceiling(host.ActualHeight));
                Rect guideBounds = guide.TransformToAncestor(host).TransformBounds(new Rect(0, 0, guide.ActualWidth, guide.ActualHeight));
                cases.Add(new { State = state, Capture = capture, GuideBounds = new { guideBounds.X, guideBounds.Y, guideBounds.Width, guideBounds.Height }, FreshProductBaseline = baseline, ButtonHeight = guide.ActualHeight, Background = guide.Background.ToString(), BorderBrush = chrome.BorderBrush.ToString(), Opacity = guide.Opacity, ToolTip = guide.ToolTip, Kind = icon.Kind.ToString(), ButtonWidth = guide.ActualWidth, Padding = guide.Padding.ToString(), PresenterWidth = presenter.ActualWidth, PresenterHeight = presenter.ActualHeight, Clip = clipBounds.ToString(), IconBounds = iconBounds.ToString(), Foreground = icon.Foreground.ToString(), Errors = errors }); failures.AddRange(errors.Select(e => state + ": " + e));
            }
        });
    }

    private static CaptureResult CaptureMainRecipeSelector(string outputPath, int width, int height, bool popupOnly = false)
    {
        string id = Guid.NewGuid().ToString("N")[..8], shortName = "Smoke_RS_" + id, longName = "Smoke_Recipe_긴이름_Long_Name_For_Selector_" + id;
        GlobalState global = new(); global.Recipe.Name = shortName;
        foreach (string name in new[] { shortName, longName }) VisionPipelineStorage.Save(name, new VisionPipeline { Name = "Main" });
        global.System.SaveWorkbenchLayout(new SystemStateConfig());
        using DisplayManagerService display = new(); OpenVisionShellHostWindow window = new(new ApplicationRuntimeContext(global, display));
        window.ClearValue(OpenVisionShellHostWindow.ClosingCommandProperty); OpenVisionShellHostView host = window.ShellHostForSmoke;
        return CaptureStandaloneWindow(window, outputPath, width, height, () =>
        {
            var model = host.Workbench; var recipes = host.RecipeCommands; model.Tool.ConfigureAutoRunPreference(() => false, _ => { });
            ComboBox combo = FindNamedVisualChild<ComboBox>(host, "cbHostRecipe"); ToggleButton manager = FindNamedVisualChild<ToggleButton>(host, "btnHostRecipeManager");
            List<object> cases = new(); List<string> failures = new(); int runs = host.NativePreviewRunCount;
            Dictionary<string, byte[]> saved = new[] { shortName, longName }.ToDictionary(name => RecipeWorkspaceService.GetVisionPipelinePath(name, "Main"), name => File.ReadAllBytes(RecipeWorkspaceService.GetVisionPipelinePath(name, "Main")));
            OpenVisionLanguage initial = OpenVisionLanguageService.CurrentLanguage;
            try
            {
                foreach (string palette in new[] { "Dark", "Light" })
                foreach (OpenVisionLanguage language in new[] { OpenVisionLanguage.Korean, OpenVisionLanguage.English })
                {
                    (palette == "Dark" ? model.SelectDarkThemeCommand : model.SelectLightThemeCommand).Execute(null);
                    OpenVisionLanguageService.SetLanguage(language, false); Pump(8);
                    combo.SelectedItem = longName; Pump(20); Observe(palette + "-" + language + "-selected-long", longName, true);
                    recipes.MainRecipeName = shortName; Pump(20); Observe(palette + "-" + language + "-owner-restored", shortName, true);
                    combo.Focus(); Pump(4); Observe(palette + "-" + language + "-inprocess-focus", shortName, true);
                    combo.IsDropDownOpen = true; Pump(8);
                    Popup popup = (Popup)combo.Template.FindName("PART_Popup", combo); FrameworkElement child = (FrameworkElement)popup.Child;
                    List<string> errors = new(); Button[] actions = FindVisualChildren<Button>(child).Where(b => AutomationProperties.GetAutomationId(b).StartsWith("MainRecipeMenu", StringComparison.Ordinal)).ToArray();
                    string[] ids = { "MainRecipeMenuNew", "MainRecipeMenuSaveAs", "MainRecipeMenuManage" };
                    ICommand[] commands = { model.OpenMainNewRecipeCommand, model.OpenMainSaveAsCommand, model.OpenRecipeManagerCommand };
                    for (int i = 0; i < ids.Length; i++)
                    {
                        Button action = actions.SingleOrDefault(b => AutomationProperties.GetAutomationId(b) == ids[i]);
                        if (action == null || !ReferenceEquals(action.Command, commands[i]) || !action.IsEnabled) { errors.Add(ids[i] + " command/canexecute"); continue; }
                        TextBlock caption = FindVisualChildren<TextBlock>(action).FirstOrDefault(t => t.IsVisible && !string.IsNullOrWhiteSpace(t.Text));
                        if (caption == null || caption.Text.Contains("Workbench.Menu.") || caption.ActualWidth + caption.Margin.Left + caption.Margin.Right + 0.5 < caption.DesiredSize.Width) errors.Add(ids[i] + " caption");
                    }
                    if (child.ActualWidth > 331 || child.ActualWidth < combo.ActualWidth || child.ActualHeight <= 0 || !combo.IsDropDownOpen) errors.Add("popup bounds");
                    string popupCapture = Path.Combine(Path.GetDirectoryName(outputPath)!, $"recipe-selector-{width}-{cases.Count:00}-{palette}-{language}-popup.png");
                    ScreenshotPngWriter.WriteElementPng(child, popupCapture, (int)Math.Ceiling(child.ActualWidth), (int)Math.Ceiling(child.ActualHeight));
                    cases.Add(new { State = palette + "-" + language + "-popup", Capture = popupCapture, Width = child.ActualWidth, Height = child.ActualHeight, Errors = errors }); failures.AddRange(errors.Select(e => palette + "-" + language + ": " + e));
                    Button newButton = actions.Single(b => AutomationProperties.GetAutomationId(b) == "MainRecipeMenuNew"); InvokeFooter(newButton);
                    if (!model.IsMainRecipeOpen || combo.IsDropDownOpen) failures.Add("new entry did not open existing form/close recipe popup");
                    model.CloseMainRecipeCommand.Execute(null); Pump(8); Observe(palette + "-" + language + "-new-cancel", shortName, true);
                    combo.IsDropDownOpen = true; Pump(8); actions = FindVisualChildren<Button>((FrameworkElement)popup.Child).Where(b => AutomationProperties.GetAutomationId(b).StartsWith("MainRecipeMenu", StringComparison.Ordinal)).ToArray();
                    Button saveAs = actions.Single(b => AutomationProperties.GetAutomationId(b) == "MainRecipeMenuSaveAs"); InvokeFooter(saveAs);
                    if (!model.IsMainRecipeOpen || !model.IsMainRecipeSaveAs || combo.IsDropDownOpen) failures.Add("save-as entry/form/popup");
                    model.CloseMainRecipeCommand.Execute(null); Pump(8); Observe(palette + "-" + language + "-saveas-cancel", shortName, true);
                    combo.IsDropDownOpen = true; Pump(8); Button manage = FindVisualChildren<Button>((FrameworkElement)popup.Child).Single(b => AutomationProperties.GetAutomationId(b) == "MainRecipeMenuManage"); InvokeFooter(manage);
                    if (manager.IsChecked != true || combo.IsDropDownOpen) failures.Add("manage entry did not activate existing host/close popup");
                    manager.IsChecked = false; combo.IsDropDownOpen = false; Pump(8); Observe(palette + "-" + language + "-manager-return", shortName, true);
                    combo.IsEnabled = false; Pump(4); Observe(palette + "-" + language + "-synthetic-disabled", shortName, false);
                    combo.ClearValue(UIElement.IsEnabledProperty); Pump(4); Observe(palette + "-" + language + "-disabled-restored", shortName, true);
                }
                if (host.NativePreviewRunCount != runs || model.Images.Count != 0) failures.Add("recipe UI caused Run or images");
                foreach (var pair in saved) if (!pair.Value.SequenceEqual(File.ReadAllBytes(pair.Key))) failures.Add("recipe UI changed saved XML: " + pair.Key);
                File.WriteAllText(Path.ChangeExtension(outputPath, ".checks.json"), JsonSerializer.Serialize(new { Cases = cases, Failures = failures, Scope = "Inprocess WPF Main recipe selector only; real string selection/owner restoration and existing command entry/cancel, synthetic focus/disabled; no actual pointer/keyboard/native DPI", NoRun = host.NativePreviewRunCount == runs, FinalN = (int?)null, Width = width, Height = height, LoadedAssembly = typeof(OpenVisionShellHostView).Assembly.Location, LoadedSHA256 = Convert.ToHexString(SHA256.HashData(File.ReadAllBytes(typeof(OpenVisionShellHostView).Assembly.Location))) }, new JsonSerializerOptions { WriteIndented = true }));
                if (failures.Count > 0) throw new InvalidOperationException("Main recipe selector: " + string.Join("; ", failures));
            }
            finally { combo.IsDropDownOpen = false; combo.ClearValue(UIElement.IsEnabledProperty); manager.IsChecked = false; OpenVisionLanguageService.SetLanguage(initial, false); }
            void InvokeFooter(Button button)
            {
                var peer = new System.Windows.Automation.Peers.ButtonAutomationPeer(button);
                var invoke = (System.Windows.Automation.Provider.IInvokeProvider)peer.GetPattern(System.Windows.Automation.Peers.PatternInterface.Invoke);
                invoke.Invoke(); Pump(8);
            }
            void Observe(string state, string expected, bool enabled)
            {
                if (popupOnly) return;
                TextBlock name = combo.Template.FindName("mainRecipeSelectedName", combo) as TextBlock;
                Border chrome = combo.Template.FindName("comboChrome", combo) as Border; List<string> errors = new();
                if (name == null || name.Text != expected || name.TextTrimming != TextTrimming.CharacterEllipsis || name.ActualWidth <= 0 || !name.IsVisible) errors.Add("selected name/ellipsis/visibility");
                if (combo.SelectedItem as string != expected || recipes.MainRecipeName != expected || global.Recipe.Name != expected) errors.Add("selection bidirectional owner");
                if (combo.IsEnabled != enabled || combo.Height != 34 || combo.ToolTip?.ToString() != expected) errors.Add("enabled/height/full tooltip value");
                if (!FindVisualChildren<MahApps.Metro.IconPacks.PackIconMaterial>(combo).Any(i => i.Kind == MahApps.Metro.IconPacks.PackIconMaterialKind.BookOpenPageVariantOutline)) errors.Add("book icon");
                if (chrome == null || chrome.Background?.ToString() != combo.Background?.ToString()) errors.Add("semantic selected background");
                string capture = Path.Combine(Path.GetDirectoryName(outputPath)!, $"recipe-selector-{width}-{cases.Count:00}-{state}.png"); ScreenshotPngWriter.WriteElementPng(host, capture, width, height);
                cases.Add(new { State = state, Expected = expected, Selected = combo.SelectedItem, Owner = recipes.MainRecipeName, Capture = capture, Background = chrome?.Background?.ToString(), Foreground = name?.Foreground?.ToString(), Width = combo.ActualWidth, NameWidth = name?.ActualWidth, Errors = errors }); failures.AddRange(errors.Select(e => state + ": " + e));
            }
        });
    }

