    private static CaptureResult CaptureMainImageMenu(string outputPath, int width, int height, bool baseline = false)
    {
        GlobalState global = new(); global.Recipe.Name = "Smoke_MainImageMenu_" + Guid.NewGuid().ToString("N");
        VisionPipelineStorage.Save(global.Recipe.Name, new VisionPipeline { Name = "Main" }); global.System.SaveWorkbenchLayout(new SystemStateConfig());
        string savedPath = RecipeWorkspaceService.GetVisionPipelinePath(global.Recipe.Name, "Main"); byte[] savedBytes = File.ReadAllBytes(savedPath);
        using DisplayManagerService display = new(); OpenVisionShellHostWindow window = new(new ApplicationRuntimeContext(global, display));
        window.ClearValue(OpenVisionShellHostWindow.ClosingCommandProperty); OpenVisionShellHostView host = window.ShellHostForSmoke;
        return CaptureStandaloneWindow(window, outputPath, width, height, () =>
        {
            var model = host.Workbench; model.Tool.ConfigureAutoRunPreference(() => false, _ => { });
            MenuItem menu = FindVisualChildren<MenuItem>(host).Single(item => AutomationProperties.GetAutomationId(item) == "WorkbenchImagesMenu");
            string[] keys = { "Workbench.Images.AddFile", "Workbench.Images.AddFolder", "Workbench.Images.AddSamples", "Workbench.Images.AddGoodFile", "Workbench.Images.AddBadFile", "Workbench.Images.AddGoodFolder", "Workbench.Images.AddBadFolder" };
            string[] parameters = { "", "", "", "good", "bad", "good", "bad" };
            string[] icons = { "ImagePlusOutline", "FolderImage", "ImageMultipleOutline", "ThumbUpOutline", "ThumbDownOutline", "FolderImage", "FolderImage" };
            List<object> cases = new(); List<string> failures = new(); int runs = host.NativePreviewRunCount;
            byte[] working = VisionPipelineExecutionPlan.SerializePipeline(model.Pipeline.WorkingCopyForTest); OpenVisionLanguage initial = OpenVisionLanguageService.CurrentLanguage;
            FieldInfo runningField = typeof(OpenVisionWorkbenchPipelineViewModel).GetField("running", BindingFlags.Instance | BindingFlags.NonPublic)!;
            MethodInfo raiseState = typeof(OpenVisionWorkbenchPipelineViewModel).GetMethod("RaiseState", BindingFlags.Instance | BindingFlags.NonPublic)!;
            try
            {
                if (baseline) Observe("before-missing-four", true);
                else
                {
                    foreach (string palette in new[] { "Dark", "Light" })
                    foreach (OpenVisionLanguage language in new[] { OpenVisionLanguage.Korean, OpenVisionLanguage.English })
                    {
                        (palette == "Dark" ? model.SelectDarkThemeCommand : model.SelectLightThemeCommand).Execute(null); OpenVisionLanguageService.SetLanguage(language, false); Pump(4);
                        Observe(palette + "-" + language + "-normal", true);
                        runningField.SetValue(model.Pipeline, true); raiseState.Invoke(model.Pipeline, null); Pump(4); Observe(palette + "-" + language + "-synthetic-running", false);
                        runningField.SetValue(model.Pipeline, false); raiseState.Invoke(model.Pipeline, null); Pump(4); Observe(palette + "-" + language + "-restored", true);
                    }
                    OpenVisionShellHostCommandController loader = (OpenVisionShellHostCommandController)typeof(OpenVisionShellHostView).GetField("commandController", BindingFlags.Instance | BindingFlags.NonPublic)!.GetValue(host)!;
                    List<object> imports = new();
                    foreach (string label in new[] { "good", "bad", "" })
                    {
                        string path = Path.Combine(Path.GetDirectoryName(outputPath)!, "menu-label-" + width + "-" + (label == "" ? "none" : label) + ".png");
                        using (Bitmap input = new(37, 23)) { using Graphics graphics = Graphics.FromImage(input); graphics.Clear(DrawingColor.Teal); input.Save(path, ImageFormat.Png); }
                        byte[] bytes = File.ReadAllBytes(path); int count = model.Images.Count;
                        if (loader.AddWorkspaceImages(new[] { path }, label) != 1 || model.Images.Count != count + 1 || model.Images.Images.Single(item => item.Path == Path.GetFullPath(path)).Label != label) failures.Add("explicit import label " + label);
                        if (!bytes.SequenceEqual(File.ReadAllBytes(path))) failures.Add("input bytes " + label);
                        imports.Add(new { Label = label, model.Images.Count, File = path, Boundary = "Existing writer with owned selected paths; native picker/Cancel not exercised" });
                    }
                    File.WriteAllText(Path.ChangeExtension(outputPath, ".imports.json"), JsonSerializer.Serialize(imports, new JsonSerializerOptions { WriteIndented = true }));
                }
                bool saved = savedBytes.SequenceEqual(File.ReadAllBytes(savedPath)), copy = working.SequenceEqual(VisionPipelineExecutionPlan.SerializePipeline(model.Pipeline.WorkingCopyForTest)), noRun = runs == host.NativePreviewRunCount;
                if (!saved || !copy || !noRun) failures.Add("saved/working/no-run invariant");
                File.WriteAllText(Path.ChangeExtension(outputPath, ".checks.json"), JsonSerializer.Serialize(new { Cases = cases, Failures = failures, SavedUnchanged = saved, WorkingCopyUnchanged = copy, NoRun = noRun, ActualInput = false, Width = width, Height = height, LoadedAssembly = typeof(OpenVisionShellHostView).Assembly.Location, LoadedSHA256 = Convert.ToHexString(SHA256.HashData(File.ReadAllBytes(typeof(OpenVisionShellHostView).Assembly.Location))), FinalN = (int?)null }, new JsonSerializerOptions { WriteIndented = true }));
                if (failures.Count > 0) throw new InvalidOperationException("Main image menu: " + string.Join("; ", failures));
            }
            finally { menu.IsSubmenuOpen = false; runningField.SetValue(model.Pipeline, false); raiseState.Invoke(model.Pipeline, null); OpenVisionLanguageService.SetLanguage(initial, false); }
            void Observe(string state, bool editable)
            {
                menu.IsSubmenuOpen = true; Pump(5); List<string> errors = new(); MenuItem[] items = menu.Items.OfType<MenuItem>().ToArray();
                if (items.Length != 7) errors.Add("canonical seven entries: " + items.Length);
                if (menu.Items.OfType<Separator>().Count() != 1 || menu.Items.Count != 8) errors.Add("one separator/no section header");
                for (int i = 0; i < Math.Min(items.Length, keys.Length); i++)
                {
                    ICommand expected = i == 2 ? model.Workspace.OpenSampleCommand : i == 1 || i >= 5 ? model.Workspace.OpenFolderCommand : model.Workspace.LoadImageCommand;
                    if (items[i].Header?.ToString() != model[keys[i]]) errors.Add("localized entry " + i);
                    if (!ReferenceEquals(items[i].Command, expected) || (items[i].CommandParameter as string ?? "") != parameters[i]) errors.Add("command/label " + i);
                    if (items[i].IsEnabled && !editable) errors.Add("running entry enabled " + i);
                    if (editable && i != 2 && !items[i].IsEnabled) errors.Add("restored entry disabled " + i);
                    var icon = items[i].Icon as MahApps.Metro.IconPacks.PackIconMaterial;
                    if (icon == null || icon.Kind.ToString() != icons[i] || icon.Width != 16 || icon.Height != 16) errors.Add("canonical icon " + i);
                    if (icon?.Foreground is not SolidColorBrush iconBrush || items[i].Foreground is not SolidColorBrush itemBrush || iconBrush.Color != itemBrush.Color || icon.IsEnabled != items[i].IsEnabled) errors.Add("rendered icon brush/enabled " + i);
                }
                System.Windows.Controls.Primitives.Popup popup = FindNamedVisualChild<System.Windows.Controls.Primitives.Popup>(menu, "PART_Popup"); FrameworkElement root = popup?.Child as FrameworkElement;
                string dir = Path.GetDirectoryName(outputPath)!, prefix = "image-menu-" + width + "-" + cases.Count.ToString("00") + "-" + state;
                string capture = Path.Combine(dir, prefix + ".png"), popupCapture = Path.Combine(dir, prefix + "-popup.png");
                ScreenshotPngWriter.WriteElementPng(host, capture, width, height);
                if (root != null) ScreenshotPngWriter.WriteElementPng(root, popupCapture, (int)Math.Ceiling(root.ActualWidth), (int)Math.Ceiling(root.ActualHeight)); else errors.Add("popup not rendered");
                menu.IsSubmenuOpen = false; Pump(3);
                if (menu.IsSubmenuOpen || host.NativePreviewRunCount != runs || model.Images.Count != 0) errors.Add("open/close caused action");
                cases.Add(new { State = state, Editable = editable, EntryCount = items.Length, Captions = items.Select(item => item.Header?.ToString()).ToArray(), Labels = items.Select(item => item.CommandParameter as string).ToArray(), Icons = items.Select(item => new { Kind = (item.Icon as MahApps.Metro.IconPacks.PackIconMaterial)?.Kind.ToString(), Foreground = (item.Icon as MahApps.Metro.IconPacks.PackIconMaterial)?.Foreground?.ToString(), Expected = item.Foreground?.ToString(), Enabled = (item.Icon as MahApps.Metro.IconPacks.PackIconMaterial)?.IsEnabled }).ToArray(), Capture = capture, PopupCapture = popupCapture, Errors = errors });
                failures.AddRange(errors.Select(error => state + ": " + error));
            }
        });
    }

    private static CaptureResult CaptureMainImageChips(string outputPath, int width, int height, bool baseline = false)
    {
        GlobalState global = new(); global.Recipe.Name = "Smoke_MainImageChips_" + Guid.NewGuid().ToString("N");
        VisionPipelineStorage.Save(global.Recipe.Name, new VisionPipeline { Name = "Main" }); global.System.SaveWorkbenchLayout(new SystemStateConfig());
        string savedPath = RecipeWorkspaceService.GetVisionPipelinePath(global.Recipe.Name, "Main"); byte[] savedBytes = File.ReadAllBytes(savedPath);
        using DisplayManagerService display = new(); OpenVisionShellHostWindow window = new(new ApplicationRuntimeContext(global, display));
        window.ClearValue(OpenVisionShellHostWindow.ClosingCommandProperty); OpenVisionShellHostView host = window.ShellHostForSmoke;
        return CaptureStandaloneWindow(window, outputPath, width, height, () =>
        {
            var model = host.Workbench; var images = model.Images; model.Tool.ConfigureAutoRunPreference(() => false, _ => { });
            string directory = Path.GetDirectoryName(outputPath)!; string first = Path.ChangeExtension(outputPath, ".input.png"), second = Path.ChangeExtension(outputPath, ".second.png");
            using (Bitmap input = CreateWorkspaceSeedSmokeBitmap()) input.Save(first, ImageFormat.Png);
            using (Bitmap input = new(321, 199)) { using Graphics graphics = Graphics.FromImage(input); graphics.Clear(DrawingColor.Teal); input.Save(second, ImageFormat.Png); }
            byte[] firstBytes = File.ReadAllBytes(first), secondBytes = File.ReadAllBytes(second), working = VisionPipelineExecutionPlan.SerializePipeline(model.Pipeline.WorkingCopyForTest);
            int runs = host.NativePreviewRunCount; OpenVisionLanguage initial = OpenVisionLanguageService.CurrentLanguage; List<object> cases = new(); List<string> failures = new();
            if (!baseline) Observe("empty", false, false);
            if (!host.LoadMainImageFromFileForTest(first)) throw new InvalidOperationException("Main chips valid first input");
            OpenVisionWorkbenchImageItem item = images.Images[images.CurrentIndex];
            void SetResult(string verdict, string source = "batch")
            {
                using OpenVisionWorkbenchImageResult identity = model.Pipeline.CaptureImageResult(source);
                item.ReplaceResult(new OpenVisionWorkbenchImageResult(identity.Context, identity.RecipeRevision, identity.Definition, new(), new(), verdict, 0D, source)); Pump(3);
            }
            try
            {
                if (baseline) { images.LabelCommand.Execute("good"); SetResult("Ok"); Observe("missing-current-good-and-batch-ok", true, true); }
                else
                {
                    foreach (string palette in new[] { "Dark", "Light" })
                    foreach (OpenVisionLanguage language in new[] { OpenVisionLanguage.Korean, OpenVisionLanguage.English })
                    {
                        (palette == "Dark" ? model.SelectDarkThemeCommand : model.SelectLightThemeCommand).Execute(null); OpenVisionLanguageService.SetLanguage(language, false); Pump(4);
                        images.LabelCommand.Execute("good"); SetResult("Ok"); Observe(palette + "-" + language + "-good-ok", true, true);
                        images.LabelCommand.Execute("bad"); SetResult("Ng"); Observe(palette + "-" + language + "-bad-ng", true, true);
                        images.LabelCommand.Execute(""); item.ReplaceResult(null); Pump(3); Observe(palette + "-" + language + "-unlabeled-before", false, false);
                    }
                    model.SelectDarkThemeCommand.Execute(null); OpenVisionLanguageService.SetLanguage(OpenVisionLanguage.English, false);
                    images.LabelCommand.Execute("good"); SetResult("Error"); Observe("error", true, true);
                    SetResult("Done"); Observe("no-verdict", true, true);
                    item.MarkResultStale(); Pump(3); Observe("stale-hidden", true, false);
                    SetResult("Ok", "flow"); Observe("flow-retained-visible", true, true);
                    SetResult("Ok");
                    if (!host.LoadMainImageFromFileForTest(second)) throw new InvalidOperationException("Main chips valid second input");
                    Observe("current-unlabeled-second", false, false);
                    images.PreviousCommand.Execute(null); Pump(4); Observe("previous-restores-label-and-batch", true, true);
                    if (!ReferenceEquals(images.Images[images.CurrentIndex], item)) failures.Add("previous did not restore same current item");
                    images.SelectAllCommand.Execute(null); images.RemoveCommand.Execute(null); Pump(4); Observe("remove-to-empty", false, false);
                }
                bool saved = savedBytes.SequenceEqual(File.ReadAllBytes(savedPath)), copy = working.SequenceEqual(VisionPipelineExecutionPlan.SerializePipeline(model.Pipeline.WorkingCopyForTest));
                bool input = firstBytes.SequenceEqual(File.ReadAllBytes(first)) && secondBytes.SequenceEqual(File.ReadAllBytes(second)), noRun = runs == host.NativePreviewRunCount;
                if (!saved || !copy || !input || !noRun) failures.Add("saved/working/input/no-run invariant");
                File.WriteAllText(Path.ChangeExtension(outputPath, ".checks.json"), JsonSerializer.Serialize(new { Cases = cases, Failures = failures, SavedUnchanged = saved, WorkingCopyUnchanged = copy, InputUnchanged = input, NoRun = noRun, ActualInput = false, Width = width, Height = height, LoadedAssembly = typeof(OpenVisionShellHostView).Assembly.Location, LoadedSHA256 = Convert.ToHexString(SHA256.HashData(File.ReadAllBytes(typeof(OpenVisionShellHostView).Assembly.Location))), FinalN = (int?)null }, new JsonSerializerOptions { WriteIndented = true }));
                if (failures.Count > 0) throw new InvalidOperationException("Main image chips: " + string.Join("; ", failures));
            }
            finally { OpenVisionLanguageService.SetLanguage(initial, false); }
            void Observe(string state, bool hasLabel, bool hasResult)
            {
                Pump(4); List<string> errors = new(); Border label = FindNamedVisualChild<Border>(host, "mainCurrentImageLabel"), result = FindNamedVisualChild<Border>(host, "mainCurrentImageResult");
                OpenVisionWorkbenchImageItem current = images.CurrentIndex < 0 ? null : images.Images[images.CurrentIndex];
                foreach (var pair in new[] { ("label", label, hasLabel), ("result", result, hasResult) })
                {
                    if (pair.Item2 == null) { errors.Add(pair.Item1 + " missing"); continue; }
                    if (pair.Item2.IsVisible != pair.Item3) errors.Add(pair.Item1 + " visibility");
                    BindingExpression binding = BindingOperations.GetBindingExpression(pair.Item2, FrameworkElement.DataContextProperty);
                    if (binding?.Status != BindingStatus.Active || !ReferenceEquals(pair.Item2.DataContext, current)) errors.Add(pair.Item1 + " current item binding");
                    if (!pair.Item3) continue;
                    TextBlock text = FindVisualChildren<TextBlock>(pair.Item2).Single(); string expected = pair.Item1 == "label" ? current.LabelText : current.ResultText;
                    if (text.Text != expected) errors.Add(pair.Item1 + " localized value");
                    if (pair.Item1 == "label" && text.IsVisible != model.ShowViewerZoomControls) errors.Add("label compact caption");
                    string tone = pair.Item1 == "label" ? (current.Label == "good" ? "Ok" : "Ng") : current.ResultKind;
                    Brush expectedBrush = (Brush)host.FindResource("OpenVision.Workbench." + tone + "Brush");
                    if (System.Windows.Documents.TextElement.GetForeground(pair.Item2).ToString() != expectedBrush.ToString()) errors.Add(pair.Item1 + " semantic tone");
                    Rect bounds = new(pair.Item2.TranslatePoint(new Point(), host), pair.Item2.RenderSize);
                    if (!new Rect(new Point(), host.RenderSize).Contains(bounds)) errors.Add(pair.Item1 + " host bounds");
                    if (text.IsVisible && text.ActualWidth == 0D) errors.Add(pair.Item1 + " zero caption width");
                    ScrollViewer toolbar = FindNamedVisualChild<ScrollViewer>(host, "workbenchViewerToolbarScroll");
                    foreach (string name in new[] { "mainCurrentImageLabel", "mainCurrentImageResult", "btnMainImagePrevious", "btnMainImageNext" })
                    {
                        FrameworkElement control = FindNamedVisualChild<FrameworkElement>(host, name); if (!control.IsVisible) continue;
                        Rect local = new(control.TranslatePoint(new Point(), toolbar), control.RenderSize);
                        if (local.Left < 0D || local.Right > toolbar.ActualWidth) errors.Add(name + " toolbar viewport bounds " + local + " / " + toolbar.ActualWidth);
                    }
                }
                string capture = Path.Combine(directory, "image-chips-" + width + "-" + cases.Count.ToString("00") + "-" + state + ".png"); ScreenshotPngWriter.WriteElementPng(host, capture, width, height);
                cases.Add(new { State = state, LabelVisible = label?.IsVisible, ResultVisible = result?.IsVisible, Current = images.CurrentName, Position = images.PositionText, ExpectedLabel = hasLabel, ExpectedResult = hasResult, Capture = capture, Errors = errors });
                failures.AddRange(errors.Select(error => state + ": " + error));
            }
        });
    }

    private static CaptureResult CaptureMainImages(string outputPath, int width, int height)
    {
        OpenVisionShellHostView host = CreateShellHost("Smoke_MainImages", false);
        string directory = Path.GetDirectoryName(outputPath)!;
        string[] names = { "Main_A_640x360.png", "Main_B_321x199_long_file_name_for_compact_image_list.png", "Main_C_3000x2000.png" };
        Size[] sizes = { new(640, 360), new(321, 199), new(3000, 2000) };
        DrawingColor[] colors = { DrawingColor.Teal, DrawingColor.IndianRed, DrawingColor.Navy };
        for (int i = 0; i < names.Length; i++)
        {
            using Bitmap image = new((int)sizes[i].Width, (int)sizes[i].Height);
            using Graphics graphics = Graphics.FromImage(image);
            graphics.Clear(colors[i]);
            image.Save(Path.Combine(directory, names[i]), ImageFormat.Png);
        }
        File.WriteAllText(Path.Combine(directory, "Main_invalid.png"), "owned invalid image");
        List<object> cases = new();
        return CaptureWindowWithContent(host, outputPath, width, height, () =>
        {
            OpenVisionWorkbenchImagesViewModel images = host.Workbench.Images;
            host.Workbench.IsBottomCollapsed = false; host.Workbench.SelectedBottomTab = 0; Pump(4);
            int runs = host.NativePreviewRunCount;
            object legacyParameter = new(), deliveredParameter = null;
            Border clickProbe = new();
            OpenVisionLab.Mvvm.Behaviors.InputCommandBehaviors.SetMouseLeftButtonUpCommandParameter(clickProbe, legacyParameter);
            OpenVisionLab.Mvvm.Behaviors.InputCommandBehaviors.SetMouseLeftButtonUpCommand(clickProbe, new OpenVisionLab.Mvvm.RelayCommand<object>(value => deliveredParameter = value));
            clickProbe.RaiseEvent(new MouseButtonEventArgs(Mouse.PrimaryDevice, Environment.TickCount, MouseButton.Left) { RoutedEvent = UIElement.MouseLeftButtonUpEvent });
            if (!ReferenceEquals(deliveredParameter, legacyParameter)) throw new InvalidOperationException("Existing field-click command parameter changed without modifier opt-in.");
            OpenVisionLab.Mvvm.Behaviors.InputCommandBehaviors.SetIncludeModifierKeys(clickProbe, true);
            clickProbe.RaiseEvent(new MouseButtonEventArgs(Mouse.PrimaryDevice, Environment.TickCount, MouseButton.Left) { RoutedEvent = UIElement.MouseLeftButtonUpEvent });
            if (deliveredParameter is not Tuple<object, bool, bool> modifierParameter || !ReferenceEquals(modifierParameter.Item1, legacyParameter)) throw new InvalidOperationException("Main modifier opt-in lost the original item.");
            OpenVisionLab.Mvvm.Behaviors.InputCommandBehaviors.SetMouseLeftButtonUpCommand(clickProbe, null);
            int pageCalls = 0; bool pageEnabled = true;
            Border pageProbe = new();
            pageProbe.InputBindings.Add(new KeyBinding(new OpenVisionLab.Mvvm.RelayCommand(() => pageCalls++, () => pageEnabled), new KeyGesture(Key.PageUp)));
            Keyboard.ClearFocus();
            KeyEventArgs PageEvent(object source = null) => new(Keyboard.PrimaryDevice, PresentationSource.FromVisual(host), Environment.TickCount, Key.PageUp) { RoutedEvent = UIElement.PreviewKeyDownEvent, Source = source ?? pageProbe };
            pageProbe.RaiseEvent(PageEvent());
            if (pageCalls != 0) throw new InvalidOperationException("Preview page routing changed a default consumer.");
            OpenVisionLab.Mvvm.Behaviors.InputCommandBehaviors.SetPreviewPageNavigation(pageProbe, true);
            KeyEventArgs pageEvent = PageEvent(); pageProbe.RaiseEvent(pageEvent);
            if (pageCalls != 1 || !pageEvent.Handled) throw new InvalidOperationException("Main page binding did not run before scrolling.");
            pageEnabled = false; pageEvent = PageEvent(); pageProbe.RaiseEvent(pageEvent);
            if (pageCalls != 1 || !pageEvent.Handled) throw new InvalidOperationException("Disabled page command ran or allowed boundary scrolling.");
            pageEnabled = true; pageEvent = PageEvent(new TextBox()); pageProbe.RaiseEvent(pageEvent);
            if (pageCalls != 1 || pageEvent.Handled) throw new InvalidOperationException("Main page navigation consumed field input.");
            OpenVisionLab.Mvvm.Behaviors.InputCommandBehaviors.SetPreviewPageNavigation(pageProbe, false);
            pageProbe.RaiseEvent(PageEvent());
            if (pageCalls != 1) throw new InvalidOperationException("Preview page subscription was not detached.");
            if (images.Count != 0 || images.PositionText != "0 / 0" || images.PreviousCommand.CanExecute(null) || images.NextCommand.CanExecute(null))
                throw new InvalidOperationException("Empty Main navigation is enabled or has a false count.");
            foreach (string name in names)
            {
                if (!host.LoadMainImageFromFileForTest(Path.Combine(directory, name))) throw new InvalidOperationException("Main image setup failed.");
            }
            Pump(8);
            if (images.Count != 3 || images.PositionText != "3 / 3" || images.NextCommand.CanExecute(null) || host.Workbench.Shell.WorkspaceInputSizeText != "3000×2000")
                throw new InvalidOperationException("Main list/current index or original source size is incorrect.");
            object stableVisibleSource = images.VisibleImages;
            Border previousImageCard = FindVisualChildren<Border>(host).Single(value => AutomationProperties.GetAutomationId(value) == "MainImageThumbnail" && ReferenceEquals(value.DataContext, images.Images[1]));
            images.PreviousCommand.Execute(null); Pump(4);
            if (!ReferenceEquals(stableVisibleSource, images.VisibleImages) || !FindVisualChildren<Border>(host).Contains(previousImageCard))
                throw new InvalidOperationException("Image state refresh replaced the focused card/ItemsSource.");
            Keyboard.ClearFocus();
            KeyEventArgs mainPage = new(Keyboard.PrimaryDevice, PresentationSource.FromVisual(host), Environment.TickCount, Key.PageDown) { RoutedEvent = UIElement.PreviewKeyDownEvent };
            previousImageCard.RaiseEvent(mainPage); Pump(4);
            if (!mainPage.Handled || images.PositionText != "3 / 3") throw new InvalidOperationException("Main thumbnail page route did not load the next input.");
            images.PreviousCommand.Execute(null); Pump(4);
            if (images.PositionText != "2 / 3" || host.Workbench.Shell.WorkspaceInputName != names[1]) throw new InvalidOperationException("Previous did not replace the actual Main input.");
            string inputName = host.Workbench.Shell.WorkspaceInputName;
            if (host.LoadMainImageFromFileForTest(Path.Combine(directory, "Main_invalid.png")) || images.CurrentName != inputName || images.PositionText != "2 / 3")
                throw new InvalidOperationException("Decode failure lost current image/list selection.");
            images.SelectImageCommand.Execute(Tuple.Create((object)images.Images[0], true, false));
            images.LabelCommand.Execute("good");
            if (images.SelectedCount != 1 || images.PositionText != "2 / 3" || images.Images[0].Label != "good") throw new InvalidOperationException("Ctrl selection or explicit good label changed the current input.");
            images.ClearSelectionCommand.Execute(null);
            if (!images.LabelCommand.CanExecute("")) throw new InvalidOperationException("Current-image label command is disabled without a multi-selection.");
            images.LabelCommand.Execute("good");
            if (images.Images[1].Label != "good" || images.SelectedCount != 0 || images.CurrentName != inputName) throw new InvalidOperationException("Current-image fallback label changed selection/input or failed.");
            images.SelectImageCommand.Execute(Tuple.Create((object)images.Images[2], false, true));
            if (images.SelectedCount != 2 || images.PositionText != "2 / 3") throw new InvalidOperationException("Shift range selection changed the current input.");
            images.LabelCommand.Execute("bad");
            images.FilterCommand.Execute("good");
            if (images.VisibleImages.Count() != 1 || images.CurrentName != inputName) throw new InvalidOperationException("Filter changed current input or ignored explicit labels.");
            images.FilterCommand.Execute("all"); images.ClearSelectionCommand.Execute(null);
            OpenVisionLanguage initial = OpenVisionLanguageService.CurrentLanguage;
            Window window = Window.GetWindow(host);
            foreach (string paletteName in new[] { "Dark", "Light" })
            {
                ResourceDictionary palette = new() { Source = new Uri($"/OpenVisionLab;component/UI/Wpf/OpenVisionWorkbench{paletteName}.xaml", UriKind.Relative) };
                host.Resources.MergedDictionaries.Add(palette);
                try
                {
                    foreach (Size size in new[] { new Size(1920, 1032), new Size(1280, 760) })
                    {
                        window.Width = size.Width; window.Height = size.Height;
                        foreach (OpenVisionLanguage language in new[] { OpenVisionLanguage.Korean, OpenVisionLanguage.English })
                        {
                            ListBox layerRows = (ListBox)typeof(OpenVisionShellHostView).GetField("hostLayerRowsList", BindingFlags.Instance | BindingFlags.NonPublic)!.GetValue(host)!;
                            object[] retainedLayerRows = layerRows.Items.Cast<object>().ToArray();
                            int selectedLayerIndex = layerRows.SelectedIndex;
                            OpenVisionLanguageService.SetLanguage(language, false); Pump(8);
                            if (!retainedLayerRows.SequenceEqual(layerRows.Items.Cast<object>()) || layerRows.SelectedIndex != selectedLayerIndex) throw new InvalidOperationException("Layer locale refresh replaced row identity or changed selection.");
                            object activeLayerRow = layerRows.Items.Cast<object>().Single(row => (bool)row.GetType().GetProperty("IsActive")!.GetValue(row)!);
                            if ((string)activeLayerRow.GetType().GetProperty("StatusText")!.GetValue(activeLayerRow)! != (language == OpenVisionLanguage.English ? "display" : "표시")) throw new InvalidOperationException("Main layer active label did not update locale.");
                            foreach (string id in new[] { "MainImagePrevious", "MainImagePosition", "MainImageNext", "MainImagesRemove", "MainImagesThumbnails", "MainImagesList" })
                            {
                                FrameworkElement element = FindVisualChildren<FrameworkElement>(host).FirstOrDefault(item => System.Windows.Automation.AutomationProperties.GetAutomationId(item) == id)
                                    ?? throw new InvalidOperationException("Main image control missing: " + id);
                                Rect windowBounds = new(new Point(), host.RenderSize);
                                if (!element.IsVisible || !windowBounds.Contains(new Rect(element.TranslatePoint(new Point(), host), element.RenderSize)))
                                    throw new InvalidOperationException(id + " is hidden or clipped.");
                            }
                            ToggleButton single = FindNamedVisualChild<ToggleButton>(host, "btnMainViewerSingle")!;
                            TextBlock caption = FindVisualChildren<TextBlock>(single).Single();
                            if (caption.IsVisible != host.Workbench.ShowViewerFitCaption || (caption.IsVisible && caption.ActualWidth == 0)) throw new InvalidOperationException("Preset caption visibility is incorrect.");
                            AssertBrushContrast(caption.Foreground, (Brush)host.FindResource("OpenVision.Workbench.PanelBrush"), "Main preset caption");
                            if (!FindVisualChildren<Border>(host).Any(item => item.DataContext is OpenVisionWorkbenchImageItem image && image.IsCurrent && item.IsVisible))
                                throw new InvalidOperationException("Current thumbnail is missing.");
                            string capture = Path.Combine(directory, $"images-{paletteName}-{(int)size.Width}-{language}.png");
                            ScreenshotPngWriter.WriteElementPng(host, capture, (int)size.Width, (int)size.Height);
                            cases.Add(new { Palette = paletteName, Size = size, Language = language.ToString(), Count = images.Count, Current = images.PositionText, Capture = capture });
                        }
                    }
                }
                finally { host.Resources.MergedDictionaries.Remove(palette); Pump(3); }
            }
            images.ListModeCommand.Execute(null); Pump(6);
            ScreenshotPngWriter.WriteElementPng(host, Path.Combine(directory, "images-list.png"), 1280, 760);
            if (!images.IsListMode || !FindVisualChildren<TextBlock>(host).Any(item => item.IsVisible && item.Text == names[1]))
                throw new InvalidOperationException("List mode lost the file name.");
            images.ThumbnailModeCommand.Execute(null); images.SelectImageCommand.Execute(images.Images[0]); Pump(4);
            OpenVisionShellHostCommandController listLoader = (OpenVisionShellHostCommandController)typeof(OpenVisionShellHostView).GetField("commandController", BindingFlags.Instance | BindingFlags.NonPublic)!.GetValue(host)!;
            using (Bitmap appended = new(233, 111)) { using Graphics g = Graphics.FromImage(appended); g.Clear(DrawingColor.Purple); appended.Save(Path.Combine(directory, "Main_D_added.png"), ImageFormat.Png); }
            if (listLoader.AddWorkspaceImages(new[] { Path.Combine(directory, "Main_D_added.png") }) != 1 || images.PositionText != "1 / 4" || host.Workbench.Shell.WorkspaceInputName != names[0] || host.NativePreviewRunCount != runs) throw new InvalidOperationException("Appending images replaced current input or executed inspection.");
            images.SelectImageCommand.Execute(Tuple.Create((object)images.Images[3], true, false)); images.RemoveCommand.Execute(null); Pump(3);
            if (images.PositionText != "1 / 3") throw new InvalidOperationException("Normal selection did not update current input.");
            images.SelectImageCommand.Execute(Tuple.Create((object)images.Images[2], true, false)); images.RemoveCommand.Execute(null); Pump(4);
            if (images.Count != 2 || images.PositionText != "1 / 2" || !File.Exists(Path.Combine(directory, names[2]))) throw new InvalidOperationException("Non-current removal changed input or deleted a file.");
            images.SelectAllCommand.Execute(null); images.RemoveCommand.Execute(null); Pump(8);
            if (images.Count != 0 || host.Workbench.Shell.HasWorkspaceInputImage || images.PositionText != "0 / 0") throw new InvalidOperationException("Removing all did not restore empty Main state/readiness.");
            if (!host.LoadMainImageFromFileForTest(Path.Combine(directory, names[1]))) throw new InvalidOperationException("Valid recovery failed.");
            if (images.Count != 1 || images.PreviousCommand.CanExecute(null) || images.NextCommand.CanExecute(null) || host.NativePreviewRunCount != runs)
                throw new InvalidOperationException("Recovery/navigation caused execution or a stale list.");
            if (images.Images.Any(item => Math.Max(item.Preview.PixelWidth, item.Preview.PixelHeight) > 160 || !item.Preview.IsFrozen))
                throw new InvalidOperationException("Image list retains a large/mutable current preview.");
            using (Bitmap changed = new(777, 333))
            {
                using Graphics changedGraphics = Graphics.FromImage(changed); changedGraphics.Clear(DrawingColor.Yellow);
                changed.Save(Path.Combine(directory, names[0]), ImageFormat.Png);
            }
            if (!host.LoadMainImageFromFileForTest(Path.Combine(directory, names[0]))) throw new InvalidOperationException("Replacement setup failed.");
            images.SelectImageCommand.Execute(images.Images[0]); images.NextCommand.Execute(null); Pump(5);
            if (host.Workbench.Shell.WorkspaceInputSizeText != "777×333" || images.Images[1].Preview.PixelWidth > 160)
                throw new InvalidOperationException("Revisiting a changed file kept stale source dimensions or a large thumbnail.");
            if (host.NativePreviewRunCount != runs) throw new InvalidOperationException("Changed-file reload executed inspection.");
            OpenVisionLanguageService.SetLanguage(initial, false); Pump(4);
            File.WriteAllText(Path.ChangeExtension(outputPath, ".images-cases.json"), JsonSerializer.Serialize(cases, new JsonSerializerOptions { WriteIndented = true }));
        });
    }

    private static CaptureResult CaptureMainPaneResize(string outputPath, int width, int height)
    {
        OpenVisionShellHostView host = CreateShellHost("Smoke_MainPaneResize", false);
        List<object> cases = new();
        return CaptureWindowWithContent(host, outputPath, width, height, () =>
        {
            Window window = Window.GetWindow(host);
            OpenVisionWorkbenchViewerViewModel model = host.Workbench.Viewer;
            OpenVisionLab.Docking.Controls.OpenVisionLayerDockWorkspaceView workspace = FindVisualChildren<OpenVisionLab.Docking.Controls.OpenVisionLayerDockWorkspaceView>(host).Single();
            int runs = host.NativePreviewRunCount, layers = host.LayerDocumentCount;
            string route = host.WorkspaceLayerTitle;
            foreach (int count in new[] { 2, 4 })
            {
                (count == 2 ? model.Split2Command : model.Split4Command).Execute(null); Pump(8);
                foreach (Size size in new[] { new Size(1280, 760), new Size(1920, 1032), new Size(1280, 760) })
                {
                    window.Width = size.Width; window.Height = size.Height; Pump(12);
                    OpenVisionLab.Docking.Controls.OpenVisionDockingVisualSnapshot snapshot = workspace.CreateVisualSnapshot();
                    Rect viewport = new(new Point(), snapshot.WorkspaceSize);
                    string capture = Path.Combine(Path.GetDirectoryName(outputPath)!, $"resize-{count}-{cases.Count}.png");
                    ScreenshotPngWriter.WriteElementPng(host, capture, (int)size.Width, (int)size.Height);
                    if (snapshot.Panes.Count != count || snapshot.Panes.Any(pane => !viewport.Contains(pane.Bounds)))
                        throw new InvalidOperationException("Main pane extent exceeds viewport: " + JsonSerializer.Serialize(new { count, size, snapshot.WorkspaceSize, snapshot.Panes }));
                    foreach (OpenVisionLayerViewerView view in FindVisualChildren<OpenVisionLayerViewerView>(host).Where(item => item.MainPane != null && item.IsVisible))
                    {
                        Rect bounds = new(new Point(), view.RenderSize);
                        foreach (string name in new[] { "mainPaneSource", "mainPanePin", "mainPaneMenu", "mainPaneFooter" })
                        {
                            FrameworkElement element = FindNamedVisualChild<FrameworkElement>(view, name)!;
                            Rect childBounds = new(element.TranslatePoint(new Point(), view), element.RenderSize);
                            if (!bounds.Contains(childBounds)) throw new InvalidOperationException(name + " is clipped by Main pane bounds.");
                        }
                    }
                    cases.Add(new { Count = count, Size = size, Viewport = snapshot.WorkspaceSize, Bounds = snapshot.Panes.Select(pane => pane.Bounds), Capture = capture });
                }
            }
            OpenVisionLab.Docking.Controls.OpenVisionDockWorkspaceController legacy = new(workspace.WorkspaceHandle, (sender, args) => { }, content => content is OpenVisionLayerViewerView);
            legacy.NormalizeComparisonPaneSizes();
            foreach (OpenVisionLab.Docking.Controls.OpenVisionDockPaneHandle pane in legacy.EnumeratePaneHandles())
            {
                object native = pane.NativePane;
                if ((double)native.GetType().GetProperty("DockMinWidth")!.GetValue(native)! < 280D || (double)native.GetType().GetProperty("DockMinHeight")!.GetValue(native)! < 180D)
                    throw new InvalidOperationException("Existing three-argument comparison constructor changed its 280x180 default minimum.");
            }
            model.SingleCommand.Execute(null); model.Split4Command.Execute(null); Pump(8);
            if (host.NativePreviewRunCount != runs || host.LayerDocumentCount != layers || host.WorkspaceLayerTitle != route) throw new InvalidOperationException("Resize changed execution/layer/routing state.");
            File.WriteAllText(Path.ChangeExtension(outputPath, ".resize-cases.json"), JsonSerializer.Serialize(cases, new JsonSerializerOptions { WriteIndented = true }));
        });
    }

    private static CaptureResult CaptureMainFinalShortReason(string outputPath)
    {
        string recipe = "Smoke_Final_Short_" + Guid.NewGuid().ToString("N");
