        using (Bitmap image = new(320, 240)) { using Graphics graphics = Graphics.FromImage(image); graphics.Clear(DrawingColor.FromArgb(128, 128, 128)); image.Save(input, ImageFormat.Bmp); }
        List<object> cases = new();
