                OpenVisionImageViewport afterScroll = controller.CaptureViewport()!.Value;
                File.WriteAllText(Path.ChangeExtension(outputPath, "." + theme + ".wheel-diagnostic.json"), JsonSerializer.Serialize(new { wheel.Handled, reason.IsLoaded, reason.IsVisible, HasVisualParent = VisualTreeHelper.GetParent(reason) != null, scroll.VerticalOffset, scroll.ScrollableHeight, Before = beforeScroll, After = afterScroll }, new JsonSerializerOptions { WriteIndented = true }));
                if (!wheel.Handled || scroll.VerticalOffset <= 0 || beforeScroll != afterScroll) throw new InvalidOperationException("Child reason wheel must scroll, not zoom/pan linked image.");
                foreach (MouseButton button in new[] { MouseButton.Left, MouseButton.Middle })
                {
                    MouseButtonEventArgs down = new(Mouse.PrimaryDevice, Environment.TickCount, button) { RoutedEvent = UIElement.MouseDownEvent, Source = reason };
                    typeof(MouseButtonEventArgs).GetProperty(nameof(MouseButtonEventArgs.ClickCount))!.SetValue(down, 2);
                    reason.RaiseEvent(down); Pump(2);
                    if ((bool)typeof(OpenVisionZoomableImageController).GetField("isPanning", BindingFlags.Instance | BindingFlags.NonPublic)!.GetValue(controller)! || surface.IsMouseCaptured || controller.CaptureViewport()!.Value != afterScroll) throw new InvalidOperationException("Reason mouse/doubleclick must not start canvas pan/reset.");
                }
