                if (Math.Abs(scroll.VerticalOffset - scroll.ScrollableHeight) > 1) throw new InvalidOperationException("Reason last line must be reachable.");
                Color ink = ((SolidColorBrush)reason.Foreground).Color;
                Rect windowViewport = scroll.TransformToAncestor(host).TransformBounds(new Rect(0, 0, scroll.ActualWidth, scroll.ActualHeight));
                Rect visibleViewport = windowViewport;
                Rect hostFooter = footer.TransformToAncestor(host).TransformBounds(new Rect(0, 0, footer.ActualWidth, footer.ActualHeight));
                Rect visibleFooter = hostFooter;
                List<object> ancestorClips = new();
                for (DependencyObject ancestor = VisualTreeHelper.GetParent(scroll); ancestor != null; ancestor = VisualTreeHelper.GetParent(ancestor))
                {
                    if (ancestor is FrameworkElement element && (element.ClipToBounds || element.Clip != null))
                    {
                        Rect localClip = element.Clip?.Bounds ?? new Rect(0, 0, element.ActualWidth, element.ActualHeight);
                        Rect hostClip = element.TransformToAncestor(host).TransformBounds(localClip);
                        visibleViewport.Intersect(hostClip);
                        visibleFooter.Intersect(hostClip);
                        ancestorClips.Add(new { Type = element.GetType().Name, element.Name, Bounds = hostClip.ToString(CultureInfo.InvariantCulture) });
                    }
                    if (ReferenceEquals(ancestor, host)) break;
                }
                File.WriteAllText(Path.ChangeExtension(outputPath, "." + theme + ".ancestor-clips.json"), JsonSerializer.Serialize(new { Viewport = windowViewport.ToString(CultureInfo.InvariantCulture), VisibleIntersection = visibleViewport.ToString(CultureInfo.InvariantCulture), Footer = hostFooter.ToString(CultureInfo.InvariantCulture), VisibleFooter = visibleFooter.ToString(CultureInfo.InvariantCulture), Ancestors = ancestorClips }, new JsonSerializerOptions { WriteIndented = true }));
                if (visibleFooter.IsEmpty || Math.Abs(visibleFooter.Height - hostFooter.Height) > 1 || visibleViewport.IsEmpty || Math.Abs(visibleViewport.Width - windowViewport.Width) > 1 || Math.Abs(visibleViewport.Height - windowViewport.Height) > 1) throw new InvalidOperationException("Reason viewport must remain inside every visible clipping ancestor.");
                RenderTargetBitmap bitmap = new((int)Math.Ceiling(host.ActualWidth), (int)Math.Ceiling(host.ActualHeight), 96, 96, PixelFormats.Pbgra32); bitmap.Render(host); byte[] pixels = new byte[bitmap.PixelWidth * bitmap.PixelHeight * 4]; bitmap.CopyPixels(pixels, bitmap.PixelWidth * 4, 0); int bottomInk = 0;
                for (int y = Math.Max(0, (int)windowViewport.Bottom - 18); y < Math.Min(bitmap.PixelHeight, (int)windowViewport.Bottom); y++)
                for (int x = Math.Max(0, (int)windowViewport.Left); x < Math.Min(bitmap.PixelWidth, (int)windowViewport.Right - 18); x++)
                {
                    int offset = (y * bitmap.PixelWidth + x) * 4;
                    if (Math.Abs(pixels[offset] - ink.B) < 25 && Math.Abs(pixels[offset + 1] - ink.G) < 25 && Math.Abs(pixels[offset + 2] - ink.R) < 25) bottomInk++;
                }
                File.WriteAllText(Path.ChangeExtension(outputPath, "." + theme + ".short-diagnostic.json"), JsonSerializer.Serialize(new { InitialViewportHeight = initialViewportHeight, BottomMaximum = model.BottomPanelMaximum, ViewHeight = view.ActualHeight, SurfaceHeight = surface.ActualHeight, scroll.ActualHeight, scroll.ViewportHeight, scroll.ExtentHeight, scroll.VerticalOffset, scroll.ScrollableHeight, ScrollBounds = scrollBounds.ToString(CultureInfo.InvariantCulture), FooterBounds = footerBounds.ToString(CultureInfo.InvariantCulture), HostViewport = windowViewport.ToString(CultureInfo.InvariantCulture), Ink = ink.ToString(), BottomInk = bottomInk, FullText = new TextRange(reason.ContentStart, reason.ContentEnd).Text, Expected = pane.FinalFailureRows.Single().ErrorText }, new JsonSerializerOptions { WriteIndented = true }));
                ScreenshotPngWriter.WriteDpiAwareWindowPng(Window.GetWindow(host), Path.ChangeExtension(outputPath, "." + theme + ".short-observed.png"));
                if (bottomInk == 0 || !new TextRange(reason.ContentStart, reason.ContentEnd).Text.Contains(pane.FinalFailureRows.Single().ErrorText, StringComparison.Ordinal)) throw new InvalidOperationException("End reason text must paint inside its viewport above coordinates/zoom.");
                double scale = controller.PixelZoomScale;
                imageView.RaiseEvent(new MouseWheelEventArgs(Mouse.PrimaryDevice, Environment.TickCount, 120) { RoutedEvent = UIElement.MouseWheelEvent, Source = imageView }); Pump(4);
