                imageView.RaiseEvent(new MouseButtonEventArgs(Mouse.PrimaryDevice, Environment.TickCount, MouseButton.Middle) { RoutedEvent = UIElement.MouseDownEvent, Source = imageView }); Pump(2);
                if (!(bool)typeof(OpenVisionZoomableImageController).GetField("isPanning", BindingFlags.Instance | BindingFlags.NonPublic)!.GetValue(controller)!) throw new InvalidOperationException("Valid canvas middle down must still enter pan.");
                view.PanImageByForTest(7, -9); imageView.RaiseEvent(new MouseButtonEventArgs(Mouse.PrimaryDevice, Environment.TickCount, MouseButton.Middle) { RoutedEvent = UIElement.MouseUpEvent, Source = imageView }); Pump(3);
                string capture = Path.ChangeExtension(outputPath, "." + theme + ".short.png"); ScreenshotPngWriter.WriteDpiAwareWindowPng(Window.GetWindow(host), capture);
                cases.Add(new { Theme = theme, SurfaceHeight = surface.ActualHeight, scroll.ViewportHeight, scroll.ExtentHeight, scroll.VerticalOffset, scroll.ScrollableHeight, ScrollBottom = scrollBounds.Bottom, FooterTop = footerBounds.Top, BottomInk = bottomInk, ChildWheelNoZoom = beforeScroll == afterScroll, ChildMouseNoPanReset = true, CanvasWheelPan = true, Capture = capture });
                File.WriteAllText(Path.ChangeExtension(outputPath, ".cases.json"), JsonSerializer.Serialize(cases, new JsonSerializerOptions { WriteIndented = true }));
                if (!ReferenceEquals(retained, model.Pipeline.GetResult(0)) || host.NativePreviewRunCount != runs || host.LayerDocumentCount != layers || host.WorkspaceLayerTitle != route) throw new InvalidOperationException("Short presentation input must not inspect or alter routing/layers.");
            }
            List<object> maximumCases = new();
            foreach (double height in new[] { 900D, 760D })
            {
                Window.GetWindow(host).Height = height; Pump(4);
                model.UpdateViewportCommand.Execute(new System.Windows.Size(host.ActualWidth, host.ActualHeight));
                foreach (int split in new[] { 1, 2, 4, 2, 4 })
                {
                    (split == 1 ? model.Viewer.SingleCommand : split == 2 ? model.Viewer.Split2Command : model.Viewer.Split4Command).Execute(null);
                    model.BottomPanelHeight = new GridLength(10000); Pump(6);
