    private static CaptureResult CaptureMainFinalVerdict(string outputPath)
    {
        string recipe = "Smoke_Final_Verdict_" + Guid.NewGuid().ToString("N");
        OpenVisionShellHostView host = CreateShellHost(recipe, seedMainLayer: false);
        string input = Path.ChangeExtension(outputPath, ".input.bmp");
        using (Bitmap image = new(320, 240)) { using Graphics graphics = Graphics.FromImage(image); graphics.Clear(DrawingColor.FromArgb(128, 128, 128)); image.Save(input, ImageFormat.Bmp); }
        VisionPipelineStep Mean(string name, string output, int minimum = 0) => VisionPipelineStepBuilder.FromProperty(new MeanProperty { NAME = name, USE_ROI = false, USE_THRESHOLD = false, MEAN_MIN = minimum, MEAN_MAX = 255 }, "Main", output);
        VisionPipeline intrinsic = new() { Name = "Final_Intrinsic" }; intrinsic.Steps.Add(Mean("Intrinsic Mean", "Mean_Intrinsic"));
        VisionPipeline mixed = new() { Name = "Final_Explicit_NonJudged" };
        mixed.Steps.Add(VisionPipelineStepBuilder.FromProperty(new BlobProperty { NAME = "Nonjudged Blob", USE_ROI = false, USE_THRESHOLD = true, THRESHOLD = 127, MIN_AREA = 0, MAX_AREA = 100000 }, "Main", "Blob_NonJudged"));
        VisionPipelineStep accepted = Mean("Explicit Mean", "Mean_Explicit"); accepted.UseAcceptance = true; accepted.AcceptanceMetricName = "MeanValueAvg";
        accepted.UseAcceptanceMetricMinimum = accepted.UseAcceptanceMetricMaximum = true; accepted.AcceptanceMetricMinimum = 0; accepted.AcceptanceMetricMaximum = 255; mixed.Steps.Add(accepted);
        VisionPipeline skipped = new() { Name = "Final_Skipped" }; VisionPipelineStep disabled = Mean("Disabled Mean", "Disabled_Output"); disabled.Enabled = false; skipped.Steps.Add(disabled);
        skipped.Steps.Add(VisionPipelineStepBuilder.FromThresholdProperty(new ThresholdToolProperty { Threshold = 127, MaxValue = 255 }, "Nonjudged threshold", "Main", "Skipped_Threshold"));
        VisionPipeline ng = new() { Name = "Final_NG" }; ng.Steps.Add(Mean("Mean lower 200", "Mean_NG", 200)); ng.Steps.Add(Mean("Not run downstream", "NotRun"));
        VisionPipeline longNg = new() { Name = "Final_Long_NG" }; longNg.Steps.Add(Mean(string.Concat(Enumerable.Repeat("가장 긴 판정 단계 이름과 측정 위치 ", 8)), "Mean_Long", 200));
        VisionPipeline error = new() { Name = "Final_ROI_Error" }; VisionPipelineStep roi = Mean("Mean ROI bounds", "Mean_Error"); roi.Parameters["USE_ROI"] = "True"; roi.Parameters["CvROI"] = "1000,1000,10,10"; error.Steps.Add(roi);
        foreach (VisionPipeline source in new[] { intrinsic, mixed, skipped, ng, longNg, error }) { VisionPipelineStorage.Save(recipe, source); }
        VisionPipelineStorage.SaveActivePipelineName(recipe, intrinsic.Name); host.RecipeCommands.RefreshOptions();
        List<object> cases = new();
        return CaptureWindowWithContent(host, outputPath, 1600, 900, () =>
        {
            OpenVisionLanguageService.SetLanguage(OpenVisionLanguage.Korean, false);
            Window window = Window.GetWindow(host);
            OpenVisionWorkbenchPipelineViewModel pipeline = host.Workbench.Pipeline;
            OpenVisionWorkbenchViewerViewModel viewer = host.Workbench.Viewer;
            viewer.Split4Command.Execute(null); Pump(4);
            OpenVisionWorkbenchViewerPane final = viewer.Panes[3];
            if (final.ShowFinalVerdict || final.FinalFailureRows.Count != 0 || viewer.ReadOverlays(final).Count != 0) throw new InvalidOperationException("No-result final must not claim a verdict or geometry.");
            if (!host.LoadMainImageFromFileForTest(input)) throw new InvalidOperationException("Final owned input setup failed.");
            Select(intrinsic); Execute("intrinsic");
            if (!OpenVisionWorkbenchPipelineViewModel.IsJudged(pipeline.GetStep(0)) || pipeline.GetResult(0).Metrics["MeanValueAvg"] != 128D) throw new InvalidOperationException("Intrinsic Mean128 must be actual judged.");
            AssertFinal("intrinsic", "Ok", 0);
            int retainedCount = pipeline.GetResult(0).Overlays.Count;
            pipeline.ToggleRowEnabledCommand.Execute(0); Pump(4);
            if (viewer.ReadOverlays(final).Count != 0 || final.ShowFinalVerdict || !final.IsPrevious) throw new InvalidOperationException("Disabled retained Mean must be excluded and not current OK.");
            File.WriteAllText(Path.ChangeExtension(outputPath, ".all-disabled-guard.json"), JsonSerializer.Serialize(new { RunEnabled = pipeline.RunCommand.CanExecute(null), pipeline.RunDisabledReason, pipeline.StatusText, final.ShowFinalVerdict, final.IsPrevious, SummarySkipped = pipeline.GetResult(0).Skipped, FinalGeometryCount = viewer.ReadOverlays(final).Count }));
            pipeline.ToggleRowEnabledCommand.Execute(0); Pump(3);
            if (pipeline.IsDirty) throw new InvalidOperationException("Disabled fixture must restore its saved definition before switch.");
            Select(skipped); Execute("disabled plus enabled nonjudged skip");
            File.WriteAllText(Path.ChangeExtension(outputPath, ".skipped.json"), JsonSerializer.Serialize(new { pipeline.VerdictKind, pipeline.StatusText, pipeline.RunDisabledReason, pipeline.GetResult(0).Skipped, final.ShowFinalVerdict, FinalOverlays = viewer.ReadOverlays(final).Count }));
            if (pipeline.GetResult(0).Skipped != true || final.ShowFinalVerdict || viewer.ReadOverlays(final).Count != 0) throw new InvalidOperationException("Skipped/nojudged final must have no fresh OK/NG.");
            Select(mixed); Execute("explicit/nonjudged");
            if (OpenVisionWorkbenchPipelineViewModel.IsJudged(pipeline.GetStep(0)) || pipeline.GetResult(0).Overlays.Count == 0) throw new InvalidOperationException("Nonjudged producer fixture must have real geometry to exclude.");
            AssertFinal("explicit", "Ok", 1);
            Select(ng); Execute("intrinsic NG"); AssertFinal("ng", "Ng", 0);
            if (pipeline.GetResult(1).Executed || !final.HasFinalReasons || !final.FinalFailureRows.Single().ErrorText.Contains("200.0 GV", StringComparison.Ordinal)) throw new InvalidOperationException("NG must retain existing localized reason and fail-fast downstream.");
            VisionPipelineStep edited = pipeline.GetStep(0); edited.Parameters["MEAN_MIN"] = "0";
            if (!pipeline.ReplaceStep(0, edited)) throw new InvalidOperationException("Final recovery edit failed."); Pump(4);
            if (!final.IsPrevious || final.ShowFinalVerdict || final.FinalFailureRows.Count != 0) throw new InvalidOperationException("Previous must not show old failure as fresh final.");
            Execute("valid NG recovery"); AssertFinal("ng recovery", "Ok", 0, 1); pipeline.UndoCommand.Execute(null); Pump(3);
            Select(error); Execute("ROI runtime error");
            if (pipeline.VerdictKind != "Error" || !final.ShowFinalVerdict || !final.HasFinalReasons || pipeline.GetResult(0).IsAcceptanceNg) throw new InvalidOperationException("ROI bounds failure must remain runtime Error with reason, not quality NG.");
            Capture("error");
            edited = pipeline.GetStep(0); edited.Parameters["USE_ROI"] = "False";
            if (!pipeline.ReplaceStep(0, edited)) throw new InvalidOperationException("Runtime recovery edit failed."); Execute("valid Error recovery"); AssertFinal("error recovery", "Ok", 0); pipeline.UndoCommand.Execute(null); Pump(3);
            Select(longNg); Execute("long NG");
            VisionPipelineStepResultSummary retained = pipeline.GetResult(0); byte[] working = VisionPipelineExecutionPlan.SerializePipeline(pipeline.WorkingCopyForTest);
            int runs = host.NativePreviewRunCount, layers = host.LayerDocumentCount; string route = host.WorkspaceLayerTitle;
            foreach (string theme in new[] { "Dark", "Light" })
            foreach (int width in new[] { 1600, 1280 })
            {
                (theme == "Dark" ? host.Workbench.SelectDarkThemeCommand : host.Workbench.SelectLightThemeCommand).Execute(null); window.Width = width; window.Height = width == 1600 ? 900 : 760; Pump(5);
                AssertFinal("long " + theme + width, "Ng", 0);
                OpenVisionLayerViewerView view = FindVisualChildren<OpenVisionLayerViewerView>(host).Single(item => item.MainPane?.Id == final.Id);
                Border badge = FindNamedVisualChild<Border>(view, "mainPaneFinalBadge")!;
                TextBlock verdict = FindNamedVisualChild<TextBlock>(view, "mainPaneFinalVerdictText")!;
                ScrollViewer scroll = FindNamedVisualChild<ScrollViewer>(view, "mainPaneFinalReasonsScroll")!;
                TextBlock reason = FindVisualChildren<TextBlock>(FindNamedVisualChild<ItemsControl>(view, "mainPaneFinalReasons")!).Single();
                string renderedReason = new TextRange(reason.ContentStart, reason.ContentEnd).Text;
                File.WriteAllText(Path.ChangeExtension(outputPath, "." + theme + width + ".presentation-diagnostic.json"), JsonSerializer.Serialize(new { BadgeVisible = badge.IsVisible, BadgeText = verdict.Text, ScrollVisible = scroll.IsVisible, Wrap = reason.TextWrapping.ToString(), TextProperty = reason.Text, InlineRenderedText = renderedReason, ExpectedReason = final.FinalFailureRows.Single().ErrorText }));
                if (!badge.IsVisible || verdict.Text != "NG" || !scroll.IsVisible || reason.TextWrapping != TextWrapping.Wrap || !renderedReason.Contains(final.FinalFailureRows.Single().ErrorText, StringComparison.Ordinal)) throw new InvalidOperationException("Final reason must be rendered in full, not hidden in tooltip/ellipsis.");
                SolidColorBrush background = (SolidColorBrush)badge.Background, foreground = (SolidColorBrush)verdict.Foreground;
                if (background.Color.A != 255 || GetContrastRatio(foreground.Color, background.Color) < 4.5D) throw new InvalidOperationException("Final badge composed palette unreadable.");
                AssertElementWithinAncestor("final badge", badge, view); AssertElementWithinAncestor("final reasons scroll", scroll, view);
                scroll.ScrollToBottom(); Pump(4);
                Border reasonBorder = (Border)VisualTreeHelper.GetParent(reason);
                if (((SolidColorBrush)reasonBorder.Background).Color.A != 255 || GetContrastRatio(((SolidColorBrush)reason.Foreground).Color, ((SolidColorBrush)reasonBorder.Background).Color) < 4.5D) throw new InvalidOperationException("Final reason composed palette unreadable.");
                Rect reasonViewport = scroll.TransformToAncestor(host).TransformBounds(new Rect(0, 0, scroll.ActualWidth, scroll.ActualHeight));
                RenderTargetBitmap raster = new((int)Math.Ceiling(host.ActualWidth), (int)Math.Ceiling(host.ActualHeight), 96D, 96D, PixelFormats.Pbgra32); raster.Render(host);
                byte[] pixels = new byte[raster.PixelWidth * raster.PixelHeight * 4]; raster.CopyPixels(pixels, raster.PixelWidth * 4, 0);
                Color ink = ((SolidColorBrush)reason.Foreground).Color; int visibleGlyphPixels = 0;
                for (int y = Math.Max(0, (int)reasonViewport.Top); y < Math.Min(raster.PixelHeight, (int)reasonViewport.Bottom); y++)
                for (int x = Math.Max(0, (int)reasonViewport.Left); x < Math.Min(raster.PixelWidth, (int)reasonViewport.Right - 18); x++)
                {
                    int offset = (y * raster.PixelWidth + x) * 4;
                    if (Math.Abs(pixels[offset] - ink.B) < 25 && Math.Abs(pixels[offset + 1] - ink.G) < 25 && Math.Abs(pixels[offset + 2] - ink.R) < 25) { visibleGlyphPixels++; }
                }
                if (visibleGlyphPixels == 0 || scroll.ViewportHeight <= 0 || (scroll.ScrollableHeight > 0 && Math.Abs(scroll.VerticalOffset - scroll.ScrollableHeight) > 1)) throw new InvalidOperationException("Wrapped full reason must paint inside the actual bounded viewport and reach its bottom.");
                string capture = Path.ChangeExtension(outputPath, "." + theme + "." + width + ".long.png"); ScreenshotPngWriter.WriteDpiAwareWindowPng(window, capture);
                cases.Add(new { Theme = theme, Width = width, Badge = verdict.Text, FullReason = renderedReason, scroll.ViewportHeight, scroll.ExtentHeight, scroll.VerticalOffset, scroll.ScrollableHeight, VisibleGlyphPixels = visibleGlyphPixels, Contrast = GetContrastRatio(foreground.Color, background.Color), Capture = capture });
                if (!ReferenceEquals(retained, pipeline.GetResult(0)) || host.NativePreviewRunCount != runs || host.LayerDocumentCount != layers || host.WorkspaceLayerTitle != route || !working.SequenceEqual(VisionPipelineExecutionPlan.SerializePipeline(pipeline.WorkingCopyForTest))) throw new InvalidOperationException("Final presentation must not execute or change recipe/layer/route.");
                scroll.ScrollToTop();
            }
            File.WriteAllText(Path.ChangeExtension(outputPath, ".cases.json"), JsonSerializer.Serialize(new { Cases = cases, IntrinsicEnabled = true, ExplicitNonjudged = true, DisabledRetainedSkipped = true, Previous = true, QualityNg = true, RuntimeError = true, ValidRecovery = true, NoImplicitRun = true, ProductSHA256 = Convert.ToHexString(SHA256.HashData(File.ReadAllBytes(typeof(OpenVisionShellHostView).Assembly.Location))), Scope = "in-process existing command/real execution/retained geometry/read-only binding and bounded presentation; actual EXE interaction/125DPI remain parent scope" }, new JsonSerializerOptions { WriteIndented = true }));
            void Select(VisionPipeline source) { host.RecipeCommands.SelectedPipelineOption = host.RecipeCommands.PipelineOptions.Single(option => option.PipelineName == source.Name); pipeline.SelectStepCommand.Execute(0); host.Workbench.Tool.IsAutoRunEnabled = false; Pump(4); }
            void Execute(string label) { WaitForTaskWithPump(pipeline.RunForTestAsync(), 12000, label); Pump(5); }
            void AssertFinal(string label, string kind, params int[] judgedIndexes)
            {
                VisionPipelineStepResultSummary[] summaries = judgedIndexes.Select(pipeline.GetResult).ToArray();
                VisionToolOverlay[] expected = summaries.SelectMany(summary => summary.Overlays).ToArray();
                bool geometryEqual = JsonSerializer.Serialize(viewer.ReadOverlays(final).Select(item => item.Shape)) == JsonSerializer.Serialize(expected);
                File.WriteAllText(Path.ChangeExtension(outputPath, "." + label.Replace(" ", "_") + ".diagnostic.json"), JsonSerializer.Serialize(new { Label = label, ExpectedKind = kind, pipeline.VerdictKind, pipeline.VerdictValue, final.ShowFinalVerdict, FinalGeometry = viewer.ReadOverlays(final).Count, ExpectedGeometry = expected.Length, GeometryEqual = geometryEqual, Steps = pipeline.Rows.Select(row => new { row.Index, Definition = pipeline.GetStep(row.Index).Parameters, Summary = pipeline.GetResult(row.Index) is VisionPipelineStepResultSummary result ? new { result.Executed, result.Success, result.IsAcceptanceNg, result.Skipped, result.Metrics, OverlayCount = result.Overlays.Count } : null }) }, new JsonSerializerOptions { WriteIndented = true }));
                if (pipeline.VerdictKind != kind || !final.ShowFinalVerdict || final.FinalVerdictValue != pipeline.VerdictValue || summaries.Any(summary => summary.Overlays.Count == 0) || !geometryEqual) throw new InvalidOperationException(label + ": final must display all case-defined judged retained geometry and verdict.");
                viewer.ReadImage(final, image => { if (image == null || image.GetPixel(160, 120).R != 128) throw new InvalidOperationException("Final original must remain input128, not output bitmap."); });
                Capture(label.Replace(" ", "_"));
            }
            void Capture(string label) { ScreenshotPngWriter.WriteDpiAwareWindowPng(window, Path.ChangeExtension(outputPath, "." + label + ".png")); }
        }, captureFloatingToolWindow: false);
    }

    private static CaptureResult CaptureMainPaneMarkerContrast(string outputPath)
    {
        string recipe = "Smoke_Viewer_Markers_" + Guid.NewGuid().ToString("N");
        OpenVisionShellHostView host = CreateShellHost(recipe, seedMainLayer: false);
        VisionPipeline source = new() { Name = "Viewer_Markers" };
        source.Steps.Add(VisionPipelineStepBuilder.FromThresholdProperty(new ThresholdToolProperty { Threshold = 127, MaxValue = 255 }, "Binary127", "Main", "Binary_Result"));
        VisionPipelineStorage.Save(recipe, source); VisionPipelineStorage.SaveActivePipelineName(recipe, source.Name);
        host.RecipeCommands.RefreshOptions(); host.RecipeCommands.SelectedPipelineOption = host.RecipeCommands.PipelineOptions.Single(option => option.PipelineName == source.Name);
        string input = Path.ChangeExtension(outputPath, ".input.bmp");
        using (Bitmap image = new(320, 240)) { using Graphics graphics = Graphics.FromImage(image); graphics.Clear(DrawingColor.FromArgb(128, 128, 128)); image.Save(input, ImageFormat.Bmp); }
        List<object> cases = new();
        return CaptureWindowWithContent(host, outputPath, 1600, 900, () =>
        {
            Window window = Window.GetWindow(host);
            OpenVisionWorkbenchPipelineViewModel pipeline = host.Workbench.Pipeline;
            OpenVisionWorkbenchViewerViewModel viewer = host.Workbench.Viewer;
            pipeline.SelectStepCommand.Execute(0); host.Workbench.Tool.IsAutoRunEnabled = false;
            if (!host.LoadMainImageFromFileForTest(input)) throw new InvalidOperationException("Marker input setup failed.");
            WaitForTaskWithPump(pipeline.RunForTestAsync(), 12000, "marker result"); Pump(5);
            viewer.Panes[0].Source = "layer:Binary_Result"; viewer.Panes[0].SnapshotCommand.Execute(null);
            viewer.Panes[1].Source = "layer:Binary_Result"; pipeline.InvalidateToolResult(0); Pump(5);
            VisionPipelineStepResultSummary retained = pipeline.GetResult(0);
            foreach (string theme in new[] { "Dark", "Light" })
            foreach (int width in new[] { 1600, 1280 })
            {
                (theme == "Dark" ? host.Workbench.SelectDarkThemeCommand : host.Workbench.SelectLightThemeCommand).Execute(null);
                window.Width = width; window.Height = width == 1600 ? 900 : 760; Pump(5);
                foreach (string name in new[] { "mainPaneSnapshotMarker", "mainPanePreviousMarker" })
                {
                    Border marker = FindVisualChildren<Border>(host).Single(border => border.Name == name && border.IsVisible);
                    TextBlock text = FindVisualChildren<TextBlock>(marker).Single();
                    SolidColorBrush foreground = (SolidColorBrush)text.Foreground, background = (SolidColorBrush)marker.Background;
                    AssertElementWithinAncestor(name, marker, FindVisualChildren<OpenVisionLayerViewerView>(host).Single(view => view.IsAncestorOf(marker)));
                    foreach (Color underlay in new[] { Colors.Black, Colors.White })
                    {
                        int pixelWidth = (int)Math.Ceiling(marker.ActualWidth), pixelHeight = (int)Math.Ceiling(marker.ActualHeight);
                        DrawingVisual surface = new();
                        using (DrawingContext context = surface.RenderOpen()) { context.DrawRectangle(new SolidColorBrush(underlay), null, new Rect(0, 0, pixelWidth, pixelHeight)); }
                        RenderTargetBitmap pixels = new(pixelWidth, pixelHeight, 96D, 96D, PixelFormats.Pbgra32);
                        pixels.Render(surface); pixels.Render(marker);
                        byte[] rgba = new byte[pixelWidth * pixelHeight * 4]; pixels.CopyPixels(rgba, pixelWidth * 4, 0);
                        int offset = ((pixelHeight / 2) * pixelWidth + 3) * 4;
                        Color renderedBackground = Color.FromArgb(rgba[offset + 3], rgba[offset + 2], rgba[offset + 1], rgba[offset]);
                        double contrast = GetContrastRatio(foreground.Color, renderedBackground);
                        int glyphPixels = 0;
                        for (int y = 3; y < pixelHeight - 3; y++)
                        for (int x = 7; x < pixelWidth - 7; x++)
                        {
                            int i = (y * pixelWidth + x) * 4;
                            if (Math.Abs(rgba[i] - foreground.Color.B) < 25 && Math.Abs(rgba[i + 1] - foreground.Color.G) < 25 && Math.Abs(rgba[i + 2] - foreground.Color.R) < 25) { glyphPixels++; }
                        }
                        string capture = Path.ChangeExtension(outputPath, "." + theme + "." + width + "." + name + "." + (underlay == Colors.White ? "white" : "black") + ".png");
                        using (FileStream stream = File.Create(capture)) { PngBitmapEncoder encoder = new(); encoder.Frames.Add(BitmapFrame.Create(pixels)); encoder.Save(stream); }
                        cases.Add(new { Theme = theme, Width = width, Marker = name, text.Text, Foreground = foreground.Color.ToString(), DeclaredBackground = background.Color.ToString(), Underlay = underlay.ToString(), RenderedBackground = renderedBackground.ToString(), Contrast = contrast, GlyphPixels = glyphPixels, Capture = capture });
                        File.WriteAllText(Path.ChangeExtension(outputPath, ".cases.json"), JsonSerializer.Serialize(cases, new JsonSerializerOptions { WriteIndented = true }));
                        if (contrast < 4.5D || background.Color.A != 255 || renderedBackground != background.Color || glyphPixels == 0)
                            throw new InvalidOperationException(name + " composed marker must have readable text on opaque semantic background; contrast=" + contrast + ", glyphs=" + glyphPixels);
                    }
                }
                ScreenshotPngWriter.WriteDpiAwareWindowPng(window, Path.ChangeExtension(outputPath, "." + theme + "." + width + ".context.png"));
                if (!ReferenceEquals(retained, pipeline.GetResult(0)) || host.NativePreviewRunCount != 0) throw new InvalidOperationException("Marker presentation must not execute.");
            }
        }, captureFloatingToolWindow: false);
    }

    private static CaptureResult CaptureMainPaneSourceWorkflow(string outputPath)
    {
        string recipe = "Smoke_Viewer_Source_" + Guid.NewGuid().ToString("N");
        OpenVisionShellHostView host = CreateShellHost(recipe, seedMainLayer: false);
        VisionPipeline source = new() { Name = "Viewer_Source" };
        source.Steps.Add(VisionPipelineStepBuilder.FromThresholdProperty(new ThresholdToolProperty { Threshold = 127, MaxValue = 255 }, "Binary127", "Main", "Binary_Result"));
        source.Steps.Add(VisionPipelineStepBuilder.FromProperty(new MeanProperty { NAME = "Brightness", USE_ROI = false, USE_THRESHOLD = false, MEAN_MIN = 0, MEAN_MAX = 255 }, "Binary_Result", "Brightness_Result"));
        VisionPipelineStorage.Save(recipe, source); VisionPipelineStorage.SaveActivePipelineName(recipe, source.Name);
        host.RecipeCommands.RefreshOptions(); host.RecipeCommands.SelectedPipelineOption = host.RecipeCommands.PipelineOptions.Single(option => option.PipelineName == source.Name);
        string directory = Path.GetDirectoryName(outputPath)!;
        string Input(int value)
        {
            string path = Path.Combine(directory, "viewer_input_" + value + ".bmp");
            using Bitmap image = new(320, 240); using Graphics graphics = Graphics.FromImage(image);
            graphics.Clear(DrawingColor.FromArgb(value, value, value)); image.Save(path, ImageFormat.Bmp); return path;
        }
        string inputA = Input(128), inputB = Input(64);
        List<object> cases = new();
        return CaptureWindowWithContent(host, outputPath, 1600, 900, () =>
        {
            OpenVisionWorkbenchPipelineViewModel pipeline = host.Workbench.Pipeline;
            OpenVisionWorkbenchViewerViewModel viewer = host.Workbench.Viewer;
            pipeline.SelectStepCommand.Execute(0); host.Workbench.Tool.IsAutoRunEnabled = false;
            if (!host.LoadMainImageFromFileForTest(inputA)) throw new InvalidOperationException("Viewer owned input A failed.");
            Pump(5);
            OpenVisionWorkbenchViewerPane output = viewer.Panes[1];
            if (!output.ShowRunToAction || !output.RunToSourceCommand.CanExecute(null)) throw new InvalidOperationException("Unproduced named output needs explicit RunTo.");
            Button runTo = FindVisualChildren<Button>(host).Single(button => AutomationProperties.GetAutomationId(button) == "MainPaneRunToSource" && button.IsVisible);
            if (!ReferenceEquals(runTo.Command, output.RunToSourceCommand)) throw new InvalidOperationException("Empty action command binding differs.");
            runTo.Command.Execute(null);
            Stopwatch timer = Stopwatch.StartNew(); while (pipeline.IsRunning && timer.ElapsedMilliseconds < 12000) { Pump(1); }
            WaitForTaskWithPump(pipeline.RunForTestAsync(), 12000, "viewer full A"); Pump(5);
            AssertPixel(output, 255);
            int openLayers = host.LayerDocumentCount, openRuns = host.NativePreviewRunCount; string openRoute = host.WorkspaceLayerTitle;
            byte[] openWorking = VisionPipelineExecutionPlan.SerializePipeline(pipeline.WorkingCopyForTest);
            int sourceChoices = viewer.SourceOptions.Count;
            viewer.Panes[0].OpenCommand.Execute(null); Pump(6);
            OpenVisionFloatingToolWindow liveWindow = Application.Current.Windows.OfType<OpenVisionFloatingToolWindow>().Single(item => item.IsVisible && item.HostedContent is OpenVisionLayerViewerView);
            if (!liveWindow.IsDockButtonVisible || ((OpenVisionLayerViewerView)liveWindow.HostedContent).Tag as string != "Main") throw new InvalidOperationException("Existing store-layer popout must retain live docking contract.");
            liveWindow.Close(); Pump(4);
            if (host.HasLayerForTest("Binary_Result")) throw new InvalidOperationException("Cache-only popout fixture unexpectedly published a store layer.");
            viewer.SetResultObjects("Binary_Result", new[] { new VisionToolOverlay { Kind = VisionToolOverlayKind.Rectangle, Bounds = new DrawingRectangleF(30, 40, 60, 70), Label = "Retained rectangle" } }, null, false);
            output.OpenCommand.Execute(null); Pump(8);
            OpenVisionFloatingToolWindow cacheWindow = Application.Current.Windows.OfType<OpenVisionFloatingToolWindow>().Single(item => item.IsVisible && item.HostedContent is OpenVisionLayerViewerView);
            OpenVisionLayerViewerView cacheView = (OpenVisionLayerViewerView)cacheWindow.HostedContent;
            if (cacheWindow.IsDockButtonVisible || cacheWindow.Owner != Window.GetWindow(host) || cacheView.Tag != null || cacheView.DisplayOverlayVisualCountForTest == 0 || host.OpenLayerViewerWindowCount != 1) throw new InvalidOperationException("Cache popout needs existing owner, read-only copied image and overlays.");
            using (Bitmap copied = cacheView.CloneImageForTest()) { if (copied.Width != 320 || copied.Height != 240 || copied.GetPixel(160, 120).R != 255) throw new InvalidOperationException("Cache popup pixels differ from the independently specified Threshold127 result."); }
            viewer.SetResultObjects(null, Array.Empty<VisionToolOverlay>(), null, false);
            if (host.HasLayerForTest("Binary_Result") || openLayers != host.LayerDocumentCount || openRuns != host.NativePreviewRunCount || openRoute != host.WorkspaceLayerTitle || sourceChoices != viewer.SourceOptions.Count || !openWorking.SequenceEqual(VisionPipelineExecutionPlan.SerializePipeline(pipeline.WorkingCopyForTest))) throw new InvalidOperationException("Cache popout must not publish layers, create snapshot catalog entries, run or edit recipe/route.");
            cases.Add(new { Case = "store-live-and-cache-readonly-popouts", StoreDocking = true, CacheOnly = true, CopiedPixel = 255, CopiedOverlay = true, NoMutation = true });
            VisionPipelineStepResultSummary producedBinary = pipeline.GetResult(0), producedMean = pipeline.GetResult(1);
            pipeline.SelectStepCommand.Execute(1); Pump(4);
            OpenVisionWorkbenchViewerPane fixedPane = viewer.Panes[0]; fixedPane.PinCommand.Execute(null); Pump(4);
            if (fixedPane.Source != "layer:Binary_Result") throw new InvalidOperationException("Pin must keep the resolved live name.");
            AssertPixel(fixedPane, 255);
            output.SnapshotCommand.Execute(null); Pump(4);
            string frozenHash = Hash(output); string frozenTitle = output.Title;
            string overlays = JsonSerializer.Serialize(output.Overlays);
            pipeline.SelectStepCommand.Execute(0); Pump(4);
            VisionPipelineStep edited = pipeline.GetStep(0); edited.Parameters["Threshold"] = "190";
            if (!pipeline.ReplaceStep(0, edited)) throw new InvalidOperationException("Owned edit failed.");
            Pump(5);
            if (!fixedPane.IsPrevious || output.IsPrevious || !output.IsSnapshot) throw new InvalidOperationException("Live previous and snapshot states differ.");
            fixedPane.SnapshotCommand.Execute(null); Pump(4);
            if (!fixedPane.Title.Contains("127", StringComparison.Ordinal) || fixedPane.Title.Contains("190", StringComparison.Ordinal)) throw new InvalidOperationException("Snapshot hint must describe executed parameters, not edited values.");
            string thresholdSnapshot = fixedPane.Source;
            foreach (string theme in new[] { "Dark", "Light" })
            {
                (theme == "Dark" ? host.Workbench.SelectDarkThemeCommand : host.Workbench.SelectLightThemeCommand).Execute(null); Pump(4);
                Border marker = FindVisualChildren<Border>(host).First(border => border.Name == "mainPaneSnapshotMarker" && border.IsVisible);
                if (marker.ActualWidth <= 0) throw new InvalidOperationException("Snapshot marker not rendered.");
                viewer.SingleCommand.Execute(null); viewer.Panes[0].Source = thresholdSnapshot; Pump(4);
                TextBlock dimensions = FindVisualChildren<TextBlock>(host).First(text => text.IsVisible && text.Text == "320×240");
                if (dimensions.ActualWidth <= 0) throw new InvalidOperationException("Wide single pane dimensions not rendered.");
                string capture = Path.ChangeExtension(outputPath, "." + theme + ".snapshot.png");
                ScreenshotPngWriter.WriteDpiAwareWindowPng(Window.GetWindow(host), capture);
                cases.Add(new { Theme = theme, Title = fixedPane.Title, SnapshotMarker = marker.IsVisible, Dimensions = dimensions.Text, Capture = capture });
                viewer.Split2Command.Execute(null); Pump(4);
            }
            fixedPane.Source = "layer:Binary_Result"; Pump(4);
            Border previousMarker = FindVisualChildren<Border>(host).First(border => border.Name == "mainPanePreviousMarker" && border.IsVisible);
            if (!previousMarker.IsVisible) throw new InvalidOperationException("Previous result marker not rendered.");
            byte[] working = VisionPipelineExecutionPlan.SerializePipeline(pipeline.WorkingCopyForTest);
            int runs = host.NativePreviewRunCount, layers = host.LayerDocumentCount; string route = host.WorkspaceLayerTitle;
            viewer.Split4Command.Execute(null); viewer.SingleCommand.Execute(null); viewer.Split2Command.Execute(null); Pump(5);
            if (!ReferenceEquals(producedBinary, pipeline.GetResult(0)) || !ReferenceEquals(producedMean, pipeline.GetResult(1)) || !working.SequenceEqual(VisionPipelineExecutionPlan.SerializePipeline(pipeline.WorkingCopyForTest)) || runs != host.NativePreviewRunCount || layers != host.LayerDocumentCount || route != host.WorkspaceLayerTitle)
                throw new InvalidOperationException("Display choices must not run, replace retained execution results, change routes, layers or recipe.");
            if (!host.LoadMainImageFromFileForTest(inputB)) throw new InvalidOperationException("Viewer owned input B failed.");
            WaitForTaskWithPump(pipeline.RunForTestAsync(), 12000, "viewer full B"); Pump(5);
            AssertPixel(fixedPane, 0);
            using (Bitmap copied = cacheView.CloneImageForTest()) { if (!cacheWindow.IsVisible || copied.GetPixel(160, 120).R != 255 || cacheView.DisplayOverlayVisualCountForTest == 0) throw new InvalidOperationException("Cache popup clone/overlay must survive later result replacement."); }
            string cacheCapture = Path.ChangeExtension(outputPath, ".cache-popup.png"); ScreenshotPngWriter.WriteElementPng(cacheWindow, cacheCapture, 820, 600);
            cacheWindow.Close(); Pump(4); if (host.OpenLayerViewerWindowCount != 0) throw new InvalidOperationException("Cache popup close must release the existing registry entry.");
            cases.Add(new { Case = "cache-popout-after-reexecute-close", PreservedPixel = 255, CurrentPixel = 0, Released = true, Capture = cacheCapture });
            if (fixedPane.IsPrevious || Hash(output) != frozenHash || output.Title != frozenTitle || JsonSerializer.Serialize(output.Overlays) != overlays)
                throw new InvalidOperationException("Live pin must refresh while snapshot pixels/overlays/name remain frozen.");
            output.Source = thresholdSnapshot; Pump(3); AssertPixel(output, 255);
            viewer.ClearSnapshotsCommand.Execute(null); Pump(5);
            if (viewer.Panes.Any(pane => pane.Source.StartsWith("snap:", StringComparison.Ordinal)) || viewer.ClearSnapshotsCommand.CanExecute(null)) throw new InvalidOperationException("Snapshot clear must restore defaults and release store.");
            File.WriteAllText(Path.ChangeExtension(outputPath, ".cases.json"), JsonSerializer.Serialize(new { Cases = cases, FrozenHash = frozenHash, FrozenTitle = frozenTitle, ExecutedHint127 = true, PinLiveRefresh0 = true, SnapshotPixels255 = true, SnapshotOverlayFrozen = true, ClearRecovery = true, NoImplicitRun = true, ProductSHA256 = Convert.ToHexString(SHA256.HashData(File.ReadAllBytes(typeof(OpenVisionShellHostView).Assembly.Location))), Scope = "in-process commands/real execution/retained pixels and rendered bindings; native interactions/DPI remain separate" }, new JsonSerializerOptions { WriteIndented = true }));
        }, captureFloatingToolWindow: false);
        string Hash(OpenVisionWorkbenchViewerPane pane)
        {
            string hash = null; viewerRead(pane, image => hash = image == null ? null : VisionPipelineScaleCalibrationStorage.ComputeBitmapSha256(image)); return hash;
        }
        void AssertPixel(OpenVisionWorkbenchViewerPane pane, int expected)
        {
            viewerRead(pane, image => { if (image == null || image.Width != 320 || image.Height != 240 || image.GetPixel(160, 120).R != expected) throw new InvalidOperationException("Independent threshold pixel expected " + expected); });
        }
        void viewerRead(OpenVisionWorkbenchViewerPane pane, Action<Bitmap> read) => host.Workbench.Viewer.ReadImage(pane, read);
    }

    private static CaptureResult CaptureMainPaneSync(string outputPath, int width, int height)
    {
        OpenVisionShellHostView host = CreateShellHost("Smoke_MainPaneSync", false);
        string directory = Path.GetDirectoryName(outputPath)!;
        string inputPath = Path.Combine(directory, "Main_sync_owned_640x360.png");
        using (Bitmap image = new(640, 360)) { using Graphics graphics = Graphics.FromImage(image); graphics.Clear(DrawingColor.Teal); image.Save(inputPath, ImageFormat.Png); }
        List<object> cases = new();
        return CaptureWindowWithContent(host, outputPath, width, height, () =>
        {
            if (!host.LoadMainImageFromFileForTest(inputPath)) throw new InvalidOperationException("Sync input setup failed.");
            OpenVisionWorkbenchViewerViewModel model = host.Workbench.Viewer;
            model.Panes[1].Source = "layer:Main"; Pump(8);
            OpenVisionLayerViewerView[] views = model.Panes.Select(pane => FindVisualChildren<OpenVisionLayerViewerView>(host).Single(item => item.MainPane?.Id == pane.Id)).ToArray();
            int runs = host.NativePreviewRunCount, layers = host.LayerDocumentCount;
            string route = host.WorkspaceLayerTitle;
            byte[] working = VisionPipelineExecutionPlan.SerializePipeline(host.Workbench.Pipeline.WorkingCopyForTest);
            OpenVisionLanguage initial = OpenVisionLanguageService.CurrentLanguage;
            foreach (string paletteName in new[] { "Dark", "Light" })
            {
                ResourceDictionary palette = new() { Source = new Uri($"/OpenVisionLab;component/UI/Wpf/OpenVisionWorkbench{paletteName}.xaml", UriKind.Relative) };
                host.Resources.MergedDictionaries.Add(palette);
                try
                {
                    foreach (OpenVisionLanguage language in new[] { OpenVisionLanguage.Korean, OpenVisionLanguage.English })
                    {
                        OpenVisionLanguageService.SetLanguage(language, false); Pump(4);
                        model.IsSyncEnabled = true; views[0].ShowOriginalSize(); views[0].ZoomImage(2D); views[0].PanImageByForTest(29D, -17D); Pump(8);
                        OpenVisionImageViewport first = views[0].ViewportForTest!.Value, second = views[1].ViewportForTest!.Value;
                        AssertViewport("synchronized", second, first);
                        if (Math.Abs(first.Scale - 2D) > 0.000001D || first.Fit) throw new InvalidOperationException("Sync reset a requested 200% view.");
                        model.IsSyncEnabled = false; views[1].ZoomImage(1.5D); views[1].PanImageByForTest(-11D, 13D); Pump(8);
                        AssertViewport("independent", views[0].ViewportForTest!.Value, first);
                        if (Math.Abs(views[1].ViewportForTest!.Value.Scale - 3D) > 0.000001D) throw new InvalidOperationException("Independent pane zoom failed.");
                        model.Activate(model.Panes[1].Id); model.ToggleSyncCommand.Execute(null); Pump(8);
                        AssertViewport("enable from active", views[0].ViewportForTest!.Value, views[1].ViewportForTest!.Value);
                        views[0].FitImageToView(); Pump(8);
                        if (views.Any(view => !view.ViewportForTest!.Value.Fit)) throw new InvalidOperationException("Fit recovery did not reach the linked panes.");
                        model.Activate(model.Panes[0].Id); Pump(4);
                        Border firstFrame = FindNamedVisualChild<Border>(views[0], "layerViewerFrame")!, secondFrame = FindNamedVisualChild<Border>(views[1], "layerViewerFrame")!;
                        if (((SolidColorBrush)firstFrame.BorderBrush).Color != ((SolidColorBrush)host.FindResource("OpenVision.Workbench.AccentBrush")).Color
                            || ((SolidColorBrush)secondFrame.BorderBrush).Color != ((SolidColorBrush)host.FindResource("OpenVision.Workbench.LineBrush")).Color)
                            throw new InvalidOperationException("Active and inactive Main frame colors do not follow the live semantic palette.");
                        string capture = Path.Combine(directory, Path.GetFileNameWithoutExtension(outputPath) + "." + paletteName + "." + language + ".png");
                        ScreenshotPngWriter.WriteElementPng(host, capture, width, height);
                        cases.Add(new { Palette = paletteName, Language = language.ToString(), Linked = first, IndependentScale = 3D, FitRecovery = true, ActiveOutline = true, Capture = capture });
                    }
                }
                finally { host.Resources.MergedDictionaries.Remove(palette); }
            }
            OpenVisionLanguageService.SetLanguage(initial, false); Pump(4);
            views[0].ShowOriginalSize(); views[0].PanImageByForTest(7D, -9D); Pump(4);
            OpenVisionImageViewport retained = views[0].ViewportForTest!.Value;
            model.SingleCommand.Execute(null); model.Panes[0].Source = "layer:Main"; Pump(8);
            OpenVisionLayerViewerView single = FindVisualChildren<OpenVisionLayerViewerView>(host).Single(item => item.MainPane?.Id == model.Panes[0].Id);
            AssertViewport("preset restore", single.ViewportForTest!.Value, retained);
            if (host.NativePreviewRunCount != runs || host.LayerDocumentCount != layers || host.WorkspaceLayerTitle != route || !working.SequenceEqual(VisionPipelineExecutionPlan.SerializePipeline(host.Workbench.Pipeline.WorkingCopyForTest)))
                throw new InvalidOperationException("Display navigation changed inspection, route, layers or working XML.");
            File.WriteAllText(Path.ChangeExtension(outputPath, ".sync-cases.json"), JsonSerializer.Serialize(new { Cases = cases, PresetRestore = true, NoImplicitRun = true, NoRecipeChange = true,
                ProductSHA256 = Convert.ToHexString(SHA256.HashData(File.ReadAllBytes(typeof(OpenVisionShellHostView).Assembly.Location))),
                Scope = "In-process Main navigation command/data/presentation and live semantic palettes; native pointer/DPI and full Main96 are separate" }, new JsonSerializerOptions { WriteIndented = true }));
        });
        static void AssertViewport(string condition, OpenVisionImageViewport actual, OpenVisionImageViewport expected)
        {
            if (Math.Abs(actual.Scale - expected.Scale) > 0.000001D || Math.Abs(actual.CenterX - expected.CenterX) > 0.000001D || Math.Abs(actual.CenterY - expected.CenterY) > 0.000001D || actual.Fit != expected.Fit)
                throw new InvalidOperationException(condition + " viewport differs: " + actual + " != " + expected);
        }
    }

    private static CaptureResult CaptureMainPaneCommands(string outputPath, int width, int height)
    {
        OpenVisionShellHostView host = CreateShellHost("Smoke_MainPaneCommands", false);
        string directory = Path.GetDirectoryName(outputPath)!;
        string inputPath = Path.Combine(directory, "Main_snapshot_owned_640x360.png");
        using (Bitmap image = new(640, 360)) { using Graphics graphics = Graphics.FromImage(image); graphics.Clear(DrawingColor.Teal); image.Save(inputPath, ImageFormat.Png); }
        List<object> cases = new();
        return CaptureWindowWithContent(host, outputPath, width, height, () =>
        {
            if (!host.LoadMainImageFromFileForTest(inputPath)) throw new InvalidOperationException("Snapshot input setup failed.");
            OpenVisionWorkbenchViewerViewModel model = host.Workbench.Viewer;
            OpenVisionWorkbenchViewerPane pane = model.Panes[0];
            int runs = host.NativePreviewRunCount, layers = host.LayerDocumentCount;
            string route = host.WorkspaceLayerTitle;
            byte[] working = VisionPipelineExecutionPlan.SerializePipeline(host.Workbench.Pipeline.WorkingCopyForTest);
            pane.SnapshotCommand.Execute(null); Pump(8);
            string source = pane.Source;
            if (!source.StartsWith("snap:", StringComparison.Ordinal) || !pane.OpenCommand.CanExecute(null)) throw new InvalidOperationException("Snapshot new-window command is unavailable.");
            pane.OpenCommand.Execute(null); Pump(12);
            OpenVisionFloatingToolWindow window = Application.Current.Windows.OfType<OpenVisionFloatingToolWindow>().Single(item => item.IsVisible && item.HostedContent is OpenVisionLayerViewerView snapshotView && snapshotView.Tag == null);
            OpenVisionLayerViewerView viewer = (OpenVisionLayerViewerView)window.HostedContent;
            if (window.IsDockButtonVisible || window.Owner != Window.GetWindow(host) || host.OpenLayerViewerWindowCount != 1) throw new InvalidOperationException("Snapshot window ownership/docking contract failed.");
            using (Bitmap replacement = new(320, 180)) { using Graphics graphics = Graphics.FromImage(replacement); graphics.Clear(DrawingColor.Orange); host.SetMainLayerImageForTest(replacement); }
            Pump(8);
            model.ClearSnapshotsCommand.Execute(null); Pump(8);
            using (Bitmap frozen = viewer.CloneImageForTest())
            {
                if (!window.IsVisible || frozen.Width != 640 || frozen.Height != 360 || frozen.GetPixel(0, 0).ToArgb() != DrawingColor.Teal.ToArgb()) throw new InvalidOperationException("Snapshot popout changed or closed after source refresh/clear.");
                string failedPath = Path.Combine(directory, "missing_owned_directory", "snapshot.png");
                if (OpenVisionShellHostCommandController.TrySaveDisplayImage(frozen, failedPath)) throw new InvalidOperationException("Save accepted a missing parent directory.");
                string saved = Path.Combine(directory, "snapshot_recovered.png");
                if (!OpenVisionShellHostCommandController.TrySaveDisplayImage(frozen, saved)) throw new InvalidOperationException("Snapshot save retry failed.");
                using Bitmap restored = new(saved);
                if (restored.Width != 640 || restored.Height != 360 || restored.GetPixel(0, 0).ToArgb() != DrawingColor.Teal.ToArgb()) throw new InvalidOperationException("Saved snapshot pixels differ.");
                cases.Add(new { Case = "new-window-source-refresh-clear-save-failure-retry", SnapshotSource = source, Size = "640x360", Frozen = true, Owner = true, Saved = saved });
            }
            string capture = Path.Combine(directory, Path.GetFileNameWithoutExtension(outputPath) + ".snapshot-window.png");
            ScreenshotPngWriter.WriteElementPng(window, capture, 820, 600);
            window.Close(); Pump(8);
            if (host.OpenLayerViewerWindowCount != 0) throw new InvalidOperationException("Snapshot window was not released.");
            foreach (int count in new[] { 2, 4 })
            {
                (count == 2 ? model.Split2Command : model.Split4Command).Execute(null); Pump(8);
                foreach (OpenVisionLayerViewerView mainView in FindVisualChildren<OpenVisionLayerViewerView>(host).Where(item => item.MainPane != null && item.IsVisible))
                {
                    Border header = FindNamedVisualChild<Border>(mainView, "mainPaneHeader")!;
                    ComboBox combo = FindNamedVisualChild<ComboBox>(mainView, "mainPaneSource")!;
                    Button pin = FindNamedVisualChild<Button>(mainView, "mainPanePin")!;
                    AssertElementWithinAncestor("Main source", combo, header); AssertElementWithinAncestor("Main pin", pin, header);
                    mainView.RaiseEvent(new MouseButtonEventArgs(Mouse.PrimaryDevice, 0, MouseButton.Left) { RoutedEvent = UIElement.PreviewMouseDownEvent, Source = mainView });
                    Pump(4);
                    if (!mainView.MainPane!.IsActive) throw new InvalidOperationException("Pane pointer activation selected a different display slot.");
                }
                ScreenshotPngWriter.WriteElementPng(host, Path.Combine(directory, Path.GetFileNameWithoutExtension(outputPath) + ".layout" + count + ".png"), width, height);
            }
            if (host.NativePreviewRunCount != runs || host.LayerDocumentCount != layers || host.WorkspaceLayerTitle != route || !working.SequenceEqual(VisionPipelineExecutionPlan.SerializePipeline(host.Workbench.Pipeline.WorkingCopyForTest)))
                throw new InvalidOperationException("Snapshot display UI changed inspection, routing, layers or working XML.");
            File.WriteAllText(Path.ChangeExtension(outputPath, ".command-cases.json"), JsonSerializer.Serialize(new { Cases = cases, Released = true, NoImplicitRun = true, NoRecipeChange = true,
                ProductSHA256 = Convert.ToHexString(SHA256.HashData(File.ReadAllBytes(typeof(OpenVisionShellHostView).Assembly.Location))),
                Scope = "Main snapshot popout/save-recovery and synthetic pointer routing only; real input/native DPI/HTML and full Main96 remain separate" }, new JsonSerializerOptions { WriteIndented = true }));
        });
    }

    private static CaptureResult CaptureMainPaneSourcePopup(string outputPath, int width, int height)
    {
        OpenVisionShellHostView host = CreateShellHost("Smoke_MainPaneSourcePopup", false);
        List<object> cases = new();
        string directory = Path.GetDirectoryName(outputPath)!;
        return CaptureWindowWithContent(host, outputPath, width, height, () =>
        {
            OpenVisionWorkbenchViewerPane pane = host.Workbench.Viewer.Panes[0];
            OpenVisionLayerViewerView view = FindVisualChildren<OpenVisionLayerViewerView>(host).Single(item => item.MainPane?.Id == pane.Id);
            ComboBox source = FindNamedVisualChild<ComboBox>(view, "mainPaneSource")!;
            OpenVisionLanguage initialLanguage = OpenVisionLanguageService.CurrentLanguage;
            foreach (string paletteName in new[] { "Dark", "Light" })
            {
                ResourceDictionary palette = new() { Source = new Uri($"/OpenVisionLab;component/UI/Wpf/OpenVisionWorkbench{paletteName}.xaml", UriKind.Relative) };
                host.Resources.MergedDictionaries.Add(palette);
                try
                {
                    foreach (OpenVisionLanguage language in new[] { OpenVisionLanguage.Korean, OpenVisionLanguage.English })
                    {
                        OpenVisionLanguageService.SetLanguage(language, false);
                        source.RaiseEvent(new MouseButtonEventArgs(Mouse.PrimaryDevice, 0, MouseButton.Left) { RoutedEvent = UIElement.PreviewMouseLeftButtonDownEvent, Source = source });
                        Pump(8);
                        if (!source.IsDropDownOpen) throw new InvalidOperationException("Main source field-click Behavior failed to open the popup.");
                        Popup popup = (Popup)source.Template.FindName("PART_Popup", source);
                        List<string> labels = new();
                        for (int i = 0; i < source.Items.Count; i++)
                        {
                            ComboBoxItem item = (ComboBoxItem)source.ItemContainerGenerator.ContainerFromIndex(i);
                            string expected = ((KeyValuePair<string, string>)source.Items[i]).Value;
                            TextBlock[] text = FindVisualChildren<TextBlock>(item).Where(label => label.IsVisible && !string.IsNullOrWhiteSpace(label.Text)).ToArray();
                            if (!text.Any(label => label.Text == expected)) throw new InvalidOperationException($"Main source popup has no readable label at {i}: '{expected}', rendered='{string.Join("|", text.Select(label => label.Text))}'.");
                            labels.Add(expected);
                        }
                        string capture = Path.Combine(directory, Path.GetFileNameWithoutExtension(outputPath) + $".{paletteName}.{language}.popup.png");
                        ScreenshotPngWriter.WriteElementPng((FrameworkElement)popup.Child, capture, Math.Max(1, (int)Math.Ceiling(((FrameworkElement)popup.Child).ActualWidth)), Math.Max(1, (int)Math.Ceiling(((FrameworkElement)popup.Child).ActualHeight)));
                        cases.Add(new { Palette = paletteName, Language = language.ToString(), Labels = labels, PopupWidth = ((FrameworkElement)popup.Child).ActualWidth, Capture = capture });
                        source.IsDropDownOpen = false; Pump(4);
                    }
                }
                finally { source.IsDropDownOpen = false; host.Resources.MergedDictionaries.Remove(palette); }
            }
            OpenVisionLanguageService.SetLanguage(initialLanguage, false);
            File.WriteAllText(Path.ChangeExtension(outputPath, ".popup-cases.json"), JsonSerializer.Serialize(cases, new JsonSerializerOptions { WriteIndented = true }));
        });
    }

    private static CaptureResult CaptureMainViewerPanes(string outputPath, int width, int height)
    {
        OpenVisionShellHostView host = CreateShellHost("Smoke_MainViewerPanes", false);
        string directory = Path.GetDirectoryName(outputPath)!;
        string inputPath = Path.Combine(directory, "Main_panes_owned_640x360.png");
        using (Bitmap image = new(640, 360)) { using Graphics graphics = Graphics.FromImage(image); graphics.Clear(DrawingColor.Teal); image.Save(inputPath, ImageFormat.Png); }
        List<object> cases = new();
        return CaptureWindowWithContent(host, outputPath, width, height, () =>
        {
            OpenVisionWorkbenchViewerViewModel model = host.Workbench.Viewer;
            int runs = host.NativePreviewRunCount, layers = host.LayerDocumentCount;
            OpenVisionLanguage languageBefore = OpenVisionLanguageService.CurrentLanguage;
            byte[] working = VisionPipelineExecutionPlan.SerializePipeline(host.Workbench.Pipeline.WorkingCopyForTest);
            Observe("empty", 2, new[] { "follow:in", "follow:out" });
            foreach (int count in new[] { 4, 1, 2 })
            {
                Switch(count);
                Observe("empty", count, count == 1 ? new[] { "follow:out" } : count == 2 ? new[] { "follow:in", "follow:out" } : new[] { "layer:Main", "follow:in", "follow:out", "final" });
            }
            if (host.NativePreviewRunCount != runs || host.LayerDocumentCount != layers || !working.SequenceEqual(VisionPipelineExecutionPlan.SerializePipeline(host.Workbench.Pipeline.WorkingCopyForTest)))
                throw new InvalidOperationException("Empty pane presets changed execution, layers or the working copy.");
            if (!host.LoadMainImageFromFileForTest(inputPath)) throw new InvalidOperationException("Main pane valid input setup failed.");
            var a = new VisionPipelineStep { Name = "First", ToolType = "Threshold", InputLayer = "Main", OutputLayer = "PaneA", Enabled = true };
            var b = new VisionPipelineStep { Name = "Second", ToolType = "Threshold", InputLayer = "Main", OutputLayer = "PaneB", Enabled = true };
            if (host.Workbench.Pipeline.InsertStep(0, a) == null || host.Workbench.Pipeline.InsertStep(1, b) == null) throw new InvalidOperationException("Main pane step source setup failed.");
            using (Bitmap image = new(641, 361)) { using Graphics graphics = Graphics.FromImage(image); graphics.Clear(DrawingColor.Red); if (!host.AddLayerImageForTest("PaneA", image)) throw new InvalidOperationException("PaneA setup failed."); }
            using (Bitmap image = new(643, 363)) { using Graphics graphics = Graphics.FromImage(image); graphics.Clear(DrawingColor.Blue); if (!host.AddLayerImageForTest("PaneB", image)) throw new InvalidOperationException("PaneB setup failed."); }
            Pump(8);
            working = VisionPipelineExecutionPlan.SerializePipeline(host.Workbench.Pipeline.WorkingCopyForTest);
            layers = host.LayerDocumentCount;
            string input = host.WorkspaceLayerTitle;
            foreach (string paletteName in new[] { "Dark", "Light" })
            {
                ResourceDictionary palette = new() { Source = new Uri($"/OpenVisionLab;component/UI/Wpf/OpenVisionWorkbench{paletteName}.xaml", UriKind.Relative) };
                host.Resources.MergedDictionaries.Add(palette);
                try
                {
                    foreach (OpenVisionLanguage language in new[] { OpenVisionLanguage.Korean, OpenVisionLanguage.English })
                    {
                        OpenVisionLanguageService.SetLanguage(language, false); Pump(4);
                        foreach (int count in new[] { 1, 2, 4 })
                        {
                            Switch(count);
                            Observe(paletteName + "." + language + ".loaded", count, null);
                            foreach (OpenVisionWorkbenchViewerPane pane in model.Panes)
                            {
                                OpenVisionLayerViewerView view = PaneView(pane.Id);
                                if (pane.Source != "follow:out" || host.Workbench.Pipeline.SelectedStepIndex >= 0)
                                    if (!view.HasImage || pane.SizeText.Length == 0) throw new InvalidOperationException("Loaded pane source has no image or pixel dimensions.");
                                ComboBox source = FindNamedVisualChild<ComboBox>(view, "mainPaneSource")!;
                                string original = pane.Source;
                                source.SelectedValue = "layer:Main"; Pump(4);
                                if (pane.Source != "layer:Main" || pane.Title != (language == OpenVisionLanguage.Korean ? "원본" : "Original")) throw new InvalidOperationException("Main source control-to-model binding failed.");
                                pane.Source = original; Pump(4);
                                if ((string?)source.SelectedValue != original) throw new InvalidOperationException("Main source model-to-control binding failed.");
                                view.ShowOriginalSize(); Pump(4);
                                model.NotifySources(); Pump(4);
                                if (Math.Abs(view.ZoomScale - 1D) > 0.000001D) throw new InvalidOperationException("Source metadata refresh reset the pane zoom.");
                            }
                        }
                    }
                }
                finally { host.Resources.MergedDictionaries.Remove(palette); }
            }
            Switch(2); host.Workbench.Pipeline.SelectedStepIndex = 0; Pump(4);
            OpenVisionWorkbenchViewerPane output = model.Panes[1];
            if (output.Source != "follow:out" || output.SizeText != "641×361") throw new InvalidOperationException("Output pane did not follow step A.");
            output.PinCommand.Execute(null); host.Workbench.Pipeline.SelectedStepIndex = 1; Pump(4);
            if (output.Source != "layer:PaneA" || output.SizeText != "641×361") throw new InvalidOperationException("Pinned pane followed a changed selection.");
            output.PinCommand.Execute(null); Pump(4);
            if (output.Source != "follow:out" || output.SizeText != "643×363") throw new InvalidOperationException("Unpin did not restore the slot's follow-output default.");
            output.SnapshotCommand.Execute(null); Pump(4);
            string snap = output.Source;
            using (Bitmap image = new(644, 364)) { using Graphics graphics = Graphics.FromImage(image); graphics.Clear(DrawingColor.Orange); host.AddLayerImageForTest("PaneB", image); }
            Pump(4);
            using (Bitmap frozen = PaneView(output.Id).CloneImageForTest())
                if (!snap.StartsWith("snap:", StringComparison.Ordinal) || frozen.Width != 643 || frozen.GetPixel(0, 0).ToArgb() != DrawingColor.Blue.ToArgb()) throw new InvalidOperationException("Snapshot pixels changed with the output layer.");
            Switch(4); Switch(2);
            if (model.Panes[1].Source != snap) throw new InvalidOperationException("Snapshot source did not survive preset round trip.");
            model.ClearSnapshotsCommand.Execute(null); Pump(4);
            if (output.Source != "follow:out" || output.SizeText != "644×364" || output.Sources.Any(choice => choice.Key.StartsWith("snap:", StringComparison.Ordinal))) throw new InvalidOperationException("Snapshot clear did not restore follow source or release options.");
            Switch(4); Observe("snapshot-clear-recovery", 4, null);
            if (host.NativePreviewRunCount != runs || host.LayerDocumentCount != layers || host.WorkspaceLayerTitle != input
                || !working.SequenceEqual(VisionPipelineExecutionPlan.SerializePipeline(host.Workbench.Pipeline.WorkingCopyForTest))) throw new InvalidOperationException("Pane UI changed execution, input routing or working recipe.");
            OpenVisionLanguageService.SetLanguage(languageBefore, false); Pump(4);
            File.WriteAllText(Path.ChangeExtension(outputPath, ".pane-cases.json"), JsonSerializer.Serialize(new { Cases = cases, Snapshot = "frozen-blue/changed-orange/preset-restore/clear passed", Runs = runs, Layers = layers,
                ProductSHA256 = Convert.ToHexString(SHA256.HashData(File.ReadAllBytes(typeof(OpenVisionShellHostView).Assembly.Location))),
                Scope = "Main display slots only; in-process WPF, no actual input/nativeDPI/HTML or whole Main96 claim" }, new JsonSerializerOptions { WriteIndented = true }));

            void Switch(int count) { (count == 1 ? model.SingleCommand : count == 2 ? model.Split2Command : model.Split4Command).Execute(null); Pump(8); }
            OpenVisionLayerViewerView PaneView(string id) => FindVisualChildren<OpenVisionLayerViewerView>(host).Single(view => view.MainPane?.Id == id);
            void Observe(string state, int count, string[]? expected)
            {
                Pump(8);
                OpenVisionLayerViewerView[] views = FindVisualChildren<OpenVisionLayerViewerView>(host).Where(view => view.MainPane != null && view.IsVisible).ToArray();
                if (model.Layout != count || model.Panes.Count != count || views.Length != count || host.DockedLayerCount != count)
                    throw new InvalidOperationException($"Main preset count mismatch: {state}, expected={count}, model={model.Panes.Count}, visible={views.Length}, documents={host.DockedLayerCount}.");
                if (expected != null && !model.Panes.Select(pane => pane.Source).SequenceEqual(expected)) throw new InvalidOperationException("Main preset defaults differ from canonical PANE_DEFAULT.");
                foreach (OpenVisionLayerViewerView view in views)
                {
                    FrameworkElement header = FindNamedVisualChild<Border>(view, "mainPaneHeader")!;
                    ComboBox source = FindNamedVisualChild<ComboBox>(view, "mainPaneSource")!;
                    Button pin = FindNamedVisualChild<Button>(view, "mainPanePin")!;
                    if (!header.IsVisible || source.ActualWidth <= 0 || !pin.IsVisible) throw new InvalidOperationException("Main pane header/source/pin is hidden.");
                    AssertElementWithinAncestor("Main pane source", source, header);
                    AssertElementWithinAncestor("Main pane pin", pin, header);
                }
                string capture = Path.Combine(directory, Path.GetFileNameWithoutExtension(outputPath) + "." + state + "." + count + ".png");
                ScreenshotPngWriter.WriteElementPng(host, capture, width, height);
                cases.Add(new { State = state, Count = count, Sources = model.Panes.Select(pane => pane.Source).ToArray(), DocumentCount = host.DockedLayerCount, Capture = capture });
            }
        });
    }

    private static CaptureResult CaptureMainHistoryAction(string outputPath, int width, int height)
    {
        OpenVisionLanguageService.SetLanguage(OpenVisionLanguage.Korean, false);
        string recipeName = "Smoke_Main_History_" + Guid.NewGuid().ToString("N");
        OpenVisionShellHostView host = CreateShellHost(recipeName);
        VisionPipeline source = CreatePipelineReviewInputStatePipeline();
        VisionPipelineStorage.Save(recipeName, source);
        VisionPipelineStorage.SaveActivePipelineName(recipeName, source.Name);
        host.RecipeCommands.RefreshOptions();
        host.RecipeCommands.SelectedPipelineOption = host.RecipeCommands.PipelineOptions.Single(option => option.PipelineName == source.Name);
        List<object> cases = new();
        List<string> failures = new();
        return CaptureWindowWithContent(host, outputPath, width, height, () =>
        {
            OpenVisionWorkbenchPipelineViewModel model = host.Workbench.Pipeline;
            Grid status = FindVisualChildren<Grid>(host).Single(item => AutomationProperties.GetAutomationId(item) == "WorkbenchStatusBar");
            TextBlock message = FindNamedVisualChild<TextBlock>(status, "workbenchActionStatus")!;
            MahApps.Metro.IconPacks.PackIconMaterial icon = FindVisualChildren<MahApps.Metro.IconPacks.PackIconMaterial>(status).Single(item => AutomationProperties.GetAutomationId(item) == "WorkbenchActionIcon");
            ListBox list = FindVisualChildren<ListBox>(host).Single(item => AutomationProperties.GetAutomationId(item) == "WorkbenchPipelineSteps");
            KeyBinding undo = list.InputBindings.OfType<KeyBinding>().Single(item => item.Key == Key.Z && item.Modifiers == ModifierKeys.Control);
            KeyBinding redo = list.InputBindings.OfType<KeyBinding>().Single(item => item.Key == Key.Y && item.Modifiers == ModifierKeys.Control);
            bool bindingPreserved = ReferenceEquals(undo.Command, model.UndoCommand) && ReferenceEquals(redo.Command, model.RedoCommand);
            string xmlPath = RecipeWorkspaceService.GetVisionPipelinePath(recipeName, source.Name);
            byte[] saved = File.ReadAllBytes(xmlPath);
            byte[] original = VisionPipelineExecutionPlan.SerializePipeline(model.WorkingCopyForTest);
            int runs = host.NativePreviewRunCount;
            string initialText = message.Text;
            bool emptyRejected = !undo.Command.CanExecute(null) && !redo.Command.CanExecute(null);
            undo.Command.Execute(null); redo.Command.Execute(null); Pump(3);
            bool emptyNoAction = initialText == message.Text && original.SequenceEqual(VisionPipelineExecutionPlan.SerializePipeline(model.WorkingCopyForTest));
            model.SelectedStepIndex = 0;
            model.RenameCommand.Execute(null); Pump(4);
            TextBox editor = FindVisualChildren<TextBox>(host).Single(item => item.IsVisible && AutomationProperties.GetAutomationId(item) == "WorkbenchStepRenameEditor");
            editor.Text = "Main undo redo owned rename";
            editor.GetBindingExpression(TextBox.TextProperty).UpdateSource();
            model.CommitRenameCommand.Execute(null); Pump(4);
            byte[] renamed = VisionPipelineExecutionPlan.SerializePipeline(model.WorkingCopyForTest);
            if (renamed.SequenceEqual(original)) throw new InvalidOperationException("Main history rename setup did not change the working copy.");
            int layers = host.LayerDocumentCount;
            foreach (string state in new[] { "undo", "redo" })
            {
                ICommand command = state == "undo" ? undo.Command : redo.Command;
                if (!command.CanExecute(null)) throw new InvalidOperationException("Main history restore unavailable: " + state);
                command.Execute(null); Pump(4);
                byte[] expected = state == "undo" ? original : renamed;
                bool workingRestored = expected.SequenceEqual(VisionPipelineExecutionPlan.SerializePipeline(model.WorkingCopyForTest));
                string beforeNoop = message.Text;
                bool noopDisabled = !command.CanExecute(null);
                command.Execute(null); Pump(3);
                bool noopStable = beforeNoop == message.Text && expected.SequenceEqual(VisionPipelineExecutionPlan.SerializePipeline(model.WorkingCopyForTest));
                foreach (string paletteName in new[] { "Dark", "Light" })
                {
                    ResourceDictionary palette = new() { Source = new Uri($"/OpenVisionLab;component/UI/Wpf/OpenVisionWorkbench{paletteName}.xaml", UriKind.Relative) };
                    host.Resources.MergedDictionaries.Add(palette);
                    try
                    {
                        foreach (OpenVisionLanguage language in new[] { OpenVisionLanguage.Korean, OpenVisionLanguage.English })
                        {
                            OpenVisionLanguageService.SetLanguage(language, false); Pump(4);
                            string expectedText = state == "undo" ? language == OpenVisionLanguage.Korean ? "실행 취소했습니다." : "Undo completed."
                                : language == OpenVisionLanguage.Korean ? "다시 실행했습니다." : "Redo completed.";
                            bool textMatches = message.Text == expectedText && Convert.ToString(message.ToolTip) == expectedText;
                            bool iconMatches = icon.IsVisible && icon.Kind == MahApps.Metro.IconPacks.PackIconMaterialKind.InformationOutline;
                            if (!textMatches || !iconMatches || !bindingPreserved || !emptyRejected || !emptyNoAction || !workingRestored || !noopDisabled || !noopStable)
                                failures.Add($"{paletteName}/{language}/{state}: text={textMatches}/{message.Text}, icon={iconMatches}, binding={bindingPreserved}, empty={emptyRejected}/{emptyNoAction}, restore={workingRestored}, noop={noopDisabled}/{noopStable}");
                            string capture = Path.Combine(Path.GetDirectoryName(outputPath)!, Path.GetFileNameWithoutExtension(outputPath) + $".{paletteName}.{language}.{state}.png");
                            ScreenshotPngWriter.WriteElementPng(host, capture, width, height);
                            cases.Add(new { State = state, Palette = paletteName, Language = language.ToString(), Expected = expectedText, Text = message.Text, TextMatches = textMatches, IconMatches = iconMatches,
                                BindingPreserved = bindingPreserved, EmptyRejected = emptyRejected, EmptyNoAction = emptyNoAction, WorkingRestored = workingRestored, NoopDisabled = noopDisabled, NoopStable = noopStable, Capture = capture });
                        }
                    }
                    finally { host.Resources.MergedDictionaries.Remove(palette); }
                }
            }
            var invariants = new { XMLUnchanged = saved.SequenceEqual(File.ReadAllBytes(xmlPath)), RunsUnchanged = host.NativePreviewRunCount == runs,
                LayersUnchanged = host.LayerDocumentCount == layers, FinalWorkingRenamed = renamed.SequenceEqual(VisionPipelineExecutionPlan.SerializePipeline(model.WorkingCopyForTest)) };
            if (!invariants.XMLUnchanged || !invariants.RunsUnchanged || !invariants.LayersUnchanged || !invariants.FinalWorkingRenamed) failures.Add("Main history action changed XML, execution, layers or the expected working copy.");
            File.WriteAllText(Path.ChangeExtension(outputPath, ".history-cases.json"), JsonSerializer.Serialize(new { Cases = cases, Failures = failures, Invariants = invariants,
                ProductSHA256 = Convert.ToHexString(SHA256.HashData(File.ReadAllBytes(typeof(OpenVisionShellHostView).Assembly.Location))),
                Scope = "Main existing CtrlZ/CtrlY bound command objects and inline edit binding through inprocess WPF only; no actual key/CU/Run/HTML/nativeDPI/full Main score." }, new JsonSerializerOptions { WriteIndented = true }));
            if (failures.Count > 0) throw new InvalidOperationException(string.Join("; ", failures));
        });
    }

    private static CaptureResult CaptureMainSampleImages(string outputPath, int width, int height)
    {
        var host = CreateShellHost("Smoke_VM17_" + Guid.NewGuid().ToString("N"), false);
        return CaptureWindowWithContent(host, outputPath, 1280, 760, () =>
        {
            void Require(bool ok, string text) { File.AppendAllText(Path.ChangeExtension(outputPath, ".trace.txt"), text + "=" + ok + Environment.NewLine); if (!ok) { throw new InvalidOperationException("VM17: " + text); } }
            var root = host.Workbench; var images = root.Images;
            var loader = ReadPrivateField<OpenVisionShellHostCommandController>(host, "commandController");
            root.Tool.ConfigureAutoRunPreference(() => false, _ => { });
            string input = Path.ChangeExtension(outputPath, ".current.png"); using (Bitmap bitmap = new(17, 11)) { bitmap.Save(input, ImageFormat.Png); }
            Require(host.LoadMainImageFromFileForTest(input), "owned current input"); Pump(3);
            images.CurrentImage.ReplaceResult(new OpenVisionWorkbenchImageResult("Synthetic prior", 0, root.Pipeline.CopyWorkingPipeline(), new(), new(), "Ok", 1, "No engine execution"));
            var current = images.CurrentImage; var result = current.Result; var working = VisionPipelineExecutionPlan.SerializePipeline(root.Pipeline.CopyWorkingPipeline());
            int runs = host.NativePreviewRunCount, layers = host.LayerDocumentCount; string route = host.ActiveHostLayerTitle;
            void Retained(string state) { Require(ReferenceEquals(current, images.CurrentImage) && ReferenceEquals(result, current.Result) && working.SequenceEqual(VisionPipelineExecutionPlan.SerializePipeline(root.Pipeline.CopyWorkingPipeline())) && runs == host.NativePreviewRunCount && layers == host.LayerDocumentCount && route == host.ActiveHostLayerTitle, state + " retains input/result/working/run/layer/route"); }
            var catalog = VisionPipelineSampleCatalogItem.LoadRunnable().Where(item => item.CanOpen && item.CatalogSourceKind == VisionPipelineSampleCatalogSourceKind.Public).ToList();
            var groups = catalog.Where(item => !string.IsNullOrWhiteSpace(item.PairGroup)).GroupBy(item => item.PairGroup).Where(group => group.Any(item => item.PairRole == "Good") && group.Any(item => item.PairRole == "Bad")).ToArray();
            Require(groups.Length >= 2, "real public pair groups available");
            var bad = groups[0].First(item => item.PairRole == "Bad"); var good = groups[0].First(item => item.PairRole == "Good");
            string error = null;
            void Pick(string role, VisionPipelineSampleCatalogItem selected, bool accept, string theme, OpenVisionLanguage language, string suffix, bool compact = false)
            {
                int before = images.Count; error = null; OpenVisionLanguageService.SetLanguage(language, false); Pump(3);
                var owner = Window.GetWindow(host); OpenVisionWorkbenchThemeBehavior.SetThemeName(owner, theme);
                host.Dispatcher.BeginInvoke(new Action(() =>
                {
                    var picker = Application.Current.Windows.OfType<OpenVisionWorkspaceSamplePickerWindow>().Single(window => window.IsVisible);
                    try
                    {
                        File.AppendAllText(Path.ChangeExtension(outputPath, ".monitor.txt"), SmokeWindowMonitorPlacement.PlaceOnLeftmostMonitor(picker) + Environment.NewLine);
                        if (compact) { picker.Width = 680; picker.Height = 560; }
                        Require(picker.Width == (compact ? 680 : 820) && picker.Height == (compact ? 560 : 620), "image-only window bounds " + suffix);
                        var vm = picker.ViewModel;
                        if (suffix == "cancel-dark-ko")
                        {
                            FindNamedVisualChild<ListBox>(picker, "imageOnlySamples").SetCurrentValue(System.Windows.Controls.Primitives.Selector.SelectedItemProperty, null); Pump(2);
                            Require(!vm.CanSelect && !FindVisualChildren<Button>(picker).Single(button => AutomationProperties.GetAutomationId(button) == "WorkspaceSamplePickerOpenButton").IsEnabled, "empty selection disables explicit Add");
                            ScreenshotPngWriter.WriteElementPng(picker, Path.ChangeExtension(outputPath, ".disabled-dark-ko.png"), (int)picker.ActualWidth, (int)picker.ActualHeight);
                        }
                        var actual = vm.SamplesView.Cast<VisionPipelineSampleCatalogItem>().First(sample => sample.SampleName == selected.SampleName && sample.CatalogSourceKind == selected.CatalogSourceKind && sample.ImageFullPath == selected.ImageFullPath && sample.PipelineFullPath == selected.PipelineFullPath); FindNamedVisualChild<ListBox>(picker, "imageOnlySamples").SetCurrentValue(System.Windows.Controls.Primitives.Selector.SelectedItemProperty, actual);
                        var radio = FindVisualChildren<RadioButton>(picker).Single(button => button.Content?.ToString() == (role == "set" ? vm.ImageSetText : role == "nolabel" ? vm.ImageUnlabeledText : vm.ImageOneText));
                        radio.SetCurrentValue(System.Windows.Controls.Primitives.ToggleButton.IsCheckedProperty, true); Pump(3);
                        Require(vm.ImageSelectionRole == role && ReferenceEquals(vm.SelectedSample, actual) && vm.SelectedImageSamples.Contains(actual), "rendered role/selected identity binding " + suffix);
                        Require(ReferenceEquals(FindNamedVisualChild<ListBox>(picker, "imageOnlySamples").SelectedItem, actual), "rendered list selection " + suffix);
                        Require(vm.IsImageOnly && vm.LearnWorkflowVisibility == Visibility.Collapsed && !vm.OpenLearnAndSelectCommand.CanExecute(null) && images.Count == before, "image-only purpose and no acceptance side effect " + suffix); Retained("browse " + suffix);
                        ScreenshotPngWriter.WriteElementPng(picker, Path.ChangeExtension(outputPath, "." + suffix + ".png"), (int)picker.ActualWidth, (int)picker.ActualHeight);
                        if (accept) { vm.AcceptSelectionCommand.Execute(null); } else { picker.Close(); }
                    }
                    catch (Exception ex) { error = ex.ToString(); picker.Close(); }
                }), System.Windows.Threading.DispatcherPriority.ContextIdle);
                host.WorkspaceCommands.OpenSampleCommand.Execute(null); Pump(3); if (error != null) { throw new InvalidOperationException(error); } Retained("return " + suffix);
                if (!accept) { Require(images.Count == before, "cancel retains image list"); }
            }
            Pick("one", bad, false, "Dark", OpenVisionLanguage.Korean, "cancel-dark-ko");
            int initial = images.Count;
            Pick("one", bad, true, "Dark", OpenVisionLanguage.English, "one-en");
            Require(images.Count == initial + 1 && images.Images.Single(item => item.Path == bad.ImageFullPath).Label == "", "selected bad reference stays exact image and unlabeled");
            Pick("set", good, true, "Light", OpenVisionLanguage.Korean, "set-light-ko");
            Require(images.Images.Single(item => item.Path == good.ImageFullPath).Label == "good" && images.Images.Single(item => item.Path == bad.ImageFullPath).Label == "", "only catalog Good label added; duplicate existing label preserved");
            int groupCount = images.Count; Pick("set", good, true, "Light", OpenVisionLanguage.Korean, "duplicate-compact", true);
            Require(images.Count == groupCount, "duplicate set does not add or relabel");
            Pick("nolabel", groups[1].First(), true, "Dark", OpenVisionLanguage.English, "unlabeled-en");
            Require(groups[1].All(sample => images.Images.Single(item => item.Path == sample.ImageFullPath).Label == ""), "unlabeled role never copies catalog labels");
            var noGroup = new VisionPipelineSampleCatalogItem { SampleName = "Owned no-group reference", ImageFullPath = input, PipelineFullPath = bad.PipelineFullPath, CatalogSourceKind = VisionPipelineSampleCatalogSourceKind.Public };
            var one = new OpenVisionWorkspaceSamplePickerViewModel(new[] { noGroup }, null, true) { ImageSelectionRole = "set" };
            Require(one.SelectedImageSamples.Count == 1 && ReferenceEquals(one.SelectedImageSamples[0], noGroup), "no group uses selected image only");
            string fault = Path.Combine(Path.GetDirectoryName(outputPath), "owned-" + Guid.NewGuid().ToString("N") + ".png");
            var faulty = new VisionPipelineSampleCatalogItem { SampleName = "Owned failure", ImageFullPath = fault, PairRole = "Good" };
            int beforeFault = images.Count; string notified = null;
            Require(loader.AddSampleImages(new[] { faulty }, true, detail => notified = detail) == 0 && notified.Contains(fault) && images.Count == beforeFault, "missing file rejected in actual importer"); Retained("missing");
            File.WriteAllText(fault, "invalid image bytes"); notified = null;
            Require(loader.AddSampleImages(new[] { faulty }, true, detail => notified = detail) == 0 && notified.Contains(fault) && images.Count == beforeFault, "corrupt file rejected in actual importer"); Retained("corrupt");
            using (Bitmap recovered = new(23, 19)) { recovered.Save(fault, ImageFormat.Png); }
            Require(loader.AddSampleImages(new[] { faulty }, true, detail => notified = detail) == 1 && images.Images.Single(item => item.Path == fault).Label == "good" && !images.IsSampleImport, "valid retry releases import guard and uses actual label"); Retained("recovery");
            var legacy = new OpenVisionWorkspaceSamplePickerViewModel(catalog);
            OpenVisionWorkbenchThemeBehavior.SetThemeName(Window.GetWindow(host), "Light");
            var legacyWindow = new OpenVisionWorkspaceSamplePickerWindow(legacy) { Owner = Window.GetWindow(host) };
            try { legacyWindow.Show(); File.AppendAllText(Path.ChangeExtension(outputPath, ".monitor.txt"), SmokeWindowMonitorPlacement.PlaceOnLeftmostMonitor(legacyWindow) + Environment.NewLine); Pump(3); Require(!legacy.IsImageOnly && legacy.LearnWorkflowVisibility == Visibility.Visible && legacy.SelectedSample != null, "legacy learning purpose unchanged"); ScreenshotPngWriter.WriteElementPng(legacyWindow, Path.ChangeExtension(outputPath, ".legacy-theme.png"), (int)legacyWindow.ActualWidth, (int)legacyWindow.ActualHeight); }
            finally { legacyWindow.Close(); }
            Retained("legacy close");
            File.WriteAllText(Path.ChangeExtension(outputPath, ".json"), JsonSerializer.Serialize(new { Scope = "Shown in-process WPF source host/child; actual GUI/native125 unverified", RealCatalog = true, ReferencePath = bad.ImageFullPath, Group = good.PairGroup, SyntheticPriorResult = true, NoEngineRun = true, NativeFailureNotice = "callback capture only; default native MessageBox unchanged" }, new JsonSerializerOptions { WriteIndented = true }));
        }, captureFloatingToolWindow: false);
    }

    private static CaptureResult CaptureMainImageStart(string outputPath, int width, int height)
    {
        OpenVisionShellHostView host = CreateShellHost("Smoke_ImageStart_" + width, false);
        string directory = Path.GetDirectoryName(outputPath)!;
        List<object> cases = new();
        void Record(object value) { cases.Add(value); File.WriteAllText(Path.ChangeExtension(outputPath, ".cases.json"), JsonSerializer.Serialize(cases, new JsonSerializerOptions { WriteIndented = true })); }
        void Require(bool condition, string message) { if (!condition) throw new InvalidOperationException("Image start: " + message); }
        return CaptureWindowWithContent(host, outputPath, width, height, () =>
        {
            OpenVisionWorkbenchViewModel root = host.Workbench;
            OpenVisionWorkbenchImagesViewModel images = root.Images;
            OpenVisionShellHostCommandController loader = (OpenVisionShellHostCommandController)typeof(OpenVisionShellHostView).GetField("commandController", BindingFlags.Instance | BindingFlags.NonPublic)!.GetValue(host)!;
            TextBlock status = FindNamedVisualChild<TextBlock>(host, "workbenchActionStatus")!;
            var icon = FindVisualChildren<MahApps.Metro.IconPacks.PackIconMaterial>(host).Single(item => AutomationProperties.GetAutomationId(item) == "WorkbenchActionIcon");
            bool before = Environment.GetEnvironmentVariable("OPENVISIONLAB_IMAGE_START_BEFORE") == "1";
            bool boundaryOnly = Environment.GetEnvironmentVariable("OPENVISIONLAB_IMAGE_START_BOUNDARY_ONLY") == "1";
            foreach (string theme in before || boundaryOnly ? new[] { "Dark" } : new[] { "Dark", "Light" })
            foreach (OpenVisionLanguage language in before || boundaryOnly ? new[] { OpenVisionLanguage.Korean } : new[] { OpenVisionLanguage.Korean, OpenVisionLanguage.English })
            {
                (theme == "Dark" ? root.SelectDarkThemeCommand : root.SelectLightThemeCommand).Execute(null); OpenVisionLanguageService.SetLanguage(language, false); Pump(3);
                string a = Path.Combine(directory, theme + language + ".a.png"), b = Path.Combine(directory, theme + language + ".b.png");
                using (Bitmap bitmap = new(64, 40)) { using Graphics graphics = Graphics.FromImage(bitmap); graphics.Clear(DrawingColor.Teal); bitmap.Save(a, ImageFormat.Png); bitmap.Save(b, ImageFormat.Png); }
                int initial = images.Count, runs = host.NativePreviewRunCount;
                int uiThread = Environment.CurrentManagedThreadId;
                List<int> notificationThreads = new();
                Action<int> startedThread = _ => notificationThreads.Add(Environment.CurrentManagedThreadId);
                images.ImportStarted += startedThread;
                Action<int, int, int> completedThread = (_, _, _) => notificationThreads.Add(Environment.CurrentManagedThreadId);
                images.ImportCompleted += completedThread;
                bool returned = false, rendered = false;
                string expected = language == OpenVisionLanguage.Korean ? "이미지 3장을 여는 중…" : "Opening 3 images…";
                string capture = Path.Combine(directory, Path.GetFileNameWithoutExtension(outputPath) + "." + theme + language + ".opening.png");
                var observation = host.Dispatcher.BeginInvoke(new Action(() =>
                {
                    Rect bounds = GetElementBounds(host, status);
                    rendered = !returned && root.MainActionKind == "Running" && status.Text == expected && images.Count == initial;
                    int reentry = before ? -1 : loader.AddWorkspaceImages(new[] { b });
                    if (!before) { loader.PromptAndLoadWorkspaceImage(); loader.PromptAndOpenWorkspaceFolder(""); }
                    Record(new { Case = "dispatcher-bound-start-before-publication", Theme = theme, Language = language.ToString(), Returned = returned, images.Count, InitialCount = initial, Text = root.MainActionText, BoundText = status.Text, Kind = root.MainActionKind, Icon = icon.Kind.ToString(), IconForeground = icon.Foreground.ToString(), SentenceForeground = status.Foreground.ToString(), Bounds = bounds.ToString(), Capture = before ? capture : null, Reentry = reentry, Pass = rendered, Boundary = "dispatcher bound observation during actual worker; no Rendering observer/helper/paint claim" });
                    if (before) ScreenshotPngWriter.WriteDpiAwareWindowPng(Window.GetWindow(host), capture);
                    if (!before) Require(reentry == 0 && images.Count == initial && bounds.Width > 0 && status.IsVisible && icon.Kind == MahApps.Metro.IconPacks.PackIconMaterialKind.TimerOutline, "rendered start/reentry guard");
                }), System.Windows.Threading.DispatcherPriority.Render);
                int added;
                added = loader.AddWorkspaceImages(new[] { a, a, b });
                images.ImportStarted -= startedThread;
                images.ImportCompleted -= completedThread;
                returned = true; Pump(3);
                string completedCapture = Path.ChangeExtension(capture, ".completed.png");
                ScreenshotPngWriter.WriteDpiAwareWindowPng(Window.GetWindow(host), completedCapture);
                Record(new { Case = "actual-completion", Theme = theme, Language = language.ToString(), Added = added, images.Count, Text = root.MainActionText, Kind = root.MainActionKind, Runs = host.NativePreviewRunCount, Attempted = 3, ObserverAttached = false, Capture = completedCapture, CaptureTiming = "after return only; no helper called during start/render observation" });
                Require(rendered && added == 2 && images.Count == initial + 2 && host.NativePreviewRunCount == runs && root.MainActionKind != "Running", "bound start during worker and unique completion replaced it");
                Require(notificationThreads.All(thread => thread == uiThread) && images.Images.All(image => image.Preview.IsFrozen), "UI notification and frozen worker previews");
                Record(new { Case = "worker-publication-thread", UiThread = uiThread, NotificationThreads = notificationThreads, FrozenPreviews = images.Images.All(image => image.Preview.IsFrozen), ObserverAttached = false });
                string final = root.MainActionText;
                Require(loader.AddWorkspaceImages(null) == 0 && loader.AddWorkspaceImages(Array.Empty<string>()) == 0 && root.MainActionText == final, "empty/null no writer");
            }
            if (!before)
            {
                string path = Path.Combine(directory, "boundary-recovery.png");
                using (Bitmap bitmap = new(50, 30)) { bitmap.Save(path, ImageFormat.Png); }
                int priorCount = images.Count;
                MethodInfo notify = typeof(OpenVisionWorkbenchImagesViewModel).GetMethod("NotifyImportStarted", BindingFlags.Instance | BindingFlags.NonPublic)!;
                notify.Invoke(images, new object[] { 7 }); OpenVisionLanguageService.SetLanguage(OpenVisionLanguage.English, false); Pump(2);
                Require(root.MainActionText == "Opening 7 images…" && status.Text == "Opening 7 images…", "locale preserves captured attempted count");
                root.Pipeline.RefreshInputState(); Require(root.MainActionText == "Opening 7 images…", "ordinary refresh preserves start");
                try { root.AttachImages(null!); throw new InvalidOperationException("Null accepted"); } catch (ArgumentNullException) { }
                notify.Invoke(images, new object[] { 8 }); Require(root.MainActionText == "Opening 8 images…", "null attachment preserves start subscription");
                OpenVisionWorkbenchImagesViewModel replacement = new(root.Shell, _ => true, () => { });
                int replacementCount = replacement.Count;
                try
                {
                    bool replaced = false;
                    host.Dispatcher.BeginInvoke(new Action(() => { loader.AttachWorkspaceImages(replacement); root.AttachImages(replacement); replaced = true; }), System.Windows.Threading.DispatcherPriority.Render);
                    string badPath = Path.Combine(directory, "worker-truncated.png");
                    File.WriteAllBytes(badPath, new byte[] { 137, 80, 78, 71 });
                    var memory = new log4net.Appender.MemoryAppender { Fix = log4net.Core.FixFlags.All };
                    var logger = (log4net.Repository.Hierarchy.Logger)log4net.LogManager.GetLogger("OpenVisionLab.All").Logger;
                    memory.ActivateOptions(); logger.AddAppender(memory);
                    int replacedAdded;
                    try
                    {
                        OpenVisionLab.Logging.OVLog.Write(OpenVisionLab.Logging.LogCategory.Main, OpenVisionLab.Logging.LogLevel.Info, "Owned import UI thread marker");
                        replacedAdded = loader.AddWorkspaceImages(new[] { path, badPath });
                        var entries = memory.GetEvents();
                        string uiLogThread = entries.Single(entry => entry.RenderedMessage.Contains("Owned import UI thread marker")).ThreadName;
                        var errors = entries.Where(entry => entry.RenderedMessage.Contains(badPath) && entry.RenderedMessage.Contains("Workspace image list load failed.")).ToArray();
                        Require(errors.Length == 1 && errors[0].ThreadName != uiLogThread, "actual malformed decode worker differs from UI log thread");
                        Record(new { Case = "actual-worker-error-thread", UiLogThread = uiLogThread, WorkerLogThread = errors[0].ThreadName, Path = badPath, Added = replacedAdded, ModalShown = false, Boundary = "actual decoder failure then captured-owner abort before UI modal; not native failure-dialog coverage" });
                    }
                    finally { logger.RemoveAppender(memory); memory.Close(); }
                    Record(new { Case = "owner-replacement-observation", Replaced = replaced, Added = replacedAdded, PriorCount = priorCount, OldCount = images.Count, NewCount = replacement.Count, InitialReplacementCount = replacementCount, RootText = root.MainActionText, SamePublisher = ReferenceEquals(root.Images, replacement) });
                    Require(replacedAdded == 0 && images.Count == priorCount && replacement.Count == replacementCount, "render owner replacement aborts without decode/list commit");
                    string current = root.MainActionText; notify.Invoke(images, new object[] { 99 }); Require(root.MainActionText == current, "old publisher unsubscribed");
                    notify.Invoke(replacement, new object[] { 4 }); Require(root.MainActionText == "Opening 4 images…", "new publisher connected");
                    host.Dispatcher.BeginInvoke(new Action(replacement.Dispose), System.Windows.Threading.DispatcherPriority.Render);
                    int disposedAdded = loader.AddWorkspaceImages(new[] { path });
                    Record(new { Case = "disposed-images-observation", Added = disposedAdded, CountBeforeDispose = replacementCount, CountAfterDispose = replacement.Count, replacement.CanEdit });
                    Require(disposedAdded == 0 && replacement.Count == 0 && !replacement.CanEdit, "disposed Images at render boundary aborts");
                }
                finally { loader.AttachWorkspaceImages(images); root.AttachImages(images); replacement.Dispose(); }
                Action<int> fail = _ => throw new IOException("Owned start callback failure");
                images.ImportStarted += fail;
                bool propagated = false;
                try { loader.AddWorkspaceImages(new[] { path }); } catch (IOException ex) { propagated = ex.Message == "Owned start callback failure"; }
                finally { images.ImportStarted -= fail; }
                Require(propagated && images.Count == priorCount, "start callback error propagated/finally guard released");
                Require(loader.AddWorkspaceImages(new[] { path }) == 1 && images.Count == priorCount + 1 && root.MainActionText == "Added 1 images", "valid recovery after abort/error");
                bool guard = (bool)typeof(OpenVisionShellHostCommandController).GetField("importingWorkspaceImages", BindingFlags.Instance | BindingFlags.NonPublic)!.GetValue(loader)!;
                Require(!guard, "final guard reset");
                FieldInfo running = typeof(OpenVisionWorkbenchPipelineViewModel).GetField("running", BindingFlags.Instance | BindingFlags.NonPublic)!;
                running.SetValue(root.Pipeline, true);
                string terminal = root.MainActionText;
                try { Require(loader.AddWorkspaceImages(new[] { path }) == 0 && root.MainActionText == terminal, "existing busy no writer"); }
                finally { running.SetValue(root.Pipeline, false); }
                Record(new { Case = "lifetime-locale-guards", CapturedCount = 7, NullAttachment = true, ReplacementAbort = true, OldPublisherDetached = true, DisposedImagesAbort = true, ErrorPropagation = propagated, ValidRecovery = true, GuardReset = !guard, BusyGuard = true, Boundary = "actual Controller/public attachment with test-only start callback fault and synthetic running guard; corrupt-file modal remains Astra native" });
                string contextRecipe = host.ActiveRecipeContextNameForTest;
                string originalPipeline = host.ActiveRecipeContextPipelineNameForTest;
                VisionPipelineStorage.Save(contextRecipe, new VisionPipeline { Name = originalPipeline });
                VisionPipelineStorage.SaveActivePipelineName(contextRecipe, originalPipeline);
                VisionPipelineStorage.Save(contextRecipe, new VisionPipeline { Name = "RenderOther" });
                root.Recipes.RefreshOptions();
                root.Recipes.SelectedPipelineOption = root.Recipes.PipelineOptions.Single(option => option.PipelineName == "RenderOther");
                Record(new { Case = "independent-option-context-precondition", Recipe = root.Recipes.SelectedRecipeName, SelectedOption = root.Recipes.SelectedPipelineOption.PipelineName, XmlValid = root.Recipes.SelectedRecipeSummary.XmlValid, root.Recipes.HasSelectedRecipePersistenceFailure, MainActionText = root.MainActionText, ProviderPipeline = host.ActiveRecipeContextPipelineNameForTest });
                Require(root.Recipes.SelectedPipelineOption.PipelineName == "RenderOther" && root.Pipeline.SelectedPipelineName == "RenderOther" && root.MainActionText == "Switched to pipeline 'RenderOther'.", "two valid pipeline options really select before import guard test");
                root.Recipes.SelectedPipelineOption = root.Recipes.PipelineOptions.Single(option => option.PipelineName == originalPipeline);
                OpenVisionRecipeContextStore contextStore = (OpenVisionRecipeContextStore)typeof(OpenVisionShellHostView).GetField("recipeContextStore", BindingFlags.Instance | BindingFlags.NonPublic)!.GetValue(host)!;
                contextStore.Refresh();
                string contextPath = Path.Combine(directory, "context-not-imported.png");
                using (Bitmap bitmap = new(44, 28)) { bitmap.Save(contextPath, ImageFormat.Png); }
                int contextCount = images.Count;
                try
                {
                    host.Dispatcher.BeginInvoke(new Action(() =>
                    {
                        VisionPipelineStorage.SaveActivePipelineName(contextRecipe, "RenderOther"); contextStore.Refresh();
                        root.Recipes.SelectedPipelineOption = root.Recipes.PipelineOptions.Single(option => option.PipelineName == "RenderOther");
                    }), System.Windows.Threading.DispatcherPriority.Render);
                    int contextAdded = loader.AddWorkspaceImages(new[] { contextPath });
                    string switchedText = root.MainActionText;
                    Record(new { Case = "owned-provider-context-switch-at-render", BeforePipeline = originalPipeline, AfterPipeline = contextStore.Current.PipelineName, SelectedOption = root.Recipes.SelectedPipelineOption.PipelineName, Added = contextAdded, BeforeCount = contextCount, AfterCount = images.Count, MainActionText = switchedText, root.MainActionKind, Runs = host.NativePreviewRunCount, Boundary = "owned active pipeline persistence plus existing context store Refresh; not actual UI context transition" });
                    Require(contextAdded == 0 && images.Count == contextCount && contextStore.Current.PipelineName == "RenderOther" && switchedText == "Switched to pipeline 'RenderOther'." && root.MainActionKind != "Running", "provider context change aborts fresh import and existing switch completion replaces Opening");
                }
                finally
                {
                    VisionPipelineStorage.SaveActivePipelineName(contextRecipe, originalPipeline); contextStore.Refresh();
                    root.Recipes.SelectedPipelineOption = root.Recipes.PipelineOptions.Single(option => option.PipelineName == originalPipeline);
                }
                Require(loader.AddWorkspaceImages(new[] { contextPath }) == 1 && root.MainActionText == "Added 1 images" && root.MainActionKind != "Running", "fresh valid import recovers after context abort");
                OpenVisionShellHostView owned = CreateShellHost("Smoke_ImageStart_Dispose_" + width, false);
                OpenVisionWorkbenchViewModel ownedRoot = owned.Workbench;
                OpenVisionWorkbenchImagesViewModel ownedImages = ownedRoot.Images;
                OpenVisionShellHostCommandController ownedLoader = (OpenVisionShellHostCommandController)typeof(OpenVisionShellHostView).GetField("commandController", BindingFlags.Instance | BindingFlags.NonPublic)!.GetValue(owned)!;
                try
                {
                    owned.Dispatcher.BeginInvoke(new Action(owned.Dispose), System.Windows.Threading.DispatcherPriority.Render);
                    Require(ownedLoader.AddWorkspaceImages(new[] { path }) == 0 && ownedImages.Count == 0, "Host Dispose during render aborts old import");
                    Delegate subscriptions = (Delegate)typeof(OpenVisionWorkbenchImagesViewModel).GetField("ImportStarted", BindingFlags.Instance | BindingFlags.NonPublic)!.GetValue(ownedImages)!;
                    Require(subscriptions == null || !subscriptions.GetInvocationList().Any(item => ReferenceEquals(item.Target, ownedRoot)), "Root Dispose detaches start event");
                    Record(new { Case = "host-dispose-render-boundary", Added = 0, SubscriberDetached = true, Boundary = "owned unattached Host in-process; no native Window close claim" });
                }
                finally { owned.Dispose(); }
                Window mainWindow = Window.GetWindow(host)!;
                foreach (string visibilityState in new[] { "Hidden", "Minimized" })
                {
                    string visibilityPath = Path.Combine(directory, visibilityState + "-recovery.png");
                    using (Bitmap bitmap = new(46, 32)) { bitmap.Save(visibilityPath, ImageFormat.Png); }
                    int visibilityCount = images.Count;
                    host.Dispatcher.BeginInvoke(new Action(() => { if (visibilityState == "Hidden") mainWindow.Hide(); else mainWindow.WindowState = WindowState.Minimized; }), System.Windows.Threading.DispatcherPriority.Render);
                    try
                    {
                        int visibilityAdded = loader.AddWorkspaceImages(new[] { visibilityPath });
                        Require(visibilityAdded == 1 && images.Count == visibilityCount + 1 && root.MainActionKind != "Running", "worker completes while " + visibilityState);
                        Record(new { Case = "worker-visibility-completion", Visibility = visibilityState, ActualVisible = mainWindow.IsVisible, ActualState = mainWindow.WindowState.ToString(), mainWindow.IsLoaded, Added = visibilityAdded, BeforeCount = visibilityCount, Count = images.Count, ObserverAttached = false });
                    }
                    finally { mainWindow.WindowState = WindowState.Normal; mainWindow.Show(); Pump(2); }
                }
                OpenVisionShellHostView closingHost = CreateShellHost("Smoke_ImageStart_Close_" + width, false);
                OpenVisionWorkbenchImagesViewModel closingImages = closingHost.Workbench.Images;
                var closingLoader = (OpenVisionShellHostCommandController)typeof(OpenVisionShellHostView).GetField("commandController", BindingFlags.Instance | BindingFlags.NonPublic)!.GetValue(closingHost)!;
                Window closingWindow = new() { Content = closingHost, Width = 800, Height = 600, Left = -10000, Top = -10000, ShowInTaskbar = false };
                closingWindow.Show(); Pump(2);
                try
                {
                    bool closed = false;
                    closingWindow.Dispatcher.BeginInvoke(new Action(() => { closingWindow.Close(); closingHost.Dispose(); closed = true; }), System.Windows.Threading.DispatcherPriority.Render);
                    int closedAdded = closingLoader.AddWorkspaceImages(new[] { path });
                    bool released = !(bool)typeof(OpenVisionShellHostCommandController).GetField("importingWorkspaceImages", BindingFlags.Instance | BindingFlags.NonPublic)!.GetValue(closingLoader)!;
                    Require(closed && closedAdded == 0 && !closingWindow.IsLoaded && closingImages.Count == 0 && released, "normal owned Window close/Dispose observes worker and releases without publication");
                    Record(new { Case = "worker-normal-window-close-dispose", Closed = closed, closingWindow.IsLoaded, closingWindow.IsVisible, Added = closedAdded, Count = closingImages.Count, GuardReleased = released, Boundary = "owned in-process WPF Window; not native EXE close/shutdown" });
                }
                finally { closingHost.Dispose(); closingWindow.Close(); }
            }
        });
    }

    private static CaptureResult CaptureMainImageImportAction(string outputPath, int width, int height)
    {
        string directory = Path.GetDirectoryName(outputPath)!, recipe = "Smoke_ImportAction_" + Guid.NewGuid().ToString("N");
        VisionPipelineStorage.Save(recipe, new VisionPipeline { Name = "Main" }); VisionPipelineStorage.SaveActivePipelineName(recipe, "Main");
        string[] paths = { Path.Combine(directory, "import_A.png"), Path.Combine(directory, "import_B.png") };
        foreach (string path in paths) { using Bitmap bitmap = new(640, 360); using Graphics graphics = Graphics.FromImage(bitmap); graphics.Clear(DrawingColor.Teal); bitmap.Save(path, ImageFormat.Png); }
        OpenVisionShellHostView host = CreateShellHost(recipe, false);
        return CaptureWindowWithContent(host, outputPath, width, height, () =>
        {
            OpenVisionWorkbenchViewModel model = host.Workbench; OpenVisionWorkbenchImagesViewModel images = model.Images;
            OpenVisionShellHostCommandController loader = (OpenVisionShellHostCommandController)typeof(OpenVisionShellHostView).GetField("commandController", BindingFlags.Instance | BindingFlags.NonPublic)!.GetValue(host)!;
            List<object> cases = new(); List<string> failures = new(); int notifications = 0, runs = host.NativePreviewRunCount;
            byte[] working = VisionPipelineExecutionPlan.SerializePipeline(model.Pipeline.WorkingCopyForTest), saved = VisionPipelineExecutionPlan.SerializePipeline(VisionPipelineStorage.Load(recipe, "Main"));
            System.ComponentModel.PropertyChangedEventHandler observe = (_, e) => { if (e.PropertyName == nameof(OpenVisionWorkbenchViewModel.MainActionText)) notifications++; };
            model.PropertyChanged += observe;
            void Require(bool value, string message) { if (!value) failures.Add(message); }
            TextBlock action = FindNamedVisualChild<TextBlock>(host, "workbenchActionStatus")!;
            FrameworkElement icon = FindVisualChildren<FrameworkElement>(host).Single(item => AutomationProperties.GetAutomationId(item) == "WorkbenchActionIcon");
            void Record(string state, string boundary, string expected, string kind)
            {
                Pump(3); string capture = Path.Combine(directory, Path.GetFileNameWithoutExtension(outputPath) + "." + state + ".png");
                Rect bounds = GetElementBounds(host, action); bool pass = model.MainActionText == expected && action.Text == expected && model.MainActionKind == kind;
                Require(pass, state + ": " + action.Text + " expected " + expected + " / " + model.MainActionKind);
                var renderedIcon = (MahApps.Metro.IconPacks.PackIconMaterial)icon;
                Require(action.Foreground.ToString() == host.FindResource("OpenVision.Workbench.SecondaryTextBrush").ToString()
                    && renderedIcon.Foreground.ToString() == host.FindResource(kind == "Warning" ? "OpenVision.Workbench.StaleBrush" : "OpenVision.Workbench.SecondaryTextBrush").ToString()
                    && renderedIcon.Kind.ToString() == (kind == "Warning" ? "AlertOutline" : "InformationOutline") && Convert.ToString(action.ToolTip) == action.Text, state + " semantic roles/icon/full tooltip");
                Require(BindingOperations.IsDataBound(action, TextBlock.TextProperty) && action.IsVisible && icon.IsVisible && bounds.Left >= 0D && bounds.Right <= host.ActualWidth, state + " rendered binding/bounds");
                ScreenshotPngWriter.WriteElementPng(host, capture, width, height);
                cases.Add(new { State = state, Boundary = boundary, Expected = expected, Actual = action.Text, Kind = model.MainActionKind, Icon = model.MainActionIcon, Foreground = action.Foreground.ToString(), IconForeground = renderedIcon.Foreground.ToString(), Bounds = bounds, Tooltip = Convert.ToString(action.ToolTip), PASS = pass, Capture = capture, Count = images.Count, Current = images.CurrentIndex });
                File.WriteAllText(Path.ChangeExtension(outputPath, ".import-cases.json"), JsonSerializer.Serialize(new { Cases = cases, Failures = failures }, new JsonSerializerOptions { WriteIndented = true }));
            }
            try
            {
                OpenVisionLanguageService.SetLanguage(OpenVisionLanguage.Korean, false); Pump(3);
                int added = loader.AddWorkspaceImages(paths, "good"); Pump(4);
                Require(added == 2 && images.Count == 2 && images.CurrentIndex == 0 && images.Images.All(item => item.Label == "good"), "actual controller import/label/initial selection");
                Record("actual-valid-before-or-after", "Actual existing Controller valid A/B", "이미지 2장 추가", "");
                MethodInfo? notify = typeof(OpenVisionWorkbenchImagesViewModel).GetMethod("NotifyImportCompleted", BindingFlags.Instance | BindingFlags.NonPublic);
                if (notify == null) { File.WriteAllText(Path.ChangeExtension(outputPath, ".baseline.json"), JsonSerializer.Serialize(new { Added = added, Actual = action.Text, Expected = "이미지 2장 추가", Images = images.Count, Current = images.CurrentIndex, Runs = host.NativePreviewRunCount }, new JsonSerializerOptions { WriteIndented = true })); throw new InvalidOperationException(string.Join("; ", failures)); }
                try { model.AttachImages(null!); failures.Add("Null AttachImages accepted"); } catch (ArgumentNullException) { }
                int beforeNullRecovery = notifications; notify.Invoke(images, new object[] { 2, 0, 0 });
                Require(ReferenceEquals(model.Images, images) && notifications == beforeNullRecovery + 1 && model.MainActionText == "이미지 2장 추가", "null attachment retains prior publisher subscription");
                int layers = host.LayerDocumentCount; string initialInput = model.Shell.WorkspaceInputName;
                int count = notifications; Require(loader.AddWorkspaceImages(paths) == 0 && notifications == count + 2 && images.Count == 2 && model.Shell.WorkspaceInputName == initialInput, "actual duplicate-only zero completion preserves current");
