                FieldInfo running = typeof(OpenVisionWorkbenchPipelineViewModel).GetField("running", BindingFlags.Instance | BindingFlags.NonPublic)!;
                running.SetValue(model.Pipeline, true); typeof(OpenVisionWorkbenchPipelineViewModel).GetMethod("RaiseState", BindingFlags.Instance | BindingFlags.NonPublic)!.Invoke(model.Pipeline, null);
                count = notifications; prior = model.MainActionText; Require(loader.AddWorkspaceImages(paths) == 0 && notifications == count && model.MainActionText == prior, "busy guard no false completion");
                running.SetValue(model.Pipeline, false); typeof(OpenVisionWorkbenchPipelineViewModel).GetMethod("RaiseState", BindingFlags.Instance | BindingFlags.NonPublic)!.Invoke(model.Pipeline, null);
                foreach (string theme in new[] { "Dark", "Light" })
                foreach (OpenVisionLanguage language in new[] { OpenVisionLanguage.Korean, OpenVisionLanguage.English })
