                        if (entry.Item2 > 0) expected += ko ? $" · 실패 {entry.Item2}장" : $" · {entry.Item2} failed";
                        if (entry.Item3 > 0) expected += ko ? $" · 하위 폴더 {entry.Item3}장 제외" : $" · {entry.Item3} images in subfolders excluded";
                        count = notifications; notify.Invoke(images, new object[] { entry.Item1, entry.Item2, entry.Item3 });
                        Require(notifications == count + 1, "repeated specific completion notification");
                        Record(theme + "-" + language + "-" + entry.Item1 + "-" + entry.Item2 + "-" + entry.Item3, "Projection-only notification; not Controller corrupt/folder coverage", expected, entry.Item2 + entry.Item3 > 0 ? "Warning" : "");
                    }
                }
                notify.Invoke(images, new object[] { 2, 1, 3 });
                using (Bitmap decoded = new(paths[0])) { images.AddImages(new[] { new OpenVisionWorkbenchImageItem(Path.Combine(directory, "projection_list_item.png"), "projection", OpenVisionBitmapImagePreviewFactory.Create(decoded, 160)) }); }
                foreach (OpenVisionLanguage language in new[] { OpenVisionLanguage.Korean, OpenVisionLanguage.English, OpenVisionLanguage.Korean })
                {
                    OpenVisionLanguageService.SetLanguage(language, false); Pump(3);
                    Require(model.MainActionText == (language == OpenVisionLanguage.Korean ? "이미지 2장 추가 · 실패 1장 · 하위 폴더 3장 제외" : "Added 2 images · 1 failed · 3 images in subfolders excluded"), "captured counts survive list change/locale");
                }
                MethodInfo present = typeof(OpenVisionWorkbenchViewModel).GetMethod("PresentMainAction", BindingFlags.Instance | BindingFlags.NonPublic)!;
                present.Invoke(model, new object[] { "Workbench.Action.RecipeSaved", "Ok", "", "", "", "" }); prior = model.MainActionText;
                Require(!prior.Contains("2장") && model.MainActionKind == "Ok", "later unrelated action overwrites import");
                OpenVisionWorkbenchImagesViewModel replacement = new(model.Shell, _ => true, () => { });
                model.AttachImages(replacement); count = notifications; notify.Invoke(images, new object[] { 9, 0, 0 }); Require(notifications == count && model.MainActionText == prior, "old Images detached");
                notify.Invoke(replacement, new object[] { 1, 0, 0 }); Require(model.MainActionText == "이미지 1장 추가", "replacement subscribed");
                model.AttachImages(images); replacement.Dispose(); count = notifications; notify.Invoke(replacement, new object[] { 9, 0, 0 }); Require(notifications == count, "disposed Images suppression");
                var invariants = new { RunsUnchanged = host.NativePreviewRunCount == runs, WorkingUnchanged = working.SequenceEqual(VisionPipelineExecutionPlan.SerializePipeline(model.Pipeline.WorkingCopyForTest)), SavedUnchanged = saved.SequenceEqual(VisionPipelineExecutionPlan.SerializePipeline(VisionPipelineStorage.Load(recipe, "Main"))), LayersUnchangedAfterLoad = host.LayerDocumentCount == layers, CurrentInputPreserved = model.Shell.WorkspaceInputName == initialInput };
                Require(invariants.RunsUnchanged && invariants.WorkingUnchanged && invariants.SavedUnchanged && invariants.LayersUnchangedAfterLoad && invariants.CurrentInputPreserved, "no implicit Run/working/saved/layers/input change");
                FieldInfo eventField = typeof(OpenVisionWorkbenchImagesViewModel).GetField("ImportCompleted", BindingFlags.Instance | BindingFlags.NonPublic)!;
                model.Dispose(); Require(eventField.GetValue(images) == null, "Root Dispose unsubscribes Images completion");
                count = notifications; notify.Invoke(images, new object[] { 9, 0, 0 }); Require(notifications == count, "post-dispose no presentation");
                File.WriteAllText(Path.ChangeExtension(outputPath, ".checks.json"), JsonSerializer.Serialize(new { Cases = cases, Failures = failures, Invariants = invariants, AttachDetachDispose = true, NullAttachRetainsPublisher = true, NoopGuard = true, CapturedCountsLocale = true, Notifications = notifications, ProductSHA256 = Convert.ToHexString(SHA256.HashData(File.ReadAllBytes(typeof(OpenVisionShellHostView).Assembly.Location))) }, new JsonSerializerOptions { WriteIndented = true }));
                if (failures.Count > 0) throw new InvalidOperationException(string.Join("; ", failures));
            }
            finally { model.PropertyChanged -= observe; }
        });
    }

    private static CaptureResult CaptureMainToolTestAction(string outputPath, int width, int height, bool boundariesOnly = false)
    {
        string directory = Path.GetDirectoryName(outputPath)!, recipe = "Smoke_ToolAction_" + Guid.NewGuid().ToString("N");
        VisionPipeline saved = new() { Name = "Main" }; saved.Steps.Add(new VisionPipelineStep { Name = "Existing", ToolType = "Threshold", InputLayer = VisionRecipeRunner.DefaultInputLayer, OutputLayer = "ExistingOutput" });
        VisionPipelineStorage.Save(recipe, saved); VisionPipelineStorage.SaveActivePipelineName(recipe, "Main");
        OpenVisionShellHostView host = CreateShellHost(recipe, false);
        string imagePath = Path.Combine(directory, "tool_action_input.png");
        using (Bitmap image = new(640, 360)) { using Graphics graphics = Graphics.FromImage(image); graphics.Clear(DrawingColor.Teal); image.Save(imagePath, ImageFormat.Png); }
        List<object> cases = new(); List<string> failures = new();
        var names = new[] { ("Threshold", "이진화", "Threshold"), ("Filter", "필터", "Filter"), ("Morphology", "모폴로지", "Morphology"), ("Arithmetic", "이미지 연산", "Image Arithmetic"), ("Blob", "블롭", "Blob"), ("Contour", "컨투어", "Contour"), ("Line", "라인 측정", "Line Measure"), ("Matching", "패턴 매칭", "Pattern Matching"), ("EdgeBasedMatching", "형상 매칭", "Shape Matching (Edge Based)"), ("FeatureMatching", "특징점 매칭", "Feature Matching"), ("EdgeDetection", "에지 검출", "Edge Detection"), ("RotateAndScale", "회전·스케일", "Rotate / Scale"), ("AffineTransform", "아핀 변환", "Affine Transform"), ("Mean", "평균 밝기", "Mean Brightness"), ("HSV", "HSV 색 추출", "HSV Color Extract"), ("Histogram", "히스토그램 보정", "Histogram Correction") };
        return CaptureWindowWithContent(host, outputPath, width, height, () =>
        {
            OpenVisionWorkbenchViewModel model = host.Workbench; OpenVisionWorkbenchToolViewModel tool = model.Tool;
            TextBlock message = FindVisualChildren<TextBlock>(host).Single(label => AutomationProperties.GetAutomationId(label) == "WorkbenchActionStatus");
            byte[] beforeWorking = VisionPipelineExecutionPlan.SerializePipeline(model.Pipeline.WorkingCopyForTest), beforeSaved = VisionPipelineExecutionPlan.SerializePipeline(VisionPipelineStorage.Load(recipe, "Main"));
            int runs = host.NativePreviewRunCount, layers = host.LayerDocumentCount, notifications = 0;
            string inputHash = Convert.ToHexString(SHA256.HashData(File.ReadAllBytes(imagePath)));
            PropertyChangedEventHandler observe = (_, e) => { if (e.PropertyName == nameof(OpenVisionWorkbenchToolViewModel.NewTestActionKey)) notifications++; };
            tool.PropertyChanged += observe;
            try
            {
                foreach (bool withInput in new[] { false, true })
                {
                    int beforeLoadLayers = host.LayerDocumentCount;
                    if (withInput)
                    {
                        if (!host.LoadMainImageFromFileForTest(imagePath)) throw new InvalidOperationException("Owned input load failed.");
                        bool loadWorkingUnchanged = beforeWorking.SequenceEqual(VisionPipelineExecutionPlan.SerializePipeline(model.Pipeline.WorkingCopyForTest));
                        bool loadSavedUnchanged = beforeSaved.SequenceEqual(VisionPipelineExecutionPlan.SerializePipeline(VisionPipelineStorage.Load(recipe, "Main")));
                        bool loadNoRun = host.NativePreviewRunCount == runs, loadSourceUnchanged = inputHash == Convert.ToHexString(SHA256.HashData(File.ReadAllBytes(imagePath)));
                        cases.Add(new { Boundary = "Owned input load", BeforeLayers = beforeLoadLayers, AfterLayers = host.LayerDocumentCount, WorkingUnchanged = loadWorkingUnchanged, SavedUnchanged = loadSavedUnchanged, NoRun = loadNoRun, SourceUnchanged = loadSourceUnchanged });
                        File.WriteAllText(Path.ChangeExtension(outputPath, ".load-boundary.json"), JsonSerializer.Serialize(cases[^1], new JsonSerializerOptions { WriteIndented = true }));
                        if (!loadWorkingUnchanged || !loadSavedUnchanged || !loadNoRun || !loadSourceUnchanged) throw new InvalidOperationException("Input load changed working/saved/source or executed.");
                    }
                    layers = host.LayerDocumentCount;
                    foreach (var entry in names)
                    {
                        bool representative = entry.Item1 is "Threshold" or "EdgeBasedMatching" or "HSV" or "Histogram";
                        if (boundariesOnly && entry.Item1 != "Threshold") continue;
                        int activationLayers = host.LayerDocumentCount;
                        if ((withInput || width < 1400) && !representative) continue;
                        VISION_MENU menu = Enum.Parse<VISION_MENU>(entry.Item1); bool supportsAdd = entry.Item1 is not "HSV" and not "Histogram";
                        int previous = notifications;
                        Button? quick = FindVisualChildren<Button>(host).SingleOrDefault(button => AutomationProperties.GetAutomationId(button) == "WorkbenchQuickTool_" + entry.Item1 && button.IsVisible);
                        if (quick != null && entry.Item1 is "Threshold" or "Matching" or "Line") { quick.Command.Execute(quick.CommandParameter); }
                        else { host.SelectToolForTest(menu); }
                        Pump(5);
                        if (!tool.IsNewTest || notifications != previous + 1 || tool.CanAddToPipeline != supportsAdd) throw new InvalidOperationException("Activation/capability contract failed for " + entry.Item1);
                        if (entry.Item1 is "Matching" or "EdgeBasedMatching" or "FeatureMatching" && tool.HasTemplate) throw new InvalidOperationException("Owned unregistered-template premise failed for " + entry.Item1);
                        if (!host.InputBindings.OfType<KeyBinding>().Any(key => key.Key == Key.F8 && ReferenceEquals(key.Command, tool.RunCommand))) throw new InvalidOperationException("Existing F8 binding does not use Tool.RunCommand.");
                        Button add = FindVisualChildren<Button>(host).Single(button => AutomationProperties.GetAutomationId(button) == "VisionToolAddPipelineButton" && button.IsVisible);
                        if (add.IsEnabled != supportsAdd || tool.AddAfterCommand.CanExecute(null) != supportsAdd) throw new InvalidOperationException("Bound Add capability mismatch for " + entry.Item1);
                        foreach (string palette in representative && !boundariesOnly ? new[] { "Dark", "Light" } : new[] { "Dark" })
                        {
                            (palette == "Dark" ? model.SelectDarkThemeCommand : model.SelectLightThemeCommand).Execute(null); Pump(3);
                            foreach (OpenVisionLanguage language in boundariesOnly ? new[] { OpenVisionLanguage.English } : new[] { OpenVisionLanguage.Korean, OpenVisionLanguage.English })
                            {
                                OpenVisionLanguageService.SetLanguage(language, false); Pump(3);
                                string expected = language == OpenVisionLanguage.Korean ? entry.Item2 + " 테스트 · F8: 실행" + (supportsAdd ? " · Ctrl+Enter: 파이프라인에 추가" : "") : entry.Item3 + " test · F8: run" + (supportsAdd ? " · Ctrl+Enter: add to pipeline" : "");
                                if (model.MainActionText != expected || message.Text != expected || model.MainActionKind != "" || notifications != previous + 1) throw new InvalidOperationException("Localized completed action mismatch for " + entry.Item1);
                                AssertElementWithinAncestor("Tool action", message, host);
                                double textWidth = new FormattedText(expected, CultureInfo.CurrentCulture, FlowDirection.LeftToRight, new Typeface(message.FontFamily, message.FontStyle, message.FontWeight, message.FontStretch), message.FontSize, message.Foreground, VisualTreeHelper.GetDpi(message).PixelsPerDip).Width;
                                bool readable = textWidth <= message.ActualWidth;
                                if (!readable) failures.Add(entry.Item1 + "/" + palette + "/" + language + "/input=" + withInput + " W09 " + textWidth + ">" + message.ActualWidth);
                                string? capture = null;
                                if (!boundariesOnly && (entry.Item1 is "Threshold" or "EdgeBasedMatching" or "HSV" or "Histogram")) { capture = Path.ChangeExtension(outputPath, "." + entry.Item1 + "." + withInput + "." + palette + "." + language + ".png"); ScreenshotPngWriter.WriteDpiAwareWindowPng(Window.GetWindow(host), capture); }
                                cases.Add(new { Tool = entry.Item1, WithInput = withInput, Palette = palette, Language = language.ToString(), SupportsAdd = supportsAdd, Expected = expected, Actual = message.Text, TextWidth = textWidth, AvailableWidth = message.ActualWidth, Readable = readable, Capture = capture, Notifications = notifications });
                                File.WriteAllText(Path.ChangeExtension(outputPath, ".progress.json"), JsonSerializer.Serialize(new { Cases = cases, Failures = failures, Notifications = notifications, F8BindingSameCommand = true, BoundAddEnabled = add.IsEnabled, NoRun = host.NativePreviewRunCount == runs }, new JsonSerializerOptions { WriteIndented = true }));
                            }
                        }
                        OpenVisionLanguageService.SetLanguage(OpenVisionLanguage.Korean, false); Pump(3);
                        string korean = entry.Item2 + " 테스트 · F8: 실행" + (supportsAdd ? " · Ctrl+Enter: 파이프라인에 추가" : "");
                        if (model.MainActionText != korean || notifications != previous + 1) throw new InvalidOperationException("KO return changed activation identity.");
                        OpenVisionLanguageService.SetLanguage(OpenVisionLanguage.English, false); Pump(3);
                        model.Recipes.SaveRecipeCommand.Execute(null); Pump(3); string savedAction = model.MainActionText;
                        typeof(OpenVisionWorkbenchToolViewModel).GetMethod("RaiseState", BindingFlags.Instance | BindingFlags.NonPublic)!.Invoke(tool, null); Pump(3);
                        if (model.MainActionText != savedAction || savedAction != OpenVisionLanguageService.T("Workbench.Action.RecipeSaved")) throw new InvalidOperationException("General tool state overwrote completed save.");
                        if (!host.CloseActiveWpfToolWindowForTest()) throw new InvalidOperationException("Tool close failed."); Pump(3);
                        host.SelectToolForTest(menu); Pump(3);
                        if (notifications != previous + 2 || !tool.IsNewTest) throw new InvalidOperationException("Same-tool reopen notification missing.");
                        host.CloseActiveWpfToolWindowForTest(); Pump(3);
                        if (host.LayerDocumentCount != activationLayers || host.NativePreviewRunCount != runs) throw new InvalidOperationException("Activation/reopen changed layers or executed.");
                    }
                }
                Type bindingType = typeof(OpenVisionWorkbenchToolViewModel).GetNestedType("EditorBinding", BindingFlags.NonPublic)!;
                object binding = Activator.CreateInstance(bindingType, true)!;
                void Bind(string name, object value) => bindingType.GetProperty(name, BindingFlags.Instance | BindingFlags.NonPublic)!.SetValue(binding, value);
                Bind("ToolName", "Threshold"); Bind("DisplayName", (Func<string>)(() => "Threshold")); Bind("CreateStep", (Func<VisionPipelineStep>)(() => new VisionPipelineStep { ToolType = "Threshold" })); Bind("ApplyStep", (Action<VisionPipelineStep>)(_ => { })); Bind("SupportsPipeline", true); Bind("IsRunning", (Func<bool>)(() => false)); Bind("LoadParameters", (Func<OpenVisionRecipeContext, object>)(_ => new object())); Bind("CaptureParameters", (Func<object>)(() => new object())); Bind("RestoreParameters", (Action<object>)(_ => { })); Bind("TemplateReady", (Func<bool>)(() => true));
                MethodInfo activate = typeof(OpenVisionWorkbenchToolViewModel).GetMethod("Activate", BindingFlags.Instance | BindingFlags.NonPublic)!;
                int count = notifications; string priorAction = model.MainActionText;
                activate.Invoke(tool, new object?[] { null, binding, 0 }); Pump(3);
                if (!tool.IsStepEditing || notifications != count || model.MainActionText != priorAction) throw new InvalidOperationException("Existing step was announced as new test.");
                try { activate.Invoke(tool, new object?[] { null, binding, int.MaxValue }); throw new InvalidOperationException("Invalid activation unexpectedly succeeded."); } catch (TargetInvocationException e) when (e.InnerException is ArgumentOutOfRangeException) { }
                if (notifications != count || model.MainActionText != priorAction) throw new InvalidOperationException("Failed activation produced completion.");
                Bind("RestoreParameters", (Action<object>)(_ => throw new InvalidOperationException("Owned initialization failure")));
                try { activate.Invoke(tool, new object?[] { null, binding, -1 }); throw new InvalidOperationException("Initialization failure unexpectedly succeeded."); } catch (TargetInvocationException e) when (e.InnerException is InvalidOperationException failure && failure.Message == "Owned initialization failure") { }
                if (notifications != count || model.MainActionText != priorAction) throw new InvalidOperationException("Failed new-test initialization produced completion.");
                host.SelectToolForTest(VISION_MENU.Threshold); Pump(3);
                if (notifications != count + 1 || !tool.IsNewTest || model.MainActionText != "Threshold test · F8: run · Ctrl+Enter: add to pipeline") throw new InvalidOperationException("New-test recovery did not produce its exact completion.");
                host.CloseActiveWpfToolWindowForTest(); Pump(3);
                var invariants = new { WorkingUnchanged = beforeWorking.SequenceEqual(VisionPipelineExecutionPlan.SerializePipeline(model.Pipeline.WorkingCopyForTest)), SavedUnchanged = beforeSaved.SequenceEqual(VisionPipelineExecutionPlan.SerializePipeline(VisionPipelineStorage.Load(recipe, "Main"))), BeforeRuns = runs, AfterRuns = host.NativePreviewRunCount, BeforeActivationLayers = layers, AfterLayers = host.LayerDocumentCount, InputUnchanged = inputHash == Convert.ToHexString(SHA256.HashData(File.ReadAllBytes(imagePath))) };
                File.WriteAllText(Path.ChangeExtension(outputPath, ".invariants.json"), JsonSerializer.Serialize(invariants, new JsonSerializerOptions { WriteIndented = true }));
                if (!invariants.WorkingUnchanged || !invariants.SavedUnchanged || invariants.BeforeRuns != invariants.AfterRuns || invariants.BeforeActivationLayers != invariants.AfterLayers || !invariants.InputUnchanged) throw new InvalidOperationException("Tool completion changed working/saved/input/layers/execution: " + JsonSerializer.Serialize(invariants));
                File.WriteAllText(Path.ChangeExtension(outputPath, ".checks.json"), JsonSerializer.Serialize(new { Cases = cases, Failures = failures, Notifications = notifications, Invariants = invariants, NoRun = true, WorkingSavedInputLayersUnchanged = true, ExistingStepNoCompletion = true, FailedActivationNoCompletion = true, InitializationFailureNoCompletion = true, RecoveryCompletion = true, F8BindingSameCommand = true, ProductSHA = Convert.ToHexString(SHA256.HashData(File.ReadAllBytes(typeof(OpenVisionShellHostView).Assembly.Location))) }, new JsonSerializerOptions { WriteIndented = true }));
                if (failures.Count > 0) throw new InvalidOperationException(string.Join("; ", failures));
            }
            finally { tool.PropertyChanged -= observe; }
        });
    }

    private static int CheckImageQuantityCopy(string outputPath, string key)
    {
        (string Korean, string OldEnglish, string English) expected = key switch
        {
            "Workbench.Action.ImagesAddedFormat" => ("이미지 {0}장 추가", "Added {0} images", "Images added: {0}"),
            "Workbench.Action.ImagesOpeningFormat" => ("이미지 {0}장을 여는 중…", "Opening {0} images…", "Opening images: {0}…"),
            _ => throw new ArgumentOutOfRangeException(nameof(key))
        };
        string dataRoot = AppPathService.DataRootDirectory;
        OpenVisionLanguageService.ReloadCatalog(false);
        string catalog = OpenVisionLanguageService.CatalogPath;
        if (!Path.GetFullPath(catalog).StartsWith(Path.GetFullPath(dataRoot) + Path.DirectorySeparatorChar, StringComparison.OrdinalIgnoreCase)
            || !Path.GetFullPath(catalog).StartsWith(@"D:\OpenVisionLab-TestData\", StringComparison.OrdinalIgnoreCase)) throw new InvalidOperationException("Added-count contract requires isolated D: CONFIG.");
        byte[] original = File.ReadAllBytes(catalog); OpenVisionLanguage language = OpenVisionLanguageService.CurrentLanguage;
        List<object> cases = new();
        void Require(bool value, string name) { if (!value) throw new InvalidOperationException(name); cases.Add(new { Case = name, PASS = true }); }
        try
        {
            var current = OpenVisionLanguageService.GetDefaultEntries("Workbench.Action.").Single(item => item.Key == key);
            Require(current.Korean == expected.Korean && current.English == expected.English, "shipped key/KO/single numeric placeholder and EN copy");
            foreach (var pair in new[] { (Ko: expected.Korean, En: expected.OldEnglish, Migrate: true), (Ko: "사용자 {0}장", En: "Custom count {0}", Migrate: false), (Ko: "사용자 {0}장", En: expected.OldEnglish, Migrate: false), (Ko: expected.Korean, En: "Custom count {0}", Migrate: false), (Ko: expected.OldEnglish, En: expected.Korean, Migrate: false), (Ko: expected.Korean, En: expected.English, Migrate: false) })
            {
                List<OpenVisionLocalizationEntry> entries = OpenVisionLanguageService.GetEntries().ToList();
                OpenVisionLocalizationEntry entry = entries.Single(item => item.Key == key); entry.Korean = pair.Ko; entry.English = pair.En;
                OpenVisionLanguageService.SaveEntries(entries); OpenVisionLanguageService.ReloadCatalog(false);
                var actual = OpenVisionLanguageService.GetEntries().Single(item => item.Key == key);
                Require(actual.Korean == (pair.Migrate ? current.Korean : pair.Ko) && actual.English == (pair.Migrate ? current.English : pair.En), "exact old/custom/partial/mixed/current pair: " + pair.Ko + " / " + pair.En);
                byte[] first = File.ReadAllBytes(catalog); OpenVisionLanguageService.ReloadCatalog(false);
                Require(first.SequenceEqual(File.ReadAllBytes(catalog)), "reload idempotent: " + pair.Ko + " / " + pair.En);
            }
            foreach (int count in new[] { 0, 1, 2 })
            {
                OpenVisionLanguageService.SetLanguage(OpenVisionLanguage.Korean, false); Require(string.Format(CultureInfo.InvariantCulture, OpenVisionLanguageService.T(key), count) == string.Format(CultureInfo.InvariantCulture, expected.Korean, count), "KO count " + count);
                OpenVisionLanguageService.SetLanguage(OpenVisionLanguage.English, false); Require(string.Format(CultureInfo.InvariantCulture, OpenVisionLanguageService.T(key), count) == string.Format(CultureInfo.InvariantCulture, expected.English, count), "EN count " + count);
            }
        }
        finally
        {
            File.WriteAllBytes(catalog, original); OpenVisionLanguageService.ReloadCatalog(false); OpenVisionLanguageService.SetLanguage(language, false);
            Require(original.SequenceEqual(File.ReadAllBytes(catalog)), "owned CONFIG bytes restored");
        }
        Directory.CreateDirectory(Path.GetDirectoryName(Path.GetFullPath(outputPath))!);
        File.WriteAllText(outputPath, JsonSerializer.Serialize(new { Key = key, Cases = cases, Catalog = catalog, UIWindowsCreated = false, Scope = "Selected quantity key only; nonvisual CONFIG/migration/format contract; no Main rendering or actual GUI/native DPI" }, new JsonSerializerOptions { WriteIndented = true }));
        Console.WriteLine(key + "=OK | Cases=" + cases.Count + " | UIWindowsCreated=false");
        return 0;
    }

    private static CaptureResult CaptureMainImageCountCopy(string outputPath)
    {
        const string key = "Workbench.Run.ImageCountFormat";
        string dataRoot = AppPathService.DataRootDirectory;
        OpenVisionLanguageService.ReloadCatalog(false);
        string catalog = OpenVisionLanguageService.CatalogPath;
        if (!Path.GetFullPath(catalog).StartsWith(Path.GetFullPath(dataRoot) + Path.DirectorySeparatorChar, StringComparison.OrdinalIgnoreCase)
            || !Path.GetFullPath(catalog).StartsWith(@"D:\OpenVisionLab-TestData\", StringComparison.OrdinalIgnoreCase)) throw new InvalidOperationException("Caption contract requires isolated D: CONFIG.");
        byte[] original = File.ReadAllBytes(catalog); OpenVisionLanguage language = OpenVisionLanguageService.CurrentLanguage;
        List<object> cases = new();
        void Require(bool value, string name) { if (!value) throw new InvalidOperationException(name); cases.Add(new { Case = name, PASS = true }); }
        void Store(string ko, string en)
        {
            List<OpenVisionLocalizationEntry> entries = OpenVisionLanguageService.GetEntries().ToList();
            OpenVisionLocalizationEntry entry = entries.Single(item => item.Key == key); entry.Korean = ko; entry.English = en;
            OpenVisionLanguageService.SaveEntries(entries);
        }
        try
        {
            var current = OpenVisionLanguageService.GetDefaultEntries("Workbench.Run.").Single(item => item.Key == key);
            Require(current.Korean == "{0}장" && current.English == "Images: {0}", "shipped KO/key/placeholder preserved; EN category caption");
            foreach (var pair in new[] { (Ko: "{0}장", En: "{0} images", Migrate: true), (Ko: "사용자 {0}장", En: "Custom count {0}", Migrate: false), (Ko: "사용자 {0}장", En: "{0} images", Migrate: false), (Ko: "{0}장", En: "Custom count {0}", Migrate: false), (Ko: "{0} images", En: "{0}장", Migrate: false), (Ko: "{0}장", En: "Images: {0}", Migrate: false) })
            {
                Store(pair.Ko, pair.En); OpenVisionLanguageService.ReloadCatalog(false);
                var actual = OpenVisionLanguageService.GetEntries().Single(item => item.Key == key);
                Require(actual.Korean == (pair.Migrate ? current.Korean : pair.Ko) && actual.English == (pair.Migrate ? current.English : pair.En), "exact default/custom/partial/mixed pair: " + pair.Ko + " / " + pair.En);
                byte[] first = File.ReadAllBytes(catalog); OpenVisionLanguageService.ReloadCatalog(false);
                Require(first.SequenceEqual(File.ReadAllBytes(catalog)), "reload idempotent: " + pair.Ko + " / " + pair.En);
            }
            Store(current.Korean, current.English);
            foreach (int count in new[] { 1, 12 })
            {
                OpenVisionLanguageService.SetLanguage(OpenVisionLanguage.Korean, false); Require(string.Format(CultureInfo.CurrentCulture, OpenVisionLanguageService.T(key), count) == count + "장", "KO count " + count);
                OpenVisionLanguageService.SetLanguage(OpenVisionLanguage.English, false); Require(string.Format(CultureInfo.CurrentCulture, OpenVisionLanguageService.T(key), count) == "Images: " + count, "EN count " + count);
            }
            OpenVisionShellHostView host = CreateShellHost("Smoke_CountCopy_" + Guid.NewGuid().ToString("N"), false);
            return CaptureWindowWithContent(host, outputPath, 1600, 900, () =>
            {
                string input = Path.ChangeExtension(outputPath, ".input.png");
                using (Bitmap bitmap = new(32, 24)) { using Graphics graphics = Graphics.FromImage(bitmap); graphics.Clear(DrawingColor.Gray); bitmap.Save(input, ImageFormat.Png); }
                Require(host.LoadMainImageFromFileForTest(input), "owned first image"); Pump(3);
                TextBlock caption = FindNamedVisualChild<TextBlock>(host, "mainBatchCountText")!;
                Store("{0}장", "{0} images"); OpenVisionLanguageService.SetLanguage(OpenVisionLanguage.Korean, false); OpenVisionLanguageService.SetLanguage(OpenVisionLanguage.English, false); Pump(3);
                Require(caption.Text == "1 images", "reconstructed old stored caption before migration");
                ScreenshotPngWriter.WriteElementPng(host, Path.ChangeExtension(outputPath, ".before-old-default.png"), 1600, 900);
                OpenVisionLanguageService.ReloadCatalog(); Pump(3);
                foreach (int count in new[] { 1, 12 })
                {
                    if (count == 12)
                    {
                        var extra = Enumerable.Range(2, 11).Select(index => { string path = Path.Combine(Path.GetDirectoryName(outputPath)!, "caption_" + index + ".png"); File.Copy(input, path); return new OpenVisionWorkbenchImageItem(path, Path.GetFileName(path), OpenVisionBitmapImagePreviewFactory.CreateFromPath(path)); }).ToArray();
                        host.Workbench.Images.AddImages(extra); Pump(3);
                    }
                    foreach (int width in new[] { 1600, 1280 })
                    {
                        Window parent = Window.GetWindow(host); parent.Width = width; parent.Height = width == 1600 ? 900 : 760; Pump(4); host.UpdateLayout();
                        Require(host.Workbench.Images.Count == count && caption.IsVisible && caption.Text == "Images: " + count, "actual Main bound EN count " + count + " width " + width);
                        var measured = new FormattedText(caption.Text, CultureInfo.CurrentCulture, caption.FlowDirection, new Typeface(caption.FontFamily, caption.FontStyle, caption.FontWeight, caption.FontStretch), caption.FontSize, caption.Foreground, VisualTreeHelper.GetDpi(caption).PixelsPerDip);
                        Require(caption.ActualWidth + 0.5D >= measured.WidthIncludingTrailingWhitespace, "required count glyphs fit " + count + " width " + width);
                        ScreenshotPngWriter.WriteElementPng(host, Path.ChangeExtension(outputPath, ".en-" + count + "-" + width + ".png"), width, width == 1600 ? 900 : 760);
                    }
                }
                File.WriteAllText(Path.ChangeExtension(outputPath, ".checks.json"), JsonSerializer.Serialize(new { Cases = cases, Catalog = catalog, BeforeCaption = "Current-build reconstruction using the exact old stored pair before ReloadCatalog migration", Scope = "Only this key/config/override pair and count1/12 at1600/1280; no real GUI/native DPI claim" }, new JsonSerializerOptions { WriteIndented = true }));
            });
        }
        finally
        {
            File.WriteAllBytes(catalog, original); OpenVisionLanguageService.ReloadCatalog(false); OpenVisionLanguageService.SetLanguage(language, false);
            if (!original.SequenceEqual(File.ReadAllBytes(catalog))) throw new InvalidOperationException("Owned CONFIG bytes were not restored.");
        }
    }

    private static CaptureResult CaptureMainRedockKeyboardFocus(string outputPath)
    {
        GlobalState global = new(); global.Recipe.Name = "Smoke_RedockFocus_" + Guid.NewGuid().ToString("N");
        VisionPipeline source = new() { Name = "Main" }; source.Steps.Add(VisionPipelineStepBuilder.FromProperty(new BlobProperty("Blob") { PIXELPERMM = 0.036, USE_ROI = false, CvROI = new OpenCvSharp.Rect(0, 0, 32, 24) }, "Main", "Focus_Blob"));
        VisionPipelineStorage.Save(global.Recipe.Name, source); VisionPipelineStorage.SaveActivePipelineName(global.Recipe.Name, "Main"); global.System.SaveWorkbenchLayout(new SystemStateConfig());
        using DisplayManagerService display = new();
        OpenVisionShellHostWindow window = new(new ApplicationRuntimeContext(global, display)); window.ClearValue(OpenVisionShellHostWindow.ClosingCommandProperty);
        OpenVisionShellHostView host = window.ShellHostForSmoke;
        return CaptureStandaloneWindow(window, outputPath, 1600, 900, () =>
        {
            File.WriteAllText(Path.ChangeExtension(outputPath, ".monitor.txt"), SmokeWindowMonitorPlacement.PlaceOnLeftmostMonitor(window));
            window.Activate(); Pump(3);
            var tool = host.Workbench.Tool; var pipeline = host.Workbench.Pipeline;
            tool.OpenStepRequested!(0); Pump(6);
            OpenVisionNativeToolDocument document = host.ActiveNativeDocumentForTest!;
            FrameworkElement view = document.View;
            var grid = FindVisualChildren<System.Windows.Controls.WpfPropertyGrid.PropertyGrid>(view).Single(item => item.IsVisible && item.SelectedObject is BlobProperty);
            object property = grid.SelectedObject;
            TextBox editor = FindVisualChildren<TextBox>(grid).First(item => item.IsVisible && item.IsEnabled && !item.IsReadOnly && item.Text == "0.036");
            editor.SetCurrentValue(TextBox.TextProperty, "0.042");
            if (!tool.CommitPendingEdits() || !pipeline.IsDirty) throw new InvalidOperationException("Owned dirty editor precondition failed.");
            byte[] working = VisionPipelineExecutionPlan.SerializePipeline(pipeline.WorkingCopyForTest);
            string path = RecipeWorkspaceService.GetVisionPipelinePath(global.Recipe.Name, "Main"); byte[] saved = File.ReadAllBytes(path);
            int runs = host.NativePreviewRunCount, layers = host.LayerDocumentCount; string route = host.ActiveHostLayerTitle;
            if (!host.FloatDockedWpfToolWindowForTest()) throw new InvalidOperationException("Could not float owned editor."); Pump(5);
            OpenVisionFloatingToolWindow floating = Window.GetWindow(view) as OpenVisionFloatingToolWindow ?? throw new InvalidOperationException("Owned editor is not hosted by its floating window.");
            File.AppendAllText(Path.ChangeExtension(outputPath, ".monitor.txt"), Environment.NewLine + SmokeWindowMonitorPlacement.PlaceOnLeftmostMonitor(floating));
            Button dock = FindVisualChildren<Button>(floating).Single(item => AutomationProperties.GetAutomationId(item) == "OpenVisionDockToolButton");
            floating.Activate(); dock.Focus(); Pump(3);
            bool dockFocused = dock.IsKeyboardFocused;
            dock.RaiseEvent(new RoutedEventArgs(Button.ClickEvent)); Pump(10);
            DependencyObject? focused = Keyboard.FocusedElement as DependencyObject;
            Window? focusedWindow = focused == null ? null : Window.GetWindow(focused);
            bool focusInMain = ReferenceEquals(focusedWindow, window) && focused is UIElement target && target.IsVisible && target.IsEnabled;
            var observation = new { DockFocusedBefore = dockFocused, MainActiveAfter = window.IsActive, FocusTypeAfter = focused?.GetType().FullName, FocusNameAfter = (focused as FrameworkElement)?.Name, FocusWindowAfter = focusedWindow?.GetType().FullName, FocusInMain = focusInMain, SameDocument = ReferenceEquals(document, host.ActiveNativeDocumentForTest), SameProperty = ReferenceEquals(property, grid.SelectedObject), WorkingUnchanged = working.SequenceEqual(VisionPipelineExecutionPlan.SerializePipeline(pipeline.WorkingCopyForTest)), SavedUnchanged = saved.SequenceEqual(File.ReadAllBytes(path)), RunsUnchanged = runs == host.NativePreviewRunCount, LayersUnchanged = layers == host.LayerDocumentCount, RouteUnchanged = route == host.ActiveHostLayerTitle };
            File.WriteAllText(Path.ChangeExtension(outputPath, ".focus.json"), JsonSerializer.Serialize(observation, new JsonSerializerOptions { WriteIndented = true }));
            if (!dockFocused) throw new InvalidOperationException("Fixture did not focus the floating Dock button before return.");
            if (!focusInMain || !window.IsActive) throw new InvalidOperationException("Redock did not restore an active Main keyboard focus target; no manual refocus was applied.");
            if (!observation.SameDocument || !observation.SameProperty || !observation.WorkingUnchanged || !observation.SavedUnchanged || !observation.RunsUnchanged || !observation.LayersUnchanged || !observation.RouteUnchanged) throw new InvalidOperationException("Redock changed editor/working/saved/execution/layer/route state.");
            KeyBinding save = window.InputBindings.OfType<KeyBinding>().Single(item => item.Key == Key.S && item.Modifiers == ModifierKeys.Control);
            if (!ReferenceEquals(save.Command, host.Workbench.Recipes.SaveRecipeCommand) || !save.Command.CanExecute(save.CommandParameter)) throw new InvalidOperationException("Main Ctrl+S command contract is unavailable.");
            save.Command.Execute(save.CommandParameter);
            if (pipeline.IsDirty || host.Workbench.Recipes.HasRecipeSaveFailure || VisionPipelineStorage.Load(global.Recipe.Name, "Main").Steps[0].Parameters["PIXELPERMM"] != "0.042") throw new InvalidOperationException("Existing Main keyboard-binding command did not save the same editor value.");
            ScreenshotPngWriter.WriteElementPng(window, Path.ChangeExtension(outputPath, ".restored.png"), 1600, 900);
            if (!host.FloatDockedWpfToolWindowForTest()) throw new InvalidOperationException("Could not prepare invalidated dock return."); Pump(3);
            floating = Window.GetWindow(view) as OpenVisionFloatingToolWindow ?? throw new InvalidOperationException("Invalidation fixture lost its owned floating view.");
            dock = FindVisualChildren<Button>(floating).Single(item => AutomationProperties.GetAutomationId(item) == "OpenVisionDockToolButton");
            floating.Activate(); dock.Focus(); Pump(2);
            dock.RaiseEvent(new RoutedEventArgs(Button.ClickEvent));
            if (!host.CloseActiveWpfToolWindowForTest()) throw new InvalidOperationException("Could not invalidate content before queued focus restoration.");
            Button sentinel = FindVisualChildren<Button>(host).Single(item => item.IsVisible && AutomationProperties.GetAutomationId(item) == "HostRecipeSaveButton");
            bool sentinelFocused = sentinel.Focus(); Pump(10);
            bool invalidatedNoOp = sentinelFocused && sentinel.IsKeyboardFocused && Window.GetWindow(view) == null && !tool.IsOpen;
            if (!invalidatedNoOp || runs != host.NativePreviewRunCount || layers != host.LayerDocumentCount || route != host.ActiveHostLayerTitle || pipeline.IsDirty) throw new InvalidOperationException("Queued dock focus did not leave closed content and the current Main focus/state alone.");
            File.WriteAllText(Path.ChangeExtension(outputPath, ".checks.json"), JsonSerializer.Serialize(new { observation, MainBindingCommandSaved = true, ClosedContentQueuedFocusNoOp = invalidatedNoOp, ProductSHA256 = Convert.ToHexString(SHA256.HashData(File.ReadAllBytes(typeof(OpenVisionShellHostView).Assembly.Location))), Scope = "In-process Window focus and binding-command checks; no physical Ctrl+S or input-delivery claim" }, new JsonSerializerOptions { WriteIndented = true }));
        });
    }

    private static CaptureResult CaptureMainTeachingResultRetention(string outputPath)
    {
        string recipe = "Smoke_TeachingResult_" + Guid.NewGuid().ToString("N");
        VisionPipelineStep step = VisionPipelineStepBuilder.FromProperty(new BlobProperty("Blob") { PIXELPERMM = 0.006, USE_ROI = false, USE_THRESHOLD = false, CvROI = new OpenCvSharp.Rect(0, 0, 64, 48) }, "Main", "Blob_Teaching");
        step.UseAcceptance = true; step.AcceptanceMetricName = "ResultCount";
        step.UseAcceptanceMetricMinimum = true; step.AcceptanceMetricMinimum = 1;
        step.UseAcceptanceMetricMaximum = true; step.AcceptanceMetricMaximum = 1;
        VisionPipeline source = new() { Name = "Main" }; source.Steps.Add(step);
        VisionPipelineStorage.Save(recipe, source); VisionPipelineStorage.SaveActivePipelineName(recipe, "Main");
        OpenVisionShellHostView host = CreateShellHost(recipe, false);
        return CaptureWindowWithContent(host, outputPath, 1600, 900, () =>
        {
            var root = host.Workbench; var pipeline = root.Pipeline; var tool = root.Tool;
            List<string> cases = new();
            void Require(bool condition, string name) { if (!condition) throw new InvalidOperationException(name); cases.Add(name); }
            string imagePath = Path.ChangeExtension(outputPath, ".input.png");
            using (Bitmap image = new(64, 48)) { using Graphics graphics = Graphics.FromImage(image); graphics.Clear(DrawingColor.Black); graphics.FillRectangle(System.Drawing.Brushes.White, 16, 12, 24, 20); image.Save(imagePath, ImageFormat.Png); }
            Require(host.LoadMainImageFromFileForTest(imagePath), "owned one-component binary input"); Pump(3);
            tool.OpenStepRequested!(0); Pump(6);
            OpenVisionNativeToolDocument document = host.ActiveNativeDocumentForTest!;
            BlobToolWpfView view = (BlobToolWpfView)document.View;
            void Wait() { Stopwatch clock = Stopwatch.StartNew(); while (document.IsPreviewRunning && clock.ElapsedMilliseconds < 10000) { Pump(2); Thread.Sleep(2); } Pump(3); Require(!document.IsPreviewRunning, "native preview completed"); }
            void Detection(string name) => Require(tool.CurrentResult?.Metrics.GetValueOrDefault("ResultCount") == 1 && tool.CurrentResult.Success && !tool.CurrentResult.IsAcceptanceNg && !tool.IsResultPrevious, name);
            WaitForTaskWithPump(pipeline.RunForTestAsync(), 20000, "explicit F5 pipeline"); Detection("F5 retains real one-object OK judgment");
            tool.RunCommand.Execute(null); Wait(); Detection("F8 retains real detector OK judgment");
            VisionPipelineStepResultSummary retained = tool.CurrentResult!;
            string path = RecipeWorkspaceService.GetVisionPipelinePath(recipe, "Main"); byte[] saved = File.ReadAllBytes(path);
            string inputRoute = document.RouteInputLayerName, outputRoute = document.RouteOutputLayerName, active = host.ActiveHostLayerTitle;
            int layers = host.LayerDocumentCount, executionActions = 0;
            tool.PropertyChanged += (_, args) => { if (args.PropertyName == nameof(OpenVisionWorkbenchToolViewModel.ExecutionActionKey)) { executionActions++; } };
            var grid = FindVisualChildren<System.Windows.Controls.WpfPropertyGrid.PropertyGrid>(view).Single(item => item.IsVisible && item.SelectedObject is BlobProperty);
            TextBox editor = FindVisualChildren<TextBox>(grid).First(item => item.IsVisible && item.IsEnabled && !item.IsReadOnly && item.Text == "0.006");
            editor.SetCurrentValue(TextBox.TextProperty, "0.036"); Require(tool.CommitPendingEdits(), "existing native commit stages edited scale");
            Require(ReferenceEquals(retained, tool.CurrentResult) && tool.IsResultPrevious, "edited settings retain prior detector result as Previous");
            VisionToolThresholdTeachingPreviewController teaching = ReadPrivateField<VisionToolThresholdTeachingPreviewController>(view, "thresholdTeachingPreviewController")!;
            teaching.Request();
            Func<OpenVisionNativePreviewOperation> capture = ReadPrivateField<Func<OpenVisionNativePreviewOperation>>(document, "capturePreview")!;
            using (OpenVisionNativePreviewOperation operation = capture()) { Require(operation.IsTeachingPreview, "real Blob capture carries consumed teaching identity"); }
            teaching.Request(); int beforePreview = document.PreviewRunCount;
            document.RunPreview(); Wait();
            Require(document.PreviewRunCount == beforePreview + 1 && document.HasPreviewResult, "teaching bitmap still publishes through native preview");
            Require(ReferenceEquals(retained, tool.CurrentResult) && tool.IsResultPrevious && tool.ResultKind == "Previous" && !tool.CurrentResult.IsAcceptanceNg, "teaching does not replace prior real result with acceptance NG/current detection");
            Require(executionActions == 0, "teaching emits no inspection-start or inspection-completion action");
            Require(saved.SequenceEqual(File.ReadAllBytes(path)) && layers == host.LayerDocumentCount && inputRoute == document.RouteInputLayerName && outputRoute == document.RouteOutputLayerName && active == host.ActiveHostLayerTitle, "teaching preserves saved XML/layer count/route/active layer");
            IDisplayManager display = ReadPrivateField<IDisplayManager>(document, "displayManager")!;
            using (Bitmap bitmap = display.GetLayerImageSnapshot(outputRoute))
            {
                bool gray = bitmap != null;
                if (bitmap != null)
                {
                    bitmap.Save(Path.ChangeExtension(outputPath, ".teaching-output.png"), ImageFormat.Png);
                    for (int y = 0; y < bitmap.Height; y++) for (int x = 0; x < bitmap.Width; x++)
                    { DrawingColor pixel = bitmap.GetPixel(x, y); gray &= pixel.R == pixel.G && pixel.G == pixel.B; }
                }
                Require(gray, "published teaching bitmap is grayscale without detector markers; Main retains separately labeled previous overlay");
            }
            VisionToolSingleInputPropertyToolShell shell = (VisionToolSingleInputPropertyToolShell)view.FindName("toolShell");
            Require(!shell.ResultReviewText.Text.Contains("Blob /", StringComparison.Ordinal), "native teaching review does not advertise detector chips");
            ScreenshotPngWriter.WriteElementPng(host, Path.ChangeExtension(outputPath, ".previous.png"), 1600, 900);
            teaching.Request(); int legacyStarted = 0; OpenVisionNativePreviewExecutionResult? legacyResult = null;
            using (OpenVisionNativePreviewExecutionBoundary legacy = new(new OpenVisionNativePreviewExecutionController(display, new OpenVisionNativePreviewLayerPublisher(display)), action => view.Dispatcher.Invoke(action)))
            {
                Require(legacy.TryStartSingleInput(inputRoute, outputRoute, inputRoute, true, null, result => legacyResult = result, () => legacyStarted++, capture), "legacy null-Step teaching accepted");
                Stopwatch clock = Stopwatch.StartNew(); while (legacy.IsRunning && clock.ElapsedMilliseconds < 10000) { Pump(2); Thread.Sleep(2); } Pump(3);
                Require(!legacy.IsRunning && legacyStarted == 1 && legacyResult is { Success: true, IsTeachingPreview: true, Summary: null }, "legacy null-Step teaching preserves processing callback and teaching metadata");
            }
            tool.RunCommand.Execute(null); Wait(); Detection("explicit F8 after teaching runs detector and restores current OK");
            WaitForTaskWithPump(pipeline.RunForTestAsync(), 20000, "F5 after teaching"); Detection("explicit F5 after teaching retains normal judgment");
            File.WriteAllText(Path.ChangeExtension(outputPath, ".checks.json"), JsonSerializer.Serialize(new { Cases = cases, ProductSHA256 = Convert.ToHexString(SHA256.HashData(File.ReadAllBytes(typeof(OpenVisionShellHostView).Assembly.Location))), Scope = "In-process native capture/boundary/document regression; actual Tab/AUTO keyboard and native DPI remain unverified" }, new JsonSerializerOptions { WriteIndented = true }));
        });
    }

    private static CaptureResult CaptureMainPendingEditorSaveRun(string outputPath)
    {
        string recipe = "Smoke_PendingEditor_" + Guid.NewGuid().ToString("N");
        VisionPipelineStep initial = VisionPipelineStepBuilder.FromProperty(new BlobProperty("Blob") { PIXELPERMM = 0.006, USE_ROI = false, CvROI = new OpenCvSharp.Rect(0, 0, 32, 24) }, "Main", "Blob_Output");
        VisionPipeline source = new() { Name = "Main" }; source.Steps.Add(initial);
        VisionPipelineStorage.Save(recipe, source);
        VisionPipelineStorage.SaveActivePipelineName(recipe, "Main");
        OpenVisionShellHostView host = CreateShellHost(recipe, false);
        return CaptureWindowWithContent(host, outputPath, 1600, 900, () =>
        {
            var root = host.Workbench; var pipeline = root.Pipeline; var tool = root.Tool;
            tool.ConfigureAutoRunPreference(() => false, _ => { });
            tool.OpenStepRequested!(0); Pump(8);
            var grid = FindVisualChildren<System.Windows.Controls.WpfPropertyGrid.PropertyGrid>(host).Single(item => item.IsVisible && item.SelectedObject is BlobProperty);
            TextBox editor = FindVisualChildren<TextBox>(grid).First(item => item.IsVisible && item.IsEnabled && !item.IsReadOnly && item.Text == "0.006");
            object binding = ReadPrivateField<OpenVisionWorkbenchToolViewModel.EditorBinding>(tool, "editor");
            string savedPath = RecipeWorkspaceService.GetVisionPipelinePath(recipe, "Main");
            int runs = host.NativePreviewRunCount, layers = host.LayerDocumentCount, completed = 0;
            string route = host.ActiveHostLayerTitle;
            List<string> cases = new();
            void Require(bool condition, string name) { if (!condition) throw new InvalidOperationException(name); cases.Add(name); }
            double Working() => double.Parse(pipeline.WorkingCopyForTest.Steps[0].Parameters["PIXELPERMM"], CultureInfo.InvariantCulture);
            double Saved() => double.Parse(VisionPipelineStorage.Load(recipe, "Main").Steps[0].Parameters["PIXELPERMM"], CultureInfo.InvariantCulture);
            void Input(string value) => editor.SetCurrentValue(TextBox.TextProperty, value);
            Input("0.012");
            Require(Working() == 0.006, "LostFocus text remains pending before explicit save");
            root.Recipes.SaveRecipeCommand.Execute(null);
            Require(!root.Recipes.HasRecipeSaveFailure && !pipeline.IsDirty && Working() == 0.012 && Saved() == 0.012, "Save commits normal pending native text before dirty check and XML publication");
            Require(runs == host.NativePreviewRunCount && layers == host.LayerDocumentCount && route == host.ActiveHostLayerTitle, "Save commit does not preview or change layers/route");
            byte[] saved = File.ReadAllBytes(savedPath), working = VisionPipelineExecutionPlan.SerializePipeline(pipeline.WorkingCopyForTest);
            Input("invalid"); root.Recipes.SaveRecipeCommand.Execute(null);
            Require(root.Recipes.HasRecipeSaveFailure && saved.SequenceEqual(File.ReadAllBytes(savedPath)) && working.SequenceEqual(VisionPipelineExecutionPlan.SerializePipeline(pipeline.WorkingCopyForTest)) && editor.Text == "invalid", "Invalid pending Save preserves valid model/XML and editable text");
            Input("0.018"); root.Recipes.SaveRecipeCommand.Execute(null);
            Require(!root.Recipes.HasRecipeSaveFailure && !Validation.GetHasError(editor) && Working() == 0.018 && Saved() == 0.018 && ReferenceEquals(binding, ReadPrivateField<OpenVisionWorkbenchToolViewModel.EditorBinding>(tool, "editor")), "Valid correction recovers same native editor and Save");
            string imagePath = Path.ChangeExtension(outputPath, ".input.png");
            using (Bitmap image = new(32, 24)) { using Graphics graphics = Graphics.FromImage(image); graphics.Clear(DrawingColor.White); image.Save(imagePath, ImageFormat.Png); }
            Require(host.LoadMainImageFromFileForTest(imagePath), "owned valid Main input"); Pump(3);
            pipeline.InspectionCompleted += (_, _) => completed++;
            Input("0.024");
            Require(pipeline.RunCommand.CanExecute(null) && Working() == 0.018, "CanExecute does not commit pending input: " + Working() + "; blocker=" + pipeline.RunDisabledReason);
            WaitForTaskWithPump(pipeline.RunForTestAsync(), 20000, "Pending Run");
            Require(completed == 1 && Working() == 0.024 && Saved() == 0.018 && pipeline.IsDirty, "Pipeline Run commits pending native value before snapshot without saving");
            working = VisionPipelineExecutionPlan.SerializePipeline(pipeline.WorkingCopyForTest); saved = File.ReadAllBytes(savedPath);
            Input("invalid"); WaitForTaskWithPump(pipeline.RunForTestAsync(), 20000, "Invalid pending Run");
            Require(completed == 1 && working.SequenceEqual(VisionPipelineExecutionPlan.SerializePipeline(pipeline.WorkingCopyForTest)) && saved.SequenceEqual(File.ReadAllBytes(savedPath)), "Invalid pending Run refuses execution and preserves valid working/saved values");
            Input("0.03"); WaitForTaskWithPump(pipeline.RunForTestAsync(), 20000, "Recovered pending Run");
            Require(completed == 2 && Working() == 0.03 && !Validation.GetHasError(editor), "Valid correction recovers Run");
            File.WriteAllText(Path.ChangeExtension(outputPath, ".checks.json"), JsonSerializer.Serialize(new { Cases = cases, ProductSHA256 = Convert.ToHexString(SHA256.HashData(File.ReadAllBytes(typeof(OpenVisionShellHostView).Assembly.Location))), Scope = "In-process native controls and command regression; no actual GUI focus or native DPI claim" }, new JsonSerializerOptions { WriteIndented = true }));
        });
    }

    private static CaptureResult CaptureMainLastAction(string outputPath, int width, int height, bool baselineOnly = false, bool clearOnly = false, bool saveOnly = false, bool transitionOnly = false)
    {
        string token = Guid.NewGuid().ToString("N")[..12], recipeA = "Smoke_TransitionA_" + token, recipeB = "Smoke_TransitionB_" + token;
        string longRecipe = "긴_검사명_" + new string('가', 40), longPipeline = "긴_파이프라인_" + new string('나', 40);
        if (transitionOnly)
        {
            foreach (string recipe in new[] { recipeA, recipeB, longRecipe })
            {
                foreach (string name in new[] { "Main", "Second", longPipeline }) { VisionPipelineStorage.Save(recipe, new VisionPipeline { Name = name }); }
                VisionPipelineStorage.SaveActivePipelineName(recipe, "Main");
            }
        }
        OpenVisionShellHostView host = CreateShellHost(transitionOnly ? recipeA : "Smoke_Main_LastAction_20261011", false);
        string directory = Path.GetDirectoryName(outputPath)!;
        string inputPath = Path.Combine(directory, "Main_last_action_640x360.png");
        using (Bitmap input = new(640, 360)) { using Graphics graphics = Graphics.FromImage(input); graphics.Clear(DrawingColor.Teal); input.Save(inputPath, ImageFormat.Png); }
        string inputHash = Convert.ToHexString(SHA256.HashData(File.ReadAllBytes(inputPath)));
        List<object> cases = new();
        List<string> failures = new();
        return CaptureWindowWithContent(host, outputPath, width, height, () =>
        {
            Grid status = FindVisualChildren<Grid>(host).Single(item => AutomationProperties.GetAutomationId(item) == "WorkbenchStatusBar");
            TextBlock message = FindNamedVisualChild<TextBlock>(status, "workbenchActionStatus")!;
            MahApps.Metro.IconPacks.PackIconMaterial? icon = FindVisualChildren<MahApps.Metro.IconPacks.PackIconMaterial>(status).SingleOrDefault(item => AutomationProperties.GetAutomationId(item) == "WorkbenchActionIcon");
            OpenVisionWorkbenchPipelineViewModel pipeline = host.Workbench.Pipeline;
            Type pipelineType = typeof(OpenVisionWorkbenchPipelineViewModel);
            Dictionary<int, VisionPipelineStepResultSummary> results = (Dictionary<int, VisionPipelineStepResultSummary>)pipelineType.GetField("results", BindingFlags.Instance | BindingFlags.NonPublic)!.GetValue(pipeline)!;
            int runs = host.NativePreviewRunCount;
            byte[] working = VisionPipelineExecutionPlan.SerializePipeline(pipeline.WorkingCopyForTest);
            OpenVisionLanguage initialLanguage = OpenVisionLanguageService.CurrentLanguage;
            string[] states = transitionOnly ? new[] { "recipe-B", "recipe-A", "pipeline-Q", "save", "loaded", "pipeline-P", "recipe-long", "pipeline-long" } : saveOnly ? new[] { "save", "loaded", "save-repeat", "save-consecutive" } : clearOnly ? new[] { "cleared" } : baselineOnly ? new[] { "ready", "loaded" } : new[] { "ready", "loaded", "preset", "running", "ok", "ng", "error", "previous", "ended", "preset-repeat", "cleared" };
            foreach (string state in states)
            {
                string expectedKind = "", expectedIcon = "InformationOutline", expectedKo = "준비", expectedEn = "Ready";
                if (state.StartsWith("recipe-", StringComparison.Ordinal))
                {
                    string target = state == "recipe-B" ? recipeB : state == "recipe-A" ? recipeA : longRecipe;
                    Task completion = (Task)typeof(OpenVisionShellHostRecipeCommandSurface).GetMethod("SelectRecipeAsync", BindingFlags.Instance | BindingFlags.NonPublic)!.Invoke(host.RecipeCommands, new object[] { target })!;
                    WaitForTaskWithPump(completion, 10000, "Main recipe transition"); Pump(4);
                    expectedKo = "‘" + target + "’ 레시피를 열었습니다."; expectedEn = "Recipe '" + target + "' opened.";
                }
                else if (state.StartsWith("pipeline-", StringComparison.Ordinal))
                {
                    string target = state == "pipeline-Q" ? "Second" : state == "pipeline-P" ? "Main" : longPipeline;
                    host.RecipeCommands.SelectedPipelineOption = host.RecipeCommands.PipelineOptions.Single(option => option.PipelineName == target); Pump(4);
                    expectedKo = "파이프라인 ‘" + target + "’로 전환했습니다."; expectedEn = "Switched to pipeline '" + target + "'.";
                }
                else if (state.StartsWith("save", StringComparison.Ordinal))
                {
                    if (!host.RecipeCommands.SaveRecipeCommand.CanExecute(null)) throw new InvalidOperationException("Save command unavailable.");
                    host.RecipeCommands.SaveRecipeCommand.Execute(null); Pump(4);
                    if (host.RecipeCommands.HasRecipeSaveFailure) throw new InvalidOperationException(host.RecipeCommands.StatusText);
                    expectedKind = "Ok"; expectedIcon = "CheckCircle"; expectedKo = "레시피를 저장했습니다."; expectedEn = "Recipe saved.";
                }
                else if (state == "loaded")
                {
                    if (!host.LoadMainImageFromFileForTest(inputPath)) throw new InvalidOperationException("Main action input setup failed.");
                    expectedKo = "이미지를 열었습니다."; expectedEn = "Image opened.";
                }
                else if (state == "preset" || state == "preset-repeat")
                {
                    if (state == "preset") { host.SelectToolForTest(VISION_MENU.Mean); Pump(10); }
                    typeof(OpenVisionWorkbenchToolViewModel).GetMethod("NotifyPresetApplied", BindingFlags.Instance | BindingFlags.NonPublic)!.Invoke(host.Workbench.Tool, new object[] { "Workbench.Tool.PresetBasic" }); Pump(3);
                    expectedKo = "프리셋 ‘처음 설정’ 적용"; expectedEn = "Preset ‘First setup’ applied";
                }
                else if (state == "running") { SetRunning(true); expectedKind = "Running"; expectedIcon = "TimerOutline"; expectedKo = "파이프라인 실행 중…"; expectedEn = "Running pipeline…"; }
                else if (state is "ok" or "ng" or "error" or "previous" or "ended")
                {
                    if (state != "ok") { SetRunning(true); }
                    bool hasVerdict = state != "ended";
                    string resultKind = state == "ng" || state == "previous" ? "Ng" : state == "error" ? "Error" : "Ok";
                    results.Clear();
                    if (hasVerdict) { results[0] = new VisionPipelineStepResultSummary { ElapsedMilliseconds = 13D, Executed = true, Success = state != "error" }; results[1] = new VisionPipelineStepResultSummary { ElapsedMilliseconds = 7D, Executed = true, Success = true }; }
                    foreach (var field in new Dictionary<string, object> { ["hasFinalResult"] = hasVerdict, ["finalStale"] = state == "previous", ["finalKind"] = resultKind,
                        ["finalValue"] = resultKind == "Ng" ? "NG" : resultKind == "Error" ? "오류" : "OK", ["finalDetail"] = "Synthetic Main last action", ["finalDetailKey"] = string.Empty, ["statusText"] = string.Empty })
                        pipelineType.GetField(field.Key, BindingFlags.Instance | BindingFlags.NonPublic)!.SetValue(pipeline, field.Value);
                    foreach (var field in new Dictionary<string, object> { ["singleRunPrefix"] = false, ["singleRunCompleted"] = state is "ok" or "ng" or "error", ["singleRunResultKind"] = resultKind, ["lastRunMilliseconds"] = 20D })
                        pipelineType.GetField(field.Key, BindingFlags.Instance | BindingFlags.NonPublic)!.SetValue(pipeline, field.Value);
                    SetRunning(false);
                    if (state == "previous") { expectedKind = "Warning"; expectedIcon = "AlertOutline"; expectedKo = "실행 결과가 이전 상태입니다."; expectedEn = "The run result is previous."; }
                    else if (state == "ended") { expectedKo = "실행이 종료되었습니다."; expectedEn = "Run ended."; }
                    else { expectedKind = resultKind; expectedIcon = resultKind == "Ng" ? "CloseCircle" : resultKind == "Error" ? "AlertCircle" : "CheckCircle"; expectedKo = "파이프라인 실행 완료 · " + (resultKind == "Error" ? "오류" : resultKind.ToUpperInvariant()) + " · 20 ms"; expectedEn = "Pipeline run completed · " + (resultKind == "Error" ? "Error" : resultKind.ToUpperInvariant()) + " · 20 ms"; }
                }
                else if (state == "cleared")
                {
                    if (clearOnly && !host.LoadMainImageFromFileForTest(inputPath)) throw new InvalidOperationException("Main clear input setup failed.");
                    if (!host.Workbench.Images.SelectAllCommand.CanExecute(null)) throw new InvalidOperationException("Main clear selection unavailable.");
                    host.Workbench.Images.SelectAllCommand.Execute(null);
                    if (!host.Workbench.Images.RemoveCommand.CanExecute(null)) throw new InvalidOperationException("Main clear removal unavailable.");
                    host.Workbench.Images.RemoveCommand.Execute(null); Pump(4);
                    if (host.Workbench.Shell.HasWorkspaceInputImage || host.Workbench.Images.Count != 0) throw new InvalidOperationException("Main clear retained input or image items.");
                    expectedKo = "이미지를 닫았습니다."; expectedEn = "Image cleared.";
                }
                foreach (string paletteName in new[] { "Dark", "Light" })
                {
                    ResourceDictionary palette = new() { Source = new Uri($"/OpenVisionLab;component/UI/Wpf/OpenVisionWorkbench{paletteName}.xaml", UriKind.Relative) };
                    host.Resources.MergedDictionaries.Add(palette);
                    try
                    {
                        foreach (OpenVisionLanguage language in new[] { OpenVisionLanguage.Korean, OpenVisionLanguage.English })
                        {
                            OpenVisionLanguageService.SetLanguage(language, false); Pump(4);
                            string expected = language == OpenVisionLanguage.Korean ? expectedKo : expectedEn;
                            string? actualKind = Convert.ToString(typeof(OpenVisionWorkbenchViewModel).GetProperty("MainActionKind")?.GetValue(host.Workbench));
                            bool messageMatches = message.Text == expected && actualKind == expectedKind && message.IsVisible && message.TextTrimming == TextTrimming.CharacterEllipsis
                                && Convert.ToString(message.ToolTip) == message.Text;
                            bool iconMatches = icon?.IsVisible == true && icon.Kind.ToString() == expectedIcon && icon.Width == 16D && icon.Height == 16D;
                            Rect messageBounds = GetElementBounds(status, message);
                            Rect iconBounds = icon == null ? new Rect(0D, 0D, 0D, 0D) : GetElementBounds(status, icon);
                            FrameworkElement input = FindVisualChildren<FrameworkElement>(status).Single(item => AutomationProperties.GetAutomationId(item) == "WorkbenchStatusInput");
                            Rect inputBounds = GetElementBounds(status, input);
                            bool bounds = icon != null && iconBounds.Left >= 0D && iconBounds.Right + 6D <= messageBounds.Left + .000001D
                                && messageBounds.Right <= inputBounds.Left + .000001D && (transitionOnly ? messageBounds.Width >= 150D : messageBounds.Width >= TextWidth(message))
                                && messageBounds.Top >= 0D && messageBounds.Bottom <= status.ActualHeight;
                            double contrast = message.Foreground is SolidColorBrush fg && status.Background is SolidColorBrush bg ? GetContrastRatio(fg.Color, bg.Color) : 0D;
                            bool sameForeground = message.Foreground?.ToString() == host.FindResource("OpenVision.Workbench.SecondaryTextBrush").ToString() && icon?.Foreground?.ToString() == host.FindResource(expectedKind == "Ok" ? "OpenVision.Workbench.OkBrush" : expectedKind == "Ng" ? "OpenVision.Workbench.NgBrush" : expectedKind == "Error" ? "OpenVision.Workbench.NgBrush" : expectedKind == "Warning" ? "OpenVision.Workbench.StaleBrush" : expectedKind == "Running" ? "OpenVision.Workbench.AccentBrush" : "OpenVision.Workbench.SecondaryTextBrush").ToString();
                            if (!messageMatches || !iconMatches || !bounds || !sameForeground || contrast < 4.5D)
                                failures.Add($"{paletteName}/{language}/{state}: message={messageMatches}/{message.Text}, kind={actualKind}, icon={iconMatches}/{icon?.Kind}, bounds={bounds}, foreground={sameForeground}, contrast={contrast:F2}");
                            AssertMainStatusVerdict(host);
                            string capture = Path.Combine(directory, Path.GetFileNameWithoutExtension(outputPath) + $".{paletteName}.{language}.{state}.png");
                            ScreenshotPngWriter.WriteElementPng(host, capture, width, height);
                            cases.Add(new { State = state, Palette = paletteName, Language = language.ToString(), Expected = expected, Text = message.Text,
                                Kind = actualKind, Icon = icon?.Kind.ToString(), MessageMatches = messageMatches, IconMatches = iconMatches, Bounds = bounds,
                                SameForeground = sameForeground, Contrast = contrast, IntentionalTrimming = messageBounds.Width < TextWidth(message), FullTooltip = Convert.ToString(message.ToolTip), MessageBounds = messageBounds, IconBounds = iconBounds, InputBounds = inputBounds, Capture = capture });
                        }
                    }
                    finally { host.Resources.MergedDictionaries.Remove(palette); }
                }
            }
            OpenVisionLanguageService.SetLanguage(initialLanguage, false); Pump(4);
            var invariants = new { RunsUnchanged = host.NativePreviewRunCount == runs, WorkingUnchanged = working.SequenceEqual(VisionPipelineExecutionPlan.SerializePipeline(pipeline.WorkingCopyForTest)), ExpectedEmptyTransition = transitionOnly && pipeline.StepCount == 0,
                InputBytesUnchanged = inputHash == Convert.ToHexString(SHA256.HashData(File.ReadAllBytes(inputPath))) };
            if (!invariants.RunsUnchanged || (!invariants.WorkingUnchanged && !invariants.ExpectedEmptyTransition) || !invariants.InputBytesUnchanged) failures.Add("Main last-action projection changed execution, the working copy or input bytes.");
            File.WriteAllText(Path.ChangeExtension(outputPath, ".action-cases.json"), JsonSerializer.Serialize(new { Cases = cases, Failures = failures, Invariants = invariants,
                ProductSHA256 = Convert.ToHexString(SHA256.HashData(File.ReadAllBytes(typeof(OpenVisionShellHostView).Assembly.Location))),
                Scope = transitionOnly ? "Main W09 actual command-owner recipe/pipeline completions, short/long captured names and save overwrite; in-process rendering only. No CU/HTML/nativeDPI/full Main N or score." : "Main W09 existing input/preset notifications and synthetic single-run transitions; localized sentence/icon and adjacent current/previous verdict. No actual Run/CU/HTML/nativeDPI/full Main N or score." }, new JsonSerializerOptions { WriteIndented = true }));
            if (failures.Count > 0) throw new InvalidOperationException(string.Join("; ", failures));
            void SetRunning(bool value)
            {
                if (value) { pipelineType.GetField("singleRunCompleted", BindingFlags.Instance | BindingFlags.NonPublic)!.SetValue(pipeline, false); }
                pipelineType.GetField("running", BindingFlags.Instance | BindingFlags.NonPublic)!.SetValue(pipeline, value);
                pipelineType.GetMethod("RaiseState", BindingFlags.Instance | BindingFlags.NonPublic)!.Invoke(pipeline, null); Pump(4);
            }
            double TextWidth(TextBlock label) => new FormattedText(label.Text, System.Globalization.CultureInfo.CurrentCulture, FlowDirection.LeftToRight,
                new Typeface(label.FontFamily, label.FontStyle, label.FontWeight, label.FontStretch), label.FontSize, label.Foreground, VisualTreeHelper.GetDpi(label).PixelsPerDip).Width;
        });
    }


