                                && outer.Padding == new Thickness(6D, 0D, 6D, 0D) && outer.BorderBrush.ToString() == host.FindResource("OpenVision.Workbench.LineBrush").ToString()
                                && status.ActualHeight == 27D && statusOnHost.Left == 6D && statusOnHost.Right == host.ActualWidth - 6D
                                && actionIconBounds.Left == 10D && actionBounds.Left == 32D && inputIconBounds.Width == 16D && inputIconBounds.Height == 16D
                                && pointerCell.MinWidth == 170D && pointerCell.Padding == new Thickness(10D, 0D, 10D, 0D) && pointer.MinWidth == 0D && pointer.HorizontalAlignment == HorizontalAlignment.Left
                                && Math.Abs(pointerBounds.Left - pointerCellBounds.Left - 10D) < .000001D && BindingOperations.IsDataBound(pointer, TextBlock.TextProperty)
                                && pointer.Text == expectedPointer && pointer.Text == host.Workbench.Workspace.PointerText && (pointerLong ? pointerCell.ActualWidth > 170D : pointerCell.ActualWidth == 170D)
                                && (!pointerLong || verdictChip.ActualHeight == 20D) && logBounds.Height == 27D && GetElementBounds(status, verdict).Top >= 0D && GetElementBounds(status, verdict).Bottom <= 27D;
                            if (!geometryValid) failures.Add($"{paletteName}/{language}/{state}: geometry footer={outer?.ActualHeight}/{status.ActualHeight}, inset={statusOnHost.Left}, action={actionIconBounds.Left}/{actionBounds.Left}, inputIcon={inputIconBounds.Size}, pointerCell={pointerCell.ActualWidth}/{pointerCell.MinWidth}, pointerOffset={pointerBounds.Left - pointerCellBounds.Left}");
                            if (!canonicalOrder || !actionLayoutValid || !inside || !sizeVisible || !recipeTrimmed || !requiredVisible || !commandPreserved || !inputPreserved || !positionVerified || !elapsedVerified || !chipVerified || contrast < 3D)
                                failures.Add($"{paletteName}/{language}/{state}: order={canonicalOrder}, actionLayout={actionLayoutValid}, inside={inside}, size={sizeVisible}, recipe={recipeTrimmed}, visible={requiredVisible}, command={commandPreserved}, input={inputPreserved}, position={positionVerified}, elapsed={elapsedVerified}, chip={chipVerified}/{chipContrast:F2}, contrast={contrast:F2}");
                            string capture = Path.Combine(directory, Path.GetFileNameWithoutExtension(outputPath) + $".{paletteName}.{language}.{state}.png");
                            ScreenshotPngWriter.WriteElementPng(host, capture, width, height);
                            cases.Add(new { PointerBeforeSyntheticRefresh = pointerBeforeSyntheticRefresh, PointerAfterSyntheticRefresh = pointer.Text, InputSpacingVerified = inputSpacingVerified, InputSpacing = new { IconToNext = iconToNextGap, PositionToName = positionToNameGap, NameToDelimiter = nameToDelimiterGap, DelimiterToSize = delimiterToSizeGap, PositionBounds = inputPositionBounds, NameBounds = inputNameBounds, DelimiterBounds = delimiterBounds, SizeBounds = inputSizeBounds, PositionVisible = position.IsVisible, DelimiterVisible = delimiter.IsVisible, SizeVisible = size.IsVisible, PositionBound = BindingOperations.IsDataBound(position, TextBlock.TextProperty), NameBound = BindingOperations.IsDataBound(name, TextBlock.TextProperty), SizeBound = BindingOperations.IsDataBound(size, TextBlock.TextProperty) }, GeometryValid = geometryValid, Geometry = new { OuterHeight = outer?.ActualHeight, TopBorder = outer?.BorderThickness.ToString(), OuterPadding = outer?.Padding.ToString(), OuterBorderBrush = outer?.BorderBrush.ToString(), StatusOnHost = statusOnHost, PointerCellBounds = pointerCellBounds, PointerCellMin = pointerCell.MinWidth, PointerOffset = pointerBounds.Left - pointerCellBounds.Left, PointerText = pointer.Text, PointerBound = BindingOperations.IsDataBound(pointer, TextBlock.TextProperty), SyntheticPointer = state.Contains("pointer"), InputIconBounds = inputIconBounds, LogHeight = logBounds.Height, VerdictChipHeight = verdictChip.ActualHeight, ExpectedPointer = expectedPointer }, Palette = paletteName, Language = language.ToString(), State = state, CanonicalOrder = canonicalOrder, ActionLayoutValid = actionLayoutValid, CanonicalAction = canonicalAction, LegacyGuideVisible = guide.IsVisible, ActionIconBounds = actionIconBounds, GuideBounds = guideBounds, Inside = inside,
                                SizeVisible = sizeVisible, RecipeTrimmed = recipeTrimmed, RequiredVisible = requiredVisible, CommandPreserved = commandPreserved,
                                InputPreserved = inputPreserved, ChipVerified = chipVerified, ChipContrast = chipContrast, ChipBackground = renderedChipBackground?.ToString(), ChipRawBackground = chip?.Background?.ToString(), ChipBrushOpacity = chip?.Background?.Opacity, ChipForeground = verdictValue.Foreground?.ToString(), ChipPadding = chip?.Padding.ToString(), ChipRadius = chip?.CornerRadius.ToString(), ChipHeight = chip?.ActualHeight, ChipValueFont = verdictValue.FontSize, ChipValueWeight = verdictValue.FontWeight.ToString(), ElapsedVerified = elapsedVerified, ElapsedText = elapsed?.Text, ElapsedVisible = elapsed?.IsVisible, ExpectedElapsed = expectedElapsed, PositionVerified = positionVerified, PositionText = position?.Text, PositionVisible = position?.IsVisible, ExpectedPosition = expectedPosition, Contrast = contrast, ActionBounds = actionBounds, InputBounds = inputBounds, PointerBounds = pointerBounds,
                                VerdictBounds = verdictBounds, LogBounds = logBounds, RecipeBounds = recipeBounds, StatusWidth = status.ActualWidth, StatusHeight = status.ActualHeight, RecipeName = recipe.Text,
                                RequiredTextWidths = new { ActionActual = action.ActualWidth, ActionText = TextWidth(action), PointerActual = pointer.ActualWidth, PointerText = TextWidth(pointer),
                                    LogActual = logCaption.ActualWidth, LogText = TextWidth(logCaption) }, Capture = capture });
                        }
                    }
                    finally { host.Resources.MergedDictionaries.Remove(palette); }
                }
            }
            if (verifyGeometry)
            {
                host.Workbench.Workspace.GetType().GetMethod("ApplyPointerStatus", BindingFlags.Instance | BindingFlags.NonPublic)!.Invoke(host.Workbench.Workspace, new object[] { OpenVisionZoomableImageStatus.Empty }); Pump(4);
                Border restoredCell = (Border)VisualTreeHelper.GetParent(pointer);
                bool restored = pointer.Text == "X —  Y —  GV —" && restoredCell.ActualWidth == 170D && BindingOperations.IsDataBound(pointer, TextBlock.TextProperty);
                cases.Add(new { State = "long-pointer-to-empty-restored", Pointer = pointer.Text, CellWidth = restoredCell.ActualWidth, PointerBound = BindingOperations.IsDataBound(pointer, TextBlock.TextProperty), SyntheticPointer = true, PASS = restored });
                if (!restored) failures.Add("Long pointer must restore the bound empty text and 170 cell.");
            }
            OpenVisionLanguageService.SetLanguage(initialLanguage, false); Pump(4);
            var invariants = new { RunsUnchanged = host.NativePreviewRunCount == runs,
                WorkingUnchanged = working.SequenceEqual(VisionPipelineExecutionPlan.SerializePipeline(host.Workbench.Pipeline.WorkingCopyForTest)) };
            if (!invariants.RunsUnchanged || !invariants.WorkingUnchanged) failures.Add("Main status layout changed execution or the working copy.");
            File.WriteAllText(Path.ChangeExtension(outputPath, ".layout-cases.json"), JsonSerializer.Serialize(new { Cases = cases, Failures = failures, Invariants = invariants,
                InitialRoute = route, FinalRoute = host.DirectResultRouteText, ProductSHA256 = Convert.ToHexString(SHA256.HashData(File.ReadAllBytes(typeof(OpenVisionShellHostView).Assembly.Location))),
                Scope = verifyChip ? "Main W09 semantic verdict chip and adjacent elapsed/current/prior/empty/reset; new consumer display and composited contrast only; synthetic states/no Run/no full View score/HTML/nativeDPI/actual input" : verifyElapsed ? "Main W09 current step processing time SUM/current/prior/zero/reset display; synthetic states and no Run; no full View score/HTML/nativeDPI/actual input" : verifyImagePosition ? "Main W09 empty/one/two/previous position display; canonical 60-ui-shell.js96/6.8, existing Images state; in-process only, no full View score/HTML/nativeDPI/actual input"
                    : "new Main status spatial order and long-value bounds; 60-ui-shell.js/6.8 define order; in-process only, no full View score/HTML/nativeDPI/actual input" }, new JsonSerializerOptions { WriteIndented = true }));
            if (failures.Count > 0) throw new InvalidOperationException(string.Join("; ", failures));

            double TextWidth(TextBlock label) => new FormattedText(label.Text, System.Globalization.CultureInfo.CurrentCulture, FlowDirection.LeftToRight,
                new Typeface(label.FontFamily, label.FontStyle, label.FontWeight, label.FontStretch), label.FontSize, label.Foreground, VisualTreeHelper.GetDpi(label).PixelsPerDip).Width;
        });
    }

    private static CaptureResult CaptureWorkbenchInputStatus(string outputPath, int width, int height)
    {
        OpenVisionShellHostView host = CreateShellHost("Smoke_W09_Input", false);
        string directory = Path.GetDirectoryName(outputPath)!;
        string inputPath = Path.Combine(directory, "Main_현재입력_Long_filename_640x360_20261010_recovery.png");
        string retryPath = Path.Combine(directory, "Main_odd_643x361.png");
        string corruptPath = Path.Combine(directory, "Main_owned_truncated.png");
        using (Bitmap input = new(640, 360)) { using Graphics graphics = Graphics.FromImage(input); graphics.Clear(DrawingColor.Teal); input.Save(inputPath, ImageFormat.Png); }
        using (Bitmap retry = new(643, 361)) { using Graphics graphics = Graphics.FromImage(retry); graphics.Clear(DrawingColor.Orange); retry.Save(retryPath, ImageFormat.Png); }
        File.WriteAllBytes(corruptPath, File.ReadAllBytes(inputPath).Take(32).ToArray());
        List<object> cases = new();
        List<string> failures = new();
        return CaptureWindowWithContent(host, outputPath, width, height, () =>
        {
            Grid status = FindVisualChildren<Grid>(host).Single(item => AutomationProperties.GetAutomationId(item) == "WorkbenchStatusBar");
            TextBlock? name = FindVisualChildren<TextBlock>(status).SingleOrDefault(item => AutomationProperties.GetAutomationId(item) == "WorkbenchStatusInputName");
            TextBlock? size = FindVisualChildren<TextBlock>(status).SingleOrDefault(item => AutomationProperties.GetAutomationId(item) == "WorkbenchStatusInputSize");
            Button log = FindVisualChildren<Button>(status).Single(item => AutomationProperties.GetAutomationId(item) == "WorkbenchOpenLog");
            int runs = host.NativePreviewRunCount;
            string route = string.Join("|", host.Workbench.Pipeline.Rows.Select(row => row.Index + ":" + row.InputLayer + "->" + row.OutputLayer));
            byte[] working = VisionPipelineExecutionPlan.SerializePipeline(host.Workbench.Pipeline.WorkingCopyForTest);
            OpenVisionLanguage initialLanguage = OpenVisionLanguageService.CurrentLanguage;
            foreach (string paletteName in new[] { "Dark", "Light" })
            {
                ResourceDictionary palette = new() { Source = new Uri($"/OpenVisionLab;component/UI/Wpf/OpenVisionWorkbench{paletteName}.xaml", UriKind.Relative) };
                host.Resources.MergedDictionaries.Add(palette);
                try
                {
                    foreach (OpenVisionLanguage language in new[] { OpenVisionLanguage.Korean, OpenVisionLanguage.English })
                    {
                        OpenVisionLanguageService.SetLanguage(language, false); Pump(4);
                        Observe(paletteName, language, "empty", language == OpenVisionLanguage.Korean ? "이미지 없음" : "No image", "");
                    }
                }
                finally { host.Resources.MergedDictionaries.Remove(palette); }
            }
            using (Bitmap output = new(80, 40)) { if (!host.AddLayerImageForTest("Owned_W09_Output", output)) throw new InvalidOperationException("W09 output setup failed."); }
            foreach (string paletteName in new[] { "Dark", "Light" })
            {
                ResourceDictionary palette = new() { Source = new Uri($"/OpenVisionLab;component/UI/Wpf/OpenVisionWorkbench{paletteName}.xaml", UriKind.Relative) };
                host.Resources.MergedDictionaries.Add(palette);
                try
                {
                    foreach (OpenVisionLanguage language in new[] { OpenVisionLanguage.Korean, OpenVisionLanguage.English })
                    {
                        OpenVisionLanguageService.SetLanguage(language, false);
                        if (!host.LoadMainImageFromFileForTest(inputPath)) throw new InvalidOperationException("W09 valid input failed.");
                        Observe(paletteName, language, "loaded-long-name", Path.GetFileName(inputPath), "640×360");
                        if (!host.ActivateHostLayerForTest("Owned_W09_Output")) throw new InvalidOperationException("W09 output activation failed.");
                        Observe(paletteName, language, "output-independent", Path.GetFileName(inputPath), "640×360");
                        BitmapSource retained = host.Workbench.Shell.WorkspaceInputPreview;
                        if (host.LoadMainImageFromFileForTest(corruptPath) || !ReferenceEquals(retained, host.Workbench.Shell.WorkspaceInputPreview))
                            throw new InvalidOperationException("W09 decode failure replaced the input.");
                        Observe(paletteName, language, "decode-retained", Path.GetFileName(inputPath), "640×360");
                        if (!host.LoadMainImageFromFileForTest(retryPath)) throw new InvalidOperationException("W09 odd-size retry failed.");
                        Observe(paletteName, language, "retry-odd-size", Path.GetFileName(retryPath), "643×361");
                        using (Bitmap replacement = new(320, 180)) { host.SetMainLayerImageForTest(replacement); }
                        Observe(paletteName, language, "non-file-main", "Main", "320×180");
                    }
                }
                finally { host.Resources.MergedDictionaries.Remove(palette); }
            }
            OpenVisionLanguageService.SetLanguage(initialLanguage, false); Pump(4);
            var invariants = new { RunsUnchanged = host.NativePreviewRunCount == runs,
                RouteUnchanged = route == string.Join("|", host.Workbench.Pipeline.Rows.Select(row => row.Index + ":" + row.InputLayer + "->" + row.OutputLayer)),
                WorkingUnchanged = working.SequenceEqual(VisionPipelineExecutionPlan.SerializePipeline(host.Workbench.Pipeline.WorkingCopyForTest)) };
            if (!invariants.RunsUnchanged || !invariants.RouteUnchanged || !invariants.WorkingUnchanged) failures.Add("W09 input metadata display changed execution, routing or the pipeline working copy.");
            File.WriteAllText(Path.ChangeExtension(outputPath, ".input-cases.json"), JsonSerializer.Serialize(new { Cases = cases, Failures = failures, Invariants = invariants,
                ProductSHA256 = Convert.ToHexString(SHA256.HashData(File.ReadAllBytes(typeof(OpenVisionShellHostView).Assembly.Location))),
                Scope = "in-process WPF; live palettes/KOEN and input projection transitions; no actual pointer/native DPI/HTML or image index" }, new JsonSerializerOptions { WriteIndented = true }));
            if (failures.Count > 0) throw new InvalidOperationException(string.Join("; ", failures));

            void Observe(string paletteName, OpenVisionLanguage language, string state, string expectedName, string expectedSize)
            {
                Pump(4);
                bool matched = name?.Text == expectedName && size?.Text == expectedSize && size.IsVisible == (expectedSize.Length != 0);
                Rect? nameBounds = name?.TransformToAncestor(status).TransformBounds(new Rect(name.RenderSize));
                Rect? sizeBounds = size?.TransformToAncestor(status).TransformBounds(new Rect(size.RenderSize));
                Rect logBounds = log.TransformToAncestor(status).TransformBounds(new Rect(log.RenderSize));
                bool inside = nameBounds.HasValue && nameBounds.Value.Top >= 0 && nameBounds.Value.Bottom <= status.ActualHeight
                    && (expectedSize.Length == 0 ? nameBounds.Value.Right <= logBounds.Left : sizeBounds.HasValue && sizeBounds.Value.Right <= logBounds.Left && sizeBounds.Value.Bottom <= status.ActualHeight && nameBounds.Value.Right <= sizeBounds.Value.Left);
                bool fullSize = expectedSize.Length == 0 || size != null && size.ActualWidth >= new FormattedText(expectedSize, System.Globalization.CultureInfo.CurrentCulture, FlowDirection.LeftToRight,
                    new Typeface(size.FontFamily, size.FontStyle, size.FontWeight, size.FontStretch), size.FontSize, size.Foreground, VisualTreeHelper.GetDpi(size).PixelsPerDip).Width;
                bool trimmed = name != null && name.TextTrimming == TextTrimming.CharacterEllipsis && name.MaxWidth == 180D
                    && (expectedSize.Length == 0 || Convert.ToString(name.ToolTip) == expectedName);
                double contrast = name?.Foreground is SolidColorBrush foreground && status.Background is SolidColorBrush background ? GetContrastRatio(foreground.Color, background.Color) : 0D;
                if (!matched || !inside || !fullSize || !trimmed || contrast < 3D) failures.Add($"{paletteName}/{language}/{state}: matched={matched}, inside={inside}, fullSize={fullSize}, trimmed={trimmed}, contrast={contrast:F2}");
                string capture = Path.Combine(directory, Path.GetFileNameWithoutExtension(outputPath) + $".{paletteName}.{language}.{state}.png");
                ScreenshotPngWriter.WriteElementPng(host, capture, width, height);
                cases.Add(new { Palette = paletteName, Language = language.ToString(), State = state, ExpectedName = expectedName, ExpectedSize = expectedSize,
                    ActualName = name?.Text, ActualSize = size?.Text, Matched = matched, Inside = inside, FullSize = fullSize, Trimmed = trimmed, Contrast = contrast,
                    NameBounds = nameBounds, SizeBounds = sizeBounds, LogBounds = logBounds, StatusHeight = status.ActualHeight, PreviewFrozen = host.Workbench.Shell.WorkspaceInputPreview?.IsFrozen, Capture = capture });
            }
        });
    }

    private static CaptureResult CaptureWorkbenchLogStatus(string outputPath, int width, int height)
    {
        OpenVisionShellHostView host = CreateShellHost("Smoke_WorkbenchStatusLog", false);
        List<object> cases = new();
        List<string> failures = new();
        List<object> parserCases = new();
        foreach (var sample in new (string Id, string? Raw, string Category, string Level, string Source, string Message)[]
        {
            ("single-line", "[2026-10-10 04:41:42.791][Main][Error][RelayCommand.Execute] Workspace image load failed.", "Main", "Error", "RelayCommand.Execute", "Workspace image load failed."),
            ("exception-LF", "[2026-10-10 04:41:42.791][Main][Error][RelayCommand.Execute] Workspace image load failed.\n   at System.Drawing.Bitmap..ctor(String filename)", "Main", "Error", "RelayCommand.Execute", "Workspace image load failed.\n   at System.Drawing.Bitmap..ctor(String filename)"),
            ("exception-CRLF", "[2026-10-10 04:41:42.791][Main][Error][RelayCommand.Execute] Workspace image load failed.\r\n   at System.Drawing.Bitmap..ctor(String filename)", "Main", "Error", "RelayCommand.Execute", "Workspace image load failed.\r\n   at System.Drawing.Bitmap..ctor(String filename)"),
            ("warning-multiline", "[2026-10-10 04:41:42.791][System][Warning] Warning\nDetails", "System", "Warning", "", "Warning\nDetails"),
            ("info-multiline", "[2026-10-10 04:41:42.791][System][Info][W09] Info\nDetails", "System", "Info", "W09", "Info\nDetails"),
            ("embedded-level", "Plain message [Main][Error] remains plain", "", "", "", "Plain message [Main][Error] remains plain"),
            ("continuation", "   at System.Drawing.Bitmap..ctor(String filename)", "", "", "", "   at System.Drawing.Bitmap..ctor(String filename)"),
            ("empty", "", "", "", "", ""),
            ("null", null, "", "", "", "")
        })
        {
            OpenVisionLab.Logging.Controls.Model.LogLine parsed = OpenVisionLab.Logging.Controls.Model.LogLine.Parse(sample.Raw);
            bool matched = parsed.Category == sample.Category && parsed.Level == sample.Level && parsed.Source == sample.Source
                && parsed.Message == sample.Message && parsed.RawText == (sample.Raw ?? string.Empty)
                && (sample.Category.Length == 0 ? parsed.Timestamp == DateTime.MinValue : parsed.Timestamp == new DateTime(2026, 10, 10, 4, 41, 42, 791));
            parserCases.Add(new { sample.Id, sample.Raw, ExpectedCategory = sample.Category, ExpectedLevel = sample.Level,
                ExpectedSource = sample.Source, ExpectedMessage = sample.Message, Actual = parsed, Matched = matched });
            if (!matched) failures.Add($"W09 log parser {sample.Id}: metadata or full message was lost.");
        }
        return CaptureWindowWithContent(host, outputPath, width, height, () =>
        {
            LogPanelView log = FindVisualChildren<LogPanelView>(host).Single();
            LogPanelViewModel model = (LogPanelViewModel)log.DataContext;
            Button button = FindVisualChildren<Button>(host).Single(item => AutomationProperties.GetAutomationId(item) == "WorkbenchOpenLog");
            Grid status = FindVisualChildren<Grid>(host).Single(item => AutomationProperties.GetAutomationId(item) == "WorkbenchStatusBar");
            ICommand command = button.Command;
            DependencyPropertyKey hoverKey = (DependencyPropertyKey)typeof(UIElement).GetField("IsMouseOverPropertyKey", BindingFlags.Static | BindingFlags.NonPublic)!.GetValue(null)!;
            DependencyPropertyKey pressedKey = (DependencyPropertyKey)typeof(ButtonBase).GetField("IsPressedPropertyKey", BindingFlags.Static | BindingFlags.NonPublic)!.GetValue(null)!;
            int runs = host.NativePreviewRunCount;
            int layers = host.LayerDocumentCount;
            string route = host.DirectResultRouteText;
            byte[] working = VisionPipelineExecutionPlan.SerializePipeline(host.Workbench.Pipeline.WorkingCopyForTest);
            string savedPath = RecipeWorkspaceService.GetVisionPipelinePath("Smoke_WorkbenchStatusLog", host.Workbench.Pipeline.SelectedPipelineName);
            byte[]? saved = File.Exists(savedPath) ? File.ReadAllBytes(savedPath) : null;
            OpenVisionLanguage initialLanguage = OpenVisionLanguageService.CurrentLanguage;
            ILog logger = LogManager.GetLogger("OpenVisionLab.W09");
            foreach (string paletteName in new[] { "Dark", "Light" })
            {
                (paletteName == "Dark" ? host.Workbench.SelectDarkThemeCommand : host.Workbench.SelectLightThemeCommand).Execute(null); Pump(3);
                ResourceDictionary palette = new() { Source = new Uri($"/OpenVisionLab;component/UI/Wpf/OpenVisionWorkbench{paletteName}.xaml", UriKind.Relative) };
                host.Resources.MergedDictionaries.Add(palette);
                try
                {
                    foreach (OpenVisionLanguage language in new[] { OpenVisionLanguage.Korean, OpenVisionLanguage.English })
                    {
                        OpenVisionLanguageService.SetLanguage(language, false);
                        host.Workbench.OpenLogCommand.Execute(null);
                        model.ShowEntireStream = true; model.SearchText = string.Empty; model.SelectedLevel = "Any";
                        WaitForTaskWithPump(Task.Delay(350), 2000, "W09 initial reader drain");
                        model.ResetCommand.Execute(null); Pump(4);
                        Observe("empty", 0);
                        logger.Info("[System][Info][W09] Info does not count as Error");
                        logger.Warn("[System][Warning][W09] Warning does not count as Error");
                        WaitForTaskWithPump(Task.Delay(350), 2000, "W09 Info/Warning arrival");
                        Observe("info-warning", 0);
                        logger.Error("[System][Error][W09] First error\n   at OwnedLogFixture.Read()");
                        WaitForTaskWithPump(Task.Delay(350), 2000, "W09 first error arrival");
                        Observe("one-error", 1);
                        foreach (string interaction in new[] { "controlled-hover", "controlled-pressed", "controlled-leave", "framework-focus" })
                        {
                            button.SetValue(hoverKey, interaction is "controlled-hover" or "controlled-pressed");
                            button.SetValue(pressedKey, interaction == "controlled-pressed");
                            if (interaction == "framework-focus") { button.Focus(); }
                            Observe(interaction, 1);
                        }
                        button.SetValue(hoverKey, false); button.SetValue(pressedKey, false); Keyboard.ClearFocus(); Pump(2);
                        logger.Error("[System][Error][W09] Second error\r\n   at OwnedLogFixture.Read()");
                        WaitForTaskWithPump(Task.Delay(350), 2000, "W09 second error arrival");
                        Observe("two-errors", 2);
                        model.ShowEntireStream = false; model.SelectedLevel = "Info"; model.SearchText = "Info does not count"; Pump(4);
                        if (model.FilteredLogs.Any(entry => entry.Level == "Error")) throw new InvalidOperationException("W09 filter fixture did not hide errors.");
                        Observe("filtered-errors-hidden", 2);
                        model.ResetCommand.Execute(null); Pump(4);
                        Observe("clear-filtered", 0);
                        host.Workbench.SelectedBottomTab = 0; Pump(4);
                        logger.Error("[System][Error][W09] Arrival while Log tab hidden");
                        WaitForTaskWithPump(Task.Delay(350), 2000, "W09 hidden-tab error arrival");
                        Observe("hidden-arrival", 1);
                        button.Command.Execute(button.CommandParameter); Pump(4);
                        if (!ReferenceEquals(log.DataContext, model) || !log.IsVisible || host.Workbench.SelectedBottomTab != 2)
                            throw new InvalidOperationException("W09 Log entry changed the reader or failed to reopen its tab.");
                        Observe("reopened", 1);
                        button.SetCurrentValue(UIElement.IsEnabledProperty, false); Pump(4);
                        Observe("synthetic-disabled", 1);
                        button.SetCurrentValue(UIElement.IsEnabledProperty, true); Pump(4);
                        Observe("enabled-recovery", 1);
                        model.ResetCommand.Execute(null);

                        void Observe(string state, int expectedCount)
                        {
                            Pump(4);
                            string actual = string.Join(" ", FindVisualChildren<TextBlock>(button).Select(text => text.Text));
                            string expected = expectedCount == 0 ? (language == OpenVisionLanguage.Korean ? "로그" : "Log")
                                : (language == OpenVisionLanguage.Korean ? $"오류 {expectedCount}" : $"Errors {expectedCount}");
                            int? boundCount = typeof(LogPanelViewModel).GetProperty("ErrorCount")?.GetValue(model) as int?;
                            Rect bounds = button.TransformToAncestor(status).TransformBounds(new Rect(button.RenderSize));
                            TextBlock text = FindVisualChildren<TextBlock>(button).First();
                            Border chrome = FindNamedVisualChild<Border>(button, "buttonChrome")!, cue = FindNamedVisualChild<Border>(button, "focusCue")!;
                            Border cell = (Border)VisualTreeHelper.GetParent(button);
                            MahApps.Metro.IconPacks.PackIconMaterial icon = FindVisualChildren<MahApps.Metro.IconPacks.PackIconMaterial>(button).Single();
                            Rect iconBounds = GetElementBounds(button, icon), textBounds = GetElementBounds(button, text);
                            SolidColorBrush underlying = (SolidColorBrush)host.FindResource("OpenVision.Workbench.ChromeBrush");
                            SolidColorBrush rendered = (SolidColorBrush)chrome.Background;
                            double alpha = rendered.Color.A / 255D * rendered.Opacity;
                            Color composed = Color.FromRgb((byte)Math.Round(rendered.Color.R * alpha + underlying.Color.R * (1D - alpha)),
                                (byte)Math.Round(rendered.Color.G * alpha + underlying.Color.G * (1D - alpha)), (byte)Math.Round(rendered.Color.B * alpha + underlying.Color.B * (1D - alpha)));
                            double contrast = text.Foreground is SolidColorBrush fg ? GetContrastRatio(fg.Color, composed) : 0D;
                            string textKey = !button.IsEnabled ? "MutedTextBrush" : expectedCount > 0 ? "NgBrush" : "SecondaryTextBrush";
                            string iconKey = button.IsEnabled ? "SecondaryTextBrush" : "MutedTextBrush";
                            bool foregroundAligned = text.Foreground.ToString() == host.FindResource("OpenVision.Workbench." + textKey).ToString()
                                && icon.Foreground.ToString() == host.FindResource("OpenVision.Workbench." + iconKey).ToString();
                            bool flat = alpha == 0D && chrome.BorderThickness == new Thickness(0D) && button.BorderThickness == new Thickness(0D)
                                && button.ActualHeight == 27D && cell.Padding == new Thickness(0D) && button.Padding == new Thickness(10D, 0D, 10D, 0D)
                                && button.ActualWidth == cell.ActualWidth - 1D && iconBounds.Width == 16D && iconBounds.Height == 16D
                                && Math.Abs(iconBounds.Left - 10D) < .000001D && Math.Abs(textBounds.Left - iconBounds.Right - 6D) < .000001D
                                && text.FontWeight == FontWeights.Normal && text.FontSize == 12D && ReferenceEquals(command, button.Command) && ReferenceEquals(button.Command, host.Workbench.OpenLogCommand)
                                && BindingOperations.IsDataBound(button, Button.CommandProperty) && BindingOperations.IsDataBound(text, TextBlock.TextProperty)
                                && (state != "framework-focus" || button.IsKeyboardFocused && cue.Visibility == Visibility.Visible);

                            bool matched = actual == expected && boundCount == expectedCount;
                            bool inside = bounds.Top >= 0D && bounds.Bottom <= status.ActualHeight && bounds.Right <= status.ActualWidth;
                            if (!matched || !inside || !foregroundAligned || !flat || contrast < 3D) failures.Add($"{paletteName}/{language}/{state}: '{actual}' expected '{expected}', count={boundCount}, inside={inside}, foregroundAligned={foregroundAligned}, flat={flat}, contrast={contrast:F2}");
                            string capture = Path.Combine(Path.GetDirectoryName(outputPath)!, Path.GetFileNameWithoutExtension(outputPath) + $".{paletteName}.{language}.{state}.png");
                            ScreenshotPngWriter.WriteElementPng(host, capture, width, height);
                            cases.Add(new { Flat = flat, Presentation = new { ButtonHeight = button.ActualHeight, CellHeight = cell.ActualHeight, ButtonWidth = button.ActualWidth, CellWidth = cell.ActualWidth, Padding = button.Padding.ToString(), CellPadding = cell.Padding.ToString(), ChromeBackground = chrome.Background.ToString(), ChromeBorder = chrome.BorderThickness.ToString(), ChromeCorner = chrome.CornerRadius.ToString(), IconBounds = iconBounds, TextBounds = textBounds, TextForeground = text.Foreground.ToString(), IconForeground = icon.Foreground.ToString(), FontWeight = text.FontWeight.ToString(), ComposedBackground = composed.ToString(), FocusVisible = cue.Visibility.ToString(), KeyboardFocused = button.IsKeyboardFocused, Hover = button.IsMouseOver, Pressed = button.IsPressed, ControlledDP = state.StartsWith("controlled"), NativeInput = false }, Palette = paletteName, Language = language.ToString(), State = state, ExpectedCount = expectedCount,
                                Expected = expected, Actual = actual, BoundCount = boundCount, Matched = matched, ButtonBounds = bounds,
                                StatusHeight = status.ActualHeight, Inside = inside, ForegroundAligned = foregroundAligned, Contrast = contrast, Enabled = button.IsEnabled,
                                Retained = model.Logs.Count, Filtered = model.FilteredLogs.Count, Capture = capture });
                        }
                    }
                }
                finally { host.Resources.MergedDictionaries.Remove(palette); }
            }
            OpenVisionLanguageService.SetLanguage(initialLanguage, false); Pump(8);
            var invariants = new { RunsUnchanged = host.NativePreviewRunCount == runs, LayersUnchanged = host.LayerDocumentCount == layers,
                RouteUnchanged = host.DirectResultRouteText == route,
                WorkingUnchanged = working.SequenceEqual(VisionPipelineExecutionPlan.SerializePipeline(host.Workbench.Pipeline.WorkingCopyForTest)),
                SavedUnchanged = saved == null ? !File.Exists(savedPath) : File.Exists(savedPath) && saved.SequenceEqual(File.ReadAllBytes(savedPath)) };
            if (!invariants.RunsUnchanged || !invariants.LayersUnchanged || !invariants.RouteUnchanged || !invariants.WorkingUnchanged || !invariants.SavedUnchanged)
                failures.Add("W09 Log display produced an execution/layer/route/working/saved XML change.");
            File.WriteAllText(Path.ChangeExtension(outputPath, ".log-cases.json"), JsonSerializer.Serialize(new { Cases = cases, ParserCases = parserCases, Failures = failures, Invariants = invariants,
                ProductSHA256 = Convert.ToHexString(SHA256.HashData(File.ReadAllBytes(typeof(OpenVisionShellHostView).Assembly.Location))),
                LogModuleSHA256 = Convert.ToHexString(SHA256.HashData(File.ReadAllBytes(typeof(LogPanelViewModel).Assembly.Location))),
                Scope = "in-process WPF; live palettes, log reader arrivals; controlled hover/pressed/leave + framework focus + synthetic disabled; no actual native mouse/held/keyboard or native DPI" }, new JsonSerializerOptions { WriteIndented = true }));
            if (failures.Count > 0) throw new InvalidOperationException(string.Join("; ", failures));
        });
    }

    private static CaptureResult CaptureLoggingBufferContract(string outputPath)
    {
        RuntimeLogSink sink = new RuntimeLogSink();
        const int producerCount = 8;
        const int messagesPerProducer = 1000;
        Parallel.For(0, producerCount, producerIndex =>
        {
            for (int messageIndex = 0; messageIndex < messagesPerProducer; messageIndex++)
            {
                sink.DoAppend(new LoggingEvent(new LoggingEventData
                {
                    LoggerName = "OpenVisionLab.OVL03",
                    Level = Level.Info,
                    Message = $"OVL03-{producerIndex}-{messageIndex}",
                    TimeStampUtc = DateTime.UtcNow
                }));
            }
        });

        IReadOnlyList<string> firstBatch = sink.ReadEntries();
        if (firstBatch.Count > RuntimeLogSink.DefaultMaxReadEntries)
        {
            throw new InvalidOperationException(
                $"Runtime log consumer batch exceeded the configured limit: {firstBatch.Count}.");
        }

        int drainedEntries = firstBatch.Count;
        long drainedCharacters = firstBatch.Sum(entry => (long)entry.Length);
        IReadOnlyList<string> batch;
        while ((batch = sink.ReadEntries()).Count > 0)
        {
            drainedEntries += batch.Count;
            drainedCharacters += batch.Sum(entry => (long)entry.Length);
        }

        if (drainedEntries > RuntimeLogSink.DefaultMaxBufferedEntries
            || drainedCharacters > RuntimeLogSink.DefaultMaxBufferedCharacters
            || sink.DroppedLogCount <= 0)
        {
            throw new InvalidOperationException(
                "Runtime log buffer did not enforce entry bounds and report overflow. "
                + $"Drained={drainedEntries}, Characters={drainedCharacters}, Dropped={sink.DroppedLogCount}");
        }

        long droppedBeforeLargeMessage = sink.DroppedLogCount;
        sink.DoAppend(new LoggingEvent(new LoggingEventData
        {
            LoggerName = "OpenVisionLab.OVL03",
            Level = Level.Error,
            Message = new string('x', RuntimeLogSink.DefaultMaxBufferedCharacters + 1),
            TimeStampUtc = DateTime.UtcNow
        }));
        if (sink.DroppedLogCount <= droppedBeforeLargeMessage)
        {
            throw new InvalidOperationException("Runtime log buffer did not count an oversized message as omitted.");
        }

        RuntimeLogStream disposedStream = new RuntimeLogStream();
        Parallel.For(0, 16, _ => disposedStream.Dispose());
        if (disposedStream.GetLogs().Length != 0 || !string.IsNullOrEmpty(disposedStream.GetLog()))
        {
            throw new InvalidOperationException("Concurrent disposal left the runtime log stream readable.");
        }

        LogPanelView view = new LogPanelView();
        try
        {
            LogPanelViewModel viewModel = (LogPanelViewModel)view.DataContext;
            ILog uiLogger = LogManager.GetLogger("OpenVisionLab.OVL03.UI");
            for (int i = 0; i < RuntimeLogSink.DefaultMaxBufferedEntries * 2; i++)
            {
                uiLogger.Info(
                    "[System][Info][Program.Main] OVL03-UI-"
                    + i.ToString(CultureInfo.InvariantCulture));
            }

            Thread.Sleep(320);
            Pump(8);
            if (viewModel.DroppedLogCount <= 0 || string.IsNullOrWhiteSpace(viewModel.DroppedLogText))
            {
                throw new InvalidOperationException(
                    "Log panel did not expose the runtime display-buffer omission count.");
            }

            return CaptureElement(view, outputPath, 900, 360);
        }
        finally
        {
            view.RaiseEvent(new RoutedEventArgs(FrameworkElement.UnloadedEvent));
        }
    }

