                Require(expander.Foreground.ToString() == ((Brush)expander.FindResource("OpenVision.Workbench.TextBrush")).ToString() && expander.Background.ToString() == ((Brush)expander.FindResource("OpenVision.Workbench.RaisedBrush")).ToString(), theme + "/" + state + " semantic owner colors");
