                Require(headerText.Foreground.ToString() == ((Brush)expander.FindResource(expander.IsEnabled ? "OpenVision.Workbench.TextBrush" : "OpenVision.Workbench.MutedTextBrush")).ToString(), theme + "/" + state + " rendered header foreground");
                Require(body.Select(item => item.Text).SequenceEqual(text) && window.SelectedTopicIndexForTest == 1, theme + "/" + state + " unchanged topic/content");
