                    Require(body.All(item => GetContrastRatio(((SolidColorBrush)item.Foreground).Color, ((SolidColorBrush)content.Background).Color) >= 4.5D), theme + "/" + state + " body contrast at least 4.5");
                    Rect contentBounds = content.TransformToAncestor(expander).TransformBounds(new Rect(0, 0, content.ActualWidth, content.ActualHeight)); Rect headerBounds = header.TransformToAncestor(expander).TransformBounds(new Rect(0, 0, header.ActualWidth, header.ActualHeight));
