                states.Add(new { Theme = theme, State = state, Width = window.ActualWidth, window.ActualHeight, expander.IsExpanded, expander.IsEnabled, toggle.IsKeyboardFocusWithin, HeaderForeground = BrushValue(headerText.Foreground), HeaderBackground = BrushValue(header.Background), ContentBackground = BrushValue(content.Background), BodyForeground = body.Select(item => BrushValue(item.Foreground)).ToArray(), StyleType = expander.Style?.TargetType.FullName, BasedOn = expander.Style?.BasedOn?.TargetType.FullName, Template = expander.Template.GetType().FullName, BackgroundSource = DependencyPropertyHelper.GetValueSource(header, Border.BackgroundProperty).BaseValueSource.ToString(), Capture = capture });
