            byte[] Staged() { VisionPipeline value = new(); value.Steps.Add(binding.CreateStep()); return VisionPipelineExecutionPlan.SerializePipeline(value); } byte[] staged = Staged();
            string route = host.ActiveHostLayerTitle; int runs = host.NativePreviewRunCount, layers = display.LayerCount;
            void Retained(string id) => Require(ReferenceEquals(binding, ReadPrivateField<OpenVisionWorkbenchToolViewModel.EditorBinding>(root.Tool, "editor")) && ReferenceEquals(test, ReadPrivateField<object>(root.Tool, "test")) && working.SequenceEqual(VisionPipelineExecutionPlan.SerializePipeline(root.Pipeline.WorkingCopyForTest)) && staged.SequenceEqual(Staged()) && ReferenceEquals(current, root.Images.CurrentImage) && ReferenceEquals(result, current.Result) && ReferenceEquals(bitmapRef, display.ImageSpace.GetImage("Main")) && runs == host.NativePreviewRunCount && layers == display.LayerCount && route == host.ActiveHostLayerTitle, id + " preserves pending editor/value/input/result/working/run/layer/route");
            var selected = Open(baseline ? 0 : 1, "selected Mean");
            ScreenshotPngWriter.WriteElementPng(selected, Path.ChangeExtension(outputPath, ".selected-ko.png"), (int)selected.ActualWidth, (int)selected.ActualHeight);
            entry.Command.Execute(entry.CommandParameter); Pump(3); Require(ReferenceEquals(selected, GetVisibleLearnWindow("repeat")), "repeat reuses one Learn Window"); Retained("selected/repeat"); selected.Close(); Pump(3); Retained("close");
            if (!baseline)
            {
                Action<string> callback = root.Tool.OpenLearnRequested; root.Tool.OpenLearnRequested = null;
                try { var fallback = Open(0, "unavailable Tool action default"); fallback.Close(); Pump(3); Retained("unavailable fallback"); }
                finally { root.Tool.OpenLearnRequested = callback; }
                var retry = Open(1, "valid retry"); Require(!ReferenceEquals(selected, retry), "closed Window recreated"); retry.Close(); Pump(3); Retained("retry");
            }
            File.WriteAllText(Path.ChangeExtension(outputPath, ".scope.json"), JsonSerializer.Serialize(new { Baseline = baseline, ShownSourceHost = true, ActualProductGui = false, EngineRun = false, SyntheticRetainedResult = true, Native125 = false }));
        }); }
        finally { foreach (var learn in System.Windows.Application.Current.Windows.OfType<OpenVisionLearnWindow>().Where(item => ReferenceEquals(item.Owner, window)).ToList()) learn.Close(); }
    }

