            }
            void Coordinates(IInlineImageEditPresentation presentation, int x, int y, int width, int height)
            {
                string[] values = { x.ToString(), y.ToString(), width.ToString(), height.ToString() };
                for (int index = 0; index < 4; index++) { presentation.InlineFields[index].SetCurrentValue(TextBox.TextProperty, values[index]); }
