                Rect bounds = pane.TransformToVisual(overlay).TransformBounds(new Rect(pane.RenderSize)); Require(Math.Abs(view.Width - bounds.Width) < .01 && Math.Abs(view.Height - bounds.Height) < .01 && Math.Abs(view.Margin.Left - bounds.Left) < .01, "resize follows same input pane"); Capture("roi-compact-ko"); ui.HandleKey(Key.Escape, ModifierKeys.None, false);
