            Require(line.CreateProperty().CvROI == initial && !root.Tool.IsResultPrevious, "cancel preserves original ROI and result freshness"); Retained("cancel");
            // First and second requests have no idle restoration callback between them.
            Start((ui, editor, presentation, model) =>
            {
                using (PropertyGridEditorFactory.BeginImageEditWriteScope(nativeOwner)) { Require(!PropertyGridEditorFactory.ShowImageEdit(editor, nativeOwner) && !VisionToolDebouncedPreviewScheduler.GetAllowAutoPreview(nativeOwner), "nested same-caller request cannot restore AUTO"); }
                Coordinates(presentation, 11, 13, 71, 53); ui.HandleKey(Key.Enter, ModifierKeys.None, true);
            }, () => entry.Command.Execute(entry.CommandParameter));
            Require(line.CreateProperty().CvROI == new OpenCvSharp.Rect(11, 13, 71, 53) && root.Tool.IsResultPrevious, "Enter writes selected ROI and marks retained test result previous"); Retained("Apply");
