    private static CaptureResult CaptureRoiEditor(string outputPath)
    {
        using Bitmap bitmap = CreateLargeSmokeBitmap(640, 480);
        RoiEditorWindow window = new(bitmap, new DrawingRectangle(0, 0, 640, 480), "ROI")
        {
            Width = 1040,
            Height = 700,
            ShowInTaskbar = false,
            WindowStartupLocation = WindowStartupLocation.Manual,
            Left = -32000,
            Top = -32000
        };

        return CaptureStandaloneWindow(window, outputPath, 1040, 700, () =>
        {
            AssertVisibleAutomationIds(
                window,
                "ROI editor zoom toolbar",
                "RoiViewportCanvas",
                "RoiFullButton",
                "RoiZoomOutButton",
                "RoiZoomValueText",
                "RoiFitViewButton",
                "RoiZoomInButton");

            OpenCvSharp.Rect initial = window.CurrentSelectedRegionForTest;
            if (initial.X != 0 || initial.Y != 0 || initial.Width != 640 || initial.Height != 480)
            {
                throw new InvalidOperationException($"ROI editor did not retain the full-image ROI. Actual={initial}.");
            }

            if (!window.IsLeftHandleInsideViewportForTest)
            {
                throw new InvalidOperationException("ROI editor clipped a full-image edge handle at fit view.");
            }

            if (!window.ResizeSelectedLeftEdgeByDisplayPixelsForTest(64))
            {
                throw new InvalidOperationException("ROI editor could not resize the full-image ROI from its left edge.");
            }

            OpenCvSharp.Rect fitResize = window.CurrentSelectedRegionForTest;
            int fitDelta = fitResize.X - initial.X;
            if (fitDelta <= 0 || fitResize.Right != initial.Right)
            {
                throw new InvalidOperationException($"ROI editor left-edge resize changed the wrong boundary. Actual={fitResize}.");
            }

            window.ZoomAndPanForTest(4, 24, -16);
            if (Math.Abs(window.ZoomLevelForTest - 4) > 0.001)
            {
                throw new InvalidOperationException($"ROI editor did not retain the requested zoom. Actual={window.ZoomLevelForTest:0.###}.");
            }

            if (!window.ResizeSelectedLeftEdgeByDisplayPixelsForTest(8))
            {
                throw new InvalidOperationException("ROI editor could not resize an ROI after zoom and pan.");
            }

            OpenCvSharp.Rect zoomResize = window.CurrentSelectedRegionForTest;
            int fineDelta = zoomResize.X - fitResize.X;
            if (fineDelta <= 0 || fineDelta >= fitDelta || zoomResize.Right != initial.Right)
            {
                throw new InvalidOperationException(
                    $"ROI editor zoomed resize was not finer than fit-view resize. FitDelta={fitDelta}, FineDelta={fineDelta}, Actual={zoomResize}.");
            }

            window.ZoomAndPanForTest(1, 0, 0);
            if (Math.Abs(window.ZoomLevelForTest - 1) > 0.001 || !window.IsLeftHandleInsideViewportForTest)
            {
                throw new InvalidOperationException("ROI editor did not restore a fully editable fit view after zoomed editing.");
            }
        });
    }

    private static CaptureResult CapturePipelineReviewEntryPerf(string outputPath)
    {
        OpenVisionLanguageService.SetLanguage(OpenVisionLanguage.Korean, false);
        string initialRecipeName = "Smoke_PipelineReviewEntryInitial_" + Guid.NewGuid().ToString("N");
        string switchedRecipeName = "Smoke_PipelineReviewEntrySwitched_" + Guid.NewGuid().ToString("N");
        VisionPipeline pipeline = CreatePipelineReviewReadabilityPipeline();
        for (int index = pipeline.Steps.Count; index < 40; index++)
        {
            FilterToolProperty filter = new()
            {
                KernelWidth = 3,
                KernelHeight = 3,
                MedianKernelSize = 3,
                Diameter = 3,
                SigmaColor = 3,
                SigmaSpace = 3
            };
            pipeline.Steps.Add(VisionPipelineStepBuilder.FromFilterProperty(
                filter,
                "Perf_Filter_" + index.ToString("00", CultureInfo.InvariantCulture),
                "Main",
                "Perf_Filter_" + index.ToString("00", CultureInfo.InvariantCulture) + "_Preview"));
        }
        VisionPipelineStorage.Save(initialRecipeName, pipeline);
        VisionPipelineStorage.SaveActivePipelineName(initialRecipeName, pipeline.Name);
        VisionPipelineStorage.Save(switchedRecipeName, pipeline);
        VisionPipelineStorage.SaveActivePipelineName(switchedRecipeName, pipeline.Name);
        OpenVisionShellHostView shellHost = CreateShellHost(initialRecipeName);
        List<string> lines = new()
        {
            "Path|CachedBefore|SelectMs|ReadyMs|InternalTiming|RunsBefore|RunsAfter|LayerCountBefore|LayerCountAfter|ActiveLayerBefore|ActiveLayerAfter|InputRouteBefore|InputRouteAfter|OutputRouteBefore|OutputRouteAfter"
        };

        try
        {
            return CaptureWindowWithContent(shellHost, outputPath, 1600, 900, () =>
            {
                WaitForPipelineReviewPrewarm(shellHost, "Startup");
                MeasurePipelineReviewEntry(shellHost, "Startup", lines);

                shellHost.SwitchRecipeContextForTest(switchedRecipeName);
                WaitForPipelineReviewPrewarm(shellHost, "RecipeSwitch");
                MeasurePipelineReviewEntry(shellHost, "RecipeSwitch", lines);

                shellHost.SelectToolForTest(VISION_MENU.Threshold);
                if (shellHost.AddActiveNativePipelineStepForTest() == null)
                {
                    throw new InvalidOperationException("Threshold Step could not be added before immediate Pipeline entry.");
                }

                MeasurePipelineReviewEntry(shellHost, "ImmediateAfterToolAndStepAdd", lines);

                File.WriteAllLines(Path.ChangeExtension(outputPath, ".perf.txt"), lines, System.Text.Encoding.UTF8);
            });
        }
        finally
        {
            RecipeWorkspaceService.DeleteVisionWorkspace(initialRecipeName);
            RecipeWorkspaceService.DeleteVisionWorkspace(switchedRecipeName);
        }
    }

    private static void WaitForPipelineReviewPrewarm(OpenVisionShellHostView shellHost, string path)
    {
        Stopwatch stopwatch = Stopwatch.StartNew();
        while (!shellHost.HasPipelineReviewDocumentForTest && stopwatch.ElapsedMilliseconds < 3000)
        {
            Thread.Sleep(20);
            Pump(1);
        }

        if (!shellHost.HasPipelineReviewDocumentForTest)
        {
            throw new InvalidOperationException(
                $"Pipeline Review was not prepared after the {path} idle interval. ElapsedMs={stopwatch.ElapsedMilliseconds}.");
        }
    }

    private static void MeasurePipelineReviewEntry(
        OpenVisionShellHostView shellHost,
        string path,
        List<string> lines)
    {
        bool cachedBefore = shellHost.HasPipelineReviewDocumentForTest;
        int runsBefore = shellHost.NativePreviewRunCount;
        int layersBefore = shellHost.HostLayerRowCount;
        string activeLayerBefore = shellHost.ActiveHostLayerTitle;
        string inputRouteBefore = shellHost.ActiveNativeRouteInputLayerNameForTest;
        string outputRouteBefore = shellHost.ActiveNativeRouteOutputLayerNameForTest;
        Stopwatch stopwatch = Stopwatch.StartNew();
        shellHost.OpenSamplePipelineForTest();
        long selectMs = stopwatch.ElapsedMilliseconds;
        Pump(12);
        long readyMs = stopwatch.ElapsedMilliseconds;
        int runsAfter = shellHost.NativePreviewRunCount;
        int layersAfter = shellHost.HostLayerRowCount;
        string inputRouteAfter = inputRouteBefore;
        string outputRouteAfter = outputRouteBefore;
        if (string.Equals(path, "ImmediateAfterToolAndStepAdd", StringComparison.Ordinal))
        {
            shellHost.SelectToolForTest(VISION_MENU.Threshold);
            Pump(4);
            inputRouteAfter = shellHost.ActiveNativeRouteInputLayerNameForTest;
            outputRouteAfter = shellHost.ActiveNativeRouteOutputLayerNameForTest;
            shellHost.OpenSamplePipelineForTest();
            Pump(4);
            runsAfter = shellHost.NativePreviewRunCount;
            layersAfter = shellHost.HostLayerRowCount;
        }
        if (!cachedBefore
            || !shellHost.HasPipelineReviewDocumentForTest
            || !shellHost.IsNativeDocumentActive
            || runsAfter != runsBefore
            || layersAfter != layersBefore
            || !string.Equals(shellHost.ActiveHostLayerTitle, activeLayerBefore, StringComparison.Ordinal)
            || !string.Equals(inputRouteAfter, inputRouteBefore, StringComparison.Ordinal)
            || !string.Equals(outputRouteAfter, outputRouteBefore, StringComparison.Ordinal))
        {
            throw new InvalidOperationException(
                $"Pipeline Review entry contract failed for {path}. CachedBefore={cachedBefore}, "
                + $"CachedAfter={shellHost.HasPipelineReviewDocumentForTest}, Active={shellHost.IsNativeDocumentActive}, "
                + $"Runs={runsBefore}/{runsAfter}, Layers={layersBefore}/{layersAfter}, "
                + $"ActiveLayer='{activeLayerBefore}'/'{shellHost.ActiveHostLayerTitle}', "
                + $"InputRoute='{inputRouteBefore}'/'{inputRouteAfter}', "
                + $"OutputRoute='{outputRouteBefore}'/'{outputRouteAfter}', "
                + $"Timing='{shellHost.LastToolOpenTimingTextForTest}'.");
        }

        lines.Add(string.Join(
            "|",
            path,
            "CachedBefore=" + cachedBefore.ToString(CultureInfo.InvariantCulture),
            "SelectMs=" + selectMs.ToString(CultureInfo.InvariantCulture),
            "ReadyMs=" + readyMs.ToString(CultureInfo.InvariantCulture),
            shellHost.LastToolOpenTimingTextForTest,
            "RunsBefore=" + runsBefore.ToString(CultureInfo.InvariantCulture),
            "RunsAfter=" + runsAfter.ToString(CultureInfo.InvariantCulture),
            "LayerCountBefore=" + layersBefore.ToString(CultureInfo.InvariantCulture),
            "LayerCountAfter=" + layersAfter.ToString(CultureInfo.InvariantCulture),
            "ActiveLayerBefore=" + activeLayerBefore,
            "ActiveLayerAfter=" + shellHost.ActiveHostLayerTitle,
            "InputRouteBefore=" + inputRouteBefore,
            "InputRouteAfter=" + inputRouteAfter,
            "OutputRouteBefore=" + outputRouteBefore,
            "OutputRouteAfter=" + outputRouteAfter));
    }

    private static CaptureResult CaptureMatchingPropertyGridCombo(string outputPath)
    {
        OpenVisionLanguageService.SetLanguage(OpenVisionLanguage.Korean, false);
        MatchingProperty policyProbe = new MatchingProperty();
        if (!OpenVisionLab.Common.PropertyGridToolPolicy.IsChildParameterProperty(policyProbe, "FIND_ANGLE")
            || OpenVisionLab.Common.PropertyGridToolPolicy.IsChildParameterProperty(policyProbe, "SCORE_MIN"))
        {
            throw new InvalidOperationException("Matching PropertyGrid application policy classification changed.");
        }

        System.Windows.Controls.WpfPropertyGrid.PropertyGrid grid = new()
        {
            SelectedObject = policyProbe
        };
        OpenVisionLab.PropertyGrid.PropertyGridDisplayOptions displayOptions =
            OpenVisionLab.PropertyGrid.PropertyGridDisplayOptions.ToolForm;
        displayOptions.ChildParameterPredicate = OpenVisionLab.Common.PropertyGridToolPolicy.IsChildParameterProperty;
        grid.ApplyDisplayOptions(displayOptions);

        return CaptureWindowWithContent(grid, outputPath, 760, 520, () =>
        {
            ComboBox? matchModeCombo = FindVisualChildren<ComboBox>(grid)
                .FirstOrDefault(combo => combo.Items.Cast<object>().Any(item =>
                    string.Equals(Convert.ToString(item, CultureInfo.InvariantCulture), "CCoeffNormed", StringComparison.Ordinal)));
            if (matchModeCombo == null)
            {
                throw new InvalidOperationException("Matching property grid combo was not found.");
            }

            matchModeCombo.BringIntoView();
            Pump(16);
            matchModeCombo.UpdateLayout();

            AssertComboBoxPopupLayout(matchModeCombo, "Matching property grid combo");
            AssertPropertyGridBridgeComboTemplate(matchModeCombo, "Matching property grid combo");
            AssertComboBoxSelectionTextIsSingle(matchModeCombo, "CCoeffNormed", "Matching property grid combo");
            AssertPropertyGridRangeEditorLayout(grid, "Matching property grid range editor");
            AssertPropertyGridChildRowPresentation(grid, "FIND_ANGLE", "Matching child-row policy");
        }, captureFloatingToolWindow: false);
    }

    private static CaptureResult CaptureImageCanvasOwnedMatLoad(string outputPath)
    {
        string artifactDirectory = Path.GetDirectoryName(outputPath)
            ?? throw new InvalidOperationException("ImageCanvas owned-load artifact directory is missing.");
        Directory.CreateDirectory(artifactDirectory);
        string grayPath = Path.Combine(artifactDirectory, "owned_loader_gray.png");
        string colorPath = Path.Combine(artifactDirectory, "owned_loader_color.png");

        using (CvMat gray = new(240, 320, OpenCvSharp.MatType.CV_8UC1, OpenCvSharp.Scalar.All(36)))
        {
            Cv.Circle(gray, new OpenCvSharp.Point(92, 120), 48, OpenCvSharp.Scalar.All(210), -1, OpenCvSharp.LineTypes.AntiAlias);
            Cv.ImWrite(grayPath, gray);
        }

        using (CvMat color = new(384, 512, OpenCvSharp.MatType.CV_8UC3, new OpenCvSharp.Scalar(24, 31, 36)))
        {
            Cv.Rectangle(color, new OpenCvSharp.Rect(70, 76, 170, 116), new OpenCvSharp.Scalar(74, 176, 222), -1);
            Cv.Circle(color, new OpenCvSharp.Point(368, 194), 74, new OpenCvSharp.Scalar(210, 162, 48), 8, OpenCvSharp.LineTypes.AntiAlias);
            Cv.PutText(color, "Owned Mat", new OpenCvSharp.Point(64, 304), OpenCvSharp.HersheyFonts.HersheySimplex, 1.1, OpenCvSharp.Scalar.White, 2, OpenCvSharp.LineTypes.AntiAlias);
            Cv.ImWrite(colorPath, color);
        }

        OpenVisionLab.ImageCanvas.ViewModels.RoiImageCanvasViewModel viewModel =
            new("OwnedMatLoaderSmoke");
        OpenVisionLab.ImageCanvas.Views.RoiImageCanvasView view = new()
        {
            DataContext = viewModel,
            ShowStatusBar = true,
            ShowToolBar = false
        };

        try
        {
            return CaptureWindowWithContent(view, outputPath, 820, 600, () =>
            {
                System.Drawing.Size canvasSize = view.ImageViewerForTest.ClientSize;
                if (canvasSize.Width <= 0 || canvasSize.Height <= 0)
                {
                    throw new InvalidOperationException($"Shown ImageCanvas has no native viewport: {canvasSize}.");
                }

                LoadOwnedCanvasMatCase(viewModel, grayPath, OpenCvSharp.MatType.CV_8UC1, Path.Combine(artifactDirectory, "owned_loader_gray_saved.png"));
                LoadOwnedCanvasMatCase(viewModel, colorPath, OpenCvSharp.MatType.CV_8UC3, Path.Combine(artifactDirectory, "owned_loader_color_saved.png"));
            });
        }
        finally
        {
            view.Dispose();
            viewModel.Dispose();
        }
    }

    private static void LoadOwnedCanvasMatCase(
        OpenVisionLab.ImageCanvas.ViewModels.RoiImageCanvasViewModel viewModel,
        string sourcePath,
        OpenCvSharp.MatType expectedType,
        string savedPath)
    {
        using (CvMat loaded = OpenVisionLab.ImageCanvas.CanvasImageLoader.LoadMatFromFile(sourcePath))
        {
            if (loaded.Empty() || loaded.Type() != expectedType)
            {
                throw new InvalidOperationException(
                    $"ImageCanvas owned file load returned {loaded.Type()} for {Path.GetFileName(sourcePath)}, expected {expectedType}.");
            }

            viewModel.LoadImage(loaded, Path.GetFileName(sourcePath));
            viewModel.FitImageToView();
        }

        GC.Collect();
        GC.WaitForPendingFinalizers();
        GC.Collect();
        Pump(20);

        int textureTileCount = viewModel.TextureTileCount;
        if (textureTileCount < 1 || !viewModel.SaveCurrentImage(savedPath))
        {
            throw new InvalidOperationException(
                $"ImageCanvas did not retain/upload/save {Path.GetFileName(sourcePath)} after the loader Mat was disposed. Tiles={textureTileCount}.");
        }

        using CvMat saved = Cv.ImRead(savedPath, CvImreadModes.Unchanged);
        if (saved.Empty() || saved.Type() != expectedType)
        {
            throw new InvalidOperationException(
                $"ImageCanvas retained save returned {saved.Type()} for {Path.GetFileName(sourcePath)}, expected {expectedType}.");
        }
    }

    private static CaptureResult CaptureOpenGlTemplateEditor(string outputPath)
    {
        using Bitmap bitmap = CreateRoiSmokeBitmap();
        OpenGlTemplateEditorWindow window = new(bitmap, new DrawingRectangle(116, 82, 210, 142), "TRAIN")
        {
            Width = 1040,
            Height = 700,
            ShowInTaskbar = false,
            WindowStartupLocation = WindowStartupLocation.Manual,
            Left = -32000,
            Top = -32000
        };

        return CaptureStandaloneWindow(window, outputPath, 1040, 700, () =>
        {
            var selected = window.SelectedRegion;
            if (selected.Width <= 0 || selected.Height <= 0)
            {
                throw new InvalidOperationException("OpenGL template editor did not keep the initial selected region.");
            }

            if (Math.Abs(selected.X - 116) > 2
                || Math.Abs(selected.Y - 82) > 2
                || Math.Abs(selected.Width - 210) > 2
                || Math.Abs(selected.Height - 142) > 2)
            {
                throw new InvalidOperationException($"OpenGL template editor returned unexpected ROI {selected}.");
            }

            bool hasPatternPreview = FindVisualChildren<Image>(window)
                .Any(item => item.IsVisible && item.Source != null && item.ActualWidth > 0D && item.ActualHeight > 0D);
            if (!hasPatternPreview)
            {
                throw new InvalidOperationException("OpenGL template editor did not render a pattern preview image.");
            }

            bool hasMainSourceImage = FindVisualChildren<Image>(window)
                .Any(item => string.Equals(item.Name, "wpfSourceImage", StringComparison.Ordinal)
                    && item.IsVisible
                    && item.Source != null
                    && item.ActualWidth > 0D
                    && item.ActualHeight > 0D);
            if (!hasMainSourceImage)
            {
                throw new InvalidOperationException("Template editor did not render the main source image.");
            }

            if (window.RoiHandleVisualCountForTest < 8)
            {
                throw new InvalidOperationException("Template editor did not render ROI resize handles.");
            }

            if (!window.MoveSelectedRegionForTest(12, -7))
            {
                throw new InvalidOperationException("Template editor could not move the selected ROI.");
            }

            selected = window.SelectedRegion;
            if (Math.Abs(selected.X - 128) > 2 || Math.Abs(selected.Y - 75) > 2)
            {
                throw new InvalidOperationException($"Template editor ROI move returned unexpected ROI {selected}.");
            }

            if (!window.ResizeSelectedRegionForTest(18, 11))
            {
                throw new InvalidOperationException("Template editor could not resize the selected ROI.");
            }

            selected = window.SelectedRegion;
            if (Math.Abs(selected.Width - 228) > 2 || Math.Abs(selected.Height - 153) > 2)
            {
                throw new InvalidOperationException($"Template editor ROI resize returned unexpected ROI {selected}.");
            }

            if (!window.SetTemplateRotationDegreesForTest(17.5))
            {
                throw new InvalidOperationException("Template editor could not set ROI rotation.");
            }

            if (Math.Abs(window.TemplateRotationDegreesForTest - 17.5) > 0.001)
            {
                throw new InvalidOperationException($"Template editor returned unexpected ROI rotation {window.TemplateRotationDegreesForTest:0.###}.");
            }

            if (window.RoiHandleVisualCountForTest < 10)
            {
                throw new InvalidOperationException("Template editor did not render ROI rotation handle.");
            }

            using OpenCvSharp.Mat sourceMat = OpenVisionLab.Common.BitmapImageConverter.ToMat(bitmap);
            using OpenCvSharp.Mat extractedTemplate = TemplateImageExtraction.Extract(
                sourceMat,
                window.SelectedRegion,
                window.TemplateRotationDegreesForTest);
            if (extractedTemplate.Empty()
                || extractedTemplate.Width != window.SelectedRegion.Width
                || extractedTemplate.Height != window.SelectedRegion.Height)
            {
                throw new InvalidOperationException("Template editor rotation did not produce a valid zero-degree extracted template.");
            }
        });
    }

    private static CaptureResult CaptureOpenGlNativeReadback(string outputPath)
    {
        string artifactDirectory = Path.GetDirectoryName(outputPath)
            ?? throw new InvalidOperationException("OpenGL native-readback artifact directory is missing.");
        Directory.CreateDirectory(artifactDirectory);

        const int width = 4;
        const int height = 4;
        byte[] expected = new byte[width * height * 4];
        byte[] upload = new byte[expected.Length];
        for (int y = 0; y < height; y++)
        {
            for (int x = 0; x < width; x++)
            {
                int expectedIndex = ((y * width) + x) * 4;
                expected[expectedIndex] = (byte)(17 + (x * 29) + (y * 7));
                expected[expectedIndex + 1] = (byte)(23 + (x * 11) + (y * 31));
                expected[expectedIndex + 2] = (byte)(41 + (x * 37) + (y * 13));
                expected[expectedIndex + 3] = 255;

                int uploadIndex = (((height - 1 - y) * width) + x) * 4;
                upload[uploadIndex] = expected[expectedIndex + 2];
                upload[uploadIndex + 1] = expected[expectedIndex + 1];
                upload[uploadIndex + 2] = expected[expectedIndex];
                upload[uploadIndex + 3] = expected[expectedIndex + 3];
            }
        }

        string sourceRawPath = Path.Combine(artifactDirectory, "native_readback_source.rgba");
        string sourcePngPath = Path.Combine(artifactDirectory, "native_readback_source.png");
        File.WriteAllBytes(sourceRawPath, expected);
        using (Bitmap sourceBitmap = new(width, height, System.Drawing.Imaging.PixelFormat.Format32bppArgb))
        {
            for (int y = 0; y < height; y++)
            {
                for (int x = 0; x < width; x++)
                {
                    int index = ((y * width) + x) * 4;
                    sourceBitmap.SetPixel(
                        x,
                        y,
                        DrawingColor.FromArgb(expected[index + 3], expected[index], expected[index + 1], expected[index + 2]));
                }
            }
            sourceBitmap.Save(sourcePngPath, ImageFormat.Png);
        }
        string sourceRawSha256 = Convert.ToHexString(SHA256.HashData(expected));
        string sourcePngSha256 = Convert.ToHexString(SHA256.HashData(File.ReadAllBytes(sourcePngPath)));

        OpenVisionLab.ImageCanvas.ViewModels.RoiImageCanvasViewModel viewModel =
            new("OpenGlNativeReadbackSmoke");
        OpenVisionLab.ImageCanvas.Views.RoiImageCanvasView view = new()
        {
            DataContext = viewModel,
            ShowStatusBar = true,
            ShowToolBar = false
        };

        try
        {
            return CaptureWindowWithContent(view, outputPath, 820, 600, () =>
            {
                using (CvMat display = new(32, 32, OpenCvSharp.MatType.CV_8UC3, new OpenCvSharp.Scalar(44, 54, 64)))
                {
                    viewModel.LoadImage(display, "opengl-native-readback.png");
                    viewModel.FitImageToView();
                }

                var viewer = view.ImageViewerForTest;
                dynamic gl = (object)viewer.GetOpenGL();
                uint textureId = viewer.GenerateOpenGLTexture(width, height, 4);
                GCHandle uploadHandle = GCHandle.Alloc(upload, GCHandleType.Pinned);
                try
                {
                    viewer.UpdateTexture(uploadHandle.AddrOfPinnedObject(), width, height, 4, textureId);
                }
                finally
                {
                    uploadHandle.Free();
                }

                bool forcedExceptionObserved = false;
                try
                {
                    OpenVisionLab.ImageCanvas.OpenGlRenderer.SetupFrameAndRenderBuffers(
                        gl,
                        textureId,
                        width,
                        height,
                        (Action)(() => throw new InvalidOperationException("forced OpenGL cleanup reproduction")));
                }
                catch (InvalidOperationException exception) when (exception.Message.Contains("forced OpenGL cleanup reproduction", StringComparison.Ordinal))
                {
                    forcedExceptionObserved = true;
                }

                if (!forcedExceptionObserved)
                {
                    throw new InvalidOperationException("Forced OpenGL exception was not preserved as the primary failure.");
                }

                OpenVisionLab.ImageCanvas.OpenGlRenderer.SetupFrameAndRenderBuffers(
                    gl,
                    textureId,
                    width,
                    height,
                    (Action)(() =>
                    {
                        gl.ClearColor(0.13F, 0.27F, 0.41F, 1F);
                        gl.Clear(0x00004000U);
                    }));

                DrawingColor renderedColor = viewer.ReadTextureColor(gl, textureId, 0, 0);
                if (renderedColor.R < 30 || renderedColor.G < 50 || renderedColor.B < 70 || renderedColor.A < 240)
                {
                    throw new InvalidOperationException(
                        $"Rendering after forced cleanup did not produce the expected clear color: {renderedColor}.");
                }

                uploadHandle = GCHandle.Alloc(upload, GCHandleType.Pinned);
                try
                {
                    viewer.UpdateTexture(uploadHandle.AddrOfPinnedObject(), width, height, 4, textureId);
                }
                finally
                {
                    uploadHandle.Free();
                }

                for (int y = 0; y < height; y++)
                {
                    for (int x = 0; x < width; x++)
                    {
                        int index = ((y * width) + x) * 4;
                        DrawingColor color = viewer.ReadTextureColor(gl, textureId, x, y);
                        AssertNativeColor(color, expected, index, $"pixel({x},{y})");
                    }
                }

                byte[] fullRegion = viewer.ReadTextureRegionColors(gl, textureId, 0, 0, width, height, width, height);
                AssertNativeBytes(fullRegion, expected, "full region");

                byte[] rightBottomPixel = viewer.ReadTextureRegionColors(gl, textureId, width - 1, height - 1, 1, 1, width, height);
                AssertNativeBytes(rightBottomPixel, expected, ((height - 1) * width + (width - 1)) * 4, "bottom-right 1x1 region");

                byte[] rightEdge = viewer.ReadTextureRegionColors(gl, textureId, width - 1, 0, 1, height, width, height);
                for (int y = 0; y < height; y++)
                {
                    AssertNativeBytes(rightEdge, expected, (y * width + width - 1) * 4, y * 4, "right edge row " + y);
                }

                byte[] bottomEdge = viewer.ReadTextureRegionColors(gl, textureId, 0, height - 1, width, 1, width, height);
                AssertNativeBytes(bottomEdge, expected, (height - 1) * width * 4, "bottom edge");

                byte[] centerRegion = viewer.ReadTextureRegionColors(gl, textureId, 2, 1, 2, 3, width, height);
                if (centerRegion.Length != 2 * 3 * 4)
                {
                    throw new InvalidOperationException($"Region readback returned {centerRegion.Length} bytes instead of 24.");
                }
                for (int regionY = 0; regionY < 3; regionY++)
                {
                    for (int regionX = 0; regionX < 2; regionX++)
                    {
                        int sourceIndex = (((1 + regionY) * width) + 2 + regionX) * 4;
                        int regionIndex = ((regionY * 2) + regionX) * 4;
                        AssertNativeBytes(centerRegion, expected, sourceIndex, regionIndex, $"interior region ({regionX},{regionY})");
                    }
                }

                byte[] clampedCornerRegion = viewer.ReadTextureRegionColors(gl, textureId, new System.Drawing.PointF(0.2F, 0.2F), 1, width, height);
                if (clampedCornerRegion.Length != 2 * 2 * 4)
                {
                    throw new InvalidOperationException($"Corner region readback returned {clampedCornerRegion.Length} bytes instead of 16.");
                }

                byte[] restoreExpected = (byte[])expected.Clone();
                byte[] restoreUpload = new byte[restoreExpected.Length];
                for (int y = 0; y < height; y++)
                {
                    for (int x = 0; x < width; x++)
                    {
                        int index = ((y * width) + x) * 4;
                        restoreExpected[index] = (byte)(151 + (x * 13) + (y * 5));
                        restoreExpected[index + 1] = (byte)(83 + (x * 17) + (y * 19));
                        restoreExpected[index + 2] = (byte)(211 - (x * 11) - (y * 7));
                        restoreExpected[index + 3] = 255;

                        int uploadIndex = (((height - 1 - y) * width) + x) * 4;
                        restoreUpload[uploadIndex] = restoreExpected[index + 2];
                        restoreUpload[uploadIndex + 1] = restoreExpected[index + 1];
                        restoreUpload[uploadIndex + 2] = restoreExpected[index];
                        restoreUpload[uploadIndex + 3] = restoreExpected[index + 3];
                    }
                }

                uint backupTextureId = viewer.GenerateOpenGLTexture(width, height, 4);
                try
                {
                    GCHandle restoreHandle = GCHandle.Alloc(restoreUpload, GCHandleType.Pinned);
                    try
                    {
                        viewer.UpdateTexture(restoreHandle.AddrOfPinnedObject(), width, height, 4, backupTextureId);
                    }
                    finally
                    {
                        restoreHandle.Free();
                    }

                    OpenVisionLab.ImageCanvas.OpenGlRenderer.RestorePartTexture(
                        gl,
                        textureId,
                        backupTextureId,
                        width,
                        height,
                        1,
                        1,
                        2,
                        2);

                    for (int y = 0; y < height; y++)
                    {
                        for (int x = 0; x < width; x++)
                        {
                            int index = ((y * width) + x) * 4;
                            byte[] source = x >= 1 && x < 3 && y >= 1 && y < 3 ? restoreExpected : expected;
                            DrawingColor color = viewer.ReadTextureColor(gl, textureId, x, y);
                            AssertNativeColor(color, source, index, $"restored pixel({x},{y})");
                        }
                    }
                }
                finally
                {
                    gl.DeleteTextures(1, new[] { backupTextureId });
                }

                uploadHandle = GCHandle.Alloc(upload, GCHandleType.Pinned);
                try
                {
                    viewer.UpdateTexture(uploadHandle.AddrOfPinnedObject(), width, height, 4, textureId);
                }
                finally
                {
                    uploadHandle.Free();
                }

                foreach (Action invalidRead in new[]
                {
                    (Action)(() => viewer.ReadTextureColor(gl, textureId, -1, 0)),
                    () => viewer.ReadTextureColor(gl, textureId, width, 0),
                    () => viewer.ReadTextureColor(gl, textureId, 0, height)
                })
                {
                    bool rejected = false;
                    try { invalidRead(); }
                    catch (ArgumentOutOfRangeException) { rejected = true; }
                    if (!rejected) { throw new InvalidOperationException("An out-of-range native pixel read was accepted."); }
                }

                using (Bitmap bitmap = OpenVisionLab.ImageCanvas.OpenGlRenderer.TextureToBitmap(gl, textureId, 4))
                {
                    for (int y = 0; y < height; y++)
                    {
                        for (int x = 0; x < width; x++)
                        {
                            int index = ((y * width) + x) * 4;
                            AssertNativeColor(bitmap.GetPixel(x, y), expected, index, $"bitmap({x},{y})");
                        }
                    }

                    string bitmapEvidencePath = Path.Combine(artifactDirectory, "native_readback_bitmap.png");
                    using Bitmap enlarged = new(width * 100, height * 100);
                    using Graphics graphics = Graphics.FromImage(enlarged);
                    for (int y = 0; y < height; y++)
                    {
                        for (int x = 0; x < width; x++)
                        {
                            using System.Drawing.SolidBrush brush = new(bitmap.GetPixel(x, y));
                            graphics.FillRectangle(brush, x * 100, y * 100, 100, 100);
                        }
                    }
                    enlarged.Save(bitmapEvidencePath, System.Drawing.Imaging.ImageFormat.Png);
                }

                using CvMat mat = OpenVisionLab.ImageCanvas.OpenGlRenderer.TextureToMat(gl, textureId, 4);
                if (mat.Width != width || mat.Height != height || mat.Type() != OpenCvSharp.MatType.CV_8UC4)
                {
                    throw new InvalidOperationException($"Native Mat readback returned {mat.Width}x{mat.Height} type {mat.Type()}.");
                }

                File.WriteAllLines(Path.ChangeExtension(outputPath, ".coordinate.txt"), new[]
                {
                    "Result=PASS",
                    "Fixture=4x4 RGBA with distinct corners, edges, and interior values",
                    "UploadOrientation=Bottom-left native texture rows; expected comparisons are top-left image coordinates",
                    $"SourceRaw={sourceRawPath}|SHA256={sourceRawSha256}",
                    $"SourcePng={sourcePngPath}|SHA256={sourcePngSha256}",
                    "ForcedExceptionCleanup=PASS|SetupFrameAndRenderBuffers action exception preserved; subsequent clear render succeeded",
                    "PixelReadback=PASS|all 16 pixels, four corners, last row/column, and interior matched",
                    "RegionReadback=PASS|1x1, right edge, bottom edge, full, interior 2x3, and clamped corner region matched",
                    "RegionRestore=PASS|half-open [1,3) x [1,3) changed exactly four pixels; neighbors matched the original",
                    "Bounds=PASS|negative x, x==width, and y==height rejected",
                    "BitmapReadback=PASS|TextureToBitmap exact 4x4 identity",
                    "MatReadback=PASS|TextureToMat returned 4x4 CV_8UC4",
                    "NativePath=FBO + PBO + glReadPixels + MapBuffer",
                    "Screenshot=Current-source WPF viewer capture; native bitmap evidence is native_readback_bitmap.png"
                });

                gl.DeleteTextures(1, new[] { textureId });
                textureId = 0;
            });
        }
        finally
        {
            view.Dispose();
            viewModel.Dispose();
        }
    }

    private static void AssertNativeColor(DrawingColor actual, byte[] expected, int expectedIndex, string label)
    {
        if (actual.R != expected[expectedIndex]
            || actual.G != expected[expectedIndex + 1]
            || actual.B != expected[expectedIndex + 2]
            || actual.A != expected[expectedIndex + 3])
        {
            throw new InvalidOperationException(
                $"{label} mismatch. Actual=ARGB({actual.A},{actual.R},{actual.G},{actual.B}) "
                + $"Expected=ARGB({expected[expectedIndex + 3]},{expected[expectedIndex]},{expected[expectedIndex + 1]},{expected[expectedIndex + 2]}).");
        }
    }

    private static void AssertNativeBytes(byte[] actual, byte[] expected, string label)
    {
        if (actual.Length != expected.Length)
        {
            throw new InvalidOperationException($"{label} length mismatch. Actual={actual.Length}; Expected={expected.Length}.");
        }

        for (int i = 0; i < actual.Length; i++)
        {
            if (actual[i] != expected[i])
            {
                throw new InvalidOperationException($"{label} byte mismatch at index {i}.");
            }
        }
    }

    private static void AssertNativeBytes(byte[] actual, byte[] expected, int expectedIndex, string label)
    {
        AssertNativeBytes(actual, expected, expectedIndex, 0, label);
    }

    private static void AssertNativeBytes(byte[] actual, byte[] expected, int expectedIndex, int actualIndex, string label)
    {
        for (int channel = 0; channel < 4; channel++)
        {
            if (actualIndex + channel >= actual.Length || expectedIndex + channel >= expected.Length || actual[actualIndex + channel] != expected[expectedIndex + channel])
            {
                throw new InvalidOperationException($"{label} byte mismatch at channel {channel}.");
            }
        }
    }

    private static CaptureResult CaptureImageCompare(string outputPath)
    {
        string sampleDirectory = Path.Combine(Path.GetDirectoryName(outputPath) ?? ".", "image_compare_samples");
        Directory.CreateDirectory(sampleDirectory);

        string leftPath = Path.Combine(sampleDirectory, "compare_left.png");
        string rightPath = Path.Combine(sampleDirectory, "compare_right.png");
        using (Bitmap left = CreateRoiSmokeBitmap())
        using (Bitmap right = CreateRoiSmokeBitmap())
        {
            using (Graphics graphics = Graphics.FromImage(right))
            using (System.Drawing.SolidBrush brush = new(DrawingColor.FromArgb(180, 62, 116, 208)))
            {
                graphics.FillRectangle(brush, 248, 122, 86, 44);
            }

            left.Save(leftPath, System.Drawing.Imaging.ImageFormat.Png);
            right.Save(rightPath, System.Drawing.Imaging.ImageFormat.Png);
        }

        ImageCompareWindow window = new()
        {
            Width = 1280,
            Height = 760,
            ShowInTaskbar = false,
            WindowStartupLocation = WindowStartupLocation.Manual,
            Left = -32000,
            Top = -32000
        };
        window.LoadImages(leftPath, rightPath);

        return CaptureStandaloneWindow(window, outputPath, 1280, 760, () =>
        {
            if (window.DataContext is not ImageCompareViewModel viewModel ||
                viewModel.Slots.Count(slot => slot.IsLoaded) < 2)
            {
                throw new InvalidOperationException("Image Compare did not load the smoke images.");
            }

            ImageCompareSlotViewModel selectedSlot = viewModel.Slots.First(slot => slot.IsLoaded);
            viewModel.ApplyZoom(selectedSlot, 120);
            if (viewModel.Slots.Where(slot => slot.IsLoaded).Any(slot => slot.Zoom <= 1.0))
            {
                throw new InvalidOperationException("Image Compare synchronized zoom did not update loaded slots.");
            }

            viewModel.FitAll();
            viewModel.UpdatePixelStatus(selectedSlot, 260, 140);
            if (!viewModel.ColorText.Contains("RGB[", StringComparison.Ordinal) ||
                !viewModel.XyText.Contains("260,140", StringComparison.Ordinal))
            {
                throw new InvalidOperationException("Image Compare did not publish pixel status.");
            }
        });
    }

    private static CaptureResult CaptureBatchLabelSummaryMigration(string outputPath)
    {
        const string key = "Workbench.Batch.LabelSummary";
        string path = OpenVisionLanguageService.CatalogPath;
        string physicalPath = path;
        for (DirectoryInfo directory = new(Path.GetDirectoryName(path)!); directory != null; directory = directory.Parent)
        {
            if (directory.LinkTarget == null) continue;
            FileSystemInfo target = directory.ResolveLinkTarget(true)!;
            physicalPath = Path.Combine(target.FullName, Path.GetRelativePath(directory.FullName, path)); break;
        }
        if (!Path.GetFullPath(physicalPath).StartsWith(@"D:\OpenVisionLab-TestData", StringComparison.OrdinalIgnoreCase)) throw new InvalidOperationException("Migration contract requires owned D: catalog storage.");
        byte[] original = File.ReadAllBytes(path);
        OpenVisionLocalizationEntry current = OpenVisionLanguageService.GetDefaultEntries("Workbench.Batch.").Single(item => item.Key == key);
        string oldKo = "판정 일치 {0}/{1} · 과검 {2} · 미검 {3}", oldEn = "Label agreement {0}/{1} · Over-rejection {2} · Misses {3}";
        List<object> cases = new();
        try
        {
            for (int variant = 0; variant < 5; variant++)
            {
                List<OpenVisionLocalizationEntry> entries = OpenVisionLanguageService.GetEntries().ToList();
                OpenVisionLocalizationEntry entry = entries.Single(item => item.Key == key);
                entry.Korean = variant == 1 || variant == 2 ? "사용자 정의 {0}/{1}" : variant == 4 ? current.Korean : oldKo;
                entry.English = variant == 1 || variant == 3 ? "Custom agreement {0}/{1}" : variant == 4 ? current.English : oldEn;
                string expectedKo = variant == 0 ? current.Korean : entry.Korean, expectedEn = variant == 0 ? current.English : entry.English;
                OpenVisionLanguageService.SaveEntries(entries); OpenVisionLanguageService.ReloadCatalog(false);
                OpenVisionLocalizationEntry actual = OpenVisionLanguageService.GetEntries().Single(item => item.Key == key);
                if (actual.Korean != expectedKo || actual.English != expectedEn) throw new InvalidOperationException("Default exact-pair migration must preserve both custom and either partially changed language.");
                byte[] first = File.ReadAllBytes(path); OpenVisionLanguageService.ReloadCatalog(false);
                if (!first.SequenceEqual(File.ReadAllBytes(path))) throw new InvalidOperationException("Batch label catalog reload must be idempotent.");
                cases.Add(new { Variant = variant, ExactOldPairMigrated = variant == 0, actual.Korean, actual.English, Idempotent = true });
            }
        }
        finally { File.WriteAllBytes(path, original); OpenVisionLanguageService.ReloadCatalog(false); }
        if (!original.SequenceEqual(File.ReadAllBytes(path))) throw new InvalidOperationException("Owned catalog bytes were not restored.");
        File.WriteAllText(Path.ChangeExtension(outputPath, ".cases.json"), JsonSerializer.Serialize(new { CatalogPath = path, PhysicalCatalogPath = physicalPath, Cases = cases, OriginalRestored = true }, new JsonSerializerOptions { WriteIndented = true }));
        return CaptureElement(new Border { Background = Brushes.White, Padding = new Thickness(24), Child = new TextBlock { Text = "Batch label summary migration: 5 cases PASS\nExact old pair only; custom/partial pairs preserved; reload idempotent; owned bytes restored.", TextWrapping = TextWrapping.Wrap, Foreground = Brushes.DarkSlateGray, FontSize = 16 } }, outputPath, 760, 180);
    }
    private static CaptureResult CaptureLocalizationCatalog(string outputPath)
    {
        string[] required =
        {
            "Shell.PendingTool.Status",
            "Shell.PendingTool.NavStatus",
            "Common.Close",
            "VisionMenu.Blob",
            "ToolView.AddPipeline",
            "VisionTool.Status.PipelineSavedContextFormat"
        };

        foreach (string key in required)
        {
            string value = OpenVisionLanguageService.T(key);
            if (string.IsNullOrWhiteSpace(value) || string.Equals(value, key, StringComparison.Ordinal))
            {
                throw new InvalidOperationException("Missing localization key: " + key);
            }
        }

        MethodInfo? migrateDefault = typeof(OpenVisionLanguageService).GetMethod(
            "TryMigrateDefaultCatalogValue",
            BindingFlags.NonPublic | BindingFlags.Static);
        if (migrateDefault == null)
        {
            throw new InvalidOperationException("Localization default migration seam is unavailable.");
        }

        OpenVisionLocalizationEntry currentLineLabel = new() { Key = "VisionTool.Line.SettingLabel", Korean = "라인", English = "Line" };
        foreach ((string korean, string english, bool expectedMigration) in new[]
        {
            ("라인", "Setting", true),
            ("라인", "Configured line label", false),
            ("선택 선", "Setting", false)
        })
        {
            OpenVisionLocalizationEntry savedLineLabel = new() { Key = currentLineLabel.Key, Korean = korean, English = english };
            bool migratedLineLabel = (bool)(migrateDefault.Invoke(null, new object[] { currentLineLabel.Key, savedLineLabel, currentLineLabel }) ?? false);
            if (migratedLineLabel != expectedMigration || savedLineLabel.Korean != (expectedMigration ? "라인" : korean)
                || savedLineLabel.English != (expectedMigration ? "Line" : english))
                throw new InvalidOperationException("Line default label migration must update Setting and preserve either customized language.");
        }

        (string Key, string OldKorean, string OldEnglish, string NewKorean, string NewEnglish)[] previewMigrations =
        {
            ("PropertyGrid.Search.NoResults", "'{0}'\uC5D0 \uD574\uB2F9\uD558\uB294 \uD30C\uB77C\uBBF8\uD130\uAC00 \uC5C6\uC2B5\uB2C8\uB2E4. Esc \uD0A4\uB85C \uAC80\uC0C9\uC744 \uC9C0\uC6B8 \uC218 \uC788\uC2B5\uB2C8\uB2E4.", "No properties match '{0}'. Press Esc to clear the search.", "\u2018{0}\u2019 \uAC80\uC0C9 \uACB0\uACFC \uC5C6\uC74C (Esc: \uC9C0\uC6B0\uAE30)", "No match for \u2018{0}\u2019 (Esc: clear)"),
            ("PropertyGrid.Type.ContourProperty.EPSILON.DisplayName", "\uADFC\uC0AC \uD5C8\uC6A9 \uC624\uCC28", "Approximation epsilon", "\uADFC\uC0AC \uD5C8\uC6A9 \uC624\uCC28", "Approx epsilon"),
            ("PropertyGrid.Property.COARSE_ANGLE_TOP_K.DisplayName", "1\uCC28 \uD6C4\uBCF4 \uAC01\uB3C4 \uC218", "Coarse angle candidates", "1\uCC28 \uD6C4\uBCF4 \uAC01\uB3C4 \uC218", "Coarse candidates"),
            ("PropertyGrid.Property.PYRAMID_POSITION_MIN_SCORE.DisplayName", "\uC704\uCE58 \uD6C4\uBCF4 \uCD5C\uC18C \uC810\uC218", "Minimum position candidate score", "\uC704\uCE58 \uD6C4\uBCF4 \uCD5C\uC18C \uC810\uC218", "Min candidate score"),
            ("PropertyGrid.Property.ALLOW_GLOBAL_POLARITY_REVERSAL.DisplayName", "\uC804\uCCB4 \uADF9\uC131 \uBC18\uC804 \uD5C8\uC6A9", "Allow global polarity reversal", "\uC804\uCCB4 \uADF9\uC131 \uBC18\uC804 \uD5C8\uC6A9", "Global polarity reversal"),
            ("PropertyGrid.Type.EdgeBasedMatchingProperty.AUTO_MPOINT_MIN_REPRESENTATIVE_IMAGES.DisplayName", "\uCD5C\uC18C \uB300\uD45C \uC774\uBBF8\uC9C0 \uC218", "Min representative images", "\uCD5C\uC18C \uB300\uD45C \uC774\uBBF8\uC9C0 \uC218", "Min rep. images"),
            ("PropertyGrid.Type.EdgeBasedMatchingProperty.AUTO_MPOINT_MIN_REPRESENTATIVE_SUCCESS_RATE.DisplayName", "\uCD5C\uC18C \uB300\uD45C \uC131\uACF5\uB960", "Min representative success", "\uCD5C\uC18C \uB300\uD45C \uC131\uACF5\uB960", "Min rep. success rate"),
            ("PropertyGrid.Property.CONTOUR_APPROXIMATION_MODE.DisplayName", "\uC724\uACFD\uC810 \uADFC\uC0AC \uBC29\uC2DD", "Contour approximation mode", "\uC724\uACFD\uC810 \uADFC\uC0AC \uBC29\uC2DD", "Contour approx. mode"),
            ("PropertyGrid.Property.MIN_GRADIENT_MAGNITUDE.DisplayName", "\uCD5C\uC18C \uAE30\uC6B8\uAE30 \uD06C\uAE30", "Minimum gradient magnitude", "\uCD5C\uC18C \uAE30\uC6B8\uAE30 \uD06C\uAE30", "Min gradient strength"),
            ("PropertyGrid.Property.HYBRID_VERIFY_TOP_N.DisplayName", "\uD558\uC774\uBE0C\uB9AC\uB4DC \uAC80\uC99D \uD6C4\uBCF4 \uC218", "Hybrid verification candidates", "\uD558\uC774\uBE0C\uB9AC\uB4DC \uAC80\uC99D \uD6C4\uBCF4 \uC218", "Hybrid candidates"),
            ("PropertyGrid.Property.HYBRID_VERIFY_IMAGE_WEIGHT.DisplayName", "\uC601\uC0C1 \uC720\uC0AC\uB3C4 \uAC00\uC911\uCE58", "Image similarity weight", "\uC601\uC0C1 \uC720\uC0AC\uB3C4 \uAC00\uC911\uCE58", "Similarity weight"),
            ("PropertyGrid.Property.MinimumSourceTriangleArea.DisplayName", "\uC18C\uC2A4 \uC0BC\uAC01\uD615 \uCD5C\uC18C\uAC12", "Source triangle minimum", "\uC18C\uC2A4 \uC0BC\uAC01\uD615 \uCD5C\uC18C\uAC12", "Min source triangle"),
            ("PropertyGrid.Property.MinimumDestinationTriangleArea.DisplayName", "\uBAA9\uD45C \uC0BC\uAC01\uD615 \uCD5C\uC18C\uAC12", "Target triangle minimum", "\uBAA9\uD45C \uC0BC\uAC01\uD615 \uCD5C\uC18C\uAC12", "Min target triangle"),
            ("PropertyGrid.Property.MinimumValidPixelRatio.DisplayName", "\uCD5C\uC18C \uC720\uD6A8 \uD53D\uC140 \uBE44\uC728", "Minimum valid pixel ratio", "\uCD5C\uC18C \uC720\uD6A8 \uD53D\uC140 \uBE44\uC728", "Min valid pixel ratio"),
            ("ToolView.NoOutputImageDetail", "미리보기를 실행하면 결과 이미지가 표시됩니다.", "Run Preview to display a result image.", "툴 실행(F8)을 누르세요.", "Press Run tool (F8)."),
            ("PropertyGrid.Property.USE_ADAPTIVE_THRESHOLD.DisplayName", "적응형 이진화 사용", "Use adaptive threshold", "적응형 이진화 사용", "Adaptive thresholding"),
            ("PropertyGrid.Type.ContourProperty.USE_APPROXPOLYDP.DisplayName", "다각형 추가 근사", "Additional polygon approximation", "다각형 추가 근사", "Approximate polygon"),
            ("PropertyGrid.Type.ContourProperty.ApproximationModes.DisplayName", "윤곽점 근사 방식", "Contour approximation mode", "윤곽점 근사 방식", "Approximation mode"),
            ("PropertyGrid.Property.USE_AVERAGE_FILTER.DisplayName", "호환(미적용) · 평균 필터", "Compatibility (inactive) · Average filter", "호환(미적용) · 평균 필터", "Mean filter (inactive)"),
            ("PropertyGrid.Property.SHOW_VERTICAL_LINE.DisplayName", "레거시 표시 · 스캔 라인", "Legacy draw · Scan line", "레거시 표시 · 스캔 라인", "Legacy scan line"),
            ("PropertyGrid.Property.USE_COARSE_TO_FINE_ANGLE_SEARCH.DisplayName", "단계적 각도 탐색", "Coarse-to-fine angle search", "단계적 각도 탐색", "Coarse angle search"),
            ("PropertyGrid.Property.USE_PYRAMID_POSITION_PROPOSAL.DisplayName", "피라미드 위치 후보 사용", "Use pyramid position proposals", "피라미드 위치 후보 사용", "Pyramid proposals"),
            ("PropertyGrid.Property.ShowAdvancedSettings.DisplayName", "고급 설정 표시", "Show advanced settings", "고급 설정 표시", "Advanced settings"),
            ("PropertyGrid.Property.PATTERN_PATH.DisplayName", "패턴 경로", "Pattern path", "템플릿 경로", "Template path"),
            ("PropertyGrid.Property.USE_CANNY.DisplayName", "Canny 사용", "Use canny", "Canny 사용", "Use Canny"),
            ("PropertyGrid.Property.SHOW_EDGE.DisplayName", "레거시 표시 · 엣지", "Legacy draw · Edge", "레거시 표시 · 에지", "Legacy draw · Edge"),
            ("PropertyGrid.Property.USE_AVERAGE_FILTER.DisplayName", "평균 필터 사용", "Use average filter", "호환(미적용) · 평균 필터", "Mean filter (inactive)"),
            ("PropertyGrid.Property.SHOW_VERTICAL_LINE.DisplayName", "스캔 라인 표시", "Show scan line", "레거시 표시 · 스캔 라인", "Legacy scan line"),
            ("PropertyGrid.Property.SHOW_EDGE.DisplayName", "엣지 표시", "Show edge", "레거시 표시 · 에지", "Legacy draw · Edge")
        };
        List<object> migrationChecks = new();
        string catalogPath = OpenVisionLanguageService.CatalogPath;
        byte[] originalCatalog = File.ReadAllBytes(catalogPath);
        try
        {
            foreach (var migration in previewMigrations)
            {
                for (int variant = 0; variant < 4; variant++)
                {
                    List<OpenVisionLocalizationEntry> entries = OpenVisionLanguageService.GetEntries().ToList();
                    OpenVisionLocalizationEntry entry = entries.Single(item => item.Key == migration.Key);
                    entry.Korean = variant == 1 ? "사용자 번역" : variant == 3 ? migration.NewKorean : migration.OldKorean;
                    entry.English = variant == 2 ? "User translation" : variant == 3 ? migration.NewEnglish : migration.OldEnglish;
                    OpenVisionLanguageService.SaveEntries(entries);
                    OpenVisionLanguageService.ReloadCatalog(false);
                    OpenVisionLocalizationEntry actual = OpenVisionLanguageService.GetEntries().Single(item => item.Key == migration.Key);
                    string expectedKorean = variant == 1 ? "사용자 번역" : variant == 2 ? migration.OldKorean : migration.NewKorean;
                    string expectedEnglish = variant == 2 ? "User translation" : variant == 1 ? migration.OldEnglish : migration.NewEnglish;
                    migrationChecks.Add(new { migration.Key, migration.OldKorean, migration.OldEnglish, Variant = variant, actual.Korean, actual.English, ExpectedKorean = expectedKorean, ExpectedEnglish = expectedEnglish });
                    if (actual.Korean != expectedKorean || actual.English != expectedEnglish)
                        throw new InvalidOperationException("Property label default migration changed custom language or failed: " + migration.Key + "/" + variant);
                    byte[] firstReload = File.ReadAllBytes(catalogPath);
                    OpenVisionLanguageService.ReloadCatalog(false);
                    if (!firstReload.SequenceEqual(File.ReadAllBytes(catalogPath)))
                        throw new InvalidOperationException("Property label localization reload must be idempotent.");
                }
            }
        }
        finally
        {
            File.WriteAllBytes(catalogPath, originalCatalog);
            OpenVisionLanguageService.ReloadCatalog(false);
        }
        File.WriteAllText(Path.ChangeExtension(outputPath, ".preview-migrations.json"), JsonSerializer.Serialize(migrationChecks, new JsonSerializerOptions { WriteIndented = true }));

        OpenVisionLocalizationEntry shippedPresetDetail = new()
        {
            Key = "VisionTool.Preset.Detail",
            Korean = "프리셋은 PropertyGrid 값만 바꿉니다. 미리보기로 검증하세요.",
            English = "Choose a starting point. It updates PropertyGrid values only; run Preview to verify."
        };
        OpenVisionLocalizationEntry currentPresetDetail = new()
        {
            Key = shippedPresetDetail.Key,
            Korean = "기본=첫 검사 / 빠른=빠른 선별 / 정밀=최종 튜닝. 선택하면 적용 이유를 표시합니다.",
            English = "Basic = first check / Fast = quick screening / Precise = final tuning. Select one to see why."
        };
        bool migratedPresetDetail = (bool)(migrateDefault.Invoke(
            null,
            new object[] { shippedPresetDetail.Key, shippedPresetDetail, currentPresetDetail }) ?? false);
        if (!migratedPresetDetail
            || !string.Equals(shippedPresetDetail.Korean, currentPresetDetail.Korean, StringComparison.Ordinal)
            || !string.Equals(shippedPresetDetail.English, currentPresetDetail.English, StringComparison.Ordinal))
        {
            throw new InvalidOperationException(
                "The shipped preset-detail default did not migrate to the current guidance.");
        }

        OpenVisionLocalizationEntry customizedPresetDetail = new()
        {
            Key = shippedPresetDetail.Key,
            Korean = "사용자 지정 프리셋 안내",
            English = "User-customized preset guidance"
        };
        bool migratedCustomizedPresetDetail = (bool)(migrateDefault.Invoke(
            null,
            new object[] { customizedPresetDetail.Key, customizedPresetDetail, currentPresetDetail }) ?? false);
        if (migratedCustomizedPresetDetail
            || !string.Equals(customizedPresetDetail.Korean, "사용자 지정 프리셋 안내", StringComparison.Ordinal)
            || !string.Equals(customizedPresetDetail.English, "User-customized preset guidance", StringComparison.Ordinal))
        {
            throw new InvalidOperationException(
                "Localization migration overwrote a customized preset-detail value.");
        }

        OpenVisionLocalizationEntry shippedAddPipeline = new()
        {
            Key = "ToolView.AddPipeline",
            Korean = "\uD30C\uC774\uD504\uB77C\uC778 \uCD94\uAC00",
            English = "Add Pipeline"
        };
        OpenVisionLocalizationEntry currentAddPipeline = new()
        {
            Key = shippedAddPipeline.Key,
            Korean =
                "\uD30C\uC774\uD504\uB77C\uC778\uC5D0 "
                + "\uCD94\uAC00\u00B7\uC800\uC7A5",
            English = "Add and save to Pipeline"
        };
        bool migratedAddPipeline = (bool)(migrateDefault.Invoke(
            null,
            new object[]
            {
                shippedAddPipeline.Key,
                shippedAddPipeline,
                currentAddPipeline
            }) ?? false);
        if (!migratedAddPipeline
            || !string.Equals(
                shippedAddPipeline.Korean,
                currentAddPipeline.Korean,
                StringComparison.Ordinal)
            || !string.Equals(
                shippedAddPipeline.English,
                currentAddPipeline.English,
                StringComparison.Ordinal))
        {
            throw new InvalidOperationException(
                "The shipped add-Pipeline default did not migrate to the "
                + "add-and-save guidance.");
        }

        OpenVisionLocalizationEntry customizedAddPipeline = new()
        {
            Key = shippedAddPipeline.Key,
            Korean = "\uC0AC\uC6A9\uC790 \uC800\uC7A5 \uB3D9\uC791",
            English = "User-customized save action"
        };
        bool migratedCustomizedAddPipeline = (bool)(migrateDefault.Invoke(
            null,
            new object[]
            {
                customizedAddPipeline.Key,
                customizedAddPipeline,
                currentAddPipeline
            }) ?? false);
        if (migratedCustomizedAddPipeline
            || !string.Equals(
                customizedAddPipeline.Korean,
                "\uC0AC\uC6A9\uC790 \uC800\uC7A5 \uB3D9\uC791",
                StringComparison.Ordinal)
            || !string.Equals(
                customizedAddPipeline.English,
                "User-customized save action",
                StringComparison.Ordinal))
        {
            throw new InvalidOperationException(
                "Localization migration overwrote a customized "
                + "add-Pipeline value.");
        }

        foreach ((string Key, string OldKorean, string OldEnglish, string NewKorean, string NewEnglish) migration in new[]
        {
            (
                "PropertyGrid.Property.MinimumSourceTriangleArea.DisplayName",
                "\uCD5C\uC18C \uC18C\uC2A4 \uC0BC\uAC01\uD615 \uBA74\uC801",
                "Minimum source triangle area",
                "\uC18C\uC2A4 \uC0BC\uAC01\uD615 \uCD5C\uC18C\uAC12",
                "Source triangle minimum"),
            (
                "PropertyGrid.Property.MinimumDestinationTriangleArea.DisplayName",
                "\uCD5C\uC18C \uBAA9\uD45C \uC0BC\uAC01\uD615 \uBA74\uC801",
                "Minimum destination triangle area",
                "\uBAA9\uD45C \uC0BC\uAC01\uD615 \uCD5C\uC18C\uAC12",
                "Target triangle minimum")
        })
        {
            OpenVisionLocalizationEntry shipped = new()
            {
                Key = migration.Key,
                Korean = migration.OldKorean,
                English = migration.OldEnglish
            };
            OpenVisionLocalizationEntry current = new()
            {
                Key = migration.Key,
                Korean = migration.NewKorean,
                English = migration.NewEnglish
            };
            bool migrated = (bool)(migrateDefault.Invoke(
                null,
                new object[] { migration.Key, shipped, current }) ?? false);
            if (!migrated
                || !string.Equals(shipped.Korean, current.Korean, StringComparison.Ordinal)
                || !string.Equals(shipped.English, current.English, StringComparison.Ordinal))
            {
                throw new InvalidOperationException(
                    "The shipped AffineTransform label did not migrate: " + migration.Key);
            }

            OpenVisionLocalizationEntry customized = new()
            {
                Key = migration.Key,
                Korean = "\uC0AC\uC6A9\uC790 \uC0BC\uAC01\uD615 \uAE30\uC900",
                English = "User-customized triangle gate"
            };
            bool migratedCustomized = (bool)(migrateDefault.Invoke(
                null,
                new object[] { migration.Key, customized, current }) ?? false);
            if (migratedCustomized
                || !string.Equals(customized.English, "User-customized triangle gate", StringComparison.Ordinal))
            {
                throw new InvalidOperationException(
                    "Localization migration overwrote a customized AffineTransform label: " + migration.Key);
            }
        }

        Border report = new()
        {
            Background = Brushes.White,
            Padding = new Thickness(24),
            Child = new TextBlock
            {
                Text = "Localization Catalog OK" + Environment.NewLine + string.Join(Environment.NewLine, required),
                FontSize = 16,
                Foreground = Brushes.DarkSlateGray
            }
        };
        return CaptureElement(report, outputPath, 760, 420);
    }

    private static CaptureResult CaptureManualGuideLanguageContract(string outputPath)
    {
        OpenVisionLanguage originalLanguage = OpenVisionLanguageService.CurrentLanguage;
        string testRoot = Path.Combine(
            Path.GetTempPath(),
            "OpenVisionLab-ScreenshotSmoke",
            "manual-guide-language-" + Guid.NewGuid().ToString("N"));
        Directory.CreateDirectory(testRoot);
        try
        {
            List<string> reportLines = new List<string>();
            string[] languageCodes = { "ko", "en", "ko" };
            string sourceDirectory = string.Empty;
            foreach (string languageCode in languageCodes)
            {
                OpenVisionLanguageService.SetLanguage(
                    string.Equals(languageCode, "en", StringComparison.Ordinal)
                        ? OpenVisionLanguage.English
                        : OpenVisionLanguage.Korean,
                    false);
                if (!OpenVisionShellHostCommandController.TryResolveUserManualPath(
                        out string resolvedPath,
                        out string failureDetail)
                    || !string.Equals(
                        Path.GetFileName(resolvedPath),
                        $"OpenVisionLab_User_Manual.{languageCode}.html",
                        StringComparison.Ordinal)
                    || !File.ReadAllText(resolvedPath).Contains(
                        $"data-openvisionlab-manual-language=\"{languageCode}\"",
                        StringComparison.Ordinal))
                {
                    throw new InvalidOperationException(
                        $"Guide did not resolve the {languageCode} manual. Path='{resolvedPath}', Failure='{failureDetail}'");
                }

                sourceDirectory = Path.GetDirectoryName(resolvedPath) ?? string.Empty;
                reportLines.Add($"{languageCode.ToUpperInvariant()} -> {Path.GetFileName(resolvedPath)}");
            }

            File.Copy(Path.Combine(sourceDirectory, "guide-manifest.json"), Path.Combine(testRoot, "guide-manifest.json"), true);
            File.Copy(
                Path.Combine(sourceDirectory, "OpenVisionLab_User_Manual.ko.html"),
                Path.Combine(testRoot, "OpenVisionLab_User_Manual.ko.html"),
                true);
            if (OpenVisionShellHostCommandController.TryValidateUserManual(
                    testRoot,
                    "en",
                    out _,
                    out _))
            {
                throw new InvalidOperationException("Guide crossed over to Korean when the selected English manual was missing.");
            }
            reportLines.Add("Missing EN -> fail closed (no KO fallback)");

            string englishSourcePath = Path.Combine(sourceDirectory, "OpenVisionLab_User_Manual.en.html");
            string englishTestPath = Path.Combine(testRoot, "OpenVisionLab_User_Manual.en.html");
            File.Copy(englishSourcePath, englishTestPath, true);
            File.AppendAllText(englishTestPath, Environment.NewLine);
            if (OpenVisionShellHostCommandController.TryValidateUserManual(
                    testRoot,
                    "en",
                    out _,
                    out _))
            {
                throw new InvalidOperationException("Guide accepted an English manual with a mismatched SHA-256 hash.");
            }
            reportLines.Add("Damaged EN -> fail closed (SHA-256)");

            Border report = new Border
            {
                Background = Brushes.White,
                Padding = new Thickness(24),
                Child = new TextBlock
                {
                    Text = "Guide Language Contract OK" + Environment.NewLine + string.Join(Environment.NewLine, reportLines),
                    FontSize = 18,
                    LineHeight = 30,
                    Foreground = Brushes.DarkSlateGray
                }
            };
            return CaptureElement(report, outputPath, 900, 380);
        }
        finally
        {
            OpenVisionLanguageService.SetLanguage(originalLanguage, false);
            if (Directory.Exists(testRoot))
            {
                Directory.Delete(testRoot, true);
            }
        }
    }

    private static OpenVisionShellHostView CreateShellHost(string recipeName, bool seedMainLayer = true)
    {
        DisplayManagerService displayManager = new();
        GlobalState global = new();
        global.Recipe.Name = recipeName;
        PropertyGridEditorFactory.SetRuntimeContext(() => displayManager);
        PropertyGridEditorFactory.SetRecipeNameContext(() => global.Recipe.Name);
        ApplicationRuntimeContext runtimeContext = new(global, displayManager);
        OpenVisionShellHostView shellHost = new(runtimeContext);
        if (seedMainLayer)
        {
            using Bitmap seedImage = CreateWorkspaceSeedSmokeBitmap();
            shellHost.SetMainLayerImageForTest(seedImage);
        }

        return shellHost;
    }

