    [StructLayout(LayoutKind.Sequential)]
    private struct NativePoint
    {
        public NativePoint(int x, int y)
        {
            X = x;
            Y = y;
        }

        public int X;
        public int Y;
    }

    [StructLayout(LayoutKind.Sequential)]
    private struct NativeMonitorRect
    {
        public int Left;
        public int Top;
        public int Right;
        public int Bottom;
    }

    [StructLayout(LayoutKind.Sequential, CharSet = CharSet.Auto)]
    private struct NativeMonitorInfo
    {
        public int Size;
        public NativeMonitorRect MonitorArea;
        public NativeMonitorRect WorkArea;
        public uint Flags;
    }

    private readonly record struct LargeImageResourceSnapshot(
        long PrivateBytes,
        long WorkingSetBytes,
        long ManagedBytes,
        int HandleCount,
        int GdiObjects,
        int UserObjects);

    private sealed class ShortcutTestKeyboardDevice : KeyboardDevice
    {
        public ShortcutTestKeyboardDevice() : base(InputManager.Current) { }
        public ModifierKeys TestModifiers { get; set; }
        protected override KeyStates GetKeyStatesFromSystem(Key key) => key == Key.Enter || key == Key.LeftCtrl && TestModifiers.HasFlag(ModifierKeys.Control)
            || key == Key.LeftShift && TestModifiers.HasFlag(ModifierKeys.Shift) || key == Key.LeftAlt && TestModifiers.HasFlag(ModifierKeys.Alt) ? KeyStates.Down : KeyStates.None;
    }


